INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (804, 'zhTW', '薩科斯', '看見你為我這麼一個素不相識的可憐傢伙做了這麼多事情，我突然又堅強了起來。我絕不能就這麼輕易地死在這種地方!我得堅持下去!可現在我還是不能自己回到大獸穴去。$n，請你再幫個忙，回大獸穴向高內克報告一下我現在的情況。', '將哈納祖目前的狀況告訴大獸穴內的高內克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 805 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (805, 'zhTW', '去森金村報到', '你在這山谷中的針對火刃氏族的試煉……如今就算是完成了。但我希望你能去向其他人報告一下你的發現。到森金村去找加德林大師吧。先從山谷的東側出去，在岔路口轉向右一直走到底就能抵達森金村了。我們必須把火刃氏族的勢力出現在試煉谷的事告訴加德林大師。去吧，$N，動作要快。恐怕我們在火刃集會所中找到的東西只是更可怕的威脅的預兆而已……', '與森金村的加德林大師談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 806 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (806,'zhTW','黑暗風暴',' $N ，我有個不妙的消息。對燃刃氏族的調查表明，杜洛塔境內還有不少這個氏族的勢力。這是我們絕對不能允許的!在他們站穩腳跟、滋生邪惡之前，我們必須把他們消滅掉。$B$B有個名叫費索·暗雷的哥布林術士就居住在西北部的雷霆山裡，他和他的那群爪牙就在那裡製造混亂。$B$B去幹掉他，再把他的爪子帶回來給我!','把費索的爪子帶給剃刀嶺的奧戈尼爾·魂痕。','','去找杜洛塔的奧戈尼爾·魂痕。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 807 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (807,'zhTW','暫無內容','我的偵察兵報告說杜隆塔爾的某些野獸受到了惡魔力量的感染。在北方和西方都見過這樣的動物。$B$B它們結伴遊蕩，和一般野獸沒什麼兩樣，不過體內充滿了邪惡的力量。$B$B一定要消滅這些野獸。$B$B如果你在杜隆塔爾發現了這些傢伙，殺了它們，取出他們的Scorched Heart交給我。我要仔細地研究研究,然後將它們徹底銷燬。','找5個Scorched Heart，送給剃刀嶺的Orgnil Soulscar。','','去找杜隆塔爾的奧戈尼爾·魂痕。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 808 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (808,'zhTW','明希納的顱骨','我在夢中聽到了我兄弟明希納的呼喚。$B$B回音群島上的術士札拉贊恩抓走了他，折磨著他，最後殘忍地害死了他。$B$B但即使是死亡也沒能讓我的兄弟得到安寧，因為札拉贊恩用邪惡的魔法把明希納的靈魂困在了他的顱骨中。我在夢中看見…我兄弟的顱骨和其他人的顱骨一起被堆在回音群島中最大的那座島上的法陣中。只要他的頭骨還在那兒，他的靈魂就無法得到自由。$B$B請你幫助他吧， $N 。找到那個邪惡的法陣，把明希納的顱骨帶回來給我，讓他的靈魂獲得自由吧!','到回音群島上去，將島上法陣中的明希納的顱骨帶回來，交給森金村的加德林大師。','','去杜洛塔找森金村的加德林大師。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 809 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (809,'zhTW','雅克塞羅斯','自從我們在上一次大戰中擊敗燃燒軍團之後，我一直在尋找潛藏在獸人中的惡魔勢力的源頭。你帶來的項圈證實了我的擔憂。$B$B這個項圈屬於火刃氏族，這幫惡魔的信徒正在憑藉著一件被稱作惡魔之種的器物重整旗鼓。你可以在鬼霧峰山頂的貧瘠之地找到惡魔之種，一定要把它毀掉！$B$B到貧瘠之地邊境西邊的前沿哨所去找我的助手雅克塞羅斯吧，他會給你進一步的指示。','到貧瘠之地去和雅克塞羅斯談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 810 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (810,'zhTW','暫無內容','瞭解這片土地有多危險對你的將來大有好處，$c。$B$B這裡的野生物可以教會我們這些……只要我們有足夠的智慧和觀察力。$B$B蠍子就是在杜隆塔爾求得生存的典範。想要生存下去的話，你不妨去向它們學習。它們堅硬的甲殼可以讓你免受烈日的折磨，甚至可以抵擋致命的攻擊。$B$給我找6個巨鉗蠍身上的Small Scorpid Carapaces回來，$N，我會留意給你應得的獎賞。','找6個Small Scorpid Carapaces 帶給森金村的Kor\'ghan。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 811 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (811,'zhTW','暫無內容','Scorpids的另一個特性是它們強烈的忠誠度。他們遇到危險時總是互相保護——你第一次捕獵它們的時候可能已經發現了這一點。$B$B如果加以留意並向它們學習，你能做得更好。團結在一起，我們將更強大；一盤散沙，則變得不堪一擊。$B$B給我找8個Armored Scorpids身上的Large Scorpid Carapaces，若能學習它們的優點，我會給你應有的獎賞。','找8個Large Scorpid Carapaces交給森金村的Kor\'ghan。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 812 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (812,'zhTW','救命如救火','$N……你來得真是時候，快救救我……$B$B我在毒尾蠍戰鬥的時候一不小心被蟄傷了，毒液正在不斷侵蝕我的血液。看樣子…我最多再撐一個小時就得玩完了，我想請你幫個忙…$B$B奧格瑪的考格漢知道怎麼做解毒劑，快去找他…$N，我…我支援不了多久了……','找到毒尾蠍的解毒劑，把它交給杜隆塔爾西北邊境的林納格。','','去貧瘠之地找怒水河的林納格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 813 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (813,'zhTW','尋找解毒劑','林納格不隨身帶著解毒劑就去抓毒尾蠍是很不明智的行為，不過現在說這些也於事無補。$B$B趕快到奧格瑪城的城門外，在那一帶的毒尾蠍身上給我找4個毒囊回來，這樣我才能給他做解毒劑。$B$B動作快點，$N。我們自己的同胞命在旦夕！','收集4個毒尾蠍的毒囊，把它們交給奧格瑪的考格漢。','','去找奧格瑪的考格漢。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 814 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (814,'zhTW','暫無內容','燒飯和打掃——這些就是我的工作。$B$B如果你想吃東西，就先給我帶點肉來！我可沒工夫整天給你們這些寄生蟲打獵。你要想得到平等的待遇，就得學會盡你的本分。$B$B如果你想讓自己看上去不是個廢物，或者不想活活餓死的話，就去給我找點野豬肉回來。','收集10大塊野豬肉，把它們交給剃刀嶺的廚師托爾卡。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 815 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (815,'zhTW','恐龍蛋大餐','啊呀!我差點忘了還得做早飯!$B$B $N ，快去給我找點鞭尾龍的蛋來，至少得要三個蛋才夠明天做飯用。$B$B血爪鞭尾龍非常兇猛，而且會拼命地保護自己的蛋。有時它們會把蛋深深地埋在地下讓你找不到，不過在森金村東南方的回音群島上，這些鞭尾龍的蛋滿地都是。','收集3個鞭尾龍的蛋，並把它們帶給剃刀嶺的廚師托爾卡。','','去找杜洛塔的廚師托爾卡。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 816 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (816,'zhTW','丟失的孩子',' $N ，請幫幫我吧!我的兒子克魯恩幾天前到西邊的怒水河畔捕獵鱷魚，卻一直沒有回來，我現在覺得不妙了。$B$B儘管他十分強壯，但他的固執和自尊常常讓自己陷入麻煩。我警告過他，鱷魚是強大而兇猛的動物，可他一聽就火了，掉頭就走。$B$B如果你找不到他，至少也請給我帶來一些關於他的消息，不管是好的還是壞的……就算把怒水河畔每隻鱷魚的肚子剖開也要找到點什麼。','把關於克魯恩的消息告訴剃刀嶺西北部農場中的米莎·托克雷。','','去杜洛塔找托克雷農場的米莎·托克倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 817 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (817,'zhTW','生活所需的虎皮','我們的獸皮大多取自生活在杜洛塔地區的老虎身上， $N 。我們捕獵這些野獸的原因很多，比如毯子、護甲，還有帳篷什麼的;同樣，還有許多原因讓我們允許它們繼續繁衍生息。$B$B但是現在，我們有必要再殺掉一些老虎了。我們的人數在增加，而庫存的獸皮也已經開始供不應求了，因此我需要更多獸皮來為他們製作各種生活用品。$B$B給我找四張杜洛塔猛虎的毛皮來，我會給你一些獎賞的。','收集四張杜洛塔虎皮，並把它們交給森金村的維爾林·長牙。','','去杜洛塔找森金村的維爾林·長牙。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 818 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (818,'zhTW','沃納爾大師','雖然我的視力不斷衰退，但我還是可以看得足夠清楚。我曾經可以很輕易地施放強力的魔法，而現在我更多時候必須依靠鍊金術的幫助才行。不過我不收學徒，因為我從來沒有看到過任何夠格的食人妖或 $R 。$B$B你是合適的人選嗎?當然，你當然是……你當然以為自己合適。$B$B我需要一點東西，你能幫我拿來嗎?$B$B我要一些龍蝦人的眼睛和幾瓶蟹膠，你可以在杜洛塔的海蟹或龍蝦人身上找到這些東西，找齊了之後再來見我。','把4個龍蝦人的眼睛和8小瓶蟹膠帶到森金村，交給沃納爾大師。','','去杜洛塔找森金村的沃納爾大師。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 819 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (819, 'zhTW', '老陳的空酒桶', '張貼在酒桶一角的紙條上寫著:「老陳 - $B$B祝汝精神得提升，祝汝精神永提升。」', '找到對老陳的空酒桶有所瞭解的人。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 820 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (820,'zhTW','暫無內容','你體內的確存在著力量的精神——或者那僅僅只是運氣？$B$B現在的年輕人總是依靠運氣，或是指望那些比自己更為強大的人對他們施以慷慨。很少有人願意走自己的路。總是向別人乞求幫助……不願完成任何任務就想獲得報酬。我肯定你就是這樣。$B$B不過我對你還有點希望。我還需要一樣東西，$N：8束微光草，在剃刀嶺西北部的雷霆山上可以找到。','找8束微光草，交給森金村的沃納爾大師。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 821 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (821,'zhTW','老陳的空酒桶','你想嘗嘗老陳的雷霆佳釀嗎?哈哈，這東西可是很帶勁的哦。老陳把釀酒術教給了我師傅，我師傅又傳給了我。去幫我找一些釀酒的材料，然後你就會得到物有所值的回報!$B$B幫我帶5顆草原獅的獠牙、5個平原陸行鳥的腎臟和1根雷霆蜥蜴的角回來，然後我就可以釀酒了。$B$B這些東西都可以在貧瘠之地找到。','收集5顆草原獅的獠牙、5個平原陸行鳥的腎臟和1根雷霆蜥蜴的角，把它們交給棘齒城的釀酒師德羅恩。','','去找貧瘠之地的釀酒師德羅恩。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 822 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (822,'zhTW','老陳的空酒桶','雷霆佳釀的味道不錯吧？$B$B我從老陳那裡還學到了另一種釀酒術，你有興趣嗎？釀造這種酒不需要花太多的時間，如果你願意冒險弄到些原料就成了。$B$B幫我弄五個雷鱗蜥蜴的閃電腺、一個巨型雷鷹的唾液腺和一個居住在貧瘠之地上的科多獸的肝臟來。$B$B我說過，這種酒很正點，就是我和你提到過的穴居怪啤酒。','收集5個閃電腺、1個雷鷹的唾液腺和1個科多獸的肝臟，把它們交給棘齒城裡的釀酒師德羅恩。','','去貧瘠之地找棘齒城的釀酒師德羅恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 823 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (823, 'zhTW', '向奧戈尼爾報告', '我們森金村這邊還有許多棘手的問題要解決，非常感謝你的幫助。但是你帶來的消息說明火刃氏族也許對所有人來說都是個大麻煩。剃刀嶺那裡有一處獸人營地，奧戈尼爾·魂痕就在那裡負責監視火刃氏族那一類的邪惡勢力。去跟他談一談，跟他說說我們目前的情況，還有你從試煉谷得到的消息，他肯定會大吃一驚的。剃刀嶺就在這裡的北邊。', '和剃刀嶺的奧戈尼爾·魂痕談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 824 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (824,'zhTW','大地之環的耶努薩克雷','大地之環是個薩滿祭司的團體，他們致力於研究和保護自然界中的元素。他們忘掉的關於上古之神的知識可能比大多數學者知道的還要多。$B$B你很幸運，我認識梣谷的大地之環的成員。到佐拉姆海岸邊上的佐拉姆加前哨站去，向耶努薩克雷展示你找到的這個東西。如果有誰對這顆水球的重要性有所瞭解的話，那麼非他莫屬了。','將被汙染的水球交給梣谷佐拉姆加前哨站的耶努薩克雷。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 825 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (825,'zhTW','海底沉船','我得到訊息說普羅德摩爾艦隊的殘骸仍在杜隆塔爾的近海，就在提拉加德城堡的東邊。$B$B與人類結盟的侏儒是一群粗俗的小東西，但是他們掌握著先進的機械技術。我們必須對任何潛在的敵人都瞭如指掌，同時我們的族人也可以從這些新知識中受益。$B$B$n，潛到那些沉船中，給我拿來聯盟使用的工具。','剃刀嶺的加索克要你從海岸邊的艦隊殘骸中打撈出3件侏儒的工具。','','去找杜隆塔爾的加索克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 826 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (826,'zhTW','札拉贊恩','巫醫札拉贊恩就住在東邊的回音群島上，那些島嶼曾經是我們的家園。$B$B札拉贊恩從那裡不斷派出他的爪牙來到這邊的大陸上，用妖術控制我們的同胞，將他們也變成札拉贊恩的傀儡。$B$B我們必須阻止他。$B$B打敗札拉贊恩和他的爪牙─那些曾經是我們的朋友和親人的暗矛食人妖。把札拉贊恩的頭給我帶回來，作為你已經斬殺了這個惡魔的證明。','打敗札拉贊恩。','','去杜洛塔找森金村的加德林大師。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 827 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (827,'zhTW','骷髏石','$N。火刃氏族就躲在奧格瑪東部的骷髏石山洞裡。他們在洞中進行邪惡的儀式，用灼熱項圈去燃燒自己的身體。$B$B我相信他們戴上這些項圈之後便會獲得惡魔的力量，不過如果要確定這一點，我還得收集一些項圈來做研究。$B$B到骷髏石去，從那些火刃祭司身上找些灼熱項圈給我，讓我來揭開他們的秘密。','在骷髏石中的火刃祭司身上收集灼熱項圈，$B$B然後交給瑪高茲。','','去找杜隆塔爾的瑪高茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 828 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (828,'zhTW','瑪高茲','有個名叫瑪高茲的薩滿祭司對於火刃氏族的墮落頗有了解。他說在奧格瑪外面的山裡有個叫骷髏石的山洞，有一大批火刃祭司藏匿在那裡。$B$B在你前往骷髏石之前，去和瑪高茲談談吧。他十分睿智，會給你一些有價值的建議。$B$B瑪高茲就住在東北方的海岸和枯水谷中間。$B$B你要聽從瑪高茲的建議，但是不管他怎麼說，$N，我都要求你幹掉那些火刃祭司！','和瑪高茲談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 829 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (829,'zhTW','尼爾魯·火刃','你帶回來的灼熱項圈是充滿惡魔力量的強大器物工具。它們的來源恐怕已經不是我這樣的薩滿祭司所能探究的了。我們必須找個專精於此的術士來研究它們。$B$B把這個項圈帶給尼爾魯·火刃。他是個技藝高超的術士，但他卻擅長使用自己所掌握的惡魔力量來對抗惡魔，還聲稱他對惡魔的研究都是有益於部落的。不管這些話是真是假，如果我們要對付那些信仰惡魔的傢伙，就需要他的幫助。$B$B你可以在奧格瑪的暗影裂口找到尼爾魯。','給奧格瑪的尼爾魯·火刃帶去一個項圈樣本。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 830 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (830,'zhTW','將軍的命令','你開啟了陳舊褪色的信封，發現了一份看上去很正式的檔案，上面蓋著普羅德摩爾將軍的徽記。$B$B這封信看上去很重要，剃刀嶺的指揮官加索克應該會對它感興趣。','把普羅德摩爾將軍的命令帶給剃刀嶺的加索克。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 831 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (831,'zhTW','將軍的命令','人類是不可信的。我們和他們並肩作戰、疲憊不堪，但我們很明白，總有一天這幫傢伙會背叛我們。$B$B普羅德摩爾將軍死了，但這並沒有終止他的計劃，這個混蛋在他玩完之前就把一切都安排好了。$B$B本尼迪克上尉不會是最後一個威脅，天知道什麼時候普羅德摩爾的人會又一次從我們的海岸上登陸。我們要儘快讓奧格瑪的納茲格雷爾得知這些資訊！快去吧，你應該能在索爾的大廳裡找到他。','把普羅德摩爾將軍的命令交給奧格瑪城中的納茲格雷爾，他就在索爾的大廳裡。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 832 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (832,'zhTW','燃影之眼','<你感受到飾物中傳來一個神秘的聲音>$B$B加祖茲？$B$B加祖茲？……快回答！$B$B我們已經聽說你在骷髏石發現了那個東西，你必須立刻發動攻擊！$B$B加祖茲，我命令你趕快回答！否則我就把你的位置告訴尼爾魯·火刃，他會用最殘忍的手段來對付你！$B$B別拿你的小命開玩笑！…$B$B加祖茲，你在那裡嗎……？','把這顆燃影之眼帶給尼爾魯·火刃。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 833 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (833,'zhTW','神聖的墓地','赤色石是我們 $R 最神聖的墓地，只有最勇敢的 $R 才能得到在那裡安息的殊榮。這是給予那些幫助保衛雷霆崖和為部族的利益而付出生命的偉大 $C 的無上榮譽。$B$B不過這段時間以來，有種邪惡的威脅正在接近我們的神聖領土。有一群刺背干涉者正在破壞我們的墓地，我的年紀太大了，無力把他們趕走。$B$B你一定要把他們驅逐出去， $N 。','在赤色石殺掉8個刺背干涉者。','','去莫高雷找赤色石的博學者諾拉·暴雨圖騰。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 834 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (834,'zhTW','沙漠之風','我叫雷茲拉克，是加茲魯維的手下。他派我來這裡跟杜洛塔的獸人作生意...一切進行得很順利，除了商隊以外。商隊的安全根本沒辦法保證!這真的給我搞了不少麻煩!$B$B上次發出的一批貨物，他們還說肯定能平安送達，結果被一票塵風鷹身人從半道上給劫了去...他們好像是從那什麼...烈風峽谷來的?$B$B我得拿到那批補給!沿著大峽谷向南走，你就會看到那條直直切入山壁東西兩面的溝壑。','取回5袋裝滿貨物的袋子。','','去找杜洛塔的雷茲拉克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 835 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (835,'zhTW','保衛商路','加茲魯維跟我說過:「雷茲拉克呀，有一件事情你必須銘記，那就是如果你想把事情做好，就得親力而為。」$B$B我不能失去我們所有的商隊，所以我得自己解決這件事才行。鷹身人正在肆虐我們的補給路線。如果我們把他們全都給做了，那條路就徹底安全了。$B$B當然，加茲魯維還教過我另一點，那就是「有錢能使鬼推磨」。那麼，你願意幫我的忙嗎， $N ?','殺掉12個杜洛塔鷹身人，任何種類的都行。','','去找杜洛塔的雷茲拉克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 836 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (836,'zhTW','拯救OOX-09/HL！','那個侏儒的聲音再次從那個機器人中傳了出來：$B$B“我需要你幫忙把OOX-09/HL移動到一個安全的開闊地，這樣它才可以啟動起飛程式。它自帶隱形系統，但是我需要一點時間來遠端啟動這個系統。請你把這個機器人從現在的位置護送到望海崖去！那裡是個非常理想的起飛點，有足夠的空間作為機器人起飛的跑道！”$B$B“將它護送到那裡，然後再到藏寶海灣來找我！奧格索普·奧布諾提斯——完畢！”','將OOX-09/HL護送到被遺忘的海岸上的碼頭，然後向藏寶海灣的奧格索普·奧布諾提斯報告。','將OOX-09/HL安全護送到目的地。','去荊棘谷找藏寶海灣的奧格索普·奧布諾提斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 837 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (837,'zhTW','野豬人的進犯','我們剛來這裡的時候，鋼鬃野豬人已經佔據了大片的土地，讓我們頭疼不已。經過不斷的努力，我們已經將絕大部分的野豬人都驅逐出去，不過在某些地區還殘留著防衛良好的野豬人。$B$B但是，這種情況已經持續太久了，我們要保護自己，我們絕不能允許鋼鬃野豬人佔據我們的領土。野豬人的營地就在西邊，只要找到荊棘就可以找到牠們。今天，我們把他們趕出杜洛塔，明天，我們就能把他們趕出整個卡林多。','替剃刀嶺的加索克殺掉4個鋼鬃野豬人，4個鋼鬃斥候，4個鋼鬃傳令兵和4個鋼鬃戰地衛士。','','去找杜洛塔的加索克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 838 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (838,'zhTW','通靈學院','通靈學院坐落在凱爾達隆島上，這所學校是亡靈天災的一座堡壘。我們的敵人就聚居在那裡，安全地進行研究並不斷增強他們的力量。有一扇堅固的大門封住了唯一的入口，如果沒有一把合適的鑰匙，我們無論如何都無法透過它。$B$B藥劑師迪瑟斯一直以來都負責與通靈學院有關的事務，他應該知道如何才能獲得那把鑰匙。你應該向我證明你確實有存在的價值，現在我把這個任務交給你，去跟迪瑟斯談談關於這件事的詳細情況吧。','和西瘟疫之地亡靈壁壘的藥劑師迪瑟斯談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 839 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (839,'zhTW','<UNUSED>','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 840 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (840,'zhTW','部落的新兵','嗯，你看上去很強壯。$B$B是這樣的，我的好朋友卡加爾正在為貧瘠之地招募新兵。我知道你想為部落做點有用的事，這次你的機會來了。$B$B把這封募兵信交給卡加爾，看看他會不會簽字。','沿著剃刀嶺西部的小路一直前進，過橋之後就可以進入貧瘠之地。$B$B在橋對面的獸人前哨找到卡加爾·戰痕，將你的募兵信交給他。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 841 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (841,'zhTW','另一個能量源？','讓我猜猜——你沒有及時完成你所謂的什麼驚天動地的任務。不，等等……是不是你把它掉在了流沙裡找不回來了？！好吧，不管是什麼理由，我這裡還有個能量源可以賣給你。這次，我要你用十個廢土水袋來換！$B$B這年頭大家都不好混，$n，能量源當然不會是長在樹上隨手可得的！呃，也許它們真的可以長在樹上……我們絕對應該試試看能不能製造這樣一棵能量源樹……','用10個廢土水袋來和加基森的總工程師比格維茲換取另外一個能量源。','','去塔納利斯找加基森的首席工程師沙克斯·比格維茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 842 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (842,'zhTW','十字路口徵兵','把我簽過字的募兵信拿到十字路口去。$B$B那裡由瑟格拉·黑棘掌管，她是個噁心的薩滿祭司，總喜歡在吩咐你去做正事之前跟你胡說一通，把你搞得頭暈腦脹。索爾覺得她是個人才，但我可不這麼看。$B$B小子，接下來的事情還是你自己去解決吧……','從卡加爾的前沿哨所往西走。$B$B在丁字路口往左拐，然後朝南走。$B$B在十字路口的道路交匯處找到瑟格拉·黑棘。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 843 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (843,'zhTW','加恩的報復','我一直在這裡孤獨地徘徊著。$B$B巴爾莫丹的矮人對我們的領土從來都沒有半點尊重。烈性的炸藥在地面上炸出了一個又一個深深的鑽孔，嘈雜的機器切開了山丘和平原，曾經屬於我們部族的美好家園現在成了那些破壞成性的矮人們的領地。$B$B我們曾希望透過外交途徑與他們和解，但是一切努力最終都以失敗告終。現在是做出決斷的時候了。$B$B用武力將這些矮人從巴爾莫丹的挖掘場趕走，把他們的頭兒勘察員卡茲戈姆的日記帶來交給我。','加恩·石塔讓你殺死15個巴爾丹挖掘者和5個巴爾丹工頭。$B$B把卡茲戈姆的日記交給加恩·石塔。','','去貧瘠之地找南黃金之路的加恩·石塔。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 844 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (844,'zhTW','平原陸行鳥的威脅','你對陸行鳥熟悉嗎?沒用的動物、飛不起來、愛玩、腦子只有我拳頭那麼大。遲鈍到不懂得避開移動的車子。多虧了牠們的硬腦殼，我不知折斷了多少根車軸...有時候我覺得野豬人是故意把牠們驅趕到我們車隊的路徑上，好為埋伏製造優勢的。$B$B讓我為你感到驕傲吧， $C 。砍殺一票那種骯髒的鳥，讓道路保持淨空，然後把牠們的鳥喙帶回來給我當做證據。','收集7個陸行鳥的喙。','','去貧瘠之地找十字路口的瑟格拉·黑棘。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 845 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (845,'zhTW','角斑馬','如果你想為我所深愛的部落服務，你得向我證明自己的力量，小子。你可以從狩獵角斑馬開始。角斑馬或許不是貧瘠之地上最兇猛的野獸，但忽視牠們的踢腿你可是會大感後悔。$B$B去獵殺北邊和南邊的角斑馬，並且收集牠們的蹄子。把蹄子帶來給我，或許我們就能接著派你去對付更兇猛的什麼東西。','殺死快步角斑馬並收集4只角斑馬蹄。','','去貧瘠之地找十字路口的瑟格拉·黑棘。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 846 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (846,'zhTW','加恩的報復','很顯然，矮人們依靠炸藥和那些吵鬧的機械來進行挖掘，而且不久後他們肯定會再派一個新的工頭來接手這裡。$B$B我要讓這些矮人自食其果。按照這日記上面寫著的配方，只要把硝化甘油、木漿和硝酸鈉混合起來，就能製造出一種強力的炸藥。據我們所知，城堡中的火槍手、戰士和軍官都擁有這些物資。$B$B為我收集這些物資，我要製造出一種讓矮人們永遠都不會忘記的炸藥！','加恩·石塔要你將6瓶硝化甘油、6份木漿和6份硝酸鈉交給他。','','去貧瘠之地找南黃金之路的加恩·石塔。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 847 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (847,'zhTW','迅猛龍的狡詐','這……這力量……是托爾甘要顯示給我的薩滿祭司的力量嗎？我不得不承認，這很有趣。告訴托爾甘他讓我十分信服……至少是現在。我會對他要說的一切都洗耳恭聽。','和托爾甘談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 848 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (848,'zhTW','菌類孢子','貧瘠之地的綠洲裡隱藏著一個謎。生命的能量從綠洲之水中湧出，給那些汲取水分的動植物帶來了勃勃生機。$B$B與此同時，這種能量也在慢慢地改變這些動植物。$B$B在綠洲附近生長著一種蘑菇，我們這些羅德隆的藥劑師發現這種蘑菇的孢子中包含有一些特殊的物質，它對我們非常有用。$B$B幫我帶一些孢子回來，我們會非常感謝你的。','從遺忘之池的蘑菇那裡收集5個菌類孢子。','','去找貧瘠之地的藥劑師赫布瑞姆。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 849 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (849,'zhTW','加恩的報復','按照卡茲戈姆的日記上所述的方法製造出來的炸藥應該不會有問題。$B$B那麼，我們開始吧。$B$B首先我有一項特殊的任務要交給你完成。拿上這隻爆破筒，去炸掉巴爾莫丹的飛行器。$B$B這個飛行器不僅是巴爾莫丹軍事設施的關鍵部分，也是一架可怕的殺戮機器。更重要的是，它是權力的象徵，而它對我們的部族來說則代表著一段恥辱的回憶。$B$B我會為你的成功感到自豪，你也將得到豐厚的獎勵。','摧毀巴爾莫丹的飛行器，然後向加恩·石塔回覆。','','去貧瘠之地找南黃金之路的加恩·石塔。','貝爾莫丹飛行器已經被摧毀','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 850 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (850,'zhTW','科卡爾首領','半人馬的問題困擾著牛頭人已經很多年了，最近，貧瘠之地的科卡爾半人馬開始形成真正的威脅。通常他們散居在這片土地上，不過他們當中已經產生了新的首領，他把一盤散沙的半人馬集合在一起。$B$B為了保護我們的家園，這些半人馬領袖就必須要除掉。$B$B幫我帶回巴拉克·科多班恩的頭顱，他在北方的遺忘之池附近駐營。$B$B除掉他，然後再回到我這裡。','把巴拉克的頭顱交給十字路口的雷戈薩·死門。','','去找貧瘠之地的雷戈薩·死門。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 851 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (851,'zhTW','狂熱的維羅戈','有一個被稱作狂熱的維羅戈的半人馬在貧瘠之地四處遊蕩，通常很難找到他，不過他的營地就在東南方的死水綠洲附近，你應該可以在那裡把他給引誘出來。$B$B到死水綠洲附近的半人馬營地去，斬殺那裡的半人馬。雖然這會讓你處於很危險的境地，不過如果你能殺死足夠多的半人馬，他們就會發出警報，之後維羅戈就會現身。$B$B把他的頭帶給我，我要把它和巴拉克·科多班恩的頭顱放在一起。','把維羅戈的頭顱交給十字路口的雷戈薩·死門。','','去找貧瘠之地的雷戈薩·死門。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 852 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (852,'zhTW','赫茲魯爾·血印','赫茲魯爾·血印是貧瘠之地的科卡爾半人馬的首領。他兇猛、殘忍，詭計多端。消滅他就可以瓦解半人馬部落，從而極大地削弱他們對我們的威脅。$B$B去殺了他。就像對付巴拉克和維羅戈那樣，帶回赫茲魯爾的頭顱。$B$B他和他的手下駐紮就在西南方的甜水綠洲一帶。','把赫茲魯爾的頭顱交給十字路口的雷戈薩·死門。','','去找貧瘠之地的雷戈薩·死門。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 853 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (853, 'zhTW', '藥劑師札瑪', '我用你給我的孢子製成了藥劑。現在我必須把它送給我的同事，藥劑師札瑪。如果你願意幫忙把這個帶給她，她會拿一些我們存儲下來的鍊金術用品獎勵你的。$B$B她就在預見之池裡，那是一個位於雷霆崖下面的洞穴。通向洞穴的小路非常隱蔽，不過你可以在靈魂高地下面找到這條小路。$B$B快點出發吧，這種藥劑的效力只能持續很短的一段時間，在這段時間裡必須要送到札瑪那裡。', '在藥劑的效力消失之前，把提煉過的孢子交給雷霆崖的藥劑師札瑪。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 854 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (854,'zhTW','十字路口之旅','我已經預見到你會來找我，年輕的$c，雖然你可能已經並不是那麼年輕了。$B$B我想，現在是時候讓你深入這片土地了，我能感覺到你命中註定是要做一番大事業的人。$B$B你應該到十字路口去，因為我們和獸人的命運已經緊緊地聯絡在了一起，他們那兒需要幫助。沿著這條路往東走，然後向北就可以走到十字路口。到那裡去找索克吧。','去十字路口和索克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 855 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (855,'zhTW','半人馬護腕','在與科卡爾半人馬的戰鬥中，你已經證明了自己。不過，他們仍然是個威脅。這些半人馬的首領的死對我們來說是非常好的訊息，不過你必須繼續削減他們軍隊的人數。$B$B為此我會交給你一項賞金任務。$B$B到科卡爾半人馬的領地去，幹掉他們的士兵，收集他們的半人馬護腕。當你能帶回足夠多的護腕的時候，部落會獎賞你的。','收集15個半人馬護腕，把他們交給十字路口的雷戈薩·死門。','','去找貧瘠之地的雷戈薩·死門。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 856 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (856,'zhTW','暫無內容','雖然你已經到了貧瘠之地，但你的旅程還沒有完成。你得繼續走到十字路口去，那裡才是最需要你的地方。$B$B沿著這條路走，遇到岔路之後往左拐。一直向北走就能看見十字路口的圍牆。$B$B進去之前，先找先祖聖者談一談，他會給你一些推薦。','從陶拉祖營地繼續沿著路走。$B$B在丁字路口向左拐，然後往北走。$B$B沿著大路一直走到十字路口，和外面的先祖聖者談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 857 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (857,'zhTW','眾月之淚','那是我的寶貝！我的！我要把它奪回來！奪回來！$B$B那些骯髒的挖掘者發現了它……它是如此美麗，眾月之淚是我們在巴爾莫丹的第一個重大發現。$B$B它本就該是我的！對，我的！我的寶貝！$B$B塔文布萊德將軍嫉妒眾月之淚帶給我的力量，居然就把它鎖在了城堡裡。他說那是一個詛咒！這個蠢貨！$B$B其他人想要奪走它，他們是不會得逞的！那個叫塔文布萊德的雜種把我趕了出來。$B$B我要奪回來！奪回我的寶貝！','被流放的費格雷要你取回他的眾月之淚。','','去貧瘠之地找巴爾莫丹的被流放的費格雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 858 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (858,'zhTW','點火裝置','你該不會是斯布特瓦夫派來的吧?我被困在這兒了。我在不知道需要鑰匙才能啟動伐木機的情況下就貿然跳了進來。更蠢的是，當另一台伐木機的操作員問我是否一切正常的時候，我居然慌了!我沒跟他說我手裡沒鑰匙，而只是說機器有些問題。$B$B我們要趕緊離開這裡!到起重機上邊的控制室去，魯格維茲主管應該有這台伐木機的鑰匙。$B$B幫幫我!','從魯格維茲主管那裡取得點火裝置的鑰匙。','','去貧瘠之地找淤泥沼澤的維茲克蘭克的伐木機。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 859 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (859,'zhTW','暫無內容','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 860 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (860, 'zhTW', '瑟格拉·黑棘', '如果你想繼續沿著獵人之道前行，就得到貧瘠之地去了。那兒的野獸強壯而兇猛，在那裡打獵會讓你學到很多東西，而你的意志力也會隨之增強。去和瑟格拉·黑棘談談吧，她會是你在貧瘠之地的第一位嚮導。她就在十字路口，只要從血蹄村一直往東進入貧瘠之地，見到岔路口之後再往北走就可以到那裡了。在貧瘠之地旅行的時候可得小心點，那是一個充滿危險和挑戰的地方。', '和十字路口的瑟格拉·黑棘談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 861 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (861,'zhTW','獵人之途','我看得出來，你渴望探索。我也曾渴望到處漫遊...$B$B漫遊並且狩獵。狩獵是 $R 最高的榮譽。$B$B如果你真想走上獵人這條路，就向我展示你的能力和決心。把莫高雷一帶的平原徘徊者的爪子帶來給我。平原徘徊者非常兇猛、狡猾，對於想要成為獵人的年輕 $C 來說是最合適的獵物。','收集4隻平原徘徊者的爪子。','','去雷霆崖找獵人高地的梅洛·石蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 862 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (862,'zhTW','掘地鼠燉肉','像你樣一個$c在貧瘠之地肯定會餓得前心貼後背，你看我，我就已經餓了整整一天了。$B$B我跟你說吧，我可以為你做一道大餐，不過得要先弄一些掘地鼠來。$B$B那些可惡的巴爾莫丹矮人幾乎把這裡的掘地鼠都給吃光了！你到南邊的巴爾莫丹去給我帶一些掘地鼠回來吧。$B$B如果你連這都搞不定的話，就不要再自稱是經驗豐富的冒險家了！','給十字路口的格拉布弄到8只掘地鼠。','','去找貧瘠之地的格拉布。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 863 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (863,'zhTW','偷跑','我想我要好好學學才行……應該不會很難。就這些按鈕，一個操縱杆和兩個……對了，你準備好要出發了嗎?','保護維茲克蘭克以及他偷來的哥布林伐木機返回棘齒城的斯布特瓦夫那裡。','護送維茲克蘭克離開風險投資公司鑽井工地','去貧瘠之地找棘齒城的斯布特瓦夫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 864 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (864, 'zhTW', '向藥劑師金格回報', '「好了，現在能量源已經被安全卸載，而你的資料也被保留下來了。嗯，接下來就只有祝你一路順風了。希望你的科學實驗一切順利。」$B$B哥布林轉身開始繼續做加基森水業公司的事情。你小心翼翼地把封好的實驗工具包收起來，然後準備把它帶回幽暗城。藥劑師金格正在那裡等著你和封裝的野外實驗工具包。', '把實驗工具包帶給幽暗城的藥劑師金格。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 865 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (865,'zhTW','一定是角','貧瘠之地的迅猛龍比其他地區的迅猛龍更加聰明狡猾。我想它們的智慧就來自它們的角!如果是這樣的話，我可以將牠們的角磨成粉末，製成「智慧飲料」。然後就能賣掉大賺一筆!!!$B$B從這裡開始就是你的工作了:我想要最聰明那隻迅猛龍的角。「鐮爪王」在棘齒城北方的峭壁上帶領著一群聰明的迅猛龍。把角給我帶來!別想跟我派去的那些人一樣敲我竹槓!','取得鐮爪王之角。','','去找貧瘠之地的麥伯克·米希瑞克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 866 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (866,'zhTW','根鬚樣本','貧瘠之地的草藥似乎和其它地方的不大一樣。它們的屬性幾乎相同，不過這裡的綠洲之水卻令它們發生了一些改變，使它們變得有那麼一點點特別了。$B$B我想找出這些草藥到底有什麼特別之處……然後看看它們有沒有利用價值！$B$B如果你精通草藥的話，就幫我在貧瘠之地收集一些這種草藥的根鬚樣本吧。把這些樣本交給我，這樣一來，我就能比較一下它們與其它地區的草藥之間的差異了。','把根鬚樣本交給棘齒城的麥伯克·米希瑞克斯。','','去找貧瘠之地的麥伯克·米希瑞克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 867 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (867,'zhTW','鷹身劫掠者','這些該死的鷹身人長期以來不停地攻擊和掠奪我們的補給商隊。現在該是我們割斷她們喉嚨，削減她們數量的時候了。$B$B我一直在她們的巢穴附近細心觀察，已經確定了誰是她們的領導者。我們應該先以削弱她們的作戰力量為目標，這樣才能徹底擊敗她們。$B$B慢慢來，先去幹掉那些在西北方出沒的巫翼鷹身人和巫翼遊蕩者，然後幫我帶8隻巫翼鷹身人的爪子回來吧。這應該是一個不錯的開始...','從巫翼鷹身人和巫翼遊蕩者身上收集8只巫翼鷹身人的爪子。','','去找貧瘠之地的達索克·快刀。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 868 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (868,'zhTW','蠍卵','嘿，$N，奧格瑪城裡的主人派我到十字路口來觀察這片土地並記錄這裡所發生的一切。$B$B我的目標之一是在巨人曠野南方出現的昆蟲狀生物。我們對這種生物知之甚少，所以我把它作為我的主要研究課題，希望能發現點什麼。它們似乎有超出一般生物的智慧。$B$B拿著這個掘地鏟，從土丘裡收集一些它們的卵。不過你要當心，這些生物一旦收到同伴的警報，就會立刻蜂擁而至。','把12枚異種蠍卵和掘地爪交給十字路口的科蘭。','','去貧瘠之地找十字路口的科蘭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 869 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (869,'zhTW','跟蹤竊賊','殘骸附近留下了巨大且彎曲的爪行足跡。這種足跡只有迅猛龍才有。$B$B你第一個直覺是迅猛龍騎兵襲擊了這個營地，但不是很確定，附近也找不到其他不屬於動物的痕跡。$B$B足跡朝東北方離開，往荊棘嶺的東邊而去。謎底一定就在那裏。','足跡通往荊棘嶺的東邊。跟著足跡走，看看你會找到什麼。','','去貧瘠之地找十字路口的加茲羅格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 870 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (870,'zhTW','遺忘之池','你感覺到那種震顫了嗎， $C ?某種東西將大地劈成了兩半。但我們德魯伊還能感覺到其他的震顫。$B$B生命正在曾經乾旱無生機的土地上顫動。十字路口周圍的綠洲是突然綻放的。我可以感覺到有股力量正不斷往地面洩露，但它的源頭是什麼?是否和讓貧瘠之地支離破碎的災難有關?$B$B我們必須找到那個源頭。前往十字路口西北邊的遺忘之池吧。在那裡的綠洲水中搜尋力量的源泉，然後回到這裡。','搜查十字路口西北邊的遺忘之池的底部。','探索遺忘之池','去找貧瘠之地的圖加·符文圖騰。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 871 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (871,'zhTW','保衛前沿哨所','所有的野豬人都是我們的敵人，而其中有些傢伙特別讓人討厭。$B$B剃鬃野豬人屢次攻擊往返於我們與杜洛塔之間的補給車隊。我的斥候一直在尋找這些襲擊事件的指揮者，但是在找到真正的幕後主使之前，我們總得想些辦法來打擊那些可惡的野豬人才行。$B$B就從這裡的南方開始搜尋，他們在河的附近襲擊我們的營地。找出他們，殺了他們。','殺掉8個剃鬃盜掠者和3個剃鬃獵手。','','去找貧瘠之地的索克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 872 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (872,'zhTW','野豬人的頭目','$N，我的探子目擊了一次針對杜隆塔爾商隊的襲擊，又是那群該死的鋼鬃野豬人幹的。其中有一個傢伙是這次襲擊事件的策劃者和組織者：克里尼格·糟鼻。有人在這裡的東北方見到過他，就在通往杜隆塔爾的大路的正南方。如果我們要結束這一切威脅，就必須殺了克里尼格·糟鼻。$B$B我們一定要終止這沒完沒了的襲擊，要讓他們吃吃苦頭。完成任務之後，帶上克里尼格·糟鼻的獠牙回來見我。','殺掉8個鋼鬃地卜師、8個鋼鬃防禦者和他們的頭目克里尼格·糟鼻。$B$B把克里尼格·糟鼻的獠牙交給十字路口的索克。','','去找貧瘠之地的索克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 873 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (873,'zhTW','依沙瓦克','依沙瓦克是這片水域的主宰，它力大無窮、威武莊嚴。海岸上的人類都怕它，因為已經有太多的人類被它殺死。$B$B但我不怕，因為它對我來說是一次很有價值的挑戰，一個值得尊敬的獵物。$B$B如果你準備好了，那麼就到海里去尋找海中的巨獸依沙瓦克吧。$B$B它的靈魂包容在他的心中，聽著它跳動的聲音，你就將看到自己的命運。','把依沙瓦克的心臟交給瑪倫·星眼。','','去貧瘠之地找提度斯階梯的瑪倫·星眼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 874 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (874,'zhTW','瑪倫·星眼','你已經獵殺了貧瘠之地的猛獸，在這個過程中你的精神力量也已經變得相當強大了。作為一個獵人，你應當時刻都作好準備，一個真正的獵手理應能在任何環境下追蹤獵物。無論是山川還是沼澤都無法阻止$g他:她。$B$B甚至連海洋都不能。$B$B去找到我的妹妹瑪倫，她正在海岸邊獵殺一種大型水獸，你可以從她那裡學習更高深的狩獵之道。$B$B不過你找她的時候要當心，因為貧瘠之地的海岸一帶是現在是被人類控制著的。','和瑪倫·星眼談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 875 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (875,'zhTW','鷹身人首領','哈哈哈，$n，你還想接下一單任務？好呀，我真是太高興了。$B$B這次的任務是剿滅無水嶺的鷹身人首領。只有巫翼殺戮者才能成為鷹身人首領，這一點你可以從她們攜帶的戒指上判斷出來。她們其實就是一夥烏合之眾，在無水嶺一帶應該就有不少。只要殺死6個首領就足以對她們的這個母系氏族造成毀滅性的打擊了。$B$B$n，你一定要讓她們死得很慘，我要讓那些下賤的鷹身人知道和部落作對是多麼愚蠢的事。','從巫翼殺戮者那裡收集6枚鷹身人首領之戒，把它們交給十字路口的達索克·快刀。','','去找貧瘠之地的達索克·快刀。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 876 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (876,'zhTW','塞瑞娜·血羽','你在上次與鷹身人首領的戰鬥中表現得十分出色，所以我希望由你來幫我做最後一件事。$B$B塞瑞娜·血羽是很久前被雷克薩殺死的鷹身人族長的妹妹。顯然，這些針對部落商隊的襲擊是她對我們採取的報復行為。$B$B你的任務就是割開她的喉嚨，把她的頭顱帶給我。我將會把她的頭顱掛在下一次發出的商隊的車頂上……讓那些鷹身人好好看看跟部落作對的下場。','殺掉塞瑞娜·血羽，把她的頭顱交給十字路口的達索克·快刀。','','去找貧瘠之地的達索克·快刀。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 877 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (877,'zhTW','死水綠洲','你在遺忘之池找到的地縫也許在貧瘠之地的其它綠洲中也存在。如果是這樣的話，那麼這些地縫就有可能是綠洲的生命之源。$B$B我們應該驗證一下。$B$B帶上這些種子，它們已經失去生命的活力。把它們帶到東南方的死水綠洲去，如果那裡有地縫的話，就把這些種子放在裡面……然後仔細地觀察一下。','調查死水綠洲，然後返回十字路口向圖加·符文圖騰報告。','','去找貧瘠之地的圖加·符文圖騰。','試驗乾枯的種子','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 878 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (878,'zhTW','野豬人的內戰','你必須殺了我的敵人。<豬哼聲>你必須幫助碎牙，幫助鋼鬃野豬人。我們的部族都非常依賴自己的精神領袖——他們可以召喚大地的力量，<豬哼聲>使他們讓野豬人的部族變得強大……<豬哼聲>$B$B如果你想要知道是誰頻繁對部落<豬哼聲>發動襲擊，那你就應該幫助碎牙！你去殺了刺背野豬人的精神領袖，削弱他們，這樣鋼鬃野豬人就可以打敗他們，統治貧瘠之地了！','殺掉6個刺背尋水者、12個刺背織棘者和12個刺背地卜師，然後到陶拉祖營地的碎牙那裡覆命。','','去貧瘠之地找陶拉祖營地的碎牙。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 879 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (879,'zhTW','內奸','有三個來自剃刀沼澤的部族參與了對部落的襲擊。<豬哼聲>他們非常狡詐而無情，如果你打敗了他們，不僅僅是十字路口，整個貧瘠之地都將迎來和平……<豬哼聲>至少野豬人不會再對你們構成威脅了。<豬哼聲>$B$B你要找的是納克、卡茲和洛克·奧克班恩，他們就在貧瘠之地的最南邊活動。他們中的一個是施法者，另一個是追蹤者，他們的首領是個戰士。<豬哼聲>$B$B殺了他們，殺了這幫背叛我的傢伙。','殺掉納克、卡茲和洛克·奧克班恩，把它們的顱骨交給陶拉祖營地的碎牙。','','去貧瘠之地找陶拉祖營地的碎牙。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 880 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (880,'zhTW','變異的生物','$N，你的發現真讓人難以置信。這些綠洲擁有一些特殊的力量，誰也不知道這些力量是怎樣來的。$B$B我想知道這幾片綠洲是如何影響那些飲用過綠洲裡的水的動物的。$B$B去捕獲一些在甜水綠洲和死亡綠洲活動的綠洲鉗嘴龜，把它們的龜殼給我帶過來，我得好好研究一下。','收集8塊變異的鉗嘴龜殼，把它們交給十字路口的圖加。','','去找貧瘠之地的圖加·符文圖騰。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 881 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (881,'zhTW','埃其亞基','白霧，也就是我們所說的埃其亞基，是草原獅的首領。它在捕食獵物時悄無聲息地行動，就像大地上浮起的一層薄薄的白霧。它的每次出擊都是一擊斃命，它的獵物甚至來不及恐懼和痛苦就已魂飛魄散。$B$B你會體會到的，因為我要讓你去獵殺埃其亞基。它的巢穴就在十字路口的東北邊，在那些巨大的科多獸骨附近。$B$B去吧，當你走到它的巢穴附近時，就吹響這個號角，它正在等著你呢。','把埃其亞基的皮交給十字路口的瑟格拉·黑棘。','','去貧瘠之地找十字路口的瑟格拉·黑棘。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 882 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (882,'zhTW','伊沙姆哈爾','伊沙姆哈爾是貧瘠之地最兇猛殘忍的赤鱗龍，它狩獵並不是為了健身或是食物，而是因為狩獵是它最大的愛好，伊沙姆哈爾天生就是個殺手。$B$B$N，你會瞭解到它的天性的，因為你很快就要動身去追蹤這條赤鱗龍了。$B$B開始這次獵殺行動吧。先去殺死一隻它最喜歡捕獵的動物——斑馬，然後把斑馬肉掛在棘齒城西北邊的枯樹上。當伊沙姆哈爾聞到肉味的時候，它就會出現的。$B$B那時，你可要做好準備。','把伊沙姆哈爾的牙齒交給陶拉祖營地的喬恩。','','去貧瘠之地找陶拉祖營地的喬恩·星眼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 883 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (883,'zhTW','拉克塔曼尼','拉克塔曼尼的蹄子是科多獸力量的象徵。','把拉克塔曼尼的蹄子交給陶拉祖營地的喬恩。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 884 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (884,'zhTW','奧瓦坦卡','只要一被觸及，奧瓦坦卡的尾刺就會閃爍起火花。','把奧瓦坦卡的尾刺交給陶拉祖營地的喬恩。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 885 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (885,'zhTW','瓦希塔帕恩','僅僅是輕輕觸碰一下瓦希塔帕恩的羽毛，你都會感到相當刺痛。','把瓦希塔帕恩的羽毛交給陶拉祖營地的喬恩·星眼。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 886 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (886,'zhTW','貧瘠之地的綠洲','雷霆崖的德魯伊們感到有一股奇怪的力量正在滲入莫高雷東邊的貧瘠之地。$B$B圖加·符文圖騰已經被派去查詢這股力量的來源了，但是我們擔心他可能需要更多的幫助。$B$B到貧瘠之地去和圖加談談吧，他應該就在十字路口。從血蹄村一直往東走就可以進入貧瘠之地，在路口向北轉，然後繼續往北走，很快就到十字路口了。$B$B記得一直在路上走，$N，貧瘠之地是一塊非常危險的土地。','和十字路口的圖加·符文圖騰談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 887 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (887,'zhTW','南海海盜','加茲魯維答應給我升遷，只要我能幫助他解決棘齒城的海盜問題。麻煩的是，這些新來的海盜佔領了這裡南邊的勇士島。他們要的不光是我們的貨物，他們對我們有些私怨!某個晚上，他們甚至跑來追我們的一艘大帆船。$B$B我有個足以應付這情況的計畫，但加茲魯維想要儘快看見結果。前往勇士島，幫我砍一些腦袋下來，行嗎?','在勇士島上殺死8位南海殺手或南海私掠者。','','去找貧瘠之地的加茲魯維。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 888 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (888,'zhTW','被竊的貨物','我希望取回所有丟失的貨物，但我想那不太可能。不過，有些貨物是我必須要取回的!$B$B正如你所見的，我的天文臺馬上就要建好了，現在只差兩塊鏡片中較小的一塊。第一塊已由杜洛塔的商隊運到，第二塊運上了船，但現在還沒有到。對了，我還沒有收到藏寶海灣的崔斯里克給我發來的靴子!$B$B到海賊營地去一趟，看看能不能找到這些貨物吧。','幫棘齒城的加茲魯維取回一箱靴子以及一塊望遠鏡片。','','去找貧瘠之地的加茲魯維。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 889 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (889,'zhTW','風之魂','','','','去找莫高雷的碎牙。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 890 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (890, 'zhTW', '丟失的貨物', '我一直在等從藏寶海灣發來的最後一批貨物！我確信是海盜偷走了它們，不過為了保險一點，我還是希望你能去一趟碼頭，幫我問問迪茲維格……問問我的貨物是否已經入庫。$B$B把我的帳本交給迪茲維格，讓他趕緊把我的存貨記錄和他的出貨單校對一下。', '把加茲魯維的帳本交給棘齒城的碼頭管理員迪茲維格。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 891 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (891,'zhTW','船長的復仇','塞拉摩那些狂熱的人類又把我艦隊中一艘船給擊沉啦!$B$B他們的新海軍准將把船停靠在岸邊，任意占領或擊沉無辜的船隻。$B$B前往南方吧，沿著商旅海岸抵達他的營地。給我拿回他們水兵和水手的徽章，處死他的中尉皮瑞和巴克蘭。就像他們毀掉我的艦隊那樣，把他們給徹底消滅!','從塞拉摩水兵和水手身上收集10枚塞拉摩徽章，殺死皮瑞中尉和巴克蘭中尉。','','去找貧瘠之地的沙羅薩斯船長。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 892 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (892, 'zhTW', '丟失的貨物', '我這邊的出貨記錄似乎沒什麼問題，$n。回去告訴加茲魯維，他似乎不太走運。不出意料的話，應該是有海盜偷走了他的貨物。$B$B很遺憾我不能為他做些什麼了。呃……不過你可以告訴他，我從安德麥弄了些東西給他，什麼時候他有空的話就過來拿一下吧。', '把加茲魯維的帳本交還給棘齒城的加茲魯維。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 893 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (893,'zhTW','野豬人的武器','在巨人曠野以南的地區，生活著大群的鋼鬃野豬人。據我所知，他們曾是一群無能的鐵匠，不過有人告訴我說，野豬人們現在已經逐漸開始改良他們的那些破爛武器了。我想要從他們那裡弄些武器樣品來進行研究。$B$B如果你能幫我帶回來幾件武器的話，部落會以你為榮的。幫我帶回一把捕獵者用的匕首，一根先知用的魔杖，和一面戰士用的盾牌。','給陶拉祖營地的塔特納克·鋼爐帶去一把鋼鬃背刺匕首、一根燒焦的鋼鬃魔杖和一面鋼鬃大盾。','','去貧瘠之地找陶拉祖營地的塔特納克·鋼爐。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 894 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (894, 'zhTW', '什麼什麼平衡器', '風險投資公司最近在北邊設立了小型的研究設備，就在淤泥沼澤的西南部。我對他們在做的東西並不瞭解，只知道他們正在試驗一種名叫「主動式負載平衡器」的裝備。$B$B那個主動式負載平衡器到底是什麼東西呢?不管它是什麼，我都想研究研究它，所以我需要找個人來幫我把它弄到手。$B$B我手裡有控制系統操作手冊的副本，你應該知道該怎麼把那什麼平衡器卸下來。', '在風險投資公司研究基地裡找到控制臺。$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 895 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (895,'zhTW','懸賞:葛瑞威船長','懸賞!$B$B少女之匕號的船長$BJ.葛瑞威$B$B罪名是在公海上搶劫、綁架、勒索、縱火、奴隸買賣等等。葛瑞威最近帶領了一夥南海掠劫者在附近海域出現，上一次被人目擊時，他們正在攻擊勇士島。領賞者必須提供可明確證明通緝者已死亡的證據!$B$B－加茲魯維','把葛瑞威船長的頭顱帶去棘齒城交給加茲魯維。','','去找貧瘠之地的加茲魯維。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 896 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (896,'zhTW','礦工的寶貝','嘿， $R ，你有對寶藏有興趣嗎?我就知道這能吸引到你。$B$B最近港口那有小道消息，就是說風險投資公司有個礦工在東北邊的石礦坑挖出了一枚足有拳頭大小的翡翠石。$B$B我知道有一些買主肯掏錢買那麼大一塊寶石，如果你幫我找到那塊寶石的話，那麼我願意和你五五分帳。你願意幫忙嗎?','從風險投資公司的某個監督者或者執行者那裡奪取貓眼翡翠。','','去貧瘠之地找棘齒城的碼頭管理員迪茲維格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 897 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (897,'zhTW','收割者','這種奇特的昆蟲狀生物看起來彷彿不是貧瘠之地的生物，而更像是個天外來物。','把收割者的頭顱交給喬恩·星眼。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 898 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (898,'zhTW','逃離監牢','終於有人來救我了!$B$B你居然能躲過那些守衛，這簡直是太不可思議了。這幫塞拉摩的狂熱分子已經毫無理智可言了。他們擊沉了我們的船隻，俘虜了我這個唯一的倖存者，還稱我為聯盟的敵人和威脅。$B$B你看我像是要威脅誰的樣子嗎?我不過是在棘齒城和藏寶海灣之間來回奔波的下等水手而已。$B$B一下子說了這麼多，你願意幫我返回棘齒城嗎?等你準備好了，我們就馬上越獄。','護送基爾薩瑞斯·火枝安全地返回棘齒城的沙羅薩斯船長那裡。','護送基爾薩瑞斯·火枝安全地返回棘齒城。','去找貧瘠之地的沙羅薩斯船長。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 899 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (899,'zhTW','復仇的怒火','我的全家都被刺背野豬人殺害了， $C 。也許你能體會這種失去親人的傷痛，也許你不能…每天我都在這裡等著，從日出到日落，尋找這些罪無可赦的惡魔。$B$B從那天起，除了關在那邊的俘虜之外，我見一個野豬人就殺一個。但這依然遠遠無法平息我復仇的欲望。$B$B我想你這個 $C 能夠幫助我。$B$B去殺掉那些野豬人，能殺多少就殺多少。帶回它們的獠牙，讓我們一起為它們的死亡而慶賀吧。','收集60根刺背野豬人的獠牙，把它們交給十字路口的曼寇里克。','','去找貧瘠之地的曼科裡克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 900 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (900,'zhTW','負載平衡器','三個控制閥門都處於打開狀態。根據控制面板上的指示說明，在拆卸零件之前必須要把這三個閥門關閉。','關閉燃油控制閥、調節閥和主控制閥，然後再使用控制臺。','','去找貧瘠之地的控制台。','關閉主控制閥','關閉燃料控制閥','關閉調節閥','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 901 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (901,'zhTW','負載平衡器','關閉設備後就可以開啟控制面板，從控制臺中移出主動式負載平衡器。一切準備就緒，現在你需要做的就是取得可以打開控制臺的鑰匙。','從技工斯尼格斯那裡拿到控制臺鑰匙。','','去找貧瘠之地的控制台。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 902 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (902, 'zhTW', '什麼什麼平衡器', '揭開控制台的蓋子之後，你看見了密密麻麻纏繞在一起的電線、管子和其他各種奇形怪狀的機械裝備——其中大多數看起來沒有什麼實際用途。你把它們撥向一邊，在控制台的最裡邊找到了主動式負載平衡器。一隻機械臂把它從機架上拽了出來。', '把主動式負載平衡器交給棘齒城的斯布特瓦夫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 903 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (903,'zhTW','獵殺雌獅','如果你真想向我證明你的勇氣，那讓我派你去處理那些咬人真的很痛的傢伙吧。貧瘠之地的草原雌獅可是無與倫比的狡猾、機敏、迅速......而且致命。她們最近一直在城郊一帶騷擾我們的斥侯，尤其東北方最為嚴重。$B$B $N ，獵殺她們的時候要當心點，否則你可能會發現自己不是獵人，而是獵物。','從草原雌獅身上收集5個雌獅的爪子。','','去貧瘠之地找十字路口的瑟格拉·黑棘。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 904 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (904,'zhTW','暫無內容','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 905 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (905,'zhTW','狂暴的鐮爪龍','$n，你要做的下一步事情是打敗你的獵物，並找到它們的巢穴。$B$B去獵殺南邊的赤鱗迅猛龍，然後拿走它們戴著的羽毛。把羽毛放在死水綠洲西南邊的赤鐮龍巢穴裡，讓它們知道你無所畏懼！','殺死赤鱗迅猛龍並收集它們的羽毛，把這些羽毛放在3個赤鱗鐮爪龍的巢穴裡，然後返回十字路口的瑟格拉·黑棘那裡。','','去貧瘠之地找十字路口的瑟格拉·黑棘。','','檢查藍色迅猛龍巢穴','檢查黃色迅猛龍巢穴','檢查紅色迅猛龍巢穴',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 906 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (906,'zhTW','內奸','$r，帶上洛克·奧克班恩的顱骨去見索克吧。*豬哼的聲音*他應該知道我的部族發生過什麼事。哈，他不知道我也參與了*豬哼的聲音*這些事情，但我敢肯定他會對你的所作所為給予獎勵的。*豬哼的聲音*$B$B我們不會再見面了。*豬哼的聲音*','把洛克·奧克班恩的顱骨交給十字路口的索克。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 907 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (907,'zhTW','被激怒的雷霆蜥蜴','現在，$n，你必須面對強大的雷霆蜥蜴。這些野獸的體型非常巨大，連大地也會隨著它們的行進而震顫。與它們作戰時一定要多加小心，一次小小的失誤就會讓你丟了性命。$B$B你可以在南貧瘠之地找到雷霆蜥蜴，當你擊敗它們之後再回來見我。','收集3瓶雷霆蜥蜴的血液，把它們交給陶拉祖營地的喬恩·星眼。','','去貧瘠之地找陶拉祖營地的喬恩·星眼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 908 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (908,'zhTW','廢墟之間','暮光之錘已經進入了黑暗深淵中的月光神殿廢墟里去了，他們的目標肯定是要強迫元素生物來對付我們。如果我們不及早採取對策的話，這個地區就將永遠被他們控制。\\n\\n\\n\\n到黑暗深淵去找到廢墟中的深淵之石，它應該在靠近水邊的地方。深淵之石裡面是深淵之核——那裡面記載了所有元素生物的歷史。如果我擁有了它，我和大地之環就能阻止他們了！ ','把深淵之核交給梣谷佐拉姆加前哨站裡的耶努薩克雷。 ','','去找梣谷的耶努薩克雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 909 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (909,'zhTW','阿奎尼斯男爵','被擊敗的水元素留下了一個奇怪的水球，你猜想這東西可能是為水元素提供能量的。一股看起來就很噁心的水流在球體內翻騰噴濺，而球體本身似乎不受任何自然力的影響。$B$B如果說有人能對這個東西有所瞭解，那就只能是大地之環的耶努薩克雷了。他就在梣谷的佐拉姆加前哨站裡。','把奇怪的水球交給梣谷佐拉姆加前哨站的耶努薩克雷。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 910 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (910,'zhTW','降帆靠港','我聽過很多有關棘齒城和藏寶海灣的航海故事！我一直都夢想著能在海洋上航行並參加大型海戰，我長大後一定要成為偉大的部落水手！那一定很棒！$B$B你願意帶我去棘齒城的碼頭上看看嗎？我保證不會掉到水裡或者製造任何麻煩——我只是想看看大帆船，聞聞那帶著鹹味的海風！','帶著你看護的孤兒去貧瘠之地的棘齒城碼頭。','參觀貧瘠之地的棘齒城碼頭。','去找獸人孤兒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 911 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (911,'zhTW','前線之門','大家都說梣谷是新的前線戰場，而且我聽說貧瘠之地的摩爾沙農場是通往那裡的必經之處。想想看，部落的前鋒部隊在一片陌生的森林中為部落爭取榮耀，多酷啊！他們說那裡將會是聯盟和部落競爭最激烈的戰場，我要到那裡去，$N！$B$B你能不能帶我去摩爾沙農場，讓我看看新的前線是什麼樣子的？求求你了！我想要看看部落是怎麼把那些討厭的暗夜精靈趕出去的！','帶著你看護的孤兒去貧瘠之地北部的摩爾沙農場，它就在靠近梣谷入口的地方。','參觀貧瘠之地北部的摩爾沙農場。','去找獸人孤兒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 912 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (912,'zhTW','假扮成碎石怪','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 913 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (913,'zhTW','雷鷹的嘶鳴','雷鷹是一種兇猛的野獸，$n。現在你應該去挑戰它們了，把它們的翅膀給我帶回來，作為你獲勝的證明。$B$B完成這個任務，你就差不多可以結束在我這裡的訓練了。','找到一隻雷鷹，殺掉它，然後把它的翅膀交給陶拉祖營地的喬恩·星眼。','','去貧瘠之地找陶拉祖營地的喬恩·星眼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 914 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (914,'zhTW','尖牙德魯伊','哀嚎洞穴中的那些尖牙德魯伊，曾經是一些高尚的德魯伊，他們的目標是治癒貧瘠之地的創傷。然而，現在他們卻想把這片土地據為己有——曾經高貴的理想變成了扭曲的妄想，我們決不能讓他們得逞。$B$B尖牙德魯伊組織共有四個首領，我在夢中見過他們，即便是現在，他們的面孔仍然縈繞在我的腦海中。打敗他們，把他們的寶石給我拿來。$B$B去吧，$N。他們就潛伏在哀嚎洞穴的深處。','將考布萊恩寶石、安娜科德拉寶石、皮薩斯寶石和瑟芬迪斯寶石交給雷霆崖的納拉·蠻鬃。','','去莫高雷找雷霆崖的納拉·蠻鬃。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 915 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (915,'zhTW','草莓冰激凌','冰激凌！哦，求你了求你了，幫我買些冰激凌來吧？！我最喜歡草莓味的，而世界上沒有比提古勒和弗洛爾的草莓冰激凌更棒的冰激凌了！這是我最最喜歡的冰激凌！$B$B上次我在閃光平原的賽車場嚐到過它，不過現在我聽說他們開始在城裡出售冰激凌了！求求你了，我實在是太想嚐嚐提古勒和弗洛爾的草莓冰激凌了！','為你看護的孩子買一些草莓冰激凌。這個孩子似乎最喜歡“提古勒和弗洛爾”牌的草莓冰激凌。','','去找獸人孤兒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 916 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (916,'zhTW','樹林的腐敗','我是為了觀察居住在影絲洞的樹林蜘蛛才來到幽影谷的。我聽說了泰達希爾在最近賜下的祝福，照理說牠們應該不再具有那麼強的攻擊性才對。看來我被誤導了。$B$B最近我取得了一些牠們的毒囊，讓人憂慮的是，在它們裡面發現一種非常不健康的腐化。總而言之，如果我們放任被腐化的野生動物這樣子四處猖獗，我擔心會有不好的事情發生。$B$B我要你削減牠們的數量好爭取一點時間。','殺死12隻樹林蜘蛛。','','去泰達希爾找幽影谷的基爾沙蘭·風行者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 917 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (917,'zhTW','樹林蜘蛛的卵','仔細想想，或許你能夠再幫我一點忙。我來這裡是為了在洞穴深處取得一顆樹林蜘蛛的卵，但那些蜘蛛可不樂意。如果你能取得蜘蛛卵並帶回去給迪蘭妮亞，我們都會很感激的。','取得一顆樹林蜘蛛的卵。','','去泰達希爾找幽影谷的基爾沙蘭·風行者。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 918 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (918,'zhTW','樹精的種子','泰達希爾的樹精是代表自然的元素生物，它們以某種方式反映了我們這裡的自然生態的情況。$B$B所以看到樹精變得如此憤怒真讓人感到擔憂。$B$B我相信這與土壤有關。我一直在用不同的方法種植植物，可以用樹精的種子來試驗一下。我請求你，能在奧拉密斯湖周圍的樹精那兒收集一些種子給我嗎?','取得6顆樹精的種子。','','去找泰達希爾的德納蘭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 919 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (919,'zhTW','樹精的新芽','小樹精在奧拉密斯湖周圍和湧泉湖以西迅速成長。我害怕它們會的數量會多到無法控制!我們應該在它們惹出亂子之前把它們從土地上清除。$B$B你在湖邊行走的時候，如果看到任何樹精的新芽長出來，就順便除掉它。讓我們的土地免受污染!','收集10個樹精的新芽。','','去找泰達希爾的德納蘭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 920 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (920, 'zhTW', '特納隆的召喚', '你叫$n，沒錯吧?我聽說特納隆大人正在找你。你可以在奧達希爾樹冠的最頂層找到他。雖然我們的壽命很長，但你最好別讓他等太久。', '與幽影谷內奧達希爾頂部的特納隆·雷拳交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 921 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (921,'zhTW','泰達希爾:艾澤拉斯之冠','該是你出發追尋自己命運的時候了， $N 。但是在你走出我們美麗的森林之前，你應該先好好瞭解我們近代的歷史。$B$B有一個你必須去完成的任務。到奧達希爾北邊的月井裡裝一瓶水。在那裡，你將會短暫地瞥見我們的魔法，並了解我們的過去。$B$B當你完成後，帶著水去找特納隆·雷拳。你可以在奧達希爾頂端的西方坡道上找到他。','裝滿水晶之瓶。','','去泰達希爾找幽影谷的特納隆·雷拳。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 922 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (922, 'zhTW', '雷利亞·綠樹', '$N，你能給我的朋友雷利亞·綠樹帶去一粒種子嗎?他是個住在達納蘇斯的德魯伊，我們上次談話時，他對我的樹精研究工作很感興趣。他有自己的想法，如果有粒可以用來作試驗的種子的話，他一定會非常感激的。$B$B謝謝你，$N。你幫了我一個大忙。希望有一天你能看到我的勞動成果。$B$B你通常可以在達納蘇斯的塞納里奧區通道上看到雷利亞來回走動。', '給達納蘇斯的雷利亞·綠樹帶去一粒樹精的種子。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 923 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (923,'zhTW','青苔之瘤','在樹精之中有一股邪惡氣息正在蔓延。我們試著找出源頭，但在我們找到之前……為了維護泰達希爾的安全，我們必須砍掉那些已經無法挽救的樹精。在北方湧泉湖一帶遊蕩的樹精受到的污染最為嚴重，你必須消滅它們!$B$B消滅在那裡發現的樹精，收集生長在它們身上的青苔之瘤，然後把那些瘤交給我，讓我燒掉它們。','取回5個青苔之瘤。','','去達納蘇斯找貿易區的雷利亞·綠樹。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 924 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (924,'zhTW','惡魔之種','惡魔之種是燃燒軍團使用的一種強大工具，它生長在鬼霧峰洞穴裡的惡魔火壇上。$B$B我已經準備好了能量石，只要把它放在惡魔之種附近，就可以切斷它與燃燒軍團的聯絡。$B$B從石臺上取一塊能量石，把它帶到鬼霧峰上的火焰祭壇去。從這裡一直往西走，然後在交叉路口向北轉，鬼霧峰就在你的左邊。從鬼霧峰北坡爬上去應該是最安全的路線。$B$B動作快點——石頭的魔力在很短的時間內就會耗盡。','取一塊有瑕疵的能量石。在能量石失去魔法之前把它帶到火焰祭壇去，然後向雅克塞羅斯覆命。','','去找貧瘠之地的雅克塞羅斯。','摧毀惡魔之種','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 925 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (925,'zhTW','凱恩的蹄印','他們說凱恩·血蹄是部落有史以來最偉大的英雄之一。當我長大之後，我也要成為部落的英雄！$B$B你認識凱恩嗎，$N？你可不可以幫我個忙呢？你能不能幫我搞到他的蹄印？我不知道怎麼向他開口，他也許一直很忙而沒有時間理我……但是你可以！你是和他一樣偉大的冒險者！我打賭他會很樂意把蹄印給你的！$B$B求求你了！','到雷霆崖去，為你看護的孩子拿到一份凱恩·血蹄的蹄印。','','去找獸人孤兒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 926 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (926,'zhTW','有瑕疵的能量石','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 927 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (927,'zhTW','佈滿苔蘚的心臟','惡臭的黑苔獸的心臟上長滿了又黑又油膩的苔蘚。事實上，如果它沒有那緩慢而有節奏的心跳，也許你根本就看不出這是顆心臟來。$B$B也許德納蘭會想要研究一下這顆心臟。','將佈滿苔蘚的心臟交給奧拉密斯湖畔的德納蘭。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 928 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (928, 'zhTW', '大地之冠', '關於月井和泰達希爾的點點滴滴實在是太多了，我無法一一告知給你，這需要你自己去探索。科瑞薩斯·月怒正在等著你。我已經把你所帶回來的水倒入了這個容器中，把它送到科瑞薩斯那裡去吧。$B$B出發吧，科瑞薩斯就在多蘭納爾的月井旁。你只需要沿著奧達希爾南邊的小路走出幽影谷，沿著鵝卵石鋪成的小路一直走，然後向西轉就行了。$B$B注意，你要一直沿著路走，$n。最近路旁的森林裡出現了許多危險的野獸。', '將裝著半瓶水的瓶子交給多蘭納爾的科瑞薩斯·月怒。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 929 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (929,'zhTW','泰達希爾:大自然的回絕','讓我告訴你所必須完成的任務的其他一些細節。達納蘇斯的德魯伊需要使用泰達希爾的月井的水，所以月井的水需要不斷地補充。使用這種特製的瓶子，你可以收集起月井之水。$B$B帶著這個瓶子去星風村外東邊的月井，裝滿水，再帶回來給我。注意聆聽月井給予你的訓誡，以免我們不斷擴張自己的缺點。','裝滿翡翠之瓶。','','去泰達希爾找多蘭納爾的科瑞薩斯·月怒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 930 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (930, 'zhTW', '發光的水果', '一顆又大又圓的果實掛在葉下。$B$B你覺得德納蘭一定會想要研究一下這東西。', '把這顆發光的水果交給奧拉密斯湖的德納蘭。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 931 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (931,'zhTW','發光的樹葉','植物上的葉子泛著微弱的光，產生了一種不斷變化的光暈。$B$B你覺得德納蘭可能會想要研究這種東西。','給奧拉密斯湖畔的德納蘭帶去1片發光的樹葉。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 932 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (932,'zhTW','扭曲的仇恨',' $N ，我必須警告你，我們不能對這件事袖手旁觀。薩特已經夠我們頭疼的了，而眼前的這件事更是一個潛藏在身邊的危機。$B$B有個名叫邁雷納斯領主的惡棍就住在北邊附近的惡魔石洞穴裡，他在那兒聚集了一大批劣魔戰士。他的心就像夜晚一樣黑，而他的計畫一定極度黑暗邪惡。$B$B你必須在北邊附近的洞穴中找到他，帶他的頭回來見我。','取得邁雷納斯領主的頭顱。','','去泰達希爾找奧拉密斯湖的塔隆凱·捷根。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 933 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (933,'zhTW','泰達希爾:黎明將至','我想要你到此處的正南方去拜訪最後一口月井，就在亞里斯瑞恩之池的岸邊。尋找那口井時務必小心，隨時準備拔出武器。我感覺在泰達希爾南部有著日益增長的腐化。$B$B當你拿到水時，我希望你將它帶去給池邊的一張熟面孔。她想要和這種腐化戰鬥，並且是她親口要求你的協助。','裝滿紅玉之瓶。','','去泰達希爾找多蘭納爾的科瑞薩斯·月怒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 934 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (934,'zhTW','大地之冠','然而泰達希爾並不是一切都盡如人意。範達爾·鹿盔對於世界之樹的計劃正如他自己所希望的那樣一步步展開了，但是還有一個小問題，這個問題或許會給泰達希爾帶來一些麻煩。$B$B不過我不打算介入此事。你得去一趟最後一口月亮井，就在這裡西北面的神諭林地裡，就在神諭之樹的樹幹下面，那是我們的第一口也是最強大的一口月亮井。在那裡灌一瓶水，然後回來向我報告。','用月亮井的水裝滿紫水晶瓶，然後把它交給多蘭納爾的科瑞薩斯·月怒。','','去泰達希爾找多蘭納爾的科瑞薩斯·月怒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 935 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (935, 'zhTW', '大地之冠', '沒有生命守縛者雅立史卓莎和時間之王諾茲多姆的祝福，泰達希爾的成長就很難一帆風順。我不斷收到有奇怪的猛獸出現的報告，而瘋狂的熊怪也開始不斷地襲擊路人。$B$B我只能希望大德魯伊們能儘快找到解決的方法。我會將把你帶來的所有月井水都灌入這個瓶中，然後讓你把它帶到達納蘇斯去。$B$B把這只瓶子交給范達爾·鹿盔，你可以在德魯伊之林裡找到他。', '將裝滿月井水的瓶子帶給在達納蘇斯的大德魯伊范達爾·鹿盔。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 936 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (936,'zhTW','協助大德魯伊','打擾一下，$c，如果可能的話，我想佔用你一點時間。$B$B雷霆崖的塞納里奧議會希望能找到像你這樣經驗豐富的冒險家來幫助他們進行一項重要的研究專案。雖然我不知道詳細的情況，但是我可以告訴你，正是哈繆爾·符文圖騰親自負責這項研究。$B$B要是你感興趣的話，請直接去雷霆崖的長者高地找他談談。','與雷霆崖的大德魯伊哈繆爾·符文圖騰談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 937 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (937,'zhTW','神諭林地','我和一個哨兵小組被派到這裡來保護神諭之樹免受鷹身人的威脅。她們已經在沼澤周圍建造了很多巢穴，我們正在試著把它們趕回去。$B$B神諭之樹曾派信差到達納蘇斯去通報這一情況，但一群鷹身人在中途殺死了那個信差。$B$B如果你認為你能勝任這項任務的話，就到她們的巢穴裡去，殺死她們，把她們的腰帶拿回來作為證明。','收集6條血羽腰帶，把它們交給神諭林地裡的哨兵阿瑞尼亞‧裂雲。','','去泰達希爾找湧泉湖的哨兵阿瑞尼亞·碎雲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 938 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (938,'zhTW','密斯特','這隻獵豹的毛皮是很特別的暗灰色，與四周的森林幾乎融為一體。她靜靜地躺在地上，你發現她傷得很重，背部和腹部都有很深的傷口。$B$B她抬起頭盯著你，藍色的雙眼閃著智慧的光芒。她似乎希望跟隨你。','護送密斯特去神諭之樹附近的月亮井旁找哨兵阿瑞尼亞·碎雲。','把密斯特領到哨兵阿瑞尼亞·碎雲身邊','去泰達希爾找神諭林地的哨兵阿瑞尼亞·碎雲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 939 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (939,'zhTW','薩瓦里克長笛','打敗薩瓦里克之後，你仔細看著從他的屍體上拿到的木製長笛。$B$B這根帶節的木棍摸起來很結實，但是當你把它拿在手中翻看時，笛子表面的紋理似乎突然開始旋轉了起來。你猛然間感覺到了一絲恐懼……$B$B你搖了搖頭，感到這可能是你的感覺在和你開玩笑。$B$B可能其它的薩特身上有關於你所發現的東西的線索。將你發現的線索交給費伍德森林南部的德魯伊，艾瑞丹·藍風。','將薩瓦里克長笛和5個碧火魔符交給費伍德森林南部的艾瑞丹·藍風。','','去費伍德森林找翡翠聖地的艾瑞丹·藍風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 940 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (940, 'zhTW', '泰達希爾', '你的事蹟在森林裡傳揚，$n。鷹身人已經被趕走，森林恢復了平靜，這裡的生物再次感受到了安全和寧靜。我幾乎已經不敢派信差去大德魯伊那裡了，但我知道你會幫我把資訊安全送達的。$B$B把消息傳遞給他，我知道森林將保佑你安全地將資訊送達目的地。', '把神諭之樹的報告交給達納蘇斯的大德魯伊范達爾·鹿盔。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 941 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (941,'zhTW','培養心臟','我已經除去心臟上的苔蘚，但它早已經被汙染了……$B$B把心臟放到我的培養槽裡，營養豐富的土壤也許能淨化並治癒這顆心臟。','把被汙染的心臟放到德納蘭的培養槽裡。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 942 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (942, 'zhTW', '健忘的勘察員', '這塊化石和我在鐵爐堡看到的一塊化石非常的相似。一個名叫弗拉岡特的考古學家把它帶到了我們一年一度的冒險者年會上。他堅信那塊化石中蘊藏著奇特的魔力，而且那種魔力是可以被提取出來的。$B$B上一次我聽到弗拉岡特的名字時，他還住在米奈希爾港的深水旅店裡，正在等著被護送到維爾加挖掘場去。把霍利恩的化石交給他，也許他能揭開化石中蘊含著的秘密。$B$B去米奈希爾的船都是從奧伯丁出發的。', '把神秘的化石交給米奈希爾港的考古學家弗拉岡特。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 943 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (943,'zhTW','健忘的勘察員','嗯，我在那裡會議之後把原始樣品交給了勘察員維爾。最近，我在洛克莫丹發現了雷魯之石，我認為它就是解開神秘化石的鑰匙。$B$B當我準備趕往維爾加挖掘場的時候，遭到了迅猛龍的攻擊，雷魯之石也給弄丟了。$B$B我不知道是哪只迅猛龍吞掉了這塊石頭，但如果你能找回它，我應該就可以釋放這些化石中的魔力了。當然，我們也需要最初從維爾加挖掘場取回的那枚化石。','米奈希爾港的考古學家弗拉岡特要你把雷魯之石帶給他。','','去濕地找米奈希爾港的考古學家弗拉岡特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 944 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (944,'zhTW','主宰之劍','我很奇怪納迦為什麼會出現在這裡，在黑海岸。但更奇怪的是...暮光之錘。那些信徒崇拜非常非常古老的大地之神，一個很久以前就被打敗的神。$B$B主宰之劍就是那個古神被打敗的地方。$B$B去那裡找到更多暮光之錘的信徒。$B$B帶上這個占卜之瓶。等你到了主宰之劍之後，就用它製造一個占卜之碗，通過那個碗，你可以直接和我通話。','收集資訊，然後使用占卜之瓶創造出一個占卜之碗，並利用這個碗和安努通話。','進入主宰之劍。','去找占卜之碗。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 945 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (945,'zhTW','護送瑟瑞露尼','救命呀!$B$B我正在主宰之劍附近散步的時候，這些骯髒的傢伙包圍了我。多虧我善於隱藏才沒有被他們找到!我很厲害吧!$B$B你能幫我離開這裡嗎?還有還有，你能不能給我姐姐瑟瑞希爾捎個口信，告訴她我平安無事?要不然她會擔心死的。她住在艾森娜神殿裡，那地方就在南方的梣谷森林裡。','幫助瑟瑞露尼逃跑，然後告訴在艾森娜神殿的瑟瑞希爾，她的妹妹目前很安全。','護送瑟瑞露尼離開主宰之劍。','去找瑟瑞希爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 946 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (946,'zhTW','<UNUSED>','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 947 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (947,'zhTW','洞中的蘑菇','我正在研製一種藥劑，需要一種生長在特定洞穴裡的稀有蘑菇才能配製。這個洞穴位於壁泉河瀑布的後面，在東邊稍稍偏北的地方。$B$B我本來準備自己去，不過古樹之林建議我不要靠近那個地方。我們尊貴的盟友覺得那個洞穴是黑海岸新出現的邪惡勢力的藏身之處。$B$B $N ，請你幫我收集那些蘑菇。與此同時，請察看一下那處洞穴以便確認古樹所擔心的事情。','收集5個粗柄蘑菇和1個毒帽蘑菇，把它們交給奧伯丁的巴瑞薩斯‧月影。','','去黑海岸找奧伯丁的巴瑞薩斯·月影。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 948 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (948, 'zhTW', '安努', '古樹之林裡的一棵知識古樹安努得知了你到壁泉河瀑布去的這次旅行，他希望和你談談。古樹之林就在南方的山麓附近。這些古樹耐心而充滿睿智，$N，不過，如果是安努找你是為了向你詢問瀑布一帶的情況，我想事情一定非常緊急。', '和古樹之林的安努談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 949 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (949, 'zhTW', '暮光之錘的營地', '暮光之錘來到主宰之劍的目的還不得而知，不過肯定是為了某些不可告人的邪惡目的。到主宰之劍去搜尋他們的營地……設法查出他們準備幹什麼。在制定計劃之前，我們必須首先知道他們的意圖。', '到位於主宰之劍的暮光之錘營地去尋找線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 950 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (950, 'zhTW', '向安努回覆', '仔細閱讀暮光之書會讓人發瘋。只要盯上一小會兒，書上的字就開始遊動亂舞，原本美妙的插圖和花邊也扭曲得變了形。$B$B為了不至於讓神志陷入混亂之中，你只好趕快撕下了一張寫著這些可怕的文字的書頁。', '把令人發狂的書頁交給安努。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 951 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (951,'zhTW','瑪塞斯特拉聖物','你在主宰之劍找到的那頁書來自於一本古籍...一本精靈撰寫的古籍。但它已經被暮光之錘詛咒和玷污了，看來暮光之錘的信徒是希望用古代精靈的魔法將他們古老的主人重新召回我們的世界。$B$B到東北邊的瑪塞斯特拉廢墟去看看，找到那些古代的聖物。如果我能研究一下它們的話，也許能搞清楚暮光之錘打算如何使用那些精靈的魔法。','收集6個黑暗深淵聖物，把它們交給古樹之林的安努。','','去黑海岸找暮光谷的安努。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 952 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (952, 'zhTW', '古樹之林', '如果你有時間為神諭之樹跑跑腿的話，我想讓你幫我送一封信到黑海岸的古樹之林去。$B$B你大概只有乘角鷹獸才能到黑海岸，不過我相信你絕對可以完成這個任務。把這個交給知識古樹安努，他正等著我的消息，就像我曾焦急地等待來自神諭林地的消息一樣。', '把范達爾的信交給黑海岸古樹之林裡的安努。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 953 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (953,'zhTW','亞米薩蘭的毀滅','到東邊去就可以發現亞米薩蘭廢墟。現在，那些未曾安息的 $R 貴族的亡靈如同生前一般盤踞在那裡，那裡也曾經是艾薩拉的僕人練習他們強大魔法的地方。$B$B我在奉命探索那片廢墟的時候偶然發現有兩塊巨大的石碑，上面是潦草寫下的亞米薩蘭的故事，還有這座城市被毀滅的歷史。在我閱讀碑上的刻文的時候,突然有亡靈出現和我說話，嚇得我趕緊逃了回來。$B$B如果你夠膽量的話就去一趟那片廢墟，替我破譯一下石碑上的刻文。','研究刻有亞米薩蘭的故事及其被毀經過的石碑，然後回到黑海岸的哨兵坦莎‧月刃那裡。','','去黑海岸找亞米薩蘭的哨兵坦莎·月刃。','閱讀《亞米薩蘭謠曲》','閱讀《亞米薩蘭的陷落》','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 954 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (954, 'zhTW', '巴莎蘭', '有一群惡魔的爪牙在東部的巴莎蘭遺跡裡到處橫行。佔據了那裡的劣魔和薩特瘋狂地汲取著該區的魔法能量，致使牠們的魔力不斷地迅速膨脹。但是，我注意到那裡有一處牠們始終無法接近的神殿。就在遺跡西側的小峭壁上，彌漫著奇特的藍光……一定有什麼原因使得惡魔不願靠近那裡。我希望你去調查一下。', '到巴莎蘭廢墟尋找奇怪藍光的源頭。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 955 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (955,'zhTW','巴莎蘭','如果要我把一生的故事都講出來，恐怕你會失去耐心。簡單地說，我的一生漫長而痛苦，而現在這種鬼靈般的生活更是對我最痛苦的折磨。$B$B我被魔法囚禁在這裡。也許我說的話有些誇張，但我可以向你發誓，如果你能幫我找到從這裡逃脫的辦法，我一定會對你感激不盡的。現在我被施加了封印，如果你能幫我拿些薩特和劣魔的耳環，我也許能找到一些線索。','幫巴莎蘭的阿斯特利安收集8只劣魔耳環。','','去黑海岸找薄霧海的阿斯特利安。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 956 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (956,'zhTW','巴莎蘭','如果劣魔開始與施加在我身上的封印頻頻聯繫的話，我想我已經猜到原因了。毫無疑問，這枚封印已經落入指揮他們的薩特的手中。$B$B我強烈地感覺到了這一點， $N 。某個薩特得到了那個封印。如果你能得到它，或許就可以幫我衝破這牢籠，我將對你不勝感激。','獲取遠古月亮石封印，把它交給巴莎蘭的阿斯特利安。','','去黑海岸找薄霧海的阿斯特利安。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 957 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (957,'zhTW','巴莎蘭','某位非常強大的貴族製造了這個用來囚禁我的封印。在南方的亞米薩蘭有一處與這裡相似的廢墟，那裡至今仍燃燒著遠古的火焰，那藍色的火焰可以摧毀這個封印。$B$B不過在那片廢墟裡，你千萬要當心， $N ...','用亞米薩蘭廢墟中的遠古火焰摧毀遠古月亮石封印，然後回到巴莎蘭的阿斯特利安那裡。','','去黑海岸找薄霧海的阿斯特利安。','摧毀古老聖焰處的封印','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 958 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (958,'zhTW','精靈貴族的工具',' $C ，我有一項任務交給你。$B$B你去過亞米薩蘭廢墟嗎?如果還沒有，你可以在通向南方的大路東側找找看。亞米薩蘭廢墟曾經是眾多 $R 貴族的家園，而如今那裡卻成為他們濫用魔法的見證。$B$B據哨兵的報告，那些貴族的亡靈依然在使用古代的魔法武器進行抵抗。我們必須獲得那些聖物，只有這樣我們才有可能真正摧毀那些亡靈。','幫奧伯丁的桑迪斯‧織風取回7個精靈貴族的聖物。','','去黑海岸找奧伯丁的桑迪斯·織風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 959 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (959,'zhTW','港口的麻煩','啊呀!$B$B你也看到了，最近有點倒霉!早間從藏寶海灣過來了一支大型的運貨船隊，我是說大型的!我從沒有見過那麼多的木箱。我想加快點速度，所以卸貨卸得稍微快了點。$B$B結果呢，還沒等我弄清楚是怎麼回事兒，我看到那個可惡的傢伙─瘋狂的馬格利什─手拿一瓶99年波爾多陳釀跑了出來。我一路追他到了哀嚎洞穴，但是我可不想進到那個可怕的地方去。$B$B嗯……你夠不夠膽量去把他給我找出來?','棘齒城的起重機操作員比戈弗茲讓你從瘋狂的馬格利什那兒取回一瓶99年波爾多陳釀，瘋狂的馬格利什就藏在哀嚎洞穴裡。','','去貧瘠之地找棘齒城的起重機操作員比戈弗茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 960 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (960,'zhTW','安努正在沉思','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 961 AND `locale` = 'zhTW';
