INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (962,'zhTW','毒蛇花','幽暗城的皇家藥劑師學會派我來這兒完成一個特殊的任務， $N 。我想你會願意幫助我的，因為黑暗女王領導下的被遺忘者將會通過我的任務得到進一步的加強。$B$B近來我在研究一種罕見的植物，它的名字叫毒蛇花，我相信這種藥草有著巨大的能量。$B$B不幸的是，它只生長在哀嚎洞穴的最深處，那是貧瘠之地最危險的洞穴之一。','為雷霆崖的藥劑師札瑪收集10朵毒蛇花。','','去找莫高雷的藥劑師扎瑪。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 963 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (963,'zhTW','永志不渝','永恆之井的戰鬥結束以後，亞米薩蘭被毀滅了，全城的 $R 都成為了這座城市的陪葬，其中就有我的至愛安娜雅。$B$B我也沒有想到，在那次災難過去了數千年之後，對安娜雅的回憶依然縈繞在我的夢中。有一次，當我恍恍惚惚地在黑海岸的森林裡遊蕩的時候，我發現自己正置身於亞米薩蘭的廢墟之中……我居然看見了我的至愛─她那飽受折磨的亡魂。$B$B她必須得到自由，但我沒有勇氣去做，因為讓她得到自由，就必須先摧毀她的亡靈。','釋放安娜雅·曦奔的靈魂，把她的墜飾交給奧伯丁的塞瑞利恩·白爪。','','去黑海岸找薄霧海的塞瑞利恩·白爪。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 964 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (964, 'zhTW', '骷髏碎片', '通靈學院大門的鑰匙名叫骷髏鑰匙，它一定是由某具骷髏製造而成─事實上是若干具骷髏─並在適當的模具中使用最堅硬的金屬進行加固。天生就能打開通靈學院大門的人擁有一種特殊的力量，這種力量能讓鑰匙發揮作用。$B$B重要的事情要優先處理掉，$N。我們需要一些骷髏碎片來製造鑰匙。安多哈爾內的骷髏應該符合我們的要求，但是安多哈爾城外的那些骷髏也許同樣有效。', '將15塊骷髏碎片交給西瘟疫之地亡靈壁壘的藥劑師迪瑟斯。', '', '去找提裏斯法林地的藥劑師迪瑟斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 965 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (965, 'zhTW', '奧薩拉克斯之塔', '歡迎你，年輕的$r。我是艾麗莎·星風，保衛奧伯丁不受邪惡勢力的侵害是我的職責。正因為如此，我派巴蘇爾·影擊去調查東北方的奧薩拉克斯之塔，那裡最近發生了一些怪事。他早就應該回來了，我擔心他在森林裡碰到了危險，如果你能幫我找到他，並看看他是否一切安好的話，我會非常感激你的。', '在黑海岸的奧薩拉克斯之塔附近找到巴蘇爾·影擊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 966 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (966,'zhTW','奧薩拉克斯之塔','一群術士在這座塔的裡裡外外住了下來。我本應該早些回去向艾麗莎報告，但我想如果我親自去報告的話也許會錯過些什麼。$B$B德爾葛蘭懷疑這夥人聚集在塔周圍是要密謀什麼壞事，但我們對此所知甚少。$B$B我手裡有一些術士的羊皮卷軸碎塊，但我還需要更多的碎塊才能解開這個謎。對了，我必須警告你，千萬不要冒險進入塔中，因為塔裡的術士非常可怕!','在奧薩拉克斯之塔附近幫巴蘇爾‧影擊收集4塊破舊的羊皮紙。','','去找黑海岸的巴蘇爾·影擊。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 967 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (967, 'zhTW', '奧薩拉克斯之塔', '我的主人，『淨化者』德爾葛蘭，是一位偉大的聖騎士。為了保護森林不受惡魔和不死生物的襲擾，德爾葛蘭一直在盡全力幫助我們。他向我傳授了聖光術和各種其他的戰鬥技巧。$B$B你必須儘快把這個教派的消息告訴德爾葛蘭。$B$B他就駐紮在南方的梣谷森林裡的邁斯特拉崗哨。請快一點，我非常擔心這個暗灘教派帶來的威脅會越來越大。', '把巴蘇爾的信送給梣谷森林中的『淨化者』德爾葛蘭。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 968 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (968,'zhTW','深淵之神','儘管這本書又舊又破，但你依然能看清封面的標題：$B$B深淵中的力量$B$B在這本皺巴巴的書裡是一串不知如何發音的名字的列表，這些名字後面都注有令人感到不安的頭銜稱謂、祭祀的方式以及首選的祭品等等……其中很多祭品是活的人型生物。$B$B在封面的內側有這樣的文字：“葛利·硬骨的符文和厄運，鐵爐堡……經營者：葛利·硬骨。”$B$B如果葛利·硬骨賣的是這樣的書，那麼也許他會把這本書買回去。','把《深淵之神》交給鐵爐堡的葛利·硬骨。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 969 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (969,'zhTW','祝你好運','啊，我一看見你就知道——你想要一個幸運符咒。瑪艾裡無所不知！$B$B在冬泉谷的南部有一道峽谷，那裡的巨人身上有時候帶有一種具有強大能量的冰塊，當然你也可以自己從峽谷中收集冰塊碎片。$B$B帶給我十片霜槌碎片回來，然後我的幸運符咒就是你的了。','收集4塊霜槌碎片，把它們交給永望鎮的巫醫瑪艾裡。','','去冬泉谷找永望鎮的巫醫瑪艾裡。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 970 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (970,'zhTW','奧薩拉克斯之塔','巴蘇爾的這封信裡的消息真是可怕。這個暗灘教派對我們而言始終是一個很大的威脅，必須儘快清除才行。我和東北方的奧迪拉蘭中的暗灘教派打過交道，他們中的一個人持有一枚靈魂寶石，其中蘊藏著有關這個教派力量來源的秘密。$B$B把它交給我，我應該有辦法從中找出一些資訊來。','搜集一枚發光的靈魂寶石，並把它交給邁斯特拉崗哨的『淨化者』德爾葛蘭。','','去梣谷找邁斯特拉崗哨的淨化者德爾格倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 971 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (971,'zhTW','深淵中的知識','收集傳說是我的義務。古老的傳說。強大的傳說。能開啟門扉的傳說，以及如果不好好處理，將能喚醒那些「沈睡者」的傳說。$B$B根據傳聞，有個古老傳說的片段，洛迦里斯手稿，就在西邊那處黑澗深淵的最底部。那地方是我們逝去已久的祖先的古老居處。在他們的城市淪為廢墟之前，他們掌握著偉大的知識。$B$B去黑澗深淵尋找那份手稿。我將不會忘記你曾為我這樣做。即使在這樣的末日之中。','將洛迦里斯手稿帶去黑澗營地給哨兵受訓員伊薩拉。','','去找丹莫洛的葛利·硬骨。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 972 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (972,'zhTW','水之靈契','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 973 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (973,'zhTW','奧薩拉克斯之塔','伊克魯德·瑪格蘇爾，沒錯，我瞭解他。他可是一個強大的獸人術士，就住在火痕神殿裡，那是一個位於梣谷西南的極端邪惡的地方。$B$B至今他並沒有給我們造成太大的麻煩，而我也沒工夫去對付他，不過現在看起來…他的死期到了。','把伊克魯德·瑪格蘇爾之書交給邁斯特拉崗哨的『淨化者』德爾葛蘭。','','去梣谷找邁斯特拉崗哨的淨化者德爾格倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 974 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (974,'zhTW','究根問底','對我來說，這裡的溫泉簡直就是個不解之謎，這些熱量究竟是哪裡來的？$B$B這些水池離火羽山那麼近，我真的想知道火山和溫泉之間到底有沒有關係。我製作了一個測溫計來讀取火山的溫度，我想要找到溫度最高的地方。它是按照我獨創的計量單位進行測量的！$B$B拿著這個溫度計，當你經過某個炎熱的地方，就順便讀取一下那裡的溫度！','安戈洛爾環形山的克拉蘭克要你去找到火羽山中溫度最高的地方。$B$B當你找到一個看上去很熱的地方時，就右鍵點選溫度計來測量當地的溫度。不斷嘗試，直到你找到溫度最高的地方。','','去安戈洛環形山找葛拉卡溫泉的克拉蘭克。','找到火羽山上最熱的地方','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 975 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (975,'zhTW','瑪艾裡的容器','在給你符咒之前，我最好解釋一下如何使用它。$B$B如果你戴上符咒，你就可以從那些被你幹掉的生物身上得到特殊的物品，如果你沒有戴上符咒的話，那你就得不到那些物品，懂了嗎？$B$B這些物品的名字叫做魂精。如果你找到它們，就把它們交給瑪艾裡，她會幫你解決剩下來的事情。$B$B在我給你修理符咒的時候，請在這裡等一會兒。','與巫醫瑪艾裡再次談話，然後拿到好運符。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 976 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (976,'zhTW','奧伯丁的補給品','德爾葛蘭讓我給奧伯丁的哨兵艾麗莎·星風捎信，順便給她提供一定的補給，但是我討厭一個人上路。密林深處到處危險的敵人，我可不想讓這些物資和資訊落到他們的手裡。$B$B如果你或者其他人能擔當我的護衛，我們現在就可以出發了。有你的幫助，我堅信這些物資一定能平安運抵奧伯丁。','護送費羅·艾隆漢安全地穿越梣谷森林，再與邁斯特拉崗哨的『淨化者』德爾葛蘭談話。','護送費羅·艾隆漢','去梣谷找邁斯特拉崗哨的淨化者德爾格倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 977 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (977,'zhTW','雪怪計劃！','現在我已經有了遮蓋機體的東西，然後只需再有一件東西就成了。好吧，實際上是兩件。兩支角！$B$B冰薊雪人王和冰薊雪人女王身上都有這樣的角，它們就住在東南邊的洞穴裡。那裡的雪人數量眾多，我想你不會找不到它們的。$B$B記住，我只要外觀最好的角——絕對不要有傷痕的或者破碎的角！','為永望鎮的烏米收集2支完美的雪人角。','','去冬泉谷找永望鎮的烏米。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 978 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (978,'zhTW','月光羽毛','從辛特蘭收集到的梟獸羽毛中包含著魔法能量的痕跡。這些能量……看來並不是梟獸能夠運用的，它們只是簡單地蘊含在這些生物體內——而帶有這種能量的都是最強悍的梟獸。$B$B在研究這個問題的過程中，我聽說在白雪皚皚的冬泉谷那有很多的梟獸。那些生物是否攜帶著相同的能量呢？請幫我找到這個問題的答案，$N。到冬泉谷去收集它們的羽毛，然後把它們交給我。','從冬泉谷收集10片月光羽毛，然後將它們帶給魯瑟蘭村的艾瑞拉斯·琥珀。','','去泰達希爾找魯瑟蘭村的艾瑞拉斯·琥珀。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 979 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (979,'zhTW','蘭莎爾拉','嗯，嗯，這些羽毛上附著的魔法似乎與我以前見到過的很類似……雖然我並不能確定我們會發現什麼，但我想你必須繼續追查下去，$n。$B$B我的一位同事最近到冬泉谷去觀察當地梟獸的生態了，你為什麼不去找她談一談，看看她有些什麼發現呢？','在冬泉谷找到蘭莎爾拉。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 980 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (980,'zhTW','新的泉水','我聽說在北邊的冬泉谷裡還有其它的溫泉。奇怪的是，那地方並沒有任何火山的存在。這聽起來很有趣，對嗎？$B$B好吧，如果你想要查個水落石出，那就到冬泉谷去跟我的朋友談一談吧。他的名字叫做多諾瓦·雪山，現在就在那溫泉附近。$B$B溫度計的事情真是太感謝你了，祝你好運，再見！','到冬泉谷去和多諾瓦·雪山談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 981 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (981, 'zhTW', '奧薩拉克斯之塔', '你應該為你所作出的貢獻而得到獎勵。回到德爾葛蘭那裡，告訴他埃瑟里克斯·納拉辛已經死在你的手下，暗灘教派也已經被打得一敗塗地，潰不成軍。', '和邁斯特拉崗哨的『淨化者』德爾葛蘭談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 982 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (982,'zhTW','深不可測的海洋','從我們現在所在位置沿著海岸一直往北可以看到兩艘沉船-銀色清晨號和迷霧之紗號。這兩艘船在穿越茫茫大海，最終將要達到奧伯丁的時候遇到了那些可惡的魚人，它們現在只能躺在海底作為那些惡棍的戰利品了。$B$B這兩艘船的船長都沒有能倖免於難，他們的日誌以及其他有價值的東西還鎖在船裡的帶鎖箱中。我希望你能幫我找到這些東西，這對於那些生還的船員也是頗有意義的。','找到銀色清晨號的帶鎖箱和迷霧之紗號的帶鎖箱，把它們交給奧伯丁的高爾博多‧鋼手。你可以在村莊北部遇難的船隻裡找到這兩隻帶鎖箱。','','去黑海岸找奧伯丁的高爾博德·鋼手。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 983 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (983,'zhTW','傳聲盒827號','嘿!看看我這劃時代的最新發明:傳聲盒!通過它，你可以和很遠的人進行交談!$B$B也許你已經見過它們了，嗯，就是那些上面有操縱杆的盒子。不過傳聲盒有一個毛病，就是它們需要經常性的維護。$B$B而且每一個盒子的問題都不一樣，不過我在這個問題上做得就很巧妙!你看，我把每一個盒子都放在那些能給它提供最合適的修理零件的生物附近。現在傳聲盒827號出了點故障，它就在奧伯丁的南邊，需要6隻蟹腿來進行修理。我會獎賞你的...','收集6隻蟹腿，把它們放進傳聲盒827號。','','去黑海岸找奧伯丁的傳聲盒827號。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 984 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (984,'zhTW','熊怪的威脅',' $N ，我來這裡是想看看魔苔的影響有多麼厲害。我的一些同胞險些被泰達希爾的一個墮落的熊怪殺死，而我發誓不會讓類似的情況再次出現...更別提更糟糕的情況了。$B$B在黑海岸，我已經看見了一系列有關各種生靈墮落的線索，但我需要找到這種墮落是否有蔓延的跡象。我想我們仍然應該通過熊怪來進行調查，你可以幫我找到一個熊怪的營地嗎?如果你發現了任何情況，就馬上回來報告我。','在黑海岸找到一處墮落熊怪的營地，然後向奧伯丁的特倫希斯報告。','找到一處墮落的熊怪營地。','去黑海岸找奧伯丁的特倫希斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 985 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (985,'zhTW','熊怪的威脅',' $N ，在偵察敵人方面，你已經展示了足夠的才能。但你與他們作戰的技能如何呢?$B$B並不是所有的冒險者都喜歡面對面的遭遇戰，我是某些冒險者更喜歡潛行之類的隱秘行動。$B$B如果你覺得自己能行，就到奧伯丁南邊的那個熊怪營地吧，那裡的熊怪對我們構成了極大的威脅。在那一帶活動的都是黑木部族的熊怪，去殺掉8個黑木探路者和5個黑木風語者，然後回來向我報告。','殺掉8個黑木探路者和5個黑木風語者，然後回到奧伯丁向特倫希斯彙報。','','去黑海岸找奧伯丁的特倫希斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 986 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (986,'zhTW','丟失的主人',' $N ，你幫了我很多忙，我能不能再請求你幫助一下銳爪和他的主人沃科爾?我可以幫你精心製作一件有魔力的披風，它能夠讓你在尋找沃科爾時暢通無阻，免受黑海岸上任何猛獸的阻撓。$B$B不過要製作這件披風，我需要從月夜雄虎或者月夜雌虎身上獲取幾張張上等毛皮。你可以在急彎河以南找到那些月夜猛虎。','收集5張優質月夜猛虎毛皮，把它們交給奧伯丁的特倫希斯。','','去黑海岸找奧伯丁的特倫希斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 987 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (987,'zhTW','暫無內容','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 988 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (988,'zhTW','暫無內容','$N，我注意到你身上穿著的那件斗篷。如果你願意把它給我的話，我可以恢復附在斗篷上的魔法，然後利用它逃脫。不過問題是，這樣一來你就得一個人留在洞裡了。$B$B如果我們這樣做的話，你一個人能離開這裡嗎？$B$B如果你關心的是報酬的話，我向你保證，特倫希斯會因為你搭救了我而獎勵你。$B$B你來作出選擇吧，不過我確實需要你的幫助。','和沃科爾談一談。','','去找費伍德森林的沃科爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 989 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (989,'zhTW','暫無內容','如果我們決定殺出一條血路，那麼計劃很簡單：我們沿著這條路向前走，殺掉所有膽敢阻擋我們去路的熊怪……以及其它一切想阻止我們前進的傢伙。$B$B我希望有別的辦法，但是熊怪的威脅早晚也得要解決。既然如此，那還不如由我們自己親手來做，這樣我們還能幫奧伯丁緩解一些壓力。$B$B準備好一切你手頭上的魔法或者武器，然後我們就殺出去。','和沃科爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 990 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (990, 'zhTW', '梣谷之旅', '$N，我的主人萊恩·狼行者正在梣谷的阿斯特蘭納城中等你。有了你的幫助，我們至少能稍微控制一下那裡混亂的局勢。從這兒向南走，沿著路一直前進─只要跟著那些指示牌，你應該不會迷路的。', '在梣谷中找到萊恩·狼行者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 991 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (991, 'zhTW', '萊恩的淨化', '$N，我有一個老朋友也正為梣谷的哨兵部隊提供援助，不過他還沒有回來。他正在尋找一件東西，一件他認為可以延緩熊怪對我們的同胞發起進攻的物品，由一個早已死掉的邪惡巫師製造的魔棒。在他離開這兒以前，他曾說過要去尋找一塊寶石，這塊寶石能幫他找到那根魔棒。他提到這塊寶石很可能就藏在法拉希姆湖的神殿中，那座神殿就坐落在西邊的山腳下。在寶石被人取走之前，它一直都放在那裡。請去找到我的朋友，$N。', '在梣谷找到泰洛尼斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 992 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (992,'zhTW','加基森水業公司','如果你感興趣的話，我們現在正在為加基森水業公司招聘兼職初級勘探員。$B$B那些遊牧民不斷地侵佔我們的水井，這迫使我們不得不去勘探更多的水源！沙漠中到處都可能有水的存在，但是隻有聰明人才能找到它們。$B$B拿著這個瓶子，到流沙崗哨旁的水池那裡幫我採集一些水樣回來。那個水池旁邊有些巨魔在看守著，小心點，完成任務之後儘快把水樣送到我這裡來。','用未使用的尋水器在流沙崗哨旁邊的池中採集水樣。一旦你收集到水樣，就儘快將其交給加基森的高階勘探員菲茲杜瑟。','','去塔納利斯找加基森的高階勘探員菲茲杜瑟。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 993 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (993, 'zhTW', '丟失的主人', '$N，披風做好了。你現在可以去尋找沃科爾，我希望時間還來得及。$B$B披風上的魔法被啟動之後持續不了多久間，也許就只有五分鐘左右的時間。你可以自行決定什麼時候使用它，不過我建議你在找到銳爪以後再用。$B$B如果銳爪告訴我的消息是真的，那麼你應該可以在南邊的某個洞穴中找到他的主人。銳爪會在路邊等你，看見它以後向它揮手打個招呼(使用/wave指令)，然後它就會將它主人所在的位置告訴你。', '在黑海岸找到沃科爾並且將附魔月虎披風交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 994 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (994,'zhTW','殺出重圍','很好， $N ，就是這樣，讓我們一起衝出去。我們要殺出一條到銳爪身邊的路，到了那裡之後我們可以分開行動。$B$B不過我想特倫希斯一定會聽你來講述這次驚心動魄的逃亡，所以在我們活著離開這裡以後，別忘了儘快去一趟奧伯丁。','保護沃科爾離開，然後去和奧伯丁的特倫希斯談話。','幫助沃科爾逃到路上','去黑海岸找奧伯丁的特倫希斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 995 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (995,'zhTW','偷偷溜走','好吧。我們走。$B$B記住，在你逃脫以後，到奧伯丁去找特倫希斯。我會自己趕去那裡的。','離開熊怪洞穴，然後去見奧伯丁的特倫希斯。','幫助沃科爾逃離洞穴','去黑海岸找奧伯丁的特倫希斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 996 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (996,'zhTW','被腐化的迎風花','','','','去找費伍德森林的被腐化的迎風花。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 997 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (997, 'zhTW', '德納蘭的泥土', '你在往南方旅行嗎?你要去奧拉密斯湖嗎?如果是這樣的話，我有個任務想請你幫忙……$B$B我的同伴德納蘭在湖的東岸有個營地，他在那兒對泰達希爾的植被進行研究和試驗。他想要一包達納蘇斯的稀土，但送貨的在路上耽擱了，我這兩天才剛剛收到稀土。$B$B你能把這包稀土帶給他嗎?', '把稀土交給奧拉密斯湖畔的德納蘭。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 998 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (998,'zhTW','被腐化的迎風花','','','','去找費伍德森林的被腐化的迎風花。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 999 AND `locale` = 'zhTW';
