INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1159,'zhTW','知識試煉','幹得好，$N。你已經透過了知識的試煉的第一部分，但是此外還有一個問題要你回答，這個問題將由別人來提出。$B$B去找洛丹倫城的帕科瓦·芬塔拉斯。在被瘟疫控制之前，他曾是一個偉大的人類歷史學家。現在他依然繼續尋求著啟迪，雖然那是一種不同性質的啟迪。$B$B他在向你提問之前會另有一個要求。到目前為止你都能對各種情況應付自如——因此我也相信你能越過這個障礙。','找到幽暗城的帕科瓦·芬塔拉斯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1160 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1160,'zhTW','知識試煉','我會告訴你必須去尋找的東西，我還會向你提出我的問題，但我做這些並不是因為你想證明你自己。知識遠比力量重要，即使別人在能力上超越了你，你對世界的認知也會讓你更勝一籌。$B$B到提瑞斯法林地北部的修道院去一趟，在那兒的圖書館裡有一本名叫《亡靈的起源》的書，它曾被那些現在已經墮落了的聖騎士用來對抗我們。$B$B把這本書給我拿來。','找到《亡靈的起源》，把它交給幽暗城的帕科瓦·芬塔拉斯。','','去找幽暗城的帕科瓦·芬塔拉斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1161 AND `locale` = 'zhTW';
