INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1164, 'zhTW', '科娜塔一家', '賤人!豬頭!科娜塔竟然還活著!我在這裡受苦受難，她居然全家和睦健康，人丁興旺的。我被她拋棄了!$B$B我已經沒有家了，他們都被瘟疫帶走了。我的財產也都在戰爭中被搶光燒光了。這些也就算了，然而就是她和她的那些野種們，竟然厚著臉皮趁我不在的時候偷走了我家最後一件值錢的東西。$B$B我倒是不再關心那些被偷的東西了。現在我要的是他們的人頭!$B$B到阿拉希高地去，避難谷地的東北方有一個達比雷農場，去那裡把他們都給我殺光啊!', '將科娜塔、法迪爾和馬塞爾的頭顱交給幽暗城的吉納維·卡隆。', '', '去找奧特蘭克山脈的吉納維·卡隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1165 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1165,'zhTW','急需精鐵礦石','','','','去找千針石林的菲茲爾·銅栓。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1166 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1166,'zhTW','莫格穆洛克的任務','向莫格穆洛克大王鞠躬致敬吧！$B$B是雷克薩讓我做了石槌氏族的領袖！$B$B我是個好領袖，是我保衛氏族安全。$B$B大龍來了，燒了我們的家園，是我這麼個有頭腦的食人魔在這兒給氏族找了個新家。$B$B離開原來的家的時候太匆忙，我忘了點東西。小$r，去把我的東西拿來。往南走，去拿回我的烈酒、鼻菸和保險箱。你做好了我就會喜歡你。','蕨牆村的莫格穆洛克大王要你從石槌廢墟拿回他的烈酒、鼻菸和保險箱。','','去塵泥沼澤找蕨牆村的莫格穆洛克大王。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1167 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1167, 'zhTW', '奧薩拉克斯之塔', '在你正面對抗埃瑟里克斯之前，最好先向巴蘇爾請教請教。毫無疑問，他一直都在警惕地觀察著那座塔，應該會有一些新消息。', '去和奧薩拉克斯之塔附近的巴蘇爾·影擊談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1168 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1168,'zhTW','黑龍軍團','雷克薩讓莫格穆洛克做大王。莫格穆洛克只知道權力，很少關心食人魔。$B$B黑龍殺了很多食人魔，還殺了薩爾格的妻子。莫格穆洛克叫我們逃跑，讓我們到這兒來。$B$B食人魔應該戰鬥。食人魔不逃跑。莫格穆洛克只關心他自己。$B$B我只把石槌村叫做家。我喜歡南邊。$B$B幫食人魔打黑龍軍團。我們要復仇。我們要回家。','蕨牆村的薩爾格要你去殺掉10個火鬃斥候，10個火鬃灰尾龍人和5個火鬃守衛。','','去泥塵沼澤找蕨牆村的薩爾格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1169 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1169,'zhTW','群龍之首','莫格穆洛克那個懦弱的傻瓜只知道權力，他整日和薩爾格爭奪著氏族的領導權，大概只有我才在想著要找出襲擊我們以前家園的邪惡勢力的源頭。$B$B幹嘛用這種疑惑眼神看我，$n？你以為我會像個粗俗的混蛋那樣說話嗎？就因為我是個食人魔？$B$B說正事吧，從那些大大小小的黑龍身上弄些心臟和舌頭回來給我，也許我可以找出這邪惡的源頭。','蕨牆村的德拉茲辛比要你給他收集7條灼熱之舌和7顆灼熱之心。','','去塵泥沼澤找蕨牆村的德拉茲辛比。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1170 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1170,'zhTW','奧妮克希亞的血脈','石槌村被奧妮克希亞的種族所侵犯，不過死亡之翼的女兒怎麼會來侵犯我們的領地？$B$B這真是個大麻煩。奧妮克希亞來這裡肯定不僅僅是為了圍攻食人魔，而是還有別的什麼目的。$B$B快去通知莫格穆洛克！我們必須採取行動了。','和蕨牆村的莫格穆洛克大王談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1171 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1171,'zhTW','奧妮克希亞的血脈','別煩我。去告訴德拉茲辛比，我們就留在這兒。這兒沒有黑龍。','去和蕨牆村的德拉茲辛比談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1172 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1172,'zhTW','奧妮克希亞的血脈','黑龍谷到處都是奧妮克希亞的子嗣，決不能讓它們繼續繁殖下去了！$B$B趕緊到塵泥沼澤西部的巨龍沼澤去，那兒肯定是奧妮克希亞的巢穴。找到那裡的龍蛋，把它們給毀了。$B$B如果他們還在不斷滋生，我們就別想奪回石槌村。$B$B至於莫格穆洛克這個傢伙……我自有辦法。','蕨牆村的德拉茲辛比要你去毀掉5枚奧妮克希亞的蛋。','','去塵泥沼澤找蕨牆村的德拉茲辛比。','摧毀奧妮克希亞的蛋','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1173 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1173,'zhTW','挑戰莫格穆洛克','你竟敢挑戰莫格穆洛克？$B$B啊啊啊啊啊啊啊！$B$B我來踩扁你這個小$r！$B$B什麼時候準備好捱揍就告訴我。','打敗莫格穆洛克，再把訊息帶給蕨牆村的德拉茲辛比。','把莫格穆洛克趕出蕨牆村。','去塵泥沼澤找蕨牆村的德拉茲辛比。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1174 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1174,'zhTW','侏儒獲勝！','','','','去找千針石林的克拉茲·滑鏈。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1175 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1175,'zhTW','安全隱患','自從地精的紅雷賽車和一隻大蜥蜴撞了個滿懷之後，科魯克萊德就僱了我去看守賽道。我不知道平原上的這些動物都是吃什麼的，居然長得這麼大，但我們必須多加小心，免得它們在比賽時突然跑進賽道里。$B$B我跟你說啊，如果你想打點零工的話，那就去把這些蜥蜴趕走吧。','為閃光平原的賽道管理員澤爾林殺死10條鹽石蜥蜴、10條鹽石水晶蜥蜴和6條鹽石凝視者。','','去千針石林找沙漠賽道的賽道管理員澤爾林。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1176 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1176,'zhTW','減輕負重','說到賽車，每一點都很重要！不論是動力輸出的調整，壓力線圈的鬆緊，或者是對於整部機車重量的控制，每一項都很關鍵，所以你必須考慮所有的東西。$B$B我們用禿鷲的骨頭對賽車進行了改造，這樣就提供了力量與重量的完美平衡，真棒。更棒的是，我們可以很容易地得到更多的禿鷲骨頭，因為這一帶到處都是禿鷲。$B$B去幫我找一些禿鷲骨頭來，我會給你個好價錢的。','給閃光平原的普茲克找10根空心禿鷲骨。','','去千針石林找沙漠賽道的普茲克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1177 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1177,'zhTW','餓！','馬德是大食人魔。$B$B我餓了。$B$B去抓點魚來。給馬德找吃的。$B$B你餵飽馬德，不然馬德就吃你。','塵泥沼澤北部的馬德克拉什要你去抓8條泥鰭小魚。','','去找塵泥沼澤的馬德克拉什。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1178 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1178,'zhTW','地精贊助商','不管在哪裡，我們的賽車隊都是地精的驕傲。你會對那些以各種方式為車隊貢獻自己力量的人感到吃驚的。$B$B你認識加茲魯維嗎？他為我們從全世界尋找賽車零件，有一次他甚至為我們找來了一臺完整的賽車！$B$B幾星期前，他說他要送給我們一套新的燃油調節器，但至今還沒有到貨。他一向說話算數……你能去棘齒城幫我問問嗎？我原本並不是特別心急，但是侏儒正在趕上我們的步伐！','和棘齒城的加茲魯維談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1179 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1179,'zhTW','防撞頭盔','你聽說過閃光平原嗎？這是一片位於卡利姆多大陸上的鹽鹼地，就在千針林大峽谷的南面。這是塊絕佳的競速場地，因為……它實在是太平坦了！$B$B有一對侏儒兄弟，嗯，他們是我的朋友，就在那兒試驗他們新近研製的火箭車，我聽說這玩意跑得還挺快，快到頻頻撞車的地步，把駕駛員都給撞出腦震盪來了。$B$B所以這兩個傢伙讓我幫他們弄幾頂蒸汽坦克駕駛員的頭盔。可是我這邊還有別的任務，根本抽不出身來！$B$B你能替我跑個腿嗎？','給閃光平原上的維茲爾·銅栓捎去一箱防撞頭盔。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1180 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1180,'zhTW','地精贊助商','回到關於你為何來這裡的話題上。我的確向普茲克保證過會幫他運一臺新的調節器，但我現在還沒有收到這臺機器。藏寶海灣的裡維加茲說他已經把東西裝船運了過來，也許是在運輸過程當中出了什麼差錯。$B$B如果是那樣的話，我們就無能為力了。現在我只知道它已經從藏寶海灣運了出來。$B$B去找碼頭管理員羅茲基爾吧，他應該能幫你查一查出貨記錄。','和藏寶海灣的碼頭管理員羅茲基爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1181 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1181,'zhTW','地精贊助商','恐怕我也只能幫你這些了，$n。如果你還想了解更多事情的話，就直接去找大財主裡維加茲本人吧。還有誰能比裡維加茲對他自己的生意更瞭解呢？$B$B你到港口那邊的小酒館頂樓的房間裡就能找到他了。','與藏寶海灣的大財主裡維加茲談一談。','','去荊棘谷找藏寶海灣的大財主裡維加茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1182 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1182,'zhTW','地精贊助商','瞧，納菲瑞提湖那邊的地精風險投資公司的伐木機上都裝備了最新型號的燃料調節器。我覺得，普茲克要是能拿到調節器的詳細設計圖，一定可以善加利用它。糟糕的是，那邊的工頭比我預計的要精明得多，要取得設計圖似乎並不容易。$B$B你看起來應該有能力去拿到那張設計圖。據我所知，他把那些東西都鎖在了屋子裡。','將燃料調節器的藍圖交給藏寶海灣的大財主裡維加茲。','','去荊棘谷找藏寶海灣的大財主裡維加茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1183 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1183,'zhTW','地精贊助商','你現在就趕快出發吧。替我向普茲克問好，順便告訴他，如果他需要什麼東西，就儘管跟我說。我期待著他能馬上打破記錄！','把燃料調節器的藍圖帶給閃光平原的普茲克。','','去千針石林找閃光平原的普茲克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1184 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1184,'zhTW','蟲群的訊息','返回奧格瑪的貝爾戈洛姆那裡，告訴他摩克塔正在一絲不苟地執行他的命令。把我的研究進展也告訴他，我希望他能知道這些資訊，貝爾戈洛姆一定會為此感到高興的。','回到奧格瑪的貝爾戈洛姆·石槌那兒。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1185 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1185,'zhTW','殼中的東西…','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1186 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1186,'zhTW','第十八個駕駛員','我要開始著手將這個新的燃油調節器裝到賽車上去了，如果你想要幫助車隊的話，就去和拉澤瑞克談談吧。他是我們的駕駛員——更確切地說，是第18個駕駛員——他想為這些賽車做一個小小的修改。$B$B他經常有些奇思妙想，所以請不要太吃驚了。','和閃光平原的拉澤瑞克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1187 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1187,'zhTW','拉澤瑞克的調整','我知道，普茲克是個偉大的機械師，但是他不敢加大油門趕超別人。但我不像他那麼膽小。$B$B在普茲克賽車的設計完成後，我花了點時間做了一些小小的修改。把控制器鬆一鬆，改造某些結構，增加更多的潤滑劑，諸如此類。$B$B我從加基森的史瑞夫那裡訂了一個爆鹽增壓器，但是那運貨的飛艇卻一頭栽進了塵泥沼澤！$n，幫我去把東西取回來吧！','為閃光平原的拉澤瑞克取回爆鹽增壓器。','','去千針石林找沙漠賽道的拉澤瑞克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1188 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1188,'zhTW','安全第一','等等，這是怎麼回事？史瑞夫開啟了保險裝置？這樣會限制推進器的輸出功率的。我說過那個裝置要關掉！對我來說開著那東西一點好處也沒有！$B$B你必須把這個拿到塔納利斯沙漠中的加基森去，讓史瑞夫把那該死的保險裝置給我拆了。','把爆鹽增壓器交給加基森的史瑞夫。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1189 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1189,'zhTW','安全第一','看，我已經按照拉澤瑞克的要求去做了。我跟他說過，在關閉安全裝置時要當心點，否則即使是最小的錯誤也會釀成大錯，輕則讓整輛賽車無法移動，重則把他直接在車裡燒成灰。$B$B如果真的那樣的話可就太丟人了，我們到哪裡去找第十九個願意入夥的賽車手呢？','將改進型爆鹽增壓器還給閃光平原的拉澤瑞克。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1190 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1190,'zhTW','跟上節奏','銅栓兄弟倆發現了一種新的材料，這是唯一說得通的解釋。它們的車速比以前快了，但它們的設計，以及我們蒐集的其它一些資料都和以前的一致。$B$B我們知道的是，瑞茲爾·銅栓一直以來都致力於這項新發明的計劃之中。$B$B扎米克可以為你提供掩護，這樣你就能從他們那兒偷到這些計劃了。','讓扎米克掩護你，然後為閃光平原的普茲克偷到瑞茲爾的計劃。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1191 AND `locale` = 'zhTW';
