INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1282,'zhTW','微笑的吉姆','我對吉姆的事很遺憾……他以前不是那樣的。他曾在沼澤地開了個旅店，那是個很不錯的地方。$B$B我真不想談這個。你想談的話就去找維米斯隊長吧。','與塞拉摩的蓋蘭·維米斯隊長談一談。','','','','','','',0);
