INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1661,'zhTW','高貴之書','很高興再見到你，$N。我很榮幸能夠稱呼你為$g兄弟:姐妹——你的奉獻和無私對我們而言是一種恩賜。$B$B現在我要對你進行嘉獎了，但是你要知道，雖然這次我把它免費送給你，但是將來，如果時間允許的話，這將成為所有聖騎士都要接受的挑戰。$B$B等一會再來與我交談，我就將給你一份很棒的禮物。','與暴風城的達索瑞恩·拉爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1662 AND `locale` = 'zhTW';
