INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1791,'zhTW','捕風者','現在既然你已經學會了狂暴姿態，就應該去弄一把稱手的武器。$B$B去和捕風者巴斯拉談談吧，他是住在奧特蘭克山脈和西瘟疫之地之間一個巨魔隱士。他是製造武器的行家，也是一個強大的薩滿祭司。$B$B去找到巴斯拉，沿著塔倫米爾東側的河流一直向北——巴斯拉的營地就在這條河東岸的廢墟旁。','和捕風者巴斯拉談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1792 AND `locale` = 'zhTW';
