INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1795,'zhTW','誓縛','如果你已經做好了充足的準備，那麼我們就開始吧。首先讓我來解釋一下整個過程。$B$B第一步是創造出基本的召喚法陣，然後，我的助手將使用導能魔棒來將其強化成為更加強大的法陣。$B$B當以上這些工作都完成之後，由你來誦讀陰謀之書上的咒語，召喚地獄獵犬。$n，你要當心。地獄獵犬可是非常強大的生物，我希望你能保護好自己。','召喚地獄獵犬並打敗它，然後把陰謀之書交給棘齒城的斯坦哈德·法爾杉。','','去找貧瘠之地的斯坦哈德·法爾杉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1796 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1796,'zhTW','魔化金線血袍','我要幫你製作的第一件裝備就是長袍，你要負責為我收集若干材料，然後我會把它們組合到一起。這樣你就將擁有有首件能使你變得更加強大的裝備。$B$B首先，你必須給我拿來一件奧法之袍。你可以去找個裁縫幫忙製作，也可以從其他冒險者手中購買——當然如果你能自己製作的話就更好了。但是無論如何，你要先把奧法之袍交給我，然後我們才能開始。','將奧法之袍交給貧瘠之地的梅納拉·沃倫德。','','去找貧瘠之地的梅納拉·沃倫德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1798 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1798,'zhTW','尋找斯坦哈德','是該教你召喚地獄獵犬的時候了，$n。但我現在手裡沒有教你這個法術所必需的材料，所以你得去找另外一個人來教你，也就是斯坦哈德·法爾杉，他是我們我們的另一個成員。$B$B他就住在在地精港口城市棘齒城附近。在你到達之前，我會通知他你要過去的。','與貧瘠之地的斯坦哈德·法爾杉談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1799 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1799,'zhTW','寶珠碎片','很好，那麼我們開始吧。$B$B首先，你必須到裡面去跟我的助手們談談，然後決定自己要走哪條路——他們會給你更詳細的解釋。$B$B然後，你必須到淒涼之地的瑪諾洛克集會所去，從那裡的某個術士身上找到一顆地獄火珠。你要淨化這顆寶珠，隱居在塵泥沼澤南部的一個名叫塔貝薩的法師會幫你完成淨化。她肯定會幫助你，因為我們曾有共同的過去。$B$B我再強調一次，這些任務沒完成之前，你就別回來見我。','在棘齒城外的塔裡與梅納拉的侍僧們談話，選擇自己修行的方式。$B$B然後給塵泥沼澤的塔貝薩帶去一顆地獄火珠。','','去塵泥沼澤找塔貝薩的農場的塔貝薩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1800 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1800,'zhTW','洛丹倫的王座','在我們很聽話的時候，孤兒院院長就會給我們講述許多偉大的故事，其中的一個就是關於洛丹倫的陷落，以及邪惡的阿爾薩斯是如何殺死自己的父親來奪取政權的。$B$B他這樣做真是太無恥了，$N！等我成長為強大的部落戰士之後，我將為榮譽而戰——而不是為了邪惡的權力！$B$B你願不願意帶我去洛丹倫的王座看看呢？王座就在你進入幽暗城之前的那個大廳裡。','帶著你看護的孤兒去幽暗城電梯外的王座大廳。','參觀幽暗城電梯外的王座大廳。','去找獸人孤兒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1801 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1801,'zhTW','陰謀之書','要召喚地獄獵犬並迎接它的挑戰，一個簡單的召喚法陣是不夠的。$B$B我和三個侍僧可以幫你製造法陣，但是你需要一本《陰謀之書》。很久以前我們就把這本書給弄丟了，它是由最早的那批不借助任何外力幫助就召喚出地獄獵犬的術士寫下的。$B$B也許約拉·安尼森能幫你的忙。這段時間裡，他作為一名製圖師受僱於幽暗城，在古籍方面他知道的比我多。','和幽暗城的約拉·安尼森談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1802 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1802,'zhTW','陰謀之書','它是丟了，不過我知道一些可以幫你找到它的線索。$B$B這本書的複製品只有一本，而且它也已經被損壞了，很大一部分的書頁全都被撕了下來，現在聽說它們落入了千針石林的半人馬手裡。$B$B其餘的部分在南海鎮的西岸丟失了，原本這些書頁是要用船送往米奈希爾港的，不過卻從來也沒能送到。$B$B你看，我告訴了你這麼多訊息，好歹你也得在找回東西以後拿來給我看看吧？','為鐵爐堡的克羅姆·粗臂找回發黴的書籍和破損的手稿。','','去找丹莫洛的克羅姆·粗臂。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1803 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1803,'zhTW','陰謀之書','啊！你果然是個品位與我相當的術士呀。事實上，能得到陰謀之書一直是我的一大心願。你知道那本書一度曾被儲存在洛丹倫城裡嗎？然而，那本書如今已經被摧毀了，大部分的書頁都不見了。到底是哪個白痴幹出這樣可憎的事？$B$B據說，失落的那一半目前在千針石林中的一群半人馬手裡。$B$B剩下的另一半本來是要被轉移到鐵爐堡去的，不過在押運過程中丟失在了南海鎮西部的海灘上。','給幽暗城的約拉·安尼森帶回發黴的書籍和破損的手稿。','','去找提瑞斯法林地的約拉·安尼森。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1804 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1804,'zhTW','陰謀之書','唉……我真是恨不得一輩子都抱著這本書。不過既然這是你找到的，而且你還要用它做更重要的事，我還是把它還給你吧……不過，請你一定要告訴斯坦哈德幫我抄寫一本。$B$B對了，你去找書的時候，他託人帶了個訊息過來，讓我告訴你說他的助手要協助進行召喚，不過你必須幫他找到3根導能魔棒。$B$B斯坦哈德可能不知道要到哪裡去找導能魔棒，不過我碰巧知道！龍喉氏族的獸人法師們手上應該還有一些這種魔棒。','將翻修過的書籍和3根導能魔棒交給棘齒城的斯坦哈德·法爾杉。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1805 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1805,'zhTW','陰謀之書','這書上寫的東西是我這幾年中看過的文章裡最有趣的。這邊的書很少，選擇也很少——大多數的書都是地理方面的——而且，我都把它們翻來覆去地讀了好些遍了。我真希望斯坦哈德能抽空給我也送一本這樣的書來。$B$B去和他談談吧，他在你離開的時候託人給我帶來了口信，說是要交給你一個任務，要求你找回三根召喚魔棒。$B$B當然，為了答謝你允許我繼續看這本書，我告訴你一個小秘密：你可以在溼地的獸人龍喉氏族那裡找到你要的東西。','將翻修過的書籍和3根導能魔棒交給棘齒城的斯坦哈德·法爾杉。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1806 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1806,'zhTW','正義試煉','我們現在就到熔爐邊上去開始工作吧！我已經為你的到來準備很久了，現在不用再等了。$B$B在我們完成這把武器之後，你就可以更好地為聖光而戰，這一點我絕對可以保證。$B$B說實話，$N，看到你所取得的這些成績，我真有點羨慕。不過我知道我也可以用我自己的方式給你提供一些幫助，這樣就已經讓我很高興了。','等待喬丹·斯迪威爾為你鑄造武器。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1818 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1818,'zhTW','迪林格爾','亡靈衛兵迪林格爾告訴我有一份工作可以交給像你這樣的$c。如果你想要為黑暗女王效力的話，那就馬上去迪林格爾那邊報到吧。$B$B亡靈衛兵迪林格爾在布瑞爾最西邊執勤，就在墓地的旁邊。','和布瑞爾的亡靈衛兵迪林格爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1819 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1819,'zhTW','切割者奧拉格','當亡靈天災席捲提瑞斯法林地的時候，我們曾經抓住他們中的一員進行研究。他具有自己的意志，並自稱為切割者奧拉格。但是，雖然他的意志是自由的，但他仍然只是一個被巫妖王掌控和奴役著的傀儡。$B$B我們希望能夠讓他脫離巫妖王的控制，但是失敗了。現在，我看是時候讓他徹底地“解脫”了。$B$B讓他解脫，殺了他。$B$B啟用北部陵墓那裡的顱骨石機關，解除奧拉格身上的魔法封印。$B$B然後……做好準備，$N。','殺死切割者奧拉格，然後和亡靈衛兵迪林格爾談一談。','','去提瑞斯法林地找布瑞爾的亡靈衛兵迪林格爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1820 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1820,'zhTW','庫勒曼','你已經向黑暗女王證明了自己的價值，現在你應該有資格繼續完成她下達的其它任務了。$B$B庫勒曼·法席恩正在徵召可以幫助他對付敵人的勇士。$B$B你可以在布瑞爾東部的恐懼之末旅店找到他。','和庫勒曼·法席恩談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1821 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1821,'zhTW','阿加曼德家傳武器','在我活著的時候，阿加曼德家族是我的主人，但他們也是讓我死去的罪魁禍首！現在他們得到了應有的報復，阿加曼德家族已經成為了巫妖王手下的行屍走肉。$B$B現在我要剝奪他們最後的榮耀。到他們家族的墓地裡去，幫我搶來他們的傳家之寶：一把劍，一柄斧，一柄匕首，還有一把釘錘。將這些東西全都給我拿來！$B$B阿加曼德家族墓穴就在阿加曼德磨坊的最北端，那裡有許多亡靈天災的部隊和死去的阿加曼德族人守衛著。','把阿加曼德家傳長劍、阿加曼德家傳戰斧、阿加曼德家傳釘錘和阿加曼德家傳匕首交給庫勒曼·法席恩。','','去提瑞斯法林地找布瑞爾的庫勒曼·法席恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1822 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1822,'zhTW','祖傳武器','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1823 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1823,'zhTW','和魯迦交談','作為一名戰士，你已經具備了相當的素質，而且名望也日漸顯赫。也許你已經準備好要接受魯迦·狂暴圖騰的試煉了？如果是這樣的話，就去貧瘠之地的陶拉祖營地找魯迦吧。$B$B他一直以來都在那裡等待英勇的戰士響應他的召喚。','和魯迦·狂暴圖騰談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1824 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1824,'zhTW','巨人曠野的試煉','要透過試煉，你必須一直向南到巨人曠野去，在那裡有一大群叫做異種蠍的昆蟲生物。我以前從未在貧瘠之地看到過這種生物，也不知道它們的到來究竟預兆著什麼。$B$B把它們的觸角交給我，$N，要剛剛割下來、還再抽搐的那種。不要浪費時間，因為一旦你把觸角割下來，它們很快就會徹底失去活力。在規定的時間內把觸角帶給我，這樣你就透過了考驗。','收集5根顫抖的觸角，把它們帶給貧瘠之地陶拉祖營地的魯迦。','','去貧瘠之地找陶拉祖營地的魯迦·狂暴圖騰。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1825 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1825,'zhTW','和索恩格瑞姆交談','著名的獸人鐵匠索恩格瑞姆·火眼已經聽說了你為部落作出的傑出貢獻。他願意為你製作一套護甲，馬上去找他談談吧。$B$B索恩格瑞姆的營地就在貧瘠之地十字路口的東邊。','與貧瘠之地的索恩格瑞姆·火眼談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1838 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1838,'zhTW','野蠻護甲','我聽說了關於你的英勇事蹟，所以希望能為你製作一套護甲，這能夠幫助你去為部落作出更多更偉大的貢獻。$B$B但是製作這樣一件護甲需要你的幫助，$N，如果你能幫助我，那你也就幫助了部落裡所有的鐵匠。$B$B拿著這個卷軸，這是我經過無數不眠之夜，強睜著我半瞎的眼睛寫下的，上面記載著製作護甲所需要的材料。把卷軸上所列出的材料幫我找來，我會為你製作一套護甲。','為索恩格瑞姆收集15根菸霧鐵錠、10份藍銅粉、10塊鐵錠和1瓶燃素。','','去貧瘠之地找荊棘嶺的索恩格瑞姆·火眼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1839 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1839,'zhTW','尤拉萊克和野蠻護手','巨魔鐵匠尤拉萊克會為你鑄造一副野蠻護手，他住在杜隆塔爾的森金村裡，那兒是暗矛氏族的家園，他正在等著你。','與杜隆塔爾的尤拉萊克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1840 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1840,'zhTW','奧姆·石蹄和野蠻頭盔','奧姆·石蹄因為他傑出的鑄造技術而被大家尊敬，他會為你鑄造野蠻頭盔。$B$B你可以在雷霆崖找到他，他就在城市中心最大的那根圖騰旁的池塘附近。','和雷霆崖的奧姆·石蹄談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1841 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1841,'zhTW','維羅拉·奈特雷和野蠻腿甲','在死亡之前，維羅拉·奈特雷曾是洛丹倫最好的鑄甲師。看來死亡讓她的技藝退步了許多。去和維羅拉談談——她會幫你鑄造野蠻腿甲。$B$B維羅拉住在洛丹倫的幽暗城裡，你可以在貿易區找到她。','與幽暗城的維羅拉·奈特雷談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1842 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1842,'zhTW','薩特之蹄','我可以為你鑄造一副具有很強魔法力量的野蠻手套。但是首先，你必須先替我去收集這樣的魔法力量。$B$B為了獲取這片森林的力量，許多薩特聚集在梣谷的東北面，它們在那裡貪婪地吸取和破壞著森林的力量。你可以從它們腫脹的蹄子上判斷出到底是哪些薩特在吸取梣谷的魔力。$B$B這些蹄子都有不小的魔法力量，把它們給我帶來，這樣我就可以給你鑄造野蠻手套了。','收集7只完整的薩特之蹄，把它們交給杜隆塔爾森金村的尤拉萊克。','','去杜隆塔爾找森金村的尤拉萊克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1843 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1843,'zhTW','野蠻護手','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1844 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1844,'zhTW','奇美拉之角','我會幫你鑄造頭盔，但是你必須向我證明你值得我這麼做。$B$B石爪山的西北面是一個名叫焦炭谷的山谷，那裡曾經是一片鬱鬱蔥蔥的森林，但是現在已經被完全被汙染，那裡剩下的生物也都被痛苦和絕望逼瘋了。$B$B現在我就要派你去那裡，$N。$B$B你必須去焦炭谷找到雌奇美拉，殺死她，讓她從苦痛中得到解脫，把她那光滑的奇美拉角帶給我作為你完成任務的證據，然後我就會為你鑄造頭盔。','把光滑的奇美拉角交給雷霆崖的奧姆·石蹄。','','去找雷霆崖的奧姆·石蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1845 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1845,'zhTW','野蠻頭盔','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1846 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1846,'zhTW','龍喉脛骨','要鑄造野蠻腿甲，我就需要一些結實的脛骨。溼地裡的龍喉獸人就有非常合適的脛骨，我就需要那樣的。$B$B但是你一定要確保脛骨是絕對牢固的，在你收集它們的時候記得要試一下它們是不是足夠牢固：如果你能徒手把它們弄碎，那麼它們肯定不符合我的要求。','給幽暗城的維羅拉·奈特雷帶去8根結實的龍喉脛骨。','','去提瑞斯法林地找 幽暗城的維羅拉·奈特雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1847 AND `locale` = 'zhTW';
