INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1858,'zhTW','破碎之手氏族','你得去想辦法把塔贊的背袋給弄開，這樣咱們才能把裡面的東西拿出來。這鎖的結構還真挺複雜的，所以你想要弄開它的話就只能靠鑰匙了。$B$B如果你沒有在塔贊的屍體上找到鑰匙，那他就一定把鑰匙放到某個安全的地方去了……啊，對了!他有一個助手叫加摩爾，是個徹頭徹尾的大酒鬼，你八成能在酒館裡找到這傢伙。我建議你「安靜地」把鑰匙從他手裡搞來。','偷來塔贊的鑰匙，用它打開他的背袋，然後將裡面的物品交給奧格瑪暗影裂口的瑟祖克。','','去找奧格瑪的瑟祖克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1859 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1859,'zhTW','瑟祖克','小聲點，$N。沒錯，我知道你叫什麼。有人讓我注意一個獸人，你完全符合他的描述。$B$B我們聽說你在戰鬥中頗有一套，有時也會使用一些非常的手段。$B$B我沒說錯吧？$B$B不管怎樣，你得去見見奧格瑪的瑟祖克，他有事要吩咐你。','到奧格瑪的暗影裂口和瑟祖克談談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1860 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1860,'zhTW','和詹妮亞交談','我們法師有一項任務要交給你去完成，一項對於暴風城和艾爾文森林的安全至關重要的任務。$B$B詹妮亞·坎農會告訴你任務的細節。她正在暴風城的法師區裡的巫師聖地裡學習，你最好儘快找到她。','和暴風城的詹妮亞·坎農談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1861 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1861,'zhTW','明鏡湖','大規模的魔法戰爭已經使得原本穩定的魔法流開始出現異常的波動。我們正在努力調查這種波動究竟會造成怎樣的影響，而有些人已經做好了最糟糕的打算！$B$B但是現在還不能輕易下結論，我們們要派你去收集更多的資訊。$B$B拿著這個水袋，到艾爾文森林明鏡湖瀑布的底部收集那裡的水樣，然後把水樣給我帶回來，這樣我就可以用它來進行魔法汙染情況的研究了。','把一份明鏡湖水的樣本交給暴風城的詹妮亞·坎農。','','去找暴風城的詹妮亞·坎農。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1878 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1878,'zhTW','收集水袋','','','','去找塔納利斯的操作員魯格倫克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1879 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1879,'zhTW','和彬克交談','$N！我在鐵爐堡的侏儒同事彬克送話過來說，她有一項必須交由某個法師來完成的任務！你不正好是個法師嗎，$N？$B$B如果你願意的話，去和彬克談談吧。她就在鐵爐堡秘法區的秘法大廳裡。','和鐵爐堡的彬克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1880 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1880,'zhTW','法師文件儲存器','我們法師能做的事情可不僅僅是彈動一下手指變出美麗的火花那麼簡單！我們控制著魔法，控制著構建這個世界的源泉！當然，這需要極大的決心和極強的能力，還有知識……足夠多的知識！$B$B我發明的一臺裝置——法師文件儲存器——裡面儲存著無數的知識。不過問題是，我把它弄丟了！當我們逃離諾莫瑞根的時候，我把它留在城外一座小屋的箱子裡，現在那地方麻瘋侏儒橫行！$B$B$N，請幫我取回我的法師文件儲存器！','幫彬克找回她的法師文件儲存器。','','去找丹莫洛的彬克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1881 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1881,'zhTW','安娜斯塔西婭','$N，安娜斯塔西婭·哈特威爾有個任務需要你這樣有才幹的$c來完成。她就在幽暗城的魔法區，去和她談談，準備為被遺忘者的法師們完成你的第一個任務吧。','和安娜斯塔西婭·哈特威爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1882 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1882,'zhTW','巴尼爾農場','東邊的瘟疫之地處於混亂的狀態。巫妖王控制下的天災軍團將邪惡的魔法灌入土地之中，腐化並殺死那裡的一切生靈。雖然瘟疫具有強大的破壞力量，但是我們——被遺忘者的法師——相信它必定可以被清除掉。$B$B首先，我們必須判斷出它在提瑞斯法到底散播到了怎樣的程度。到提瑞斯法東部的巴尼爾農場去，在那裡的花園中收集一些金魚草，然後再回來。','將巴尼爾金魚草交給幽暗城法師區的安娜斯塔西婭·哈特威爾。','','去找提瑞斯法林地的安娜斯塔西婭·哈特威爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1883 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1883,'zhTW','安蘇瓦','森金村的部落法師安蘇瓦發現杜隆塔爾的魔法流出現了波動，為此他向我尋求幫助。去和安蘇瓦談談，盡你所能去幫助他。$B$B快去吧，到時一定會有更多的秘密展示在你的面前。','和安蘇瓦談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1884 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1884,'zhTW','魂能骨堆','回音群島的術士扎拉贊恩擾亂了杜隆塔爾的魔法流。他那些邪惡的魂能骨堆就是造成這一切的罪魁禍首，他把那些骨堆放在回音群島的主島上。$B$B骨堆破壞了我們的生活，還讓在黑暗角落裡隱藏著的術士和惡魔獲得源源不斷的力量。$B$B你必須在魔法流被徹底改變之前摧毀那些魂能骨堆，$N。','摧毀4個魂能骨堆，然後向森金村的安蘇瓦彙報。','','去杜隆塔爾找森金村的安蘇瓦。','摧毀魂能骨堆','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1885 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1885, 'zhTW', '米奈特·卡加德', '$n?雖然現在的情況並不像我所預計的一樣，但卡加德確實對你非常感興趣。聽起來是不是有點難以置信?無論如何，你得儘快去找他談談。我想你並不想知道上一個對他的召喚置之不理的人的下場吧。', '與幽暗城盜賊區的米奈特·卡加德談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1886 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1886,'zhTW','亡靈哨兵','想加入瓦里瑪薩斯大人的精英衛隊——亡靈哨兵的話，你首先必須證明自己的價值。$B$B坦城地說吧，$n，你很可能在這種證明自己價值的任務中喪命，所以我勸你最好三思而行。$B$B現在，我有一個任務要你去完成。有一位來往於銀松森林與幽暗城之間的信使，他叫阿斯托·哈德恩，由於特殊的公務需要，我必須得到他身上的一些私人物品。至於採用怎樣的策略去得到這些物品，那是你的事情，不要問我。$B$B如果你的好奇心能小一點，不那麼關心這些物品的用途的話，你會過得更自在一些。完成這個任務之後，我會再和你談的。','得到阿斯托的介紹信，並將其交給盜賊區的米奈特·卡加德。','','去提瑞斯法林地找幽暗城的米奈特·卡加德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1898 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1898,'zhTW','亡靈哨兵','這封介紹信足以使安德隆認為你就是他正在等的那位信使。我之前已經見過安德隆了，估計以他那點腦子是根本不會懷疑你的。$B$B瓦里瑪薩斯大人懷疑安德隆正在為某些其他的組織提供援助。他想知道那是個什麼組織，而且你要收集到充分的證據。$B$B我要求你在與安德隆的談話中把這些資訊都給套出來，他的店就在鍊金房旁邊。','與幽暗城的安德隆·甘特交談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1899 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1899,'zhTW','亡靈哨兵','你在我背後的書架上就可以找到記有你的主子最需要的資訊的賬本。把它交給他們，記得代我問他們好。哦，還有，告訴他們，如果他們覺得與我合作確實不錯，並且還打算按日程繼續合作下去的話，他們最好還是派你來。','將阿斯托的的賬本交給幽暗城盜賊區的米奈特·卡加德。','','去提瑞斯法林地找幽暗城的米奈特·卡加德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1918 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1918,'zhTW','被汙染的水元素','被毀滅的水元素留下了一顆水球，它令你感到極端的厭惡，彷彿汙染密斯特拉湖的所有物質都包含在這顆水球中一樣。$B$B你不清楚誰會對這個感興趣，不過碎木哨崗的馬斯托克·維爾西斯——那個最初派你來這裡的傢伙——也許對此有所瞭解。','將被汙染的水球交給梣谷碎木哨崗的馬斯托克·維爾西斯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1919 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1919,'zhTW','向詹妮亞報告','你的能力正在不斷地增強，年輕的$N。你準備好要接受真正的挑戰了嗎？你願意加入到我們正在進行的這場秘密戰爭之中嗎？$B$B如果你願意的的話，就去和詹妮亞·坎農談談吧，她在暴風城法師區的巫師聖殿裡。她有一項任務要交給你，這將幫你開啟通向那個秘密世界的第一扇窗。','和暴風城的詹妮亞·坎農談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1920 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1920,'zhTW','調查藍色隱士','有報告稱，法師區的藍色隱士旅店裡出現了異常的魔法波動。一些隱形的奇怪生物徘徊在旅店裡，我擔心那裡已經有了一道魔法裂隙。$B$B我希望你去調查一下旅店，捕獲那些生物。用旅店中的顯形卷軸讓它們現出原形，然後用封靈箱抓住它們。當你抓到足夠數量的隱形生物之後，就帶上裝滿了的封靈箱和顯形卷軸回到我這裡來。','從詹妮亞·坎農身後拿取一根顯形卷軸以及一盒封靈箱。將3個裝滿的封靈箱交給巫師聖殿裡的詹妮亞·坎農。','','去找暴風城的詹妮亞·坎農。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1921 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1921,'zhTW','收集原料','你幫了你的法師同行們很多忙，現在是為你製作巫師長袍的時候了。維恩·拉爾森可以幫你這個忙，不過你必須把必需的原料交給她。$B$B制袍用的亞麻布很容易找到，不過你還必須得到充能裂隙寶石，唯一出產這些寶石的地方是在洛克莫丹的銀泉礦洞，它們大多被密封在矮人礦工協會的箱子裡。$B$B收集好亞麻布和寶石之後，把它們交給法師區拉爾森服裝店裡的維恩·拉爾森。','把10匹亞麻布和6顆充能裂隙寶石交給暴風城的維恩·拉爾森。','','去找暴風城的維恩·拉爾森。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1938 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1938,'zhTW','烏爾的暗影魔法研究論文','很久以前，三個法師在暴風城裡一起學習法術，直到其中的一個開始研究黑暗魔法。他原本並不想深入其中，但是卻發現自己在不經意間越陷越深。最終，他被放逐出了暴風城。$B$B這個被放逐的法師就住在赤脊山的伊爾加拉之塔中，他手中有一本強大的魔法書——《烏爾的暗影魔法研究論文》。$B$B我們這些暴風城的法師希望能把那本書拿回來。你要做的就是溜進伊爾加拉之塔，幫我們取回那本書。','將《烏爾的暗影魔法研究論文》交給暴風城的高階巫師安多瑪斯。','','去找暴風城的高階巫師安多瑪斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1939 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1939,'zhTW','高階巫師安多瑪斯','高階巫師安多瑪斯希望和你談談，$N。他就在暴風城法師區的高塔頂端。$B$B能去和他會面可是非常難得的機會，因為安多瑪斯是少數幾個沒有被困在達拉然的超強的大法師之一，他找你也一定是有非常重大的事情。','和高階巫師安多瑪斯談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1940 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1940,'zhTW','新鮮的蜘蛛絲','你一直在幫助我們，$N。我想，也許你應該換一件好點的長袍了，一件更適合資深法師地位的長袍。如果你能收集到必需的原料，我們就幫你做一件新的長袍。$B$B你必須進入暮色森林，獵捕那裡的食腐獨行蛛。抽出它們的絲，但只有最好的、最純的絲才行。你得到足夠的蛛絲後，就把它們交給維恩·拉爾森來幫你縫製長袍，她就在法師區的拉爾森服裝店裡。','找到8束新鮮的蜘蛛絲，把它們交給暴風城的維恩·拉爾森。','','去找暴風城的維恩·拉爾森。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1941 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1941,'zhTW','法紋長袍','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1942 AND `locale` = 'zhTW';
