DELETE FROM `quest_template_locale` WHERE `ID` = 1943 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1943,'zhTW','巨魔法師迪諾','$N，巨魔法師迪諾需要你的幫助，她就住在奧格瑪的暗木小屋裡。','和迪諾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1944 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1944,'zhTW','克薩維亞之水','傳說中的克薩維亞城位於梣谷的東部，據說在那裡可以找到所有智者都渴望獲得的古代知識，而克薩維亞之水也具有超強的魔法力量。$B$B我需要一些克薩維亞之水——要從水源直接取得的那種。$B$B拿著這隻瓶子，去尋找傳說中的克薩維亞城吧。從那裡最高的瀑布底部收集水樣，然後把它交給我。在那裡你要步步小心，薩特佔領了整個遺蹟，它們一定不會喜歡讓多事的法師侵入它們的領地。','將克薩維亞水樣交給奧格瑪的迪諾。','','去找奧格瑪的迪諾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1945 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1945,'zhTW','歡笑的姐妹','我已經把為你製作新袍子的事情安排妥當了，就等你來提供一些材料……$B$B我需要一些頭髮來製作你的法袍，你應該可以在梣谷的樹妖身上弄到符合條件的頭髮，那些樹妖們都聚集在林中樹居那裡。$B$B當你找到足夠的材料之後，就把它們交給貧瘠之地十字路口的基爾哈拉，他是一個巨魔裁縫。他正等著為你製作最新款的法袍。','給十字路口的基爾哈拉帶去12縷歡笑姐妹的頭髮。','','去貧瘠之地找十字路口的基爾哈拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1946 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1946,'zhTW','虛靈長袍','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1947 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1947,'zhTW','沼澤之旅','現在，是讓你得到自己的法師魔杖的時候了。首先，你得去和住在塵泥沼澤的人類隱者塔貝薩談一談。你可以在沼澤深處找到她的小室，那地方就在塞拉摩的西邊，石槌廢墟的北邊。$B$B去和她談談，她的知識非常淵博。','和塔貝薩談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1948 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1948,'zhTW','強大的物品','鑄造一根法師的魔杖並不容易。我們需要一些珍貴的材料，而且必須製作一個能儲存大量魔法能量的容器——這些事情就交給你了。$B$B我已經把要你去找的東西寫在這張羊皮紙上了，把上面列著的東西交給我，另外你一定要按照羊皮紙上的指示行事。如果你不聽從我的指示擅自決斷的話，我們鑄造魔杖時就可能會有……大麻煩。','將電能草莓和1顆翡翠交給塵泥沼澤的塔貝薩。','','去塵泥沼澤找塔貝薩的農場的塔貝薩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1949 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1949,'zhTW','隱藏的秘密','為了製作你的魔杖，我得查詢一本書裡的一些關鍵段落。這本書叫做《能量儀祭》，是大法師提爾斯寫的。$B$B我沒有這本書，世界上所有的大圖書館也沒有收藏。你必須去和提爾斯談談，從他那裡要一本來。$B$B祝你好運。提爾斯曾經是個偉大的法師和學者，不過他現在把時間都花在飲酒、賭博，還有去閃光平原觀看侏儒與地精的車賽上了。','和閃光平原的大法師提爾斯談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1950 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1950,'zhTW','解封咒語','我可以給你書，但你得先幫助我！$B$B你要找的書被鎖在我的魔法箱裡了。必須念出一些咒語才能開啟它，但是我忘記這些咒語了！通常都是我的助手幫我記這些事情，但現在他也不知道跑哪裡去了。$B$B如果你想要我的書，那就得先找到我的學徒！到賽車道周圍去問問——如果幸運的話，會有人知道他在哪裡的。要麼把他給我帶回來，要麼從他那兒問到咒語，不然就別想開啟我的箱子！','找到提爾斯保險箱的解封咒語，然後向提爾斯覆命。','獲得秘密咒語','去千針石林找沙漠賽道的大法師提爾斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1951 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1951,'zhTW','能量儀祭','嗯……我想起來了，我的書已經沒有了！你要知道，我欠了一屁股的債，不得不把最後一冊《能量儀祭》賣掉來還債，我把它賣給了一個牧師……$B$B他是血色十字軍的成員。他一定把那本書帶到了他們的根據地——提瑞斯法林地裡的血色修道院圖書館去了！$B$B如果你想要那本書的話，就得去一趟修道院。很抱歉給你帶來這麼多麻煩，這些天我已經有些頭昏腦漲了……','將《能量儀祭》交給塵泥沼澤的塔貝薩。','','去塵泥沼澤找塔貝薩的農場的塔貝薩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1952 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1952,'zhTW','法師的魔杖','我現在要去鑄造魔杖了。','等塔貝薩的儀式完成後，和她談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1953 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1953,'zhTW','返回沼澤','$N，是時候讓你去和塔貝薩談談了……這位塵泥沼澤裡的隱士將指導你如何鑄造強大的法師物品。$B$B塔貝薩就隱居在塵泥沼澤的深處，塞拉摩的西邊。','和塔貝薩談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1954 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1954,'zhTW','地獄火寶珠','首先，我們必須弄到一顆有魔力的寶珠。火刃氏族的術士有高質量的寶珠……糟糕的是，他們將惡魔收入了寶珠裡！當然我們可以解決這個問題，對……我們可以。$B$B到淒涼之地去，從火刃召喚師那裡奪取一顆地獄火寶珠。那幫傢伙通常在瑪諾洛克集會所活動。$B$B拿到寶珠之後就儘快返回我這兒來。','將一顆地獄火寶珠交給塵泥沼澤的塔貝薩。','','去塵泥沼澤找塔貝薩的農場的塔貝薩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1955 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1955,'zhTW','驅除魔鬼','既然我們已經得到了召喚師的寶珠，現在就讓我們來把惡魔從裡面驅趕出來。我能做到，這部分相當容易。$B$B我有個艱鉅的任務給你，你必須在惡魔出現的時候殺死它。$B$B而且動作要夠快。如果你耗時過久的話，或許它就會再跳進去，那我們又得重來一次了！$B$B所以你得準備好最強的技能和所有的物品，如果你有朋友的話，也一起叫上。這件事情不會很輕鬆的。','殺死寶珠之魔，然後與塔貝薩談一談。','殺死寶珠之魔','去塵泥沼澤找塔貝薩的農場的塔貝薩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1956 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1956,'zhTW','奧達曼的能量源','既然惡魔已經被消滅了，接下來我們就得去找一個能量源。不幸的是，最合適的能量源往往非常古老而且極難獲得。有的時候，命運就喜歡這樣捉弄你，難道不是嗎？$B$B所以，為了得到能量源，你必須到奧達曼去打敗那裡的黑曜石守衛。他體型巨大而且很難對付，但是你可以從他身上得到我們所需要的能量源！$B$B祝你好運，$N。如果你運氣不好的話，那麼……很高興認識你。','找到一個黑曜石能量源，將其交給塵泥沼澤的塔貝薩。','','去塵泥沼澤找塔貝薩的農場的塔貝薩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1957 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1957,'zhTW','法力怒靈','我們幾乎已經要大功告成了，但是最後一步也是最危險的，$N。$B$B我有一顆空的召喚寶珠，準備給它注入力量。我們將透過一道魔法裂縫來完成這個步驟，首先，我會念一段咒語來開啟裂縫，此時特殊的生物——法力怒靈將大量湧出來。你必須打敗這些生物以釋放它們的能量，我會及時用寶珠收集這些能量。$B$B在裂縫關閉之前殺死足夠多的法力怒靈，我會把所有收集起來的能量注入你的寶珠。','在限定時間內殺死12只法力怒靈。','','去塵泥沼澤找塔貝薩的農場的塔貝薩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1958 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1958,'zhTW','蒼穹之力','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1959 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1959,'zhTW','向安娜斯塔西婭報告','幽暗城的法師們注意到城裡出現了一股魔法波動，他們隨即發出訊息，請求部落的法師來協助他們進行調查。$B$B安娜斯塔西婭·哈特威爾會告訴你更多的詳細內容，她就在幽暗城的魔法區，去和她談談吧。','和安娜斯塔西婭·哈特威爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1960 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1960,'zhTW','調查鍊金店','在鍊金房的奧格諾恩鍊金店裡有一股奇怪的魔法波動。由魔法能量構成的隱形生物在商店裡四處遊蕩，這其中一定有什麼原因，我們必須找到它！$B$B我希望你去調查一下，捕獲那些生物。用我身後的顯形卷軸讓它們現出原形，然後用封靈箱抓住它們。當你抓到足夠數量的隱形生物之後，就帶上裝滿了的封靈箱和顯形卷軸回到我這裡來。','從安娜斯塔西婭·哈特威爾身後拿取一根顯形卷軸以及一盒封靈箱。將3個裝滿的封靈箱交給幽暗城的安娜斯塔西婭·哈特威爾。','','去找提瑞斯法林地的安娜斯塔西婭·哈特威爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1961 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1961,'zhTW','收集原料','$N，是時候為你製作你的第一件法師袍了。那會是你地位的標誌，同時也是對你的一次考驗。$B$B你必須從銀松森林的達拉然法師身上獲得製作法袍所必需的法力寶石。那些法師和我們擁有相似的信仰，所以殺掉他們會是一件讓人感到不快的事情，但是既然他們不具備抵禦我們的力量，那他們也就沒有繼續存活下去的價值了。$B$B把寶石和亞麻布交給法師區裁縫店裡的喬瑟夫·格里高利，他會為你製作你的第一件法師袍。','把10塊亞麻布和6塊達拉然法力寶石帶給喬瑟夫·格里高利。','','去找提瑞斯法林地的喬瑟夫·格里高利。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1962 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1962,'zhTW','魔焰長袍','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1963 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1963,'zhTW','破碎之手氏族','大酋長行事的方法實在是有些太謹慎了。他總是很小心地不讓部落顯得過於鋒芒畢露。一旦我們足夠強大了，我們的力量將能征服一切。部落必須重現往日的榮耀和尊嚴，而現在看來能做到這一點的就只有我們破碎之手氏族了。$B$B我們必須在暗中積蓄力量，再突然向敵人發起致命的打擊，神不知鬼不覺地將敵人除掉。如果你想加入我們，就必須先為我完成一個任務，以此來證明你自己的價值。$B$B有個名叫塔贊的食人妖在棘齒城附近和海賊們做交易，而他那裡有我感興趣的消息。殺了他，把他的背袋拿來給我。','殺死塔贊，把他的背袋帶給奧格瑪暗影裂口的瑟祖克。','','去找奧格瑪的瑟祖克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1978 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1978,'zhTW','亡靈哨兵','辛迪加？我竟然從來都沒有想到是他們，看來奧特蘭克的那些貴族們自從背叛聯盟以後真是愈加墮落了。$B$B瓦里瑪薩斯大人知道了這些一定會非常高興，另外，既然你在這次偵查行動中表現得這麼出色，那麼，就由你把我們的調查結果給他送過去吧。$B$B啊，我怎麼可能忘了說這個呢！$B$B歡迎加入亡靈哨兵的行列。','將安德隆的賬本交給幽暗城黑暗女王大廳裡的瓦里瑪薩斯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1998 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1998,'zhTW','芬維克·薩托斯','瓦里瑪薩斯大人剛剛給我下達了一道命令，要求我派人去把一個對被遺忘者構成巨大威脅的傢伙立刻剷除掉。他的名字是芬維克·薩托斯，瓦里瑪薩斯大人認為他是一群在銀松森林中肆虐的不死生物的領袖。$B$B一接到這個任務，我馬上就想到了你， $N 。我堅信，以你的能力一定可以將這個任務輕鬆完成。$B$B我們派遣到銀松森林的亡靈哨兵們傳回的最新報告中指出，薩托斯就躲藏在洛丹米爾湖岸邊的一處廢棄碼頭上。','殺掉芬維克·薩托斯，把他的頭顱交給幽暗城盜賊區的米奈特·卡加德。','','去提瑞斯法林地找幽暗城的米奈特·卡加德。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 1999 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1999,'zhTW','交易工具','安伯米爾的祈倫托巫師那裡保存著大量關於達拉然現狀的檔案，這些情報是我們從一個囚犯的口中拷問出來的。瓦里瑪薩斯大人已經下令，要求我們必須把這些檔案弄到手。$B$B於是這個任務就落到了你的肩上， $N 。你需要一些裝備，更重要的是得學會開鎖的技術。去跟我們的工具商艾斯特蕾·根德瑞談談，在你出發前向她要一套開鎖工具吧。','找到達拉然形勢報告，把它交給幽暗城盜賊區的米奈特·卡加德。','','去提瑞斯法林地找幽暗城的米奈特·卡加德。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2000 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2000,'zhTW','洛卡·刃影','你最近是不是太悠閒了點，$n？我看該讓你多學點我們的營生了。就在今天晚上，我們在奧格瑪的一處岩石縫裡發現了五個同伴的屍體，現場沒留下任何線索。好傢伙，這一定是我們敵人乾的，竟然以我們的手法來對付我們。$B$B所以我決定派你去學撬鎖。$B$B真可惜呀，這門精巧的手藝對我這雙手來說太難了。你得去找到洛卡，他就住在杜隆塔爾附近的山裡。儘管他已經年紀很大了，但我想他應該還活得很好。','去找杜隆塔爾的洛卡·刃影談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2018 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2018,'zhTW','洛卡的試煉','啊，現在瑟祖克竟然把他的小學徒送到我這兒來了，是吧？嗯，我想我還是能教你些什麼的。我根本不關心你的事情，但我也不想平白無故地讓你去送死。$B$B你必須先證明你自己的價值。$B$B我得告訴你，$n，我根本不喜歡風險投資公司。這片土地讓我想起了德拉諾，所以我很討厭那些毀了這裡的地精們的想法。如果我們能幹掉他們在淤泥沼澤裡的監工，他們的工程進度也許會癱瘓下來了。','殺死監工格里比，把他的哨子交給杜隆塔爾的洛卡·刃影。','','去找杜隆塔爾的洛卡·刃影。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2019 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2019,'zhTW','交易工具','出發吧，$n。這些東西你用起來一定會很趁手。它們都是我親手製作的，我發誓你找不到更好的了。$B$B別把你的工作告訴我，那隻會讓我心煩。畢竟，我對瑟祖克的計劃是一點興趣都沒有了，我只希望自己能過上平靜的退休生活。$B$B如果你需要一套新的工具的話，就隨時回來找我，我會給你造一套新的。不過你要小心使用它們！','向奧格瑪暗影裂口的瑟祖克復命。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2020 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2020,'zhTW','暫無內容','好了，重點來了。','','','去找奧格瑪的瑟祖克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2038 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2038,'zhTW','賓格斯的補給品','好像在洛克湖墜機還不夠倒楣似的，湖心小島上的穴居怪還襲擊了我，搶走了我的工具和氣壓爆裂物。沒有旋翼機沒有爆裂物，我什麼都做不了!$B$B去幫我找回工具和氣壓爆裂物， $N 。為了諾姆瑞根!','找回賓格斯的裝備:','','去洛克莫丹找洛克湖的賓格斯·雷管。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2039 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2039, 'zhTW', '尋找賓格斯', '我們和賓格斯失去了聯繫!他被派去偵察諾姆瑞根，不過已經有足足一個星期沒回來報告了。這傢伙應該是失蹤了。最後有人看到他時，他正在洛克湖上空飛行。你可以去那一帶調查一下，$N。', '去洛克莫丹尋找賓格斯·布萊頓海默。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2040 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2040,'zhTW','地底突襲','諾姆瑞根已經被那群卑鄙懦弱的穴居怪們完全佔據了!情況很緊急，或許你能幫上我們的忙， $N 。$B$B在死亡礦坑深處有一台功能強大的哥布林伐木機，找到這台伐木機並帶回它的能源供應機件。有了這台伐木機的能源供應機件，我們就能給高速鑽孔挖掘機供應足夠的能量，用它來鑽透這裡與諾姆瑞根之間的岩石。鑽開一條路，給他們來一次地精式的突襲!','從死亡礦坑中帶回小型高能發動機，將其帶給暴風城矮人區中的沉默的舒尼。','','去暴風城的矮人區找沉默的舒尼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2041 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2041, 'zhTW', '沉默的舒尼', '也許……也許你能幫我們攻打諾姆瑞根。你可以到暴風城去找秘密攻擊部隊的指揮官，沉默的舒尼。舒尼需要有人幫他找一些東西。你可以在暴風城的矮人區中找到她。祝你好運，$N。', '在暴風城的矮人區和沉默的舒尼談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2058 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2058,'zhTW','暫無內容','殺了一個人，他是刺客同盟的成員。他殺害了死亡守衛的前任首領。','','','去找。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2059 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2059,'zhTW','暫無內容','你猜怎麼著，我們對你很感興趣。','','','去找。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2078 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2078,'zhTW','基爾卡克的報復','旱鴨子，你得幫忙找到我的大副。$B$B帶上這把鑰匙，把它插入我的大副身上的鑰匙孔裡，然後把他給我帶回來。$B$B那些魚人們馬上就要吃不了兜著走了，因為我的大副就要回來啦!','找到基爾卡克的大副─機械打手4100型，把他帶到基爾卡克那裡。','','去黑海岸找薄霧海的基爾卡克·旋杆。','基爾卡克的大副','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2098 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2098,'zhTW','基爾卡克的鑰匙復原','想要當一個出色的海賊可不簡單呀，你這個旱鴨子是不會理解的。我們的生活並不僅僅只是掠奪和痛飲!唉，我的船在海岸附近被那些可惡的魚龍給弄沉了。$B$B我希望我的大副能夠重新回來工作!$B$B當我被沖到海岸的時候，大副的鑰匙在岩石上折斷了，接著又被黑海岸那一帶的怪物給偷走了，我只記得隱約看見一些狂暴暗礁蟹、兇猛的森林陸行鳥和幾個魚人正在搜尋船的殘骸...','找到基爾卡可鑰匙的3段碎片，把它們交給基爾卡克‧旋杆。','','去黑海岸找薄霧海的基爾卡克·旋杆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2118 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2118,'zhTW','瘟疫蔓延','一種疾病正在黑海岸蔓延，它能夠控制一切與它接觸的靈魂和肉體。$B$B這種瘟疫對薊熊的影響最大，使得這種曾經高貴的動物現在幾乎變成了毀滅和殺戮的機器─它們變得狂暴，完全失去了理智。我有一種方法應該可以治療這種病。$B$B把這個陷阱放到森林的空地上。任何狂暴薊熊經過時，都會在短時間內變得馴服。一旦薊熊安靜下來了，就上前安撫它，減輕它的痛苦(使用/soothe命令)，然後它就會跟你走。把它帶到這裡來， $N 。','你帶回染病的薊熊了嗎，小心慢慢?','','去黑海岸找奧伯丁的薩納瑞恩·綠樹。','捕獲狂暴薊熊','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2138 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2138,'zhTW','清除疫疾','正如我所擔心的，這種療法沒有得到效果。$B$B對我來說，任何野生動物的死都是一件令我難過的事情，但是我們必須殺掉這些感染了瘟疫的狂暴薊熊。$B$B $N ，回到森林裡去，殺掉20隻狂暴薊熊。這雖然無法驅散瘟疫，但可以在短期內降低狂暴薊熊對這片森林和森林裡的居民們帶來的破壞。','到森林裡去殺掉20隻狂暴薊熊。','','去黑海岸找奧伯丁的薩納瑞恩·綠樹。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2139 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2139,'zhTW','薩納瑞恩的希望',' $N ，我們用慘痛的代價換取了黑海岸和奧伯丁的平安。$B$B你殺了很多早已病入膏肓的動物，減輕了森林的痛苦，也解脫了這些動物的靈魂。儘管這種狀況只能持續一小會兒，但是奧伯丁的人民感謝你。$B$B我要交給你最後一項任務，請注意，這將是又一次的殺戮任務。我希望這是最後一次讓你去做這樣的事情， $N 。$B$B有一隻雌薊熊住在東北方的一個靠近巴莎蘭的洞穴裡，殺了她。','找到雌薊熊，然後殺掉它。','','去黑海岸找奧伯丁的薩納瑞恩·綠樹。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2158 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2158, 'zhTW', '休息和放鬆', '每個冒險家在疲憊的時候都需要休息─而休息和放鬆的最佳去處就是獅王之傲旅店!我的好朋友法雷是那裡的旅店老闆。告訴他是我介紹你去的，也許他還會給你些特別優惠呢。如果你要去獅王之傲旅店的，沿著大路往南走就沒錯了!', '和獅王之傲旅店的旅店老闆法雷談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2159 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2159, 'zhTW', '多蘭納爾的貨物', '你好，年輕的$c。你能幫我一個忙嗎?我有一包藥草必須送到多蘭納爾去，但是現在我還要忙於處理幽影谷德魯伊的事情，所以走不開。$B$B你能幫我把這包藥帶去嗎?把它送到多蘭納爾旅店的老闆凱達米爾那裡，那座旅店就在南方的路邊上。', '把藥草送到旅店老闆凱達米爾手中。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2160 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2160, 'zhTW', '塔諾克的補給品', '嘿!我一看就知道你是個精力充沛的冒險家。如果你要繼續前進的話，能不能幫我帶個包裹到卡拉諾斯的旅館去?$B$B你應該已經計畫在那個旅店裡稍作休息了，對吧?我敢說只要你到了旅店，就肯定會想在那裡歇一下腳。$B$B無論如何，請把這包裹帶給旅館主人的助手塔諾克·霜錘。我自己是沒法活著穿越那危險的通道了，巡山人衛隊還得過些天才會經過這兒，所以我只能靠你了。', '把旅店補給木箱帶給卡拉諾斯的塔諾克·霜錘。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2161 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2161, 'zhTW', '苦工的重擔', '對不起，你能幫幫我嗎?$B$B我這兒有一車食物，一路上我遭遇了蠍子、蜘蛛，還有其他更可怕的東西!我把這些食物送到了試煉谷，因為我覺得他們可能會需要這個，同時我又很樂意幫助他們。$B$B但是他們居然根本就不需要食物!現在我還得把這些東西帶回剃刀嶺，可是我害怕路上的那些野獸……$B$B你能不能幫我送回去呢?我只是個苦工，可你是個大英雄，你一定什麼都不怕!$B$B請把東西交給剃刀嶺旅館的老闆格羅斯克。', '把烏克爾的貨物帶給剃刀嶺的旅館主人格羅斯克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2178 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2178,'zhTW','燉陸行鳥','你聞到撲鼻的香氣了嗎?那可是用我的秘方精心烹製的、新鮮出爐的陸行鳥燉肉，口感超絕，美味無比!$B$B你對我的食譜很感興趣吧?$B$B在我告訴你食譜之前，你得證明你能對付那些動物。$B$B我可並不是要求你簡單地跑出去馴服一隻陸行鳥，然後騎回來見我。你得去捕殺一些陸行鳥，把它們那些多汁的肉脯帶回來給我。只有這樣我才會把陸行鳥燉肉的秘方教給你。','給急彎河的奧蘭達利亞‧夜歌帶回5塊陸行鳥肉。','','去黑海岸找奧伯丁的奧蘭達利亞·夜歌。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2198 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2198,'zhTW','破碎的項鍊','你找到了一條破碎的項鍊，但是破舊不堪的外表並不能掩飾它高超的製作工藝。項鍊已經破碎，原本應該鑲在項鍊上的三塊寶石不見了。在項鍊的內側印有鐵爐堡的徽記，旁邊還刻著三個小字：“TdK”。$B$B如果你想要了解這條項鍊背後的故事，你就必須找到它的主人。也許那個徽記和小字就是線索……','找到破碎的項鍊的來源，從而瞭解其潛在的價值。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2199 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2199,'zhTW','昂貴的知識','我在鐵爐堡可是鼎鼎有名的珠寶匠！好吧，我承認那是以前的我……因為一個競爭對手的汙衊讓我變成現在這個樣子！名聲不好在這行裡就根本混不下去。結果，你看，我現在就變得窮困潦倒。$B$B現在，我要你給我搞五塊銀錠來，這樣我才能完成我手頭上的這份訂單——看來這是我唯一的一份訂單了。$B$B你給我五塊銀錠之後，我就會回答你所有關於這條項鍊的問題。','給鐵爐堡的塔瓦斯德·基瑟爾帶去五塊銀錠。','','去找溼地的塔瓦斯德·基瑟爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2200 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2200,'zhTW','回到奧達曼','我的一個邪惡的競爭對手居然汙衊我，說是我製作的項鍊詛咒了那個聖騎士！顯然沒有人願意買被詛咒的東西。$B$B不如我們來做筆交易吧：如果你能幫我找回寶石，我就能重新把它鑲到項鍊上，然後只要你幫我宣傳這條項鍊並沒有受到詛咒，幫我恢復名譽的話，我就將把這條項鍊送給你！$B$B我建議你從奧達曼開始蒐集線索，或許那個聖騎士的屍體就在下面，畢竟他是最後一個擁有它的人！當你找到寶石之後就使用這個東西，它可以讓你隨時和我進行聯絡。','去奧達曼尋找塔瓦斯的魔法項鍊，被殺的聖騎士是最後一個拿著它的人。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2201 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2201,'zhTW','尋找寶石','從這個聖騎士的日記上看，只有奧達曼才有可能是項鍊上的那三塊寶石的所在地。如果日記的描述還算準確的話，在奧達曼裡有大量的暗爐矮人和石顎怪在活動。$B$B知道了這些資訊之後，對寶石的搜尋行動就可以開始了。當你收集到所有的寶石之後，透過塔瓦斯德的占卜之瓶和他聯絡來獲取下一步的指示。','在奧達曼尋找紅寶石、藍寶石和黃寶石的下落。找到它們之後，透過塔瓦斯德給你的占卜之瓶和他進行聯絡。','','去找塔瓦斯德的占卜之碗。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2202 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2202,'zhTW','奧達曼的蘑菇','$N，我聽說有一種紫色蘑菇剛剛被發現，它們似乎只在奧達曼挖掘場裡生長。我需要十二個這樣的蘑菇來進行鍊金術的研究。$B$B你要多加小心，這種蘑菇會噴射出有毒的孢子。$B$B幫我這個忙吧，我會給你豐厚的報酬，另外還可以讓你嚐嚐我收藏多年的好酒！','收集12顆紫色蘑菇，把它們交給卡加斯的加卡爾。','','去荒蕪之地找卡加斯的加卡爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2203 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2203,'zhTW','荒蕪之地的材料 II','$C，你幫我了大忙了。我願意與你分享你曾經品嚐過的那種佳釀的配方……但我還要你去完成一項相當危險的任務。仔細聽好我的要求。$B$B這隻有鎖的箱子裡面裝著三個空的魔瓶，它們被賦予了一種能夠汲幹烈焰守護者血液的魔法能量，用魔瓶收集烈焰守護者的血液是非常危險的，所以請多加小心。當你裝滿了三個瓶子之後，就把它們交給我。$B$B快去吧，你離那個配方只有一步之遙了。','用空的魔瓶吸收荒蕪之地的烈焰守護者的血液。裝滿所有瓶子之後，把它們交給卡加斯的加卡爾。','','去荒蕪之地找卡加斯的加卡爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2204 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2204,'zhTW','修復項鍊','你現在需要去為項鍊找到它的“精神”力量，奧達曼無疑最適合的地方。據說那裡有很多的石人跑來跑去，對嗎？那麼，殺死他們當中最強大、最邪惡的那個石人，然後把他身上的能量源奪過來！我敢保證可以把那能量源裡的能量重新注入到項鍊之中。$B$B如果沒有那樣的能量源，想要修復項鍊根本是不可能的。取得能量源之後盡快回到鐵爐堡來找我，然後我們就能把項鍊完全恢復到原來的狀態啦！','從奧達曼最強大的石人身上獲得能量源，然後將其交給鐵爐堡的塔瓦斯德。','','去找溼地的塔瓦斯德·基瑟爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2205 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2205,'zhTW','軍情七處','徽章？哦，沒什麼，你應付不了的。看你的樣子，我敢說馬迪亞斯·肖爾一定會把你當成送乳酪的$g男孩:女孩而不是個真正的盜賊。不管怎樣，我被指派了一個任務，而且我曾保證要完成這個任務。$B$B對了，說到這個，你去把這個包裹帶給馬迪亞斯吧，他可能會交代你去做些事情。$B$B快去吧。','把科瑞恩·塞爾留斯的包裹帶給暴風城兵營的馬迪亞斯·肖爾。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2206 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2206,'zhTW','連偷帶搶','我們派在外面的探子回報說，迪菲亞兄弟會在閃金鎮南部的活動相當頻繁。報告中還說道，迪菲亞兄弟會控制了傑羅德碼頭，並利用它將大量的違禁品從赤脊山走私到西部荒野去。$B$B我要你想辦法到碼頭旁的屋子裡去一趟，把裡面的船運時間表給我偷出來，那東西應該就在碼頭主管的衣服口袋裡。$B$B……還有，$N，如果你的行動被發現了的話，暴風城軍情七處將不會承認你的存在。','找到迪菲亞碼頭主管，從他那裡為馬迪亞斯·肖爾拿到迪菲亞船運時間表。','','去暴風城找軍情七處的馬迪亞斯·肖爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2218 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2218,'zhTW','救贖之路','又一個迷失的靈魂，是來尋找指引的麼？我想你一定希望能找到目標——屬於你自己的目標。像你這樣的$r我已經見過不下一千個了，又是一個找活幹的英雄！$B$B今天你運氣不錯，朋友，霍格拉爾可以幫你。$B$B按照我說的去做吧：沿著這條路到鐵爐堡，找到被遺棄的洞穴裡的盜賊公會，和霍夫丹·黑鬚談談，他會指引你一條救贖之路的。','和鐵爐堡的霍夫丹·黑鬚談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2238 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2238,'zhTW','國王的財寶','你知道，國王搶走了採集礦石寶物的機會，那些財富……矮人活十輩子也掙不到。$B$B我們在鐵爐堡那裡有些關係，$N，很有價值的關係，你懂吧？$B$B國王應該把他的財寶拿出來和我們分享，不過我們不想讓那老傢伙知道他正在和我們分享——你懂我的意思吧。$B$B你到諾莫瑞根附近去和奧寧·雨錘談一談，然後回來跟我報告。那個狡猾的矮人混跡在一群麻瘋侏儒當中，你要小心點。','在諾莫瑞根附近找到奧寧·雨錘。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2239 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2239,'zhTW','奧寧的報告','你是說採石場？是的，我幾乎天天都能看見那些龐大的蒸汽坦克從營地邊經過。$B$B我在東邊佈下的線人告訴我，這些機車是從鐵爐堡出發的，在古博拉礦場稍作停留之後，在卡拉諾斯補給燃料，由於某些該死的原因，他們用了很長的時間才經過諾莫瑞根，最後在鐵爐堡卸下了貨物。$B$B情況全都寫在這份報告裡了，$c。把它交給霍夫丹，讓他好好計劃下一步的行動。','把奧寧的報告交給鐵爐堡的霍夫丹。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2240 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2240,'zhTW','密室','現在我手頭有個任務。$B$B我們要找到一間被稱作卡茲穆爾大廳的密室。問題是這個房間在一扇巨大的門後面，而那扇門被鎖住了！幸運的是，我知道如何開啟它。$B$B我把所有東西都寫在我的日記裡了，就在這個臺子上。我的隊伍現在被困在這裡……所以呢，$n，你必須為我們找到卡茲穆爾大廳！$B$B閱讀我的日記，探索那間密室，然後向鐵爐堡探險者協會的勘察員塔伯斯·雷矛彙報。','閱讀巴爾洛戈的日記，探索密室，然後向鐵爐堡的勘察員塔伯斯·雷矛彙報。','探索密室','去找丹莫洛的勘察員塔伯斯·雷矛。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2241 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2241, 'zhTW', '詹諾克的花', '他們說我已經「陷入愛的深淵」，管它是什麼意思呢。$B$B當然啦，我清醒的每一刻都在想念著塞尤娜，我的家裡也掛滿了她的畫像。當然，我會經常不吃不喝也不睡地度過一整天，深陷於我們曾經擁有的美好愛情的回憶之中。這難道有錯嗎?$B$B現在她不會再見我了!我想要給她傳遞消息，但她不願和任何人說話，除非那人是個盜賊。$B$B你能替我把這些花帶給她嗎?別忘了告訴她這些花是詹諾克送的。', '把詹諾克的玫瑰帶給達納蘇斯的塞尤娜。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2242 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2242,'zhTW','命運的召喚','我們相信有一個薩特可以幫助我們搞清泰達希爾的森林中究竟發生了什麼。但不幸的是，他可不會老老實實地跟我們合作。$B$B他的藏身之處就在神諭林地週邊的一棵樹上，但是與他接觸的人─無論是使用武力還是試圖交涉─都被他殺死了。也許只有偷偷摸摸地行動才是唯一可行的方案， $N 。$B$B去看看塞希爾的包裹裡有些什麼，然後回來向我報告。','找到遠古的塞希爾，帶回任何你可能發現的線索。','','去達納蘇斯找貿易區的塞尤娜。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2258 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2258,'zhTW','荒蕪之地的試劑','$C，我需要你的幫助。我是個略有名氣的鍊金術者，現在我想請你去荒蕪之地幫我弄些試劑來。$B$B我需要以下物品：5個禿鷲的胃囊，10顆峭壁山狗的牙齒，還有5個石元素的碎片。當然，你可以從那裡的野獸身上弄到這些東西，但是假如你不是那麼善於戰鬥的話，就去找一些朋友幫幫忙吧。$B$B幫我找到這些物品，我就會給你些錢作為報酬。願意試試嗎？','前往荒蕪之地取回加卡爾需要的試劑，然後回到卡加斯把試劑交給他。','','去荒蕪之地找卡加斯的加卡爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2259 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2259, 'zhTW', '艾里安·影語', '別擔心，$N，我不是要把你送去見塞尤娜。艾里安正在塞納里奧區等你，快點吧!', '與達納蘇斯的艾里安·影語取得聯繫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2260 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2260, 'zhTW', '艾里安的命令', '你已經是個很有名氣的$c了，$N。事實上，暴風城的情報機構點名要你去為他們效力。這次旅行會很辛勞，而且一路上危機四伏，不過我想誰也不會輕易放棄在暴風城軍情七處訓練的機會。一個嶄新的世界在等著你，$N。到暴風城的舊城區去,和軍情七處總部裡的「剃刃」雷吉克談一談吧，祝你好運。', '到暴風城去找到「剃刃」雷吉克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2278 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2278,'zhTW','白金圓盤','財寶室的中間是四塊巨大的白金圓盤，每塊圓盤上都刻滿了各種各樣的未知文字和圖案。你的手觸控這些圓盤的時候，你感到了一絲震動。就在你接觸圓盤的一瞬間，一個巨大的石頭守衛者的形象出現在了你的面前。$B$B“你好。我是知識的守衛者。土靈的創造者所留下的一切有關這個種族的知識都已經儲存在了這張諾甘農圓盤上了。”$B$B你發掘到了迄今為止這個世界上最寶貴的知識財富！','和石頭守護者交談，從他那裡瞭解更多古代的知識。一旦你瞭解到了所有的內容之後就啟用諾甘農圓盤。','學習石頭守護者所看守的知識','使用諾甘農圓盤。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2279 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2279,'zhTW','白金圓盤','再次觸及諾甘農圓盤讓你的手感受到了又一次的震顫。這一次從圓盤傳出了一種奇怪的研磨聲。$B$B你的揹包忽然沉了一下。開啟揹包之後，你發現了一張迷你版的圓盤！$B$B毫無疑問，在任何對艾澤拉斯大陸歷史感興趣的人手中，這張圓盤都絕對是無價之寶。鐵爐堡的探險者協會是一個非常有名的探險團體，也許他們能好好利用這張圓盤。','把迷你版的諾甘農圓盤帶到鐵爐堡的探險者協會去。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2280 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2280,'zhTW','白金圓盤','再次觸及諾甘農圓盤讓你的手感受到了又一次的震顫。這一次從圓盤傳出了一種奇怪的研磨聲。$B$B你的揹包忽然沉了一下。開啟揹包之後，你發現了一張迷你版的圓盤！$B$B毫無疑問，在任何對艾澤拉斯大陸歷史感興趣的人手中，這張圓盤都絕對是無價之寶。雷霆崖的先知們對歷史知識的瞭解程度享譽整個部落，也許他們能好好利用這張圓盤。','把迷你版的諾甘農圓盤帶到雷霆崖的賢者那裡。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2281 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2281, 'zhTW', '赤脊山的聯絡員', '現在就把你派出去等於讓你去自殺，雷吉克可不想再讓哪個初出茅廬的盜賊平白掛掉。不過你也別著急，$N。雷吉克要先培養你的能力。現在你就動身去赤脊山，和一個名叫盧修斯的軍情七處聯絡員談一談吧。他就在湖畔鎮的碼頭附近，和其他一些遊手好閒的傢伙整天攪在一起。', '到赤脊山的湖畔鎮去和盧修斯談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2282 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2282,'zhTW','奧瑟爾伐木場','多年以來，我們都在這裡對 $C 進行訓練!畢竟不是每一個 $C 都能像老盧修斯那樣機靈和優雅的。$B$B沿著這條路向前走，一直到奧瑟爾伐木場去。我在那裡放了一隻裝著重要物品的箱子。去把箱子裡的東西給我拿來，我就給你頒發偷竊技能認證書!','打開盧修斯的帶鎖箱，拿到偷竊技能證明物，然後把它歸還給湖畔鎮的盧修斯。','','去赤脊山找湖畔鎮的盧修斯。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2283 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2283,'zhTW','搜尋項鍊','我們有工作要交給你做，不過能否完成要看你有沒有膽子！$B$B在荒蕪之地的深處有一個名叫奧達曼的挖掘場，我們最近聽說有個沒腦子的聖騎士在裡面掛了。我之所以如此關心這個問題是因為那蠢貨身上帶著一條非常珍貴的項鍊，項鍊上有三塊大寶石：一塊紅寶石，一塊藍寶石和一塊黃寶石。$B$B現在的問題是，我們需要它，而且我們會付給完成這個任務的人最豐厚的報酬。也許那條項鍊已經受到了損壞，但是不管怎麼樣，只要你把它帶給我們，就總是會有辦法修好它。','在奧達曼挖掘場中尋找一條珍貴的項鍊，然後將其交給奧格瑪的德蘭·杜佛斯。項鍊有可能已經損壞。','','去找奧格瑪的德蘭·杜佛斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2284 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2284,'zhTW','搜尋項鍊，再來一次','瑪爾頓這個笨蛋，我確信寶石還在奧達曼的某個地方，你必須回去找到它們。$B$B就像我之前所說的那樣，如果我們掌握的情報是正確的話，那麼這條項鍊上原本應該有紅寶石、黃寶石和藍寶石各一塊。找到它們，並且把它們放回到項鍊上。$B$B至於那些寶石的具體位置就沒有人知道了。如果你運氣不錯的話，也許你能找到那個笨蛋聖騎士的屍體。如果他還沒有被剝光的話，沒準你還能在他身上找到那些寶石。','在奧達曼裡找尋寶石的線索。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2298 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2298,'zhTW','國王的搜查','然後我們就到了那裡，準備執行第三階段的計劃。突然，一夥麥格尼手下的傢伙闖了進來，他們自稱是來搜查的，二話不說就要抓人。$B$B但是沒人敢在我霍夫丹·黑鬚面前動粗！於是雙方唇槍舌劍地開始吵，結果你的名字就被不知道哪個白痴吼了出來！$B$B我的意見？趕緊騎上獅鷲離開鐵爐堡，到暴風城去。到舊城區裡去找我的一個老朋友，他的名字叫“剃刀”雷吉克。','到暴風城裡去找到“剃刀”雷吉克。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2299 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2299,'zhTW','去找霍夫丹！','你去哪兒啦，$N？霍夫丹到處找你。我們都以為國王把你抓起來了。$B$B快去鐵爐堡找霍夫丹！','到鐵爐堡去和霍夫丹·黑鬚談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2300 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2300,'zhTW','軍情七處','雷吉克在找你呢，新手。$B$B如果我是你的話，就不會讓馬迪亞斯的副手乾等著。','到暴風城去找到“剃刀”雷吉克。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2318 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2318,'zhTW','翻譯日記','顯然你看不懂日記上的字，得找個人來幫忙翻譯才行。這個世界上有不少可以勝任這項工作的人，最近的一個應該在荒蕪之地的卡加斯哨所裡。也許你應該去那裡找找。','在荒蕪之地的卡加斯哨所裡尋找一個可以幫你翻譯聖騎士日記的人。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2338 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2338,'zhTW','翻譯日記','杜佛斯那個蠢貨是不可能恢復項鍊的力量的，不過我可以。現在我要做的就是好好研究一下項鍊，然後給你製作一條跟它完全一樣的複製品。請把項鍊借給我作為我幫你翻譯日記的交換吧，在你出發去找尋寶石的這段時間裡，我應該可以完成對項鍊的研究和對日記的翻譯工作。$B$B這個交易很簡單明瞭，而且沒有別人可以幫你翻譯日記。你看怎麼樣？','將項鍊借給加卡爾。作為交換，他將幫你翻譯日記。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2339 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2339,'zhTW','尋找寶貝','日記已經全部翻譯完畢了。$B$B其中的關鍵是紅寶石在暗爐矮人手裡，黃寶石在石顎怪手裡，而藍寶石則在一個名叫格瑞姆洛克的石顎怪那裡。$B$B你需要一個強力能力源來讓項鍊重新恢復以前的力量，這一點是德蘭·杜佛斯所不知道的。我所能想到唯一符合如此要求的能量源應該在奧達曼的最強生物身上，所以你必須深入奧達曼的最底層，殺掉所有看上去最強的生物，這樣你就肯定可以獲得它。$B$B當你把所有東西找全之後就儘快把它們帶回來給我。','從奧達曼找回項鍊上的所有三塊寶石和能量源，然後把它們交給卡加斯的加卡爾。$B$B紅寶石被藏在暗影矮人層層設防的地區。$B$B黃寶石藏在石顎怪活動地區的一個甕中。$B$B藍寶石在格瑞姆洛克手中，他是石顎怪的領袖。$B$B能量源可能在奧達曼的某個最強生物的手中。','','去荒蕪之地找卡加斯的加卡爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2340 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2340,'zhTW','交付寶石','只要採用相同的材料進行製作，任何的項鍊和寶石的組合都能發揮作用。而這個能量源才是真正給項鍊提供力量的關鍵……我希望如此。$B$B只要能量源能夠一直保持正常運轉，我隨時都可以為你製作這麼一條項鍊。$B$B去奧格瑪找德蘭·杜佛斯完成你們的交易吧。記住不要透露任何關於項鍊的資訊，當你回來的時候，我會給你一個特別的驚喜的。','把項鍊和寶石送到奧格瑪的德蘭·杜佛斯那裡。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2341 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2341,'zhTW','項鍊任務的終結 (地下城)','在德蘭和瑪爾頓為了他們的戰利品而爭執不休的同時，你的任務也算完成一半了。現在你得去荒蕪之地完結這個任務，卡加斯營地裡的加卡爾應該已經為你準備好了特別的獎勵。','去卡加斯看看加卡爾是否成功了。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2342 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2342,'zhTW','尋找寶物','我簡直煩透了用這把破掃帚在這裡打掃蝙蝠窩了！我靠這個該死的工作中存了一些錢，而且我願意用這些錢來僱你幫我做些事情。$B$B加瑞特家族的祖傳武器自從我們家到那裡去當挖掘工以來就一直被鎖在奧達曼的南部大廳中的箱子裡。沒有它，我就要永遠被困在這裡——也就是說，我就得永遠跟這些該死的蝙蝠在一起！$B$B找到我家族的寶藏，把它給我拿來！幫我找回原本就屬於我的東西！','從奧達曼南部大廳的箱子中找到加勒特的家族寶藏，然後把它交給幽暗城的帕特里克·加瑞特。','','去銀松森林找幽暗城的帕特里克·加瑞特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2358 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2358,'zhTW','奈茲拉之角','很多年之前，奈茲拉之角被從拉文霍德的領地上偷走了。經過漫長的跋涉和搜尋，我終於得知它一直以來都在那些野獸的手中。$B$B幹掉你見到的所有黑石獸人，直到你奪回奈茲拉之角為止，拿到它之後就回來找我。$B$B請為我找回奈茲拉之角吧，你的名字將永遠被拉文霍德家族銘記， $N 。','將奈茲拉之角交給湖畔鎮的阿蘭提爾。','','去赤脊山找湖畔鎮的混亂之手阿蘭提爾','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2359 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2359,'zhTW','克拉文之塔','我為如何進入這座塔的問題頭痛好久了， $N 。最近從暮色森林來了一船貨物，同時還來了不少守衛。$B$B他們是誰?我也有著和你一樣的疑問。我所知道的是─他們不是人類。$B$B不管怎麼樣，這批貨物中有一隻特殊的箱子─我想這就是那些亡靈在守護的東西。帶著狼牙棒的那個傢伙手裡有那座塔的鑰匙。$B$B拿到鑰匙，進入塔里，看看箱子中到底有什麼，然後去向馬迪亞斯報告。','偷取迪菲亞塔樓鑰匙，進入迪菲亞塔樓，看看暮色森林的箱子裡到底有什麼東西，然後向暴風城的馬迪亞斯·肖爾彙報。','','去暴風城找軍情七處的馬迪亞斯·肖爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2360 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2360, 'zhTW', '馬迪亞斯和迪菲亞盜賊', '$N，不久之前，軍情7處接到西部荒野出現大量迪菲亞兄弟會成員的報告。現在他們已經佔據了位於哨兵嶺東南部的一座荒廢的哨塔，並將其作為從赤脊山走私補給物資的中轉站。到西部荒野去和密探吉爾妮會面，你應該可以在哨塔的附近找到她。另外……$N，一旦你的行動被發現，軍情7處將會否認與你有任何聯繫。', '去西部荒野和密探吉爾妮談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2361 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2361,'zhTW','修復項鍊','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2378 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2378, 'zhTW', '尋找破碎之手氏族', '$N，你一向以來都對我們衷心耿耿，現在是讓你出去闖一闖的時候了。雖然你已經展現出了在盜賊之路上過人一等的天賦，但是你還是需要更多的練習才能達到更高的境界。我們和破碎之手氏族是盟友。去找他們吧，一直以來我們的關係都很好─去奧格瑪找申蘇爾。', '前往奧格瑪，和暗影裂口那的申蘇爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2379 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2379, 'zhTW', '贊杜沙', '單憑你的決心是無法幫助我們克服困境的。去和贊杜沙談談，然後你就可以作為破碎之手氏族的一員接受訓練了。只有掌握了潛行和偷竊的技術，你才能繼續沿著你的命運之路前進。', '與暗影裂口的贊杜沙談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2380 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2380,'zhTW','向奧格瑪進發！','你還不是個秘密行動和欺詐的高手，不過遲早會是的。曾經訓練過你的導師們都對你的潛力印象深刻，於是偉大的申蘇爾點名要召見你。$B$B沿著路向北走，一直到奧格瑪去，在暗影裂口和申蘇爾談一談。','在奧格瑪城中的暗影裂口和申蘇爾談談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2381 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2381,'zhTW','搶劫海盜','我並不是要嚇唬你， $N ，但是前五個派去偷南海寶藏的小偷都是被別人一塊塊運回來的……$B$B沿著這裡南邊的海岸走，你會找到海浪剃刀號，那是南海海賊的船。貨艙中的東西就是你的目標─南海寶藏。在船艙的二層是海賊的聚集處，那裡也是他們訓練 $C 的地方。$B$B設法登上那條船，然後把南海寶藏給我偷到手。你可以在那群海賊紮堆的地方試試自己的身手，但是你要非常小心，否則你就會成為第六個!','把南海寶藏帶回給棘齒城的卑鄙的維尼克斯。不要忘了從維尼克斯的機械設備中拿取一份大餅乾和盜賊工具，你的任務需要使用這兩件東西。','','去貧瘠之地的棘齒城找卑鄙的維尼克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2382 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2382, 'zhTW', '棘齒城的維尼克斯', '贊杜沙確實看到了!是的，我看到了那一天的到來!索爾死了……匕首刺在他的背上，毒液滲透到他的血管之中……贊杜沙說得太多了。$N!贊杜沙有個任務要交給你!你必須馬上到十字路口東邊的棘齒城去，跟卑鄙的維尼克斯談談。', '到棘齒城去，與卑鄙的維尼克斯談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2383 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2383,'zhTW','簡易羊皮紙','啊，剛剛你不在的時候，有人送來了這張羊皮紙，$N。$B$B如果你有時間的話，還是看看這上面說些什麼的好。如果我沒搞錯的話，這張羊皮紙是戰士訓練師弗朗恩寫的，他有事找你。你可以在大獸穴外面的陰涼處找到他。','閱讀簡易羊皮紙，然後和試煉谷的弗郎恩談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2398 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2398, 'zhTW', '失蹤的矮人', '奧達曼挖掘場從前並不是現在這樣一團糟的。我們鐵爐堡的矮人曾經控制了這個區域，但是……當穴居怪來了之後，一切都變了。它們的數量太多了，連我們矮人也擋不住它們!事實上，因為它們非常突然地發起了攻擊，所以我擔心我們有些人被困在了挖掘場裡面。我的朋友巴爾洛戈帶了一個矮人小隊進入了挖掘場深處，就在穴居怪發起攻擊之前。如果他和他的同伴們還活著的話，我希望你能找到他們。', '在奧達曼找到巴爾洛戈。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2399 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2399,'zhTW','發芽的樹葉','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2418 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2418,'zhTW','能量石','不久之前，我和暗爐矮人打過一段時間的交道。他們把我帶到了苦痛堡壘，讓我對兩種來自於奧達曼的奇怪石頭進行研究。我發現這兩種石頭如果經過正確的處理，就會變成相當理想的能量源。能在那個廢舊的挖掘場裡發現這樣的東西讓我感到十分驚奇！$B$B之後，在我告訴他們這個秘密之後，那幫該死的傢伙就把我踢出了苦痛堡壘，然後自己在奧達曼挖掘更多的石頭。$B$B我要為自己搞一些那種石頭！幫我帶那兩種石頭來，我會給你豐厚的報酬的。','給荒蕪之地的裡格弗茲帶去8塊德提亞姆能量石和8塊安納洛姆能量石。','','去荒蕪之地找巨牙谷的裡格弗茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2438 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2438,'zhTW','翡翠攝夢符','班奈希爾獸穴的德魯伊守護者蓋洛拉斯‧塔文斯倫曾經給了我一個翡翠攝夢符。這種強大的護符可以吸取翡翠夢境的能量，給拿著它的人帶來好運。$B$B不過，我把它放在星風村的衣櫃裡了，沒辦法把它取回來...星風村原本是個寧靜的小村子，但現在那裡受到了熊怪的侵襲。$B$B你能不能幫我拿回攝夢符， $C ?','取得翡翠攝夢符。','','去泰達希爾找多蘭納爾的塔隆凱·捷根。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2439 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2439,'zhTW','白金圓盤','這東西真是個驚人的發現。如果這裡儲存的知識都是正確的話，那麼這些圓盤所涉及的古代泰坦——或者說造物之神——肯定和我們的起源有所聯絡！我們要用儘可能多的時間來研究它。$B$B至於你，英勇的$c，把這個憑證交給大廳裡的丁尼塔·石衣，你一定會為你的偉大發現得到應有的報酬！$B$B準備好了之後就回到我這裡來，探險者協會還有很多事等著你去做！','把你的報酬憑證交給鐵爐堡銀行的丁尼塔·石衣。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2440 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2440,'zhTW','白金圓盤','我要把精力都集中在這些圓盤上，它們一定會向我展示其真正的作用。$B$B至於你，$N，你的努力也會得到我的回報。把這個證明交給雷霆崖的鍊金師本娜·冰蹄，她會給你一樣不錯的東西作為回報，還會給你一些我私人收藏的藥水。$B$B盡快回來見我，我感覺這個發現還會讓我有很多事要忙。','把報酬憑證交給雷霆崖的本娜·冰蹄。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2458 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2458,'zhTW','臥底密探','風險投資公司……也許你聽說過他們？$B$B一年以來，我們一直都想在他們的高層中安插一名密探，經過艱苦的努力和仔細的謀劃，我們終於成功了。$B$B最近密探給我們帶來情報說風險投資公司有個大規模的計劃，所以我派你到淤泥沼澤的北部去，在風險投資公司的塔樓附近聯絡我們的臥底密探費蘇勒。$B$B找到塔樓之後，用這個訊號槍和費蘇勒聯絡，然後用碎手軍禮向他致敬。','到淤泥沼澤北邊的風險投資公司塔樓去，聯絡碎手氏族的臥底費蘇勒。$B$B看到塔樓之後，用訊號槍發射訊號，向工頭費蘇勒示意你已經到達。發出兩個閃光訊號，然後使用碎手軍禮和工頭費蘇勒接頭。$B$B注意，這些步驟必須依次進行，因為費蘇勒會攻擊並幹掉任何他無法識別的人。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2459 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2459,'zhTW','『食夢者』菲羅斯塔','翡翠...不見了!我的攝夢符被毀了!$B$B星風村北部有一群瘤背秘法師。我接到報告說他們的領袖『食夢者』菲羅斯塔的脖子上戴著一條在夜間會發出綠光的項鍊。我覺得就是他偷走了我的翡翠...他絕不會想到那顆翡翠對他毫無用處。$B$B去找到丟失的寶石， $N 。另外，你在那兒活動的時候，別忘了順便清除一些墮落的瘤背秘法師。','殺掉7個瘤背秘法師，並找到遺失的珠寶。','','去泰達希爾找奧拉密斯湖的塔隆凱·捷根。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2460 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2460,'zhTW','碎手軍禮','作為碎手氏族的潛行者，你必須學會碎手軍禮。這是識別氏族成員的唯一方法。$B$B看好了，然後重複做一遍。','對著申蘇爾練習碎手軍禮。','碎手軍禮','去找奧格瑪的申蘇爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2478 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2478,'zhTW','基本不可能的任務','你必須從工頭希裡克斯身上偷出塔樓的鑰匙，$N。拿到鑰匙之後，就把它收好——你也許用得到它。$B$B記住，毒藥已經讓塔樓裡的所有人都變得虛弱不堪。盡你所能給那些傢伙製造混亂和破壞，把他們全都殺了——不要手下留情！$B$B等裡面所有人都躺在血泊中之後，你就可以去開啟加里維克斯的箱子，然後拿走贊吉爾的改良藥劑。把加里維克斯的腦袋和藥劑一起交給奧格瑪的申蘇爾。','從工頭希裡克斯那裡偷出希裡克斯的塔樓鑰匙，進入塔樓，然後殺掉兩個變異風險投資公司工人、兩個風險投資公司巡邏員、兩個風險投資公司看守。$B$B殺掉大工頭普茲克·加里維克斯，取了他的首級，然後開啟加里維克斯的箱子，拿走贊吉爾的改良藥劑。將藥劑和加里維克斯的頭顱交給奧格瑪的申蘇爾，等候進一步的指示。','','去找奧格瑪的申蘇爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2479 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2479,'zhTW','希諾特的幫助','把這個混合物的樣本交給塔倫米爾的瑟爾格·希諾特。$B$B只有瑟爾格能治得了你所中的毒。如果你能活得久一點的話，他還能教你製造並使用這種毒藥的方法。','到希爾斯布萊德丘陵的塔倫米爾去，把贊吉爾的藥劑樣品交給瑟爾格·希諾特。$B$B要去塔倫米爾，可以搭乘飛艇到幽暗城，然後沿著大路向南穿過銀松森林，直到希爾斯布萊德丘陵。跟著路標走！','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2480 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2480,'zhTW','希諾特的幫助','我從來沒有見過哪種毒藥能產生這麼驚人的效果！你是說贊吉爾？從沒聽過這個傢伙，不過既然他能製造出這種毒藥來，那他還是值得我刮目相看的。$B$B那麼你是要我幫你解毒，然後教你如何使用這種毒藥？$B$B給我點時間研究一下毒藥，$N。','等待瑟爾格·希諾特完成解藥。','解藥完成','去希爾斯布萊德丘陵找塔倫米爾的瑟爾格·希諾特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2498 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2498, 'zhTW', '向德納蘭回報', '我剛接到消息，奧拉密斯湖畔的德納蘭可能已經發現了讓樹精長出那些毒瘤的原因。你去和他談談吧，告訴他是我派你去的。動作快點，$N，他需要我們的幫助。', '雷利亞·綠樹要你和奧拉密斯湖的德納蘭談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2499 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2499,'zhTW','奧肯斯古爾','我搞明白了!我不得不衝來這裡找你!其實答案很簡單...腐化是經由樹精傳染的，但源頭卻只有一個。$B$B奧肯斯古爾已經被一顆我所見過的最大的腫瘤毒害了...那個腫瘤簡直可以稱之為龐然大物。$B$B奧肯斯古爾過去住在我湖泊附近的一個洞穴裡，但後來跑到了東北方的一個隱蔽處。 $N ，殺掉奧肯斯古爾，拿到它身上的腫瘤，讓這個墮落之源永遠從我的家園消失。','從奧肯斯古爾那裡取得巨大的瘤。','','去找泰達希爾的德納蘭。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2500 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2500,'zhTW','荒蕪之地的試劑',' $C ，我需要你的幫助。我是個小有名氣的鍊金師，我需要你去荒蕪之地幫我找一些原材料。$B$B我需要這些東西補充我的庫存:五個禿鷲的胃囊、十顆峭壁山狗的牙齒和五塊岩石元素裂片。當然你可以從這些動物身上拿到這些東西，不過如果你不擅長打仗的話，可以找些擅長的朋友。$B$B找到這些東西給我，作為交換你可以得到一些錢幣。$B$B好吧，你覺得怎麼樣?','從荒蕪之地拿到加克所需的材料，然後回到塞爾薩瑪去見他。','','去洛克莫丹找灰爪山的加克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2501 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2501,'zhTW','荒蕪之地的材料 II','你對我的幫助很大，$N。我可以把以前我給你的那種酒的配方作為報酬送給你，不過還得讓你先幫我個忙才行——這次的事比較危險。$B$B這隻上鎖的箱子裡裝著三個空的魔瓶，裡面有一種可以吸取火龍血液的魔法能量。用這些容器去對付火龍會把它們激怒，所以你得小心點。把三個容器都盛滿了，再把它們拿回來給我。$B$B完成這個任務之後，配方就是你的了。','在荒蕪之地的守護火龍身上使用空的魔瓶。將這些容器都盛滿之後，把它們交給塞爾薩瑪的加克。','','去洛克莫丹找塞爾瑪的加克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2518 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2518,'zhTW','月神的淚水','薩絲拉女士曾經受到月神的寵愛，這只優雅而純潔的蜘蛛在月光下的迷霧中編織著銀線，用以收集銀色的露水，並將這種有強大治療功效的露水存放在附近的神殿裡。$B$B不過最近薩絲拉突然變得瘋狂起來，她的後代也受到了威脅。$B$B找到薩絲拉， $N ，結束她的痛苦。她住在這裡東北邊的河流附近。取得她的銀色絲囊，然後帶回來交給我。','取得薩絲拉的銀色絲囊。','','去達納蘇斯找神殿花園的女祭司艾茉拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2519 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2519, 'zhTW', '月神殿', '森林裡有一個曾經強大無比的生物現在急需幫助，$c。現在你有一項艱難的任務必須完成。請你去找女祭司艾茉拉，她會向你解釋具體的問題。她就在這裡東南方的月神殿裡。', '艾奎恩妮修女讓你和月神殿的女祭司艾茉拉談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2520 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2520,'zhTW','薩絲拉的祭品','現在你必須完成交給你的任務。拿上銀色絲囊，然後將它作為薩絲拉的祭品獻給伊露恩，讓這只蜘蛛得以安息。$B$B找到大殿中央的噴泉，在那兒放下祭品。神聖的泉水可以淨化並清洗讓薩絲拉發瘋的墮落力量。$B$B完成任務之後再回來見我。','女祭司艾茉拉讓你將薩絲拉女士的銀色絲囊放在大殿的噴泉處，然後回去見她。','在噴泉處奉上祭品','去找達納蘇斯的女祭司艾茉拉。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2521 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2521,'zhTW','為庫米沙效力','$R，你的小腦袋能理解一顆無暇的德萊尼水晶球有多麼珍稀嗎？無數德萊尼人終其一生就想要尋找一塊這樣的水晶，可是卻屢遭失敗，一直沒能達到願望。$B$B你現在就站在庫米沙面前，你知道庫米沙想要什麼，而且你還願意幫助我？很好，$r……在你探索者個區域的過程中，只要找到一顆無暇的德萊尼水晶球，就把它帶回來給我，我會以你永遠都無法想象的財富回報你。','在你探索詛咒之地的旅程中，如果碰巧發現了無暇的德萊尼水晶球，就把它交給收藏家庫米沙。$B$B你要知道，這種寶石是整個艾澤拉斯最珍稀的水晶。詛咒之地上的任何一種生物都有可能帶著一顆無暇的德萊尼水晶球。$B$B每找到一顆，你都會得到相應的酬勞。','','去找詛咒之地的收藏家庫米沙。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2522 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2522,'zhTW','庫米沙的努力','雖然召喚傳送門的魔法失敗了，不過我相信下一次一定能成功。$B$B德萊尼人的希望就象你們$R對財寶的渴望一樣強烈，回到這塊被詛咒的土地中去，再給我拿回一顆無暇的德萊尼水晶球來。$B$B當然，要不要接受這個任務完全取決於你*咧嘴笑*。','找到一顆無暇的德萊尼水晶球，把它交給收藏家庫米沙。','','去找詛咒之地的收藏家庫米沙。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2523 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2523,'zhTW','被腐化的輕歌花','','','','去找費伍德森林的被腐化的輕歌花。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2541 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2541,'zhTW','沉睡的德魯伊','這裡的瘤背薩滿找到了一種可以在德魯伊休眠時將他的靈魂和肉體分離的方法。熊怪就這樣驅使著我的肉身，利用我去襲擊那些對班奈希爾獸穴進行偵察的人。現在我沉睡在翡翠夢境裡，無法阻止他們。$B$B你一定要幫幫我。瘤背薩滿用一種特殊的符咒來完成這種儀式，我希望能研究一下這種符咒。 $N ，全靠你了。','將一個薩滿巫毒符咒交給班奈希爾獸穴的奧本·怒爪。','','去找泰達希爾的奧本·怒爪。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2561 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2561,'zhTW','利爪德魯伊','在研究過這個符咒之後， $N ，我知道該做什麼了。請拿著它，然後照我說的去做。$B$B你必須接近附近房室的門。在門裡，你會發現我那失去靈魂的軀體...雖然我對接下來要說的話感到很遺憾，但是除此之外我找不到其他可以讓我擺脫瘤背熊怪控制的辦法了。$B$B你必須殺了我的肉身，然後對我的屍體使用巫毒符咒。完成這個任務之後就請回到我這裡來。','奧本·怒爪要求你去殺掉他那失去靈魂的身體，然後對其屍體使用巫毒符咒。','釋放奧本·怒爪的靈魂','去找班薩羅獸穴的奧本·怒爪。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2581 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2581,'zhTW','彎牙土狼的顎骨','眾所周知，土狼的顎骨具有強大的力量，不過它能折斷三英寸厚的瑟銀條嗎？不可能，決不可能，可是我卻親眼看到了這種事情。$B$B到詛咒之地去給我弄三個彎牙土狼的顎骨回來，路上順便打一些野豬和蠍子，因為我還需要兩片詛咒之地的野豬肺和一個厚甲蠍螯。','收集3個彎牙土狼的顎骨、2片詛咒之地的野豬肺和1個厚甲蠍螯，把它們交給血法師德拉吉亞。','','去找詛咒之地的血法師德拉吉亞。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2582 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2582,'zhTW','遠古之怒','啊，$N，歡迎回來。你好像非常喜歡從土狼的顎骨中提煉出來的藥劑所帶給你的感覺。但是你要小心，雖然它可以使你擁有泰坦一般的力量，不過它對你的精神和智力也具有長期的負面作用。$B$B我跟你說了這麼多之後，你還想要更多這種藥劑嗎？如果你還要的話，就給我弄三個彎牙土狼的顎骨、兩片詛咒之地的野豬肺和一個厚甲蠍螯來。','收集3個彎牙土狼的顎骨、2片詛咒之地的野豬肺和1個厚甲蠍螯，把它們交給血法師德拉吉亞。','','去找詛咒之地的血法師德拉吉亞。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2583 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2583,'zhTW','野豬的活力','這片不毛之地上生活著兩種野豬：灰鬃野豬和地獄野豬。$B$B看來這些野獸的耐力十足，這讓它們幾乎可以不受任何傷害，因此其它動物都無法與之抗衡。$B$B我們要做進一步的研究，$N。你給我弄三片詛咒之地的野豬肺、兩個厚甲蠍螯和一顆石化蜥蜴的大腦來，我就可以從中提煉出一種超強的藥劑。而你就將成為我的第一個實驗物件！','收集3片詛咒之地的野豬肺、2個厚甲蠍螯和1顆石化蜥蜴的大腦，把它們交給血法師德拉吉亞。','','去找詛咒之地的血法師德拉吉亞。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2584 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2584,'zhTW','野豬之魂','在第一次試用這種藥劑的時候，我就知道僅用一兩次是無法滿足你對它的渴求的。即使是現在，我也還能看見你眼中的渴望。這種藥劑會讓人上癮，再有意志力的人也無法抵擋它的誘惑。$B$B好吧！如果你還想要更多的肺片雞尾酒，就到詛咒之地裡去給我弄三片詛咒之地的野豬肺、兩個厚甲蠍螯和一顆石化蜥蜴的大腦來。','收集3片詛咒之地的野豬肺、2個厚甲蠍螯和1顆石化蜥蜴的大腦，把它們交給血法師德拉吉亞。','','去找詛咒之地的血法師德拉吉亞。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2585 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2585,'zhTW','決定性的打擊','你見過它們作戰嗎，$N？我是說那些蠍子。你有沒有見過他們優美、敏捷的動作？有沒有看到過它們那迅捷的攻擊？$B$B如果我們能將它們的敏捷性分離出來並製成藥劑，那我們就發達了……我的意思是……那將是我們對科學的一大貢獻！$B$B幫幫我吧，$N，我可以送給你一份實驗樣品。$N我需要三個厚甲蠍螯，兩個禿鷲的砂囊和一片詛咒之地的野豬肺。','收集3個厚甲蠍螯、2個禿鷲的砂囊和1片詛咒之地的野豬肺，把它們血法師德拉吉亞。','','去找詛咒之地的血法師德拉吉亞。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2586 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2586,'zhTW','厚甲蠍鹽','你還活著！這真是個好訊息。我猜你回來是想要更多的厚甲蠍鹽吧？$B$B很好，$N，那麼，你再回到詛咒之地去，幫我弄三個厚甲蠍螯、兩個禿鷲的砂囊和一片詛咒之地的野豬肺回來吧。','收集3個厚甲蠍螯、2個禿鷲的砂囊和1片詛咒之地的野豬肺，把它們血法師德拉吉亞。','','去找詛咒之地的血法師德拉吉亞。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2601 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2601,'zhTW','石化蜥蜴的大腦','這塊荒地上到處都是紅石蜥蜴，$N。這些蜥蜴的族群比這裡的其它任何生物都要興旺。$B$B我曾經在遠處觀察過它們的捕獵和其它日常活動——這些野獸表現出了某種思考過程，它們的智商甚至比某些人型生物還要高。$B$B我得研究一下他們的腦子！$B$B給我找十顆蜥蜴的大腦來，$N。還有，你必須再找兩個禿鷲的砂囊，否則我就無法完成藥物的配製。','收集10顆石化蜥蜴的大腦和2個禿鷲的砂囊，把它們交給血法師萊諾雷。','','去找詛咒之地的血法師萊諾雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2602 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2602,'zhTW','清晰的思想','藥效這麼快就沒了？看來我還有更多的研究要做！$B$B哦，當然，條件不變，$N。回到詛咒之地去，給我弄十顆石化蜥蜴的大腦和兩個禿鷲的胃囊來。','收集10顆石化蜥蜴的大腦和2個禿鷲的砂囊，把它們交給血法師萊諾雷。','','去找詛咒之地的血法師萊諾雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2603 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2603,'zhTW','禿鷲的活力','死亡在這片被詛咒的土地上長出了翅膀，$c。我曾親眼目睹那些禿鷲將探險者的屍體狼吞虎嚥地吃掉——有時它們甚至會吃下攜帶著致命疾病的屍體。它們身體內部的系統竟然能夠抵禦席捲了這片土地的瘟疫，這的確令我感到十分驚奇。$B$B請幫助我進行研究，$N！我需要禿鷲的砂囊，還需要兩塊彎牙土狼的顎骨作為原料。$B$B我會和你五五分成的。','收集10個禿鷲的砂囊和2塊彎牙土狼的顎骨，把它們交給血法師萊諾雷。','','去找詛咒之地的血法師萊諾雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2604 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2604,'zhTW','精神矍鑠','我看到你體內的火焰已經漸漸熄滅，那就是說，藥效只持續了一個小時？$B$B如果你還需要更多砂囊口香糖，就給我弄更多的砂囊來。在詛咒之地中收集十個砂囊和兩塊顎骨之後再回來。','收集10個禿鷲的砂囊和2塊彎牙土狼的顎骨，把它們交給血法師萊諾雷。','','去找詛咒之地的血法師萊諾雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2605 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2605,'zhTW','口渴的地精','住在大沙漠裡真是活受罪！我都要被烤乾了。$B$B不過我有個主意。聽說有一種被稱作露水收集者的生物就在西南方活動……它們有一種特殊腺體，可以用來儲藏水分。$B$B如果能得到這種腺體，我就可以暢飲一頓，至少滋潤滋潤我的嘴唇！你能幫幫我嗎，$N？$B$B找到有一大片仙人掌的地方，$N，露水收集者常在那裡出沒。','找到1個飽滿的露水腺，把它交給加基森的馬林·諾格弗格。','','去塔納利斯找加基森的馬林·諾格弗格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2606 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2606,'zhTW','好味道','呸！這個東西真難吃！這個主意也不過如此嘛……$B$B等等，你說什麼？哦，我知道，我知道，你認為我不該就這麼放棄它。那麼，好吧。$B$B對了，我有個主意！一個妙極了的主意！去和我朋友斯普琳科談談吧——她是個出色的廚師。告訴她我們想做什麼，還有我們想要知道加點什麼才能把讓人這東西嚥下去。$B$B我的意思是，如果它這麼難吃的話，總得讓它有些讓人興奮的東西才行……可是我現在就是感覺不到。','馬林·諾格弗格讓你與加基森的斯普琳科談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2607 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2607, 'zhTW', '贊吉爾之觸', '看樣子你帶來的消息比我想像的還要多。這的確是一個奇怪的轉捩點，$N。解藥?嗯……到地窖裡去跟道克·米希匹克斯談談吧─他也許能提供點幫助。', '到兵營的地窖裡去和道克·米希匹克斯談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2608 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2608,'zhTW','贊吉爾之觸','哦，天哪，你看起來就像死人一樣。糾正一下─我見過死人，你看起來比死人還要糟，簡直像是死了又死!$B$B哈哈!諾拉姆，你聽見了吧?把它記下來!$B$B*咳嗽*嗯，好吧。為了幫助你，我得先給你抽點血。別擔心，只有前幾次抽血會有點疼……大概前五十次吧……準備好了之後就躺下(使用/lay指令)， $N 。','用/lay指令躺下，接受道克·米希匹克斯的治療。如果他找不到病因，就找不到治療的方法。','診斷完成','去找暴風城的道克·米希匹克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2609 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2609,'zhTW','贊吉爾之觸','我們達成了共識， $N ，你得的是「伊提斯綜合症」。$B$B幸運的是，我這裡有醫治伊提斯綜合症的藥方。$B$B我需要些東西:一束普通野花、一隻鉛瓶，一根青銅管，最後還要一卷淡綠色絲線。奧·艾瑪在「最好的線團」那家店裡給我留了一卷這樣的線，就在運河區沿岸。$B$B趕緊出發吧， $N ，記住在你的病痊癒之前不要接觸任何人。哦，還有，蒙特高莫醫生說你該洗個澡了─他說的，不是我說的。','給道克·米希匹克斯帶去一束普通野花、一隻鉛瓶，一根青銅管，最後還要一卷淡綠色絲線。伊提斯綜合症可不會不治而愈，年輕的小姐。','','去暴風城找英雄谷的道克·米希匹克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2621 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2621,'zhTW','悔恨的戰士','遺憾，我現在只有遺憾。一個錯誤的決定造成了這麼可怕的結果。我真應該留在那兒等候命令。也許它可以告訴我們，在那個該死的地方有什麼可怕的事情在等著我們！也許它是要將我們調到別的地方去？歸根結底還是我的錯，都是我的錯。$B$B所以我現在就站在這兒，等候命令。我必須瞭解情況，必須拿到那些命令。$B$B傳令官魯爾格駐紮在斯通納德，去找他，查明那封命令現在到底在哪裡。','與斯通納德的分隊指揮官魯爾格談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2622 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2622,'zhTW','丟失的命令','命令？你怎麼能向我要酋長的那封命令？$B$B你是什麼意思，$N？我當然派人把命令送了出去！我派去送信的士兵被魚人伏擊，損失慘重，只有本戈爾活下來——如果那還算活著的話。他現在幾乎不能說話，更不要說走路了，他只能靠管子餵食，奄奄一息。如果你想知道那封命令出了什麼事，就去和他談談，他肯定就在附近什麼地方……還有，這裡到處都是危險的生物，你一定要小心一點。','與本戈爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2623 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2623,'zhTW','沼澤空談者','分隊指揮官下達了命令。我們接……接到了命令。在去詛咒之地的路上，被伏擊了。$B$B魚人……很多魚人……其中一個叫沼澤空談者的魚人，從我手上搶走了命令，然後……長矛插入了我的頭骨。它應該就在東邊……山洞……$B$B<本戈爾昏死了過去。>','取回酋長的命令，把它們還給部落英雄的靈魂。','','去悲傷沼澤斷矛路口找部落英雄的靈魂。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2641 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2641,'zhTW','斯普琳科的秘密佐料','在我還小的時侯，我姐姐包攬了所有燒飯的活，那簡直是糟透了！她做的有些東西簡直讓我無法忍受——直到我發現了一種被我稱作“秘密佐料”的東西，只要加上一點……嘖嘖！味道好極了！$B$B你問那是什麼東西？嗯，是一種被稱作紫色水生菇的蘑菇。如果你要我把這個嚐起來像拖把一樣的東西變成可以下嚥的食品，那麼我建議你去一趟辛特蘭，到那裡去找一個小湖泊。$B$B哦，記住了，紫色水生菇只有在水下才能找到。','加基森的斯普琳科要你去給她找到一顆紫色水生菇。','','去塔納利斯找加基森的斯普琳科。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2661 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2661,'zhTW','給馬林的粉末','這是紫色粉末，$N，把它交給馬林，告訴他，他欠我一個人情！','斯普琳科讓你把紫色粉末交給加基森的馬林·諾格弗格。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2662 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2662,'zhTW','諾格弗格藥劑','現在，把這些粉末和露水混合在一起。$B$B等會兒再回來找我……那時我應該已經完成效力驚人的諾格弗格藥劑了！','馬林·諾格弗格讓你在他製成藥劑之後再去找他。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2681 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2681,'zhTW','禁錮我們的石頭','要擊敗拉瑟萊克和他的手下，只靠你一個是不夠的。$B$B召集一隊勇士，讓我的同伴擺脫永恆的折磨吧！你要打碎十八塊石頭。$B$B努力戰鬥吧，$N。','解救九個拉瑟萊克的僕從、三個瑟溫妮的僕從、三個奧利斯塔的僕從和三個戈洛爾的僕從。完成任務後，回到部落英雄的靈魂這裡。','','去悲傷沼澤斷矛路口找部落英雄的靈魂。','解放拉瑟萊克的僕從','解放戈洛爾的僕從','解放奧利斯塔的僕從','解放瑟溫妮的僕從',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2701 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2701,'zhTW','古代英雄','請把這些古老的遺物拿走吧，我們不再需要這些東西了。$B$B希望在你和燃燒軍團的戰鬥中，它們能對你有所幫助。','開啟箱子，取走你的酬勞。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2702 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2702,'zhTW','古代英雄','你用你高尚的行動和英勇的表現為我贏得了榮譽，$N。$B$B你也為他們贏得了榮譽……','和桑德·裂蹄談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2721 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2721,'zhTW','基利斯','你已完成了一次冒險，現在又有新的冒險在等著你，$N。$B$B我有個手下至今下落不明，他應該在詛咒之地的某個地方，我說的就是基利斯中尉。$B$B我告訴過你，我和他當時被奧利斯塔囚禁起來嚴刑拷打，可憐的基利斯……他的意志力變得越來越薄弱。在我的牢房裡都能聽到他受刑的聲音，他的慘叫在山洞裡迴盪。那是我最後一次聽見基利斯的聲音。','找到基利斯的下落。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2741 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2741,'zhTW','超級測蛋器','','','','去找塔納利斯的測蛋器。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2742 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2742,'zhTW','林吉被困住了！','嘿，那邊的$r！$B$B請你幫林吉逃出去，我知道像你這樣的$r不喜歡林吉，不過林吉求你了！我要逃出去！$B$B如果$r幫林吉逃出這裡，$r就可以得到一些好東西……$B$B林吉在望海崖藏了個大秘密。','護送林吉逃出奎爾丹尼小屋，然後在望海崖找到他藏起來的東西。','護送林吉到安全地區','去辛特蘭找望海崖的林吉的秘密。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2743 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2743,'zhTW','黑暗籠罩','我們都別拐彎抹角了，$c，我的時間有限。$B$B你必須摧毀保護惡魔之王拉瑟萊克的三大魔頭的勢力。這個任務可不像解救一個被詛咒的靈魂那樣簡單。$B$B<基利斯咧開嘴大笑著>。$B$B你要知道，拉瑟萊克的三個手下各自戴著一件由拉瑟萊克特製的護符的三分之一。有了這個護符，你才能召喚那個惡魔。$B$B回去見特雷博，告訴他需要什麼東西才能召喚拉瑟萊克，他會給你進一步的指示。','回去見部落英雄的靈魂，將你的發現告訴他。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2744 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2744,'zhTW','惡魔獵手','那三個魔王受到拉瑟萊克的保護。$B$B為了讓他們忠誠地為他效力，拉瑟萊克使他們在詛咒之地可以使用幾乎無限的力量。他們佩帶的護符和他們的命運聯絡在一起，並使他們變得不老不死。只要他們待在詛咒之地，你就沒法殺了他們，他們的生命力可以維持到世界末日。$B$B我認識一個也許可以幫助你的朋友，$N。到艾薩拉地區的小島上去找惡魔獵手洛拉姆斯·薩里比迪斯談談吧。','與艾薩拉的洛拉姆斯·薩里比迪斯談一談。','與洛拉姆斯會面','去艾薩拉找風暴海灣的洛拉姆斯·薩里比迪斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2745 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2745, 'zhTW', '潛入城堡', '嗯，真是個有趣的故事，而且我們還要認真對待它。好吧，我可以幫你，但如果你想成功的話，就必須採用某種……正義而非法的手段。我們要趕快解決萊斯科瓦和馬爾松，你認為你能勝任嗎?你必須下定決心，到城堡裡去找我的一個老朋友，一個名叫泰里恩的地精。幾星期來他一直在監視著萊斯科瓦，他可以幫你解決這件事。', '與暴風城堡的泰里恩談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2746 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2746, 'zhTW', '必備物品', '提亞斯要加快執行計畫了嗎?好吧，我們可以做到，不過我還沒準備好。你知道，我要做的是最困難的部分，而你是負責動手的人，明白嗎?很好。$B$B我要讓你先幫我準備些東西，這樣我就可以對間諜機器人進行偽裝，讓它安全地騙過那些守衛。$B$B給我帶回一些絲綢和幾隻蘋果來。絲綢你自己去找，不過城外那個克拉拉的小農場上有非常合適的蘋果。', '將3塊絲綢和2顆克拉拉的新鮮蘋果交給暴風城的泰里恩。', '', '去找暴風城的泰里恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2747 AND `locale` = 'zhTW';
