INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2857,'zhTW','蠻皮頭盔','蠻皮頭盔可以為你的頭部提供極好的保護，與此同時，它也具有相當的舒適性。和所有的蠻皮護甲一樣，製作頭盔時使用的野葡萄會使它產生一種強大的隨機魔法效果。對於穿著皮甲的人來說，這東西可是非常不錯的！$B$B想要得到這頂頭盔的圖樣的話，就給我帶兩件夜色外套、兩條夜色頭巾和一株野葡萄來。完成這個任務之後，圖樣就是你的了！','給莫沙徹營地的杉多爾·迅蹄帶去2件夜色外套、2條夜色頭巾和1株野葡萄。','','去找菲拉斯的杉多爾·迅蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2858 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2858,'zhTW','蠻皮戰靴','你現在已經學到了很多東西，$N，但你仍有更多的東西要學習。現在我們來談談蠻皮戰靴，它是這一套裝備的基石。$B$B這種靴子舒適合腳，可以讓你的雙腳在長途跋涉之後仍然輕鬆自如。柔軟的鞋底對於那些喜歡悄悄行動的人來說再合適不過了。$B$B如果你想要得到它的圖樣，就給我拿兩條夜色短褲和兩雙夜色長靴來。另外我還需要兩株野葡萄……只有一株的話可不夠。拿到以上這些東西之後，就把它們交給我。','給莫沙徹營地的杉多爾·迅蹄帶去2條夜色短褲、2雙夜色長靴和2株野葡萄。','','去找菲拉斯的杉多爾·迅蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2859 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2859,'zhTW','蠻皮護腿','看來你已經準備好學習更加複雜的課程了，$N。蠻皮護脛是最堅硬和強大的皮製系列裝備中的一樣。野獸系列皮裝備讓你的胸部，大腿，小腿和其他致命的部位都被保護起來。再加上野葡萄所起的輔助作用，擁有這種裝備的冒險者一定會永遠感謝你的。$B$B如果你想要得到這個圖樣的話，帶給我兩頂龜鱗頭盔，兩付龜鱗護腕和兩株野葡萄。','給莫沙徹營地的杉多爾·迅蹄帶去2頂龜鱗頭盔、2副龜鱗護腕和2株野葡萄。','','去找菲拉斯的杉多爾·迅蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2860 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2860,'zhTW','蠻皮護甲大師','$N，我能教你的你已經全部都學會了。蠻皮護甲只剩下一種式樣你還沒有學會了。我不會要求你為最後的式樣無謂地浪費時間和精力，你可以直接得到它，還有一些……但我不能自己傳授給你。我的老師，就是帶我進入這一行的人，她會教你該怎麼做的。$B$B帶這封信給猶納；她在雷霆崖教授皮革製作。給她看這封信，讓她像我一樣地認同你。','將杉多爾的信交給雷霆崖的制皮大師猶納。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2861 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2861, 'zhTW', '塔貝薩的任務', '據說有個名叫塔貝薩的法師想要某個祖爾法拉克食人妖的命。如果你去找塔貝薩的話，她會讓你知道詳情的。別忘了帶幾個夥伴，$N。如果塔貝薩真的讓你去祖爾法拉克的話，你最好不要獨自前往。塔貝薩的小屋就在塵泥沼澤裡，準確地說，是在塞拉摩的西邊，石槌廢墟的北邊。', '與塵泥沼澤的塔貝薩談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2862 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2862,'zhTW','與豺狼人開戰','豺狼人……它們現在不再只是一個小麻煩了，它們已經對我們形成了巨大的威脅！這些豺狼人是不是菲拉斯的原住民已經不重要了；如果我們無法有效地對抗它們，那我們早晚都會被趕出這個地區的。$B$B豺狼人最近對營地的攻勢愈演愈烈，因此我們需要你的幫助來削弱它們的數量。帶給我十份豺狼人的鬃毛，我會為你付出的努力而給予優厚的報酬。$B$B趕快出發吧！','將10份木爪豺狼人的鬃毛交給莫沙徹營地的哈杜肯·迅蹄。','','去菲拉斯找莫沙徹營地的哈杜肯·迅蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2863 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2863,'zhTW','突然襲擊','我們計劃在很短的時間裡拿下豺狼人的領導者——按他們自己的說法是突擊隊員。如果我們順利地執行了這個計劃……不僅他們的內部會出現混亂，而且這也會向他們愚蠢的腦袋傳達一個資訊，那就是我們有能力而且必將消滅他們！$B$B我想讓你成為傳達這個資訊的使者，你必須在一小時內消滅五個突擊隊員，否則我們還會處於這種僵局中。','在1個小時內殺死5個木爪突擊隊員，並向哈杜肯·迅蹄彙報。','','去菲拉斯找莫沙徹營地的哈杜肯·迅蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2864 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2864, 'zhTW', '特蘭雷克', '我的兄弟特蘭雷克現在顯然處於困境中。幾個星期之前他曾經向我承諾會給我一批聖甲蟲的殼，但是至今為止我還沒有收到。他是我的兄弟，所以我可不想派人去加基森砸他的場子。你能幫我去問問特蘭雷克到底是怎麼回事嗎?在我真的發飆之前他最好快點把貨給我送來。加基森就在卡林多大陸上的塔納利斯沙漠北部。', '與加基森的特蘭雷克談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2865 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2865,'zhTW','聖甲蟲的殼','塔納利斯這裡的聖甲蟲的殼都很硬！硬得足可以給好多東西當建築材料，好多東西！$B$B事實上，因為那些殼都太有用了……聖甲蟲已經被獵殺得近乎滅絕了！$B$B我知道哪裡有更多的聖甲蟲，如果你保證會給我弄些殼來，我就告訴你它們在哪裡。你保證嗎？$B$B好吧，祖爾法拉克里面有許多聖甲蟲，我想巨魔們並不因為想要那些殼而獵殺它們。$B$B但你可以！到祖爾法拉克去給我弄些完好無損的殼回來！','給加基森的特蘭雷克帶去5個完整的聖甲蟲殼。','','去找塔納利斯的特蘭雷克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2866 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2866,'zhTW','索蘭索爾廢墟','在我們的南邊就是索蘭索爾廢墟，那個地區的歷史相當悠久。我們探索過那個遺蹟，沒有發現什麼特別值得注意的東西，所以我們就離開了。$B$B最近，憎世納迦佔據了那片遺蹟，而且他們的數量已經多到了讓我們不得不警惕的程度。一開始我們認為那些納迦是準備對我們發起攻擊，雖然這種可能性現在依然存在，但我們覺得他們可能是有什麼別的目的。$B$B現在就到那片廢墟去檢視一番吧，祝你好運，$n。','探索索蘭索爾廢墟，並調查納迦在那個地區的情況。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2867 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2867,'zhTW','返回羽月要塞','在索蘭索爾廢墟的心臟地帶發現了奇怪的瞭望臺之後，你覺得應該馬上回到羽月要塞去向珊蒂斯·羽月彙報這個發現。','向羽月要塞的珊蒂斯·羽月彙報你的發現。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2868 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2868,'zhTW','暫無內容','把這個壞小子塞到Sunken Temple的巨魔墓裡，讓他吃吃苦頭。','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2869 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2869,'zhTW','憎世納迦之戰','我們認為，無論納迦想要幹什麼，他們最終的目的無非是完全佔據這座島嶼，由此我們制定了相應的行動計劃。我們要儘早採取攻擊行動來消除這種威脅，否則就可能全盤皆輸。$B$B給我帶來十塊完整的憎世納迦的鱗片——你應該知道如何獲得這東西。這樣一來，納迦在索爾多島上的力量就被大大削弱了，這對我們是非常有利的。','收集10塊憎世納迦的鱗片，把它們交給羽月要塞的拉託尼庫斯·月矛。','','去菲拉斯找羽月要塞的拉託尼庫斯·月矛。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2870 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2870,'zhTW','擊敗沙爾扎魯','$n，新的偵查報告讓我們對納迦部隊的組成有了一個更清晰的概念。納迦的皇室成員在他們的部隊中具有最高的權威性。$B$B皇室成員中的沙爾扎魯是個極端殘酷的納迦，偵查報告表明最近他在南部的遺蹟中發現了一塊奇怪的古代遺物，那個地方就在恐怖之島那裡。$B$B你的任務就是結果他，然後把那塊遺物給我帶回來進行研究。','消滅沙爾扎魯，然後把神秘遺物交給羽月要塞的拉託尼庫斯·月矛。','','去菲拉斯找羽月要塞的拉託尼庫斯·月矛。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2871 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2871,'zhTW','遞送遺物','如果你能幫我將這個東西送給我的妻子維斯提亞，那我會非常感激的。她不僅是我們這裡的女祭司，也會是你所見過的最博學的學者之一。我即使抓破頭皮也搞不清楚這個東西到底是什麼，可我的妻子不同，如果世界上有人能知道這東西是什麼，那無疑就是她了……我們也迫切地需要知道真相！$B$B拜託了，$n。','將神秘遺物交給羽月要塞的維斯提亞·月矛。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2872 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2872, 'zhTW', '斯杜雷的債務', '我的老朋友欠我一瓶特殊的朗姆酒。他在塔納利斯沙漠的熱砂港裡經營著一家酒吧，他向我保證說，那裡的朗姆酒絕對比藏寶海灣的任何酒都要香醇，還說如果我喝了他的酒不滿意的話，那他就會雙倍奉還他欠我的錢!好吧，我想他現在已經不像他上次說這話的時候那麼自信了，他害怕給我嘗他的朗姆酒了。但是我還是想繼續這個賭注，那麼你就替我去和他談談吧……', '與熱砂港的斯杜雷談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2873 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2873,'zhTW','斯杜雷的貨物','我欠藏寶海灣的“海狼”馬克基雷一些朗姆酒，那是打賭輸的，但我現在一瓶朗姆酒都沒有了！科爾戈船長偷了我最後一船貨，他把它們藏在南邊的那個戒備森嚴的海盜鎮裡。$B$B如果你能找到我的那批朗姆酒並把它們給我拿回來的話，那我就可以向馬克基雷證明，藏寶海灣的那些酒跟我的朗姆酒比起來只能被稱作垃圾！','將斯杜雷的貨物交給熱砂港的斯杜雷。','','去塔納利斯找熱砂港的斯杜雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2874 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2874,'zhTW','給馬克基雷的貨物','再次感謝你的幫助，$N。這裡有一瓶熱砂港朗姆酒。把它交給馬克基雷，這樣他就可以拋棄藏寶海灣烈酒，改喝熱砂港朗姆酒了！','將斯杜雷的瓶子交給藏寶海灣的“海狼”馬克基雷。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2875 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2875,'zhTW','通緝：安德雷·費爾比德','可惡的海盜安德雷·費爾比德因對熱砂港和加基森所犯的罪行正被通緝。$B$B根據政府討論所釋出的決議，任何閱讀這則通緝令的人有權在逮捕安德雷和他的同黨過程中採取可能致其死亡的手段。$B$B進一步的決議表明，如在審訊期間，安德雷死了或病了，他的人頭可以作為代替品，將它交給安全主管吉羅姆·比格維茲仍將使這份通緝令生效。','將安德雷的頭顱交給熱砂港的安全主管吉羅姆·比格維茲。','','去塔納利斯找熱砂港的安全主管吉羅姆·比格維茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2876 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2876,'zhTW','船運時刻表','這卷軸上面記載著熱砂港和藏寶灣之間的船運時刻表，包括過去和未來計劃中的船運批次和船名，一些船的旅程旁有個大大的紅叉記號，剩下的旁邊有類似“華麗的戰利品”和“堅固的戰艦”之類的字樣。$B$B熱砂港那裡的人一定非常想看看這個檔案。','把船運時刻表交給熱砂港的某個官員。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2877 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2877,'zhTW','清理隱匿石','比起那些鐵爐堡的兄弟們來，我們蠻錘部族對於過去曾發生過的事情有著更加深刻的記憶。如果你想在這裡交朋友的話，那麼你就要證明給我們看！$B$B部落的蠻子們從隱匿石一帶撤了出去，現在那裡滿地都是淤泥怪。我們想要佔領那個地區，不過首先我們要找些人來幫我們清理一下惱人的淤泥怪。$B$B這就是你要做的事情了！到那邊去幹掉十個綠色淤泥怪和十個玉石軟泥怪，然後回到這裡來向我報告。快出發吧！','殺掉10個綠色淤泥怪和10個玉石軟泥怪，然後回到鷹巢山向弗拉加爾報告。','','去辛特蘭找鷹巢山的弗拉加爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2878 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2878,'zhTW','被腐化的輕歌花','','','','去找費伍德森林的被腐化的輕歌花。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2879 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2879,'zhTW','艾奎尼克斯法杖','看來這根法杖可能就是艾奎尼克斯法杖了。它事實上是把鑰匙，你可以用它開啟位於北方廢墟中的艾奎尼克斯石碑。$B$B找到仍在那片廢墟中燃燒的四團烈火：薩姆哈之焰、拜爾坦之焰、伊姆貝爾之焰和萊哈薩之焰。從這些火焰那裡採集它們的精華。然後在艾奎尼克斯石碑旁使用這些精華，把它們的能量注入法杖。如果這真的是艾奎尼克斯法杖的話，你就可以開啟石碑，並得到存放在裡面的古物。','給特洛亞斯的法杖注入能量，並找到艾奎尼克斯石碑。','','去菲拉斯找雙塔山的艾奎尼克斯石碑。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2880 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2880,'zhTW','巨魔部族項鍊','直接說吧，$c——我們不屬於聯盟！蠻錘部族是獨立的，我們依靠自己所做的事情來證明自己的價值，不像那些只會說廢話的傢伙一樣，用閒聊來掩飾自己什麼都不想做的態度！$B$B如果你要和我們作朋友，那麼首先向我們證明你的價值！那些遍佈辛特蘭的巨魔有時會帶著他們部族的項鍊。給我帶五條項鍊過來作為友好的證明吧！','給鷹巢山的弗拉加爾帶去5條巨魔部族項鍊。','','去辛特蘭找鷹巢山的弗拉加爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2881 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2881,'zhTW','巨魔部族項鍊','','','','去找辛特蘭的弗拉加爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2882 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2882,'zhTW','科爾戈的黃金','這張地圖上畫著一條對著南方的海灘，圖下面用優雅的字型寫著……$B$B$B熱砂港南邊$B家的南邊$B找到骨頭，旗子和旗杆$B如果你夠膽，就去挖挖看$B挖挖看啊，科爾戈的金子光燦燦！$B開箱需鑰匙，鑰匙你會看見$B你面對的要用血來做交換。','找到科爾戈的黃金！','','去找海盜的寶藏！。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2902 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2902,'zhTW','調查木爪嶺','豺狼人不是菲拉斯最具威脅的勢力，但它們最近的活動毫無疑問是有些具體戰略的。如果我們能找到它們的計劃，那麼我們就能知道究竟是什麼讓它們變得如此精明。$B$B我要你回到木爪嶺去，尋找任何有可能是它們的戰鬥計劃的東西。他們一定有些這樣的東西，因為它們的攻擊行動太協調了，沒有一個像樣的戰鬥計劃是不可能進行的。找到那東西，然後再回到我這裡來。','在莫沙徹營地以南的豺狼人營地中尋找豺狼人的戰鬥計劃。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2903 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2903,'zhTW','作戰計劃','既然我們已經發現了豺狼人的作戰計劃，接下來要做的就是把計劃交給莫沙徹營地的哈杜肯·迅蹄。他或者那兒的其他什麼人也許可以進一步弄清楚豺狼人到底想要做什麼。','把木爪豺狼人的作戰計劃交給莫沙徹營地的哈杜肯·迅蹄。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2904 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2904,'zhTW','一團混亂','<克努比呻吟著。>發……發生什麼事了?$B$B我只記得自己被一隊黑鐵矮人抓住了，他們揍了我一頓，把我跟這些醜陋的穴居怪扔在一塊兒。$B$B快救我出去， $N !$B$B我有個計畫:把我帶到出口，如果我們能活著走出去的話，你就到藏寶海灣去，告訴斯庫提我去了棘齒城，然後警告廷克維斯，黑鐵矮人準備製造超強的鑽探設備。$B$B讓我們開始吧!','將克努比護送到發條小徑的出口，然後向藏寶海灣的斯庫提彙報。','營救克努比','去荊棘谷找藏寶海灣的斯庫提。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2922 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2922,'zhTW','拯救尖端機器人!','當我們摯愛的諾姆瑞根城淪陷時，我可憐的發明─尖端機器人─受到了某種致命的打擊。它原本包含了很多精巧的設計，並且儲存了大量的資訊，憑藉這些，它無數次地幫助了我和我的同事，但現在它的正電子腦被極化，變成了負電子腦……尖端機器人的行為已經變得完全異常了。它像個瘋子似的在諾姆瑞根裡咆哮!$B$B也許我們仍然可以挽救它，如果你能找回尖端機器人的記憶體核心並把它交給我，那麼我就能找到故障的原因，然後把我可憐的尖端機器人修好。$B$B','將尖端機器人的記憶體核心交給鐵爐堡的技工大師歐沃斯巴克。','','去鐵爐堡找侏儒區的工匠大師歐沃斯巴克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2923 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2923, 'zhTW', '技工大師歐沃斯巴克', '技工大師歐沃斯巴克正在為他發明的尖端機器人的命運感到沮喪。我記得尖端機器人對地精來說是一種很友好的輔助工具，但歐沃斯巴克告訴我，它出了故障。我很難過，不過如果運氣不錯的話，也許他還可以修好尖端機器人!去跟鐵爐堡地精區的技工大師歐沃斯巴克談談吧，看到有你這樣的$c想要幫助他，他會很高興的。', '與鐵爐堡的技工大師歐沃斯巴克談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2924 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2924,'zhTW','基礎模組','有一種通用型的機械部件─基礎模組─對於諾姆瑞根的技工和鐵匠來說都非常重要，不過在我們大舉逃出諾姆瑞根的時候，誰也沒想起要把這些東西帶上!我手頭上的工作需要大量這種部件。$B$B請去諾姆瑞根給我拿一些基礎模組回來，它們就裝在城市深處的機械儲存櫃裡。$B$B謝謝你， $N ，請儘快出發吧!','收集12個基礎模組，把它們交給鐵爐堡的科勞莫特·鋼尺。','','去鐵爐堡找侏儒區的科羅莫特·鋼尺。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2925 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2925, 'zhTW', '幫助科勞莫特', '我的地精朋友科勞莫特·鋼尺從鐵爐堡給我捎了個信過來，說是要我找人去完成一項很危險但也很重要的任務:潛入諾姆瑞根。現在這座壯觀的地精城市裡到處都是瘋狂的地精和他們的機械裝置。我必須待在這裡，但無法幫助我的朋友讓我感到很心痛。如果你能替我去的話，我會很感謝你的。你可以在鐵爐堡的地精區裡找到科勞莫特。', '與鐵爐堡的科勞莫特·鋼尺談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2926 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2926,'zhTW','諾恩','事故後，諾恩想的說的都離不開兩個主題:如何將穴居怪趕出諾姆瑞根，以及如何為席捲諾姆瑞根的瘟疫找到治療的方法。$B$B幸運的是，拉茲和我已經快要研究出一種治療方法了─要不然就是一種很強勁的朗姆酒的配方。我們要試過才知道!當然，為了檢驗我們的理論是否成立，我們需要一些東西，準確地說，是諾姆瑞根城裡那些穴居怪身上的輻射塵。用這個小瓶子裝一些泛著綠光的輻射塵，然後把它帶回來!','用空著的鉛之瓶對著輻射入侵者或者輻射掠取者，從它們身上收集放射塵。瓶子裝滿之後，把它交給卡拉諾斯的奧齊·電環。','','去丹莫洛找卡拉諾斯的奧齊·電環。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2927 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2927, 'zhTW', '災難之後', '你不會認為我生來就是是禿子吧?事實並不是這樣的，<先生/女士>!諾姆瑞根的放射性洩露導致了我悲劇性的脫髮。在那之前，我有著整個艾澤拉斯世界獨一無二的地精式飛機頭!<諾恩一邊說一邊揮舞著拳頭>那些該死的穴居怪─他們都該死!!或許現在還不晚，$N。我們也許仍然可以挽回局勢─我說的是這座城市!去跟卡拉諾斯的奧齊·電環談談吧，他和他夥伴拉茲正在想辦法。', '與卡拉諾斯的奧齊·電環談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2928 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2928,'zhTW','陀螺式挖掘機','太糟糕了， $N 。我們沒有足夠的零件讓我們的陀螺式挖掘機部隊進入丹莫洛。$B$B我們需要的是零件， $N ，更多的零件。說到尋找零件，難道還有比諾姆瑞根更好的地方嗎?我聽說那裡的機器人像牧區的牛似的到處遊蕩。$B$B我要你做的就是到諾姆瑞根去，把這些機器人拆開，拿出它們的內部裝置。給我弄兩打來就夠了。','收集24副機械內膽，把它們交給暴風城的舒尼。','','去暴風城的矮人區找沉默的舒尼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2929 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2929,'zhTW','大叛徒','我以前曾經非常信任瑟瑪普拉格，我從未想過他會背叛我和所有地精同胞。他為什麼要背叛我們?為了權力?為了金錢?這些東西只要假以時日他都可以擁有。現在我們背井離鄉，那個瘋子掌握了政權，成了個什麼都沒有的國王……$B$B我們要奪回諾姆瑞根， $N 。在奪回自己的城市之前，我們絕不停止努力。如果你想加入我們，就先去完成一個簡單的任務:殺了那個叛徒，機電師瑟瑪普拉格。','到諾姆瑞根去殺掉機電師瑟瑪普拉格。完成任務之後向大工匠梅卡托克報告。','','去鐵爐堡找侏儒區的大工匠梅卡托克。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2930 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2930,'zhTW','搶救資料','在逃離諾姆瑞根的時候，我們留下了太多的資料!非常重要的資料!$B$B我需要一張稜彩穿孔卡片，你可以從諾姆瑞根城裡的矩陣式打孔電腦3005-D型裡找到這種卡片。不過糟糕的是，要得到它的話，你就必須先接近低級安全終端，也就是A型，B型和C型電腦，然後用不同的穿孔卡片開啟它們，從白色的卡片開始……而且我們把所有的穿孔卡片都留在城裡了。$B$B這真是一場災難!你能幫忙嗎?','將稜彩穿孔卡片交給鐵爐堡的大技師卡斯派普。','','去鐵爐堡找侏儒區的大機械師卡斯派普。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2931 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2931, 'zhTW', '卡斯派普的任務', '鐵爐堡的大技師卡斯派普正在徵集冒險者!他正在組織一個冒險小隊，要到諾姆瑞根去執行一項極度機密和重要的資料收集任務。卡斯派普也許不是鍊金術、魔法和工程學協會的一員，不過他也算是個很聰明的地精，如果是他認為這是件很重要的事情，那麼根據我的計算，這件事有百分之八十四的可能性是確實很重要的!這個可能性可不小!', '與鐵爐堡的大技師卡斯派普談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2932 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2932,'zhTW','可怕的訊息','枯木巨魔原來是部落的盟友，但他們現在背叛了索爾……他們要為此受到懲罰！$B$B來，拿起我的長矛，到北面的辛特蘭去，那個地方就在塔倫米爾的東北方向。$B$B追捕那裡的枯木巨魔，收集他們的頭皮，把我的長矛插在他們的某個村莊中，比如西利瓦薩或者祖瓦沙。$B$B讓他們知道，背叛部落，遲早要還的！','在辛特蘭收集枯木巨魔的頭皮，把它們串在尼姆布亞之矛上。將尼姆布亞的長矛插在辛特蘭的某個枯木巨魔村莊中，然後回到荊棘谷的尼姆布亞那裡。','傳達可怕的資訊。','去荊棘谷找格羅姆高營地的尼姆布亞。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2933 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2933,'zhTW','毒液瓶','這些瓶子裡裝有綠色的毒液。$B$B由村莊中這種瓶子的數量來看，枯木巨魔一定很重視這些東西。或許塔倫米爾的藥劑師會對這些毒液的樣本感興趣。','將毒藥瓶交給塔倫米爾的某個藥劑師。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2934 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2934,'zhTW','完好無損的毒囊','我必須要有一個你帶來的那種毒液的新鮮樣本才能進行研究。生產毒液的蜘蛛一定生活在辛特蘭一帶——獵捕這些蜘蛛，直到你找到一個完好無損的毒囊，把它給我帶來。巨魔們的沙德拉洛城附近有許多蜘蛛，到那裡去找找吧。$B$B別耽擱了，毒囊一定要非常新鮮才行。','將完好無損的毒囊交給塔倫米爾的藥劑師林度恩。','','去希爾斯布萊德丘陵找塔倫米爾的藥劑師林度恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2935 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2935,'zhTW','請教加德林大師','巢穴守衛的毒液沒有你先前帶來的毒液那麼有威力，它肯定來自不同型別的蜘蛛。$B$B我要那種毒液的新鮮樣本。如果要找到它的出處，那麼你必須與一個很瞭解枯木巨魔的巨魔談一談——我說的是森金村的加德林大師。到杜隆塔爾去找加德林吧。如果運氣好的話，他會知道枯木巨魔是在哪裡找到這種毒液的。','與森金村的加德林大師談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2936 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2936,'zhTW','蜘蛛之神','枯木巨魔崇拜蜘蛛之神，他們從她那裡收集極具威力的毒液。如果你想要毒液，就必須召喚他們的蜘蛛之神！$B$B要召喚她的話，你就必須知道她真正的名字，刻有這個名字的石板被埋藏在一座墓穴中，那墓穴就在塔納利斯沙漠中的巨魔城市祖爾法拉克，由殉教者塞卡守衛著墓穴的入口。$B$B擊敗塞卡，閱讀那塊石板，找到蜘蛛之神的名字。知道了她的名字之後就回到我這裡來。','閱讀塞卡石板，瞭解枯木巨魔的蜘蛛之神的名字，然後回到加德林大師那裡。','找到蜘蛛之神的名字','去杜隆塔爾找森金村的加德林大師。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2937 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2937,'zhTW','召喚沙德拉','拿著這張羊皮紙，在辛特蘭的沙德拉洛祭壇上唸誦羊皮紙上的咒文。這樣就可以召喚蜘蛛之神沙德拉。','在沙德拉洛祭壇上擊敗沙德拉，把它的毒液交給塔倫米爾的藥劑師林度恩。','','去希爾斯布萊德丘陵找塔倫米爾的藥劑師林度恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2938 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2938,'zhTW','送往幽暗城的毒藥','你在枯木巨魔的蜘蛛之神身上採集的毒液真是一個重大的發現！只消一小滴，我就可以殺死足足二十隻兔子。當然，有些兔子很幼小，小得足以放在手掌上，它們對毒藥的抵抗力非常低，但你也不能否認這種毒藥極具威力！$B$B我想要給我的上級——幽暗城鍊金房的大藥劑師法拉尼爾——送去一些樣本，我敢說他也會對此很感興趣的。','將法拉尼爾的包裹交給幽暗城的大藥劑師法拉尼爾。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2939 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2939,'zhTW','尋找知識','雖然遍佈菲拉斯的廢墟和遺蹟可能很危險，但是它們講述了許多曾經發生的事情……$B$B幾天前我在南邊的碎石堆裡搜尋的時候，發現了一個看起來像是根普通法杖的東西。但是，我總覺得事情並不是那麼簡單，安吉拉斯和我在這裡鑽研書籍已經很久了，不過我們沒發現什麼和它相關的資訊。$B$B我在達納蘇斯有一個同事，她能告訴我這是什麼東西，$N。你為什麼不去跟她談談呢？也許她能幫助我們。','與魯瑟蘭村的達蕾恩·輕風談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2940 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2940,'zhTW','菲拉斯的歷史','看起來這本書很久沒有人開啟過了。它的封面破舊而且書頁發黃，但檢查後你會發現這正是特洛亞斯要找的那本書。$B$B你把它撿了起來，但你卻突然意識到，也許應該在借閱之前得到物主的允許。','如果你想借達蕾恩·輕風的書，要先得到她的允許。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2941 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2941,'zhTW','海龜照片','我一生中研究了許多課題，最近我迷上了遍佈辛特蘭海灘地區的鉗嘴龜。我特別想看到一隻名叫加莫里塔的大型鉗嘴龜，本來呢，我想要自己去一趟，但繁重的研究工作讓我不得不留在這裡。如果能搞到一張它的畫像就好了。$B$B把這封信交給塔納利斯的克格爾·曲藤。她為我發明了一種可以快速抓取影象的裝置，我想她把那個東西叫做“快照”……','把信交給塔納利斯的克格爾·曲藤。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2942 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2942,'zhTW','晨光石','石碑中的東西被你拿出來的一瞬間，你突然感到艾奎尼克斯法杖的力量開始衰竭。','將閃光的石頭和艾奎尼克斯法杖交給羽月要塞的特洛亞斯·月風。','','去菲拉斯找羽月要塞的特洛亞斯·月風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2943 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2943,'zhTW','向特洛亞斯回覆','給你，$N。請小心保管我的書。$B$B現在快點出發吧，特洛亞斯正在翹首企盼你的迴歸呢！','把書交給羽月要塞的特洛亞斯·月風。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2944 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2944,'zhTW','超級攝影器FX','先來看看我的發明吧，$N。你所要做的只是將它對準任何一個你想要拍攝的物品，然後按下這個按鈕。$B$B你說的辛特蘭的生物是什麼？加莫里塔？好吧，祝你好運，希望你能找到它。我堅信達蕾恩會對你給她的照片很滿意的。$B$B不說那麼多了，這是給你的超級攝影器。玩得開心點！','用超級攝影器FX給加莫里塔拍張照片，然後把它交給魯瑟蘭村的達蕾恩·輕風。','','去泰達希爾找魯瑟蘭村的達蕾恩·輕風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2945 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2945,'zhTW','髒兮兮的戒指','你在一個黑鐵矮人的屍體上發現了一枚戒指。但要辨認戒指的細節卻很困難，泥土和堅硬的汙垢將它整個包裹了起來，你根本沒法戴上它。你覺得它是用某種珍貴的金屬製成的，似乎還鑲著寶石。$B$B如果你想好好看看這枚戒指的話，就得找些東西把戒指表面的汙垢清理掉。','想方法把髒兮兮的戒指弄乾淨。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2946 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2946, 'zhTW', '拭目以待', '我希望你把這張圓盤拿到奧丹姆的封印之門去。我們……我們不能肯定這樣做會帶來什麼後果。$B$B當然，這聽起來確實很危險，但也有可能什麼都不會發生。也許你要將圓盤放在什麼東西上，也許你只要帶著圓盤，大門就會自己打開。總之，不試一試是不會知道真相的。$B$B等你完成這項任務之後就回到鐵爐堡來，我們還有很多事需要討論。', '將迷你白金圓盤拿到塔納利斯的奧丹姆大門去，找出兩者之間的聯繫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2947 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2947,'zhTW','戒指歸來','開啟由超級清潔器5200型製作的盒子之後，你看到了一枚閃閃發光的戒指！你戴上了戒指，立刻感覺身體中湧動著神奇的力量。$B$B戒指的內側有一個很小的鐵爐堡徽記，旁邊刻著三個字母：“TdK”。$B$B這可能是它以前的主人或是製作者的姓名縮寫。是將這枚戒指留著自己用，還是把它物歸原主，這要由你自己來決定……','你要麼自己留著這枚戒指，要麼就按照戒指內側刻著的名字找到它的主人。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2948 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2948, 'zhTW', '地精的手藝', '聽著，$n，這戒指當然是你的……但是我可以給你做一枚更好的!就像我說的一樣，那種設計實在太簡單了。現在我的技術更加嫺熟了，只要你付我三十個銀幣的費用，我就可以幫你製作一枚新戒指!好吧，事實上還要再加一點點……$B$B我現在手頭很緊，我的所有存貨都用完了。如果你給我一塊銀錠和一塊綠瑪瑙，我就可以讓戒指看起來更加閃亮華貴!$B$B相信我!', '將閃亮的金戒指、1塊銀錠、1塊綠瑪瑙和30個銀幣交給鐵爐堡的塔瓦斯德·基瑟爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2949 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2949,'zhTW','戒指歸來','開啟由超級清潔器5200型製作的盒子之後，你看到了一枚閃閃發光的戒指！你戴上了戒指，立刻感覺身體中湧動著神奇的力量。$B$B戒指的內側有一個很小的鐵爐堡徽記，旁邊刻著三個字母：“TdK”。$B$B這可能是它以前的主人或是製作者的姓名縮寫。是將這枚戒指留著自己用，還是把它物歸原主，這要由你自己來決定……','你要麼自己留著這枚戒指，要麼就按照戒指內側刻著的名字找到它的主人。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2950 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2950,'zhTW','諾格的手藝','不，不，不——我當然不是突然就說這枚戒指是我的。嗯，我通常不這樣做，但你提供的關於黑鐵矮人的情報很有用，所以我會破例為你改造你的戒指，我的手藝絕對比製作這個小東西的傢伙要高超得多。嗯，八成是個侏儒做的……$B$B如果你給我拿來一塊銀錠、一塊綠瑪瑙和三十枚銀幣作為加工費的話，我就可以在戒指中加入白銀和瑪瑙的精華來加強其魔力。怎麼樣，感興趣嗎？','將閃亮的金戒指、1塊銀錠、1塊綠瑪瑙和30個銀幣交給奧格瑪的諾格。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2951 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2951,'zhTW','超級清潔器5200型!','這個裝置屹立於那些竭力保護房間的地精中，裝置上有一塊小金屬牌，上面寫著「超級清潔器5200型」，還有一段文字:$B$B:「污垢和殘渣讓你的東西看起來污穢不堪?超級清潔器5200型會使它重現光芒!將你想要清理的物品放入清潔器中，然後向槽裡投入三枚銀幣。稍候片刻，你的珍寶就會重新變得潔淨而耀眼!」','將髒兮兮的東西放入超級清潔器5200型，記得要用三枚銀幣來啟動機器。','','去找銀松森林的超級清潔器5200型。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2952 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2952, 'zhTW', '超級清潔器5200型!', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2953 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2953,'zhTW','再次使用超級清潔器','','','','去找希爾斯布萊德丘陵的超級清潔器5200型。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2954 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2954,'zhTW','石頭衛士','“向你致意——我是把守入口的守護者。除非你擁有完整的奧丹姆圓盤，否則我不會讓你進入奧丹姆城。”$B$B這個石頭衛士一定就是派你來這裡的人希望能在這裡找到的東西。看來你必須在繼續探索之前找出石頭衛士背後隱藏的故事。','詢問諾甘農的石頭衛士，搞清楚它要讓你幹什麼，然後再次點選它腳下的奧丹姆石座。','瞭解諾甘農的石頭衛士要讓你幹什麼。','去塔納利斯使用奧丹姆石座。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2962 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2962,'zhTW','更多的輻射塵!','你的樣本不僅數量不夠，而且純度也不夠。$B$B我們需要更多的輻射塵。很顯然，穴居怪身上的輻射劑量根本無法滿足我們的需要。你必須重返諾姆瑞根，直接從輻射源頭取回一些輻射塵。我指的是那些受到輻射的泥漿怪、潛伏者和水元素。小心一點，收集這種輻射塵並不容易。也許你得試好幾次才能找到一個合適的樣本。','到諾姆瑞根去收集高強度輻射塵。要多加小心，這種輻射塵非常不穩定，很快就會分解。','','去丹莫洛找卡拉諾斯的奧齊·電環。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2963 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2963, 'zhTW', '奧丹姆的線索', '你好，很高興再一次見到你，$n!你在奧達曼的發現使探險者協會興奮不已。協會一直都在努力揭開你所發現的那張白金圓盤的秘密。你來的正是時候，我可以和你分享一下我們的最新進展!史學家卡尼克發現了一些很重要的線索，可能有助於找到塔納利斯沙漠中的守衛之谷的起源。他想和你談談，越快越好!', '與鐵爐堡探險者大廳中的史學家卡尼克談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2964 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2964,'zhTW','進一步的任務','好吧，$n…我們現在好象走進了一個死衚衕。我們知道我們需要的是什麼——奧丹姆圓盤——但我們不知道這些東西在哪裡。我們得進行大量的研究才能制定出確實可行的計劃。關於到哪裡去尋找圓盤……我有一些想法，我堅信我們馬上就會要求你儘快出發去找到它。$B$B這件事要通知資深探險家，$n，毫無疑問，他也會再次感謝你對探險者協會的幫助。','與鐵爐堡的資深探險家麥格拉斯談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2965 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2965,'zhTW','奧丹姆的線索','啊，$N，你來得正好。你在奧達曼挖掘場的發現讓我們的賢者進行了激烈的討論。我和納拉·蠻鬃也交換了看法，因為當初我和她一起經歷過一段冒險旅程，這段經歷對於我們將要採取的下一步行動非常重要。$B$B我想讓你和她去談一談，聽聽她當年在塔納利斯的守衛之谷中遇到的事情。她在長者高地等你。','與雷霆崖長者高地的納拉·蠻鬃談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2966 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2966,'zhTW','拭目以待','聖者圖希克和我希望你把這張圓盤拿到奧丹姆的封印之門去。我們……我們不能肯定這樣做會帶來什麼後果。$B$B當然，這聽上去確實很危險，但也有可能什麼都不會發生。也許你要將圓盤放在什麼東西上，也許你只要帶著圓盤，大門就會自己開啟。總之，不試一試是不會知道真相的。$B$B等你完成這項任務之後就回到我這裡來，我們還有很多事需要討論。','將迷你白金圓盤拿到塔納利斯的奧丹姆大門去，找出兩者之間的聯絡。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2967 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2967,'zhTW','返回雷霆崖','你開啟了底座，白金圓盤又一次突然出現在你的揹包裡。$B$B你從石頭守衛那裡獲取了許多資訊，而且白金原盤又回到了你的手中，現在你應該回雷霆崖向納拉·蠻鬃彙報這個大發現了。','與雷霆崖的納拉·蠻鬃談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2968 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2968,'zhTW','進一步的任務','好吧，$n…我們現在好象走進了一個死衚衕。我們知道我們需要的是什麼——奧丹姆圓盤——但我們不知道這些東西在哪裡。我們得進行大量的研究才能制定出確實可行的計劃。關於到哪裡去尋找圓盤……我有一些想法，我堅信我們馬上就會要求你儘快出發去找到它。$B$B這件事必須要通知聖者圖希克，$n，毫無疑問，他也會再次感謝你對我們的幫助。','與雷霆崖的聖者圖希克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2969 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2969,'zhTW','精靈龍的自由','可惡的恐怖圖騰部族正在捕捉精靈龍，$N。耶爾卡和我不知道他們打算對這些精靈龍做什麼，但那總不會是什麼好事。$B$B我們還沒有強悍到可以殺進營地去解救那些精靈龍，但也許有了你的幫助……如果你能找到一些得力的幫手的話，就從籠中釋放那些精靈龍吧，另外你要保證它們都活著逃出去。我也會幫你的。耶爾卡會留在這裡繼續戒備。','從恐怖圖騰營地的圍欄裡釋放被俘獲的小精龍。至少6個小精龍和辛達爾·月紋必須活著。$B$B如果6分鐘之內你還沒能達成這個目標，辛達爾就會決定撤退，任務也會隨即失敗。','至少拯救6只小精龍','去找菲拉斯的辛達爾·月紋。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2970 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2970,'zhTW','菲拉斯的正義','辛達爾已經跟你說過了，我們準備去和恐怖圖騰部族作戰。幹掉幾個牛頭人對我們兩個來說不是什麼問題，但如果你願意幫忙的話，我們還是很歡迎的。$B$B看到下面那個營地了嗎？東邊有更多這樣的營地。運用你的戰術，儘可能讓那些牛頭人多吃些苦頭。當他們被你和辛達爾打得落花流水之後，我們再回到這裡來碰頭。','殺掉12個恐怖圖騰博學者、10個恐怖圖騰襲擊者和6個恐怖圖騰薩滿祭司，然後向菲拉斯的耶爾卡·月紋彙報。','','去找菲拉斯的耶爾卡·月紋。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2971 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2971,'zhTW','暫無內容','[PH] Description','[PH] Log Description','[PH] Log Bullet Entry','去找希爾斯布萊德農場的爆破專家艾米·短線。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2972 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2972,'zhTW','菲拉斯的正義','在這片蠻荒的土地上，辛達爾和我有無數的方法來報答你，但我們想讓你有更多的成就感。把我的戒指拿去吧，如果你哪一天到了泰達希爾，就去一趟達納蘇斯城裡的月神殿。你可以在那裡找到高階祭司泰蘭妲·語風。她看到這枚戒指就會知道我們在這裡一切安好，並相信你所說的一切。$B$B$N，我們都很感謝你。','將耶爾卡的徽記之戒交給達納蘇斯的高階女祭司泰蘭妲·語風。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2973 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2973,'zhTW','新斗篷的光輝','你好，$c。我和我的夥伴們正準備去菲拉斯執行任務。$B$B我的妻子科琳很喜歡新衣服，所以我想為她做一件用小精龍的翅膀裝飾的新披風。你能幫幫我嗎？長著美麗翅膀的小精龍在莫沙徹營地的西邊。','給莫沙徹營地的克魯伊格·碎顱帶去10個閃光的小精靈翅膀。','','去菲拉斯找莫沙沏營地的克魯伊格·碎顱。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2974 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2974,'zhTW','可怕的發現','什麼？！你在這一地區碰到牛頭人了？你開玩笑吧！他們長什麼樣？！$B$B恐怖圖騰氏族！你看到他們了？貝爾戈洛姆對他們這種生物很有興趣……甚至出重金懸賞他們。$B$B你必須得回去，$c。回去給我帶些他們的角回來……如果可以的話，儘可能多弄一些。你可別低估了恐怖圖騰氏族，回去殺了他們，讓菲拉斯的河流被他們的鮮血染紅。','收集20支恐怖圖騰之角，把它們交給千針石林的克魯伊格·碎顱。','','去菲拉斯找莫沙沏營地的克魯伊格·碎顱。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2975 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2975,'zhTW','菲拉斯的食人魔','戈杜尼食人魔在這一地區的影響已經不容忽視了。$N，你可以清楚地看到這一點，他們的存在汙染了這片土地。在他們進一步擴張之前，我們一定要把他們趕回去。$B$B沿著河向北走，你會找到他們的前哨營地。去殺掉他們，$N。我們必須告訴這些食人魔：他們在這裡不受歡迎。','莫沙徹營地的洛卡·奧赫要你殺掉10個戈杜尼食人魔、10個戈杜尼食人魔法師和5個戈杜尼蠻兵。','','去菲拉斯找莫沙徹營地的洛卡·奧赫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2976 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2976,'zhTW','可怕的發現','什麼？！$B$B啊，我確實提到過獎賞，對嗎？好吧，我知道了$B$B你完成了任務，我覺得你應該得到最高的獎賞。把這些角拿去，我會幫你把它們放到箱子裡。到榮譽谷去找貝爾戈洛姆·石槌，向他彙報你所見的一切，他會表彰你的。$B$B祝你一路平安，$c，再次感謝你。','將一箱恐怖圖騰之角交給奧格瑪的貝爾戈洛姆·石槌。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2977 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2977, 'zhTW', '返回鐵爐堡', '你打開了底座，白金圓盤又一次突然出現在你的背包裡。$B$B你從石頭守衛那裡獲取了許多資訊，而且白金原盤又回到了你的手中，現在你應該回鐵爐堡向探險者協會彙報這個大發現了。', '與鐵爐堡的史學家卡尼克談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2978 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2978,'zhTW','戈杜尼卷軸','你撿起了這個沾滿泥土的卷軸，發現上面寫著某種集會或儀式的內容。洛卡·奧赫應該會對這個卷軸以及它對戈杜尼食人魔的意義感興趣。','將戈杜尼卷軸交給莫沙徹營地的洛克·奧漢。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2979 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2979,'zhTW','黑暗儀式','這些好像是某種黑暗儀式的計劃，$N。根據我所瞭解的情況，這種儀式是由戈杜尼食人魔中的大法師進行的。$B$B從某個戈杜尼大法師身上給我弄一顆寶珠來。$B$B法師的寶珠蘊含了巨大的力量，它可以幫我們搞清楚更多關於這種儀式的細節。','莫沙徹營地的洛卡·奧赫希望你找到一顆戈杜尼之寶珠。','','去菲拉斯找莫沙徹營地的洛卡·奧赫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2980 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2980,'zhTW','菲拉斯的食人魔','現在你已經證明了自己是一個真正的勇士，我相信你具備足夠的勇氣繼續完成下一個任務。$B$B到這裡西南邊的高原荒野去，在那塊原本屬於暗夜精靈的土地上還殘存著一些被遺棄和毀壞的建築物。搜尋那些廢墟，當你看到枯萎的樹木和滿目瘡痍的大地時，你就會看到那些戈杜尼食人魔。把他們都幹掉。$B$B這些食人魔比你曾面對的任何敵人都要強大，$N。你一定要小心行事。','莫沙徹營地的洛卡·奧赫要你去殺掉十個戈杜尼薩滿祭司、10個戈杜尼術士和5個戈杜尼虐待者。','','去菲拉斯找 莫沙徹營地的洛卡·奧赫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2981 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2981,'zhTW','菲拉斯的危機','菲拉斯是一個有成就的$c證明自己能力的理想場所。有個名叫戈杜尼的食人魔部落是那裡最主要的軍事力量，而且他們的勢力仍在不斷增長。在這些食人魔威脅到我們在菲拉斯的地位以前，我們必須要阻止他們。$B$B我認識一個名叫洛卡·奧赫的戰士，她住在菲拉斯的莫沙徹營地裡，去找她談談吧，她會讓你知道更多情況的。','貝爾戈洛姆·石槌想讓你去和莫沙徹營地的洛卡·奧赫談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2982 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2982,'zhTW','高原荒野','雖然菲拉斯森林的廢墟中隱藏著巨大的危險，但特洛亞斯和我一直以來都在調查這個地區。$B$B最近特洛亞斯老是獨自一人去高原荒野，這很讓我擔心。戈杜尼食人魔已經佔領了那裡，他們不會對任何進入他們領地的冒險者手下留情的。$B$B我希望你能到菲拉斯南部去一趟，消滅一些食人魔。讓我的特洛亞斯安全一點，我會十分感激你的。','安吉拉斯·月風要求你殺死8個戈杜尼術士、8個戈杜尼薩滿祭司和8個戈杜尼蠻兵。','','去菲拉斯找羽月要塞的安吉拉斯·月風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2983 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2983,'zhTW','火焰的召喚','你上次考驗至今已經有一段時間了，$N。從那以來，你一直耐心地學習，但在是時候讓你學習更大的力量了……是時候讓你學習真正的力量。如果你準備好付出，火的元素就是你的了。$B$B在貧瘠之地找到卡納爾·菲斯。他居住在十字路口北部的小房子裡，小心，如果你到了被詛咒的暗夜精靈的領地，那你走得太遠了。','去貧瘠之地找到卡納爾·菲斯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2984 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2984,'zhTW','火焰的召喚','你已經很久沒有接受試煉了，$N。到目前為止，你已經證明了自己有足夠的耐心，現在是時候讓你學習更多東西，是時候讓你瞭解毀滅…和混亂了。只要你明白自己即將為此付出的代價，火焰的元素就會與你建立連線。$B$B到貧瘠之地去找卡納爾·菲斯，他就住在十字路口北部的一間小房子裡。路上小心點，走太遠的話，你就會進入精靈的領地。','去貧瘠之地找到卡納爾·菲斯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2985 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2985,'zhTW','水之召喚','你的下一個目標是水，$N。 我可以看出你已經能很熟練地運用火焰的力量，看來你也準備好去和伊斯倫談談了。$B$B伊斯倫住在貧瘠之地的河岸邊，你只要沿著怒水河往南走，就肯定能找到她。她對各種元素的使用方法都很熟悉，可以教你關於水元素的知識……$B$B不要向南走得太遠，她就在棘齒城旁邊，$N。','找到貧瘠之地的水之先知伊斯倫。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2986 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2986,'zhTW','水之召喚','從你上次接受測驗到現在已經有很長的時間了，$N。迄今為止，你展示了足夠的耐心，不過現在你應該學到更多的東西，應該去了解水的純潔。$B$B去貧瘠之地找到水之先知伊斯倫，沿著怒水河的東岸向棘齒城的南方走，你可以在一間小漁屋裡找到她。祝你好運，$N。','找到貧瘠之地的水之先知伊斯倫。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2987 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2987,'zhTW','戈杜尼鈷礦石','我剛剛到達菲拉斯時，曾聽說這裡的戈杜尼食人魔有一些有趣的礦石。天知道食人魔用礦石來幹什麼，但他們確實在很小心地保護那種東西！他們有意隱藏這些礦石，以免我們接觸到它。$B$B如果你願意的話，我會把我的鏟子給你。到北面的戈杜尼前哨站去，給我挖些戈杜尼鈷礦回來。注意找那些泛著藍光的礦石，然後就挖！','莫沙徹營地的奧爾文·吉茲米克需要12塊戈杜尼鈷礦石的樣本。','','去菲拉斯找莫沙徹營地的奧爾文·吉茲米克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2988 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2988,'zhTW','枯木巨魔的牢籠','我們最強大的獅鷲的兒子失蹤了！幾天前，沙普比克和塔的父母外出打獵時失蹤了，我們認為是巨魔抓走了它。$B$B你必須幫幫我們！到枯木巨魔的兩個村子裡去搜一搜那裡的籠子，看看沙普比克是不是被關在裡面。','檢查兩個枯木巨魔村落裡的籠子，然後向獅鷲管理員沙拉克·鷹斧回覆。','','去辛特蘭找鷹巢山的獅鷲管理員沙拉克·鷹斧。','檢查第一隻籠子','檢查第二隻籠子','檢查第三隻籠子','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2989 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2989,'zhTW','祖爾祭壇','沙普比克沒有和枯木巨魔在一起，那麼或許是邪枝巨魔帶走了他……到邪枝巨魔控制地區的西部邊緣去，在那裡的祖爾祭壇上找一找吧。','檢查祖爾祭壇的頂部，然後向獅鷲管理員沙拉克·鷹斧報告。','搜尋祖爾祭壇','去辛特蘭找鷹巢山的獅鷲管理員沙拉克·鷹斧。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2990 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2990,'zhTW','薩迪斯·格希德','把這根羽毛交給占卜師薩迪斯·格希德。幾年前，他離開鷹巢山去尋求黑暗的知識，但他內心深處仍是一個不折不扣的蠻錘矮人！$B$B也許他的智慧能幫助我們找到沙普比克。$B$B這根羽毛是從它的巢穴裡拿出來的，如果你把它交給薩迪斯，那麼他也許就可以用占卜法術找到沙普比克。$B$B祝你好運，$N。你可以在詛咒之地找到薩迪斯，他就在守望堡的法師塔上。','將沙普比克的羽毛交給詛咒之地的薩迪斯·格希德。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2991 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2991,'zhTW','耐克魯姆的徽章','我會幫你找出那頭獅鷲的下落，但你得先為我做點事情。巨魔城市祖爾法拉克里面有一個名叫耐克魯姆的巨魔，他擁有一枚徽章，我很想研究一下那東西。把徽章交給我，我就幫你找到沙普比克。$B$B祖爾法拉克在塔納利斯的沙漠中。','將耐克魯姆的徽章交給詛咒之地的薩迪斯·格希德。','','去詛咒之地找守望堡的薩迪斯·格希德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2992 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2992,'zhTW','占卜','在我進行占卜儀式的過程中，不要打斷我。我會找出你拿來的那根羽毛和它主人之間的關係，然後順藤摸瓜找到沙普比克。$B$B理論上講是這樣……如果一切都按照計劃進行的話。如果不是，那麼……你最好閉上眼睛。','等待薩迪斯完成占卜儀式。','等待薩迪斯的儀式結束','去詛咒之地找守望堡的薩迪斯·格希德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2993 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2993,'zhTW','返回辛特蘭','沙普比克被關在巨魔城市辛薩羅的懸崖上的一隻籠子裡，籠子的鑰匙由邪枝巨魔的邪惡祭司海克斯掌管著。$B$B我已經做了我該做的那部分事情，希望你執行任務的時候一切順利，$N。','與辛特蘭的獅鷲管理員沙拉克·鷹斧談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2994 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2994,'zhTW','拯救沙普比克','你必須得救出沙普比克！$B$B殺進邪枝巨魔那座城市——辛薩羅的山頂，從邪惡祭司海克斯那裡拿到沙普比克籠子的鑰匙，找到沙普比克，把它救出來！','到辛薩羅山頂去，殺掉邪惡祭司海克斯，找到沙普比克籠子的鑰匙，然後救出沙普比克。','','去辛特蘭找鷹巢山的獅鷲管理員沙拉克·鷹斧。','','開啟沙普比克的籠子','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2995 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2995,'zhTW','聯絡中心','奎爾丹尼小屋是高等精靈在辛特蘭的聯絡中心。他們的使者正在試圖與其他種族建立聯絡，他們會與這些種族分享與辛特蘭南部的枯木巨魔的情報。所有聯絡其他種族所需的檔案都被儲存在了小屋中。$B$B我們不希望那些精靈與其他種族建立聯盟關係，$N。$B$B去摧毀他們的檔案，或者說，我們要毀掉他們的聯絡中心……','幽暗城的奧蘭·斯內克威瑟讓你到辛特蘭去燒燬高原精靈記錄、高原精靈報告和高原精靈信件。','','去找提瑞斯法林地的奧蘭·斯內克威瑟。','燒燬高原精靈記錄','燒燬高原精靈信件','燒燬高原精靈報告','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2996 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2996,'zhTW','尋找斯坦哈德','我過去曾教過你一些知識和技藝，現在該讓別人繼續教你了。我說的是棘齒城的斯坦哈德，他是個人類，但不要以為他很弱小。雖然他看上去非常矮小，但是卻有著超強的力量。他可以教你最強大的召喚法術——我覺得你已經準備好了，現在就到他那裡去吧。他住在棘齒城……他的塔就在那座港口城市旁邊的山上。','與棘齒城的斯坦哈德·法爾杉談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2997 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2997,'zhTW','聖潔之書','你好，$N。我知道你在忙著幫助丹莫洛的人民，但如果你有時間的話，你應該去鐵爐堡，到那裡去跟我們最受尊敬的族人蒂薩·熱爐談一談。當年輕的聖騎士需要學習更多關於聖光以及其它一些必要的知識時，他們就會去找她。','和鐵爐堡的蒂薩·熱爐談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2998 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2998, 'zhTW', '聖潔之書', '你好，我的<兄弟/姐妹>。我們這裡最有影響力的聖騎士─達索瑞恩·拉爾最近談起過你。我聽他說過你應該去找他接受試煉了……我也從他那裡聽說過你的出色表現。如果我是你，而且我有時間的話，我就會去暴風城和他聊聊的。我很肯定他會待在光明大教堂裡─他一般都待在那裡。', '與暴風城的達索瑞恩·拉爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2999 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2999,'zhTW','聖潔之書','你好，$N。我知道你在忙著幫助丹莫洛的人民，但如果你有時間的話，你應該去鐵爐堡，到那裡去跟我們最受尊敬的族人蒂薩·熱爐談一談。當年輕的聖騎士需要學習更多關於聖光以及其它一些必要的知識時，他們就會去找她。','與鐵爐堡的蒂薩·熱爐談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3000 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3000,'zhTW','聖潔之書','你好，$N。我知道你在忙著幫助丹莫洛的人民，但如果你有時間的話，你應該去鐵爐堡，到那裡去跟我們最受尊敬的族人蒂薩·熱爐談一談。當年輕的聖騎士需要學習更多關於聖光以及其它一些必要的知識時，他們就會去找她。','和鐵爐堡的蒂薩·熱爐談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3001 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3001,'zhTW','尋找斯坦哈德','我過去曾教過你一些知識和技藝，現在該讓別人繼續教你了。我說的是棘齒城的斯坦哈德，他是個人類，但不要以為他很弱小，也不要以為他是你的敵人……至少現在不是。他很強大，所以理應受到尊重。他可以教你最強大的召喚法術，我覺得你已經準備好了，現在就到他那裡去吧。他住在棘齒城……他的塔就在那座港口城市旁邊的山上。','在棘齒城找到斯坦哈德·法爾杉。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3002 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3002,'zhTW','戈杜尼寶珠','雖然我很熟悉我的敵人，但我只是一個戰士，$N。我不知道這顆寶珠是用來幹什麼的。$B$B我認識一個住在奧格瑪的法師，他可以告訴你更多關於寶珠的資訊。把它拿到他那裡去吧。','將戈杜尼寶珠交給奧格瑪暗木小屋裡的尤塞爾奈。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3022 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3022,'zhTW','小心運送','$N，顯然你很想幫我進行崇高的事業。嗯，當然，你可以為我做一些事情！$B$B請把這箱蛋送給艾瑞拉斯·琥珀。他是一個很重視這些蛋的德魯伊，而且一直在幫助孵化這些蛋，以及訓練幼小的角鷹獸。你可以在泰達希爾南邊的一個名叫魯瑟蘭村的村莊裡找到他。','把仔細包裝過的箱子交給魯瑟蘭村的艾瑞拉斯·琥珀。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3023 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3023,'zhTW','暫無內容','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3042 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3042,'zhTW','巨魔調和劑','祖爾法拉克的沙怒巨魔用砂石製造巨魔調和劑，我可以用它來加強我鑄造的東西！有眼光的行家會出高價購買經過這樣處理的裝備，所以，如果你能給我提供足夠的調和劑，那我一定會重重獎賞你的。$B$B祖爾法拉克在加基森的西北邊。祝你好運。','收集20瓶巨魔調和劑，把它們交給加基森的特倫頓·輕錘。','','去找塔納利斯的特倫頓·輕錘。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3062 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3062,'zhTW','黑暗之心','艾丹娜·邪爪是居住在西面廢墟里的北泉鷹身人的皇后。她是個徹頭徹尾的惡魔，我聽說她的心是水晶做的。除了對別人的仇恨之外，她沒有一絲其它的情感。你必須幹掉艾丹娜，把她的黑心交給我。$B$B我聽說鷹身人有一種號角——在廢墟北部的邪爪石那裡吹響號角就可以召來她。$B$B當她發現召喚她的是死亡的命運而不是她的同族時，她會有多麼驚訝啊！','莫沙徹營地的塔羅·刺蹄要你給他拿去艾丹娜·邪爪的黑心。','','去菲拉斯找莫沙徹營地的塔羅·刺蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3063 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3063,'zhTW','對鷹身人的復仇','年輕時，我曾是個經驗豐富的獵手，沒有什麼野獸會讓我感到害怕，直到……$B$B有一次在樹林裡，我在一場惡戰之後正在打磨自己的武器，這時我遭到了伏擊。鷹身人包圍了我，好不容易我才脫了身。$B$B直到現在，我還能聽見它們的嚎叫在耳邊迴盪……$B$B現在我已經不再年輕了，不過仇恨還在我的心中燃燒——這麼多年了，我一定要報仇。$B$B北泉鷹身人就在西邊，$N，去為我復仇。','塔羅·刺蹄讓你殺掉4個北泉鷹身人、4個北泉遊蕩者、4個北泉喚風者和4個北泉殺戮者。','','去菲拉斯找莫沙徹營地的塔羅·刺蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3064 AND `locale` = 'zhTW';
