INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3116,'zhTW','簡易符記','我們的戰士訓練師奧莉希亞派來的信使把這塊符記交給了我，看起來奧利希亞有話要跟你說，看看符記上寫了些什麼，然後把符記給她帶去吧。','閱讀簡易符記，然後與幽影谷的奧莉希亞談一談。','','','','','','',0);
