INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3120,'zhTW','綠色符記','我們的德魯伊訓練師瑪丹特派來的信使把這塊符記交給了我，看起來瑪丹特有話要跟你說，看看符記上寫了些什麼，然後把符記給他帶去吧。','閱讀綠色符記，然後與幽影谷中的奧達希爾頂端的瑪丹特·硬木談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3121 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3121,'zhTW','奇怪的要求','在莫沙徹營地北邊拉瑞斯小亭的夏拉什·火刃有我所需要的東西！他調配出了一種混合物，我需要用它來……好吧，你以後會知道的。$B$B快點出發，快點出發，去找夏拉什。拿著這個東西，這是一顆皺縮的徽記，我答應夏拉什用此來交換草藥。這是某個可憐侏儒的徽記，我在森林裡撞見了他，然後就……我敢說夏拉什會很高興得到這個東西的。$B$B你可以在菲拉斯里找到夏拉什。','將皺縮的頭顱交給菲拉斯的夏拉什·火刃。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3122 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3122,'zhTW','向巫醫尤克里回覆','拿著這些草藥，$N。把它們交給巫醫尤克里。$B$B請告訴他，我對那些皺縮的頭顱很滿意。','將尼爾魯的草藥包送給菲拉斯的巫醫尤克里。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3123 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3123,'zhTW','測試容器','這是一個測試，對我將要進行的儀式和你的能力來說都是一個測試。拿著這個容器，$N。你可以用它將一個生物的靈魂禁錮起來。$B$B到辛特蘭去尋找一種被稱作梟獸的生物，它們曾經是暗夜精靈的女神艾露恩的寵物。那些墮落、頭腦簡單而又野蠻的梟獸就是你的目標，$N。殺死十頭梟獸，在它們的靈魂逃跑之前用靈魂精華容器把它們收起來。','到辛特蘭去殺掉10頭梟獸，然後使用靈魂精華容器捕獲它們的靈魂。$B$B將靈魂精華容器和10個梟獸靈魂精華交給菲拉斯的巫醫尤克里。','','去菲拉斯找莫沙徹營地的巫醫尤克里。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3124 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3124,'zhTW','角鷹獸靈魂精華','既然你已經證明了自己是個值得信賴的$c，而且還具有使用靈魂精華容器的能力，那麼現在我希望你能幫我抓住另一種生物。$B$B角鷹獸多年來一直是暗夜精靈的忠實夥伴，它們的靈魂忠實而又堅定。$B$B去殺掉十隻亂羽角鷹獸，動作要快，將它的靈魂關在容器裡，這樣它的靈魂精華才可以儲存下來。你可以在高原荒野一帶找到這種角鷹獸，從這裡一直向南走就到了。','殺掉10只任意種類的亂羽角鷹獸，然後用靈魂精華容器捕獲它們的靈魂。','','去菲拉斯找莫沙徹營地的巫醫尤克里。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3125 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3125,'zhTW','精靈龍靈魂精華','$N，下一步我必須讓你捕獲一種看上去可能很脆弱，但卻有著我們真正需要的強大精神力量的生物。我所說的就是精靈龍，它們是暗夜精靈的夥伴。我們必須抓一隻精靈龍來進行研究，這樣部落也可以從這種精神力量中獲益。$B$B我們需要它們的靈魂精華，$N。殺掉八隻小精龍或精龍，並俘獲它們的靈魂。從這裡向西就可以找到它們。','殺掉8只精龍或小精龍，然後用靈魂精華容器捕獲它們的靈魂。','','去菲拉斯找莫沙徹營地的巫醫尤克里。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3126 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3126,'zhTW','樹人靈魂精華','在森林中到處遊蕩的森林漫遊者是我們的下一個目標，$N。暗夜精靈已經和樹人結成聯盟，共同與部落為敵。它們的行動也許很緩慢，但它們卻是強大的衛士。$B$B我們馬上就能讓這種力量為我們所用。$B$B去找到三個森林漫遊者，然後用靈魂精華容器將它們的靈魂捕獲。','殺掉3個森林漫遊者，然後用靈魂精華容器捕獲它們的靈魂。','','去菲拉斯找莫沙徹營地的巫醫尤克里。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3127 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3127,'zhTW','山嶺巨人靈魂精華','我給你的最後一項任務是到西北邊去找到我們最後的敵人。$B$B在燃燒軍團入侵的時候，山嶺巨人幫助了暗夜精靈。在你穿過他們的領地時，你可以看到他們那龐大的身軀，感受到大地在隨著他們的腳步聲震動。$B$B我非常想得到如此龐大身軀下所蘊藏的力量，去殺掉十二個山嶺巨人，然後用靈魂精華容器將他們強大的靈魂給我帶回來。','殺掉7個大地行者或者峭壁巨人，然後用靈魂精華容器捕獲它們的靈魂。','','去菲拉斯找莫沙徹營地的巫醫尤克里。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3128 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3128,'zhTW','天然材料','我需要一些特定的材料來完成我的工作……你可以把這件事情與我要給你的其它幾個任務一起完成了。$B$B我需要菲拉斯樹人身上的一段斷裂的原木，西邊的那些山嶺巨人和精靈龍身上的包殼礦石，還有從辛特蘭的梟獸或者菲拉斯的角鷹獸身上找到的有彈性的肌腱。最後，我還需要大量的金屬碎片，這些碎片可以從我剛才提到過的這些生物身上找到。','為莫沙徹營地的巫醫尤克里收集2根斷裂的原木、6顆包殼礦石、20片有彈性的肌腱和40塊金屬碎片。','','去菲拉斯找莫沙徹營地的巫醫尤克里。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3129 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3129,'zhTW','靈魂武器','將靈魂精華注入武器是個非常艱難的過程。既然我現在具備了所有必需的材料，還有這些你弄到的靈魂精華，那麼我現在可以開始了。請等一會兒，我馬上就回來。','巫醫尤克里希望你在他準備武器的時候稍等一會兒。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3130 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3130,'zhTW','憎世納迦之戰','現在，我要讓你到我的助手拉託尼庫斯那裡去，他一直都在密切注意納迦的動向。我會對這裡的綜合形勢作出評價，然後才能夠採取行動將他們趕出這裡，但是一旦我們發起攻擊，我們的要塞就必然處於部落的直接威脅下——或者更糟，因此這並不是最佳的方案。$B$B不管怎麼樣，拉託尼庫斯正在等著你。你的表現一直很不錯，$n，希望你能繼續保持。$B$B你可以出發了。','到羽月要塞的拉託尼庫斯·月矛那裡去報到。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3141 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3141,'zhTW','洛拉姆斯','你想和惡魔戰鬥？聽聽我的故事會對你有好處。','聽洛拉姆斯·薩里比迪斯講述他的故事。','洛拉姆斯的故事','去艾薩拉找風暴海灣的洛拉姆斯·薩里比迪斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3161 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3161,'zhTW','加茲瑞迪安','$N，我是一個科學家，但是我真正的身份其實是一個賞金獵人！$B$B很久以前，當巨魔還在片土地上橫行的時候，他們製作了很多以加茲瑞拉為原型的飾物，並把它作為偶像膜拜。那些裝飾物上的形象被稱為“加茲瑞迪安”，也就是九頭蛇之神的意思。$B$B我自己找到了一些這種飾物，但是我需要更多來進行研究——也許你可以幫我搞到一些？$B$B我甚至發明了一個可以幫助你尋找加茲瑞迪安的裝置！把這件頭盔拿去，開始尋找吧！','塔納利斯的瑪爾馮·瑞文斯克要你收集30件加茲瑞迪安飾物。','','去塔納利斯找破碎石柱的瑪爾馮·瑞文斯克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3181 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3181,'zhTW','瑪爾戈的巨角','這根巨大的角上有許多擦痕和裂縫，還有一塊金屬物體嵌在粗糙的表面上。$B$B仔細檢查了一番之後，你發現這塊金屬實際上是一把斷掉的斧頭。金屬上刻著一行字：$B$B巡山人貝波蒂的財產。$B$B當你試著把斧頭拔出來的時候，它一下子變成了無數的碎片。$B$B真糟糕！','將瑪爾戈的巨角交給巡山人貝波蒂。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3182 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3182,'zhTW','證明信','你指望我會相信這樣一個故事？真正的角怎麼會是這個樣子？$B$B聽著，把這個明顯是贗品的東西拿給鐵爐堡的索里奧斯館長看看。如果他能證明你的話是真的，那麼你就能收到一份證明。把那份證明拿回來給我，我就給你一把灼熱峽谷的鑰匙。$B$B快動身去找索里奧斯館長！','把瑪爾戈的巨角交給鐵爐堡的索里奧斯館長。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3201 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3201,'zhTW','館長的證明！','我真不敢相信貝波蒂居然懷疑這支角的真實性。現在就你和我，我不妨直說，我認為她純粹是嫉妒！我知道她很想親手殺了那隻野獸，你的“意外的成功”讓她的美夢破滅了。$B$B那麼，你需要證明是嗎？你對博物館的貢獻很大，這不是問題。$B$B<索里奧斯館長從一大堆檔案中翻找東西。>$B$B好了！你可以把它拿去交給貝波蒂。','把索里奧斯的證明信交給巡山人貝波蒂。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3221 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3221, 'zhTW', '與倫法洛會面', '當你在幫助我們的亡靈哨兵的時候，藥劑師倫法洛派人來找過你。他並沒有告訴我詳情，但他想和你談談你所交給他那些狼的心臟的事情。', '與瑟伯切爾的藥劑師倫法洛談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3241 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3241,'zhTW','暫無內容','從鬼霧峰收集圖騰，因為那裡現在令人作嘔，沒有地方有乾淨閃亮的圖騰。','把他們帶給圖加·符文圖騰。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3261 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3261,'zhTW','喬恩·星眼','你將結束跟隨我進行修煉的日子，$N。為了進一步的深造，你必須到南邊的陶拉祖營地去找喬恩·星眼，他會對你進行更深入的指導。','與陶拉祖營地的喬恩·星眼談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3281 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3281,'zhTW','被偷走的銀幣','你殺了迅猛龍，很好，但是它們偷走的那些銀幣必須要找回來！我接到報告說有大量的迅猛龍聚集在棘齒城南面，那裡現在被稱為迅猛龍平原，它們八成是把銀幣藏在那裡了。$B$B到那個迅猛龍平原去找到被偷走的銀幣，然後把銀幣送還到我這裡來。','把被偷走的銀幣交給十字路口的加茲羅格。','','去找貧瘠之地的加茲羅格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3301 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3301,'zhTW','茉拉·符文圖騰','我的族友茉拉·符文圖騰去了銀松森林，她去那裡是為了幫助我們的亡靈盟友。銀松森林狀況不佳，那是一片瀕死的森林，茉拉希望透過自己的努力給銀松森林帶來新的活力。也許在貧瘠之地找到的這種奇怪的生命形式能夠對她在銀松森林的工作有所幫助。$B$B把你收集到的龜殼樣品交給她吧，茉拉一般都在瑟伯切爾待著。如果運氣夠好的話，這些貝殼可以幫她找到治癒那片瀕死之地的方法。','和瑟伯切爾的茉拉·符文圖騰談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3321 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3321,'zhTW','秘銀會的認可','你為秘銀會做了很多事情，$N。像你這樣無私而純粹地奉獻並不是人人都能做到的。在我和加爾文的心中，你無疑已經成為我們的一員了。$B$B所以我覺得你應該獲得一些小獎勵。其實也沒什麼，也就是一個飾品，我想你應該很清楚它的意義，而且我相信它應該就是你到我們這裡來的最初目的。','等待特倫頓完成他的工作。','等待特倫頓完成工作','去找塔納利斯的特倫頓·輕錘。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3341 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3341,'zhTW','寒冰之王','在貧瘠之地有一處藤蔓交錯的地方，那裡被稱為剃刀高地。我們很久以前派去的斥候就已經發現那裡的情況有些不對勁了，最近的發現表明那裡的情況變得更加糟糕了……$B$B剃刀高地的野豬人和亡靈天災結成了同盟。有個名叫寒冰之王亞門納爾的巫妖指揮著它們的每一步行動。$B$B亞門納爾與耐奧祖有著直接的心靈感應聯絡，我們必須切斷這樣的聯絡，$N。我們必須幹掉寒冰之王。','安德魯·布隆奈爾要你殺了寒冰之王亞門納爾並將其頭骨帶回來。','','轉至幽暗城，去找魔法區的安德魯·布隆奈爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3361 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3361,'zhTW','逃難者的困境','我本來正在前往諾姆瑞根的途中，打算和我的地精同胞會合，結果一切錯得一塌糊塗!$B$B我離開安威瑪，包包裝好，跋涉過及腰的雪。然後我們遇上這場莫名其妙的地震，把我震得暈頭轉向。結果我跑到了這裡，更糟的是，食人妖偷光了我的東西!$B$B $N ，過去那一天半顯然證明了我能力不足。你介意幫個忙，進入西南方的食人妖營地，把我的東西帶回來給我嗎?','找回菲利克斯的盒子、菲利克斯的箱子和菲利克斯的螺釘桶。','','去丹莫洛找寒脊山小徑的菲利克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3362 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3362,'zhTW','灌木谷','你有沒有去過灌木谷？那是個非常危險的地方，$N。$B$B那裡到處都是奇怪的野獸，我根本不會冒險去靠近它們！那些野獸應該是被稱作長瘤的灌木獸和灌木塑根者……$B$B不管怎麼樣，我想要親自到那個山谷裡去看一看，但是那麼多的灌木獸在山谷裡活動，我可不想去送死。但是現在你來了——如果你能幫我清除一些灌木獸的話，也許我就能去一趟了。$N，我想你應該能幫忙的吧？幫幫我，好不好？','加基森的特蘭雷克要你殺掉8只長瘤的灌木獸和8只灌木塑根者。','','去找塔納利斯的特蘭雷克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3363 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3363,'zhTW','被腐化的輕歌花','','','','去找費伍德森林的被腐化的輕歌花。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3364 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3364, 'zhTW', '熱酒快遞', '嘿!我早就該把這美味又熱騰騰的熱酒送給安威瑪的德南·弗卡特，不過我得先送一杯給附近的格瑞林!我肯定沒辦法在酒變涼之前把酒送給他!$B$B你看起來動作挺快的，也許你能辦到……這杯酒只能保溫5分鐘，德南要的可不是冰鎮熱酒，所以你一定要趕快!安威瑪就在這裡的東北邊，那個在山壁上鑿出來的大洞裡。$B$B謝謝你, $N, 別忘了把我的杯子帶回來!', '在5分鐘內把熱騰騰的熱酒交給安威瑪的德南·弗卡特。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3365 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3365, 'zhTW', '歸還酒杯', '太正點了!沒有什麼別的東西能像這杯熱騰騰的熱酒，在這個大冬天裡溫暖你的靈魂了!$B$B拿著這個，$N─幫個忙，把這個空杯子還給諾里，現在就去。', '把諾里的杯子還給諾里·激流。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3366 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3366,'zhTW','發光的碎片','這塊碎片透出異樣的綠色光芒，雖然它完全是一塊固體，但是卻讓人感覺好像有一股煙從碎片中冒出來。你情不自禁地注視著這塊水晶的深處，這時你突然覺得這其中必定包含著許多曲折的故事。\\n\\n\\n\\n也許你應該去棘齒城看看那裡有沒有人知道這塊碎片的來歷。 ','尋找更多有關這塊噩夢碎片的資訊。 ','找人談談噩夢碎片的事情','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3367 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3367,'zhTW','蘇塔拉之石','<杜里奧斯痛苦地呻吟著。>$B$B我受了重傷，$c。我感覺……頭重腳輕……世界在旋轉……身體裡面在出血。$B$B我必須回到鐵爐堡，幫幫我，$N……','幫助杜里奧斯回到鐵爐堡。','護送杜里奧斯','去找灼熱峽谷的燒焦的信件。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3368 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3368,'zhTW','蘇塔拉之石','我的好兄弟：$B$B如果你讀到了這封信，那我已經不在這個世界上了。至於這封信是怎樣到你手中的，我就不得而知了。 $B$B關於那些石頭：它們確實存在，而且在黑鐵矮人手裡。他們的領袖，黑衣拉索裡克正在使用石頭的力量來禁錮我們勘探隊的同伴。他們被帶到了大熔爐那裡。他們的意志已經被扭曲，被迫不分晝夜地幹活以完成一個名叫奧比斯頓的東西。$B$B幫幫他們，我的兄弟。這是一個死者最後的希望了。$B$B——杜里奧斯','把燒焦的信件交給鐵爐堡的索里奧斯，他在探險者大廳裡。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3369 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3369,'zhTW','在噩夢中','這塊碎片中蘊含有巨大的秘密，它是翡翠夢境的精華所在。然而，我從這片碎片中看到的卻不是夢境，而是一種噩夢。$B$B我並不是想要警告你什麼，$N，但是我希望你儘快把這個碎片送到一位睿智的德魯伊手裡。$B$B到雷霆崖的長者高地去找哈繆爾·符文圖騰，我不能再多說了。','把噩夢碎片交給長者高地的哈繆爾·符文圖騰。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3370 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3370,'zhTW','在噩夢中','這塊碎片中蘊含有巨大的秘密，它是翡翠夢境的精華所在。然而，我從這片碎片中看到的卻不是夢境，而是一種噩夢。$B$B我並不是想要警告你什麼，$N，但是我希望你儘快把這個碎片送到一位睿智的德魯伊手裡。$B$B到達納蘇斯的塞納里奧議會去找瑪斯雷·馭熊者，我不能再多說了。','把噩夢碎片交給達納蘇斯的瑪斯雷·馭熊者。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3371 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3371, 'zhTW', '矮人的正義', '我的心已被悲痛腐蝕，變成了一個空虛的黑洞，$N。杜里奧斯的逝去讓我一時之間無法恢復。我必須讓他的心願得以實現─那個冷血的兇手必須得到正義的懲罰。回到灼熱峽谷去，完成他最後的心願:拯救他的同伴。黑鐵矮人強迫他們的奴隸在一個名為熔渣之池的悶熱礦坑工作。去那裡尋找杜里奧斯的同伴吧。', '回去灼熱峽谷，尋找到杜里奧斯的考古隊員。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3372 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3372,'zhTW','釋放他們','釋放他們，$c。即使他們的肉體已經不復存在，蘇塔拉的力量也會讓他們去完成自己的使命。$B$B蘇塔拉祭壇是關鍵。到這裡的北邊去，在洞穴上面的山頂……暮光之錘守衛著一件古器。拿到它，把它放在蘇塔拉祭壇上。$B$B<瀕死的考古學家倒下了。>','到北方去找到被暮光之錘守衛著的神秘的古器。','','去灼熱峽谷找觀火嶺的蘇塔拉祭壇。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3373 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3373,'zhTW','伊蘭尼庫斯精華','當你接觸寶石的時候，一個雄渾的聲音迴響在你的腦際。$B$B“凡人，請聆聽我的請求。我是綠龍軍團的伊蘭尼庫斯，這座被詛咒的神廟的守護者。我的任務是阻止這些巨魔召喚出上古的邪神，但是現在看來，我失敗了。我把我的精華力量注入了這塊寶石中，我能感到自己對夢境的控制正在陷入混亂。請你幫幫我——把這塊寶石放入我的巢穴中，讓那裡的魔法淨化我心智中的汙點，那樣我才能夠安息。”','把伊蘭尼庫斯精華放在精華之泉裡，精華之泉就在沉沒的神廟中，伊蘭尼庫斯的巢穴裡。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3374 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3374,'zhTW','伊蘭尼庫斯精華','你碰觸了一下誓言石，伊薩里奧斯的聲音透過這塊石頭直接和你進行對話。$B$B“一旦你拿起誓言石，就表示你會幫助我，並且準備幫助伊瑟拉的綠龍拯救伊蘭尼庫斯的靈魂。我們所要做的第一件事情，就是將禁錮著伊蘭尼庫斯自由心智的寶石交給我。”$B$B“快一點吧，$N，我們要共同努力來拯救一個值得拯救的靈魂。”','把伊瑟拉巨龍軍團的誓言石和被禁錮的伊蘭尼庫斯精華交給悲傷沼澤的伊薩里奧斯。在那裡你可以決定是否要幫助伊瑟拉的綠龍軍團。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3375 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3375,'zhTW','占卜之瓶','嗯……你還需要一個占卜之瓶？你在開玩笑嗎？你用我給你的那瓶水乾了些什麼？！$C，我們有很多事情要做。那些東西可不是長在樹上隨手可得的！實際上，我希望它們確實如此，因為那樣的話，我只需去隨手摘一個就可以擺平這個問題，因為我手裡已經沒有存貨了！！$B$B為了幫你製作新的占卜之瓶，我需要一瓶法力藥水、一塊煤和一些蜂蜜酒。不要問為什麼，把這些東西給我拿來，然後我就可以幫你製作新的占卜之瓶了。','把一瓶法力藥水、一塊煤和一瓶蜂蜜酒送到鐵爐堡的塔瓦斯德·基瑟爾那裡，用以換取塔瓦斯德的占卜之瓶。','','去鐵爐堡找秘法區的塔瓦斯德·基瑟爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3376 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3376,'zhTW','打斷尖牙!',' $N ，我聽說過你的名字，新來的。或許你可以幫我們一個其他人都做不到的忙。$B$B我們 $R 在這塊土地上建立了自己的家園，但是我們也付出了代價。刺刃峽谷中有一座刺背野豬人的村莊，在他們的首領─尖牙刺鬃酋長的帶領下，一直在與我們交戰，這讓我們的生活變得非常艱難。我要你去取回尖牙刺鬃酋長的首級!$B$B你可以在東邊的峽谷中找到他們那簡陋的村莊，刺鬃酋長就在村子裡面。','把尖牙刺鬃酋長的頭顱交給紅雲台地的勇者風羽。','','去莫高雷找納拉其營地的衛兵維薩羅·風羽。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3377 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3377,'zhTW','艾露恩禱言','你願意幫我的忙嗎？無論怎樣，請先聽聽我的故事吧。','聽薩麥爾講述他的故事。','薩麥爾的故事','去灼熱峽谷找觀火嶺的薩麥爾·月棘。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3378 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3378,'zhTW','艾露恩禱言','你願意幫我的忙嗎？你能找到艾露恩禱言嗎？$B$B就如我所說的，禱言被刻在一塊金色的石板上，那些崇拜它的惡棍把它佔為己有。$B$B如果你能夠找回我的禱言，就把它交給達納蘇斯的阿斯塔利·逐星。如此我才能在遭受如此多不幸之後重新恢復信心，而且更加重要的是，我的祈禱能夠有人聽見，至於我是否能被寬恕，我根本不關心。','找到艾露恩禱言，然後將其交給達納蘇斯的阿斯塔利·逐星。','','去達納蘇斯找月神殿的阿斯塔利·逐星。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3379 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3379,'zhTW','暗影蛛絲','灼熱峽谷的蜘蛛可以為我們提供暗影蛛絲，這使得它們的商業價值倍增。據我所知，暗影蛛絲在我們的交易中有著很大的需求量。$B$B最近有一批偷獵者來到了這裡，他們隨意地屠殺蜘蛛，根本不關心他們的行為可能造成的長期影響。我給你的第一個任務非常簡單：找到他們……然後終結他們。$B$B到北邊去開始你的搜尋吧。$B$B如果你需要幫助的話，就去和拆毀者談談。','殺死在灼熱峽谷遊蕩的暗影蛛絲偷獵者小隊。尼莉絲認為他們共有5名成員，你的任務就是把他們全都幹掉。','','去找灼熱峽谷的尼莉絲·洛克拉夫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3380 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3380,'zhTW','沉沒的神廟','世界上到處都是不肯安息的靈魂，$N。有些靈魂因為孤獨而被腐化，繼而和一個上古的邪惡力量聯結了起來……$B$B我聽說有一個地下的神廟，那裡遊蕩著極其強大的力量。$B$B如果你想要對這個被稱作失落的神廟的地方有更多瞭解的話，就去找一個名叫瑪爾馮·瑞文斯克的地精吧。他曾經研究過許多古代遺蹟，我最後一次聽到他的訊息時，他正從從棘齒城出發去塔納利斯沙漠研究巨魔的遺蹟。','到塔納利斯找到瑪爾馮·瑞文斯克。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3381 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3381,'zhTW','會見主人','啊，一個年輕的$R來到了薩納斯的面前。多麼美妙的一天啊！您的大駕光臨令我誠惶誠恐。謝謝您！$B$B啊……請不要傲慢地把這些讚美之詞真的當作一種恭維。讓我們有話直說了吧：我不喜歡你。但是我們之間的關係如何並不重要——重要的是我的主人怎麼看待你。$B$B給我帶來一些角鷹獸的羽毛，我就向他引薦你。他曾吩咐我帶那些有價值的旅行者去見他。','如果你想要見到薩納斯的主人，就把2根完好無損的角鷹獸羽毛交給他。','','去找艾薩拉的薩納斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3382 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3382,'zhTW','危難中的船長','當時我們正在找一個安全的港口下錨，但是日落還不到一個小時，他們就突然發起了攻擊……那些該死的納迦！$B$B我不知道他們在找什麼，但是他們顯然是沒找到他們要的東西——納迦們已經回來過一次了。我的偵查兵在山谷的入口守著，以便在他們下次發動攻擊的時候及時通報我們。$B$B很抱歉把你捲了進來，$N，但是現在的情況已經不在我的掌控之中了。$B$B你做好戰鬥的準備了嗎？','幫助瓦妮莎·貝蒂斯船長、她的船員和地平線輕帆號上的乘客抵禦納迦的攻擊。瓦妮莎·貝蒂斯船長必須存活。','幫助瓦妮莎·貝蒂斯船長抵禦納迦的攻擊','去找艾薩拉的瓦妮莎·貝蒂斯船長。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3383 AND `locale` = 'zhTW';
