INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3442,'zhTW','無瑕之焰','你做出了正確的決定，$N。$B$B我們必須對敵人的要害下手，除掉那四座哨塔。$B$B一旦這四座塔都化為灰燼，我們就可以在他們反應之前發動攻擊。$B$B你需要合適的工具來點燃防禦塔，而製作這樣的工具就需要合適的材料。$B$B給我弄四份烈焰之心和四份傀儡之油來，然後我就會給你製作出一把燃燒著無瑕之焰的火炬。$B$B在這片土地上的傀儡和元素生物身上找找吧。','收集4份烈焰之心和4份傀儡之油，然後把這些東西交給卡拉然·溫佈雷。','','去灼熱峽谷的大熔爐找卡拉然·溫佈雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3443 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3443,'zhTW','鑄造火炬杆','為了承載無瑕之焰，我們需要一根杆子和一隻箱子，你必須首先從杆子入手。$B$B大熔爐的黑鐵工頭和黑鐵奴隸販子使用附魔過的瑟銀作為武器，那是一種很堅硬的合金。如果你可以給我弄八把瑟銀匕首來，我就能將它們熔解並鑄成一根杆子。','給卡拉然帶去8把瑟銀匕首。','','去灼熱峽谷的大熔爐找卡拉然·溫佈雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3444 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3444,'zhTW','石環','我曾經進入到沉沒的神廟中的那個充滿邪惡氣息的房間，那裡的惡魔會殘忍地殺死每個進入房間的冒險者……我在那些滿是泥濘的房間裡艱難前進，差點就找不到出來的路了。我只記得自己蹣跚地穿過一個圓形的房間，房間裡到處都是毒蛇塑像……$B$B最後，我發現了一塊圓石，上面印著相同的毒蛇標記，我把它打包運到棘齒城的車間去了。去把它取回來，也許我能讓你知道更多的資訊。','到棘齒城去，從瑪爾馮·瑞文斯克的車間裡取回石環。','','去塔納利斯找破碎石柱的瑪爾馮·瑞文斯克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3445 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3445,'zhTW','沉沒的神廟','我聽說有一個地方被埋在地底深處，它是被一個我聞所未聞的強大力量沉入地下的。$B$B如果你想要對這個沉沒的神廟有更多瞭解，就去找一個名叫瑪爾馮·瑞文斯克的地精吧。就像特洛亞斯和我一樣，他也探索過許多人跡罕至的地區。聽說他離開了在棘齒城的家，前往塔納利斯研究巨魔遺址去了。$B$B祝你好運，我好久都沒有他的訊息了。','到塔納利斯找到瑪爾馮·瑞文斯克。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3446 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3446,'zhTW','深入神廟','在神廟裡，我發現一間有著六個陽臺的圓形房間，每個陽臺的邊緣都有一尊毒蛇塑像。我感到好奇，就推動了其中的一個，隨即發現這是個陷阱！我差點在爆炸中丟了性命。我躺在臺階上往下看去，注意到在房間的底部還有一尊塑像，那好像是是什麼神的祭壇……哈卡祭壇？似乎是這個名字。$B$B我認為這祭壇就是秘密所在——你必須把這個東西帶到沉沒的神廟中的那個祭壇上去……','在悲傷沼澤沉沒的神廟中找到哈卡祭壇。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3447 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3447,'zhTW','雕像群的秘密','我的記憶有些模糊了，但是我會盡量把我能回憶起來的細節都告訴你。雖然沉沒的神廟中的雕像群充滿危險，但我相信它們正是找到一筆巨大財富的鑰匙。$B$B你可以在主祭壇上啟用一系列光芒。我認為如果你能搞清楚出這些光代表著什麼，或許你就能解開那座大廳中隱藏著的秘密。$B$B但是我要警告你，$N。神廟中潛伏著可怕的惡魔。它們會忠心地守護那些有價值的東西……','到沉沒的神廟去，揭開雕像群中隱藏的秘密。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3448 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3448, 'zhTW', '委以重任', '最近我一直在負責調查艾薩拉地區，那片美麗的土地曾經是精靈的故鄉，他們曾在此研習魔法。現在這兒變得非常危險，但是這並不能阻止我們搜尋每一寸土地來尋找我們的歷史。我的同伴泰摩爾對這樣的事情特別感興趣，因此他願意幫助我調查艾薩拉。在城裡的秘法大廳右邊有一間小房子是他的。', '跟鐵爐堡的泰摩爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3449 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3449, 'zhTW', '秘法符文', '秘法曾經跟月神伊露恩一樣，受到某些精靈的尊崇。他們中最厲害的法師發明了符文跟石板，記錄下秘法的規則和他們對事物的研究成果。他們把這些都公開讓所有人一起思考。$B$B我非常想要這些來自埃達拉斯廢墟的符文拓片。我將會提供工具來幫助你取得拓片，但是你可以自己決定要不要去找這些石板。凡是要小心，對埃達拉斯廢墟感興趣的可不止探險者協會。', '在前往艾薩拉南部半島處的小島之前，使用繪圖工具獲取貝薩瑪拉符文、辛耶爾符文、瑪寇里符文和塞爾哈符文的拓片，然後通知駕駛員希格斯·熔火去拾取這些拓片。', '', '去找艾薩拉的駕駛員希格斯·熔火。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3450 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3450, 'zhTW', '簡單的接收任務', '我想把這些拓片送到我的塔裡去，但是你不必親自跑一趟，我會把它們空運到艾薩拉。希格斯·熔火欠我幾個人情，而且他馬上就會到這個地區來—因為他被派遣到海岸邊巡邏。在你離開之前，別忘了去跟他談談。他會給你一支閃光彈發射器用於發送信號。當你拿到拓片之後就到他指定的地點去發信號給他，這樣他就能把拓片安全地送到我的塔裡了。現在他應該在軍事區的機棚裡。', '與鐵爐堡的希格斯·熔火談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3451 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3451, 'zhTW', '信號發射器', '啊，是泰摩爾派你來的，是嗎?對，我還欠他人情呢。怎麼?哦，那個小惡魔，是的，我當然可以幫助他。你需要一把信號槍和一個合適的地點……就行了。在艾薩拉南部的半島附近有一座小島，我們在那裡已經有個起落台。拿著這把信號槍，在那個地方使用它，我就能看見信號，然後過去接收那個……隨便他想要什麼東西了。', '與鐵爐堡的希格斯·熔火談話，從他那獲得一支標準型信號槍。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3452 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3452,'zhTW','烈焰之盒','我們還需要最後一部分來完成火炬。$B$B在西北方的山腳下，你可以找到暮光之錘的營地。據說他們攜帶著特殊的徽章和石像，用以表示對神明的崇敬。這些徽章和石像具有強大的魔法能力，足以製成一個魔法容器。將拉格納羅斯符記交給我，我將試著從裡面提取魔法，然後製造一個容器。','找到一個拉格納羅斯符記，把它交給卡拉然·溫佈雷。','','去灼熱峽谷的大熔爐找卡拉然·溫佈雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3453 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3453,'zhTW','懲戒火炬','給我一點時間來拼合這些碎片，然後對它進行必要的附魔。','等待卡拉然·溫佈雷完成懲戒火炬。','製造火炬','去灼熱峽谷的大熔爐找卡拉然·溫佈雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3454 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3454,'zhTW','懲戒火炬','現在，火炬必須與它的擁有者建立聯結。拿起火炬，$N。','拿起懲戒火炬。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3461 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3461,'zhTW','向法師泰摩爾回覆','泰摩爾並沒有給我什麼可以付你報酬的東西，我建議你回鐵爐堡去的時候好好跟他交流一下。我想他還在秘法區，去找他吧，他會付你報酬的。$B$B再次感謝你幫助他擺脫困境，祝你好運。$B$B哦，我不需要繪圖工具包啦，你為什麼不順便把它還給泰摩爾呢？','到鐵爐堡去，將法師泰摩爾的繪圖工具包還給他。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3462 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3462,'zhTW','侍衛瑪特拉克','跟我的特使——侍衛瑪特拉克談談吧,他會進一步指導你使用懲戒火炬。','與侍衛瑪特拉克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3463 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3463,'zhTW','燒掉它們！','聽好了，$N。雖然我們無法摧毀那四座哨塔，但是你可以使用懲戒火炬點燃它們，這種火焰是任何元素或力量都沒法熄滅的。$B$B在哨塔燃燒的過程中，沒有什麼部隊可以駐紮在裡面，這樣他們的第一道防線就失效了。$B$B你必須進入每一個塔樓，用懲戒火炬把它們燒掉。要小心黑鐵矮人的精英哨兵，$N。','使用懲戒火炬點燃北部、南部、東部和西部的哨塔。','','去找灼熱峽谷的侍衛瑪特拉克。','點燃西部哨塔','點燃南部哨塔','點燃東部哨塔','點燃北部哨塔',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3481 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3481,'zhTW','開啟箱子…','箱子似乎上鎖了。','開啟箱子。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3482 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3482,'zhTW','佈滿孔洞的黑匣子*','這個盒子的表面已經非常老舊了,因為它他酸中泡了很久了--它一定在那隻巨大的禿鷲胃裡呆了很久,$B$B把盒子翻過來,在它底部有個符記,在這符記下面寫的是:\\"Kr..el Ko.l..ard \\"','把這個盒子帶給克拉維爾','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3483 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3483, 'zhTW', '信號發射器', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3501 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3501,'zhTW','多多益善','儘管你可能找不到純淨無暇德萊尼水晶，但是在你探索這片土地的過程中，一定可以找到若干有瑕疵的德萊尼水晶碎片。$B$B庫米沙是否可以利用這些碎片返回家園，這還很難說，但是這些碎片可以為德萊尼人所用。$B$B把你發現的有瑕疵的德萊尼水晶碎片都交給我，我會給你報酬的。','將有瑕疵的德萊尼水晶碎片交給庫米沙，你就可以得到相應的回報。','','去找詛咒之地的收藏家庫米沙。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3502 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3502,'zhTW','德萊尼的垃圾…','嗯，見識了你的貪婪之後，我感到噁心。$B$B不管怎樣，我可不會跟你的貪慾糾纏不清。$B$B你每交給我一塊有瑕疵的德萊尼水晶碎片，我就給你更多的垃圾。我的垃圾都被你收走了。在德拉諾，我們稱這種情況為“雙贏”。','將有瑕疵的德萊尼水晶碎片交給庫米沙。詛咒之地的任何怪物都有可能攜帶著這樣的碎片。','','去找詛咒之地的收藏家庫米沙。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3503 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3503,'zhTW','見到主人','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3504 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3504,'zhTW','叛徒','這個毫無誠信可言的女人！她只能配得上這個稱呼——罪有應得！$B$B我可能犯下了一個嚴重的錯誤，$N。我相信了一個血精靈。更糟糕的是，她還是個女的！$B$B她聲稱艾薩拉那裡埋藏著數不盡的財富……我派了一些戰士保護她去那裡，滿以為我可以有所斬獲。但是，到頭來我卻被耍了——她把他們都殺掉了。$B$B我要報仇，$N，但是我手邊已經沒有可以派遣的人了。到哈達爾營地北邊的瓦羅莫克去找阿格圖，他會告訴你更詳細的情況。','把這封給阿格圖的密信交給艾薩拉的阿格圖·血拳。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3505 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3505,'zhTW','叛徒','我的計劃是這樣的：$B$B我們從艾薩拉的北部半島開始，沿著懸崖的南部開始進攻她的工人。把他們都幹掉，讓他們知道當叛徒的後果。$B$B先別管她——她大部分時間都跟她的護衛一起在艾薩拉進行搜尋工作。在殺死她的工人之後，我們在去考慮怎麼收拾她比較好。我們應該先仔細偵察一番，也許有一些可以激怒她的東西。','殺死10個血精靈搜尋者和10個血精靈勘測員，並找到大法師雷姆托里的營地。一旦你發現了營地，就去找到某個對她極為重要的東西，以用於激怒她，讓她與你戰鬥。','找到大法師雷姆托里的營地','去艾薩拉找薩拉斯營地的卡多雷召喚寶典。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3506 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3506,'zhTW','叛徒','經過思考，你對眼下的情形已經有了大致的瞭解，你的臉上浮現出一絲笑容：也許摧毀水晶將使那些殺死眾多獸人並背叛貝爾戈洛姆的血精靈方寸大亂？$B$B你繼續翻譯著文字和圖片，並瞭解到其中一塊水晶就在這個石陣的製造者身上——其餘的則在更為邪惡的生物手中。$B$B你合上書本，開始考慮要摧毀哪塊水晶。','摧毀大法師雷姆托里攜帶的奧術聚焦水晶並殺死她。然後把她的腦袋交給艾薩拉的阿格圖·血拳。','','去找艾薩拉的阿格圖·血拳。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3507 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3507,'zhTW','叛徒','回到奧格瑪的貝爾戈洛姆那兒去，他肯定想要好好看看這個女人的腦袋！我們很快就回去。$B$B啊，這真是一個好日子。謝謝你的幫助，$N。','與奧格瑪的貝爾戈洛姆·石槌談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3508 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3508,'zhTW','破壞結界','你是個有勇無謀的$r，$N。你這樣的$r具有令人敬佩的品質——在希望渺茫的情況下盲目地進行戰鬥。我會協助你，即使你只能殺掉拉瑟萊克的一個小小的爪牙，我也會協助你。$B$B要破壞拉瑟萊克的結界要花些時間，還需要稀有的神器。$B$B你先別急，我必須首先進行一次啟迪儀式，我收集的資訊將有助於我們鑄造威力強大的武器。','等待洛拉姆斯完成啟迪法術。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3509 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3509,'zhTW','惡魔之名','要除掉惡魔之王和他的爪牙，只有一個方法：鑄造一件刻有他真名的強大武器。$B$B這件武器鑄造完成之時，就是惡魔之王的死期。$B$B有一個名叫亞考羅克的低階神祗居住在艾薩拉，你必須找到他，但是如果他發現了你，那麼他的爪牙就會不顧一切地想要殺死你。$B$B毫無疑問，你不費點力是沒法成功的。','與艾薩拉的亞考羅克談一談。你應該在海邊搜尋亞考蘭神殿。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3510 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3510,'zhTW','惡魔之名','她殺了我的孩子，她稱自己為海洋的統治者。她是個虛偽的神。殺死她，把她的所有頭顱都帶回來。$B$B這樣，你就能得知你要尋找的名字，並得到與其同樣重要的東西。$B$B她的名字叫做赫塔拉。$B$B<亞考羅克指向西南方。>$B$B去吧！','殺掉赫塔拉，將染血的赫塔拉頭顱、破碎的赫塔拉頭顱和淤血的赫塔拉頭顱交給亞考羅克。','','去艾薩拉找亞考蘭神殿的亞考羅克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3511 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3511,'zhTW','惡魔之名','我曾許諾將惡魔之王汙染者拉瑟萊克的名字告訴你。不過，我得先為你的旅程準備一些至關重要的東西。$B$B你要鑄造的武器必須有調劑才能製成。給我一點時間，讓我從這些頭顱中弄點血液出來。$B$B<亞考羅克用他那巨大的手掌擠壓頭顱，壓出了血液。>$B$B將調劑交給洛拉姆斯，告訴他，那個惡魔的名字是拉瑟萊克。','將調劑交給洛拉姆斯·薩里比迪斯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3512 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3512,'zhTW','幫助伊蘭尼庫斯','$N，第一步，我們將設法透過寶石與伊蘭尼庫斯交談。現在他正處於半睡半死的不穩定狀態，並受到噩夢的困擾。儘管你給我的精華已經被嚴重汙染，但我們還是有機會跟他溝通的。$B$B到冬泉谷東部的冰川地帶去尋找我們的盟友，靈語者阿姆布蘭希。他可以與死者進行交談——儘管伊蘭尼庫斯並沒有真正死去，但阿姆布蘭希依然會對我們有所幫助。','到冬泉谷的東部地區去，與靈語者阿姆布蘭希談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3513 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3513,'zhTW','符文卷軸','這份看起來很正式的卷軸被一條銀色絲帶緊緊地裹著。你覺得會有什麼人對此感興趣，但是這人是誰呢？$B$B在梣谷邊界以北有一處前哨站，如果卷軸上的資訊與暗夜精靈有關，那麼你就應該把它送到那兒去。','將符文卷軸帶到貧瘠之地的北部警戒塔去。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3514 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3514,'zhTW','部落的示威','這份卷軸是在石爪峰的樹妖琳薩瑞爾那兒得來的，她是猛禽洞穴的頭目。$B$B她不會再與帶著這份卷軸的信使有任何聯絡了，哈哈……但是我們必須保持警戒。部落不會允許此地再出現聯盟的信使。$B$B$N，到猛禽洞穴去，殺死琳薩瑞爾，然後給他們一個所有人都能看到的訊號。帶上部落的旗幟，把它插在猛禽洞穴裡，這樣他們就不會急於派出另一個信使來到我們的地盤上送死了。','殺死猛禽洞穴的領袖琳薩瑞爾。','','去貧瘠之地找摩爾沙農場的卡德拉克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3515 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3515,'zhTW','暫無內容','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3516 AND `locale` = 'zhTW';
