INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3541,'zhTW','傑斯雷蒙的石版','我在奧格瑪有個主顧，他住在暗巷區。如果你不熟悉那裡，那麼你是很難找到他的，不過如果你到那個區域中最高的那座建築物裡去，就應該能找到他。$B$B不過呢，你可別讓全卡利姆多的人都知道他在哪裡，他在幹什麼——這對咱們倆都沒好處。$B$B為了這塊辛耶爾石板，他會付給咱們一大筆錢的。我不知道他為什麼如此在乎這塊石板，不過你真該看看他聽到這塊石板的訊息後有多激動。','將辛耶爾石板交給奧格瑪的傑斯雷蒙。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3542 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3542,'zhTW','安德隆·甘特的石版','安德隆·甘特是我的下一個主顧。他通常待在幽暗城裡……就在鍊金房附近。當我們談到石板的用途時，他就有些藏不住話。顯然幽暗城中的某些法師想要學習上層精靈所使用的魔法。他們認為這石板能對他們有所幫助。瑪科裡曾以善於召喚各種生物——特別是元素生物而聞名。$B$B把瑪科裡石板給他帶過去，然後回到我這兒來取你的報酬吧。','將瑪科裡石板交給幽暗城的安德隆·甘特。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3561 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3561,'zhTW','大法師克希雷姆的石版','最後這塊石板要交給一個非常危險的傢伙，$N。聽著，比起我先前讓你接觸的那些人，我對他可以說是非常不信任的。$B$B大法師克希雷姆在艾薩拉的一處山頂上建了座高塔。他是個人類，但是他的行為跟我見過的……或是殺掉的那些人類大不相同。他充滿了力量，我可不敢問他為什麼想要這塊石板。$B$B他來找過我，但是他跟我說，當我準備就緒時，他的侍衛薩納斯會帶我到塔裡去。到北邊去找薩納斯吧。','將塞爾哈石板交給艾薩拉的大法師克希雷姆。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3562 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3562,'zhTW','瑪加薩的報酬','把這張便箋交給傑迪加,告訴她當她回來的時候就到這兒來領取報酬。我對她的成績很滿意。$B$B快去吧，$N。告訴你的主人，我在這兒等她。','將瑪加薩的便箋交給艾薩拉的傑迪加。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3563 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3563,'zhTW','傑斯雷蒙的報酬','把這封信交給傑迪加，告訴她，我們的交易很成功，而且我對她很滿意。$B$B讓她馬上返回奧格瑪，傑斯雷蒙會確保她的安全。$B$B也許將來我還需要你的幫助，$N。','將傑斯雷蒙的便箋交給艾薩拉的傑迪加。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3564 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3564,'zhTW','安德隆的報酬','拿著……這個……<嗝>交給傑迪加。祝你好運！','將安德隆的便箋交給艾薩拉的傑迪加。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3565 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3565,'zhTW','克希雷姆的報酬','什麼？哦，你的報酬。當然。$B$B拿好了，趕快走吧。我想傑迪加正在耐心地等你回去呢。','將克希雷姆的便箋交給艾薩拉的傑迪加。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3566 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3566,'zhTW','奧比斯頓','這……這……這是個陷阱。$B$B原諒……我。$B$B殺掉這個該死的混蛋……為我們殺掉他……為了索里奧斯。','殺死黑衣拉索裡克和奧比斯頓，帶著黑衣拉索裡克的頭顱和奧比斯頓的心臟回到鐵爐堡的索里奧斯那兒。','','去找鐵爐堡的索里奧斯館長。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3567 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3567,'zhTW','登高','','','','','','','','',0);
