INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3568, 'zhTW', '墮落之水', '看見我後面的那個看起來隨時都可能病倒的牛頭人了嗎?她前段時間去過艾薩拉。她說自己在經過埃達拉斯廢墟時受到納迦的攻擊，而且負了傷。$B$B在擊退一些納迦之後，她在海灘休息了一下，並飲用了海潮之池中的水，現在她感覺有些噁心……$B$B我要找出她飲用的水。拿著這個盒子，我在裡面放了一些空瓶子，用它們到各個海潮之池中收集一些水，然後回來。', '在艾薩拉的埃達拉斯廢墟旁的海潮之池中收集4瓶水，然後回到藥劑師科雷那兒。', '', '去找藥劑師科雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3569 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3569,'zhTW','墮落之水','把這個交給瑟爾薩。也許她可以痊癒……也許不能。反正要在她喝下後才能知道結果。','將科雷的藥劑交給幽暗城的瑟爾薩·風歌。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3570 AND `locale` = 'zhTW';
