INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3633,'zhTW','地精工程學','高階的工程學有兩個分支：侏儒派和地精派，顯然，地精工程學是所有明智的技師都會選擇的一派，用華麗的高爆炸藥和機械裝置統治世界！$B$B好吧，$N，讀一下這本手冊。如果你想要學習地精工程學，就把這個交給加基森的尼克斯·斯普克斯賓。請記住，一旦你加入某一派，就永遠也不能再加入另一派了，所以在你完成他交給你的任務之前要三思。','如果你想要對地精工程學有更多瞭解，就把工程學教材交給加基森的尼克斯·斯普克斯賓。','','','','','','',0);
