INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4120,'zhTW','墮落的力量','作為獵人，我總是努力來模仿我對手的長處。知己知彼，百戰不殆，$N$B$B在梣谷北部的費伍德森林中生活的野獸們都被惡魔的能量所感染，熊和狼都已經變得瘋狂，而且我相信它們的力量也變得更加強大了。$B$B出發吧，$N。去費伍德森林面對那些野獸。如果你和我想象中的一樣強大，就去那裡鍛鍊自己吧。','菲拉斯莫沙徹營地的塔羅·刺蹄要你去費伍德森林殺掉12頭怒爪灰熊和12頭魔爪掠奪者。','','去菲拉斯找莫沙徹營地的塔羅·刺蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4121 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4121,'zhTW','押送囚徒','你真的以為可以把我押出去嗎？你難道以為你能穿越戒備森嚴的黑石要塞，而且還能神不知鬼不覺地帶走一個對他們來說如此重要的人嗎？$B$B你死定了！','押送你的囚犯格拉克·洛克魯布。穿過燃燒平原和黑石山脈，一直走到灼熱峽谷。$B$B雷克斯洛特曾經告訴過你，他會讓他的人等在黑石山脈的另外一邊準備接收格拉克。$B$B另外，你還要把瑟銀鐐銬一併還給雷克斯洛特。','押送囚徒','去荒蕪之地找卡加斯的雷克斯洛特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4122 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4122,'zhTW','格拉克·洛克魯布','我追蹤他穿過灼熱峽谷，穿過群山，進入燃燒平原。在那裡，我親眼看見那個叛徒——我說的是格拉克·洛克魯布——把我們的詳細行動計劃交給了黑石獸人。$B$B他現在仍然在燃燒平原，在黑石獸人的保護之下高枕無憂——至少他自己是這麼以為的。$B$B拿著這些鐐銬，$N。找到格拉克，給他戴上鐐銬，然後把他帶出黑石山。成功之後，我必定會重賞你。','到燃燒平原去找到格拉克·洛克魯布。你回憶起雷克斯洛特曾經提起過，格拉克應該是在一座大型的黑石要塞中。$B$B當你找到格拉克·洛克魯布之後，用瑟銀鐐銬把他銬起來，然後將其帶回灼熱峽谷。雷克斯洛特會讓他的部下等在那裡接應你。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4123 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4123,'zhTW','山脈之心','多年以來，我都在追尋一塊特殊的寶石。它的名字是山脈之心，個頭大概和你的拳頭差不多！黑鐵矮人把它鎖在他們的一個房間裡，雖然我想盡了辦法，但他們就是不賣給我。$B$B所以我只好訴諸暴力了。$B$B到黑石深淵底部的寶庫裡去，擊敗那裡的守衛，把山脈之心給我搶出來。你所要做的就是擊敗衛兵杜格瑞普，不過只有在你開啟房間裡所有的保險箱之後他才會出現！$B$B祝你好運。','把山脈之心交給燃燒平原的麥克斯沃特·尤博格林。','','去燃燒平原找烈焰峰的麥克斯沃特·尤博格林。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4124 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4124,'zhTW','失蹤的信使','我的同事基恩諾·火花正在尋找信使的下落，以及他身上攜帶的包裹。那個信使已經失蹤一個星期了，我們所有的搜尋行動都徒勞而返，因此現在我不得不宣佈：信使已經失蹤了。$B$B如果你有時間的話，請去跟基恩諾談談。他應該在要塞裡——也許在他自己的房間裡。','和羽月要塞的基恩諾·火花談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4125 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4125,'zhTW','失蹤的信使','拉斯卡爾這個信使出發去薩蘭納爾已經快一個星期了。他對菲拉斯瞭如指掌，自從羽月將軍率領遠征軍踏上這片土地的時候，他就和我們在一起了。我知道他這次是想要划船沿著海岸前進，然後橫穿菲拉斯的南部區域以避開部落的營地。$B$B我找不到他的船，但是也許你可以。也許那艘船被藏起來了，也許它已經沉沒了。不管怎麼樣，只要找到船，就有可能找到他的線索。如果你找到什麼東西的話，請趕快告訴我。','找到信使的小船，你應該在菲拉斯的南部海岸線上展開搜尋。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4126 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4126,'zhTW','霍爾雷·黑鬚','在萬惡的霍爾雷·黑鬚的帶領下，那些黑鐵矮人偷了我們的雷霆啤酒的配方，那些混蛋！他們不配得到如此美味的佳釀！$B$B$N，我有個艱鉅的任務要交給你。去燃燒平原的黑石深淵，摧毀找到的所有裝有雷霆啤酒的桶，然後把雷霆啤酒的配方帶回來！$B$B求求你了，你一定要把配方帶回來，即使要把黑石深淵翻個底朝天你也一定要找到它。','把遺失的雷酒秘方帶給卡拉諾斯的拉格納·雷酒。','','轉至丹莫洛，去找卡拉諾斯的拉格納·雷酒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4127 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4127,'zhTW','船隻的殘骸','你的手沿著泥漿滑過，手指碰到了一把刀柄。它看起來護理得不錯，而且肯定是曾經乘坐過這艘船的人把它給弄丟了。這可能和失蹤的信使有關。$B$B你抓住這把刀，想起羽月要塞的基恩諾·火花要你把任何能找到的線索都報告給他。然而，你有一種感覺，在水中並不是只有你一個人……','回到羽月要塞，給基恩諾·火花看看你找到的這把被丟棄的小刀。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4128 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4128,'zhTW','拉格納·雷酒','你好，$N。我聽說拉格納·雷酒正因為有人偷了他的酒而大發雷霆呢。他在找合適的冒險者來幫忙，而且報酬豐富。$B$B如果你感興趣的話就去找拉格納談談吧，他在丹莫洛，卡拉諾斯的雷酒釀製廠裡。','和拉格納·雷酒談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4129 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4129,'zhTW','奎恩提斯的技藝','要塞裡有一個名叫奎恩提斯的德魯伊，他有一些……非同尋常的技藝，比如心靈占卜術——透過觸控某件物品揭示與其關聯的歷史。不要問我他是怎麼做到的，我認為那是一種我不懂也不願去弄懂的魔法。然而我確實知道兩件事：首先，那把戲的效果確實不錯；其次，他還欠著我的債。$B$B把小刀交給小樹屋裡的奎恩提斯，替我告訴他……如果他把他的本事用在那把刀子上的話，他跟我打牌時欠下的債務就一筆勾銷。','把被丟棄的小刀交給羽月要塞的奎恩提斯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4130 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4130,'zhTW','心靈占卜術','我仍然有些暈，不好意思。嗯，我看到了一些有用的影象。$B$B拉斯卡爾從小船裡拿了兩隻皮袋子，然後上了岸；然而，他又回到了小船那裡。我看到了豺狼人……他遇到了豺狼人——那些被稱作木爪豺狼人的傢伙。他看起來很著急——看上去有些恐懼——似乎是在躲避什麼。他甚至沒有注意到身後的水元素……就是這些了。$B$B我得休息一下，對不起，$N。把我看到的東西告訴基恩諾，他需要知道這些。','和羽月要塞的基恩諾·火花談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4131 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4131,'zhTW','木爪豺狼人','拉斯卡爾也許是被我們的那些豺狼人“朋友”抓去了，雖然直覺告訴我事情並不是這樣的。但是你最好還是從它們那裡開始搜尋。$B$B我希望我知道該幹什麼，現在我現在能說的只有“去搜尋木爪豺狼人的營地，現在就出發。”我知道豺狼人會把他們搶到的東西藏起來，而且為何這些東西互相爭鬥。也許是它們搶了奎恩提斯所說的包裹。我在搜尋過程中沒有去跟豺狼人作戰，不過既然奎恩提斯有這種預感，我們就必須採取行動了。','在菲拉斯南部地區的木爪豺狼人營地裡尋找信使的下落或者信使的物品。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4132 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4132,'zhTW','行動：殺死安格弗將軍','迄今為止你一直表現得很好，$N。現在你應該去完成你的最後一個任務了。$B$B黑鐵矮人中的安格弗將軍負責策劃了對K.E.F.109師的攻擊，並殘殺我們的無數士兵——正義必須得到伸張！$B$B這無疑是一個極端艱難的任務，但是成功之後，你也會獲得豐厚的獎勵。','到黑石深淵去殺掉安格弗將軍！當任務完成之後向軍官高圖斯覆命。','','去荒蕪之地找卡加斯的軍官高圖斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4133 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4133,'zhTW','薇薇安·拉格雷','暗法師薇薇安·拉格雷需要你的幫助。她在荒蕪之地，就在獸人的卡加斯前哨基地裡，她在那裡對有關黑鐵矮人的事情進行調查。$B$B去和薇薇安談談吧，她正在等著你。','與卡加斯的暗法師薇薇安·拉格雷談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4134 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4134,'zhTW','遺失的雷酒秘方','有傳言說黑鐵矮人霍爾雷·黑鬚偷到了一種酒的配方。這種被稱作雷霆啤酒的飲料會使飲用者獲得無窮的力量和勇氣。我們希望能研究一下這種飲料。也許我們可以開發它的其它功能……能夠幫助我們被遺忘者達成目標的功能。$B$B我說了被遺忘者的目標？我的意思是……整個部落的目標，我當然是這個意思！$B$B到黑石深淵去找到雷霆啤酒的配方，把它給我帶回來。','把遺失的雷酒秘方交給卡加斯的薇薇安·拉格雷。','','轉至荒蕪之地，去找卡加斯的暗法師薇薇安·拉格雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4135 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4135,'zhTW','痛苦深淵','在揹包中有兩樣東西：第一件是要送到薩蘭納爾去的包裹，第二件是匆忙書寫的便箋。$B$B便箋上面寫著在豺狼人營地南邊有一處被稱作痛苦深淵的地方，那裡有許多邪惡的蟲類生物。作者認為他應該親自去調查一番，因為他覺得那是對整個菲拉斯的威脅。便箋的末尾署了名，“羽月要塞的拉斯卡爾”。$B$B看來你最終找到了拉斯卡爾的下落。','現在你已經知道了拉斯卡爾的去向，那麼你最好到痛苦深淵去尋找他，或者至少是他的屍體。根據便箋上的資訊，那個地方應該在木爪豺狼人營地的南邊。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4136 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4136,'zhTW','雷布里·斯庫比格特','我的兄弟雷布里就是我們家族的恥辱，他拿走了我們所有的錢，然後揮霍一空。$B$B藏寶海灣的大財主裡維加茲剛剛開始懸賞雷布里的腦袋，這對他來說可能有些糟糕，但我簡直無法形容斯庫比格特家族在得知這個訊息之後有多高興了！我們的小雷布里終於有點價值了！$B$B但是現在他躲在黑石深淵的深處。請你幫忙找到他，然後把他帶到我這裡來！$B$B如果他不願意來的話，那麼也好……至少把他的頭給我提來。','把雷布里的頭顱交給燃燒平原的尤卡·斯庫比格特。','','去找燃燒平原的尤卡·斯庫比格特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4141 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4141,'zhTW','穆爾金和拉瑞安','看見那裡的拉瑞安了嗎？就是他的錯導致我們不得不待在這裡！$B$B我告訴過他我們走錯路了，但是他會聽我的嗎？你能相信他居然不和我說話嗎？好吧，除非他改變主意，否則我們就準備看場好戲吧。$B$B你注意到周圍那些像植物一樣的生物了嗎？它們確實很麻煩，但是我認為只要經過正確的訓練，我就可以讓它們聽命於我。$B$B首先，我需要一些樣品來進行研究。你可不可以幫我收集一些呢？','從安戈洛爾環形山的血瓣花猛擊者和血瓣花掠奪者身上收集20個血瓣花，然後向穆爾金回覆。','','去找安戈洛環形山的穆爾金。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4142 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4142,'zhTW','造訪格雷甘','我不能完全確定這是由什麼構成的，$N。這些植物……好像具有一些最簡單的智慧。$B$B雖然我並不是這方面的專家。但是我知道有人一定知道答案！$B$B到菲拉斯去找我的一個名叫格雷甘·山酒的朋友，他是這方面的專家。$B$B我敢肯定格雷甘能幫我們，你應該可以在菲拉斯的野外找到他，他可不是那種喜歡生活在大城市裡的傢伙。','把血瓣花交給菲拉斯的格雷甘·山酒。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4143 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4143,'zhTW','邪惡之霧','我跟你說實話吧，$N，在我的旅途生涯中，我從來沒有看見過這樣的植物。也許我應該去一下環形山……$B$B不管怎麼樣，我想我知道穆爾金正在找什麼東西——阿塔萊之霧。那是種恐怖的東西，而且非常難找，但是穆爾金需要這種材料來控制那些小怪獸。$B$B你應該去悲傷沼澤裡的那座沉沒的神廟，那裡的潛伏者、黑暗蟲和泥漿怪身上都有阿塔萊之霧。祝你好運，$N！','收集5份阿塔萊之霧的樣本，然後向安戈洛環形山的穆爾金覆命。','','去找安戈洛環形山的穆爾金。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4144 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4144,'zhTW','血瓣花苗','','','','去找安戈洛環形山的穆爾金。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4145 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4145,'zhTW','拉瑞安和穆爾金','看到那邊的穆爾金了嗎？就是他的錯使我們迷路了！$B$B我知道正確的路，但是他堅持說他知道一條捷徑，然後我們就到了這裡！$B$B更糟的是，現在他還不斷用他那些瘋狂的植物來煩我。我很生氣，所以我原本打算不和他說話了，但是這些該死的植物實在是太多，我沒有足夠的能力來清除它們。$B$B那麼，首先讓我們來減少這些東西的數量吧，去幫我幹掉一些血瓣花鞭笞者和血瓣花捕獸者。','為馬紹爾營地裡的拉瑞安殺掉5個血瓣花鞭笞者、5個血瓣花捕獸者、5個血瓣花掠奪者和5個血瓣花猛擊者。','','去安戈洛環形山找馬紹爾營地的拉瑞安。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4146 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4146,'zhTW','除草器的燃料','你運氣真不錯，$N！在瑪爾馮離開之後，我一直都在進行一些實驗，其中的一項就是研究一種專殺除草器。只要進行一些調整，它就可以幫助你輕鬆地除掉那些血瓣花。$B$B我可以給你一部這種除草器的樣品，但是你仍然得自行收集所需的燃料。你可以在沉沒的神廟找到你要的阿塔萊之霧，那裡的潛伏者、黑暗蟲和泥漿怪身上都有這種東西。','收集5份阿塔萊之霧的樣本，然後將它們送到馬紹爾營地的拉瑞安那裡。','','去安戈洛環形山找馬紹爾營地的拉瑞安。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4147 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4147,'zhTW','瑪爾馮的車間','我查了查穆爾金到底在幹什麼，結果發現他居然在種植那些該死的東西！$B$B我想現在唯一的解決方法是……不，不是去和他談判……你在想什麼？唯一的解決方法就是以牙還牙！$B$B我需要我的朋友瑪爾馮的幫助，他在棘齒城有個車間。我敢說他一定能造點對我們有用的東西出來。','到棘齒城去，在瑪爾馮·瑞文斯克的車間裡找到他。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4148 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4148,'zhTW','血瓣花除草器','','','','去找安戈洛環形山的拉瑞安。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4161 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4161,'zhTW','卡多雷的食譜','很久以前， $R 被稱作卡多雷，卡多雷的意思是「眾星之子」。瞭解這些歷史對幫助你成為一名真正的 $C 非常重要， $N ，所以好好聆聽我告訴你的故事吧。$B$B卡多雷總是以自己和環境之間的和諧關係而感到自豪，這意味著我只向自然索取生活必需的東西，並且要給自然以友善的回報。這種平衡使我們受益良多， $N 。$B$B去幫我收集7條小蜘蛛腿 -- 不要多，然後回來找我。','收集7條小蜘蛛腿。','','去泰達希爾找多蘭納爾的扎瑞恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4181 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4181,'zhTW','地精工程學','高階的工程學有兩個分支：侏儒派和地精派，請注意我提到地精工程學的唯一原因是因為我是個公正的訓練師。他們喜歡製造一些會爆炸的東西，而且絲毫不關心有什麼東西會被炸到——即使是他們自己。$B$B好吧，$N，讀一下這本手冊。如果你想要學習把自己炸上天的方法，就把這個交給加基森的尼克斯·斯普克斯賓。請記住，一旦你加入某一派，就永遠也不能再加入另一派了，所以在你完成他交給你的任務之前要三思。','如果你想要對地精工程學有更多瞭解，就把工程學教材交給加基森的尼克斯·斯普克斯賓。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4182 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4182,'zhTW','黑龍的威脅','燃燒平原上永遠充滿了爭端。$B$B看看這個地方！我們不知道這些建築到底是怎麼回事，但是我們會永遠記住，在大爆炸之前，這些地方原本都是屬於赤脊山範圍的。$B$B現在的情況真是太糟糕了！我們碰到了一個問題，$N。你也許已經注意到在這道山脊下徘徊的那些龍了。殺了它們，越多越好。去完成這個任務，然後我們再來談談別的。','殺掉15條黑色小龍、10條黑色龍人、4條火鱗龍人和1條黑色幼龍。當你完成任務之後就向赫林迪斯·河角回報。','','去燃燒平原摩根的崗哨找赫林迪斯·河角。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4183 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4183,'zhTW','真正的主人','我們以前總是認為黑石獸人的殘忍是與生俱來的。不過我們在這裡找到的東西卻告訴我們另一個故事。$B$B沒錯，嗜血和對戰鬥的飢渴使他們變成了如今的樣子，但是這一切的幕後主使卻是那些黑龍。我們認為，正是黑龍把憤怒和敵意灌輸給了他們。$B$B把這封信交給所羅門鎮長，他會知道該做什麼的。$B$B<赫林迪斯把一封信交給了你。>','把赫林迪斯·河角的信交給湖畔鎮的所羅門鎮長。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4184 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4184,'zhTW','真正的主人','這真是個可怕的訊息，$N。我們的敵人竟然只是一個更強大的勢力的爪牙，這讓我感到更加氣餒。湖畔鎮不可能抵抗黑石獸人和黑龍的聯手攻擊。如果湖畔鎮陷落了，那麼下一個就是夜色鎮，接下來會是哪裡？閃金鎮？暴風城？$B$B你必須把這個訊息告訴伯瓦爾·弗塔根公爵！如果暴風城不施以援手的話，那麼一切就都完了。','到暴風城去把所羅門的求援信交給伯瓦爾·弗塔根公爵。$B$B伯瓦爾在暴風要塞裡。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4185 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4185,'zhTW','真正的主人','所羅門描繪了一幅恐怖的畫面，但是我們不可能把原本就已經捉襟見肘的兵力再分派一部分去湖畔鎮。我需要確鑿的證據才能採取行動。$B$B和女伯爵卡特拉娜·普瑞斯托談談吧，$N。她是個學識淵博的女性，並且對龍類生物很有了解。她應該可以在這件事情上幫助我們。','與女伯爵卡特拉娜·普瑞斯托談話，然後再與伯瓦爾·弗塔根公爵談話。','女伯爵卡特拉娜·普瑞斯托的建議','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4186 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4186,'zhTW','真正的主人','我現在任命你為暴風城執行代表，$N。$B$B回到湖畔鎮的所羅門鎮長那裡，向他傳達這份命令。','把伯瓦爾的命令交給湖畔鎮的所羅門鎮長。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4201 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4201,'zhTW','愛情藥水','啊，愛情的痛苦！我親愛的羅克諾特下士對我的魅力不來電，他將我無情地拒絕了！這真是令我發狂！$B$B你必須幫幫我！我們魅魔對於愛情瞭如指掌，所以我可以配製一種藥水，用它來融化包圍著羅克諾特心臟的鐵牆。不過我需要一些材料才能配置這種藥水——一種被稱作格羅姆之血的藥草，一塊從艾薩拉的懸崖巨人那裡得到的巨大銀礦，還有從安戈洛的溫泉中取得的水。你可以把水放在這個小瓶裡。$B$B$N，請幫助一個可憐的靈魂追求她的快樂吧！','將4份格羅姆之血、10塊巨型銀礦和裝滿水的娜瑪拉之瓶交給黑石深淵的娜瑪拉小姐。','','去黑石深淵找黑鐵酒吧的娜瑪拉小姐。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4221 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4221,'zhTW','被腐化的迎風花','','','','去找費伍德森林的被腐化的迎風花。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4222 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4222,'zhTW','被腐化的迎風花','','','','去找費伍德森林的被腐化的迎風花。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4223 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4223,'zhTW','真正的主人','<所羅門鎮長嘆著氣。>$B$B你必須回到燃燒平原去，$N。作為暴風城的代表，你現在應該去向麥克斯韋爾元帥報告。祝你好運。','和燃燒平原的麥克斯韋爾元帥談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4224 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4224,'zhTW','真正的主人','什麼？你以為你是第一個被派來這裡的？我們到底要損失多少士兵，暴風城才會下決心採取行動？$B$B對於黑石獸人可能造成的威脅，我們已經有了充足的證據，但是在指揮官溫德索爾元帥被俘虜之後，我們損失了許多寶貴的情報。$B$B我們需要的是那份檔案。去跟約翰談談吧，$N。他當時和溫德索爾一起遇到了黑石氏族的襲擊，現在他正在北邊的一個洞穴裡休息。','和狼狽不堪的約翰談談來了解溫德索爾元帥的命運，然後回到麥克斯韋爾元帥那裡。$B$B你想起麥克斯韋爾元帥說過他在一個北面的洞穴那裡。','約翰的故事','去燃燒平原摩根的崗哨找麥克斯韋爾元帥。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4241 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4241,'zhTW','溫德索爾元帥','這麼說來，那個沒用的廢物說溫德索爾還活著，是嗎？$B$B做好準備，士兵，你必須去找到他。如果溫德索爾還活著的話，你就把他帶回來。如果他死了，那我就要你拿出他已經死亡的證據。$B$B<麥克斯韋爾大笑著。>$B$B我打賭你已經厭倦聽到這樣的命令了，是不是？','到西北部的黑石山脈去，在黑石深淵中找到溫德索爾元帥的下落。$B$B狼狽不堪的約翰曾告訴你說溫德索爾被關進了一個監獄。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4242 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4242,'zhTW','被遺棄的希望','伯瓦爾是個笨蛋。我一直以來都在收集有關他的“證據”，要將他徹底打敗。$B$B他是個沒腦子的小丑，證據在他面前堆了足有兩英尺高而他卻視而不見。$B$B如果我能找到鐵仇之錘並且走出這個該死的迷宮，那我要做的第一件事就是去暴風城，把那個卑鄙的傢伙一劈為二。$B$B離我遠點，$N。','把這個壞訊息傳達給麥克斯韋爾元帥。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4243 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4243,'zhTW','找回A-Me 01','非常不幸，我的一項最偉大的發明出了點問題。你以前見過機械松鼠，對嗎？嗯，為了接近安戈洛環形山的猿猴，我製造了一隻機械猿猴混入它們的群落——我把她稱為A-Me 01。$B$B她的水晶眼珠上附有特殊的魔法，因此我能看見她所看見的一切。不過，在她到了北邊的蘑菇石——也就是那群猿猴的巢穴裡面之後，我便與她失去了聯絡。我最後看到她的時候，猿群中有一隻雄猿正在衝上前去想和她套近乎！$B$B你能幫我找到她嗎？','在安戈洛環形山找到A-Me 01。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4244 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4244,'zhTW','找回A-Me 01','你仔細看了看,發現有一塊麵板被開啟了。在配線下面清楚地寫著一行字，“更換秘銀外殼，關閉電源之後再重新開啟。”$B$B更換面板之後，你不禁覺得沒理由這麼容易就能修好A-Me 01，並讓她回到馬紹爾營地附近的卡爾納·雷塔維身邊。$B$B只有先試試看了。','找到一個秘銀外殼，然後回到安戈洛環形山的A-Me 01身邊。','','去找安戈洛環形山的A-Me 01。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4245 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4245,'zhTW','找回A-Me 01','在看了看周圍的情況是否允許你把A-Me 01帶回卡爾納·雷塔維身邊之後，你將開關扳到了“關閉”位置。你有看了看周圍，確信沒有某隻猩猩朝你衝過來，然後將開關扳到“開啟”。$B$B這是你最後的機會了……你確定要這樣做嗎？','將A-Me 01交給安戈洛環形山的卡爾納·雷塔維。','護送A-Me 01回到卡爾納·雷塔維身邊','去安戈洛環形山找拉卡利油沼的卡爾納·雷塔維。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4261 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4261,'zhTW','遠古之靈','費伍德森林曾經是個和平安詳的地方……直到燃燒軍團佔據了這裡。惡魔、毀滅和混亂接踵而來……$B$B古爾丹之顱讓這裡的所有生物無一倖免地全都墮落了。$B$B直到現在，我還是身陷其中，不得不忍受這片土地所遭受的痛苦。請幫我找到回家的路吧，$N，告訴我你願意帶領一個古樹之靈離開這裡，讓我得到最終的安息。$B$B在我獲得自由之後，就請去找住在林歌神殿的德魯伊凱尼斯·靜風。','護送艾雷脫離危險，然後和梣谷東部的林歌神殿中的凱尼斯·靜風談一談。','幫助艾雷脫離危險','去梣谷找林歌神殿的凱尼斯·靜風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4262 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4262,'zhTW','征服者派隆','前五個試圖進入黑石深淵的法師幾乎個個都灰頭土臉地回來了，有的情況還要更糟糕。$B$B<加琳達從地上抓了一把灰塵灑向天空。>$B$B造成這種情況的主要原因是有一個可惡的臭蟲——征服者派隆給我們帶來了很多麻煩。我們必須幹掉這個元素生物，然後才能順利地進入黑石深淵！$B$B他就守在黑石採礦場的黑石深淵入口處。','殺掉征服者派隆，然後向加琳達覆命。$B$B加琳達告訴過你，派隆守在採礦場中，也許你應該去那裡找找。','','去燃燒平原摩根的崗哨找加琳達。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4263 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4263,'zhTW','伊森迪奧斯！','你確定派隆臨死之前喊出了“伊森迪奧斯”這個詞？$B$B<加琳達使勁嚥了口唾沫。>$B$B傳說伊森迪奧斯是拉格納羅斯的手下！哦，我的天啊，我的天啊……我們該怎麼辦啊？$B$B你認為你能再去完成一個任務嗎？我現在手頭沒有足夠的人手了，$N！$B$B如果伊森迪奧斯不斷復活派隆的話，那我們的隊伍永遠也不要想進去了。$B$B你必須找到伊森迪奧斯，把他幹掉！','在黑石深淵裡找到伊森迪奧斯，然後把他幹掉！','','去燃燒平原摩根的崗哨找加琳達。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4264 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4264,'zhTW','弄皺的便箋','這份便箋上滿是汙漬，上面的文字已經模糊不清了，但是還是能看出個大概來：$B$B……甜蜜的諷刺……$B$B……聯盟的分崩離析……$B$B……如果不是因為安格弗將軍的努力工作，也許我們至今還找不到譯碼的方法……$B$B……阿格曼奇已經差不多可以完成溫德索爾便箋的破譯了。$B$B我們的主人將從深淵中歸來，摧毀所有剩餘的東西……$B$B- 達格蘭·索瑞森大帝。','溫德索爾元帥也許會對你手中的東西感興趣。畢竟，希望還沒有被完全扼殺。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4265 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4265,'zhTW','逃離蟲巢','當你觸及蟲繭時，蟲繭裂開了一個小口，裡面有一個暗夜精靈，他居然還活著。雖然他處於深度昏迷中，但看起來並沒有缺胳膊少腿。當你幫助他從蟲繭中時，他驚醒了過來。$B$B“感謝艾露恩——你救了我的命，朋友！我……我是拉斯卡爾。我被這些蟲子麻痺，並被封在這隻蟲繭裡。你能幫我逃離這兒，然後去羽月要塞報告一下我已經脫險的訊息嗎？我沒事，但我們必須離開這兒，要快！”$B$B看起來你已經找到了失蹤的信使！','將拉斯卡爾安全護送到祖卡什蟲巢外。$B$B回到羽月要塞的基恩諾·火花那兒，告訴他拉斯卡爾還活著，且狀況良好。','解救拉斯卡爾。','去菲拉斯找羽月要塞的基恩諾·火花。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4266 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4266,'zhTW','羽月將軍的歡迎','$N，珊蒂斯·羽月將軍想與你私下談一談。毫無疑問，她是想要感謝你對要塞做出的貢獻，但我知道她還想和你討論一下你和拉斯卡爾在菲拉斯南部遇到的那種昆蟲。毫不誇張地說，那些祖卡什的昆蟲……非常可怕。$B$B羽月將軍正在主廳裡等你。','與羽月要塞的珊蒂斯·羽月談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4267 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4267,'zhTW','異種蠍的崛起','我信任你，所以把這份由拉斯卡爾撰寫的關於菲拉斯東南部現狀的報告交給你。現在這份報告的原本正在達納蘇斯歸檔，我要你做的是把這份副件交給最高女祭司的助手，她的名字叫格拉希娜·靈風，是一個住在達納蘇斯月神殿中的女祭司。她對於這些生物有著很深入的瞭解，把這份報告提交給她對我們大家都有好處。$B$B現在解散，祝你好運，$N。願艾露恩保佑我們。','把拉斯卡爾的報告交給達納蘇斯的格拉希娜·靈風。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4281 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4281,'zhTW','薩蘭納爾的貨物','你在木爪豺狼人營地裡發現的這包貨物應該是送往菲拉斯東南部的薩蘭納爾驛站的。不管那個失蹤的信使命運如何，遞送包裹的任務顯然是沒有完成。$B$B你仔細地檢查包裹，發現在外包裝上有手寫的“法芬德爾”字樣，也許這就是包裹接收人的名字。','將未遞送的包裹交給薩蘭納爾驛站的法芬德爾。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4282 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4282,'zhTW','一絲希望','<溫德索爾元帥激動地抖著手裡的信。>$B$B你知道這意味著什麼嗎，$N？$B$B也許他們還沒有得到所有的東西！我可以確定的是，現在有兩個黑鐵矮人——安格弗將軍和傀儡統帥阿格曼奇——正在破解我的那些情報。我相信我們是不大可能很順利地取回我的那封信的。$B$B希望你已經做好了戰鬥準備。$B$B去找到那兩個惡棍！幹掉他們，然後帶回我遺失的情報。','找回溫德索爾元帥遺失的情報。$B$B溫德索爾元帥確信那些情報在安格弗將軍和傀儡統帥阿格曼奇的手裡。','','去找黑石深淵的溫德索爾元帥。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4283 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4283,'zhTW','五十個！','我要告訴你個小秘密，士兵。走近一些。$B$B我是這裡唯一正常的人！$B$B看看我周圍的那些傢伙！你相信他們都不正常嗎？事實上他們都不正常！他們都瘋了！瘋了！$B$B<奧拉留斯放低了聲音。>$B$B這是個秘密，不要告訴別人，只有你，我，還有我的那個軍官夥計知道。$B$B<奧拉留斯緊握拳頭。>$B$B不管怎麼樣……我在收集食人魔耳朵的同時也收集徽章，就是那些獸人身上的徽章。給我弄五十枚徽章來，現在就出發！$B$B<奧拉留斯雙手攏在嘴邊作喇叭狀。>$B$B快去拿到那些徽章！','奧拉留斯想要50枚黑石徽章。在燃燒平原的獸人身上應該可以找到那些徽章。','','去燃燒平原找摩根的崗哨的奧拉留斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4284 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4284,'zhTW','能量水晶','我確定你一定已經注意過它們了，$N。它們到處都是！$B$B我在說什麼？這都不知道，我當然在說水晶！$B$B那些水晶……它們遍佈在整個環形山裡。大多數人都會忽視它們，但我感覺到那些水晶裡一定蘊含著特殊的力量。我一直以來都在用它們進行實驗，但似乎總是沒有什麼成果。好吧，我承認至今為止我一無所獲。$B$B這麼說吧，我這裡的水晶已經不多了——我想你也許能夠幫我收集一些水晶回來？','收集紅色能量水晶、藍色能量水晶、黃色能量水晶和綠色能量水晶各7塊，把它們交給馬紹爾營地裡的科琳。','','去找安戈洛環形山的科琳。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4285 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4285,'zhTW','北部水晶塔','那些到底是什麼東西？我腦子裡現在只有這個問題！$B$B它都快要把我逼瘋了——我相信那些關於水晶塔的傳言都是真的。隨便你怎麼說，但是我一般總是會相信別人告訴我的任何東西。$B$B不管怎麼樣，我聽說有一座水晶塔就在北部很近的地方……請去找到它，$N。我敢肯定它們確實存在。','在安戈洛爾環形山找到北部水晶塔。','找到並檢視北部水晶塔','去找安戈洛環形山的科琳。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4286 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4286,'zhTW','好東西','溫奇船長跟我說黑暗深淵裡的黑鐵矮人有很多好東西。對吧，溫奇？$B$B<奧拉留斯努力扮演一名海盜。>$B$BB對！$B$B明白我所說的了吧？你到那裡去，給我帶回一些好東西來。$B$B到那兒去搖你的搖錢樹吧！','到黑石深淵去找到20個黑鐵挎包。當你完成任務之後，回到奧拉留斯那裡覆命。你認為黑石深淵裡的黑鐵矮人應該會有這些黑鐵挎包。','','去燃燒平原找摩根的崗哨的奧拉留斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4287 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4287,'zhTW','東部水晶塔','這段時間我聽說了一些關於神秘的水晶塔的奇怪傳言，據說它們就在環形山中，$N。我猜它們的體積非常巨大，而且裡面蘊含有珍貴的水晶。$B$B雖然我從來沒有見過它們，但我卻情不自禁地願意去相信這些傳言是真的——而且那些水晶塔有可能和我們找到的水晶有某種聯絡。$B$B請幫幫我，滿足一下我的好奇心吧。也許在環形山的東部地區有一個水晶塔，你認為你可以找到它嗎？','在安戈洛爾環形山找到東部水晶塔。','找到並檢視東部水晶塔','去找安戈洛環形山的科琳。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4288 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4288,'zhTW','西部水晶塔','我的實驗迄今為至沒有取得任何實質性的進展，$N。我真希望你能幫我去檢視一下傳說中的一座水晶塔。$B$B也許我們在那裡組合特定顏色的水晶的話……嗯，這我會自己去做的。首先我們得找到那些水晶塔！$B$B$N，去搜尋一下環形山的西部區域；據說那裡有個水晶塔。','在安戈洛爾環形山找到西部水晶塔。','找到並檢視西部水晶塔','去找安戈洛環形山的科琳。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4289 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4289,'zhTW','安戈洛的猩猩','這個環形山中居住著許多奇怪的生物——它們似乎比我家鄉那邊的生物更加高貴。我無法解釋這一點，但是這塊地方在呼喚大地之母。每次我看到大地之母創造的某種美麗的生物時，我都會對她肅然起敬。$B$B如果你也希望感覺到見證這偉大功績的幸福感，就向北方出發吧。你將在那兒遇到巨大的猩猩，這對$r的力量來說是一個挑戰。把它們的皮毛交給我……證明你的力量。','將2塊安戈洛猩猩的皮、2塊安戈洛大猩猩的皮和2塊安戈洛巨猩猩的皮交給安戈洛環形山入口處的托爾瓦·尋路者。','','去安戈洛環形山找沼澤地的托爾瓦·尋路者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4290 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4290,'zhTW','拉克維的食物','很久以前，我的一個兄弟從拉克維的獵物身上拿了一些肉。他那時並不知道拉克維就潛伏在叢林中看著他。拉克維跟蹤了我的兄弟好幾天，毀滅了他碰過的一切。我的兄弟嚇壞了，最終他決定從安戈洛逃走，徹底甩開拉克維。$B$B拉克維就在這附近殺死了他。$B$B如果你想激怒拉克維，就去尋找它剛剛殺死的獵物，並從屍體上取一些肉。$B$B做完這些之後，就回到我這兒來。','找到拉克維剛剛獵殺的動物的屍體，從屍體上偷取一塊蛇頸龍肉塊，然後回到安戈洛環形山的托爾瓦·尋路者那裡。','','去安戈洛環形山找沼澤地的托爾瓦·尋路者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4291 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4291,'zhTW','拉克維的氣味','它居然沒有來攻擊你，這讓我感到很驚訝。但是不要緊，我有個計劃可以讓那頭野獸出來。$B$B作為這塊區域的領袖，拉克維有權與任何雌性暴掠龍交配——而且它確實這麼做了。你可以在這裡的西邊找到許多暴掠龍蛋，靠近它們，這時就會有雌性暴掠龍跑出來攻擊你。這些雌性暴掠龍頭上有一種腺體，它所散發出的味道可以告訴雄性暴掠龍：它準備進行交配了。給我帶兩個這樣的腺體回來。','將2份暴掠龍資訊素交給安戈洛爾環形山入口附近的托爾瓦·尋路者。','','去安戈洛環形山找沼澤地的托爾瓦·尋路者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4292 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4292,'zhTW','拉克維的誘餌','計劃有些複雜，因此這是最困難的部分。沿著山腳向北面走，你可以發現一條很不起眼的小道直通山中。那是我最後一次看到拉克維的地方。那裡應該散落著大型野獸的殘骸，所以你很容易判斷自己的位置是否正確。帶上這塊肉，把它放在那兒。然後在肉上塗抹我配製的這種液體。如果這還不能使拉克維現身的話，我想也沒什麼東西能把它引誘出來了。','使用托爾瓦的麻袋中的東西召喚拉克維並打敗它。將拉克維的頭顱交給安戈洛環形山入口處的托爾瓦·尋路者。','','去安戈洛環形山找沼澤地的托爾瓦·尋路者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4293 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4293, 'zhTW', '軟泥怪的樣本…', '費伍德是在貧瘠之地北邊很遠的地方的一片森林，比梣谷還要遠。在那裡的被惡魔污染的池水中到處都可以看到軟泥怪，天譴軍團的地獄火和其他惡魔法術曾經在這個地區肆虐過─軟泥怪應該是在這段時間裡從地底下冒出來的。$B$B從費伍德森林的軟泥怪身上收集一些樣本，然後我們就可以用我的測試儀器拿它們和其他樣本作一下比較了。', '從費伍德的軟泥怪身上收集費伍德軟泥怪樣本，然後使用幽暗城的化學家弗雷身旁的測試設備來檢測你所收集的樣本中哪一份被腐化的程度最深。給化學家弗雷帶去5個被腐化的費伍德樣本。', '', '去找奧特蘭克山脈的化學家弗雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4294 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4294, 'zhTW', '一大堆軟泥怪', '$N，你聽說過安戈洛環形山嗎?它就在塔納利斯沙漠附近，那裡是個神奇的地方，到處都是鬱鬱蔥蔥的大樹，還有大量的野生動物。 $B$B你必須到那裡去一趟，我聽說那塊地方至今未至從未受到過外界的污染，探險者們正在逐漸揭開它的秘密。$B$B我想要對那裡的軟泥怪或者泥漿怪做一下測試，如果它們真的沒有受到污染的話，那我真的想要看看這些生物是怎麼進化的。', '從安戈洛環形山那裡任何泥漿怪身上收集安戈洛泥漿怪樣本。使用幽暗城的化學家弗雷身旁的測試儀器來檢驗你所採集到的樣本的純度。把5份純淨的安戈洛樣本送到化學家弗雷那裡去。', '', '去找奧特蘭克山脈的化學家弗雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4295 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4295,'zhTW','羅克諾特的麥酒','','','','去找奧特蘭克山脈的羅克諾特下士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4296 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4296,'zhTW','七賢石板','我追尋七賢的傳說來到了燃燒平原，七賢是一群具有豐富知識和強大力量的矮人，你知道，一旦你有了這兩樣東西，那麼財富必將接踵而來。我要的就是財富！$B$B如果我們能對七賢有更多瞭解，那我們就能一起發財了。據說索瑞森廢墟里有一塊七賢石板，上面刻有那些古代矮人所掌握的知識。找到那塊石板，把上面的碑文拓下來給我，讓我們共同揭開其中的秘密！','把石板拓文交給燃燒平原的麥克斯沃特·尤博格林。','','去燃燒平原找烈焰峰的麥克斯沃特·尤博格林。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4297 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4297,'zhTW','小精龍的食物','小精龍是雜食動物——它們既吃肉也吃植物。要是這顆蛋即將孵化的話，我們最好有所準備。信不信由你，這些小傢伙最喜歡吃生的新鮮腰肉。我始終不明白為什麼，但是這也許和艾露恩的旨意有關……或許它們將成為守護者或是別的什麼，誰知道呢。$B$B我會照顧好這顆蛋，而你要負責找到一些銀鬃捕獵者的肉，以便在小精龍孵化後餵食。','將5塊銀鬃捕獵者的肉交給辛特蘭的阿格納。','','去找辛特蘭的阿格納。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4298 AND `locale` = 'zhTW';
