INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4421,'zhTW','碧火薩特','很少有$r到這邊來……費伍德森林的墮落已經遍佈各個角落，而且仍在毫無節制地汙染所有事物。$B$B作為翡翠議會的一員，我在努力治癒這片土地，但是仍然有些傢伙希望它被腐化墮落。$B$B我所說的就是居住在西南方的克斯特拉斯廢墟中的碧火薩特。他們的頭目是一個名叫薩瓦瑟拉斯的薩特，這些邪惡的惡魔仍在繼續將疾病散佈給他們遇到的一切生物。$B$B我們必須保衛這片原本屬於我們的土地。擊敗薩瓦瑟拉斯，消滅他的爪牙。','殺掉11個碧火魔僕、9個碧火巡影者、9個碧火潛行者和薩瓦瑟拉斯。任務完成之後回到費伍德森林的艾瑞丹·藍風處覆命。','','去費伍德森林找翡翠聖地的艾瑞丹·藍風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4441 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4441,'zhTW','被禁錮的古樹','你所發現的長笛是由某個守護古樹——忠心守護著暗夜精靈的樹人——雕刻而成的。$B$B薩特能使他們接觸到的任何東西受到腐蝕，其中也包括那些在費伍德森林安家的古樹。他們的靈魂在惡魔能量的作用下受到束縛和折磨，永遠無法解脫。你找到的碧火魔符就是禁錮古樹的東西。$B$B我們必須淨化長笛，$N。為我從達納蘇斯的月神殿取回一瓶祝福之水吧。','到達納蘇斯去，用艾瑞丹的瓶子收集月神殿中的祝福之水，然後回到艾瑞丹那兒。','','去費伍德森林找翡翠聖地的艾瑞丹·藍風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4442 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4442,'zhTW','淨化！','我要用月神之水來淨化這根笛子。我們必須結束這場劫難……$B$B願艾露恩指引我的雙手和我的心。$B$B過一會再和我說話。','過一會兒再與艾瑞丹對話。','','','','','','',0);
