INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4449,'zhTW','被鎖起來的矮人','嘿！嘿，你！過來！$B$B你要幫幫我。我正在逃避黑鐵矮人的追擊，我藏在這裡，滿以為他們就找不到我了。但那些可惡的混蛋還有魔法！他們肯定看到我藏了起來，他們很快就把門鎖上，說了些什麼過一陣子再回來之類的話，然後就離開了。$B$B你要給它們的顏色瞧瞧！給那些黑鐵地質學家一個教訓！哦……對了，你能不能給我弄幾塊絲綢來做……做……呃，沒什麼。','殺掉8個黑鐵地質學家，並將15塊絲綢交給灼熱峽谷裡那個被鎖在廁所中的矮人。','','去找荒蕪之地的木製廁所。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4450 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4450,'zhTW','塔納利斯的賬本','哦，你猜怎麼著？我想起了一件事情。$B$B我現在仍然被困在這裡，那麼你可以幫我完成一項我在塔納利斯接受的任務嗎？很簡單……嗯，對於你來說是這樣的。$B$B加基森的克林科·古德斯迪爾需要一些從灼熱峽谷和其它地方收集的東西。也許你可以看一下清單，然後把東西交給他……$B$B如果你感興趣的話，我會把他的賬本從門下遞給你。把賬本和他需要的那些東西交給他就行了。','把古德斯迪爾的賬本和上面所列的物品交給塔納利斯的克林科·古德斯迪爾。','','去塔納利斯找加基森的克林科·古德斯迪爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4451 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4451,'zhTW','自由的鑰匙','這把小小的黃銅鑰匙看起來可真簡單……它唯一與眾不同的地方是刻在鑰匙頭部的一句話：$B$B“黑鐵廁所——請勿複製。”$B$B你完全不明白這是什麼意思，也不明白這鑰匙是幹什麼用的。','搜尋灼熱峽谷並找到一個可以插入這把格里塞特廁所鑰匙的鎖眼。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4461 AND `locale` = 'zhTW';
