INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4485,'zhTW','高貴之書','你好，$N。我看到你仍然有著奉獻的熱情，仍然有著堅定的信念。$B$B我覺得你應該去跟暴風城的達索瑞恩·拉爾談一談了。你還有更多的東西要到那裡去學習，我覺得你已經準備好了。$B$B到光明大教堂去找他吧，呂正，你一定要認真學習這些知識。你因為謙卑和勤懇贏得了我們的尊敬，不要因為傲慢而讓我們失望。$B$B祝你好運。','與暴風城的達索瑞恩·拉爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4486 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4486,'zhTW','高貴之書','嘿，看看我們這位聖騎士不可一世的樣子。$B$B對不起，$N，我不是想要冒犯你……我只是有時候會對你能做那麼多的事情而感到嫉妒。蒂薩說過這是我的弱點，我向她發誓我正在努力改正它……不過說起來容易做起來就難了。$B$B但是我要告訴你的是，暴風城的達索瑞恩·拉爾派人捎信過來說，讓你近期回一趟光明大教堂，聽上去他是有什麼重要的事情要找你。','與暴風城的達索瑞恩·拉爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4487 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4487,'zhTW','召喚地獄戰馬','啊，很好，你來了。我派了一個$g魅魔:地獄火跟著你，以便引起你的注意，但看起來你在它找到你之前就來到這裡了。沒關係。$B$B最近大家都知道你的力量在日漸增長，而且大家對此議論紛紛——這對你來說很好，但有可能對其它人來說就不是什麼好訊息了。這些都是雞毛蒜皮的事情。重要的是，我覺得你已經證明了自己有資格得到……呵呵……某種祝福。$B$B在貧瘠之地的棘齒城中有一個名叫斯坦哈德的人，我相信你以前見過他的。','與棘齒城的斯坦哈德·法爾杉談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4488 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4488,'zhTW','召喚地獄戰馬','啊，$N,你的出現使我們倍感榮幸！$B$B不過你也沒指望我們會對你俯首貼耳吧？你的力量也許正在迅速增長，但說到真正的知識和理解力，你還是一個新手呢。如果你不當心的話，墮落的力量就會侵蝕你的意志。$B$B說正事吧，斯坦哈德想要跟你見一面。他仍然住在貧瘠之地，就在那座可以俯瞰棘齒城的塔中。我建議你不要耽擱太久。','與棘齒城的斯坦哈德·法爾杉談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4489 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4489,'zhTW','召喚地獄戰馬','你，說你哪！過來！$B$B你就是他們所說的那個叫做$N，對嗎？$B$B我也這麼想。我長話短說：你的力量在不斷增長，這點眾所周知。現在，你的努力終於可以為你帶來回報了。$B$B到貧瘠之地去，在那裡的棘齒城中找到斯坦哈德·法爾杉——你還記得他吧？他會跟你詳談的，趕快去吧。','與棘齒城的斯坦哈德·法爾杉談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4490 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4490,'zhTW','召喚地獄戰馬','我會為你的忍耐和辛勤工作而獎勵你的。但你要知道，召喚一匹地獄戰馬的能力在將來會變得困難許多。你必須努力爭取它……而且這不很容易。$B$B現在，你可以在自己需要的時候召喚地獄戰馬了。','與棘齒城的斯坦哈德·法爾杉談一談，學習召喚地獄戰馬的能力。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4491 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4491,'zhTW','朋友的幫助','啊……太熱了……$B$B我正在探索這片地域，突然之間，我就熱得昏了過去，我一定是中暑了。$B$B求求你，帶我回到馬紹爾營地的朋友斯普拉格那裡去，我想我還可以堅持到走回去……$B$B我感覺有些不對勁，如果我又暈倒了，就用斯普拉格的水壺裡給我灑點水。我希望這能有點用……','把林格帶回馬紹爾營地的斯普拉格·弗勞克身邊。$B$B如果林格暈倒了，就用斯普拉格的水壺讓他恢復。','把林格帶回馬紹爾營地的斯普拉格·弗勞克身邊','去安戈洛環形山找馬紹爾營地的斯普拉格·弗勞克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4492 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4492,'zhTW','走丟了！','你必須幫幫我，$N！我的朋友林格前不久離開這裡去探索南邊的火山了，但他一直沒回來。我很為他擔心。$B$B你能幫我找找他嗎？帶著我的水壺，如果你找到了林格，沒準他正需要它呢！','在火羽山找到林格。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4493 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4493,'zhTW','異種蠍的遠征','看起來異種蠍的意圖，不——它們存在的原因，就是毀滅它們遇到的所有其它生物。它們的目標非常明確，也正是由於這個原因，它們成了對艾澤拉斯所有生物的巨大威脅。$B$B我們現在見到的僅僅是個開始，我懷疑它們的力量來自卡利姆多的腹地：安戈洛環形山。到塔納利斯沙漠裡的加基森鎮去，跟鍊金師匹斯特蘇格談一談。把我的想法告訴他，他肯定會幫我們對抗異種蠍的。','與加基森的鍊金師匹斯特蘇格談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4494 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4494,'zhTW','異種蠍的遠征','看起來異種蠍的意圖，不——它們存在的原因，就是毀滅它們遇到的所有其它生物。它們的目標非常明確，也正是由於這個原因，它們成了對艾澤拉斯所有生物的巨大威脅。$B$B我們現在見到的僅僅是個開始，我懷疑它們的力量來自卡利姆多的腹地：安戈洛環形山。到塔納利斯沙漠裡的加基森鎮去，跟鍊金師匹斯特蘇格談一談。把我的想法告訴他，他肯定會幫我們對抗異種蠍的。','與加基森的鍊金師匹斯特蘇格談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4495 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4495, 'zhTW', '好朋友', '我有一位名叫埃沃隆的朋友，他通常都會在每天的固定時段裡來拜訪我。奇怪的是，今天他根本沒來，實際上現在他已經晚了好幾個小時了。我承認我有些擔心，$N。埃沃隆常常在北邊的一個洞穴裡待很長的時間，你知道那裡有多危險─那裡到處都是蜘蛛!如果你剛好要過去那邊的話，能幫我找找他嗎?', '在北邊的洞穴附近找到埃沃隆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4496 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4496,'zhTW','擒蟲先擒王','我的研究表明異種蠍就像蜜蜂一樣，消滅蜂房中的蜂后，其餘的就會亂作一團。我可以製造一種誘餌來讓你引出異種蠍的皇后，並且打倒她。$B$B然而在那之前，我們需要一些材料，我可不想讓你冒冒失失地進入叢林。到西邊安戈洛環形山的異種蠍洞穴裡去，從那裡的某隻蟲子身上弄到它的資訊素腺。另外我還需要一些安戈洛的土壤樣本。','把一份格里什資訊素和5份安戈洛的泥土樣本交給加基森的鍊金師匹斯特蘇格。','','去塔納利斯找加基森的鍊金師匹斯特蘇格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4501 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4501,'zhTW','當心翼手龍','懸賞：尋找技藝精湛的冒險者來對付安戈洛爾環形山中的翼手龍。它們的數量正在不斷增加，已經威脅到了這個地區的旅行者。$B$B請殺掉10只翼手龍和15只狂怒的翼手龍來削減它們的數量。$B$B在完成任務之後，請向斯普拉格·弗勞克報告並換取獎勵。','殺掉10只翼手龍和15只狂怒的翼手龍，然後向馬紹爾營地的斯普拉格·弗勞克報告。','','去安戈洛環形山找馬紹爾營地的斯普拉格·弗勞克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4502 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4502,'zhTW','火山的活動','作為瑪爾馮·瑞文斯克的學徒，我從他那裡學到了很多知識。但是他已離開很長時間了，因此我想自己去學習新的知識。$B$B近來我一直在閱讀關於安戈洛環形山裡面那些持續而奇怪的火山活動的資料。我想如果能從那兒的火元素身上弄到一些灰燼，就可以瞭解到很多東西了。$B$B如果你要往那兒去的話，能順便幫我收集一些嗎？','到安戈洛環形山的火山中去，從那裡的元素身上收集9份安戈洛灰燼，把它們交給棘齒城的莉芙·雷茲菲克斯。','','去找貧瘠之地的莉芙·雷茲菲克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4503 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4503,'zhTW','希茲爾的的飛行器','我正在做一架飛行器！$B$B我被困在了這裡，而且不敢輕易出去。如果我走出這裡的話，肯定會迷路的，但是如果使用飛行器，我就可以輕鬆地回到加基森去。$B$B那麼，你願意幫助我嗎？我現在只剩下機翼沒有完成了，我想翼手龍和雙帆龍的鱗片會是非常合適的材料。我自己是不可能去搞到這些鱗片的，但是你看上去好像有兩把刷子。為什麼你不幫我找找呢？','為馬紹爾營地的希茲爾收集8塊精細的雙帆龍鱗片和8塊精細的翼手龍鱗片。','','去安戈洛環形山找馬紹爾營地的希茲爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4504 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4504,'zhTW','極度粘稠的瀝青','我總是在尋找快速賺錢的方法，$N。如果你能幫我實現新計劃，我可以讓你也賺點錢，怎麼樣？$B$B就這麼定了！$B$B到安戈洛爾環形山北部的油沼去，在那裡幫我收集一些瀝青。並不是所有的瀝青都合適，你必須從油沼周圍的野獸身上得到它。一般意義上的瀝青根本不夠黏，但是那些生物的皮膚中包含著葉綠素，和瀝青混合在一起之後，它就變得非常具有粘性！','幫加基森的特蘭雷克收集12塊極度粘稠的瀝青。','','去塔納利斯找加基森的特蘭雷克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4505 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4505,'zhTW','腐化之井','有人可能會說我非常殘忍……但事實上，我只不過是迫切地希望以任何可能的方法使部落能夠壓倒聯盟。$B$B我最近對南邊的克斯特拉斯廢墟中的月亮井很感興趣，這座月亮井是由碧火薩特守護的，它曾經是那些暗夜精靈新生的象徵，但如今它已遭到腐化，被用於製造更多的薩特。$B$B我有個主意，$N，我需要一份井水的樣品……給我們的那些“朋友”。','從碧火薩特的月亮井中收集一份被腐化的水的樣本，把它交給血毒哨所的溫娜·哈薩德。','','去費伍德森林找血毒崗哨的溫娜·哈薩德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4506 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4506,'zhTW','被腐蝕的貓','我們可以利用這些墮落的水，$N。只需少量這種水，我的小貓的體積就會變大，而且看上去會變得非常強壯……$B$B給你，$N。拿著這隻貓籠，在克斯特拉斯廢墟的月亮井旁邊把貓放出來。呵呵……我相信你一定會對結果感到滿意的！$B$B把貓給我帶回來，我會讓你覺得這點時間不是白白浪費掉的。','把溫娜的小貓帶到墮落的月亮井旁邊，把貓放出來，然後把它還給溫娜。$B$B當你回到溫娜那裡之後，點選貓就可以將它還給溫娜。','將被腐蝕的貓交給溫娜·哈薩德','去費伍德森林找血毒崗哨的溫娜·哈薩德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4507 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4507,'zhTW','捕捉皇后','拿著這份誘餌。在四通八達的蟲巢中一定有一塊水晶之類的東西，我想異種蠍就是使用它作為協調裝置的。至於水晶在哪裡……我建議你到蟲巢中的孵化室找找看。$B$B在那裡對水晶使用誘餌，這樣就可以引出異種蠍的皇后了，但是你要小心——也許會有幾個守衛保護著她。幹掉皇后，然後拿出她的腦子。雖然這聽上去有些噁心，但是我們必須對它進行研究。祝你好運，$N！','召喚格里什皇后，然後擊敗她。$B$B把格里什皇后的大腦交給加基森的鍊金師匹斯特蘇格。','','去塔納利斯找加基森的鍊金師匹斯特蘇格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4508 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4508,'zhTW','臨危不懼','我最近的研究結果表明情況相當糟糕，我們必須得通知某個能採取一些實質行動的人，因為我們不可能單獨解決這件事情。$B$B把我的最新報告交給達納蘇斯的格拉希娜·靈風吧，她還在月神殿，不是嗎？她的許多朋友都是聯盟的要人，$N，如果我們能讓他們涉及這件事情，那解決問題的希望就大增了。','把匹斯特蘇格的安戈洛報告交給達納蘇斯的格拉希娜·靈風。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4509 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4509,'zhTW','臨危不懼','我最近的研究結果表明情況相當糟糕，我們必須得通知某個能採取一些實質行動的人，因為我們不可能單獨解決這件事情。$B$B把我的最新報告交給奧格瑪的基爾茲賓·鼓眼，他還在暗巷區裡待著，不是嗎？他的許多朋友都是部落的要人，$N，如果我們能讓他們涉及這件事情，那解決問題的希望就大增了。','把匹斯特蘇格的安戈洛報告交給奧格瑪斯的基爾茲賓·鼓眼。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4510 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4510,'zhTW','臨危不懼','$N，你對我們的幫助是無價的。等到時機成熟時，我肯定會再次請求你幫助我們去對付異種蠍。我們必須清晰地解讀我們在安戈洛得到的資訊，恐怕我原本假設安戈洛是異種蠍發源地的想法是錯誤的……看來它們還有更大規模的聚居地。$B$B把這封信交給銀行的伊迪瑞娜。她會讓你從我的倉庫中挑選一件東西。感謝你為我們提供的幫助，勇敢的$c。','把銀行贈券交給達納蘇斯銀行的伊迪瑞娜。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4511 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4511,'zhTW','臨危不懼','$N，你對我們的幫助是無價的。等到時機成熟時，我肯定會再次請求你幫助我們去對付異種蠍。我們必須清晰地解讀我們在安戈洛得到的資訊，恐怕我原本假設安戈洛是異種蠍發源地的想法是錯誤的……看來它們還有更大規模的聚居地。$B$B把這封信交給銀行的卡魯斯。他會讓你從我的倉庫中挑選一件東西。感謝你為我們提供的幫助，勇敢的$c。','把銀行贈券交給奧格瑪銀行的卡魯斯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4512 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4512, 'zhTW', '遠方的軟泥怪', '但我研究最多的生物是軟泥怪。我知道這聽起來很奇怪，但是這種東西已經到處都是了!$B$B不久之前，我幫米納希爾港的一位女士找到了她的袋子─那個袋子被軟泥怪吃掉了。我也看過幽暗城的皇家藥劑師學會的成員去收集軟泥怪的樣品。我要知道為什麼!軟泥怪究竟是從哪裡來的?$B$B我聽說在費伍德森林有許多軟泥怪，我需要那些軟泥怪的樣品來進行研究。我會給你一些容器，這樣你就可以幫我收集軟泥怪了。', '將6個被詛咒的軟泥怪樣本和6個受污染的軟泥怪樣本交給鐵爐堡的拉里斯·空輪。', '', '去找鐵爐堡的拉里斯·空輪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4513 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4513, 'zhTW', '遠方的軟泥怪', '「我需要更多的樣品，$N。但是─我不知道怎麼讓你明白─嗯，我需要的是純淨的樣品。」「不過什麼是『純淨』的樣品呢，拉里斯?」「我也不知道。你拿來的這些都是已經被腐化的……就好像整個費伍德森林一樣。這讓我的想法變的十分重要:看來軟泥怪會去適應周圍的環境。我需要一些未經污染的樣品以證實這一點。但是哪裡有呢?哪裡?!$B$B算了!$N，帶著這些容器，如果你找到未被污染的軟泥怪，就把它交給我。」', '將10個裝滿的純淨樣品瓶交給鐵爐堡的拉里斯·空輪。$B$B如果你無法找到它們的話，試著到拉里斯那裡去再打聽一些線索。', '', '去找丹莫羅的拉里斯·空輪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4521 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4521,'zhTW','冬泉谷的梟獸','冬泉谷就在費伍德森林的東北面，木候要塞的另一邊。你去過那兒嗎？$B$B我聽說那片區域裡到處都是一種被稱作梟獸的生物，這些野獸以守護著暗夜精靈的秘密而知名。$B$B我們必須找出可能隱藏在冬泉谷裡的東西。$B$B我聽說你可在道路的南邊找到蓬毛梟獸，而狂怒的梟獸則可在冬泉谷的中心地區找到。清除它們，控制那片土地。','費伍德森林的特魯爾·法貝恩要你去冬泉谷獵殺15頭狂怒的梟獸和15頭蓬毛梟獸。','','去費伍德森林找血毒崗哨的特魯爾·法貝恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4541 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4541,'zhTW','暫無內容','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4542 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4542,'zhTW','給亂風崗的緊急信件','勇敢的旅行者，半人馬已經加強了對這個地區的攻勢。亂風崗必須馬上得知這個新的麻煩！到東南方的亂風崗去，找到峭壁衛兵圖林·長角，把這個十萬火急的訊息通知給他。$B$B多加小心，避開附近的恐怖圖騰氏族……他們最近對我們有一些很奇怪的舉動。','把緊急信件交給亂風崗的峭壁衛兵圖林·長角。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4561 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4561,'zhTW','雜質檢測 - 安戈洛環形山','','','','去找測試儀器。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4581 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4581, 'zhTW', '凱尼斯·靜風', '德魯伊凱尼斯·靜風讓人捎話過來說，他需要一份關於我們這邊海岸和阿斯特蘭納附近森林的報告。他擔心有一股墮落的力量正在靠近梣谷……也許他是正確的。$B$B給你，拿著我的報告。你可以在林歌神殿裡找到他，就在東邊的夜歌森林一帶。', '把辛德瑞爾的便箋交給林歌神殿裡的凱尼斯·靜風。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4601 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4601,'zhTW','超級清潔器5200型!','這個裝置屹立於那些竭力保護房間的地精中，裝置上有一塊小金屬牌，上面寫著「超級清潔器5200型」，還有一段文字:$B$B:「污垢和殘渣讓你的東西看起來污穢不堪?超級清潔器5200型會使它重現光芒!將你想要清理的物品放入清潔器中，然後向槽裡投入三枚銀幣。稍候片刻，你的珍寶就會重新變得潔淨而耀眼!」','將髒兮兮的東西放入超級清潔器5200型，記得要用三枚銀幣來啟動機器。','','去找希爾斯布萊德丘陵的超級清潔器5200型。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4602 AND `locale` = 'zhTW';
