INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4786,'zhTW','完成金線血袍','稍等一下，我現在就為你織好披風。這需要一些時間，可別走得太遠了。','等待梅納拉·沃倫德織好披風，然後跟她談一談。','等待梅納拉·沃倫德完工','去找貧瘠之地的梅納拉·沃倫德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4787 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4787,'zhTW','遠古之卵','摩沙魯的預言提到了一枚遠古之卵。當巨魔建造的強大帝國還無人能敵時，那枚卵就已經存在了，它具有控制哈卡的靈魂精華的力量。也許它就是能使我們的世界免受邪惡侵擾的唯一希望。$B$B把這枚遠古之卵交給我，$N。據說它被深藏在辛特蘭地區的巨魔城市辛薩羅，就在城市最頂端的大廣場後面的洞穴中。','將遠古之卵交給塔納利斯的葉基亞。','','去塔納利斯找熱砂港的葉基亞。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4788 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4788,'zhTW','最後的石板','在我研究摩沙魯的第三塊和第四塊石板的同時，你必須找到第五塊和第六塊！這並不容易，因為它們在黑石塔的燃棘巨魔手中。黑石塔位於燃燒平原和灼熱峽谷之間，那是一座到處都是岩漿和火焰的黑色山脈。$B$B祝你好運，$N。黑石塔可不是個觀光的去處……','將第五塊和第六塊摩沙魯石板交給塔納利斯的勘查員詹斯·鐵靴。','','去塔納里斯找熱砂港的勘查員詹斯·鐵靴。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4801 AND `locale` = 'zhTW';
