INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5047,'zhTW','芬克·恩霍爾，為您效勞！','你可以在永望鎮找到瑪雷弗斯·暗錘，$c。告訴他“芬克一切都好”，還有衣服很不錯。$B$B然後給他這個。$B$B<芬克給了你一塊光鮮的肉。>$B$B這是我“度假”時從比斯巨獸的內臟裡摘出來的。$B$B我敢打賭，瑪雷弗斯對看到這個東西的時候會大吃一驚的！$B$B哦，我猜你不知道永望鎮在哪裡，是嗎？到冬泉谷去，$g小夥子:女士！','與永望鎮的瑪雷弗斯·暗錘談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5048 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5048,'zhTW','善良的艾瑪','她是個奇怪的人，很可能精神不正常……但是記錄顯示這個艾瑪可能確實就是艾瑪·費爾斯通。$B$B你也許見過艾瑪在城市裡到處遊逛——她不停地自言自語，通常都是些荒誕而含糊不清的話。但是她沒有傷害任何東西或是任何人，因此人們大都不刁難她。$B$B因此，我認為艾瑪事實上就是你要找的艾瑪·費爾斯通。你可以問問她是不是姓費爾斯通。','找到暴風城的艾瑪並弄清她是否就是艾瑪·費爾斯通。如果是的話，那麼她可能想要拿到詹妮絲·費爾斯通給她的包裹。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5049 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5049,'zhTW','傑雷米亞的憂傷','根據這些證據，我認為你所找的應該就是傑雷米亞·派森，幽暗城的蟑螂商人。$B$B我一直以為能跑去賣蟑螂的一定是個不平凡的人……毫無疑問，您眼下正在譜寫一卷史詩，偉大的$c。我會讓您繼續進行重塑世界的偉大工作。然而，請允許我成為您這一傑作的一部分，並謙卑地向您揭示他的位置。他就在銀行的附近，正舒服地趴在某條人行道下面呢。','在幽暗城找到傑雷米亞·派森並查明他是否就是你要找的傑雷米亞·費爾斯通。如果他是的話，那麼他可能會想要拿到詹妮絲·費爾斯通寄給他的包裹。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5050 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5050, 'zhTW', '好運符咒', '看起來我錯怪你了，$N，為此我應向你道歉。我姐姐送給我許多東西，包括看起來很滑稽的費爾斯通農場地契，我想我一時半會是沒法收回它了。$B$B如果我姐姐的靈魂還被束縛在農場不能安息，請你幫幫忙……你能把這個還給她嗎?這是她的半個符咒，她的丈夫拿著另外一半。$B$B或許當她知道我拿到這些東西之後就可以安息了。', '把半個好運符咒還給西瘟疫之地的詹妮絲·費爾斯通。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5051 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5051, 'zhTW', '合二為一', '這個可憐的鬼魂繼續說道:$B$B「我好冷，約翰，把你的符咒帶給我，我們就可以在一起了!快點，約翰，在瘟疫把我們變成可惡的野獸之前!我看不到你，約翰……但是我知道你就在附近。我感覺你就在我身旁，」$B$B或許，找到另一半的符咒並組合起來，就能組成珍妮絲·菲爾斯通的靈魂所尋找的東西。', '在西瘟疫之地的費爾斯通農場的某個地方找尋另外半個好運符並組合起來。$B$B把好運符交給西瘟疫之地費爾斯通農場的珍妮絲·菲爾斯通。', '', '去找西瘟疫之地的詹妮絲·費爾斯通。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5052 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5052,'zhTW','阿迦瑪甘的血巖碎片','和荊棘一樣，鮮血也影響了<豬哼聲>大地的其它特性：血紅的石頭與別的礦石摻雜在一起，刺背野豬人挖出這些碎片並把它們帶走，在戰鬥中把它們當作增強<豬哼聲>力量和魔法能量的圖騰。<豬哼聲>$B$B我知道那個魔法的秘密。$B$B把一塊血石碎片交給碎牙來表示你明白了。給碎牙拿來許多血牙碎片，他就會用野豬人的魔法保護你——阿迦瑪甘的魔法！<豬哼聲>','給陶拉祖營地的碎牙帶去一塊血巖碎片。$B$B如果你想要他賜予你阿迦瑪甘的力量，就蒐集更多的血巖碎片。','','去貧瘠之地找陶拉祖營地的碎牙。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5053 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5053,'zhTW','<UNUSED>','這個任務會把郵件寄到你的信箱。只需點選完成即可。','測試任務，用來確認郵件是否會送達你的信箱。點選完成，然後去查看你的郵件。$B$B祝你有美好的一天。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5054 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5054,'zhTW','碎齒熊尤西烏斯','在冬泉谷那白雪茫茫的山脈裡，有一頭狩獵技術純熟精湛的碎齒熊，尤西烏斯。$B$B現在我讓你去對付他，尤西烏斯就在永望鎮西邊的山坡上徘徊。在它發現你的意圖之前找到他，擊敗他。$B$B所有前去獵殺尤西烏斯的獵人都很快發現自己變成了獵物，而尤西烏斯才是獵人。你要多加小心。','永望鎮的斯托姆·影蹄想要你去殺死尤西烏斯。','','去冬泉谷找永望鎮的斯托姆·影蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5055 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5055,'zhTW','冰風奇美拉布魯米蘭','布魯米蘭迅捷而又聰明，她悄無聲息地在冬泉谷南邊的雪地中滑翔。但是不要讓她那優雅的外表迷惑了你，所有從她身旁經過的旅行者都受到了猛烈的攻擊，而且多半會賠上他們的性命。$B$B從那些冰風奇美拉中找出布魯米蘭，打敗它，然後再回來見我。','永望鎮的斯托姆·影蹄想要你去殺死布魯米蘭。','','去冬泉谷找永望鎮的斯托姆·影蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5056 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5056,'zhTW','希洛塔姆','在冬泉谷的北方，有一大群兇猛的雪豹聚集在一處被稱作霜刀石的地方。這些豹子的首領是希洛塔姆。打敗她，你的同伴就會對你充滿敬意。$B$B再去一次冬泉谷，一到那裡就開始從霜刃豹身上搜集它們的肉。找到希洛塔姆之石，把肉放在那裡，這樣就可以召來憤怒的希洛塔姆。$B$B迎戰狂怒的霜刃豹首領，並打敗她。','永望鎮的斯托姆·影蹄想要你去殺死希洛塔姆。','','去冬泉谷找永望鎮的斯托姆·影蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5057 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5057,'zhTW','以往的努力','$N，我已經聽說過許多有關你的傳言了……據說你有著堅強不屈的信念，作為一個$c，你具備傑出的能力。現在看到你，我終於相信這些都是事實了。$B$B像你這樣優秀的$r值得嘉獎。把這個交給我在雷霆崖的一個名叫梅洛·石蹄的朋友。我肯定他會記得你，還有你以往做出的努力。將你近期所取得的勝利告訴他，還有永遠不要忘記你今天所取得的成就。','把斯托姆·影蹄的徽記交給雷霆崖的梅洛·石蹄。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5058 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5058, 'zhTW', '達爾松夫人的日記', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5059 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5059, 'zhTW', '被鎖起來的農夫', '', '進度廁所的門幾乎被撐開了，裡面有什麼東西在瘋狂而執著地反復衝撞它。不過到目前為止這扇門還是從外面緊緊鎖住的。$B$B當你推擠這扇門時，你聽到從裡面傳出了混濁的咕嚕聲!不管那裡有什麼，它肯定不是個友善的傢伙。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5060 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5060, 'zhTW', '被鎖起來的農夫', '', '進度一個極其結實的櫃子立在你面前，櫃子的門被一個內建的鎖牢牢地鎖著。櫃子的前面有深深的劃痕與刻痕，看起來好像是在無數次想要解開其中秘密的粗暴失敗嘗試所導致的結果。$B$B如果你想要打開這個櫃子，就得先找到鑰匙。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5061 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5061,'zhTW','水棲形態','你已經學完了掌握水棲形態所必須具備的所有知識，現在回到達納蘇斯的瑪斯雷·馭熊者那兒去吧。把墜飾拿給他看看，以此證明你已準備好接受新的知識。他會讓你掌握變化為水棲形態的訣竅，讓你在水中靈活自如。$B$B再見，年輕的德魯伊。我們會再見面的。','回到達納蘇斯，讓瑪斯雷·馭熊者看看你的海獅墜飾。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5062 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5062,'zhTW','神聖之火','阿利卡拉是個致命的威脅，我們必須馬上將其解決。你必須點燃生命聖火，這樣就可以召喚出阿利卡拉了。$B$B現在就去採集稀有的火巖龍舌蘭植株。在你採集到了足夠的植株後，到雷霆崖的長者高地上去找瑪加薩·野性圖騰。她是個具有強大力量的薩滿祭司，她可以點化火巖龍舌蘭來創造一種引燃聖火所需的材料。$B$B到西北面的沸騰之池去收集火巖龍舌蘭吧。','收集10支火巖龍舌蘭，然後去找雷霆崖長者高地的瑪加薩·野性圖騰。','','去找雷霆崖的瑪加薩·野性圖騰。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5063 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5063,'zhTW','血色學者之帽','一頂你從未見過的帽子。我們熟練的工匠將使用比斯巨獸的皮製造出最漂亮華美的、每個施法者都夢寐以求的帽子！$B$B另外還需要三百個金幣的製作費用和下面列出的製造材料：$B$B*比斯巨獸的皮。$B$B*磨損的憎惡縫合線。$B$B*奧術水晶。$B$B*魔化紅線。','為了製造血色學者之帽，你必須將下列物品交給瑪雷弗斯·暗錘：1塊比斯巨獸的皮，5根磨損的憎惡縫合線，8塊奧術水晶，5根魔化紅線。$B$B另外你還必須支付50金幣的製作費用。','','去冬泉谷找永望鎮的瑪雷弗斯·暗錘。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5064 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5064,'zhTW','恐怖圖騰的密信','$n，你曾為我們做了不少事情，現在我要交給你一個重要的任務。恐怖圖騰氏族正在策劃一些神秘的行動。最近幾個星期，有三個神秘的訪客去過恐怖圖騰氏族的營地中。我們發現他們在黑雲峰放置了幾隻分散的箱子，裡面就藏著他們的密信。$B$B$N，如果你成功地完成了這個危險的任務，我一定會好好獎勵你的。','在黑雲峰拿到三封密信。','','去千針石林找亂風崗的峭壁衛兵圖林·長角。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5065 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5065, 'zhTW', '失落的摩沙魯石板', '那個食人妖沒有對你說出真相。你為他弄來的那兩塊石板提到了哈卡精華，但是那個傳說的內容應該還有更多才對。我已經研究很久了，而且我發現摩沙魯石板應該總共有六塊，並非兩塊!是六塊!$B$B我恐怕其他人所掌握的那些秘密會對我們不利……$B$B找到第三塊和第四塊摩沙魯石板。它們在東瘟疫之地，被居住在那裡的爛苔食人妖控制著。找到它們並把它們交給我。', '把第三塊和第四塊摩沙魯石板交給塔納利斯的勘察員鐵靴。', '', '去塔納利斯找熱砂港的勘察員鐵靴。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5066 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5066, 'zhTW', '戰鬥的號角:瘟疫之地!', '大家都聽著!大家都聽著!所有的英雄都應該聆聽這號召的聲音!暴風城已經發出了備戰的號召!所有勇士都應該拿起武器，一同面對來自東部王國北部地方天譴軍團的威脅!城中傳言四起，東部王國的廢墟中滋生出了新的威脅!它們已經在幽暗城東面的瘟疫之地大量集結，聯盟的安全岌岌可危!聯盟的英雄們-去向指揮官阿胥拉姆·瓦羅菲斯特報到吧，他的大本營就在奧特蘭克山脈北邊的冰風營地!', '找到指揮官阿胥拉姆·瓦羅菲斯特。他的大本營位於奧特蘭克山脈以北的冰風營地。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5067 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5067,'zhTW','阿卡納護腿','雖然歷史上從來沒有成功鑄造這件裝備的記錄，但是只要有合適的環境，鑄造它還是有可能的。$B$B如果奧秘的追尋者想要得到這樣一件具有強大力量的護腿，他就需要以下這些材料：$B$B*比斯巨獸的皮。$B$B*磨損的憎惡縫合線。$B$B*奧金錠。$B$B*萊斯·霜語的防腐液。','為了製造阿卡納護腿，你必須將下列物品交給瑪雷弗斯·暗錘：1塊比斯巨獸的皮，5根磨損的憎惡縫合線，5塊奧金錠，5份萊斯·霜語的防腐液。$B$B另外你還必須支付50金幣的製作費用。','','去冬泉谷找永望鎮的瑪雷弗斯·暗錘。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5068 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5068,'zhTW','嗜血胸甲','據說嗜血胸甲只有一件，那是為最強的刺客迦羅娜製造的。迄今為止，是否還存在其它的事血胸甲仍然是個懸而未決的謎。$B$B但是！我們的工匠只要獲得必要的材料就可以將它複製出來：$B$B*比斯巨獸的皮。$B$B*磨損的憎惡縫合線。$B$B*奧金錠。$B$B*暗影之皮。','為了製造嗜血胸甲，你必須將下列物品交給瑪雷弗斯·暗錘：1塊比斯巨獸的皮，10根磨損的憎惡縫合線，5塊奧金錠，5塊暗影之皮。$B$B另外你還必須支付50金幣的製作費用。','','去冬泉谷找永望鎮的瑪雷弗斯·暗錘。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5081 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5081,'zhTW','麥克斯韋爾的任務','這條訊息正好彌補了我們對黑石塔情報的不足。$B$B本次進攻具有決定性的戰略意義，$N。$B$B首先，我們要消滅他們的主帥，巨魔沃恩。沒有他的戰鬥計劃，黑石獸人將陷入一片混亂之中。$B$B接下來，你必須除掉食人魔之王歐莫克。黑石塔裡那些膽小如鼠的食人魔如果沒有了他的指揮，就會變成一盤散沙。$B$B最後是黑石塔的核心將領維姆薩拉克。只要維姆薩拉克一死，他們的指揮中樞就會徹底癱瘓。','到黑石塔去消滅指揮官沃恩、歐莫克大王和維姆薩拉克。完成任務之後回到麥克斯韋爾元帥處覆命。','','去燃燒平原摩根的崗哨找麥克斯韋爾元帥。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5082 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5082,'zhTW','冬泉熊怪的威脅','我是來冬泉谷調查冰火溫泉的。我注意到這裡的泉水似乎有些……古怪。我暫時還沒有找出問題的根源，老實說，我最近遇到一些麻煩，都是那些冬泉熊怪在作祟。$B$B它們跟我一樣被吸引到了泉水附近。這些熊怪對水源的保護意識極強，不讓我接近北邊那兩處較大的溫泉。$B$B我想繼續進行研究，你能幫幫我嗎？','冬泉谷的多諾瓦·雪山要你去殺死8個冬泉探路者、8個冬泉巢穴守衛和8個冬泉圖騰師。','','去找冬泉谷的多諾瓦·雪山。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5083 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5083,'zhTW','冬泉火酒','你從冬泉熊怪那兒揀來的這隻小瓶子是空的，但是裡面有一些奇怪的綠色液體，它甚至發出了微微的光芒。$B$B這會是什麼重要的東西嗎？$B$B多諾瓦·雪山可能會告訴你更多的資訊，她在冬泉谷的溫泉附近有個營地。','將空的火酒瓶交給冬泉谷的多諾瓦·雪山。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5084 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5084,'zhTW','墮落熊怪','這種綠色液體……它讓我想起了費伍德森林中的那些淤泥。我還看見一些冬泉谷的信使進入了木喉要塞……也許這與你正在尋找的瓶子有關，$N。$B$B有一大群熊怪剛剛經過費伍德森林的木喉要塞，它們被稱為死木部族，惡魔的氣息讓它們墮落了。你為什麼不去周圍看看，找到冬泉谷熊怪和死木熊怪之間的關係？','搜尋費伍德森林北部的死木熊怪的營帳，繼續尋找線索。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5085 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5085,'zhTW','神秘的粘液','鍋裡沸騰的綠色物質看起來與你在小瓶子中找到的東西一樣。這種奇怪的粘液狀的物體可能與製造它的熊怪一樣，感染了嚴重的墮落力量……$B$B如果冬泉熊怪在使用它，那麼這是否意味著它們很快就會像死木部族一樣墮落？$B$B你最好趕快向多諾瓦彙報你的發現，順便從鍋裡採集一點液體樣本給她。','將你的發現報告給多諾瓦·雪山。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5086 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5086,'zhTW','劇毒之水','我研究了你取回來的樣本，雖然我還無法確定，但是我相信其中包含著有毒的成分。判斷這一點的唯一方法是收集其它類似的物質進行比較。$B$B我想死木熊怪也許會從費伍德森林的其它墮落生物那兒收集這些東西，尤其是生活在鐵木森林中的那種被稱作劇毒之水的元素生物。$B$B為我收集一些樣本以進行比較，但是要小心——那裡是個非常危險的地方！','為冬泉谷的多諾瓦·雪山收集3份劇毒水滴。','','去找冬泉谷的多諾瓦·雪山。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5087 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5087,'zhTW','冬泉信使','真有趣，$N……$B$B當這種有毒物質與溫泉裡的水混合的時候，它的毒性就消失了，對飲用者來說，它只會產生暫時的影響。這必定是冬泉熊怪如此熱衷於守護溫泉的原因——它們需要這些泉水來淨化火酒。$B$B我們必須阻止它們——截斷冬泉熊怪與死木熊怪之間的聯絡。有一隊冬泉熊怪的信使往返於它們的村子和費伍德森林之間。找到它們，把它們的貨物劫下來。','找到冬泉信使，阻止他們向冬泉村運送物品。','','去找冬泉谷的多諾瓦·雪山。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5088 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5088,'zhTW','阿利卡拉','把這些提純淨化的火巖粉拿到千針石林去，並灑在生命聖火之上。那團火焰位於黑雲峰的一根用於埋葬死者的石針上。$B$B我注入火巖粉中的魔法會將阿利卡拉召喚到你身旁，$N。$B$B我擔心她可能在追蹤凱恩·血蹄……牛頭人的觀念改變得太多了，而我擔心這一點激怒了阿利卡拉。在事情變得無法收拾之前趕快行動吧，$c！','殺死阿利卡拉。把她的遺體和火巖粉交給白沙崗哨的莫特加·火鬃作為證明。','點燃生命聖火','去千針石林找白沙崗哨的莫特加·火鬃。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5089 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5089,'zhTW','達基薩斯將軍的命令','你從屍體上發現了一封看上去很重要的信：一封來自於他的上級達基薩斯將軍的信，信的內容似乎跟某種協議有關。$B$B你的直覺告訴你，應該把它交給麥克斯韋爾元帥。','把達基薩斯將軍的命令交給燃燒平原的麥克斯韋爾元帥。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5090 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5090, 'zhTW', '戰鬥的號角:瘟疫之地!', '大家都聽著!大家都聽著!所有的英雄都應該聆聽這號召的聲音!暴風城已經發出了備戰的號召!所有勇士都應該拿起武器，一同面對來自東部王國北部地方天譴軍團的威脅!城中傳言四起，東部王國的廢墟中滋生出了新的威脅!它們已經在幽暗城東面的瘟疫之地大量集結，聯盟的安全岌岌可危!聯盟的英雄們-去向指揮官阿胥拉姆·瓦羅菲斯特報到吧，他的大本營就在奧特蘭克山脈北邊的冰風營地!', '找到指揮官阿胥拉姆·瓦羅菲斯特。他的大本營位於奧特蘭克山脈以北的冰風營地。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5091 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5091,'zhTW','戰鬥的號角：瘟疫之地！','大家都聽著！大家都聽著！所有的英雄都應該聆聽這號召的聲音！$B$B暴風城已經發出了備戰的號召！所有勇士都應該拿起武器，一同面對來自東部王國北部地區亡靈天災的威脅！城中傳言四起，東部王國的廢墟中滋生出了新的威脅！它們已經在幽暗城東面的瘟疫之地大量集結，聯盟的安全岌岌可危！$B$B聯盟的英雄們——去向指揮官阿什拉姆·瓦羅菲斯特報到吧，他的大本營就在奧特蘭克山脈北邊的冰風崗！','找到指揮官阿什拉姆·瓦羅菲斯特。他的大本營位於奧特蘭克山脈以北的冰風崗。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5092 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5092, 'zhTW', '掃清道路', '安多哈爾城西和城北的入口防守非常嚴密，我正在努力從防禦力較弱的東面入口尋找突破點。天譴軍團以佔據悔恨嶺的不死生物部隊所組成的第一道防線作為緩衝區，如果我們想要進攻安多哈爾的話，就必須穿過悔恨嶺。$B$B你的第一個任務是清除悔恨嶺一帶的障礙，掃除在這一地區出沒的骷髏和食屍鬼，任務完成之後就回來向我彙報!', '殺掉悔恨嶺中的10個骷髏撕掠者和10個被奴役的食屍鬼。$B$B然後向西瘟疫之地冰風營地的指揮官阿胥拉姆·瓦羅菲斯特覆命。', '', '去西瘟疫之地找冰風崗的指揮官阿胥拉姆·瓦羅菲斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5093 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5093, 'zhTW', '戰鬥的號角:瘟疫之地!', '部落的英雄們，請聆聽這召喚的聲音─部落召喚你們迅速行動起來!戰鬥的號角已經吹響，所有勇士都應拿起武器，準備與天譴軍團殊死作戰!城中傳言四起，東部王國的廢墟中滋生出了新的威脅!它們已經在幽暗城東面的瘟疫之地大量集結，部落的安全岌岌可危!部落的英雄們─去向高級執行官德靈頓報到吧，他的大本營就在提里斯法林地東部的亡靈壁壘!', '找到高級執行官德靈頓。他將自己的大本營建在提里斯法林地和幽暗城以東的亡靈壁壘。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5094 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5094, 'zhTW', '戰鬥的號角:瘟疫之地!', '部落的英雄們，請聆聽這召喚的聲音─部落召喚你們迅速行動起來!戰鬥的號角已經吹響，所有勇士都應拿起武器，準備與天譴軍團殊死作戰!城中傳言四起，東部王國的廢墟中滋生出了新的威脅!它們已經在幽暗城東面的瘟疫之地大量集結，部落的安全岌岌可危!部落的英雄們─去向高級執行官德靈頓報到吧，他的大本營就在提里斯法林地東部的亡靈壁壘!', '找到高級執行官德靈頓。他將自己的大本營建在提里斯法林地和幽暗城以東的亡靈壁壘。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5095 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5095, 'zhTW', '戰鬥的號角:瘟疫之地!', '部落的英雄們，請聆聽這召喚的聲音─部落召喚你們迅速行動起來!戰鬥的號角已經吹響，所有勇士都應拿起武器，準備與天譴軍團殊死作戰!城中傳言四起，東部王國的廢墟中滋生出了新的威脅!它們已經在幽暗城東面的瘟疫之地大量集結，部落的安全岌岌可危!部落的英雄們─去向高級執行官德靈頓報到吧，他的大本營就在提里斯法林地東部的亡靈壁壘!', '找到高級執行官德靈頓。他將自己的大本營建在提里斯法林地和幽暗城以東的亡靈壁壘。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5096 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5096, 'zhTW', '誤導血色十字軍', '在進軍安多哈爾之前，我們必須解決來自壁爐谷的血色十字軍的威脅。他們已經在費爾斯通農場和達爾松之淚中間建立了營地，這使得我們在對天譴軍團和十字軍的作戰中處於劣勢，風險激增。$B$B我的計畫是挑起他們之間的戰爭，你要做的就是去摧毀十字軍的指揮帳篷，使用這只箱子裡的燃燒瓶就行了。在點燃了帳篷之後，把天譴軍團戰旗插在他們的營地中。如果我們運氣夠好的話，十字軍就會對天譴軍團進行報復。', '到血色十字軍建在費爾斯通農場和達爾松之淚之間的營地去，摧毀他們的指揮帳篷。$B$B將天譴軍團戰旗插在營地中，然後回到西瘟疫之地亡靈壁壘的高級執行官德靈頓那兒。', '摧毀指揮帳篷並在營地插上天災旗幟', '去找提裏斯法林地的高級執行官德靈頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5097 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5097, 'zhTW', '標記哨塔', '通過使用一種被稱作信號火炬的魔法物品，我們可以為軍隊即將展開的行動標識出目標。我們認為天譴軍團正在將安多哈爾的哨塔作為控制軍隊的手段。$B$B你的任務就是突破安多哈爾的防線，將信標放置在四座哨塔中。你必須將信標放在每座哨塔的門口才行。信號火炬僅可使用五次，可別浪費了!', '使用信號火炬為安多哈爾城中的四座哨塔做上標記，你必須站在哨塔門口才能成功地進行標記。$B$B在做完了標記之後，將信號火炬還給西瘟疫之地冰風營地的指揮官阿胥拉姆·瓦羅菲斯特。', '', '去西瘟疫之地找冰風崗的指揮官阿胥拉姆·瓦羅菲斯特。', '標記第一座塔', '標記第二座塔', '標記第三座塔', '標記第四座塔', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5098 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5098, 'zhTW', '標記哨塔', '通過使用一種被稱作信號火炬的魔法物品，我們可以為軍隊即將展開的行動標識出目標。我們認為天譴軍團正在將安多哈爾的哨塔作為控制軍隊的手段。$B$B你的任務就是突破安多哈爾的防線，將信標放置在四座哨塔中。你必須將信標放在每座哨塔的門口才行。信號火炬僅可使用五次，可別浪費了!', '使用信號火炬為安多哈爾城中的四座哨塔做上標記，你必須站在哨塔門口才能成功地進行標記。$B$B在做完了標記之後，將信號火炬還給西瘟疫之地亡靈壁壘的高級執行官德靈頓。', '', '去找提裏斯法林地的高級執行官德靈頓。', '標記第一座塔', '標記第二座塔', '標記第三座塔', '標記第四座塔', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5101 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5101,'zhTW','暫無內容','哼！你以為這是什麼啊？ 測試任務嗎？ 就算文字有錯，我還是在那裡！$B$B如果你以為我的任務很簡單的話，那你就倒大楣了！$B$B幫我殺10只羊(1933)，在你完成前別回來見我！','幫本尼殺死六隻羊然後趕快瘋狂地跑開！$B$B$B$B\\r\\n\\r\\n跑開的部分是開玩笑的。','','去給你任務的班尼那裡。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5102 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5102,'zhTW','達基薩斯將軍之死','我們和這些怪物正在進行雙線作戰：在暴風城，我們努力不讓它們的魔爪深入城市；在燃燒平原，我們把戰火燒到它們門前。我們必須時刻保持著警惕，$N。當它們侵佔我們的領地，殘害我們家人的時候，我們要把怒火全部傾瀉出來。$B$B找到達基薩斯將軍，然後幹掉它！$B$B這個任務顯然不簡單，但是完成它所能得到的獎勵也是相當豐厚的。','到黑石塔去殺掉達基薩斯將軍，完成任務之後就回到麥克斯韋爾元帥那裡覆命。','','去燃燒平原摩根的崗哨找麥克斯韋爾元帥。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5103 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5103,'zhTW','火熱的死亡','這個人留下的只有一把燒焦了的骨頭。他似乎是死於他找到的東西——一副未淬火的板甲護手。$B$B也許你應該拿起那副手套，然後離開這裡？','世界上一定有人知道關於這副手套的事情，祝你好運！','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5121 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5121,'zhTW','冬泉酋長','雖然我們還不太清楚為什麼熊怪會吃下這種奇怪的物質，但我們最好儘快阻止它們。$B$B冬泉熊怪並不是一個好戰的部族，它們的巨大變化讓我認為它們一定是在執行領袖的命令。我們無法挽回它們已經造成的損失，但是我想，如果它們的領袖被除掉的話，事態至少不會進一步惡化。$B$B快去冬泉村吧。','冬泉谷的多諾瓦·雪山要你去擊敗冬泉酋長。','','去找冬泉谷的多諾瓦·雪山。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5122 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5122,'zhTW','信仰獎章','','','','去找奧裡克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5123 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5123,'zhTW','最後一片','你在冬泉酋長身上找到的日誌看起來內容豐富，但是看完幾頁之後，你發現自己完全看不懂這本書。上面的符號粗糙而又拙劣——你不禁懷疑是否真的有人能讀懂它們。$B$B不過，多諾瓦也許能告訴你這本書上寫了些什麼……','把潦草的日誌交給冬泉谷的多諾瓦·雪山。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5124 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5124,'zhTW','熾熱板甲護手','以索瑞森鬍鬚的名義！$B$B你是在哪兒找到這些東西的？$B$B更重要的是，你願意出售它們嗎？我自然會付給你豐厚的酬勞。$B$B我跟你說啊，$N，要是你把這些沒淬火的護手給我，我就教你如何打造自己的裝備。你要做的就是為我收集這些東西，這樣我就能獲得精確的配方了。$B$B你覺得怎麼樣？$B$B這是一張我需要的東西的列表，你把護手交給我之後，其它的材料我自己搞定。','將6塊魔化瑟銀錠、2份火焰精華和4顆紅寶石交給瑪雷弗斯·暗錘。另外你還得把未淬火的板甲護手也交給他。','','去冬泉谷找永望鎮的瑪雷弗斯·暗錘。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5125 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5125,'zhTW','奧裡克斯的清算','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5126 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5126,'zhTW','羅拉克斯的故事','那個薩特正在四處踱步並且自言自語。你想跟他搭話嗎？','與羅拉克斯談一談，聽聽他要說什麼。','聆聽羅拉克斯的故事','去冬泉谷找暗語峽谷的羅拉克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5127 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5127,'zhTW','惡魔熔爐','羅拉克斯做生意，但他不與那些無足輕重的凡人打交道。$B$B不過，我要跟你做一筆生意……帶上這支矛，它充滿著惡魔的強大能量，當你找到古拉魯克時，殺了他，然後用這支矛刺穿他的心臟。他的靈魂將被吸取，而這靈魂將為我所有。把長矛和他偷走的胸甲給我帶回來，然後我就會交給你他想要學習的東西。','到黑石塔去找到古拉魯克。殺死他，然後用血汙長矛刺入他的屍體。當他的靈魂被吸乾後，這支矛就會成為穿魂長矛。$B$B你還必須找到未鑄造的符文覆飾胸甲。$B$B將穿魂長矛和未鑄造的符文覆飾胸甲都交給冬泉谷的羅拉克斯。','','去冬泉谷找霜語峽谷的羅拉克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5128 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5128,'zhTW','熊怪酋長的話','冬泉熊怪對我而言已不是個威脅了，但是如果你仍然想要查出是什麼驅使熊怪製造並飲用這種奇怪的火酒，那麼你應該去尋求科雷克·望天的幫助。$B$B他是翡翠議會的成員，那個組織中的德魯伊都在致力於淨化和治癒費伍德森林的創傷。$B$B科雷克對費伍德森林中的熊怪非常瞭解，他可以告訴你更多關於這本日誌的資訊。$B$B再次感謝你，$N。','將潦草的日誌交給費伍德森林南部的科雷克·望天。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5141 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5141,'zhTW','龍鱗制皮','龍鱗制皮可不是件簡單的工作，但是收益也非常豐厚。我可以教你如何製造這件精良的鎖甲，但你得先同意我的一些條件。$B$B你選擇了這條路，就必須承諾永遠不會學習元素制皮技術或部族制皮技術，只能沿著這條路走下去。此外，你還必須製造一件蠍殼護甲。最後，我還要看看你是否有能力獲得製造護甲所必需的材料：龍類的鱗片。','將2套硬化蠍殼胸甲、2套硬化蠍殼手套和10片龍鱗交給艾薩拉的彼得·加林。$B$B完成這項任務之後，你就可以學到龍鱗制皮技術了。$B$B同時，你也將永遠無法學習元素制皮技術和部族制皮技術，在決定之前先考慮清楚。','','去艾薩拉找埃達拉斯廢墟的彼得·加林。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5142 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5142, 'zhTW', '小帕米拉', '在達隆郡戰役中，我們犧牲了很多人。很多人死了……甚至更糟……戰爭一開始，我就把我的侄女帕米拉藏了起來，我不知道她現在到底怎麼樣了。我只是一個遊魂，但是我一直很想知道帕米拉的下落。求求你，好心的$c，你能去達隆郡找她嗎?往東邊走，過了蓋羅恩農場就到達隆郡了。', '找尋帕米拉·雷德帕斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5143 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5143,'zhTW','部族制皮','要學習部族制皮技術，你就必須瞭解大自然最初的狀態。我知道你已經掌握了製造蠻皮護甲的技術，我很樂意幫助你完成訓練。$B$B要知道，$C，一旦你選擇了這條路，就得承諾永遠不會學習龍鱗制皮技術和元素制皮技術，你只能沿著自己選定的路走下去。此外，將你所能製造出來的最好的蠻皮護甲給我看看，然後我就可以向你傳授技藝了。','將1件蠻皮外衣和1件蠻皮頭盔交給菲拉斯的凱雷希亞·獵月。$B$B完成這項任務之後，你就可以學到部族制皮技術了。$B$B同時，你也將永遠無法學習元素制皮技術和龍鱗制皮技術，在決定之前先考慮清楚。','','去找菲拉斯的凱雷希亞·獵月。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5144 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5144,'zhTW','元素制皮','我熟知元素制皮的技藝，如果你願意敞開心扉學習更多的知識，那麼我願意與你分享我所知的一切。$B$B你要明白，$c：一旦你選擇了這條道路，就必須承諾永遠不學習龍鱗制皮或是部落制皮；你只能學習這三種手藝中的一種。此外，我需要你證明自己與大自然的元素有著融洽的關係，所以，你要將火、水、土和風元素最純淨的精華交給我。','將2個火焰之心、2個純水之球、2個大地之核和2個風之氣息交給灼熱峽谷的薩拉·坦尼。$B$B一旦你完成這項任務，就可以開始學習元素制皮技藝了。$B$B同時，你也就無法再學習龍鱗制皮和部落制皮了，在你決定之前要考慮清楚。','','去找灼熱峽谷製皮匠營地的薩拉·坦尼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5145 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5145,'zhTW','龍鱗制皮','龍鱗制皮可不是件簡單的工作，但是收益也非常豐厚。我可以教你如何製造這件精良的鎖甲，但你得先同意我的一些條件。$B$B你選擇了這條路，就必須承諾永遠不會學習元素制皮技術或部族制皮技術，只能沿著這條路走下去。此外，你還必須製造一件蠍殼護甲。最後，我還要看看你是否有能力獲得製造護甲所必需的材料：龍類的鱗片。','將2套硬化蠍殼胸甲、2套硬化蠍殼手套和10片龍鱗交給荒蕪之地的索卡夫·龍眼。$B$B完成這項任務之後，你就可以學到龍鱗制皮技術了。$B$B同時，你也將永遠無法學習元素制皮技術和部族制皮技術，在決定之前先考慮清楚。','','去找荒蕪之地的索卡夫·龍眼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5146 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5146,'zhTW','元素制皮','我熟知元素制皮的技藝，如果你願意敞開心扉學習更多的知識，那麼我願意與你分享我所知的一切。$B$B你要明白，$c：一旦你選擇了這條道路，就必須承諾永遠不學習龍鱗制皮或是部落制皮；你只能學習這三種手藝中的一種。此外，我需要你證明自己與大自然的元素有著融洽的關係，所以，你要將火、水、土和風元素最純淨的精華交給我。','將2個火焰之心、2個純水之球、2個大地之核和2個風之氣息交給阿拉希山脈的布魯姆·白蹄。$B$B一旦你完成這項任務，就可以開始學習元素制皮技藝了。$B$B同時，你也就無法再學習龍鱗制皮和部落制皮了，在你決定之前要考慮清楚。','','去阿拉希高地找博德戈爾的布魯姆·白蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5147 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5147,'zhTW','通緝：阿納克·恐怖圖騰','通緝：阿納克·恐怖圖騰$B$B流放者阿納克因罪大惡極的謀殺和綁架行為而被通緝。那些敢於將這名罪犯繩之以法的勇士將獲得豐厚的報酬。$B$B阿納克最後一次被發現是在黑雲峰附近的懸崖上。請向亂風崗的峭壁衛兵圖林·長角出示你殺死阿納克的證明。','殺死阿納克·恐怖圖騰，並向亂風崗的峭壁衛兵圖林·長角出示證據。','','去千針石林找亂風崗的峭壁衛兵圖林·長角。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5148 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5148,'zhTW','部族制皮','要學習部族制皮技術，你就必須瞭解大自然最初的狀態。我知道你已經掌握了製造蠻皮護甲的技術，我很樂意幫助你完成訓練。$B$B要知道，$C：一旦你選擇了這條路，就得承諾永遠不會學習龍鱗制皮技術和元素制皮技術，你只能沿著自己選定的路走下去。此外，將你所能製造出來的最好的蠻皮護甲給我看看，然後我就可以向你傳授技藝了。','將1件蠻皮外衣和1件蠻皮頭盔交給荊棘谷的瑟伊布。$B$B完成這項任務之後，你就可以學到部族制皮技術了。$B$B同時，你也將永遠無法學習元素制皮技術和龍鱗制皮技術，在決定之前先考慮清楚。','','去找荊棘谷的瑟伊布。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5149 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5149, 'zhTW', '帕米拉的洋娃娃', '瑪萊恩姑媽讓我留在家裡，因為我的爸爸出去作戰了。爸爸是世界上最勇敢的人!$B$B但是我在這裡等了很長時間，他一直都沒有回來。有時候會有壞人來和我說話，我想讓爸爸把他們趕走，但是他不在這裡!$B$B有時候，天黑了以後，我會和我的洋娃娃玩，但是我把它丟在鎮子裡了。$B$B你能不能去幫我找到洋娃娃呢?', '找到帕米拉的洋娃娃。', '', '去找東瘟疫之地的帕米拉·雷德帕斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5150 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5150,'zhTW','達丹加餓了！','','','','去找達丹加。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5151 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5151,'zhTW','超適應齒輪','我們的商隊被半人馬襲擊了，而我是唯一的倖存者！但是那頭罕見的黑豹守護著我最完美的發明，嗯，就掛在它的脖子上。哈哈！即使是半人馬也會在那頭兇猛的野獸面前顫抖！$B$B這是那個籠子的鑰匙。他們拿走了那裡所有的東西，但是把黑豹留在了那裡。把那頭野獸殺了，然後拿回我的超適應齒輪，我會好好獎勵你的。$B$B商隊的殘骸就在這裡的北面。','殺了那頭野獸，把超適應齒輪和鑰匙交給維茲羅。','','去千針石林找白沙崗哨的維茲羅。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5152 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5152, 'zhTW', '瑪萊恩姑媽', '啊，我感到好孤獨!我的家人在哪裡?瑪萊恩姑媽要我在這裡等，但是她就這樣一去不復返了!還有我的父親……你看到過他沒有?也許瑪萊恩姑媽知道他在哪裡。她住在安多哈爾附近，在靠南邊的一座房子裡。我想那房子是在一座小山上……她說過房子在山上。請你幫幫忙，$N。你是我的新朋友!你可以幫我去找我的姑媽嗎?', '與安多哈爾廢墟南邊的瑪萊恩談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5153 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5153,'zhTW','古怪的歷史學家','我希望約瑟夫重新回到她女兒身邊，但是這已經不可能了。他的靈魂已經屬於亡靈天災，他已經變成了一個怪物。唉，他命中註定如此！$B$B但是，也許我們能改變他的命運。$B$B在墓地外圍尋找約瑟夫的墓碑。他的軀體不在那裡，因為他已經在幾年前灰飛煙滅了，但是在墓碑下埋著他的戒指。把戒指交給克羅米……那是個具有強大魔法力量的侏儒。$B$B克羅米在安多哈爾南牆附近的旅館廢墟中。','把約瑟夫的結婚戒指交給安多哈爾的克羅米。','','去西瘟疫之地找安多哈爾廢墟的克羅米。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5154 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5154, 'zhTW', '達隆郡的歷史', '要拯救約瑟夫·雷德帕斯，我們首先得找到他的過去。安多哈爾城鎮中心有一本書，名叫《達隆郡的歷史》，它可以告訴我們一些重要的事情。$B$B把書拿來給我，然後我們就可以了解約瑟夫的命運，如果運氣好的話……我們還能改變它!', '把《達隆郡的歷史》交給安多哈爾的克羅米。', '', '去西瘟疫之地找安多哈爾廢墟的克羅米。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5155 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5155,'zhTW','加德納爾的勢力','如果要我完全信任你的話，你就必須先證明自己的實力。$B$B我必須確信你可以擊敗暗影議會。$B$B到費伍德森林的深處去，你可以在路的西邊看到一條通往加德納爾的小徑。暗影議會就在那裡與燃燒軍團密謀著邪惡的計劃。$B$B進入被腐化的獸穴，然後殺了他們的成員。當你完成任務之後再回到我這裡來。這樣我可以相信你是真的想要幫助我們了。','到加德納爾去殺掉4個加德納爾惡犬、4個加德納爾守護者、6個加德納爾精兵和6個加德納爾祭司，然後向費伍德森林的格雷塔·苔蹄覆命。','','去費伍德森林找翡翠聖地的格雷塔·苔蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5156 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5156,'zhTW','驗證腐蝕','在這裡的北面，沿著大路向東看，你可以找到一處被稱作碎痕谷的地方，那裡是上次戰爭中燃燒軍團的地獄火惡魔們的著陸點——迄今仍有許多地獄火在那裡遊蕩。$B$B我感興趣的有兩件事情。首先，那裡是否還有被汙染的元素生物？其次，那些凹坑中是否還充滿了墮落的惡臭之水？你能幫我去看看嗎，$N？小心一些，地獄火可是會攻擊它們看到的一切東西的。','殺掉2個熱能野獸和2個熱能恐獸，並探索碎痕谷。然後檢視凹坑中是否仍然充滿了墮落的惡臭之水，完成這些任務之後，向費伍德森林中的塔諾恩·紅羽覆命。','探索碎痕谷','去費伍德森林找翡翠聖地的塔諾恩·紅羽。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5157 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5157,'zhTW','收集墮落之水','在加德納爾深處有一座暗影堡，那裡是墮落和邪惡的主要源頭。$B$B暗影議會使用幾座火盆製造防護結界，將他們的巢穴保護了起來。$B$B如果我想要透過占卜來獲得更多有關他們的情報，那你首先要想辦法熄滅那些火盆，然後我就可以偵測暗影議會並找到究竟是誰在領導他們了。$B$B如果你願意幫忙的話，拿著這隻水壺，用它在加德納爾中心的月亮井中裝滿水，然後回到我這裡來。','把空壺拿到加德納爾中心的月亮井去，裝滿井水之後再回到費伍德森林的格雷塔·苔蹄那裡。','','去費伍德森林找翡翠聖地的格雷塔·苔蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5158 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5158,'zhTW','水之魂的幫助','把腐化的月亮井水拿到貧瘠之地去，$N。棘齒城南面的海岸邊上住著我的一個老朋友，水之先知伊斯倫。她是個強大的薩滿祭司，並且願意幫助我們。她和水之魂的關係不錯，我們高尚的目標一定可以讓她和水之魂出手幫助我們。$B$B你可以在水邊的一個小帳篷中找到她。另外，$N，不要管那些海盜……他們對你完全不構成威脅。','把腐化的月亮井水交給貧瘠之地的水之先知伊斯倫。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5159 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5159,'zhTW','淨化過的水','感謝水之魂，$N。它們答應幫助你了。$B$B現在我就把這瓶淨化好的水交給你。代我向格雷塔問好，她正在做的事情比我們大多數人所做的事情都要偉大……我確信不久之後她也會發現這一點的。$B$B不要小看暗影議會的力量，$N。記住這一點。$B$B現在就出發吧，把水交給格雷塔。','把淨化過的月亮井水交給費伍德森林的格雷塔·苔蹄。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5160 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5160,'zhTW','監護者','到卡利姆多去，$r。我們藍龍軍團在寒冷的冬泉谷定居。在你到達冬泉谷之後，就去尋找麥索瑞爾洞穴。$B$B在麥索瑞爾的冰冷的地板上，你將會找到鈷藍色的符文。拿著我的鱗片站在某個符文上，你就會被傳送到哈爾琳身邊, 她是我們的監護者。$B$B把鱗片交給她，讓她用水晶球占卜一下我在這個可怕的地方所看到和感覺到的是什麼。','到冬泉谷去找到哈爾琳，把奧比的鱗片交給她。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5161 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5161,'zhTW','藍龍之怒','我們瞭解那些被詛咒的死亡之翼的後代想要做什麼，我們不能讓它們得逞。$B$B由於黑石山脈對奈法利安有著天然的保護作用，我們根本無法與它們進行溝通。$B$B但是，我們可以授權給你，$r——你必須這麼做。$B$B你眼前的道路充滿了危險，你必須決定是否接受我們的幫助。考慮一下，決定之後再找我談談吧。','要是你想繼續的話，就與哈爾琳談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5162 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5162,'zhTW','藍龍之怒','我所駕馭的是魔法的力量，而這魔法的力量將把你送到下一個目的地。$B$B當你準備好之後，你的旅程就將開始。你將前往瘟疫之地，與耶茲巴見面。$B$B他是個睿智的的精靈，他像亙古不變的大地那樣富有耐心。到安多哈爾去找他。','與瘟疫之地的耶茲巴交談。他居住在安多哈爾。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5163 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5163,'zhTW','雪怪計劃！','搞定！$B$B現在，我已經給我的朋友們發信了，說是我有個驚喜要給他們看看。這就是你要做的事情！$B$B我要把機械雪人給你，然後你就去訪問我所有的朋友並給他們一個驚喜，啟動機械雪人，然後讓他們大開眼界！$B$B讓永望鎮的萊加奇、加基森的斯普琳科，還有馬紹爾營地的奎克希爾看看它，然後回來告訴我他們有什麼反應！$B$B別忘了把我的雪人也帶回來。','帶著烏米的機械雪人去嚇唬她的朋友：$B$B永望鎮的萊加奇（冬泉谷）、加基森的斯普琳科（塔納利斯），還有馬紹爾營地的奎克希爾（安戈洛環形山）。$B$B當你完成任務之後，把機械雪人還給烏米。','','去冬泉谷找永望鎮的烏米。','嚇唬萊加奇','嚇唬斯普琳科','嚇唬奎克希爾','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5164 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5164,'zhTW','遊蕩者目錄','這是一個更好的選擇，但是哈爾琳肯定不會選擇它。閱讀遊蕩者目錄，得到它的啟示。$B$B如果你堅持……如果你完成它交給你的任務……如果你能活下來……那麼你將成為一名英雄。','閱讀遊蕩者目錄。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5165 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5165,'zhTW','熄滅火焰','現在，你必須回到加德納爾去。那些火盆分佈在暗影堡中，熄滅它們的火焰，這樣保護暗影議會的屏障就會消失一段時間——我正在等待著那個時刻的到來。如果你成功了，我就會仔細檢視暗影堡，然後找出他們的頭目。然後，我們將決定是否發起正面攻擊。','使用淨化過的月亮井水熄滅暗影堡內部的四座火盆的火焰，從而破除其保護效果，然後向翡翠聖地的格雷塔·苔蹄覆命。','','去費伍德森林找翡翠聖地的格雷塔·苔蹄。','熄滅痛苦火盆','熄滅怨意火盆','熄滅受難火盆','熄滅仇恨火盆',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5166 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5166,'zhTW','多彩巨龍胸甲','鑄造一件足以抵禦彩色巨龍冷酷攻擊的胸甲，就必須使用最堅硬的材料。$B$B我們需要把成年彩色巨龍的多彩龍鱗和那些被我們擊敗的兇殘的野獸的外皮縫合在一起。這些東西的存在並不為人所知，願它們永不存在於這個世界。$B$B另外，最難以得到的東西就是英雄之血。$B$B雕刻者將會為你完成鑄造。','為了鑄造多彩巨龍胸甲，你必須把以下材料交給雕刻者耶茲巴：$B$B1塊多彩龍鱗。$B$B10塊閃亮的彩色龍鱗。$B$B10份英雄之血。$B$B10塊磨損的憎惡縫合線。','','去西瘟疫之地找安多哈爾廢墟的耶茲巴。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5167 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5167,'zhTW','多彩挑戰者腿甲','成年彩色巨龍的外殼是製造護腿的基礎。彩色龍鱗將被用於製作鑲邊，最後在英雄之血中進行洗禮。最後，暗影之皮的力量將被注入護腿中。','為了鑄造多彩挑戰者腿甲，你必須把以下材料交給雕刻者耶茲巴：$B$B1塊多彩龍鱗。$B$B10塊閃亮的彩色龍鱗。$B$B10份英雄之血。$B$B5塊暗影之皮。','','去西瘟疫之地找安多哈爾廢墟的耶茲巴。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5168 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5168, 'zhTW', '達隆郡的英雄', '我永遠銘記著達隆郡的英雄，你帶給我的這本《達隆鎮的歷史》中就講述了他們的故事。$B$B書中提到了聖騎士達維·萊法爾，還提到了血色十字軍把他的聖契放在壁爐谷的城鎮大廳中。$B$B書中還提到了我的兄弟，雷德帕斯隊長。在他叛變之後，他的盾牌被擊碎並拋棄了，它就被扔在一個看起來最不可思議的地方─靠近蓋羅恩農場的穀倉那裡。$B$B收集那些被命運和悲劇籠罩的聖物，$N。', '把達維的聖契和雷德帕斯之盾交給卡林·雷德帕斯。', '', '去東瘟疫之地找聖光之願禮拜堂的卡林·雷德帕斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5181 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5181, 'zhTW', '達隆郡的惡魔', '《達隆郡的歷史》講述了那場戰役中的幾個天譴軍團頭目。聯盟在這場戰役中如何殺死了食屍鬼之王，『劫毀者』霍古斯。他的屍體被扔到考林路口西北面的湖泊中，現在他的頭顱還在那兒呢。$B$B黑衣瑪杜克從未吃過敗仗，但是他的劍卻被擊落，留在了考林路口西面的山谷底部。$B$B去找回顱骨和寶劍吧，$N。我不清楚原因，但是我知道它們的命運是跟你有關聯的。', '將霍古斯的顱骨和馬杜克的破碎之劍交給聖光之願禮拜堂的卡林·雷德帕斯。', '', '去東瘟疫之地找聖光之願禮拜堂的卡林·雷德帕斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5201 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5201,'zhTW','冬泉熊怪的侵擾','大多數人都不知道我在這裡，$N。但是，在冬泉谷有個許久以來揮之不去的大麻煩：冬泉熊怪。$B$B我可從來沒有直接跟熊怪發生過沖突，它們極度癲狂，對面前的一切事物都毫不畏懼。我曾看到熊怪殘殺無數生物，而這些不幸的生物慘遭殺戮的原因無非是擋了熊怪的路。$B$B我對它們的胡作非為感到厭煩——請幫幫我，代替月神懲罰它們吧。殺死熊怪，讓它們永遠也不敢侵入霜刀石！','雷沃·霜翼要你去殺死5個冬泉薩滿祭司和5個冬泉巨熊怪。','','去冬泉谷找霜刀石的雷沃·霜翼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5202 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5202,'zhTW','奇怪的紅鑰匙','這把紅色的小鑰匙似乎是由某種骨頭製成的。它非常沉重，但是看上去卻非常脆弱。為什麼暗影議會的成員會拿著這樣的東西呢？或許在加德納爾內部有什麼東西可以用這把奇怪的鑰匙開啟。','搜尋加德納爾，找出血紅鑰匙的用途。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5203 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5203,'zhTW','逃出加德納爾','雖然我承受了很大的痛苦，但是有件事情我們必須先做好：我要找到特雷·萊弗治，然後從暗影堡逃出去，把這裡所發生的一切都報告給我們的上司。你能幫我嗎，$N？$B$B我的裝備就在離這裡不遠的地方，而且你已經證明了你的實力。$B$B在我們逃脫之後，我會去達納蘇斯，請你到梣谷的邊界地帶去找到傑希爾。她應該在那裡的翡翠議會營地中。$B$B你認為怎麼樣，$n？你能再幫我一次嗎？','護送亞科納琳到萊弗治和她的裝備所在的地方，然後保護她逃離暗影堡。之後，在費伍德森林找傑希爾·月弓，並告訴她剛才發生的事情。','保護亞科納琳逃出暗影堡','去費伍德森林找翡翠聖地的傑希爾·月弓。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5204 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5204,'zhTW','光明的懲戒','她假裝自己沒事。她希望我認為她有足夠堅強，可以獨自承擔所有的悲傷，這一點我很清楚。特雷的死和他被折磨時發出的慘叫會讓她在很長一段時間裡都被痛苦煎熬，我們對此無能為力。但是我們至少可以給她一些安慰！$B$B$N，回到暗影堡去，殺了折磨特雷的混蛋，並找回他的遺體。在亞科納琳默默承受痛苦的時候，我們可不能留在這裡什麼事情都不做。','回到加德納爾殺了魅魔拉凱雅，然後找到特雷·萊弗治的殘骸。','','去費伍德森林找加德納爾的特雷·萊弗治的殘骸。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5205 AND `locale` = 'zhTW';
