INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5225, 'zhTW', '目標:蓋羅恩農場', '最後的一口瘟疫之鍋在一個被稱作蓋羅恩農場的地方，由天譴軍團中較為強大的爪牙守衛著─那裡的鬼魂和怨靈尤其危險。你可不能掉以輕心，$N。$B$B蓋羅恩農場在這裡的東北方向，靠近東瘟疫之地的邊界。和以前一樣，消滅那裡的護鍋領主以獲取他的鑰匙。拿著這個空樣品瓶，把它裝滿給我拿回來。願聖光護佑你平安完成這次危險的任務，$c。', '到西瘟疫之地的蓋羅恩農場去，找到並擊敗那裡的護鍋領主，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶蓋羅恩農場的空瓶來採集瘟疫之鍋中的毒藥樣本。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5226 AND `locale` = 'zhTW';
