INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5228,'zhTW','瘟疫之鍋','在洛丹倫的土地上有八口瘟疫之鍋，其中四口在西瘟疫之地，另外四口在東瘟疫之地。這些瘟疫之鍋不斷向空中噴出毒氣，將天災軍團的瘟疫傳播到整個大地。$B$B克爾蘇加德的力量太強大了，我們無法關掉這些瘟疫之鍋，但是我想我們可能有辦法利用它們。我的助手，暗影牧師範蒂絲負責此項任務的執行，你去找她談談吧。','與西瘟疫之地亡靈壁壘的暗影牧師範蒂絲談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5229 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5229,'zhTW','目標：費爾斯通農場','在西瘟疫之地的四口瘟疫之鍋中，費爾斯通農場裡的那一口可能是最容易進入的了。亡靈天災在那邊駐紮的都是新兵，儘管他們也不是輕易可以擊敗的對手，但相對來說畢竟容易一些。$B$B到費爾斯通農場去，它就在這裡的正東方，安多哈爾的西北方，並與那裡的護鍋者交戰。它身上有一把可以開啟瘟疫之鍋的鑰匙。當你開啟那口鍋之後，用這個瓶子裝滿鍋裡的毒藥樣品，我們要對它進行研究以製造出一種解藥。','到西瘟疫之地的費爾斯通農場去，找到並擊敗那裡的護鍋者，用它的鑰匙開啟瘟疫之鍋。你必須隨身攜帶費爾斯通農場的空瓶來採集瘟疫之鍋中的毒藥樣本。','','去西瘟疫之地的費爾斯通農場解鎖天災之鍋。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5230 AND `locale` = 'zhTW';
