INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5241,'zhTW','卡林叔叔','有時，在夜裡，我能聽到我的叔叔卡林在哭，但那哭聲聽起來好像是從很遙遠的東邊傳過來的。$B$B我希望他不是在為我哭泣！$N，你能找到我的叔叔並告訴他我過得很好嗎？$B$B如果你找到他，跟他說我在等他，還有我想聽他過去常講的故事……那個關於兔子和果醬的故事！那個故事可真有趣！','找到卡林·瑞德巴思。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5242 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5242,'zhTW','最終一擊','不幸的是，我認為唯一可以解決暗影議會的方法就是從正面進攻。沒有別的方法進入暗影堡，我也沒有辦法把你傳送進去。通往底部的筆直小徑是唯一的通路……而且我也知道你的目標是誰。他的名字是費爾丹……暗影領主費爾丹。他就是暗影堡的頭目。殺了他和他的兩個魅魔僕從，然後回到我這兒來。費爾丹與燃燒軍團定下了盟約，你必須除掉他！','殺掉米萊恩和薩莉亞，並把暗影領主費爾丹的頭顱交給費伍德森林的格雷塔·苔蹄。','','去費伍德森林找翡翠聖地的格雷塔·苔蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5243 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5243,'zhTW','神聖之屋','我把我的非死非生的狀態看作一種疾病，$c。一種幾乎不需要治療的疾病。然而，它也是對銀色黎明的祝福。還有什麼辦法比透過亡靈來打擊天災軍團更有效呢？$B$B我的同事尊敬我，因為我做出了犧牲，但讚美和榮譽對我毫無意義。$B$B如果你有興趣幫助銀色黎明，那麼我可以提供你一項任務。$B$B到斯坦索姆去找回我們剩餘的聖水，在城中的補給箱裡找一找吧。','到北方的斯坦索姆去，尋找散落在城市中的補給箱，並收集5瓶斯坦索姆聖水。當你找到足夠的聖水之後就回去向萊尼德·巴薩羅梅覆命。','','去東瘟疫之地的聖光之願禮拜堂找萊尼德·巴薩羅梅。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5244 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5244,'zhTW','凱斯利爾廢墟','凱斯利爾背後的故事是關於一個被詛咒的種族的,這個種族被困在在他們試圖進行一場典禮的地方……$B$B你會在那裡找到的上層精靈從前偷了一個聖物，它們相信可以把它的力量吸出供自己使用，以使自己變得更加強大。在他們試圖吸取其力量時，這個遺物在一場大爆炸中粉碎了，碎片被埋在了湖面的冰下……$B$B如果你想知道更多的話去找加隆·石矛談話；他最近剛去過這一地區可以告訴你更多事情。','與墜星村的加隆·石矛談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5245 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5245,'zhTW','凱斯利爾的怨靈','那些上層精靈的靈魂是非常悲慘的，他們仍在尋找那件詛咒了他們、使他們被困在凱斯利爾的古代遺物的碎片。$B$B如果你感興趣的話，拿著我的鎬到南方的湖邊去，看看你能否從冰裡找到它的碎片。$B$B眼下我不能告訴你任何有關這些碎片的事，但我知道誰可以……奧蘿拉，她就住在東瘟疫之地北部的北地哨塔附近。','使用加隆的鎬來尋找四塊上層精靈遺物的碎片，把它們交給東瘟疫之地的奧蘿拉。','','去找東瘟疫之地的奧蘿拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5246 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5246, 'zhTW', '歷史的殘片', '我沒有意識到……請原諒我無情的話語，$c。$B$B我並不想回顧祖先犯下的錯誤，但是如果你的請求是真心的，那麼我會幫助你。$B$B<奧蘿拉查看了一下這些碎片>$B$B我相信這就是辛瑪洛水晶，一種具有強大的魔法力量並可以控制更強大力量的神器。它原本是用來做善事的，但那些偷走它的竊賊的邪惡力量使它破碎了。$B$B到艾薩拉的辛瑪洛神殿去─希望那本書還放在那裡。', '在艾薩拉的辛瑪洛神殿裡，找到神聖的精靈貴族筆跡。然後交給奧蘿拉，她就靠近東瘟疫之地的北地哨塔。', '', '去找東瘟疫之地的奧蘿拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5247 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5247, 'zhTW', '歷史的殘片', '如果你真的希望重塑神器，那我就可以幫助你。$B$B為了修復碎片，我需要一些具有強大魔法能量的物品。一塊附魔瑟銀錠和五塊恢復水晶……你還得從一個非常危險的地方搜集一些水……在菲拉斯地區的厄運之槌中，艾德雷斯區有一個厄運之池，用池中的水裝滿這只小瓶。$B$B在你去收集這些東西的時候，我會嘗試從書中找到復原神器所需的知識。', '給接近東瘟疫之地的奧蘿拉帶1塊附魔瑟銀錠、5塊恢復水晶，以及1小瓶恐怖之水。', '', '去找東瘟疫之地的奧蘿拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5248 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5248, 'zhTW', '記憶的折磨', '$N，我為過去所發生的事情哭泣。就像這塊水晶一樣，精靈這個種族已經破碎了。我不知道這些碎片是否還能被拼成一塊，但是能夠幫你完成這項小小的任務，這令我的悲痛減輕了許多。$B$B我們決不能忘記過去，$N……$B$B請把辛瑪洛水晶帶回凱斯利爾湖去，你必須尋找一個意識到這個錯誤的精靈貴族，讓他看到我們已經糾正了他們犯下的彌天大錯。', '把辛瑪洛水晶帶回冬泉谷的凱斯利爾湖，在那裡尋找一個會與你講話的精靈貴族。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5249 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5249,'zhTW','前往冬泉谷！','在冬泉谷，也就是這裡北面的極寒之地，有許多遠古的精靈遺蹟。那是一塊荒涼的土地，但它藏著許多秘密和有待探索的地方。$B$B因為我在費伍德森林這裡還有事情要做，因此我沒有機會到冬泉谷去。但你如果不去可就沒有理由了！$B$B你到了冬泉谷之後，就去墜星村找到維恩德·夜風，他非常瞭解那片土地。','找到冬泉谷的墜星村，在那裡與維恩德·夜風談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5250 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5250,'zhTW','墜星村','在冬泉谷，也就是這裡北面的極寒之地，有許多遠古的精靈遺蹟。那是一塊荒涼的土地，但它藏著許多秘密和有待探索的地方。$B$B因為我在費伍德森林這裡還有事情要做，因此我沒有機會到冬泉谷去。但你如果不去可就沒有理由了！$B$B你到了冬泉谷之後，就去墜星村找到維恩德·夜風，他非常瞭解那片土地。$B$B告訴他你是我的學生……','找到冬泉谷的墜星村，在那裡與維恩德·夜風談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5251 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5251,'zhTW','檔案管理員','所謂物極必反，血色十字軍就是這樣的典型。你認為他們盲目的狂熱會有好結果嗎？他們以聖光的名義殘害了多少無辜的人？$B$B他們都是該死的惡徒！$B$B我對他們中的一個成員最為關注，那就是斯坦索姆的檔案管理員加爾福特，他看管著十字軍最寶貴的檔案檔案。殺了他，然後燒燬那些文件！如果你成功了，就回到我這裡來，你會得到獎勵的。','在斯坦索姆城中找到血色十字軍的檔案管理員加爾福特，殺掉他，然後燒燬血色十字軍檔案。','','去東瘟疫之地找聖光之願禮拜堂的尼古拉斯·瑟倫霍夫公爵。','','燒燬文件','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5252 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5252,'zhTW','悔恨的上層精靈','那塊……水晶……$B$B這裡的上層精靈被他們的過錯折磨著……$B$B我感到很悲傷，但是我意識到了很久之前我們犯下的錯誤。雖然我們沒有辦法糾正這個過錯，但是你拿回了辛瑪洛水晶，現在我終於可以安息了……$B$B你必須歸還它……$B$B必須……','和墜星村的維恩德·夜風談一談，瞭解到辛瑪洛水晶所在的位置。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5253 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5253,'zhTW','辛瑪洛水晶','你給我留下了深刻的印象，$N。$B$B辛瑪洛水晶永遠都無法重回神殿，你應該知道的，它已經變成了廢墟。但是我相信你對抗邪惡力量的努力會得到回報的。$B$B到達納蘇斯去找大德魯伊範達爾·鹿盔，然後把水晶交給他，$N。這樣水晶就不會再次落到居心叵測的人手中了。根據我的觀察，只有極其強大的魔法使用者才能控制水晶的力量。','將辛瑪洛水晶送到達納蘇斯的大德魯伊範達爾·鹿盔那裡。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5261 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5261, 'zhTW', '伊根·派特斯金納', '伊根·派特斯金納正在找人幫他獵捕狼。這是個好消息，因為現在北郡山谷裡的狼實在是太多了。如果你感興趣的話，那就去和伊根談談吧。他就在修道院的左邊。', '與伊根·派特斯金納談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5262 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5262,'zhTW','可怕的真相','當房間中的塵埃逐漸落定的時候，你努力整理著自己的思路。在回憶了一遍剛剛發生的事情之後，你似乎還是無法相信這一切。$B$B血色十字軍的頭號人物是個惡魔？不僅僅是惡魔，他還是幽暗城中的瓦里瑪薩斯的兄弟？$B$B你小心地將恐懼之王的頭顱砍下，然後裝入包中。顯然，如果沒有證據的話,沒有人會相信你所說的。$B$B你必須馬上讓尼古拉斯·瑟倫霍夫公爵得知這個訊息！','將巴納扎爾的頭顱交給東瘟疫之地的尼古拉斯·瑟倫霍夫公爵。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5263 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5263,'zhTW','超越','你很能幹，而且你一直遵從我的命令。我很少見到同時具備這兩點的$c。現在我相信你可以執行神聖的正義。$B$B<瑟倫霍夫雙手合十，並把它們舉到面前。>$B$B克爾蘇加德的大將駐守在斯坦索姆。向我證明你是一個勇士——我的勇士。除掉瑞文戴爾男爵，把他的頭顱給我帶回來。','到斯坦索姆去殺掉瑞文戴爾男爵，把他的頭顱交給尼古拉斯·瑟倫霍夫公爵。','','去東瘟疫之地找聖光之願禮拜堂的尼古拉斯·瑟倫霍夫公爵。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5264 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5264,'zhTW','瑪克斯韋爾·泰羅索斯男爵','你即將獲得最崇高的榮譽，$N。$B$B瑪克斯韋爾男爵會因你對銀色黎明所做的貢獻而嘉獎你！$B$B瑪克斯韋爾已經有很多年沒有嘉獎過外人了。','和瑪克斯韋爾·泰羅索斯男爵談一談。他就在教堂裡面。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5265 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5265,'zhTW','銀色黎明寶箱','許多年來，銀色黎明寶箱都一直鎖著，沒有人能得到開啟它的殊榮——直到今天。$B$B銀色黎明寶箱現在為你敞開，$N。','開啟銀色黎明寶箱，拿取你應得的獎勵。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5281 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5281, 'zhTW', '永不安息的靈魂', '在斯坦索姆淪陷的時候，許多人都悲慘地死去了。其中許多人是自殺的，他們寧願選擇葬身火海，也不願成為天譴軍團的一員。現在他們成了永遠也不得安息的幽靈，在斯坦索姆的街道上到處遊蕩。我們必須拯救他們，$N!我有一個名叫伊根的同伴，他多年來對鬼魂和幽靈進行了大量的研究，你可以去找他幫忙。伊根正在斯坦索姆附近的東瘟疫之地對他的新發明進行測試。', '找到伊根。你只知道他在斯坦索姆附近。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5282 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5282,'zhTW','永不安息的靈魂','對亡靈的憤怒是我力量的源泉，也是我繼續生存下去的動力。但是，我不是個沒大腦的狂熱分子。總有些人——比如血色十字軍，他們只知道瘋狂地摧毀一切亡靈，但從來也沒想過要對他們有哪怕一丁點的同情。$B$B所以我發明了這樣一件東西：衝擊器。它可以解放斯坦索姆城中的那些痛苦的靈魂。$B$B對那些在街道上游蕩的鬼魂使用它，讓他們的靈魂獲得自由吧。','對斯坦索姆城中的鬼魂使用埃根的衝擊器。當那些永不安息的靈魂掙脫他們的外殼時，再次使用埃根的衝擊器——他們就可以獲得自由了！$B$B解放15個永不安息的靈魂，然後回到埃根那裡去。','','去東瘟疫之地找恐懼谷的埃根。','已解放靈魂','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5283 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5283,'zhTW','鑄造護甲的藝術','這麼說，你做出了明智的決定。$B$B對我來說，鑄造護甲就是我的愛好。那些整天打造玩具刀槍的根本不知道什麼是鍛造。$B$B有了絕佳的防護，才能取得戰爭的勝利。當戰爭的優勢不在你這邊時，任何武器都沒法幫你擺脫困境。$B$B好吧，我們開始工作吧。首先你必須證明自己已經學會了一些粗略的手藝。然後，我將把你塑造成一名真正的護甲鑄造師。你應該知道如何製造精製秘銀護甲，對吧？','要想成為一名護甲鑄造師的話，你必須將下列物品交給格魯努斯：4頂精製秘銀頭盔、2雙精製秘銀戰靴和1副精製秘銀胸甲。','','去找丹莫洛的格魯努斯·削鋼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5284 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5284,'zhTW','武器鑄造師之道','作為一名武器鑄造師，你將發現英雄和冒險者們會經常來向你購買裝備。雖然你應該可以承受這繁重的工作量，但是你所得的錢財會有一大部分耗費在治療肌肉拉傷和肺塵病上。$B$B哦，沒錯，$N，武器鑄造師擁有驚人的財富！$B$B要是你想成為我們當中的一員，就必須證明自己能幫我賺——我的意思是，你必須要證明，當人們需要高質量的武器時，他們會來找你而不是別人。去工作吧！','要想成為一名武器鑄造師的話，你必須將下列物品交給埃隆努斯·冷鋼：4把月鋼寬劍、4把巨型鐵斧、2把秘銀重斧和2把巨型黑色錘。','','去鐵爐堡找大鍛爐的埃隆努斯·冷鋼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5301 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5301,'zhTW','鑄造護甲的藝術','我很滿意。我對自己使用鐵錘和鐵砧製造出的東西感到滿意。每當看到驕傲的部落士兵身穿著由我打造的鋼鐵鎧甲，我就能體會到活著的意義。永不放棄是我不變的信念，$N。$B$B我無法將自己的滿足感分給你，我只能引導你前進。盡你的全力，成為護甲鑄造師的道路就像一次漫長的旅程。$B$B如果你想要成為技藝精湛的護甲鑄造師，就告訴我吧，我將對你進行訓練，但在此之前你必須完成一項任務。','要想成為一名護甲鑄造師的話，你必須將下列物品交給奧克索斯：4頂精製秘銀頭盔、2雙精製秘銀戰靴和1副精製秘銀胸甲。','','去找奧格瑪的奧克索斯·鐵怒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5302 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5302,'zhTW','武器鑄造師之道','總有一天，我要製造出一把無以倫比的鐵錘，配得上酋長的鐵錘！$B$B這是我畢生的工作，$N，也是我的激情所在。我認為你有潛力成為我們中的一份子，成為一名武器鑄造師。我可以幫助你發揮自己的潛能。$B$B你只需完成一項簡單的任務，讓我來看看你夠不夠資格。','要想成為一名武器鑄造師的話，你必須將下列物品交給伯古什：4把月鋼寬劍、4把巨型鐵斧、2把秘銀重斧和2把巨型黑色錘。','','去找奧格瑪的伯古什。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5303 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5303,'zhTW','暫無內容','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5304 AND `locale` = 'zhTW';
