INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5305,'zhTW','甜美的平靜','平靜之劍位於血色堡壘內，紅衣鑄錘師以生命守護著它。打敗他，並將他的圍裙交給我。作為報答，我將訓練你成為鍛造戰錘的鐵匠。','到斯坦索姆去殺死紅衣鑄錘師。將紅衣鑄錘師的圍裙交給莉莉絲。','','去冬泉谷找永望鎮的輕盈的莉莉絲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5306 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5306,'zhTW','沃什加斯的菊石','別被她的美貌愚弄了，$c。暗影獵手沃什加斯是個狂暴而致命的獵手。$B$B<基爾拉姆指著自己臉上的傷疤。>$B$B喏，這就是她給我的——她稱之為愛的陷阱。$B$B復仇的時刻終於來臨了。$B$B你可以在黑石塔中找到沃什加斯。殺死她並將她的菊石交給我。如果你成功了，我就教你如何打造精良的戰斧。','到黑石塔去殺死暗影獵手沃什加斯，將沃什加斯的菊石交給基爾拉姆。','','去冬泉谷找永望鎮的基爾拉姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5307 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5307,'zhTW','腐蝕','如果我看起來對你有些無禮，那是有原因的。腐蝕之劍的設計圖被黑衣守衛——瑞文戴爾男爵的精英骷髏部隊給盜走了。$B$B沒錯，斯坦索姆的瑞文戴爾男爵。$B$B現在黑衣守衛鑄劍師正在以他的生命——呃，姑且這麼說吧——守護著設計圖。$B$B殺死他，把他的物品拿回來作為憑證，我就會教你如何鍛造閃耀輕劍！','在斯坦索姆找到黑衣守衛鑄劍師，然後殺死他。將黑色衛士徽記交給亡靈殺手瑟里爾。','','去冬泉谷找永望鎮的亡靈殺手瑟里爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5321 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5321,'zhTW','昏昏欲睡','我正要趕路去邁斯特拉崗哨見利拉迪斯‧月河，但是我決定在這裡停下打個盹...自從我被從翡翠夢境中喚醒之後，就總是那麼睏...$B$B<打哈欠>$B$B你願意給我帶路嗎?我知道邁斯特拉崗哨在這裡的南邊，就沿著梣谷的路走好了。路上可能會有危險，我希望你的朋友也能一起來幫助我。$B$B最後一點，也許我會在半路上睡著，你只要吹響我的號角就可以喚醒我了。號角就在這個箱子裡。','護送克羅尼亞‧恒影到梣谷邁斯特拉崗哨的利拉迪斯‧月河那裡去。','護送克羅尼亞·恆影到邁斯特拉崗哨去','去找梣谷的利拉迪斯·月河。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5341 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5341,'zhTW','巴羅夫家族的寶藏','通靈學院中藏著巴羅夫家族的遺產。我，阿萊克斯·巴羅夫，是這個家族說過僅存兩名後嗣之一。另一個是我的兄弟維爾頓。$B$B那個懦弱的維爾頓，他在戰爭開始時就逃走了，保住了他的小命。$B$B現在，他正在到處搜尋地契，想要獨吞那筆財富。搶在我的兄弟之前取得那些地契，我保證將使你變得非常富有，富有得遠遠超出你的想象。','到通靈學院中去取得巴羅夫家族的寶藏。這份寶藏包括四份地契：凱爾達隆地契、布瑞爾地契、塔倫米爾地契，還有南海鎮地契。完成任務之後就回到阿萊克斯·巴羅夫那兒去。','','去提瑞斯法林地找亡靈壁壘的阿萊克斯·巴羅夫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5342 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5342, 'zhTW', '巴羅夫的繼承人', '既然我的兄弟仍然活著，那麼自然就是家族財產的理所應當的繼承人。我絕不能讓他得到這筆財產。$B$B你這樣卑賤的流浪者除了當個冷血殺手之外還能幹什麼?$B$B這任務很簡單，我希望你能勝任。如果你想要得到報酬，就按我說的去做吧。$B$B維爾頓在東邊的冰風營地，他在那裡受到了聯盟的保護。殺死他，把他的腦袋給我帶回來。$B$B<阿萊克斯打了個哈欠。>$B$B趕快出發吧。', '到冰風營地─聯盟的領地─去暗殺維爾頓·巴羅夫。把他的腦袋交給阿萊克斯·巴羅夫。$B$B要多加小心，聯盟也許對維爾頓執行了嚴密的保護。', '', '去找提裏斯法林地的阿萊克斯·巴羅夫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5343 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5343,'zhTW','巴羅夫家族的寶藏','我親愛的兄弟阿萊克斯……我真不該饒了他的命。我與已經成為亡靈的他四目相視，最終卻免了他一死。$B$B<維爾頓啐了一口唾沫。>$B$B現在他正到處尋找屬於我的財產！我絕不能讓他得逞。$B$B在他骯髒的爪子碰到財寶之前，你必須找到我們巴羅夫家族的地契，我會用無數的珍寶和財富回報你。它們就在通靈學院的廢墟中，要快！','到通靈學院中去取得巴羅夫家族的寶藏。這份寶藏包括四份地契：凱爾達隆地契、布瑞爾地契、塔倫米爾地契，還有南海鎮地契。完成任務之後就回到維爾頓·巴羅夫那兒去。','','去西瘟疫之地找冰風崗的維爾頓·巴羅夫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5344 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5344, 'zhTW', '巴羅夫的繼承人', '地契已經找到了，我們還剩下一件事要做─殺死阿萊克斯。只要他一死，我就用不著再擔心那些惟利是圖、肆無忌憚的強盜來取我的腦袋了。$B$B這任務很簡單。阿萊克斯在亡靈壁壘，他在那裡受到了部落的保護。$B$B不，只是殺死他還不行，我要你把他的腦袋拿回來!至於你怎麼做到這一點……呃，那是你的事情。這種行為可不是我這樣的貴族會做的。', '去亡靈壁壘─部落的領地─去暗殺阿萊克斯·巴羅夫。把他的腦袋交給維爾頓·巴羅夫。$B$B要小心，部落也許對阿萊克斯執行了嚴密的保護。', '', '去西瘟疫之地找冰風崗的維爾頓·巴羅夫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5361 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5361,'zhTW','兄弟','我的兄弟納塔卡駐紮在淒涼之地的幽靈崗哨。我想問你……你能幫我把這份報告交給他嗎？距離我上次寫報告給他已經過去一年了，最近半人馬有些不尋常的舉動，我想我應該把這些告訴他。$B$B到十字路口北邊的石爪山脈去，然後向西進入焦炭谷，再往南進入淒涼之地，在那兒有一條路通往南邊的幽靈崗哨。','將峭壁衛兵圖林·長角的報告交給淒涼之地幽靈崗哨的納塔卡·長角。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5381 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5381,'zhTW','埃魯索斯之手','火刃氏族擁有惡魔之盒，那裡面放著強大的埃魯索斯之手。火刃氏族用它來開啟瑪諾洛克集會所的惡魔之門。我們必須阻止成群的惡魔湧入這個世界，$n！用這把惡魔之鋤去挖掘雷斧堡壘中的紅色水晶，拿到惡魔之盒。','在雷斧堡壘中找到惡魔之盒，把它和惡魔之鋤一起交給葬影村的泰迦·慧鬃。','','去淒涼之地找葬影村的泰迦·慧鬃。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5382 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5382,'zhTW','瑟爾林·卡斯迪諾夫教授','卡斯迪諾夫殺死了數千條生命。他必須得到懲罰，正義必須得到伸張。$B$B找到他，讓他也嚐嚐他給那些無辜者帶來的痛苦。在他死掉之後燒燬我們的遺體，讓它們都化為灰燼，$N。','在通靈學院中找到瑟爾林·卡斯迪諾夫教授。殺死他，並燒燬艾瓦·薩克霍夫和盧森·薩克霍夫的遺體。任務完成後就回到艾瓦·薩克霍夫那兒。','','去西瘟疫之地找達隆米爾湖的艾瓦·薩克霍夫。','','燒燬艾瓦·薩克霍夫的遺骸','燒燬盧森·薩克霍夫的遺骸','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5383 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5383,'zhTW','卡斯迪諾夫的恐懼之袋','開啟口袋之後，你發現了許多拷問罪犯所用的器械。在這些可隨身攜帶的用具中，你的目光被一件古怪的物品吸引了——那是一瓶還帶著餘溫的血液。$B$B你認為薩克霍夫也許會對你的發現感興趣。','將恐懼之袋交給凱爾達隆的艾瓦·薩克霍夫。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5384 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5384,'zhTW','傳令官基爾圖諾斯','就是這個了，$N。$B$B<艾瓦指著口袋中的小瓶。>$B$B這無辜者之血。最純淨的血，用於取悅卡斯迪諾夫的主人。$B$B也許它可以召喚基爾圖諾斯，這樣我們就能殺死他了。$B$B把血液帶到門廊去，放在火盆下。基爾圖諾斯會出現的——他無法抵抗這血液的誘惑。當他出現時，釋放出那些憤怒的無辜者的靈魂。$B$B如果你成功的話，你所能得到的不僅僅是我們的感激之情。','帶著無辜者之血回到通靈學院，將它放在門廊的火盆下面，基爾圖諾斯會前來吞噬你的靈魂。$B$B勇敢地戰鬥吧，不要退縮！殺死基爾圖諾斯，然後回到艾瓦·薩克霍夫那兒。','','去西瘟疫之地找達隆米爾湖的艾瓦·薩克霍夫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5385 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5385,'zhTW','特雷·萊弗治的殘骸','你小心地拾起袋子，準備返回費伍德森林和梣谷邊界處的傑希爾·月弓那兒去。希望在你將聖騎士的遺體交給他的朋友之後，他會被隆重地安葬。','將特雷·萊弗治的殘骸交給費伍德森林的傑希爾·月弓。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5386 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5386,'zhTW','食魚度日','我在幽靈崗哨這兒好久都沒有聞到過魚肉的香味了。葬影村的巨魔最擅長捕魚……但是，我要在此負責半人馬的事情，因此沒有時間去拜訪巨魔。嗯……$B$B幫我個忙吧，替我去一趟葬影村。在那裡找當地的漁夫吉納澤林談談，給我帶點美味可口的血肚魚回來。沿著南邊的道路走，你就可以到達西邊的巨魔村莊。','與葬影村的吉納澤林談話，然後將2條血肚魚交給納塔卡·長角。','','去淒涼之地找幽靈崗哨的納塔卡·長角。','','','','',0);
