INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5513, 'zhTW', '黎明披肩', '你對銀色黎明所做出的貢獻將受到表彰，$N。你在我們的組織中有著很高的聲譽，因此我授權你可以購買我們最寶貴的裝備─我們的魔法抗性披肩。$B$B只要把它加在你現有的披肩上，你就可以抵抗五種魔法的力量。作為對我們的事業繼續做出貢獻的標誌，我要求你拿至少10枚銀色黎明勇氣勳章來換取這些披肩。', '把10個銀色黎明勇氣勳章交給東瘟疫之地聖光之願禮拜堂的軍需官米蘭達·布利洛克。', '', '去東瘟疫之地找聖光之願禮拜堂的軍需官米蘭達·布利洛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5514 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5514, 'zhTW', '昂貴的模具', '你要找的哥布林的名字叫做克林科·古德斯迪爾。他在塔納利斯的加基森鎮裡生活，為出價最高的顧客效力。看來他是唯一個可以幫我們完成融合工序的鐵匠，不過他的標價會非常高，所以你來解決他的工錢。$B$B我是個鍊金師，不是個銀行家。如果我有一堆金子的話，還待在這裡幹什麼?$B$B我相信我已經把事情說得很直白了，咳咳。$B$B加基森在等待你!祝你好運!', '把灌魔的骷髏碎片和15枚金幣交給加基森的克林科·古德斯迪爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5515 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5515,'zhTW','卡斯迪諾夫的恐懼之袋','$N，你幫我去掉了壓在心上的一塊大石頭，但是你的任務還沒有完成。卡斯迪諾夫的主人基爾圖諾斯還活著。$B$B在你面對基爾圖諾斯之前，必須先找到召喚他的方法。$B$B據說詹迪斯·巴羅夫負責將卡斯迪諾夫收集的無辜者之血交給基爾圖諾斯。$B$B到通靈學院中那個沉沒的墓穴裡去找到她，打敗她。把你找到的線索拿回來交給我。','在通靈學院找到詹迪斯·巴羅夫並打敗她。從她的屍體上找到卡斯迪諾夫的恐懼之袋，然後將其交給艾瓦·薩克霍夫。','','去西瘟疫之地找達隆米爾湖的艾瓦·薩克霍夫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5516 AND `locale` = 'zhTW';
