DELETE FROM `quest_template_locale` WHERE `ID` = 5517 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5517, 'zhTW', '炫彩黎明披肩', '$N，你為銀色黎明做出的貢獻在這裡被廣為傳頌。作為一種獎勵，你將有資格獲得我們特殊的炫彩黎明披肩，它可以幫你抵抗各種魔法效果。炫彩黎明披肩只會被授予最強大的英雄!$B$B交給我二十五枚勇氣勳章作為你對銀色黎明做出貢獻的標誌，然後我就會把我們最好的披肩給你。', '把25個銀色黎明勇氣勳章交給東瘟疫之地聖光之願禮拜堂的銀色黎明軍需官米蘭達·布利洛克。', '', '去東瘟疫之地找聖光之願禮拜堂的軍需官米蘭達·布利洛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5518 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5518,'zhTW','戈多克食人魔裝','如果你想要和那個笨蛋食人魔國王作戰，那麼首先你必須透過克羅卡斯那一關。好吧，你當然可以殺了他，但實際上你也可以留他一條命。$B$B你問我該怎麼做？嗯，你真好運，我想我知道如何製作一件可以把你偽裝成食人魔的服裝，用來迷惑那些四肢發達的笨蛋。唯一的問題可能就是穩定性——這種衣服的持續時間最多為10分鐘。把我需要的東西給我拿來，然後我就可以幫你做一件。我就等在這裡……','把4份符文布卷、8塊硬甲皮、2卷符文線和一份食人魔鞣酸交給諾特·希姆加克。他現在被拴在厄運之槌的戈多克食人魔那邊。','','去找厄運之槌的諾特·希姆加克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5519 AND `locale` = 'zhTW';
