DELETE FROM `quest_template_locale` WHERE `ID` = 5659 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5659, 'zhTW', '<NYI> Touch of Weakness', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5660 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5660, 'zhTW', '虛弱之觸', '你已離家很遠了，$c。你的那座地下的城市需要你。你的女主人，那位召喚你回家的艾薩萊斯特需要你回到她身邊。有些東西你只能從她那兒學到，就像我的部落一樣。別在這兒待得太久了，你該迅速趕往幽暗城的軍事區。', '與幽暗城的艾薩萊斯特談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5661 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5661, 'zhTW', '虛弱之觸', '血蹄村離你的家園很遠，$N。我來此是為了尋找自己部落的祭司，將他們帶回去同我們的領袖談談，但是這並不意味著我就沒法幫你了。我聽說你們的牧師領袖想要召集所有的被遺忘者─讓他們去跟她學點什麼。回到你的城市去，在軍事區跟艾薩萊斯特見一面吧。', '與幽暗城的艾薩萊斯特談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5662 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5662, 'zhTW', '虛弱之觸', '我對你和你的族人表示尊重，$N。我一般只向我自己的同胞傳授技藝，你的課程開始於那座曾經被稱作羅德隆的城市中。如果你要學習那些只有你們才能掌握的技能，就回到幽暗城的軍事區裡去找艾薩萊斯特吧。', '與幽暗城的艾薩萊斯特談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5663 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5663, 'zhTW', '虛弱之觸', '艾薩萊斯特正在召集她管轄的所有牧師，我們要指引那些較為年輕的成員到幽暗城去進行更多的訓練。如果你真的認為自己是我們中的一員，那麼你也應該回到那兒去。你可以在幽暗城深處的軍事區裡找到艾薩萊斯特。', '與幽暗城的艾薩萊斯特談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5664 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5664,'zhTW','暫無內容','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5665 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5665,'zhTW','眾星之衣','達納蘇斯那邊有訊息過來，$N。好像是某位女祭司想讓你返回家園，與月神殿的女祭司阿蘭希雅談談。她對你取得的進展似乎相當滿意。我想，當她看到一個艾露恩的信徒對自己的信仰更加堅定時，她肯定會非常驕傲的。$B$B願聖光與你同在。','與達納蘇斯的女祭司阿蘭希雅談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5666 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5666,'zhTW','眾星之衣','啊，$N，很高興能見到你。聽說月神殿正準備對你進行下一次試煉。女祭司阿蘭希雅想要親自與你談談，你應該儘快返回達納蘇斯。把你在這邊的事情處理掉，然後趕快回去吧。','與達納蘇斯的女祭司阿蘭希雅談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5667 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5667,'zhTW','眾星之衣','你好啊，年輕的牧師，很高興看到你的修行進展順利。不久之前，你的一個同伴曾到這兒來尋找你，似乎是要你回一趟達納蘇斯，大概是關於女祭司阿蘭希雅和月神殿的事兒。這事情聽起來挺重要的，我想你應該盡快回去。','與達納蘇斯的女祭司阿蘭希雅談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5668 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5668,'zhTW','聖光的祝福','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5669 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5669,'zhTW','聖光的祝福','啊，$N，很高興你能停下來與我交談。不久之前，一位聖光的牧師曾來此尋找過你，說光明大教堂中的高階牧師勞瑞娜想與你會面。如果這次會面的內容是關於你近來所取得的成就的話，我可絲毫不會感到驚訝。隨著修行的深入，我們的許多成員都在不斷地接受試煉，並被賦予更多的責任。','與暴風城的高階牧師勞瑞娜談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5670 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5670,'zhTW','聖光的祝福','你剛剛與暴風城派來找你的信使失之交臂，$N。似乎你的名聲很不錯，高階牧師勞瑞娜想要與你談談。我想，教會那邊應該是認為你已經為下一輪的試煉做好了準備。$B$B等你把這邊的事情都安排妥當之後，就到暴風城的光明大教堂去找她談談吧。我想她正在等你呢。','與暴風城的高階牧師勞瑞娜談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5671 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5671,'zhTW','聖光的祝福','年輕的牧師，你所屬的教會通知你返回暴風城。當你準備就緒後，高階牧師勞瑞娜將與你進行會談，似乎你的這位上司認為你已為下一輪的試煉做好了準備。$B$B我相信她就在光明大教堂裡等你。願艾露恩保佑你你旅途平安。','與暴風城的高階牧師勞瑞娜談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5672 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5672,'zhTW','艾露恩的賜福','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5673 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5673,'zhTW','艾露恩的賜福','$N，不要虛度光陰，你該回一趟達納蘇斯了。女祭司阿蘭希雅派人捎信來通知你返回家園進行試煉。他們似乎認為你已準備好接受新的試煉了，就像那些信仰聖光的人也要接受試煉一樣。阿蘭希雅說她正在月神殿等你，祝你好運。','與達納蘇斯的女祭司阿蘭希雅談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5674 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5674,'zhTW','艾露恩的賜福','今天是個好日子，$N。你已經到了學習那些只有暗夜精靈牧師才能掌握的特有技能的年紀了，不過負責訓練你的並不是我。你應該儘快了結你在此地的事務，然後返回月神殿去跟女祭司阿蘭希雅談談。她將對你進行試煉以確保你已準備就緒，只有透過了她的試煉，你才能學到艾露恩的恩賜。','與達納蘇斯的女祭司阿蘭希雅談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5675 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5675,'zhTW','艾露恩的賜福','$g小夥子:小姑娘，不要虛度光陰，你該回一趟達納蘇斯了。女祭司阿蘭希雅派人捎信來通知你返回家園進行試煉。他們似乎認為你已準備好接受新的試煉了，就像那些信仰聖光的人也要接受試煉一樣。阿蘭希雅說她正在月神殿等你，祝你好運。','與達納蘇斯的女祭司阿蘭希雅談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5676 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5676,'zhTW','奧術回饋者*','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5677 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5677,'zhTW','奧術回饋者','我很想向你傳授使用聖光的技能，但是這不是該由我們來做的事情。現在，你應該回到暴風城裡，去找你的同伴，$N……相信我，我沒有冒犯你的意思。當你回到光明大教堂的高階牧師勞瑞娜那兒時，你就會了解我在說什麼了——現在是你的種族為了未來而訓練你，使你在同類人中出類拔萃的時候了。','與暴風城的高階牧師勞瑞娜談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5678 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5678,'zhTW','奧術回饋','年輕人，現在你該回一趟暴風城了，你的上司召喚你回去接受更多的試煉。儘管你的離去會稍微擾亂我的計劃，但是你的種族和我的種族是同盟，而我是永遠不會背棄盟約的。$B$B我並不想在你面前扭捏作態——不管那些神秘的魔法是否是由神授予的，我對這些魔法都感到強烈地不信任。$B$B當你返回光明大教堂之後，你就會明白我所說的這些話的意義了，到那裡去跟高階牧師勞瑞娜談談吧。','與暴風城的高階牧師勞瑞娜談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5679 AND `locale` = 'zhTW';
