INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5682,'zhTW','星夜之衣','是時候讓你再次回到達納蘇斯去了，$N。與月神殿的高階女祭司阿蘭希雅談談吧，她會告訴你那些你應該知道的東西。$B$B如果我沒有搞錯的話，應該是有關教會要送你新袍子的事情。願聖光與你同在。','與達納蘇斯的高階女祭司阿蘭希雅談一談。','','','','','','',0);
