INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5683,'zhTW','星夜之衣','啊，我的$g兄弟:姐妹，我真為你感到高興！是時候讓你回到達納蘇斯去和高階女祭司阿蘭希雅談談了。我的信使很肯定地說，你所屬的教會要送新的袍子給你。$B$B你有空的時候就趕快回去一趟，待我向月神殿的姐妹們問好。$B$B願艾露恩與你同在。','與達納蘇斯的高階女祭司阿蘭希雅談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5684 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5684,'zhTW','星夜之衣','嗯，很高興看到你在不斷進步，牧師。也許你正在考慮什麼時候該回達納蘇斯去慶祝一番，對不對？好吧，至少今天不會……我是說不會有什麼慶祝。$B$B高階女祭司阿蘭希雅捎信來告訴我，如果我碰到你的話就讓你回去一趟。你可以在月神殿找到她。','與達納蘇斯的高階女祭司阿蘭希雅談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5685 AND `locale` = 'zhTW';
