INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5686,'zhTW','聖光保佑','又到了讓你回到暴風城去的時候了，年輕的牧師。由於你出色的表現，高階牧師勞瑞娜要對你進行嘉獎。她還在光明大教堂裡——到那裡去找她吧。$B$B你動身之前仍可以隨時在這裡接受訓練，如果有任何我可以為你效勞的事情，請儘管開口。','與暴風城的高階牧師勞瑞娜談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5687 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5687,'zhTW','聖光保佑','又到了讓你回到暴風城去的時候了，年輕的牧師。由於你出色的表現，高階牧師勞瑞娜要對你進行嘉獎。她還在光明大教堂裡——到那裡去找她吧。$B$B祝你好運，願艾露恩在你的旅途中保佑你。','與暴風城的高階牧師勞瑞娜談一談。','','','','','','',0);
