INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5689,'zhTW','巫毒之觸','嘿，$c。不久之前有個信使來我這裡找你，他說你應該回奧格瑪去，跟精神谷裡的烏爾庫談談。他似乎並不是因為發怒而要找你，但是這事情似乎很重要。也許你應該去看看究竟是什麼事。','與奧格瑪的烏爾庫談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5690 AND `locale` = 'zhTW';
