INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5699,'zhTW','一絲希望','哈哈！快回暴風城，$N。高階牧師勞瑞娜要你回去再次接受考驗。回光明大教堂去，不要耽擱。你有很多事情要做，隨著你變得越來越強大，會有更多的重擔壓在你的肩上。這是我們的必經之路——你越有價值，人們就會越來越仰仗你。$B$B願聖光與你同在。','與暴風城的高階牧師勞瑞娜談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5700 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5700,'zhTW','一絲希望','你的神殿要求你盡快回去，$N。高階牧師勞瑞娜在找你，看來光明大教堂那裡近來有不少動作，這並不讓我感到驚訝——天災軍團和部落的外在威脅，還有我們內部的許多問題，這些都讓我們頭痛不已。$B$B當你準備好的時候，就到大教堂去吧。','與暴風城的高階牧師勞瑞娜談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5701 AND `locale` = 'zhTW';
