INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5927,'zhTW','回應召喚','朋友，打擾一下……$B$B我注意到圖拉克·符文圖騰已經放出話來，說想要和你談談。看樣子你即將開始嶄新的生活——去接受德魯伊的訓練，他將親自訓練你。圖拉克是大德魯伊的助手，也是最為睿智、最為威嚴的德魯伊之一。$B$B他居住在雷霆崖，就在長者高地上的塞納里奧議會大帳裡。','與雷霆崖長者高地上的圖拉克·符文圖騰談話。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5928 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5928,'zhTW','響應召喚','朋友，打擾一下……$B$B我注意到圖拉克·符文圖騰已經放出話來，說想要和你談談。看樣子你即將開始嶄新的生活——去接受德魯伊的訓練，他將親自訓練你。圖拉克是大德魯伊的助手，也是最為睿智、最為威嚴的德魯伊之一。$B$B他居住在雷霆崖，就在長者高地上的塞納里奧議會大帳裡。','與雷霆崖長者高地上的圖拉克·符文圖騰談一談。','','','','','','',0);
