INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6081,'zhTW','訓練野獸','你現在已擁有了馴服寵物的力量，但是你還必須掌握訓練寵物的技能。$B$B去奧格瑪吧。你得去跟奧瑪克——我們最敬重的獵人談一談，他會傳授你訓練新寵物的技能。奧瑪克就在士兵大廳附近。$B$B祝你好運，$N。','與奧格瑪的奧瑪克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6082 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6082,'zhTW','馴服野獸','你需要馴服的最後一種生物是危險的硬甲蠍，它攻擊速度非常快，而且非常準確，獵人就應該控制這樣的力量。$B$B你成功歸來後，我將傳授你馴服寵物的技能，這種生物從此將聽從你的命令。在你的控制之下，它將與你同甘共苦，我還要為你演示如何召喚它，以及在必要的時候如何解散它。','使用馴獸棒馴服硬甲蠍。練習你的技能，然後將馴獸棒還給剃刀嶺的索塔爾。','馴服一隻硬甲蠍','去杜隆塔爾找剃刀嶺的索塔爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6083 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6083,'zhTW','馴服野獸','當你面對敵人時，寵物可為你提供有力的支援，$N。當你取得對某隻野獸的控制權時，你自己的力量也會得到增強。你的寵物必須成為你自己的延伸。$B$B下一項任務要求你到海邊去，在那裡尋找另一種可供你馴服的生物。在森金村附近有一種名叫海浪蟹的螃蟹，使用馴獸棒馴服它，以此來練習你的技能。','使用馴獸棒馴服海浪蟹。練習你的技能，然後將馴獸棒還給剃刀嶺的索塔爾。','馴服一隻海浪蟹','去杜隆塔爾找剃刀嶺的索塔爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6084 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6084,'zhTW','馴服野獸','這些峭壁野豬相當魁梧，或許你希望選擇一種更合適自己的野獸？好吧，我明白了。在此地的南面和東面有一種名叫雪豹的大型動物。它們就像精雕細琢的步槍一樣，在美麗的外表下隱藏著強大的戰鬥力和驚人的破壞力。你會發現它們比你先前馴服的野豬更為敏捷。$B$B帶著這根馴獸棒，看看你有多喜歡雪豹吧。','使用馴獸棒馴服雪豹。練習你的技能，然後將馴獸棒還給卡拉諾斯的格瑞夫。','馴服一隻雪豹','去找丹莫洛的格瑞夫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6085 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6085,'zhTW','馴服野獸','也許你想要同又聰明又強壯的野獸對抗，對於像你這樣初出茅廬的獵人來說，冰爪熊可以成為極佳的同伴，你可以在卡拉諾斯東邊找到它。拿著這個馴獸棒，把冰爪熊變成你的寵物，看看你是否喜歡它！$B$B你回來以後，我會向你傳授馴服野獸的方法，這種野獸將與你一同面對挑戰，並與你一起成長。我還會向你展示召喚和解散它的方法。','使用馴服獸棒馴服一頭冰爪熊。練習你的技能，然後將馴獸棒還給卡拉諾斯的格瑞夫。','馴服一頭冰爪熊','去找丹莫洛的格瑞夫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6086 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6086,'zhTW','訓練野獸','$N，現在你已具備了馴服寵物的能力，但是你還必須掌握訓練它的方法。$B$B到鐵爐堡的軍事大廳去跟我們最尊敬的馴獸師貝莉亞·雷巖談談吧，她將向你傳授訓練新寵物的方法，那麼趕快出發吧，$G小子:小姑娘！$B$B貝莉亞是個友好的馴獸師，你應該能和她相處得很融洽。祝你好運，$N。','與鐵爐堡的貝莉亞·雷巖談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6087 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6087,'zhTW','馴服野獸','你是個勇敢的獵人，現在你已經準備好接受下一次挑戰了。$B$B你的下一個任務是馴服被稱為草原捕食者的狼。這是一種敏捷而無畏的野獸，要讓它成為你的寵物，你必須同樣具備這些品質。$B$B在戰鬥中，你將學會如何與自己的寵物並肩作戰。最終，你們的行動必須融為一體。$B$B這是馴獸棒，$N。去馴服一隻草原捕食者，練習你的技能。','使用馴獸棒馴服一隻草原捕食者。練習你的技能，然後將馴獸棒還給血蹄村的雅文·刺鬃。','馴服一隻草原捕食者','去莫高雷找血蹄村的雅文·刺鬃。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6088 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6088,'zhTW','馴服野獸','我給你最後一個任務是馴服一種在空中飛行的生物。猛鷲是個難纏的對手，但是一旦它成為你的同伴，你就會發現它的快捷和威懾力對你來收都是很有用的。$B$B當你返回時，我將根據大地母親的意願，向你傳授馴服野獸的技能。這種野獸從此以後將與你一同面臨挑戰、共同成長。我還將為你展示召喚和解散它的方法。','使用馴獸棒馴服一隻猛鷲。練習你的技能，然後將馴服法杖交還給血蹄村的雅文·刺鬃。','馴服一隻猛鷲','去莫高雷找血蹄村的雅文·刺鬃。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6089 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6089,'zhTW','訓練野獸','現在你已經擁有了馴服寵物的能力，但是你還必須學會訓練它的方法。$B$B到雷霆崖去吧，在那裡同最受尊敬的獵人浩特·雷角談談。如果他認可你的能力，便會將訓練新寵物的方法傳授給你。$B$B浩特曾經馴服過世界上最強大、最可怕的野獸，他與大地母親的聯結很緊密，你可以從他那兒學到許多東西。祝你好運，$N。','與雷霆崖獵人高地的浩特·雷角談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6101 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6101,'zhTW','馴服野獸','大自然的複雜和多變是永恆的，$N。它不會一成不變，它總是在不斷地改變著。$B$B我給你的任務將幫助你瞭解各種野獸之間的不同之處。$B$B帶上這根馴獸棒，去馴服南邊的夜刃捕食者，練習你的馴獸技巧，然後你就會開始瞭解大自然的相似性和相異性。','使用馴獸棒馴服一隻夜刃捕食者。練習你的技能，然後將馴獸棒還給多蘭納爾的達扎拉。','馴服一隻夜刃捕食者','去泰達希爾找多蘭納爾的達扎拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6102 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6102,'zhTW','馴服野獸','你已經馴服了在這裡繁衍生息的兩種生物，現在你必須再馴服一種在空中飛翔的生物。使用馴獸棒去馴服西邊的巨翼惡梟，用這種強大的貓頭鷹來練習自己的技能吧。$B$B當你回來的時候，我將告訴你如何將野獸馴服成為你的同伴，它將與你一同面臨挑戰，與你一同在戰鬥和歷險中成長。我還會向你展示如何召喚它，以及如何在必要的時候解散它。','使用馴獸棒馴服一隻巨翼惡梟。練習你的技能，然後將馴獸棒還給多蘭納爾的達扎拉。','馴服一隻巨翼惡梟','去泰達希爾找多蘭納爾的達扎拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6103 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6103,'zhTW','訓練野獸','現在你已經擁有馴服寵物的能力了，但是你還必須學會如何訓練它。$B$B到達納蘇斯去跟我們最尊敬的獵人——祖卡斯特談一談吧。她將傳授你訓練新寵物的技能，趕快出發吧。$B$B雖然祖卡斯特看起來很嚴厲，但她總是樂於看見新的獵人誕生。對她保持尊敬，她也會對你態度和藹。祝你好運，$N。','與達納蘇斯塞納里奧區的祖卡斯特談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6121 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6121,'zhTW','新的課程','你應該好學習有關德魯伊的解毒能力的知識了，$N。塞納留斯賜予了我們特殊的能力，讓我們只需施展一個簡單的法術就能淨化世間最邪惡的劇毒。但是這份禮物可不是隨便就可以送給你的……為了保證你能深刻地理解這門新的課程，你要像個剛剛入行的新手那樣，逐一瞭解各種毒藥的特點。$B$B到月光林地去跟德迪利特·星焰談談吧，他會在那裡向你傳授這些知識的。','到月光林地去，與永夜港的德迪利特·星焰談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6122 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6122,'zhTW','毒水之源','黑海岸的峭壁之泉是這個地區的主要水源，我認為那裡就是造成當地的動物大量中毒的罪魁禍首。用這個取樣器在洞口取一些水樣，你要小心一些，瀑布旁邊的一個洞穴中居住著危險的納迦。$B$B一旦你拿到了水樣，就把它送到奧伯丁的奧蘭達利亞·夜歌那裡去。她是向我們尋求幫助的人之一，往後你將和她一起工作。','使用空的峭壁之泉取樣器在瀑布洞口獲得水樣。$B$B將盛滿的峭壁之泉取樣器送到黑海岸奧伯丁的奧蘭達利亞·夜歌那裡。','','去黑海岸找奧伯丁的奧蘭達利亞·夜歌。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6123 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6123,'zhTW','收集解藥','這些水將作為解毒藥膏的基礎材料。為了使它產生治療效果，我需要一些地根草。採藥人知道怎樣找到它，如果你不懂草藥學的話，那你就得找一個懂行的來幫你。$B$B另外，為了增強藥力，我們還需要一些月亮菇。尋找月亮菇很簡單——這裡東面的洞穴裡到處都是。不過這些洞穴裡住著一些月光梟獸，它們很容易發怒，所以你要多加小心。','收集5個地根草和12個月亮菇，把它們交給奧伯丁的奧蘭達利亞·夜歌，這樣她就可以製作解藥了。','','去黑海岸找奧伯丁的奧蘭達利亞·夜歌。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6124 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6124,'zhTW','消除疾病','你所帶來的材料足夠製作十份解藥，$n。在我繼續想辦法準備更多解藥的時候，希望你可以給我們開個好頭。黑海岸到處都是生病的鹿，對它們使用藥膏就可以治療它們的疾病。$B$B在你完成任務之後，就去找月光林地的德迪利特·星焰談一談。請向那裡的塞納里奧議會轉達奧伯丁的謝意……另外，我要對你所提供的幫助表示感謝！','對黑海岸的10頭生病的鹿使用動物醫療藥膏，以此來治療它們。從壁泉河到奧伯丁，直到最南端靠近梣谷的地區都有生病的鹿出沒。','','去月光林地找永夜港的德迪利特·星焰。','治療生病的鹿','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6125 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6125,'zhTW','解毒之術','你已經知道在沒有精神支柱的情況下清除毒素有多麼困難了。你很快就會擁有可以輕鬆解除毒性的能力了，所以請牢記其他的生靈在抵抗毒素侵襲時所承受的痛苦。$B$B現在，你應該返回達納蘇斯去找瑪斯雷·馭熊者了，$N。既然你已經領悟了這一課的內容，那麼他就應該會把這個非常重要的法術教給你。$B$B再見，年輕的德魯伊。','回到達納蘇斯塞納里奧區的瑪斯雷·馭熊者那裡。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6126 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6126,'zhTW','新的課程','你應該好學習有關德魯伊的解毒能力的知識了，$N。塞納留斯賜予了我們特殊的能力，讓我們只需施展一個簡單的法術就能淨化世間最邪惡的劇毒。但是這份禮物可不是隨便就可以送給你的……為了保證你能深刻地理解這門新的課程，你要像個剛剛入行的新手那樣，逐一瞭解各種毒藥的特點。$B$B到月光林地去跟德迪利特·星焰談談吧，他會在那裡向你傳授這些知識的。','到月光林地去，與永夜港的德迪利特·星焰談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6127 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6127,'zhTW','毒水之源','看來，十字路口的西北面的鬼霧峰是最有可能散播毒藥的地點。那裡的水池可能已經被崇拜惡魔的火刃氏族汙染了。$B$B用取樣器在山頂的水池中收集一些水樣，灌滿之後就把它送到十字路口的圖加·符文圖騰那裡去。他是向我們尋求幫助的人之一，往後你將和他一起工作。','使用空的鬼霧峰取樣器在山頂取水樣。$B$B將盛滿的鬼霧峰取樣器送到貧瘠之地十字路口的圖加·符文圖騰那裡。','','去找十字路口的圖加·符文圖騰。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6128 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6128,'zhTW','收集解藥','這些水將作為解毒藥膏的基礎材料。為了使它產生治療效果，我需要一些地根草。採藥人知道怎樣找到它，如果你不懂草藥學的話，那你就得找一個懂行的來幫你。$B$B另外，為了增強藥力，我們還需要一些科多獸角——小碎片可不行。貧瘠之地的北部區域有許多科多獸，為了治癒大自然的惡疾，你必須殺掉一些，把它們的角拿來給我。','收集5個地根草和5個科多獸角，把它們交給十字路口的圖加·符文圖騰，這樣他就可以製作解藥了。','','去找十字路口的圖加·符文圖騰。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6129 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6129,'zhTW','消除疾病','你所帶來的材料足夠製作十份解藥，$n。在我繼續想辦法準備更多解藥的時候，希望你可以給我們開個好頭。貧瘠之地北部到處都是生病的瞪羚，對它們使用藥膏就可以治療它們的疾病。$B$B在你完成任務之後，就去找月光林地的德迪利特·星焰談一談。請向那裡的塞納里奧議會轉達奧伯丁的謝意……另外，我要對你所提供的幫助表示感謝！','對貧瘠之地北部的10只生病的瞪羚使用動物醫療藥膏，以此來治療它們。在穿過十字路口的那條東西走向的大路北面到處都是生病的蹬羚。','','去月光林地找永夜港的德迪利特·星焰。','治療生病的瞪羚','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6130 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6130,'zhTW','解毒之術','你已經知道在沒有精神支柱的情況下清除毒素有多麼困難了。你很快就會擁有可以輕鬆解除毒性的能力了，所以請牢記其他的生靈在抵抗毒素侵襲時所承受的痛苦。$B$B現在，你應該返回雷霆崖去找圖拉克·符文圖騰了，$N。既然你已經領悟了這一課的內容，那麼他就應該會把這個非常重要的法術教給你。$B$B再見，年輕的德魯伊。','回到雷霆崖長者高地的圖拉克·符文圖騰那裡。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6131 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6131,'zhTW','木喉熊怪的盟友','木喉部族是唯一沒有被墮落力量汙染的熊怪部族。然而，許多其他的種族盲目地屠殺熊怪，卻並沒有搞清他們是敵是友。因此，木喉熊怪很少相信別人。$B$B你想要證明自己的立場嗎？去趕走腐化的死木部族，我們以後也許會接受你成為盟友。你可以在費伍德的南部找到死木戰士、探路者和園丁。','格拉茲要你去殺死5個死木戰士、5個死木探路者以及5個死木園丁。','','去費伍德森林找翡翠聖地的格拉茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6132 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6132,'zhTW','救我出去！','救我出去！$B$B我本來是到長矛谷這裡找瑪洛迪半人馬談判的……我本以為可以跟他們做點生意……但他們根本不想做生意！我想他們要吃了我！$B$B救我出去吧，我哥哥霍恩尼茲會給你很多錢的！他在東邊靠近科多獸墳場的營地裡。$B$B我們趕緊出發吧，$N。大概兩分鐘前，我聽到幾隻半人馬說要找些木頭燒火……','護送梅麗薩，然後與科多獸墳場的霍恩尼茲談一談。','護送梅麗薩抵達安全地帶','去找淒涼之地的霍恩尼茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6133 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6133, 'zhTW', '遊俠之王的命令', '奎爾林斯小屋裡的高等精靈拿著一件屬於我的東西，一本記錄著我生前的那些往事的日記。$B$B在你詢問之前，我要先明確地告訴你:你不得翻閱這些資料。照我說的做，你這條蟲子，去給我找到這份文件。$B$B另外，一定要讓他們飽嘗痛苦和悲傷，讓他們受盡苦難和折磨……', '到東瘟疫之地的北方邊界去找回奎爾薩拉斯名冊，這件物品在奎爾林斯小屋的某處。$B$B另外你還必須殺掉8個遊俠、8個巡路者和8個護林者。', '', '去東瘟疫之地找瑪瑞斯農場的納薩諾斯·凋零者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6134 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6134,'zhTW','幽靈電漿','東南方有一處山谷——白骨之谷，那裡是瑪格拉姆半人馬的鬼魂出沒的地方。聽起來很可怕，不是嗎？好吧，想想那裡對瑪格拉姆半人馬有多麼可怕吧！如果我們從那個地方收集鬼魂的能量，我敢打賭它對那些半人馬來說是很值錢的。$B$B給，拿著這箱幽靈磁鐵。如果你把它放在山谷中的兩具大骷髏之間，那麼鬼魂就會實體化，並聚集到它旁邊。幹掉那些鬼魂並收集他們的幽靈電漿——那就是我們要賣給瑪格拉姆部族的東西。','把幽靈磁鐵箱和8份幽靈電漿交給淒涼之地的霍恩尼茲。','','','殺死8只亡靈劫掠者','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6135 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6135,'zhTW','暗翼蝠','到現在為止，你已經完成了我分配的所有任務，雖然並不是非常及時。$B$B我想你認為自己已經準備好接受真正的挑戰了。很好……很好，蠢貨，也許你需要一些更加棘手的任務。$B$B蒼白的惡魔蝙蝠——暗翼蝠——就在這裡的北方遊蕩。消滅它，把它的毛皮給我帶回來，你會得到獎賞的。','找到暗翼蝠並殺掉它。從屍體上取下一塊暗翼蝠的皮，並把它交給納薩諾斯·凋零者。$B$B據說暗翼蝠遊蕩在瑪瑞斯農場北面的荒原上。','','去東瘟疫之地找瑪瑞斯農場的納薩諾斯·凋零者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6136 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6136,'zhTW','肥大的食腐蟲','在聖光之願禮拜堂和北谷西邊的銀色黎明營地，你就可以找到一條非常肥胖的蛆蟲，它叫淤血蟲。$B$B那個怪物曾經讓我損失了一大票士兵。而且它吃得越多就變得越大……$B$B雖然這頭怪獸吃了你我也不會覺得悲傷，但我還是希望你能獲勝。我建議你召集一些同伴來完成這項任務，淤血蟲曾吃掉過無數貿然攻擊它的蠢貨。','找到東瘟疫之地北方荒原中的淤血蟲並消滅它。任務完成之後，向納薩諾斯·凋零者覆命。','','去東瘟疫之地找瑪瑞斯農場的納薩諾斯·凋零者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6141 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6141, 'zhTW', '安東修士', '我的好兄弟安東修士聽說在卡林多大陸的某處有不死生物出沒的傳聞─那個地方叫做淒涼之地。安東立即就決定要到那裡去消滅不死生物!他正在尋找有勇氣和決心幫助他的冒險者。如果你願意的話，就去找安東談談吧。他在淒涼之地的尼耶爾前哨站裡。', '與淒涼之地的安東修士談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6142 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6142,'zhTW','蚌肉魚餌','你看起來像是個漁夫，$c！我喜歡釣魚——我一生都在釣魚。最好用的魚餌是軟殼蚌肉，魚兒根本無法抗拒它的誘惑，你知道我說的是什麼嗎？$B$B往北方走，你可以在海岸邊找到一艘失事的船，那一帶到處都是軟殼蚌肉。如果你給我帶回來十塊軟殼蚌肉，我也會給你一些回報。','找到10塊軟殼蚌肉，把它們交給葬影村的麥拉斯。','','去淒涼之地找葬影村的麥拉斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6143 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6143,'zhTW','另一種魚','你可能聽說過，也可能沒有……我的同伴和我一起在靠近納迦島的地方釣魚，就在北面海岸邊的那艘失事船舶的更北面。我們過去常常在那裡釣魚，但是現在我滿腦子想的都是為我死去的同伴報仇。$B$B有一天早上，納迦攻擊了我們，殺了除我以外的所有人。$B$B我的心每天都被內疚和仇恨煎熬著，$c。我想讓你去把納迦全都給幹掉，而且我保證你的努力會得到回報的。那麼，你願意幫我嗎？','殺死7個滑刃侍從、7個滑刃納迦，以及5個滑刃巫師，然後與葬影村的杜澤加爾談談。','','去淒涼之地找葬影村的杜澤加爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6144 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6144,'zhTW','上級的命令','命令已經傳達下來了，$c。瓦里瑪薩斯要求我把手下最能幹的特工派回幽暗城去，完成一項高度機密的任務。$B$B不幸的是，我最能幹的特工三年多以前就基本上死絕了，代替他們的是一大群不長腦子的蠢貨。$B$B<納薩諾斯冷冷地注視著你。>$B$B立即到幽暗城去向瓦里瑪薩斯報告。不要給我添麻煩，$c！','到幽暗城去與瓦里瑪薩斯談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6145 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6145,'zhTW','紅衣信使','就像身體沒有頭就不能存活一樣，頭沒有了身體也不能存活。斯坦索姆城中的血色十字軍司令部幾乎是無法攻破的。因此，我們必須把他們的身體從頭下切斷。$B$B我的亡靈哨兵一直在斯坦索姆城外蒐集十字軍活動的情報，每天都有有一份報告從他們的指揮部送到提爾之手去。這份報告就是關鍵，$r！找到紅衣信使並取回那份報告，然後把它交給納薩諾斯。','返回東瘟疫之地，找到並殺死紅衣信使，拿到大十字軍的命令。$B$B把命令交給納薩諾斯·凋零者，並等待進一步的指示。','','去東瘟疫之地找瑪瑞斯農場的納薩諾斯·凋零者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6146 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6146,'zhTW','納薩諾斯的計謀','我已經對這份命令做了一些調整。如果我們的小計謀成功了，他們就會暴露血色十字軍聖賢，然後我們就可以出擊了！$B$B現在聽好了，$c。你要把這份命令交給十字軍領主瓦德瑪爾。$B$B怎麼交給他？親手交給他，你這白痴。$B$B把命令和這隻爛蘋果拿到提爾之手去。當你快到那裡的時候，吃掉這個蘋果，你會變成某種更加……能被人類接受的東西。把這份命令交給十字軍領主瓦德瑪爾。','到瑪瑞斯農場東南方的提爾之手去，抵達那裡之後就咬一口爛蘋果。在血色十字軍偽裝的掩護下，把大十字軍的命令交給十字軍領主瓦德瑪爾。','','去東瘟疫之地找提爾之手的十字軍領主瓦德瑪爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6147 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6147,'zhTW','向納薩諾斯覆命','大十字軍有一個不尋常的要求。嗯，不管怎麼說……他的命令必須執行。返回血色堡壘去，告訴他聖賢很快就要上路了。$B$B我們將盡全力防範，確保她毫髮無傷地抵達斯坦索姆。','帶著新情報返回納薩諾斯·凋零者那裡。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6148 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6148,'zhTW','血色十字軍聖者，德米提雅','德米提雅是大十字軍的首席顧問，她因為具備“來世的感覺”而被稱作聖者。她已經成功地幫助十字軍贏得了數次對亡靈天災的戰鬥。$B$B如果她真的有點本事的話，那麼眼下她應該已經預見到自己會有麻煩了。你要去幫她驗證這一點，給她點“麻煩”嚐嚐。$B$B找到聖者德米提雅並殺了她。在我們說話的時候，他們應該正在從提爾之手出發去巡邏。別讓我失望。','血色十字軍正在從提爾之手到斯坦索姆的路上巡邏，你可以在巡邏隊中找到聖者德米提雅和她的隨從，找到並殺死她。如果你成功了，就回到納薩諾斯·凋零者那裡去覆命。','','去東瘟疫之地找瑪瑞斯農場的納薩諾斯·凋零者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6161 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6161,'zhTW','拉克摩爾的財寶！','拉克摩爾的日誌上面說，他的船是在駛向羽月要塞的途中受到海洋生物攻擊的。為了避免自己的財寶落入敵人之手，他將寶物箱藏在了一座島上。$B$B你需要兩把鑰匙才能開啟箱子，一把金鑰匙和一把銀鑰匙。這兩把鑰匙都丟失了，但是如果你能找到鑰匙和寶箱，就能得到財寶了！','找到拉克摩爾的銀鑰匙和金鑰匙。找到並開啟拉克摩爾的箱子。','','去淒涼之地的薩瑟里斯海岸找拉克摩爾的箱子。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6162 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6162,'zhTW','最後一戰','我的丈夫為了氏族的榮耀去了費伍德森林，與暗影議會和其它墮落的勢力作戰！$B$B他多次從死亡邊緣逃了回來，直到我收到了他的一封信，說是有一名德魯伊請他幫忙幹掉一隻被稱作主宰洛爾的熊怪——但他們兩個再也沒有了音信。$B$B我想要洛爾的爪子，$N。我要它償還令我成為寡婦的代價！我相信這頭野獸就在南邊……靠近梣谷的邊境。','殺死主宰洛爾，把他的爪子交給費伍德森林血毒崗哨的德雷卡蘇。','','去費伍德森林找血毒崗哨的德雷卡蘇。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6163 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6163,'zhTW','吞嚥者拉姆斯登','我被完全擊敗了。為了守衛我們的家園，為了守衛洛丹倫，我在這裡絕望地戰鬥著……一切抵抗者都在潮水般的天災士兵面前被夷為廢墟。$B$B那個邪惡而骯髒的怪物把我踏在腳下，我能看到它的內臟掛在破碎的胸腔中。$B$B我被亡靈天災喚醒了，一直以來，我是如此的無助。我的意志被巫妖王牢牢地控制著。$B$B她趕來解救了我……不管用什麼方式，在什麼地方，我知道她早晚會這麼做的。自由。$B$B現在，我必須進行復仇——對那些奪取我生命的敵人進行復仇。毀滅它。','到斯坦索姆去，殺掉吞嚥者拉姆斯登。把他的頭顱交給納薩諾斯。','','去東瘟疫之地找瑪瑞斯農場的納薩諾斯·凋零者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6164 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6164, 'zhTW', '奧古斯圖斯的收據冊', '準備開張!你想要點什麼?$B$B啊，等等……沒有收據冊，我就不能開張。沒有收據冊的話，我怎麼能搞清楚帳目呢?$B$B我一定是把它丟在鎮裡了。我在旅店裡住過，一定是在那裡。$B$B把我的收據冊拿回來吧。請把它交給我!我要儘快開張營業，而你會看到我的價格完全出乎你的意料!', '把奧古斯圖斯的收據冊交給恐懼谷中精神失常的奧古斯圖斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6165 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6165, 'zhTW', '<NYI> <TXT> Archmage Timolain\'s Remains', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6181 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6181,'zhTW','快遞訊息','儘管我沒有直接從暴風城得到很多幫助，但是城裡有個好心人一直在為我提供護具。他的名字叫做奧斯瑞克·斯圖恩，他在暴風城的舊城區裡開了一家名叫“有限防護”的店。$B$B現在我們的護甲供應短缺，所以我必須聯絡到奧斯瑞克以得到更多的裝備。你能把這張便箋交給他嗎？$B$B到暴風城去的最快捷的辦法就是透過索爾，我們的獅鷲管理員。他就在山腳下，把我的便箋拿給他看看，然後從他那裡租一頭獅鷲飛到暴風城去吧。','將劉易斯的便箋交給獅鷲管理員索爾。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6182 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6182, 'zhTW', '第一個和最後一個', '納薩諾斯·瑪瑞斯是歷史上第一個也是最後一個人類遊俠領主，他是希瓦娜斯·風行者的學生。我們一直以為納薩諾斯在五年前的羅德隆保衛戰中犧牲了。儘管他的屍體從未被發現，但人們都認為他不大可能從東瘟疫之地逃出來。馬迪亞斯·肖爾一直在調查這起失蹤案，而且可能有了一些新的消息。立即去向他彙報。馬迪亞斯就住在舊城區的兵營裡。', '與暴風城的馬迪亞斯·肖爾談一談，他住在舊城區的兵營裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6183 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6183,'zhTW','逝者的榮耀','我手下最強的五個人被派去調查瑪瑞斯的那件事情。只有一個人回來了，三天之後，他在睡夢中死掉了。$B$B我們從他混亂而含糊的喃喃自語中沒有得到什麼有用情報，只聽出來兩個詞：“納薩諾斯”和“凋零者”。$B$B我沒有足夠的人手來繼續調查，而拉文霍德也不願意協助我們。我們必須對這件事情調查到底，即便只是為了表示對逝者的哀悼。你願意幫忙嗎？','如果你願意接這個任務，就再和馬迪亞斯·肖爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6184 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6184,'zhTW','弗林特·沙多摩爾','到目前為止，我們掌握的唯一資訊就是納薩諾斯·瑪瑞斯也許已經被這個凋零者給殺死了。而且我們認為凋零者就是殺死那些軍情七處密探的惡魔。$B$B另一個軍情七處的間諜弗林特·沙多摩爾正駐守在西瘟疫之地冰風崗的聯盟營地中。去找到他，他會告訴你瘟疫之地的現狀，並派給你下一步的任務。$B$B祝你好運，$N。','到西瘟疫之地的冰風崗去跟弗林特·沙多摩爾會面。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6185 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6185,'zhTW','東部的瘟疫','正如我所說的，你的第一項任務就是偵察工作。沒什麼難度，$N。你必須到東瘟疫之地去尋找任何有關這個凋零者的線索。$B$B留意我們的幾個失蹤的密探。我們只能是認為他們已經死了，不過如果他們確實死了，那就一定可以在某個地方找到……他們的屍體。$B$B<弗林特艱難地嚥了一下唾沫。>$B$B所有的軍情七處成員都有這樣的一枚徽章。$B$B<弗林特給你看了他的軍情七處徽章。>$B$B把你發現的所有東西都帶回來給我。','搜尋東瘟疫之地，尋找“凋零者”的線索以及失蹤的軍情七處密探。如果你找到任何軍情七處徽章，就把它們交給冰風崗的弗林特·沙多摩爾。','找到凋零者','去西瘟疫之地找冰風崗的弗林特·沙多摩爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6186 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6186,'zhTW','凋零者','<弗林特面無血色。>$B$B這是納……納薩諾斯干的？納薩諾斯是就是凋零者？$B$B為什麼？他……他那麼高貴——他是個受人尊敬的遊俠領主，是唯一接受過高等精靈訓練的人類。他居然是亡靈的一員？$B$B我……我很抱歉要再請你做一件事，$N，但是你必須立刻將這件事情告訴伯瓦爾·弗塔根公爵。趕快去暴風城吧。','回到暴風城，將納薩諾斯·瑪瑞斯的下落報告給伯瓦爾·弗塔根公爵。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6187 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6187,'zhTW','重鑄秩序','你知道這個世界上總共才出現過多少遊俠領主嗎？你知道這其中的人類遊俠領主有幾個嗎？$B$B納薩諾斯的貢獻是空前的。他是個戰術天才，他讓聯盟獲得了無數次戰鬥的勝利。$B$B現在……他卻成了被遺忘者的勇士。$B$B不，事情不可能是這樣的。我們必須恢復那裡的秩序。$B$B召集一支部隊，$N。回到瘟疫之地，殺掉凋零者。$B$B祝你好運，$N。事實上，這次你確實需要一些好運。','組織一支部隊，然後到東瘟疫之地去。向納薩諾斯·凋零者和任何敢於保護他的部落成員發起攻擊。$B$B你要傾盡全力，$N。部落會不惜一切代價保護他們的遊俠領主。','','去暴風城找暴風要塞的瓦里安·烏瑞恩國王。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6201 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6201,'zhTW','暫無內容','','','','去找。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6202 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6202,'zhTW','暫無內容','','','','去找。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6221 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6221,'zhTW','北方的死木熊怪','此地西南方向有一處死木熊怪的營地。我不清楚他們想要幹什麼，但是我希望能在他們開始搗亂之前就結果他們。$B$B死木部族非常邪惡，是惡魔的力量侵蝕了他們的心智。他們的天性並不壞，但是現在一切都無法挽回了。因此，我對被迫與自己的同胞作戰感到非常悲哀。$B$B$N，去結果他們吧，別對我說起戰鬥的具體過程，我不忍心聽到那些。','格拉茲要你去殺死6個死木守衛、6個死木復仇者和6個死木薩滿祭司。','','去費伍德森林找翡翠聖地的格拉茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6241 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6241,'zhTW','冬泉熊怪的活動','木喉部族傾向於防守，$N。雖然我們允許那些值得信賴的朋友安全地透過，但我們還是儘可能地避開其他熊怪部族。$B$B最近我注意到冬泉部族與我們的敵對情緒有所增長。他們似乎處於極度憤怒的狀態，完全陷入了對一切他們無法理解的事物的恐慌和仇視。$B$B如果你能削減他們的數量，那對我們來說將是莫大的幫助，$N。','索爾法要你去殺死6個冬泉圖騰師、6個冬泉巢穴守衛和6個冬泉探路者。','','去找冬泉谷的索爾法。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6261 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6261,'zhTW','杜加爾·朗德瑞克','$N，我收集了奧斯瑞克需要的所有東西，把它們都放在這個箱子裡了。你能幫我把它運過去嗎？$B$B如果你以前和西部荒野的索爾說過話，那麼你就可以搭乘獅鷲直接飛回他那裡。杜加爾·朗德瑞克是我們的獅鷲管理員，就在貿易區那邊。$B$B和杜加爾談一談，然後儘快把這個東西交給劉易斯。我們不希望西部荒野的戰士們赤手空拳地進行戰鬥！','將奧斯瑞克的箱子交給獅鷲管理員杜加爾·朗德瑞克。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6281 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6281,'zhTW','趕赴暴風城','只需花費很少的錢，你就可以坐獅鷲去暴風城，把劉易斯的便箋交給奧斯瑞克。這是你到那裡去的最快捷的辦法。$B$B如果你覺得可行的話，就做好準備，然後再次和我對話。我的收費非常低廉，而且絕對物有所值！','從獅鷲管理員索爾那裡租用一頭獅鷲，然後把劉易斯的便箋交給暴風城的奧斯瑞克·斯圖恩。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6282 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6282,'zhTW','鷹身人的威脅','牛頭人以保護這片土地而感到驕傲。毫無疑問，你知道我為什麼對石爪山的鷹身人的數量感到擔心。$B$B血怒鷹身人是卡利姆多大陸上膨脹速度最快的鷹身人族群，它們會阻止任何人離開它們的領地。$B$B你必須去減少它們的數量，$N！','烈日石居的馬格蘭要你去殺掉7個血怒鷹身人、7個血怒伏擊者、7個血怒殺戮者和7個血怒遊蕩者。','','去石爪山脈找烈日石居的馬格蘭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6283 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6283,'zhTW','血怒一族','限制血怒鷹身人的數量還不夠，要解決它們的問題，唯一的方法就是殺了它們的領袖，血怒撕裂者！$B$B她是那些邪惡生物的女王。只要殺了她，鷹身人的數量就一定會減少。$B$B回到焦炭谷去，你可以在西部的山嶺中找到她。她可不好對付，但是如果你完成這個任務的話，我也會給你可觀的獎勵。','烈日石居的馬格蘭要你去殺掉血怒撕裂者，然後把她的遺體帶回來作為證據。','','去石爪山脈找烈日石居的馬格蘭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6284 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6284,'zhTW','貝瑟萊斯','警告：從這裡往西進入希塞爾山谷的旅行者請多加小心。$B$B貝瑟萊斯和她的蜘蛛後代們佔領了這座峽谷，將其作為它們的巢穴。$B$B烈日石居的馬格蘭正在懸賞貝瑟萊斯。殺了她並將證據交給馬格蘭以換取獎勵。','殺掉貝瑟萊斯，然後把貝瑟萊斯的牙齒交給烈日石居的馬格蘭。','','去石爪山脈找烈日石居的馬格蘭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6285 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6285,'zhTW','返回西部荒野','西部荒野的獅鷲管理員是索爾。如果你以前和他談過的話，那你就可以乘坐我的獅鷲去他那裡。$B$B有件事情你應該知道：獅鷲總是可以從外圍城鎮直飛主城的，不過只有在你和當地的獅鷲飼養員談過話之後才行。$B$B你已經去過索爾那裡了，那麼，你只需再次和我說話就可以乘坐獅鷲去西部荒野。到了那裡之後，把奧斯瑞克的箱子交給軍需官劉易斯。','從獅鷲管理員杜加爾·朗德瑞克那裡租用一頭獅鷲飛到哨兵嶺，然後將奧斯瑞克的箱子交給哨兵嶺的劉易斯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6301 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6301,'zhTW','生生不息','工業集團的貪婪和持續不斷的戰事已經讓了石爪山脈的土地飽經創傷，在我的血管中流淌著的薩滿能量可以幫助這裡的森林。$B$B$N，我需要派你去尋找一種特殊的種子。蓋亞之種僅生長石爪山地區，你可以在北邊的暗色湖一帶找到蓋亞之種，就在湖岸邊。$B$B當你把種子交給我之後，我就會為它們灌入薩滿的能量，使它們快速成長。','烈日石居的塔姆拉·荒原想讓你去收集10枚蓋亞之種。','','去石爪山脈找烈日石居的塔姆拉·荒原。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6321 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6321, 'zhTW', '瑟伯切爾的補給', '執行官哈德瑞克讓我清查我們在瑟伯切爾的裝備。由於森林中潛伏著的天譴軍團士兵的威脅，他不希望我們在裝備方面有所短缺。$B$B我發現，我們的武器裝備基本上庫存豐富，但是我們仍然需要更多的武器來替換那些在戰場上丟失的武器。$B$B這是一份武器訂單，把它交給幽暗城裡的武器供應商高頓·溫德哈姆。帶著訂單去找我們的蝙蝠管理員卡洛斯·拉佐克，跟他談談關於前往幽暗城的事兒吧。', '將博迪瑞格的訂單交給卡洛斯·拉佐克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6322 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6322, 'zhTW', '邁克爾·加勒特', '我已經將瑟伯切爾那邊要求的物資裝箱了。如果你已經拜訪過瑟伯切爾，並與他們那裡的蝙蝠管理員打過招呼，那麼你就可以乘坐蝙蝠回到那兒去。$B$B與幽暗城的蝙蝠飼養員邁克爾·加勒特談談吧，他可以為你提供一隻飛往瑟伯切爾的蝙蝠。', '將高頓的箱子交給邁克爾·加勒特。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6323 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6323, 'zhTW', '飛往幽暗城', '只需一小筆費用，我的蝙蝠就可以把你帶到幽暗城去。當你準備就緒時再來找我，然後我會幫你安排剩下的事情。$B$B你可以在幽暗城的貿易區裡找到高頓·溫德哈姆，我的蝙蝠正好會降落在那個區域。', '從蝙蝠管理員卡洛斯·拉佐克那裡租一隻蝙蝠飛往幽暗城，然後將博迪瑞格的訂單交給幽暗城裡的高頓·溫德哈姆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6324 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6324, 'zhTW', '向博迪瑞格回報', '瑟伯切爾的蝙蝠管理員是卡洛斯·拉佐克。如果你們已經見過面，那麼我可以為你提供一隻返回他那兒去的蝙蝠。$B$B這些蝙蝠都可以直飛幽暗城，但是如果你想要飛到更遙遠的地方去，就必須先拜訪那個區域的蝙蝠飼養員。$B$B你已經在瑟伯切爾跟卡洛斯碰過面了，現在你可以乘坐蝙蝠回到他那裡去。當你準備就緒時再來找我吧。', '從蝙蝠管理員邁克爾·加勒特那兒租一隻蝙蝠飛往瑟伯切爾，然後將高頓的箱子交給瑟伯切爾的亡靈衛兵博迪瑞格。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6341 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6341, 'zhTW', '泰達希爾的漁業', '魯瑟蘭村周圍水域中的魚又大又肥，所以這裡的漁業很昌盛。我希望把從這裡捕獲的魚和卡林多的魚進行比較，研究一下它們有何不同。$B$B我收集了一些魚骨頭和鱗片，想要把它們帶到我在黑海岸的一個同事那裡去。他的名字叫做賴爾德，是奧伯丁的魚商。$B$B把我的東西拿到角鷹獸管理員維斯派塔斯那裡去，跟他談談關於去奧伯丁的事宜。', '將奈莎的貨物交給維斯派塔斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6342 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6342, 'zhTW', '飛往奧伯丁', '從魯瑟蘭村到奧伯丁去的方法有兩種:乘船或者騎角鷹獸。這兩種方式都很迅捷可靠，但是如果你沒有搭乘過角鷹獸的話，我建議你試一下。$B$B另外，你最好和各個城鎮中的角鷹獸管理員談談。一旦你和某地的角鷹獸飼養員打過了招呼，那麼以後你就可以從其他城鎮飛到那裡去了。$B$B這裡是奈莎的貨物。如果你準備好了的話，就再次和我對話，然後把這包東西送到賴爾德那裡。', '從角鷹獸管理員維斯派塔斯那裡乘一隻角鷹獸到奧伯丁，然後將奈莎的貨物交給賴爾德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6343 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6343, 'zhTW', '回去找奈莎', '我必須給奈莎回信，她應該會對這裡的魚跟泰達希爾沿岸的那些魚的差異感興趣。出現這種差異的原因……也許是世界之樹在影響其周圍的生物!$B$B請你幫我給奈莎捎個信。如果你想要乘坐角鷹獸回魯瑟蘭村的話，那就去跟角鷹獸管理員凱萊斯·月羽談談吧。如果你要搭船回去，西北面的碼頭那裡有定時的航班。', '將賴爾德的回信交給奈莎·影歌。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6344 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6344, 'zhTW', '奈莎·影歌', '我的朋友奈莎·影歌是魯瑟蘭村的一個漁業商人，她要送一個包裹到黑海岸去，所以她正在找人幫忙。如果你感興趣的話，那就去找奈莎吧。從達納蘇斯到魯瑟蘭村去的傳送門就在神殿花園的西邊。', '與奈莎·影歌談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6361 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6361, 'zhTW', '一捆獸皮', '我有一捆從貧瘠之地採集的獸皮，必須要把它們送到雷霆崖去。我在那兒的同伴安哈努需要用這些獸皮來製作皮件。$B$B你能幫我把這些獸皮交給他嗎?$B$B前往雷霆崖最為快捷的方法就是乘坐雙足飛龍。帶著這捆獸皮去十字路口找雙足飛龍管理員迪弗拉克，跟他談談到雷霆崖去的事兒。', '帶著獸皮去找十字路口的雙足飛龍管理員迪弗拉克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6362 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6362, 'zhTW', '飛往雷霆崖', '只需一小筆費用，我就可以為你提供飛往雷霆崖的雙足飛龍。沒有比這更方便快捷的旅行方式了!$B$B如果你願意的話，準備一下就來找我吧。$B$B如果你要把這些獸皮交給安哈努，就到雷霆崖雙足飛龍高塔底層的海瓦的武器店裡去找他吧，就是你降落的地方!', '從雙足飛龍管理員迪弗拉克那裡租一隻馭風者飛往雷霆崖，然後將這捆獸皮交給雷霆崖的安哈努。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6363 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6363, 'zhTW', '雙足飛龍管理員塔爾', '我已經為加翰準備好了供他在十字路口出售的皮件。請你把這些交給他好嗎?$B$B如果你已經拜訪過了十字路口的雙足飛龍管理員，那麼你就可以乘坐雷霆崖的雙足飛龍返回他那兒了。$B$B將皮件交給雷霆崖的雙足飛龍管理員塔爾，然後和他談談前往十字路口的行程安排。', '將安哈努的皮貨交給雷霆崖的塔爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6364 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6364, 'zhTW', '向加翰回覆', '想要飛回某座城鎮的話，你必須已經徒步到達過那裡，並且和那裡的雙足飛龍管理員打過招呼。如果你去過十字路口並和他們的雙足飛龍管理員迪弗拉克談過話，那麼你就可以從這裡搭乘雙足飛龍直接飛過去了。$B$B如果你準備好了，就再次和我談談。一旦到了十字路口，你就可以把這些皮貨交給加翰·鷹翼了。', '從雙足飛龍管理員塔爾那裡租用一頭飛往十字路口的雙足飛龍，並把安哈努的皮貨交給加翰·鷹翼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6365 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6365,'zhTW','送往奧格瑪的肉','我有一些上等的肉片想送給我的朋友。她的名字叫雷什卡，是奧格瑪旅店的老闆。你可以替我把這些肉交給她嗎？$B$B到奧格瑪去的最快捷方法就是乘坐雙足飛龍。帶著這些肉去找十字路口的雙足飛龍管理員迪弗拉克，跟他談談關於到奧格瑪去的事情。','把扎爾夫的肉品交給十字路口的迪弗拉克。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6381 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6381,'zhTW','新的生命','如你所見，$c，我純淨的心靈可以為這片不毛之地帶來新的生機。你必須將這些種子種植在破壞之源中，在西邊的焦炭谷裡就是破壞大自然的源泉——這片被汙染的土地上到處都是鷹身人和兇惡的火元素。$B$B$N，拿著這些附有魔法的蓋亞之種，把它們種植在蓋亞土堆裡。','將10枚蓋亞之種種植在蓋亞土堆中，然後與烈日石居的塔姆拉談一談。','','去石爪山脈找烈日石居的塔姆拉·荒原。','種植蓋亞之種','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6382 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6382,'zhTW','梣谷狩獵','你的力量給我留下了深刻的印象，$c。你對狩獵興趣昂然，這讓我相信你有能力參與更大規模的狩獵行動……面臨更大的挑戰。$B$B梣谷森林是一大片未開化的土地，部落正在為控制這片土地而努力。如果你想要在那裡證明自己的能力，就到碎木哨崗去尋求塞娜尼·雷心的指點吧。那個前哨站就在貧瘠之地的正北方。','與梣谷碎木哨崗的塞娜尼·雷心談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6383 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6383,'zhTW','梣谷狩獵','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6384 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6384,'zhTW','飛往奧格瑪','只需一小筆費用，我就可以為你提供飛往奧格瑪的馭風者。當你到那兒後，就去把扎爾夫的肉品交給格雷什卡。她在距離通天塔不遠的力量谷裡，馭風者會在通天塔上降落。$B$B當你準備動身的時候就來找我吧。','從雙足飛龍管理員迪弗拉克那裡租一隻馭風者飛往奧格瑪，然後將扎爾夫的肉品交給奧格瑪的格雷什卡。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6385 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6385,'zhTW','雙足飛龍管理員多拉斯','我已經為扎爾夫寫了一封感謝信。你能幫我交給他嗎？如果你已經去過十字路口，並且和那裡的雙足飛龍管理員談過話，那麼你就可以乘坐一頭雙足飛龍直飛到那裡去。$B$B把我的信交給奧格瑪的雙足飛龍管理員多拉斯，並同他談談去十字路口的事兒。','將格雷什卡的信交給奧格瑪的多拉斯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6386 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6386,'zhTW','返回十字路口','經過訓練，我的馭風者可以飛往許多不同的地方，只要你已經去過那個地方，並且與那裡的馭風者管理員進行了交談，馭風者就可以載著你前往那地方。$B$B你已經去過十字路口，也跟那裡的馭風者飼養員迪弗拉克打過了招呼，所以現在你可以直接飛到他那兒了。一旦你到了十字路口，就把格雷什卡的信交給扎爾夫。$B$B當你準備出發時就來找我談談。','從馭風者管理員多拉斯那裡僱一隻馭風者前往十字路口，然後將格雷什卡的信交給十字路口的扎爾夫。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6387 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6387,'zhTW','榮譽學員','我看見門前聚集了一大群年輕的矮人，他們都迫切地想要學習採礦技巧。如果說有一件東西是礦工最為需要的工具的話，那當然是鐵鋤無疑了！$B$B我有一張學習採礦的學生的名單，他們表現得都很出色，因此都將獲得一把榮譽鋤。把這張名單交給鐵爐堡的高尼爾·石趾，他會為你準備好榮譽鋤。$B$B去鐵爐堡最快的途徑是乘坐獅鷲，帶著這張名單去找獅鷲管理員索格拉姆·伯雷森吧，跟他談談去鐵爐堡的事兒。','將布洛克的名單交給塞爾薩瑪的索格拉姆·伯雷森。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6388 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6388,'zhTW','格萊斯·瑟登','這是給布洛克的學生的榮譽鋤。如果你已經去過塞爾薩瑪了，那麼就乘坐獅鷲返回那裡吧！$B$B把這些榮譽鋤交給獅鷲管理員格萊斯·瑟登，跟他談談關於返回塞爾薩瑪的事兒。','將榮譽鋤交給鐵爐堡的格萊斯·瑟登。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6389 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6389,'zhTW','瘟疫與你','你在伐木場附近尋找能開啟桶的工具，很快就找到了一根鐵棍，似乎可以用它撬開桶。$B$B你開始撬桶，並暗自祈禱能在白蟻發現你之前離開伐木場。','使用北山伐木場裡的鐵棍放出那裡的瘟疫白蟻，然後向西瘟疫之地冰風崗的納薩尼爾·杜馬報告。','','去西瘟疫之地找冰風崗的納薩尼爾·杜馬。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6390 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6390,'zhTW','瘟疫與你','你在伐木場附近尋找能開啟桶的工具，很快就找到了一根鐵棍，似乎可以用它撬開桶。$B$B你開始撬桶，並暗自祈禱能在白蟻發現你之前離開伐木場。','使用北山伐木場裡的鐵棍放出那裡的瘟疫白蟻，然後向提瑞斯法林地亡靈壁壘的米克·萊文報告。','','去提瑞斯法林地找亡靈壁壘的米克·萊文。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6391 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6391,'zhTW','飛往鐵爐堡','只需一小筆費用，我就能為你提供一隻飛往鐵爐堡的獅鷲，讓你把布洛克的名單交給高尼爾·石趾。你可以在鐵爐堡大鍛爐區的深山礦工協會里找到他，獅鷲也會在那個區域降落！$B$B當你準備出發時就來找我。','從獅鷲管理員索格拉姆·伯雷森那裡租一隻獅鷲飛往鐵爐堡，然後將布洛克的名單交給鐵爐堡的高尼爾·石趾。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6392 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6392,'zhTW','向布洛克回覆','只需一小筆費用，我就能為你提供一隻飛往塞爾薩瑪的獅鷲，當然，在這之前你必須已經去過塞爾薩瑪了。獅鷲只能載著你飛往你以前曾經去過的地方，因此你必須跟你所見到的每個獅鷲管理員交談，以確保稍後你能乘坐獅鷲飛到管理員那裡。$B$B你已經見過了塞爾薩瑪的獅鷲管理員索格拉姆，因此現在你可以返回他那兒了。到了塞爾薩瑪之後，把這些鎬交給布洛克·尋石者。$B$B當你準備出發時就來找我吧。','從獅鷲管理員格萊斯·瑟登那裡租用一頭飛往塞爾薩瑪的獅鷲，然後將榮譽鋤交給塞爾薩瑪的布洛克·尋石者。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6393 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6393,'zhTW','元素戰爭','海潮議會派我來與石爪山的火元素作戰。水元素的統帥，獵潮者耐普圖隆對於消滅火元素很感興趣。$B$B$N，你可以透過消滅焦炭谷的火元素來贏得我們的青睞。當火元素被摧毀之後，它們會留下焚火餘燼。把那些東西給我帶回來，然後你就能獲得獎勵。','將10塊焚火餘燼交給烈日石居的蘇納曼。','','去石爪山脈找烈日石居的蘇納曼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6394 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6394,'zhTW','塔茲利爾的鎬',' $N ，你是個值得信賴的 $R 。我能把另一個任務也託付給你嗎?$B$B不久前，我在北邊的一個洞穴中挖掘礦石的時候不小心弄丟了我最喜歡的鎬。後來當我回去找它的時候，卻發現洞穴中住滿了邪惡的野獸!到那個被稱作燃刃集會所的洞穴中去幫我取回我的鎬，行嗎?$B$B我把它放在一個有瀑布的大廳裡了。我的鎬附有魔法，你在黑暗中也能看見它，所以你不必擔心找不到它……只要小心那些守護它的野獸就是了!','將塔茲利爾的鎬還給工頭塔茲利爾。','','去找杜洛塔的工頭塔茲利爾。','','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 6395 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6395,'zhTW','瑪拉的遺願','瘟疫發生之前，我的朋友瑪拉·菲普斯和她的丈夫山繆生活在一起。但是瘟疫掃過這片土地之後，山繆加入了天譴軍團的隊伍。$B$B瑪拉逃過了瘟疫，卻慘死在她那愚蠢的丈夫手裡。唉，這個傻女人深愛著自己的丈夫，她的遺願竟然是同山繆葬在一起。$B$B山繆·菲普斯就住在喪鐘鎮東北邊，在路旁的一座廢棄的營帳裡。去打敗他，實現瑪拉的遺願─將他葬在瑪拉的墳墓裡，就在墓地的第一排。','將山繆·菲普斯的遺骸帶到瑪拉的墳墓去，然後回到新兵艾爾雷斯那裡。','','去提瑞斯法林地找喪鐘鎮的新兵艾爾雷斯。','埋葬薩繆爾的遺體','','','',18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 6401 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6401,'zhTW','卡雅還活著','把這個好訊息告訴卡雅的姑母，烈日石居的塔姆拉·荒原！告訴她卡雅還活著！我們以為在村子經歷了那場劫難之後她就失蹤了。沿著西面的路去烈日石居吧。','把這個好訊息告訴烈日石居的塔姆拉·荒原。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6402 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6402,'zhTW','集合在暴風城','你必須到暴風城的城門去，在那裡跟溫德索爾元帥碰面。$B$B溫德索爾即將披露的事情將震撼整個暴風王國！$B$B別想逞英雄，$N。你必須集合一支強大的軍隊！召集你的同胞，準備戰鬥吧！','前往暴風城的城門。與侍衛洛文交談，他會通知溫德索爾元帥你已經到達了。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6403 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6403,'zhTW','潛藏者','朋友，黑石塔那一仗可真是驚心動魄，我欠你一大筆人情。也許等這一切都結束之後……$B$B就像你已經確認了的那樣，女伯爵卡特拉娜·普瑞斯托就是奧妮克希亞，死亡之翼家族中的一員，黑石塔內的那個奈法利安的姐妹。$B$B她長期以來一直在操縱著我們的王國。連伯瓦爾·弗塔根公爵也被她耍得團團轉。今天這一切都將結束了……她的魔法將被破除。$B$B不要怕，我們會取得勝利的！$B$B你準備好了嗎？','跟隨雷吉納德·溫德索爾元帥在暴風城中前進。保護他，別讓他受到傷害！','雷吉納德·溫德索爾的征討','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6421 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6421,'zhTW','滾岩峽谷','石爪山脈有些事不大對勁。你能感覺到空氣中的緊張氣氛嗎，$N？在此地以南的滾岩峽谷中有一處很深的洞穴，狗頭人正在那兒瘋狂地開採一種被稱作共鳴水晶的稀有礦石。我需要你去取回一些礦石樣本，那樣我就能瞭解洞穴中究竟發生了什麼事兒。另外，你還得去勘查一下洞穴的深度。$B$B去吧，年輕的$c，我必須知道這裡的山脈中潛伏著什麼樣的邪惡力量。','深入滾岩峽谷的洞穴中，為烈日石居的摩羅加爾取回10塊共鳴水晶以供研究。','調查滾岩峽谷','去石爪山脈找烈日石居的摩羅加爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6441 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6441,'zhTW','薩特之角','你好啊！我要穿越梣谷往棘齒城去，途中在碎木哨崗這裡稍作休息。我一直在尋找發財的機會，眼下似乎就有一個——這些日子以來棘齒城的薩特角行情看漲。$B$B在附近詢問了一番之後，我認為夜道谷、薩提納爾和薩維亞的薩特頭上的角都符合我的要求。不過我可不是薩特的對手……你也許能行！$B$B幫我收集一些角吧，我會給你報酬的。','為碎木哨崗的皮克希爾收集16只薩特的角。','','去梣谷找碎木崗哨的皮克希爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6442 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6442,'zhTW','佐拉姆海岸的納迦','邪惡的力量正潛伏在海岸邊，$c。$B$B海面下長眠著一座在很久以前就被摧毀的城市，佐拉姆城。這座城市差不多都快要被遺忘了。$B$B現在，出於某種未知的原因，納迦又重新回來了。但是這其中的原因並不重要，重要的是，我們必須為這片土地而戰！我們必須保衛經過浴血奮戰而得來的領土。$B$B去奮勇殺敵吧，$n，給我帶回20個納迦的頭顱來！將它們逼回深海！','將20顆怒尾納迦的頭顱交給佐拉姆海岸的瑪魯凱。','','去梣谷找佐拉姆加前哨站的瑪魯凱。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6461 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6461,'zhTW','盜竊的蜘蛛','瑪拉卡金的巨魔在這片土地上繁衍生息，石爪山脈是我們賴以生存的狩獵場。$B$B但是近來卻有些不請自來的客人……山中的蜘蛛常常在夜間洗劫我們的營帳，竊取我們的獵物。$B$B如果你能幫我們殺死這些可怕的怪物，瑪拉卡金的巨魔會對你感激不盡的。石爪山脈到處都是蜘蛛——往北走，你就會看到的。','瑪拉卡金的辛吉拉要求你殺死10只深苔爬行者和7只深苔毒蜘蛛。','','去石爪山脈找瑪拉卡金的辛吉拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6462 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6462,'zhTW','巨魔符咒','我的族人攜帶著大量神聖的巨魔符咒到這裡來，但是在他們抵達佐拉姆加之前，薊皮熊怪襲擊了他們，把他們全都給殺了！這些可憎的熊怪！$B$B我思念那些死去的兄弟姐妹，但願我們能在另一個世界重逢。不過，他們的巨魔符咒蘊含著強大的魔力。這些符咒落在熊怪手裡對我們來說簡直是一種恥辱！$B$B$N，你必須取回符咒！薊皮熊怪的村落在阿斯特蘭納背面，穿過村落進入那個被稱作薊皮要塞的洞穴，從它們的箱子裡拿回我們的符咒。','將8個巨魔符咒交給佐拉姆加前哨站的米蘇瓦。','','去梣谷找佐拉姆加前哨站的米蘇瓦。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6481 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6481,'zhTW','土靈的覺醒','你已經找到了一個隱藏在這片土地中的威脅，$c。你在洞穴中發現的共鳴桶中藏有一個沉睡的土靈，他的名字叫做高戈羅克。$B$B我已經用薩滿力量改變了你收集的共鳴水晶的成分。用這塊魔化共鳴水晶開啟那隻藏有土靈的共鳴桶。$B$B當高戈羅克清醒過來時，他的能力也將減弱……殺死他，$N！','使用魔化共鳴水晶開啟共鳴桶，然後殺死高戈羅克。將這個訊息告訴摩羅加爾，並把魔化共鳴水晶還給他。','','去石爪山脈找烈日石居的摩羅加爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6482 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6482,'zhTW','魯爾的自由','呃？你是誰？$B$B$N？你不是熊怪，它們是邪惡的生物！它們認為我是一頭熊並俘虜了我，現在它們又讓我忍飢挨餓！我快要沒力氣了……$B$B幫我逃離這裡，然後到東面的碎木哨崗去找我的妹妹雅瑪。$B$B$N！我必須離開這兒！','護送魯爾，然後與碎木崗哨的雅瑪·雪蹄談一談。','護送魯爾逃離薊皮熊怪的領地。','去梣谷找弗倫河的雅瑪·雪蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6501 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6501,'zhTW','巨龍之眼','我所能給你的就是這枚獎章的碎片。$B$B你必須找到另一個願意幫你鑄造新鑰匙的龍類。在得到鑰匙之後，你必須到塵泥沼澤的巨龍沼澤那裡去。你將會在那裡找到她的巢穴，$N。$B$B到哪兒去找到其他願意幫忙的龍呢？遺憾的是，我不知道……據說是有的。其中的一些也許就混跡於我們當中，化裝成某種人型生物的樣子。祝你好運。','你必須尋遍世界以找到一種能恢復龍眼碎片的能量的生物。你對這種生物的唯一瞭解就是：他們確實存在。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6502 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6502,'zhTW','龍火護符','這是龍身上的一部分，一片龍鱗——它已經被附上了魔法，不再是普通的龍鱗了。完整的龍鱗可以幫助我們找到那頭野獸的巢穴，而破碎的龍鱗就毫無用處。$B$B要修復龍鱗也不是沒有辦法，但是你需要黑龍勇士的血。眼下就有一個……他被稱為達基薩斯將軍，是奈法利安龍人軍隊的首領。也許你以前聽說過他？$B$B把他的血帶回來，$c，我將為這塊碎片附魔，使你能進入奧妮克希亞的巢穴。','你必須從達基薩斯將軍身上取回黑龍勇士之血，你可以在黑石塔的晉升大廳後面的房間裡找到他。','','去冬泉谷找凱斯利爾廢墟的哈爾琳。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6503 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6503,'zhTW','梣谷先驅者','我們得到訊息說，不久前從梣谷派出的先遣人員離開了銀翼哨站，現在正向我們的領地滲透。我們不能讓這些間諜得到我們防禦工事的情報！$B$B悄悄穿過我們崗哨南邊以及聯盟的銀翼哨站東邊的森林，找到並殺死那些先驅者，然後回到我這裡來。','殺掉9個梣谷先驅者，然後回到碎木哨崗的庫萊比那裡。','','去梣谷找碎木崗哨的庫萊比。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6504 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6504,'zhTW','丟失的書頁','我剛剛從棘齒城得到了這臺伐木機，準備回到戰歌伐木場去上班。伐木機中放著一本操作說明書，但在回來的路上，一陣強風把它從我手中吹走了，紙張散落得到處都是，剩下的就只有封面了。$B$B現在那些紙都飛到不知哪裡去了……沒有它們，我就壓根不知道該如何操作這臺伐木機！你能幫我找到它們嗎？','找到丟失的12頁伐木機操作指南，把它們合併為第1、2、3章。然後帶著這些書頁回到碎木崗哨去找古爾達·怒痕。','','去梣谷找碎木崗哨的古爾達·怒痕。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6521 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6521,'zhTW','邪惡的盟友','瑪克林聲稱他在剃刀高地外面。這位大使必須被幹掉——他的任務在巫妖王的眼中是徹頭徹尾的失敗。$B$B他在那裡的出現確實解釋了我們的一些發現，比如某些野豬人已經變得非常強大，並且還顯示出了被感染亡靈瘟疫的跡象。那一定是他們達成某種交易的徵兆。$B$B找到瑪克林並殺了他，$N。任務完成後回來找我。','把瑪克林大使的頭顱交給幽暗城的瓦里瑪薩斯。','','轉至幽暗城，去找皇家區的布拉貢·血拳。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6522 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6522,'zhTW','邪惡的盟友','大人：$B$B您很清楚我們可以提供什麼。您佔領貧瘠之地及其它土地的機會非常大，我們也只想要您的幫助作為回報。所謂的幫助不過是讓您授予我們在這一帶行動的自由。$B$B請允許我們說得更遠些。我們擁有強大的力量，並願意與那些希望加入我們的聰明人分享。我目前仍待在剃刀高地外面。$B$B向您致以最高的敬意，$B瑪克林大使','把小卷軸交給幽暗城的瓦里瑪薩斯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6523 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6523,'zhTW','保護卡雅','謝謝你救了我！我們必須趕快離開，不然很快就會被發現的。請護送我回到阿帕拉耶營地去。到了那裡，我就知道回去的路了。$B$B我的父親瑪卡巴·扁蹄得知我安全回家之後一定會很高興的。','護送卡雅·扁蹄回到阿帕拉耶營地，然後到石爪山東南邊界附近的瑪卡巴·扁蹄那裡去覆命。','護送卡雅·扁蹄回到阿帕拉耶營地','去石爪山脈和貧瘠之地的交界處找瑪卡巴·扁蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6541 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6541,'zhTW','向卡德拉克報到','你去過北面的梣谷沒有？部落最近在那裡的佐拉姆海岸旁設立了哨所，我們經常派一些剛剛招募的新兵來協助防守前線。$B$B如果你願意的話，就到貧瘠之地北部的哨塔裡找卡德拉克。他正要去梣谷進行戰鬥，應該可以給你進一步的指示。','到貧瘠之地北部的卡德拉克那裡報到。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6542 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6542,'zhTW','向卡德拉克報到','你去過北面的梣谷沒有？部落最近在那裡的佐拉姆海岸旁設立了哨所，我們經常派一些剛剛招募的新兵來協助防守前線。$B$B如果你願意的話，就到貧瘠之地北部的哨塔裡找卡德拉克。他正要去梣谷進行戰鬥，應該可以給你進一步的指示。','到貧瘠之地北部的卡德拉克那裡報到。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6543 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6543,'zhTW','戰歌報告','我最近派了一些斥候進入梣谷，所以我得找個跑腿的去把他們的報告帶回來。$B$B你的第一站應該是西面的佐拉姆海岸邊的佐拉姆加前哨站，在那裡可以找到第一個斥候。另外你還要到北邊的碎木哨崗去，它就在東邊的路上，靠近艾薩拉地區。你可以在那裡找到一個斥候和一個偵查騎兵。$B$B給他們每人一份報告，然後把他們的最新報告拿回來。','開啟報告集，把戰歌報告交給戰歌斥候、戰歌信使和戰歌偵查騎兵。把他們的最新報告交給貧瘠之地北部哨塔上的卡德拉克。','','去貧瘠之地找摩爾沙農場的卡德拉克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6544 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6544,'zhTW','託雷克的突襲','嘿！$C！到這兒來！$B$B我將和我的部隊準備襲擊西邊的銀翼哨站，這次行動的目標是他們的首領杜瑞爾·月火。據偵察，那座哨站中有重兵把守。這將是一場激烈而光榮的戰役！$B$B你願意加入我們的隊伍嗎，$N？如果你願意的話，那麼當戰役結束時，你就可以去將我們勝利的訊息彙報給慰藉之林的埃爾託格·怒齒了。$B$B你認為怎麼樣，要跟我們一起來嗎？','保護在銀翼哨站與杜瑞爾·月火作戰的託雷克，然後向慰籍之林的埃爾託格·怒齒彙報勝利的訊息。','攻佔銀翼哨站。','去梣谷找弗倫河的埃爾託格·怒齒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6545 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6545,'zhTW','戰歌信使的報告','','','','去找費伍德森林的戰歌信使。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6546 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6546,'zhTW','戰歌侍從的報告','','','','去找艾薩拉的戰歌偵查騎兵。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6547 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6547,'zhTW','戰歌斥候的報告','','','','去找梣谷的戰歌斥候。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6548 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6548,'zhTW','為我的村莊復仇','恐怖圖騰氏族劫掠了我的村莊，一個活口都沒留下。我奮力殺敵，但還是差一點就被殺掉了。$B$B $N ，現在我唯一的願望就是讓他們付出血的代價。你可以在這裡的西面找到他們。','殺掉8個恐怖圖騰惡徒和6個恐怖圖騰傭兵，然後向石爪山脈東南邊界處的瑪卡巴·扁蹄覆命。','','去石爪山脈和貧瘠之地的交界處找瑪卡巴·扁蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6561 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6561,'zhTW','黑暗深淵中的邪惡','我的力量已經離我而去。我需要你的幫助！$B$B很久以前，這裡曾經是偉大的月神殿。但是不幸降臨了，一名墮落的上古之神從地下冒出來，汙染了神聖的月亮井。 $B$B上古之神的奴僕阿庫麥爾從水中升起。$B$B暮光之錘的信徒和納迦一起佔領了這塊土地。由克爾里斯領導的那些信徒為了讓阿庫麥爾獲得力量而犧牲了許多無辜的生命。$B$B請你殺掉克爾里斯，把他的頭顱交給雷霆崖的巴珊娜。','把夢遊者克爾里斯的頭顱交給雷霆崖的巴珊娜·符文圖騰。','','在雷霆崖的長者高地找到芭莎娜符文圖騰。.','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6562 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6562,'zhTW','幫助耶努薩克雷','耶努薩克雷需要幫助。他在梣谷的佐拉姆加前哨站那裡，就在石爪山的北面。穿過風剪峭壁，或者從貧瘠之地直接往北走，都可以到達那裡。佐拉姆海岸在森林的最西面，小心一些，$N。那裡是非常危險的。','與梣谷的耶努薩克雷談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6563 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6563,'zhTW','阿庫麥爾水晶','在通往黑暗深淵入口的通道中有許多生長在洞穴牆壁上的藍寶石，最近有訊息說納迦正在挖掘這些寶石。在搞清楚他們的動機之前，我們應該先阻止它們。這些水晶中蘊含著強大的元素力量，只要經過一定的處理，它們就可以被製作成強大的魔法材料。$B$B你能幫幫我嗎，$N？從我們的哨所往北走，然後就可以在佐拉姆海岸附近找到黑暗深淵了。','收集20顆阿庫麥爾藍寶石，把它們交給梣谷的耶努薩克雷。','','去梣谷找佐拉姆加前哨站的耶努薩克雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6564 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6564,'zhTW','上古之神的僕從','皺巴巴的便箋上潦草地寫著：$B$B“對，通知所有的祭司把水晶帶到我這裡來，水元素的靈魂蘊含其中，它們能夠很好地幫助我們的水佔師進行召喚儀式。$B$B透過控制水晶中的力量，我們就可以取悅阿庫麥爾。終有一天，我們會獲得足夠的力量，把阿庫麥爾帶回到我們身邊，整個世界都將要迎接一個偉大的新時代！一個由上古之神統治的時代！”','把潮溼的便箋交給梣谷的耶努薩克雷。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6565 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6565,'zhTW','上古之神的僕從','我們絕對不能讓這個暮光之錘的信徒完成他的計劃。暮光之錘根本不瞭解自然的真義。他們信仰上古之神——很久之前就被擊敗了的、代表著混亂和毀滅的生物。你必須阻止洛古斯，$N。我無法自己來完成這個任務——因為我太脆弱了。$B$B到黑暗深淵去，找到他，殺了他。完成任務之後就回到我這裡來。','殺掉黑暗深淵裡的洛古斯·杰特，然後向梣谷的耶努薩克雷覆命。','','去梣谷找佐拉姆加前哨站的耶努薩克雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6566 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6566,'zhTW','風吹來的訊息','很高興再次看到你，$N。風從東部王國帶來了新的訊息。$B$B坐下，聽我說。','聽索爾講話。','索爾的故事','去找奧格瑪的索爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6567 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6567,'zhTW','部落的勇士','我的一位忠誠的勇士雷克薩說他發現了進入龍穴的方法，不過他已經離開艾澤拉斯，加入了外域遠征軍。$B$B幸好，雷克薩的同伴羅卡魯目前住在葬影村，他可以幫助你。去找他吧。','按照酋長的指示找到羅卡魯。他在淒涼之地的葬影村。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6568 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6568,'zhTW','幻術的欺詐','你對幻象有什麼瞭解嗎，$N？你必須要製造一個幻象，這樣你才能騙過那些黑龍的眼睛。$B$B我知道有一個人也許願意幫你完成任務。她過去曾經幫助過我們，因此她值得信任。$B$B你可以在西瘟疫之地找到巫女麥蘭達，她是被洛丹倫聯盟放逐的幻術師。把這個交給她。','把羅卡魯的信交給西瘟疫之地的巫女麥蘭達。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6569 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6569,'zhTW','黑龍幻象','那麼，一個$r想要變成一條黑龍，是嗎？$B$B你所透過一個試煉才能製造幻象，但是我們所需的原料卻是非常難以獲得的。酋長非常信任你，而且把這個任務交給了你，所以麥蘭達也同樣認為你可以勝任。$B$B到黑石塔的上層堡壘去，殺掉足夠多的黑色龍人，把它們的眼睛給我拿回來。','到黑石塔去收集20顆黑色龍人的眼球，完成任務之後回到巫女麥蘭達那裡。','','去西瘟疫之地找悔恨嶺的巫女麥蘭達。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6570 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6570,'zhTW','埃博斯塔夫','我已經對這塊獎章施加了魔法，它可以在埃博斯塔夫的巢穴裡製造並維持幻影。$B$B埃博斯塔夫是一條古老的龍，它是奈法利安的衛士，專門負責考察那些即將成為奧妮克希亞精英守衛的龍人。$B$B到塵泥沼澤中的巨龍沼澤吧，埃博斯塔夫的巢穴就在那裡。進入巢穴之後戴上護符，讓命運指引你前進吧！','到塵泥沼澤中的巨龍沼澤去，找到埃博斯塔夫的洞穴。進入洞穴之後戴上龍形護符，然後跟埃博斯塔夫交談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6571 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6571,'zhTW','戰歌氏族的補給品','我們在戰歌伐木場中的某些物資出現了短缺！$B$B碎木哨崗的皮克希爾有我們所需的戰歌鋸條，另外，你必須前往藏寶海灣，從碼頭管理員羅茲基爾那兒取回一箱斧頭。$B$B不過要取回油和繩索就比較困難了。熊怪盜走了繩索，薩特截走了油，在它們的儀式中使用！$B$B如果我不能儘快把這批物資送過去，我可就麻煩大了——你能幫幫我嗎？','收集戰歌氏族的補給品：戰歌鋸條、伐木繩、戰歌之油，還有一箱戰歌之斧。','','去梣谷找碎木崗哨的洛克·奧卡爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6581 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6581,'zhTW','戰歌鋸條','','','','去找梣谷的皮克希爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6582 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6582,'zhTW','龍骨試煉，斯克利爾','我們是死亡之翼的孩子，小黑龍。我們對於其它低等龍類的控制必須得到保障。$B$B如果你真的有價值的話，那些低等龍類就會因為你的到來而毀滅。$B$B找到他們，以我們父親的名義消滅他們！$B$B到冬泉谷去獵殺強大的藍龍斯克利爾，殺了它以及任何膽敢阻擋你的藍龍。把它的顱骨給我拿回來。','找到藍龍斯克利爾並殺掉他。從他的身上取下他的顱骨，然後將其交給埃博斯塔夫。$B$B你可以在冬泉谷找到斯克利爾。','','去找塵泥沼澤的埃博斯塔夫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6583 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6583,'zhTW','龍骨試煉，索姆努斯','我們的父親擊潰了其它守護巨龍，我們也必須給他們的孩子帶來混亂和毀滅。$B$B你必須在那些綠龍的孩子身上檢驗你的力量。$B$B到悲傷沼澤去找到索姆努斯，它是綠龍的勇士。讓它感受你的憤怒，殺掉那隻可憐的小蟲……把他的顱骨給我拿回來……','殺掉綠龍索姆努斯，把他的顱骨交給埃博斯塔夫。','','去找塵泥沼澤的埃博斯塔夫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6584 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6584,'zhTW','龍骨試煉，克魯納里斯','諾茲多姆，時間之王……他的孩子們……$B$B有三條龍看守著時光之穴，但我們黑龍只對其中一條感興趣：時光的轉換者，克魯納里斯，他是諾茲多姆最喜歡的孩子……$B$B把他殺掉，讓整個沙漠都因你的力量而震動，把他的顱骨給我拿回來……','諾茲多姆的孩子克魯納里斯在塔納利斯沙漠守衛著時光之穴。殺了他，把他的顱骨交給埃博斯塔夫。','','去找塵泥沼澤的埃博斯塔夫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6585 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6585,'zhTW','龍骨試煉，埃克托茲','我們的父親在格瑞姆巴托的群山中大發神威，對抗守護之龍的力量。阿萊克斯塔薩，那個懦弱的背叛者，她畏怯地逃跑了。$B$B多麼可恥的行為……$B$B現在紅龍守衛著格瑞姆巴托，他們的領導者埃克托茲必須被幹掉，把他的顱骨給我帶回來。為了我們的父親而戰，小黑龍！','到格瑞姆巴托去殺掉紅龍埃克托茲，把他的顱骨交給埃博斯塔夫。','','去找塵泥沼澤的埃博斯塔夫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6601 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6601,'zhTW','晉升……','我用我們的那些敵人的顱骨製作了一枚勳章，你知道這枚勳章的用處吧？你以前一定看到過你的前輩戴著這樣的一枚勳章了。$B$B拿著它，小黑龍。回到黑石塔去，把它給達基薩斯將軍看看，將軍會對它進行最後的點化，將它與你的靈魂綁在一起。$B$B完成之後的勳章將使你感到你所擁有的榮譽，它象徵著你已經達到了一個令人敬畏的高度：我們母親的守護者。$B$B現在就出發吧！','看來這場假面舞會就要結束了。你知道麥蘭達為你製作的龍形護符在黑石塔裡面不會發揮作用，也許你應該去找羅卡魯，將你的困境告訴他。把黯淡的龍火護符給他看看，也許他知道下一步該怎麼做。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6602 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6602,'zhTW','黑龍勇士之血','你要去拜訪一下將軍，沒錯，但並不是以黑龍的樣子去拜訪。$B$B你看，這個儀式所需的不過是更多的流血而已。$B$B這個未完成的飾物只需要將軍的血就可啟用，這是它們那野蠻而原始的備用機制。$B$B回到黑石塔去幹掉達基薩斯，把他的血拿來給我，然後我就可以幫你啟用開啟奧妮克希亞巢穴的鑰匙。','到黑石塔去殺掉達基薩斯將軍，把它的血交給羅卡魯。','','去淒涼之地找葬影村的羅卡魯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6603 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6603,'zhTW','冬泉谷的麻煩！','冬泉谷有麻煩了！$B$B當然，我在野外度過了如此長的時間，所以我對這些事情是瞭如指掌……我總是對能這麼說感到很光榮。我感到我在那些山嶺裡度過的時光是很寶貴的，那段時光培養了我快捷的反應，冷靜的頭腦，還有銳利的目光……$B$B只有具備足夠的判斷力和豐富的知識才能像我一樣評價大自然。$B$B嗯，我都說了些什麼？$B$B啊，對，麻煩。到溫泉那邊去找多諾瓦·雪山，她會告訴你更多的細節。','到冬泉谷的溫泉附近去找到多諾瓦·雪山。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6604 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6604,'zhTW','被激怒的梟獸','你有沒有注意到南邊那個廢棄的營地？看來那裡是被瘋狂的梟獸洗劫過了！$B$B我聽說從那次攻擊中僥倖逃脫的一個倖存者正在墜星村裡休養，就在這裡的西邊。我對這事情很感興趣……你呢？','與墜星村的加隆·石矛談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6605 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6605,'zhTW','奇怪的傢伙','我剛從費伍德森林回來，$N。我在血毒崗哨停留了一下，在那裡我遇見了一個奇怪的傢伙……她似乎有重要的事情要做，我可以告訴你她要幹什麼，但是我想最好還是讓她自己解釋給你聽吧。$B$B如果你感興趣的話，就到費伍德森林西部的血毒崗哨去找溫娜·哈薩德。$B$B誰知道呢，也許她需要你的幫助……','與費伍德森林的溫娜·哈薩德談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6606 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6606,'zhTW','一點運氣','我們總是需要一些運氣，不是嗎？一些小優勢就可以讓你把事情轉向有利你的方向……$B$B我讓一個熟人，嗯，一個奇怪的巫醫幫我做了個幸運符……當然是有代價的。但是相信我，那絕對值得！$B$B也許你自己也想要有這樣一個幸運符？那麼到冬泉谷去找巫醫瑪艾裡吧，我可不會把自己的這個給你！','與冬泉谷永望鎮的巫醫瑪艾裡談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6607 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6607,'zhTW','釣魚專家納特·帕格','我不能說我非常喜歡釣魚，但是算起來我也已經釣了有二三十年了吧。$B$B我想很多人都是因為各種各樣的原因而去做他們正在做的那些事情吧。$B$B當然，我的意思並不是你也得耐著性子釣三十年才能成為一個釣魚高手。我想你只需有足夠的耐心和定力，可以一坐就是幾個小時，而且要在這期間什麼都不幹。$B$B我跟你說啊，給我抓來一些非常稀有的魚，然後我就會教你幾招。以下是列表：','納特·帕格要你釣到以下幾種魚：$B$B悲傷沼澤蘆葦海岸的蘆葦海岸大馬哈魚。$B$B淒涼之地薩瑟里斯海岸的薩瑟里斯虎魚。$B$B菲拉斯沃丹提斯河的菲拉斯草魚。$B$B荊棘谷野人海岸的野人海岸藍色叉牙魚。$B$B當你釣到這些魚之後，就可以回到納特·帕格那裡去了！','','去塵泥沼澤找納特的碼頭的納特·帕格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6608 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6608,'zhTW','你真棒！','魯瑪克已經沒有什麼可教給$n的了。你太棒了！去找魯瑪克的朋友納特·帕格吧，他是一個人類，但我不吃他！他是魯瑪克的朋友！納特教你釣魚。$B$B你也許可以在塞拉摩島的那個人類鎮子南面，嗯，塵泥沼澤裡，在那裡找到他，納特·帕格可能正在那裡釣魚。現在就出發吧！','你認為魯瑪克想要告訴你，他已經不能幫你提高釣魚的技能了。也許你應該去找到他的朋友納特·帕格，他居住在塞拉摩以南的某個島嶼上，他是一名人類漁夫（至少你認為魯瑪克是這麼說的）。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6609 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6609,'zhTW','青出於藍！','我是個大嗓門的矮人，我親愛的$g小夥子:小姑娘！我可不是為了釣魚而生出來的！我的意思是，看看我！我是用石頭刻出來的。$B$B我沒有什麼可保留的了——你已經把我知道的全都學會啦！$B$B你還不明白嗎？啊，好吧。我在卡利姆多大陸有一個朋友，他也許可以幫你。他的名字叫納特·帕格，是一個很友善的人。你可以在塞拉摩南邊的島上找到他。快出發吧！','到卡利姆多大陸的塞拉摩去。從那裡向南方出發，找到一座島嶼。納特·帕格就在島上等待著你的到來！','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6610 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6610,'zhTW','蚌肉大餐','你聽說過蚌肉大餐沒有？顯然沒有！這是我最最終極、最最偉大的烹飪傑作！哦，$N，只是想一想蚌肉大餐就足以讓我垂涎三尺了。$B$B不幸的是，我沒有足夠的原料來烹飪它！我們來做筆交易怎麼樣？你為我收集必需的原料，我將這種無上美味的烹飪方法告訴你，此外我還請你吃一頓蚌肉大餐！如何？$B$B很好！我需要下列材料：','迪爾格·奎克里弗想要你收集這些原料：$B$B10只巨蛋。你可以在塔納利斯的大鵬或是其它大型鳥類那裡獲得這種蛋。$B$B10塊美味的蚌肉。你可以從任何蚌類身上獲得這種原料！$B$B20塊奧特蘭克冷酪。去買就是了！$B$B收集好所有原料，然後把它們交給迪爾格。','','去找塔納利斯的迪爾格·奎克里弗。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6611 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6611,'zhTW','加基森之旅！','你還想讓扎姆沙教你什麼呢？你已經學到了扎姆沙的所有烹飪秘訣，所以扎姆沙已經無能為力了！肥胖的亡靈應該去加基森，你可以在那裡找到一個名叫迪爾格的小地精——他會幫助你的。$B$B當你成為炙手可熱的大廚時，再回來教教扎姆沙吧，好嗎？出發吧！','到塔納利斯沙漠的加基森去，與迪爾格·奎克里弗談談你的廚師生涯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6612 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6612,'zhTW','我認識一個傢伙…','我可以從你手裡的炒菜勺子看出你是幹什麼的。不幸的是，我什麼也不能教你。$B$B不過我認識一個傢伙，他是個地精，也許是卡利姆多大陸上最好的廚師。$B$B啊，也許這是個壞訊息，$g小夥子:小姑娘——你要跑一趟卡利姆多。到加基森去找迪爾格·奎克里弗，他會告訴你接下來該怎麼做的。','到塔納利斯沙漠的加基森去，與迪爾格·奎克里弗談談你的廚師生涯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6621 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6621,'zhTW','汙林熊怪之王','$N，熊怪的汙林部族住在阿斯特蘭納的東南面。它們在數量上並沒有薊皮熊怪多，但是其殘暴和好戰的性格卻對我們造成了巨大的威脅。我們必須給它們一個嚴厲的警告。$B$B拿著這面旗子，把它插在汙林村莊的圖騰堆中。這會激怒那些熊怪，讓它們衝上來想要除去旗子，但是你一定要堅守自己的位置，最終你就會面對它們的酋長穆戈特。擊敗它，把它身上的圖騰給我拿回來。$B$B別忘了和你的朋友一起去，$n，僅憑一個$c是無法成功的。','把卡拉恩的旗子插到汙林圖騰堆中。不要讓熊怪摧毀這面旗子。擊敗穆戈特酋長，將穆戈特的圖騰交給佐拉姆加的卡拉恩·阿瑪卡。','','去梣谷找佐拉姆加前哨站的卡拉恩·阿瑪卡。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6622 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6622,'zhTW','救死扶傷','你好，醫生。我們將在今天下午對你的醫術進行檢驗。如果你透過了測試，那麼你將榮幸地成為部落外科醫療隊的一員。$B$B現在注意了！致命傷要優先處理，然後是重傷，傷勢一般的病患放在最後處理。你必須拯救至少15個病人才能透過這個測試。如果有6個病人在這個過程中死亡，那麼你就失敗了。$B$B我們會給你提供治療所需的繃帶。$B$B祝你好運，醫生。','使用急救繃帶來治療病人。你必須在6個病人死亡之前拯救15個病人。$B$B一定要牢記治療的順序！受致命傷的病人會很快死亡，其次是重傷病人，受普通傷的病人死亡得最慢。所以你最好在治療那些受致命傷和重傷的病人之後再去治療受普通傷的病人。','拯救15個病人！','去阿拉希高地找落錘鎮的格里高利·維克托醫生。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6623 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6623,'zhTW','部落醫療隊','$N醫生，我想我應該這麼稱呼你。很高興再見到你。$B$B我有些好訊息要告訴你！格里高利·維克托醫生，也就是部落外科醫療隊的首席醫師，要求你到落錘鎮去加入他的隊伍。這可是畢生難求的機會啊！我真希望能付出一切來換取跟隨格里高利·維克托醫生學習的機會！你可不要浪費了這個機會！','到阿拉希高地的落錘鎮去，與格里高利·維克托醫生談一談關於加入部落外科醫療隊的事宜。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6624 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6624,'zhTW','救死扶傷','你好，醫生。我們將在今天下午對你的醫術進行檢驗。如果你通過了測試，那麼你將榮幸地成為聯盟外科醫療隊的一員。$B$B現在注意了!致命傷要優先處理，然後是重傷，傷勢一般的病患放在最後處理。你必須拯救至少15個病人才能通過這個測試。如果有6個病人在這個過程中死亡，那麼你就失敗了。$B$B我們會給你提供治療所需的繃帶。$B$B祝你好運，醫生。','使用急救繃帶來治療病人。你必須在6個病人死亡之前拯救15個病人。','拯救15個病人！','去塵泥沼澤找塞拉摩島的古斯塔夫·範沃森醫生。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6625 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6625,'zhTW','聯盟醫療隊','$N醫生，我想我應該這麼稱呼你。很高興再見到你。$B$B我有些好訊息要告訴你！古斯塔夫·範沃森醫生，也就是聯盟外科醫療隊的首席醫師，要求你到塞拉摩去加入他的隊伍。這可是畢生難求的機會啊！我真希望能付出一切來換取跟隨古斯塔夫·範沃森醫生醫生學習的機會！你可不要浪費了這個機會！','到塵泥沼澤的塞拉摩去，與古斯塔夫·範沃森醫生談一談關於加入聯盟外科醫療隊的事宜。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6626 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6626,'zhTW','邪惡之地','被遺忘者不會因為他們的疾病而逝去……至少我所看到的是這樣。這使得他們的追隨者在某種意義上可以獲得永恆的生命。我在想，他也許是亡靈天災的一員。$B$B至於現在，我關注的不是他，而是他身邊不斷膨脹的部隊。他們總是躲藏在陰影之中，總是向他祈求更多的力量。$B$B現在我無法自己去和他們作戰，$N。你看怎麼樣？你做好大戰一場的準備了嗎？','殺掉8個剃刀沼澤護衛者、8個剃刀沼澤織棘者和8個亡首教徒，然後向剃刀高地入口處的麥雷姆·月歌覆命。','','轉至貧瘠之地，去找剃刀高地入口附近的麥雷姆·月歌。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6627 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6627,'zhTW','知識試煉','你把這本書帶來給了我，現在是向你提問的時候了。你準備好了嗎？$B$B時間並不緊迫，$c，所以不要太緊張。你可以在準備妥當之後再來接受提問。','成功回答布勞格·幽魂的問題，然後和他再次對話。他會一直在石爪山等你回答問題。','成功回答布勞格·幽魂的問題','去找石爪山脈的布勞格·幽魂。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6628 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6628,'zhTW','知識試煉','我們又將面臨一個考驗。作為知識的學生，你在接受我的任務的時候展示了驚人的堅韌和決心。$B$B現在我將要向你提出一個問題。如果你準備好了，就再次和我說話，你的時間很充分，$N，別太著急。','成功回答帕科瓦·芬塔拉斯的問題，然後再次和他對話。他會一直在幽暗城等你回答問題。','成功回答帕科瓦·芬塔拉斯的問題','去幽暗城找鍊金房的帕科瓦·芬塔拉斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6629 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6629,'zhTW','殺死格魯迪格·暗雲',' $N ，你很好地完成了殺掉恐怖圖騰成員的任務。如果你有膽量的話，就去挑戰格魯迪格·暗雲和他的手下吧，他們是最難對付的敵人，而格魯迪格就是攻擊我們村莊的主謀。$B$B你可以在這裡西邊稍遠的地方找到恐怖圖騰崗哨，他就在那裡。殺了他，我會永遠感謝你的。','殺掉格魯迪格·暗雲和6個恐怖圖騰蠻卒，然後向石爪山東南面的瑪卡巴·扁蹄覆命。','','去石爪山脈和貧瘠之地的交界處找瑪卡巴·扁蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6641 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6641,'zhTW','鞭笞者沃爾沙','鞭笞者沃爾沙……在海中出沒的殘忍的多頭蛇怪……$B$B她頻繁地、無緣無故地襲擊我們的崗哨，到處製造混亂。$B$B但是我已經準備就緒了，$N。我要去擊敗那個怪物，讓她不再對佐拉姆構成威脅。$B$B納迦在海岸邊的小島上放置著一個長明的火盆，以此來表示他們對這野獸的尊崇。我想，如果我們熄滅火盆，沃爾沙一定會非常憤怒的。$B$B我們需要幫助，因此你最好邀上一些強大的朋友同去。','在穆格拉什尋找火盆的過程中保證他的安全。幫助他撲滅火盆，然後在與納迦作戰時保護他。$B$B如果你成功了，就回到佐拉姆加前哨站去，把鞭笞者沃爾沙的死訊通知給戰歌信使。','擊敗鞭笞者沃爾沙','去找梣谷的戰歌信使。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6642 AND `locale` = 'zhTW';
