INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6661,'zhTW','捕捉礦道老鼠','慢著，你這飯桶。你...你在找活幹嗎?我們這兒鼠災氾濫，甲板上人手不夠。$B$B你說什麼?你只需要吹奏這根捕鼠者之笛就行了，牠們會跟著你走向生命的盡頭!$B$B給我抓五隻小壞蛋來，把牠們交給我，我要活的。$B$B啊...','使用捕鼠者之笛捕獲5隻礦道老鼠，把老鼠們引到蒙提那兒去。','','去鐵爐堡找坑道地鐵的蒙提。','捕捉老鼠','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6662 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6662, 'zhTW', '我的兄弟，尼普希', '我的兄弟尼普希在地鐵的另一端經營一家烤老鼠肉。你必須在這箱老鼠壞掉之前把它們交給他。趕快!$B$B你以前坐過地鐵，對吧?很簡單，只要等車停下來，走上去，然後就享受你的旅程吧。在車子行進時可別把頭手伸出車外，免得你下半輩子得靠義肢過日子。', '把裝著神秘肉品的紙箱交給在暴風城礦道地鐵倉庫的尼普希。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6681 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6681,'zhTW','拉文霍德莊園',' $N :$B$B拉文霍德已經對你感興趣了，小賊。我們一直在觀察你。你的狀況有些尷尬，但沒有什麼是我們不能改變的。$B$B如果你想要在拉文霍德大人手下謀求一份工作，以及成為刺客聯盟的一員，只需把拉文霍德徽印(已附在信中)拿到拉文霍德莊園來。$B$B你的第一項任務就是要找到莊園，它就隱藏在希爾斯布萊德的群山之中，你要充分發揮你的聰明才智。$B$B向你致敬，$B$B- 法拉德。','把拉文霍德徽印交給拉文霍德莊園的法拉德，莊園就坐落在希爾斯布萊德的群山之中。','','去希爾斯布萊德丘陵找拉文霍德莊園的法拉德。','','詭計儀式','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6701 AND `locale` = 'zhTW';
