INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6844,'zhTW','檔案管理員阿姆伯爾','我們有很多事情要做，但是我認為把這個帶回議會進行分析是最關鍵的。相信我，如果這團黏呼呼的東西里面是一本日記的話，議會將最終開啟通往過去的視窗！$B$B把這個交給永夜港議會的檔案管理員阿姆伯爾，他是個才華橫溢的人，雖然有些瘋瘋癲癲，但是真的非常能幹！阿姆伯爾曾補救許多遠比這本書更破舊的典籍，他肯定可以勝任這個工作。','將異種蠍粘液包裹的物體交給月光林地永夜港的阿姆伯爾，他是塞納里奧議會的檔案管理員。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6845 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6845,'zhTW','發現過去的秘密','無論如何，如果你想要了解這兒的情況的話……就應該儘快找我核實。一旦我查明瞭真相，而且這確實是一本書的話，那麼我會很高興與你分享這裡面的知識。$B$B同時，我也會通知月光林地的拉比恩，他肯定想要知道你做出了多麼瘋狂的事情。別讓他等太久，$N……除非你想被扔到蜂蜜中。$B$B相信我，這樣的事兒不是沒發生過。','與月光林地永夜港的拉比恩·薩圖納談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6846 AND `locale` = 'zhTW';
