INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6847,'zhTW','雷爾松的全視之眼','你們在奧特萊克山脈大舉交戰對辛迪加來說沒什麼意義，$C。我們會按照慣例來做，等待時機，直到看見你們分出勝負，然後趁勢發起攻擊。但是，那並不是我們現在留在這裡的原因。我的全視之眼不見了，它被這裡的冰斧巨魔給拿走了。找到全視之眼，然後我們就會為你效力——直到分出勝負。當你拿到全視之眼後就回到我這裡來，然後我就可以好好看看你了。$n;指揮官雷爾松咧嘴笑著。$g;','從冰斧巨魔洞穴中找到雷爾松的全視之眼，然後回到指揮官雷爾松那裡。要當心，據說雷爾松的全視之眼帶有可怕的詛咒！','找回雷爾松的全視之眼','去找奧特蘭克山谷的辛迪加指揮官雷爾松。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6848 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6848,'zhTW','雷爾松的全視之眼','你們在奧特萊克山脈大舉交戰對辛迪加來說沒什麼意義，$C。我們會按照慣例來做，等待時機，直到看見你們分出勝負，然後趁勢發起攻擊。但是，那並不是我們現在留在這裡的原因。我的全視之眼不見了，它被這裡的冰斧巨魔給拿走了。找到全視之眼，然後我們就會為你效力——直到分出勝負。當你拿到全視之眼後就回到我這裡來，然後我就可以好好看看你了。$n;指揮官雷爾松咧嘴笑著。$g;','從冰斧巨魔洞穴中找到雷爾松的全視之眼，然後回到指揮官雷爾松那裡。要當心，據說雷爾松的全視之眼帶有可怕的詛咒！','找回雷爾松的全視之眼','去找奧特蘭克山谷的辛迪加指揮官雷爾松。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6861 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6861,'zhTW','斯菲萊克斯的行動式伐木機','我和你一樣焦急地想要試一下我的行動式伐木機，$c，但是我必須要弄到一些材料——我是說很多材料——才能製作出配套的工具！$B$B實際上，我需要像山那麼大的一堆瑟銀、秘銀和鐵，另外每一臺伐木機還需要有一個蒸汽鋸才能完工，你最好到伐木場去找找看。$B$B我在這裡遊蕩的時候（在我被抓住之前），曾在雷矛伐木場裡看到很多的蒸汽鋸。','首席技師斯菲萊克斯要你給他拿去下列物品：$B$B30塊瑟銀錠。$B$B50塊秘銀錠。$B$B75塊鐵錠。$B$B1個蒸汽鋸。','','去找奧特蘭克山谷的首席技師斯菲萊克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6862 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6862,'zhTW','斯菲萊克斯的行動式伐木機','我和你一樣焦急地想要試一下我的行動式伐木機，$c，但是我必須要弄到一些材料——我是說很多材料——才能製作出配套的工具！$B$B實際上，我需要像山那麼大的一堆瑟銀、秘銀和鐵，另外每一臺伐木機還需要有一個蒸汽鋸才能完工，你最好到伐木場去找找看。$B$B我在這裡遊蕩的時候（在我被抓住之前），曾在雷矛伐木場裡看到很多的蒸汽鋸。','首席技師斯菲萊克斯要你給他拿去下列物品：$B$B30塊瑟銀錠。$B$B50塊秘銀錠。$B$B75塊鐵錠。$B$B1個蒸汽鋸。','','去找奧特蘭克山谷的首席技師斯菲萊克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6881 AND `locale` = 'zhTW';
