INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7027,'zhTW','補充坐騎','看看這裡的獸欄，$N！空空如也！雷矛部族的騎兵部隊沒有坐騎——它已經名存實亡了。$B$B你必須幫助我們，士兵。拿著這根頸圈，到山谷中去尋找四處徘徊的奧特蘭克山羊，並使用訓練頸圈來抓住它們。當你抓住山羊之後，就把它給我帶回來，然後我就可以將它配備給騎兵部隊了。$B$B當我們有足夠的山羊之後，山羊騎兵將再次準備就緒。有了你的幫助，騎兵部隊將會獲得重生！','找到奧特蘭克山谷中的山羊。使用雷矛訓練頸圈來馴服它們。被馴服的山羊會跟隨你回到獸欄管理員那裡，然後與獸欄管理員談話以獲得你的獎勵。','馴服並上繳山羊','去奧特蘭克山谷找丹巴達爾的雷矛獸欄管理員。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7028 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7028,'zhTW','扭曲的邪惡','泰拉莫克水晶洞穴坐落在這裡的西邊，在瑪拉頓的深處……那裡是一處擁有悠久歷史的古蹟。我希望從那裡得到一些東西，$c。上古之神的遺物就在那些巨門的後面。$B$B如果你願意挑戰潛伏在瑪拉頓裡的那些扭曲的邪惡力量，我一定會讓你為做出這個決定而感到滿意的。收集你所找到的瑟萊德絲水晶雕像，把它們交給我。$B$B一旦我拿到雕像，我就能……研究它們。雕像中蘊含的力量已經沉睡太久了……','為淒涼之地的維洛收集15個瑟萊德絲水晶雕像。','','去找淒涼之地的維洛。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7029 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7029,'zhTW','維利塔恩的汙染','一個名叫維利塔恩的薩特正在玷汙瑪拉頓的洞穴，使那裡的許多植物無法生長。$B$B拿著這個瓶子，$N。用洞穴裡面橙色水晶池中的水裝滿這個瓶子；瓶中所包含的物質可以中和毒藥，將它變成一種治療藥劑。$B$B你可以在橙色的洞穴中找到維利斯塔姆藤蔓，然後對它們使用淨化過的液體。這樣，附著在植物上的墮落物質就會被淨化，但是你要知道維利塔恩仍然控制著這些植物。他會利用它來對付你……','在瑪拉頓裡用天藍水瓶在橙色水晶池中裝滿水。$B$B在維利斯塔姆藤蔓上使用裝滿水的天藍水瓶，使墮落的諾克賽恩幼體出現。$B$B治療8株植物並殺死那些諾克賽恩幼體，然後向葬影村的瓦克·戰痕覆命。','','去淒涼之地找葬影村的瓦克·戰痕。','治療維利斯塔姆藤蔓','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7041 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7041,'zhTW','維利塔恩的汙染','一個名叫維利塔恩的薩特正在玷汙瑪拉頓的洞穴，使那裡的許多植物無法生長。$B$B拿著這個瓶子，$N。用洞穴裡面橙色水晶池中的水裝滿這個瓶子；瓶中所包含的物質可以中和毒藥，將它變成一種治療藥劑。$B$B你可以在橙色的洞穴中找到維利斯塔姆藤蔓，然後對它們使用淨化過的液體。這樣，附著在植物上的墮落物質就會被淨化，但是你要知道維利塔恩仍然控制著這些植物。他會利用它來對付你……','在瑪拉頓裡用天藍水瓶在橙色水晶池中裝滿水。$B$B在維利斯塔姆藤蔓上使用裝滿水的天藍水瓶，使墮落的諾克賽恩幼體出現。$B$B治療8株植物並殺死那些諾克賽恩幼體，然後向尼耶爾前哨站的塔琳德莉亞覆命。','','去淒涼之地找尼耶爾前哨站的塔琳德莉亞。','治療維利斯塔姆藤蔓','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7042 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7042,'zhTW','被偷走的冬幕節禮物','聽著……我不想破壞了節日的美好氣氛，但是煙林牧場需要幫助——需要你這樣的冒險家。$B$B我們弄丟了節日所需的重要禮品，現在連我們派去尋找禮品的煙林牧場密探也不見了！請幫幫忙——禮品是在奧特蘭克山脈附近丟失的，我們派出的密探也在那兒。$B$B看看禮品和密探是否都安然無恙吧！','前往奧特蘭克山脈雪域尋找失蹤的煙林牧場密探。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7043 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7043, 'zhTW', '你是個卑鄙的人……', '一個叫做「可惡的格林奇」的生-生-生物偷走了我們的貨-貨-貨物，$N。但是要小-小-小心！就-就-就是他把我變成了一團雪-雪-雪人的！$B$B如果你要-要-要面-面-面對他的話，你可-可-可能需要一點幫助。我看見他總是在雪-雪-雪怪出沒的地方晃-晃-晃悠；他一-一-一定在那-那-那裡！找-找-找到我們的貨物，$N，把貨物帶回-回-回給鐵爐堡的燻木牧場，並告-告-告訴他們我需-需-需要解凍！', '找到並把被偷走的禮品帶給鐵爐堡的烏爾莫特。它被可惡的格林奇拿走了，去奧特蘭克山脈的雪地中去找它。', '', '去找鐵爐堡的烏爾莫特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7044 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7044,'zhTW','瑪拉頓的傳說','一個名叫維利塔恩的黑暗薩特在這些蜿蜒曲折的洞穴中散播著他的邪惡力量。他住在有著紫色水晶的入口那邊。$B$B維利塔恩還創造了一個名叫諾克賽恩的墮落生物，讓它把守在有著橙色水晶的入口那邊。他們偷取了我兄弟的節杖。塞雷布拉斯，我的兄弟……他在洞中毫無目的地遊蕩，被墮落的力量所詛咒。$B$B你必須幫助他！找到節杖的兩個部分，然後……想辦法和我兄弟談談。','找回塞雷布拉斯節杖的兩個部分：塞雷布拉斯魔棒和塞雷布拉斯鑽石。$B$B然後設法和塞雷布拉斯對話。','','去找瑪拉頓的塞雷布拉斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7045 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7045, 'zhTW', '', '', '[Speak with Greatfather Winter in Ironforge.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7046 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7046,'zhTW','塞雷布拉斯節杖','我的權杖是我希望的源泉。它的力量可以讓我自由穿梭於這些洞穴中。我希望能夠讓我叔叔的靈魂得到安寧……這是我要交給你的任務。$B$B為了讓這兩個部分再次結合起來，我需要你的協助來完成儀式。請跟著我，聽從我的指示行動，然後我就會重新把鑽石鑲到節杖上。$B$B讓我們一起把塞雷布拉斯節杖重新組合起來！','幫助贖罪的塞雷布拉斯製作塞雷布拉斯節杖。$B$B當儀式完成之後再和他談談。','製造塞雷布拉斯節杖','去找瑪拉頓的塞雷布拉斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7061 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7061, 'zhTW', '冬幕節', '這兒 - 若你有興趣對冬幕節了解更多的話，可以閱讀這本書。當我認為我們對於確認這個傳說的行為是適當的同時，我也受夠了學者把珍貴的資訊都搜括到一個地方的行為。$B$B當你完成了以後，把這本書拿給凱恩·血蹄。我知道他若聽到有其他人關注著我們族人的傳說之時，他會感到有興趣的。', '請自由取閱那本「冬幕節」來學習更多關於這個節日的意義。當你看完這本書後，把它送去給雷霆崖的凱恩·血蹄。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7062 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7062, 'zhTW', '季節的由來', '禮物，款待，獎品……我要說，呸！那些哥布林玷污了這個季節的真正意義——冬幕節。這是個萬物復甦的時刻，整個大地安靜的覆蓋在冬天爺爺所帶來的薄雪之下，冬天爺爺可不是那個穿著紅色外套的笨蛋！如果你想要瞭解更多關於冬幕節的事情，就去問問探險者聯盟的史學家卡尼克吧。它肯定會因為有人對禮物不感興趣而是對冬幕節的歷史感興趣而感到驚奇的。', '跟鐵爐堡的探險者聯盟的史學家卡尼克詢問關於冬幕節的事情。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7063 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7063, 'zhTW', '冬幕節', '拿著 - 若你有興趣對冬幕節多點了解的話，可以閱讀這本書。當我認為我們對於確認這個傳說的行為是適當的同時，我也受夠了學者把珍貴的資訊都搜括到一個地方的行為。$B$B當你看完以後，把這本書拿給國王麥格尼·銅鬚。我知道他若聽到有其他人關注著更老的傳說之時，他會感到興趣的。', '請自由取閱那本「冬幕節」的書來學習更多關於這個節日的意義。當你看完這本書後，把它送去給鐵爐堡的國王麥格尼·銅鬚。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7064 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7064,'zhTW','大地的汙染','在瑪拉頓的深處居住著一個邪惡的混亂生物——瑟萊德絲公主，她是一個和上古之神相關的地元素。很早以前，她和塞納留斯的長子扎爾塔結合，他們的後代……被稱為半人馬。那些半人馬殺掉了扎爾塔，並保留了他的遺體。我的任務是徵召足夠強大的冒險者去殺死瑟萊德絲，這樣我們就可以在回到石爪山之前找到扎爾塔的遺體了。','殺死瑟萊德絲公主，然後回到淒涼之地葬影村附近的瑟琳德拉那裡覆命。','','去淒涼之地找薩瑟里斯海岸的瑟琳德拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7065 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7065,'zhTW','大地的汙染','在瑪拉頓的深處居住著一個邪惡的混亂生物——瑟萊德絲公主，她是一個和上古之神相關的地元素。很早以前，她和塞納留斯的長子扎爾塔結合，他們的後代……被稱為半人馬。那些半人馬殺掉了扎爾塔，並保留了他的遺體。我的任務是徵召足夠強大的冒險者去殺死瑟萊德絲，這樣我們就可以在回到石爪山之前找到扎爾塔的遺體了。','殺死瑟萊德絲公主，然後回到淒涼之地尼耶爾前哨站的守護者瑪蘭迪斯那裡覆命。','','去找淒涼之地的守護者瑪蘭迪斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7066 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7066,'zhTW','生命之種','這些私生的半人馬——我的兒子和女兒——需要他們的父親。$B$B看看你的周圍——這個地方遍佈著希望，遍佈著我父親塞納留斯夢想中的寧靜。它們在從我的體內源源不斷地湧出來！我不能剝奪他們享受這一切的權利……即便他們對我犯下了深重的罪惡。$B$B但是我有一件事情需要請你幫助，以便讓我兄弟的心靈得到撫慰。拿著這個……這是我的遺體孕育出來的第一顆種子。告訴他，我的靈魂還在這裡，我還在繼續活著。我相信他可以理解我。','到月光林地去找到雷姆洛斯，將生命之種交給他。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7067 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7067,'zhTW','賤民的指引','雖然我被當作異教徒流放了，但我的信仰還是一如既往——它將永遠激勵我前進。為了完成我的使命，我不得不借助外來者的力量……而不是我的半人馬同胞們。這真可悲。$B$B這個任務需要深入神聖的瑪拉頓——那座墳墓被我的同胞保護著，只有最為虔誠的半人馬才能進入。$B$B如果你願意幫助我，只需點點頭就行了。我會給你一塊羊皮紙，上面寫著具體的指示。閱讀那塊羊皮紙然後考慮一下我的話。','閱讀賤民的指引，然後從瑪拉頓得到聯合墜飾，將其交給淒涼之地南部的半人馬賤民。','','去淒涼之地找瑪諾洛克集會所的半人馬賤民。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7068 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7068,'zhTW','暗影殘片','在半人馬的聖地瑪拉頓中有著強大的魔法，淒涼之地的半人馬用他們的生命來保衛那個地方，但他們無法阻止我們拿走我們想要的東西。$B$B你現在要去一趟瑪拉頓，尋找那些由暗影殘片組成的石頭生物。如果你把那種紫色的水晶交給我，那麼尤塞爾奈就會為你付出的時間而獎勵你。$B$B那個地方很危險，也許你應該找一些朋友與你一同探險。','從瑪拉頓收集10塊暗影殘片，然後把它們交給奧格瑪的尤塞爾奈。','','去找奧格瑪的尤塞爾奈。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7069 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7069,'zhTW','<UNUSED>','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7070 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7070,'zhTW','暗影殘片','我最近開始測試不同的水晶和它們所具有的魔法特性。普羅德摩爾女士讓我徵集一些旅行者去淒涼之地尋找一處被稱作瑪拉頓的地方。在那座廢棄的廟宇中，巨大的元素生物帶有紫色的石頭，我把那種石頭稱為暗影殘片。$B$B如果你決定去那裡的話，請幫我找些暗影殘片回來，我會非常感謝你的。如果你需要的話，我甚至可以用它們製作一件飾物給你。','從瑪拉頓收集10塊暗影殘片，然後把它們交給塵泥沼澤塞拉摩島上的大法師特沃什。','','去找塞拉摩島的大法師特沃什。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7081 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7081,'zhTW','奧特蘭克山谷的墓地','奧特蘭克山谷中的墓地具有非常重要的戰略價值，部落和聯盟為爭奪這些神聖的土地瘋狂地廝殺，雙方都付出了慘重的代價。而你，$N，你做好加入戰鬥的準備了嗎？$B$B如果你想要知道一塊墓地是由哪一方控制的，只需觀察插在墓地上的旗幟就知道了。看到由部落佔領的墓地就把它攻打下來！一直殺到墓地中間去，拔出部落的旗幟。這樣一來，那片墓地就是我們的了！','佔領一座墓地，然後向丹巴達爾的諾雷格·雷矛中尉覆命。','','去奧特蘭克山脈找加文高地的杜爾根·雷矛。','佔領墓地','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7082 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7082,'zhTW','奧特蘭克山谷的墓地','奧特蘭克山谷中的戰鬥總是寸土必爭的。在殊死的拼殺中，我們和敵人所控制的區域在不斷地變化。而對墓地的爭奪則是最激烈的戰鬥，$N。$B$B為部落佔領一座墓地！找到插著聯盟戰旗的墓地，把他們的旗子拔掉。然後這座墓地就是我們的了！','佔領一座墓地，然後向霜狼村的亞斯拉覆命。','','去找奧特蘭克山脈的提卡·血牙。','佔領墓地','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7101 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7101,'zhTW','哨塔和碉堡','哨塔和碉堡是非常重要的戰略設施，我們必須完全佔領它們！因此，我要求你去進攻被敵人佔領的哨塔和碉堡。$B$B想要佔領一座哨塔和碉堡，你就必須殺進去，將聯盟的旗幟拔掉，這樣部落的旗幟就會在那裡出現，然後大功告成！$B$B此時你就完成了我下達給你的任務，如果我們能夠佔據那些設施足夠長的時間，並且不被聯盟奪回去，那麼我們就可以控制那一帶了！','佔領敵方的某座哨塔，然後向霜狼村的提卡·血牙覆命。','','去找奧特蘭克山脈的提卡·血牙。','佔領哨塔','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7102 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7102,'zhTW','哨塔和碉堡','哨塔和碉堡是非常重要的戰略設施，我們必須完全佔領它們！因此，我要求你去進攻被敵人佔領的哨塔和碉堡。$B$B想要佔領一座哨塔和碉堡，你就必須殺進去，將部落的旗幟拔掉，這樣聯盟的旗幟就會在那裡出現，然後大功告成！$B$B此時你就完成了我下達給你的任務，如果我們能夠佔據那些設施足夠長的時間，並且不被部落奪回去，那麼我們就可以控制那一帶了！','摧毀敵方的某座哨塔或者碉堡中的旗幟，然後向丹巴達爾的杜爾根·雷矛覆命。','','去奧特蘭克山脈找加文高地的杜爾根·雷矛。','摧毀旗幟','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7121 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7121,'zhTW','軍需官','$N，我們的軍需官讓我派新兵去他那裡報到。他需要奧特蘭克礦洞中的礦藏作為軍需之用，也許他會派你去採集它們。$B$B沿著這條路走，你可以在西邊找到軍需官。','與雷矛軍需管談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7122 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7122,'zhTW','佔領礦洞','奧特蘭克的這座礦洞蘊藏不僅僅是礦藏。部落和聯盟都在深鐵礦洞和冷齒礦洞中儲藏了大量的補給……如果我們能控制它們的話，那就太好不過了！$B$B佔領一座礦洞，然後回到我這裡來。想要佔領一個礦洞的話，你必須進入一個還未被我們控制的礦洞並殺死那裡的領袖。這樣礦洞就是我們的了，而我們也將派遣部隊來保護它！','佔領一座還沒有被雷矛部族控制的礦洞，然後向丹巴達爾的雷矛軍需官覆命。','','去奧特蘭克山脈找加文高地的杜爾根·雷矛。','佔領礦洞','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7123 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7123,'zhTW','霜狼軍需官','$N，霜狼軍需官正在招募新兵，他需要派一些士兵深入奧特蘭克山谷的礦洞。去和他談談吧，他會告訴你更多的資訊。$B$B沿著西邊的路進入碉堡，然後從西邊的出口出去，你就可以找到軍需官了。','與霜狼軍需官談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7124 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7124,'zhTW','佔領礦洞','奧特蘭克山谷中戰事不斷升級，對冷齒礦洞和深鐵礦洞的爭奪也越來越激烈。豐富的礦藏和物資儲備吸引了雙方的勢力，它們的價值實在是太高了！$B$B請幫助我們的部隊，$N！為部落佔領一座礦洞！你必須進入一個仍未被我們控制的礦洞，然後幹掉其中的首領。當你完成這個目標之後，這座礦洞就是我們的了，而且我們會派遣部隊駐守其中！','佔領一座礦洞，然後向霜狼村的霜狼軍需官報告。','','去找奧特蘭克山脈的提卡·血牙。','佔領礦洞','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7141 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7141,'zhTW','奧特蘭克的戰鬥','偵查人員報告說，在奧特蘭克山谷中隱藏著許多神器，但是霜狼氏族的獸人不會讓我們接近它們。我們不能讓部落阻止我們對於學術的追求！去幹掉他們的統帥，德雷克塔爾。只要他死了，那些獸人就會亂成一團。$B$B德雷克塔爾在奧特蘭克山谷南端的霜狼要塞中，把他除掉，然後回到我這裡來。','進入奧特蘭克山谷，擊敗部落將軍德雷克塔爾。然後回到勘查員塔雷·石鎬那裡。','擊敗德雷克塔爾。','去找勘查員塔雷·石鎬。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7142 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7142,'zhTW','為奧特蘭克而戰','雷矛部族的矮人和他們的盟友正在入侵奧特蘭克山谷，我們必須和他們決一死戰！要想贏得這場戰鬥的勝利，我們就必須幹掉他們的統帥，範達爾·雷矛！$B$B你可以在北面的丹巴達爾要塞裡找到他，$B$B幹掉他，然後回來向我報告。','進入奧特蘭克山谷，擊敗矮人將軍範達爾·雷矛。然後回到沃加·死爪那裡。','擊敗範達爾·雷矛。','去找奧特蘭克山脈的沃加·死爪。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7161 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7161,'zhTW','實驗場','你好，$c。經過如此長時間的等待，我們終於有機會響應戰鬥的召喚了。舊日的感覺正在慢慢恢復，我們又將熱血沸騰！$B$B所有新兵都必須完成氏族的試煉。$B$B在附近的蠻爪豺狼人山洞裡面有一面霜狼氏族的旗幟。去那裡拿回旗幟，然後把它還給我，我就將授予你霜狼新兵的勳章。','到主基地東南邊的蠻爪洞穴中去找到霜狼軍旗，然後把它交給拉格隆德。','','去找奧特蘭克山脈的拉格隆德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7162 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7162,'zhTW','實驗場','你來得真及時，$c。那些霜狼氏族的蠻子就是不願意放棄！我們要讓他們看看聯盟真正的力量，讓他們一潰千里。$B$B在你踏入戰場之前，你最好先透過雷矛部族的試煉。$B$B在這裡東南邊的冰翼洞穴深處有一面雷矛部族的旗幟。到那裡去，把旗幟帶回來，然後把它交給我。這樣你就可以得到一枚雷矛部族新兵的勳章。','到主基地東南邊的冰翼洞穴中去找到雷矛軍旗，然後把它交給哈格丁中尉。','','去希爾斯布萊德丘陵找達隆山的哈格丁中尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7163 AND `locale` = 'zhTW';
