INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7402,'zhTW','通緝：獸人！','根據諾雷格·雷矛中尉的命令，所有雷矛部族的士兵都要殺掉$g他:她在戰場上看到的每一個獸人。$B$B帶回獸人的獠牙來作為完成任務的證明。$B$B另外別忘了戴手套。','你被指派去殺死奧特蘭克山谷中的獸人玩家。$B$B殺掉一個獸人，然後把獸人的獠牙交給丹巴達爾的諾雷格·雷矛中尉。','','去奧特蘭克山谷找丹巴達爾的諾雷格·雷矛中尉。','','','','',0);
