INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7492,'zhTW','莫沙徹營地','菲拉斯的牛頭人長者塔羅·刺蹄派人送信請求幫助。他並沒有詳細述說詳情，但是他說他需要一個有著足夠的勇氣而且做事細緻的冒險者來幫助他。$B$B為了部落而戰，$N。到菲拉斯的莫沙徹營地去找塔羅談談吧。','和菲拉斯莫沙徹營地的塔羅·刺蹄談一談。','','','','','','',0);
