INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7494,'zhTW','羽月要塞','$N！菲拉斯需要你的幫助！$B$B一個名叫蕾瑟塔蒂絲的流亡法師逃進了古代暗夜精靈的遺蹟——埃雷薩拉斯，現在那裡被稱為厄運之槌。她手中有一件非常危險的魔法物品，我們一定要拿回它。$B$B拉託尼庫斯·月矛要求派遣強大的冒險者進入厄運之槌，從蕾瑟塔蒂絲手裡拿回那件東西。$B$B為了聯盟而戰！你可以在菲拉斯的羽月要塞中找到拉託尼庫斯。','和菲拉斯羽月要塞的拉託尼庫斯·月矛談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7495 AND `locale` = 'zhTW';
