INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7507,'zhTW','弗洛爾的屠龍技術綱要','你找到了一些非常重要的東西。這本書和你看到過的其它的書不太一樣。$B$B某些人或者某些東西將圖書館的封印揭掉了，這本書中的文字十分混亂，根本無法辨識。','將《弗洛爾的屠龍技術綱要》還回圖書館。','','','','','','',0);
