INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7508,'zhTW','鑄造奎爾塞拉','如果你想要接手這個任務，那就把這把黯淡的精靈劍交給萊德羅斯吧。','把黯淡的精靈劍交給博學者萊德羅斯。','','','','','','',0);
