INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7738,'zhTW','完美的雪人毛皮','你找到了一塊非常完美的雪人毛皮，它非常厚實——比那些怒痕雪人的毛皮要厚實許多。$B$B莫沙徹營地的杉多爾·迅蹄專門做雪人毛皮的生意，這些毛皮一定可以引起他的興趣。','把完美的雪人毛皮交給菲拉斯莫沙徹營地的杉多爾·迅蹄。','','','','','','',0);
