INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7785,'zhTW','復生之瓶','去檢視一下他的復生之瓶，凡人。逐風者會在那兒重生！','檢視復生之瓶，然後回到德米提恩那裡去。','','','','','','',0);
