INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7786,'zhTW','逐風者桑德蘭','我已經把我所知道的東西都告訴你了，$N。你必須找到源質，你必須毀滅拉格納羅斯的軀體。$B$B快點出發吧，完成我的命令，你就將獲得桑德蘭的祝福。','如果你想要把逐風者桑德蘭從監牢裡釋放出來，你就必須找到左右兩塊逐風者禁錮之顱，10塊源質錠，以及火焰之王的精華，把它們交給德米提恩。','','去找希利蘇斯的德米提恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7787 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7787,'zhTW','覺醒吧,雷霆之怒','你已經擊敗了逐風者，那麼，拿上風吻之刃，讓那個叛徒德米提恩用你提供的材料喚醒雷霆之怒吧。','把風吻之刃交給德米提恩。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7788 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7788,'zhTW','擊敗入侵者！ (PvP)','在這個通道的另一端，你會看到一片戰火紛飛的土地，年輕的$C。部落不斷侵入我們神聖的森林，鋸斷這裡的蒼天古樹來建造他們的戰爭機器。$B$B進入戰歌峽谷，幫助銀翼要塞擊敗入侵的部落勢力，並贏得一枚功勳獎章吧。把這樣的獎章給我拿來，你就將獲得獎賞。','進入戰歌峽谷抵禦部落小隊的攻擊，獲得一枚銀翼功勳獎章，然後向銀翼樹林中的哨兵艾蒂亞·輕歌回覆。','','去梣谷找銀翼樹林的哨兵艾蒂亞·輕歌。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7789 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7789,'zhTW','鎮壓銀翼部隊','梣谷森林將在強大的部落面前屈服，$R。無論暗夜精靈們說什麼做什麼，都無法阻止我們的推進。卡利姆多屬於部落，誰敢阻止我們拿取屬於我們的東西，誰就要死！$B$B讓你的心中充滿榮耀之光，讓那些膽敢阻止我們的敵人一個個倒下。摧毀銀翼要塞中的哨兵部隊，並拿到一枚戰歌榮譽獎章。把這樣一枚獎章給我拿來，你就可以獲得獎賞。','進入戰歌峽谷擊敗聯盟小隊，獲得一枚戰歌榮譽獎章，然後向莫爾杉營地的沙塔爾·碎顱覆命。','','去貧瘠之地找莫爾杉營地的沙塔爾·碎顱。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7790 AND `locale` = 'zhTW';
