INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7828,'zhTW','銀鬃捕獵者','許多勇敢的巨魔都在辛特蘭的森林中失蹤了，$r。銀鬃狼對我們的獵人來說是最大的威脅。它們靜靜地隱藏在灌木叢中，當時機成熟之後就發起突然襲擊。$B$B我們一定要阻止這種殘忍的行為！$B$B你必須和銀鬃狼一樣思考。我們要以牙還牙，獵捕它們！把它們全都幹掉！','辛特蘭惡齒村的獵戶馬克霍爾要求你去殺掉5頭銀鬃捕獵者和5頭銀鬃嗥狼。完成任務之後就回到他那裡覆命。$B$B馬克霍爾說過那些狼都躲在辛特蘭的野外。','','去辛特蘭找惡齒村的獵戶馬克霍爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7829 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7829,'zhTW','野蠻的梟獸','辛特蘭地區最令人討厭的生物之一就是那些野蠻的梟獸。很多勇敢的惡齒戰士都倒在了那些野獸的利爪和尖嘴之下。$B$B幹掉你看到的每個野蠻的梟獸，$r。當你把它們殺得血流成河的時候就回到我這裡來，你的貢獻一定會得到我們的讚賞。','辛特蘭惡齒村的獵戶馬克霍爾要求你去殺掉10頭野蠻的梟獸。完成任務之後就回到他那裡覆命。$B$B馬克霍爾說過那些野蠻的梟獸都躲在辛特蘭的野外。','','去辛特蘭找惡齒村的獵戶馬克霍爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7830 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7830,'zhTW','死者的復仇','現在蠻錘部族訓練的獅鷲正在肆意屠殺巨魔。這真是太可怕了，但是我知道不久之後正義就將得到伸張。$B$B現在我需要派你去清除那些成年的獅鷲首領，也就是那種翱翔的獅鷲。$B$B幹掉它們中的一個，然後把它的羽毛交給我。','辛特蘭惡齒村的獵戶馬克霍爾要求你殺掉一頭翱翔的鋒喙獅鷲，並將它的獅鷲長羽拿回去交給他。$B$B馬克霍爾說過那些翱翔的鋒喙獅鷲就躲在辛特蘭的野外。','','去辛特蘭找惡齒村的獵戶馬克霍爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7831 AND `locale` = 'zhTW';
