INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7905, 'zhTW', '暗月馬戲團', '暗月馬戲團來囉!它們進城後，你一定要去體驗所有驚奇與刺激!$B$B如果你現在就行動，你可以用這張禮券去兌換免費的獎品券!只要把你的禮券交給馬戲團裡的吉瓦斯·葛萊蓋特就行了。$B$B現在，馬戲團就在閃金鎮外，在艾爾文森林。千萬別錯過囉!今天就去吧!', '將這張免費獎券兌換券交給暗月馬戲團中的吉瓦斯·葛萊蓋特。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7906 AND `locale` = 'zhTW';
