DELETE FROM `quest_template_locale` WHERE `ID` = 7907 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7907,'zhTW','暗月野獸套牌','你現在已經收集到了野獸套牌的所有卡片，與前8張的背面圖案完全一樣的第9張卡片神秘地出現在你手中。在這張卡片上寫著，“將這些卡片拿到暗月馬戲團去，你就將獲得獎勵。”你聽說暗月馬戲團每過幾個月就會路過一次莫高雷和閃金鎮，因此你也許需要等待一段時間才能看到他們。','當暗月馬戲團來到鎮上的時候，把野獸套牌交給他們。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7908 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7908,'zhTW','競技場高手','要成為競技場高手肯定需要付出更多的代價！也許管理古拉巴什競技場的海盜知道到底要多少！','與荊棘競技場的小個子約翰·米斯瑞爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7921 AND `locale` = 'zhTW';
