INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8120,'zhTW','阿拉希盆地之戰！','無疑你已經聽說了，阿拉索聯軍正派大量的軍隊進駐阿拉西盆地。聯盟那幫蠢貨想要食物和補給，因此妄圖佔據這塊富饒的土地。我們必須讓他們知道阿拉希永遠不再會是人類的家園了！$B$B去阿拉希盆地然後進攻那裡礦井，伐木場，鐵匠鋪和馬廄。奪下敵人在那裡的旗幟，把那裡變成部落的領土。$B$B出發吧，$N。當任務完成之後向我覆命。','進攻阿拉希盆地的礦洞、伐木場、鐵匠鋪和獸欄，然後向落錘鎮的屠殺者杜維爾覆命。','','去阿拉希高地找東部禁錮法陣的屠殺者杜維爾。','突襲礦洞','突襲伐木場','突襲鐵匠鋪','突襲獸欄',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8121 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8121,'zhTW','奪取四座基地','$N，隨著阿拉希盆地的戰事進展，你的事蹟已經傳遍了戰場。你的所做所為讓我確信你一定可以完成現在我要給你的任務。$B$B現在是給阿拉索聯軍一個訊號的時候了。我們將會向他們展示，他們在阿拉希盆地的防守是多麼脆弱。我們要透過同時佔領阿拉希盆地的四個戰略點來讓他們明白這一點。$B$B如果你可以完成這個任務，$N，你將贏得汙染者的尊敬。','同時佔據阿拉希盆地中的四座基地，然後向落錘鎮的屠殺者杜維爾覆命。','控制四座基地。','去阿拉希高地找東部禁錮法陣的屠殺者杜維爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8122 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8122,'zhTW','奪取五座基地','我們其實已經深深陷入戰爭之中，只是我們還沒有意識到。幸好，我們的探子回報說發現了阿拉索聯軍的弱點。我們必須利用這一機會對他們造成致命一擊！回到阿拉希盆地，和我們的敵人交戰吧。詛咒他們，幹掉他們，控制所有的五個戰略點！讓他們的士兵尖叫，流血，從前線倉皇撤退，讓他們用抽泣的嘴唇述說你的事蹟。$B$B完成這一目標，為汙染者帶來光輝的勝利。','同時佔據阿拉希盆地中的五座基地，然後向落錘鎮的屠殺者杜維爾覆命。','控制五座基地。','去阿拉希高地找東部禁錮法陣的屠殺者杜維爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8123 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8123,'zhTW','切斷阿拉索補給線','阿拉索聯軍正在不惜一切代價進攻阿拉希，並妄圖奪回這個區域。聯盟的各個種族正在全力進軍這塊遙遠的土地，想要將他們的勢力從避難谷地擴張到這裡。我們必須阻止他們，而最好的方式就是奪取他們的資源。$B$B你可以幫助我們，$N。進入阿拉希盆地，那裡遍地都是豐富的礦藏、肥沃的土地和技藝精湛的能工巧匠。佔據並控制你找到的所有基地，贏得戰鬥，然後把你獲得的資源給我拿回來。','進入阿拉希盆地，獲得一箱阿拉希資源箱，然後將它交給落錘鎮的亡靈哨兵莫提斯。','','去阿拉希高地找落錘鎮的亡靈哨兵莫提斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8124 AND `locale` = 'zhTW';
