INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8149, 'zhTW', '緬懷英雄', '在艾澤拉斯收穫節上，我們對那些無私奉獻英雄們表示感謝，他們其中甚至獻出自己的性命。聯盟曾湧現出很多的英雄，但是沒有誰的光芒能超越光明使者烏瑟。$B$B將這些祭品帶到西瘟疫之地光明使者烏瑟的墓碑那兒，去表達我們的敬意吧。把祭品放在墓碑下，然後回到我們這兒來。收穫節結束之前我會一直在這兒，別浪費時間了，出發吧。', '前往西瘟疫之地的光明使者烏瑟的墓碑，在墓碑前放下他的祭品。在收穫節結束之前返回鐵爐堡的瓦格納·巨錘那兒。', '在烏瑟之墓前獻上祭品', '去找丹莫羅的瓦格納·巨錘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8150 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8150, 'zhTW', '緬懷英雄', '在艾澤拉斯收穫節上，我們對那些無私奉獻英雄們表示感謝，他們其中甚至犧牲自己的生命。部落曾湧現出許多英雄，但是沒有誰的光芒能超越葛羅·地獄吼。$B$B將這些祭品帶到梣谷屠魔峽谷中的葛羅·地獄吼的墓碑那兒，去表達我們的敬意吧。把祭品放在墓碑下，然後回到我們這兒來。收穫節結束之前我會一直在這兒，別浪費時間了，出發吧。', '前往梣谷屠魔峽谷的葛羅·地獄吼的墓碑，在墓碑前放下他的祭品。在收穫節結束之前返回奧格瑪的亞尼·納沙克那兒。', '在格羅姆紀念碑前獻上祭品', '去找杜隆塔爾的亞尼·納沙克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8151 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8151,'zhTW','獵人的護符','艾薩拉的奧汀克正在召集象你這樣經驗豐富的獵人。他是一名熊怪獵人，他離開了自己的部族，前來幫助塞納里奧議會。奧汀克與他人分享自己的智慧，也告訴他們要如何維護平衡。你最好去跟他談談。$B$B奧汀克居住在艾薩拉埃達拉斯廢墟東北部的懸崖頂部。','跟艾薩拉的奧汀克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8152 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8152,'zhTW','REUSE','$N，如果你準備就緒的話，在艾薩拉有一位名叫奧汀克的熊怪獵人，他聰明博學，經驗豐富。或許他能訓練並指導你。$B$B奧汀克居住在艾薩拉埃達拉斯廢墟東北部的懸崖頂部。','跟艾薩拉的奧汀克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8153 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8153,'zhTW','苔蹄快步者的鹿角','艾薩拉的苔蹄快步者那強勁有力的鹿角是它們發動進攻時的有效武器，可以造成不小的傷害。完好的、自然的鹿角是這種動物的精神和信心的標誌。$B$B如果你持有這樣的鹿角，你也將擁有同樣的自信。$B$B獵殺苔蹄快步者，把完好的鹿角交給我。','將一副完好的苔蹄快步者鹿角交給艾薩拉的奧汀克。奧汀克居住在埃達拉斯廢墟東北部的懸崖頂。','','去艾薩拉找破碎海岸的奧汀克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8154 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8154,'zhTW','阿拉希盆地的資源!','我們必須依靠我們的士兵進行戰鬥，所有的士兵都會這麼告訴你的。他們還會告訴你，他們正在使用破爛不堪的裝備，饑腸轆轆地開向戰場!$B$B這就是阿拉希盆地顯得非常重要的原因。金屬，武器，食物，木材─所有我們所需要的東西都可以從那裡獲得。$B$B那就是我需要你發揮作用的地方， $N 。進入阿拉希盆地，比敵人佔據更多的基地，以此來獲得戰鬥的勝利，然後給我帶回一箱資源來。','獲得阿拉希盆地戰鬥的勝利，獲取一只阿拉希資源木箱，然後向避難谷地的瑪克里爾中士覆命。','','去阿拉希高地找避難谷地的瑪克里爾中士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8155 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8155,'zhTW','阿拉希盆地的資源!','我們必須依靠我們的士兵進行戰鬥，所有的士兵都會這麼告訴你的。他們還會告訴你，他們正在使用破爛不堪的裝備，饑腸轆轆地開向戰場!$B$B這就是阿拉希盆地顯得非常重要的原因。金屬，武器，食物，木材─所有我們所需要的東西都可以從那裡獲得。$B$B那就是我需要你發揮作用的地方， $N 。進入阿拉希盆地，比敵人佔據更多的基地，以此來獲得戰鬥的勝利，然後給我帶回一箱資源來。','獲得阿拉希盆地戰鬥的勝利，獲取一隻阿拉希資源木箱，然後向避難谷地的瑪克里爾中士覆命。','','去阿拉希高地找避難谷地的瑪克里爾中士。','','','','',0);
