INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8181,'zhTW','面對葉基亞','透過對摩沙魯石板的研究，我得出了一個可怕的訊息，$N。你用一枚蛋收復了哈卡，然而血神哈卡的真身可以透過那枚蛋獲得新生！葉基亞告訴你說那枚蛋是用來禁錮哈卡的邪惡力量的，但實際上，它的作用是讓哈卡重生！那個巨魔將你引入了歧途！$B$B去找到葉基亞，摧毀那枚蛋。希望我們還有足夠的時間阻止哈卡死灰復燃！','跟葉基亞談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8182 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8182,'zhTW','拉斯塔哈之手','$N，我們最擔心的事情終於發生了。相傳擁有無上力量的奪靈者哈卡正在統治著巨魔的古代帝國，那裡充斥著邪惡和恐怖。如果我們不做點什麼的話，他的統治範圍很可能會蔓延到整個艾澤拉斯！$B$B也許贊達拉巨魔能幫助我們阻止悲劇的發生。他們駐紮在荊棘谷的祖昆達廢墟以西，也就是那個名叫尤亞姆巴的小島上。跟他們的首領莫托爾談談，但願他知道如何打敗哈卡。','跟荊棘谷的莫托爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8183 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8183,'zhTW','哈卡之心','哈卡之心熊熊燃燒著。雖然奪魂者已經被擊敗，但是他邪惡的力量依然在被詛咒的軀體之中湧動。','把哈卡之心交給尤亞姆巴島上的莫托爾。','','','','','','',0);
