INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8274,'zhTW','測試獵殺任務','有空嗎？幫我殺幾個魚人，我會給你很棒的東西！','殺死15只魚人然後向測試角色回報。','','Return to [PH] Luis Test NPC in Designer Island.','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8275 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8275, 'zhTW', '奪回希利蘇斯', '注意，聯盟的英雄們!異種蠍的威脅已經未經調查很久了。他們被真正的敵方釋放，這些時間都在準備一次大規模的擴張。塞納里奧議會的軍隊正在希利蘇斯集結以打敗這些可惡的生物，所有健全的冒險者都應該要加入我們!再等就來不及了!幫助我們防守艾澤拉斯!向塞納里奧城堡的喚風者傲角報告以獲得詳細指示!', '和在希利蘇斯塞納里奧城堡裡的喚風者傲角談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8276 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8276, 'zhTW', '奪回希利蘇斯', '注意，部落的勇士們!有一個威脅已經未受挑戰很久了。他們準備擴張的同時，整個艾澤拉斯異種蠍巢穴附近的地表震動已經大大的改變了我們。塞納里奧議會軍隊已在希利蘇斯集結，趁來得及之前對希利蘇斯採取行動!他們不能再敗壞我們的土地!所有健全的戰鬥者都要向塞納里奧議會的喚風者傲角報告!我們要征服異種蠍!', '和在希利蘇斯塞納里奧城堡裡的喚風者傲角談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8277 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8277, 'zhTW', '沙漠中的劇毒', '比提克斯·斯巴格為你效勞!我的堂兄諾格在為塞納里奧城堡的鍊金師進行稀有草藥的採集工作，好吧，至少以前他在這麼做。在他最後一次回來的時候，他的血液中帶著一種強力毒液。$B$B我已經設法減緩毒性發作的時間，但是如果想要完全中和它的話，我就需要這種毒液的原始樣本。$B$B諾格是從北面回來的，因此我想應該是石鞭蠍或者掠沙蜘蛛幹的。帶給我一些尖刺和毒牙，然後我就可以製作解毒劑了。', '希利蘇斯的塞納里奧城堡的比提克斯·斯巴格要你去收集8只石鞭蠍刺和8只掠沙蜘蛛毒牙。完成任務後回到她那裡。', '', '去希利蘇斯找塞納里奧要塞的比提克斯·斯巴格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8278 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8278, 'zhTW', '諾格的最後一線希望', '可惡!解毒劑沒有生效。諾格一定是被南邊的某種毒性更強的生物蜇了。$B$B我需要你去那裡給我帶回更多的樣品，$N。好消息是因為它們的毒性夠強，所以我需要的樣品數量不用那麼多。壞消息是南部各種有毒生物的種類更多，因此我需要各種各樣的樣品。', '希利蘇斯塞納里奧城堡的比提克斯·斯巴格要你去收集3只石鞭巨鉗蠍刺，3只石鞭撕掠者刺，和3只石行蜘蛛毒牙。', '', '去希利蘇斯找塞納里奧要塞的比提克斯·斯巴格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8279 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8279, 'zhTW', '暮光詞典', '暮光之錘對離開他們軍隊的人並不友善。他們把我當作野獸般的抓來!不用多說!他們的敵人就是我的朋友!$B$B要解讀這塊碑文，我需要他們的抄寫員所使用的那本書來破解秘密的訊息:也就是暮光詞典。那是一個極為重要的工具，所以他們將書本的三章放在不同的地方。負責託管辭典的職員叫暮光守護者，去暮光之錘營地找他們。', '將暮光詞典的3章帶給希利蘇斯的隱士奧泰爾。', '', '去找希利蘇斯的隱士奧泰爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8280 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8280, 'zhTW', '保護補給線', '塞納里奧城堡是最具戰略重要性的據點。我確信如果握有這個地方，我們對異種蠍的勝利就有保障。但前提是我們的物資供應可以維持。$B$B沙漠之蟲已被證實比異種蠍還威脅著我們的供給車隊。就在今天早上，一大批的晨光穀就被一群掘泥打擊者搶劫了。我需要你去削減他們的勢力，以確保我們的物資供給不受威脅。', '希利蘇斯的塞納里奧城堡的喚風者傲角要你去殺15個掘泥打擊者。', '', '去希利蘇斯找塞納里奧要塞的喚風者傲角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8281 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8281, 'zhTW', '確保安全', '$N，你的表現到目前為止的確是個典範。但是我們的供給線仍不完全安全。沒有了掘泥打擊者，他們在南方的大批表親會繼續向北移動來替補他們的位子。$B$B你必須殺死一些掘泥摧毀者讓他們留在海灣，但我們不能冒險丟下供給線的安全不管。', '希利蘇斯的塞納里奧城堡的喚風者傲角要你去殺20個掘泥摧毀者。', '', '去希利蘇斯找塞納里奧要塞的喚風者傲角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8282 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8282, 'zhTW', '諾格的背包', '我在哪裡?我的包包呢?*打嗝* 我一定是在從死亡彎鉤那隻巨蠍那裡逃走的時候弄丟了。我急忙逃亡的時候走進了石鞭撕掠者的巢穴。$B$B我帶的那個包包裡裝著所有種類的稀有試劑。沒有它們，我和比提克斯就不能製作塞納里奧城堡需要的藥劑。我還太虛弱不能起來，但如果你能將我的試劑帶回來，我絕對會讓你感到值得的。$B$B我是在銅鬚營地後面的南方山區遇到死亡彎鉤的。', '到希利蘇斯南邊山區找回諾格的背包，並回到塞納里奧城堡交還給他。', '', '去希利蘇斯找塞納里奧要塞的諾格·斯巴格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8283 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8283, 'zhTW', '通緝:死亡彎鉤', '隨著日益頻繁的異種蠍活動，大家相信恐怖的蠍子死亡彎鉤，已經撤退到南邊的山區了。他對南邊的巡邏兵和探險者來說是個很大的威脅。參予摧毀她的行列將會重重有賞。向塞納里奧城堡，眺望台頂端的維斯·庫魯茲隊長詢問相關事宜。', '將死亡彎鉤的刺針帶給守衛隊長維斯·庫魯茲。', '', '去希利蘇斯找塞納里奧要塞的維斯·庫魯茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8284 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8284, 'zhTW', '暮光的秘密', '一群暮光之錘祭司曾經在這裡的西北邊繁榮過。如果你是要去那邊冒險，你只會看到一個充斥著元素的區域，有著散落的木頭和標誌營地的帆布碎片。$B$B我從那裡拿回來幾個泥土字板碎片，但是數量實在太少，不能拼湊出什麼有用的東西。看看你能不能找到剩下的石板碎片，我們就能對希利蘇斯的暮光之錘多一些了解。', '希利蘇斯的塞納里奧城堡的地理學家拉克斯班要你去收集8個暮光石板碎片。', '', '去希利蘇斯找塞納里奧要塞的地理學家拉克斯班。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8285 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8285, 'zhTW', '沙漠隱士', '謠傳暮光之錘有個叫奧泰爾的成員背棄了他的教派。聽說他隱居在南風村南方的山裡。或許你可以獲得他的幫助來解讀石板。$B$B帶著修補的石板去找奧泰爾吧。', '帶著修補的石板去找希利蘇斯的隱士奧泰爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8286 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8286, 'zhTW', '明天的希望', '死亡的擁抱擁有一切，卻不能在干擾我的時候戰勝我的生命。他只要在我受傷的身體旁邊呼吸一次，然後耐心地等待時間之沙淨化我的傷口。$B$B他說，「只要你堅持，你會永遠存在」，就因為那幾個字我成為了一個守夜人。$B$B現在看看那個沙漠。第二次戰爭就要逼近我們了。你一定要找到銅龍的棲息地。到時光之穴冒險，看看大師是否回來了。我一定要在前進之前確定這點。', '到塔納利斯的時光之穴尋找諾茲多姆的子嗣安納克羅斯。', '發現諾茲多姆的血脈', '去希利蘇斯找塞納里奧要塞的流沙守望者巴里斯托爾斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8287 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8287, 'zhTW', '擺脫困境', '好，就是這個…這真是一個有價值的消息!我看到塞納里奧議會的軍隊到達希利蘇斯。他們打算把暮光之錘趕出去，對吧?這很有幫助。$B$B把這張羊皮紙交給他們的領導者，指揮官瑪爾利斯。很快的，暮光之錘會被擊敗，我就能永遠逃離他們的手掌心了!', '將解譯過的碑文羊皮紙交給指揮官瑪爾利斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8288 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8288, 'zhTW', '唯一的領袖', '不要浪費時間了!一定要找到一個英雄!我給的任務需要一個軍隊來完成，但是只有其中一個人會是優勝者，而他將接下身為龍族盟友的重擔和責任。$B$B黑石之王的巢穴裡有一隻最殘暴的野獸。龍領主勒西雷爾守衛著征戰大廳，阻擋通往奈法利安的核心密室之路。殺死那個骯髒的怪物並帶著他的頭顱回來找我。完成之後你就可以展開旅途的下一步驟。', '帶著龍領主勒西雷爾的頭顱回到希利蘇斯，到塞納里奧城堡的流沙之地找巴里斯托爾斯。', '', '去希利蘇斯找塞納里奧要塞的流沙守望者巴里斯托爾斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8289 AND `locale` = 'zhTW';
