INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8290, 'zhTW', '擊敗入侵者', '在這個通道的另一端，你會看到一片戰火紛飛的土地，年輕的$c。部落不斷侵入我們神聖的森林，鋸斷這裡的蒼天古樹來建造他們的戰爭機器。$B$B進入戰歌峽谷，幫助銀翼要塞擊敗入侵的部落勢力吧。', '進入戰歌峽谷並擊敗部落小隊，取得戰歌峽谷榮譽獎章後向銀翼樹林的哨兵艾蒂亞·輕歌回覆。', '', '去梣谷找銀翼樹林的哨兵艾蒂亞·輕歌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8291 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8291, 'zhTW', '擊敗入侵者！', '在這個通道的另一端，你會看到一片戰火紛飛的土地，年輕的$c。部落不斷侵入我們神聖的森林，鋸斷這裡的蒼天古樹來建造他們的戰爭機器。$B$B進入戰歌峽谷，幫助銀翼要塞擊敗入侵的部落勢力吧。', '進入戰歌峽谷並擊敗部落小隊，取得戰歌峽谷榮譽獎章後向銀翼樹林的哨兵艾蒂亞·輕歌回覆。', '', '去梣谷找銀翼樹林的哨兵艾蒂亞·輕歌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8292 AND `locale` = 'zhTW';
