INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8446, 'zhTW', '夢魘的纏繞', '這東西滲出了墮落的力量。$B$B它和來自翡翠夢境的龍類或許有些關係。你必須找到能解讀這東西的人。或許月光林地或是塞納里奧城堡的德魯伊能協助你。', '尋找能解讀夢魘包裹物品中所隱藏信息的人。$B$B或許擁有強大力量的德魯伊可以幫助你。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8447 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8447, 'zhTW', '喚醒傳說', '月神湖的湖水可以融解這東西裡面的夢魘。給我點時間來淨化它吧，$N。', '等待月光林地的守護者雷姆洛斯淨化夢魘包裹的物品。', '喚醒傳奇', '去月光林地找雷姆洛斯神殿的守護者雷姆洛斯。', '', '', '', '', 0);
