INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8458,'zhTW','暫無內容','我可以在擁有適當材料的情況下找到這個惡魔領主。$B$B如果他確實如我推測的一般強大，那我就得先準備一些只有從非常危險的生物身上才能收集到的物品。既然你是為酋長做事的，那麼我想你應該會接受我交付給你的任務吧。$B$B首先，我需要破壞他的反檢測結界。去給我找一塊薩特的頭皮來，不過並不是任何薩特的頭皮都可以的，只有怨怒巡影者的頭皮才能用。$B$B從淒涼之地東北部的古代遺蹟附近開始找起吧。','給淒涼之地的瑪烏林·碎骨帶回一張巡影者的頭皮。','','去淒涼之地找幽靈崗哨的瑪烏林·碎骨。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8459 AND `locale` = 'zhTW';
