INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8460, 'zhTW', '木喉熊怪的盟友', '木喉部族是唯一沒有被墮落力量污染的熊怪部族。然而，許多其他的種族盲目地屠殺熊怪，卻並沒有搞清他們是敵是友。因此，木喉熊怪很少相信別人。$B$B你想要證明自己的立場嗎?去趕走腐化的死木部族，我們以後也許會接受你成為盟友。你可以在我的西邊找到第一批死木部族 – 死木戰士、探路者和園丁。', '格拉茲要你去殺死6個死木戰士、6個死木探路者以及6個死木園丁以證明自己的立場。完成後回到翡翠聖地附近的費伍德森林南方找他。', '', '去費伍德森林找翡翠聖地的格拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8461 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8461, 'zhTW', '北方的死木熊怪', '此地西南方向有一處死木熊怪的營地。我不清楚他們想要幹什麼，但是我希望能在他們開始搗亂之前就結果他們。$B$B死木部族非常邪惡，是惡魔的力量侵蝕了他們的心智。他們的天性並不壞，但是現在一切都無法挽回了。因此，我對被迫與自己的同胞作戰感到非常悲哀。$B$B$N，去結果他們吧，別對我說起戰鬥的具體過程，我不忍心聽到那些。', '納菲恩要你去殺死6個死木守衛、6個死木復仇者和6個死木薩滿。再回到木喉要塞入口附近的費伍德森林北方找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8462 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8462, 'zhTW', '與納菲恩交談', '或許你能處理我們木喉面臨的大威脅。你已在這展現了你的能力……我們族人在木喉要塞的入口外守衛著，就沿著這條路直到北方處。他的名字是納菲恩;雖然他是個兇猛可怕的野獸，但不要怕他。他只會向威脅我們家園的邪惡力量尋求幫助。', '沿著費伍德森林的大路往北走並和一隻叫納菲恩的熊怪交談。他就在木喉要塞的入口守衛著。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8463 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8463, 'zhTW', '不穩定法力水晶', '近來鄙惡者從我們的秘法聖所搜刮了一批不穩定法力水晶。若沒有妥當處置的話，水晶可能會爆炸，也許猛烈到把城門炸出一個大洞來。$B$B現在，$N，我不管敲到不穩定秘法材料是否會蒸發，可是這整件意外會讓我變得很慘。$B$B把剩下被偷的水晶都帶回來給我，它們應該都還在原本的木箱裡。', '帶回6個不穩定法力水晶給獵鷹之翼廣場的艾爾頓·桑布蘭德。', '', '去找永歌森林的艾爾頓·桑布蘭德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8464 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8464, 'zhTW', '冬泉熊怪的活動', '木喉部族傾向於防守，$N。雖然我們允許那些值得信賴的朋友安全地通過，但我們還是盡可能地避開其他熊怪部族。$B$B最近我注意到冬泉部族與我們的敵對情緒有所增長。他們似乎處於極度憤怒的狀態，完全陷入了對一切他們無法理解的事物的恐慌和仇視。$B$B如果你能削減他們的數量，那對我們來說將是莫大的幫助，$N。', '薩爾法要你去殺死8個冬泉薩滿，8個冬泉巢穴守衛和8個冬泉巨熊怪。薩爾法就在冬泉谷的木喉要塞入口外面。', '', '去找凍霜林地的薩爾法。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8465 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8465, 'zhTW', '與薩爾法交談', '腐敗的威脅不只從南方的死木熊怪襲來，還有東邊冬泉谷的冬泉熊怪。如果你想更進一步的幫助我們，去和要塞另一邊的薩爾法交談，就在冬泉谷的入口。沿著左邊的小徑走就能到了。提高警覺 – 如果裡面我的族人認為你有敵意或仇恨，他們就會攻擊你。動作越快越好，避免衝突。殺害木喉 – 即使是為了自衛 – 都只會讓你被疏遠而已。', '通過木喉要塞前往冬泉谷。和薩爾法交談，他就在木喉要塞入口外守衛著。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8466 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8466, 'zhTW', '給格拉茲的羽毛', '', '', '', '去找費伍德森林的格拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8467 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8467, 'zhTW', '給納菲恩的羽毛', '', '進度雖然你已向我證明自己的來意，你還需要繼續努力向我部族懷疑的兄弟們證明你自己。只有這樣，我才能繼續幫助你。$B$B有些死木熊怪戴著特殊的頭巾，可以作為削減他們勢力的證據。帶給我你從任何頭巾上取得的羽毛；你每給我一套5個，就會贏得木喉的信賴。', '', '去找費伍德森林的納菲恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8468 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8468, 'zhTW', '懸賞:『飢餓者』泰利斯', '銀月城正懸賞『飢餓者』泰利斯的頭顱，他是惡名昭彰的鄙惡者頭目。他因為多次對銀月城百姓犯下罪行而被追緝，包括殺死兩名城市守衛。$B$B向士官坎倫領取獎勵。', '帶著泰利斯的頭顱到永歌森林的獵鷹之翼廣場，交給士官坎倫。', '', '去找永歌森林的士官坎倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8469 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8469, 'zhTW', '給薩爾法的珠串', '', '進度你無疑地得到了我的信任，$N，但你仍要努力得到我整個部族的信任。拜託…讓我繼續幫助你。$B$B冬泉谷的人都會配戴靈魂珠子來避開邪惡的靈魂。但這些珠子顯然失去了它們的意義，因為冬泉谷的人就是腐敗的媒介。幫我從冬泉谷熊怪那裡帶來這些靈魂珠子；你每給我一套5個，就會贏得木喉的信賴。', '', '去找費伍德森林的薩爾法。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8470 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8470, 'zhTW', '死木儀式圖騰', '你找到了一個死木熊怪的儀式圖騰。圖騰本身是個無圖形的建造物，但是它散發出一種可觸知的絕望。如果有任何東西可以作為折磨死木熊怪的墮落例子，那麼那個東西就是它了。$B$B木喉要塞裡的一隻熊怪或許會用到這樣物品…當然，前提是你要先獲得他們的信任才能和他們交談。', '帶著死木儀式圖騰進入木喉要塞，看看有沒有熊怪對這物品有用途的。除非你達到中立聲望值或比他們更好，否則木喉不會跟你說話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8471 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8471, 'zhTW', '冬泉儀式圖騰', '你找到了一個冬泉熊怪的儀式圖騰。圖騰本身是個無圖形的建造物，但是它散發出一種可觸知的恐怖與絕望。如果真的有很多冬泉熊怪都會攜帶這種東西，要解釋他們的現況將不是件容易的事。$B$B木喉要塞裡的一隻熊怪或許會用到這樣物品……當然，前提是你要先獲得他們的信任才能和他們交談。', '將冬泉儀式圖騰帶進木喉要塞，看看是否有任何熊怪會使用這個物品。如果你沒有在木喉要塞達到中立或更高的聲望值，他們將不會與你交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8472 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8472, 'zhTW', '嚴重失靈', '祖先塑造的秘法巡邏者是用來保護城市的，現在卻已成為失修的危險狀態。他們無法認出我們就是他們的主人，還會看到就攻擊!$B$B儘管他們製造已有一段時間了，對我們來說，用來啟動控制他們的秘法核心還是既好用又很有價值。我要你收集這些秘法核心給我，這樣我才能善用他們。你可以在西北邊的銀月城廢墟區找到秘法巡邏者。', '從銀月城廢墟閒晃的秘法巡邏者身上收集6個秘法核心帶回永歌森林給獵鷹之翼廣場的博學者賈若尼斯。', '', '去找永歌森林的博學者賈若尼斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8473 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8473, 'zhTW', '陰鬱任務', '現在是我們的艱困時期，$N。為了避免天譴軍團的擴散必須燒光鬼魂之地邊界的樹林，這還真是個難下的決定。$B$B長久以來，樹人就一直是我們的朋友，現在正嘗試沿著烈焰邊境再次養育茁壯森林。$B$B要你做這件事我們也很痛苦，$c，但我們無法說服我們的盟友停止努力。我要你用唯一能制止他們而讓我們生存的方法:武力。', '在烈焰邊境殺掉10個憔悴的森林守衛者，然後到永歌森林跟拉瑞安娜·河風回報。', '', '去找永歌森林的拉瑞安娜·河風。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8474 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8474, 'zhTW', '老白樹墜飾', '這個墜飾上刻有縮寫L.R.。也許這些字母可以指引我們製作墜飾的人。', '去尋找可能製作老白樹墜飾的人，他們可能認得這物品。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8475 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8475, 'zhTW', '死亡之痕', '穿過永歌森林的那塊黑色土壤，長久提醒著世人那一幕，阿薩斯帶領他的天譴軍團進攻我們摯愛的城市。$B$B這個污點比眼中釘還惹人厭，甚至於今日都還有鬼魂之地的天譴軍團來到銀月城。$B$B去吧，$N，幫我的人殺掉死亡之痕那些無腦的不死族。', '殺掉8個瘟疫之骨掠取者，然後到永歌森林的內精靈之門跟遊俠潔拉回報。', '', '去找永歌森林的遊俠潔拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8476 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8476, 'zhTW', '侵犯阿曼尼', '我們人類和獸人的國土並不是非常遼闊廣大。你眼前所見就是我們艾澤拉斯僅存的土地了，$N。$B$B在我們到達外域前，就必須不惜任何代價捍衛我們的小家園。$B$B我們在東南方野蠻的鄰居，阿曼尼食人妖，似乎對於這些土地的所有權抱持著不同的意見。我們無法再容忍他們每日的襲擊行動。去他們駐紮的拉伯瓦薩和托爾瓦薩，給他們點顏色瞧瞧。', '永歌森林，遠行者居所的晨路中尉，要你殺掉5個阿曼尼狂戰士和5個阿曼尼擲斧者。', '', '去找永歌森林的晨路中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8477 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8477, 'zhTW', '製矛者之錘', '阿曼尼和辛多雷有著相互嫌惡和對彼此仇視的一段過去。但那些不會影響我欣賞別人的手工藝品，$N。$B$B我偶然發現了阿曼尼的武器，我承認我對他們的製品品質留下非常深刻的印象。謠傳製矛者歐坦畢有一支極輕且平衡感很棒的魔錘，讓他的手藝十分靈巧又有效率。$B$B如果你幫我帶來這個工具，我就用它幫你製造一把武器。', '去遠行者居所東南邊的托爾瓦薩找製矛者歐坦畢，帶回歐坦畢之錘給永歌森林，遠行者居所的艾瑞塞爾·光鑄。', '', '去找永歌森林的艾瑞塞爾·日鑄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8478 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8478,'zhTW','選擇你的武器','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8479 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8479, 'zhTW', '祖瑪羅什', '靠近點，老兄。不要害怕，凡加許不會傷害你的。$B$B我們暗矛就像你一樣對阿曼尼來說是致死敵人。他們的首領祖瑪羅什是邪惡的食人妖。他給我邪惡毒藥，然後任由我在牢籠內自生自滅。$B$B我不怕死，老兄。我與死亡對看，但我嘲笑她。$B$B我要告訴你，$c，如果祖瑪羅什沒死，我也不能安息。我會握著這毒藥，直到看到你提著他醜陋的頭顱來見我為止，老兄。只有這樣我才能安心的走。', '凡加許，托爾瓦薩的食人妖囚犯，要你把祖瑪羅什酋長之顱帶給他。酋長祖瑪羅什就在拉伯瓦薩，艾蘭達之湖對面。', '', '去找永歌森林的凡加許。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8480 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8480, 'zhTW', '丟失的裝備', '鄙惡者一天比一天放肆，$N。他們已經協調到能對日帆船廠發動攻擊。$B$B更丟臉的是，我們大部分的武器都在他們攻擊的時候搞丟了。幫我把我們的裝備帶回來，這樣我們才能對那些渣滓發動攻擊。', '帶回8個辛多雷軍備給永歌森林的微蘭德絲·白晨。', '', '去找永歌森林的微蘭德絲·白晨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8481 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8481,'zhTW','萬惡之源','$N，感謝你的幫助，我們已經找到了致使冬泉部族墮落的根源——有一個墮落的惡魔正在控制著他們！$B$B把這支火炬拿到冬泉酋長所在的山洞去，然後放在那裡。這樣就可以讓那個惡魔現身。此時你和你的盟友就要把它擊倒！只有使用惡魔身上的精華才能幫助我們進行治癒冬泉部族的工作……最終解除他們對木喉要塞的威脅。','把惡魔召喚火炬放在寒水村的冬泉酋長的洞穴入口處。擊敗召喚出來的惡魔，然後把沙迪維爾斯精華交給木喉要塞的獨眼高恩。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8482 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8482, 'zhTW', '控告文件', '這份文件內含詳細的永歌森林不同戰略建築的地圖。秘法聖所的圖解也記錄了很多細節說明，不過好像有很多註解是你看不懂的語言。$B$B這是由達納蘇斯間諜帶過來的，你可以將它們交給衛兵隊長 - 艾爾頓·桑布蘭德。', '將控告文件交給艾爾頓·桑布蘭德，他在永歌森林的內精靈之門。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8483 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8483, 'zhTW', '矮人間諜', '聽好，$N。這是個需要仔細審慎的情況，就算我們已確認他間諜的身分，我們也不能公然殺他。更不能冒著他蓄意逃跑的風險而擄掠。$B$B我要你去北部聖所殺了勘察員安維瓦德。小心行事，不要讓間諜在城裡的消息走漏了。$B$B把他的頭顱帶回作證。鐵爐堡將會明白他們不可以插手辛多雷的事。', '帶回勘察員安維瓦德之顱給艾爾頓·桑布蘭德。他在永歌森林的獵鷹之翼廣場。', '', '去找永歌森林的艾爾頓·桑布蘭德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8484 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8484,'zhTW','重鑄和平','你的事蹟已經遠遠超過英雄的範疇，$N。如果你代表了你的人民，那麼我們一定會努力和你的人民保持和平。$B$B請你把這個交給住在鋼鐵之山中的那位矮人國王，我想你們把那裡叫做鐵爐堡。過去，他曾經代表聯盟試圖和我們建立聯絡。現在我們需要依賴你來實現木喉部族與聯盟之間的和平。','將木喉和平契約交給鐵爐堡的國王麥格尼·銅鬚。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8485 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8485,'zhTW','重鑄和平','你的行為超越了平凡英雄的故事，$N。若你是你們人民的代表，那麼，你們人民都將成為我們為了維持和平而努力的夥伴。$B$B請將這項提議帶給獸人酋長，他就住在杜洛塔群島，我知道你們都稱這座城為奧格瑪。很久以前，他曾試著代表他的部落和我們接觸，現在正是通知你的時候，你將代表你部落的努力成果進行和平斡旋。','帶回木喉和平契約給奧格瑪的索爾。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8486 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8486, 'zhTW', '秘法不穩定性', '是時候讓凱丹尼斯那個傻瓜派人來這裡了。$B$B我已經警告過增加西部聖所的負載會有的危險了!現在我們的一個能量轉換器被毀了，秘法怨靈全從聖所傾巢而出!$B$B我要你在我們派人去修理前解決那些生物。動作要快!', '牧地看守者維蘭妮雅要你殺死5個法力怨靈和5個法力行者。', '', '去找永歌森林的牧地看守者維蘭妮雅。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8487 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8487, 'zhTW', '被汙染的土壤', '在阿薩斯和他的憎恨軍隊決定開路前往銀月之前，這還算是一個功能齊全的秘法聖所。$B$B現在，對我們來說它也跟死亡之痕一樣重要。土地已被感染，不死族被吸引前去，地脈的能量也遭瓦解。$B$B我想了解的是，$N，目前是否可扭轉腐敗局勢。我要你去收集本區的土壤標本，我要拿來好好研究一下。也許過陣子我們就能回歸正常。', '永歌森林東部聖所的學徒莫維達要你收集8份受污染的泥土樣本。', '', '去找永歌森林的學徒莫維達。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8488 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8488, 'zhTW', '意外的結果', '大事不妙了，$N。我感覺天譴軍團要出現了。準備好要迎戰了。', '保護學徒莫維達免於天譴軍團的伏擊。', '保護學徒米爾維達', '去找永歌森林的學徒莫維達。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8489 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8489, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8490 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8490, 'zhTW', '增強我們的防禦', '古老的符文石曾在永歌森林邊界形成保護屏障。許多符文石都在阿薩斯的攻擊中被摧毀;其他的也被偷了。$B$B在僅存的三個中，只有這一個還保有它的力量。不過東邊的符文石或許還有救。$B$B帶著這個水晶將它的能量注入東符文石。過程只需要一分鐘。不過要小心，它的能量會吸引附近區域的天譴軍團，他們便會開始尋找並摧毀它。阻止他們!', '將灌能水晶放在東符文石上並保護它不受天譴軍團破壞1分鐘。將灌能水晶交給永歌森林的符文守護者德蘭並領取獎勵。', '', '去找永歌森林的符文守護者德蘭。', '符文石能量增強', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8491 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8491, 'zhTW', '收集毛皮', '居住在這區域的泉爪山貓以他們高品質的毛皮出名。我們還見過夜精靈敗類專門前來獵捕它們。$B$B我們和阿曼尼的鬥爭讓戰鬥物資有些吃緊，而我們的騎兵巡邏隊也沒什麼時間獵捕毛皮。如果你願意幫忙收集一些毛皮，我很樂意送你一件手工製的護甲。你可以在北邊的樹林一帶找到泉爪山貓潛行者。', '維嵐·布萊圖克要你帶回6個泉爪之皮給他。他在永歌森林的晴風村。', '', '去找永歌森林的維嵐·布萊圖克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8492 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8492,'zhTW','聯盟需要銅錠！','你好，$c，看來你很合適為我們的備戰計劃做出點貢獻！我們歡迎一切幫助來準備安其拉之戰。$B$B為了這樣一件有意義的事情，我正在收集20塊一組的銅錠。你覺得怎麼樣？','把20塊銅錠交給鐵爐堡軍事區的布羅恩·石眉。','','去找丹莫洛的布羅恩·石眉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8493 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8493,'zhTW','聯盟需要更多銅錠！','又回來了$c？太好了！我們需要更多你從安其拉之戰取得的銅錠。你會幫我們嗎？','帶20個銅錠給丹莫洛飛機場的石眉中尉。','','去找丹莫洛的布羅恩·石眉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8494 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8494,'zhTW','聯盟需要鐵錠！','你好，$g先生:小姐，你不是傳說中雲遊四海，無所不知的那種冒險者嗎？最近的事情你都不知道？聯盟正在準備對安其拉發動戰爭，我們需要大量的鐵錠，越多越好。把它們帶給我，每20塊一組。我們會在功勞薄上為你記上一筆，怎麼樣，$c？','把20塊鐵錠交給丹莫洛飛機場的卡恩斯下士。','','去找丹莫洛的卡恩斯下士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8495 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8495,'zhTW','聯盟需要更多鐵錠！','這麼快就回來了？不要讓我再重新評估對你不好的看法$c，你讓我覺得很感傷。那麼，你知道我們仍然沒有足夠的鐵錠供應武器、護甲、蒸氣坦克和搜尋故障所有需要的東西。你覺得你可以在去祖爾格拉布的路上，或是你們這些孩子現在鬼混的地方帶回另一批20個鐵錠嗎？','帶20個鐵錠給丹莫洛飛機場的卡恩斯下士。','','去找丹莫洛的卡恩斯下士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8496 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8496,'zhTW','戰場上的繃帶','我們的繃帶儲備在最近接連不斷的戰事之後急劇降低。收集大量的急救物資，把它們交給塞納里奧要塞的喚風者梅恩·長角。','把30根厚符文布繃帶、30根厚魔紋繃帶和30根厚絲質繃帶交給喚風者梅恩·長角。你還必須隨身帶著後勤任務簡報 X才能完成這個任務。','','去希利蘇斯找塞納里奧要塞的喚風者梅恩·長角。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8497 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8497,'zhTW','沙漠生存包','隨著新兵增援塞納里奧城堡，如何讓他們在沙漠中生存成了一個問題。缺水是基本的問題，沙漠中無數具毒的生物對沒有經驗的志願兵而言是很大的威脅。收集沙漠生存工具包需要的物資並帶給塞納里奧城堡的卡蘭德拉斯。','帶4個純水之球，4個強效抗毒藥劑和4個沙漠肉丸子帶到希利蘇斯給塞納里奧城堡旅店的卡蘭德拉斯。你還必須將後勤任務簡報 I帶去才能完成這個任務。','','去希利蘇斯找塞納里奧要塞的卡蘭德拉斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8498 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8498,'zhTW','暮光作戰命令','我們的偵察兵報告說，暮光之錘的領袖收到了新的作戰命令。現在這道命令正在被髮送到各處的暮光預言者那裡，並且有重兵護送。攔截這道命令，把它們交給指揮官瑪爾利斯。','拿到暮光作戰命令，把它交給希利蘇斯塞納里奧要塞的指揮官瑪爾利斯。','','去希利蘇斯找塞納里奧要塞的指揮官瑪爾利斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8499 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8499,'zhTW','聯盟需要瑟銀錠！','你能主動關心聯盟需要什麼東西，這真是太好了。除了現在正在收集的各種物資之外，我們還需要大量的瑟銀錠，我將負責這方面的收集。所有的瑟銀都將用於製作各種戰爭必需的物資，特別是用來製造一個軍團的蒸汽坦克，準備進攻希利蘇斯。你能幫幫我嗎，$c？','把20塊瑟銀錠交給鐵爐堡軍事區的達米。','','去找丹莫洛的達米。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8500 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8500,'zhTW','聯盟需要更多瑟銀錠！','你能主動關心聯盟需要什麼東西，這真是太好了。除了現在正在收集的各種物資之外，我們還需要大量的瑟銀錠，我將負責這方面的收集。所有的瑟銀都將用於製作各種戰爭必需的物資，特別是用來製造一個軍團的蒸汽坦克，準備進攻希利蘇斯。你能幫幫我嗎，$c？','把20塊瑟銀錠交給鐵爐堡軍事區的達米。','','去找丹莫洛的達米。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8501 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8501,'zhTW','目標：亞什毒蠍','這一地區猖獗的異種蟲類對我們來說是個巨大的威脅。你被指派負責對亞什蟲巢發動攻擊，主要目標是亞什毒蠍。$B$B在你的任務完成之後，向指揮官瑪爾利斯彙報。','擊殺30只亞什毒蠍，然後向塞納里奧要塞的指揮官瑪爾利斯覆命。你還必須帶著作戰任務簡報 XII才能完成這個任務。','','去希利蘇斯找塞納里奧要塞的指揮官瑪爾利斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8502 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8502,'zhTW','目標：亞什工蠍','這一地區猖獗的異種蟲類對我們來說是個巨大的威脅。你被指派負責對亞什蟲巢發動攻擊，主要目標是亞什工蠍。$B$B在你的任務完成之後，向指揮官瑪爾利斯彙報。','擊殺30只亞什工蠍，然後向塞納里奧要塞的指揮官瑪爾利斯覆命。你還必須帶著作戰任務簡報 III才能完成這個任務。','','去希利蘇斯找塞納里奧要塞的指揮官瑪爾利斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8503 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8503,'zhTW','聯盟需要荊棘藻！','那麼$c，我是否告訴過你荊棘藻的所有用處？有沒有說過？哦，好吧……不管怎麼樣，我們需要很多荊棘藻，我說很多的意思就是非常非常多！你可以幫幫我嗎？我知道這意味著你無法用它來製作許多你需要的東西，但是我們是在為了正義的事業而努力！','把20棵荊棘藻交給鐵爐堡軍事區的列兵德拉里格。','','去找丹莫洛的列兵德拉里格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8504 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8504,'zhTW','聯盟需要更多荊棘藻！','又見面了…有什麼事？啊，對了，$N！來看看我是否需要更多的荊棘藻嗎？嗯，今天真是你的幸運日，因為這個重要問題的答案是肯定的“是”！你可以再收集20個來嗎？','帶20個荊棘藻給丹莫洛飛機場的士兵德拉里格。','','去找丹莫洛的列兵德拉里格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8505 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8505,'zhTW','聯盟需要紫蓮花！','$c，紫蓮花是一種非常有用的植物。我在這裡作為聯盟的官員收集紫蓮花，我要負責監督整個收集過程，並保證在戰時有足夠的紫蓮花儲量可供使用。$B$B我希望你可以到世界各地幫我帶回一些紫蓮花。你可以做到嗎？','把20朵紫蓮花交給鐵爐堡軍事區的艾文·夜歌。','','去找鐵爐堡的艾文·夜歌。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8506 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8506,'zhTW','聯盟需要更多紫蓮花！','$c，紫蓮花是一種非常有用的植物。我在這裡作為聯盟的官員收集紫蓮花，我要負責監督整個收集過程，並保證在戰時有足夠的紫蓮花儲量可供使用。我希望你可以到世界各地幫我帶回一些紫蓮花。你可以做到嗎？','把20朵紫蓮花交給鐵爐堡軍事區的艾文·夜歌。','','去找鐵爐堡的艾文·夜歌。','','','','',0);
