INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8572,'zhTW','精兵的裝備','$N，你在與敵人作戰、提供後勤補給和執行戰略任務之後獲得的徽章並不只是用來炫耀的。$B$B希望你還保留著它們。作為對你的鼓勵，我想要獎勵你一些只有塞納里奧議會最親近的盟友才能獲得的東西。','把7枚作戰徽章、4枚後勤徽章和4枚戰術徽章交給塞納里奧要塞的瓦古斯。你必須在塞納里奧議會中達到尊敬聲望才能完成這個任務。','','去希利蘇斯找塞納里奧要塞的瓦古斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8573 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8573,'zhTW','勇士的裝備','$N，你在與敵人作戰、提供後勤補給和執行戰略任務之後獲得的徽章並不只是用來炫耀的。$B$B希望你還保留著它們。作為對你的鼓勵，我想要獎勵你一些只有塞納里奧議會最親近的盟友才能獲得的東西。','把15枚作戰徽章、20枚後勤徽章、20枚戰術徽章和1枚塞納留斯印記交給塞納里奧要塞的瓦古斯。你必須在塞納里奧議會中達到崇拜聲望才能完成這個任務。','','去希利蘇斯找塞納里奧要塞的瓦古斯。','','','','',0);
