INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8575,'zhTW','艾索雷葛斯的魔法賬本','<你無法理解這上面的字。你甚至不知道這些文字是什麼語言！>','把魔法賬本交給塔納利斯的納瑞安。','','','','','','',0);
