INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8577,'zhTW','斯圖沃爾，前任死黨','如果我要翻譯東西的話，就得戴上我的占卜眼鏡。不幸的，很久以前，我的眼鏡就被我的前任死黨給偷走了，他就是斯圖沃爾。他把我打翻在地，然後拿走了眼鏡，把我留在了這裡。$B$B在我忠實的水晶球的幫助下，我現在找到他了！他要麼就在銀松森林的格雷邁恩之牆，要麼就在遍地傳送門的外域，那裡現在到處都是燃燒軍團的傢伙。你要追蹤到他，然後把我的眼鏡拿回來，$N！','納瑞安要你找到他的前任死黨斯圖沃爾，從他那裡拿回從納瑞安那裡偷走的占卜眼鏡。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8578 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8578,'zhTW','占卜眼鏡？沒問題！','<你聽到箱子裡面傳來一個聲音。>$B$B你只需要他的占卜眼鏡？很好！這不是問題……給我一分鐘……嘿！該死……在哪裡！$B$B好吧，我這裡有一些壞訊息，還有一些更壞的訊息。壞訊息是我把眼鏡給弄丟了。更壞的訊息是，我是上個星期在熔火之心裡晃悠的時候把它給弄丟的。是的，熔火之心……我想這不是我能搞定的了！再見！','找到納瑞安的占卜眼鏡。','','去找塔納利斯的納瑞安。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8579 AND `locale` = 'zhTW';
