INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8580,'zhTW','部落需要火焰花！','嘿，$c。就是你！部落需要非常大量的火焰花來支援安其拉之戰。也許他們會把火焰花用在一些爆炸物中，也許還會把它們交給聯盟來作為蒸汽坦克的燃料？誰知道？但這不是關鍵！這不關比雷凱基的事情！$B$B比雷凱基只知道……只知道你會幫助他收集很多火焰花，對不對？','把20份火焰花交給奧格瑪精神谷的蝙蝠騎士比雷凱基。','','去找奧格瑪精神谷的蝙蝠騎士比雷凱基。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8581 AND `locale` = 'zhTW';
