INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8582,'zhTW','部落需要紫蓮花！','紫蓮花是很多藥水、藥劑和精油的重要材料，它對於我們準備發動的安其拉之戰很重要。我們正在為這場戰爭準備許多藥劑，而且我還希望能發掘出更多紫蓮花的用途。但前提是，我們需要大量的這種花朵。$B$B這就是你來這裡的目的。去收集儘可能多的紫蓮花。你還擅長別的什麼事情嗎？','把20份紫蓮花交給交給奧格瑪精神谷的藥劑師耶澤爾。','','去找奧格瑪精神谷的藥劑師耶澤爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8583 AND `locale` = 'zhTW';
