INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8584,'zhTW','少管閒事','如果說我有一些原則是你應該瞭解的，那就是：永遠不要管我的閒事！我所做的事情都是你無法理解的。比如說：你知道精神電能整流器是什麼嗎？顯然你不知道！這就是為什麼我來負責我們的專案規劃，而你負責滿世界跑腿。$B$B我之前說過，如果你想繼續下去的話，那麼我們需要一隻500磅重的雞。$B$B到加基森去跟迪爾格·奎克里弗談談——他知道如何讓你找到合適的品種。','塔納利斯的納瑞安讓你和加基森的迪爾格·奎克里弗談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8585 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8585,'zhTW','恐怖之島！','傳說菲拉斯恐怖之島的那群名叫奇美洛克的奇美拉族群是最鮮美多汁的食物！現在它們之中出現了一個首領，它的肉在經過巧妙的烹調之後可以變成一盤極品大餐！$B$B去恐怖之島殺掉拉克麥拉，然後把它的肉帶回來。這就可以滿足那個侏儒了，而我則需要你帶一些奇美洛克的腰肋肉給我。$B$B我會給你那500磅的肉雞和一些別的什麼東西作為交換。','加基森的迪爾格·奎克里弗要你去菲拉斯的恐怖之島擊殺拉克麥拉，獲得拉克麥拉的肉，並從島上收集20份奇美洛克的腰肋肉。','','去找塔納利斯的迪爾格·奎克里弗。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8586 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8586,'zhTW','迪爾格的超美味奇美拉肉片','我的食譜完成了！我還需要一些火箭燃料和石中鹽，只要把這些調料和你帶給我的肉混合起來就可以了。$B$B如果你帶來了我要的東西，納瑞安想要的那隻雞就可以完成了。','加基森的迪爾格·奎克里弗要你給他帶去20份地精火箭燃油和20份石中鹽。','','去找塔納利斯的迪爾格·奎克里弗。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8587 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8587,'zhTW','向納瑞安回覆','我是一個不會食言的地精，孩子。這是你要的500磅的小雞。$B$B為什麼那侏儒想要一隻500磅的小雞，那我就不知道了……$B$B<迪爾格喃喃自語著。>$B$B也許那傢伙想要睡在裡面……骯髒的侏儒……','把500磅的小雞交給塔納利斯的納瑞安。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8588 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8588,'zhTW','部落需要重皮！','我們正在準備進行一場戰爭，所以我們最好首先把所有的物資準備妥當，你認為不該這樣做嗎，朋友？我們所需要的一類重要物資就是重皮。我們可以把它用在各個方面，強化護甲和製作防水布都用得到它。$B$B我們需要大量的重皮。這就是你的工作，$c。磨快你的剝皮刀，給我帶回大量的重皮吧。做完這件事情，我們再繼續談談。','把10塊重皮交給奧格瑪精神谷的剝皮師亞曼尼。','','去找奧格瑪的剝皮師亞曼尼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8589 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8589,'zhTW','部落需要更多重皮！','','','','去找奧格瑪的剝皮師亞曼尼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8590 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8590,'zhTW','部落需要厚皮！','我很高興你決定和我談談這個，$c。部落方面已經著手為即將開始的安其拉之戰做準備了，你我都要做好自己該做的事情。$B$B我被指派來收集大量的厚皮，我需要你幫忙去收集這些東西。這項工作是你的榮耀，也是表示你對部落的忠誠的好機會。你願意幫忙嗎？','把10塊厚皮交給奧格瑪精神谷的烏瑪拉中士。','','去找奧格瑪的烏瑪拉中士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8591 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8591,'zhTW','部落需要更多厚皮！','','','','去找奧格瑪的烏瑪拉中士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8592 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8592,'zhTW','神諭者的皇冠','雙子皇帝……他們正向我輕聲密語，這折磨著我的神志。他們嘲笑我，他們知道我無法進入神殿的深處去拯救我的兄弟亞雷戈斯。$B$B我可以看見他們猙獰的臉龐，他們頭上戴著具有無窮力量的皇冠。但是我必須要報仇……我會把這種代表其拉蟲人力量的飾品轉化成對我們有利的東西。$B$B把我需要的材料交給我，$N。我會為你製作一頂具有超凡力量的頭盔。','把維克尼拉斯的頭飾、2個先知塑像、5個銀質甲蟲和5個白骨甲蟲交給安其拉的安多葛斯。你必須首先在諾茲多姆的子嗣中達到友善聲望才可以完成這個任務。','','去找安其拉的安多葛斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8593 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8593,'zhTW','神諭者的長褲','你想要向我們證明你的價值嗎，凡人？很好，也許我們可以互相幫助。$B$B在傳說中，古老的沙蟲奧羅是一個非常強大的存在。據說是上古把它創造出來的原因是為了嘲笑生命的軟弱。$B$B它的皮膚非常特殊……異常結實，甚至是無法擊破的，而它本身的移動速度卻不會因此而受到任何妨礙，它和那些小型生物一樣動作靈敏。$B$B把它的皮膚樣品和其它一些原材料都交給我，我會給你製作一條具有強大力量的護腿。','把巨型沙蟲的皮、2個重生塑像、5個黃金甲蟲和5個陶土甲蟲交給安其拉的坎多斯特拉茲。你必須首先在諾茲多姆的子嗣中達到友善聲望才可以完成這個任務。','','去找安其拉的坎多斯特拉茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8594 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8594,'zhTW','神諭者的襯肩','據說凡人所穿著的絢麗護肩是他們用來模仿龍翼的。$B$B把其拉蟲人的最高領袖所佩戴的腕輪交給我，我會用它來製作一副比奈法利安的雙翼還要可怕的護肩！','把其拉命令腕輪、2個重生塑像、5個銀質甲蟲和5個象牙甲蟲交給安其拉的安多葛斯。你必須首先在諾茲多姆的子嗣中達到中立聲望才可以完成這個任務。','','去找安其拉的安多葛斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8595 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8595,'zhTW','凡人中的勇士','','','','去找坎多斯特拉茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8596 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8596,'zhTW','神諭者的裹足','其拉蟲人的魔法古老而又強大，它們最強大的武器甚至可以與龍抗衡。$B$B把其拉統御腕輪和其它輔助材料交給我，我將為你製作一雙威力無比的靴子。$B$B你會在與敵人作戰的時候發現它所蘊含的力量。','把其拉命令腕輪、2個死亡塑像、5個青銅甲蟲和5個黃金甲蟲交給安其拉的坎多斯特拉茲。你必須首先在諾茲多姆的子嗣中達到中立聲望才可以完成這個任務。','','去找安其拉的坎多斯特拉茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8597 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8597,'zhTW','龍語傻瓜教程','我就知道總有一天這本書會有用的！幸運的是，我已經學聰明瞭！我把它藏了起來。$B$B不要擔心，它被放在誰都找不到的地方！嗯，我需要搭乘一架直升飛機才可以到那裡去。不幸的是，在我回來的路上，飛機墜毀了。就是因為這次事故，我才獲得了超級侏儒精神力量！$B$B到天涯海灘那邊去尋找墜毀的直升飛機，然後往南邊遊！你到了那裡就會看到的！','尋找納瑞安埋在南海的某座小島上的書。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8598 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8598,'zhTW','敲詐','<便箋上用不同的字型拼湊出一段話。>$B$B我們已經拿到了你寶貴的書，侏儒。如果你想再見到它的話，那麼你就必須按照我們說的來做。$B$B<以下是長達3頁的具體指示說明。>$B$B把錢帶來，只需你一個人來！','把勒索信交給塔納利斯的納瑞安。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8599 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8599,'zhTW','唱給納瑞安的情歌','並不是總是有人來拜訪我。上一次有人來拜訪，還是那次我把那個可愛的侏儒從墜毀的機器中救出來的時候。$B$B<米莉蒂絲若有所思。>$B$B你認識他嗎？他叫納瑞安……哦，如果有人可以替我給他傳個話，那就太好了。我一定要告訴他我的感覺！我知道這就是愛！就是這樣的！$B$B你可以幫我傳話給納瑞安嗎？我永遠都不會忘記你的！','把米莉蒂絲的情書交給塔納利斯的納瑞安。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8600 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8600,'zhTW','部落需要硬甲皮！','我發現你的刀子的手感比鋒利的程度更重要。只要使用得當，最鈍的刀子也可以切開東西。但是我們不會碰到這樣的問題，因為我們把武器保養得都很好。$B$B好吧，不多說了。我現在有個任務給你，$c。為了部落，你現在要為安其拉之戰做出你的貢獻，我需要你幫忙收集大量的硬甲皮。你願意嗎？','把10塊硬甲皮交給奧格瑪精神谷的塞拉圖斯。','','去找奧格瑪的塞拉圖斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8601 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8601,'zhTW','部落需要更多硬甲皮！','','','','去找奧格瑪的塞拉圖斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8602 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8602,'zhTW','風暴召喚者的肩甲','據說凡人所穿著的絢麗護肩是他們用來模仿龍翼的。$B$B把其拉蟲人的最高領袖所佩戴的腕輪交給我，我會用它來製作一副比奈法利安的雙翼還要可怕的護肩！','把其拉統御腕輪、2個生命塑像、5個黃金甲蟲和5個水晶甲蟲交給安其拉的安多葛斯。你必須首先在諾茲多姆的子嗣中達到中立聲望才可以完成這個任務。','','去找安其拉的安多葛斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8603 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8603,'zhTW','神諭者的外套','最令人恐怖的上古之神正在從安其拉的休眠之中慢慢醒來。艾澤拉斯世界不久之後即將面對這股恐怖的力量，時間對於如此強大的存在來說毫無意義。$B$B當星辰的位置合適的時候，他將讓恐怖的力量席捲所有的一切。你必須在此之前找到他，消滅他。$B$B完成這個任務，把他的外殼交給我。我會獎勵你一件凡人從未見到過的護甲……一件只有弒神者才有資格獲得的護甲！','把上古之神的外鞘、2個死亡塑像、5個岩石甲蟲和5個水晶甲蟲交給安其拉的溫瑟拉。你必須在諾茲多姆的子嗣中達到尊敬聲望才能完成這個任務。','','去找安其拉的溫瑟拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8604 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8604,'zhTW','部落需要絨線繃帶！','你好，$c。為了準備安其拉之戰，我在這裡幫助部落協調收集絨線繃帶。在戰場上，士兵們不能指望總有醫師跟著他們，所以我們要為他們準備急救包。$B$B如果你有時間的話，我需要很多絨線繃帶，請把繃帶交給我，我會獎勵你的。','把20卷絨線繃帶交給奧格瑪精神谷的醫師朗蘭納。','','去找奧格瑪的醫師朗蘭納。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8605 AND `locale` = 'zhTW';
