INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8606,'zhTW','螳螂捕蟬！','我終於想到了！我們應該這樣做。我要給袋子裡裝滿石頭，然後你來負責送貨。我知道他們說應該由我親自送去之類的。$B$B<納瑞安上下打量著你。>$B$B嗯，你也可以完成這個任務。戴上這條頭巾，穿上這件長袍，拿著這袋石頭，去冬泉谷的交貨地點吧。$B$B我在這個工具包中幫你準備了所有必需的東西。當他們冒出來拿貨的時候，就幹掉他們！讓他們知道惹毛了納瑞安的下場！','塔納利斯的納瑞安要你去冬泉谷，把一袋金子放在綁匪的勒索信上所寫的位置。他還要求你教訓一下那些傢伙！','','去找塔納利斯的納瑞安。','是誰控制著人造猿二號？','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8607 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8607,'zhTW','部落需要魔紋布繃帶！','我相信你來找我是想要幫助我收集東西？很好！不管怎麼樣，我接受所有的幫助，並且我需要你幫忙去收集厚魔紋繃帶。最好是新做的，但不是必須。把它們交給我，$c，我會給你適當的獎勵的。','把20卷魔紋繃帶交給奧格瑪精神谷的卡隆。','','去找奧格瑪的卡隆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8608 AND `locale` = 'zhTW';
