INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8609,'zhTW','部落需要符文布繃帶！','毫無疑問，部落和聯盟在準備安其拉之戰的過程中會發生摩擦。奇怪的是，這場戰爭居然不是在部落和聯盟之間進行的，雙方的敵人都是異種蟲類和控制這些蟲子的幕後黑手。部落和聯盟都在積極收集資源來發動這場戰爭。$B$B我負責收集符文布繃帶，但是如果我得不到幫助的話就不會成功。你能幫助我嗎，$c？','把20卷符文布繃帶交給奧格瑪精神谷的尼根·陶蹄。','','去找奧格瑪的尼根·陶蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8610 AND `locale` = 'zhTW';
