INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8611,'zhTW','部落需要瘦狼排！','我站在這裡可不是為了把自己皮膚曬成健康色的，$c。我們必須為戰爭做好準備。如果我們想要把那些安其拉的蟲子都碾碎的話，那麼我們現在就得好好準備一下了，這當然包括食物的儲備工作！$B$B我們需要收集足夠的狼肉來為戰爭做好準備。我要待在這裡進行整理工作，所以我要委託你去殺幾條狼，然後把它們的肉燒成瘦狼排給我。你知道該怎麼做了嗎？','把20塊瘦狼排交給奧格瑪精神谷的血衛士拉爾塔。','','去找杜隆塔爾的血衛士拉爾塔。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8612 AND `locale` = 'zhTW';
