INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8613,'zhTW','部落需要斑點黃尾魚！','真是釣魚的好天氣，你不這麼認為嗎，$g小夥子:姑娘？這天氣真好，我正好需要很多的魚。部落讓我負責收集大量的斑點黃尾魚。這是為了即將開始的安其拉之戰做準備。我告訴他們我會盡力而為的，所以我現在需要一些幫助。你可以幫幫我嗎，$c？','把20條斑點黃尾魚交給奧格瑪精神谷的漁夫林度。','','去杜隆塔爾找奧格瑪的漁夫林度。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8614 AND `locale` = 'zhTW';
