INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8617,'zhTW','部落需要熔火之石！','是時候讓你為安其拉之戰做出貢獻了，$c。你不能繼續這樣遊手好閒下去。現在是你為我和部落效勞的時候，而且我可不想酋長那樣寬大仁慈。$B$B你必須組織起強大的力量，最好是整個公會的力量，深入熔火之心。在那裡，你可以找到很多被稱為熔火之石的東西。把它們都交給我。','把50塊熔火之石交給奧格瑪精神谷的佐格將軍。','','去找丹莫洛的佐格將軍。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8618 AND `locale` = 'zhTW';
