INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8640,'zhTW','死亡執行者的護腿','你想要向我們證明你的價值嗎，凡人？很好，也許我們可以互相幫助。$B$B在傳說中，古老的沙蟲奧羅是一個非常強大的存在。據說是上古把它創造出來的原因是為了嘲笑生命的軟弱。$B$B它的皮膚非常特殊……異常結實，甚至是無法擊破的，而它本身的移動速度卻不會因此而受到任何妨礙，它和那些小型生物一樣動作靈敏。$B$B把它的皮膚樣品和其它一些原材料都交給我，我會給你製作一條具有強大力量的護腿。','把奧羅的外皮、2個夜晚塑像、5個岩石甲蟲和5個水晶甲蟲交給安其拉的坎多斯特拉茲。你必須首先在諾茲多姆的子嗣中達到友善聲望才可以完成這個任務。','','去找安其拉的坎多斯特拉茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8641 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8641,'zhTW','死亡執行者的護肩','據說凡人所穿著的絢麗護肩是他們用來模仿龍翼的。$B$B把其拉蟲人的最高領袖所佩戴的腕輪交給我，我會用它來製作一副比奈法利安的雙翼還要可怕的護肩！','把其拉命令腕輪、2個太陽塑像、5個銀質甲蟲和5個陶土甲蟲交給安其拉的安多葛斯。你必須首先在諾茲多姆的子嗣中達到中立聲望才可以完成這個任務。','','去找安其拉的安多葛斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8642 AND `locale` = 'zhTW';
