INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8655,'zhTW','復仇者的脛甲','其拉蟲人的魔法古老而又強大，它們最強大的武器甚至可以與龍抗衡。$B$B把其拉統御腕輪和其它輔助材料交給我，我將為你製作一雙威力無比的靴子。$B$B你會在與敵人作戰的時候發現它所蘊含的力量。','把其拉統御腕輪、2個先知塑像、5個青銅甲蟲和5個陶土甲蟲交給安其拉的坎多斯特拉茲。你必須首先在諾茲多姆的子嗣中達到中立聲望才可以完成這個任務。','','去找安其拉的坎多斯特拉茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8656 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8656,'zhTW','攻擊者的護甲','最令人恐怖的上古之神正在從安其拉的休眠之中慢慢醒來。艾澤拉斯世界不久之後即將面對這股恐怖的力量，時間對於如此強大的存在來說毫無意義。$B$B當星辰的位置合適的時候，他將讓恐怖的力量席捲所有的一切。你必須在此之前找到他，消滅他。$B$B完成這個任務，把他的外殼交給我。我會獎勵你一件凡人從未見到過的護甲……一件只有弒神者才有資格獲得的護甲！','把上古之神的外鞘、2個生命塑像、5個黃金甲蟲和5個陶土甲蟲交給安其拉的溫瑟拉。','','去找安其拉的溫瑟拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8657 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8657,'zhTW','攻擊者的王冠','雙子皇帝……他們正向我輕聲密語，這折磨著我的神志。他們嘲笑我，他們知道我無法進入神殿的深處去拯救我的兄弟亞雷戈斯。$B$B我可以看見他們猙獰的臉龐，他們頭上戴著具有無窮力量的皇冠。但是我必須要報仇……我會把這種代表其拉蟲人力量的飾品轉化成對我們有利的東西。$B$B把我需要的材料交給我，$N。我會為你製作一頂具有超凡力量的頭盔。','把維克尼拉斯的頭飾、2個征戰塑像、5個青銅甲蟲和5個象牙甲蟲交給安其拉的安多葛斯。你必須首先在諾茲多姆的子嗣中達到友善聲望才可以完成這個任務。','','去找安其拉的安多葛斯。','','','','',0);
