INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8667,'zhTW','起源頭盔','雙子皇帝……他們正向我輕聲密語，這折磨著我的神志。他們嘲笑我，他們知道我無法進入神殿的深處去拯救我的兄弟亞雷戈斯。$B$B我可以看見他們猙獰的臉龐，他們頭上戴著具有無窮力量的皇冠。但是我必須要報仇……我會把這種代表其拉蟲人力量的飾品轉化成對我們有利的東西。$B$B把我需要的材料交給我，$N。我會為你製作一頂具有超凡力量的頭盔。','把維克洛爾的王冠、2個生命塑像、5個黃金甲蟲和5個陶土甲蟲交給安其拉的安多葛斯。你必須首先在諾茲多姆的子嗣中達到友善聲望才可以完成這個任務。','','去找安其拉的安多葛斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8668 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8668,'zhTW','起源長褲','你想要向我們證明你的價值嗎，凡人？很好，也許我們可以互相幫助。$B$B在傳說中，古老的沙蟲奧羅是一個非常強大的存在。據說是上古把它創造出來的原因是為了嘲笑生命的軟弱。$B$B它的皮膚非常特殊……異常結實，甚至是無法擊破的，而它本身的移動速度卻不會因此而受到任何妨礙，它和那些小型生物一樣動作靈敏。$B$B把它的皮膚樣品和其它一些原材料都交給我，我會給你製作一條具有強大力量的護腿。','把巨型沙蟲的皮、2個戰爭塑像、5個岩石甲蟲和5個水晶甲蟲交給安其拉的坎多斯特拉茲。你必須首先在諾茲多姆的子嗣中達到友善聲望才可以完成這個任務。','','去找安其拉的坎多斯特拉茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8669 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8669,'zhTW','起源護肩','據說凡人所穿著的絢麗護肩是他們用來模仿龍翼的。$B$B把其拉蟲人的最高領袖所佩戴的腕輪交給我，我會用它來製作一副比奈法利安的雙翼還要可怕的護肩！','把其拉統御腕輪、2個征戰塑像、5個黃金甲蟲和5個白骨甲蟲交給安其拉的坎多斯特拉茲。你必須首先在諾茲多姆的子嗣中達到中立聲望才可以完成這個任務。','','去找安其拉的安多葛斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8670 AND `locale` = 'zhTW';
