INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8728,'zhTW','好訊息和壞訊息','好吧，這比預期的時間稍微長了一些。現在讓我看看賬本上都寫了些什麼。$B$B<納瑞安默默地讀著賬本，有的時候還喃喃自語。>$B$B好訊息是，我可以99%地肯定，我能為你製作一個奧金魚漂。當然，還有一個壞訊息。$B$B壞訊息就是，我需要大量的奧金，源質礦石，還有一些珍貴的寶石。$B$B把它們帶來，然後我就可以開工了。','塔納利斯的納瑞安要你給他帶去20塊奧金錠、10塊源質礦石、10顆艾澤拉斯鑽石，以及10顆藍寶石。','','去找塔納利斯的納瑞安。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8729 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8729,'zhTW','奈普圖洛斯的憤怒','我和你說過壞訊息了嗎?它的名字叫巨齒鯊:100尺長，死亡和毀滅的化身。我想我忘記和你說這個了。$B$B根據我的超級精準千里眼提供的訊息，你會在艾薩拉的海岸找到最合適使用這個浮標的地方，就在風暴海灣。$B$B你要尋找一個大漩渦，就是附近都是沉船的地方。$B$B另外，我希望你帶上你的朋友。$B$B如果你成功的話，那麼把權杖碎片帶給安納克羅斯。','在艾薩拉風暴海灣一帶的大漩渦使用奧金浮標。','','去塔納利斯找時光之穴的阿納克洛斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8730 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8730,'zhTW','奈法里奧斯的腐蝕','勇士，是你嗎？我受命保管這個碎片已經一千年了，在我最黑暗的時候，應該有人站出來替我把它拿回來……但是一切都是任重道遠的。$B$B<瓦拉斯塔茲輕輕地咳嗽著。>$B$B耐……耐法里奧斯現在掌握著scepter shard。$B$B時間是最關鍵的。耐法里奧斯將要摧毀這個scepter。你必須趕快！','幹掉奈法利安並拿到Red Scepter Shard。把Red Scepter Shard帶給塔納利斯時光之穴門口的阿納克洛斯。你必須在一個半小時之內完成這個任務。','','去塔納利斯找時光之穴的阿納克洛斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8731 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8731,'zhTW','戰地任務','你好，$N。在我為你佈置更重要的任務之前，你需要首先完成一些常規的戰地任務。$B$B你可以在佐拉蟲穴外找到克魯格·碎顱的部隊。$B$B向他報到，然後拿著你完成任務的證明檔案回到我這裡來。那時我將會給你下達進一步的指令。$B$B哦，別忘了離鐵爐堡軍團遠一些。由於聯盟和部落的志願兵之間摩擦不斷，我們被迫把他們分開來。','向雷戈蟲巢外的奧格瑪軍團報到，從克魯格·碎顱那裡拿到簽過字的戰地任務檔案，把它交給希利蘇斯塞納里奧要塞的喚風者卡爾東。$B$B注意：給奧格瑪軍團的士兵治療或者施放增益法術會開啟你的PvP標誌。','','去希利蘇斯找塞納里奧要塞的喚風者卡爾東。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8732 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8732,'zhTW','戰地任務檔案','','','','去找希利蘇斯塞納里奧議會的喚風者梅恩·長角','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8733 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8733,'zhTW','伊蘭尼庫斯，夢境之暴君','這將是一段救贖之旅，英雄。如果今天我要死去，那麼我也要為了一個正義而偉大的事業而犧牲。你必須找到綠色節杖碎片，你必須淨化被上古之神控制的伊蘭尼庫斯。$B$B到達納蘇斯去，在城牆外，你可以找到我的人。這個人將會為我們進行協調，並在不讓鹿盔發現的情況下將我們的計劃通知給泰蘭妲。$B$B<瑪法里奧嘆了口氣。>$B$B一千年的守護終究墮落了……','到達納蘇斯的城牆外去找到瑪法里奧的親信。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8734 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8734,'zhTW','泰蘭妲和雷姆洛斯','我們會通知泰蘭妲的，凡人。瑪法里奧·怒風已經讓我做好應付這次事件的準備了。$B$B現在你必須去月光林地，和雷姆洛斯談一談。他會進一步指引你召喚伊蘭尼庫斯。$B$B祝你好運。','到月光林地去，和守護者雷姆洛斯談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8735 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8735,'zhTW','腐蝕夢魘','你必須到艾澤拉斯世界的四個翡翠夢境入口去。在每個入口處，你都可以收集到腐蝕夢魘的碎片。住在這些地區的龍類生物身上會攜帶著這樣的碎片。當你收集到全部四塊碎片後就回到我這裡來。','到艾澤拉斯世界的四個翡翠夢境入口去，分別收集該處的腐蝕夢魘的碎片。當你任務完成之後，就回到月光林地的守護者雷姆洛斯那裡。','','去月光林地找雷姆洛斯神殿的守護者雷姆洛斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8736 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8736,'zhTW','噩夢顯現','我們必須儘量控制伊蘭尼庫斯，我們要讓他獲得救贖，而不是摧毀他。$B$B泰蘭妲已經在趕來幫助我們的路上了。我們必須守住巨龍的攻擊，保護永夜港免遭傷害。$B$B做好準備!你和你的盟友是我們唯一的希望。','保護永夜港免受伊蘭尼庫斯的傷害。不要讓守護者雷姆洛斯死亡。不要殺掉伊蘭尼庫斯。保護好你們自己。等待泰蘭妲。','伊蘭尼庫斯的救贖','去月光林地找月神湖的守護者雷姆洛斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8737 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8737,'zhTW','灰燼公爵','暮光之錘和深淵議會之間的聯絡看來比我們想象的還要意義重大。$B$B根據可靠情報，那個被稱作灰燼公爵的元素領主將要策動暮光之錘對塞納里奧要塞實施一次大規模的攻擊。設法把他引誘出來，然後擊殺他。','設法召喚並擊殺灰燼公爵，然後向塞納里奧要塞的喚風者梅恩·長角覆命。','','去希利蘇斯找塞納里奧要塞的鮑爾·蠻鬃。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8738 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8738,'zhTW','雷戈蟲巢偵查報告','我們派出了最好的斥候深入異種蟲類的巢穴收集情報。蘭迪奧這幾天來一直在監視佐拉蟲巢，去找到他，拿回他的書面報告。我們需要這些情報來制定戰術，要儘快，$n。','在雷戈蟲巢內找到塞納里奧斥候蘭迪奧，然後把雷戈蟲巢偵查報告交給塞納里奧要塞的喚風者梅恩·長角。你還必須隨身帶著戰術任務簡報 VII才能完成這個任務。','','去希利蘇斯找塞納里奧要塞的喚風者梅恩·長角。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8739 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8739,'zhTW','灰燼公爵','暮光之錘和深淵議會之間的聯絡看來比我們想象的還要意義重大。$B$B根據可靠情報，那個被稱作灰燼公爵的元素領主將要策動暮光之錘對塞納里奧要塞實施一次大規模的攻擊。設法把他引誘出來，然後擊殺他。','設法召喚並擊殺灰燼公爵，然後向塞納里奧要塞的喚風者梅恩·長角覆命。','','去希利蘇斯找塞納里奧要塞的喚風者梅恩·長角。','','','','',0);
