INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8740,'zhTW','聖殿騎士','許多幕光之錘的騎兵教徒經常在我們塞納里奧要塞守衛範圍之外的區域遊蕩，並伺機襲擊我們巡邏和商旅小隊。$B$B找到並擊敗twilight marauders和他們的領袖，一個叫做Morna的恐怖戰士。當任務完成之後向喚風者梅恩·長角報告。','幹掉Twilight Marauder Morna和5個Twilight Marauders。當任務完成之後向喚風者梅恩·長角報告。','','去希利蘇斯找塞納里奧要塞的喚風者梅恩·長角。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8741 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8741,'zhTW','冠軍的回報','守護者在等待著你，$N。把綠色節杖碎片交給時光之穴前的阿納克洛斯吧。','把綠色節杖碎片交給塔納利斯時光之穴的阿納克洛斯。','','','','','','',0);
