INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8770,'zhTW','目標：亞什工蠍','我們需要援軍進攻亞什蟲巢。你的主要目標是那些亞什工蠍。當你的任務完成之後向指揮官瑪爾利斯報告。','擊殺25只亞什工蠍和40只亞什雄蠍。','','去希利蘇斯找塞納里奧要塞的指揮官瑪爾利斯。','','','','',0);
