INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8778,'zhTW','鐵爐堡軍團需要爆炸品！','戰場的繃帶儲存量在最近戰爭傷亡之後急劇降低。把大量的急救物資帶給塞納里奧要塞的喚風者梅恩·長角。','把20個重符文繃帶，20個厚絲質繃帶和20個厚絨線繃帶帶給喚風者梅恩·長角。','','去希利蘇斯找佐拉蟲巢附近的奧術師諾斯賓。','','','','',0);
