INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8779,'zhTW','研究材料','戰場的繃帶儲存量在最近戰爭傷亡之後急劇降低。把大量的急救物資帶給塞納里奧要塞的喚風者梅恩·長角。','把20個重符文繃帶，20個厚絲質繃帶和20個厚絨線繃帶帶給喚風者梅恩·長角。','','去希利蘇斯找塞納里奧要塞的地質學家拉克斯班。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8780 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8780,'zhTW','戰場上的護甲片','我們的繃帶儲備在最近接連不斷的戰事之後急劇降低。收集大量的急救物資，把它們交給塞納里奧要塞的喚風者梅恩·長角。','把20根重符文繃帶、20根厚絲質繃帶和20根厚絨線繃帶交給喚風者梅恩·長角。','','去希利蘇斯的佐拉蟲巢附近找珍妮拉·鋼錘。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8781 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8781,'zhTW','戰場上的武器','我們的繃帶儲備在最近接連不斷的戰事之後急劇降低。收集大量的急救物資，把它們交給塞納里奧要塞的喚風者梅恩·長角。','把20根重符文繃帶、20根厚絲質繃帶和20根厚絨線繃帶交給喚風者梅恩·長角。','','去希利蘇斯的佐拉蟲巢附近找珍妮拉·鋼錘。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8782 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8782,'zhTW','制服供應','最近不斷湧來的志願者導致我們制服緊缺。去搜集一些制服的材料，然後把它們交給喚風者梅恩·長角。','把1塊月布、2卷符文布卷和1份鐵網蛛絲交給塞納里奧要塞的喚風者梅恩·長角。你還必須隨身帶著後勤任務簡報 VIII才能完成這個任務。','','去希利蘇斯找塞納里奧要塞的喚風者梅恩·長角。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8783 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8783,'zhTW','特殊的材料','瓦古斯是塞納里奧要塞的鐵匠，他需要一些附魔材料來為我們的部隊製作強力的武器。去找到這些材料，把它們直接交給瓦古斯，這樣塞納里奧議會的軍隊就有了作戰裝備的保障。','把2塊魔化瑟銀錠和2塊魔化皮交給希利蘇斯塞納里奧要塞的瓦古斯。你還必須隨身帶著後勤任務簡報 IX才能完成這個任務。','','去希利蘇斯找塞納里奧要塞的瓦古斯。','','','','',0);
