INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8784,'zhTW','其拉的秘密','你找到了一件上古其拉神器！也許神殿入口附近的龍用得到這件東西。','把上古其拉神器交給隱藏在神殿入口處的龍類。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8785 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8785,'zhTW','奧格瑪軍團需要魔精！','奧格瑪軍團要求我們提供一些不尋常的物資。他們在希利蘇斯的表現很不錯，因此我們最好儘快滿足他們的需求。收集必需的材料，把它們交給那個名叫沙艾的巨魔。','把6份強力魔精、6份大瓶魔精和8份獻祭之油交給希利蘇斯地區的雷戈蟲巢附近的暗影祭司沙艾。你還必須隨身帶著後勤任務簡報 IV才能完成這個任務。','','去希利蘇斯找雷戈蟲巢的暗影祭司沙艾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8786 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8786,'zhTW','戰場上的武器','我們的繃帶儲備在最近接連不斷的戰事之後急劇降低。收集大量的急救物資，把它們交給塞納里奧要塞的喚風者梅恩·長角。','把20根重符文繃帶、20根厚絲質繃帶和20根厚絨線繃帶交給喚風者梅恩·長角。','','去希利蘇斯找雷戈蟲巢的梅洛克·遠途。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8787 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8787,'zhTW','戰場上的護甲片','戰場的繃帶儲存量在最近戰爭傷亡之後急劇降低。把大量的急救物資帶給塞納里奧要塞的喚風者梅恩·長角。','把20個重符文繃帶，20個厚絲質繃帶和20個厚絨線繃帶帶給喚風者梅恩·長角。','','去希利蘇斯找雷戈蟲巢的梅洛克·遠途。','','','','',0);
