INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8789,'zhTW','其拉帝王武器','一千年以來，我們並沒有無所事事地留在這裡，$N。$B$B我們在這裡看著這些野獸耗盡資源時自相殘殺，我們傾聽了它們密謀毀滅我們世界的談話，我們還知道了它們內部的爭權奪利。$B$B它們確實有弱點，而且我們知道如何利用這些弱點。$B$B找到它們在葬禮儀祭上陪葬用的武器，把它和他們自己的神所創造的最強的元素融合在一起，我們就可以創造出終結一切的武器。','把其拉帝王武器和3塊源質礦石交給安其拉神殿的亞雷戈斯，他會幫你製作使用源質強化過的武器。','','去找亞雷戈斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8790 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8790,'zhTW','其拉帝王徽記','亞雷戈斯認為，在一定情況下，因上古之神和他們的僕從之間的衝突而產生的元素也會對他們本身造成致命的威脅。凡人，我指的是源質。$B$B將其拉帝王徽記和這種元素交給我，我就能為武器注入巨大的力量。','把其拉帝王徽記和3塊源質礦石交給安其拉神殿的夢境之龍麥琳瑟拉，她會幫你製作使用源質強化過的武器。','','去找夢境之龍麥琳瑟拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8791 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8791,'zhTW','奧斯里安之死','來自其拉蟲人的威脅已經被平息。可怕的奧斯里安被消滅了。$B$B卡利姆多的人民聽到這個訊息應該可以鬆口氣了。將奧斯里安的頭顱交給塞納里奧要塞的指揮官瑪爾利斯。','將無疤者奧斯里安的頭顱交給希利蘇斯塞納里奧要塞的指揮官瑪爾利斯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8792 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8792,'zhTW','部落需要你的幫助！','你好，我很高興你願意聽我說話。部落需要一切可以獲得的幫助來準備發動安其拉戰爭，這意味著，我們需要你！現在，官方的資源收集者正在收集必需的資源儲備，但是如果沒有你的幫助的話，我們是無法達成目標的，$N！$B$B你應該和負責此事的督軍格爾庫克談一談。你覺得怎麼樣？你是否願意幫助部落做好戰爭的準備？','和奧格瑪精神谷的督軍格爾庫克談一談。','','','','','','',0);
