INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8799,'zhTW','節日英雄','聽好...我不應該告訴你這件事情的內容，但既然你是今日的英雄...$B$B每年的這個時候到處都有新鮮的冬青，但是都沒法保存太久。我們有一台保存的機器，能為冬青永遠保鮮!我們用它來點綴節日...在夏天的時候還可以賺取利潤!$B$B我會讓你使用保存機，但你一定要是個大師級的廚師才行。你需要一些石中鹽和兩個，三個，喔五個好了，五個金幣。我會幫你弄到一批好貨的。','攜帶1份石中鹽及5個金幣到冬青保存機去，你可以獲得5份保存的冬青。','','去找冬青樹儲藏器。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8800 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8800,'zhTW','塞納里奧的裝備','一旦你完成了分配給你的任務，就去找鐵匠瓦古斯談談。讓他看看你在戰鬥中得到的徽章。他會為你提供一些合適的裝備。','與希利蘇斯塞納里奧要塞的瓦古斯談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8801 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8801,'zhTW','克蘇恩的遺產','安其拉的高牆搖晃起來。超越這世界的邪惡力量已經被摧毀了。$B$B當你注視著巨像憎惡的遺蹟時，心跳幾乎被凍結。在死一般的寂靜中，你還是能感覺克蘇恩的邪惡力量。$B$B你完成了別人認為不可能的任務。$B$B你取下惡魔的眼柄小心放進你的包包裡。$B$B把克蘇恩之眼帶到下一個房間裡的巨龍那兒。','將克蘇恩之眼帶給安其拉神廟的卡拉史塔斯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8802 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8802,'zhTW','卡利姆多的救世主','到時光之穴去吧，$N$g大人:女士。阿納克洛斯還在等你回去呢。把克蘇恩之眼交給他，我相信他一定會很樂意在自己的收藏品中增加這麼一件東西。','把克蘇恩之眼交給時光之穴的阿納克洛斯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8803 AND `locale` = 'zhTW';
