INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8804,'zhTW','沙漠生存包','目前塞納里奧要塞湧入了大量的新兵，我們的首要問題就成了如何保證他們在沙漠中生存下來。缺水的環境和遍佈希利蘇斯的劇毒生物都威脅著這些缺乏經驗的志願者。去收集一些必需的物資，把他們交給要塞裡的卡蘭德拉斯吧。','把4份純水之球、4份特效抗毒藥劑和4份烤鮭魚交給希利蘇斯塞納里奧要塞的卡蘭德拉斯。你還必須隨身帶著後勤任務簡報 I才能完成這個任務。','','去希利蘇斯找塞納里奧要塞的卡蘭德拉斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8805 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8805,'zhTW','衛兵的護甲片','目前塞納里奧要塞的騎兵團缺乏足夠的毛皮護甲片，去收集大量護甲片，然後立即把它們交給塞納里奧要塞的維斯·庫魯茲隊長。','把毛皮護甲片交給希利蘇斯塞納里奧要塞的維斯·庫魯茲。','','去希利蘇斯找塞納里奧要塞的維斯·庫魯茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8806 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8806,'zhTW','衛兵的磨刀石','塞納里奧要塞的衛兵急需磨刀石。去收集足夠的磨刀石，然後立即把它們交給塞納里奧要塞的維斯·庫魯茲隊長。','把磨刀石交給希利蘇斯塞納里奧要塞的維斯·庫魯茲。','','去希利蘇斯找塞納里奧要塞的維斯·庫魯茲。','','','','',0);
