INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8809,'zhTW','特殊的材料','瓦古斯是塞納里奧要塞的鐵匠，他需要一些附魔材料來為我們的部隊製作強力的武器。去找到這些材料，把它們直接交給瓦古斯，這樣塞納里奧議會的軍隊就有了作戰裝備的保障。','把2塊魔化瑟銀錠和2塊魔化皮交給希利蘇斯塞納里奧要塞的瓦古斯。你還必須隨身帶著後勤任務簡報 IX才能完成這個任務。','','去希利蘇斯找塞納里奧要塞的瓦古斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8810 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8810,'zhTW','戰場上的繃帶','我們的繃帶儲備在最近接連不斷的戰事之後急劇降低。收集大量的急救物資，把它們交給塞納里奧要塞的喚風者梅恩·長角。','把30根重符文繃帶，30根厚絲質繃帶和30根厚絨線繃帶帶給喚風者梅恩·長角。你還必須隨身帶著後勤任務簡報 X才能完成這個任務。','','去希利蘇斯找塞納里奧要塞的喚風者梅恩·長角。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8811 AND `locale` = 'zhTW';
