INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8856,'zhTW','沙漠生存包','目前塞納里奧要塞湧入了大量的新兵，我們的首要問題就成了如何保證他們在沙漠中生存下來。缺水的環境和遍佈希利蘇斯的劇毒生物都威脅著這些缺乏經驗的志願者。去收集一些必需的物資，把他們交給要塞裡的卡蘭德拉斯吧。','把4份純水之球、4份特效抗毒藥劑和4份烤鮭魚交給希利蘇斯塞納里奧要塞的卡蘭德拉斯。','','去希利蘇斯找塞納里奧要塞的卡蘭德拉斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8857 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8857,'zhTW','亞什巨像的秘密','我正在尋找那些經過戰爭洗禮的冒險者，看他們是否願意從亞什巨像的屍體上取到新鮮的獠牙樣本，並把它交給藏寶海灣的奧格索普。不，不，我可不希望你在那傢伙的屍體附近遊蕩。你只需迅速取回樣本，這東西腐爛了就不好辦了！','把亞什巨像的獠牙交給藏寶海灣的奧格索普·奧布諾提斯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8858 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8858,'zhTW','巨像的秘密 - 雷戈','我只想把這個甲蟲殼套在奧菲斯特的大肥臉上…可惜，我現在要在這裡收集畸形的蟑螂樣本。我會一直在這裡直到清晨。$B$B快點幫我把這個樣本帶給奧菲斯特，$c。他會重重答謝你!$B$B沒錯，瑟銀哨塔 – 就在灼熱峽谷。','把雷戈巨像的甲殼帶給灼熱峽谷的工頭奧菲斯特。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8859 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8859,'zhTW','巨像的秘密 - 佐拉','我的奴僕差點在取得這個樣本時喪命。你一定要動作快！瑪克斯韋爾·泰羅索斯男爵急需要一個新鮮的甲殼樣本。他相信巨像的秘密可以幫助我們對抗天譴軍團！$B$B你怎麼還在這裡！？到聖光之願禮拜堂！沒錯，你會得到可觀的獎勵…','把佐拉巨像的甲殼帶到東瘟疫之地的聖光之願禮拜堂給瑪克斯韋爾·泰羅索斯男爵。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8860 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8860,'zhTW','慶祝新年！','暴風城正在舉行新年慶典！所有人都可以全天暢飲美酒佳餚，晚上還會有焰火表演！聽起來是不錯……不過藏寶海灣也有這樣的慶典，我敢說這個肯定更棒！$B$B總之，暴風城的旅店老闆奧裡森需要一些煙林牧場的補給品才能應付需求量巨大的慶典，你能幫我送一趟貨嗎？$B$B謝謝你，$n！旅店老闆奧裡森在鑲金玫瑰旅店，就在暴風城的貿易區裡。','將煙林補給品交給暴風城的旅店老闆奧裡森。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8861 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8861, 'zhTW', '新年慶典！', '雷霆崖正在舉辦新年的慶典！那裡整天提供免費的飲料，晚上他們還會舉辦煙火表演！$B$B應該會很不錯的……但是藏寶海灣今天晚上也有個宴會；我敢說那一定更棒！$B$B總之，雷霆崖的旅店老闆帕拉需要燻木牧場的補給品才能應付需求量龐大的慶典。你能幫我送過去嗎？$B$B謝謝你，$N！旅店老闆帕拉就在通往獵人高地橋邊的旅店裡面。', '將燻木補給品帶給雷霆崖的旅店老闆帕拉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8862 AND `locale` = 'zhTW';
