INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8921,'zhTW','靈質提純器','啊，你需要我最新的研究產品……超維度幽靈顯形器！不過遺憾的是，我已經消耗光了所有的人力和資金，沒法繼續研究了。$B$B你說你願意幫忙？太好了！我們首先需要建立起一個能夠收集亡靈物質的裝置，製造一臺靈質提純器！這可不是一項簡單的工作，$N。$B$B我需要你給我找來一個奧金轉換器，一些強效不滅精華和一些石鱗魚油。我還需要一些來自燃燒平原的岩漿流裡的火山灰，用來製造過濾網。','將1個精密奧金轉換器、4份強效不滅精華、10瓶石鱗魚油、25份火山灰和40枚金幣交給加基森的穆克斯·瑪納斯卡波。','','去找塔納利斯的穆克斯·瑪納斯卡波。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8922 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8922,'zhTW','超自然的裝置','我必須想個辦法與安泰恩·哈爾蒙談談……更確切地說，和他的鬼魂好好談談！$B$B我知道有個技師對這種超自然的東西有著一種奇怪的興趣。他宣稱他可以造出一臺能讓與死者對話的機器！$B$B你收集來的血其實是為他所準備的，到加基森去，把這些帶給他，就算是支付給他的酬勞吧！','將封起來的血液容器交給加基森的穆克斯·瑪納斯卡波。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8923 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8923,'zhTW','超自然的裝置','你竟然收集到了這麼多，看來真是個夠膽量的傢伙。要不然就是我給你的護甲套件挑起了你興趣吧。要是你還願意幫我的忙，我還能給你更多的套件。$B$要你採集的毒液樣本是為我的一個熟人穆克斯·瑪納斯卡波準備的。他是個技師，對於超自然的事物有著濃厚的興趣。他最近研究中的新專案是一臺可以讓你與死者交談的機器！那也是我聯絡安泰恩，並且瞭解自己處境的最後希望了。','將封起來的毒液容器交給加基森的穆克斯·瑪納斯卡波。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8924 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8924,'zhTW','獵取靈質','這真是一件完美的器物，若能應用在工程學裡就太好了，我不得不這麼說！恐怕，你現在需要跑點遠路了，得去一些我們所必需的虛體亡靈生物裡的靈質來。$B$B你看，不同的氣候將會導致幽靈體的亡靈生物的靈質不同。希利蘇斯的被折磨的暗夜精靈，冬泉谷的上層精靈幽靈，以及東瘟疫之地的幽靈和女妖或許能分別給我們提供不同的靈質樣本。在收集之前，一定要把萃取器放在它們附近！','使用靈質提純器在希利蘇斯收集12份燒焦的靈質，在冬泉谷收集12份冰凍的靈質，以及在東瘟疫之地收集12份穩定的靈質。然後將這些東西與靈質提純器一起交給加基森的穆克斯·瑪納斯卡波。','','去塔納利斯找加基森的穆克斯·瑪納斯卡波。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8925 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8925,'zhTW','便攜的能量源','接下來我們需要找到一種穩定且便於攜帶的能量，以便維持靈質的活性。我聽說有個名叫熔岩領主博奧克的強大土元素，它的心臟是個富含能量的岩漿核，永遠地在不停地散發著熱能！$B$B據說它就居住在燃燒平原的大熔爐。把它的心臟取來，這樣我們就可以獲得足夠的富含熱能的液體來維持超維度幽靈顯形器的運轉了！','前往燃燒平原，找到熔岩領主博奧克，把它的岩漿核心交給加基森的穆克斯·瑪納斯卡波。','','去塔納利斯找加基森的穆克斯·瑪納斯卡波。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8926 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8926,'zhTW','公平的補償','你信守承諾將莫克斯建構的儀器帶來了。我相信如果我給你獎賞，你會感興趣的。若你想升級的話，就把腰帶和一整套手套拿來給我。我承諾我交還給你的一定是更為精良的物品。','將野性之心腰帶，一套野性之心手套帶給鐵爐堡的德莉娜。','','去鐵爐堡找王座廳的德莉亞娜。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8927 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8927,'zhTW','公平的補償','你證明了自己是個非常可靠的人，$N。我相信你會幫我度過這次的困境，我會依照你的表現來給予獎勵。$B$B現在我要把你的腰帶和手套換掉。如果我們一起度過了這個難關，我就會把剩下的裝備都做給你。','將野性之心腰帶和1套野性之心手套帶給奧格瑪的莫克瓦。','','去找奧格瑪的莫克瓦爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8928 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8928,'zhTW','小巧的商人','那個核心可以提供足夠的岩漿來驅動我們的裝置，現在我們只需要製造一根耐性足夠，不會被熔掉的導流棒來引導能量就可以了！$B$B我曾在冬泉谷見過一個販賣各類奇特貨物的小鬼。他似乎有一根由某種元素製成的棒子，應該就是最完美的了。現在我真想抽自己的耳光，為什麼當初沒有買下它。$B$B他就住在暗語峽谷入口附近的一處洞穴裡。看看你能不能找到他吧！$B$B記住，超過40金幣就別要了，這是他過去給我開的價！','到冬泉谷南部的暗語峽谷入口附近去，在那裡的一處洞穴內的某個小鬼那裡購買一根惡魔元素之杖，並把它交給加基森的穆克斯·瑪納斯卡波。','','去找塔納利斯的穆克斯·瑪納斯卡波。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8929 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8929,'zhTW','尋找安泰恩','好吧，看來我們除了試試地精的發明外別無他法。據說安泰恩在試圖進入斯坦索姆時被天災軍團砍翻了。$B$B試試使用這個裝置，看看你能從安泰恩的靈魂那裡得到什麼訊息。','在斯坦索姆的入口處使用超維度幽靈顯形器，然後與安泰恩·哈爾蒙的靈魂交談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8930 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8930,'zhTW','尋找安泰恩','非常好，$N。後面唯一要做的事就是把這個地精的發明拿去測試一下了。據說安泰恩在嘗試進入斯坦索姆的時候被亡靈軍團幹掉了。$B$B到那裡去用一下這個裝置吧，看看你是否真的能跟死人說話！','在斯坦索姆的入口處使用超維度幽靈顯形器，然後與安泰恩·哈爾蒙的靈魂交談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8931 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8931,'zhTW','小小的補償','你做到了你所承諾的事，把穆克斯製造的裝備給我帶了回來，那麼我也按承諾給予你一件不錯的獎勵。把你原先使用的腰帶和手套拿來吧，我會幫你升級它們。我敢保證，新的裝備會比原來的好得多。','將一條野獸追獵者腰帶和一副野獸追獵者手套交給鐵爐堡的德莉亞娜。','','去鐵爐堡找王座廳的德莉亞娜。','','','','',0);
