INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8945,'zhTW','死人的請求','我會把我所知道的一切都告訴你的，$N。但現在還有些更緊迫的事情要做。$B$B我摯愛的妻子被該死的瑞文戴爾男爵和他手下的亡靈渣滓們給監禁了。$B$B我過去就非常反對她加入那個什麼銀色黎明的愚蠢組織，不過現在這並不重要了。你一定得幫我這個忙，完成我的遺願——從男爵的魔爪中救出我的伊思達！','進入斯坦索姆，從瑞文戴爾男爵手中救出伊思達。','','去找斯坦索姆的伊思達·哈爾蒙。','解救伊思達','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8946 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8946,'zhTW','生命的證據','我的愛人在趕來營救我的途中不幸喪命，這是多麼悲慘的命運。不過既然你說自己有跟靈魂交談的能力……$B$B把這個小盒子交給他，告訴他我過得很好。讓他的靈魂不要繼續在世間遊蕩了，我已經無法承受內心的傷痛。$B$B再見，$N。你心腸真好，我會永遠記得你的。','將伊思達的盒子交給東瘟疫之地的安泰恩·哈爾蒙。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8947 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8947,'zhTW','安泰恩的奇怪請求','我們竟沒有意識到瓦塔拉克勳章的重要性，它被分割成了幾部分，分別由不同的人儲存著。第一部分被一個名叫塞爾德林的矮人拿走了。我曾嘗試著把它要回來，可那個矮人幾乎把我活活打死。要想拿回它，你恐怕得用點暴力手段。$B$B有關這個塞爾德林的近況……他好像在黑鐵矮人那邊，成了一名角鬥士。想讓他跟你打，你恐怕得先透過一些挑戰。$B$B把這些材料都收集來，你會用到它們的。','將3塊黑鐵錠、20張魔化皮、3塊月布和4塊熟化毛皮交給東瘟疫之地的安泰恩·哈爾蒙。','','去東瘟疫之地找斯坦索姆的安泰恩·哈爾蒙。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8948 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8948,'zhTW','安泰恩的老朋友','塞爾德林可不是一個願意參加一場公平決鬥的傢伙。我做了這面旗子，上面繪有他家族的紋章。$B$B只需要再附加上一點小小的巫術，這面旗子就可以讓他無法抗拒地迎接他人的挑戰。$B$B我有個老熟人叫法爾林，他知道如何附加上這個小巫術。對於……對於激怒他人，他有一種非常特別的方式。你可以在厄運之槌的圖書館裡找到他。','將未完成的挑戰之旗交給厄運之槌圖書館內的法爾林·樹影。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8949 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8949,'zhTW','法爾林的復仇','是的，沒錯，我確實對你所想要的這種強化魔法十分熟悉，$c。可我並不是那種隨隨便便就免費施恩的人，哪怕你是我的老朋友介紹來的。$B$B對於那些粗鄙野蠻的食人魔鄰居，我除了討厭與憎恨以外就沒有其他情感了。不光是那些戈多克大王的手下，我還特別討厭那些追隨歐莫克大王的食人魔。$B$B我要你殺了他們。殺了他們！全殺光！把他們脖子上常掛的珠串給我拿回來，做為證明。去幹吧，讓我滿意的話，我就考慮一下你的要求。','在厄運之槌和黑石塔的食人魔身上收集25串食人魔珠串，然後回去向厄運之槌圖書館內的法爾林·樹影覆命。','','去奧特蘭克山脈找達拉然巨坑的法爾林·樹影。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8950 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8950,'zhTW','旗幟上的附魔','我能按照你的要求在挑戰之旗上附魔，$N。不幸的是，我恰好沒有那種附魔材料。那可是個稀罕物，有些人甚至把它當作護身符來用。$B$B我需要這一帶的建築裡面的艾德雷斯亡靈生物的精華，一些黑暗符文，以及一些大塊魔光碎片。將附魔材料交給我，我就能幫你完成任務。','將1份遊蕩鬼靈的精華、4個黑暗符文和8個大塊魔光碎片交給厄運之槌圖書館內的法爾林·樹影。','','去菲拉斯找厄運之槌圖書館的法爾林·樹影。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8951 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8951,'zhTW','安希恩的離別感言','瓦薩拉克的靈魂被存封在這個護符裡。因為我們的貪婪，愚蠢地把護符分成三塊，不知道有可怕的詛咒在等著我們。$B$B阻止瓦薩拉克魔法的唯一方法就是將護符重新組合回去。回到德莉娜那裡，告訴她佈德利是找到剩下護符的唯一希望。和她談談為你安排的獎勵。$B$B我，這一次，終於可以安息了。祝你好運；你需要這份好運的！','帶著野性之心長靴，野性之心褶裙和野性之心肩甲回到鐵爐堡的德莉娜那裡。','','去鐵爐堡找王座廳的德莉亞娜。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8952 AND `locale` = 'zhTW';
