INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8960,'zhTW','伯德雷的不幸','那麼也就是說我們需要找回勳章的其他部分？要找伯德雷可有點麻煩。他去了黑石山，想嘗試重新進入黑石塔，結果就再也沒有回來了。$B$B我建議你帶上地精的那臺裝置吧，萬一最壞的結果發生了，你也有辦法應對。','到黑石山去，使用超維度幽靈顯形器找到伯德雷。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8961 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8961,'zhTW','烈焰之王','$C，要召喚出黑石山的瓦塔拉克公爵並解決這個麻煩的傢伙，我們首先得找到三塊護符中的其他兩塊。因此，我們需要一隻火盆和某些特殊的燃料。$B$B三位火元素領主，黑石深淵裡的伊森迪奧斯、黑石塔裡的烈焰衛士艾博希爾和希利蘇斯的灰燼公爵就有我們需要的東西。你可以從每個火元素領主的屍體上分別收集一塊殘骸，如果你在銀色黎明中的聲望達到了尊敬的話，就可以買到空火盆。將三塊殘骸和一隻空火盆帶回來吧。','收集伊森迪奧斯的餘炭、艾博希爾灰燼和灰燼公爵的殘渣，並從銀色黎明軍需官那兒購買一隻空火盆，然後將這些東西交給黑石山的伯德雷。','','去找燃燒平原的伯德雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8962 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8962,'zhTW','重要的材料','$C，仔細聽好了。既然我們有了火盆和點燃它的方法，我們還需要另一個材料來注入火盆；一種強大的集中力來誘使我已故亡友的靈魂出現。$B$B莫爾·灰蹄，我們最重要的德魯伊，在塞納里奧議會有很多親密的朋友，其中有些人已被異種消滅。我要你去希利蘇斯從雷戈蟲巢的異種身上取得德魯伊遺骨。','取得德魯伊的遺體，再回到黑石山找佈德利。','','去找燃燒平原的伯德雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8963 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8963,'zhTW','重要的材料','$C，仔細聽好了。既然我們有了火盆和點燃它的方法，我們還需要另一個材料來注入火盆；一種強大的集中力來誘使我已故亡友的靈魂出現。$B$B伊薩利恩，我們的女祭司，在星風村的冬泉谷長大。我要你去冬泉谷南邊的霜語峽谷，從那裡的霜槌巨人身上取得星風村聖物，他們有時候會襲擊北方。','取得星風村聖物，再回到黑石山找佈德利。','','去找燃燒平原的伯德雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8964 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8964,'zhTW','重要的材料','$C，仔細聽好了。既然我們有了火盆和點燃它的方法，我們還需要另一個材料來注入火盆；一種強大的集中力來誘使我已故亡友的靈魂出現。$B$B賈林和索索斯這對兄弟是血色十字軍的信徒。他們渴望在那個邪惡的組織裡成為騎士。前往東瘟疫之地的提爾之手，從血色禁衛隊那裡取得光亮的狂熱之劍。','取得光亮的狂熱之劍，再回到黑石山找佈德利。','','去找燃燒平原的伯德雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8965 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8965,'zhTW','重要的材料','$C，仔細聽我說。我們已經拿到火盆了，但是要點燃火盆，我們還需要藉助某些特殊材料的力量。那些稀有的材料可以釋放出足夠的能量，以引出那些已死的靈魂，我昔日的同伴。$B$B有個叫庫爾莫克的食人魔通靈師曾與我們一起旅行，他曾在希爾斯布萊德海岸南方的贖罪島那邊召喚出被流放的死者的靈魂。到那裡去，從他們的遺體身上幫我找些放逐者的靈魂灰燼回來。','拿到放逐者的靈魂灰燼，把它交給黑石山的伯德雷。','','去找燃燒平原的伯德雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8966 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8966,'zhTW','瓦薩拉克護符的左半塊','我的朋友，莫爾·灰蹄，是第一個因為擁有瓦薩拉克的護符碎片和其中包含的腐敗靈魂碎片而受害的人。在偷了瓦薩拉克的法術書和護符之後，我們就立刻從黑石塔上層逃走。途中，莫爾跌進了塔底。$B$B之後，我們發現他並沒有摔死，只是被指揮官沃恩俘虜起來且受盡折磨。幾個鬼魂刺客溜進去在沃恩面前把他給殺了。','使用召喚火盆來召喚莫爾·灰蹄的靈魂並殺了他。帶著瓦薩拉克護符的左半塊和召喚火盆回到黑石山的佈德利那裡。','','去找燃燒平原的伯德雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8967 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8967,'zhTW','瓦塔拉克飾品的左瓣','就在幾天前，我們掙扎著尋求生存時得到了這樣的訊息，我們隊伍中的暗夜精靈牧師伊薩莉恩私自去了那座暗夜精靈的古城遺蹟，也就是現在被稱為厄運之槌的地方。根據我們蒐集到的資訊，她去那裡不僅是為了個人原因，也是想解開她所擁有的那部分飾品中蘊涵的秘密。$B$B但她似乎沒能成功。我們所蒐集到的訊息是，她在艾德雷斯神殿被奧茲恩及其手下幹掉了。','使用召喚火盆召喚出伊薩利恩的靈魂，然後殺掉她。完成之後，將召喚火盆與瓦塔拉克飾品的左瓣還給伯德雷。','','去找燃燒平原的伯德雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8968 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8968,'zhTW','瓦薩拉克護符的左半塊','賈林和索索斯這對兄弟，決定要加入血色十字軍因為我們的傭兵公司要解散了。他們帶著瓦薩拉克的左半塊護符。我說這真是一個很好的解脫，但我們需要拿回那個東西。$B$B據訊息指出，他們是因為在血色十字軍堡壘的創始儀式失敗，被大十字軍戰士達索漢在他的房間裡殺死。$B$B無論如何，我們……也就是你，還是要把那塊護符討回來。','使用召喚火盆來召喚賈林和索索斯並殺了他們。帶著瓦薩拉克護符的左半塊和召喚火盆回到黑石山的佈德利那裡。','','去找燃燒平原的伯德雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8969 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8969,'zhTW','瓦塔拉克飾品的左瓣','現在我們終於有了我們需要的一切，是時候討論一下你該召喚誰了。$B$B庫爾莫克過於曾是還不錯的食人魔，可開始學習通靈術之後他就徹底變了。自那以後，每個人都開始遠離他，厭惡他。於是，毫無懸念地，他帶著他的那部分飾品去了他的新家，通靈學院。$B$B然而，就算在那裡，他仍然不免遭了幽靈刺客的毒手。它們乾脆當著他的主人萊斯·霜語的面，殺死了他。','使用召喚火盆召喚出庫爾莫克的靈魂，然後殺掉他。完成之後，將召喚火盆與瓦塔拉克飾品的左瓣還給黑石山的伯德雷。','','去找燃燒平原的伯德雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8970 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8970,'zhTW','奧卡茲島在你前方……','正如我說的那樣，$C，我很草率地做了決定，成為一名預言師。預言師並非想象中那樣來錢……這份工作充滿危險，施法材料價格昂貴而且很不好找。但是我知道最後一塊飾品碎片在哪兒，那上面還附著我的老朋友的靈魂。$B$B$N，恐怕你得去塵泥沼澤的奧卡茲島一趟，從斯塔莎茲納迦身上收集血藻。','前往塵泥沼澤的奧卡茲島，從斯塔莎茲納迦身上收集20份血藻，然後返回黑石山的伯德雷那兒。','','去找燃燒平原的伯德雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8971 AND `locale` = 'zhTW';
