INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9014,'zhTW','最後的獎賞','真是個不可思議的故事，$N！謝謝你，我保證，所有相關的人都衷心的感激你。因為你的努力，我們走出了從前犯的錯誤。$B$B至於你的獎勵，我確信這幾樣東西你會很喜歡。','將你的博學者頭冠和博學者長袍交給莫克瓦。','','去找奧格瑪的莫克瓦爾。','','','','',0);
