INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9015,'zhTW','挑戰','聽好了，$N。為了讓這面旗幟運轉起來，你必須要進入黑石深淵的競技場，然後聽任裁決者格里斯通宣判你，然後將這面旗子牢牢地插在地面上有處挑戰標記的地方。$B$B這時你想挑戰的人就會被不可抗拒的力量推入戰場，渾身上下只有將你殺死的慾望。當你從他身上找到了你要的東西以後，就回去找安泰恩吧。','到黑石深淵的競技場去，在你被裁決者格里斯通宣判之後將挑戰之旗插在場地中央。殺死塞爾德林和他的角鬥士，然後將瓦塔拉克飾品第一部分交給東瘟疫之地的安泰恩·哈爾蒙。','','去東瘟疫之地找斯坦索姆的安泰恩·哈爾蒙。','打敗塞爾德林的小隊','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9016 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9016,'zhTW','安希恩的離別感言','瓦薩拉克的靈魂被存在這個護符裡。因為我們的貪婪，愚蠢地把護符分成三塊，不知道有可怕的詛咒在等著我們。$B$B阻止瓦薩拉克的魔法的唯一方法就是將護符重新組合回去。回到莫克瓦那裡，告訴他佈德利是找到剩下護符的唯一希望。和他談談為你安排的獎勵。$B$B我，這一次，終於可以安息了。祝你好運；你需要這份好運的！','帶著野性之心長靴，野性之心褶裙和野性之心肩甲回到奧格瑪的莫克瓦那裡。','','去找奧格瑪的莫克瓦爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9017 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9017,'zhTW','安希恩的離別感言','瓦薩拉克的靈魂被存在這個護符裡。因為我們的貪婪，愚蠢地把護符分成三塊，不知道有可怕的詛咒在等著我們。$B$B阻止瓦薩拉克的魔法的唯一方法就是將護符重新組合回去。回到莫克瓦那裡，告訴他佈德利是找到剩下護符的唯一希望。和他談談為你安排的獎勵。$B$B我，這一次，終於可以安息了。祝你好運；你需要這份好運的！','帶著馭獸者長靴，馭獸者短褲和馭獸者襯肩回到奧格瑪的莫克瓦那裡。','','去找奧格瑪的莫克瓦爾。','','','','',0);
