INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9023,'zhTW','完美的毒藥','我和我的兄弟在拉文霍德莊園外進行毒藥研究。$B$B拉文霍德公爵命令我們研製一種極效混合毒藥，祖爾格拉布和安其拉廢墟出產這種毒藥的原料，也就是毒囊。$B$B有兩隻劇毒的野獸居住在那些可怕的廢墟中，它們很可能有我們需要的毒囊。$C，去取回庫林納克斯和溫諾希斯的毒囊，我們會永遠記得你的恩情的。','塞納里奧要塞的德爾克·雷木讓你把溫諾希斯的毒囊和庫林納克斯的毒囊交給他。','','去希利蘇斯找塞納里奧要塞的德爾克·雷木。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9024 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9024,'zhTW','阿瑞斯坦的預感','我找到了！你聞到過風中的新香氣沒有？新的香水現在有那麼流行麼？我們的衛兵不該這麼簡單就這樣拋棄他們的職責！$B$B嗯，一定是因為他們的理智完全被這些該死的鍊金術產品所蓋過去了。$B$B要想搞清楚問題，只有一個辦法：弄一些香水的樣本，把它們交給摩根·匹斯特，並把我的推斷告訴他。別擔心，你回來的時候我會把買香水的錢付給你的。','將1瓶古龍水和1瓶香水交給暴風城貿易區的摩根·匹斯特。','','去找暴風城的摩根·匹斯特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9025 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9025,'zhTW','摩根的發現','好吧，有問題。看來阿瑞斯坦還真是個很警覺的人。我在香水中發現了一些應用在愛情藥水中的物質，以及一些可以影響情緒的危險成分。$B$B在香水中應用這些物質雖然並非是前所未有的，但我從中分析出的一些原料……聞起來很有趣。','回到暴風城銀行附近的阿瑞斯坦·莫塔那裡。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9026 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9026,'zhTW','追查貨源','我們一定得找到源頭才行。我看到許多人，包括衛兵，都在鑲金玫瑰那裡進進出出。跟奧裡森談談，要是她在賣這些東西，就問問她是從哪裡弄來的貨。','與暴風城貿易區中的鑲金玫瑰旅店的老闆奧裡森談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9027 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9027, 'zhTW', '追溯來源', '古龍水發生什麼事了嗎？有可能。我從沒見過有這麼多人都爭相搶購一項商品。聽著，如果它有什麼問題，我也想知道。我跟一個叫艾佛特·索里山姆的商人買了補給品。他是鎮上新來的。他提到有一些物品要送到「最好的線團」那家店。', '到暴風城運河邊和「最好的線團」那家店的艾佛特·索里山姆談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9028 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9028, 'zhTW', '揭露來源', '什麼？叛國罪？不，不，我向你保證，我完全沒有惡意。難道我想幫助那些人減輕痛苦的求愛儀式也有錯嗎？拜託，那不是犯罪。為了證明我沒有惡意，我甚至可以告訴你我的貨源是誰。是一個叫史塔弗隆·雷倫的人運給我的，他是個藥劑師。我從沒跟他講過話。我們的哥布林經紀人說他在希爾斯布萊德丘陵越過神秘的拉文霍德莊園工作。希望你有那個運氣能找到他。', '找到在希爾斯布萊德丘陵，拉文霍德莊園後方的藥劑師史塔弗隆·雷倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9029 AND `locale` = 'zhTW';
