DELETE FROM `quest_template_locale` WHERE `ID` = 9030 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9030,'zhTW','告別安泰恩','瓦塔拉克的靈魂就封印在這枚護符裡。因為貪婪，我們愚蠢地將它分成了好幾部分，絲毫不瞭解這會為我們帶來怎樣殘酷的詛咒。$B$B唯一解除瓦塔拉克的法術的辦法，就是將這枚勳章重新組合在一起。回到德莉亞娜那裡去，告訴她說，伯德雷已經是她找齊剩餘部分的最後希望了。$B$B我只希望能從此安息。祝你好運……你會非常需要運氣的！','與鐵爐堡的德莉亞娜談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9031 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9031,'zhTW','告別安泰恩','瓦塔拉克的靈魂就封印在這枚護符裡。因為貪婪，我們愚蠢地將它分成了好幾部分，絲毫不瞭解這會為我們帶來怎樣殘酷的詛咒。$B$B唯一解除瓦塔拉克的法術的辦法，就是將這枚勳章重新組合在一起。回到德莉亞娜那裡去，告訴她說，伯德雷已經是她找齊剩餘部分的最後希望了。$B$B我只希望能從此安息。祝你好運……你會非常需要運氣的！','與奧格瑪的莫克瓦爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9032 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9032,'zhTW','佈德利不幸的命運','這枚徽章裡有瓦薩拉克的靈魂嗎?被這強大的詛咒所守護其實也沒什麼好驚訝的。$B$B佈德利的所在位置顯現出一些問題。上次我聽到的是他準備重返黑石塔的訊息，然後就再也沒音訊了。$B$B到黑石山去找他，不過我很擔心他可能早已身亡。所以我建議你隨身攜帶哥布林的裝置，朋友。','到黑石山並使用超空間鬼魂顯像機，去黑石塔附近尋找佈德利。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9033 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9033,'zhTW','戰爭的迴響','上一次戰爭距今已有5年了……$B$B數萬名士兵戰死沙場，他們的犧牲換來了什麼？危機遠遠沒有消失。$B$B巫妖王再次蠢蠢欲動……他的走狗克爾蘇加德正在集聚軍隊，準備對我們的家園發動新一輪的襲擊。$B$B我們絕不會讓他得逞！拿出你的奉獻精神吧。勇敢地投入戰鬥，以此證明你的無畏！銀色黎明和血色十字軍組成的聯軍將是你堅強的後盾和戰友。$B$B前往納克薩瑪斯的宮殿，打敗天災軍團……','東瘟疫之地聖光之願禮拜堂的指揮官埃裡戈爾·黎明使者要你殺死5個畸形妖、5只巖膚石像鬼、8個死亡騎士隊長和3只毒性捕獵者。','','去找東瘟疫之地的指揮官埃裡戈爾·黎明使者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9034 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9034,'zhTW','無畏胸甲','在你與納克薩瑪斯宮殿中的天災軍團作戰過程中，如果看到被玷汙的護甲和板甲碎片，將它們帶給我，我會為你打造一套適合英雄穿著的護甲。','如果你將1件被玷汙的胸甲、25塊板甲碎片、4塊奧金錠和2塊連結水晶交給東瘟疫之地聖光之願禮拜堂的科爾法克斯，他會為你製作一件無畏胸甲。','','去找東瘟疫之地的科爾法克斯，聖光之勇士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9035 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9035, 'zhTW', '路邊的伏擊', '嘿，就是你!你一定要幫我，拜託!我的同伴學徒和我遭到鄙惡者的攻擊!由於他們對魔法瘋狂的渴望，拿走了所有可以得手的東西:法力水晶，魔杖，魔法書……所有的東西!美勒杜跑去追他們了，我得留在這裡看守他們沒拿走的東西。沿著路往下走，看看你能不能幫他一把。', '沿著銀月城的路往南走，和永歌森林的學徒美勒杜談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9036 AND `locale` = 'zhTW';
