INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9051,'zhTW','毒性測試','這些你幫我製造的毒素有著特殊的用途。環形山裡的魔暴龍使得那裡的狩獵和生存環境對我來說都變得十分惡劣。即使我足夠強壯，殺死一隻魔暴龍也只會讓另一隻遊蕩入那塊帶領地而已。$B$B帶上這根毒針並將其刺入一隻活著的魔暴龍體內。毒素會使它很快就安靜下來，不過……我不知道很快有多快……','將魔暴龍之刺扎入一隻魔暴龍的體內。','把毒刺扎入魔暴龍體內','去安戈洛環形山找沼澤地的托爾瓦·尋路者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9052 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9052,'zhTW','血瓣毒藥','我要你幫我製作一批毒素，用來制服某些生活在環形山裡的巨獸。它並非是致命性的，不過只有一個足夠細心和聰明的$c才能收集到所有的材料。$B$B在環形山裡任意血瓣花苗身上，你都可以找到一些血帽蘑菇，而格里什釘刺則可以從環形山南部巨痕谷中的那些巨蜂身上找到。','收集一些血帽和格里什釘刺，然後向托爾瓦·尋路者覆命。','','去安戈洛環形山找沼澤地的托爾瓦·尋路者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9053 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9053,'zhTW','更好的材料','這正是我所擔心的，看來毒素的力量還是太弱了，無法對這樣強大的生物產生影響。$B$B我們必須造出一種更強力的毒素，你需要前往阿塔哈卡神廟的底部，揭開那個祭壇的秘密，並從那裡的守衛身上取一些腐爛的藤蔓來。神廟很危險，我建議你帶些朋友一起去。$B$B完成之後回到我這裡來吧。','從沉沒的神廟底部的守衛身上得到一些腐爛藤蔓，把它們交給托爾瓦·尋路者。','','去安戈洛環形山找沼澤地的托爾瓦·尋路者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9054 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9054,'zhTW','地穴追獵者外套','我發現地穴惡魔的甲殼大有用處。我可以利用這種甲殼以及丟失在納克薩瑪斯宮殿中的被玷汙的護甲，打造出一套輕便時尚的、具有毀滅性力量的套裝。$B$B幫我尋找必需的材料，我就能製作出這套前所未有的裝備！','如果你將1件被玷汙的外套、25塊鎖甲碎片、4塊奧金錠和3個熟化毛皮交給東瘟疫之地聖光之願禮拜堂的獵手雷奧普德，他會為你製作一件地穴追獵者外套。','','去東瘟疫之地找聖光之願禮拜堂的獵手雷奧普德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9055 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9055,'zhTW','地穴追獵者腿甲','我發現地穴惡魔的甲殼大有用處。我可以利用這種甲殼以及丟失在納克薩瑪斯宮殿中的被玷汙的護甲，打造出一套輕便時尚的、具有毀滅性力量的套裝。$B$B幫我尋找必需的材料，我就能製作出這套前所未有的裝備！','如果你將1條被玷汙的腿甲、20塊鎖甲碎片、3塊奧金錠和5個熟化毛皮交給東瘟疫之地聖光之願禮拜堂的獵手雷奧普德，他會為你製作一條地穴追獵者腿甲。','','去東瘟疫之地找聖光之願禮拜堂的獵手雷奧普德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9056 AND `locale` = 'zhTW';
