INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9072,'zhTW','碎地者長靴','你能將那些戰死沙場的英雄的護甲給我帶回來嗎？$B$B那些護甲被邪惡的敵人奪去，早已被玷汙了，但是護甲碎片能徹底清潔它們，讓我們重新穿著它們殺入戰場。$B$B將陣亡英雄的遺物以及那些淨化所需的材料交給我，我會為你打造碎地者的套裝。$B$B到納克薩瑪斯去尋找吧！','如果你將1雙被玷汙的長靴、12塊鎖甲碎片、1塊奧金錠和3塊連結水晶交給東瘟疫之地聖光之願禮拜堂的雷布拉特·碎地者，他將為你製作一雙碎地者長靴。','','去東瘟疫之地找聖光之願禮拜堂的雷布拉特·碎地者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9073 AND `locale` = 'zhTW';
