INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9076, 'zhTW', '鄙惡者頭目', '鄙惡者在狼吞虎嚥邪惡魔法的時候非常懈怠，他們根本不知道我們已取回我們的軍備。但是我們也不能總是期望他們保持懈怠。現在就是採取果斷攻擊的時候。讓我們先以他們的首領阿德倫為先例。有人看見他在船廠旁那棟建築物的頂樓。幫我把他的頭帶來，我會好好地獎勵你。', '把阿德倫的頭顱帶給永歌森林日帆船廠附近的微蘭德絲·白晨。', '', '去找永歌森林的微蘭德絲·白晨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9077 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9077,'zhTW','骨鐮胸甲','如果你想要骨鐮護甲，就得幫我找來一些必需的材料。$B$B進入納克薩瑪斯的宮殿——就是那座漂浮在空中的巨大城市，去收集被玷汙的護甲和皮甲碎片。集齊所有材料，我就能為你打造骨鐮護甲。噢，對了，你還得付點金幣給我……製作護甲所需的骨頭由我來提供。','如果你將1件被玷汙的胸甲、25塊皮甲碎片、2塊奧金錠和6個熟化毛皮交給東瘟疫之地聖光之願禮拜堂的殺手洛汗，他會為你製作一件骨鐮胸甲。','','去東瘟疫之地找聖光之願禮拜堂的殺手洛汗。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9078 AND `locale` = 'zhTW';
