INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9095,'zhTW','霜火長袍','作為一名守衛，我有權使用麥迪文的私人物品。我發現在所有的物品中，書籍最能予人啟迪。坦白地說，雖然大部分書籍內容都相當垃圾，但其中也不乏精品。其中一本記載了大法師的霜火套裝的製作方法。$B$B<安吉拉指著她的腦袋。>$B$B它們現在都在我的腦子裡，如果你能給我適當的材料，我會很樂意與你分享這些寶貴的知識。','如果你將1件被玷汙的長袍、25塊布衣碎片、4張月布和2塊連結水晶交給東瘟疫之地聖光之願禮拜堂的大法師安吉拉·杜薩圖斯，她會為你製作一件霜火長袍。','','去東瘟疫之地找聖光之願禮拜堂的大法師安吉拉·杜薩圖斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9096 AND `locale` = 'zhTW';
