INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9103,'zhTW','瘟疫之心長袍','我可不是吹牛，你這卑微的傢伙。瘟疫之心套裝擁有的黑暗力量很可能會要了我們倆的性命。這也是我要價很高的原因。要死的話，我也得做個富鬼不是？$B$B我可不關心你的死活，除非你照我說的去做。去尋找我需要的材料吧，這對我們都有好處——當然，或者我們都會丟掉性命，但是我已經解釋過了……','如果你將1件被玷汙的長袍、25塊布衣碎片、4張月布和2塊連結水晶交給東瘟疫之地聖光之願禮拜堂的憤怒者瑪塔烏斯，他會為你製作一件瘟疫之心長袍。','','去東瘟疫之地找聖光之願禮拜堂的憤怒者瑪塔烏斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9104 AND `locale` = 'zhTW';
