INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9119, 'zhTW', '西部聖所的故障', '既然你在這裡，$N，我有一個忙想請你幫。牧地看守者維蘭妮雅的學徒先前來這裡尋求協助。明顯地在西部聖所有些錯誤運作發生。我又忙於招待我們的……最可愛的……矮人客人。你可以幫我個忙嗎?', '到永歌森林和西部聖所的牧地看守者維蘭妮雅談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9120 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9120, 'zhTW', '科爾蘇加德的墮落', '骨匣是納克薩瑪斯主人所留下來全部的遺物。你最好是摧毀骨匣以防巫妖再次形成。幸好，你很少聽信內心的理智。$B$B聖光之願的某人會為此給予你極大的獎勵。誰在乎科爾蘇加德再生至全能力量?', '將科爾蘇加德的骨匣帶到東瘟疫之地的聖光之願禮拜堂。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9121 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9121, 'zhTW', '可怕的堡壘 - 納克薩瑪斯', '在濃密的病木林裡有個入口通往納克薩瑪斯的可怕堡壘。以前，任何想嘗試進入的人都被符文傳送門外的魔法守衛擋下來。直到現在。$B$B我們設計了一個方法，透過一個永久的秘法掩護 - 肯瑞托的古老咒語加上一些我自己做的修改。說到這，那個披風是要錢的。由於你對銀色黎明的貢獻稍嫌不足，$N;價格會不低。你可以選擇達到崇敬或崇拜後再來換取折扣。', '東瘟疫之地聖光之願禮拜堂的大法師安琪拉·多桑杜需要5個秘法水晶，2個聯結水晶，1個正義寶珠和60金。你一定要在銀色黎明達到尊敬聲望。', '', '去東瘟疫之地找聖光之願禮拜堂的大法師安琪拉·多桑杜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9122 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9122,'zhTW','恐怖之城，納克薩瑪斯','病木林深處就是納克薩瑪斯的宮殿入口。那兒的符文傳送門被魔法結界籠罩，一般人是根本進不去的，不過現在不一樣了。$B$B我們已經想出了破除結界的方法——奧術遮罩。我對肯瑞託古老的咒語進行了一些修改，使它具備了破除納克薩瑪斯結界的能力。我說過，這種咒語價格不菲，但是你對銀色黎明的貢獻令人非常敬佩，我們會給你打個折扣的。','東瘟疫之地聖光之願禮拜堂的大法師安吉拉·杜薩圖斯需要2塊奧術水晶、1塊連結水晶和30金幣。你在銀色黎明中的聲望必須達到崇敬。','','去東瘟疫之地找聖光之願禮拜堂的大法師安吉拉·杜薩圖斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9123 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9123,'zhTW','可怕的堡壘 - 納克薩瑪斯','在濃密的病木林裡有個入口通往納克薩瑪斯的可怕堡壘。以前，任何想嘗試進入的人都被符文傳送門外的魔法守衛擋下來。直到現在。$B$B我們設計了一個方法，透過一個永久的秘法掩護 - 肯瑞託的古老咒語加上一些我自己做的修改。說到這，那個斗篷是要錢的；不過，你對銀色黎明的貢獻不可動搖!我們會取消所有的費用。','東瘟疫之地聖光之願禮拜堂的大法師安琪拉·多桑杜將免費給你秘法掩護。你一定要在銀色黎明達到崇拜聲望。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9124 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9124, 'zhTW', '地穴行者護甲的零件……', '想不想自己賺一些閃亮的錢幣啊?$B$B<里歐波拿著一枚十字軍的徽記。>$B$B我有一個小麻煩你或許能幫我，$N。你知道，我為那些夠愚笨想進入納克薩瑪斯的人製作地穴行者護甲。雖然他們會給我製作護甲需要的熔核材料，我還是缺少地穴惡魔部位。幫我帶一束回來，我就會給你一枚徽記 - 可以在軍需官那裡使用。', '東瘟疫之地聖光之願禮拜堂的獵人里歐波要30個地穴惡魔部位。', '', '去東瘟疫之地找聖光之願禮拜堂的獵人里歐波。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9125 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9125,'zhTW','地穴魔的碎塊','','','','去東瘟疫之地找聖光之願禮拜堂的獵手雷奧普德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9126 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9126, 'zhTW', '骨鐮掘鏟', '胡力歐的骨鐮護甲樣式需要骨頭碎片 - 大量的骨頭碎片。雖然那些瘋狂的人會冒險進入納克薩瑪斯為我帶來足夠的熔核材料製作護甲，但我總是在尋找更多的天譴軍團骨頭碎片。$B$B你覺得怎麼樣?有興趣捲起袖子殺幾個天譴軍團的人嗎?這是個雙贏的情勢。', '東瘟疫之地聖光之願禮拜堂的『刺客』羅漢要30個骨頭碎片。', '', '去東瘟疫之地找聖光之願禮拜堂的『刺客』羅漢。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9127 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9127,'zhTW','白骨碎片','','','','去東瘟疫之地找聖光之願禮拜堂的殺手洛汗。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9128 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9128, 'zhTW', '元素方程式', '你好冒險者!你有興趣接一些工作嗎?我付徽記給我底下工作的人。這些徽記可以在軍需官那裡購買能量的物品。$B$B我要你做的就是盡可能給我帶來元素之核。越多越好!$B$B你會在我們世界中不同形狀大小的元素上找到它們。', '東瘟疫之地聖光之願禮拜堂的大法師安琪拉·多桑杜要30個元素之核。', '', '去東瘟疫之地找聖光之願禮拜堂的大法師安琪拉·多桑杜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9129 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9129,'zhTW','元素之核','','','','去找東瘟疫之地的大法師安吉拉·杜薩圖斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9130 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9130, 'zhTW', '銀月城的貨物', '歡迎志願者!我們現在物資稍嫌短缺，但血精靈已允諾給我們物資上的援助。那是你剛剛走進來的地方。$B$B我要你帶著這個提貨單去找飛行師·日翼。他會給你進一步的指示，告訴你如何快速到達銀月城。', '把軍需官里莫的提貨單送到安寧地的飛行師·日翼那裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9131 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9131, 'zhTW', '訂做無畏護甲', '你有看過無畏護甲嗎，$c?沒有，你當然沒看過。你還是個<小男孩/小女孩> - 一個小頑童。讓我告訴你，它超棒的。$B$B你大概在問你自己這和你有什麼關係，對吧?我跟你說，蠢蛋;我需要黑鐵碎塊，我願意付錢，碎塊越多越好。$B$B我需要碎塊為我們的戰士組成無畏套裝。幫我帶碎塊來就能拿錢。', '東瘟疫之地聖光之願禮拜堂的柯菲斯要30個黑鐵碎塊。', '', '去找東瘟疫之地的『聖光勇士』柯菲斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9132 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9132,'zhTW','黑鐵碎片','','','','去找東瘟疫之地的科爾法克斯，聖光之勇士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9133 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9133, 'zhTW', '飛往銀月城', '$C，你只要付一點點錢給我，我就可以讓你坐在這種極佳的野獸身上快速地翱翔空中。而且這比在這邊走路要安全多了，我向你保證!$B$B等你到了銀月城，去找商店街的賽詩倫·藍晨。$B$B等你決定好要在空中飛翔後再和我談談。', '飛回銀月城並將軍需官里莫的提貨單交給銀月城的賽詩倫·藍晨。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9134 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9134, 'zhTW', '女飛行師·薄暮', '嗯，你看起來不像有台運貨車或馱獸的樣子，所以我只讓你帶回能裝載的量好了。如果你已經和安寧地的飛行師·日翼談過了，那你就要盡快飛回去把這個送給軍需官里莫。$B$B把這些貨物送給銀月城牧羊人之門外的女飛行師·薄暮做最後的檢驗。', '將軍需官里莫的物品帶給銀月城牧羊人之門外的女飛行師·薄暮。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9135 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9135, 'zhTW', '回到軍需官里莫那裡', '我已經全部都檢查過了。在我看來被遺忘者已經為我們做好一切的準備了，即使他們全都又醜又腐敗，我們還是欠他們一份人情。$B$B所以問題是，你和安寧地的飛行師·日翼談過了嗎?如果是，那麼你就付了錢，快點飛回那裡。$B$B等你準備好再讓我知道。', '飛回鬼魂之地的安寧地，將軍需官里莫的貨物帶回鬼魂之地交給安寧地的軍需官里莫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9136 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9136, 'zhTW', '野性植物群', '我為進入夢幻步行者納克薩瑪斯的勇敢英雄製作一種特殊的護甲。他們能提供我大部份製作的材料，但我總是在尋找能夠從我們世界的野性植物群取得野性藻葉的人。$B$B你可能覺得這個任務過於簡單，但沒有藻葉也不能製作護甲。$B$B我還有一個獨特的身分能夠讓你選擇支柱我資金的黎明或十字軍徽記。', '東瘟疫之地聖光之願禮拜堂的瑞恩要30個野性藻葉。', '', '去找東瘟疫之地的瑞恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9137 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9137,'zhTW','蠻荒之葉','','','','去東瘟疫之地找聖光之願禮拜堂的萊茵。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9138 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9138, 'zhTW', '日冠村', '我們全都圍繞在這裡，$c。邊遠的村子都被天譴軍團侵犯了。$B$B你必需立刻朝東北方前往日冠村並對付奈幽蟲族的天譴勢力。你千萬不能放過它們 - 它們長得就像蜘蛛一樣的怪物。$B$B沒有時間可以浪費了……一定要收復奎爾薩拉斯!', '殺死10個奈幽碧斯守衛，再回到鬼魂之地的安寧地找秘法師范德隆。', '', '去找幽魂之地的秘法師范德隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9139 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9139, 'zhTW', '金霧村', '我們已經有了一次成功的經驗，但是，還有兩個村子也需要對付!$B$B金霧村是我們下一個目標。它在西北邊，過去由住在那裡的高等精靈鬼魂接管。很可怕，我知道，但這些是對抗天譴軍團的策略。$B$B前往那裡擊敗鬼魂和怨靈，$c。順著西邊的路走出安寧地到達那裡。', '到金霧村擊敗6個奎爾多雷鬼靈和4個奎爾多雷怨靈，再回到鬼魂之地的安寧地找秘法師范德隆。', '', '去找幽魂之地的秘法師范德隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9140 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9140, 'zhTW', '風行者村', '$N，最後一場對抗鬼魂之地村莊的戰役就要來臨。西南邊的風行者村已被一支更強大的天譴軍團突擊兵、鬼怪和怪獸接管了。我需要你再次帶領我們的防禦先鋒去削弱他們的勢力。$B$B但是附近太陽聖所的博學者提出了特別的要求;他們要研究這些天譴軍團的遺物以找出有效的方法來擊敗他們。$B$B祝你好運!', '收集6份幻魅實體和4份石像鬼碎片並帶到鬼魂之地的安寧地給秘法師范德隆。', '', '去找幽魂之地的秘法師范德隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9141 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9141, 'zhTW', '他們叫我「鬥士」', '你想要一份令狀?什麼?你一出現我就要把一份高詢問度的工作令交給你?我不這麼認為，笨蛋。全世界的工匠都爭相搶著前線這裡的工作，你必須向我證明你願意為理想流血流汗。幫我帶來勇氣勳章我們再談。$B$B只有一個方法能讓你骯髒的小蠢手得到勳章 - 大開殺戒!', '東瘟疫之地聖光之願禮拜堂的發送指揮官梅茲想要一枚銀色黎明勇氣勳章。', '', '去找東瘟疫之地的發送指揮官梅茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9142 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9142,'zhTW','工匠文書','','','','去找東瘟疫之地的物資官員梅茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9143 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9143, 'zhTW', '與札布索拉交涉', '中尉沒有先評估狀況就直接派我們上戰場與湖那邊的食人妖作戰，我們的部隊被他的愚蠢害慘了!你聽到我說什麼了嗎，湯瑪索?你這個白痴!$B$B你會幫我們吧，$c? 這些食人妖仍然需要處理一下，而我必須留在這保護這傢伙 -- 我想他已經瘋了。$B$B只要往東走到湖的另一邊進入札布索拉。我要復仇……帶一些他們的耳朵回來給我，這樣我就可以做一條漂亮的項鍊了。', '收集6個札布索拉食人妖耳朵再回到鬼魂之地找遊俠瓦拉娜。', '', '去找幽魂之地的遊俠瓦拉娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9144 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9144, 'zhTW', '鬼魂之地的失蹤者', '我的姪子幾天前被派到鬼魂之地去。他從沒提過關於任務的事，只有說是極機密的類型。他之後再也沒回來，我擔心最糟的事會發生，$c。一個失蹤的信差對冷酷無情的銀月城博學者來說可能不算什麼，但他的父母將他托付給我。他就像是我自己的孩子一樣。拜託，$N，可以幫忙找找他嗎?', '沿著晴風村外面的路往南走，到鬼魂之地找信差晨行者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9145 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9145, 'zhTW', '幫幫遊俠瓦拉娜!', '$C，我不能枯坐在這裡等待高級執行官或阿莉法娜奧絲夫人接見我!這可不能等!我們要到艾蘭達之湖東北邊對付札布索拉的影松食人妖。但是中尉沒有處理好這次的攻擊使我們失去了很多遠行者。接著之後他就一蹶不振了。遊俠瓦拉娜派我來這裡，而遊俠沙里莎則是被派往遠行者營地尋求協助。請找到他們，$c。瓦拉娜傷的很重而中尉一點用處都沒有。', '到日冠村附近的鬼魂之地找到遊俠瓦拉娜與湯瑪索倫中尉，他在艾蘭達之湖的湖岸邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9146 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9146, 'zhTW', '向希里歐斯隊長回報', '$c，我要請你幫最後一個忙。以防萬一遊俠沙里莎沒辦法回到湖南邊的遠行者營地，我要你去那裡幫忙。和希里歐斯隊長談談，讓他知道這裡發生了什麼事。我相信他會盡快派支援回來。', '到鬼魂之地的艾蘭達之湖南邊，和遠行者營地的希里歐斯隊長談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9147 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9147, 'zhTW', '倒下的信差', '你在這站著做什麼?你看不出來這個小男孩需要立刻被治療嗎?看他的樣子，瘟疫已然開始蔓延到他整個身體。幾分鐘後就連像我這樣的大藥劑師都無法拯救他。$B$B小河南邊的動物全都流著感染瘟疫的血液。到橋的另一邊捕獵感染瘟疫的野獸。幫我帶來足夠的瘟疫血液樣本，我就能提煉出血清救這血精靈一命。快!', '永歌森林的藥劑師泰德拉要你幫她從鬼魂之地的野獸身上帶來4份感染瘟疫的血液樣本。', '', '去找永歌森林的藥劑師泰德拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9148 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9148, 'zhTW', '送貨至安寧地', '我……我太虛弱了沒辦法繼續。我身上有一封來自地區統治者塞隆的緊急警告信，拿著這個包裹。你一定要將它交給安寧地的秘法師范德隆。$B$B沿著這條路往南走你會看到一個村莊。快去……找到范德隆……', '將銀月的信件送到鬼魂之地交給安寧地的秘法師范德隆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9149 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9149, 'zhTW', '感染瘟疫的海岸', '瘟疫以不同的方式感染不同的生物。它影響動物生理機能的方式看來和影響人類或精靈的方式沒有什麼不同。$B$B我想研究一下感染瘟疫的鬼魂之地海岸，那裡有一群魚人。前往西北方並幫我帶來他們的脊椎，這樣我才能研究一下他們骨髓裡累積的瘟疫病毒。', '將6個感染瘟疫的魚人脊椎帶到鬼魂之地給安寧地的藥劑師倫澤紳。', '', '去找幽魂之地的藥劑師倫澤紳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9150 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9150, 'zhTW', '搶救過去', '你相信嗎?我們擁有一座真正在東南方運作的秘法聖所:太陽聖所。各有專精的重要博學者都來共襄盛舉。$B$B當然他們都已經忘了明月聖所。明月聖所遺留下來的東西並不多，而且它提升了奇異生物的能量。$B$B不過，我不是一個會浪費好資源的人。前去明月聖所，看看你能不能從生物身上找到晶化的精華。', '博學者戴倫尼斯要你前往安寧地西邊的明月聖所並從住在那棟建築物的秘法吞噬者和法力轉移蟲身上取回8個晶化法力精華。', '', '去找幽魂之地的博學者戴倫尼斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9151 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9151, 'zhTW', '太陽聖所', '你已證明你對安寧地的忠誠，並協助我們抵抗天譴軍團的威脅。我們有一些強大的博學者已經從銀月城趕來協助我們進攻敵人的據點。他們已經在南方重建了秘法聖所，且將附近區域的天譴軍團勢力趕走。他們計劃進攻死亡之域，達克汗的堡壘。你最好趕快加入他們，$N。我相信他們會善用像你一樣經驗豐富的$c。', '到鬼魂之地和太陽聖所的博學者艾度尼斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9152 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9152, 'zhTW', '土柏的貨物', '如果我連安全地讓我的物資運到這裡都沒有辦法，我要如何提供戰事補給?有人允諾要護送我但他卻從未出現。接著，我得在西邊丟下我的一輛貨車因為我被一群食屍鬼給攻擊!$B$B想幫忙，想讓我的生意開張嗎?沿著西邊的路走出城外通過墓地。在死亡之痕的另一邊有一個岔路。我的貨車就在那山丘後面。', '取回拉提斯·土柏的貨物並回到鬼魂之地的安寧地交給他。', '', '去找幽魂之地的拉提斯·土柏。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9153 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9153,'zhTW','陰影之下','那些漂浮在空中的天災浮空城汙染了部落和聯盟的土地。塔納利斯、詛咒之地、冬泉谷和燃燒平原都籠罩在它們的陰影之下。$B$B我們只有協力作戰，才能消滅敵人。$B$B在天災入侵之地，有多處魔法陣支援著這些浮空城。我們決定要攻破法陣周圍的防禦勢力。','在你的地圖上尋找天災入侵的地區。擊敗浮空城周圍的天災士兵，摧毀一處浮空城。將10塊死靈石交給東瘟疫之地聖光之願禮拜堂的指揮官托馬斯·海勒拉。','','去東瘟疫之地找聖光之願禮拜堂的指揮官托馬斯·海勒拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9154 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9154,'zhTW','聖光之願禮拜堂','天災軍團糾集了浩浩蕩蕩的部隊向我們發動了反攻，妄圖憑藉數量取勝。銀色黎明現在招募所有有戰鬥能力的有志之士，無論男女，共同保衛我們的家園。$B$B如果我們站在同一陣線，請將這份檔案交給東瘟疫之地聖光之願禮拜堂的名單登記員。','將徵兵公告交給東瘟疫之地聖光之願禮拜堂的名單登記員。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9155 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9155, 'zhTW', '進入死亡之痕', '既然你都走了這麼遠，那麼你應該知道死亡之痕的事，還有為何無腦的天譴軍團到今天都還跟隨著阿薩斯在去銀月城的路上創造的摧毀之路。$B$B做點有用的事，削減死亡之痕裡面的天譴軍團數量。如果你能證明自己的能力我就會多幫你說些好話。', '殺死死亡之痕的10個重生的飢餓者和10個笨拙的食人者。再回到安寧地找亡靈哨兵瑞希爾領取獎勵。', '', '去找幽魂之地的亡靈哨兵瑞希爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9156 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9156, 'zhTW', '懸賞:納克羅和路斯萊恩', '只要抓到可恨的納克羅和路斯萊恩就可以得到一筆賞金。這些達克汗的可怕生物相當危險，有人看過他們在哀嚎通靈塔和血色通靈塔附近巡邏。想領取賞金的人必須將它們的頭顱交給亡靈哨兵瑞希爾做為成功的證據。', '前往鬼魂之地找到納克羅和路斯萊恩。把他們的頭顱帶到安寧地給亡靈哨兵瑞希爾以領取賞金。', '', '去找幽魂之地的亡靈哨兵瑞希爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9157 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9157, 'zhTW', '被遺忘的儀式', '日冠村的居民每年都會參加一個儀式讓各個自然之貌都在掌控之中。召喚並奴役一個稱為海之平衡的元素象徵著我們對水元素的統治。但是海之平衡竟突破了我們魔法的邪惡乖僻，衝破它的束縛反過來奴役我們!$B$B參與儀式的人都會佩帶形狀像波浪的勳章。到湖底去尋找這些東西;我們需要這些東西來重建對海之平衡的統治權並再次解放我們的靈魂。', '帶8個浪鋒勳章給鬼魂之地的傑若尼斯·白晨。', '', '去找幽魂之地的傑若尼斯·白晨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9158 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9158, 'zhTW', '削弱瘟疫', '你敢來鬼魂之地已經是展現了你的勇氣，$N。這裡有更多的工作等著完成但勇敢的人總是不多。$B$B如果你有意願幫助我們的事業，我有個吃力不討好的工作要給你。這片土地上的野生生物已遭到瘟疫的感染而我們務必要阻止它散播。獵殺東邊和南邊的鬼爪暗殺者，殺夠了再回來找我。', '鬼魂之地的遠行者·賽狄娜要你去殺10個鬼爪暗殺者。', '', '去找幽魂之地的遠行者賽狄娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9159 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9159, 'zhTW', '遏止瘟疫', '你已經證明了一個盟友的價值，$N。我要你繼續你的任務並追蹤更多感染瘟疫的野生生物。這次去找更危險的野獸。去死亡之痕的西邊獵捕細網潛伏者再到這裡的南邊獵捕吸血迷霧蝙蝠。完成後再回來找我。', '鬼魂之地，遠行者營地的遠行者·賽狄娜要你去殺死8隻細網潛伏者和10隻吸血迷霧蝙蝠。', '', '去找幽魂之地的遠行者賽狄娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9160 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9160, 'zhTW', '調查安都拉斯', '$C，我們的麻煩是一群最近接管附近一座島嶼的夜精靈。他們在舊的高等精靈能量界線連結點，安都拉斯那裡紮了一個小營地，就在西北方。過了死亡之痕有一條泥巴路就通往那裡。$B$B我非常希望你能幫我們前往那裡，調查他們都在做些什麼並殺死越多自負的夜精靈越好。', '調查安都拉斯，殺死12名崗哨間諜再回到鬼魂之地的安寧地找阿莉法娜奧絲夫人。', '調查安達洛斯', '去找幽魂之地的阿莉法娜奧絲夫人。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9161 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9161, 'zhTW', '背叛者的陰影', '人們相信達克汗·崔希爾已經復活在鬼魂之地，要統治天譴軍團的軍隊。達克汗很久前就與天譴軍團結盟……而他現在又是一個活生生的精靈。他大部份的時間都待在東北方的晨星尖塔裡面。他在那裡藏了很多夜，密謀策劃。搜索哨塔尋求更多情報，$N。搞不好他有日記或記筆記的習慣。我們永遠不知道有用的訊息會在哪裡冒出來。', '前往鬼魂之地的晨星尖塔並尋找任何與達克汗的過去有關的蛛絲馬跡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9162 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9162, 'zhTW', '過去的線索', '當你翻閱日記的書頁時一種被監視的不安感排山倒海而來。$B$B其中的內容使人很不安。達克汗的靈魂對他自己的人民是充滿仇恨和蔑視的。他的陰謀和詭計都以詳細的文字記錄在其中。$B$B或許薇娜會發現裡面有些有用的東西。', '帶著達克汗的日記回到遠行者營地找遊俠薇娜。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9163 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9163, 'zhTW', '進入被佔據的土地', '$c，如我所說，如果我們要搞清楚這些夜精靈到底在做什麼，就要採取更直接的行動。我的偵察兵告訴我，他們還沒有足夠的軍力或物資可以入侵，而且我們的船隻也沒有接獲夜精靈變換位置的消息。$B$B所以，我要你做的是沿著出城往薩藍迪斯小島的路向西邊走，就在離岸邊不遠的海面。前往那裡取回任何他們在島上或船上的計畫書。', '偷取夜精靈的計畫:安都拉斯，夜精靈的計畫:安歐恩和夜精靈的計畫:占卜辛多雷，然後帶回鬼魂之地給安寧地的阿莉法娜奧絲夫人。', '', '去找幽魂之地的阿莉法娜奧絲夫人。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9164 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9164, 'zhTW', '死亡之域俘虜', '啊，是的。我最棒的創作之一。這個藥膏將化解大部分由鍊金引發的恍惚。$B$B副作用包括了混淆，噁心和 - 較罕見的情形 - 暫時的致盲。如果你問我，這全都比天譴軍團打算對那些死亡之域的囚犯做的事要好的多。$B$B祝你好運，$c。你會需要它的。', '帶著倫澤紳製作的恢復藥劑前往死亡之域解救學徒瓦尼司，藥劑師艾尼斯和遊俠維多蘭。然後再回到太陽聖所向秘法師珍妮達領取獎勵。', '', '去找幽魂之地的秘法師珍妮達。', '藥劑師艾尼斯獲救', '學徒瓦尼司獲救', '', '遊俠維多蘭獲救', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9165 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9165, 'zhTW', '安全之路令狀', '如果沒有冒險者的幫忙，我的商隊絕不可能成功!天譴軍團已經停下他們的木工活，想阻止我們進入那裡。$B$B<守衛迪笛兒擦了擦他的額頭。>$B$B現在我們要在這裡等待戰場元帥錢柏到達。他會簽署你的安全之路令狀讓你帶回聖光之願禮拜堂的發送指揮官梅茲那裡。$B$B還有$N，在錢柏面前講話可要小心。他是那種會咬斷你的頭刺穿你氣管的人 - 只是他不一定會這麼做……', '將簽署的安全之路令狀送到東瘟疫之地給聖光之願禮拜堂的發送指揮官梅茲。', '', '', '', '簽署過的安全之路令狀', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9166 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9166, 'zhTW', '送計畫書到安泰拉斯', '$N，我想請你替我去安泰拉斯一趟。我要你帶著你在薩藍迪斯小島發現的夜精靈計畫一起去。$B$B安泰拉斯在東邊，就在日傷山峰的南邊斜坡上，太陽聖所的東北方。博學者塞拉斯特在那裡進行能量界線連結能量的研究。他可能會讓我們更清楚那些夜精靈在做些什麼。$B$B請照他的話去做。', '將夜精靈的計畫送到鬼魂之地給安泰拉斯的博學者塞拉斯特。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9167 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9167, 'zhTW', '叛國者的毀滅', '我們在鬼魂之地所做的一切都是為了一個目標，那就是奪回所有我們應有的。天譴軍團掌控該區域的重要據點夠久了。$B$B復仇的時刻來臨了，$N。謝謝你和新盟友，被遺忘者的幫忙，我們很快就能復仇成功了。$B$B想偷取太陽之井能量的人都得死。前往死亡之域，天譴軍團堡壘南方的死亡之痕。幫我把達克汗的頭顱帶來，你的作為會千古流芳!', '殺死死亡之域的達克汗·崔希爾並把他的頭顱帶回鬼魂之地給太陽聖所的博學者坎德立斯。', '', '去找幽魂之地的博學者坎德立斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9168 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9168,'zhTW','戴索姆之心','我們的敵人躲在戴索姆深處，瘋狂地製造著強大而致命的亡靈士兵。那些令人憎惡的生物簡直就是完美的殺戮機器，達爾坎親手製造了他們，戴索姆的黑暗魔法力量令他們變得更加強大。$B$B轉至達爾坎的要塞消滅那些亡靈士兵，$N。我們不但要鞏固自己在鬼魂之地的立足處，還要防止敵人擴展他們的勢力範圍。','殺死8個達爾坎之眼，然後向鬼魂之地太陽聖殿的魔導師伊東尼斯覆命。','','到鬼魂之地找博學者艾度尼斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9169 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9169, 'zhTW', '關閉安歐恩水晶', '他們的月水晶是占卜儀器 - 他們要監視我們!就我所知安都拉斯無法提供他們所需的能量，但正南方的安歐恩則絕對可以!$B$B從這些計畫中我對他們的寶珠有了基本的認識;足以關閉它們。它們被鎖上了所以才能被關閉。你一定要前往安歐恩從其中一個夜精靈手中拿到控制寶珠，再使用在月水晶上才能阻止夜精靈的計畫!$B$B快，$c!', '取得水晶控制寶珠並使用它關閉安歐恩的夜精靈月水晶。再回到鬼魂之地的安泰拉斯找博學者塞拉斯特。', '', '去找幽魂之地的博學者塞拉斯特。', '已關閉夜精靈月水晶', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9170 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9170, 'zhTW', '達克汗的中尉', '可憎的達克汗，已在天譴軍團間重拾了強大的力量。他的副官們率領大批的不死族軍隊對抗我們日益減少的子民。$B$B黑衣瑪蘇霏爾，『欺詐者』裘萊恩，『放血者』伯格斯，『墮落者』米爾多藍。記好這幾個傢伙的名字，因為他們的地位在鬼魂之地這些領導者當中僅次於達克汗。只要殺死他們，那些無腦的天譴軍團就會陷入一片混亂。', '博學者艾度尼斯要你到死亡之域冒險，殺掉黑衣瑪蘇霏爾、『欺詐者』裘萊恩、『放血者』伯格斯和『墮落者』米爾多藍。任務完成之後到鬼魂之地的太陽聖所向他報告。', '', '去找幽魂之地的博學者艾度尼斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9171 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9171, 'zhTW', '香脆料理', '這實在是令人無法忍受!我在這裡沒有一點材料可以使用!夫人要我從銀月城過來;她需要適合她身份地位的料理。不是嗎?但是我來到這裡卻找不到食物。你一定要到外面去，$c，帶回新鮮的食材讓我有東西可做。$B$B阿莉法娜奧絲夫人喜歡吃香香脆脆的食物。死亡之痕另一邊的西南方有大量的細網潛伏者。很噁心，我知道，但那就是我們需要的材料。', '收集5隻香脆蜘蛛腿帶回鬼魂之地給安寧地的大廚師瑪戴爾。', '', '去找幽魂之地的大廚師瑪戴爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9172 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9172, 'zhTW', '向博學者坎德立斯回報', '太陽聖所的博學者有了被遺忘者的幫助後，已經在分析天譴軍團的弱點上有了極大的進展。博學者坎德立斯會知道要拿這些資訊做什麼。$B$B太陽聖所就在這邊的西南方。你要加快腳步，$N。達克汗是個狡猾的敵人，監視著我們的每個動作!', '將達克汗的日記帶回鬼魂之地交給太陽聖所的博學者坎德立斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9173 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9173, 'zhTW', '奪回風行者塔', '$C，我要你奪回風行者之塔!$B$B這是一項榮譽，真的。風行者塔是被遺忘者女王，希瓦娜斯·風行者原本的家。但現在已被天譴軍團侵擾。$B$B想要到那裡就往南一直走到岔路口。往右邊的岔路進去，過了死亡之痕後繼續往西南方。你絕對不會錯過它的。', '殺死8名死亡之域侍僧和10名遊俠靈魂，再回到鬼魂之地的安寧地找高階執行官瑪弗倫。', '', '去找幽魂之地的高階執行官瑪弗倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9174 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9174, 'zhTW', '消滅海之平衡', '那個固執的元素在反叛我們那天結束了許多人的生命。藉著召集卑微的魚人來破壞我們的祭儀，他推翻了我們的魔法並將它轉而與我們作對。$B$B讓他知道我們復仇的渴望絲毫沒有削減!帶著這些勳章並把它們放在湖底的潮汐專精聖壇裡。海之平衡會立刻回應你們的召喚!$B$B小心點，$r!沒有我們的魔法控制他，他的憤怒會變的非常放肆。摧毀海之平衡我們才能安息!', '傑若尼斯·白晨要你游到日冠村東邊的湖底並在潮汐專精聖壇使用一堆勳章。召喚並殺死一個叫海之平衡的元素再回到傑若尼斯那裡。', '', '去找幽魂之地的傑若尼斯·白晨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9175 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9175, 'zhTW', '女士的項鍊', '項鍊閃著光，這件出眾的珠寶似乎不受鬼魂之地籠罩的陰鬱影響。依照上面的銘文和你發現它的地點，它一定是希瓦娜斯·風行者丟失的財產!$B$B或許把它先送到安寧地的高階執行官瑪弗倫會是最好的辦法?他好像是這附近最高階的被遺忘者，一定知道該如何處置它。', '將女士的項鍊帶到鬼魂之地給安寧地的高階執行官瑪弗倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9176 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9176, 'zhTW', '雙子通靈塔', '根據這本日記，達克汗向天譴軍團允諾了兩樣強大的精靈手工藝品:聖光之石和火焰之石。這兩樣東西都注入了太陽之井的魔法能量，而且已協調至具有對抗天譴軍團的保護力量。$B$B水晶之前被傳送至哀嚎通靈塔和血色通靈塔現在的所在位置，就在死亡之痕中間。如果它們仍然在那裡，我們就必須取得它們。它們的能量對我們抵抗敵人的侵略非常有用。', '前往哀嚎通靈塔和血色通靈塔取回聖光之石與火焰之石。取得物品後回到太陽聖所找博學者坎德立斯。', '', '去找幽魂之地的博學者坎德立斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9177 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9177, 'zhTW', '幽暗城之旅', '這還真特別!這應該就是希瓦娜斯·風行者的姊姊，艾蘭里亞送的禮物吧!$B$B你一定要立刻把它帶到幽暗城給她。希瓦娜斯·風行者就在皇家區宮廷裡。$B$B要到那裡，你要去銀月城的日怒尖塔，使用內聖所的傳送寶珠到幽暗城。到了那裡，乘坐電梯進入城裡。查閱地圖可以找到皇家區。', '將女士的項鍊帶給幽暗城皇家區的希瓦娜斯·風行者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9178 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9178, 'zhTW', '工匠令狀 - 緻密平衡石', '這張令狀的持有人在完成訂定的工作後會以徽記的形式得到獎賞。$B$B工作令BS-091:$B$B120個緻密平衡石。$B$B所有完成的工作令都要送到東瘟疫之地給聖光之願禮拜堂的軍需籌備官石漢。$B$B一旦契約遭到損壞或篡改一律視為無效。$B$B-發送指揮官梅茲，銀色黎明', '將120個緻密平衡石和工匠令狀 - 緻密平衡石 - 帶到東瘟疫之地給聖光之願禮拜堂的軍需籌備官石漢 。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9179 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9179, 'zhTW', '工匠令狀 - 君王鎧甲護胸', '這張令狀的持有人在完成訂定的工作後會以徽記的形式得到獎賞。$B$B工作令BS-428:$B$B3個君王鎧甲護胸。$B$B所有完成的工作令都要送到東瘟疫之地給聖光之願禮拜堂的軍需籌備官石漢。$B$B一旦契約遭到損壞或篡改一律視為無效。$B$B-發送指揮官梅茲，銀色黎明', '將3個君王鎧甲護胸和工匠令狀 - 君王鎧甲護胸 - 帶到東瘟疫之地給聖光之願禮拜堂的軍需籌備官石漢 。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9180 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9180, 'zhTW', '幽暗城之旅', '這還真特別!這應該就是希瓦娜斯·風行者的姊姊，艾蘭里亞送的禮物吧!$B$B你一定要立刻把它帶到幽暗城給她。希瓦娜斯·風行者就在皇家區宮廷裡。$B$B要到那裡，你要去銀月城的日怒尖塔，使用內聖所的傳送寶珠到幽暗城。到了那裡，乘坐電梯進入城裡。查閱地圖可以找到皇家區。', '將女士的項鍊帶給幽暗城皇家區的希瓦娜斯·風行者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9181 AND `locale` = 'zhTW';
