INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9192, 'zhTW', '光底礦坑的麻煩', '這些麻煩的報告永無止盡的紛至沓來，$c。這裡又是另一個，顯然西南邊的光底礦坑已被一群自稱黑掌的豺狼人佔據。我不需要提醒你那些礦坑對我們在鬼魂之地的戰役而言是多麼重要的戰略性資產吧!$B$B踏上城外往南的路，沿著岔路往右走。走過右邊的通靈塔就就會看到西邊有一條短短的泥土小路。沿著它走。$B$B礦石是我們的!', '殺死8個黑掌豺狼人，6個黑掌覓食者和4個黑掌薩滿，再回到鬼魂之地的安寧地找亡靈守衛瑪塔堤斯。', '', '去找幽魂之地的亡靈哨兵瑪塔堤斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9193 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9193, 'zhTW', '調查阿曼尼地下墓穴', '$C，我們的消息指出在日傷山峰阿曼尼地下墓穴裡的食人妖已起死回生。阿莉法娜奧絲夫人要你去調查這些地下墓穴並將所有未復活的遺體放火燒了，以免更多這些生物興起。$B$B到達那裡最快的方法就是往北走出城，在第一個岔路右轉。你就會到達山峰的北邊，再向南邊找尋入口。', '調查阿曼尼地下墓穴並燒毀10個屍化食人妖遺體再回到鬼魂之地的安寧地找諫言者法溫。', '調查阿曼尼地下墓穴', '去找幽魂之地的諫言者法溫。', '屍化食人妖遺體燒毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9194 AND `locale` = 'zhTW';
