INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9207, 'zhTW', '光底礦物樣本', '我從太陽聖所被派來這裡收集一些光底礦物樣本，但是豺狼人已經橫行於這個地方了!如果我不快點將那些樣本交給博學者，我就要人頭落地了。或許你可以幫我，$c?$B$B你可以在礦物節點找到樣本，而豺狼人身上也有攜帶它們。等你收集到足夠的數量請將它們交給太陽聖所的博學者奎壘司提斯。就在東邊，過了死亡之痕，日傷山峰的南邊。', '收集6個光底礦物帶到鬼魂之地的太陽聖所交給博學者奎壘司提斯。', '', '去找幽魂之地的博學者奎壘司提斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9208 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9208,'zhTW','野性戒衛 - 防護秘藥','贊扎可以使用適當的材料對你的裝備進行古老的魔法增強處理！你聽說過野性戒衛嗎？啊，你當然沒有聽說過。你滿腦子都是那些低階的暗夜精靈的魔法。$B$B給我拿來一份暗夜精靈的秘藥，我也許能重新為你附魔。去吧，我會把野性戒衛作為獎勵送給你的。','祖爾格拉布的無眠者贊扎需要一份防護秘藥。','','去找祖爾格拉布的無眠者贊扎。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9209 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9209,'zhTW','野性戒衛 - 急速秘藥','贊扎可以使用適當的材料對你的裝備進行古老的魔法增強處理！你聽說過野性戒衛嗎？啊，你當然沒有聽說過。你滿腦子都是那些低階的暗夜精靈的魔法。$B$B給我拿來一份暗夜精靈的秘藥，我也許能重新為你附魔。去吧，我會把野性戒衛作為獎勵送給你的。','祖爾格拉布的無眠者贊扎需要一份急速秘藥。','','去找祖爾格拉布的無眠者贊扎。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9210 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9210,'zhTW','野性戒衛 - 專注秘藥','贊扎可以使用適當的材料對你的裝備進行古老的魔法增強處理！你聽說過野性戒衛嗎？啊，你當然沒有聽說過。你滿腦子都是那些低階的暗夜精靈的魔法。$B$B給我拿來一份暗夜精靈的秘藥，我也許能重新為你附魔。去吧，我會把野性戒衛作為獎勵送給你的。','祖爾格拉布的無眠者贊扎需要一份專注秘藥。','','去找祖爾格拉布的無眠者贊扎。','','','','',0);
