INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9223, 'zhTW', '精良級軍備之戰-銀色黎明聲望尊敬', '你好，朋友。你想要用點黎明徽記或是十字軍徽記來換取一些強大的物品嗎?$B$B不過我必須要警告你，雖然你是的銀色黎明所尊敬的朋友，但是想要購買這些物品還需要一些額外的收費，我建議你去提升更高的聲望後再來考慮這些物品吧。', '付出20個黎明徽記和20個十字軍徽記就能換取銀色黎明藏寶庫裡的一樣強大的物品。', '', '去東瘟疫之地找聖光之願禮拜堂的軍需官米蘭達·布利洛克。', '', '', '', '', 0);
