INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9229,'zhTW','拉瑪蘭迪的命運','拉瑪蘭迪是兄弟會的一名戰士，早在銀色黎明成立之前他便是莫格萊尼閣下的學生了！當莫格萊尼的死訊傳來時，仇恨和憤怒充斥著他的心靈。$B$B試想一下吧，$N，一個被複仇的怒火佔據了心靈的人還能算個人嗎，無非是個被情緒操控的傀儡。拉瑪蘭迪在盛怒之下衝進了納克薩瑪斯的宮殿，想為恩師報仇……可惜是肉包子打狗。$B$B前往納克薩瑪斯的宮殿打探拉瑪蘭迪的下落吧。','進入納克薩瑪斯的宮殿，找到拉瑪蘭迪的下落。','','去找東瘟疫之地的科爾法克斯，聖光之勇士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9230 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9230,'zhTW','拉瑪蘭迪的寒冰之握','要修復這枚戒指可不是件容易的事兒，$N。瞧，它的原材料是取自天災建築物中形成的冰凍符文，例如納克薩瑪斯的宮殿。當然我還需要其它材料，但是你的主要任務就是找到冰凍符文。把我所需的材料拿來，我會讓這枚戒指重新恢復光澤的。','東瘟疫之地聖光之願禮拜堂的科爾法克斯要1個冰凍符文、1塊藍寶石和1塊奧金錠。','','去找東瘟疫之地的科爾法克斯，聖光之勇士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9231 AND `locale` = 'zhTW';
