INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9232,'zhTW','我只會唱這一首歌……','你自詡為銀色黎明的英雄，是嗎？克爾蘇加德手下的小嘍囉能輕鬆砍翻我軍最優秀的士兵，這是我親眼所見！像你這樣的蠢貨還想去納克薩瑪斯的宮殿？$B$B<威爾海姆嘆了一口氣。>$B$B呸，我還能有什麼選擇？你是我惟一的希望；我或許能幫上忙。$B$B“奧瑪裡恩悄悄地走，除了一份圖樣，他什麼都沒留……”，我只會唱這一首歌……嗯，我可以為你製作一條很棒的褲子，但是你得為我提供材料。','將2個冰凍符文、2個水之精華、2塊藍寶石和30金幣交給東瘟疫之地聖光之願禮拜堂的工匠威爾海姆。','','去東瘟疫之地找聖光之願禮拜堂的工匠威爾海姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9233 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9233,'zhTW','奧瑪裡恩的手冊','威爾海姆：$B$B當你翻閱這本手冊時，我已經嚥氣了——這對我來說是個解脫。我想告訴你，我臨死前還想著你和你那糟糕的商業頭腦。不幸的是，就工匠技能來說，送手冊給你的傢伙連你都不如。$B$B這本手冊記載了我生前研製的配方，可以讓手冊的持有者製造出任何他們想要的東西。我想你一定會向別人收取高額費用的，因為你就是這麼個混帳。$B$B我鄙視你，$B$B奧瑪裡恩','將奧瑪裡恩的手冊交給東瘟疫之地聖光之願禮拜堂的工匠威爾海姆。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9234 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9234,'zhTW','冰克護手','謝謝你與歐瑪利安，願他安息。我現在能製作冰克護手了，你只需要替我找來製作材料，以及支付一些工匠費就可以了。','東瘟疫之地聖光之願禮拜堂的鐵匠維爾海姆需要你帶給他5個冰凍符文，12個瑟銀錠，2個奧金錠，2個水之精華，還有200金。','','去東瘟疫之地找聖光之願禮拜堂的工匠威爾海姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9235 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9235,'zhTW','破冰護腕','感謝你和奧瑪裡恩（願奧瑪裡恩就此安息），現在我可以開始製作破冰護腕了。你要做的只是為我提供材料，並支付一筆小小的加工費。','將4個冰凍符文、12塊瑟銀錠、2塊奧金錠、2個水之精華和200金幣交給東瘟疫之地聖光之願禮拜堂的工匠威爾海姆。','','去東瘟疫之地找聖光之願禮拜堂的工匠威爾海姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9236 AND `locale` = 'zhTW';
