INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9241,'zhTW','北極護腕','感謝你和奧瑪裡恩（願奧瑪裡恩就此安息），現在我可以開始製作北極護腕了。你要做的只是為我提供材料，並支付一筆小小的加工費。','將4個冰凍符文、12個魔化皮、3個水之精華、3個熟化毛皮和200金幣交給東瘟疫之地聖光之願禮拜堂的工匠威爾海姆。','','去東瘟疫之地找聖光之願禮拜堂的工匠威爾海姆。','','','','',0);
