INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9246,'zhTW','冰鱗胸甲','謝謝你與歐瑪利安，願他安息。我現在能製作冰鱗胸甲了，你只需要替我找來製作材料，以及支付一些工匠費就可以了。','東瘟疫之地聖光之願禮拜堂的鐵匠維爾海姆需要你帶給他8個冰凍符文，24個厚蠍鱗，7個水之精華 ，5塊熟化毛皮，還有300金。同時你必須在銀色黎明達到崇拜聲望值，才能完成這項任務。','','去東瘟疫之地找聖光之願禮拜堂的工匠威爾海姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9247 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9247,'zhTW','聖光的召喚','$N，$B$B在過去的日子裡，你盡心盡力地為銀色黎明做出了傑出的貢獻。現在，在這緊要關頭，我們再次發出號召。$B$B$N，如果你願意伸出援手，就去東瘟疫之地聖光之願禮拜堂向名單登記員報道吧。','將名單登記員的信交給東瘟疫之地聖光之願禮拜堂的名單登記員。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9248 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9248,'zhTW','謙卑的饋贈','Ishnu-alah，$R。讓我看看能證明你殺死深淵議會領主的證據，我就獎勵你一件好東西，它能在你與其拉蟲人作戰時幫你一臂之力。','將一根深淵節杖交給希利蘇斯塞納里奧要塞的奧蕾爾·金葉。你在塞納里奧議會的聲望必須達到尊敬。','','去希利蘇斯找塞納里奧要塞的奧蕾爾·金葉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9249 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9249,'zhTW','40張獎券 - 高階獎品','','','','去找吉瓦斯·格里加特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9250 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9250,'zhTW','埃提耶什之杖','合成杖柄之後，從形狀上來看，守護者的傳說之杖埃提耶什只差法杖頂部和杖柄末端兩個部分了。還有個小問題就是：這根杖子蘊涵著薩格拉斯的邪惡力量。$B$B看看有誰能幫你找到殘餘的法杖碎片並且淨化那些邪惡的力量。','看看有誰能幫你找到法杖的最後兩個部分，並且淨化邪惡的力量。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9251 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9251,'zhTW','埃提耶什，被玷汙的傳說之杖','你很困惑為何自己還活在世上吧。畢竟，你擁有這麼一件邪惡的物品。沒有確切的答案，$N。我只是做我應該做的事兒罷了。$B$B克爾蘇加德就在納克薩瑪斯宮殿的王座上策劃著某個陰謀……他要找的東西在你手中，而你要找的東西在他手中。$B$B一位名叫布萊恩·銅鬚的矮人曾攜帶杖柄的末端進入安其拉，卻不小心將它遺失在了安其拉里面。$B$B一旦你成功拿到杖柄末端，就立即來找我吧。','塔納利斯時光之穴的阿納克洛斯要你找到埃提耶什的法杖頂部和埃提耶什的杖柄末端。','','去塔納利斯找時光之穴的阿納克洛斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9252 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9252, 'zhTW', '保衛晴風村', '我們已感覺到天譴軍團明顯提高攻擊行動，$N。我們快抵抗不住了，而且銀月城好像也沒有增援的跡象。協助我們削弱死亡之痕不死生物的數目，一起來保護這村莊。', '殺掉4個腐肢掠奪者、4個黑暗怨靈。然後回到遊俠塞瑞覆命，他在永歌森林的晴風村。', '', '去找永歌森林的遊俠塞瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9253 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9253, 'zhTW', '符文守護者德蘭', '天譴軍團有增無減的攻擊行動讓我相信，鬼魂之地邊界那裡的某個防禦符文石一定發生故障。我們用這些古老的石頭來保護我們不受不死族傷害。它們大部分都在太陽之井的攻擊後被摧毀或不見了。朝著鬼魂之地的方向沿著路往南走，往西邊看就會發現一條小徑。你會在附近的一個符文石看到符文守護者德蘭;他會知道發生了什麼問題。', '與永歌森林的符文守護者德蘭談話，他在鬼魂之地邊界附近。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9254 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9254, 'zhTW', '遊蕩者學徒', '感謝你的幫忙，$N。當我整頓好這裡的事情時，我想請你幫個忙。我之前的一個學徒捲入了危險的研究調查。她前往了東部聖所，就在死亡之痕中間。我擔心她的安危。你能不能幫我把她找回來，並說服她找回自己。', '與東部聖所的學徒莫維達談話，位置在永歌森林。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9255 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9255, 'zhTW', '研究報告', '雖然我的研究結果令人沮喪，這份資料還是有可取之處。我要在這份報告被正視之前，先讓博學者檢視一下我的成果。拜託你，把這些報告拿給西邊晴風村的博學者蘭德拉·晨行者。', '把研究報告帶到永歌森林交給晴風村的博學者蘭德拉·晨行者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9256 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9256, 'zhTW', '晴風村', '我有另一個任務要給你，$N。遊俠迪哥里恩被派去晴風村找尋更多有關鄙惡者攻擊附近船廠的線索。他正尋求增援，可是我們還不能幫忙。去找到他，然後盡你全力去幫助他吧。沿著內精靈之門這條路一直往南走就能找到晴風村了。祝你好運，$N。', '到永歌森林與晴風村的遊俠迪哥里恩談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9257 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9257,'zhTW','埃提耶什，守護者的傳說之杖','艱鉅的任務總在最後，$N。你已經擊敗了一位上古之神和一位巫妖王的大將，現在是面對薩格拉斯的時候了。$B$B帶上這根杖子轉至斯坦索姆。你會在那兒發現一處神聖之地：洛丹倫最偉大的騎士們的埋骨之處。將這柄被玷汙的傳說之杖放在神聖之地中，準備好挑戰被驅趕出法杖的可怕生物……擊敗控制著法杖的惡魔，然後再回來找我。','塔納利斯時光之穴的阿納克洛斯要你轉至斯坦索姆，在神聖之地上使用埃提耶什，守護者的傳說之杖。擊敗被驅趕出法杖的生物，然後回到阿納克洛斯那裡去。','','去塔納利斯找時光之穴的阿納克洛斯。','淨化埃提耶什','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9258 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9258, 'zhTW', '烈焰邊境', '天譴軍團的污土持續進攻新的區域。為此，我們在鬼魂之地邊界建造了防護符石，以防止污染繼續蔓延。某次天譴軍團的攻擊行動中，他們摧毀了西邊的符石，迫使我們必須燒掉四周的土地來遏止污穢擴散。我的姐妹，拉瑞安娜·河風，看管著烈焰邊境。去找她，她可能有工作要給你。', '去烈焰邊境附近找拉瑞安娜·河風，位置就在永歌森林的西南方。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9259 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9259,'zhTW','血帆海盜的叛徒','','','','去找荊棘谷的血帆叛徒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9260 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9260,'zhTW','調查暴風城的天災入侵','巫妖王的部隊已經在我們鼻子底下紮了營，我們可不能坐以待斃！你會拿起武器跟這些可憎的入侵者作戰，保衛暴風城的吧？$B$B城外出現了奇怪的符文法陣，它散發著神秘的能量，亡靈和懸浮在半空的浮空城也被同樣的能量環繞著。我想這個符文法陣對天災士兵們必然有著重要的意義，因此想讓你調查此事。去和城外的亡靈作戰吧，帶回你殺死他們的證據，以及你的調查結果，我會獎勵你的。去吧！','從暴風城外面的天災士兵身上收集3塊暗淡的死靈石，並調查天災營地附近的發光符文法陣。','調查法陣','去暴風城找英雄谷的奧林中尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9261 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9261,'zhTW','調查鐵爐堡的天災入侵','巫妖王的部隊已經在我們鼻子底下紮了營，我們可不能坐以待斃！你會拿起武器跟這些可憎的入侵者作戰，保衛鐵爐堡的吧？$B$B城外出現了奇怪的符文法陣，它散發著神秘的能量，亡靈和懸浮在半空的浮空城也被同樣的能量環繞著。我想這個符文法陣對天災士兵們必然有著重要的意義，因此想讓你調查此事。去和城外的亡靈作戰吧，帶回你殺死他們的證據，以及你的調查結果，我會獎勵你的。去吧！','從鐵爐堡外面的天災士兵身上收集3塊暗淡的死靈石，並調查天災營地附近的發光符文法陣。','調查法陣','去找鐵爐堡大門的奈維爾中尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9262 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9262,'zhTW','調查達納蘇斯的天災入侵','巫妖王的部隊已經在我們鼻子底下紮了營，我們可不能坐以待斃！你會拿起武器跟這些可憎的入侵者作戰，保衛達納蘇斯的吧？$B$B城外出現了奇怪的符文法陣，它散發著神秘的能量，亡靈和懸浮在半空的浮空城也被同樣的能量環繞著。我想這個符文法陣對天災士兵們必然有著重要的意義，因此想讓你調查此事。去和城外的亡靈作戰吧，帶回你殺死他們的證據，以及你的調查結果，我會獎勵你的。去吧！','從達納蘇斯外面的天災士兵身上收集3塊暗淡的死靈石，並調查天災營地附近的發光符文法陣。','調查法陣','去泰達希爾找阿里斯瑞恩之池的貝薩中尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9263 AND `locale` = 'zhTW';
