INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9269,'zhTW','埃提耶什，守護者的傳說之杖','艱鉅的任務總在最後，$N。你已經擊敗了一位上古之神和一位巫妖王的大將，現在是面對薩格拉斯的時候了。$B$B帶上這根杖子轉至斯坦索姆。你會在那兒發現一處神聖之地：洛丹倫最偉大的騎士們的埋骨之處。將這柄被玷汙的傳說之杖放在神聖之地中，準備好挑戰被驅趕出法杖的可怕生物……擊敗控制著法杖的惡魔，然後再回來找我。','塔納利斯時光之穴的阿納克洛斯要你轉至斯坦索姆，在神聖之地上使用埃提耶什，守護者的傳說之杖。擊敗被驅趕出法杖的生物，然後回到阿納克洛斯那裡去。','','去塔納利斯找時光之穴的阿納克洛斯。','淨化埃提耶什','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9270 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9270,'zhTW','埃提耶什，守護者的傳說之杖','艱鉅的任務總在最後，$N。你已經擊敗了一位上古之神和一位巫妖王的大將，現在是面對薩格拉斯的時候了。$B$B帶上這根杖子前往斯坦索姆。你會在那兒發現一處神聖之地：洛丹倫最偉大的騎士們的埋骨之處。將這柄被玷汙的傳說之杖放在神聖之地中，準備好挑戰被驅趕出法杖的可怕生物……擊敗控制著法杖的惡魔，然後再回來找我。','塔納利斯時光之穴的阿納克洛斯要你前往斯坦索姆，在神聖之地上使用埃提耶什，守護者的傳說之杖。擊敗被驅趕出法杖的生物，然後回到阿納克洛斯那裡去。','','去塔納利斯找時光之穴的阿納克洛斯。','淨化埃提耶什','','','',0);
