INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9292,'zhTW','破碎的死靈水晶','你在憎惡的屍體上找到一塊散發著腐壞能量的破碎水晶。','將破碎的死靈水晶交給暴風城門外的奧林中尉。','','','','','','',0);
