INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9299,'zhTW','前線的便條','你在殺掉的眾多天譴軍團爪牙其中一人身上找到這封信。從它的樣子和氣味判斷，它已經和不死族在一起一些日子了。或許聖光之願禮拜堂的某人會對它有興趣進而好好的研究它...','將乾淨的便條帶到東瘟疫之地的聖光之願禮拜堂交給名冊保管者。','','','','','','',0);
