INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9302,'zhTW','被弄皺的信','你在某個天災士兵的屍體上找到了這封信。破舊發黃的信紙散發著黴臭，看來它在亡靈手裡已經有些日子了。或許聖光之願禮拜堂的傢伙會對此感興趣的……','將被弄皺的信交給東瘟疫之地聖光之願禮拜堂的名單登記員。','','','','','','',0);
