INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9322, 'zhTW', '卡林多的藍色火焰', '艾澤拉斯到處都在慶祝仲夏火焰節慶，而卡林多這塊多變的土地也不例外。你看起來很適合旅行 - 或許已經安排好一個旅程了。$B$B如果你沒有看過世界各處猛烈的藍色火焰就不算真的體驗了仲夏。主持者們在冷颼颼的西冬泉谷，艾薩拉東北邊，希利蘇斯荒地的勇士之墓附近，和通往繁茂安戈洛的入口都點燃了火焰。等你的旅行完成了再回來。', '拜訪艾薩拉，希利蘇斯，安戈洛環形山，和冬泉谷的仲夏營地，再回去找節慶營火管理者。', '', '去找節慶營火管理者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9323 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9323, 'zhTW', '東部王國的藍色火焰', '我們的火焰慶典遍布整個大陸，$c。每一個地方都感受到這個節日的熱情，最旺盛的火焰燃燒著明亮的藍色。去找它們吧。你會在黑石塔北邊就發現一個。其他有的在東瘟疫之地一個老舊的城鎮附近，有的在沿著路到多山的辛特蘭懸崖邊，還有詛咒之地通往黑暗之門的路上。$B$B完成之後再回來這裡。', '拜訪詛咒之地，東瘟疫之地，辛特蘭和灼熱峽谷的火焰節慶營地。', '', '去找節慶營火管理者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9324 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9324, 'zhTW', '偷取奧格瑪之焰', '這個從奧格瑪中心偷出來的火焰，讓你感到很溫暖。這股新的力量對你而言很陌生，但博學大師或許知道更多……', '將奧格瑪之焰交給節慶博學大師。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9325 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9325,'zhTW','盜取雷霆崖的烈焰','從雷霆崖薩滿祭司身上偷來的烈焰令你感到異常的溫暖。你對這種罕見的力量一無所知，但是博學者或許知道些什麼……','將雷霆崖烈焰交給節日博學者。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9326 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9326, 'zhTW', '偷取幽暗城之焰', '這個從幽暗城廢墟偷出來的火焰，讓你感到很溫暖。這股新的力量對你而言很陌生，但博學大師或許知道更多……', '將幽暗城之焰交給節慶博學大師。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9327 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9327, 'zhTW', '被遺忘者', '我知道這聽起來很奇怪，但被遺忘者竟來這裡幫忙。你應該和他們的領導者高階執行官瑪弗倫談談。他就在城西邊的塔裡。還有，$c，等你和他談完後再來找我;我有些緊急的事要立刻處理!', '到鬼魂之地的安寧地和高階執行官瑪弗倫談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9328 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9328, 'zhTW', '辛多雷的英雄', '這是我們種族歷史中新的一章，$N。我們將會奪回我們的領土，並且鞏固和希瓦娜斯及其盟友的關係。$B$B把背叛者的頭顱帶給銀月城的地區統治者，洛索瑪·塞隆。他會非常渴望聽到這個消息。', '把達克汗的頭顱帶給銀月城的洛索瑪·塞隆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9329 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9329, 'zhTW', '被遺忘者', '我知道這聽起來很奇怪，但被遺忘者竟來這裡幫忙。你應該和他們的領導者高階執行官瑪弗倫談談。他就在城西邊的塔裡。還有，$c，等你和他談完後再來找我;我有些緊急的事要立刻處理!', '到鬼魂之地的安寧地和高階執行官瑪弗倫談談。', '', '', '', '', '', '', 0);
