INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9340,'zhTW','大裂隙','聯盟的軍隊幾乎包圍了獵鷹崗哨，我們的處境相當危險。艾澤拉斯世界的血精靈朝聖者們蜂擁而至，我們必須修築一條安全的路線，躲避敵人的窺探。$B$B我已經想好了解決此事的辦法，那就是開闢一條穿越大裂隙的秘密通道。$B$B好吧，我知道那兒盤踞著兇猛的剝石者，可它們只是一群野獸而已。給它們點教訓，它們就不敢滋擾我們了。我要你轉至大裂隙獵殺這些傢伙，讓它們知道我們的厲害。','獵鷹崗哨的遊俠隊長維恩雷要你轉至獵鷹崗哨以東的大裂隙，殺死8個石鐮幼崽和3個石鐮突擊者。','','去地獄火半島找獵鷹崗哨的遊俠隊長維恩雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9341 AND `locale` = 'zhTW';
