INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9342,'zhTW','潛行的地殼穿刺者','看上去侵佔礦井的gan\'arg還不是最令人頭疼的，最近有一些巨型蟲子從另外一個方向向我們入侵！$B$B索爾瑪的駐軍正忙於防範燃燒軍團和照顧他們的傷員，只能由我和礦工們來解決這件事情。$B$B〈工頭指了指睡著的苦工們。〉$B$B你能指望他們幫上什麼忙嗎……$B$B如果你能幫我消滅掉那些蟲子，我很樂意把他們的酬勞都給你。','索爾瑪附近礦井中的Foreman Razelcraz想你殺掉15個Marauding Crust Bursters。這些蟲子有可能從地面下的隧道突然發起進攻。','','去地獄火半島找索爾瑪的工頭拉澤克拉茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9343 AND `locale` = 'zhTW';
