INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9344,'zhTW','倉促的離開','你好，$N。外域到處都充滿了危險，這是許多遠征軍很快就意識到的問題。我想年輕的Grelag也應該親自去感受一下。$B$BGrelag是一個非常有前途的學生，但是他缺乏耐心！他渴望研究他們人民的歷史，但他常常會忘記如今是危機四伏。$B$B他正前往斷背崗哨，完全忘記了虎視耽耽的燃燒軍團和邪獸人。我擔心他會發生什麼不測。','先知瑞卡酷要你找到她的學生格萊克。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9345 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9345,'zhTW','準備藥膏','在我試圖進入塞斯高的時候，一名燃燒軍團的巡邏兵發現了我。我拼命地逃，想躲進不遠處的那些塔裡去，可是他們放出了地獄獵犬，撲倒了我，幾乎差點把我弄成殘廢！$B$B後來，我掙扎著逃到了這裡，不過我的一條腿已經嚴重骨折了。石頭守衛安比蘭發現我之後，把我帶到了這裡。$B現在，我必須先想辦法醫治好這條腿。北邊白骨之谷那裡生長著一種刺葉植物，用它製成的藥膏應該能夠緩解我的傷痛，讓我痊癒。','將製作藥膏所需的12片地獄火刺葉交給斷背崗哨的葛雷拉格。','','去地獄火半島找斷背崗哨的葛雷拉格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9346 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9346,'zhTW','地獄野豬飛起來','你看過地獄野豬飛嗎？他們還不需要翅膀就能飛喔！$B$B<警備隊長克朗克笑著。>$B$B對抗北邊的燃燒軍團營地消耗了我們的存貨，包括髮射的彈藥。這是個嘗試新事物的大好時機。$B$B除了使用大卵石，我想試試點燃東邊廢墟附近餓死的地獄野豬屍體並用來發射到燃燒軍團的營地。$B$B你是要自願幫忙，還是要我來命令你呢？','索爾瑪的警備隊長克朗克要你幫他從飢餓的地獄野豬那裡弄到10個鼓起的地獄野豬屍體。','','去地獄火半島找索爾瑪的前線指揮官卡倫克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9347 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9347,'zhTW','野放的虛無行者','檢查精華髮現容器內有不知明物質的強烈能量漩渦。你一邊思考，一邊感覺到你的心智開始被牽引，要你更靠近看的更深。$B$B你發覺你快抓不住你的意志，便立刻將你的視線移開。在你決定要如何處置它時，它的樣子還停留在你的意識邊緣。','將悸動的虛無行者精華帶給索爾瑪的馬琥藍·胖蹄。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9348 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9348,'zhTW','圍捕劫毀者','外域充斥著令人著迷的生物，$N。迷人但也極度危險。$B$B那裡充滿了劫毀者，以那樣貧瘠的土地看來有點奇怪，但仔細研究卻發現階級的奧妙。$B$B石頭劫毀者似乎馴化了另一種劫毀者，也就是劫毀者，並將它們育為打獵的同伴和守衛動物。我需要了解他們如何訓練劫毀者。我們一定要中斷並檢視他們在西南邊的繁殖地點，就在泰洛卡森林附近。','替索爾瑪的馬琥藍·胖蹄殺死10個被困的小劫毀者並取得12顆劫毀者蛋。','','去地獄火半島找沙納爾荒地的瑪霍拉姆·硬蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9349 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9349,'zhTW','掠食者的卵','哦哦……我快要餓死了！$B$B嘿，朋友，你是不是覺得很諷刺？廚師快被活活餓死了？$B$B<雷加希乾笑兩聲，從口袋中掏出一張褶皺的羊皮紙，並慢慢展開。>$B$B根據我們的旅遊地圖，我們的飛艇被搞下來之前是要飛去西南邊靠近泰羅卡森林的一個叫荊刺小徑的地方。據說那裡盛產掠食者的卵，無比美味！如果你夠膽去那裡幫我弄些這種蛋回來的話，我就能做頓大餐了！前菜是蛋黃沙拉配蛋花湯，主菜是芥末煎蛋卷配蛋炒飯，甜點是蛋撻，唔，聽起來好象有點扯蛋……','將12枚飢餓掠食者的卵交給地獄火半島飛艇墜毀點的雷加希。','','去地獄火半島找飛艇墜毀點的雷加希。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9350 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9350,'zhTW','永不休息的苦工','燃燒軍團每日不停地進犯這裡，這給我們的防守造成了非常沉重的壓力。你看，如果城牆倒塌，索爾瑪一定會失守。我已經安排了一些苦工去維修城牆，但材料似乎快要用完了。$B$B好在，先知大人的一位學生對過去的許多獸人傳統瞭解十分深刻，他推薦我們採用一種過去常用的材料修補城牆。很久很久以前，獸人經常獵殺裂蹄牛，它的肉、皮，還有骨頭，都可以派上很大的用場。現在，你去東南邊再次獵殺一些裂蹄牛，收集它們身上所有有用的東西，順便也可以透過這種方式來紀念我們的祖先。','殺死暴怒的裂蹄牛，收集8張裂蹄牛的皮和8根裂蹄牛的骨頭，將它們交給索爾瑪的前線指揮官卡倫克。','','去地獄火半島找索爾瑪的前線指揮官卡倫克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9351 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9351,'zhTW','瘋狂的虛空行者','雖然飛艇的機身已經修好了，但我還得找一些能燒的東西來發動引擎。我們的燃料全部用完了，在這個地方又搞不到新的燃料！$B$B在我們的正南面有個叫遷躍平原的地方，那裡有許多失去控制的、兇猛的虛空行者。不過在我看來，那就是一群活蹦亂跳活潑可愛的活電池。$B$B如果你能幫我搞到些它們的精華，我就可以將飛艇的引擎改為由它們驅動的裝置，說不定能比以前飛得更遠哩！','將10份濃縮的虛空行者精華交給飛艇墜毀點的“尖嗓子”斯克裡·拉克希德。','','去地獄火半島找飛艇墜毀點的“尖嗓子”斯克裡·拉克希德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9352 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9352, 'zhTW', '達納蘇斯的入侵', '除了鄙惡者不斷帶來的威脅外，我還要處理各種謊報目睹夜精靈的狀況。$B$B雖然大部份的報導都是沒有根據的，但是，最近有個事件需要進一步的調查。我們的主要能量來源之一，西部聖所，而且關於達納蘇斯破壞的傳言一直很猖獗。$B$B前往那裡對付任何可疑的人。再向看守聖所的牧地看守者維蘭妮雅回報。', '前往西部聖所，就在獵鷹之翼廣場的西南邊，擊敗那裡所有的入侵者。將你的發現向牧地看守者維蘭妮雅報告。', '', '去找永歌森林的牧地看守者維蘭妮雅。', '擊敗入侵者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9353 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9353,'zhTW','Redeem iCoke Gift Box Voucher','','','','去找艾拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9354 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9354,'zhTW','尋找新材料','<正忙著做事的矮人見到你過來，立刻滿是期待地抬起頭。>$B$B你如果也想委託我製造裝備的話，就排隊等著吧，$c。我現在正忙著維修洛薩之子的盔甲呢，畢竟，沒幾天之後我們就得再次與敵人戰鬥了。$B$B自從那些該死的硬殼穿地蟲侵佔了礦井之後，我們的金屬庫存量就一直在下降，如今可是沒剩多少了。我正在用從榮耀堡東北邊那些暴怒的裂蹄牛身上收集到的材料做一些試驗。雖然這些材料不能完全取代鋼鐵，但眼下我們也只能將就著用了。','殺死一些暴怒的裂蹄牛，收集8張裂蹄牛的皮和8根裂蹄牛的肌腱，將它們交給榮耀堡的哈姆菲。','','去找地獄火半島的哈姆菲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9355 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9355,'zhTW','聰明人的工作','你好，$c。總算有援兵過來了，現在我們終於可以開始處理周邊生物所造成的問題了！$B$B我們的首要目標是確保西南邊的那條道路的交通安全，但現在那些該死的硬殼穿地蟲在那裡頻繁出沒，將路面也破壞得凌亂不堪。$B$B如果你願意幫助我們解決那些可惡的傢伙，洛薩之子將感激不盡。不過，你千萬得小心，它們很敏感。','殺死15只遊蕩的硬殼穿地蟲，然後向榮耀堡的工頭比格姆斯覆命。','','去地獄火半島找榮耀堡礦洞的工頭比格姆斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9356 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9356,'zhTW','萬無一失','斯克裡總是喜歡誇自己的飛行技術“萬無一失”，但我覺得這傢伙好象隨時能把飛艇開墜毀的樣子！$B$B看看那邊的殘骸吧，那就是他某次成功的“緊急迫降”搞出來的。$B$B當然，那時候我們的確也遭到了敵人的攻擊，但如果他能少吹噓幾句他的飛行技術，我就願意原諒他！$B$B哦，對了，我想我得幫他搞點鳥翅來，這傢伙說吃啥補啥，給他來點翅膀或許他的飛行技術也會好點。在東邊的白骨之谷中，你可以看到許多啄骨禿鷹，它們的翅膀巨大多汁，最合適燒烤了。','將12只強壯的禿鷲翅膀交給飛艇墜毀點的雷加希。','','去地獄火半島找飛艇墜毀點的雷加希。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9357 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9357, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9358 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9358, 'zhTW', '遊俠塞瑞', '別以為這個村子的安全是與生俱來的。我們被東邊的天譴軍團和西邊的鄙惡者包圍。遊俠塞瑞保護我們的邊界，不讓死亡之痕湧入的不死族侵擾我們。沿著出城後往東邊的路走，看看你能否幫她一把。', '向永歌森林晴風村外的遊俠塞瑞報告。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9359 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9359, 'zhTW', '遠行者居所', '你對壓制鄙惡者的幫助是無價的。遠行者在對抗阿曼尼食人妖時如果能有像你這樣的人一定會很有用。去東北方的遠行者營地和晨奔中尉談談，看看他需要怎樣的幫助。', '向永歌森林遠行者營地的晨奔中尉報告。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9360 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9360, 'zhTW', '阿曼尼入侵', '雖然你不了解這些作戰計劃的語言，你還是能清楚地辨別出一個標記著遠行者居所和晴風村的地圖。$B$B你最好讓遠行者居所的晨奔中尉知道這點。', '將阿曼尼攻擊計畫送給遠行者居所的晨奔中尉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9361 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9361,'zhTW','地獄野豬，另一種白肉','這些蛋好極了，但為什麼我們不再來點別的呢？$B$B加上一些燻肉會讓這頓大餐更加完美，而且，我知道在哪裡能弄到燻肉。$B$B你看，這片區域到處都有地獄野豬，而且這裡沒有人去檢查它們的肉是否能夠食用，也沒有人會烹飪那些肉。不過我們非常幸運！$B$B<雷加希在揹包裡仔細翻找，拿出了一個小瓶子。>$B$B這個雖然不是專為豬肉所準備的，不過，你要知道，烹飪需要創意！','飛艇墜毀點的雷加希要你收集8塊純淨的地獄野豬肉。你必須首先獵殺地獄野豬，然後利用淨化藥劑來淨化被汙染的地獄野豬肉。','','去地獄火半島找飛艇墜毀點的雷加希。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9362 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9362,'zhTW','軍閥克雷利安','沒什麼時間了，$n！我的探知法術最近發現了一個很強大的法術源。但我卻不能離開法師塔，所以只有請你幫我殺死那個佔有這件神器的邪惡生物。$B$B這個邪惡的傢伙名叫軍閥克雷利安，他躲藏在守衛森嚴的辛瑪洛神殿。把他燒成灰，然後將他垂涎已久的虹彩貝殼給我帶回來。','為大法師克希雷姆奪回虹彩貝殼。大法師克希雷姆就居住在艾薩拉北部懸崖上的一座塔中。','','去艾薩拉找在熊頭的大法師克希雷姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9363 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9363, 'zhTW', '警告晴風村', '前往晴風村警告遊俠迪哥里恩關於阿曼尼的計劃。即使祖瑪羅什已死，晴風村還是要準備好對抗食人妖的攻擊。告訴迪哥里恩我們會盡快派遣援軍給他。', '前往永歌森林的晴風村和遊俠迪哥里恩談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9364 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9364,'zhTW','魔法的碎片','我的研究發現了這個虹彩貝殼的一個特殊用途。$B$B帶上這個貝殼，到艾薩拉四處找一些惡鞭納迦，使用一下變形術看看。如果你願意等一段時間，那麼這個貝殼上所附帶的光環會使他們分裂為幾個小一些的相似物體。儘快殺死這些物體，貝殼就可以收集它們的精華。$B$B等貝殼滿了之後，回來找我。','對艾薩拉的惡鞭納迦使用變形術，然後殺死幾秒鐘後出現的相似體。當你殺了50個相似體後，回去向大法師克希雷姆覆命。','','去艾薩拉找在熊頭的大法師克希雷姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9365 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9365, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9366 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9366,'zhTW','邪惡之血','此地東北方的阿苟納之池曾是德萊尼人的聖地，惡魔阿苟納的血液灑入池水後，整片區域都被汙染了。$B$B雖然事隔多時，被稀釋的惡魔之血仍然蘊涵著強大的力量。盤踞在那兒的恐懼魔也擁有了阿苟納血液中的邪惡力量。殺死他們，替我取回一些邪惡樣本。我不會讓你白忙活的。','獵鷹崗哨的陰沉的利亞森要你轉至阿苟納之池，從恐懼魔身上收集6份邪血樣本。','','去找地獄火半島獵鷹崗哨的陰沉的利亞森。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9367 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9367, 'zhTW', '火焰節慶', '仲夏又來了!$B$B每一年，按照傳統，雀屏中選的營火管理者要負責看管我們城市裡的營火。當整個艾澤拉斯都是燃燒的火焰時，我們的火苗一定要是最熱烈、最明亮的，才能恰當地表現出對季節的尊敬。$B$B事實上，我有個任務要給你，如果你不介意的話。我還沒聽說所有主城裡的火焰都燃燒的恰如其分。前往那裡讓火焰為你取取暖 -- 確定它們是燙的!', '觸摸暴風城，鐵爐堡和達納蘇斯裡的營火，再和任何一個節慶傳說大師談談。', '', '去找節慶傳說大師。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9368 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9368, 'zhTW', '火焰節慶', '仲夏又來了!$B$B每一年，按照傳統，雀屏中選的營火管理者要負責看管我們城市裡的營火。當整個艾澤拉斯都是燃燒的火焰時，我們的火苗一定要是最熱烈、最明亮的，才能恰當地表現出對季節的尊敬。$B$B事實上，我有個任務要給你，如果你不介意的話。我還沒聽說所有主城裡的火焰都燃燒的恰如其分。前往那裡讓火焰為你取取暖 -- 確定它們是燙的!', '觸摸奧格瑪，雷霆崖和幽暗城裡的營火，再和任何一個節慶故事使者談談。', '', '去找節慶故事使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9369 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9369,'zhTW','補充治療水晶','我們是德萊尼。我們的船失事了，而且由於我們有許多傷者，我們現在最擔心的就是治療水晶的庫存。我們一定要盡快補足水晶!$B$B不幸的是，我們此時唯一的選擇就是從當地的山谷飛蛾身上直接抽取血液。牠們的血液是很合適的替代品。$B$B你可以在溪谷附近的區域找到牠們，不過牠們大多集中在西北方。','從附近的安曼谷飛蛾身上取得6瓶飛蛾血清，再交給安曼谷失事地點的波尼特斯。','','去埃門谷找墜毀點的普羅尼圖斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9370 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9370,'zhTW','阻止淨化','我們的斥候在阿苟納之池俘獲了一名德萊尼聖騎士。當時他正在操辦某種淨化儀式，看來德萊尼人企圖淨化阿苟納之池。我們必須阻止他們，否則邪血樣本的來源就會被切斷！$B$B我們從聖騎士身上搜出一枚訊號寶石，這東西似乎是用來標記安全地點的，這樣那些自稱為“學者”的德萊尼牧師就知道該在哪裡啟動淨化儀式了。將這顆寶石放置在阿苟納祭壇附近，擊敗靠近它的德萊尼人。$B$B我建議你最好帶上一兩個朋友。','轉至阿苟納之池，將訊號寶石放置在阿苟納祭壇附近，擊敗被召喚出來的德萊尼學者。完成任務後返回獵鷹崗哨，將訊號寶石交還給陰沉的利亞森。','','去找地獄火半島獵鷹崗哨的陰沉的利亞森。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9371 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9371, 'zhTW', '植物學家泰瑞茲', '$N，植物學家泰瑞茲需要你的幫助。你可以在西邊找到她和她的學徒，就在船外面。', '和安曼谷失事地點的植物學家泰瑞茲談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9372 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9372,'zhTW','惡魔的玷汙','歡迎來到塞納里奧哨站，$c。我們很少結交外面的朋友，不過，依然很高興見到你。為了研究這個破碎世界中的生物與生態，我常常會轉至許多偏遠的角落。$B$B不過，上一次塞納里奧遠征隊派我去研究外域中最危險的野生生物時，我卻發現了一件驚人的事情。當這裡的許多生物遭受輻射之後，它們的身體都發生了可怕的變異。當前，我正在收集血樣，試圖研究這些變異。如果你願意幫忙的話，我會非常感激你的。','地獄火半島塞納里奧哨站的塞安·紅鬃要你從笨拙的地獄野豬身上收集6份地獄野豬血樣。','','去地獄火半島找塞納里奧哨站的塞安·紅鬃。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9373 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9373,'zhTW','遺失的信件','仔細地顯示過這隻壞掉的皮箱子之後，你發現它很明顯是遭到了那些蟲子消化道內的腐蝕性液體的破壞。它表面的皮革似乎經過了一些簡單的加工，但裝飾與加工的細節已經無從辨認，也無法提供線索了。$B$B皮箱上唯一能看清楚的是一小塊已經磨損很嚴重的塞納里奧議會的標誌。除此以外，你沒有辦法瞭解更多有關這個小皮箱的情況了。因此，你認為最好的處理方法就是將它交給一名塞納奧議會的成員。','轉至地獄火半島西部的沙納爾廢墟，將被腐蝕的皮箱交給駐紮在廢墟附近的塞安·紅鬃。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9374 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9374,'zhTW','埃雷利恩的日記','來到外域後，我的丈夫埃雷利恩便對阿苟納之池著了迷。他耗費大量的時間去那兒研究軟泥怪！$B$B幾天前，他突然失蹤了。他們都說他已經死了，勸我放棄一切希望。$B$B我唯一能做的就是找回他的研究筆記。轉至阿苟納之池的東北方尋找他的日記，他總是把它放在那個褐色的揹包中。','地獄火半島獵鷹崗哨的魔導師卡爾琳達要你轉至阿苟納之池，找回埃雷利恩的日記。','','去地獄火半島找獵鷹崗哨的魔導師卡爾琳達。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9375 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9375,'zhTW','獵鷹崗哨之路','<這個受盡折磨的血精靈看到你之後，臉上的痛苦表情顯得平緩了許多。>$B$B$c，請你一定把我救出去。唉……我太愚蠢了，沒有聽從瑪提克·託塞多雷的警告，一意孤行離開了索爾瑪。結果，我在路上遭到了那些可怕怪物的襲擊，是的，沒錯，就是瑪提克·託塞多雷提到過的掠食者。我好不容易擊退了它們，可沒想到竟然遇到了更大的麻煩。$B$B在我包紮傷口的時候，那些鳥人發現了我，並把我抓來這個洞穴，鎖進了這隻籠子裡！我必須出去，我必須到獵鷹崗哨去！','護送受傷的血精靈朝聖者返回獵鷹崗哨，然後與塔雷里斯·晨光談一談。','護送受傷的血精靈朝聖者回到獵鷹崗哨','去地獄火半島找獵鷹崗哨的塔雷里斯·晨光。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9376 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9376,'zhTW','朝聖者的困境','這名受傷的朝聖者在昏迷中似乎一直在說著什麼，好象有提到什麼揹包的樣子。$B$B那麼，你遇到她的時候，在附近看到過她的揹包嗎？$B$B嗯……她一定是在逃走的時候把它弄丟了。南邊峽谷的鋼牙掠食者常常會襲擊單身的旅行者。$B$B如果她不能平靜下來的話，我是沒有辦法為她療傷的，唉，她的倔強會要了她的命……$B$B去塵羽峽谷看看能否找到她的營地吧，或許她把揹包遺留在那裡了。','受傷的血精靈朝聖者在塵羽峽谷宿營時遭到了鋼牙掠食者的襲擊。轉至那處營地尋找丟失的揹包。','','去地獄火半島找獵鷹崗哨塔的雷里斯·晨光。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9377 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9377,'zhTW','渴望力量','一般來說，獵鷹崗哨是朝聖者們來到外域之後的第一個停留點。儘管這裡已經是那些朝聖者所能找到的最近的血嚮導定居點，但許多朝聖者到達這裡時，已經深深陷入了對魔法能量的極度飢渴之中。$B$B在這樣一個全新的世界中，許\\r\\n多血嚮導都會發現他們有必要重新學習如何獲得魔法能量。$c，他們需要食物和水，不過他們最需要的仍然是魔法能量。外域中的虛空行者體內蘊藏著十分強大力量，但是虛空行者數量非常稀少，你只能在西南邊的遷躍平原找到他們。','從虛空行者身上收集1份強大的虛空行者精華，將其交給獵鷹崗哨的塔雷里斯·晨光。','','去地獄火半島找獵鷹崗哨塔的雷里斯·晨光。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9378 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9378, 'zhTW', '巫妖王之怒 任務', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9379 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9379,'zhTW','地獄獵犬的補品','你好，$c。跟基爾西也打個招呼吧。別怕別怕，除非有我的命令，否則它是不會咬人的。$B$B<安吉拉對著這隻地獄犬發出咕咕的叫聲。>$B$B跟居住在外域的遷躍犬相比，它的體型未免也太過嬌小了。不過我們很快就能改變這一點，對吧，基爾西？$B$B我想我已經有辦法了。我希望你能幫我搞來一些遷躍犬的血液，你可以去東南邊捕捉它們，然後放血，我需要這些東西來進行試驗……嗯，算是“治療”吧。','將6份遷躍獵犬之血交給索爾瑪的“利爪”安吉拉·凱斯提爾。','','去找地獄火半島的“利爪”安吉拉·凱斯提爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9380 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9380,'zhTW','群居的獵犬','我發誓，如果我再收到來自鐵爐堡的信件……$B$B你有沒有過向那些根本聽不進你說話的人解釋過什麼事的經歷呢，$c？我把鐵爐堡裡那些人要的遷躍獵犬標本送了過去，可他們居然厚顏無恥地回信說，他們要的不是一隻而是“一群”！一群遷躍獵犬！$B$B我只好再寫信向他們解釋說遷躍獵犬是獨居生物，但是沒有一個人相信。我真是懶得再跟他們多說了，你願意到榮耀堡的東邊去幫我再搞六隻標本回來嗎？','將6只完整的遷躍獵犬屍體交給榮耀堡的勘探員穆拉圖斯。','','去找地獄火半島的勘探員穆拉圖斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9381 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9381,'zhTW','箭矢之羽','最近，朝聖者的大批湧入和聯盟軍隊的不斷進犯都清楚地表明，獵鷹崗哨正經歷著一個多事之秋。連我這樣的人，最近在有空的時候都會幫那些遊俠們準備箭支。不過，最近空閒太少，我已經有很長時間無法去收集箭尾要用的羽毛了。$B$B如果你能幫我收集一些啄骨禿鷲的尾羽，我會給你一些錢作為報酬的。我以前經常在獵鷹崗哨北邊的巨獸屍骨周圍找到它們，你也可以去那邊看看。','從啄骨禿鷲身上收集8片啄骨禿鷹的尾羽，把它們交給獵鷹崗哨的馴鷹者德蕾娜·河風。','','去地獄火半島找獵鷹崗哨的馴鷹者德蕾娜·河風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9382 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9382,'zhTW','裂蹄的命運','你好，$c。$B$B我相信你在外域的旅行中一定已經見到了這個世界中某些墮落的力量。這些力量讓居住在這裡正常的生物變得扭曲\\r\\n - 確切地說是那些活著的生物。$B$B南邊和西邊的clefthoof曾經是非常溫順的食草動物，但世界的墮落給他們造成了無止境的災難。儘管我們會很傷心，但只有死亡才能將他們從痛苦的折磨中解救出來。你願意幫幫我，解除bristlehide clefthoof的痛苦嗎？','殺掉15個Bristlehide Clefthoof，向塔哈瑪特神殿的Wise Amaan覆命。','','去找地獄火半島的智者阿曼恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9383 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9383,'zhTW','艱鉅的計劃','血精靈就是濫用魔法者的典型，$c。現在，他們已經無法控制魔法的能量，更確切地說，他們已經淪為了魔法的奴隸，徹底根本無法擺脫對魔法能量的依賴與沉迷了。來到外域之後，他們開始汲取外域的虛空行者的力量，並強化了他們那種源自惡魔的法術。$B$B我準備了一塊附有符咒的水晶，它可以中和一個虛空行者的身軀，使它被毀滅後就立即切斷與這個世界的關聯，去試試它吧。我常常看見虛空行者出現在地獄火堡壘東南邊的遷躍平原。','在失控的虛空行者受傷之後對其使用淨化水晶，然後返回塔哈瑪特神殿向艾爾薩娜覆命。','','去地獄火半島找塔哈瑪特神殿的艾爾薩娜。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9384 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9384,'zhTW','<待完成任務>','現在是時候殺死這個怪物了。$N，你一定要小心，畢竟你對外域的虛空行者還不夠熟悉。$B$B將這個容器交給負責毀滅虛空行者的魯瑪圖。仔細地觀察整個過程，然後回來向我報告。','將閃光的淨化水晶交給沙納爾神殿的魯瑪圖，他會利用聖光的力量來摧毀水晶中的虛空行者。','','去找地獄火半島的艾爾薩娜。','協助摧毀虛空行者','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9385 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9385,'zhTW','鋼牙掠食者','榮耀堡派我們來消滅這一帶的鴉人勢力，到了這邊以後，我們覺得這裡是個不錯的地方，於是就駐紮了下來。然而，我們卻根本沒有發現這裡與鋼牙掠食者的老巢竟然如此接近。$B$B它們都是些非常兇猛的掠食者，經常騷擾這裡，讓我們根本無法進行工作。如果你願意幫我們幹掉它們的話，我們願意支付你一筆不錯的報酬，你覺得怎麼樣呢？','殺死10只鋼牙掠食者，然後向地獄火半島的格雷尼·長鬚覆命。','','去找地獄火半島的格雷尼·長鬚。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9386 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9386, 'zhTW', '[A Light in Dark Places]', '[An eager one, aren\'t you? If you\'re willing to enter the depths once more, I\'ll gladly reward you.$B$BSeek out the bonfires burning within Stratholme, Scholomance, Dire Maul, and the halls of Blackrock Spire itself; I look forward to your return, $n.]', '[Find and touch the bonfires located within Blackrock Spire, Dire Maul, Scholomance, and Stratholme, then speak with the Festival Flamekeeper.]', '', '去找節慶營火管理者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9387 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9387,'zhTW','墮落之源','那些沒有墮落的德萊尼人，例如這個倒黴的傢伙，都是聖光忠實的擁護者。究竟是什麼導致這個偉大的種族分化出破碎者和失落者呢？$B$B我聽來的說法是惡魔的力量導致了德萊尼人的變異。我想驗證這種推測是否屬實。$B$B此地西北方便是沙納爾廢墟。那兒聚集著地位低下的破碎者，伊利達雷監工負責看管他們。將監工身上的惡魔精華帶回來給我，這樣我就能用它們在德萊尼人身上做試驗了。','轉至地獄火半島的沙納爾廢墟，從伊利達雷監工身上收集5個惡魔精華。完成任務後返回獵鷹崗哨，向藥劑師艾瑟森覆命。','','去地獄火半島找獵鷹崗哨的藥劑師艾瑟森。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9388 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9388, 'zhTW', '卡林多的閃爍火焰', '世界各地都有許多的火焰在燃燒著，$n。最難處理的火焰就是那些發著綠光的;沒有管理的話它們不會長久燃燒。為我們的火焰管理者確認那些翠綠色的火焰仍在卡林多燃燒著，聽到了嗎?$B$B你可以在貧瘠之地的棘齒城，黑海岸的主宰之劍附近找到它們，還有從銀翼哨站旁的橋邊進入梣谷的森林裡，和沿著石爪山脈的幹道走到通往狂風峭壁的路上都能找到。', '探勘梣谷，貧瘠之地，黑海岸，和石爪山脈的營火，再和節慶火焰管理者談談。', '', '去找節慶營火管理者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9389 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9389, 'zhTW', '東部王國的閃爍火焰', '仲夏火焰節慶傳統上會在整個土地上點燃無數的火焰。有些人說綠色的火焰是最美的，因為它們是最難維持的而且又有獨特的色澤。為我們的火焰管理者確認它們仍在東部王國燃燒著。它們座落在濕地的丹莫德附近，銀松森林內的焚木村那裡也有，眺望濕地燈塔的峭壁上，和希爾斯布萊德丘陵廢棄的哨塔旁。', '探勘希爾斯布萊德丘陵，銀松森林，西部荒野，和濕地的營火，再和節慶火焰管理者談談。', '', '去找節慶營火管理者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9390 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9390,'zhTW','尋找瑟丹','請聽聽我所說的話，$c。我的兄弟瑟丹為了與瑪格漢崗哨的獸人取得聯絡，在很久以前就離開了。他就是這樣一個不切實際的傢伙，認為現在時機已經成熟，可以將我們的隔閡拋在腦後，大家從此和平相處。$B$B他已經失蹤好幾天了，我擔心他出事了……$B$B你能讓我放心，幫我去找找他嗎？瑟丹應該是在東邊的某個地方。','學者歐巴迪要你去塔哈瑪特神殿東邊附近的區域尋找他的兄弟瑟丹。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9391 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9391,'zhTW','點燃燈塔','我們成功地削減了剝石者的數量，現在只需要指引朝聖者們踏上這條安全的通道。帶上這柄燃燒的火炬返回大裂隙，在東邊尋找沿途的三座燈塔。$B$B點燃三座燈塔，然後回來向我覆命。當你點燃燈塔時，小心那些被吸引而來的剝石者。','轉至地獄火半島的大裂隙，點燃南部燈塔、西部燈塔和中部燈塔。完成任務後返回獵鷹崗哨，將燃燒的火炬還給遊俠隊長維恩雷。','','去地獄火半島找獵鷹崗哨的遊俠隊長維恩雷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9392 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9392,'zhTW','盜賊訓練','既然你已經在你所選擇的職業上有所進步了，我想你一定會希望能夠獲得來自職業訓練師的更多指導。逐日島上有一位名叫尋路者卡雷爾的盜賊訓練師。跟他談談，看看能學到什麼新技能。當然，你得付點學費。$B$B卡雷爾跟逐日島其它訓練師都在太陽之塔的下層。','與逐日島太陽之塔內的尋路者卡雷爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9393 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9393,'zhTW','獵人訓練','既然你已經在你所選擇的職業上有所進步了，我想你一定會希望能夠獲得來自職業訓練師的更多指導。逐日島上有一位名叫遊俠薩琳娜的獵人訓練師。跟她談談，看看能學到什麼新技能。當然，你得付點學費。$B$B薩琳娜跟逐日島其它訓練師都在太陽之塔的下層。','與逐日島太陽之塔內的獵人訓練師遊俠薩琳娜談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9394 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9394, 'zhTW', '威利坦在哪裡?', '暗木的地面守衛者不見了!一定是博學者和大家離開時忘了叫他一起走了。我知道他還在營地附近，但我不敢自己去找他，有太多魔法生物在那裡閒晃了。你能幫我去找他嗎，$c，確定他還安然無恙?', '到永歌森林的暗木營地尋找地面守衛者威利坦。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9395 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9395, 'zhTW', '薩瑟里的避風港', '我發誓如果再讓我收到跟薩瑟里領主的舞會物資相關的請求我就要用火球殺了某人!我看起來像舞會策劃人嗎?!再偷偷告訴你，那個白痴和他的食客們根本就不相信我們這裡正遭受攻擊!我們有些人正忙著，呃，我不知道，防守奎爾薩拉斯剩下的土地!$C，可以請你前往薩瑟里的避風港看看能不能讓他閉上嘴嗎?那地方就在往西邊的路上。', '到永歌森林和薩瑟里的避風港的薩瑟里領主談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9396 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9396,'zhTW','鴉人的魔法','外域隱藏著許多秘密，$N。要揭開這些秘密，我們需要的只是時間。$B$B半人半鳥的鴉人氏族掌握著古老而神秘的知識，可以幫助我們探索這個世界。轉至南邊的哈爾什巢穴。從哈爾什鳥人手中奪得魔法卷軸，將它們帶回來給我。','將4個哈爾什卷軸交給地獄火半島獵鷹崗哨的奧術師卡雷希斯·晨星。','','去地獄火半島找獵鷹崗哨的奧術師卡雷希斯·晨星。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9397 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9397,'zhTW','捉小鳥','哈爾什鴉人馴養了一種名叫卡利鳥的飛禽，它們的羽毛非常漂亮。$B$B我設法抓來了一隻雄性小卡利鳥，憑我的經驗，馴養這種鳥類應該不成問題。不過雌性卡利鳥非常罕見，如果能抓來一隻雌鳥，我就能嘗試繁殖出它們的後代。但是……她必須是一隻小卡利鳥才行。若是強行將成年卡利鳥囚禁起來，她肯定無法存活。$B$B帶上這個籠子轉至南邊的哈爾什巢穴。在卡利鳥巢穴中搜尋那些即將孵化的鳥蛋，如果你能為我抓回一隻雌性小卡利鳥，我一定會好好獎賞你的。','轉至地獄火半島的哈爾什巢穴，在卡利鳥巢穴中尋找雌性小卡利鳥。利用空鳥籠捕獲雌性小卡利鳥，將其交給獵鷹崗哨的馴鷹者德蕾娜·河風。','','去地獄火半島找獵鷹崗哨的馴鷹者德蕾娜·河風。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9398 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9398,'zhTW','致命的獵手','外域的破碎者是個悲慘的民族，他們的生存權利和自由一直在遭受著無止境的侵害。所以，當黑暗之門開啟時，他們滿懷著希望大批地湧入了這裡，希望轉至我們的世界，這一點也不奇怪。$B$B然而不幸的是，棲息在大裂隙附近的那些掠食者卻把這些從南邊惶恐逃亡過來的兄弟姐妹們當成了唾手可得的獵物。你必須到那裡去削減掠食者的力量，這樣我們的同胞的生存機會就能改善許多。','地獄火半島塔哈瑪特神殿的斥候瓦努拉要你殺死8只石鐮幼崽和4只石鐮突擊者。','','去找地獄火半島塔哈瑪特神殿的斥候瓦努拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9399 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9399,'zhTW','殘忍的監工','你該不會認為大多數破碎者都是邪惡的吧？其實，他們大多本性善良，只是缺少正確的道德與信仰指引而已。$B$B在見到歐麥尼——也就是神殿中的這些德萊尼人以前，我也幾乎完全迷失了自我。$B$B獸人的惡魔法術折磨著我們的思想，從而讓我們很容易受到他們的迷惑，被他們利用。$B$B除此以外，惡魔們也會和伊利丹聯手，他們常常襲擊地獄火半島，並將我們變成他們的奴隸。直到歐麥尼出現之後，我們才有了希望。到西南邊的沙納爾廢墟去殺掉那些伊利達雷監工，我的人民才有希望獲得自由！','轉至沙納爾廢墟，殺死4名伊利達雷監工，然後向地獄火半島塔哈瑪特神殿的伊坎覆命。','','去地獄火半島找塔哈瑪特神殿的伊坎。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9400 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9400,'zhTW','刺客','$n，最近我們發現，我們派駐在獵鷹崗哨的特使陷入了被刺殺的危險之中。地獄火堡壘刺探到了我們的計劃，今天上午早些時候派出了一支敢死隊準備發動突襲。$B$B我們的斥候報告說，當前有一位名叫克倫·斷脊者的刺客正在堡壘北方的路邊待命。立刻過去殺死這名刺客。要讓那幫邪獸人知道，我們可不是好對付的！','納茲格雷爾要求你到地獄火堡壘北方的道路附近尋找一個名叫克倫·斷脊者的刺客。','找到克倫·斷脊者','去地獄火半島調查邪獸人的屍體。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9401 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9401,'zhTW','奇怪的武器','你從屍體上拔下了這把石斧，放在眼前仔細檢查。這把武器的製造工藝有點不同尋常。$B$B它的樣式與外形的確是獸人風格，但材料卻是你從來沒有見過的。納茲格雷爾或許會對這把武器有點興趣。','將重型石斧交給索爾瑪的納茲格雷爾。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9402 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9402,'zhTW','撈瓶子','那麼……你叫$n，對嗎？不用驚訝，我知道你是誰，我的一個學生常常稱讚你，簡直是讚不絕口呢。$B$B嗯……如果你想給$g她:他留下深刻的印象，為什麼不幫我做點什麼事呢？在我身後的池塘底有一隻小瓶子，到水裡去幫我找到它。','在縈語水池底部為指導者安瑟隆找到碧藍瓶。','','去永歌森林找縈語水池的指導者安瑟隆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9403 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9403,'zhTW','最純淨的水','現在你應該算是學到點東西了，我想讓你去做點更重要的事情。這關係到你在近戰中保護自己的能力。當然，除非萬不得已，你不應該讓敵人靠近你，但是同樣你也不能在敵人靠近之後毫無辦法。$B$B我會給你製作一根適合你用的法杖。你要做的就是帶上這隻你剛剛撈上來的瓶子，在裡面灌滿艾倫達爾瀑布的水。沿著河往東南邊走就可以找到瀑布了。','指導者安瑟隆希望你能在碧藍瓶中裝滿艾倫達爾瀑布的水。','','去永歌森林找縈語水池的指導者安瑟隆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9404 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9404,'zhTW','活動的樹木','你應該注意到在艾倫達爾瀑布附近行走的那些樹了吧？作為大自然的守護者，它們身上都有著原始的魔法能量，我們可以使用你收集的水來改造這些魔法能量。$B$B不幸的是，這些綠色的守護者們都是些狂暴而扭曲的生物，所以如果你想找到一根有用的樹枝，也許需要幹掉許多守護者。','清理永歌護衛者，直至你找到指導者安瑟隆所需要的生命綠枝。','','去永歌森林找縈語水池的指導者安瑟隆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9405 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9405,'zhTW','酋長的命令','你應該知道，酋長之所以在這支遠征軍中投入了這麼多的資源，其理由只有一個。這個世界曾是我們的故鄉，這裡是我們的根源所在。$B$B來到這裡，對於一個獸人與一個血精靈來說有著完全不同的意義。他們來到這裡，是為了尋找一處新的家園，而我們則是回到了久違的故鄉。$B$B不知是誰用我們獸人的工藝製成了這把石斧，但我們一定要找到他。它很重要，有了它，就可以利用我們最傳統的方法來找到製作者。把這武器拿給先知雷古庫特看看，她知道該做什麼。','將重型石斧交給索爾瑪的先知雷古庫特。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9406 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9406,'zhTW','瑪格漢','這……這就是你從黑暗之門的那一邊帶來的訊息嗎？你是說……你是說杜隆坦的兒子正統治著那邊的國度，還……還已經擺脫了惡魔的操控？現在，他的手下已經回到了這個世界？！你要我們相信這些嗎？$B$B希望這不是你開的玩笑，$c。這對我的人民來說意味著……不，這簡直無法形容……我必須立刻通知納格蘭那邊，必須立刻通知地獄咆哮大人。$B$B把這封信送給你在索爾瑪的上級。告訴他們，瑪格漢歡迎他們回家！','將瑪格漢的來信送給索爾瑪的納茲格雷爾。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9407 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9407,'zhTW','跨越黑暗之門','數年來，黑暗之門靜靜地矗立在詛咒之地……如同一座被遺忘的紀念碑。如今戰爭打破了這片寂靜。$B$B在成功地阻止惡魔入侵艾澤拉斯世界之後，我們的軍隊跨越了黑暗之門，揮師直指惡魔的老巢！$B$B這是一場殘酷的混戰，甚至有人認為我們可能會敗北。因此，$N，打敗勁敵就成了我們肩上的責任，也是我們惟一的選擇。$B$B如果你願意伸出援手，就立即向沃雷恩中將報到吧。他就在外域等你……','穿越黑暗之門，找到沃雷恩中將。他就在黑暗之門另一側的外域等你。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9408 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9408,'zhTW','被遺忘的英雄','在為那些當初在關閉黑暗之門的戰役中犧牲的士兵們感到痛苦的同時，我的內心也為得知仍有許多當初的遠征軍戰士活了下來而感到自豪與驕傲。$B$B我真不敢相信，但他們確實矗立在那裡——宛如一座座鐫刻著所有聯盟將士決心的豐碑。$B$B就在那座要塞中，有一位我們所有人都萬分景仰的英雄——達納斯·托爾貝恩！立刻找到他，$c。他已經見過許多我們派過去的士兵了，當然也會非常樂意見到你。','與榮耀堡的遠征軍指揮官達納斯·托爾貝恩談一談。','','去地獄火半島的榮耀堡找遠征軍指揮官達納斯·托爾貝恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9409 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9409, 'zhTW', '緊急送件!', '既然你已收集了所有我們需要的東西來補充我們的治療水晶，我要你送些瓶子給我們的牧師，薩度恩。他就在船中央的房間裡照料我們的傷者。', '將一捆瓶子送到安曼谷給失事地點的薩度恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9410 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9410,'zhTW','靈魂的指引','使用幽靈狼吧，即使是最優秀的戰狼在追蹤技巧上也無法與它們匹敵，$N。元素之靈的感官與瞭解世界的方式和我們完全不同。它們並不是使用嗅覺，而是使用心靈來進行追蹤。$B$B去吧， $c，將這支圖騰帶上，在你發現那把石斧的地方使用它。','在你找到克倫·斷脊者屍體的地方使用先祖狼魂圖騰，並跟隨先祖狼魂前進。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9411 AND `locale` = 'zhTW';
