INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9662,'zhTW','琪安娜的自由','我的記憶……我現在全部都記起來了！我的腦袋像拼圖忽然間拼湊在一起。$B$B我是卡拉贊改變後第一批被派去調查那裡的人。惡魔莫克札發現了我的侵入。$B$B我很快就知道我不是他的對手。我開始感覺我的靈魂被他的魔法抑制。$B$B在最後一刻我將自己的一部分藏起來……將一部分的記憶藏在我唯一能想到的地方:我的武器裡。莫克札掌握了我的靈魂。你一定要幫我取回它！','打敗卡拉贊裝備著琪安娜意志的莫克札。琪安娜的斷面一定要活下來。','','去找金娜之影。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9663 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9663, 'zhTW', '幫凱索的忙', '你來的正好，$N。這區域的血精靈活動在過去一個禮拜已經加倍了。我們的密探告訴我們自稱為太陽之鷹的血精靈計畫要對藍謎島發動攻擊。我要你去警告一下我們的盟友和同伴。$B$B警告靜松要塞的大酋長靜松，藍色守望的主教米奈奧斯，和奧迪席斯平臺的艦隊司令·奧迪席斯。$B$B時間緊迫所以我借你我的伊萊克。記得不能讓它碰到水。', '凱索十字路的凱索要你去警告靜松要塞的大酋長靜松，藍色守望的主教米奈奧斯，和奧迪席斯平臺的艦隊司令·奧迪席斯關於血精靈即將發動的攻擊。完成任務後回到凱索那裡。你只有15分鐘。', '', '去找鮮血島的凱索。', '已警告大酋長靜松', '已警告主教米奈奧斯', '警告艦隊司令·奧迪席斯', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9664 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9664,'zhTW','建立新據點','歡迎來到瘟疫之地，$n。正如你所知，被遺忘者和他們的盟友控制著西邊的土地，並與我們互相抗衡。聯盟的指揮官們決定在東部建立數個新的據點，以加強我們在敵人外圈的包圍網。$B$B洛丹倫戰爭後期被廢棄的那些哨塔正好用來達成這個目標。不過，這些地方都非常危險，我們需要你的幫助。','奪取東瘟疫之地的皇冠哨塔、東牆哨塔、北地哨塔和病木林哨塔，然後向聖光之願禮拜堂的白鬚大使覆命。','','去東瘟疫之地找聖光之願禮拜堂的白鬚大使。','佔領皇冠哨塔','佔領東牆哨塔','佔領北地哨塔','佔領病木林哨塔',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9665 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9665, 'zhTW', '增強防禦', '被遺忘者密探揭發了聯盟的秘密計畫，他們要在東瘟疫之地被廢棄的哨塔上建立新基地。$B$B現在要緊的是我們不能讓他們在東部邊界建立重要的據點，所以我們一定要趕走這批聯盟入侵者。我們目前的計畫是把他們可能已攻佔的所有哨塔中趕走，並佔據控制那些哨塔不受進一步的攻擊。', '佔領東瘟疫之地的皇冠哨塔，東牆之塔，北地哨塔和病木林哨塔，再回到聖光之願禮拜堂的密使·戈馬克那裡。', '', '去東瘟疫之地找聖光之願禮拜堂的密使·戈馬克。', '已奪得皇冠哨塔', '已奪得東牆之塔', '奪得北地哨塔', '奪得病木林哨塔', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9666 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9666, 'zhTW', '宣示力量', '你有看過毒蛇人嗎?就是自稱納迦的那些人?$B$B<凱索吐了一口口水。>$B$B他們竟敢在三天前趁著夜色的掩護向這營地進軍。你相信那些原始野獸的膽大妄為嗎?$B$B我要你送一個訊息給他們的領導者，$N。東北方的怒鱗巢穴是希司領主的家。找到他，殺了他，把這支旗幟插在他的屍體上。$B$B讓他們知道每當看見我們的軍旗，就是該害怕的時候!', '血謎島，凱索十字路的凱索要你殺了怒鱗巢穴的希司領主，並將德萊尼旗幟插入他的屍體。', '力量的宣言', '去找鮮血島的凱索。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9667 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9667, 'zhTW', '拯救靜松公主', '救救我，$N!鬚肢熊怪把我抓來並且打算將我獻祭給他們骯髒的神祇!$B$B大酋長鬚肢握有開啟籠子的鑰匙。要逼他現身，你必須殺死邪惡的鬚肢熊怪，位置就在這座營地西邊的兩座鬚肢熊怪營地。如果你殺了夠多熊怪，他就會出來報仇!當他出現的時候，殺了他並拿到鑰匙!$B$B如果你救了我，我的父親會重重答謝你的!', '釋放囚禁在籠子裡的靜松公主後與血色守望的靜松大使歐洛格談談。$B$B你得殺掉大酋長鬚肢才能得到籠子的鑰匙。', '', '去找鮮血島的靜松大使法薩布。', '已拯救靜松公主', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9668 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9668, 'zhTW', '向主教阿德密特斯回報', '一個阿古斯之手的士兵代表了很多意義:服從，勇敢，智慧，和最重要的，高尚。你或許還沒展現出這些特質，$c。如果你還對加入阿古斯之手有興趣，就向血色守望的主教阿德密特斯回報吧。他和他的部屬會進一步的以德萊尼士兵的方式訓練你。還有記住，$N:高尚的人不會永遠都做高尚的事，有時候他們身不由己。沿著這條路往北走你就可以找到血色守望。', '和血色守望的主教阿德密特斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9669 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9669, 'zhTW', '失蹤的遠征隊', '大概一個禮拜前，當我和我的研究小組在血謎島西邊的荒野探勘時，遭到嗜血的蜘蛛攻擊。水晶汙染的效果非常明顯，因為這些蜘蛛體型變得既龐大又極具攻擊性。$B$B我設法逃了出來，但我的組員就沒這麼幸運。我們不能讓同樣的命運降臨在其他人身上。去西邊的琥珀網小徑殺死蜘蛛和他們的女王，沙拉克。', '殺死8隻謎霧紡紗者，8隻謎霧吸血者和他們的領導者，沙拉克。任務完成後回到血色守望找阿奇拉斯。', '', '去找鮮血島的阿奇拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9670 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9670, 'zhTW', '他們還活著!或許吧……', '那真是一場血戰啊，$N。我們被一大群蜘蛛給突襲。他們的祖先用不可思議的速度向我們蜂擁而上並把我們包在繭裡。$B$B在我們被纏住後，她開始在我們附近產卵。我們就要成為她幼蟲的食物了!是食物!$B$B我設法逃了出來，但我沒辦法丟下其他人不管。目前為止我都無法成功接近那裡。你可以伸出援手嗎?$B$B摧毀那些繭!希望我們的隊員還有人活著!', '研究員卡尼勒斯要你救出5個遠征隊研究員。', '', '去找鮮血島的研究員卡尼勒斯。', '已釋放遠征隊研究員', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9671 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9671, 'zhTW', '緊急送件', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9672 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9672, 'zhTW', '血咒遺產', '親愛的朋友，我顫抖著手寫下這封信。我希望它能及時送到你手中。昨天夜裡，「失望」號的船長，艾德華·漢尼斯出現在我帳篷前面。和20年前因壞血病而死的艾德華·漢尼斯一模一樣。這個亡魂告訴我一個讓我的心不停顫抖的故事。一個我要你聽的故事和一個我要你完成的任務。你願意接受嗎?你願意去基地東北方的龍痕島找艾德華嗎?艦隊司令·奧迪席斯，敬上', '艦隊司令·奧迪席斯要你找到隊長艾德華·漢尼斯並和他談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9673 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9673,'zhTW','訓練野獸','在你和你所選中的寵物能夠良好地配合作戰之外，還有許多有關寵物的訓練和照料事宜等著你去了解和學習呢。銀月城的野獸訓練師哈森尼斯會教你如何處理的。$B$B只要我的學生也能尊重他，那麼他總是願意付出同等的尊重。去找他吧，別讓我失望。','與銀月城的哈森尼斯談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9674 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9674, 'zhTW', '血咒納迦', '他們說當世界分裂的時候，這座島是最悲情的。數千條夜精靈性命在這裡犧牲而被世人遺忘，原本屬於夜精靈的土地如今興起了為仇恨而生的可怕生物 - 納迦。$B$B他們效忠於他們瘋狂的女王艾薩拉，誓要殺光任何膽敢穿越他們海洋的人。這種情形將會持續數千年，但是現在將要改變。$B$B任務的第一個命令就是解決掉沙洲的血咒納迦。', '龍痕島的隊長艾德華·漢尼斯要你殺死10個血咒納迦。', '', '去找鮮血島的隊長艾德華·漢尼斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9675 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9675,'zhTW','野獸訓練','哦，還有一件事！你應該去找一下艾克索達的甘納爾。他會教你許多有關照顧和訓練寵物的知識。$B$B他就在貿易階梯的西南角。','與艾克索達貿易階梯內的甘納爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9676 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9676, 'zhTW', '聖騎士訓練', '當你在職業中不斷進步，你會想從職業訓練師所能提供你的訓練中獲得助益。對逐日者之島這裡的年輕聖騎士而言，你們的訓練師是傑斯賽尼斯·擊日者。和傑斯賽尼斯談談，看他能提供什麼訓練給你。他的訓練需要收費，所以帶一些錢在身上。你的訓練師 - 和逐日者之島上所有的訓練師一樣 - 都在日尖塔的較低層。', '和傑斯賽尼斯·擊日者 - 聖騎士職業訓練師 - 談談，他就在逐日者之島的日尖塔裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9677 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9677,'zhTW','騎士領主布拉德瓦羅的召喚','$N，你在早期的訓練中已經展示出了成為一個優秀血騎士的驚人天賦。你將接受下一階段的訓練，首先騎士領主布拉德瓦羅會和你談談。$B$B我想騎士領主布拉德瓦羅一定會想要透過試煉來考察你的能力和訓練成果。你可以在銀月城遠行者廣場的血騎士總部找到他。祝你成功，$N。','與銀月城遠行者廣場的騎士領主布拉德瓦羅談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9678 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9678,'zhTW','第一項試煉','你已經學習過許多關於戰鬥與犧牲這方面的事了，見習騎士。但你還有更多的東西需要掌握。$B$B對聖光的理解與掌握需要你擁有高度集中的精神和堅固而強大的意志力。沒有這些，你至多隻能算是個比一般的街頭小混混略強一點的小人物而已。$B$B在鬼魂之地的東北邊界附近有一座小島，名叫苦難島，我們一般都在那裡磨礪自己的技藝。你會在那裡的一處洞穴中找到一隻火盆。跪在火盆前，點亮它，並集中精神，看看你眼前會發生什麼吧。','轉至騎士領主布拉德瓦羅所描述的那座小島，找到洞穴，並點亮火盆。當第一個試煉完成之後，向銀月城的騎士領主布拉德瓦羅覆命。','','去找永歌森林的騎士領主布拉德瓦羅。','完成第一個試煉','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9679 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9679,'zhTW','回到騎士領主伯洛德瓦勒身邊','你的襲擊者已死，但他的話聽起來好像他出現在這裡不是個意外。這隻能代表騎士領主伯洛德瓦勒所說的試驗的一部分。$B$B你在苦難中活了下來並完成了騎士領主要你做的事，你應該回到銀月城向他報告。','向銀月城的騎士領主伯洛德瓦勒報告。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9680 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9680,'zhTW','挖掘歷史','卡姆希絲說得對！這裡面的內容至關重要。$B$B你看，這裡寫道，當時麥迪文將自身生命的精華與他所施展的法術相融合，擊敗了藍龍阿坎納苟斯。如果這是真的，那就意味著我們有很大的機會從藍龍的屍骸中分離出麥迪文的生命精華的殘留物質。天啊，這逆風小徑中，竟掩藏著這樣偉大的未知奧秘，等待著世人發覺。$B$B你立刻到卡拉贊之塔南方的山脈中去取回一塊龍骨的碎片回來。','大法師奧圖魯斯要求你轉至逆風小徑，從卡拉贊以南的山脈中取回一塊焦骨碎塊。','','去找逆風小徑的大法師奧圖魯斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9681 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9681,'zhTW','掌握力量','不要認為我這樣做很過分，$N。桑利亞斯·靜刃很清楚地知道他被派過去的使命。他充分理解並接受了他的職責，他是所有熱誠而積極的血騎士所要學習的榜樣。$B$B我在這裡說的話可不是在為他歌功頌德，$N。桑利亞斯·靜刃對我們的卓越貢獻遠比這些要偉大，而你則是他獲得新生的工具。$B$B你當前所學習到的所有聖光之道，不過是些上不得廳堂的小把戲小伎倆而已。在凱爾薩斯背叛了我們，並且奪走了我們的能量源之後，你必須學習掌控聖光的新方法。立刻去找阿斯塔洛·血誓吧。','與血騎士總部樓下密室中的魔導師阿斯塔洛·血誓談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9682 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9682, 'zhTW', '絕望者……', '在沙洲的突出處，比你發現血咒納迦再深入一點的地方，可以找到絕望者:血咒航海者，那些被血咒抓去的鬼魂。$B$B我現在要你做的事，讓人感到不忍心……但他們一定要被消滅並把他們被詛咒的軀殼帶回來給我。$B$B他們的靈魂一定要得到安息。等你完成了我要求的事情再回來找我，我就會給你最後的一個任務。', '龍痕島的隊長艾德華·漢尼斯要你帶回4個血咒靈魂。', '', '去找鮮血島的隊長艾德華·漢尼斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9683 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9683, 'zhTW', '終止血咒', '你會在南方找到血咒島。在島的頂端你會找到一座獻給摯愛的納迦女王，艾薩拉的神殿。摧毀那個雕像 - 把它燒毀!這一定會引起阿托夫，血咒領導者的憤怒。$B$B殺了阿托夫再回來找我!', '龍痕島的隊長艾德華·漢尼斯要你摧毀艾薩拉女王雕像並殺了血咒的阿托夫。', '', '去找鮮血島的隊長艾德華·漢尼斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9684 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9684,'zhTW','駕馭聖光','拿著這隻瓶子，$N。啟動其中的魔法，你就可以吸取這些魔導師身上殘存的光明能量。他們曾經負責控制那個被我們捕獲的納魯，因此納魯的能量還有一部分留在他們體內。$B$B這應該就足以讓你的夥伴起死回生了。$B$B不用為這些魔導師擔心，$N。我正在照料他們，而且索拉納·血怒大人向我保證過，莉亞德琳大人正在積極尋找新的能量源。','用血精靈魔導師身上的能量裝滿微光容器，然後向銀月城的騎士領主布拉德瓦羅覆命。','','去找永歌森林的騎士領主布拉德瓦羅。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9685 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9685,'zhTW','救贖死者','在你準備這隻瓶子的時候，我派一些人去帶回了桑利亞斯·靜刃的遺體。你可以在銀月城旅店的頂樓找到他，應該還有一個侍從陪在他邊上。你現在就立刻到他那裡去，利用瓶中的魔法力量使他重新獲得生命吧。$B$B時間很寶貴，$N。如果時間過得太久，即使是聖光的力量也無法使他回到我們身邊了。在你復活了桑利亞斯·靜刃之後，立刻回到我這裡來。','帶著裝滿的微光容器到銀月城旅店去，使用其中的力量復活桑利亞斯·靜刃。','','去找永歌森林的騎士領主布拉德瓦羅。','復活桑利亞斯·靜刃','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9686 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9686,'zhTW','第二項試煉','現在你在騎士團中已經是最接近正式騎士地位的見習成員了，$N。但真正成為正式騎士之前，你必須還要接受另一個試煉，以證明你自己的價值。$B$B第二個試煉與前一個最大的不同之處在於，這次將不會有任何令你吃驚的成分。你需要面對的挑戰很簡單，只需要依次與四名最優秀的血騎士英雄比武就可以了。$B$B在你接受挑戰之後，一顆水晶會出現在帳篷中央。你只需碰觸這顆水晶就可以開始試煉了。注意，比武中千萬不要遠離這座建築物。$B$B你準備好了嗎？','擊敗克雷倫·血傷一旁帳篷中的勇士布拉維·血怒、勇士萊倫德·光痕、勇士瑪爾婭·迅刃和勇士斯塔克·射日者，完成第二項試煉。','完成第二項試煉','去永歌森林找銀月城廢墟的克雷倫·血傷。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9687 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9687, 'zhTW', '恢復聖潔', '不久以前，區域裡曾經平靜的梟獸出現在島的海岸。他們會一個接一個來偷取陣亡的龍骨。我不知道是什麼讓這些生物這樣苦惱，或是他們為什麼會想要死者的骨頭，但那些後裔的靈魂因為這樣悖理逆天的行為無法安息。$B$B到西邊去，穿過赤紅地帶，你會找到怒羽山脊。進入梟獸營地取回被偷走的龍骨。', '龍痕島的托瑞斯王子要你取回8根龍骨。', '', '去找鮮血島的托瑞斯王子。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9688 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9688, 'zhTW', '進入夢境', '你在這島上看到的幼龍都是綠龍軍團被激怒的靈魂。就像我一樣，他們都被束縛在這塊土地上，無法回到他們在夢境之國的最後安息之地。$B$B取得亡者的骨頭會暫時讓他們平息下來，但你一定要採取進一步的行動。$B$B解放他們永恆的束縛。在完成之前我不能離開這裡。他們一定要被釋放!', '龍痕島的托瑞斯王子要你殺死5隻翠綠色幼龍和5隻翠綠色小龍。', '', '去找鮮血島的托瑞斯王子。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9689 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9689, 'zhTW', '瑞索默', '許多黑龍軍團的成員都在攻擊中被殺了。這些亡魂中有一名死亡之翼的副官，他的靈魂現在還出沒在這個地方。如果你望著天空，你會看見他的鬼靈面容在空中環繞。他的仇恨心太重以致於連死後都還心懷憤恨。$B$B帶著你先前為我收集的骨頭到這座島的山頂上，將它們放在永不熄滅的柴堆裡。此舉會發出一種訊息使瑞索默降下來查看究竟。到時候就殺死他的不死身驅。', '龍痕島的托瑞斯王子要你殺了瑞索默。', '', '去找鮮血島的托瑞斯王子。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9690 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9690,'zhTW','第二項試煉','見習騎士$N，這段時間以來，你一直努力地學習著控制魔導師們為我們奪來的聖光之力。你已經充分瞭解到了我們能力的來源與血騎士的職責。$B$B現在是時候讓你接受第二個試煉，並為獲得正\\r\\n式的血騎士地位而努力了。這次的試煉將由城北的克雷倫·血傷負責管理，你只需向北穿過銀月城廢墟，然後在通向逐日島的橋前沿路折向東方就可以找到他了。','向克雷倫·血傷報到。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9691 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9691,'zhTW','返回銀月城','立刻返回銀月城向騎士領主布拉德瓦羅報到吧。你的到達就會讓他瞭解到試煉的結果。$B$B他會告訴你，若想成為一名正式騎士，接下來你還有哪些剩餘的任務需要完成。抬高你的徽記，$N。許多人都曾接受過這個試煉的挑戰，但卻很少有人能成功地回來。','向銀月城的騎士領主布拉德瓦羅報到。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9692 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9692,'zhTW','騎士之路','在新的正式騎士被騎士團接受之前，$g他:她必須首先鍛造一把騎士團特有規格的武器，也就是淬血長矛。$B$B此外，你還需要爭取到佩戴騎士團徽章的權利。自騎士團建立之日起，我們的徽章就嚴格控制著總數，每一名新晉級的正式騎士都需要從一名資深騎士那裡繼承徽章。你的徽章曾屬於一名勇敢帶隊突襲了戴索姆的騎士，可這位騎士已經犧牲了。$B$B這裡還有一份筆記，你需要按照上面的說明去做。','將一塊被汙染的科爾寶石、一箱血鑄鐵錠、一份憤怒者之血和一枚血騎士徽章交給銀月城的騎士領主布拉德瓦羅。','','去找永歌森林的騎士領主布拉德瓦羅。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9693 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9693, 'zhTW', '阿古斯對我的意義', '阿古斯對你而言有什麼意義，$N?你大概和許多德萊尼一樣不知道或不記得我們的家園。我們在那裡和曼那瑞分開:那是薩格拉斯『賦予』我們一族的扭曲惡魔形態，或是如他們所自稱的，埃雷達爾。埃雷達爾……這個字曾經有它的意義。<阿德密特斯好像在品嚐這個字一樣。>真噁心。不要再浪費時間了。找到復仇者波羅斯展開你的訓練。', '血色守望的主教阿德密特斯要你去和復仇者波羅斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9694 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9694, 'zhTW', '血色守望', '你知道，血色守望是阿古斯之手運作的兩個前鋒基地之一。你已經去過另一個基地藍色守望了;血謎島的情形是完全不同的。當我們第一次到這裡，這片土地是和藍謎島一樣美麗的。我們甚至還稱它為銀色歡地，但是現在疾病散播大地，而更糟的是，我們在艾克索達對抗的血精靈從失事中生還了。這讓我想到你的第一個任務:前往西北方的劍木林除掉所有你見到的血精靈。', '血色守望的復仇者波羅斯要你殺死10個太陽之鷹間諜。', '', '去找鮮血島的復仇者波羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9695 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9695,'zhTW','太陽之王的命令','這份公文非常重要。不幸的是它所使用的語言是你不能理解的嚮導語。$B$B或許Vindicator Boros能看懂。','將太陽之王的命令帶給血色守望的復仇者波羅斯。\\r\\n\\r\\n','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9696 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9696, 'zhTW', '翻譯……', '我們的首席審問者伊萊希雅會說流利的薩拉斯語。把文件帶給她，看看她怎麼說。', '將太陽之鷹書信帶給血色守望的審問者伊萊希雅。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9697 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9697,'zhTW','觀察者莉薩奧','贊加沼澤的生態環境是一項重要的研究課題，尤其是孢子人和沼澤領主的生活習性。相信我，一旦涉足這項科研領域，你就會發現研究工作非常有挑戰性。$B$B轉至贊加沼澤西部的塞納里奧崗哨，跟觀察者莉薩奧談談吧。沿著西邊的道路一直走就到了。她有些……迂腐，可別受她影響。$B$B啊，你還要當心她的貓。','與贊加沼澤塞納里奧崗哨的觀察者莉薩奧談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9698 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9698, 'zhTW', '覲見預言者', '我要你把翻譯的文件親自交給費倫，$N。我不信任那個笨手笨腳的信差。$B$B向預言者解釋血精靈正在從外域接收援軍，他們在艾克索達的德萊尼之中有個間諜。費倫住在艾克索達的聖光地窖。$B$B動作快!', '將翻譯太陽之鷹的書信帶給艾克索達的預言者費倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9699 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9699, 'zhTW', '是真是假', '謝謝你及時的送達，$N。你將要成為阿格斯之手優秀的密探之一了。$B$B要是我們能知道他們在血謎島向誰報告那就好了，還有更重要的，太陽之門在什麼地方……他們似乎有重重戒備 - 不管它是在什麼地方。$B$B你有興趣接一些勘察的工作嗎?$B$B如果可以，請帶著這些命令回到復仇者波羅斯那裡。他會給你下一個任務。', '將費倫的命令帶給血色守望的復仇者波羅斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9700 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9700, 'zhTW', '向黑暗中發射魔法', '費倫表示如果血精靈已在這座島和外域間開啟了裂縫，傳送門開啟的地方就會有召喚儀式的殘餘物或異常者出現。你一定要搜索島上有顯現出這些異象的地方。$B$B小心，$N;有些異象是從虛無本身來的生物。如果你發現虛無反常者，就殺了他們!帶著你找到的新資訊回來向我報告。從北邊開始你的搜索，靠近星移活塞的地方。', '血色守望的復仇者波羅斯要你找到太陽之門地點並殺死5個虛無反常者。', '已確認太陽傳送門地點', '去找鮮血島的復仇者波羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9701 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9701,'zhTW','觀察孢子人','我們要儘可能地調查居住在孢子村的孢子人，瞭解它們的生活習性，以及他們與其它生物之間的關係。這就是我當前的工作：觀察並記錄它們的活動情況。$B$B我希望你轉至西邊的孢殖林，調查整片區域，然後向我彙報你的發現。','調查贊加沼澤的孢殖林，然後返回贊加沼澤的塞納里奧崗哨，向觀察者莉薩奧彙報你的發現。','調查孢殖林','去贊加沼澤找塞納里奧崗哨的觀察者莉薩奧。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9702 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9702,'zhTW','狼吞虎嚥','我一直在想，沼澤領主為何離開自己的地盤，跑去孢殖林覓食——難道是飢餓難耐？這可不行！$B$B唔，通常我不會插手這種閒事，但是如果任由它們吞食孢子囊，孢子人很快就會絕種的！$B$B我決定留在這兒，你去東邊的泥濘山跑一趟吧，調查究竟是什麼原因導致沼澤領主吞食孢子囊。','將10份丟棄的食物交給贊加沼澤塞納里奧崗哨的觀察者莉薩奧。','','去贊加沼澤找塞納里奧崗哨的觀察者莉薩奧。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9703 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9703, 'zhTW', '冬眠核心', '我們還有其他人在尋找太陽之門的線索，$N。我要你先專注於手上的工作。$B$B波羅斯收到一則新報告指出有另一個失事地點。我們發現那個失事地點就是艾克索達的冬眠核心。這是覆蓋船艙的支撐區域，就和我們德萊尼從安曼谷爬出來的那個船艙一樣。$B$B這個區域也有醫療補給。前往冬眠核心，就在血色守望正西邊。尋找物資及生還者。', '血色守望的復仇者庫羅斯要你取得12箱醫療補給。', '', '去找鮮血島的復仇者庫羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9704 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9704,'zhTW','失心者的犧牲品','信使是個艱苦的差事，需要頻繁往返於逐日島和鷹翼廣場。時間緊迫，路途遙遠，最糟糕的是還要對付失心者！$B$B南面的道路一直通往銀月城廢墟……盤踞在廢墟中的失心者會為了幾塊法力水晶大肆殺戮。我們曾派出一位信使投遞艾洛娜的包裹，我想他大概已經慘遭不幸了。$B$B你似乎躍躍欲試想要證明自己的實力。那麼，轉至黎明之路尋找這位信使的下落吧。','往南進入銀月城廢墟，在黎明之路附近尋找被殺死的信使。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9705 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9705,'zhTW','找回包裹','經過仔細辨認，這個包裹確實是魔導師艾洛娜的東西。奧拉莉恩應該會讓你把這東西歸還給她吧。','將艾洛娜的包裹交給信使奧拉莉恩。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9706 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9706, 'zhTW', '高拉恩的日誌 - 復仇者薩魯安的命運', '你的手顫抖著撿起書。庫羅斯一定知道這個悲劇了。將書還給他。', '將高拉恩的日誌帶給血色守望的復仇者庫羅斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9707 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9707,'zhTW','鑄造武器','你又一次在騎士團與你的同齡人面前證明了自己的價值。我現在懷著極大的喜悅授予你正式騎士的銜位，$N。凱爾薩斯王子也會為你而感到自豪的。$B$B我們所有人都為能與你並肩作戰而感到榮幸。繼續以身作則，讓那些想要加入我們的血精靈以你為榜樣吧。你要拒絕一切仁慈與懦弱，保衛你的人民與兄弟，並繼續提高你在聖光運用上的造詣。$B$B現在，去領取那把象徵晉級的武器吧。','將這箱材料交給銀月城的波瑪爾。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9708 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9708,'zhTW','熟悉的蘑菇','唔，對，我記得曾在贊加沼澤的某處見過這種特殊的蘑菇！$B$B此地以北就是菌杆沼澤。真是個奇怪的地名，不過我從來沒有去過那兒。我需要一些蘑菇樣本來驗證自己的猜測是否正確。$B$B$c，千萬小心。聽說菌杆沼澤是食人魔的駐地，恐怕你得從他們手中搶些蘑菇樣本。這或許就是沼澤領主不去那兒覓食的原因。','將15份蘑菇樣本交給贊加沼澤塞納里奧崗哨的觀察者莉薩奧。','','去贊加沼澤找塞納里奧崗哨的觀察者莉薩奧。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9709 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9709,'zhTW','偷回蘑菇','$C，我想到解決此事的辦法了。我要你再去北邊跑一趟，深入食人魔駐地的中心！$B$B菌杆沼澤西北方有一座巨大的蘑菇橋，橋對面的浮島名叫安葛洛什要塞。$B$B食人魔肯定會把蘑菇儲存在要塞中。我敢打賭那兒到處都是蘑菇，說不定你還可以在食人魔身上找到它們！$B$B替我帶回幾箱蘑菇，我會試著為沼澤領主提供新的食物。','將10箱蘑菇交給贊加沼澤塞納里奧崗哨的觀察者莉薩奧。','','去贊加沼澤找塞納里奧崗哨的觀察者莉薩奧。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9710 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9710,'zhTW','淬血長矛','一切都已經準備好了，$N。很快你就將擁有一件與你的地位相稱的武器。','等待波瑪爾為你鍛造出你的武器。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9711 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9711, 'zhTW', '殘忍的馬帝斯', '馬帝斯會得到正義的，$N;我要你找到他並把他帶回三頭政治。$B$B搜索島嶼找到這個混蛋。如果你找到他，就使用這把信號槍。我的追蹤者看到閃光就會前去協助逮捕馬帝斯。抓到他後再來找我。', '血色守望的復仇者庫羅斯要你抓到殘忍的馬帝斯。', '殘酷的馬提斯已捕獲', '去找鮮血島的復仇者庫羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9712 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9712,'zhTW','薩拉斯戰馬','你在騎士團中的服務非常優異而出色，$N。你對聖光之力的運用技巧證實了魔導師阿斯塔洛與他的同伴教授你這些知識的努力沒有白費，他們的工作是值得的。$B$B既然你已經掌握了聖光的力量，那麼你完全可以召喚出一匹健壯的戰馬，作為你忠實的坐騎。$B$B繼續為騎士團帶來貢獻與榮耀吧，$N，更加美好的前臺在等待著你。','與騎士領主布拉德瓦羅交談，學習如何召喚你的薩拉斯戰馬。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9713 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9713,'zhTW','白閃菇可採集標誌','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9714 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9714,'zhTW','我還要紅色木槿！','','','','去贊加沼澤找孢子村的舒特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9715 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9715,'zhTW','我要紅色木槿！','紅色木槿的用途廣泛，因此我們需要補充這種花朵的儲量。它們原本跟灌木一樣茂密，但是沼澤水位下降後，就只能在盤牙水庫的幽暗沼澤中見到紅色木槿了。$B$B據說蹣跚者、泥沼巨人和幽暗蝠將其視為美食。如果你願意幫助我們的話，就去獵殺這些沼澤生物，將紅色木槿帶回來給我。','將5朵紅色木槿交給贊加沼澤孢子村的舒特。','','去贊加沼澤找孢子村的舒特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9716 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9716,'zhTW','暗澤湖的異常','我們滿懷期冀地來到外域，希望能發現新的物種。剛到贊加沼澤時，我們所見的是一處繁榮茂盛的生態系統。$B$B可惜最初的判斷是錯誤的。經過測量，我們發現這個區域的湖泊和沼澤的水位在不斷下降。$B$B這很可能給當地的動植物帶來毀滅性的災難。轉至西南方的暗澤湖，調查水位下降的原因。','調查暗澤湖水位下降的原因，然後返回贊加沼澤的塞納里奧避難所，向伊謝爾·風歌覆命。','調查暗澤湖','去贊加沼澤找塞納里奧庇護所的伊謝爾·風歌。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9717 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9717,'zhTW','孢子葉','雖然我們愛好和平，卻不得不與泥沼巨人交戰。有句諺語是這麼說的：蘑菇，戰爭，都要不擇手段！$B$B霍加爾芬是泥沼巨人的首領之一，他負責照料那株名叫幽暗孢子的特殊植物。如果這株壽命已有千年的植物受到任何損傷，對霍加爾芬而言必定是個沉重的打擊。$B$B轉至盤牙水庫的幽暗沼澤，偷偷摘取一片幽暗孢子葉。相信我，他會察覺你的行為的。','將一片幽暗孢子葉交給贊加沼澤孢子村的塔蘇。','','去贊加沼澤找孢子村的塔蘇。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9718 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9718,'zhTW','烏鴉的飛翔','我們必須查明納迦的活動範圍，以便採取相應的措施。$B$B逐一調查贊加沼澤的湖泊將會耗費大量時間。如果你願意的話，我可以使用魔法將你變形為更適合執行偵察任務的飛鳥。$B$B當你準備就緒後，就在我附近的平臺上使用這個護符。完成任務後，我會指引你安全返回的。','伊謝爾·風歌要求你使用風暴烏鴉護符，然後調查贊加沼澤的主要湖泊。','調查贊加沼澤的湖泊','去贊加沼澤找塞納里奧庇護所的伊謝爾·風歌。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9719 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9719,'zhTW','黑色闊步者','一直以來，我們都將泥沼遊蕩者視為最大的威脅。如今我們卻要面臨來自泥沼巨人的攻勢，恐怕無力與宿敵抗衡。$B$B$c，你是位頗具實力的勇士。你願意前往盤牙水庫的幽暗沼澤，殺死泥沼遊蕩者之母——黑色闊步者嗎？$B$B做為憑證，將它的大腦帶回來給我。','將黑色闊步者的大腦交給贊加沼澤孢子村的肯尼克斯。','','去贊加沼澤找孢子村的肯尼克斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9720 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9720,'zhTW','恢復平衡','我無法理解納迦為何要將水排出自己的棲息地，我只知道必須制止他們的行為。$B$B這些種子包含著大地的憤怒，我要你利用它們破壞納迦的蒸汽泵控制檯。$B$B從種子中抽出的藤蔓會像你的手臂一樣粗壯，像鑄鐵一樣堅硬。$N，去吧。恢復贊加沼澤原有的生態平衡。','伊謝爾·風歌要你利用鐵藤種子，破壞毒蛇湖、暗澤湖、沼光湖和環礁湖的蒸汽泵控制檯，然後返回贊加沼澤的塞納里奧庇護所，將剩餘的鐵藤種子還給她。','','去贊加沼澤找塞納里奧庇護所的伊謝爾·風歌。','破壞暗澤湖控制檯','破壞沼光湖控制檯','破壞毒蛇湖控制檯','破壞環礁湖控制檯',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9721 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9721,'zhTW','索拉納大人的召喚','最近一段時間裡，你對騎士團的卓越貢獻，以及你身為騎士的逐漸進步，我們都看在眼中。事實上，索拉納·血怒——女伯爵莉亞德琳的左膀右臂——已經決定召見你。$B$B這是一個只有極少人才能獲得的光榮，$N。通常來說，索拉納·血怒只將騎士團的階級和文書管理工作交給我，但這次，他對你有了一些個人上的興趣。別讓他等太久，$N。','與銀月城的索拉納·血怒談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9722 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9722,'zhTW','大師之路','在騎士團的各階級之中，存在著一個僅由精英騎士組成的內環議會。議會的成員都是由領導層親自挑選出的最具奉獻精神、最值得信賴，以及技巧最為優秀的血騎士。這些大師們最顯著的標誌就是他們所擁有的薩拉斯戰馬坐騎。$B$B每名議會的預備成員都必須擁有一個議會內的推薦人，並需要表現出他們對騎士團核心原則的奉獻與尊崇。$B$B鑑於你的優秀表現，我已被選為你的推薦人，將以血騎士大師的身份推薦你加入議會，不知道你是否願意加入。','再次與索拉納·血怒交談，接受他對你的推薦。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9723 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9723,'zhTW','血騎士的義務','血騎士的忠誠並不僅僅體現在$g他:她的劍上，$N。騎士團對其成員的要求也不僅僅在於殺戮與戰鬥。一位真正的騎士能夠對騎士團所有的活動做出貢獻，儘管其中有些在表面上看起來可能不是那麼光鮮。$B$B第一個任務不需要你去戰鬥，看起來也並不光榮，但如果沒有人做出這樣的貢獻，騎士團必將衰落。我先給你一張清單，魔導師阿斯塔洛·血誓的人需要這些物品，否則就無法持續供應給我們聖光能量了。','將40塊符文布、6塊奧金錠、10株太陽草、5個黑暗符文和150枚金幣交給銀月城的索拉納·血怒。','','去找銀月城的索拉納·血怒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9724 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9724,'zhTW','通知塞納里奧議會','塞納里奧遠征隊已經成為了一個強大且獨立的組織。這件事情非常重要，我們必須提醒塞納里奧議會。$B$B用不著擔心，我不會讓你回月光林地的。在地獄火半島上就有我們的信使。','與地獄火半島的塞納里奧哨站中的阿米希爾·迷霧行者談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9725 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9725,'zhTW','忠誠的表現','我們血騎士以保衛奎爾薩拉斯為己任，$N。這是你所接受的一切訓練的核心目的。我們的敵人兇猛殘暴而冷酷無情，銀月城和她的居民卻能因為我們的努力與盟友們的援助而安然無恙。$B$B我最近收到了一些訊息，據說一批新生成的天災軍團出現在了我們領土與東瘟疫之地的邊界附近。而眾多天災軍團的攻城裝置及負責操作它們的工程師也已經到位，似乎想要進攻鬼魂之地。一定要阻止它們！','銀月城的索拉納·血怒要求你摧毀3臺天災絞肉車，並殺死15名天災攻城技師。','','去找銀月城的索拉納·血怒。','','摧毀天災絞肉車','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9726 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9726,'zhTW','既然我們是朋友……','東北邊血鱗領地的納迦正在追殺我們的人民。我們絕對不容許這樣的事情繼續發生，$c！$B$B希望你能去給他們點顏色瞧瞧，同時也可以證明我們之間的友誼。','殺掉12個血鱗驅奴者和6個血鱗女巫，然後向贊加沼澤孢子村的舒特覆命。','','去贊加沼澤找孢子村的舒特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9727 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9727,'zhTW','既然我們仍是朋友……','有報告說東北邊血鱗領地的納迦還在繼續追殺我們的人民。我們覺得你有經驗去解決這件事，$c！$B$B我想委託你去好好教訓教訓他們，作為我們友誼延續的證明。','殺掉12個血鱗驅奴者和6個血鱗女巫，然後向贊加沼澤孢子村的舒特覆命。','','去贊加沼澤找孢子村的舒特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9728 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9728,'zhTW','熱情的歡迎','在塞納里奧遠征隊的德魯伊們忙於研究植被和勘測湖泊時，我承擔起了保衛庇護所的重責。$B$B自打我們來到贊加沼澤，納迦就在毫無徵兆的情況下多次對我們發動突襲。我們已經盡力牽制他們的攻勢，可惜畢竟人手有限。$B$B我想讓你轉至納迦在贊加沼澤的各個據點，讓他們明白我們不是好惹的。把納迦的爪子帶回來給我，作為你擊殺他們的證據。','將30個納迦爪子交給塞納里奧庇護所的監護者哈穆特。','','去贊加沼澤找塞納里奧庇護所的監護者哈穆特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9729 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9729,'zhTW','弗沃爾發怒了！','納迦惹惱了弗沃爾！孢子人是弗沃爾的朋友，所以弗沃爾要搶走薩斯里斯聖櫃。$B$B我們去附近的納迦村落吧。你願意幫忙嗎？那就叫上你的朋友！','護送弗沃爾進入沼光湖水域，在蒸汽泵處找回薩斯里斯聖櫃，保護弗沃爾攜帶聖櫃安然返回，然後向贊加沼澤孢子村的舒特覆命。','將薩斯里斯聖櫃送回孢子村','去贊加沼澤找孢子村的舒特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9730 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9730,'zhTW','暗潮納迦的首領','塞納里奧遠征隊重金懸賞擊殺暗潮納迦首領——哈格哈茲王子的勇士。塞納里奧斥候最後一次發現哈格哈茲是在贊加沼澤中南部的環礁湖。$B$B暗潮納迦曾多次襲擊塞納里奧遠征隊，他們的首領被視為極度危險的人物。$B$B誅殺哈格哈茲王子的勇士可在監護者哈穆特處領取獎賞。','殺死環礁湖的哈格哈茲王子，然後返回贊加沼澤的塞納里奧遠征隊，向監護者哈穆特領取獎賞。','','去贊加沼澤找塞納里奧庇護所的監護者哈穆特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9731 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9731,'zhTW','抽水泵結構圖','這張結構圖上繪製著連線毒蛇湖和鄰近湖泊的地下排水系統。$B$B如果圖表屬實的話，那麼毒蛇湖的中心必定有一臺巨大的抽水泵。核實這個訊息是否屬實，然後返回塞納里奧庇護所覆命。','轉至毒蛇湖搜尋抽水泵的蹤跡，然後向塞納里奧庇護所的伊謝爾·風歌彙報你的發現。','發現抽水泵','去贊加沼澤找塞納里奧庇護所的伊謝爾·風歌。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9732 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9732,'zhTW','返回沼澤','轉告伊謝爾，我們會盡快提供增援。$B$B大家正為月光林地和希利蘇斯的事務忙得不可開交，但是我們會盡量抽調人手轉至塞納里奧庇護所幫忙的。','返回贊加沼澤的塞納里奧庇護所，向伊謝爾·風歌覆命。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9733 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9733,'zhTW','通知塞納里奧議會','塞納里奧遠征隊已經成為了一個強大且獨立的組織。這件事情非常重要，我們必須提醒塞納里奧議會。$B$B用不著擔心，我不會讓你回月光林地的。在地獄火半島上就有我們的信使。','與地獄火半島的索爾瑪城中的瑪霍拉姆·硬蹄談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9734 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9734,'zhTW','回到沼澤','回去向Ysiel報告，告訴她增援軍會盡快到達。$B$B我們的軍隊正忙於月光林地和希利蘇斯戰鬥，不過我們一定會盡力將必須的資源送去塞納里奧庇護所的。','返回向贊加沼澤塞納里奧庇護所的Ysiel覆命。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9735 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9735,'zhTW','聖光的主人','血騎士能夠以一種那些所謂的“聖騎士”完全無法理解的精妙技巧運用聖光的力量。但儘管我們發揮出了聖光的真正潛能，他們仍然保持著對我們的輕視。$B$B我們必須把自己的力量展示給他們，告訴他們，我們絕對不是他們可以隨意嘲諷的物件。我當前已經有了一個主意，不過它有些複雜，也很艱難。但我想，你一定可以勝任。那麼，首先你需要潛入提爾之手修道院的圖書館區，並獲得一瓶提爾之手聖水。','銀月城的索拉納·血怒要求你給他帶回一瓶提爾之手聖水。','','去找銀月城的索拉納·血怒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9736 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9736,'zhTW','聖光的主人','現在我們擁有聖水了，但還需要一些其它的材料。$N，這其中有些物質十分稀有，而且價格昂貴，但我已經找到了可靠的貨源。$B$B你應該可以從一個名叫索爾雷的材料商那裡買到一些奧術觸媒，他的商店開在死亡之痕附近的一處曠野上。城內謀殺小徑的盜賊訓練師一旁的毒藥商達爾莉亞那裡有一些黃昏之塵的存貨。$B$B此外，要完成這種混合藥劑，我還需要一顆艾澤拉斯鑽石和一顆原始黑鑽石。','銀月城的索拉納·血怒要求你給他帶回一份奧術觸媒、一份黃昏之塵、一顆艾澤拉斯鑽石和一顆原始黑鑽石。','','去找銀月城的索拉納·血怒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9737 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9737,'zhTW','聖光的主人','我們利用聖光的方式才是最完美的方式，$N。一定讓那些自稱“聖騎士”的傢伙們知道他們利用聖光的方式有多麼的愚蠢，一定要把這個事實明明白白地擺在他們的面前。$B$B阿隆索斯禮拜堂是白銀之手騎士團組建的地方，似乎在毀滅斯坦索姆的大火之中也被完整地儲存了下來。這處教堂裡的永恆之焰有著聖光力量的保護，但如果你使用這份藥劑的話，就可以熄滅那裡的火焰，保護結界也會不復存在。火焰熄滅之後，我們對聖光的統馭之力就會被全世界知曉了。','在阿隆索斯禮拜堂的永恆之焰上使用熄焰之水，除去聖光的保護，然後消滅所有試圖保衛禮拜堂的人。','','去找銀月城的索拉納·血怒。','解除阿隆索斯禮拜堂的保護','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9738 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9738,'zhTW','失蹤的同伴','你必須幫助我！伊謝爾派我們來這裡調查神秘的蒸汽泵事件，以及納迦為什麼要利用蒸汽泵排出沼澤地的水。但是我的幾位同伴鬧了彆扭，竟然撇下我獨自行動。$B$B那四個傢伙有時候脾氣是挺古怪，不過我還是很喜歡他們的。$B$B我要你查明他們到底出了什麼狀況，我很擔心他們遭遇不測。去奴隸圍欄和幽暗沼澤看看吧。$B$B謝謝你，$c。','查明縛地者雷葛、博學者拜特、除草者格林薩姆和喚風者克勞恩的下落，然後返回贊加沼澤的盤牙水庫，向觀察者傑哈恩覆命。','','去贊加沼澤找盤牙水庫的觀察者傑哈恩。','找到縛地者雷葛','找到博學者拜特','找到除草者格林薩姆','找到喚風者克勞恩',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9739 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9739,'zhTW','孢子人的困境','喂，叫你呢！你必須幫助我們！$B$B真菌巨人正在吞食孢子囊！必須想點什麼辦法，不然我們的孩子就都沒命了！$B$B孢子囊剛剛開始生長的時候體積較大，隨著囊內空氣的消耗會逐漸縮小。尋找那些體積較小的成熟的孢子囊，盡你所能地拯救它們！','孢殖林的法恩森要你收集10個成熟的孢子囊。','','去贊加沼澤找孢殖林的法恩森。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9740 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9740, 'zhTW', '太陽之門', '多虧了你和你做的努力，我的斥候才能找到太陽之門。精靈讓傳送門的位置保持活動，這樣他們才能瞬間移動它。這是為什麼你調查到的地點是空的。$B$B這個系統的優點也是它最大的缺點。太陽之門由傳送門控制器來穩定。如果我們可以擊敗控制器，我們就能摧毀傳送門。目前太陽之門的位置在西邊，旋繞導航器的南方。找到並摧毀它!', '血色守望的復仇者艾伊森要你摧毀太陽之門。', '', '去找鮮血島的復仇者艾伊森。', '摧毀太陽之門', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9741 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9741, 'zhTW', '虛無異常者', '幾天前艾伊森派我的小組去進行一個勘察任務，搜索太陽之門。不用說，我們發現了……$B$B<羅莉指著喬爾力。>$B$B不管那些蠢精靈透過傳送門在傳送什麼，這讓虛無能量不斷被釋放。那個區域到處都是虛無異常者。$B$B我們一定要在他們有機會變成虛無反常者前毀了他們。你可以在西南方靠近太陽之門的地方找到這些生物的發源地。殺了他們，完成後向艾伊森報告。', '殺死12個虛無異常者再向血色守望的復仇者艾伊森回報。', '', '去找鮮血島的復仇者艾伊森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9742 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9742,'zhTW','更多孢子囊','','','','去贊加沼澤找孢殖林的法恩森。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9743 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9743,'zhTW','天敵','孢子人與沼澤領主是世代的宿敵。過去，我們利用長矛和石塊與之抗衡。近來他們似乎變得更具攻擊性……並且更加不計後果。他們不再懼怕我們，也無視我們手中的武器。$B$B你的威懾力和裝備都遠勝於我們。如果你願意替我們打敗沼澤領主的話，孢子人會永遠感激你的！把他們的卷鬚帶回來給我，這樣我就知道你確實在幫助我們了。','將6根沼澤領主的卷鬚交給贊加沼澤孢殖林的法恩森。','','去贊加沼澤找孢殖林的法恩森。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9744 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9744,'zhTW','更多卷鬚！','','','','去贊加沼澤找孢殖林的法恩森。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9745 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9745,'zhTW','熄滅火焰','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9746 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9746, 'zhTW', '體能極限', '勝利就只差臨門一腳，$N。發現了太陽之門，他們的補給線不久後就會被完全封鎖了。現在是襲擊他們部隊的時候。$B$B你可以在西邊找到許多的太陽之鷹營地。太陽之鷹控火者和太陽之鷹防衛者佔據了大部分的區域。找到他們，殺了他們，再回來找我。', '血色守望的復仇者艾伊森要你殺死10個太陽之鷹控火者和10個太陽之鷹防衛者。', '', '去找鮮血島的復仇者艾伊森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9747 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9747,'zhTW','暗澤部族','納迦真是可憎的生物，但是暗地裡幫助納迦的破碎者和失落者更加令人厭惡！$B$B其中尤以暗澤失落者部族的行徑最為惡劣，他們利用黑暗的魔法奴役其它人。暗澤失落者對企圖逃跑的奴隸非常殘忍，如果我離開庇護所，肯定會被他們幹掉的。$B$B轉至南邊的暗澤村，殺死暗澤失落者和他們的首領卡塔魯，否則我就要在惶惶不安中度過餘生了。','塞納里奧庇護所的伊卡因希望你轉至暗澤村，殺死卡塔魯、8個暗澤先知、6個暗澤巫醫和6個暗澤神諭者。','','去贊加沼澤找塞納里奧庇護所的伊卡因。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9748 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9748, 'zhTW', '別喝那裡的水', '我們的薩滿聲稱水元素因為水源的污染受到很大的影響。我們知道艾克索達的能量核心位在西邊的山裡。它一定是正滲漏出揮發性的液體到水供給裡!我要你去幫我收集更多資訊。$B$B<艾伊森指向一個瓶子並點點頭。>$B$B你要帶著這個瓶子沿著海邊北方走，直到你到達血謎島的河流匯入海洋的區域。採集那裡的樣本並帶回來給我。', '血色守望的復仇者艾伊森要你使用水樣本瓶取得血謎水樣本。', '', '去找鮮血島的復仇者艾伊森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9749 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9749,'zhTW','他們還活著！或許吧……','真是倒黴透了，$N。我們遭到了一大群蜘蛛的突襲。他們的先驅以驚人的速度突然襲擊我們，將我們困在蜘蛛網裡。$B$B我們被網纏住後，她開始在我們附近產卵。我們將成為她後代的食物！食物！$B$B我費盡力氣逃了出來，但我不能丟下其它人不管。直到現在我也沒能將他們解救出來。你能幫幫我嗎？$B$B毀掉那些蜘蛛網！希望我們隊的人還活著！','研究員卡尼勒斯要你救出5個遠征隊研究員。','','去秘血島找琥珀蛛網小徑的研究員考內留斯。','Expedition Researcher Freed','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9750 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9750,'zhTW','傳遞急件','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9751 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9751, 'zhTW', '血咒遺產', '昨天夜裡，「失望」號的船長，艾德華·漢尼斯出現在我帳篷前面。和20年前因壞血病而死的艾德華·漢尼斯一模一樣。這個亡魂告訴我了一個讓我的心顫抖的故事。一個我要你聽的故事和一個我要你完成的任務。你會去做嗎?你會去找血色守望東北方的龍痕島找艾德華嗎?', '艦隊司令·奧迪席斯要你去找隊長艾德華·漢尼斯並和他談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9752 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9752,'zhTW','逃離暗澤村','你必須幫助我逃離此地！$B$B我在附近採集草藥時，這群野蠻人突然將我團團圍住，企圖綁架我。我奮力反抗，無奈他們人多勢眾。$B$B幫助我返回塞納里奧庇護所，擺脫這幫渣滓和他們那邪惡魔法的控制！','護送凱拉·長鬃返回贊加沼澤的塞納里奧庇護所，然後向伊謝爾·風歌覆命。','護送凱拉·長鬃回到塞納里奧庇護所','去贊加沼澤找塞納里奧庇護所的伊謝爾·風歌。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9753 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9753, 'zhTW', '我們所知道的事……', '我們最近幾天了解了很多敵人的事。血精靈由一個叫賽羅娜斯的人領導並密謀要摧毀我們。最後，他們要征服歐蘿絲並重拾對艾克索達的控制。$B$B讚美聖光，我們摧毀了太陽之門，阻止了他們的補給線。不幸的是，他們持續使用旋繞導航器的污染物來毒害大地，使用幅射性落塵的突變物質來利己。$B$B有了這樣的認識，阿德密特斯便想出個計畫。快去找他。', '和血色守望的主教阿德密特斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9754 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9754, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9755 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9755,'zhTW','','我們對敵人的審訊毫無進展，朋友。無論怎樣刑訊逼供也無法取得任何成果。現在我們需要派遣勇士打入敵人內部。\\r\\n\\r\\n我可以在你身上施展一個法術，讓你從外表和說話風格上都變成一個血精靈。這樣，也許你能幫我們從俘虜那裡套取出一些情報。\\r\\n\\r\\n你要和那些囚犯仔細攀談，儘量讓他們透露更多的資訊。\\r\\n\\r\\n同時還要記住，朋友，在偽裝期間不要離開秘血崗哨，否則偽裝就會失效。','同秘血崗哨中被俘的炎鷹偵察兵交談。取得炎鷹情報。完成任務以後回去見主教埃德門圖斯。','取得炎鷹情報','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9756 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9756, 'zhTW', '我們不知道的事……', '我們嘗試審問的企圖已悲慘地失敗了，$N。折磨 - 當然 - 是絕對會有的。我們需要的是一個在裡面的德萊尼。$B$B我可以對你施放一個法術讓你變成血精靈並調整你的語言。透過一些藉口，我們或許可以獲得被俘虜的密探的消息。$B$B在這樣的偽裝下，我要你盡可能的從囚犯那裡取得資訊。$B$B還有$N，偽裝的時候不可以離開血色守望否則法術就會失效。', '和血色守望被俘虜的太陽之鷹密探談談並取得太陽之鷹情報。完成任務後回報主教阿德密特斯。', '', '去找鮮血島的主教阿德密特斯。', '取得太陽之鷹情報', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9757 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9757,'zhTW','尋找女獵手凱拉·夜弓','女獵手凱拉·夜弓要求附近所有符合條件的獵人都去見她。她會教你馴化野獸的技巧，這是你獵人生涯中最為重要的一門課程。$B$B凱拉就在艾克索達西邊的港口附近。','與瓦拉爾港口附近的女獵手凱拉·夜弓談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9758 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9758, 'zhTW', '回到秘法師范德隆那裡', '我的朋友，希望你可以好心的回到秘法師范德隆那裡，我知道他非常渴望派你來鬼魂之地這裡進行你的第一個任務。我們都靠你了，$N。別讓我們失望。', '回到鬼魂之地的安寧地找秘法師范德隆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9759 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9759, 'zhTW', '結束他們的世界', '如果你珍惜你的生命就不要接下這個任務。你看到遠處那個從山邊突起的巨大能量核心嗎?任何接下這個重擔的人都需要一路戰鬥到那座山上，在保護我的同時要和太陽之鷹軍隊作戰，而我要切斷那個核心以破壞它。賽羅娜斯也在那裡某處。$B$B如果你就此離去我也不會輕視你的，$N。$B$B但或許你就是那個能摧毀旋繞導航器和擊敗賽羅娜斯的人。那麼，你是嗎?', '在破壞者勒茍索嘗試摧毀旋繞導航器並殺死賽羅娜斯時跟著他並保護他。完成任務後回到血色守望的主教阿德密特斯那裡。', '向量線圈已摧毀，希羅娜絲已擊殺', '去找鮮血島的主教阿德密特斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9760 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9760, 'zhTW', '復仇者之陵', '我不會要你獨自一人背負著摧毀旋繞導航器和殺死賽羅娜斯的重擔，$N;不過，我想你可以幫忙為其他可能接下這樣危險任務的人清理道路。$B$B踏上血色守望外往北邊的路並沿著它一直走到岔路。到了那裡，選擇左邊的路並一直走到你看見復仇者之陵 - 它會在路的偏西邊一點。科林會在那邊等你。', '到血謎島和復仇者之陵的復仇者科林談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9761 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9761, 'zhTW', '清除道路', '只有最身經百戰，高尚，又毫無畏懼的德萊尼才會接下於勒茍索的任務。主教不會命令任何一個阿格斯之手的密探接下摧毀旋繞導航器和殺死賽羅娜斯的任務。他拒絕讓任何一個德萊尼去送死 - 像是那些自殺般的任務……$B$B<科林嘆氣。>$B$B我的工作是削弱太陽之鷹的防禦。你要殺死旋繞導航器附近的太陽之鷹並為我們的勇士將道路清空 - 不論我們的勇士是誰。', '復仇者之陵的復仇者科林要你殺死8個太陽之鷹破壞者和8個太陽之鷹密探。', '', '去找鮮血島的復仇者科林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9762 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9762, 'zhTW', '未寫下的預言', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9763 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9763,'zhTW','督軍的末日','當你悄悄地隱藏在敵人的藏身之處外面的入口時，會發現一些非常有用的情報。$B$B幾個小時前，我看到有一群納迦穿過了左邊第二個隧道的石門。我不太懂他們的語言，但是我非常肯定地聽清了其中一個詞：卡利瑟里斯。$B$B那裡一定是通往督軍卡利瑟里斯的指揮營——蒸汽地窟的入口。你必須找到並阻止他。我太虛弱了，沒有辦法幫上一點忙。','觀察者傑哈恩要求你找到並殺死盤牙水庫的督軍卡利瑟里斯。','','去贊加沼澤找盤牙水庫的觀察者傑哈恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9764 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9764,'zhTW','瓦絲琪的命令','這封信中記載了一份詳細的指令，是下達給那些操作蒸汽泵的盤牙納迦的。指令中提到塞納里奧德魯伊已經進入盤牙水庫，並命令他們一旦發現入侵者就格殺勿論。這份命令還指示需要將其它湖泊引入盤牙水庫的水量翻倍。信上蓋有聲名狼藉的瓦絲琪的印章。$B$B塞納里奧遠征隊的德魯伊會對這封信感興趣的。將它交給遠征隊的首領伊謝爾·風歌吧。','將瓦絲琪女王的命令交給贊加沼澤塞納里奧庇護所的伊謝爾·風歌。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9765 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9765,'zhTW','戰爭準備','塞納里奧遠征隊抱著和平的意圖而來，卻不得不面臨與納迦的這場全面戰爭。$B$B遠征隊的許多成員鬥志昂揚地準備投入戰鬥，可惜我們的裝備過於簡陋。替我奪回一些納迦的武器來，這樣我們就能將它們重新鑄造成利刃和箭頭。$B$B$N，我們要利用盤牙武器鑄造最好的兵器。盤牙水庫便是納迦的據點。','從盤牙水庫的納迦手中奪得盤牙武器，將它們交給贊加沼澤塞納里奧庇護所的伊謝爾·風歌。','','去贊加沼澤找塞納里奧庇護所的伊謝爾·風歌。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9766 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9766,'zhTW','盤牙武器','','','','去找伊謝爾·風歌。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9767 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9767, 'zhTW', '[Know Your Enemy]', '[Defeating an enemy requires more than superior power or numbers.  Victory often hinges on knowledge of an opponent\'s weaknesses, the anticipation of their plans or the recognition of a behavior pattern.$B$BWe know much about the naga, yet much of their magical practices remain foreign to us.$B$BI seek to learn of the Hydromancy used by the naga of Coilfang Reservoir.  Bring me one of their spellbooks so I may learn more about it.]', '[Obtain a Coilfang Spellbook from the naga inside of Coilfang Reservoir and bring it to Ashyen at the Cenarion Refuge in Zangarmarsh.]', '', '去找贊加沼澤的艾斯炎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9768 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9768,'zhTW','盤牙法術書','','','','去找贊加沼澤的埃西恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9769 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9769,'zhTW','時尚無罪','<瑪加沙莞爾一笑。>$B$B我敢打賭，如果他們知道自己身上的衣物取材於昆蟲的翅膀，這種流行趨勢立馬就會終結。$B$B一開始，我們殺死崗哨附近的螢火蟲僅僅是因為它們妨礙了我們的建築工作。後來，有位商人曾在沼澤鼠崗哨留宿一晚，次日就買走了所有的蟲翼！$B$B據說他利用蟲翼來製作衣服。唔，我還是喜歡自己的盔甲。如果你能收集到一些蟲翼，我很樂意將它們買下來。','獵殺贊加沼澤的螢火蟲，將8片透明的蟲翼交給沼澤鼠崗哨的瑪加沙。','','去贊加沼澤找沼澤鼠崗哨的瑪加沙。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9770 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9770,'zhTW','沼牙的威脅','有時候我真希望德恩加能派一位薩滿祭司來沼澤鼠崗哨，或者至少給我們一根圖騰來牽制沼牙撕裂者吧。$B$B這些害蟲氾濫成災！事情有些不大對頭，難道它們沒有天敵嗎？$B$B我們輪流負責捕殺沼牙撕裂者，真是疲憊不堪。$N，你來得正是時候。祝賀你！現在就出去獵殺這些該死的害蟲吧！','沼澤鼠崗哨的裡維伊要你去殺死10只沼牙撕裂者。','','去贊加沼澤找沼澤鼠崗哨的裡維伊。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9771 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9771,'zhTW','尋找斥候尤爾巴','既然你已經熟悉了地形，我還有件事要請你幫忙。此地西北方有一處神秘的區域，我們稱它為死亡泥潭。去過的人都說泥潭中沒有任何生命的跡象，當然他們在那裡停留的時間並不長。$B$B斥候尤爾巴自願去調查死亡泥潭。三天前他就離開了哨所，到現在也沒有回來。通常他不會離開那麼長的時間而不送回任何報告的。$N，你願意去找他嗎？','在贊加沼澤的死亡泥潭搜尋斥候尤爾巴的下落。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9772 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9772,'zhTW','尤爾巴的報告','枯萎的蘑菇碎粒佈滿斥候尤爾巴的屍體。殺死他的一定是某種渾身長滿菌類的生物，比如說盤踞在死亡泥潭的枯萎的巨人。枯萎的巨人很可能趁尤爾巴坐下來寫報告時偷襲了他。$B$B若是找不到那份報告，我們根本無從得知他究竟發現了什麼秘密。如果你找到了尤爾巴的報告，就把它交給祖萊。','從枯萎的巨人手中奪回斥候尤爾巴的報告，把它交給沼澤鼠崗哨的祖萊。','','去贊加沼澤找沼澤鼠崗哨的祖萊。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9773 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9773,'zhTW','別再提蘑菇了！','蘑菇湯、蘑菇粥、蘑菇丸子、蘑菇醬！$B$B蘑菇、蘑菇、蘑菇！這裡能吃的只有蘑菇。如果你餓了，廚師會扔給你一把斧頭，讓你自己去採些蘑菇回來！$B$B唔，我厭倦了每餐都吃蘑菇。我曾在這附近的湖泊中見過某種鰻魚。雖然它們的長相著實噁心，但總比蘑菇好！$B$B我得吃頓像樣的食物才行，說吧，我出多少錢可以讓你替我弄些魚肉大餐來？','獵殺暗澤鰻魚，將8份電鰻魚片交給沼澤鼠崗哨的瑪加沙。','','去贊加沼澤找沼澤鼠崗哨的瑪加沙。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9774 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9774,'zhTW','厚重多頭蛇鱗片','裡維伊帶來了他的皮甲，真是明智啊。用不了多久，沼澤地潮溼的環境就會讓我這身鎖甲完全報廢。$B$B我一直在設法替換這些快要生鏽的部件。居住在沼澤中的多頭蛇具有厚重的鱗片，能幫助它們抵禦溼氣。$B$B但是，要篩選出合適的鱗片卻頗為費事。那些品質優良的鱗片要麼被撕裂，要麼因為長期的磨損，已經薄得不適合製作護甲了。去較大的湖泊中幫我找些厚重多頭蛇鱗片來吧。','將12塊厚重多頭蛇鱗片交給沼澤鼠崗哨的祖萊。','','去贊加沼澤找沼澤鼠崗哨的祖萊。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9775 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9775,'zhTW','向暗影獵手德恩加報到','暗影獵手德恩加一定盼望著能收到沼澤鼠崗哨建設進度的報告。我已經準備好了一份簡明報告，可惜斥候尤爾巴不幸喪命，我們根本抽不出多餘的人手去送報告。$B$B如果你正要轉至西邊的話，能不能把這份報告捎給薩布拉金的德恩加？$B$B暗影獵手德恩加乍看起來很有威懾力，不過跟他相處久了，你就會發現他其實是個挺不錯的傢伙。','將祖萊的報告交給贊加沼澤中薩布拉金的暗影獵手德恩加。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9776 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9776,'zhTW','奧雷柏爾營地','泰雷多爾的居民大多是從燃燒軍團對德萊尼人的大屠殺中僥倖逃生的流亡者。我希望永遠守護泰雷多爾，讓它成為戰亂中所有盟友的安全港。有一些人迫切地希望與我們結盟，但是又覺得自己還沒有準備好。$B$B$N，我們應該竭盡所能地幫助他們。伊庫提率領一群破碎者隱居在毒蛇湖西北方的古代神殿廢墟中。去那裡找到他們，伸出你的友誼之手。','與贊加沼澤中奧雷柏爾營地的伊庫提談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9777 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9777,'zhTW','燦爛的孢子','$N，贊加沼澤中的可燃材料數量非常稀少，我們必須透過其它途徑來解決泰雷多爾的照明問題。生活在沼澤中的許多動植物都可以散發出柔和的光芒。$B$B捕捉並囚禁那些發光的動物過於殘忍，因此我們選擇了某種特殊的蘑菇做為光源。$B$B雖然我們在泰雷多爾種植了這種燦爛的孢子，但仍然無法滿足照明的需求，因此時常需要外出採摘。這種綠色的小蘑菇通常生長在泰雷多爾附近較大的蘑菇的根部。','將6個燦爛的孢子交給泰雷多爾的魯埃姆。','','去贊加沼澤找泰雷多爾的魯埃姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9778 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9778,'zhTW','監護者哈穆特','在你離開塞納里奧庇護所之前，記得與監護者哈穆特談一談。他負責遠征隊的安全問題。$B$B如果我沒有把一位像你這樣經驗豐富的冒險者引薦給他，他是永遠都不會原諒我的。','向贊加沼澤塞納里奧庇護所的監護者哈穆特報到。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9779 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9779, 'zhTW', '攔截訊息', '再見到你真好，$N。我有個困難你或許可以解決。$B$B我們在太陽之鷹陣線後方的密探回報，看見太陽之鷹士兵傳送一份不尋常的文件。$B$B不幸的是，我們未成功取得一份文件的副本。我要你去那裡嘗試弄到那個文件。我確定如果你施加足夠的壓力，太陽之鷹密探就會供出我們要的資訊。必要時你可以使用武力。', '殺死太陽之鷹的血精靈們直到你取得太陽之鷹書信，然後交給血色守望的復仇者波羅斯。', '', '去找鮮血島的復仇者波羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9780 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9780,'zhTW','電鰻魚片','真高興能在這裡見到新面孔。我和海爾倫初次來到泰雷多爾時，也像陌生人那樣拘謹，不過那似乎是很久以前的事了。$B$B我們歡迎所有路經此地的冒險者，並努力確保泰雷多爾維持著充足的食物供給。雖然我們無法回報好心腸的泰雷多爾學者，但是我們會以他們為榜樣，將溫暖的關懷傳遞到每個角落。$B$B附近的湖泊中生活著一種名叫電鰻的魚類，它們的肉是我們的主要食物來源。如果你願意幫忙的話，就去收集一些電鰻魚片吧。','將8份電鰻魚片交給泰雷多爾的諾蘭妮。','','去贊加沼澤找泰雷多爾的諾蘭妮。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9781 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9781,'zhTW','不堪重負','上次外出狩獵時，我發現一群巨魔正在建造新的崗哨。毫無疑問，他們已經開始捕殺沼澤地的動物了。$B$B如果他們打算長期駐紮下來的話，食物的競爭將變得非常激烈。我們總不能無緣無故地向這些巨魔發動攻擊吧？但是，我們可以設法減輕大自然中跟我們競爭食物的動物所帶來的壓力。$B$B幹掉一隻泥潭多頭蛇，就少了三張貪吃的嘴！多划算啊！','殺死10只泥潭多頭蛇，然後向泰雷多爾的海爾倫覆命。','','去贊加沼澤找泰雷多爾的海爾倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9782 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9782,'zhTW','死亡泥潭','$N，我與泰雷多爾的學者們共同生活了一段時間，對贊加沼澤的生態環境有了深刻的瞭解。最近，我留意到東北方的沼澤地出現了令人不安的變化。$B$B所有的生命似乎都無緣無故地開始枯萎並死亡。我大概猜到發生了什麼事，但也僅僅是我個人的推測而已。如果你能取回一份泥土樣本，我或許能弄清楚真相。','將一份死亡泥潭土壤樣本交給泰雷多爾的守備官伊達爾。','','去贊加沼澤找泰雷多爾的守備官伊達爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9783 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9783,'zhTW','異樣的乾旱','$N，你帶回的泥土樣本幾乎完全失去了水分。如果連土壤都乾涸的話，生活在死亡泥潭的生物一定面臨著巨大的痛苦。$B$B瞧瞧那些枯萎的真菌巨人，難以忍受的苦楚令他們喪失了心智，到處攻擊別的生物。$B$B這些巨人根本不明白髮生了什麼事。我們沒有能力挽救枯萎的巨人，只能選擇結束他們的痛苦。','泰雷多爾的守備官伊達爾要你去殺死12個枯萎的巨人。','','去贊加沼澤找泰雷多爾的守備官伊達爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9784 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9784,'zhTW','鑑定植物','','','','去贊加沼澤找塞納里奧庇護所的勞蘭娜·薩維爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9785 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9785,'zhTW','古樹的祝福','$N，你已經贏得了塞納里奧遠征隊的信任。現在，與我們的盟友——古樹埃西恩和克勒斯談談吧，獲得他們的祝福。$B$B這些古樹所賜的印記可以賦予你強大的力量。隨著你在塞納里奧遠征隊的聲望不斷提升，印記的力量也會相應增強。$B$B$N，去吧，請求古樹賜福與你。','喚風者塔魯·黑蹄要求你與塞納里奧庇護所的埃西恩和克勒斯談一談，獲得古樹的祝福。','','去贊加沼澤找塞納里奧庇護所的喚風者塔魯·黑蹄。','知識印記','戰爭印記','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9786 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9786,'zhTW','博哈姆廢墟','在獸人大肆屠殺我的族人之前，泰雷多爾曾是德萊尼學者和靈魂師的庇護所。一部分德萊尼學者和守備官奉命管理這片區域的數座神殿。$B$B在混戰中，我們與駐守神殿的學者失去了聯絡，尤其是西南方的博哈姆神殿。有報告稱一支失落者氏族已經在那兒安營紮寨。調查博哈姆廢墟，然後向我彙報情況。','泰雷多爾的學者安霍爾要你去偵察博哈姆廢墟。','偵察博哈姆廢墟','去贊加沼澤找泰雷多爾的學者安霍爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9787 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9787,'zhTW','蠻沼雕像','從你在博哈姆廢墟觀測到的情況來看，這支失落者氏族似乎恢復了對野獸之靈的崇拜。想要接近他們，就必須瞭解到更多關於該氏族信仰的資訊。$B$B返回蠻沼村，小心地收集一些雕像，把它們帶回來供我研究。$N，儘量避免惹惱蠻沼失落者，否則很可能破壞我們與他們建立溝通的機會。','將6個蠻沼雕像交給泰雷多爾的學者安霍爾。','','去贊加沼澤找泰雷多爾的學者安霍爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9788 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9788,'zhTW','陰冷之地','我逃出暗澤村後，就躲藏在村子南邊的洞穴中。我根本不知道沼澤生物和孢子人正在爭奪那處洞穴！$B$B在匆忙撤離洞穴時，我不小心落下了一隻裝滿我全部珍寶的箱子。$B$B我好不容易才帶著寶箱逃離暗澤村，沒想到這麼快又失去了它，這簡直是命運對我的嘲弄。如果你願意幫我找回它，我就送你一件好東西。$N，你覺得怎麼樣？','進入暗澤村以南的一處洞穴尋找伊卡因的物品，把它們還給贊加沼澤塞納里奧庇護所的伊卡因。','','去贊加沼澤找塞納里奧庇護所的伊卡因。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9789 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9789,'zhTW','狩獵裂蹄牛','想在狩獵隊中贏得一席之地？那你就得證明自己的實力。$B$B我可不管你以前殺過什麼猛獸；如果你沒捕獲過納格蘭的野獸，就不算合格的獵手。如果你認為自己夠強壯，就從獵殺裂蹄牛開始吧。$B$B它們分佈在狩獵隊營地四周以及偏南的地帶。','殺死12頭裂蹄牛，然後向納格蘭奈辛瓦里狩獵隊營地的赫米特·奈辛瓦里覆命。','','去納格蘭找奈辛瓦里狩獵隊營地的赫米特·奈辛瓦里。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9790 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9790,'zhTW','透明的蟲翼','生活在這窮鄉僻壤，迫使我們學會了就地取材，物盡其用。當然，你最好別去細想某些材料的來源。$B$B我發現暗光釘刺者的翅膀具有防水效果。它們的質地堅韌、輕薄而富有彈性。$B$B<海爾倫輕聲地笑了。>$B$B瞧你臉上的表情。我說過，別去細想這些材料的來源。如果你正要出去走走，能不能幫我帶回一些蟲翼？','獵殺贊加沼澤的螢火蟲，將8片透明的蟲翼交給泰雷多爾的海爾倫。','','去贊加沼澤找泰雷多爾的海爾倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9791 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9791,'zhTW','沼牙的威脅','在獸人與德萊尼人交戰期間，為了避免遭受襲擊或是淪為俘虜，我們很少離開泰雷多爾。現在，我們時常會冒險外出，但是沼澤地依然危機四伏。$B$B最近幾個月，虛空鰩越發肆虐起來。不知道是不是跟激烈的捕食競爭有關，它們頻繁地攻擊我們的糧草徵收隊。如果我們能削減泰雷多爾附近的虛空鰩的數量，或許它們就不會再來滋擾生事了。','殺掉10個沼牙撕裂者，然後向泰雷多爾的諾蘭妮覆命。','','去贊加沼澤找泰雷多爾的諾蘭妮。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9792 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9792,'zhTW','轉至塔拉','$N，庫雷尼氏族不會輕易信任外人，你卻能憑藉不懈的努力贏得我們的尊敬。$B$B此地以南便是納格蘭，我的同胞們就居住在那座古老的德萊尼之城——塔拉。沿著路往南進入納格蘭，然後一直向東南方走，塔拉就在沃舒古東邊的懸崖附近。$B$B凡是幫助過庫雷尼氏族的朋友都會受到塔拉的歡迎，你也一樣。$B$B告訴納霍德，你已經贏得了我的信賴。','轉至納格蘭，與塔拉的納霍德談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9793 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9793,'zhTW','圖雷姆的命運','先知維倫堅持不懈尋求盟友的事蹟鼓舞了外域的德萊尼人，他們開始搜尋自己的同盟。燃燒軍團將我們逐出城鎮和神殿，卻沒能摧毀我們的文明。$B$B泰羅卡森林的圖雷姆曾經是我的家園，也是第一座被獸人侵佔的城鎮。我很久都沒有收到來自圖雷姆的訊息了。轉至泰羅卡森林的奧蕾莉亞要塞，將這封信交給安達爾吧，順便查探那兒的情況。','將守備官伊達爾的信交給泰羅卡森林奧蕾莉亞要塞的安達爾。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9794 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9794, 'zhTW', '沒時間好奇了', '$N，我有件事想請你幫忙。通常我會自己做這件事，但我現在真的太忙了。$B$B我有個叫齊亞隆的朋友在北邊劍刃山脈的希爾瓦納。他在等我的消息，雖然我想他聽到後不會太高興。$B$B如果你可以幫我傳話給他，我會很感謝你。另外我一定要堅持，這很重要，那就是你不能偷讀這封信。這只能讓齊亞隆知道。', '把提莫斯的信帶給位在劍刃山脈希爾瓦納的齊亞隆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9795 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9795, 'zhTW', '巨魔威脅', '好像納迦和他們的盟友還不夠多似的，巨魔將他們的觸角延伸到了沼澤區。他們已征服了西北邊大部分區域，那裡已經沒有什麼緩衝之地了。我們每殺一個人，就會有好幾個人代替他的位子。我不確定如果他們決定發動攻擊，我們還能保住薩布拉金多久。前往北方進入山裡，到的獸人雷霆王村堡壘讓奈克薩爾知道我們的困境。我們歡迎他可提供的任何幫助。', '前往劍刃山脈的雷霆王村和奈克薩爾談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9796 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9796,'zhTW','贊加沼澤的來客','除了暗影獵手德恩加之外，泰羅卡森林裂石堡的莫薩卡也在等待我發回報告。裂石堡的信使頻繁路經沼澤地，因此她迫切地想要了解崗哨建設的進展。$B$B她說一旦沼澤鼠崗哨建成，就立即告訴她。如果你願意去裂石堡跑一趟的話，我會非常感謝你的。崗哨很快就能投入正常使用了，但是還有很多事情等著我們去做。$B$B沿著南邊的道路穿越贊加沼澤，進入泰羅卡森林，抵達圖雷姆後繼續往南走便是裂石堡。','轉至泰羅卡森林的裂石堡，與莫薩卡談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9797 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9797,'zhTW','支援加拉達爾','<信使喘著氣，示意你坐下。>$B$B$r，他們可能難逃此劫！以你最快的速度趕往加拉達爾吧。$B$B<見你一臉茫然，信使詳細地解釋起來。>$B$B瑪格漢氏族的家園就在納格蘭。沿著南邊的道路穿越贊加沼澤，在第一個交叉口往東轉，瑪格漢氏族的駐地就座落在湖畔附近。$B$B向我們的指揮官克洛坎上尉伸出援手。加拉達爾絕不能失守！','轉至納格蘭的加拉達爾，與克洛坎上尉談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9798 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9798, 'zhTW', '血精靈計畫書', '這些計畫書看起來很重要。你應該帶著它們去找失事地點的復仇者艾德。', '帶著血精靈計畫書到安曼谷的失事地點找復仇者艾德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9799 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9799,'zhTW','植物學家的跑腿任務','西邊的安曼牧場是當地主要的鞭笞者繁殖地。因為附近湖泊的地下水污染，植物學家泰瑞茲擔心一旦我們淨化湖泊，鞭笞者將無法再自己重新繁殖。$B$B前往安曼牧場摘一些受污染的花給我，或許我可以看看它們並想個辦法。你可以不尋常的紅色花瓣來辨別它們。','收集3朵被污染的花朵再回到安曼谷的失事地點找學徒米虛歐。','','去埃門谷找墜毀點的學徒維莎爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9800 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9800,'zhTW','稀有的豆子','憑你這身差勁的裝備，怎麼能與納格蘭躁動不安的元素抗衡呢？還是先提升下自己的裝備再想想如何幫助大地之環吧，比如……潛水用品。$B$B在元素王座西邊的草原上，隨處可見納格蘭的野生動物留下的糞堆。你拔開糞堆之後就可以找到一些卡拉果。這種果實製成的小藥片能幫助你潛水，對抗那些元素生物。$B$B收集兩隻拳頭那麼大的一堆卡拉果……我是說按食人魔的拳頭尺寸來算。','將8顆挖出來的卡拉果交給納格蘭元素王座的元素師魯艾普。','','去納格蘭找元素王座的元素師魯艾普。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9801 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9801,'zhTW','收集材料','我覺得失落者也許不會友善地對待德萊尼人，但是他們肯定會對鴉人示好。我可以配製一\\r\\n種特殊的藥水，讓你在短時間內偽裝成鴉人。這種藥水需要兩種材料，但是它們無法長期儲藏，必須在採集後的數小時內使用，否則就會失效。$B$B替我收集一些孢子蝠的眼睛和沼澤闊步者的觸鬚。孢子蝠和沼澤闊步者分佈在泰雷多爾四周。','將4只孢子蝠的眼睛和4根沼澤闊步者的觸鬚交給泰雷多爾的學者安霍爾。','','去贊加沼澤找泰雷多爾的學者安霍爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9802 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9802,'zhTW','贊加沼澤的植物','贊加沼澤的湖泊日益乾涸，我們尚未查明具體原因，但是許多植物正面臨滅絕的危險。$B$B做為遠征隊的編目者，我的任務是記錄和鑑定植株，幫助我們更好地瞭解它們的特性。$B$B如果你願意幫忙，就替我採集一些未鑑定過的植物。如果你恰好是草藥師的話，可以直接從地面上採集到這種植物，當然你也可以在沼澤生物身上找到它們。','將10株未鑑定過的植物交給贊加沼澤塞納里奧庇護所的勞蘭娜·薩維爾。','','去贊加沼澤找塞納里奧庇護所的勞蘭娜·薩維爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9803 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9803,'zhTW','蠻沼的信使','是時候向蠻沼失落者表明我們的誠意了，讓他們明白聖光並沒有拋棄他們。帶上我為你準備的藥水，轉至博哈姆廢墟。$B$B到達廢墟後立即喝下藥水，偽裝成蠻沼失落者崇拜的猛禽之魂的模樣。與長者庫魯提談一談，告訴他德萊尼人將蠻沼失落者視為失散多年的同胞，我們期待著與他們的重聚。','到達博哈姆廢墟後飲下安霍爾的藥劑，偽裝成鴉人，然後與長者庫魯提談一談。','','去贊加沼澤找泰雷多爾的學者安霍爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9804 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9804,'zhTW','天歌湖的元素','納格蘭水域中那異常的潮汐漲落令天歌湖的湖水之魂躁動不安。它們沿著水道，企圖將騷亂的種子傳播到其它地方。$B$B流水之賢者瓦圖蘇以幻像的形式出現在我們面前，請求大地之環伸出援手，找出這場騷亂的根源，令躁動的元素恢復平靜。$B$B我們一定要揪出破壞自然平衡的幕後真兇，不過首先你必須解決元素王座眼前的難題。殺死湖水之魂，然後向我覆命。','消滅8個湖水之魂，然後向納格蘭元素王座的元素師魯艾普覆命。','','去納格蘭找元素王座的元素師魯艾普。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9805 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9805,'zhTW','伊森拉圖斯的祝福','卑鄙的失落者！那群傢伙被放逐到贊加沼澤後，仍然蠢蠢欲動，企圖將汙穢的種子傳播到世界的其它角落。$B$B我已向元素尋求解決之道，並與他們達成了共識：要根治這場騷亂，就得讓失落者嚐嚐元素的厲害！$B$B這蔟活火取自伊森拉圖斯的火焰精華。轉至東南方的風茅村，用活火焚燬失落者的小屋！讓他們看看那熊熊燃燒的怒火！','納格蘭元素王座的元素師魯艾普要你焚燬風茅村的大棚屋、西部棚屋、南部棚屋和東部棚屋。$B$B完成任務後將活火還給元素師魯艾普。','','去納格蘭找元素王座的元素師魯艾普。','燒燬大棚屋','燒燬西部棚屋','燒燬南部棚屋','燒燬東部棚屋',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9806 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9806,'zhTW','成熟的孢子','孢子蝠和泥沼遊蕩者通常聚集在沼澤地的長杆蘑菇附近，它們的附肢上堆積著許多成熟的孢子。$B$B瞧，我們身材矮小，能夠採集到的孢子非常有限。你能幫我們從孢子蝠和泥沼遊蕩者身上收整合熟的孢子嗎？所有的孢子人都會感謝你的。','從贊加沼澤的孢子蝠和泥沼遊蕩者身上收集6個成熟的孢子，把它們交給孢子村的格沙弗。','','去贊加沼澤找孢子村的格沙弗。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9807 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9807,'zhTW','更多成熟的孢子','','','','去贊加沼澤找孢子村的格沙弗。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9808 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9808,'zhTW','亮頂蘑菇','我看見你們使用亮閃閃的金屬圓片來交換各自需要的東西。其實我們跟你們差不多吧，不過我們用的是亮閃閃的圓蘑菇。$B$B沼澤地裡遍佈著亮頂蘑菇，你只需要懂得如何採集這些蘑菇而不至於將它們弄壞就行了。如果你願意幫助我們採集一些亮頂蘑菇，我就告訴你該怎麼做。$N，你覺得怎麼樣？','將10枚亮頂蘑菇交給贊加沼澤孢子村中的姆希菲。','','去贊加沼澤找孢子村的姆希菲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9809 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9809,'zhTW','更多亮頂蘑菇','','','','去贊加沼澤找孢子村的姆希菲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9810 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9810,'zhTW','汙染的靈魂','瓦圖蘇設法抵禦了這場災難的侵襲，可惜這位賢者卻不慎在淨化過程中製造出了一塊扭曲的靈魂精華。這塊靈魂精華彙集了最可怕的元素汙染質！$B$B轉至西南方的沼澤地，瓦圖蘇的汙染精華就藏匿在日泉湖的深處。$B$B殺死瓦圖蘇的汙染精華以及日泉湖中被汙染的水元素生物。','殺死瓦圖蘇的汙染精華和8個湖水湧動者，然後向納格蘭元素王座的元素師魯艾普覆命。','','去納格蘭找元素王座的元素師魯艾普。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9811 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9811, 'zhTW', '辛多雷的朋友', '這是我們血精靈歷史中嶄新的一章，$N。你的幫助加強了我們雙方種族的關係，$r。$B$B把背叛者的頭顱帶給銀月城的地區統治者，洛索瑪·塞隆。他等不及想聽到這個消息。', '把達克汗的頭顱交給銀月城的洛索瑪·塞隆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9812 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9812, 'zhTW', '部落的使者', '我們潛在的新盟友對我們的能力有些懷疑。被認為連自己家的問題都無法解決那我們對他們而言還有什麼用?$B$B這會改變一切。我們的能力不再會被質疑。我們會以同等的姿態加入部落。$B$B把這封信交給希瓦娜斯，被遺忘者的統治者。她已經和我們站在同一陣線了，但達克汗的死訊對她而言沒有影響力。準備好長途跋涉吧，$N。如果一切進行順利她會送你到奧格瑪的。', '將來自洛索瑪·塞隆的信帶到幽暗城，提里斯法林地的被遺忘者首都給希瓦娜斯·風行者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9813 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9813,'zhTW','覲見酋長','你知道的，我還沒有喪失對往昔的故鄉與人民的愛。我曾為了銀月城能在幽暗城與奧格瑪的談判桌上有一席之地而與獸人針鋒相對。$B$B你帶來的訊息可以讓任何反對者閉上嘴。立刻將這封信送給奧格瑪的索爾酋長。身為部落的領袖，他會最終接受辛多雷的效忠宣誓。$B$B我已經在信上蓋了自己的印章，表明了我個人的認可。到城市的西北方去，你就可以找到地精飛艇的空港，搭乘飛艇可以很快到達杜隆塔爾。','希爾瓦娜斯·風行者要求你將她的密信交給杜隆塔爾首都奧格瑪的索爾。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9814 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9814,'zhTW','爆頂蘑菇','朋友，你喜歡蘑菇嗎？贊加沼澤薩布拉金附近生長著一種威力強大的蘑菇。$B$B不過你要當心，它們被稱為爆頂蘑菇是有原因的。如果你沒有做好防護措施就貿然靠近的話，它會突然爆炸！砰！形成一團有毒的孢子云。$B$B我利用這種蘑菇預測吉凶，可是已經快用完了。','將6枚爆頂蘑菇交給巫醫托爾加什。','','去贊加沼澤找薩布拉金的巫醫托爾加什。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9815 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9815,'zhTW','潛水','在納格蘭被汙染的各處水域之中，以西南方哈蘭盆地的情況最為嚴重。那裡有許多躁動難安的水元素在廢棄的哈蘭城下徘徊。一般來說，某些元素生物的殘骸不會對環境造成任何影響，泥濘爪牙則不然，必須將它們的殘骸全部銷燬。$B$B泥濘爪牙死後，會留下沾滿淤泥的核心。如果不加處理的話，就會繼續擴散開來，對環境造成負面影響。$B$B殺掉泥濘爪牙，將沾滿淤泥的核心帶回來給我。','將5個沾滿淤泥的核心交給納格蘭元素王座的元素師魯艾普。','','去納格蘭找元素王座的元素師魯艾普。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9816 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9816,'zhTW','你見過魚人嗎？','朋友，你不覺得贊加沼澤少了點什麼嗎！這裡居然沒有魚人。$B$B別擔心，我來解決這個問題。看見加爾戈和古爾戈了嗎？我準備將魚人作為禮物送給失落者！$B$B帶上這隻籠子轉至匕潭村，在村子東北角把它們放出來。當然，我可不能讓加爾戈和古爾戈跟著你去那種危險的地方，但是我會給你一籠子各色各樣的小魚人。將魚人籠放在那塊平坦的岩石上，然後開啟籠門！','將魚人籠放在匕潭村附近的平坦的岩石上。','','去贊加沼澤找薩布拉金的巫醫托爾加什。','在匕潭村放生小魚人','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9817 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9817,'zhTW','血鱗納迦的領袖','塞納里奧遠征隊懸賞擊殺血鱗納迦的首領弗亞希王女的勇士。這名納迦女巫最後一次被發現是在贊加沼澤北部的毒蛇湖。$B$B血鱗納迦極度危險，想要挑戰他們的首領的勇士必須非常小心謹慎。$B$B成功擊殺弗亞希王女之後，請向塞納里奧庇護所的監護者哈穆特領取獎賞。','殺死毒蛇湖的弗亞希王女，然後返回贊加沼澤的塞納里奧庇護所，向監護者哈穆特領取獎賞。','','去贊加沼澤找塞納里奧庇護所的監護者哈穆特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9818 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9818,'zhTW','地下的滋擾','最近，不知是什麼東西在地底哀嚎。它總是在敲擊著地面，彷彿在宣洩怒火。$B$B*砰*$B$B<溫塔格掄起拳頭拍了拍他的胸脯。>$B$B它不停地製造這種聲音，劇烈的震擊令大地也搖晃起來。這分明是衝我們來的。$B$B戈達烏應該知道究竟是什麼生物在地底滋擾生事，攪得元素不得安寧。$B$B跟戈達烏談談吧。不，要聽戈達烏說，你別出聲。千萬要仔細聽戈達烏說……','與戈達烏溝通。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9819 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9819,'zhTW','被折磨的地靈','將侵佔者揪出來。你會找到他的，只要你遵循我的指示。首先消滅那些被折磨的地靈。必須讓它們再次沉睡。$B$B<戈達烏揮拳擊中大地，碎裂的土壤傳來腐臭的氣味。>$B$B必須讓它們沉睡！$B$B<戈達烏指向東南方。>$B$B地靈就分佈在那片山嶺中。$B$B讓它們睡去吧。$B$B東南方的……塔拉盆地。','納格蘭元素王座的戈達烏要你消滅10個被折磨的地靈。','','去納格蘭找元素王座的戈達烏。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9820 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9820,'zhTW','通緝：格羅阿克','死亡通緝令：格羅阿克，安葛洛什食人魔砍伐蘑菇行動的監工。$B$B這個蠻橫的渣滓和他的斧頭幫走狗砍光了薩布拉金以北的蘑菇林。我們必須阻止格羅阿克，否則他和他的手下就會開闢出一條直達薩布拉金城牆的通道。$B$B擊殺格羅阿克的勇士請將他的徽記交給暗影獵手德恩加，領取重賞。','將格羅阿克的徽記交給薩布拉金的暗影獵手德恩加。','','去贊加沼澤找薩布拉金的暗影獵手德恩加。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9821 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9821,'zhTW','吞食詛咒','<戈達烏撿起一塊岩石咀嚼起來。>$B$B戈達烏要辨別味道。戈達烏知道這塊岩石來自何處。$B$B<戈達烏抬起腳，重重地踏向大地。>$B$B瞧。納格蘭。$B$B<戈達烏讓你觀察他的腳印。地面竟然凹顯出一幅完美的納格蘭地形圖，戈達烏要你轉至地圖上被標記的地方消滅被激怒的碾壓者。>$B$B殺掉它們！把岩石碎片帶給戈達烏！$B$B帶上地圖。','將10塊被激怒的碾壓者的核心交給納格蘭元素王座的戈達烏。','','去納格蘭找元素王座的戈達烏。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9822 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9822,'zhTW','戰鬥迫近','食人魔選擇在薩布拉金附近砍伐蘑菇絕非偶然。我猜測他們準備攻擊薩布拉金。$B$B$N，我必須搞清楚這件事。食人魔在西北方設立了另一處哨站——安葛洛什營地。如果他們在密謀襲擊計劃，一定會留下證據的。$N，轉至安葛洛什營地搜尋食人魔進攻計劃的線索。將任何可疑的東西都帶回來給我。','將安葛洛什攻擊計劃交給交給薩布拉金的暗影獵手德恩加。','','去贊加沼澤找薩布拉金的暗影獵手德恩加。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9823 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9823,'zhTW','你死我活','要解除安葛洛什食人魔的威脅，就必須殺死他們的首領戈爾費斯大王。不過，我們還可以做得更有威懾力一些。$B$B轉至安葛洛什要塞，與我們的敵人戰鬥吧。要塞就在薩布拉金西北方某座小島的洞穴中。跨越沼澤地邊緣那株倒下的蘑菇形成的橋樑，就能看見要塞了。$B$B$N，不要心軟。這幫傢伙絕不會放過我們。','殺死戈爾費斯大王、10個安葛洛什毆鬥者和10個安葛洛什食魂者，完成任務後向薩布拉金的暗影獵手德恩加覆命。','','去贊加沼澤找薩布拉金的暗影獵手德恩加。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9824 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9824,'zhTW','奧術擾動','一直以來，我都想要獲得一份卡拉贊內能量譜系的拓印……當然，僅僅是出於私人研究之用。可惜我至今仍一無所獲。若我能再靠近一些這裡的地下水源，這塊水晶所能接收的能量訊號就會更清晰一些了。$B$B我聽說麥迪文的酒窖中有一處地下水井和一處地下水池，那些地方應該就是最合適的取樣地點。但是，酒窖裡到處都是鬼魂，對我這樣的老頭子來說太危險了。$N，你願意幫我這位老人探測卡拉讚的能量譜系嗎？','在麥迪文的酒窖內的地下水源附近使用紫羅蘭占卜水晶，然後向卡拉贊外的大法師奧圖魯斯覆命。','','去找逆風小徑的大法師奧圖魯斯。','收集地下水井的訊號','收集地下水池的訊號','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9825 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9825,'zhTW','幽靈的活動','你也注意到那些徘徊在卡拉贊外的幽靈與鬼魂了吧。它們出現在此地的原因當前完全不明，這令我非常困擾！$B$B去幫我從它們身上收集一些幽靈精華來，或許我可以研究出它們的來意。$N，卡拉贊中隱藏著許多秘密，而我，決心揭開這些秘密之後的真相。','將10個幽靈精華交給卡拉贊外的大法師奧圖魯斯。','','去找逆風小徑的大法師奧圖魯斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9826 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9826,'zhTW','聯絡達拉然','$N，探測結果並不樂觀。我向來不是個守口如瓶的人，那麼就讓我告訴你一些關於我所屬的組織——紫羅蘭之眼的內幕吧。$B$B我們是達拉然肯瑞託法師議會直屬的密探，負責監視麥迪文和卡拉贊之塔的狀況，避免這裡局勢失控。$B$B在麥迪文失蹤後，我們對這裡展開了一次非常迅速的“調查行動”，然後這裡就沉寂了下來。$B$B那麼，這是一份詳細的調查報告，將它交給達拉然巨坑外的大法師塞德瑞克，他也是紫羅蘭之眼的成員。','將奧圖魯斯的報告交給達拉然巨坑外的大法師塞德瑞克。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9827 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9827,'zhTW','枯萎的孢芽','仔細地檢查孢芽之後，你發現許多可能曾被用來容納某種東西的凹痕。這枚怪異的蘑菇是一個謎團，它完全不健康，但是你找不到任何線索來了解它可能曾經派作什麼用場。$B$B也許熟悉贊加沼澤生態的人應該可以告訴你更多有關這種孢芽的情況。','將枯萎的孢芽交給贊加沼澤中泰雷多爾的魯埃姆。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9828 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9828,'zhTW','枯萎的孢芽','仔細地檢查孢芽之後，你發現許多可能曾被用來容納某種東西的凹痕。這枚怪異的蘑菇是一個謎團，它完全不健康，但是你找不到任何線索來了解它可能曾經派作什麼用場。$B$B也許熟悉贊加沼澤生態的人應該可以告訴你更多有關這種孢芽的情況。','將枯萎的孢芽交給贊加沼澤中沼澤鼠崗哨的裡維伊。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9829 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9829,'zhTW','卡德加','奧圖魯斯的報告書令我非常不安。自卡拉贊之塔封印了自身，截斷了與外界的一切聯絡時，我們就感覺到了情況的惡化。我們曾派出過一些探子進入塔中，但是卡拉贊封閉之後就沒有人再回來。現在……這裡竟然散發出這麼濃重的惡魔氣息。我們必須徹底調查這裡。$B$B這世界上只有兩個可以重新開啟卡拉贊封印的人——星界法師麥迪文和他的學徒卡德加，曾被認為都已經死了。$B$B我們當然希望前者確實死掉了，但後者，他的學徒卡德加，有訊息說當前還活著，在一處名叫撒塔斯城的地方。立刻找到他，並將奧圖魯斯的報告書交給他。','將奧圖魯斯的報告交給泰羅卡森林中撒塔斯城的卡德加。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9830 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9830,'zhTW','沼澤中的毒液','在和德萊尼人交談時，我總覺得他們的語氣中透露出被逐出家園的怨氣。他們似乎非常同情破碎者，認為我們失去了某種東西。$B$B雖然聖光不再眷顧破碎者氏族，但是豐富的閱歷使我們對自然界的瞭解更加深入。$B$B我的族人能洞悉到許多潛在的機會，卻很少有德萊尼人能如此獨具慧眼。舉個例子吧，此地的南面和西面是沼光抽血者的聚集地，這種生物分泌的毒液具有廣泛的用途，無論是狩獵還是療傷都用得著。','將6份沼光抽血者的毒液交給奧雷柏爾營地的普爾魯。','','去贊加沼澤找奧雷柏爾營地的普爾魯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9831 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9831,'zhTW','卡拉讚的鑰匙','這份報告書裡提到的情況讓我十分擔憂，$N，看來的確需要進入卡拉贊調查，但你也要知道，進入卡拉贊是十分困難的。$B$B當初，我本人在外域幾乎走投無路，處境十分艱難，於是我就將卡拉讚的鑰匙分成三個部分藏了起來。$B$B當時，我將它們分別放進了三個魔法容器中，分別藏匿在三個我認為十分安全的地方。$B$B可是，時過境遷……隨著黑暗勢力逐漸籠罩了外域，這些地方也不再有安全可言。第一部分碎片在奧金頓中，那個區域當前被暗影議會佔據著。將這塊碎片帶回來給我吧。','卡德加要求你進入奧金頓的暗影迷宮中，回收儲藏在那裡的一個奧術容器中的第一塊鑰匙碎片。','','去找撒塔斯城的卡德加。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9832 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9832,'zhTW','第二塊和第三塊','第二部分的鑰匙，被我藏在了毒蛇湖的湖底，當時那裡還不叫這個名字。納迦們佔據了毒蛇湖之後，在湖中央安裝了巨大的抽水裝置。恐怕容器也被吸進了盤牙水庫的深處。$B$B第三部分則更加難以回收，我原本將其留在了風暴要塞，當時那裡在納魯的掌控之下。可現在凱爾薩斯佔領了要塞，而我原來存放容器的地方也變成了一處監獄。$B$B把這些鑰匙的碎片給我帶回來吧，$N。一切都要依靠你了。','從盤牙水庫內的一個奧術容器中拿到第二塊鑰匙碎片，從風暴要塞內的一個奧術容器中拿到第三塊鑰匙碎片。任務完成之後向撒塔斯城的卡德加覆命。','','去找撒塔斯城的卡德加。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9833 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9833,'zhTW','通訊路線','我們跟隨伊庫提來到贊加沼澤，此行的目的之一就是開闢一條安全通道，幫助德萊尼人與居住在納格蘭塔拉的庫雷尼人建立通訊。為了讓信使在塔拉和泰雷多爾之間通行無阻，我們必須確保道路的安全。$B$B在來時的路上，我們多次遭到沼牙切割者的襲擊。儘管我們將它們全部擊退，但是對孤單的信使而言，這些野獸必定會帶來巨大的威脅。削弱它們的數量才能確保信使的安全。','奧雷柏爾營地的普爾魯要你殺死12個沼牙切割者。','','去贊加沼澤找奧雷柏爾營地的普爾魯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9834 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9834,'zhTW','天然的護甲','即使在陰暗的沼澤地，瑪克圖也能在一里開外看見那些穿著閃亮盔甲的德萊尼人！$B$B瑪克圖想要嘲笑他們，但是他又想到德萊尼人對待庫雷尼人的態度是多麼友善，因此瑪克圖想教教他們製作護甲的方法。$B$B瑪克圖曾經用泥爪毀壞者的黑鱗皮製作過最好的護甲。如果$N願意去毒蛇湖深處獵殺泥爪毀壞者，把泥爪皮交給瑪克圖，他一定會樂意送給$N幾件護甲的。','將8張泥爪皮交給奧雷柏爾營地的瑪克圖。','','去贊加沼澤找奧雷柏爾營地的瑪克圖。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9835 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9835,'zhTW','安葛洛什的威脅','我帶領這支破碎者小隊，奉命從納格蘭的塔拉趕來奧雷柏爾營地執行任務。我們稱自己為庫雷尼人，是渴望與德萊尼同胞重聚的破碎者。$B$B我們來此的目的就是加強庫雷尼人與泰雷多爾的德萊尼人之間的溝通。$B$B如果任由安葛洛什食人魔為所欲為，這座營地很快就會失守。他們已經砍光了菌杆沼澤中高大的蘑菇，離我們的避難所越來越近。如果你是我們的朋友，就幫我們擊退敵人吧。','殺死10個安葛洛什食人魔和5個安葛洛什薩滿祭司，然後返回奧雷柏爾營地向伊庫提覆命。','','去贊加沼澤找奧雷柏爾營地的伊庫提。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9836 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9836,'zhTW','麥迪文的觸控','所有碎片已經組合完畢，這就是我當學徒時使用過的那把鑰匙了。看上去倒是跟以前沒什麼兩樣，但是如果你想用它來開啟卡拉讚的大門，這東西不過是一塊廢金屬罷了。$B$B除非獲得麥迪文的同意，否則這把鑰匙就毫無價值。唔，我當然知道麥迪文已經死了。這事兒不是不可能，只是有些難辦而已。$B$B在艾澤拉斯世界，有一處名叫時光之穴的地方，青銅龍守護著那塊聖地。設法進入時光之穴，返回過去，說服麥迪文讓這把鑰匙重新獲得開啟卡拉贊大門的能力吧。','進入時光之穴，說服麥迪文讓復原的學徒鑰匙重新獲得開啟卡拉贊大門的能力。','麥迪文的觸控','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9837 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9837,'zhTW','返回卡德加身邊','哦，我腦海中似乎一直擁有許多關於未來的記憶，特別是關於你和你手裡這枚鑰匙。$B$B<麥迪文默默地注視著你，彷彿注視著某個幽靈或是鬼魅。>$B$B$N，未來的旅途將更加充滿艱辛，我由衷希望你能應對那一切。$B$B至於這把鑰匙，我以後會在卡德加來到卡拉贊時交給他。以學徒而言，我想他是最好的了。$B$B你也需要一把鑰匙。$B$B<麥迪文從口袋中掏出他自己的鑰匙，把它遞給了你。>$B$B拿去吧。$c，祝你好運。','將麥迪文的鑰匙交給撒塔斯城的卡德加。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9838 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9838,'zhTW','紫羅蘭之眼','$N，命運已經將重要的使命賦予了你。如果紫羅蘭之眼的調查結果確實可信，那麼你就必須向他們伸出援手。$B$B儘管我與大法師塞德瑞克有許多不睦，可是像奧圖魯斯這樣的人，他們所從事的研究工作還是至關重要的。總之，幫助他們的同時，你也要提防被紫羅蘭之眼所利用。話說回來，如果卡拉贊真是面臨危機，甚至成為了危機本身，恐怕也只有紫羅蘭之眼能為你指引方向，幫助你消滅其中的邪惡力量。回到奧圖魯斯那兒吧，竭盡全力幫助他。','與卡拉贊外的大法師奧圖魯斯談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9839 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9839,'zhTW','戈爾費斯大王','食人魔首領是整個氏族的核心。一旦失去首領，安葛洛什部族就會瓦解，他們會自相殘殺，爭奪新一任首領的頭銜。$B$B儘管食人魔曾在這片區域出沒，但是他們的主要勢力聚集在西北邊的安葛洛什要塞。沼澤地邊緣有一株倒下的蘑菇，要塞就位於那座蘑菇橋對面小島上的洞穴中。$B$B去那裡殺死戈爾費斯大王，緩解奧雷柏爾營地的危機。','殺死戈爾費斯大王和10個安葛洛什毆鬥者，完成任務後向奧雷柏爾營地的伊庫提覆命。','','去贊加沼澤找奧雷柏爾營地的伊庫提。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9840 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9840,'zhTW','評估事態','既然進入麥迪文之塔的鑰匙已經掌握在了我們手中，好吧，確切的說是掌握在你手中，那麼我們的首要任務就是對塔中的情況進行一次初步判斷。$B$B很久以前，紫羅蘭之眼的一位密探金娜曾成功潛入卡拉贊，並將探察到的所有資訊用密文寫入了日記。不幸的是，卡拉贊關閉之後，我們很快就得到了她的死訊。但是，卡拉讚的鐵匠庫雷恩也曾受僱紫羅蘭之眼。雖然他不是組織的成員，不過他應該能幫我們找到金娜的日記。進入卡拉贊跟他談談。','進入卡拉贊尋找庫雷恩。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9841 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9841,'zhTW','清除沼光抽血者','這吵死人的嗡嗡聲簡直讓人沒法幹活！你聽見了嗎？$B$B我滿腦子都是這聲音！我知道誰在製造噪音——那些該死的沼光抽血者！噪音總是從村子的南邊和西邊傳來。$B$B沼光抽血者體型龐大，不能象對付小蟲子那樣拍死、踩死或是趕走它們。消除噪音的唯一辦法就是殺死它們。$N，我可不管你準備用什麼方法，總之讓它們安靜下來！','殺死8個沼光抽血者，然後向薩布拉金的加巴林卡覆命。','','去找贊加沼澤的加巴林卡。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9842 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9842,'zhTW','最鋒利的刀刃','沼澤地潮溼的環境使我的金屬工具嚴重受損。這讓原本簡單的木工活變得困難許多，所以我放棄了使用金屬刀刃。$B$B薩布拉金的南邊和西邊生活著一種名叫沼牙切割者的沼澤生物，它們鋒利的附肢是我所使用過的最好的刀刃，同時還具有防鏽和抗磨損的功能。當然，要靈活運用這種利器需要一點點技巧，不過這對我來說已經不成問題了。如果你能幫我取回一些沼牙切割者之刃的話，我會非常感激你的。','將10柄沼牙切割者之刃交給薩布拉金的加巴林卡。','','去找贊加沼澤的加巴林卡。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9843 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9843,'zhTW','金娜的日記','再說一次，你要找誰來著？金娜？$B$B哦哦，我以前也曾在卡拉贊見過一個名字也叫金娜的女人，她那時一直呆在會客間那邊。我本應保守這個秘密的。$B$B你說你替紫羅蘭之眼辦事？不，我從來沒聽過這個組織。$B$B如果你不介意的話，我回去幹活了。$B$B<庫雷恩一瞬間就似乎已經完全忘記了你。>','在卡拉讚的會客間搜尋金娜的日記，然後將它交給卡拉贊外的大法師奧圖魯斯。','','去找逆風小徑的大法師奧圖魯斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9844 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9844,'zhTW','惡魔的氣息','金娜的最後幾篇日記證實了我們的懷疑，卡拉贊中確實有惡魔出沒。$B$B她曾在卡拉贊中發現燃燒軍團的一名密探出沒，位置，我看看……按描述應該是從塔頂潛入的。$B$B寫到這裡，日記就中斷了。$B$B$c，卡拉贊是一處至關重要的所在，它是連線扭曲虛空與這個世界的傳送門，是照耀著異界天空的燈塔。一旦卡拉贊落入邪惡勢力之手，後果將不堪設想。我們必須阻止這些惡魔的入侵，$N，你是唯一有鑰匙的人，這重大的使命就交給你了。','大法師奧圖魯斯要求你消滅出現在卡拉贊頂部的惡魔。','','去找逆風小徑的大法師奧圖魯斯。','摧毀惡魔','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9845 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9845,'zhTW','下鉤釣魚','長途跋涉穿越荒涼的地獄火半島後，待在有水的地方真是舒坦，我原本還擔心外域很可能沒有適合垂釣的地方呢。$B$B現在，我真高興隨行帶了漁具過來。大多數時候，釣魚是一件非常愉快的事情，如果沒有毒蛇湖裡那些討厭的泥爪毀壞者的話。$B$B它們不僅把魚嚇跑了，還膽敢咬掉我魚鉤上的誘餌。我不得不花更多的時間一次次地重灌誘餌，根本沒法釣到任何東西！','殺死10個泥爪毀壞者，然後向薩布拉金的蘇爾加亞覆命。','','去贊加沼澤找薩布拉金的蘇爾加亞。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9846 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9846,'zhTW','蠻沼之靈','據說沼澤地中最強大的失落者氏族——蠻沼氏族擁有某種神奇的藥膏。雖然這個流言有可能是假的，但一切可能幫我引導這個世界靈魂的東西都不容忽視。$B$B$N，從蠻沼秘法師、蠻沼獵人和蠻沼德魯伊手中奪得保護圖騰。圖騰上的雕文應該記載著我想要知道的東西。','將10根蠻沼保護圖騰交給薩布拉金的先知亞尼迪。','','去贊加沼澤找薩布拉金的先知亞尼迪。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9847 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9847,'zhTW','靈魂之盟？','我們必須查明蠻沼毒蛇之魂到底蘊藏著多大的力量，以及它是否願意服從我們的意志。如果我能隨意支配來自外域的靈魂的力量……難以想象！$B$B帶上圖騰轉至博哈姆廢墟，將它插在臺階底部的地面上。只有這樣，我們才能透過毒蛇之魂瞭解到究竟是誰使用過保護圖騰。','轉至博哈姆廢墟，將蠻沼圖騰插在臺階底部的地面上。然後返回薩布拉金，向先知亞尼迪彙報你的發現。','','去贊加沼澤找薩布拉金的先知亞尼迪。','召喚毒蛇之魂','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9848 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9848,'zhTW','匕潭的秘密','蟲子、蟲子、蟲子！贊加沼澤到處都是蟲子，營地的同伴們似乎為此深感困擾。$B$B呸，我真是受夠這些蟲子了！不過有件更有趣的事情吸引了我的注意。營地以西是一座失落者村落，他們自稱為匕潭失落者。$B$B整個部族由訓練有素的暗殺者組成。我留意到他們所配製並使用的某種強效毒藥，我迫切地想要了解這種毒藥，但是我需要一份配方和一小瓶樣本。','將匕潭毒藥手冊和一隻匕潭毒藥瓶交給奧雷柏爾營地的迪莫斯·丹尼斯。','','去贊加沼澤找奧雷柏爾營地的迪莫斯·丹尼斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9849 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9849,'zhTW','打碎外殼','<戈達烏從後背掰下一塊岩石。>$B$B我把這塊代表大地之怒的碎片交給你。將戈達烏的石塊砸向破碎奔行者。擊碎他們的外殼，看看這幫傢伙的真面目。殺死侵佔者的爪牙，然後返回元素王座，將侵佔者的名字告訴戈達烏。$B$B破碎奔行者分佈在納格蘭西南方的邊緣地帶。','納格蘭元素王座的戈達烏要你殺死30個戈隆克的爪牙。','','去納格蘭找元素王座的戈達烏。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9850 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9850,'zhTW','狩獵裂蹄牛','看來獵殺裂蹄牛對你來說已經不在話下，不過裂蹄公牛就不那麼容易對付了，它是比裂蹄牛更危險的獵物。$B$B殺死十二頭裂蹄公牛，然後再來誇耀你的狩獵技能吧。$B$B你可以在營地以西和以南方向的納格蘭中心地帶找到它們的蹤跡。','殺死12頭裂蹄公牛，然後向納格蘭奈辛瓦里狩獵隊營地的赫米特·奈辛瓦里覆命。','','去納格蘭找奈辛瓦里狩獵隊營地的赫米特·奈辛瓦里。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9851 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9851,'zhTW','狩獵裂蹄牛','班塔爾是外域的裂蹄牛中最兇猛也是最難捕捉的一隻。她身上的鬃毛也是最濃密的。$B$B據說她和一群裂蹄牛生活在沃舒古附近的靈魂平原上。想要證明你的狩獵技能？把她的犄角帶回來！','將班塔爾的犄角交給納格蘭奈辛瓦里狩獵隊營地的赫米特·奈辛瓦里。','','去納格蘭找奈辛瓦里狩獵隊營地的赫米特·奈辛瓦里。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9852 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9852,'zhTW','終極挑戰','塔絲克是納格蘭所有雷象的王后，你在別處肯定見不到像她這樣體型龐大的雷象！$B$B你最好不要小瞧塔絲克，一定要尊敬這個強大的對手！巴克洛爾、裂腸者和班塔爾的力量都\\r\\n不足以與她相提並論。遙遠的西南方有一處高聳的斷崖，可以眺望沃舒古，據說她經常在那一帶的某處懸崖附近出沒。將塔絲克之心帶回來給我。$B$B哦，對了，你要不要留下一封遺書？要是你不幸沒有回來，我可以幫忙將它交給你的家人。','將塔絲克之心交給納格蘭奈辛瓦里狩獵隊營地的赫米特·奈辛瓦里。','','去納格蘭找奈辛瓦里狩獵隊營地的赫米特·奈辛瓦里。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9853 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9853,'zhTW','侵佔者古羅克','必須召喚出古羅克。你，召喚古羅克，然後殺掉他。$B$B去西北方的戰槌山，那裡的食人魔將古羅克當作神崇拜。收集戰槌食人魔的徽記，擺放在戰槌山的大地印記上。只有這樣才能召喚出古羅克。記得，7枚徽記。$B$B如果你能獲勝，就將古羅克的徽記帶回來交給戈達烏。戈達烏會毀掉他的徽記。$B$B<戈達烏做出猛烈撕咬的動作，你腳下的大地震顫起來。>','殺死侵佔者古羅克，將古羅克的徽記交給納格蘭元素王座的戈達烏。','','去納格蘭找元素王座的戈達烏。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9854 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9854,'zhTW','狩獵風鵬','$c，你是否跟我一樣嚮往獵手的生活？你知道追捕獵物時如何保持沉著冷靜嗎？知道怎樣才算是對倒下的獵物的尊敬嗎？我會教你領悟其中的秘訣。$B$B納格蘭蔥翠的大草原上生活著無數野生動物。去獵殺一些風鵬，然後再來跟我談話。$B$B營地四周都能找到它們的蹤跡。','殺死12只風鵬，然後向納格蘭奈辛瓦里狩獵隊營地的“好兒子”沙度·遠行者覆命。','','去納格蘭找奈辛瓦里狩獵隊營地的“好兒子”沙度·遠行者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9855 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9855,'zhTW','狩獵風鵬','想要獵殺最強大的野獸，就必須保持進取心！在你茫然不知所措的時候，我會為你指明方向。$B$B納格蘭生活著另一種更可怕的風鵬。下一步就是獵殺那些飢餓的風鵬。你可以在營地以西和西南方向的納格蘭中心地帶找到它們的蹤跡。','殺死12只飢餓的風鵬，然後向納格蘭奈辛瓦里狩獵隊營地的“好兒子”沙度·遠行者覆命。','','去納格蘭找奈辛瓦里狩獵隊營地的“好兒子”沙度·遠行者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9856 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9856,'zhTW','狩獵風鵬','$c，備戰吧。勇敢地面對風鵬的女王——裂腸者！你殺了這麼多女王的子民；為了表示對獵物的尊重，至少你要給她復仇的機會吧！去遙遠的西邊尋找裂腸者，她跟體型較大的風鵬生活在一起。$B$B如果你能戰勝她，就把裂腸者的眼睛帶回來。','將裂腸者的眼睛交給納格蘭奈辛瓦里狩獵隊營地的“好兒子”沙度·遠行者。','','去納格蘭找奈辛瓦里狩獵隊營地的“好兒子”沙度·遠行者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9857 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9857,'zhTW','狩獵塔布羊','我今天不想外出狩獵。你願意替我跑一趟嗎？$B$B我跟赫米特提過，今天會去獵殺一些塔布羊。塔布羊在納格蘭廣為分佈，雄性塔布羊更是上等的獵物。你可以在附近的樹林中找到它們。$B$B你能勝任這件差事嗎？','殺死12頭塔布雄羊，然後向納格蘭奈辛瓦里狩獵隊營地的哈羅德·蘭恩覆命。','','去納格蘭找奈辛瓦里狩獵隊營地的哈羅德·蘭恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9858 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9858,'zhTW','狩獵塔布羊','這該死的傷簡直是要了我的命。你願意再……<咳嗽聲>……替我跑一趟嗎？$B$B這次你要獵殺一些食棘者。跟雄性塔布羊比起來，它們更難對付，你千萬不能大意。你可以在……<咳嗽聲>……營地以西和以南方向的納格蘭中心地帶找到塔布羊食棘者的蹤跡。$B$B去吧……<咳嗽聲>……讓赫米特瞧瞧你的能力。我會沒事的。','殺死12頭塔布羊食棘者，然後向納格蘭奈辛瓦里狩獵隊營地的哈羅德·蘭恩覆命。','','去納格蘭找奈辛瓦里狩獵隊營地的哈羅德·蘭恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9859 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9859,'zhTW','狩獵塔布羊','<劇烈的咳嗽聲。>$B$B別擔心……<咳嗽聲>……我。我會沒事的。這點小傷……<咳嗽聲>……算不了什麼。$B$B唔，我想你還得……<咳嗽聲>……再替我跑……<咳嗽聲>……跑一趟。$B$B獵殺那頭名叫巴克洛爾的塔布羊，他是塔布……<咳嗽聲>……塔布羊之王。你最好……<咳嗽聲>……帶上你的朋友。$B$B把他的蹄子……<咳嗽聲>、<咳嗽聲>……帶回來。$B$B去遙遠的西邊尋找……<咳嗽聲>尋找他的蹤跡。','將巴克洛爾的蹄子交給納格蘭奈辛瓦里狩獵隊營地的哈羅德·蘭恩。','','去納格蘭找奈辛瓦里狩獵隊營地的哈羅德·蘭恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9860 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9860,'zhTW','新的指示','$N，立即去向塞德瑞克報告。你給予紫羅蘭之眼的重大貢獻必將得到回報。$B$B$c，好好想想，你希望我們和我們的組織給你什麼；不過你放心，你幫助了達拉然的大法師們，我們是絕不會讓你後悔的。','與達拉然巨坑外的大法師塞德瑞克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9861 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9861,'zhTW','呼嚎之風','這團飄忽不定的空氣元素用你難以理解的語言述說著什麼。你認為這是被稱為古卡利姆多語的元素語言。或許元素王座那裡的人會對這件與眾不同的東西有獨到的見解。','返回元素王座尋找某個會講古卡利姆多語的人，將呼嚎之風交給他。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9862 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9862,'zhTW','暗血腐蝕者','是暗血破碎者！他們抓走了空氣之靈並肆意地折磨它們！說起來，暗血氏族跟我同屬破碎者一族，不過他們卻聽命於盤牙水庫的沼地領主穆塞雷克。$B$B那些暗血淨化者抓走了好些空氣之靈，利用它們在元素界製造騷亂。而且，暗血破碎者似乎還剛剛洗劫了西南方一座名叫日泉崗哨的獸人村落，企圖利用元素強大的魔法力量擾亂湖中的水之靈。去殺掉那些暗血淨化者，$N！','納格蘭元素王座的元素師莫格要你殺死5個暗血淨化者。','','去納格蘭找元素王座的元素師魯艾普。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9863 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9863,'zhTW','邪惡的信仰','蓋亞安祖母的病情加重之後，瑪格漢氏族就不斷遭到外族侵襲，而卑鄙的暗血氏族在我們四面受敵之際乘虛而入！$B$B這些天來，暗血破碎者發動了不下五次攻擊。他們還佔領了原本屬於我們的日泉崗哨。$B$B我們必須要打擊暗血氏族的囂張氣焰，給他們點顏色瞧瞧！殺掉那些信仰邪教的傢伙，將他們隨身攜帶的神像搶回來，這樣他們就知道厲害了。','將10個暗血神像交給納格蘭加拉達爾的先知古庫斯。','','去納格蘭找加拉達爾的先知古庫斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9864 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9864,'zhTW','失蹤的戰鬥小隊','加拉達爾最近遭受襲擊後，一群年輕的瑪格漢士兵決定向暗血氏族發起反攻。他們被憤怒衝昏了頭腦，根本聽不進任何勸阻。這些孩子離家已有一週時間了。$B$B$r，懇請你一定要找到這些孩子們的下落！他們才剛剛成年而已，如何能與兇蠻的暗血氏族抗衡？$B$B沿著西邊的道路尋找這支戰鬥小隊，他們就是從那條路離開的。$B$B$N，記得繞道避過哈蘭。那兒衝突不斷，很不安全。','找到失蹤的加拉達爾戰鬥小隊。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9865 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9865,'zhTW','我們曾是戰士','陌生人，雖然我不認識你，不過能請你幫個忙嗎？雖然乞求他人的幫助令我感到很羞愧，但是整個戰鬥小隊只有我一人僥倖活了下來。$B$B滿腔的怒火讓我難以自制。我……我要報仇，血債血償！你可曾有過這樣的經歷？我想要掄起斧頭，將敵人統統劈成兩半，直到耗盡最後的氣力，再也揮不動武器。$B$B正南方就是日泉崗哨。我們的敵人就盤踞在那兒……殺了他們……不留活口……','消滅20個暗血清道夫和10個暗血掠奪者。','','去納格蘭找瑪格漢車隊的小薩魯法爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9866 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9866,'zhTW','他要遊歷世界……','$N，能幫我最後一個忙嗎？我不想回加拉達爾。我命中註定要漂泊流浪……總有一天，我要做出一番大事來。$B$B請你轉告先知考爾胡克，我不回家了。我不能回家。我必須遊歷整個世界……他會明白的。','返回加拉達爾，將訊息告訴先知考爾胡克。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9867 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9867,'zhTW','暗血領袖','新近爆發的戰爭奪走了許多夥伴的性命。$B$B數十年來，我們與納格蘭的食人魔一直處於交戰狀態；最近卻遭遇了新的威脅。暗血破碎者氏族襲擊了西南方的漁村——日泉崗哨，而村裡的獸人要麼被屠殺，要麼被逐出了家園。$B$B雖然別的族人認為我們應該將入侵者悉數殺掉，不過我覺得“擒賊先擒王”方為上策。我不知道暗血酋長是誰，不過我想你應該辨認得出。','將暗血酋長奧托爾的徽記交給納格蘭加拉達爾的先知瑪加迪。','','去納格蘭找加拉達爾的先知瑪加迪。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9868 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9868,'zhTW','卡達什圖騰','陌生人，謝謝你。要不是你路經此地，我肯定早沒命了。$B$B三天前，暗血破碎者趁著夜色襲擊了加拉達爾，我也不幸淪為戰俘。後來，我聽到，這幫野蠻的傢伙居然在尋找卡達什圖騰！若是被他們找到，外域很可能會再次陷入動盪！絕不能讓卡達什圖騰落入暗血破碎者的手中！$B$B請帶我逃離日泉崗哨。陌生人，如果我不能活著返回加拉達爾，那請你務必將這裡的情況轉告給加爾魯什……','護送瑪格漢俘虜逃離日泉崗哨，完成任務後返回加拉達爾，向加爾魯什覆命。','營救瑪格漢俘虜','去納格蘭找加拉達爾的加爾魯什。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9869 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9869,'zhTW','元素王座','$r，你好。我是大地之環的元素師猶基。我來塔拉的目的是讓庫雷尼方面瞭解元素生物的近況。$B$B你能幫我個忙嗎？請你轉至納格蘭北部山丘地帶、天歌湖對岸的元素王座，告訴元素師沙爾瓦克我已經平安抵達塔拉。她會獎勵你的，這對你來說不過是個舉手之勞吧。','元素師猶基希望你轉至元素王座，與元素師沙爾瓦克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9870 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9870,'zhTW','元素王座','$r，你好。我是大地之環的元素師亞爾哈。我來加拉達爾向瑪格漢氏族彙報元素的情況。$B$B你能幫我個忙嗎？轉至納格蘭北部、天歌湖對岸的元素王座，告訴元素師沙爾瓦克我已經平安抵達加拉達爾，好嗎？她會獎勵你的，這對你來說不過是個舉手之勞吧。','元素師亞爾雜湊望你轉至元素王座，與元素師沙爾瓦克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9871 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9871,'zhTW','暗血入侵者','羊皮紙上粗略地描繪著納格蘭的地圖。塔拉的位置標記著一個大大的紅叉。似乎這幫野蠻人想要攻擊這座小鎮。立刻將暗血入侵計劃交給塔拉的阿雷克隆。','將暗血入侵計劃交給納格蘭的塔拉的阿雷克隆。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9872 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9872,'zhTW','暗血入侵者','羊皮紙上粗略地描繪著納格蘭的地圖。在加拉達爾的位置畫著一個紅色的大叉。看來這幫野蠻的傢伙計劃入侵這座鎮子。將暗血入侵計劃交給加拉達爾的加爾魯什。','將暗血入侵計劃交給加爾魯什。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9873 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9873,'zhTW','奧托爾，我的老朋友……','這些入侵計劃書應該是由暗血酋長奧托爾所擬定的。他原本曾是一位高貴的破碎者，精通於駕馭元素的力量，但可惜現在已經成為沼地領主穆塞雷克身邊一條搖尾乞憐的哈巴狗了。$B$B計劃書中寫道，他們已經佔領了西北方一座名叫日泉崗哨的獸人村落。$B$B立刻轉至日泉崗哨殺死暗血酋長奧托爾。你所做的一切都是為了我們大家的生存……','殺死暗血酋長奧托爾，然後向納格蘭塔拉的阿雷克隆覆命。','','去納格蘭找塔拉盆地的阿雷克隆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9874 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9874,'zhTW','阻止汙染','$N，我剛剛得知日泉崗哨那場慘絕人寰的悲劇。邪惡的暗血氏族侵佔了西北方的日泉崗哨，大肆殺戮居住在那兒的獸人。更糟糕的是，他們開始將屍體拋入日泉湖。一旦屍體腐爛，我們的主要水源就會遭到嚴重汙染。$B$B我要交給你的這項任務相當噁心，但是勢在必行。帶上這把魔油火炬，返回日泉崗哨，燒掉那些腐爛的獸人遺體……','用魔油火炬燒掉10具日泉村民的遺體，然後向納格蘭塔拉的先知歐圖布覆命，並歸還魔油火炬。','','去納格蘭找塔拉的先知歐圖布。','燒掉日泉村民的遺體','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9875 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9875,'zhTW','未歸類的植物','勞蘭娜一定沒見過這株特殊的植物。你確定你所發現的是她尚未編錄的新物種。你最好把它交給勞蘭娜，看看她對此瞭解多少。','將未歸類的植物交給贊加沼澤塞納里奧庇護所的勞蘭娜·薩維爾。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9876 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9876,'zhTW','失蹤的先遣隊','我派了一小隊德魯伊轉至毒蛇湖調查你發現的水泵。我原本以為他們很快就會回來，但是到現在都沒有任何訊息。$B$B你是我們最能幹的盟友之一，我想麻煩你去尋找他們的下落，看看到底出了什麼事。','伊謝爾·風歌要你轉至贊加沼澤的盤牙水庫，在入口附近搜尋塞納里奧遠征隊德魯伊的下落。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9877 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9877, 'zhTW', '恢復藥劑', '對抗天譴軍團的戰役讓我們死傷慘重。每天都有很多人被殺，還有更多人的命運更悲慘。天譴軍團俘虜人質也是常見的事。和在死亡之域等待他們的比起來死亡會是更好的選擇。他們在可怕的毒藥效果下喪失意志被嚴刑拷打。安寧地的藥劑師倫澤紳發明了一種解藥;去找他並取得這個恢復藥劑。', '和安寧地的藥劑師倫澤紳談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9878 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9878,'zhTW','解決問題','暗血氏族在納格蘭滋擾生事，嚴重影響了我們周圍的環境。元素們躁動難安，由此波及到此地所有生物。更糟糕的是，日泉崗哨的大屠殺事件重新點燃了獸人們對破碎者的新仇與舊恨。$B$B雖然庫雷尼跟暗血是截然不同的兩個氏族，可在獸人看來，我們都是十惡不赦的破碎者。$B$B我們必須解決眼下這進退維谷的窘境。轉至西北方的日泉崗哨，消滅盤踞在那兒的暗血破碎者。','消滅10個暗血清道夫和5個暗血掠奪者，然後向納格蘭塔拉的智者普里魯魯克覆命。','','去納格蘭找塔拉的智者普里\\r\\n魯魯克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9879 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9879,'zhTW','卡達什圖騰','陌生人，要不是你恰好路經此地，我早就沒命了。為了尋找一件失蹤的聖物，他們已經殺掉了不少庫雷尼。$B$B那件聖物據說名叫卡達什圖騰。真想不通暗血破碎者為什麼會認定我們知道這東西的下落，圖騰難道不是獸人才會有的東西嗎？$B$B請你務必將此事告訴阿雷克隆大人。或許他知道暗血破碎者為什麼會為了這些獸人的玩意兒綁架並拷問我們庫雷尼。$B$B我們快走吧，不然麻煩就大了。','護送庫雷尼俘虜逃離日泉崗哨，完成任務後返回塔拉，向阿雷克隆覆命。','營救庫雷尼俘虜','去納格蘭找塔拉的阿雷克隆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9880 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9880,'zhTW','Hellfire Penninsula: -pn - A - ToWoW - Hellfire Turnin Cap','','','','去找地獄火半島的委任官翠希·普羅維爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9881 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9881,'zhTW','Hellfire Penninsula: -pn - H - ToWoW - Hellfire Turnin Cap','','','','去找地獄火半島的傳令官布萊肯·黑眼。','','','','',0);
