INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9882,'zhTW','偷盜賊的東西……能算偷麼？','節點親王哈拉邁德大人嚴令禁止我們在沃舒古中開採水晶，惟恐這樣會激怒某位強大的納魯。這令我們的工作嚴重受阻。$B$B不過，我已經找到空子可鑽了。$B$B你看，被這塊大鑽石吸引來的虛靈可不僅僅只有我們星界財團而已，還有個名叫加瓦克希的盜賊頭目領著一幫虛靈手下也進入了沃舒古，並且已經開始搬運那些大塊的碎片了。$B$B$r，你的任務就是替我們奪得那些水晶碎片，這可不算是我們親自開採的。偷取這些盜賊的東西可不算偷，對吧？','將10塊沃舒古水晶碎片交給納格蘭埃瑞斯碼頭的傑赫。','','去納格蘭找埃瑞斯碼頭的傑赫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9883 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9883,'zhTW','更多水晶碎片','','','','去找納格蘭的傑赫。','','','','',0);
