INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9888,'zhTW','落魄的領袖','石拳食人魔趁著夜色突襲了村落，我僥倖逃生，來到加拉達爾尋求幫助。$B$B陌生人，你猜我得到了什麼答覆？$B$B<約林指著加爾魯什。>$B$B他拒絕伸出援手。食人魔在我的家園橫行，這傢伙卻呆呆地坐在那兒，對著篝火堆抹眼淚。我的族人會面臨怎樣的命運？$B$B我們的村落已是殘垣斷壁，密探安克爾已經返回血環廢墟查探敵情去了。你能去那兒找到他，幫幫我的族人嗎？他就躲在納格蘭和泰羅卡森林的交界處。','約林·死眼要你找到吉爾拉斯並跟他談談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9889 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9889,'zhTW','別殺那個胖傢伙！','數日來，我一直在觀察這幫野蠻的食人魔。他們當中的那個大胖子說要等待時機，但是他究竟在等什麼就不得而知了。$B$B我倒是有個法子，不過你得使用暴力。殺掉他手下的僕從，然後將這傢伙揍個半死。他一定會跪地求饒，乖乖地吐露秘密的。','泰羅卡森林的吉爾拉斯要求你殺死10名石拳入侵者，並擊敗無情的安克爾，讓他招供。','安克爾招供','去泰羅卡森林找血環廢墟的無情的安克爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9890 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9890,'zhTW','成功了！','數年來，石拳氏族一直統治著外域的所有食人魔。在氏族首領克魯的帶領下，我們在各自的領地上過著安寧的生活。最近幾個月，新近崛起的戰槌食人魔氏族襲擊了我們的村落，許多族人也因此罹難。這幫強盜佔領了我們在納格蘭的大部分屬地，他們的雙手沾滿了族人們的鮮血。$B$B我們別無選擇，只能將這座獸人村落當做避難所。石拳氏族就快滅絕了……$B$B克魯下落不明，整個氏族陷入混亂。氏族首領暫時由蘭特瑞索·火刃擔任。','返回泰羅卡森林，將安克爾供述的秘密告訴吉爾拉斯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9891 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9891,'zhTW','吉爾拉斯這個懦夫！','返回加拉達爾，將安克爾探察到的秘密告訴約林。這幫食人魔毀了我們的家園，殺害我們的同胞，僅僅是為了爭奪更多的生存空間。約林聽到這個訊息必定會勃然大怒。$B$B願先祖的靈魂與你同在……我會繼續躲在這兒觀察動向；如果你有需要的話，盡快回來找我。','返回納格蘭的加拉達爾，將安克爾供述的秘密告訴約林·死眼。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9892 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9892,'zhTW','更多黑曜石作戰念珠','','','','去找納格蘭的傑赫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9893 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9893,'zhTW','黑曜石作戰念珠','$N，不知道什麼時候我們才能開採沃舒古的水晶。眼下我們只能呆在這兒乾耗著。$B$B幸運的是，我發現了另一項收入來源。納格蘭的食人魔都佩戴著黑曜石製成的作戰念珠，這種礦石在許多地方都價值不菲。$B$B最近瑟利德為了解決埃瑞斯碼頭的安全問題已經幹掉了不少食人魔。他搞的那些作戰念珠就當是我們額外的收入吧……抱歉，我自言自語了。總之，你什麼都不用管，只需去從食人魔身上把東西拿來，然後交給我。','將10串黑曜石作戰念珠交給納格蘭埃瑞斯碼頭的傑赫。','','去納格蘭找埃瑞斯碼頭的傑赫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9894 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9894,'zhTW','保護觀察者','在贊加沼澤的旅途中，你可能遇見過一些遠征隊的觀察者。他們通常在戶外作業：記錄沼澤地特有的生物，收集樣本以及核對物種目錄。$B$B$c，觀察者的安全非常重要。因為沼澤獸的襲擊，我們不得不召回派去南邊蘑菇洞的觀察者。監護者哈穆特認為只要殺死它們的首領克拉其大王，沼澤獸的攻擊就會立即結束。','殺死克拉其大王，然後向塞納里奧庇護所的喚風者塔魯·黑蹄覆命。','','去贊加沼澤找塞納里奧庇護所的喚風者塔魯·黑蹄。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9895 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9895,'zhTW','崩潰的平衡','$N，你仔細觀察過周圍的環境嗎？這片土地呈現出明顯的病態，它掙扎著想要保持平衡卻失敗了。$B$B如果你留意到沼澤地的生態，必定能看出一些端倪。某些生物以驚人的速度生長著，體型大大超過同類物種，變得越來越具有侵略性。$B$B沼澤之鞭正是不受抑制、過度生長的生物的典型。如果你願意的話，就去庇護所南邊的沼澤地親眼看看。$B$B一定要做好防禦準備。這隻怪物不懂什麼是仁慈。','找到沼澤之鞭並殺死它，然後向塞納里奧庇護所的萊森·月火覆命。','','去贊加沼澤找塞納里奧庇護所的萊森·月火。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9896 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9896,'zhTW','黑釘之刺','以卡茲格羅斯的名義發誓，這兒真是炙熱難耐！我沒有理由責怪先前撤離的隊伍，但是大夥兒心裡明白，迫使他們離開的並不是熱浪。唔，這幫傢伙不願意承認罷了，他們是因為懼怕黑釘才撤離的。$B$B探險隊曾駐紮在此地以西德萊尼雙塔的南面，就在蠻沼村以北。那兒分佈著巨大的胡蜂群，他們常常受到無情的攻擊！我迫不及待地想知道，當我將黑釘之刺帶回鐵爐堡時，他們的臉上會有什麼樣的表情！','將黑釘之刺交給泰雷多爾的勘探員柯納爾。','','去贊加沼澤找泰雷多爾的勘探員柯納爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9897 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9897,'zhTW','我得救了！','我是很樂意與他人分享的。你從甘克雷手中救了我的命，我真是太高興了！我從贊加沼澤收集了大量皮革，分一點給別人完全不成問題！','將一捆皮革交給納格蘭奈辛瓦里狩獵隊營地的哈羅德·蘭恩。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9898 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9898,'zhTW','求愛的禮物','她將屬於我。沒錯，她一定會是我的。$B$B瑪加沙難道不是你所見過的最美麗的巨魔嗎？我必須想辦法贏得她的心。當然，現在她的眼裡只有祖萊，不過我要改變這一切。我已經想好了一個簡單有效的辦法。$B$B我要向她證明，我是位優秀的獵手。朋友，這就是我要交代你的事情。西邊的德萊尼雙塔以南有一隻名叫黑釘的巨蜂。將黑釘之刺帶回來給我，我就可以施展我的魅力了。','將黑釘之刺交給沼澤鼠崗哨的裡維伊。','','去贊加沼澤找沼澤鼠崗哨的裡維伊。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9899 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9899,'zhTW','未完的職責','想辦法讓裡維伊清醒過來吧！他完全忘記了自己的職責，整天就想著怎麼討我歡心。我試著不去理睬他，也勸說過他好幾次，可根本無濟於事。$B$B我不得不替他收拾這堆爛攤子。他原本奉命殺掉孢子之翼，但我打賭這隻蝙蝠還活得好好的。如果你有時間的話，能不能去死亡泥潭西部殺死孢子之翼？我要利用這段時間，讓裡維伊清醒過來。','沼澤鼠崗哨的瑪加沙要你殺死孢子之翼。','','去贊加沼澤找沼澤鼠崗哨的瑪加沙。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9900 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9900,'zhTW','加瓦克希','傑赫看待問題總是會往好的方面想，他認為我們大可利用在沃舒古活動的虛靈盜賊獲取水晶碎片，可是這幫虛靈嚴重威脅著埃瑞斯碼頭的安全。$B$B他們的首領加瓦克希更是名極度危險的罪犯。而我的首要職責就是消滅這類隱患。$B$B如果你想要證明自己的實力，就去做掉加瓦克希吧。我保證會好好獎勵你的。','殺死沃舒古附近的加瓦克希，然後向納格蘭埃瑞斯碼頭的瑟利德覆命。','','去納格蘭找埃瑞斯碼頭的瑟利德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9901 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9901,'zhTW','遺留事務','探險者協會派出的第一支遠征隊發回報告，稱他們被一隻名叫孢子之翼的巨型蝙蝠襲擊。他們在沼澤地中並未停留太久便匆忙離開了，因此沒有機會殺死它，我打算幫他們解決這個問題。$B$B遠征隊在報告中提到這隻蝙蝠在死亡泥潭的西南方活動。我聽守備官伊達爾說，死亡泥潭就在泰雷多爾的東北方。','泰雷多爾的勘探員柯納爾要求你幹掉孢子之翼。','','去贊加沼澤找泰雷多爾的勘探員柯納爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9902 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9902,'zhTW','沼光湖的恐怖','在穿越納迦聚集地的旅途中，我才瞭解到殘忍的納迦是如何對待那些倒黴的同胞的。在西南方的沼光湖，我親眼目睹了一名極度邪惡的工頭玩起致命的遊戲。每當那隻名叫恐爪的龍蝦人要進食時，他便強行將奴隸們趕到沼光湖的小島上。$B$B我沒有必要繼續描述接下來發生的事情了。我們勢單力薄，不能直接向納迦發動攻擊；但是我們可以殺死這隻寵物，阻止這種殘忍的取樂方式。','殺死恐爪，然後向奧雷柏爾營地的普爾魯覆命。','','去贊加沼澤找奧雷柏爾營地的普爾魯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9903 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9903,'zhTW','多頭蛇之王','你殺死了很多小多頭蛇，但是我懷疑穆拉格什對此毫不在意。這頭狡猾兇殘的巨獸令許多垂釣者吃足了苦頭。$B$B看來我們要給它帶來的麻煩劃上句號了。穆拉格什就躲藏在東北方毒蛇湖的深處，它早已風光不在，可惜它自己還沒有意識到這一點。','殺死穆拉格什，然後向薩布拉金的蘇爾加亞覆命。','','去贊加沼澤找薩布拉金的蘇爾加亞。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9904 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9904,'zhTW','獵殺恐爪','我在沼澤地中釣到過各種各樣的魚，不過有件事卻始終讓我耿耿於懷。你看，我連電鰻和泥鱗狂魚都釣上來過，但是上次我在沼光湖的小島上釣魚時，眼看一個巨型泥沼龍蝦人上了鉤，卻被它咬斷魚線逃走了。$B$B這傢伙名叫恐爪，在它死掉之前我都不會安心的。恐爪身型龐大，普通的漁夫是不可能捉到它的，因此我們只能採用古老的辦法，那就是直接殺死它。','殺死恐爪，然後向薩布拉金的蘇爾加亞覆命。','','去贊加沼澤找薩布拉金的蘇爾加亞。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9905 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9905,'zhTW','瑪克圖的復仇','上次瑪克圖在毒蛇湖收集多頭蛇鱗片時，遭到一頭前所未見的巨型多頭蛇的襲擊。瑪克圖伸手去取他的長矛，但是已經來不及了。他僥倖蛇口逃生。$B$B誰知道呢？說不定下次就沒這麼幸運了。瑪克圖不希望有下次。你願意幫瑪克圖報仇，殺死穆拉格什嗎？','找到穆拉格什並殺死他，然後返回奧雷柏爾營地向瑪克圖覆命。','','去贊加沼澤找奧雷柏爾營地的瑪克圖。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9906 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9906,'zhTW','粗暴的訊號','食人魔只會屈從於力量。一旦我們顯露出內心的軟弱，他們就會利用這一點徹底擊潰我們。$B$B加爾魯什大概已經放棄了抵抗，任由那些強盜侵犯我們的家園，但是我絕不會束手就擒！$N，我要你給石拳食人魔捎個信，用他們看得懂的語言：暴力。$B$B轉至此地東南方的火刃廢墟，讓他們嚐嚐瑪格漢氏族的厲害。$B$B$N，對了，在你離開之前不妨問問其它人，看他們是否願意幫助你，與你同去。','納格蘭加拉達爾的約林·死眼要你殺死8個石拳打擊者和8個石拳秘術師。','','去納格蘭找加拉達爾的約林·死眼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9907 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9907,'zhTW','大膽的攻勢','此地的正西邊就是哈蘭盆地。石拳食人魔的突擊部隊就駐紮在盆地的北風裂谷和南風裂谷中。$B$B我要你以瑪格漢氏族的名義，殺死你遇見的所有石拳食人魔。','納格蘭加拉達爾的約林·死眼要你殺死10個石拳戰士和10個石拳法師。','','去納格蘭找加拉達爾的約林·死眼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9908 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9908,'zhTW','Hellfire Penninsula: -pn - A - ToWoW - Hellfire Turnin','','','','去找地獄火半島的委任官翠希·普羅維爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9909 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9909,'zhTW','Hellfire Penninsula: -pn - H - ToWoW - Hellfire Turnin','','','','去找地獄火半島的傳令官布萊肯·黑眼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9910 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9910,'zhTW','揚旗示威','如果你正要轉至火刃廢墟的話，我恰好有項任務要拜託你。帶上這些瑪格漢軍旗，將它們插在火刃食人魔營地三處最顯眼的地方。我建議你挑選那些引人注目的區域，比如那些營地上層熊熊燃燒的篝火堆。總之，將瑪格漢軍旗分別插在第一堆火刃篝火、第二堆火刃篝火和第三堆火刃篝火附近。$B$B讓這些軍旗可以時刻提醒那些僥倖撈到一條命的食人魔，我們瑪格漢獸人不是好惹的！','納格蘭加拉達爾的秘法師埃爾卡甘要你將瑪格漢軍旗分別插在第一堆火刃篝火、第二堆火刃篝火和第三堆火刃篝火附近。完成任務後將剩餘的瑪格漢軍旗還給他。','','去納格蘭找加拉達爾的秘法師埃爾卡甘。','放置第一面軍旗','放置第二面軍旗','放置第三面軍旗','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9911 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9911,'zhTW','沼澤中的伯爵','這塊帶血的下顎骨是虛空鰩的骨頭，這隻體型龐大的虛空鰩一定是贊加沼澤中最大的生物。從下顎骨的構造來看，“伯爵”放棄了食用腐肉的傳統，改吃新鮮的肉類。$B$B想必塞納里奧遠征隊會對這件樣本感興趣的。去泥濘山西邊的營地找觀察者莉薩奧談談吧。','將“伯爵”昂古拉的下顎骨交給贊加沼澤中塞納里奧哨站的觀察者莉薩奧。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9912 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9912,'zhTW','塞納里奧遠征隊','塞納里奧議會派駐外域的主要遠征軍組織被稱為塞納里奧遠征隊。儘管它最早是由塞納里奧議會直接領導的探險隊，但現在已經發展成了一支人數眾多、完全獨立的軍隊。$B$B遠征隊的首領伊謝爾·風歌希望我們能派些自願者去她的哨站。轉至贊加沼澤東部的塞納里奧庇護所向她報告。沿著西邊的大道一直往前走就到了。','轉至贊加沼澤的塞納里奧庇護所，與伊謝爾·風歌談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9913 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9913,'zhTW','星界財團需要你！','星界財團正在尋找像你這樣足智多謀的勇士。我們是最誠實、最勤勉、最容易相處的虛靈。$B$B星界財團對你的要求只有忠誠、奉獻和一點道德上的靈活性而已。如果你對此感興趣的話，就去我們的首領傑赫談談。他就在沃舒古北面的埃瑞斯碼頭。','向納格蘭埃瑞斯碼頭的傑赫報到。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9914 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9914,'zhTW','象牙生意','象牙，那可是供不應求的緊俏貨。許多顧客都不顧路途遙遠趕來排隊搶購。$B$B我可以考慮讓你入夥，分你一筆利潤。$B$B納格蘭野生雷象的象牙成色極佳，屬於最受歡迎的品種。不過，好鬥的雷象例外，它們的象牙破碎太多，品質過於低劣。$B$B別擔心，這不屬於偷獵；我與獸人和德萊尼都達成了協議。$B$B怎麼樣，你入夥嗎？','將3物件牙交給納格蘭埃瑞斯碼頭的沙德雷克。','','去納格蘭找埃瑞斯碼頭的沙德雷克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9915 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9915,'zhTW','更多象牙','','','','去找納格蘭的沙德雷克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9916 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9916,'zhTW','血環補給箱','石拳食人魔洗劫了我們的村落，將偷來的補給箱運去了西邊哈蘭盆地的北風裂谷和南風裂谷。$B$B如果你要去那邊的話，就替我留意一下這些血環補給箱吧。如果我們能拿回這些補給箱，或許能幫加拉達爾減輕一點負擔。','納格蘭加拉達爾的秘法師埃爾卡甘要你找回10個血環補給箱。','','去納格蘭找加拉達爾的秘法師埃爾卡甘。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9917 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9917,'zhTW','是我眼花了？','是我眼花了，還是遠處真的有一隊食人魔在狩獵？他們遠離老巢來這兒做什麼？陌生人，我一點都不喜歡食人魔！麻煩真多，先是暗血破碎者，現在又是食人魔。我們卻沒有足夠的人手來解決這些滋擾生事的傢伙。$B$B你能調查一下食人魔在東邊的活動情況嗎？此地以東大約兩百碼的地方就是他們的營地。那些石拳獵手就駐守在營地周圍，很容易辨識。幹掉他們，搞清楚他們的計劃！','找回石拳計劃書，然後向納格蘭塔拉的女獵手彬圖克覆命。','','去納格蘭找塔拉的女獵手彬圖克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9918 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9918,'zhTW','這是我的地盤！','作戰計劃書出自某個食人魔中尉之手。他應該是叫達普，或者是拉普吧。$B$B<彬圖克將羊皮紙放在一旁，仰起頭來想了想。>$B$B也有可能是比利。$B$B我想你得再跑一趟，跟這位比利或者拉普或者達普……管他叫什麼！跟這傢伙談談。小心翼翼地靠近他，若是談話行不通，那就拳腳伺候。','與拉普交談，獲取足夠的情報後向納格蘭塔拉的女獵手彬圖克覆命。','','去納格蘭找塔拉的女獵手彬圖克。','審問拉普','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9919 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9919,'zhTW','孢子村','你真是個好心的$r，$N。完全不像我見過的其它人。$B$B你應該去見見我的同胞，他們一定會感激你的。把這些孢子囊拿去交給我的首領姆希菲。你可以在北邊的孢子村找到他。','去贊加沼澤孢殖林北邊的孢子村，將搶救出來的孢子囊交給姆希菲。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9920 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9920,'zhTW','擊碎者姆摩爾','你必須立即找到姆摩爾！他應該就在塔拉中央的噴泉旁邊。將食人魔的原話一字不漏地告訴他！','納格蘭塔拉的女獵手彬圖克要你去找擊碎者姆摩爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9921 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9921,'zhTW','火刃廢墟','這些食人魔狩獵隊分明是入侵者的先遣部隊。我們必須在這幫傢伙糾集大軍夷平城鎮之前殲滅他們。$B$B你的雙手將不可避免地沾滿鮮血，$r。$B$B食人魔的主營地設在塔拉正東方，泰羅卡森林邊界處的火刃廢墟處。要讓石拳氏族知道，塔拉絕不會屈服！','殺死8個石拳打擊者和8個石拳秘術師，然後向納格蘭塔拉的擊碎者姆摩爾覆命。','','去納格蘭找塔拉的擊碎者姆摩爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9922 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9922,'zhTW','納格蘭的峽谷','$N，幹得漂亮。準備好接受新任務了嗎？$B$B報告稱石拳食人魔的另一支分遣隊躲藏在納格蘭西北部哈蘭盆地中的兩個大裂谷裡。$B$B去對付那些剩下的石拳食人魔吧。','殺死10個石拳戰士和10個石拳法師，然後向納格蘭塔拉的擊碎者姆摩爾覆命。','','去納格蘭找塔拉的擊碎者姆摩爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9923 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9923,'zhTW','救命啊！','救命啊！他們會吃了我的！真的！$B$B鑰匙，我知道鑰匙在那邊的某個食人魔身上。$B$B要是你能救我出去，我的父親一定會用豐厚的獎勵答謝你！他是塔拉的老大，對，就是阿雷克隆。','找到石拳鑰匙，解救考爾奇，然後向塔拉的阿雷克隆覆命。','','去納格蘭找塔拉的阿雷克隆。','營救考爾奇','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9924 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9924,'zhTW','考爾奇又走丟了！','<阿雷克隆嘆了口氣。>$B$B真是難為情啊。你還記得我的兒子考爾奇嗎？對，就是你不久前從火刃廢墟救出來的那個孩子。哎，他的好奇心比較過剩，這次他說他要幫姆摩爾大叔調查石拳部族，結果直奔北邊的食人魔老巢哈蘭盆地去了。$B$B你能轉至哈蘭盆地搜尋他的下落嗎？我會永遠銘記你的恩情。','塔拉的阿雷克隆要你去搭救考爾奇。','','去納格蘭找塔拉的阿雷克隆。','再次營救考爾奇','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9925 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9925,'zhTW','安全問題','傑赫不顧我們的安危，將星界財團的營地設立在靠近沃舒古的地方。他為何這麼做？就因為這傢伙認為在碼頭做買賣比在南邊的山脈能多獲得十個百分點的收入。$B$B至於那些距我們只有十步之遙的空靈爪牙，那就是我這個安全官員的事兒了，完全與傑赫無關。$B$B替我殺掉一些空靈爪牙，我就付你星界財團本地安全預算的十個百分點。別激動，這筆預算的金額沒你想象的那麼多。','納格蘭埃瑞斯碼頭的瑟利德要求你殺死沃舒古附近的8個空靈爪牙。','','去納格蘭找埃瑞斯碼頭的瑟利德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9926 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9926,'zhTW','標誌暗影議會/戰槌任務支線','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9927 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9927,'zhTW','無情的計謀','<蘭特瑞索遞給你一捆旗幟。>$B$B這些是我最近收集到的一批戰槌食人魔軍旗。$B$B我要你轉至正南方的基爾索羅要塞，盡你所能地殺死那裡的基爾索羅成員。每殺死一名基爾索羅士兵，就在屍體上插一面戰槌食人魔軍旗。完成這項任務以及計劃所需的另一項任務之後，回來向我覆命。','轉至基爾索羅堡壘，將10面戰槌食人魔軍旗插在基爾索羅成員的屍體上，然後返回納格蘭火刃廢墟向蘭特瑞索·火刃覆命。$B$B將沒有用完的戰槌食人魔軍旗還給蘭特瑞索。','','去納格蘭找火刃廢墟的蘭特瑞索·火刃。','放置戰槌食人魔軍旗','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9928 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9928,'zhTW','欺詐所需的軍備','要實現我的計劃，你就得從基爾索羅堡壘偷些軍備過來。$B$B在堡壘中搜尋裝有基爾索羅軍備的箱子，然後把這些箱子統統帶回來給我就可以了。$B$B基爾索羅堡壘就在火刃廢墟正南偏西一點的位置。','納格蘭火刃廢墟的蘭特瑞索·火刃要你收集10份基爾索羅軍備。','','去納格蘭找火刃廢墟的蘭特瑞索·火刃。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9929 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9929,'zhTW','失蹤的商人','你剛剛來到這裡不久，我想你還不認識Dugar吧，認識嗎？他是一個能與撒塔斯城中各派都有聯絡的商人。$B$B別問他是怎麼做到的，總之他確實能夠賣給他們一些連我們的軍需官都無法提供的東西。$B$B他三天前離開沙塔斯，可到現在也沒有回來。他通常全程往返也用不了三天的。要是你也打算進入森林的話，可以幫我們找找他嗎？','沿著通往沙塔斯的道路向西北方前進，尋找有關Dugar的一切線索。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9930 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9930,'zhTW','失蹤的商人','你剛剛來到這裡不久，我想你還不認識Deirom吧，認識嗎？他是一個能與撒塔斯城中各派都有聯絡的商人。$B$B別問他是怎麼做到的，總之他確實能夠賣給他們一些連我們的軍需官都無法提供的東西。$B$B他三天前離開沙塔斯，可到現在也沒有回來。他通常全程往返也用不了三天的。要是你也打算進入森林的話，可以幫我們找找他嗎，有任何訊息就和僱傭兵團長Thander說吧。','沿著通往沙塔斯的道路向西北方前進，尋找有關Deirom的一切線索。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9931 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9931,'zhTW','以牙還牙','我要你在那些戰槌食人魔愚蠢而肥胖的腦袋裡播下仇恨的種子。去吧，嘲顱廢墟就坐落在此地西北方的山腳下。$B$B<蘭特瑞索指著你帶回來的基爾索羅軍備箱。>$B$B你認得這些旗子嗎？這就是基爾索羅軍旗。我要你殺入嘲顱廢墟，將這些基爾索羅軍旗插在戰槌食人魔的屍體上。記住，戰槌食人魔的老巢在西北方，別找錯了地方。','納格蘭火刃廢墟的蘭特瑞索·火刃要你殺入嘲顱廢墟，將10面基爾索羅軍旗插在戰槌食人魔的屍體上。$B$B將沒有用完的基爾索羅軍旗還給蘭特瑞索。','','去納格蘭找火刃廢墟的蘭特瑞索·火刃。','放置基爾索羅軍旗','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9932 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9932,'zhTW','屍證','你在基爾索羅堡壘的這一場殺戮為我們創造了非常有利的機會。這些基爾索羅士兵的屍體完全可以用來偽裝一個混戰後的現場。$B$B現在，你立刻轉至嘲顱廢墟的嘲顱營地。營地中應該有一堆燃燒的戰槌篝火堆，當你清理掉礙事的戰槌食人魔以後，就點燃這張潮溼的毛毯。我手下的石拳食人魔看到煙霧訊號後就會悄悄潛入，將基爾索羅士兵的屍體丟棄在營地中。$B$B這將會是戰爭的導火索！','納格蘭火刃廢墟的蘭特瑞索·火刃要你轉至嘲顱營地，在燃燒的戰槌篝火堆處點燃潮溼的毛毯，利用煙霧向食人魔傳遞訊號。','','去納格蘭找火刃廢墟的蘭特瑞索·火刃。','放置基爾索羅屍體','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9933 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9933,'zhTW','回到塔拉','<蘭特瑞索指著一個沒有標誌的箱子。>$B$B拿著。這是我送給你的人民的禮物。是你讓我的氏族免遭滅頂之災。$B$B回去告訴你的首領，火刃廢墟的蘭特瑞索和整個石拳食人魔氏族願意與你們和平相處。$B$B<蘭特瑞索鞠了一躬。>','將火刃的議和禮物交給納格蘭的塔拉的阿雷克隆。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9934 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9934,'zhTW','回到加拉達爾','<蘭特瑞索指著一個沒有標誌的箱子。>$B$B拿著。這是我送給你的人民的禮物。是你讓我的氏族免遭滅頂之災。$B$B回去告訴你的首領，火刃廢墟的蘭特瑞索和整個石拳食人魔氏族願意與你們和平相處。$B$B<蘭特瑞索鞠了一躬。>','將火刃的議和禮物交給加拉達爾的加爾魯什。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9935 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9935,'zhTW','通緝：巫婆吉塞爾達','死亡通緝令：$B$B基爾索羅的巫婆吉塞爾達和她的僕從們犯下了諸多謀殺、綁架、行竊、舉行活祭儀式、與燃燒軍團來往密切等重大罪行。$B$B他們聚集在納格蘭東南部的基爾索羅堡壘，就在納格蘭與泰羅卡森林的交界處附近。$B$B誰能讓吉塞爾達得到正義的制裁，就能從加拉達爾的監護者布羅克處領到一筆豐厚的賞金。','殺死巫婆吉塞爾達以及任意10名基爾索羅成員，完成任務後向加拉達爾的監護者布羅克復命。','','去納格蘭找加拉達爾的監護者布羅克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9936 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9936,'zhTW','通緝：巫婆吉塞爾達','死亡通緝令：$B$B基爾索羅的巫婆吉塞爾達和她的僕從們犯下了諸多謀殺、綁架、行竊、舉行活祭儀式、與燃燒軍團來往密切等重大罪行。$B$B他們聚集在納格蘭東南部的基爾索羅堡壘，就在納格蘭與泰羅卡森林的交界處附近。$B$B誰能讓吉塞爾達得到正義的制裁，就能從塔拉的監護者莫布吉爾處領到一筆豐厚的賞金。','殺死巫婆吉塞爾達以及任意10名基爾索羅成員，完成任務後返回塔拉向監護者莫布吉爾覆命。','','去納格蘭找塔拉的監護者莫布吉爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9937 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9937,'zhTW','通緝：飢餓者杜恩','$N，你已經解決了納格蘭的兩大威脅，是否能再奔赴靈魂平原，為我們清理另一個禍害呢？$B$B飢餓者杜恩長期以來在沃舒古一帶作威作福；誰敢擋他的道就會招來殺身之禍。迄今為止，沒人能除掉這個兇殘的戈隆。召集你的盟友，轉至西南方沃舒古附近的靈魂平原尋找杜恩的下落。殺掉他就可以到我這裡領取一筆豐厚的賞金，我保證數目不會讓你失望的。','殺死飢餓者杜恩，完成任務後向監護者布羅克復命。','','去納格蘭找加拉達爾的監護者布羅克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9938 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9938,'zhTW','通緝：飢餓者杜恩','$N，你已經解決了納格蘭的兩大威脅，是否能再奔赴靈魂平原，為我們清理另一個禍害呢？$B$B飢餓者杜恩長期以來在沃舒古一帶作威作福；誰敢擋他的道就會招來殺身之禍。迄今為止，沒人能除掉這個兇殘的戈隆。召集你的盟友，轉至西邊沃舒古附近的靈魂平原尋找杜恩的下落。殺掉他就可以到我這裡領取一筆豐厚的賞金，我保證數目不會讓你失望的。','殺死飢餓者杜恩，完成任務後向塔拉的監護者莫布吉爾覆命。','','去納格蘭找塔拉的監護者莫布吉爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9939 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9939,'zhTW','通緝：顧問佐爾布','死亡通緝令：$B$B顧問佐爾布曾策劃多起針對加拉達爾的襲擊事件，並夥同其手下的劫掠者和薩滿祭司殺害了無數的獸人。毫無疑問，他是個心狠手辣的危險份子。$B$B佐爾布盤踞在納格蘭北部的嘲顱廢墟。$B$B誰能殺死顧問佐爾布，就能從加拉達爾的監護者布羅克處領到一筆豐厚的賞金。','殺死顧問佐爾布、5個戰槌薩滿祭司和5個戰槌劫掠者，完成任務後向監護者布羅克復命。','','去納格蘭找加拉達爾的監護者布羅克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9940 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9940,'zhTW','通緝：顧問佐爾布','死亡通緝令：$B$B顧問佐爾布曾策劃多起針對塔拉的襲擊事件，並夥同其手下的劫掠者和薩滿祭司殺害了無數的破碎者。毫無疑問，他是個心狠手辣的危險份子。$B$B佐爾布盤踞在納格蘭北部的嘲顱廢墟。$B$B誰能殺死顧問佐爾布，就能從塔拉的監護者莫布吉爾處領到一筆豐厚的賞金。','殺死顧問佐爾布、5個戰槌薩滿祭司和5個戰槌劫掠者，完成任務後向塔拉的監護者莫布吉爾覆命。','','去納格蘭找塔拉的監護者莫布吉爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9941 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9941,'zhTW','追蹤罪犯','阿拉卡的足跡，伴隨著一對淺淺的車轍，走向路的北邊。看來阿拉卡從作戰地點拖走了什麼，或許朝著附近的安身之處去。$B$B雖然壞掉的馬車顯示了打鬥的痕跡，但還是沒有提供什麼迪羅姆的下落。跟隨阿拉卡足跡往北，繼續尋找商人。如果他被活捉，那或許還有機會拯救他。','到壞掉的馬車北方，持續在阿拉卡聚集地搜尋迪羅姆的下落。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9942 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9942,'zhTW','追蹤罪犯','阿拉卡的足跡，伴隨著一對淺淺的車轍，走向路的北邊。看來阿拉卡從作戰地點拖走了什麼，或許朝著附近的安身之處去。$B$B雖然壞掉的馬車顯示了打鬥的痕跡，但還是沒有提供什麼杜葛爾的下落。跟隨阿拉卡足跡往北，繼續尋找商人。如果他被活捉，那或許還有機會拯救他。','到壞掉的馬車北方，繼續在阿拉卡聚集地搜尋杜葛爾的下落。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9943 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9943,'zhTW','回到薩德爾那裡','迪羅姆的貨物不像是被損壞甚至是被開過。他們明顯地對貨物有興趣，但看來他們的犯人更重要一點。阿拉卡攻擊和綁架迪羅姆的意圖仍不清楚，但商人絕對沒有被囚禁在這裡。$B$B沒有未來的線索讓你繼續搜尋，你決定是時候向薩德爾報告你的發現了。','將你的發現回報給奧蕾莉亞要塞的薩德爾。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9944 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9944,'zhTW','失蹤的瑪格漢車隊','蓋亞安祖母一直告誡我們要勤勉自律，承擔起保衛氏族的重任。她要我們為加爾魯什樹立榜樣，讓他明白生命的意義。$B$B我一直負責處理氏族內的各項事務，在蓋亞安祖母病重倒下之後更是忙得不可開交。不知道你是否願意幫幫我？$B$B數日之前，我們派一支車隊轉至先祖之地送喪，可他們至今未歸。你能幫我們尋找車隊的下落嗎？他們是從西邊的道路離開加拉達爾的，你也沿著那條道路走吧，記得繞開哈蘭。','尋找失蹤的瑪格漢車隊。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9945 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9945,'zhTW','戰槌之戰','在轉至先祖之地的途中，我們遭到了戰槌食人魔的伏擊。他們從四面八方湧來，很快就殺死了車隊的衛兵和其它獸人，躺在車上的長者遺體也慘遭褻瀆。$B$B難道這樣的羞辱就能顯示戰槌氏族的強大？就連石拳食人魔都不會犯下如此低劣的惡行。$B$B$N，即使是身為瑪格漢氏族的靈魂師，我也有很多力所不能及的事，所以我需要你的幫助。請你立刻轉至西北方的戰槌山尋找那幫強盜，殺光他們！','納格蘭瑪格漢車隊的長者尤爾雷要求你殺死8個戰槌蠻兵和8個戰槌術士。','','去納格蘭找瑪格漢車隊的長者安格雷茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9946 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9946,'zhTW','掠奪者考瓦爾','$r，你見過食人魔之王嗎？很少有人能從他的魔爪下逃生。我們要對付的正是這樣一位殘暴的君主。$B$B那些野蠻的戰槌食人魔全都聽命於考瓦爾。據說他甚至攆走了原本統治著那些食人魔的戈隆，大搖大擺地登上王座，並解散了為戈隆服務的食人魔氏族，將他們重新揉成了一個新的氏族，是的，戰槌食人魔就此誕生。$B$B去戰槌山洞窟的深處殺掉考瓦爾，將他的徽記帶回來給我。','納格蘭瑪格漢車隊的長者尤爾雷要求你殺死掠奪者考瓦爾，並將考瓦爾的徽記帶回來覆命。','','去納格蘭找瑪格漢車隊的長者安格雷茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9947 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9947,'zhTW','回到瑞克格那裡拉','杜葛爾的貨物不像是被損壞甚至是被開過。他們明顯地對貨物有興趣，但看來他們的犯人更重要一點。阿拉卡攻擊和綁架杜葛爾的意圖仍不清楚，但商人絕對沒有被囚禁在這裡。$B$B沒有未來的線索讓你繼續搜尋，你決定是時候向瑞克格報告你的發現了。','將你的發現回報給裂石堡的瑞克格。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9948 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9948,'zhTW','尋找倖存者','我只知道食人魔喜食新鮮的肉類。也就是說，他們很可能將擄去的瑪格漢戰俘暫時囚禁起來，以保持食物的新鮮。想想就令人作嘔，但是我們可以利用這一點。$B$B轉至戰槌山尋找瑪格漢俘虜。牢籠的鑰匙通常由各個牢籠附近的食人魔保管。$B$B殺掉看守牢籠的食人魔，奪得鑰匙，搭救瑪格漢俘虜。','納格蘭瑪格漢車隊的長者安格雷茲要求你去釋放5個瑪格漢俘虜。','','去納格蘭找瑪格漢車隊的長者安格雷茲。','營救瑪格漢俘虜','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9949 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9949,'zhTW','鳥眼視線','沒有未來的資訊，我們現在處於一個艱難的狀況。我不會放棄尋找並拯救迪羅姆。他被綁架不是意外，$N。$B$B阿拉卡在動鬼腦筋，但他們究竟在計劃什麼呢？$B$B法師哨塔裡的安達爾歐知道他們一些特殊的魔法。如果有正確的工具，他可以湊出一些新資訊給我們。他需要白骨荒野北邊各個阿拉卡城鎮的“眼睛”水晶 - 就在迷霧斯奇司，迷霧瑞斯克，和迷霧辛諾那裡。','將迷霧斯奇司之眼，迷霧辛諾之眼，和迷霧瑞斯克之眼交給奧蕾莉亞要塞的安達爾歐。','','去找泰羅卡森林的安達爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9950 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9950,'zhTW','鳥眼視線','沒有未來的資訊，我們現在處於一個艱難的狀況。我不會放棄尋找並拯救杜葛爾。他被綁架不是意外，$N。$B$B阿拉卡在動鬼腦筋，但他們究竟在計劃什麼呢？$B$B庫爾卡拓克術士知道他們一些特殊的魔法。如果有正確的工具，他可以湊出一些新資訊給我們。他需要白骨荒野北邊各個阿拉卡城鎮的“眼睛”水晶 - 就在迷霧斯奇司，迷霧瑞斯克，和迷霧辛諾那裡。','將迷霧斯奇司之眼，迷霧辛諾之眼，和迷霧瑞斯克之眼交給裂石堡的庫爾卡拓克。','','去找泰羅卡森林的庫加托克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9951 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9951,'zhTW','它在盯著你！','快，藏起來！納弗塔拉那雙眼睛正死死地盯著你……它也盯著我們！$B$B我可不敢冒險去塔頂跟它交談，但你就不同了……你似乎知道該跟它說些什麼。千萬小心，它不喜歡玩笑話，更容忍不了愚蠢的言行。$B$B如果可以的話，說服它下來品茶吧。不過，你要盡一切辦法讓它別那麼盯著我！','殺死納弗塔拉，然後返回泰羅卡森林的塞納里奧樹林向監護者忒洛斯覆命。','','去泰羅卡森林找塞納里奧樹林的監護者忒洛斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9952 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9952,'zhTW','勘察員波莫羅','所以安達爾歐確定迪羅姆被囚禁在迷霧撒拉斯？那裡是我們所知道最大的阿拉卡聚集地。$B$B迷霧撒拉斯在森林的南方遠處，和白骨荒野的東部邊界很近。不幸的是，我沒有太多的瞭解，不過我們有個探險者協會成員駐紮在那裡，他或許能幫你。勘察員波莫羅的營地就在迷霧撒拉斯西南方土地的邊緣。和他談談再來對付阿拉卡。','找到並和勘察員波莫羅談談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9953 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9953,'zhTW','監視者諾達克','所以庫爾卡拓克確定杜葛爾被囚禁在迷霧撒拉斯？那裡是我們所知道最大的阿拉卡聚集地。$B$B迷霧撒拉斯在森林的南方遠處，和白骨荒野的東部邊界很近。不幸的是，我對那裡並不太瞭解，不過我們有個斥候駐紮在那裡，他或許能幫你。監視者諾達克的營地就在迷霧撒拉斯西南方土地的邊緣。和他談談再來對付阿拉卡。','找到並和監視者諾達克談談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9954 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9954,'zhTW','考爾奇的贖金','<阿雷克隆遞給你一張髒兮兮的信紙。>$B$B我剛收到這封信。是統治著納格蘭西北疆域的戰槌食人魔氏族寄來的。信上說考爾奇落到了他們手上，如果我們不滿足他們的要求，他們就要吃掉考爾奇。雖說考爾奇是個正牌的蠢材，可他畢竟還是我的孩子。$N，你願意搭救他嗎？$B$B他應該被關押在戰槌山的某個牢籠中，你得去那邊找他。','阿雷克隆要你轉至戰槌山尋找考爾奇。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9955 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9955,'zhTW','掠奪者考瓦爾','$N，那些食人魔稱他為掠奪者考瓦爾。他趕走了統治戰槌食人魔的戈隆，自己做了氏族之王。你最好相信我的話，他是個可怕的對手！$B$B我聽廚師說考瓦爾居住在那邊的大洞穴中……無論如何，取來鑰匙，把我從這鬼地方救出去！如果我們能逃得此劫，我父親必定會好好賞賜你的！救出我之後，就去找他吧。','奪得考瓦爾的鑰匙，將考爾奇從牢籠中釋放出來，完成任務後返回塔拉向阿雷克隆覆命。','','去納格蘭找塔拉的阿雷克隆。','營救考爾奇','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9956 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9956,'zhTW','不幸的商隊','我是商隊的一名成員，我們當時奉命將一批貨物運往贊加沼澤的奧雷柏爾營地。然而，就在車隊行進到沼澤邊界附近時，一隊戰槌食人魔突然攔住了我們的去路。他們殘忍地殺害了商隊的其它成員，將我和所有的貨物一併劫回了營地。$B$B謝天謝地，他們忘了鎖住關押我的牢籠，於是我趁他們睡著時逃了出來。$B$B雖然夥伴們都不幸罹難，可是那些被偷走的貨物還是能用的，請你一定要幫我們回收。戰槌山就在納格蘭西北部。','收集10個塔拉補給箱，把它們交給塔拉的女獵手琪瑪。','','去納格蘭找塔拉的女獵手琪瑪。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9957 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9957,'zhTW','塞納里奧樹林出事了？','泰羅卡森林的塞納里奧樹林中居住著一群德魯伊，我們有好些日子沒收到他們的訊息了。$B$B$N，去那兒看看是不是出了什麼狀況。轉至塞納里奧樹林的最快路線是沿著道路往南走，再轉向撒塔斯城東面的岔路。','與泰羅卡森林地區的塞納里奧樹林中的某位德魯伊談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9958 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9958,'zhTW','偵察防禦','我在這裡的時候和阿拉卡有一些互動，他們沒有一個人是友善的。他們看起來非常具領域性，但我想我們也是一樣，對嗎？就連先祖們都沒有任何和鳥人來往的紀錄。$B$B阿拉卡擁有一種原始的魔法，那是艾澤拉斯上的我們所未知的力量，被用來編織迷霧撒拉斯的防禦網。在和他們對抗前，我們最好先偵察他們的防禦才知道對手的斤兩。','前進迷霧撒拉斯觀察城鎮的防禦。','','去找泰羅卡森林的勘測員巴莫拉爾。','Investigate Veil Shalas Defenses','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9959 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9959,'zhTW','偵察防禦','我在這裡的時候和阿拉卡有一些互動，他們沒有一個人是友善的。他們看起來非常具領域性，但我想我們也是一樣，對嗎？就連先祖們都沒有任何和鳥人來往的紀錄。$B$B阿拉卡擁有一種原始的魔法，那是我們的先知所未知的力量，被用來編織迷霧撒拉斯的防禦網。在和他們對抗前，我們最好先偵察他們的防禦才知道對手的斤兩。','前進迷霧撒拉斯瞭解防禦營地的魔法。','','去泰羅卡森林找鴉羽山的斥候努達克。','Investigate Veil Shalas Defenses','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9960 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9960,'zhTW','塞納里奧樹林出事了？','$c，你好。塞納里奧樹林中居住著一群德魯伊，不過我們有好些日子沒收到他們的訊息了。$B$B去那兒看看是不是出了什麼狀況。塞納里奧樹林就在這片森林的西北方。','與泰羅卡森林地區的塞納里奧樹林中的某位德魯伊談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9961 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9961,'zhTW','塞納里奧樹林出事了？','$C，有件要緊事要你跑一趟。塞納里奧樹林中居住著一群德魯伊，不過我們有好些日子沒收到他們的訊息了。通常每隔幾天我們就能收到他們的來信的。$B$B去那兒看看是不是出了什麼狀況。塞納里奧樹林就在這片森林的西北方。','與泰羅卡森林地區的塞納里奧樹林中的某位德魯伊談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9962 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9962,'zhTW','鮮血競技場：斷蹄','那麼你已經做好迎接首場較量的準備了？等你準備就緒，我就宣佈比賽開始。你只需進入鮮血競技場，等待對手登場。$B$B你的對手名叫斷蹄，是一頭兇殘的裂蹄牛。$B$B祝你好運！希望你帶了朋友一起來。$B$B記住，你和你的對手中有任何一方倒地身亡，戰鬥即宣告結束。','擊敗斷蹄，獲勝之後找巨魔僕從伍迪領取獎勵。','擊敗斷蹄','去找納格蘭的巨魔僕從伍迪。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9963 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9963,'zhTW','向源頭尋找幫助','你遇到的結界的確是強大的魔法。阿拉卡使用的技巧是遠遠超出我們所能理解的，我們只能希望藉他們的幫忙找到一個抗衡物。$B$B我知道你在想什麼。敵人怎麼會幫我們征服他們的防禦？答案是他們當然不會。你有聽過瘋狂老阿拉卡聖人，可可瑞克的故事嗎？他們說他就躲在白骨荒野西邊的迷霧里斯克裡，等待失落的世代重返。','找到迷霧里斯克裡的可可瑞克並和他談談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9964 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9964,'zhTW','向源頭尋找幫助','你遇到的結界的確是強大的魔法。阿拉卡使用的技巧是遠遠超出我們所能理解的，我們只能希望藉他們的幫忙找到一個抗衡物。$B$B我知道你在想什麼。敵人怎麼會幫我們征服他們的防禦？答案是他們當然不會。你有聽過瘋狂老阿拉卡聖人，可可瑞克的故事嗎？他們說他就躲在白骨荒野西邊的迷霧里斯克裡，等待失落的世代重返。','找到迷霧里斯克裡的可可瑞克並和他談談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9965 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9965,'zhTW','良心的約定','現在，我很有誠意地建議你與我做一筆小小的交易：只要你願意展示出為我解決一個小小問題的好意來，我就願意幫助你營救你的同志。$B$B巨魔是我們一族長久以來不共戴天的仇敵，最近，他們又從納格蘭的大草原遷徙回了森林中。$B$B遷徙回來的巨魔中有一個很特別，他叫穆格苟克，很有冒險精神，可惜不怎麼聰明。他和他的朋友一直血環廢墟那邊，給我們製造著麻煩，想要激怒我們。','把穆格苟克的頭顱交給迷霧里斯克的可可瑞克。','','去泰羅卡森林找雷希鴉巢的庫庫雷克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9966 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9966,'zhTW','良心的約定','現在，我很有誠意地建議你與我做一筆小小的交易：只要你願意展示出為我解決一個小小問題的好意來，我就願意幫助你營救你的同志。$B$B巨魔是我們一族長久以來不共戴天的仇敵，最近，他們又從納格蘭的大草原遷徙回了森林中。$B$B遷徙回來的巨魔中有一個很特別，他叫穆格苟克，很有冒險精神，可惜不怎麼聰明。他和他的朋友一直血環廢墟那邊，給我們製造著麻煩，想要激怒我們。','把穆格苟克的頭顱交給迷霧里斯克的可可瑞克。','','去泰羅卡森林找雷希鴉巢的庫庫雷克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9967 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9967,'zhTW','鮮血競技場：藍色兄弟','接下來，你要同時挑戰兩名對手——準確地說是孿生兄弟。他們自稱為“藍色兄弟”。$B$B$N，現在選擇退出還來得及，我能理解。$B$B如果你想要試試的話，就進入鮮血競技場，等待暗血雙胞胎登場吧。$B$B擊殺對手便可獲勝！','擊敗自稱為藍色兄弟的暗血雙胞胎，獲勝之後找巨魔僕從伍迪領取獎勵。','擊敗藍色兄弟','去找納格蘭的巨魔僕從伍迪。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9968 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9968,'zhTW','奇怪的能量','塞納里奧樹林中的巨蛾不知何故發生了鉅變。 $B$B這兒曾棲息著許多種生物，現在卻只剩巨蛾了。它們本是性情溫順的小昆蟲，如今卻變得極具攻擊性。$B$B我要將邪惡巨蛾與普通的巨蛾進行比較。你能替我收集這兩類蛾子的標本嗎？那些未受影響的蛾子分佈在南邊和北邊。$B$B我想這必定與德魯伊被殺一事有關。','收集4份巨蛾樣本和4份邪惡巨蛾樣本，然後向泰羅卡森林中塞納里奧樹林外的縛地者塔弗格倫覆命。','','去泰羅卡森林找塞納里奧樹林的縛地者塔弗格倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9969 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9969,'zhTW','最後的試劑','我能製造出一種可以抑制住沙拉斯鴉巢那裡結界法術的物品。但我得提醒你，$N，這個法術僅僅是為了讓你救出被關押在那裡的朋友而用的。我絕對不會允許你任意傷害我的同胞。$B$B用於製造這個護身符的材料我這裡基本都有了，但仍有一些其它材料我需要你幫我收集回來。我需要一些扭曲獵人精華，還有一把泰羅卡灌木，這些都可以在鴉巢附近的地方找到。','將5份扭曲獵者精華和30顆泰羅卡灌木交給迷霧里斯克的可可瑞克。','','去泰羅卡森林找雷希鴉巢的庫庫雷克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9970 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9970,'zhTW','鮮血競技場：裂石之王洛卡達爾','$N，這將是一場苦戰。你有沒有叫上可靠的朋友來幫忙？食人魔從刀鋒山找來了一位名叫洛卡達爾的巨人！相信我，你必須跟你的朋友們一起戰鬥。這傢伙看起來就很猛！他跟岩石一樣堅韌，事實上他就是個極能打的石巨人！$B$B如果你想要跟他較量一番，就進入鮮血競技場，等待他登場吧。','擊敗裂石之王洛卡達爾，獲勝之後找巨魔僕從伍迪領取獎勵。','擊敗裂石之王洛卡達爾','去找納格蘭的巨魔僕從伍迪。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9971 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9971,'zhTW','樹林中的線索','不知道是誰殺光了這兒的德魯伊。我一直在此地以南的白骨荒野進行調查研究，因此逃得一劫。$B$B請你一定要伸出援手，幫我揭開這場慘劇的真相。如果可以的話，進入塞納里奧樹林尋找線索吧。我記得曾在樹林中看見一具破碎者的屍體，他旁邊還有個奇怪的物體。這條線索可能對我們有所幫助。$B$B別擔心忒洛斯，他雖然受到驚嚇失了心智，可我相信他不會傷害你。','調查破碎者的屍體旁的奇怪物體，看看究竟是什麼在滋擾塞納里奧樹林，然後向塞納里奧樹林外的縛地者塔弗格倫覆命。','','去泰羅卡森林找塞納里奧樹林的縛地者塔弗格倫。','檢查奇怪的物體','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9972 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9972,'zhTW','鮮血競技場：瑟克拉加斯','孩子，你差點沒把那幫食人魔活活氣死！這次他們耍了個小花招，讓虛空領主代為出場。看來他們還不想派出冠軍選手跟你一較高下。那個蹩腳的穆戈爾在那邊對你嚷嚷呢，聽見了嗎？這場比賽賭注很高呢！$B$B進入鮮血競技場，迅速解決你的對手吧！','擊敗瑟克拉加斯，獲勝之後找巨魔僕從伍迪領取獎勵。','擊敗瑟克拉加斯','去找納格蘭的巨魔僕從伍迪。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9973 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9973,'zhTW','鮮血競技場：戰槌勇士','他們不得不派出這位來自刀鋒山格鬥場的冠軍選手。這名選手經過嚴酷的訓練，每次都有三名山嶺巨人同時跟他較量。$B$B如果你贏了這場比賽，你就是新的冠軍了。孩子，你覺得獲勝的希望有多大？願意試試嗎？只要你接受挑戰，我就把所有的賭注都下在你身上。$B$B進入鮮血競技場，戰勝對手！','擊敗戰槌勇士，獲勝之後找巨魔僕從伍迪領取獎勵。','擊敗戰槌勇士','去找納格蘭的巨魔僕從伍迪。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9974 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9974,'zhTW','最後的試劑','我能製造出一種可以抑制住沙拉斯鴉巢那裡結界法術的物品。但我得提醒你，$N，這個法術僅僅是為了讓你救出被關押在那裡的朋友而用的。我絕對不會允許你任意傷害我的同胞。$B$B用於製造這個護身符的材料我這裡基本都有了，但仍有一些其它材料我需要你幫我收集回來。我需要一些扭曲獵人精華，還有一把泰羅卡灌木，這些都可以在鴉巢附近的地方找到。','將5份扭曲獵者精華和30顆泰羅卡灌木交給迷霧里斯克的可可瑞克。','','去泰羅卡森林找雷希鴉巢的庫庫雷克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9975 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9975,'zhTW','原始魔法','我已經將法術灌注到了這個護符中。而你所要做的，就是找到沙拉斯鴉巢邊界上的守護圖騰，然後釋放其中的力量。這樣一來，結界就會被撕裂。$B$B<你發現這個護符上所雕刻著的人物形象並不是非常像一個鴉人。>$B$B啊，我們的族人並非在最初就是這個樣子的。我們曾經也曾是擁有華麗外表的生物，但我們……我們一再聽信讒言，做出了錯誤的抉擇。最終，我們未能完成那個神聖的使命，也使我們失去了美麗的外表，強大的力量，甚至是……我們的生命。不要重複我們所犯過的錯誤，$N。','在通向沙拉斯鴉巢的道路周圍的圖騰附近使用庫庫雷克的護符，然後與勘測員巴莫拉爾談一談。','','去找泰羅卡森林的勘測員巴莫拉爾。','使用庫庫雷克的護符','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9976 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9976,'zhTW','原始魔法','我已經將法術灌注到了這個護符中。而你所要做的，就是找到沙拉斯鴉巢邊界上的守護圖騰，然後釋放其中的力量。這樣一來，結界就會被撕裂。$B$B<你發現這個護符上所雕刻著的人物形象並不是非常像一個鴉人。>$B$B啊，我們的族人並非在最初就是這個樣子的。我們曾經也曾是擁有華麗外表的生物，但我們……我們一再聽信讒言，做出了錯誤的抉擇。最終，我們未能完成那個神聖的使命，也使我們失去了美麗的外表，強大的力量，甚至是……我們的生命。不要重複我們所犯過的錯誤，$N。','在通向沙拉斯鴉巢的道路周圍的圖騰附近使用庫庫雷克的護符，然後與斥候努達克談一談。','','去泰羅卡森林找鴉羽山的斥候努達克。','使用庫庫雷克的護符','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9977 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9977,'zhTW','鮮血競技場：終極挑戰','<古爾戈索克貪婪地數著大堆的金幣。>$B$B孩子，你真是個招財寶。如果你能擊敗穆戈爾，我發誓我會好好酬謝你的。你在鮮血競技場灑下的熱血一定會得到回報！$B$B進入鮮血競技場，讓那些食人魔知道你才是真正的強者！','擊敗戰槌英雄穆戈爾，獲勝之後找巨魔僕從伍迪領取獎勵。','擊敗戰槌英雄穆戈爾','去找納格蘭的巨魔僕從伍迪。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9978 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9978,'zhTW','不擇手段','此事依然毫無頭緒，但是我知道如何獲得更多的線索。$B$B埃博爾是位訊息靈通的破碎者商人。如果你能讓他開口說話，我們必定能得到些有趣的資訊。$B$B他一般在圖雷姆和撒塔斯城之間往返。當心些，他隨身帶著一名護衛呢。','在泰羅卡森林中，圖雷姆和撒塔斯城之間的大路上找到並說服埃博爾將他所知道的一切都告訴你。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9979 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9979,'zhTW','星界商人拉斯萊','我奉命為撒塔斯城中的一位虛靈運送貨物。$B$B我最後一次見他是在貧民窟的天涯旅店外。他名叫星界商人拉斯萊，我就知道這麼多！$B$B想知道更多的話，你直接找他問去吧！','與撒塔斯城貧民窟天涯旅店附近的星界商人拉斯萊談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9980 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9980,'zhTW','拯救迪羅姆！','立刻進入沙拉斯鴉巢，$N！現在時間非常寶貴。如果阿拉卡發現你已經破除了他們的防禦體系，他們一定會換個地方關押迪羅姆的，甚至把他殺掉。$B$B如果可能的話，帶上一兩個朋友幫助你，闖入那裡面看起來確實很困難。那些鳥人對他們的囚犯看守得十分嚴密，絕不會允許他們輕易逃脫。如果你找到了迪羅姆，立刻消滅他身邊的守衛，帶他回到奧蕾莉亞要塞，並通知薩德爾。','前往迷霧撒拉斯，殺了盧安卡，再釋放迪羅姆。完成任務後再向奧蕾莉亞要塞的戴娜·甘乃迪女士回報。','','去泰羅卡森林找奧蕾莉亞要塞的德娜·肯尼迪。','','Free Deirom','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9981 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9981,'zhTW','拯救杜葛爾！','立刻進入沙拉斯鴉巢，$N！現在時間非常寶貴。如果阿拉卡發現你已經破除了他們的防禦體系，他們一定會換個地方關押迪羅姆的，甚至把他殺掉。$B$B如果可能的話，帶上一兩個朋友幫助你，闖入那裡面看起來確實很困難。那些鳥人對他們的囚犯看守得十分嚴密，絕不會允許他們輕易逃脫。如果你找到了迪羅姆，立刻消滅他身邊的守衛，帶他回到裂石堡，並通知羅卡格。','前往迷霧撒拉斯，殺了盧安卡，再釋放杜葛爾。完成任務後再向裂石堡的羅卡格回報。','','去找泰羅卡森林的羅卡格。','','Free Dugar','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9982 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9982,'zhTW','他叫奧圖裡斯……','上週，有位暗夜精靈乘坐著虛空幼龍來到鎮上。他說自己名叫奧圖裡斯，然後向城民們詢問了一些關於納格蘭的問題。$B$B最誇張的是，他宣稱還自己的職責是追殺燃燒軍團。你聽聽這癲狂的言語，你能想象嗎？居然還有人願意獵殺惡魔？$B$B奧圖裡斯臨走之前讓我們告訴那些想要成為英雄的人，說什麼如果人願意做點有意義的事，就儘管去找他。他會一直在納格蘭西部恭候諸位的大駕。','如果你想與燃燒軍團作戰，就到納格蘭西部去找到受難者奧圖裡斯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9983 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9983,'zhTW','他叫奧圖裡斯……','上週，有位暗夜精靈乘坐著虛空幼龍來到鎮上。他說自己名叫奧圖裡斯，然後向城民們詢問了一些關於納格蘭的問題。$B$B最誇張的是，他宣稱還自己的職責是追殺燃燒軍團。你聽聽這癲狂的言語，你能想象嗎？居然還有人願意獵殺惡魔？$B$B奧圖裡斯臨走之前讓我們告訴那些想要成為英雄的人，說什麼如果人願意做點有意義的事，就儘管去找他。他會一直在納格蘭西部恭候諸位的大駕。','如果你想與燃燒軍團作戰，就到納格蘭西部去找到受難者奧圖裡斯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9984 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9984,'zhTW','隱秘之城','儘管你無法辨認出卷軸上的奇怪筆跡，但還是可以從公文最後華麗的印章中看出，這份卷軸出自一位頗有地位的鴉人之手。盧埃加或許就是那個抓捕和監禁迪魯姆的鴉人，還負責審問他。不過，他看上去也是接到了另一個地位更高的鴉人之命令才負責這件事的。$B$B你突然想起山德曾說過，安達爾對鴉人研究頗多，或許他能讀懂卷軸中的內容。','將盧埃加的命令交給泰羅卡森林中奧蕾莉亞要塞的安達爾。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9985 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9985,'zhTW','隱秘之城','儘管你無法辨認出卷軸上的奇怪筆跡，但還是可以從公文最後華麗的印章中看出，這份卷軸出自一位頗有地位的鴉人之手。盧埃加或許就是那個抓捕和監禁杜加爾的鴉人，還負責審問他。不過，他看上去也是接到了另一個地位更高的鴉人之命令才負責這件事的。$B$B你突然想起羅卡格曾說過，庫加托克對鴉人研究頗多，或許他能讀懂卷軸中的內容。','將盧埃加的命令交給泰羅卡森林中裂石堡的庫加托克。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9986 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9986,'zhTW','教訓鴉人','我們必須讓那些該死的鴉人知道，任何攻擊我們的人都要付出慘重的代價。否則，我們在泰羅卡森林內的所有商人、信使和士兵將會面臨他們的威脅。$B$B我的斥候已經確認了鴉人在這個地區各個主要定居點的首領。去吧，找到里斯克鴉巢的阿什卡茲、西諾鴉巢的埃伊特和基斯鴉巢的烏達克，將他們全部定點清除。','殺死里斯克鴉巢的阿什卡茲，西諾鴉巢的埃伊特和基斯鴉巢的烏達克，然後返回奧蕾莉亞要塞向山德覆命。','','去泰羅卡森林找奧蕾莉亞要塞的山德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9987 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9987,'zhTW','教訓鴉人','我們必須讓那些該死的鴉人知道，任何攻擊我們的人都要付出慘重的代價。否則，我們在泰羅卡森林內的所有商人、信使和士兵將會面臨他們的威脅。$B$B我的斥候已經確認了鴉人在這個地區各個主要定居點的首領。去吧，找到里斯克鴉巢的阿什卡茲、西諾鴉巢的埃伊特和基斯鴉巢的烏達克，將他們全部定點清除。','殺死里斯克鴉巢的阿什卡茲，西諾鴉巢的埃伊特和基斯鴉巢的烏達克，然後返回裂石堡向羅卡格覆命。','','去泰羅卡森林找裂石堡的羅卡格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9988 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9988,'zhTW','公子哥的好朋友','千萬不要被山德和他那些同夥給騙了。雖然這群傢伙看起來像是一群令人生畏的優秀士兵，其實在那華麗的外表下，他們只不過是一堆徹頭徹尾的廢物，一群公子哥兒而已！$B$B當然，這一點他們是絕對不會讓別人知道的。他們特別喜歡奢侈的氈製品和毛皮，還有各類最華美的羽毛。$B$B當然，當然，最令人嚮往的羽毛要數鴉人身上的那些，但是我的存貨越來越少了。如果你能幫我去找些羽毛回來，我會很樂意付一筆可觀的工\\r\\n錢給你。','給奧蕾莉亞要塞的洛瑟蕾絲帶回30片鴉人的羽毛。','','去泰羅卡森林找奧蕾莉亞要塞的洛瑟蕾絲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9989 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9989,'zhTW','異類的靈魂','記得當我第一次來到外域並傾聽這裡各種靈魂的聲音時，我對自己聽到的東西感到非常詫異。同時，我也留意到有些靈魂的聲音我竟然無法聆聽清楚。$B$B我嘗試過各種辦法，仍然接觸不到這些鴉人的靈魂。他們的魔法與我們的完全不同，但我還不能確定接觸他們的靈魂是否超出了我的能力範圍。$B$B總之，幫我找一些鴉人的羽毛回來吧，或許依靠這些他們身上的東西，我就能接觸到他們的靈魂。','將30片鴉人的羽毛交給裂石堡的瑪魯卡茲。','','去泰羅卡森林找裂石堡的瑪魯卡茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9990 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9990,'zhTW','調查圖雷姆','我想起來了。大約一個月前，我確實將幾盒奇異的工程零件賣給了埃博爾。我不知道它們有什麼用處，只知道這批貨物是運往圖雷姆的。$B$B或許那裡還留有一兩隻盒子？','找到密封的盒子，將其交給塞納里奧樹林外的縛地者塔弗格倫。','','去泰羅卡森林找塞納里奧樹林的縛地者塔弗格倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9991 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9991,'zhTW','偵查大地','你若想成為我的耳目，就必須加倍勤勉些才行。首先，馬上去執行一次高空偵察任務吧。奈瑟蘭達姆斯將載著你飛越燃燒軍團的幾處鑄魔營地，你必須記下你所看到的一切，哪怕是最微不足道的細節也不能放過。你認為無關緊要的資訊，其實有可能派上大用場。$B$B我要你特別留意營地中的建築物佈局和防禦力量的部署。$B$B$N，奈瑟蘭達姆斯正等你呢，別害怕，他會確保你的安全。','好好享受這趟旅程吧。調查完畢之後跟奧圖裡斯談一談。','偵查鑄魔營地','去納格蘭找受難者奧圖裡斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9992 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9992,'zhTW','奧雷巴種子','你不覺得這片森林裡的樹很漂亮嗎？我經常會希望能在艾澤拉斯世界也看到這麼美麗的樹。$B$B可是我很猶豫該不該將種子帶回去。這些樹種跟普通的種子不同，很難運輸，帶上它們將會給旅程增加許多不便。這些包藏在堅硬的松果內的種子一旦成熟，就會從樹枝上掉下來。$B$B如果你在旅行途中見到掉落下來的松果，能幫我把裡面的種子帶一些回來嗎？','收集30顆奧雷巴種子，把它們交給奧蕾莉亞要塞的洛瑟蕾絲。','','去泰羅卡森林找奧蕾莉亞要塞的洛瑟蕾絲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9993 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9993,'zhTW','奧雷巴油','森林裡奧雷巴樹上結的那些油乎乎的種子非常有用。我一直想要收集這類種子，榨出它們的油，然後再想想能用它來做什麼。$B$B你看，外面的森林中到處都是奧雷巴樹，許多種子都被浪費掉了。總之，我不管最後榨出來的是食用油也好，燈油也好，武器油也好，我希望不要浪費那些種子！$B$B將你從奧雷巴果中收集到的種子帶回來給我，森林裡到處都是這些玩意。','將30顆奧雷巴種子交給裂石堡的拉克妮亞。','','去泰羅卡森林找裂石堡的拉克妮亞。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9994 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9994,'zhTW','這些東西是什麼？','我不知道你怎麼想，但是我對這些東西壓根沒有了解。我只知道它們看上去相當危險！$B$B$N，我想你應該將這箱零件交給東南方奧蕾莉亞要塞的傑奈·星語。她或許知道這些東西的來歷。','將這一箱零件交給泰羅卡森林奧蕾莉亞要塞的傑奈·星語。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9995 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9995,'zhTW','這些東西是什麼？','我不知道你怎麼想，但是我對這些東西壓根沒有了解。我只知道它們看上去相當危險！$B$B$N，我想你應該將這箱零件交給東南方裂石堡的圖基。他或許知道這些東西的來歷。','將這一箱零件交給泰羅卡森林裂石堡的圖基。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9996 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9996,'zhTW','攻擊火翼崗哨','火翼崗哨的血精靈為凱爾薩斯和伊利丹效力。從你說的情況來看，血精靈顯然在利用圖雷姆的破碎者偷運零件，企圖製造某種殺傷力極強的武器。$B$B無論他們在打什麼鬼主意，現在我們能做的就是削減這幫傢伙的數量。$B$B除掉火翼血精靈！轉至北邊的火翼崗哨，給他們點顏色瞧瞧。','殺死10個火翼防禦者、10個火翼血警衛和10個火翼術士，然後向泰羅卡森林奧蕾莉亞崗哨的米利迪安中尉覆命。','','去泰羅卡森林找奧蕾莉亞崗哨的米利迪安中尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9997 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9997,'zhTW','攻擊火翼崗哨','火翼崗哨的血精靈為凱爾薩斯和伊利丹效力。從你說的情況來看，血精靈顯然在利用圖雷姆的破碎者偷運零件，企圖製造某種殺傷力極強的武器。$B$B無論他們在打什麼鬼主意，現在我們能做的就是削減這幫傢伙的數量。$B$B除掉火翼血精靈！轉至東北方的火翼崗哨，給他們點顏色瞧瞧。','殺死10個火翼防禦者、10個火翼血警衛和10個火翼術士，然後向泰羅卡森林裂石堡的卡烏尼中士覆命。','','去找泰羅卡森林裂石營地的卡烏尼中士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9998 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9998,'zhTW','野蠻的鄰居','最近佔據了東邊廢墟的那些邪獸人給山德製造了成堆的困擾和麻煩。他們一進入廢墟，就迫不及待地開始建造堡壘並整修了房屋。$B$B現在，他們日夜不停地趕工，似乎在謀劃著什麼。我已經派了一名非常值得信賴的斥候去監視他們，不過，我們不能再耽誤時間了。你要立刻轉至噬骨廢墟，消滅他們的苦工，然後去北邊的奧蕾莉亞崗哨找到塞洛莉婭·影衣，她會給你指示後續的任務。','殺死12名扭曲的苦工，然後向奧蕾莉亞崗哨的塞洛莉婭·影衣報告。','','去泰羅卡森林找奧蕾莉亞崗哨的塞洛莉婭·影衣。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9999 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9999,'zhTW','爭取時間','只要那些傳送裝置仍然完好無損，燃燒軍團就能源源不斷地向各處鑄魔營地輸送兵力。這樣一來，我們是不可能徹底摧毀那些鑄魔營地的。必須設法破壞他們的傳送裝置。$B$B現在我馬上開始制定一個完美的攻擊計劃。但我需要時間，如果你能殺掉一些工程師和修理工，必定會令營地陷入混亂，這樣我就有了寶貴的時間。$B$B$N，儘可能避開那些監工，他們很難對付。','納格蘭西部的受難者奧圖裡斯要求你除掉2個惡魔衛士軍團士兵、3個莫爾葛工程師和8個甘爾葛修理工。','','去找納格蘭的受難者奧圖裡斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10000 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10000,'zhTW','不受歡迎者','我們在索爾瑪的軍隊認為地獄火堡壘附近區域的邪獸人已經全部清除掉了，但是最近，在東邊廢墟一帶，我們又發現了一些邪獸人。$B$B現在，我們必須阻止他們在那裡建立新的據點。羅卡格已經派追蹤者凱德去監視他們的行動了，但我們還得采取進一步的措施來阻止他們繼續深入廢墟。$B$B你先去廢墟里清理一些他們的苦工，然後去北邊的樹林找裡找到凱德。他會告訴你接下去做什麼。','殺死12名扭曲的苦工，然後向追蹤者凱德報告。','','去找泰羅卡森林裂石營地的追蹤者凱德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10001 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10001,'zhTW','主規劃師','所有鑄魔營地的都是由一名莫爾葛主規劃師進行設計的。這個人將會負責規劃鑄魔營地中各個建築物型別、位置和數量。而且，這些資訊將會被整理成一份藍圖，由該營地的主規劃師隨身攜帶，妥善保管。$B$B我們現在需要的就是這份主規劃師的藍圖。一旦這東西到手，我們就可以去找我的一位老朋友，並說服他幫助我們。$B$B總之你，你現在先去殺掉莫爾葛主規劃師，並奪得藍圖。他現在應該就在鑄魔營地中。','納格蘭西部的受難者奧圖裡斯要求你取回主規劃師的藍圖。','','去找納格蘭的受難者奧圖裡斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10002 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10002,'zhTW','莉塞蕾·火紋','在過去的幾天裡，我看到過一個女血精靈出入邪獸人的要塞，與邪獸人的首領進行會談。從她的肢體語言中，我可以看出她是在釋出命令。但這到底是怎麼回事？她是在傳達誰的命令？$B$B我對此充滿好奇，所以我在她離開邪獸人營地時跟蹤她，結果發現她往北邊的火翼崗哨去了。我在火翼崗哨邊界停止了跟蹤。$B$B在她下一次離開邪獸人營地前殺掉她。','找到莉塞蕾·火紋並殺掉她，然後向塞洛莉婭·影衣覆命。','','去泰羅卡森林找奧蕾莉亞崗哨的塞洛莉婭·影衣。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10003 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10003,'zhTW','莉塞蕾·火紋','在過去的幾天裡，我看到過一個女血精靈出入邪獸人的要塞，與邪獸人的首領進行會談。從她的肢體語言中，我可以看出她是在釋出命令。但這到底是怎麼回事？她是在傳達誰的命令？$B$B我對此充滿好奇，所以我在她離開邪獸人營地時跟蹤她，結果發現她往北邊的火翼崗哨去了。我在火翼崗哨邊界停止了跟蹤。$B$B在她下一次離開邪獸人營地前殺掉她。','找到莉塞蕾·火紋並殺掉她，然後向追蹤者凱德覆命。','','去找泰羅卡森林裂石營地的追蹤者凱德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10004 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10004,'zhTW','耐心與理解','帶上這份藍圖轉至泰羅卡森林的撒塔斯城。在撒塔斯城貧民窟中尋找一位名叫薩薩拉比姆的莫爾葛。他最近經常會在酒吧買醉，想要依靠飲酒來平復心中的哀痛。$B$B你得試著說服他伸出援手，首先耐心地說明你的來意，如果這法子不奏效，就得用用你的拳頭了。','納格蘭西部的受難者奧圖裡斯要你將主規劃師的藍圖交給撒塔斯城中的薩薩拉比姆，並說服他幫助你。','說服薩薩拉比姆','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10005 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10005,'zhTW','告知縛地者塔弗格倫','$N，慶祝完我們的勝利後，我想你應該返回塞納里奧樹林，跟縛地者塔弗格倫談談。$B$B他一定很想知道那場慘劇的真相。','與泰羅卡森林塞納里奧樹林外的縛地者塔弗格倫談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10006 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10006,'zhTW','告知縛地者塔弗格倫','$N，慶祝完我們的勝利後，我想你應該返回塞納里奧樹林，跟縛地者塔弗格倫談談。$B$B他一定很想知道那場慘劇的真相。','與泰羅卡森林塞納里奧樹林外的縛地者塔弗格倫談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10007 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10007,'zhTW','削弱邪獸人','你得了解山德和波爾泰姆的心理，他們連群鳥人都不能忍，就更不會允許如此強大的敵人在我們的大門口建立起據點。所以，得他們讓派些援軍過來。要攻擊邪獸人營地的駐軍，僅僅依靠我們兩人的力量是不夠的。$B$B我們必須抑制住來自邪獸人的威脅。我決定了，你去騷擾他們，我會想辦法阻止他們的援兵。','殺死10名噬骨蹂躪者和6名噬骨碎脊者，然後向塞洛莉婭·影衣覆命。','','去泰羅卡森林找奧蕾莉亞崗哨的塞洛莉婭·影衣。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10008 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10008,'zhTW','泰羅卡的事情，在泰羅卡解決','如果立刻把邪獸人沒有被完全消滅乾淨通知索爾瑪，那邊一定會增派更多的援兵過來碾平一切。但是，說實話，我不太希望情況演變成這樣，所以我們一點風聲都不要透露出去，知道嗎？$B$B如果我們剿滅這些邪獸人的速度足夠快，那就不會引起裂石堡以外任何人的關注。所以，現在就開始行動吧。$B$B你現在立刻拿起武器，用你能想到的一切辦法去襲擊他們——只要能將邪獸人消滅乾淨，怎樣都好。','追蹤者凱德要你殺死10名噬骨蹂躪者和6名噬骨碎脊者。','','去找泰羅卡森林裂石營地的追蹤者凱德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10009 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10009,'zhTW','大打出手','<薩薩拉比姆大笑起來。>$B$B這是都是我薩薩拉比姆設計的。$B$B<薩薩拉比姆指著藍圖上繪製的建築物。>$B$B瞧這些塔。惡魔獵手雙眼不能視物，對吧？可憐的奧圖裡斯。如果他能看見鑄魔營地的構架，恐怕會失聲痛哭。$B$B只要你肯幫薩薩拉比姆，薩薩拉比姆就幫你。$B$B<薩薩拉比姆遞給你一本賬本。>$B$B這些傢伙欠薩薩拉比姆的錢。很多很多錢。為薩薩拉比姆討回債務，他們肯定不願意乖乖交出金幣，你得使用武力，好在你是個強者。連薩薩拉比姆都不是你的對手呢！','撒塔斯城的薩薩拉比姆要你取回拉里克的債款、庫什庫什的債款和弗魯恩的債款。','','去泰羅卡森林找撒塔斯城的薩薩拉比姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10010 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10010,'zhTW','就這麼簡單？','<薩薩拉比姆指著藍圖。>$B$B瞧見這些邪能火炮了嗎？$B$B<薩薩拉比姆在邪能火炮的影象上畫了個調轉方向的箭頭。>$B$B調轉邪能火炮的炮頭，用它們摧毀鑄魔營地的建築物。$B$B等等！別激動！還有件事你不知道呢，邪能火炮的鑰匙在當地監工手中。你得先拿到鑰匙才行！每臺邪能火炮都由獨立的監工看管！$B$B不太容易，對吧？$B$B回去向奧圖裡斯覆命吧。','撒塔斯城的薩薩拉比姆要你返回納格蘭西部向受難者奧圖裡斯覆命。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10011 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10011,'zhTW','掃蕩鑄魔營地','$N，召集你的盟友吧。監工都是些很難對付的強者，你需要朋友的幫助。$B$B和你的盟友們並肩作戰，殺掉鑄魔營地的監工，然後用他們的鑰匙調轉邪能火炮的炮口，朝著鑄魔營地開火吧。摧毀營地後回來向我覆命。','納格蘭西部的受難者奧圖裡斯要求你摧毀鑄魔營地：仇恨和鑄魔營地：畏懼。','','去找納格蘭的受難者奧圖裡斯。','摧毀鑄魔營地：仇恨','摧毀鑄魔營地：畏懼','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10012 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10012,'zhTW','邪獸人的計劃','這張潦草無比的計劃書明顯出自於某一個邪獸人的手筆。雖然你不知道它到底在說什麼，但裡面隱含的意思卻非常清楚：邪獸人接受了火翼崗哨的血精靈下達的命令。$B$B為什麼這兩個種族會聯合起來？波爾泰姆或許會知道一些內幕。你決定把地圖帶回奧蕾莉亞要塞去交給他。','將邪獸人的計劃交給泰羅卡森林中奧蕾莉亞要塞的波爾泰姆。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10013 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10013,'zhTW','幕後黑手','這張潦草無比的計劃書明顯出自於某一個邪獸人的手筆。雖然你不知道它到底在說什麼，但裡面隱含的意思卻非常清楚：邪獸人接受了火翼崗哨的血精靈下達的命令。$B$B為什麼這兩個種族會聯合起來？羅卡格或許會知道一些內幕。你決定把地圖帶回裂石堡去交給他。','將邪獸人的計劃交給泰羅卡森林中裂石堡的羅卡格。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10014 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10014,'zhTW','火翼崗哨的專案','正如我說的那樣，我們已經收到了新的情報，並且面臨著更棘手的問題。$B$B血精靈正在火翼崗哨拼命地製造第二枚炸彈。用不著我再多說，你也知道一旦他們建成這個裝置並投入使用的話，對奧蕾莉亞要塞來說該意味著什麼了！$B$B我的偵察員告訴我他們在環繞中心庭院的四座較小的建築物裡看守著該裝置的密碼。趁現在還來得及，到那裡去幫我把密碼偷回來！','偷取四張魔法炸彈密碼錶，把它們交給泰羅卡森林中奧蕾莉亞崗哨的米利迪安中尉。','','去泰羅卡森林找奧蕾莉亞崗哨的米利迪安中尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10015 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10015,'zhTW','火翼崗哨的專案','正如我說的那樣，我們已經收到了新的情報，並且面臨著更棘手的問題。$B$B血精靈正在火翼崗哨拼命地製造第二枚炸彈。用不著我再多說，你也知道一旦他們建成這個裝置並投入使用的話，對裂石堡來說該意味著什麼了！$B$B我的偵察員告訴我他們在環繞中心庭院的四座較小的建築物裡看守著該裝置的密碼。趁現在還來得及，到那裡去幫我把密碼偷回來！','偷取四張魔法炸彈密碼錶，把它們交給泰羅卡森林中裂石營地的卡烏尼中士。','','去找泰羅卡森林的卡烏尼中士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10016 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10016,'zhTW','森林座狼的尾巴','你在旅行途中遇到任何森林座狼沒有？當我在勘察森林北邊擴展區域時看到過它們。我建議，如果你沒有準備好戰鬥的話，千萬不要靠近它們。$B$B它們一點也不害怕我們，而且會毫不遲疑地保衛它們的領地。$B$B不過，森林座狼的尾巴都非常非常的漂亮。我正在收集它們的尾毛來裝飾我的新斗篷，不過但它們總是能逃脫我的捕捉。你能幫幫我的忙嗎？','奧蕾莉亞要塞的波爾泰姆想讓你收集12條森林座狼的尾巴。這些尾巴可以從森林座狼和森林座狼前鋒身上獲得。','','去泰羅卡森林找奧蕾莉亞要塞的波爾泰姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10017 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10017,'zhTW','物資緊張','每天湧入撒塔斯城尋求庇護的難民越來越多了。很多人還受了嚴重的傷，他們能活著堅持到這裡，可真是個奇蹟。$B$B我可以醫治大部分的尋常傷症。身為一名奧爾多醫者，我所接受過的訓練讓我對此有著良好的準備和應對經驗。染毒的傷症則略麻煩一些，更何況我這裡的抗毒劑儲備量已經不太夠了。$B$B給從我當地的巨牙蜘蛛身上取一些毒囊來吧，這樣我就能製作更多的解毒劑了。在泰羅卡地區東南方的那塊地方，你就可以找到那些蜘蛛。','給撒塔斯城的莎妮爾帶回8個巨牙毒囊。$B$B為奧爾多完成任務將會使你在占星者陣營中的聲望等級降低。','','去找泰羅卡森林的莎妮爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10018 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10018,'zhTW','狼魂之衣','很久以前，當獸人部落還居住在泰羅卡森林的時候，他們非常崇拜狼的野性。而在他們離開之後，獸人開始變得不再需要狼之魂，並將它遺棄在了森林中。$B$B在那些日子裡，狼之魂漸漸地感到孤獨，最後離開了森林。$B$B我相信我能將狼之魂召喚回泰羅卡森林，就像我們一樣回到祖先的家園。我要為儀式準備一些用森林中狼的毛皮製作的祭袍，這樣才能指引靈魂回來。','給裂石堡的瑪魯卡茲帶回12塊森林座狼的毛皮交。','','去泰羅卡森林找裂石堡的瑪魯卡茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10019 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10019,'zhTW','更多毒囊','','','','去找地獄火半島的莎妮爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10020 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10020,'zhTW','薩恩莉亞的解藥','我右側的這位女士的頭部曾受過非常嚴重的創傷。雖然她很幸運地活了下來，卻失去了視力。$B$B有一種非常傳統的方法可以治癒她的眼睛，但是這需要使用一種原始蜥蜴的血。$B$B不幸的是，這裡來自世界各地的偷獵者數量實在太多，導致棲息在泰羅卡森林裡的蜥蜴數量正在逐漸變少。$B$B有一隻名叫“凝石者”的蜥蜴非常著名，我小時侯就經常聽到它的名字。據說它就住在東邊，陸地的盡頭。$B$B把它的血帶回來給我，這樣薩恩莉亞就能重見光明瞭。','將凝石者的血交給撒塔斯城的莎妮爾。$B$B為奧爾多完成任務將會使你在占星者陣營中的聲望等級降低。','','去找泰羅卡森林的莎妮爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10021 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10021,'zhTW','重現聖光','以前，有許多德萊尼人生活在這個地區，而我們奧爾多則擔負著守衛德萊尼聖地與祭壇的任務。現在，這些聖地與祭壇大多已經被我們的敵人摧毀或佔據了。$B$B從這裡向東去，就有一處鴉人的據點。這處據點是故意建立在過去我們的三處神聖祭壇之上的。那些鴉人利用他們的邪惡魔法扭曲並褻瀆了聖地中原生的純潔能量。$B$B把這個帶到那處據點去，用它淨化那裡的三座祭壇。','伊沙娜希望你能轉至撒塔斯城正東方的鴉人前哨站，使用神聖之瓶淨化東部祭壇、西部祭壇和北部祭壇。$B$B為奧爾多完成任務將會使你在占星者陣營中的聲望等級降低。','','去撒塔斯城找奧爾多高地的伊沙娜。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10022 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10022,'zhTW','狡猾的鐵顎','我這裡已經有了許多非常漂亮的毛皮，但是，我還是最想得到一件由狼的毛皮作成的斗篷兜帽，那樣一切就完美了。想想，假如你看到你的敵人披著森林裡最狡猾的掠奪者的毛皮，是不是會感覺害怕呢！$B$B我曾捕捉過那隻叫鐵顎的老狼，但沒有成功。那時候我試過將它逼上死路，試過最精巧的陷阱，也試過最誘人的肉餌，但是都失敗了……它可真聰明。$B$B這傢伙通常都遊蕩在森林東北邊的擴展區域。如果你能幫我捉到它，我一定會支付你一大筆報酬的。','為奧蕾莉亞要塞的波爾泰姆帶回鐵顎的毛皮。','','去泰羅卡森林找奧蕾莉亞要塞的波爾泰姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10023 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10023,'zhTW','狼王鐵顎','收集第一批毛皮的工作，你完成得非常出色。$B$B不過，製作祭袍還需要另一塊特殊的毛皮。你知道嗎，森林中有一隻很特別的狼，它年老卻相當狡猾，還是森林中狼群的族長。它是一隻力量非常強大的食肉動物，名叫鐵顎。$B$B我常常看到它在森林的東北邊漫步。如果能將它的毛皮新增到祭袍中，一定能為狼之魂指明道路。$B$B不要為鐵顎的死亡而感到悲傷，它會為此受到所有人的尊敬。','將鐵顎的毛皮交給裂石堡的瑪魯卡茲。','','去泰羅卡森林找裂石堡的瑪魯卡茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10024 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10024,'zhTW','沃雷塔爾的預言','我們的領袖先知沃雷塔爾曾是凱爾薩斯最重要的一名顧問。有一天，他的預言夢境卻警告他說，如果凱爾繼續沿著當前的道路走下去，那麼等待我們整個種族的只有毀滅。$B$B夢境一般都是非常模糊和不確定的，但我們的鍊金師為他發明了一種藥劑，使他可以集中感官與意識去了解夢境的內容。然而，這種藥劑需要一種非常稀有的材料：蜥蜴的眼球。我之前的供貨商，也就是這個可憐的虛靈，太令我失望了。$B$B在泰羅卡的岩石地域尋找這些溼鱗蜥蜴吧，把它們的眼球帶回來給我。','將8顆溼鱗蜥蜴的眼睛交給撒塔斯城的奧術師艾蒂莉亞。$B$B為占星者完成任務將會使你在奧爾多陣營中的聲望等級降低。','','去找撒塔斯城的奧術師艾蒂莉亞。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10025 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10025,'zhTW','更多蜥蜴眼','','','','去找地獄火半島的奧術師艾蒂莉亞。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10026 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10026,'zhTW','魔法擾動','雖然承認這件事令我的確很尷尬，但是最近泰羅卡森林裡發生了許多奇怪的事情，這在我當學徒的時候可從未發生過。$B$B比如說，我的魔法在泰羅卡森林內偶爾會失效，而且我肯定所有的施法步驟都沒有出錯。第一次發生這樣的事情時，我差點瘋掉。$B$B不過，我想我已經找到原因了。這片森林裡到處都有一種叫遷躍跟蹤者的怪獸，它們首選魔法能量，而且能影響施法者施法。最好的解決辦法就是殺掉它們。','奧蕾莉亞要塞的安達爾要求你殺死10只遷躍跟蹤者。','','去泰羅卡森林找奧蕾莉亞要塞的安達爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10027 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10027,'zhTW','魔法擾動','沒有什麼事情能比在施法時被某些未知的力量所幹擾更讓人煩心了。在做了四次嘗試後，我終於明白這絕對不是巧合，於是我派了凱比希爾出去調查此事。$B$B我敢保證，你這輩子絕對沒有遇到過比它還愛頂嘴的小鬼，讓它幹點活可真難。$B$B不過它最後還是找到了問題的根源，是一種叫作遷躍跟蹤者的怪物在從中搗鬼。無論出現在什麼地方，它們總是習慣於擾亂魔法能量流。我已經受夠了，把它們都幹掉。','殺死10只遷躍跟蹤者，然後向裂石堡的庫加托克覆命。','','去泰羅卡森林找裂石堡的庫加托克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10028 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10028,'zhTW','強大的容器','在圖雷姆廢墟中有許多富含原始魔法能量的容器。非常幸運的是，當前侵佔了圖雷姆的那些破碎者並不知道這些容器的存在。但是，恐怕不久之後他們就會發現這一點。$B$B如果我們這些倖存者能夠掌握容器中的魔法能量，或許就能抵擋住惡魔魔法的引誘。每拯救一名奎爾多雷，都能為我們贏得失去的榮耀。幫我帶一些那種容器回來，$c。','為奧蕾莉亞要塞的洛瑟蕾絲帶回8個德萊尼容器。','','去泰羅卡森林找奧蕾莉亞要塞的洛瑟蕾絲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10029 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10029,'zhTW','亡靈在召喚','白骨荒野的亡者靈魂一直在召喚著我！其中一個叫索拉伏恩在懇求我的幫助。$B$B$C，你一定要前往南方的白骨荒野幫助這個靈魂。他就在奧齊頓的北邊入口附近。為了跟他溝通，你必須跨越時空到來生一下。我會給你一份精華讓你在荒野裡使用。$B$B如果你覺得需要更多的精華，就回來找我。\\r\\n\\r\\n','隱士麗蒂娜要你去泰洛卡森林的白骨荒野，在難民商隊找到她的助理，索拉伏恩。$B$B完成奧爾多所有的任務會降低你的占星者聲望。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10030 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10030,'zhTW','收集骸骨','無數德萊尼人在奧金頓大爆炸中不幸罹難，屍骨就散落在白骨荒野。他們不安寧的靈魂仍在世間飄蕩。$B$B$C，幫幫我吧，將他們的屍骨帶往最終的安息之地！只有這樣，他們才能安然長眠。$B$B收集無眠之骨，將它們交給白骨荒野中心奧金頓的瘋狂的拉姆杜爾。儘管此人名字古怪，可他懂得如何處理這些屍骨。','收集10根無眠之骨，並將它們交給奧金頓儀式廣場西側的瘋狂的拉姆杜爾，奧金頓就在泰羅卡森林白骨荒野的中心。','','去泰羅卡森林奧金頓的儀式廣場找瘋狂的拉姆杜爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10031 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10031,'zhTW','迷失者的解脫','奧金頓大爆炸使許多德萊尼人的靈魂墮落腐化。如今，他們痛苦地在白骨荒野徘徊著。$B$B$N，求求你，讓他們獲得安寧吧。消滅奧金頓外的失落的幽魂和破碎的骷髏。$B$B什麼？你認為讓他們繼續在痛苦中掙扎會更好？$B$B完成任務後你就返回難民車隊，告訴蘇拉文你都做了什麼。','消滅10個失落的幽魂和10只破碎的骷髏，然後向泰羅卡森林白骨荒野難民車隊的蘇拉文覆命。','','去白骨荒野找難民車隊的蘇拉文。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10032 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10032,'zhTW','圖雷姆的神器','你留意過圖雷姆的那些失落者嗎？他們一直在廢墟中四處徘徊，尋找德萊尼人留下來的碎片。$B$B這些失落者的智慧水平完全不能與他們的破碎者主人相比，他們已經忘掉了以前的生活和身份，變成了完全不同的物種。$B$B我認為我們可以利用失落者的這些無意識舉動來收集到一些古老的德萊尼聖物。既然妥善地選擇目標能夠為我們謀得利益，還為什麼要去冒險與這些破碎者開戰呢？','從圖雷姆清道夫和圖雷姆獵人身上收集6個圖雷姆神器，把它們交給裂石堡的拉克妮亞。','','去泰羅卡森林找裂石堡的拉克妮亞。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10033 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10033,'zhTW','通緝：白骨禿鷲！','通緝：白骨荒野的白骨禿鷲。這些攜帶著瘟疫的白骨禿鷲必須被悉數消滅！$B$B雖然它們的行蹤遍佈白骨荒野，但多數集中在北邊的腐臭山。$B$B完成任務後可以向泰拉·遠途領取獎賞。','殺死20只白骨禿鷲，然後向泰羅卡森林內奧蕾莉亞要塞的泰拉·遠途覆命。','','去泰羅卡森林找奧蕾莉亞要塞的泰拉·遠途。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10034 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10034,'zhTW','通緝：白骨禿鷲！','白骨荒野的白骨禿鷲襲擊了瑪烏格，令他身染疾症。他現在想要殺死所有的白骨禿鷲！$B$B雖然它們的行蹤遍佈白骨荒野，但多數集中在北邊的腐臭山。$B$B完成任務後向瑪烏格·銳箭領賞吧。','殺死20只白骨禿鷲，然後向泰羅卡森林裂石堡的瑪烏格·銳箭覆命。','','去泰羅卡森林找裂石堡的瑪烏格·銳箭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10035 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10035,'zhTW','託古斯！','白骨荒野中有一隻非常可怕的生物，只有最無畏的勇者才有膽去獵殺它。$B$B沒錯，我說的便是白骨禿鷲之王託古斯，它盤踞在位於白骨荒野西部邊緣的哈茲鴉巢。$B$B可是鴉人們在那附近紮了一個被稱為託古斯克星的大型稻草人，這玩意令託古斯膽怯不已。不過，如果你能將託古斯的配偶特拉克拉的殘骸放在稻草人腳下，它必定會不顧一切地飛離鴉巢衝過來。你可以在白骨荒野北邊的腐臭山找到特拉克拉。$B$B如果成功殺死了託古斯，記得將一片託古斯的尾羽帶回來給我。','利用特拉克拉的殘骸引出託古斯，將託古斯交給泰羅卡森林奧蕾莉亞要塞的泰拉·遠途。','','去泰羅卡森林找奧蕾莉亞要塞的泰拉·遠途。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10036 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10036,'zhTW','託古斯！','我想要白骨禿鷲之王託古斯的命！$B$B不久前，我在白骨荒野西部邊緣的哈茲鴉巢狩獵時，它突然撲向我。$B$B<瑪烏格拍了拍他的眼罩。>$B$B它啄瞎了我的眼睛，那麼我就要它的命！將一片託古斯的尾羽帶回來給我，我會好好獎賞你的。$B$B鴉巢附近豎著一個被稱為託古斯克星的稻草人，這玩意令託古斯膽怯不已。不過，如果能將託古斯的配偶特拉克拉的殘骸放在稻草人腳下，它必定會不顧一切地飛離鴉巢。$B$B你可以在白骨荒野北邊的腐臭山找到特拉克拉。','利用特拉克拉的殘骸引出託古斯，將託古斯交給泰羅卡森林裂石堡的瑪烏格·銳箭。','','去泰羅卡森林找裂石堡的瑪烏格·銳箭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10037 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10037,'zhTW','寧可去釣魚','說到湖泊，東北邊的那面湖泊是釣魚的好地方。我以前常常跟朋友們一起去，但是現在，我媽媽不再讓我去那個地方了。$B$B她總是說那裡很危險，但是，我只看到一些小蜘蛛出現在湖泊周圍啊。或許，或許……說不準這些蜘蛛會對你做些什麼吧……$B$B但是，但是呢，我特別愛吃湖裡的鰻魚。如果你恰好也要去湖泊那邊的話，能不能幫我帶回來一些呢？你放心，這些狂躁不安的鰻魚一旦被制服，就能輕易地帶回來了哦。','為撒塔斯城的塞瑟帶回8條新鮮的亮鱗電鰻。','','去找撒塔斯城貧民窟的塞瑟。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10038 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10038,'zhTW','援助列兵維克斯','我剛剛收到一份來自格蘭戈瓦村的報告，據說一隊暗影氏族的成員在那座廢棄的村落安營紮寨。$B$B$N，去跟列兵維克斯談談，看你能不能幫他查明這幫鬼鬼祟祟的傢伙想做什麼。出了要塞往西走，繞過裂石堡就是格蘭戈瓦村了。列兵維克斯在村子北面的入口。','與泰羅卡森林格蘭戈瓦村北方入口附近的列兵維克斯談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10039 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10039,'zhTW','援助斥候奈弗蒂絲','我剛剛收到一份來自格蘭戈瓦村的報告，據說一隊暗影氏族的成員在那座廢棄的村落安營紮寨。$B$B$N，去跟斥候奈弗蒂絲談談，看你能不能幫她查明這幫鬼鬼祟祟的傢伙想做什麼。出了裂石堡往南，然後轉向正西方，格蘭戈瓦村就位於白骨荒野的北部邊緣。斥候奈弗蒂絲在村子的南部入口。','與泰羅卡森林格蘭戈瓦村南方入口附近的斥候奈弗蒂絲談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10040 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10040,'zhTW','他們是誰？','我不知道他們究竟是誰，但我知道他們充滿了敵意！$B$B據我觀察，營地中有三個傢伙總是喋喋不休的。穿上這件偽裝服，潛入格蘭戈瓦村，與陰暗新兵、陰暗勞工和陰暗顧問聊聊天。$B$B要小心，陰暗獵人可以識破你的偽裝，這些獵人看上去就不好對付！維繫偽裝的魔法能量有些脆弱，因此打探敵情期間，你千萬不能離開村子。如果你弄丟了這件偽裝，就回來找我吧。我會為你另做一件的。','在偽裝狀態下，與陰暗新兵、陰暗勞工和陰暗顧問交談，然後向泰羅卡森林格蘭戈瓦村的列兵維克斯覆命。','','去泰羅卡森林找格蘭戈瓦村的列兵維克斯。','與陰暗新兵交談','與陰暗勞工交談','與陰暗顧問交談','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10041 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10041,'zhTW','他們是誰？','我不知道他們究竟是誰，但我知道他們充滿了敵意！$B$B據我觀察，營地中有三個傢伙總是喋喋不休的。穿上這件偽裝服，潛入格蘭戈瓦村，與陰暗新兵、陰暗勞工和陰暗顧問聊聊天。$B$B要小心，陰暗獵人可以識破你的偽裝，這些獵人看上去就不好對付！維繫偽裝的魔法能量有些脆弱，因此打探敵情期間，你千萬不能離開村子。如果你弄丟了這件偽裝，就回來找我吧。我會為你另做一件的。','在偽裝狀態下，與陰暗新兵、陰暗勞工和陰暗顧問交談，然後向泰羅卡森林格蘭戈瓦村的斥候奈弗蒂絲覆命。','','去泰羅卡森林找格蘭戈瓦村的斥候奈弗蒂絲。','與陰暗新兵交談','與陰暗勞工交談','與陰暗顧問交談','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10042 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10042,'zhTW','暗影議會必須死！','什麼！這幫傢伙是暗影議會的成員？！$B$B$N，你必須返回格蘭戈瓦村消滅他們！我要你殺掉他們的暗影主宰，並且儘可能多地幹掉陰暗劊子手和陰暗召喚者。$B$B完成任務後向奧蕾莉亞要塞的加維·砂錘中尉覆命。$B$B$c，祝你好運！','殺死10個陰暗劊子手、10個陰暗召喚者和暗影主宰格里弗，然後向泰羅卡森林奧蕾莉亞要塞的加維·砂錘中尉覆命。','','去泰羅卡森林找奧蕾莉亞要塞的加維·砂錘中尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10043 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10043,'zhTW','暗影議會必須死！','什麼！這幫傢伙是暗影議會的成員？！$B$B$N，你必須返回格蘭戈瓦村消滅他們！我要你殺掉他們的暗影主宰，並且儘可能多地幹掉陰暗劊子手和陰暗召喚者。$B$B完成任務後向裂石堡的顧問菲埃拉覆命。$B$B$c，祝你好運！','殺死10個陰暗劊子手、10個陰暗召喚者和暗影主宰格里弗，然後向泰羅卡森林裂石堡的顧問菲埃拉覆命。','','去泰羅卡森林找裂石堡的顧問菲埃拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10044 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10044,'zhTW','拜訪蓋亞安祖母','蓋亞安祖母要我來找你，並替她向你傳個口信。是這樣的，她想再跟你談談。$B$B$N，我先警告你，雖然祖母病重的訊息令我意志很消沉，不過你若是惹惱了她，我還是會召集瑪格漢氏族的勇士把你給劈了！她在大廳裡等你。$B$B<加爾魯什指著北邊的那座大型建築物。>$B$B耐心地聽她的話，她吩咐你的事情一律照辦。','與蓋亞安祖母談談，聽她講述故事。','聆聽蓋亞安祖母的話','去納格蘭找加拉達爾的蓋亞安祖母。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10045 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10045,'zhTW','必需的材料','$N，卡舒爾宗母想跟你談談。但在此之前，你必須先去採集一些特殊的草藥，我要為你配製一瓶開拓心智的藥水，讓你具備與先祖的靈魂溝通的能力。$B$B我需要一根泰羅卡森林的奧雷巴根鬚、一顆贊加沼澤的沼澤莓、一片納格蘭的塔拉蕨和一株刀鋒山的龍脊草草。這張羊皮紙上記載了四種草藥的地理位置。集齊草藥後回來向我覆命。','納格蘭加拉達爾的蓋亞安祖母要你收集1根奧雷巴根鬚、1顆沼澤莓、1片塔拉蕨和1株龍脊草草。','','去納格蘭找加拉達爾的蓋亞安祖母。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10046 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10046,'zhTW','跨越黑暗之門','兩週前，我們接到哨兵的報告，稱戰地指揮官洛姆斯帶領著一支浩浩蕩蕩的聯盟大軍離開了守望堡。這支軍隊兵力雄厚，供給充足，並且有著一位屢建戰功的指揮官，他們的目標必定只有一個：揮師外域。$B$B酋長已經派出先遣部隊轉至黑暗之門，如果聯盟真的認為有必要派那麼多人去，那我們也得讓他們見識一下部落的增援部隊。$B$B跨越黑暗之門，向索爾瑪的納茲格雷爾報到。','跨越黑暗之門，跟索爾瑪的納茲格雷爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10047 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10047,'zhTW','榮耀之路','“榮耀之路”，他們如此稱呼它。這條路從他們那陰森恐怖的要塞中心一直擴展到黑暗之門，路上鋪滿了我的同胞的屍骨。$B$B他們像對待動物一樣追殺我們，摧毀我們的家園，折磨我們的倖存者。這樣做還遠遠不夠，他們甚至把我們的屍骨當做鋪路石，不讓我的同胞得到聖光的照耀。$B$B那些被折磨的靈魂至今還徘徊在這地方，大聲呼喊著要解脫出來。$N，我希望你能幫我完成這件事情。','在榮耀之路上使用德萊尼聖水淨化8個被踐踏的骷髏，然後返回榮耀堡向位面占卜者克雷夫覆命。','','去地獄火半島找榮耀堡的位面占卜者克雷夫。','淨化被踐踏的骷髏','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10048 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10048,'zhTW','魔法粉塵','我需要一些粉塵，但不是普通的粉塵。$B$B附近森林中的華麗的巨蛾翅膀上覆蓋著一種魔法粉塵，可以讓試圖捕獲它們的生物平靜下來。我可以利用這種粉塵來破除鴉人之眼的魔法結界。這樣，我們就可以用它們來追蹤迪魯姆的下落。$B$B我不需要太多，幾小撮粉塵就行。','收集7撮安撫粉塵，將它們交給奧蕾莉亞要塞的安達爾。','','去泰羅卡森林找奧蕾莉亞要塞的安達爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10049 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10049,'zhTW','魔法粉塵','我需要一些粉塵，但不是普通的粉塵。$B$B附近森林中的華麗的巨蛾翅膀上覆蓋著一種魔法粉塵，可以讓試圖捕獲它們的生物平靜下來。我可以利用這種粉塵來破除鴉人之眼的魔法結界。這樣，我們就可以用它們來追蹤杜加爾的下落。$B$B我不需要太多，幾小撮粉塵就行。','收集7撮安撫粉塵，將它們交給裂石堡的庫加托克。','','去泰羅卡森林找裂石堡的庫加托克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10050 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10050,'zhTW','陰魂不散','當我們征討德拉諾世界的戰役接近尾聲的時候，南邊的物資庫遭到了部落中最為陰險的死亡騎士的攻擊。那些卑鄙的幽靈詛咒了物資庫的衛兵，他們的靈魂就此遭受到了禁錮，無法得到安息。我們必須拯救那些高貴的靈魂！我請求你結束我的同胞們的痛苦，$N，我實在不忍心親手殺掉他們。','榮耀堡衛兵維斯洛要你轉至南邊的遠征軍物資庫，殺死12個步兵的陰魂、10個巫師的陰魂和5個騎士的陰魂。','','去地獄火半島找榮耀堡的榮耀堡衛兵維斯洛。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10051 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10051,'zhTW','逃離火翼崗哨！','能遇見你真是謝天謝地！$B$B$C，你能幫我逃離火翼崗哨嗎。我掌握著關係到奧蕾莉亞要塞乃至整個外域安危的重要情報！$B$B我奉塞納里奧遠征隊之命來這兒建立外交關係，可是你也瞧見了，這幫傢伙很不友善。如果你能護送我離開這兒，必定能獲得一筆豐厚的獎勵！$B$B我們兩個可能沒法打出去，你應該還有盟友與你同行，對吧？','護送伊斯拉·星鬃逃離火翼崗哨，然後向泰羅卡森林奧蕾莉亞要塞的烏瑞克·獵日者上尉覆命。','護送伊斯拉·星鬃','去泰羅卡森林找奧蕾莉亞要塞的烏瑞克·獵日者上尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10052 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10052,'zhTW','逃離火翼崗哨！','能遇見你真是謝天謝地！$B$B$C，你能幫我逃離火翼崗哨嗎。我掌握著關係到裂石堡乃至整個外域安危的重要情報！$B$B我奉塞納里奧遠征隊之命來這兒建立外交關係，可是你也瞧見了，這幫傢伙很不友善。如果你能護送我離開這兒，必定能獲得一筆豐厚的獎勵！$B$B我們兩個可能沒法打出去，你應該還有盟友與你同行，對吧？','護送伊斯拉·星鬃逃離火翼崗哨，然後向泰羅卡森林裂石堡的顧問菲埃拉覆命。','護送伊斯拉·星鬃','去泰羅卡森林找裂石堡的顧問菲埃拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10053 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10053,'zhTW','進攻塞斯高','我們必須妥善利用你殺死指揮官奈克羅格這一輝煌戰果，要乘勝追擊，$N。如果我們運氣夠好，塞斯高的首領——“暗眼”格里洛克現在應該還沒有收到任何關於奈克羅格的訊息。$B$B這個“暗眼”格里洛克領導著東南邊塞斯高的噬骨氏族邪獸人發動過許多次戰爭。立刻轉至他的巢穴，到那處邪獸人營地內的某個山洞裡找到並幹掉他。然後，你要在洞中找到邪獸人的作戰計劃書，我們一定要避免遭到對方的突襲。','擊敗“暗眼”格里洛克，在他的巢穴中搜尋血環攻擊計劃書。','','去地獄火半島找塞斯高的血環攻擊計劃書。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10054 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10054,'zhTW','迫近的厄運','快速地瀏覽完整個計劃之後，你發現這次的襲擊應該是由塞斯高的首領督軍摩爾肯直接策劃，由白骨法師沃爾洛率隊執行的。此外，地圖上標識出的東西遠不止摩爾肯的部隊而已。$B$B計劃書中還提到，已經完成集結的噬骨氏族軍隊將配合來自地獄火堡壘的其它邪獸人軍隊向榮耀堡發起全面的進攻。$B$B沒有時間去通知阿曼蒂中尉了。你必須在噬骨氏族的軍隊發起進攻前阻止他們！','殺死15名血環步兵、10名血環通靈師、5名血環苦工和督軍摩爾肯，然後向榮耀堡西部哨塔的阿曼蒂中尉報到。','','去地獄火半島找榮耀堡西部哨塔的阿曼蒂中尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10055 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10055,'zhTW','回收材料','有增援軍到來是件好事，但是我發現他們沒有帶來金屬和木材。$B$B朋友，看看這周圍。木材從來都是稀缺物資，而礦井又被燃燒軍團的渣滓侵佔了。$B$B我根本找不到供應源，只得去尋找替換物，不過幸好我們可以回收利用一切合適的物資。$B$B榮耀之路南部邊緣有許多廢棄的攻城車，它們的一些零件還可以使用。你能幫我們找一些回來，補充我們的供給嗎？','給榮耀堡的達姆菲帶去8塊回收的金屬和8塊回收的木材。','','去地獄火半島找榮耀堡的達姆菲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10056 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10056,'zhTW','血環補給品','東南邊的獸人城鎮廢墟塞斯高現在成了那些地獄火堡壘中源源不斷湧出的邪獸人的基地。$B$B洛薩之子一直和他們有著小規模的對抗和衝突。那些邪獸人真的十分可怕，若是我沒有親眼見過他們，恐怕真得很難相信洛薩之子對他們的評價。$B$B總之，某種神秘的東西令那些邪獸人發生了變化，變得更加強大了。我們必須想辦法阻止他們繼續壯大自己的力量。現在你立刻轉至塞斯高，破壞掉那裡所有的補給品。','摧毀6堆血環補給箱，然後向榮耀堡的阿曼蒂中尉覆命。','','去地獄火半島找榮耀堡的阿曼蒂中尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10057 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10057,'zhTW','尋找首領','儘管你幫了大忙，遠征軍物資庫那裡卻仍處於混亂的狀態。沒有人知道那裡到底發生了什麼事情，也沒人清楚真正是什麼樣的詛咒將那些已死士兵的鬼魂禁錮在廢墟中。$B$B不過，或許我們完全理解錯了。我一直以為每一個鬼魂都是被廢墟所禁錮的，但也有很大可能是他們的首領在束縛著他們！$B$B大法師辛托爾和塔沃斯少校的鬼魂應該就在其它鬼魂附近，或許擊敗他們就可以讓其它人得到安息。','擊敗大法師辛托爾和塔沃斯少校的鬼魂，然後向榮耀堡西北部哨塔的榮耀堡衛兵維斯洛覆命。','','去地獄火半島找榮耀堡的榮耀堡衛兵維斯洛。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10058 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10058,'zhTW','古老的禮物','<牧師把目光緩緩地從杯子前轉移到了你的身上。>$B$B難道你不知道，千萬不要去打擾借酒消愁的人嗎？$B$B唉，有什麼用？我覺得有陌生人來是件好事，不過，不知道圖拉揚會怎麼想？$B$B我記得許多年前，我們從艾澤拉斯出發的前夜，我把《聖光的秘密》借給了他。在戰爭期間和之後的許多年裡，他每天都閱讀那本書中的內容，激勵他身邊的人，賜予他們祝福。$B$B然而，當他必須再次離開我們的時候，他把書還給了我。而我，就像個傻子一樣，居然以為把它放在物資庫南邊的營房中會很安全，就一直把它丟在那裡了。','將《聖光的秘密》交給榮耀堡的瑪格爾·戴維迪庫斯神父。','','去地獄火半島找榮耀堡的瑪格爾·戴維迪庫斯神父。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10059 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10059,'zhTW','塞斯高的首領','我們必須妥善利用你殺死指揮官奈克羅格這一輝煌戰果。要乘勝追擊，$N！如果我們運氣夠好，塞斯高的首領——“暗眼”格里洛克現在應該還沒有收到任何關於奈克羅格的訊息。$B$B這個“暗眼”格里洛克領導著東南邊塞斯高的噬骨氏族邪獸人發動過許多次戰爭。立刻轉至他的巢穴，到那處邪獸人營地內的某個山洞裡找到並幹掉他。然後，你要在洞中找到邪獸人的作戰計劃書，我們一定要避免遭到對方的突襲。','殺死“暗眼”格里洛克，在他的巢穴中搜尋血環攻擊計劃書。','','去地獄火半島找塞斯高的血環攻擊計劃書。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10060 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10060,'zhTW','迫近的末日','快速地瀏覽完整個計劃之後，你發現這次的襲擊應該是由塞斯高的首領督軍摩爾肯直接策劃，並由白骨法師沃爾洛率隊執行的。此外，地圖上標識出的東西遠不止摩爾肯的部隊而已。$B$B計劃書中還提到，已經完成集結的噬骨氏族軍隊將配合來自地獄火堡壘的其它邪獸人軍隊向榮耀堡發起全面的進攻。$B$B沒有時間去通知阿曼蒂中尉了\\r\\n。你必須在噬骨氏族的軍隊發起進攻前阻止他們！','消滅15名血環步兵、10名血環通靈師、5名血環苦工和督軍摩爾肯，然後向斷背山的石頭守衛安比蘭彙報情況。','','去地獄火半島找斷背崗哨的石頭守衛安比蘭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10061 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10061,'zhTW','陰魂不散','當初，噬骨氏族的邪獸人對遠征軍物資庫發動了一次突襲，幾乎將那裡的駐軍屠戮殆盡。那場戰役充滿了血腥和暴力，生還者寥寥無幾。$B$B後來，儘管我們派人埋葬了所有的死難者，可是他們的靈魂仍舊徘徊在那些廢墟之間。最近，我在預言的夢境常常看到，這些靈魂成為了索爾瑪最大的威脅之一。$B$B因此，現在我們能做的事情只有一件——必須讓這些靈魂得到安息。去吧，孩子，你必須擊敗他們。','葛雷拉格要你轉至榮耀堡以南的遠征軍物資庫，殺死12個步兵的陰魂、10個巫師的陰魂和5個騎士的陰魂。','','去地獄火半島找斷背崗哨的葛雷拉格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10062 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10062,'zhTW','尋找領袖','儘管你作了很大的努力，遠征軍物資庫的騷動仍在繼續。沒有人知道那裡到底發生了什麼事情，也不知道到底是什麼令那些死去的士兵靈魂依舊徘徊在廢墟。$B$B或許我們完全錯了。我看到的幻象顯示出每一個靈魂都被廢墟束縛，但也許束縛他們的其實是他們的首領呢？$B$B大法師辛托爾和塔沃斯少校在那些士兵周圍，擊敗他們的靈魂或許會讓其它的人安息下來。','擊敗大法師辛托爾和塔沃斯少校的鬼魂，然後向斷背山的葛雷拉格覆命。','','去地獄火半島找斷背崗哨的葛雷拉格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10063 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10063, 'zhTW', '探險者協會，那是給地精的東西嗎?', '帶小孩!你相信嗎?他們把我從前途光明的考古發掘裡叫出來要我去奧迪席斯隊長的遠征隊去照顧一個小地精!我從未聽說有地精要當勘察員，所以我問了。看來好像我們現在接受地精了，而這個特別的傢伙受到魚人們的愛戴!哎，他已經下班了，在島的北方海岸那一個破舊的龜殼處紮營。如果你不相信我就去看看吧!', '在血色守望的北邊海岸上的破舊龜殼處尋找克羅波·維茲班。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10064 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10064, 'zhTW', '與阿格斯之手談談', '阿古斯之手在復仇者之陵建立了一個前方據點，但被血精靈及突變的野生生物在數量上遠遠的超過了。沒有後備的話，他們的前哨將有陷落的危險，而我們則無法監視旋繞導航器週遭的狀況。到復仇者之陵西北方找斥候喬爾力報到，並提供你的協助，$N。', '向復仇者之陵的斥候喬爾力報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10065 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10065, 'zhTW', '清出一條路來', '在我們偵察太陽之鷹及他們的門戶這段期間，我受了許多的傷。斥候羅莉設法幫我止血，並試著想出一個方法將我疏送到血色守望。$B$B問題就在於我們得放棄現在這個位置以確保日後能夠安全的回來。$B$B只要我們一離開這個神聖的地區，我們就會被劫毀者捉住。如果你能幫我們清理掉一些暴怒的劫毀者，也許就能讓我們回程安全些。', '殺了10個暴怒的劫毀者後回到復仇者之陵找斥候喬爾力。', '', '去找鮮血島的斥候喬爾力。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10066 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10066, 'zhTW', '噢，他們所編織的糾纏的圈套', '我們不敢放棄我們的哨站，或離開復仇者之陵太遠，$r。接近旋繞導航器的突變生物藉由水晶洩漏的能量而產生了極大的改變。$B$B突變的糾纏者好像獲得了某些程度的知覺。他們已經懂得創造，佈置，及隱藏惡毒的陷阱，能夠捕捉住即使是最細心的戰士。$B$B假如我們繼續否認事實，我們將無法與這些太陽之鷹對抗。去攻擊問題的源頭，$N。', '殺掉8個突變的糾纏者後向復仇者之陵的復仇者科林回報。', '', '去找鮮血島的復仇者科林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10067 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10067, 'zhTW', '污濁的水精靈', '大部分的生物接觸過水晶的能量後都以同樣的方式墮落:肌肉上有奇怪的記號，強烈地侵略性，以及身體有小片的水晶裂片。然而，位於這裡北方的污濁的水之靈似乎整個都晶化了。$B$B我之前從未看過任何生物會這樣晶化的，不過當我們偶然發現他們後，發現他們特別的危險。我們必須在太陽之鷹將他們當成新的力量來源前除掉他們。', '殺掉6個污濁的水之靈後回到復仇者之陵找復仇者科林。', '', '去找鮮血島的復仇者科林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10068 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10068,'zhTW','護井者索蘭尼亞','有件事得麻煩你跑一趟。$B$B護井者索蘭尼亞需要幫助。你的辦事能力毋庸置疑，必定能討得他的歡心。$B$B沿著室內的坡道往上走，他就在外面的平臺上。','與逐日島的太陽之塔上的護井者索蘭尼亞談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10069 AND `locale` = 'zhTW';
