INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10074,'zhTW','沃舒古水晶塵','哈蘭曾經是德萊尼人研究納魯水晶的重要基地。$B$B我們發現，產自“鑽石山”沃舒古的水晶具有極高的研究價值，而且這個區域的所有生物體內似乎都殘留著這種水晶塵。如果你在探險途中找到水晶塵的話，就把它們統統拿來給我吧。我會獎勵你一枚勳章，你可以用它向軍需官購買東西。','將10份沃舒古水晶塵樣本交給哈蘭的主研究員阿米蒂恩。','','去納格蘭找哈蘭的主研究員阿米蒂恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10075 AND `locale` = 'zhTW';
