INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10364,'zhTW','凱德莫斯','你在短時間內的進步相當可觀，$n，遠比我想象和希望得要快。差不多是時候讓你繼續接受凱德莫斯的指導和監護了。$B$B我已經給他帶去了口信，他也正在艾克索達等著你呢。你可以在聖光穹頂門口附近的學者聖殿找到他。','與艾克索達聖光穹頂的凱德莫斯談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10365 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10365,'zhTW','關閉法力熔爐：艾拉','你取得的成就完全出乎我們的意料。法力熔爐：艾拉是凱爾薩斯碩果僅存的一座法力熔爐。它位於此地西北方的浮島上，不過你得繞一大圈才能到達那兒。關閉最後這座法力熔爐。$B$B控制水晶由工頭阿扎拉德掌管。據我們所知，法力熔爐：艾拉是凱爾最後一處能量來源，必定駐派了重兵把守。換做是我的話，我會叫上一幫朋友共同轉至。$B$B唔……阿扎拉德。辛多雷取這樣的名字真是古怪。','轉至法力熔爐：艾拉，從工頭阿扎拉德手中奪得艾拉控制水晶。對法力熔爐：艾拉的控制檯使用水晶關閉法力熔爐。$B$B為占星者完成任務將降低你在奧爾多陣營中的聲望等級。','','去虛空風暴找52區的間諜大師薩羅迪恩。','','關閉法力熔爐：艾拉','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10366 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10366,'zhTW','約爾','聖光與淨化之路並非是一條容易前行的道路，$n。即使是我，在追隨它的過程中也經歷了數次動搖。$B$B現在你立刻到艾克索達去尋找我過去的導師約爾。在我剛剛開始追尋聖光之時，就是她指引了我。我相信，她很快就會發現你也是一位十分優秀的學生。$B$B你在艾克索達聖光穹頂的守備官聖殿就可以找到她，那是一處充滿了聖光力量的房間。','與艾克索達守備官聖殿的約爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10367 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10367,'zhTW','叛徒','在每個被奴役的破碎者部族中，必定有一位叛徒作祟。這個卑鄙的傢伙為了得到力量不惜出賣自己的同胞。$B$B沙納爾廢墟中心的階梯頂部有一間小屋。那便是背叛者的居所。$B$B他現在恰好不在，如果你有耐心的話，可以悄悄地潛進去。小屋中有個箱子，裡面的鑰匙可以開啟囚禁殘冠長者的鐐銬。把鑰匙帶回來給我。$B$B千萬小心，無情的阿爾澤斯就在小屋附近徘徊。','沙納爾廢墟的納拉杜要你在附近的小屋中找到沙納爾鑰匙。','','去地獄火半島找沙納爾廢墟的納拉杜。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10368 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10368,'zhTW','殘冠長者','殘冠長者被囚禁後，氏族的靈魂便陷入了絕望。帶上這把鑰匙，去搭救殘冠長者。$B$B救出撫風者莫洛德、召火者阿庫魯和喚水者埃伊蘭。一旦他們重獲自由，靈魂就會返回殘冠氏族。','搭救被囚禁在沙納爾廢墟的撫風者莫洛德、召火者阿庫魯和喚水者埃伊蘭。完成任務後向納拉杜覆命。','','去地獄火半島找沙納爾廢墟的納拉杜。','釋放撫風者莫洛德','釋放召火者阿庫魯','釋放喚水者埃伊蘭','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10369 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10369,'zhTW','阿爾澤斯之死','沒錯，元素的靈魂已經回到了我們身邊！雖然我們不如從前那樣強大，但是使用得當的話，一點點魔法都會發揮巨大的功效。$B$B阿爾澤斯的主子賜予了他可怕的力量。帶上這根法杖，它曾是殘冠氏族力量的象徵。利用它對付阿爾澤斯，法杖能讓阿爾澤斯的力量暫時消失。趁機殺死他，我們才能獲得真正的自由！','對無情的阿爾澤斯使用殘冠長者法杖，趁阿爾澤斯失去力量時殺死他。完成任務後向沙納爾廢墟的納拉杜覆命。','','去地獄火半島找沙納爾廢墟的納拉杜。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10370 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10370,'zhTW','納茲格雷爾的命令','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10371 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10371,'zhTW','猶魯斯·麥酒','一個名叫猶魯斯·麥酒的矮人戰士向聯盟所有強大的戰士發出了挑戰。他在赤脊山的湖畔鎮旅店等候著你們，並承諾會給所有透過試煉的戰士提供豐厚的報酬。你的旅途會很遙遠，但是你可以透過它來證明自己的實力，$n。','與赤脊山湖畔鎮的猶魯斯·麥酒談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10372 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10372,'zhTW','謹慎的詢問','我在塔奎林的一位同事艾拉蘭向我發來了請求，需要我派人過去協助她完成一件十分緊急的工作。$B$B我並不知道她在想什麼，但出於紀律原因，我是不會問的。如果你能證明自己具備足夠的能力來完成這項工作的話，我希望你能到鬼魂之地的塔奎林與艾拉蘭談談。$B$B她的性格可能不怎麼溫和，甚至有點粗暴，但她絕對是一個值得信賴的人。','與塔奎林的艾拉蘭談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10373 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10373, 'zhTW', '戰鬥的號角:瘟疫之地!', '大家都聽著!大家都聽著!所有的英雄都應該聆聽這號召的聲音!暴風城已經發出了備戰的號召!所有勇士都應該拿起武器，一同面對來自東部王國北部地方天譴軍團的威脅!城中傳言四起，東部王國的廢墟中滋生出了新的威脅!它們已經在幽暗城東面的瘟疫之地大量集結，聯盟的安全岌岌可危!聯盟的英雄們-去向指揮官阿胥拉姆·瓦羅菲斯特報到吧，他的大本營就在奧特蘭克山脈北邊的冰風營地!', '找到指揮官阿胥拉姆·瓦羅菲斯特。他的大本營位於奧特蘭克山脈以北的冰風營地。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10374 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10374, 'zhTW', '戰鬥的號角:瘟疫之地!', '部落的英雄們，請聆聽這召喚的聲音-部落召喚你們迅速行動起來!戰鬥的號角已經吹響，所有勇士都應拿起武器，準備與天譴軍團殊死作戰!城中傳言四起，東部王國的廢墟中滋生出了新的威脅!它們已經在幽暗城東面的瘟疫之地大量集結，部落的安全岌岌可危!部落的英雄們-去向高級執行官德靈頓報到吧，他的大本營就在提里斯法林地東部的亡靈壁壘!', '找到高級執行官德靈頓。他將自己的大本營建在提里斯法林地和幽暗城以東的亡靈壁壘。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10375 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10375,'zhTW','黑曜石作戰念珠','想要證明你對我們的忠誠，就勇敢地跟我們的敵人作戰吧。$B$B殘忍野蠻的食人魔是塔拉最大的威脅。如果你想證明自己的實力，就把他們脖子上的作戰念珠帶回來給我。我會將你取得的成就告訴氏族其它成員的。','','','去找。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10376 AND `locale` = 'zhTW';
