INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10380,'zhTW','黑暗的契約','$N，兩個最危險的敵人已經結為同盟，而我們竟然一無所知！$B$B如果是占星者故意隱瞞這個訊息的話，我並不會為此感到驚訝。但是，我們必須面對現實。燃燒軍團已經和凱爾薩斯的日怒軍團站到了同一陣線上。$B$B凱爾薩斯能夠利用風暴要塞的科技，肯定和燃燒軍團的惡魔有關。根據歐雷里斯的指示，我命令你立即消滅他們。','圖魯曼的營地中的凱蘭恩要你殺死6名甘爾葛遷躍修理師、3名命運之女和3名莫爾葛空間主宰。$B$B為奧爾多完成任務將降低你在占星者陣營中的聲望等級。','','去虛空風暴圖魯曼的營地找凱蘭恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10381 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10381,'zhTW','退出奧爾多','我的使命已經結束。我一如既往地完成了歐雷里斯交代的所有指令。$B$B到此為止吧。凱爾薩斯和燃燒軍團既已結為同盟，我想一場大屠殺——也就是所謂的遠征即將拉開序幕。$B$B他們先是將我們聖地讓給了敵人，現在還想讓我們為保衛他們流血犧牲。請你回去轉告歐雷里斯，從今以後讓納魯親自上陣作戰吧。','返回52區，向大主教歐雷里斯報到。$B$B為奧爾多完成任務將降低你在占星者陣營中的聲望等級。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10382 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10382,'zhTW','奔赴前線','嗯，$N，我希望你已經準備好進行我們下一步的計劃了。燃燒軍團從來沒有停歇過，我們也絕對不會停下來！你立即乘坐獅鷲飛到榮耀崗哨去——那是靠近軍團前線的一小塊駐地。$B$B與巴洛克元帥談一談，他會安排工作給你的。哦，告訴那個臉色煞白的可憐蟲，我向他問好。','乘坐獅鷲飛往榮耀崗哨，抵達之後與巴洛克元帥談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10383 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10383,'zhTW','線索在這！','哈囉。你應該查明那些兔子。','與強納森·樂卡夫特談論關於兔子的事。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10384 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10384,'zhTW','復仇軍的資料','仔細檢視你四周，這臺傳送器附近應該有一份復仇軍資料單元。找到這份資料單元，取出裡面的內容。$B$B然後立刻將它帶回傳送器面前！','復仇軍前沿基地中的復仇軍發射器 - 塞塔所投射出來的指揮官阿米爾的影像要你帶回復仇軍資料單元。','','去虛空風暴的復仇軍前沿基地用復仇軍發射器塞塔找到指揮官阿米爾的影像。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10385 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10385,'zhTW','腦部損傷機率：高','復仇軍利用一種名叫傳達者的東西在各個前線基地之間傳遞訊息。$B$B想要發現並解讀傳達者攜帶的資訊，只有一個辦法。不幸的是，這樣做很可能使你受到無可挽回的腦部損傷。$B$B如果你仍然有興趣的話，就轉至前線基地殺死復仇軍虛靈，取出他們的精華。飲下虛靈精華後，你就能暫時看見覆仇軍傳達者，精華的有效時間足以讓你摧毀傳達者並解讀它攜帶的資訊。','復仇軍前沿基地中的復仇軍發射器 - 塞塔所投射出來的指揮官阿米爾的影像要你帶回15份復仇軍中繼資料。','','去虛空風暴的復仇軍前沿基地用復仇軍發射器塞塔找到指揮官阿米爾的影像。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10386 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10386,'zhTW','魔能機甲的摧毀者','大督軍霍恩·重拳一直在尋找願意採用自殺式攻擊方法對付燃燒軍團的人。你一定有勇氣去接受其中一個任務。$B$B當你準備好流血犧牲的時候去跟他談一談。他正在那邊慶祝幹掉了一臺魔能機甲。他和他的護衛隊幾個小時前摧毀了那臺魔能機甲，要不是他的兇猛和戰鬥技巧，我們可能都死在這裡了。','與大督軍霍恩·重拳談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10387 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10387,'zhTW','魔能機甲的摧毀者','大督軍霍恩·重拳一直在尋找願意採用自殺式攻擊方法對付燃燒軍團的人。你一定有勇氣去接受其中一個任務。$B$B當你準備好流血犧牲的時候去跟他談一談。他正在那邊慶祝幹掉了一臺魔能機甲。他和他的護衛隊幾個小時前摧毀了那臺魔能機甲，要不是他的兇猛和戰鬥技巧，我們可能都死在這裡了。','與大督軍霍恩·重拳談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10388 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10388,'zhTW','返回索爾瑪','希望你的旅途愉快，朋友。你剛離開的時候來了一個信使——看來納茲格雷爾有新的任務給你了。你最好回索爾瑪去看看，我預感燃燒軍團又有了新的動向。','返回索爾瑪與納茲格雷爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10389 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10389,'zhTW','痛苦與黑暗','你好，$N。我破譯出了燃燒軍團的信件，發現了這些惡魔進攻地獄火半島的戰略計劃。似乎有一大群可怕的恐懼魔聚集在了西邊的阿苟納之池附近。我們絕對不能允許這樣一支龐大的軍隊來攻擊我們。你必須趕到那裡去，殺掉那些該死的惡魔，削弱他們的力量。','魔導師文森特·血鷹要你在阿苟納之池殺掉10個恐懼魔。','','去地獄火半島找索爾瑪的魔導師文森特·血鷹。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10390 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10390,'zhTW','鑄魔營地：暴虐','$N，我們有理由相信最東邊的鑄魔營地還沒有完全建造好。燃燒軍團的甘爾葛僕從正在日夜趕工讓營地運作起來，我們必須阻止他們。$B$B去東邊的鑄魔營地：暴虐，殺掉10個甘爾葛僕從。把他們的主人剃刀電鋸的徽記給我帶回來——燃燒軍團的魔能機甲鑄造計劃必須停止！','索爾瑪的納茲格雷爾命令你攻擊鑄魔營地：暴虐，殺死10個甘爾葛僕從，然後將剃刀電鋸的徽記帶回去交給納茲格雷爾。','','去地獄火半島找索爾瑪的納茲格雷爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10391 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10391,'zhTW','軍團的火炮','第二個鑄魔營地：狂亂位於索爾瑪的東北邊。惡魔們將一些邪能火炮部署在了山脈地區——他們將攻擊目標直接瞄準了我們！你必須進入到營地中毀掉這些邪能火炮。$B$B$N，你必須引爆所有的邪能火炮，否則燃燒軍團仍會利用這些該死的東西來對付我們！','摧毀鑄魔營地：狂亂中的3座邪能火炮I型，然後返回索爾瑪向納茲格雷爾覆命。','','去地獄火半島找索爾瑪的納茲格雷爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10392 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10392,'zhTW','深淵之門','我們為你感到榮耀，$N。不過現在我們必須在燃燒軍團恢復實力之前再給他們一次重擊！索爾瑪的北邊就是登陸場：殲滅，裡面有一座傳送門負責傳送燃燒軍團的增援軍。$B$B你必須設法使它過載，把它炸成灰燼。開啟傳送門的鑰匙在登陸場指揮官阿利薩瑪爾身上。殺掉他，找到鑰匙，用鑰匙開啟傳送門後炸燬它。願酋長祝福你。','殺掉阿利薩瑪爾，找到燃燒軍團傳送門鑰匙，利用它毀掉怨恨符文，然後返回索爾瑪向納茲格雷爾覆命。','','去地獄火半島找索爾瑪的納茲格雷爾。','','關閉燃燒軍團傳送門','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10393 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10393,'zhTW','邪惡的計劃','信上的字是使用某種黑暗而潦草的筆跡書寫的，難以辨認。你盯著看的時間越久，那些符號在你的眼前就變得越發扭曲，似乎要熊熊燃燒起來。在索爾瑪只有一個人能辨認出這樣邪惡的筆跡——血精靈魔導師文森特·血鷹。','將燃燒軍團信件交給交給索爾瑪的魔導師文森特·血鷹。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10394 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10394,'zhTW','鑄魔營地：暴虐','聽仔細了，$N。我們正在調查前方山脈中的燃燒軍團營地。我們有理由相信這些所謂的“鑄魔營地”是他們鑄造那些該死的魔能機甲的地方。$B$B你可以看到最近的一處目標，也就是西邊的鑄魔營地：暴虐。情報表明這座營地仍在建造中。如果你能殺掉甘爾葛僕從和他們的主人剃刀電鋸，我們就可以阻止燃燒軍團鑄造魔能機甲的計劃！','殺掉鑄魔營地：暴虐的剃刀電鋸和10個甘爾葛僕從，然後返回榮耀崗哨向巴洛克元帥覆命。','','去找軍團前線的巴洛克元帥。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10395 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10395,'zhTW','邪惡的信件','信上的字是使用某種黑暗而潦草的筆跡書寫的，難以辨認。你盯著看的時間越久，那些符號在你的眼前就變得越發扭曲，似乎要熊熊燃燒起來。榮耀堡只有一個人能辨認出這種古老的筆跡，那就是德萊尼秘法師克雷夫。$B$B將燃燒軍團信件交給榮耀堡的位面占卜者克雷夫。','將燃燒軍團信件交給榮耀堡的位面占卜者克雷夫。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10396 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10396,'zhTW','我的敵人的敵人……','我們的第二個目標是鑄魔營地：狂亂，它就在鑄魔營地：暴虐的西邊。但現在的問題是，惡魔們將許多邪能火炮直接瞄準了部落的前哨基地索爾瑪！儘管這聽起來有些奇怪，但我們確實需要部落幫忙守住黑暗之門的戰線。因此絕對不能讓索爾瑪失守，你必須在燃燒軍團擊敗我們的同伴之前毀掉這些火炮！','摧毀鑄魔營地：狂亂中的3座邪能火炮I型，然後返回榮耀崗哨向巴洛克元帥覆命。','','去找軍團前線的巴洛克元帥。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10397 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10397,'zhTW','登陸場：殲滅','嗯，我們鎖定了燃燒軍團的最後一座營地——登陸場：殲滅。它位於鑄魔營地：狂亂的西北邊，在裡面有一座傳送燃燒軍團援軍的傳送門！$B$B你必須將那座傳送門毀掉，阻止燃燒軍團利用它輸送更多的惡魔。傳送門的鑰匙在那裡的頭目阿利薩瑪爾身上。將鑰匙奪過來，炸燬那道門！','殺掉阿利薩瑪爾，找到燃燒軍團傳送門鑰匙，利用它毀掉怨恨符文。','','去找軍團前線的巴洛克元帥。','','關閉燃燒軍團傳送門','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10398 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10398,'zhTW','返回榮耀堡','PH:出發到榮耀堡。','PH: 出發到榮耀堡。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10399 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10399,'zhTW','黑暗之心','正如我擔心的那樣。你之前殺死的那個惡魔阿利薩瑪爾聽命於一個神秘的燃燒軍團領主，殘酷的阿拉修斯。這個惡棍似乎在阿苟納之池附近聚集了一支可惡的恐懼魔部隊。$B$B你必須趕在他們襲擊我們之前去那裡殺掉恐懼魔。不過你一定要小心，朋友——阿苟納之池在一個充滿劇毒的山谷中，你可以在西北邊找到這個邪惡的地方，就在地獄火堡壘的那一邊。$B$B聖光與你同在， $N。','在阿苟納之池殺掉10個恐懼魔，然後向榮耀堡的位面占卜者克雷夫覆命。','','去地獄火半島找榮耀堡的位面占卜者克雷夫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10400 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10400,'zhTW','霸王','$N，尊敬的位面占卜者說你冒著生命危險發現了新的敵人。如果克雷夫說得沒錯，那這個“殘酷的阿拉修斯”就無疑是個非常強大而又邪惡的敵人了。$B$B你願意幫助我們嗎，$N？你願意去對付這個燃燒軍團的頭目，讓他受到聖光的制裁嗎？如果你願意的話，就去阿苟納之池找到他吧。如果你不去殺掉他，他的邪惡力量也終究會找到你。','轉至阿苟納之池，除掉殘酷的阿拉修斯，然後返回榮耀堡向遠征軍指揮官達納斯·托爾貝恩覆命。','','去地獄火半島找榮耀堡的遠征軍指揮官達納斯·托爾貝恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10401 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10401,'zhTW','任務:終結所有，戰勝所有','假如你沒有截獲這些信件，你知道會發生什麼事情嗎，$N？<納茲格雷爾點了點頭。>$B$B是的，全地獄火半島的燃燒軍團部隊都會來敲我們索爾瑪的大門。若是真有那樣一場突襲，沒有人可以活下來。$B$B要想不讓這些命令抵達軍團前線，那只有一個辦法。你必須立刻轉至西北方的阿苟納之池，並殺死這隻阿拉薩爾斯。$B$B去吧，若是能夠成功，我會推薦酋長大力嘉獎你的。','地獄火半島上索爾瑪的納茲格雷爾要求你殺掉殘忍的阿拉薩爾斯。','','去地獄火半島找索爾瑪的納茲格雷爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10402 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10402,'zhTW','<TXT>','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10403 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10403,'zhTW','納拉杜','或許殘冠氏族還存有一線希望。被伊利達雷惡魔奴役之前，我是氏族的四名長者之一。我原本以為另外三位長者都已亡故，但後來才知道至少還有兩人活著——他們跟我一樣被囚禁起來，無力逃脫。$B$B至今我都沒能找到納拉杜的下落，我擔心他可能遭遇不測。廢墟頂部還有許多小屋，或許你可以去找找他。如果所有的殘冠長者都活著，對我們的氏族而言將會是個天大的好訊息。','轉至沙納爾廢墟，尋找納拉杜的下落。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10404 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10404,'zhTW','對抗軍團','我們當前已經獲悉，燃燒軍團向凱爾薩斯提供了大量的技術援助，這已經使凱爾薩斯的威脅等級提高了數倍。$B$B然而，由於燃燒軍團在這一地區部署的軍隊實在太多了，我們所能對敵人造成的最大打擊，恐怕也只有直接正面進攻地域內正北方的兩處鑄魔營地了。立刻轉至鑄魔基地：煉獄和鑄魔基地：湮滅，消滅那裡所有的敵人。願聖光指引著劍的方向，$N。','在52區的主教歐瑞利斯要你去熔爐基地:遺忘和熔爐基地:苦難，並殺掉12個甘納格鍛造黑手，6個莫阿格鍛造王和6個憤怒使者。$B$B為奧多爾完成任務會使你的占星者聲望降低。','','去找大主教歐雷里斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10405 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10405,'zhTW','破壞行動','我們必須摧毀將復仇軍的虛靈變異為節點獵手的特殊機器。但是這種機器是虛靈科技的產物，直接破壞原質加速器根本不起作用。我們得破壞那些傳輸魔法能量的管道。$B$B眼下還缺一份材料，沒有它，我無法制造能使管道能量超負荷的裝置。為了校準這臺裝置，我要你從尚未變異的虛靈執政官或主宰身上拿來他的裹布。','復仇軍前沿基地中的復仇軍發射器 - 塞塔所投射出來的指揮官阿米爾的影像要你帶回1條精製復仇軍裹布。','','去虛空風暴的復仇軍前沿基地用復仇軍發射器塞塔找到指揮官阿米爾的影像。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10406 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10406,'zhTW','傳達資訊','我打算派一名爆破師去放置擾流器。希望你能在他安裝擾流器時保護他。$B$B一定要確保他的安全！他\\r\\n會以全息影像的形式執行這項任務，因此遭到攻擊時他根本無法反抗，但是全息影像是可以被摧毀的！$B$B完成任務後回來向我覆命。','復仇軍前沿基地中的復仇軍發射器 - 塞塔所投射出來的指揮官阿米爾的影像要你護送維序派爆破師轉至法力熔爐：烏提斯的管道，並在他破壞時保護他的安全。','破壞復仇軍管道','去虛空風暴的復仇軍前沿基地用復仇軍發射器塞塔找到指揮官阿米爾的影像。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10407 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10407,'zhTW','索克雷薩之影','索克雷薩，這個聲名狼藉的艾瑞達人統領著整個虛空風暴的燃燒軍團部隊。單是提起他的名字，就足以令大多數德萊尼人嚇得發抖。索克雷薩駐紮在西北方的某座浮島上，只有他最信任的軍官才有資格與他會面。$B$B你必須奪得傳送石才能進入那座浮島，這可不是件容易的事。傳送石的上半部在鑄魔基地：湮滅的熔爐主管莫魯格手中，而下半部則由鑄魔基地：煉獄的希爾洛斯保管。','52區的學者卡爾亞要你從鑄魔基地：湮滅的熔爐主管莫魯格手中奪得索克雷薩之石的上半部，並從鑄魔基地：煉獄的希爾洛斯手中奪得索克雷薩之石的下半部。$B$B為奧爾多完成任務將降低你在占星者陣營中的聲望等級。','','去虛空風暴找52區的學者卡爾亞。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10408 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10408,'zhTW','節點之王薩哈達爾','我這裡還有一個擾流器，它能摧毀環繞著薩哈達爾的三根管道。一旦管道盡數被毀，薩哈達爾身上的保護力場就會消失。$N，那樣的話，他會爆發出你前所未見的狂暴力量，你將與他展開激烈的戰鬥。$B$B如果你決意要剷除薩哈達爾，我就將這個擾流器交給你。','復仇軍前沿基地的復仇軍發射器 - 塞塔中投射出來的指揮官阿米爾的影像要你使用維序派擾流器關閉薩哈達爾防禦力場，然後殺死節點之王薩哈達爾。','','去虛空風暴的復仇軍前沿基地用復仇軍發射器塞塔找到指揮官阿米爾的影像。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10409 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10409,'zhTW','重創燃燒軍團','在面對擁有強大力量的艾瑞達人時，以數量制勝恐怕是無稽之談。他們的腐蝕力足以令凡人迅速墮落，只有意志最堅定的勇士才敢於面對這種挑戰。$B$B召集你最親密和最優秀的戰友，帶上這塊傳送石，轉至位於鑄魔基地：湮滅和鑄魔基地：煉獄之間的登陸場：霸王。歐雷里斯和卡爾亞會在索克雷薩之座等你，我還會派阿德因一同去幫助你。$B$B聖光必勝，$N！讓索克雷薩消亡吧！','高階祭司伊沙娜要你轉至虛空風暴西北角的軍團傳送控制器，利用它傳送到索克雷薩之座，然後擊敗索克雷薩。$B$B為奧爾多完成任務將降低你在占星者陣營中的聲望等級。','重創燃燒軍團','去撒塔斯城找奧爾多高地的伊沙娜。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10410 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10410,'zhTW','伊沙娜的幫助','是時候面對索克雷薩了，$N。對我們來說，挑戰艾瑞達人的領袖並不是一件容易的事。如果準備得不夠妥當，那麼任何微小的錯誤都會讓我們付出生命的代價。$B$B帶上索克雷薩的傳送石，轉至撒塔斯城的永恆聖光神殿，去找高階祭司伊沙娜。她會告訴我們要如何應對當前的情況。','返回撒塔斯城奧爾多高地的永恆聖光神殿，將索克雷薩的傳送石交給高階祭師伊沙娜。$B$B為奧爾多完成任務將降低你在占星者陣營中的聲望等級。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10411 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10411,'zhTW','電磁衝擊！','你在法力熔爐的廢墟四周可以發現大量從迪門修斯體內滲透出的流質。滴水的淤泥怪已經佔據了烏提斯外圍的池塘，池塘正下方就是復仇軍的前線基地，基地中到處都是一種名叫空靈廢棄者的流質生命體。$B$B要對付這些軟泥怪，最好的辦法就是用電磁衝擊槍將它們轟成小水珠。利用這瓶藥劑強化你的電流攻擊能力吧，如此一來，那些軟泥怪就會衰變成原始的形態。消滅那些水珠！','虛空風暴維序派哨站的研究員納烏德要你摧毀30只空靈廢棄者水珠和30只滴水的淤泥怪水珠。','','去虛空風暴找維序派哨站的研究員納烏德。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10412 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10412,'zhTW','火翼徽記','凱爾薩斯·逐日者已將我們視為一個巨大的威脅，這早就不再是什麼秘密了。讓我們勇敢地面對他們吧，並不是所有銀月城的辛多雷都願意追隨凱爾薩斯的。$B$B此外，我們與凱爾薩斯·逐日者之間的衝突也早已不只停留在文字與紙面上，這也不是秘密了。現在，占星者與凱爾薩斯的軍隊只要一見面就會交戰。而你唯一向我們證明自身價值的方式，就是讓我們分享你的力量，$N。$B$B凱爾的低階追隨者身上都帶有用於標識其階級的火翼徽記。將它們帶回來給我。','撒塔斯城的魔導師菲亞琳要求你給她帶回10個火翼徽記。$B$B為占星者完成任務將會使你在奧爾多陣營中的聲望等級降低。','','去找泰羅卡森林的魔導師菲亞琳。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10413 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10413,'zhTW','虛空的軟泥','你小心地將虛空軟泥留下的泥漿裝入瓶中。$B$B維序派哨站的研究員納烏德一定會對此感興趣的！快把這瓶虛空軟泥帶給他吧！','將一瓶虛空軟泥交給虛空風暴維序派哨站的研究員納烏德。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10414 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10414,'zhTW','單枚火翼徽記','','','','去找泰羅卡森林的魔導師菲亞琳。','','','','',0);
