INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10455, 'zhTW', '失控的侵略', '我們已經加快了種植生命之林的速度，但不知為何那裡的山貓失去了控制。$B$B曾經他們的數量很穩定，但現在森林山貓卻開始侵犯希爾瓦納，而且不久前才發生一連串令人不快的事件。$B$B我懷疑是迷霧拉斯的阿拉卡在背後搞鬼，但目前的問題是與山貓本身有關。$B$B我會很感謝要是你肯幫助我們解決這個問題。', '琳娜·月泉要你以最快的速度殺掉12隻森林山貓後回到劍刃山脈的希爾瓦納找她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10456 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10456, 'zhTW', '巡邏的狼群', '這些卑鄙的部落種族已經在東邊落腳了。他們帶來了一大隊可怕的恐狼用來作為坐騎及守衛。$B$B這些守衛已經進犯過這座橋隔開了我們。他們一直在偷襲我們生命之林授粉的關鍵生物，精靈龍。$B$B使用東邊的出口穿越血槌深谷的橋樑到東邊的鋸齒山脊去，並將他們的尾巴帶來作為證明!', '琳娜·月泉要你帶給她4根雷霆王恐狼尾。完成後，回到劍刃山脈的希爾瓦納找她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10457 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10457, 'zhTW', '保護我們自己', '雖然你對於保護我們這裡的新家提供了很大的幫助，但我還是覺得生命之林需要更多的防護。$B$B拜託，帶著這個我施放了自然之力的小樹枝。使用在我栽種的樹叢幼苗身上時，就會出現一股暴風雨加快樹人防衛者的成長速度。$B$B這些樹人是這個樹叢的防禦關鍵，特別是如果你不打算把希爾瓦納當成你長久的家。', '在5株果樹幼苗身上使用琳娜的樹枝以召喚今後生命之林的防護者。完成後回到劍刃山脈的希爾瓦納找琳娜·月泉。', '', '', '生命之林防衛者召喚', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10458 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10458,'zhTW','憤怒的火靈和地靈','我們必須設法挽救現在的局面。跟這片區域的元素溝通，看看有什麼補救措施！$B$B$r，我將靈魂圖騰交給你。如果你在圖騰附近殺死暴怒的元素之靈，靈魂圖騰將吸收它們的靈魂。使用圖騰吸收元素生物的靈魂，然後向我覆命。$B$B首先對付火之靈和土之靈吧，將裝滿土之魂和火之魂的靈魂圖騰交給我。','使用靈魂圖騰俘獲8個土之魂和8個火之魂，然後向影月谷詛咒祭壇的大地治癒者託洛克覆命。','','去影月谷找詛咒祭壇的大地治癒者託洛克。','捕獲土之魂','捕獲火之魂','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10459 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10459,'zhTW','塞納里奧遠征隊的崇敬','$N，你取得的成就，我們有目共睹。你所做的完全超出我們的預想。$B$B我有一項特殊的請求，但是在那之前，我必須考驗你對塞納里奧遠征隊的忠心。','塞納里奧庇護所的伊謝爾·風歌要求你在塞納里奧遠征隊中達到崇敬聲望。','','','','','','',0);
