INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10476,'zhTW','強悍的敵人','想要證明你對我們的忠誠，就勇敢地與我們的敵人作戰吧。$B$B殘忍野蠻的食人魔是塔拉最大的威脅。因此，如果你想證明自己的實力，就把他們脖子上的作戰念珠帶回來給我。我會將你的功績告訴氏族其它成員的。','塔拉的監護者莫布吉爾要你從納格蘭的食人魔身上收集10串黑曜石作戰念珠。','','去納格蘭找塔拉的監護者莫布吉爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10477 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10477,'zhTW','更多作戰念珠','','','','去納格蘭找塔拉的監護者莫布吉爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10478 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10478,'zhTW','更多作戰念珠！','','','','去納格蘭找加拉達爾的監護者布羅克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10479 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10479,'zhTW','證明你的力量','平靜的生活誰不向往？可是我們不得不面對許多敵對勢力的挑戰。殘忍野蠻的食人魔是加拉達爾最大的威脅。$B$B如果你想證明自己的實力，就把他們脖子上的作戰念珠帶回來給我。我會將你取得的成就告訴氏族其它成員的。','加拉達爾的監護者布羅克要你從納格蘭的食人魔身上收集10串黑曜石作戰念珠。','','去納格蘭找加拉達爾的監護者布羅克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10480 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10480,'zhTW','憤怒的水靈','這個地區的納迦控制著影月谷唯一干淨的水源。$B$B此地正北方便是納迦的老巢庫斯卡。那裡周圍分佈著許多小水窪，水面劇烈地翻騰著，彷彿在對大地發出陣陣痛苦的哀嚎。暴怒的水靈就在水窪附近遊蕩。$B$B轉至庫斯卡，使用靈魂圖騰俘獲水之魂。那些水靈大多聚集在庫斯卡水池。','使用靈魂圖騰俘獲5個水之魂，然後向影月谷詛咒祭壇的大地治癒者託洛克覆命。','','去影月谷找詛咒祭壇的大地治癒者託洛克。','捕獲水之魂','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10481 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10481,'zhTW','憤怒的氣靈','英雄，往東南方前進吧。當你看見大片破土而出的巨型藍色水晶時，就說明你的目的地靈翼平原到了。暴怒的空氣之靈在平原四周的懸崖和山嶺附近遊蕩。$B$B殺死這些被折磨的元素生物，使用靈魂圖騰俘獲氣之魂。完成任務後回來向我覆命。','使用靈魂圖騰俘獲10個氣之魂，然後向影月谷詛咒祭壇的大地治癒者託洛克覆命。','','去影月谷找詛咒祭壇的大地治癒者託洛克。','捕獲氣之魂','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10482 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10482,'zhTW','邪獸人清理者','噬骨清理者躲藏在荒廢的城垛上，窺視著榮耀之路的動向。我們相信，這幫邪獸人正在替地獄火堡壘中的主子收集戰爭機器的元件——必須阻止他們！$B$B$N，榮耀堡北邊聚集了大批噬骨獸人。去殺死他們！但是不可掉以輕心，雖然噬骨獸人是邪獸人氏族中不起眼的一支，但是他們的力量跟那些綠皮獸人不相上下……','殺死20個噬骨獸人，然後向榮耀堡的阿曼蒂覆命。','','去地獄火半島找榮耀堡的阿曼蒂中尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10483 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10483,'zhTW','邪惡的咒語','$N，在與血環邪獸人交戰時，我們發現他們身上佩戴著某種不祥的飾物。那些邪獸人從榮耀堡士兵的屍體上取下徽章，製作成被詛咒的護符。我們擔心血環獸人利用黑暗魔法將我們的徽章變成了咒符，還用來對付我們！$B$B轉至榮耀堡以東的塞斯高，從血環獸人手中奪得一枚被詛咒的護符，然後將它交給塞斯高東北方遠征軍崗哨的埃隆雷下士。','榮耀堡的阿曼蒂中尉要你轉至遠征軍崗哨，將1枚被詛咒的護符交給埃隆雷下士。','','去地獄火半島找遠征軍崗哨的埃隆雷下士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10484 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10484,'zhTW','被詛咒的護符','$N，我們絕對不能讓血環獸人繼續利用被詛咒的護符！你必須替我們奪回護符，讓那些犧牲的榮耀堡士兵們得到應有的尊重。$B$B轉至血環獸人被詛咒的據點塞斯高，執行這項艱鉅的任務……集齊護符後返回榮耀堡向我覆命。','將12枚被詛咒的護符交給遠征軍崗哨的埃隆雷下士。','','去地獄火半島找遠征軍崗哨的埃隆雷下士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10485 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10485,'zhTW','血環督軍','你能夠幸運地從塞斯高安然返回，足以證明你具備優秀的作戰能力！現在，我有一項艱鉅的任務要交給你，希望這次好運氣還能伴隨你……$B$B督軍摩爾肯坐鎮於塞斯高的兵營，指揮著他的邪獸人軍團與我們作戰。他的戰術靈活而殘忍，我必須承認，他重挫了我軍計程車氣。因此，$N，我命令你除掉摩爾肯。將他的護甲帶回來，我要將它放在這兒示眾，鼓舞軍中的將士。','把督軍摩爾肯的破碎護甲交給遠征軍崗哨的埃隆雷下士。','','去地獄火半島找遠征軍崗哨的埃隆雷下士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10486 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10486, 'zhTW', '失控的侵略', '在雷霆王被曼諾洛斯之血轉化成魔獄獸人前他們曾是一個驕傲的獸人氏族。$B$B最近我們從污染下游河谷的巨魔手中重新發現了這個獸人村落。他們在雷霆王氏族遺棄這裡後進駐。$B$B我們要保住這個地方，而我需要你來幫忙。$B$B在鋸齒山脊的南方及西方，那裡有一群放血者已經變成我們的災難。他們不停地繁殖。$B$B殺掉他們並於完成後回來找我。', '葛德雷克要你去殺掉12個刃翼血信。完成後回到劍刃山脈的雷霆王村找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10487 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10487, 'zhTW', '龍的粉末', '聯盟最近進駐西邊，使用他們精靈法術在短期內建立一個城鎮及果園。我們得將她們的防禦削弱以防她們不會也生出勇氣來。$B$B我有個方法可以達成目的甚至更好。我要你越過橋到西南方去，經過血槌深谷進去生命之林。$B$B攻擊她們在生命之林的精靈龍防禦並將在它們翅膀中找到的魔法粉塵帶回來給我。', '葛德雷克要你去取得4份精靈龍粉末。完成後，回到劍刃山脈的雷霆王村找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10488 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10488, 'zhTW', '保護我們自己', '有了你帶回的魔法粉塵，我製作了一個魔法藥膏可助於我們本身的防護。$B$B我們的恐狼完美的將坐騎，守衛及朋友集結於一身，但是那些聯盟的人渣在鋸齒山脊那獵殺它們。$B$B$N，我要你將這個藥膏使用在我們那些恐狼朋友身上。下一次聯盟再派他們的獵殺團隊來時就會得到一個野蠻的驚喜。$B$B要小心還是有一些狼可能不喜歡這個藥膏，將會反咬你。', '在5隻雷霆王恐狼身上使用葛德雷克的藥膏來強化它們及鋸齒山脊的防禦。完成後回到劍刃山脈的雷霆王村找葛德雷克。', '', '', '強化雷霆王恐狼', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10489 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10489, 'zhTW', '砍伐古老之樹', '懸賞!$B$B斯卓霖普·深根，戰爭古樹及希爾瓦納南方的生命之林防衛者領袖。$B$B往西邊過了橋後越過血槌深谷就可以找到他。$B$B將他的大箱帶回給雷霆王村旅館內的吐查克·雙爪。', '取得斯卓霖普·深根的樹幹並送到劍刃山脈的雷霆王村給吐查克·雙爪。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10490 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10490,'zhTW','水之召喚','自你上一次接受考驗之後已經過去一段時間了。預言者努波頓想讓你去見他。$B$B你的智慧在過去的這段時間裡是否有長足的提高？因為你被召喚的原因，是要去了解水元素的秘密。$B$B我相信你一定還記得怎樣去卡利姆多大陸的黑海岸地區，乘坐奧伯丁的航船回艾克索達吧？你也一定記得先知在艾克索達水晶大廳的什麼位置，對吧？','與艾克索達水晶大廳的預言者努波頓談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10491 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10491,'zhTW','空氣的召喚','$N， 預言者努波頓再次希望你去見他。是時候讓你去了解最後一種元素——空氣的奧秘了！$B$B我希望你知道，我對你當前為止所有的表現都非常滿意。相信接下去你會做得更好。$B$B在卡利姆多黑海岸的奧伯丁乘船，穿過迷霧之海，到秘藍島的艾克索達城中去，預言者就在水晶大廳裡。','與艾克索達水晶大廳中的預言者努波頓談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10492 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10492,'zhTW','熱心的建議','你好，$c。我這裡有一些你可能會很感興趣的東西。$B$B它跟你們這個職業的人平常穿著的那些護甲有點類似，但質量上遠遠好於你們現在所擁有的。要是你能幫我一個小忙的話，我願意拿它來從你手裡換一件普通的套裝元件。$B$B棲息在冬泉谷的霜刃豹和熊身上的血液有著某種我當前很需要的特性。給我帶來一批樣本，再把普通套裝的手腕部分拿來，當然了，你還得支付一些金幣。你會發現這其實是筆很划算的交易。','將15份冬泉谷血樣、20枚金幣以及一副元素護腕交給鐵爐堡的德莉亞娜。','','去鐵爐堡找王座廳的德莉亞娜。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10493 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10493,'zhTW','熱心的建議','嗨，$C！從你的言行舉止就能看出你是個歷經滄桑、見多識廣的傢伙。但是我打賭你沒有見過這麼一件護甲。$B$B要是你能幫我一個小忙的話，我願意拿它來從你手裡換一件普通套裝的手腕部分。$B$B我需要大量生活在希利蘇斯地區的蠍子和蜘蛛的毒液。把毒液樣本帶給我，再支付一些金幣，我就跟你交換。','將15份希利蘇斯毒液樣品、20枚金幣以及一副光鑄護腕交給奧格瑪的莫克瓦爾。','','去找奧格瑪的莫克瓦爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10494 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10494,'zhTW','小小的補償','你做到了你所承諾的事，把穆克斯製造的裝備給我帶了回來，那麼我也按承諾給予你一件不錯的獎勵。把你原先使用的腰帶和手套拿來吧，我會幫你升級它們。我敢保證，新的裝備會比原來的好得多。','將一條元素腰帶和一副元素護手交給鐵爐堡的德莉亞娜。','','去鐵爐堡找王座廳的德莉亞娜。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10495 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10495,'zhTW','小小的補償','你已經證明了自己是個非常守信譽的$r，$N。我堅信你能夠幫我走出當前的困境，當然我也會根據你的表現給予你一些獎勵。$B$B現在我可以幫你更換腰帶和手套，如果事情進展順利，我會繼續幫你升級其它的部件。','將一條光鑄腰帶和一副光鑄護手交給奧格瑪的莫克瓦爾。','','去找奧格瑪的莫克瓦爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10496 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10496,'zhTW','告別安泰恩','瓦塔拉克的靈魂就封印在這枚護符裡。因為貪婪，我們愚蠢地將它分成了好幾部分，絲毫不瞭解這會為我們帶來怎樣殘酷的詛咒。$B$B唯一解除瓦塔拉克的法術的辦法，就是將這枚勳章重新組合在一起。回到德莉亞娜那裡去，告訴她說，伯德雷已經是她找齊剩餘部分的最後希望了。順便跟她提一下你應得的報酬。$B$B我只希望能從此安息。祝你好運……你會非常需要運氣的！','帶上一雙元素長靴、一條元素護腿和一副元素護肩，回去向鐵爐堡的德莉亞娜覆命。','','去鐵爐堡找王座廳的德莉亞娜。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10497 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10497,'zhTW','告別安泰恩','瓦塔拉克的靈魂就封印在這枚護符裡。因為貪婪，我們愚蠢地將它分成了好幾部分，絲毫不瞭解這會為我們帶來怎樣殘酷的詛咒。$B$B唯一解除瓦塔拉克的法術的辦法，就是將這枚勳章重新組合在一起。回到莫克瓦爾那裡去，告訴他說，伯德雷已經是他找齊剩餘部分的最後希望了。順便跟他提一下你應得的報酬。$B$B我只希望能從此安息。祝你好運……你會非常需要運氣的！','帶上一雙光鑄戰靴、一條光鑄腿鎧和一副光鑄肩鎧，回去向奧格瑪的莫克瓦爾覆命。','','去找奧格瑪的莫克瓦爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10498 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10498,'zhTW','最後的獎賞','這真是個令人驚異的故事，$N！我實在是太感謝你了，其它一些與此有關的人也會對你表示真心誠意的感激。或許今天晚上我就能睡個安穩覺了。$B$B這兒還有些你絕對會很喜歡的東西，送你算作獎勵吧。','將你的元素罩帽與元素外衣交給德莉亞娜。','','去鐵爐堡找王座廳的德莉亞娜。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10499 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10499,'zhTW','最後的獎賞','確實是個令人驚異的故事，$N！我實在是太感謝你了，其它一些與此有關的人也會對你表示真心誠意的感激，這一點我向你保證。你的努力使我們終於認識到了自己過去所犯的錯誤。$B$B這兒還有些你絕對會很喜歡的東西，送你算作獎勵吧。','將你的光鑄頭盔與光鑄胸甲交給莫克瓦爾。','','去找奧格瑪的莫克瓦爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10500 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10500,'zhTW','部落需要你的幫助！','你好，我很高興你願意聽我說話。部落需要一切可以獲得的幫助來準備發動安其拉戰爭，這意味著，我們需要你！現在，官方的資源收集者正在收集必需的資源儲備，但是如果沒有你的幫助的話，我們是無法達成目標的，$N！$B$B你應該和負責此事的督軍格爾庫克談一談。你覺得怎麼樣？你是否願意幫助部落做好戰爭的準備？','和奧格瑪精神谷的督軍格爾庫克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10501 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10501,'zhTW','聯盟需要你的幫助！','你好，我很高興你願意聽我說話。聯盟需要一切可以獲得的幫助來準備發動安其拉戰爭，這意味著，我們需要你！現在，官方的資源收集者正在收集必需的資源儲備，但是如果沒有你的幫助的話，我們是無法達成目標的，$N！$B$B你應該和負責此事的大元帥斯諾·落雪談一談。你覺得怎麼樣？你是否願意幫助聯盟做好戰爭的準備？','和鐵爐堡軍事區的大元帥斯諾·落雪談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10502 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10502, 'zhTW', '血槌巨魔', '希爾瓦納有一個比雷霆王村的部落還要致命的威脅。$B$B我說的是居住在這些山區中的巨魔。這裡的南邊還有東邊，深谷的底部住著血槌氏族。雖然他們並不是唯一威脅我們的巨魔氏族，他們卻是最靠近我們的一族。$B$B我要你往南穿過生命之林，然後轉向東邊的道路前往他們的前哨站。在血槌前哨站盡可能的殺光那些血槌巨魔。', '指揮官天影要你去血槌前哨站殺死30個血槌巨魔。當你完成這個可怕的任務後，回到劍刃山脈的希爾瓦納向他回報。', '', '', '殺死血槌巨魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10503 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10503, 'zhTW', '劍刃的威脅', '雷霆王村有一個比希爾瓦納的聯盟還要可怕的威脅。$B$B我說的是居住在這些山區中的巨魔。這裡的西邊，深谷的底部住著劍刃氏族。雖然他們並不是唯一威脅我們的巨魔氏族，他們卻是最靠近我們的一族，當初我們就是打敗他們才佔領這個地方。$B$B往北越過鋸齒山脊，然後順著路往下走，你就會到達他們的要塞。在劍刃要塞還有劍刃庭園盡可能的殺光那些劍刃巨魔還有劍刃迅猛龍。', '吐查克·雙爪要求你在劍刃要塞還有劍刃庭園殺死30個劍刃巨魔還有10隻劍刃迅猛龍。任務完成時回到劍刃山脈的雷霆王村向他回報。', '', '', '殺死劍刃巨魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10504 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10504, 'zhTW', '劍刃巨魔', '血槌氏族的北邊有一個更嚴重的威脅:劍刃要塞。$B$B這些劍刃巨魔是山區之中最強的氏族，受到被稱為弒龍者戈魯爾的古羅還有他的七個兒子所支持。$B$B現在我們已經解決了血槌氏族，是時候該轉移目標到他們的競爭對手了。$B$B從血槌要塞往北穿過深谷直到你到達劍刃要塞還有劍刃庭園。盡可能殺光裡頭的劍刃巨魔。', '指揮官天影要你在劍刃要塞還有劍刃庭園殺死30個劍刃巨魔。任務完成時回到劍刃山脈的希爾瓦納向他回報。', '', '', '殺死劍刃巨魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10505 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10505, 'zhTW', '血槌巨魔', '在劍刃氏族的南方還有另外一個威脅:血槌前哨站。$B$B雖然血槌巨魔不是這些山區中最強的氏族，不受名為弒龍者戈魯爾的古羅厚愛，不過他們緊接在第二名。$B$B現在我們已經解決掉劍刃氏族，是時候轉移焦點對付他們的對手了。$B$B從劍刃要塞往南經過深谷一直走直到你到達血槌前哨站為止。盡你所能的殺光附近的血槌巨魔。', '吐查克·雙爪要你在血槌前哨站殺死30個血槌巨魔。任務完成時回到劍刃山脈的雷霆王村向他回報。', '', '', '殺死血槌巨魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10506 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10506, 'zhTW', '情況緊迫', '因為狼群的減少，部落正在尋找代替品。不幸的是附近剛好有可替代的狼。$B$B在東邊深谷下方的血槌巨魔養了一大群強壯的狼作為他們自己的守衛。我不想派你去殺掉那些恐狼，那麼為何這次我們不做點不同的呢?$B$B我已經由精靈龍的翅膀所自然落下的粉塵中提煉出一種魔法粉末。將它灑在那些恐灰狼的身上使部落對他們失去興趣。', '琳娜·月泉要你帶著她的縮小粉末並使用在5隻血槌恐狼身上，你可以在血槌前哨站及血槌深谷找到這些狼群。完成後，回到劍刃山脈的希爾瓦納找她。', '', '', '削弱血槌恐狼', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10507 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10507,'zhTW','轉折點','$N，我們一直在等待這樣的機會。凱爾薩斯與燃燒軍團私下勾結的陰謀已經敗露，現在你要拿起武器，擊敗凱爾的新主子——索克雷薩。$B$B我的健康狀態不允許我親自上陣，無法與你並肩作戰真是遺憾。我將這顆寶珠交給你，它能聚集我全部的能量，幫助你擊敗索克雷薩。','轉至位於鑄魔基地：湮滅以北的登陸場：霸王，使用索克雷薩的傳送石將你的小隊傳送到索克雷薩之座。利用沃雷塔爾的寶珠擊敗索克雷薩。$B$B為占星者完成任務將降低你在奧爾多陣營中的聲望等級。','','去泰羅卡森林找占星者之臺的先知沃雷塔爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10508 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10508,'zhTW','給沃雷塔爾的禮物','我可不想讓你兩手空空去見沃雷塔爾，低調不是我做事的風格。$B$B想要進入北邊的索克雷薩之座，我們就必須使用索克雷薩的傳送器，而只有他的傳送石才能啟動傳送器。鑄魔基地：湮滅的熔爐主管莫魯格掌管著索克雷薩之石的上半部，索克雷薩之石的下半部則由鑄魔基地：煉獄的希爾洛斯保管。$B$B奪得索克雷薩之石的上半部和下半部，沃雷塔爾必定會驚訝得說不出話來。','52區的間諜大師薩羅迪恩要你從鑄魔基地：湮滅的熔爐主管莫魯格手中奪得索克雷薩之石的上半部，並從鑄魔基地：煉獄的希爾洛斯手中奪得索克雷薩之石的下半部。$B$B為占星者完成任務將降低你在奧爾多陣營中的聲望等級。','','去虛空風暴找52區的間諜大師薩羅迪恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10509 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10509,'zhTW','無上的榮耀','現在我可以派你回撒塔斯城了。你已經掌握了凱爾薩斯與燃燒軍團結盟的證據，並且奪得了通往索克雷薩之座的鑰匙。$B$B不過你得看著點沃雷塔爾，別讓他太激動——他年歲已高，恐怕經不起這麼震撼的訊息，你應該懂我的意思。去占星者之臺的先知圖書館找他吧。','將索克雷薩的傳送石交給撒塔斯城占星者之臺的先知沃雷塔爾。$B$B為占星者完成任務將降低你在奧爾多陣營中的聲望等級。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10510 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10510, 'zhTW', '進入德萊尼礦坑', '看到有人願意幫助這裡真的是太好了!$B$B波爾葛利姆和我是探險者協會的一員，我們到這是要知道我們能從這些山中得到什麼。我們聽過各種不同的傳說，我等不及要紮營開始探險。$B$B有一個東西特別吸引了我的注意力。夜精靈提到東邊深谷下面有個地方叫做德萊尼礦坑。就在血槌前哨站的南方盡頭。我想要那邊土生土長的一些水晶。', '波爾葛利姆·頑錘要你去收集5個德萊尼礦坑水晶然後回到劍刃山脈的希爾瓦納找她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10511 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10511, 'zhTW', '怪酒', '如果我要現在就開始這個假期，那麼我就需要更多的酒。不幸的是，這些精靈們根本不懂發酵的藝術。$B$B我偶然聽到深谷那邊的血槌巨魔有很多的酒。我想要試看看。$B$B幫我個忙吧?往南方出發經過生命之林，接著下了斜坡往東進入血槌前哨站帶幾瓶酒給我?我聽說他們有幾大桶的酒就放在附近而釀酒大師會帶著酒到處提供給所有的巨魔。', '波爾葛利姆·頑槌要你拿到11瓶血槌蠻禁烈酒給他。一旦你完成後，將這個帶到劍刃山脈的希爾瓦納給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10512 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10512, 'zhTW', '灌醉劍刃巨魔', '我不會再嚐一口那個難聞的穢物!不過這倒是給了我一個點子。$B$B<波爾葛利姆眼中閃了一下。>$B$B計畫是這樣的。我們知道那些血槌氏族實際上每天都要牛飲這些東西。但我好奇他們的敵人，劍刃巨魔，是怎樣想的?$B$B$N，我要你帶著這些剩下的廢物去看看是否能夠讓這些劍刃巨魔喝醉。你可以從血槌前哨站往北通過深谷的地方找到他們。', '帶著這個血槌蠻禁烈酒並試著用來讓5個劍刃巨魔喝醉。如果你成功了，回到劍刃山脈的希爾瓦納找波爾葛利姆。', '', '', '喝醉的劍刃巨魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10513 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10513,'zhTW','歐魯諾克·裂心','$N，我不知道要如何才能掌握元素之靈提到的法術。老實說，我甚至不知道從何下手。$B$B<託洛克凝視著遠方，陷入了沉思。>$B$B嗯……此行可能會毫無收穫，不過這是我們惟一的希望。詛咒祭壇曾有一位獸人長者來訪。我跟他攀談過幾句。據說他隱居在東北方的庫斯卡水池附近的山上。去尋找這位名叫歐魯諾克·裂心的獸人。$B$B我說過，此行可能無功而返。','轉至庫斯卡水池北邊的破碎岩床尋找歐魯諾克·裂心。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10514 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10514,'zhTW','歷經滄桑……','陌生人，我曾歷經滄桑，但是昔日的輝煌已是過眼雲煙。時過境遷，我現在不過是個普通的農夫罷了。$B$B我在農場訓練地獄野豬，教它們從破碎平原的堅硬土壤中掘出影月塊莖。但是，來自東北方的一批剝石者最近不斷襲擊豬圈，搞得我沒辦法收集塊莖。$B$B你願意去北邊的農地幫我採集塊莖嗎？你可以站在影月塊莖露出根鬚的地方吹響這隻哨子，就會有地獄野豬跑來掘出塊莖！','影月谷歐魯諾克農場的歐魯諾克·裂心要你在破碎平原收集10個影月塊莖。$B$B任務完成後把歐魯諾克的野豬哨一併歸還給他。','','去影月谷找歐魯諾克農場的歐魯諾克·裂心。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10515 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10515,'zhTW','嚴厲的教訓','這幫剝石者膽敢冒犯歐魯諾克，我們要給他們點厲害瞧瞧！$B$B我要你返回破碎平原，摧毀貪婪剝石者的卵。它們大多分佈在剝石者的老巢中，因此請千萬小心。','返回破碎平原，摧毀10枚貪婪剝石者的卵，然後向影月谷歐魯諾克農場的歐魯諾克·裂心覆命。','','去影月谷找歐魯諾克農場的歐魯諾克·裂心。','摧毀貪婪剝石者的卵','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10516 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10516, 'zhTW', '復仇者的服飾', '我知道這很怪，但我真的想要待在這個籠子裡。這讓我有絕佳的機會去進行我來這要做的事;收集劍刃氏族的資訊。$B$B我隨時都可以離開，不過我想要取回我的劍跟盾。$B$B他們的兩位領導者擁有我的裝備。卓克嘎姆擁有我的劍而瑪格多克擁有我的盾。$B$B要是你有需要的話，拿著並使用這個來自血槌前哨站的啤酒到南邊去降低他們的防衛並引誘他們兩個，不過要小心他們那些沒喝酒還清醒著的守衛!', '帶回復仇者瓦黎恩之刃及復仇者瓦黎恩之盾。然後將這兩項物品帶回劍刃山脈的劍刃要塞給復仇者瓦黎恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10517 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10517,'zhTW','哥爾迪姆，你的死期到了...','劍刃要塞的領導者叫哥爾迪姆，相信我…這個名字很適合他。$B$B但我不會低估他的，他畢竟成功提升了自己氏族的地位，現在成為弒龍者戈魯爾最信賴的氏族。如今他們支配著這些山脈。哥爾迪姆隨時都有一位隨扈跟在身邊，其中還有滴酒不沾的防衛者。$B$B為了希爾瓦納的安全，我需要你回去解決他。','殺掉劍刃要塞巨魔的首領，哥爾迪姆。','','去劍刃山脈找刀塔要塞的守備官烏里恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10518 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10518, 'zhTW', '插上戰旗', '我要你去從他們的一位勇士身上將劍刃旗幟偷來，帶到南方的血槌前哨站去。將旗插在他們的北槌哨塔上。$B$B這樣會激怒血槌氏族，他們會毫不留情的攻擊你。不過這樣也會將他們的敵意集中在劍刃要塞上，進而遠離希爾瓦納。$B$B在你打倒葛恩·葛羅巴諾斯拿到他的頭盔時就表示你完成任務了。將頭盔帶回希爾瓦納去。$B$B$N，這並不容易。帶一兩個朋友跟你一起去吧。', '在北槌哨塔頂端使用劍刃旗幟來誘引葛恩·葛羅巴諾斯。將旗幟跟葛恩·葛羅巴諾斯的頭盔送到劍刃山脈的希爾瓦納給指揮官天影。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10519 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10519,'zhTW','詛咒密碼 - 真相和歷史','<歐魯諾克變換了站姿，挺直了腰板，身形頓時高大起來。>$B$B$N，我從不做沒把握的事。剛才算是對你的考驗吧，請原諒我現在才顯露真面目。我並不是一位普通的獸人老農。$B$B如果你是為詛咒密碼而來，就先聽聽我的故事吧。等你做好準備，我們就開始吧。','影月谷歐魯諾克農場的歐魯諾克·裂心要你聽聽他的故事。跟歐魯諾克談談，聽這位年老的獸人講述他的故事。','詛咒密碼 - 真相和歷史','去找影月谷歐魯諾克農場的歐魯諾克·裂心。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10520 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10520, 'zhTW', '協助大德魯伊鹿盔', '打擾一下，$c，如果可能的話，我想佔用你一點時間。達納蘇斯的塞納里奧議會希望能找到像你這樣經驗豐富的冒險家來幫助他們進行一項重要的研究項目。雖然我不知道詳細的情況，但是我可以告訴你，正是伊范達爾·鹿盔親自負責這項研究。要是你感興趣的話，請直接去達納蘇斯的塞納里奧區找他談談。', '與達納蘇斯的大德魯伊范達爾·鹿盔談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10521 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10521,'zhTW','格洛姆託，歐魯諾克之子','我的長子格洛姆託轉至正西南方的庫斯卡崗哨去打探詛咒密碼的線索。$B$B他是系列中的戰士，這小子脾氣暴躁、嗜血成性……完全遺傳了他母親的脾氣。去庫斯卡崗哨附近搜尋他的下落。如果你發現了納迦的屍體，那格洛姆託一定就在附近。$B$B找到他後，告訴他：“我們為了正義而揮灑熱血。”這樣，他就會明白你是歐魯諾克的朋友，你也可以避免死於非命。','轉至影月谷的庫斯卡崗哨尋找格洛姆託，歐魯諾克之子。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10522 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10522,'zhTW','詛咒密碼 - 格洛姆託的命令','這是我今天審問的第六個納迦。這傢伙身穿華麗的護甲，想必知道些內情。其它的都是些一無是處的廢物。$B$B<格洛姆託指著地上橫七豎八的納迦屍體。>$B$B我揍了他一頓，他就什麼都說了。$B$B詛咒密碼的第一塊碎片被鎖在庫斯卡崗哨或是庫斯卡水池的某個箱子中，鑰匙就在納迦身上。殺死納迦，奪得鑰匙，取回碎片之後回到我這裡來。','取回詛咒密碼的第一塊碎片，然後向影月谷庫斯卡崗哨的歐魯諾克之子格洛姆託覆命。','','去影月谷找庫斯卡崗哨的格洛姆託，歐魯諾克之子。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10523 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10523,'zhTW','詛咒密碼 - 第一塊碎片','<格洛姆託將詛咒密碼的第一塊碎片捲起來，放入帶鎖的箱子中。>$B$B把這隻箱子交給我的父親。他在東北方的歐魯諾克農場等你。$B$B請轉告他，我玩夠了就會回家，很快的……','將格洛姆託的箱子交給影月谷歐魯諾克農場的歐魯諾克·裂心。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10524 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10524, 'zhTW', '雷霆王氏族手工藝品', '神器上的標記指出它原來是由雷霆王氏族獸人製造的。這些獸人在變成魔獄獸人之前曾住在雷霆王村這。$B$B血錘巨魔曾暫時居住在這個村落直到最近被部落趕走了。你曾經聽說過人們試著尋找其他遺失的神器。你的腦海中浮現關於這些神器的記憶，那是一個鼓、一支箭及一片石板。$B$B到劍刃要塞去找到它們並帶回給洛克嘎·血握。', '取回雷霆王氏族大鼓，雷霆王氏族之箭以及雷霆王氏族石板。將它們隨同雷霆王氏族手工藝品一起帶回，交給劍刃山脈雷霆王村的洛克嘎·血握。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10525 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10525, 'zhTW', '幻象導覽', '$R笨蛋。你差點毀掉這個鼓!$B$B我費盡千辛萬苦來到這裡，直到現在才有所收獲。至少你能夠在別人都失敗，或是更慘的地方成功。$B$B是時候喚出幻象來引領你找到最後一個我一直在找尋的神器。$B$B拿著這個代表我的靈魂的熾熱之魂碎片。用它來將你的身體轉化為火，將你的靈魂變為幻象指引你前往最後發現雷霆王神器的位置。', '使用熾熱之魂碎片將你的靈魂轉化成幻象導覽模式。在你的幻象導覽帶領你找到最後一個雷霆王神器的所在地後，與雷霆王村的洛克嘎·血握談談。', '已發現最後的雷霆氏族神器', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10526 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10526, 'zhTW', '雷霆之矛', '如果那個我讓你看見的幻象屬實，那麼你就得往下到河谷以及血槌深谷的南方盡頭。在那你會找到德萊尼礦坑。$B$B到礦坑的後方去，取得雷霆之矛。不用管其他東西!我對於礦坑內的水晶沒有興趣，還有巨魔也是一樣。$B$B一但你拿到這個矛就馬上帶回來這裡給我!$B$B還有，$N，你要非常小心……我可不願去想要是它有任何損傷的話你會發生什麼事。', '洛克嘎·血握派你去取回雷霆之矛。將它帶回劍刃山脈的雷霆王村給她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10527 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10527,'zhTW','阿托爾，歐魯諾克之子','我的幼子阿托爾轉至伊利達雷崗哨打探詛咒密碼的線索，伊利達雷崗哨在遙遠的西南方，位於軍團要塞和蠻錘要塞之間。$B$B雖然阿托爾箭術精湛、善於追蹤，但此行危機重重，恐怕他也應付不過來。伊利達雷崗哨是伊利丹惡魔大軍的試驗場。那裡到處都是叛離燃燒軍團、投靠背叛者的惡魔！$B$B$N，轉至伊利達雷崗哨尋找阿托爾吧。','轉至影月谷的伊利達雷崗哨尋找阿托爾，歐魯諾克之子。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10528 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10528,'zhTW','惡魔的水晶牢籠','漂浮在半空中的水晶環繞著地面上的神秘符文，水晶射出的能量光束形成禁錮法陣，將阿托爾的屍體困在法陣中央。你試著想要移動這具屍體，卻發現怎麼用力都無濟於事。$B$B你注意到所有的水晶底座上都有一個空槽，或許它們都配有鑰匙吧。附近似乎時不時還有魅魔在舉行某種儀式。$B$B在伊利達雷崗哨尋找魅魔首領的下落，也許她攜帶著解除禁錮法陣的鑰匙。','殺死伊利達雷崗哨的痛苦女王加布莉薩，奪得晶體鑰匙，然後返回歐魯諾克之子阿托爾的屍體旁。','','去影月谷找伊利達雷崗哨的阿托爾，歐魯諾克之子。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10529 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10529,'zhTW','獵人之道','遠行者居所的達恩·晨行者中尉召集所有年輕強壯的獵人去見她。如果你能去找她的話，將對你未來的職業生涯非常有好處，$N。在我們這一行中，她就是智慧的燈塔，照亮著許多獵人前進的道路。$B$B遠行者居所就在銀月城正南方向。','與永歌森林中遠行者居所的達恩·晨行者中尉談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10530 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10530,'zhTW','獵人之道','遠行者居所的達恩·晨行者中尉召集所有年輕強壯的獵人去見她。如果你能去找她的話，將對你未來的職業生涯非常有好處，$N。在我們這一行中，她就是智慧的燈塔，照亮著許多獵人前進的道路。$B$B遠行者居所就在銀月城正南方向。','與永歌森林中遠行者居所的達恩·晨行者中尉談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10531 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10531,'zhTW','阿拉希盆地之戰！','$N，在阿拉希盆地的戰鬥是為了資源和領土而進行的戰鬥。這個地區作戰的關鍵是保證我們軍隊稀有物資和補給的順暢運作。我命令你去攻擊距離我們在阿拉希盆地中的基地最遠的戰略設施。$B$B當農場、礦洞、伐木場或鐵匠鋪被敵人佔據時，攻擊這些設施，找到敵人的旗幟，然後把它拔掉！$B$B當你完成了奪回這四個點的任務之後，就回到我這裡來。','進攻礦洞、伐木場、鐵匠鋪和農場，然後向避難谷地的奧斯萊特元帥覆命。','','去阿拉希高地找避難谷地的奧斯萊特元帥。','突襲礦洞','突襲伐木場','突襲鐵匠鋪','突襲農場',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10532 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10532,'zhTW','切斷阿拉索補給線','阿拉索聯軍正在不惜一切代價進攻阿拉希，並妄圖奪回這個區域。聯盟的各個種族正在全力進軍這塊遙遠的土地，想要將他們的勢力從避難谷地擴張到這裡。我們必須阻止他們，而最好的方式就是奪取他們的資源。$B$B你可以幫助我們，$N。進入阿拉希盆地，那裡遍地都是豐富的礦藏、肥沃的土地和技藝精湛的能工巧匠。佔據並控制你找到的所有基地，贏得戰鬥，然後把你獲得的資源給我拿回來。','進入阿拉希盆地，獲得一箱阿拉希資源箱，然後將它交給落錘鎮的亡靈哨兵莫提斯。','','去阿拉希高地找東部禁錮法陣的亡靈哨兵莫提斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10533 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10533,'zhTW','更多的資源','','','','去找阿拉希高地的亡靈哨兵莫提斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10534 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10534,'zhTW','回家','$R$C……$B$B嗯，之前有位跟你同族的牧師前來拜訪，$N。他說你該返回艾克索達跟凱德莫斯會面。似乎這事兒挺緊急的，我們匆匆聊了幾句他就離開了。','艾克索達的凱德莫斯要你回去與他會面。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10535 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10535,'zhTW','阿拉希盆地的資源！','我們必須依靠我們的士兵進行戰鬥，所有的士兵都會這麼告訴你的。他們還會告訴你，他們正在使用破爛不堪的裝備，飢腸轆轆地開向戰場！$B$B這就是阿拉希盆地顯得非常重要的原因。金屬，武器，食物，木材——所有我們所需要的東西都可以從那裡獲得。$B$B那就是我需要你發揮作用的地方，$N。進入阿拉希盆地，比敵人佔據更多的基地，以此來獲得戰鬥的勝利，然後給我帶回一箱資源來。','獲得阿拉希盆地戰鬥的勝利，獲取一隻阿拉希資源箱，然後向避難谷地的瑪克里爾中士覆命。','','去阿拉希高地找避難谷地的瑪克里爾中士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10536 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10536,'zhTW','更多的資源','','','','去找阿拉希高地的瑪克里爾中士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10537 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10537,'zhTW','洛恩戈魯，裂心之弓','這就是命運，$N，我的靈魂從未停止過抗爭。我必須取回詛咒密碼的第一塊碎片。只要你肯伸出援手，就可以幫我達成這個未遂的心願。$B$B在此之前，請替我取回長弓洛恩戈魯。那是裂心繫列世代相傳的寶物。$B$B直覺告訴我，肯定是某個惡魔擄走了它。殺死崗哨中的惡魔，直到你找到洛恩戈魯。','影月谷伊利達雷崗哨的阿托爾的靈魂要你從駐守崗哨的惡魔手中奪得洛恩戈魯，裂心之弓。','','去影月谷的伊利達雷崗哨找阿托爾的靈魂。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10538 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10538,'zhTW','沸騰之血','上次的實驗不能算完全失敗，至少我保留了一些你帶來的血樣。血液一經煮沸，血環巫師在邪獸人血液中施加的詛咒就能得以消除。$B$B我需要更多的血樣進行研究。從塞斯高的獸人身上收集血環血樣，然後將它們投入被詛咒的大鍋中煮沸，然後把沸騰之血帶回來給我。','將血環血樣投入被詛咒的大鍋中煮沸，然後將12份沸騰之血交給斷背崗哨的藥劑師阿爾布雷克。','','去地獄火半島找斷背崗哨的藥劑師阿爾布雷克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10539 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10539,'zhTW','回家','$R$C……$B$B嗯，之前有位跟你同族的牧師前來拜訪，$N。他說你該返回艾克索達跟凱德莫斯會面。似乎這事兒挺緊急的，我們匆匆聊了幾句他就離開了。','艾克索達的凱德莫斯要你回去與他會面。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10540 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10540,'zhTW','詛咒密碼 - 阿托爾的命令','一切準備就緒。英雄，這是從我的靈魂中抽離出的一塊碎片。它會保護你的安全，幫助你對抗邪惡勢力。$B$B伊利達雷崗哨以南的祭壇附近躲藏著一個名叫維內拉圖斯的怪物。一旦維內拉圖斯出現在靈魂碎片的追蹤範圍內，我的靈魂獵手就會召喚出他來。$B$B殺了維內拉圖斯，取回詛咒密碼的第二塊碎片。','從維內拉圖斯手中奪得詛咒密碼的第二塊碎片，然後向影月谷伊利達雷崗哨的阿托爾的靈魂覆命。$B$B你無法從被靈魂獵手攻擊或殺死的怪物身上獲得物品和經驗值。','','去找蠻錘要塞的阿托爾的靈魂。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10541 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10541,'zhTW','詛咒密碼 - 第二塊碎片','英雄，謝謝你。沒有你的幫助，我的靈魂將永遠禁錮在這個被詛咒的地方。$B$B<阿托爾遞給你一隻帶鎖的箱子。>$B$B把箱子交給我的父親，他住在庫斯卡水池附近的農場，在遙遠的東北方……箱子裡面裝著洛恩戈魯和詛咒密碼的第二塊碎片。$B$B他聽聞我的死訊後必定會非常悲傷。答應我，讓他相信我是在寧靜祥和中離開這個世界的。告訴他我看見了美麗的狩獵場，告訴他我在那兒等他……','將阿托爾的箱子交給影月谷歐魯諾克農場的歐魯諾克·裂心。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10542 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10542, 'zhTW', '他們偷走我的水煙筒和酒!', '提洽里曾經是一個非常友善的食人妖。我來這裡是為了?血槌氏族如何釀造酒。但是如果我這樣做，血槌氏族會埋了提洽里然後讓他的屍體放在這裡腐爛!$B$B最不好的事情是他們偷走了我的水煙筒!$B$B那麼，你想要幫助提洽里嗎?你幫我找回我的水煙筒。提洽里認為偷走它的巨魔往西南方礦坑的礦坑方向去了。$B$B還有當你到那邊的時候，順便撿一些酒!', '取得提洽里的水煙筒還有10份血槌蠻禁烈酒。帶到劍刃山脈交給血槌深谷的巫醫提洽里。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10543 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10543, 'zhTW', '葛瑞諾克和柯爾卡赫，我為你們而來!', '提洽里一直在等待著他復仇的時刻!$B$B他們活埋提洽里讓他自生自滅的那天，就是由葛瑞諾克·巴拓伯恩領導。隔天劍刃氏族的柯爾卡赫到南方發動攻擊的時候踢到提洽里的頭。$B$B我要他們死光光!$B$B你可以在血槌前哨站的南槌哨塔頂端找到葛瑞諾克。柯爾卡赫則在劍刃要塞最北邊的一棟建築物的頂端。柯爾卡赫的身邊有清醒的防衛者，所以你要使用這瓶酒來引誘他離開他們。', '巫醫提洽里要你殺死最令他痛苦的人，葛瑞諾克·巴拓伯恩還有柯爾卡赫。完成後回到劍刃山脈的血槌深谷找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10544 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10544, 'zhTW', '詛咒你們的氏族!', '提洽里要向所有的巨魔復仇!$B$B提洽里在世的時候曾經是一個法力強大的巫醫。假如你去我的墳墓就可以找到邪惡重型神像。$B$B將神像的魔力灌注在劍刃要塞還有血槌前哨站的建築物以及塔的門口。你對他們下的巫毒將會召喚出一個邪惡的靈魂而你必須擊敗它。如此你就可以詛咒他們的建築物。$B$B但是要注意，假如你嘗試去詛咒一個已經被詛咒的建築物，你將會喚出另一個詛咒的靈魂!', '使用邪惡重型神像詛咒5個在劍刃要塞的建築物或者高塔以及血槌前哨站的2個建築物或者高塔。任務完成時回到劍刃山脈的血槌深谷找巫醫提洽里。', '', '', '已詛咒劍刃要塞建築物', '已詛咒血槌前哨站建築物', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10545 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10545, 'zhTW', '劍刃氏族的喝酒大會', '正如提洽里所說，他幫他的血槌朋友釀造酒。但是他卻沒說背後的原因。$B$B血槌氏族正在面對可怕的困境。劍刃氏族快打垮他們了，而他們需要新的武器來幫助戰鬥。$B$B這個時候提洽里想出了一個很棒的方法。為什麼不釀造一種完美的酒，使這種酒可以提高你們的力量同時又削弱敵人的戰鬥力呢?只不過，提洽里不知道這個方法是否能成功。$B$B所以，你必須把這種酒帶到劍刃要塞看它是否有效用!', '提洽里要你使用血槌蠻禁烈酒讓5個劍刃巨魔喝醉。任務完成後回到劍刃山脈的血槌深谷找巫醫提洽里。', '', '', '劍刃巨魔已喝醉', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10546 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10546,'zhTW','伯拉克，歐魯諾克之子','在阿托爾外出狩獵、格洛姆託勤練武藝時，伯拉克卻醉心於學習。最終他成為一名學者，並離家轉至滿目瘡痍的德拉諾世界。數年後，返家的遊子卻已改頭換面。$B$B敏銳的洞察力和靈活的應變性造就了一位沉默寡言的刺客。$B$B他自信滿滿地承擔起最為艱鉅任務：奪回詛咒密碼的第三塊碎片。$B$B轉至南邊的日蝕崗哨尋找伯拉克。他就在崗哨附近的石橋邊。','轉至影月谷的日蝕崗哨附近尋找伯拉克，歐魯諾克之子。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10547 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10547,'zhTW','血薊交易……','要不是我發現了一個重要線索，也許我早就放棄了跟蹤……這傢伙是個血薊癮君子。剛開始我還沒有注意到，後來卻發現種種跡象都指向這一點……$B$B如果我們能弄到血薊，事情就好辦了。$B$B我曾在撒塔斯城遇見一個名叫托比亞斯的破碎者。$B$B托比亞斯跟血精靈有貿易往來，他將血薊賣給血精靈，以換取腐爛的鴉人之卵。$B$B此地正西方就是一片鴉人廢墟。去那裡尋找一枚腐爛的鴉人之卵，然後轉至撒塔斯城的貧民窟找到托比亞斯。','位於日蝕崗哨北面石橋旁的歐魯諾克之子伯拉克要你將一枚腐爛的鴉人之卵交給撒塔斯城中的暴食者托比亞斯。','','去泰羅卡森林找撒塔斯城的暴食者托比亞斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10548 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10548,'zhTW','悲傷的事實','還記得我跟你提過的那個尋找指環的胖商人嗎？這位商人派他那醉心於考古學的兒子外出搜尋古物，可惜此行不順。我的意思是，他掛了，死在了巨魔手裡。$B$B雖然這樣說顯得冷酷無情，不過這位父親願意出重金取回他兒子的徽記。這項任務派你去再適合不過了！$B$B轉至東邊的巨魔廢墟塞布提拉和塞布努瓦，徽記應該就在某個營地的某個箱子裡。','從塞布提拉或是塞布努瓦的某個箱子中取出考古學家的徽記，然後向塔奎林的艾拉蘭覆命。','','去鬼魂之地找塔奎林的艾拉蘭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10549 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10549,'zhTW','REUSE','還記得我跟你提過的那個尋找指環的胖商人嗎？這位商人派他那醉心於考古學的兒子外出尋找古物，可惜此行不順。我的意思是，他掛了，被巨魔砍下了腦袋。$B$B雖然這樣說顯得冷酷無情，不過這位父親願意出重金取回他兒子的腦袋。這項任務派你去再適合不過了！$B$B轉至東邊的巨魔廢墟塞布提拉和塞布努瓦，頭顱應該就在某個營地的某個箱子裡。','塔奎林的依蘭兒要你從札布泰拉還有札布諾瓦其中的一個箱子取得考古學家的皺縮頭顱。','','去鬼魂之地找安達洛斯的艾拉蘭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10550 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10550,'zhTW','一捆血薊','我可沒說謊。這蛋真是美味中的極品。你從哪兒搞到的？$B$B唔，如果你想要更多的血薊，只管來找我，咱們各取所需嘛。$B$B這是你要的一捆血薊。回去找你的頭兒吧。','將一捆血薊交給位於影月穀日蝕崗哨附近石橋處的歐魯諾克之子伯拉克。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10551 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10551,'zhTW','為奧爾多效力','','','','','','','','',0);
