INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10552,'zhTW','為占星者效力','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10553 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10553,'zhTW','先知沃雷塔爾','現在你已經做出了選擇，$N，你需\\r\\n要與占星者的領袖會面。$B$B先知沃雷塔爾就在占星者之臺的先知的圖書館內。$B$B看看你是否能為他做點什麼吧。如果你願意幫助他，他一定會非常高興的。','到撒塔斯城的占星者之臺去，與先知圖書館中的先知沃雷塔爾談一談。$B$B為占星者完成任務將會使你在奧爾多陣營中的聲望等級降低。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10554 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10554,'zhTW','伊沙娜','現在你已經決定站在奧爾多的一邊，你需要向奧爾多的領袖做個自我介紹。$B$B高階女祭司伊沙娜就在永恆聖光神殿裡，去找她吧。','到撒塔斯城的奧爾多高地去，與永恆聖光神殿中的伊沙娜談一談。$B$B為奧爾多完成任務將會使你在占星者陣營中的聲望等級降低。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10555 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10555, 'zhTW', '莫名的不安', '拉斯汗阿拉卡所研究的法術是很邪惡的。他們一手抓滿-還是應該說一爪?-自己身上的羽毛當做施法材料!$B$B我並不覺得那是一種善良的法術。我來這邊是為了研究他們的法術，可惜我無法接近他們。$B$B你可以這樣做:將他們的法術施放在你自己身上，然後回來找我。你必須找到他們的其中一本法術書，位置就在迷霧拉斯的樹林高處。$B$B除非你自己可以長出羽毛，我看是長不出來啦，你就必須取回他們的一些羽毛。', '收集18根掉落的拉斯汗羽毛，然後在迷霧拉斯的樹梢上閱讀拉斯汗書卷。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10556 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10556, 'zhTW', '達成要求', '書中的圖案文字告訴我們要去迷霧拉斯的魔力法陣使用阿拉卡的羽毛才能施展該法術。$B$B令人困惑的圖案看起來像是一個阿拉卡正在為自己注入卡里瑞的精神力量。', '在拉斯汗的法陣使用一把羽毛，然後在卡里瑞的精神退去之前回去找希爾瓦納的達藍艾歐。', '', '', '讓達藍艾歐分析卡里瑞光環', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10557 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10557, 'zhTW', '測試飛行:ZC號', '我製造了一個很棒的裝置，ZC號，我確定他的功能沒有問題，但是……你願意幫我測試它嗎?$B$B傷殘補助金可是很高的喔!$B$B跟我旁邊的雙胞胎兄弟，瑞利談話。祝你好運，$N。測試完畢後回來找我。或者……假如你因為重大傷殘無法回來找我，你的戰友可以來向我回報取得你的報酬。', '跟瑞利·薩普納伯談話然後使用ZC號。回去托斯利基地找塔利·薩普納伯。', '測試塔莉的實驗', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10558 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10558,'zhTW','榮耀堡的崇敬','你向我們證明了你的能力，$N。像你這樣的人總有一天會成為偉大的領袖。$B$B繼續去攻擊破碎大廳的敵人，為你自己在我們的士兵中贏得榮譽。如果你沒有讓我失望，那我就會交給你更重要的任務。','地獄火半島榮耀堡的遠征軍指揮官達納斯·托爾貝恩要求你進入地獄火堡壘的破碎大廳對抗邪獸人，直到你在榮耀堡的聲望達到崇敬。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10559 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10559,'zhTW','索爾瑪的崇敬','你向我們證明了你的能力，$c。但是你還要經受更多的考驗。$B$B繼續攻擊地獄火堡壘破碎大廳的邪獸人，這片土地上所有追隨索爾的部落勇士都會知道你的名字。','地獄火半島索爾瑪的納茲格雷爾要求你進入地獄火堡壘的破碎大廳對抗邪獸人，直到你在索爾瑪的聲望達到崇敬。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10560 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10560,'zhTW','沙塔爾的崇敬','<阿達爾所發出的平和而寧靜的音律略略轉向低沉與憂鬱。>$B$<你的眼前浮現了一座帶有明顯納魯風格的巨大建築，你知道那是風暴要塞，它現在已經被凱爾薩斯的軍隊佔領了。他們還把那裡的強大力量用於某些極端邪惡的目的。阿達爾承諾，在你為奪回風暴要塞做出應有的貢獻之後，將賦予你更重要的使命。>','撒塔斯城的阿達爾希望你通過擊敗風暴要塞內的凱爾薩斯的軍隊，在沙塔爾陣營中達到崇敬聲望。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10561 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10561,'zhTW','時光守護者：崇敬','$r，你已經證明了自己的價值。但是，入侵者依然在設法破壞歷史的程序。$B$B我們需要真正的勇士來維護歷史，你或許能成為這樣的英雄。$B$B繼續打敗企圖改寫歷史的入侵者，你會獲得整個青銅龍族的讚譽。','時光之穴的安多爾姆要求你繼續保護時光之穴中的舊希爾斯布萊德丘陵和黑色沼澤事件，直到你在時光守護者陣營的聲望達到崇敬。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10562 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10562,'zhTW','兵臨城下！','保持警惕，$r。燃燒軍團的攻擊從沒有停止過。$B$B他們當前盤踞在西南方的軍團要塞，每天召喚出的地獄火總能像潮水般朝我們這裡湧來。我們消滅敵人的速度根本就跟不上他們補充兵力的速度。$B$B現在，士兵們個個都精疲力竭，我也不知道他們還能撐多久了。$N，請你向我們伸出援手吧，幫助我們對抗軍團。衝上前線，阻止那些地獄火的攻勢！','蠻錘要塞外的空軍指揮官努埃恩要求你殺死10個地獄火攻擊者。','','去影月谷找蠻錘要塞的空軍指揮官努埃恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10563 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10563,'zhTW','轉至軍團要塞','軍團要塞固若金湯，難以攻取。老實說，我軍也沒有足夠的兵力發動襲擊。$N，所有的希望都寄託在你身上。$B$B從我們當前掌握的零碎情報來看，燃燒軍團正在要塞中囤積和準備他們的地獄火大軍。穿上這套偽裝潛入軍團要塞，打探他們的秘密計劃。$B$B或許你能從燃燒軍團指揮官們的談話中偷聽到一些東西。祝你好運，$N。','轉至軍團要塞尋找軍團通訊裝置。在偽裝狀態下站在軍團通訊裝置附近，偷聽燃燒軍團的計劃。完成任務後向蠻錘要塞的空軍指揮官努埃恩覆命。','','去影月谷找蠻錘要塞的空軍指揮官努埃恩。','','','偷聽燃燒軍團的計劃','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10564 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10564,'zhTW','炸燬地獄火！','我們裝配出來的這玩意雖然其醜無比，但是它能消滅軍團要塞的地獄火大軍。瞧瞧魔能機甲能量核心對惡臭之池的影響，這東西蘊藏的爆炸威力可不容小覷。$B$B如果在軍團要塞的綠色雕文中心引爆這個邪能炸彈，應該可以一舉殲滅所有地獄火。','站在軍團要塞的綠色雕文上使用魔能炸彈消滅地獄火，然後向蠻錘要塞的空軍指揮官努埃恩覆命。','','去影月谷找蠻錘要塞的空軍指揮官努埃恩。','','摧毀軍團要塞的地獄火','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10565 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10565, 'zhTW', '維克尼爾之石', '多年來維克尼爾的阿拉卡一直是我們的眼中釘。他們奉行的是一種奇怪的信仰，指使他們做出瘋狂的行為。他們現在把這種水晶隨身攜帶，使用在不好的地方。$B$B我對他們的儀式有一點了解。他們把水晶拿到他們的法陣將能量注入其中。村裡的人都想了解多一些。伏擊幾個阿拉卡直到你得到水晶為止，將水晶灌滿能量，然後交還給我。', '收集一個維克尼爾水晶並且在維克尼爾的法力之環使用它，然後把充能維克尼爾水晶交給摩克納薩爾村的德托克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10566 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10566, 'zhTW', '錯誤的試驗', '我已經打造了四根魔杖，我相信可以加強阿拉卡的水晶力量。將這些魔杖帶到索格瑪領土，然後使用在巨魔奴隸身上。$B$B你必須從該區的阿拉卡身上取得注入能量的水晶。$B$B當你測試出來哪一根魔杖是最好的，回來找我。', '對一個阿拉卡巨魔奴隸測試每一根德托克的魔杖。每一根魔杖都需要消耗一個灌能維克尼爾水晶。', '', '', '測試第一根魔杖', '測試第二根魔杖', '測試第三根魔杖', '測試第四根魔杖', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10567 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10567, 'zhTW', '製造墜飾', '魯安曠野的阿拉卡依靠著烏鴉神諭使，他們神祇的信使讓他們聚集在一起。$B$B他們相信那些神諭使從天上看著他們，而他們的神則在天上將教義宣揚給信使們，最後信使們從天上下來傳達神的旨意。$B$B神諭使對阿拉卡的靈魂有著非常強的支配能力。他們使用一種魔法的墜飾正好是我們所需要的。$B$B殺死一些阿拉卡並奪取他們的爪子以引起神諭使的注意。把爪子放在他們的祭壇就可以得到信使的注意。', '在魯安歐克神諭者法陣找到6個魯安歐克之爪來召喚1個烏鴉神諭使。殺死它然後將神諭使墜飾交給魯安曠野的泰姆昂。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10568 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10568,'zhTW','巴爾裡石板','影月谷中心的火山正是那位可怕的術士古爾丹數十年前的傑作，也因此，它被命名為古爾丹之手。當初，在這裡的西南方曾有一座名叫巴爾裡的德萊尼村落。火山爆發當日，大多數的村民和許多神聖古器都那場災難中盡數被火山岩漿淹沒，埋入了地底。$B$B最近，一支名叫灰舌的破碎者氏族奉伊利丹之命，在巴爾裡廢墟展開了一系列挖掘工作。他們的目標毫無疑問就是找回那些神器。我們必須利用這個機會奪回巴爾裡石板。據說，那上面記載著許多卡拉波神殿——也就是黑暗神殿的秘密。','沙塔爾祭壇的學者希拉要你收集12塊巴爾裡石板，它們散落在巴爾裡廢墟中，那裡的灰舌工人身上也攜帶著這種石板。$B$B為奧爾多陣營完成任務將降低你在占星者陣營中的聲望等級。','','去影月谷找沙塔爾祭壇的學者希拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10569 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10569,'zhTW','斯克瑟隆廢墟','從斥候帶回的訊息來看，附近那座廢棄的鴉人營地的情形令人堪憂。$B$B鴉人魔法師們陰魂不散，他們擁有的強大力量超出了我們的想象。這些幽靈們似乎在有組織地預謀著什麼，可惜我們對此所知有限。面對潛伏的危機，我們絕不能無動於衷！$B$B從這裡向北走，到死亡熔爐西北方的斯克瑟隆廢墟搜尋線索。','從斯克瑟隆廢墟黑暗教團的鴉人身上奪得斯克瑟隆指揮官的日記 - 第1頁、斯克瑟隆指揮官的日記 - 第2頁，以及斯克瑟隆指揮官的日記 - 第3頁，將它們交給獅鷲騎士基爾蘭。','','去影月谷找蠻錘要塞的獅鷲騎士基爾蘭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10570 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10570,'zhTW','血薊癮君子','<伯拉克接過血薊，放到鼻子下嗅了嗅。>$B$B真刺鼻……$B$B把這包東西放在石橋的另一端。特使每天都會在日蝕崗哨四處巡視；當他發現血薊時，一定會撇下護衛，迫不及待地跑來撿起包裹。你知道，血精靈最瞧不起那些對血薊上癮的傢伙。如果他的族人發現了這一點……$B$B你只需埋伏在一旁，等待特使遣散他的護衛，然後給他致命一擊！殺掉特使，取回他攜帶的信件。','將怒風的信件交給位於影月穀日蝕崗哨附近石橋處的歐魯諾克之子伯拉克。','','去找影月谷的伯拉克，歐魯諾克之子。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10571 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10571,'zhTW','長者奧洛努','根據巴爾裡石板的記載，巴爾裡廢墟中埋藏著一件名為卡拉波勳章的神器。在過去，德萊尼人當中只有最高階的祭司團成員才有資格得到這件神器，從而也獲得了自由進出卡拉波神殿的權利。$B$B我們現在必須查明灰舌破碎者們是否已從廢墟中挖掘出了這枚勳章。這件神器一定可以對我們抵抗伊利丹有所幫助。$B$B現在，駐守在巴爾裡廢墟的灰舌軍官——長者奧洛努每天都會接到他的上司阿卡瑪的書面指令。去把阿卡瑪的命令帶來給我。','沙塔爾祭壇的學者希拉要求你從巴爾裡廢墟的長者奧洛努手中奪得阿卡瑪的命令。$B$B為奧爾多陣營完成任務將降低你在占星者陣營中的聲望等級。','','去影月谷找沙塔爾祭壇的學者希拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10572 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10572,'zhTW','製造炸彈','燃燒軍團意欲在轉至黑暗神殿的行軍途中摧毀蠻錘要塞，我們絕不能讓他們的奸計得逞。$B$B$N，要阻止這場戰事只有一個辦法，那就是使用威力強大的炸彈將軍團要塞的地獄火大軍統統炸燬。$B$B軍團要塞附近有一片惡臭之池，那裡的魔能機甲動力核心可用作炸藥。那些魔能機甲附近另一處廢墟中的魔能機甲護板可用作炸彈外殼。','將魔能機甲動力核心和魔能機甲護板交給蠻錘要塞的空軍指揮官努埃恩。','','去影月谷找蠻錘要塞的空軍指揮官努埃恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10573 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10573,'zhTW','死亡熔爐','從你在軍團要塞查探到的情況來看，暗影議會正在死亡熔爐幫助燃燒軍團製造地獄火。我曾派出偵察小隊去探察死亡熔爐的動向，可這幫廢柴竟然一事無成。$B$B如果我們不採取行動的話，他們很快就可以重新糾集起新的地獄火大軍，數量堪比你在軍團要塞炸掉的兵團。$B$B立刻轉至西北方的死亡熔爐哨塔，向奉命在那兒監視死亡熔爐的伊萬·蠻翼報到。','轉至死亡熔爐哨塔向伊萬·蠻翼報到。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10574 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10574,'zhTW','灰舌腐蝕者','阿卡瑪在指令中提到，被挖掘出來的4塊勳章碎片分別由四位灰舌腐蝕者負責保管。這些灰舌腐蝕者本都是氏族中的薩滿祭司，如今卻轉而與他們曾經崇拜與侍奉的元素為敵，唉……$B$B氣之腐蝕者哈魯姆當前在靈翼小徑；地之腐蝕者埃肯尼和火之腐蝕者烏拉魯，曾有人看見他們在古爾丹之手附近的魔能熔池旁出沒；水之腐蝕者拉坎恩據說在庫斯卡崗哨附近。$B$B殺死他們，取回全部的勳章碎片。','從哈魯姆、埃肯尼、拉坎恩和烏拉魯手中奪得他們的勳章碎片，並把這些碎片交給影月谷沙塔爾祭壇的學者希拉。$B$B為奧爾多陣營完成任務將降低你在占星者陣營中的聲望等級。','','去影月谷找沙塔爾祭壇的學者希拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10575 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10575,'zhTW','守望者的牢籠','你取回的碎片只能拼湊出半塊卡拉波勳章。另一半必定在灰舌破碎者的首領阿卡瑪手中。$B$B派你去執行這項任務令我心中隱隱有些不安，因為阿卡瑪是個邪惡而狡詐的傢伙。$B$B據說，他甚至還和氏族中那些最卑劣殘忍的成員——灰舌死誓者一起在守望者牢籠中設立了刑訊室。$B$B現在，我要你立刻轉至刑訊室尋找阿卡瑪的下落。如果有必要的話，你可以將他的副官薩諾魯抓來審問。','學者希拉要求你進入巴爾裡廢墟以南的守望者牢籠，從薩諾魯口中審問出阿卡瑪的下落。$B$B為奧爾多完成任務將降低你在占星者陣營中的聲望等級。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10576 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10576,'zhTW','影月谷的喬裝者','<伯拉克打量著你。>$B$B這事兒有些棘手，不過我應該能辦到。$B$B$N，我打算把你偽裝成一名伊利達雷血精靈。但首先你得給我找些血精靈的護甲來，護甲必須保持整潔，不能有任何血漬！這樣才不會引起懷疑。$B$B替我收集一些護甲，剩下的事就交給我吧。$B$B偽裝完畢後，你就要親自把口信傳達給他們的總指揮官了。','將6件日蝕護甲交給位於影月穀日蝕崗哨附近石橋處的歐魯諾克之子伯拉克。','','去找影月谷的伯拉克，歐魯諾克之子。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10577 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10577,'zhTW','伊利丹的信使……','帶上這件血精靈偽裝轉至日蝕崗哨。記得及時換上偽裝。日蝕血精靈大多不可能識破你的真面目，一路暢行無阻，你便可以見到總指揮官盧斯克。$B$B找到盧斯克後，告訴他詛咒密碼的下一個藏匿點。$N，這場戲你可得用心去演。擺足架勢，把自己想象成傳達伊利丹口信的長官。這樣必定能唬到他！$B$B哦，記得避開日蝕龍鷹，它們可以識破你的偽裝。','位於影月穀日蝕崗哨附近石橋處的歐魯諾克之子伯拉克要求你將伊利丹的口信傳達給日蝕崗哨的總指揮官盧斯克。','傳達伊利丹的口信','去找影月谷的伯拉克，歐魯諾克之子。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10578 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10578,'zhTW','詛咒密碼 - 伯拉克的命令','不能讓祖魯希德拿到詛咒密碼的碎片。你必須搶在褻瀆者魯爾將它轉交給祖魯希德之前劫回碎片。$B$B在這裡的正東方，靈翼平原對面便是龍喉要塞，魯爾就在龍喉要塞和群星聖殿之間的某處。一旦你發現他的蹤跡，就迅速殺掉他！$N，從我們套出的情報來看，魯爾是個不好對付的傢伙。請千萬小心。$B$B奪得詛咒密碼的碎片後就回來向我覆命。','從褻瀆者魯爾手中奪回詛咒密碼的第二塊碎片，然後向位於影月穀日蝕崗哨附近石橋處的歐魯諾克之子伯拉克復命。$B$B該任務最好組隊完成。','','去找影月谷的伯拉克，歐魯諾克之子。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10579 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10579,'zhTW','詛咒密碼 - 第三塊碎片','將箱子交給我的父親。他住在庫斯卡水池附近的歐魯諾克農場，在遙遠的北方。一旦集齊了碎片，我們就可以解讀詛咒密碼了。$B$B祝你好運，$N。請轉告我的父親，我會盡快啟程返家。','將伯拉克的箱子交給影月谷歐魯諾克農場的歐魯諾克·裂心。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10580 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10580, 'zhTW', '這些該死的地精跑去哪裡了?', '儘管我們在這裡的工作已完成，但是有件事讓我覺得很抱歉:我們迫使托斯利還有他的地精朋友們離開了。我們沒有選擇;他們的工程技術還有科學實驗在小樹林裡把我們過去所做的努力弄的一團糟。假如你願意幫我去看看他們後來的情況我會很感激。他們最後的消息是往東方過橋而行。我確定他們後來一定是轉往南方了，遠離雷霆王村。到南方的鋸齒山脊尋找他們移動的線索。', '指揮官天影要求你去劍刃山脈南邊的鋸齒山脊尋找托斯利還有其他地精去向的線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10581 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10581, 'zhTW', '跟著痕跡走', '很好，我是來警告你在山脊上不會找到任何東西。千萬不要跟著散落地上的備用零件痕跡走，那會通到托斯利基地的!你不會在那邊找到托斯利還有其他地精的。', '講了一圈，原來R-3D0型機器人已經告訴你跟著散落地面的零件痕跡上斜坡到剃刀山脊，你就會發現地精們在一個叫做托斯利基地的地方。假如你找的到托斯利的話，跟他談談吧。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10582 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10582,'zhTW','暗影議會的爪牙','<伊萬一邊聽著你彙報軍團要塞的情況，一邊不停地點著頭。>$B$B聽你這麼一說，我們探察到的線索逐漸清晰了許多。偵察兵們曾隱約發現他們在向軍團要塞那邊輸送地獄火，但是未能探得更多細節。$B$B暗影議會則將死亡熔爐部署得跟雷霆啤酒桶一般密不透風。因此，你首先得掃平外圍的障礙。去消滅駐守在死亡熔爐入口處的暗影議會衛兵吧！','殺死10個死亡熔爐守護者和5個死亡熔爐召喚者，然後向死亡熔爐哨塔的伊萬·蠻翼覆命。','','去影月谷找死亡熔爐哨塔的伊萬·蠻翼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10583 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10583,'zhTW','弗蘭尼斯的命運','空軍指揮官努埃恩指派我和另外兩名偵察兵來這兒密切注視死亡熔爐的動向，並收集情報。弗蘭尼斯·迅翼自告奮勇潛入死亡熔爐，可是數日來都沒有他的訊息。$B$B我擔心事情不妙了，$N。雖然弗蘭尼斯是一位經驗豐富的偵察兵，可是這次他孤身深入敵後，我們已經無法與他取得聯絡。請你立刻轉至死亡熔爐尋找他的行蹤，獲取他收集到的情報或物品。','死亡熔爐哨塔的伊萬·蠻翼要你轉至死亡熔爐尋找弗蘭尼斯·迅翼，並找回弗蘭尼斯的揹包。','','去影月谷找死亡熔爐哨塔的伊萬·蠻翼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10584 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10584, 'zhTW', '收集能量轉換器', '北邊劍刃崗哨那些愚笨的巨魔一直在襲擊我們的能量轉換器!你要為我把它們追回來，可以這麼說。$B$B毫無疑問的，巨魔巨大、笨拙的手毀壞了轉換器。所以，我要你做的就是從他們那裡釋放能量並在組合的電流體上使用這個原始電磁集電器來裝住它。$B$B你可能會感覺有點疼痛，所以在它被裝在磁力發電機球體裡時你需要「殺掉」它。', '托斯利要你帶著原始電磁集電器去收集5個電流體。任務完成時回去劍刃山脈的托斯利基地找托斯利。', '', '', '收集電流體', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10585 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10585,'zhTW','召喚之廳','為了滿足燃燒軍團的地獄火兵力需求，暗影議會必定挑選了一處隱蔽之地，在那裡召喚墮落的元素生物來構成地獄火的核心部分。$B$B召喚室通常在地下，附近會有被汙染的水池或熔岩。轉至死亡熔爐尋找召喚大廳，並設法破壞他們的召喚儀式。一些莫爾葛惡魔也參與了製造地獄火，他們身上攜帶的某種工具或許能打斷召喚師的魔法。','從死亡熔爐鐵匠或死亡熔爐雜役身上取得元素置換器，用它打斷召喚大廳中的召喚儀式。完成任務後返回死亡熔爐哨塔向伊萬·蠻翼覆命。','','去影月谷找死亡熔爐哨塔的伊萬·蠻翼。','終止地獄火召喚儀式','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10586 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10586,'zhTW','擊敗戰爭使者！','我們這次成功地阻止了暗影議會在死亡熔爐的軍事擴張行動，但是要想取得全面勝利，就必須擊敗燃燒軍團派駐在死亡熔爐的頭目。$B$B我在弗蘭尼斯的揹包中找到了一把鑰匙。它必定能幫你找到軍團要塞的戰爭使者拉索恩的行蹤。$B$B找到並擊敗戰爭使者拉索恩，然後直接向空軍指揮官努埃恩覆命。他正在焦急地等你的好訊息呢！','擊敗戰爭使者拉索恩，取回拉索恩的命令，然後返回蠻錘要塞向空軍指揮官努埃恩覆命。','','去影月谷找蠻錘要塞的空軍指揮官努埃恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10587 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10587,'zhTW','卡拉波訓練場','據斥候回報，一支由日怒血精靈新兵組成的大部隊當前正朝卡拉波廢墟前進。原本，如此大規模的軍事行動勢必會構成強烈的軍事威脅，但是我們相信此事另有內情。$B$B他們的服飾和戰鬥風格很像伊利丹麾下的部隊。我可不想自亂陣腳。轉至卡拉波廢墟取回他們的武器，這樣我們就能搞清楚狀況了。','沙塔爾祭壇的大主教歐納拉要你轉至沙塔爾祭壇東南方的卡拉波廢墟，從惡魔獵手學員和惡魔獵手新兵身上奪取8柄日怒闊劍。$B$B為奧爾多完成任務將會降低你在占星者陣營中的聲望等級。','','去影月谷找沙塔爾祭壇的大主教歐納拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10588 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10588,'zhTW','詛咒密碼','不知道這條危害世間的咒語被使用過多少次。你也看到了，它強大的破壞力是毋庸置疑的。$B$B帶上經過修復的詛咒密碼，轉至詛咒祭壇，在古爾丹面前吟唱咒語。$B$B唸誦咒語時，那些鐫刻在大地上的回憶將浮現在你眼前，而你要做的就是等待火焰之王森盧肯現身。$B$B$N，你必須擊敗他。這片土地已經無法承受新一輪的摧殘了。','在詛咒祭壇唸誦詛咒密碼，召喚出火焰之王森盧肯。$B$B殺死火焰之王森盧肯，然後與詛咒祭壇的大地治癒者託洛克談一談。','','去影月谷找詛咒祭壇的大地治癒者託洛克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10589 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10589,'zhTW','控制權','從拉索恩的命令來看，地獄火大軍轉移到了登陸場：災難，就在北面的山上！只有使用軍團要塞內的傳送裝置才能達到那裡。$B$B燃燒軍團的某些爪牙必定隨身攜帶著可以控制傳送裝置的裝置。你必須搞到這種裝置才能使用傳送裝置。殺光那些惡魔，一一搜屍，絕不能空手而歸。','將軍團傳送控制器交給蠻錘要塞的空軍指揮官努埃恩。據說軍團要塞的莫爾葛武器匠身上攜帶著這東西。','','去影月谷找蠻錘要塞的空軍指揮官努埃恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10590 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10590,'zhTW','仇恨的證明','阿爾薩斯和他的天災軍團揹負著沉重的血債……你要牢記這段不該被遺忘的歷史。$B$B燃起復仇的怒火是釋放我們內心傷痛的惟一途徑。不幸的是，恐懼和痛楚對這幫行屍走肉完全不起作用。只有將其徹底毀滅才能給你的心靈帶來一點點慰藉。$B$B與銀色黎明的軍官加魯什交談，瞭解天災石的來歷以及獲得天災石的方法。在我們再次交談之前，我需要你交給我一些天災石，作為你的能力和仇恨的憑證。','亡靈壁壘的麥拉·黎明之刃要求你給他帶去20枚爪牙的天災石。','','去找提瑞斯法林地的麥拉·黎明之刃。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10591 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10591,'zhTW','DESTROY THIS QUEST！','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10592 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10592,'zhTW','女妖之王的智慧','一旦脫離了主人的身體，天災石的力量就會減弱。瞧，我輕輕一握就能粉碎它們。$B$B<麥拉將天災石捏成了碎片。>$B$B轉至幽暗城的皇家區，將這些天災石碎片交給女妖之王希爾瓦娜斯·風行者。女王知道如何將這些碎片鑄造成對抗亡靈天災的利器。','轉至幽暗城，將天災石碎片交給希爾瓦娜斯女王。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10593 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10593,'zhTW','遠古的邪惡','想要把這堆石頭打造成武器來對抗天災士兵，你就需要某種侵染著邪惡氣息的物品來強化它們。$B$B悲傷沼澤的阿塔哈卡神廟深處潛伏著古老的邪靈。釋放並擊敗這個邪靈，然後將他的殘骸交給麥拉·黎明之刃。我的衛兵們會替你將天災石碎片交給麥拉的。','揭開阿塔哈卡神廟的秘密，釋放阿塔拉利恩並擊敗他，從他的屍體上取走腐爛藤蔓。完成任務之後向亡靈壁壘的麥拉·黎明之刃覆命。','','去找提瑞斯法林地的麥拉·黎明之刃。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10594 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10594, 'zhTW', '測量共振的頻率', '帶著這些掃描器到美聲山脊。當你依照地上的位置裝設它們，你會創造出彼此相疊的掃描區域來讀取水晶的振幅。但是你必須站在五個震動區域的交錯點，這樣一來我才能獲的我所需要的資料。$B$B你的掃描器同時也會與其他人放置的掃描器產生共鳴。$B$B喔對了，在過程中將會產生一個裂縫!我完全不知道會跑出什麼東西來。', '地鐵地精尼克偉恩寇要你以下列的方式來安裝震盪頻率掃瞄器。你必須在安裝完畢時同時處在五個震盪區域之中。$B$B完成之後，回到劍刃山脈的托斯利基地向地鐵地精尼克偉恩回報。', '已測量鳴唱水晶的共振頻率', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10595 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10595,'zhTW','兵臨城下！','<古爾穆克望著天空。>$B$B哎……我們的士兵消滅敵人的速度根本就跟不上他們補充兵力的速度。$B$B燃燒軍團當前盤踞在西南方的軍團要塞，每天召喚出的地獄火總能像潮水般朝我們這裡湧來。就算是庫卡隆的精英將士也沒法阻擋他們的攻勢。$B$B每一位強壯的$c都應該承擔起保衛影月村的重擔。這可不是兒戲，$c，形勢確實已經岌岌可危。為了部落的榮耀，加入前線大軍的陣列吧！','影月村外的血衛士古爾穆要求你殺死10個地獄火攻擊者。','','去影月谷找影月村的血衛士古爾穆克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10596 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10596,'zhTW','轉至軍團要塞','你的目的地是軍團要塞。你沒有援軍，所以就不要想發動正面攻擊了。$B$B從我們當前掌握的零碎情報來看，燃燒軍團正在要塞中囤積和準備他們的地獄火大軍。穿上這套偽裝潛入軍團要塞，打探他們的秘密計劃。$B$B或許你能從燃燒軍團指揮官們的談話中偷聽到一些東西。','轉至軍團要塞尋找軍團通訊裝置。在偽裝狀態下站在軍團通訊裝置附近，偷聽燃燒軍團的計劃。完成任務後向影月村的血衛士古爾穆克復命。','','去影月谷找影月村的血衛士古爾穆克。','','','偷聽燃燒軍團的計劃','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10597 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10597,'zhTW','製造炸彈','燃燒軍團意欲在轉至黑暗神殿的行軍途中摧毀蠻錘要塞，我們絕不能讓他們的奸計得逞。$B$B設法消滅地獄火大軍。$N，這不是請求，而是命令。$B$B軍團要塞附近有一片惡臭之池，那裡的魔能機甲動力核心可用作炸藥。那些魔能機甲附近另一處廢墟中的魔能機甲護板可用作炸彈外殼。收集這些兩樣東西來，然後你就可以製造出一枚威力強大的魔能炸彈了。','將魔能機甲動力核心和魔能機甲護板交給影月村的血衛士古爾穆克。','','去影月谷找影月村的血衛士古爾穆克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10598 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10598,'zhTW','炸燬地獄火！','我們裝配出來的這玩意雖然奇醜無比，但是它能消滅軍團要塞的地獄火大軍。瞧瞧魔能機甲能量核心對惡臭之池的影響，這東西蘊藏的爆炸威力可不容小覷。$B$B如果在軍團要塞的綠色雕文中心引爆這個邪能炸彈，應該可以一舉殲滅所有地獄火。','站在軍團要塞的綠色雕文上使用魔能炸彈消滅地獄火，然後向影月村的血衛士古爾穆克復命。','','去影月谷找影月村的血衛士古爾穆克。','','摧毀軍團要塞的地獄火','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10599 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10599,'zhTW','死亡熔爐','在你轉至軍團要塞執行消滅地獄火的任務時，我一直在研究你查探到的情報。要知道，我們沒有理由只注意軍團要塞，卻忽視死亡熔爐那幫蠢蠢欲動的燃燒軍團，他們的確在那兒製造地獄火大軍。我已經派出偵察小隊注意死亡熔爐的動向。$B$B如果我們不採取行動的話，他們很快將重新糾集起新的地獄火大軍，數量堪比你在軍團要塞炸掉的兵團。$B$B轉至東南方的熔渣哨塔，向奉命在那兒監視死亡熔爐的斥候薩格蘭報到。','轉至熔渣哨塔向斥候薩格蘭報到。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10600 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10600,'zhTW','暗影議會的爪牙','<薩格蘭聽你彙報軍團要塞的情況，不停地點著頭。>$B$B你探察到的情況跟我們掌握的線索恰好吻合。偵察兵們曾隱約發現他們在向軍團要塞那裡運送地獄火，但是未能探得更多細節。$B$B暗影議會將死亡熔爐部署得密不透風。看來你得首先掃平沿途的障礙，先去消滅駐守在死亡熔爐入口處的暗影議會衛兵吧！','殺死10個死亡熔爐守護者和5個死亡熔爐召喚者，然後向熔渣哨塔的斥候薩格蘭覆命。','','去影月谷找熔渣哨塔的斥候薩格蘭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10601 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10601,'zhTW','卡格羅什的命運','偵察小隊原本有三名成員，偏偏卡格羅什這傢伙逞強好勝，想當英雄。$B$B他孤身潛入死亡熔爐後，便與我們失去了聯絡。$B$B現在，這個蠢貨很可能已經被殺掉了，暗影議會的成員可不是傻子，卡格羅什也算不得偵察兵中的佼佼者。你立刻轉至死亡熔爐尋找他的行蹤，帶回他收集到的情報或物品。','熔渣哨塔的斥候薩格蘭要你轉至死亡熔爐尋找卡格羅什，並找回卡格羅什的揹包。','','去影月谷找熔渣哨塔的斥候薩格蘭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10602 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10602,'zhTW','召喚之廳','為了滿足燃燒軍團的地獄火兵力需求，暗影議會必定挑選了一處隱蔽之地，在那裡召喚墮落的元素生物來構成地獄火的核心部分。$B$B召喚室通常在地下，附近會有被汙染的水池或熔岩。轉至死亡熔爐尋找召喚大廳，並設法破壞他們的召喚儀式。一些莫爾葛惡魔也參與了製造地獄火，他們身上攜帶的某種工具或許能打斷召喚師的魔法。','從死亡熔爐鐵匠或死亡熔爐雜役身上取得元素置換器，用它打斷召喚大廳中的召喚儀式。完成任務後返回熔渣哨塔向斥候薩格蘭覆命。','','去影月谷找熔渣哨塔的斥候薩格蘭。','終止地獄火召喚儀式','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10603 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10603,'zhTW','擊敗戰爭使者！','我們成功地阻止了暗影議會在死亡熔爐的軍事擴張行動，現在是徹底肅清這幫傢伙的時候了。$B$B我在卡格羅什的揹包中找到一把鑰匙。看來卡格羅什還是有所收穫的。$B$B這把鑰匙應該能幫你找到軍團要塞的戰爭使者拉索恩的行蹤。$B$B搜尋並擊敗戰爭使者拉索恩，然後直接向血衛士古爾穆克復命。可別讓他等太久。','擊敗戰爭使者拉索恩，取回拉索恩的命令，然後返回影月村向血衛士古爾穆克復命。','','去影月谷找影月村的血衛士古爾穆克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10604 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10604,'zhTW','控制權','從拉索恩的命令來看，地獄火大軍轉移到了登陸場：災難，就在我們村子後面的山上！只有使用軍團要塞內的傳送裝置才能達到那裡。$B$B燃燒軍團的某些爪牙必定隨身攜帶著可以控制傳送裝置的裝置，你必須搞到這種裝置才能使用傳送裝置。殺光那些惡魔，一一搜屍，絕不能空手而歸。快去吧，情勢危急，敵人離我們很近了。','將軍團傳送控制器交給影月村的血衛士古爾穆克。據說軍團要塞的莫爾葛武器匠身上攜帶著這東西。','','去影月谷找影月村的血衛士古爾穆克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10605 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10605,'zhTW','凱倫丁的召喚','你似乎對獲取知識顯得十分飢渴的樣子，$n。看來你的學習正好到了一個提升層次的階段。$B$B去幽暗城與凱倫丁·哈加爾談談吧，那把老骨頭知道許多歪門邪道，或許你以後的冒險裡會用得上。','與幽暗城的凱倫丁·哈加爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10606 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10606,'zhTW','魔能機甲維修竅門大全','殲滅燃燒軍團殘餘勢力的最好辦法便是以彼之道還施彼身。我一直在開發某種可以操控魔能機甲斥候的儀器。$B$B當然，還有一堆設計上的問題沒解決。我需要加特里克博士的手冊。不過，這傢伙總是把它鎖在斜坡底部的箱子裡，他應該不會輕易交出鑰匙。你得用搶的，朋友。取回魔能機甲的手冊，剩下的就由我來搞定！','殺死加特里克博士，用博士的鑰匙開啟博士的保險箱，從中取出魔能機甲維修竅門大全，把它交給登陸場：災難的普雷西。','','去影月谷找登陸場：災難的普雷西。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10607 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10607, 'zhTW', '烏鴉神的秘密預言', '在葛瑞許納什，烏鴉智者留下的圖騰使得阿拉卡人可以聽見烏鴉的話語。不幸的是，阿拉卡的語言對我們來說太難以解讀。$B$B使用神諭使墜飾就可以讓我們了解他們的語言。你將可以捕捉阿拉卡的靈魂以了解他們的語言。當你身體內充滿著阿拉卡的靈魂時，你可以接近圖騰了解它們想傳達的訊息。$B$B幫助我們了解它們的訊息吧，$n。', '殺死葛瑞納阿拉卡取得理解烏鴉語的效果2分鐘。在法術的效果之下，你可以從四個聖物之中得知四段預言。當你得知四段預言之後就回來找我。', '', '', '獲得第一段預言', '獲得第二段預言', '獲得第三段預言', '獲得第四段預言', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10608 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10608, 'zhTW', '清除水晶的障礙', '那些該死的岩石鐮奪怪阻礙了我在美聲山脊所做的研究!當我在挖掘那些歌唱水晶的時候，它們總是跑來破壞我研究那些水晶的美妙旋律。$B$B你看起來像是可以幫我解決這個問題的人。幫我去南邊殺死那些水晶鐮奪怪。', '地鐵地精尼克偉恩寇要你殺死10個水晶鐮奪怪然後回到劍刃山脈的托斯利基地向他回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10609 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10609, 'zhTW', '龍生蛋，蛋生龍?', '我在我的醫生領域裡頭研究龍之精華的用途。對於一個生病的人來說，我想它們可能是一種萬靈藥!我需要有人去南邊的美聲山脊幫我取回一些。$B$B你願意帶著我的時光相位轉換器使用在剛從虛空龍蛋孵出來的虛空幼龍嗎?不管它們會變化成什麼，幫我取回精華。$B$B關於這件事，我想補充一下，我並不確定它們變化的結果因為我們所使用的是非常不穩定、改變時間與空間的科技產品。', '收集3個原始虛空龍之精華、3個年輕的虛空龍之精華還有3個成熟的虛空龍之精華。交給劍刃山脈托斯利基地的費茲特「醫生」克羅克塔可。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10610 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10610,'zhTW','基本的勘察','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10611 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10611,'zhTW','魔能機甲維修竅門大全','殲滅燃燒軍團殘餘勢力的最好辦法便是以彼之道還施彼身。我一直在開發某種可以操控魔能機甲斥候的儀器。$B$B當然，還有一堆設計上的問題沒解決。我需要麥爾費蘇斯博士的手冊。不過，這傢伙總是把它鎖在斜坡底部的箱子裡，他應該不會輕易交出鑰匙。你得用搶的，朋友。取回魔能機甲的手冊，剩下的就由我來搞定！','殺死麥爾費蘇斯博士，用博士的鑰匙開啟博士的保險箱，從中取出魔能機甲維修竅門大全，把它交給登陸場：災難的納斯坎。','','去影月谷找登陸場：災難的納坎斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10612 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10612,'zhTW','狂暴的魔能機甲','<普雷西迅速翻閱著手冊。>$B$B嗯，手冊上記載著我需要的所有資訊，現在只剩最後一個問題了。要知道，魔能機甲並不具備遙控的功能。$B$B不過，我們倒是可以改裝出一臺控制器來，但是它的控制有效期很短；你得抓緊時間，不然誰也無法預料會發生什麼事！那幫燃燒軍團的走狗目睹被控制的魔能機甲引發騷亂，必定會大跌眼鏡。保持警惕，儘可能地消滅那些地獄火！','使用魔能機甲控制檯控制一臺魔能機甲斥候，並在控制失效之前殺死60個死亡熔爐地獄火。完成任務後向登陸場：災難的普雷西覆命。','','去影月谷找登陸場：災難的普雷西。','摧毀死亡熔爐的地獄火','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10613 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10613,'zhTW','狂暴的魔能機甲','<納坎斯迅速翻閱著手冊。>$B$B嗯，手冊上記載了我需要的所有資訊，現在只剩最後一個問題了。要知道，魔能機甲並不具備遙控的功能。$B$B不過，我們倒是可以改裝出一臺控制器來，但是它的控制有效期很短；你得抓緊時間，不然誰也無法預料會發生什麼事！那幫燃燒軍團的走狗目睹被控制的魔能機甲引發騷亂，必定會大跌眼鏡。在確保自身安全的同時請以影月村賦予你的使命為重！','使用魔能機甲控制檯控制一臺魔能機甲斥候，並在控制失效之前殺死60個死亡熔爐地獄火。完成任務後向登陸場：災難的納坎斯覆命。','','去影月谷找登陸場：災難的納坎斯。','摧毀死亡熔爐的地獄火','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10614 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10614, 'zhTW', '風中低語', '我已經尋遍外域有關摩克納薩爾的謠言，但沒有任何關於它的蹤跡。最後，我們可能找到他們的家。但是既然現在就在這裡，我心裡卻充滿著不安。在我搜尋的期間，心神不安使我到深夜都無法入睡。他們會接受我嗎?我……知道他們領導人的名字:李歐羅克斯。將他找出來。這次你必須當我的眼睛。', '到劍刃山脈的摩克納薩爾村找到李歐羅克斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10615 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10615, 'zhTW', '魯安曠野', '你幫助我揭示關於這裡阿拉卡本質的情報，將有很多其他人有很大的興趣知道。我們已經被塞納里奧遠征隊的成員拜訪過，那些人也已經變得掛慮阿拉卡在劍刃山脈這裡的意圖。你應該出外尋找他。他的名字是泰姆昂，而你將在魯安曠野的永恆樹林裡找到他。沿著這裡西方的道路走，然後在剃刀山脊分岔處向北走。最後，當路在刀刃峽谷分開時，沿著西邊的道路走。', '與永恆樹林的泰姆昂交談，永恆樹林在劍刃山脈的魯安曠野。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10616 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10616,'zhTW','<nyi>Breadcrumb','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10617 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10617, 'zhTW', '絲翼之繭', '絲翼之繭的絲在我們村子有非常多種的用途。我們永遠都不夠用，絲越多越好。$B$B要從幼蟲身上採集繭是很困難的，因為一旦它們開始成長變化繭就被破壞了。$B$B我們的士兵們都忙於應付對村莊的攻擊行動。假如你可以幫我們收集一些它們的繭來，那就太好了。', '摩克納薩爾村的塔爾瑞克要你從絲翼幼蟲身上收集8個絲翼之繭。$B$B在幼蟲成長成絲翼之前殺掉它，不然繭就會被破壞。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10618 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10618, 'zhTW', '最柔軟的翅膀', '捕獵絲翼幼蟲對我們的年輕士兵來說是一項困難的挑戰，但幸運的是，即使他們從幼蟲身上採集繭失敗了，我們仍然可以使用已孵化的絲翼翅膀。$B$B事實上，我們對翅膀的使用量大於繭，而且希望越多越好。$B$B假如你願意幫助我們去外面收集一些翅膀就太好了。', '摩克納薩爾村的希歐瑪納要你收集12個彩虹之翼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10619 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10619,'zhTW','灰舌氏族','灰舌氏族是所有破碎者中最可怕的存在，這個氏族的成員都經過阿卡瑪的精挑細選，個個生性邪惡、嗜血成癮。即使是與伊利丹麾下的其它納迦部隊、惡魔部隊或是血精靈部隊相比，他們的殘忍與無情也毫不遜色。眼下，有大批灰舌破碎者盤踞在西南方的巴爾裡廢墟一帶。我們要先下手為強，在這幫傢伙有機會攻擊我們之前削弱他們的勢力。','守備官奧魯門要你進入巴爾裡廢墟，殺死3名灰舌馴獸者、4名灰舌戰士和6名灰舌薩滿祭司。$B$B為奧爾多完成任務將降低你在占星者陣營中的聲望等級。','','去影月谷找沙塔爾祭壇的守備官奧魯門。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10620 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10620, 'zhTW', '山脊的威脅', '當托斯利決定搬到外域去後我們就開始幫忙，自此之後就一直幫下去。$B$B現在看來我們終於斬除了一些根源。所有瘋狂的科學家們繼續進行著他們的計畫，而我們非正式騎兵是來保護他們的。$B$B我們現在需要你去北方的剃刀山脊，或是東邊的鱗翼沙洲，殺死行者來保持淨空。他們是住在岩石礦脈間的鬼祟蜘蛛，會對沒有戒心的過路者一撲而上。', '迪希·迪娜要你殺死10隻山脊行者。任務完成後，回到劍刃山脈的托斯利基地向她回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10621 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10621,'zhTW','伊利達雷斬除碎片','這似乎是一塊武器的殘片，金屬表面鐫刻著的符文依然清晰可辨，並閃爍著詭異的光芒。$B$B這把武器的用途已經不得而知，但你很想解開這個疑團。軍團要塞的莫爾葛武器匠似乎經常使用這種材質的金屬鑄造武器。或許蠻錘要塞的武器鍛造師能替你揭開謎底？','將伊利達雷斬除碎片交給蠻錘要塞的奧丁·雷拳。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10622 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10622,'zhTW','忠誠的證明','$N，你不知道，其實阿卡瑪大人一直在暗中觀察你的動向。$B$B事實上，你在巴爾裡廢墟殺死的那些灰舌氏族成員正是所有破碎者中生性最為邪惡的一群，阿卡瑪精心挑選出這樣一批兇殘的成員，為的正是利用他們的表現迷惑伊利丹。而我們灰舌死誓者才是阿卡瑪真正的心腹，只有我們才瞭解大人真正的意圖。$B$B最重要的事情是，我們必須確定你不是伊利丹的同夥。伊利丹指派了一個名叫杉德拉斯的薩特負責監視整座守望者牢籠。殺死他，以此證明你的忠誠。','殺死影月谷內守望者牢籠的杉德拉斯，然後向薩諾魯覆命。','','去影月谷找守望者牢籠的薩諾魯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10623 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10623,'zhTW','伊利達雷斬除碎片','這似乎是一塊武器的殘片，金屬表面鐫刻著的符文依然清晰可辨，並閃爍著詭異的光芒。$B$B這把武器的用途已經不得而知，但你很想解開這個疑團。軍團要塞的莫爾葛武器匠似乎經常使用這種材質的金屬鑄造武器。或許影月村的武器鍛造師能替你揭開謎底？','將伊利達雷斬除碎片交給影月村的格羅克姆·死眼。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10624 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10624,'zhTW','陰森的歷史','你感受到陣陣的寒意了嗎？就像冰涼的手掌落在肩上？$r，這並不是你的錯覺。這兒確實有鬼魂出沒，不散的怨靈永世在這片土地上徘徊著。$B$B你確定想看看他們的模樣嗎？這很可能會影響你的一生——而且是不良的影響。$B$B那麼好吧，我要你轉至影月谷西部的熔岩池收集一些永燃灰燼。綠色熔岩池附近到處都是這種東西……','將15份永燃灰燼樣本交給影月谷影月村的主藥劑師希爾達迦。','','去影月谷找影月村的主藥劑師希爾達迦。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10625 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10625,'zhTW','幽靈眼鏡','我把這東西稱為“幽靈眼鏡”。很棒的名字，不是嗎？戴上這副護目鏡，你就能看見影月谷中的鬼魂。$B$B在把幽靈眼鏡交給你之前，你得答應我一件事：幫我們清除影月村的鬼魂。$B$B來吧，戴上護目鏡，殺掉徘徊在村落中的鬼魂。希望這能起到殺一儆百的效果，迫使剩餘的鬼魂離開影月村。','影月谷影月村的主藥劑師希爾達迦要你去殺死12個影月狂徒。','','去影月谷找影月村的主藥劑師希爾達迦。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10626 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10626,'zhTW','奪取武器','如果你能提供更多的此類材料，我就能為你鑄造一柄適合的武器。$B$B軍團要塞的兩位深淵領主瑪卡扎頓和莫戈洛隆就隨身帶著這種特殊的抗魔武器。如果能取回這兩柄武器重新熔鑄，應該就有足夠的材料了，或許還有許多剩下來的呢。$B$B<奧丁咧嘴一笑。>$B$B用燃燒軍團的“秘密武器”來對付他們應該相當有趣，不是嗎？','將瑪卡扎頓之刃和莫戈洛隆之刃交給蠻錘要塞的奧丁·雷拳。','','去影月谷找蠻錘要塞的奧丁·雷拳。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10627 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10627,'zhTW','奪取武器','如果你能提供更多的此類材料，我就能為你鑄造一柄適合的武器。$B$B軍團要塞的兩位深淵領主瑪卡扎頓和莫戈洛隆就隨身帶著這種特殊的抗魔武器。如果能取回這兩柄武器重新熔鑄，應該就有足夠的材料了，或許還會有許多剩下來呢。$B$B真是迫不及待地想讓那些傢伙嚐嚐抗魔武器的厲害了。','將瑪卡扎頓之刃和莫戈洛隆之刃交給影月村的格羅克姆·死眼。','','去影月谷找影月村的格羅克姆·死眼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10628 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10628,'zhTW','阿卡瑪','你並非伊利丹的同夥，這點我們已經清楚了。我現在就告訴你阿卡瑪大人的藏身之處。$B$B你從這裡沿著牆一直走，不久之後就會看到右手邊有一潭死水，地下秘道就在那兒。$B$B$N，我必須\\r\\n警告你。你在秘道中的所見所聞，不可對任何人提起。','與守望者牢籠的密室中的阿卡瑪談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10629 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10629,'zhTW','骯髒的工作','伐木機總算是修好了，可我好像又把鑰匙弄丟了。我養了一群地獄警衛犬來保護營地，不過這幫廢物除了喜歡咬我之外什麼事兒都辦不成。它們還特別喜歡亮晶晶的東西。我猜伐木機鑰匙大約是被其中一隻警衛犬給吃了。如果你願意帶它出去散散步的話，我就付給你一大筆錢。散步的時候殺些地獄野豬來餵它，飽餐之後它肯定得按自然規律辦事。然後，你就在它排出的“殘渣”裡找找看有沒有鑰匙吧。','使用地獄犬哨召喚一隻惡魔警衛犬。帶惡魔警衛犬外出散步，並獵殺瘋狂的地獄野豬來餵養它。在惡魔警衛犬排出的“殘渣”中尋找伐木機鑰匙。然後返回索爾瑪西北方的礦洞，將伐木機鑰匙交給工頭拉澤克拉茲。','','去地獄火半島找索爾瑪礦洞的工頭拉澤克拉茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10630 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10630,'zhTW','索爾瑪的地下','我本來馬上就可以開始幹活了。可……現在問題是我的礦裡怎麼會有這麼多的甘爾葛。我沒法派苦工進去，而且，雖然機器人修好了，可我也不想在戰鬥中把它弄壞。礦洞的深處肯定有一個甘爾葛的頭目在坐鎮指揮。要是你去把它幹掉，或許這幫甘爾葛就會被嚇跑，然後我就可以開始掙錢買票回家了。','殺死烏加茲，然後返回索爾瑪西北方的礦洞，向工頭拉澤克拉茲覆命。','','去地獄火半島找索爾瑪礦洞的工頭拉澤克拉茲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10631 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10631,'zhTW','恢復營運','開著我的伐木機器人，到礦裡去挖一些礦石回來。','取一些礦石。','','去找。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10632 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10632, 'zhTW', '割下你的牙齒', '托斯利還有他的科學家們能夠得到你的幫助真是太好了。可惜我並沒有時間可以沉迷在「個人」嗜好上面。$B$B假如你想要幫這裡的忙，你只要聽從我的要求去做，而且是馬上，我需要一些武器。$B$B我們的槍在射程內很有殺傷力，但是當敵人靠近，我們則需要擁有一些強大的近戰武器做預備。$B$B北邊剃刀山脊的匕爪尾龍的牙齒可以做出精良的武器鋸齒劍身，連我都感到畏懼。', '洛薩克·鐵面要你取回5個特級銳利匕爪牙齒。完成後回到劍刃山脈的托斯利基地交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10633 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10633,'zhTW','塔隆·血魔的傳說','世間流傳著許多關於塔隆·血魔的故事，但是大多數都只是傳說。人們並不知道塔隆·血魔返回德拉諾世界後發生的事。$B$B我們只能確定一件事，那就是他已經死了。$B$B我曾聽這兒的斥候說，在遙遠的東南方，跨越靈翼平原，穿過靈翼小徑就能到達暗影祭壇，有位遠古的獸人靈魂居住在那兒。戴上幽靈眼鏡搜尋這位獸人。他應該知道更多關於塔隆·血魔的事。','影月谷影月村的主藥劑師希爾達迦要你找到上古影月之魂。$B$B如果你弄丟了幽靈眼鏡，主藥劑師希爾達迦可以再幫你做一副。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10634 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10634,'zhTW','占卜：血魔的護甲','血魔活著的時候就是個不折不扣的混蛋，死了之後依然惡性不改，禍害世間。$B$B東南方的靈翼浮島本是影月谷大陸的一部分，如今已變成一座殘破的浮島。$B$B這個地方曾經是死亡之翼的後嗣厄庫爾的家園，但現在這裡只是他的埋骨之地。厄庫爾還在浮島上空盤旋著，被血魔擊敗的恥辱令他狂怒不已。$B$B想要取回血魔的護甲，就得打敗厄庫爾。','將血魔的護甲交給影月谷東南方暗影祭壇的上古影月之魂。','','去影月谷找暗影祭壇的上古影月之魂。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10635 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10635,'zhTW','占卜：血魔的披風','血魔這傢伙可謂是罪行累累，其中最殘忍一次的要數卡拉波的牧師大屠殺事件。$B$B當年，古爾丹率領大軍擊敗了駐守在卡拉波神殿的德萊尼人，倖存的卡拉波祭司們淪為戰俘，獸人們便將這些牧師統統關押在地獄火堡壘中。$B$B那時，血魔還未墮落成死亡騎士，這個冷血的畜生竟然殺光了那些毫無反抗能力的戰俘。如今，卡拉波祭司們的怨靈依然在黑暗神殿前遊蕩著，他們心中復仇的怒火愈燃愈烈。$B$B血魔的披風就在那些卡拉波的牧師手中。','將血魔的披風交給影月谷東南方暗影祭壇的上古影月之魂。','','去影月谷找暗影祭壇的上古影月之魂。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10636 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10636,'zhTW','占卜：血魔的權杖','他們一個接一個地跪下來，願以自身性命為誓效忠血魔。血魔手起刀落，砍下了他們的首級。大屠殺之後，這個殘忍的劊子手便自殺了。$B$B他可不是誠心悔罪！絕不是，這傢伙是在追求永生！卡拉波幽靈騎士在死亡騎士的屍體上覆蘇。$B$B他們繞著古爾丹之手行進，等待著主人的歸來。血魔的權杖就在他們手中。把它取回來……','將血魔的權杖交給影月谷東南方暗影祭壇的上古影月之魂。','','去影月谷找暗影祭壇的上古影月之魂。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10637 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10637,'zhTW','必要的混亂','這些武器足以證明我們的擔憂不是沒有道理。伊利丹確實在卡拉波廢墟訓練惡魔獵手，我們必須阻止他進一步擴大勢力。$B$B$N，別被惡魔獵手這名字給迷惑了，總有一天這幫傢伙會像對付惡魔那樣來對付我們的。$B$B當前，還有一批日怒術士在卡拉波廢墟召喚並奴役惡魔，用於新兵訓練。他們曾召喚出一個名叫阿薩洛斯的深淵領主，不過阿薩洛斯過於強大，並不適合新兵的訓練課程，術士們只得不斷地放逐他。設法令阿薩洛斯擺脫放逐，這場混亂必定能為我們贏得了解敵情的時間。','大主教歐納拉要你返回卡拉波廢墟，設法令阿薩洛斯擺脫放逐狀態。$B$B為奧爾多完成任務將會降低你在占星者陣營中的聲望等級。','','去影月谷找沙塔爾祭壇的大主教歐納拉。','釋放阿薩洛斯','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10638 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10638,'zhTW','影月城的訓練','在影月城找到你的訓練師。','在影月城的<地區>尋找<姓名>。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10639 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10639,'zhTW','我就是塔隆·血魔……','你取回了塔隆·血魔的所有物件，離謎底僅剩一步之遙：寄主。$B$B<上古影月之魂邪惡地咧嘴一笑。>$B$B你顯然不相信我之前告訴你的故事。暗影祭壇便是我的牢獄。沒有你的幫助，我大概會永世被禁錮在這座祭壇中。現在，我要寄宿在你體內。殺死上古看守者卡修斯，讓我擺脫束縛。如果你拒絕的話，那咱倆就永遠留在這兒好了。$B$B塔隆·血魔就要重獲自由了！','上古影月之魂利用了你！在你集齊所有的物品後，他便露出了真面目，原來這傢伙就是塔隆·血魔。想要擺脫束縛，就必須按他的吩咐殺死上古看守者卡修斯。$B$B殺死卡修斯之後，向影月村的主藥劑師希爾達迦覆命。','','去影月谷找影月村的主藥劑師希爾達迦。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10640 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10640,'zhTW','奧圖裡斯','如今，選擇惡魔獵手之路的人本來就非常罕見，要找到不願意追隨伊利丹的惡魔獵手更是難上加難。$B$B不過，據說外域就有這樣一位英雄人物。他的名字令納格蘭的燃燒軍團聞風喪膽，整支奧爾多守備軍的官團都無法與他的力量抗衡。他就是奧圖裡斯。$B$B轉至納格蘭西部尋找奧圖裡斯。他或許會告訴我們關於惡魔獵手訓練場的事。','轉至納格蘭西部尋找受難者奧圖裡斯。$B$B為奧爾多完成任務將會降低你在占星者陣營中的聲望等級。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10641 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10641,'zhTW','對抗軍團','燃燒軍團可以令凡人的靈魂墮落腐化，這已是不爭的事實，所以我並不信任你。想要從我口中得知惡魔訓練場的詳情，就必須證明你並非是燃燒軍團的間諜。$B$B我正在追蹤一個名叫薩莎爾的女惡魔，可惜她是以虛體形態存在的，因此總能逃脫我的偵測。$B$B薩莎爾負責管理鑄魔基地：煉獄的天罰祭司，這些天罰祭司是她的心腹和爪牙，只聽從她的命令。殺掉她的天罰祭司，將那祭司體內的魔血潑在地上。這必定會激得薩莎爾暫時顯露真身，趁此機會殺死她。','受難者奧圖裡斯要你轉至虛空風暴的鑄魔基地：煉獄，從天罰祭司身上取回一份新鮮的魔血。然後，將新鮮的魔血潑在地上，並殺死薩莎爾的化身。完成任務之後向奧圖裡斯覆命。','','去找納格蘭的受難者奧圖裡斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10642 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10642,'zhTW','要塞中的幽靈','這些笨蛋矮人根本不知道他們把蠻錘要塞建在了什麼地方。這兒曾是影月谷獸人的埋骨地。是的，$r，就是獸人的鬼魂。$B$B近二十年來，他們一直靜靜地躺在蠻錘要塞地下，最近卻不知何故躁動起來。$B$B離開蠻錘要塞，在影月谷中搜尋熔岩池或是熔岩流。那附近到處都是永燃灰燼，去收集一些這種灰燼，我或許能利用它製作一件有用的物品。','將15份永燃灰燼樣本交給影月谷蠻錘要塞的仲裁者索魯斯。','','去影月谷找蠻錘要塞的仲裁者索魯斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10643 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10643,'zhTW','影月先驅者','要知道，索魯斯是很有幽默感的。$B$B不過，閒聊到此為止吧。戴上幽靈眼鏡，你就能看見徘徊在蠻錘要塞的獸人鬼魂了。別怕，其實我們才算是真正的入侵者。唉，可惜我們不得不痛下殺手，他們本應在平靜中永遠沉睡的。$B$B殺死滋擾蠻錘要塞的影月先驅者，然後向我覆命。','影月谷蠻錘要塞的仲裁者索魯斯要你去殺死12個影月先驅者。','','去影月谷找蠻錘要塞的仲裁者索魯斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10644 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10644,'zhTW','塔隆·血魔的傳說','世間流傳著許多關於塔隆·血魔的故事，但是大多數都只是傳說。人們並不知道塔隆·血魔返回德拉諾世界後發生的事。$B$B我們只能確定一件事，那就是他已經死了。$B$B我曾聽這兒的斥候說，在遙遠的東南方，跨越靈翼平原，穿過靈翼小徑就能到達暗影祭壇，有位遠古的獸人靈魂居住在那兒。戴上幽靈眼鏡搜尋這位獸人。他應該知道更多關於塔隆·血魔的事。','影月谷蠻錘要塞的仲裁者索魯斯要你找到上古影月之魂。$B$B如果你弄丟了幽靈眼鏡，仲裁者索魯斯可以再幫你做一副。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10645 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10645,'zhTW','我就是塔隆·血魔……','你取回了塔隆·血魔的所有物件，離謎底僅剩一步之遙：寄主。$B$B<上古影月之魂邪惡地咧嘴一笑。>$B$B你顯然不相信我之前告訴你的故事。暗影祭壇便是我的牢獄。沒有你的幫助，我大概會永世被禁錮在這座祭壇中。現在，我要寄宿在你體內。殺死上古看守者卡修斯，讓我擺脫束縛。如果你拒絕的話，那咱倆就永遠留在這兒好了。$B$B塔隆·血魔就要重獲自由了！','上古影月之魂利用了你！在你集齊所有的物品後，他便露出了真面目，原來這傢伙就是塔隆·血魔。想要擺脫束縛，就必須按他的吩咐殺死上古看守者卡修斯。$B$B殺死卡修斯之後，向蠻錘要塞的仲裁者索魯斯覆命。','','去影月谷找蠻錘要塞的仲裁者索魯斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10646 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10646,'zhTW','伊利丹的學生','$N，你已向惡魔獵手證明了自己的忠誠。請原諒我的謹慎，但是如今這世道人心叵測，我這樣小心也不為過。$B$B接下來，我會告訴你關於瓦雷迪斯的故事。','聽奧圖裡斯講述他的故事。','伊利丹的學生','去納格蘭找鑄魔營地：仇恨的受難者奧圖裡斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10647 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10647,'zhTW','通緝：烏魯洛斯，影月谷的禍患','死亡通緝令：$B$B烏魯洛斯，影月谷的禍患。$B$B奉奧巴洛恩大王之命，必須擊殺邪惡的野獸烏魯洛斯，並從它的屍首上取下烈焰之鬃做為憑證。如果你成功完成使命，請將烏魯洛斯的烈焰之鬃交給戰爭召喚者薩爾東·圖斯萊。$B$B烏魯洛斯曾在影月村以東，位於影月谷中心的古爾丹之手附近出沒。','殺死烏魯洛斯，將烏魯洛斯的烈焰之鬃交給影月谷影月村的戰爭召喚者薩爾東·圖斯萊。','','去影月谷找影月村的戰爭召喚者薩爾東·圖斯萊。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10648 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10648,'zhTW','通緝：烏魯洛斯，影月谷的禍患','死亡通緝令：$B$B烏魯洛斯，影月谷的禍患。$B$B奉大領主尤雷加爾之命，必須擊殺邪惡的野獸烏魯洛斯，並從它的屍首上取下烈焰之鬃做為憑證。如果你成功完成使命，請將烏魯洛斯的烈焰之鬃交給戰爭召喚者薩爾東·圖斯萊。$B$B烏魯洛斯曾在蠻錘要塞東北方，位於影月谷中心的古爾丹之手附近出沒。','殺死烏魯洛斯，將烏魯洛斯的烈焰之鬃交給影月谷蠻錘要塞的戰爭召喚者比爾斯諾特。','','去影月谷找蠻錘要塞的戰爭召喚者比爾斯諾特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10649 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10649,'zhTW','惡魔名冊','我理解你想要消滅瓦雷迪斯及其追隨者的心願，但時機尚未成熟，現在的你恐怕難以與他抗衡。除非，你能找到那件賜予他力量的神器。$B$B據說，惡魔名冊在奧金頓暗影迷宮的煽動者布萊卡特手中，它是你擊敗瓦雷迪斯的唯一希望。','進入奧金頓的暗影迷宮，從煽動者布萊卡特手中奪得惡魔名冊。完成任務後返回納格蘭向奧圖裡斯覆命。','','去納格蘭找鑄魔營地：仇恨的受難者奧圖裡斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10650 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10650,'zhTW','返回沙塔爾祭壇','這本書……我可以用它使我的力量增強十倍……不！那樣做只會令我的靈魂墮落腐化，這是必然的結局。$N，回到將你派來的人那裡去吧。$B$B你們現在可以利用這本惡魔名冊擊敗瓦雷迪斯。你們必須要在他變身為惡魔形態時焚燬惡魔名冊，這是唯一能削弱他的力量的方法。','與影月谷沙塔爾祭壇的大主教歐納拉談一談。$B$B為奧爾多完成任務將會降低你在占星者陣營中的聲望等級。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10651 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10651,'zhTW','阻止瓦雷迪斯','我們必須摧毀這個邪惡的神器，但在那之前，可以先利用它來削弱瓦雷迪斯的力量。$B$B要徹底毀掉卡拉波廢墟的訓練場，就必須殺掉瓦雷迪斯，以及他手下的惡魔獵手阿蘭蒂恩、瑟拉斯和奈薩里爾。$B$B召集你的朋友，一起返回卡拉波廢墟。根據奧圖裡斯的指示擊敗瓦雷迪斯。希望這辦法能起作用。','大主教歐納拉要你轉至卡拉波廢墟，殺死阿蘭蒂恩、瑟拉斯、奈薩里爾和瓦雷迪斯。在瓦雷迪斯變身為惡魔形態時利用惡魔名冊削弱他的力量。完成任務後將惡魔名冊交給大主教歐納拉。$B$B為奧爾多完成任務將會降低你在占星者陣營中的聲望等級。','','去影月谷找沙塔爾祭壇的大主教歐納拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10652 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10652,'zhTW','深入敵後','我已經安排好了，這頭雙足飛龍會載你飛往密探的藏身之處。準備就緒後立即出發吧。','當你準備啟程轉至法力熔爐：庫魯恩時，就告知維羅妮婭。抵達法力熔爐：庫魯恩後，跟卡勒迪斯·晨光談一談。$B$B為占星者完成任務將降低你在奧爾多陣營中的聲望等級。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10653 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10653,'zhTW','薩格拉斯印記','現在，我想你已經非常清楚為什麼我們要和燃燒軍團和他們的追隨者對抗了。$B$B如果你想在奧爾多陣營中證明自己，那麼就給我帶來一些只有高階燃燒軍團成員和高階暗影議會成員才能擁有的徽記。最高階別的燃燒軍\\r\\n團成員一般都在虛空風暴和影月谷一帶活動。','將10枚薩格拉斯印記交給撒塔斯城內的聖光護衛者阿德因。$B$B為奧爾多完成任務將會使你在占星者陣營中的聲望等級降低。','','去撒塔斯城找奧爾多高地的聖光護衛者阿德因。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10654 AND `locale` = 'zhTW';
