INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10659,'zhTW','單枚日怒徽記','','','','去找泰羅卡森林的魔導師菲亞琳。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10660 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10660,'zhTW','奇怪的生物……','我對生活在影月谷熔岩流附近的爬行動物很感興趣，這些奇怪的生物竟然能承受液態的岩漿所產生的高溫，真是聞所未聞！$B$B你可以在影月村外發現許多魔火雙帆龍，它們聚集在岩漿噴湧之處。殺死這些魔火雙帆龍，將它們身上的魔火脾臟帶回來。這樣，我就能開始研究它們如何抵禦高溫了。$B$B從村子東南方開始搜尋吧。','影月谷影月村的研究員提歐魯斯要求你給他帶回8個魔火脾臟。','','去影月谷找影月村的研究員提歐魯斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10661 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10661,'zhTW','美味的脾臟！','你聽說過食物會自己變熟並一直保持剛出鍋的新鮮嗎？嘿，你要敢於想象才行！$B$B不過，這可真不是什麼白日夢！在蠻錘要塞外面，你可以找到許多魔火雙帆龍，它們無視灼熱的高溫，聚集在熔岩池或是熔岩流附近。$B$B矮人們告訴我，魔火雙帆龍的脾臟堪稱美味中的極品，而且這東西在它們身上就已經煮熟了！給我搞些魔火脾臟來，這些金幣就歸你。$B$B從要塞正東方開始搜尋吧。','影月谷蠻錘要塞的諾姆斯要求你給他帶回8個魔火脾臟。','','去影月谷找蠻錘要塞的諾姆斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10662 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10662,'zhTW','隱居的鐵匠','<奧丁試圖將這些金屬塊鍛造成武器，但是失敗了。他遺憾地搖了搖頭。>$B$B這些鐵錠並非不能用於鍛造武器，只是我的能力有限罷了。$B$B我知道有位技藝精湛的鐵匠名叫戴維·韋恩，他是跟隨著洛薩之子來到德拉諾的。現在，這位著名的鐵匠已經離開了遠征軍，隱居在泰羅卡森林地區的火翼崗哨東北方的某個半島上。帶上鐵錠去找他吧，或許他能有辦法為你鍛造武器。','將一箱鐵錠交給泰羅卡森林內韋恩的避難所的戴維·韋恩。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10663 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10663,'zhTW','隱居的鐵匠','<你面前的這位獸人搖了搖頭，他明顯是失敗了。>$B$B這些鐵錠並非不能用於鍛造武器，只是我的能力有限而已。$B$B雖然這麼說挺傷自尊的，可你唯一的希望是一位名叫戴維·韋恩的人類鐵匠。他曾是聯盟遠征軍的一員，不過那已經是猴年馬月的事了。這位鐵匠現在早已離開洛薩之子，隱居在泰羅卡森林地區的火翼崗哨東北方的某個半島上。帶上這些鐵錠去找他吧，或許他能有辦法為你鍛造武器。','將一箱鐵錠交給泰羅卡森林內韋恩的避難所的戴維·韋恩。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10664 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10664,'zhTW','其它的材料','你帶來的鐵錠是鑄造劍刃的主要原料，但是我還需要別的材料來製作武器的其它部分。$B$B讓我看看，我還需要一個精金框架、一些重結締皮和一個惡魔防護結界圖騰。熟練的工匠能製作出前兩樣東西，第三樣就需要轉至撒塔斯城的貧民窟向施法材料商芬提購買了。他跟其它商人一起在那塊區域做生意。','將一個精金框架、4張重結締皮和一個惡魔防護結界圖騰交給韋恩的避難所的戴維·韋恩。','','去泰羅卡森林找韋恩的避難所的戴維·韋恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10665 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10665,'zhTW','能源艦的熱源','要熔鍊你帶來的鐵錠需要極高的溫度，普通的熔爐無法提供這樣的溫度。$B$B我需要一種特殊的熱源，外域中能製造出如此高溫的東西屈指可數。$B$B風暴要塞的能源艦裡就能生產這種蘊涵著不可思議的能量的魔法晶格。這些超載的魔法晶格就分佈在機械領主卡帕西圖斯周圍，去取一塊吧。','將超載的魔法晶格交給韋恩的避難所的戴維·韋恩。','','去泰羅卡森林找韋恩的避難所的戴維·韋恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10666 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10666,'zhTW','魔語辭典','只有用惡魔語吟唱法術才能重新為劍刃附魔。$B$B雖然我做學徒的時候完全沒有學過什麼惡魔語，可眼下沒別的路可走了。暗影議會的某個術士手中有一本魔語辭典，其中記載了附魔所需的大部分惡魔語詞彙。$B$B沃匹爾大師是此書的主人，這個難以對付的傢伙就躲在奧金頓暗影迷宮的大廳深處。去吧，無論如何也要把魔語辭典完好無損地給搶回來。','從沃匹爾大師手中奪得魔語辭典，將它交給韋恩的避難所的戴維·韋恩。','','去泰羅卡森林找韋恩的避難所的戴維·韋恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10667 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10667,'zhTW','地下的土壤','你先前帶來的精金框架未經強化是不能承受金屬熔化後產生的熱量的。我們可以往精金框架中填入某種稀有土壤，強化其冷卻效能。$B$B這種名為水下洞穴沃土的土壤被納迦視為珍品，極少數納迦才有資格擁有它；而據我所知，在外域，只有盤踞在盤牙水庫內蒸汽地窟的水術師瑟絲比婭使用這種土壤。','從水術師瑟絲比婭手中奪得水下洞穴的沃土，將它交給韋恩的避難所的戴維·韋恩。','','去泰羅卡森林找韋恩的避難所的戴維·韋恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10668 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10668,'zhTW','對抗伊利丹','我對伊利丹仍然心存敬意。若不是他，我也不會走上惡魔獵手之路。$B$B可惜，他已經不再是過去的他了。對力量的渴求讓他出賣了靈魂，而數次失敗又令他扭曲了心智。他已經成為了我發誓要徹底剷除的那種存在。伊利丹和他的僕從——那些被稱為伊利達雷的傢伙，現在跟燃燒軍團的惡魔爪牙已經沒什麼區別。$B$B雖然伊利丹在外域的統治權已經越來越弱，但是他的勢力依然不容小覷。轉至影月谷的伊利達雷崗哨，殺死伊利丹手下的軍官洛瑟魯斯，以此證明你的立場。','受難者奧圖裡斯要你轉至影月谷的伊利達雷崗哨殺死洛瑟魯斯。','','去找納格蘭的受難者奧圖裡斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10669 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10669,'zhTW','掃除餘孽','這世上也有少數惡魔依舊我行我素，不會起誓效忠他人。但是，真正的惡魔獵手絕不會因此生惻隱之心。$B$B惡魔克瑟勒斯曾被生活在贊加沼澤的原始沼澤生物奉為神靈，他一直拒絕加入燃燒軍團。德拉諾世界險些被摧毀時，他躲到沼光湖底，陷入了沉睡。轉至沼光湖附近的荒棄傳送門，將這根銀色魔槍插入地面。$B$B這樣一來，克瑟勒斯必定會甦醒。殺掉他，以此證明你也不是惡魔一夥的。','受難者奧圖裡斯要你轉至贊加沼澤，在沼光湖附近的荒棄傳送門使用銀色魔槍以喚醒克瑟勒斯。殺死這個惡魔之後，向奧圖裡斯覆命。','','去找納格蘭的受難者奧圖裡斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10670 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10670,'zhTW','大地之母的眼淚','劍刃的附魔還需要將一些強大的能源體熔化入其中，例如寶石。有一顆寶石可以為我們所用，要知道，這世上能容納如此強大的魔法能量而不碎裂的寶石可不多見。$B$B這顆名為“大地之母的眼淚”的寶石是食人魔製造的，當前在戰爭使者沃姆羅格手中。這傢伙盤踞在地獄火堡壘內的破碎大廳內，有很多強大的手下幫襯，不好對付。$N，取回大地之母的眼淚，一路小心。','從戰爭使者沃姆羅格手中奪得大地之母的眼淚，將它交給韋恩的避難所的戴維·韋恩。','','去泰羅卡森林找韋恩的避難所的戴維·韋恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10671 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10671, 'zhTW', '一磅多的肉', '$N，我有別的事情要你去做。那些知識份子之中的一個人想要研究在雷森平台那出現像惡魔般的血肉野獸，就在剃刀山脊的北邊。$B$B更重要的是，他們想研究那邊的血肉野獸的肉。$B$B<迪希做出了一個作嘔的表情。>$B$B不過當然，他們不想把自己的手弄髒，而且他們只想要蒼穹能量肉體，這可不是所有的血肉野獸都有的。$B$B我說，拿人的手短，但是你又能怎麼辦呢?', '迪希·迪娜要你取得5個蒼穹能量肉體然後回到劍刃山脈的托斯利基地交給她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10672 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10672,'zhTW','沒理由啊……','我們必須深入研究這些生物。$B$B此地以東便是巴爾裡廢墟。在那裡，巨大的熔岩流從地表噴湧而出，而你可以在熔岩附近找到魔蠍控制器。這些控制器是一個名叫諾姆斯的天才製造的，可以用於操縱機械蠍探測熔岩。$B$B可惜的是，這傢伙早已迷失心竅，現在他只對以辛辣著稱的侏儒食品感興趣。$B$B<提歐魯斯露出滑稽的表情。>$B$B我要你使用控制器標記熔岩流中的大型魔火雙帆龍，以便展開下一步的研究工作。','影月谷影月村的研究員提歐魯斯要求你轉至巴爾裡廢墟附近的熔岩流，使用魔蠍控制器控制一隻魔蠍，並用它標記8只大型魔火雙帆龍。','','去影月谷找影月村的研究員提歐魯斯。','標記大型魔火雙帆龍','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10673 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10673,'zhTW','魔脊龍','諾姆斯知道那條巨型魔火雙帆龍的存在，並且打算把它吃了！我可以透過魔蠍發現魔脊龍，他必定也早已知曉了。沒時間多解釋了。諾姆斯這個瘋子，魔脊龍的皮是上好的防火服，可不能讓他給吃了。$B$B返回巴爾裡廢墟附近的熔岩流，搜尋魔脊龍。一旦你找到這頭巨獸，立即殺掉它，然後將魔脊龍之皮帶回來給我。$B$B$N，別跟我爭辯。我早就不屑於此了。','殺死魔脊龍，將魔脊龍之皮交給影月谷影月村的研究員提歐魯斯。','','去影月谷找影月村的研究員提歐魯斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10674 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10674, 'zhTW', '捕捉神奇的光球', '北邊雷森平台的雷森伊斯利開發了一些有趣的科技產品。$B$B我相信他們不會介意你使用這個陷阱捕捉幾個他們浮在空中的粉紅色光球吧?反正那些光球八成只是裝飾品而已。$B$B這個陷阱有一個特殊的功能，當陷阱開啟時會吸引一個飄浮的光球飛向它。當然，它同時也會驚動到那些雷森關於你的到來。', '托斯利要你使用聖光陷阱捕捉15個雷森光球。任務完成後回到劍刃山脈的托斯利基地向他回報。', '', '', '已捕捉雷森光球', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10675 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10675, 'zhTW', '給他們地精式的解脫!', '<血從托斯利的臉上流了下來。>$B$B這些球體是由虛空的能量還有靈魂所組成的，部分的靈魂竟然是地精的靈魂!$B$B他們真大膽!我們那些往北旅行的同伴們，就是他們殺死的嗎?!$B$B$N，你必須阻止這件事，而唯一的解決方法就是殺死他們的首領，奈薩斯王子洛薩恩。$B$B但是你必須將他從隱匿中引誘出來。我猜你只要殺死大量的雷森伊斯利就會引誘他現身。$B$B將他身上的靈魂收集品交給我，那東西一定在他身上。', '托斯利要你取得靈魂收集品然後回到劍刃山脈的托斯利基地交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10676 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10676,'zhTW','伊利達雷的斬除者','<戴維開始蒐集他手邊的鍛造工具。>$B$B你成功取回了鑄造這柄抗魔之劍所需的材料。現在，你付出的艱辛都將得到回報。$B$B讓我們開始鑄劍吧。','等待戴維·韋恩為你鑄劍。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10677 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10677,'zhTW','第二道菜……','我曾在古爾丹之手以東、巴爾裡廢墟周圍的熔岩流附近見過大型魔火雙帆龍。我要你從它們身上取回一個巨大的魔火胃囊。這東西不太好切下來，運氣不好的話，你可能要多殺幾隻才能弄到合適的。加油！下一頓美餐就靠你了。','影月谷蠻錘要塞的諾姆斯要求你給他帶回一個巨大的魔火胃囊。','','去影月谷找蠻錘要塞的諾姆斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10678 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10678,'zhTW','主菜！','長話短說，我曾與一位名叫提歐魯斯的血精靈共事過一段時間。但自從我醉心美食之後，他便與我分道揚鑣了。這傢伙非常自以為是，現在居然還在繼續用我發明的裝置進行研究。他前幾天指派某個蠢貨利用我的魔蠍勘測了巴爾裡廢墟的熔岩流，結果發現了所有雙帆龍的頭目！$B$B我要你趕在他之前去殺掉那條名叫魔脊龍的雙帆龍王，將魔脊龍之皮帶回來給我。$B$B快去！','將魔脊龍之皮交給影月谷蠻錘要塞的諾姆斯。','','去影月谷找蠻錘要塞的諾姆斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10679 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10679,'zhTW','淬火','武器就快鍛造成功了！$B$B你幾乎能感受到鋼刃中的魔法力量在慢慢凝聚，只差最後一步了。$B$B轉至影月谷內古爾丹之手頂部的滾燙熔池，將鑄成的伊利達雷斬除之刃放入熔岩池中淬火，然後再將淬火的伊利達雷斬除之刃帶回來給我。','轉至古爾丹之手頂部尋找滾燙熔池，將鑄成的伊利達雷斬除之刃放入熔岩池中淬火。然後將淬火的伊利達雷斬除之刃交給韋恩的避難所的戴維·韋恩。','','去泰羅卡森林找韋恩的避難所的戴維·韋恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10680 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10680,'zhTW','古爾丹之手','元素需要你的幫助，$r！影月谷曾遭受過一場難以言喻的災難。元素之靈至今仍在痛苦中掙扎，現在，這些被激怒的元素之靈已經不願再繼續與大地之環溝通了。$B$B朋友，幫助影月谷恢復原貌吧。$B$B蠻錘要塞東北方便是詛咒祭壇，到那裡去，與大地治癒者託洛克談談。','與影月谷詛咒祭壇的大地治癒者託洛克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10681 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10681,'zhTW','古爾丹之手','元素需要你的幫助，$r！影月谷曾遭受過一場難以言喻的災難。元素之靈至今仍在痛苦中掙扎，現在，這些被激怒的元素之靈已經不願再繼續與大地之環溝通了。$B$B朋友，幫助影月谷恢復原貌吧。$B$B蠻錘要塞東北方便是詛咒祭壇，到那裡去，與大地治癒者託洛克談談。','與影月谷詛咒祭壇的大地治癒者託洛克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10682 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10682, 'zhTW', '協商時間……', '當我們抵達魯安曠野，巨龍教徒們正集中在黑翼集會所，經由這個隧道通往西方。不過現在，它們正接近我們這裡，$B$B我需要你去找到巨龍教徒的監督者。他在魯安曠野的各個營地之間定時巡邏。$B$B與他商量一下。讓他知道有協商的空間，不過我們不會寬恕或允許大規模屠殺野生生物，包括樹林的砍伐也是一樣。', '林木守衛蕭恩要你去與監督者奴阿爾協商。完成後回到劍刃山脈的永恆樹林找林木守衛。', '與監工努阿爾的談判已完成', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10683 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10683,'zhTW','巴爾裡石板','最近，一支名叫灰舌的破碎者氏族奉伊利丹之命，在巴爾裡廢墟展開了一系列挖掘工作。他們的目標毫無疑問就是當初那些被古爾丹所引發的火山爆發埋入地下的神聖古器。我們必須利用這個機會奪回巴爾裡石板。據說，那上面記載著許多卡拉波神殿——也就是黑暗神殿的秘密。','群星聖殿的奧術師塞里斯要你收集12塊巴爾裡石板。它們散落在巴爾裡廢墟中，那裡的灰舌工人身上也攜帶著這種石板。$B$B為占星者陣營完成任務將降低你在奧爾多陣營中的聲望等級。','','去影月谷找群星聖殿的奧術師塞里斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10684 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10684,'zhTW','長者奧洛努','根據巴爾裡石板的記載，巴爾裡廢墟中埋藏著一件名為卡拉波勳章的神器。在過去，德萊尼人當中只有最高階的祭司團成員才有資格得到這件神器，從而也獲得了自由進出卡拉波神殿的權利。$B$B我們現在必須查明灰舌破碎者們是否已從廢墟中挖掘出了這枚勳章。這件神器一定可以對我們抵抗伊利丹有所幫助。$B$B現在，駐守在巴爾裡廢墟的灰舌軍官——長者奧洛努每天都會接到他的上司阿卡瑪的書面指令。去把阿卡瑪的命令帶來給我。','群星聖殿的奧術師塞里斯要求你從巴爾裡廢墟的長者奧洛努手中奪得阿卡瑪的命令。$B$B為占星者陣營完成任務將降低你在奧爾多陣營中的聲望等級。','','去影月谷找群星聖殿的奧術師塞里斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10685 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10685,'zhTW','灰舌腐蝕者','阿卡瑪在指令中提到，被挖掘出來的4塊勳章碎片分別由四位灰舌腐蝕者負責保管。這些灰舌腐蝕者本都是氏族中的薩滿祭司，如今卻轉而與他們曾經崇拜與侍奉的元素為敵，唉……$B$B氣之腐蝕者哈魯姆當前在靈翼小徑；地之腐蝕者埃肯尼和火之腐蝕者烏拉魯，曾有人看見他們在古爾丹之手附近的魔能熔池旁出沒；水之腐蝕者拉坎恩據說在庫斯卡崗哨附近。$B$B殺死他們，取回全部的勳章碎片。','從哈魯姆、埃肯尼、拉坎恩和烏拉魯手中奪得他們的勳章碎片，並把這些碎片交給影月谷群星聖殿的奧術師塞里斯。$B$B為占星者陣營完成任務將降低你在奧爾多陣營中的聲望等級。','','去影月谷找群星聖殿的奧術師塞里斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10686 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10686,'zhTW','守望者的牢籠','你取回的碎片只能拼湊出半塊卡拉波勳章。另一半必定在灰舌破碎者的首領阿卡瑪手中。$B$B派你去執行這項任務令我心中隱隱有些不安，因為阿卡瑪是個邪惡而狡詐的傢伙。$B$B據說，他甚至還和氏族中那些最卑劣殘忍的成員——灰舌死誓者一起在守望者牢籠中設立了刑訊室。$B$B現在，我要你立刻轉至刑訊室尋找阿卡瑪的下落。如果有必要的話，你可以將他的副官薩諾魯抓來審問。','奧術師塞里斯要求你進入巴爾裡廢墟以南的守望者牢籠，從薩諾魯口中審問出阿卡瑪的下落。$B$B為占星者完成任務將降低你在奧爾多陣營中的聲望等級。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10687 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10687,'zhTW','卡拉波訓練場','據斥候回報，一支由日怒血精靈新兵組成的大部隊當前正朝卡拉波廢墟前進。原本，如此大規模的軍事行動勢必會構成強烈的軍事威脅，但是我們相信此事另有內情。$B$B他們的服飾和戰鬥風格很像伊利丹麾下的部隊。我可不想自亂陣腳。轉至卡拉波廢墟取回他們的武器，這樣我們就能搞清楚狀況了。','群星聖殿的拉瑞薩·射日者要你轉至群星聖殿東北方的卡拉波廢墟，從惡魔獵手學員和惡魔獵手新兵身上奪取8柄日怒闊劍。$B$B為占星者完成任務將會降低你在奧爾多陣營中的聲望等級。','','去影月谷找群星聖殿的拉瑞薩·射日者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10688 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10688,'zhTW','必要的混亂','這些武器足以證明我們的擔憂不是沒有道理。伊利丹確實在卡拉波廢墟訓練惡魔獵手，我們必須阻止他進一步擴大勢力。$B$B$N，別被惡魔獵手這名字給迷惑了，總有一天這幫傢伙會像對付惡魔那樣來對付我們的。$B$B當前，還有一批日怒術士在卡拉波廢墟召喚並奴役惡魔，用於新兵訓練。他們曾召喚出一個名叫阿薩洛斯的深淵領主，不過阿薩洛斯過於強大，並不適合新兵的訓練課程，術士們只得不斷地放逐他。設法令阿薩洛斯擺脫放逐，這場混亂必定能為我們贏得了解敵情的時間。','拉瑞薩·射日者要你返回卡拉波廢墟，設法令阿薩洛斯擺脫放逐狀態。$B$B為占星者完成任務將會降低你在奧爾多陣營中的聲望等級。','','去影月谷找群星聖殿的拉瑞薩·射日者。','釋放阿薩洛斯','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10689 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10689,'zhTW','奧圖裡斯','如今，選擇惡魔獵手之路的人已經非常罕見了，畢竟，他們受到了自己族人太多的猜忌，而且要找到不願意追隨伊利丹的惡魔獵手就更是難上加難。$B$B不過，據說納格蘭就有這樣一位名叫奧圖裡斯的英雄人物。他對所有的惡魔都恨之入骨，如果你能說服他，讓他相信我們和他有著共同的目的，他必定會伸出援手。$B$B轉至納格蘭西部尋找奧圖裡斯。他或許會告訴我們關於惡魔獵手訓練場的事。','轉至納格蘭西部尋找受難者奧圖裡斯。$B$B為占星者完成任務將會降低你在奧爾多陣營中的聲望等級。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10690 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10690, 'zhTW', '獸穴之后', '懸賞!$B$B瑞瑪，雷霆王村南邊鋸齒山脊的獸穴之后及主要的防衛者。$B$B出到鎮外向東走，越過橫跨血槌深谷的橋找到她。她隱居在橋南邊的隧道內。$B$B帶著她死亡的消息回到希爾瓦納的指揮官天影那裡。', '殺死瑞瑪然後通知在劍刃山脈之希爾瓦納的指揮官天影。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10691 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10691,'zhTW','返回群星聖殿','這本書……我可以用它使我的力量增強十倍……不！那樣做只會令我的靈魂墮落腐化，這是必然的結局。$N，回到將你派來的人那裡去吧。$B$B你們現在可以利用這本惡魔名冊擊敗瓦雷迪斯。你們必須要在他變身為惡魔形態時焚燬惡魔名冊，這是唯一能削弱他的力量的方法。','與影月谷群星聖殿的拉瑞薩·射日者談一談。$B$B為占星者完成任務將會降低你在奧爾多陣營中的聲望等級。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10692 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10692,'zhTW','阻止瓦雷迪斯','我們當然必須摧毀這個邪惡的神器，但在那之前，可以先利用它來削弱瓦雷迪斯的力量。$B$B要徹底毀掉卡拉波廢墟的訓練場，就必須殺掉瓦雷迪斯，以及他手下的惡魔獵手阿蘭蒂恩、瑟拉斯和奈薩里爾。$B$B召集你的朋友，一起返回卡拉波廢墟。根據奧圖裡斯的指示擊敗瓦雷迪斯。希望這辦法能起作用，否則……我只能說跟你合作愉快了。','拉瑞薩·射日者要你轉至卡拉波廢墟，殺死阿蘭蒂恩、瑟拉斯、奈薩里爾和瓦雷迪斯。在瓦雷迪斯變身為惡魔形態時利用惡魔名冊削弱他的力量。完成任務後將惡魔名冊交給拉瑞薩·射日者。$B$B為占星者完成任務將會降低你在奧爾多陣營中的聲望等級。','','去影月谷找群星聖殿的拉瑞薩·射日者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10693 AND `locale` = 'zhTW';
