INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10737,'zhTW','大師之觸','我已經將這把曾還是個學徒時使用過的鑰匙重新拼接好了。雖然它現在看起來應該具備了以前鑰匙的功能，但你還是沒法用它來開啟卡拉讚的大門。事實上，它現在就跟一塊廢鐵一樣。$B$B沒有麥迪文調和這把鑰匙中的魔法力量，它就完全沒有任何價值。是的，沒錯，我知道麥迪文已經死了。但事情並非已經完全沒有希望。$B$B艾澤拉斯世界那邊有一處地方名叫時光之穴，被青銅龍軍團所守護著。你只要找到那裡，就可以回到過去找到麥迪文，讓他調和這把鑰匙中的魔法力量。','轉至時光之穴，勸說麥迪文為你重鑄Apprentice\'s Key。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10738 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10738,'zhTW','卓越的貢獻','$N，你沒有令我們失望。不過，我們也對你寄予了更大的期望。$B$B繼續為紫羅蘭之眼效力吧，你會得到滿意的回報的。','當你在紫羅蘭之眼的聲望達到崇敬後，將紫羅蘭徽記交給逆風小徑的大法師蕾爾達。','','','','','','',0);
