DELETE FROM `quest_template_locale` WHERE `ID` = 10744 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10744,'zhTW','勝利的訊息','立即去向庫德蘭·蠻錘大人彙報這個好訊息吧！空軍指揮官努埃恩和士兵們日夜守衛著蠻錘要塞的安全，這次勝利必定能鼓舞他們計程車氣。燃燒軍團的威脅已被清除，庫德蘭大人也可以專心對付伊利丹了。雖然我們還未在此地站穩陣腳，可畢竟已經取得了一次大勝。','返回蠻錘要塞，與庫德蘭·蠻錘談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10745 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10745,'zhTW','勝利的訊息','立即去向奧巴洛恩大王彙報這個好訊息吧！影月谷燃燒軍團的威脅已被清除，奧巴洛恩也可以專心對付其它敵人了。$B$B我們總算擺脫了腹背受敵的窘態，庫卡隆衛兵們嘴上雖然不承認，心裡可美著呢。','返回影月村，與奧巴洛恩大王談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10746 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10746,'zhTW','DEPRECATED Karazhan: LAB - E - Exalted Ring - Caster','你的成就已經大大的超過我的預期，$N.$B$B你如同所有青銅龍般可以輕鬆的進出時空。你註定擁有巨大的力量，而我也非常榮幸能夠一路協助你得到它。$B$B繼續侍奉流沙之鱗，而我將釋放你天賦的充分潛能。','當你的流沙之鱗聲望值到達崇拜之後帶著你的永恒指環給在時光之穴的索芮朵蜜。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10747 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10747, 'zhTW', '巨龍教團的幼龍', '我需要檢查生長在黑翼集會所的那些幼龍。$B$B那裡有一大群幼龍在洞穴裡外飛來飛去，同樣的也有為數不少的蛋，可能你一靠近就會孵化。$B$B$N，麻煩你拿著這個網子去活抓一堆幼龍給我。$B$B朝西前進越過龍骨橋或經過龍骨隧道可以找到它們。順著路一路經過葛瑞許納什及烏鴉林到盡頭去。', '沙彌亞·暗示者要你使用黑色幼龍網補抓10隻巨龍教團黑色幼龍。將這些幼龍帶到劍刃山脈的永恆樹林給她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10748 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10748, 'zhTW', '麥克斯納爾必須要死!', '他們讓我們別無選擇，$N。是時候把黑翼集會所帶來的威脅做個了結了，殺掉他們的領導者，灰喉麥克斯納爾。$B$B我不知道你在那裡的時候有沒有瞥見他，但他是龍族的一員，半人半龍。而且他很強壯，所以不要低估了他!$B$B快點把它了結，幸運的話你就能保衛永恆樹林和魯安曠野的安全。', '代表永恆樹林的塞納里奧遠征隊的德魯伊，以及魯安曠野當地的生命，林木守衛蕭恩要你去殺掉灰喉麥克斯納爾。完成後回到劍刃山脈的永恆樹林找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10749 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10749, 'zhTW', '沙伯曼男爵的毒藥', '來，把這個拿給你的主人。我確定無論理由為何，雷克薩都會好好使用它。$B$B喔，記得提醒他，他欠我一次。$B$B他知道我要什麼，因此我相信不管如何他都會把東西交給我，我們會比你想像的還要更快再次見到面。$B$B現在，當個聽話的小<男孩/女孩>把這個送去給雷克薩吧。', '將沙伯曼男爵的毒藥送到劍刃山脈的雷霆王村給雷克薩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10750 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10750,'zhTW','征服之路','$N，我從馭風者那兒得知，日蝕血精靈正在謀劃一次大規模的行動。他們當前已經開始在東南方的征服之路一帶聚集兵力。$B$B我要你轉至日蝕崗哨附近的征服之路偵察敵情。判斷清楚局勢後，使用這支訊號槍。一名庫卡隆馭風者會在看到訊號之後去接應你。將你探得的情報告訴他，而他也會給你下一步的指示。','轉至影月谷的征服之路。','偵查征服之路','使用庫卡隆訊號槍召喚一名庫卡隆馭風者。$B$B如果你不慎丟失了庫卡隆訊號槍，可以問奧巴洛恩大王另要一支。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10751 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10751,'zhTW','掃清道路','$r，我們必須得繼續深入調查。我和另一些馭風者將進入征服之路的上空。真希望我們能查探到更詳細的敵情。不過，請你為我們清理前面路上的障礙，當然，最重要的是，確保我們不被血精靈的弓箭給射下來！$B$B在你成功削減他們的數量之後，使用庫卡隆訊號槍，給我們的馭風者編隊發出訊號。','殺死20名日蝕士兵、10名日蝕騎兵和10名日蝕縛法者。','','使用庫卡隆訊號槍召喚一名庫卡隆馭風者。$B$B如果你不慎丟失了庫卡隆訊號槍，可以問影月谷內影月村的奧巴洛恩大王另要一支。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10752 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10752, 'zhTW', '前進梣谷', '最近萊恩·狼行者從達納蘇斯經過奧伯丁而來，朝著梣谷前進;他提到跟熊怪有關的事情。我沒有機會去問她的情況如何但是也許你可以去找她並且提供協助$C。順著奧伯丁的南部道路走。一旦你到達梣谷邊界繼續順著路走。你會在那邊找到阿斯特蘭納還有萊恩·狼行者。', '在阿斯特蘭納跟萊恩·狼行者談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10753 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10753, 'zhTW', '搶救自然', '燃燒軍團所犯下的暴行不記其數。即使在我們對話的同時，他們也派出燃燒軍團部隊對付外域的生物們。無力抵抗燃燒軍團的力量，外域的生物們一個接一個的倒下。$N，幫助我停止他們這些破壞自然的罪行。$B$B越過山丘往東邊去，你會看到燃燒軍團的破壞已經遍及整個刀刃峽谷了。殺死犯下這些罪行的元兇，惡魔墮落者，還有盡可能殺死越多的魔誓越好。', '殺死4隻魔誓鱗翼，4隻魔誓匕爪還有2隻惡魔墮落者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10754 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10754,'zhTW','堡壘的鑰匙','這件模具看上去是用來澆鑄某種鑰匙的。從背後雕刻的影象來看，它似乎跟地獄火堡壘有關。$B$B或許榮耀堡的遠征軍指揮官達納斯·托爾貝恩會對此感興趣。','將原始鑰匙模具交給地獄火半島榮耀堡的遠征軍指揮官達納斯·托爾貝恩。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10755 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10755,'zhTW','堡壘的鑰匙','這件模具看上去是用來澆鑄某種鑰匙的。從背後雕刻的影象來看，它似乎跟地獄火堡壘有關。$B$B或許索爾瑪的部落統領納茲格雷爾會對此感興趣。','將原始鑰匙模具交給地獄火半島索爾瑪的納茲格雷爾。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10756 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10756,'zhTW','羅霍克大師','鑰匙柄上的符號……雕刻在模具內的符號很難辨別，但是我能認出這是碎手邪獸人的鑰匙。$B$B這是個很好的機會，這把鑰匙可以讓你進入破碎大廳。$B$B與我們的鐵匠羅霍克談一談。如果說有誰能鑄造這把鑰匙的話，只能是他了。','將原始鑰匙模具交給索爾瑪的羅霍克。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10757 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10757,'zhTW','羅霍克的要求','邪獸人鐵匠或許算不上技藝最精湛的鐵匠，但他們還是有兩把刷子的。想要利用這個模具配製出能用的鑰匙，就必須以魔鐵錠為熔料——其它材料很可能會破壞模具。$B$B我需要幾塊魔鐵錠、一點奧法之塵還有幾顆火焰微粒。我會試著鑄造鑰匙，但是我不保證能成功。','將4塊魔鐵錠、2份奧法之塵和4顆火焰微粒交給地獄火半島索爾瑪的羅霍克。','','去地獄火半島找索爾瑪的羅霍克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10758 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10758,'zhTW','比地獄更炎熱','$N，真是糟透了！不管我往火堆裡扔多少煤塊，就是達不到需要的溫度。$B$B我唯一能想到的熱源就是燃燒軍團的魔能機甲，只有利用它體內的高溫才能對鑰匙進行淬火處理。$B$B我曾親眼目睹魔能機甲被摧毀時的景象。毀損的機甲噴射著火花和蒸汽，在濃煙中轟然倒地。將鑰匙模具插入魔能機甲的殘骸中淬火。想要摧毀魔能機甲的話，我建議你叫上幾個朋友。','摧毀地獄火半島的魔能機甲，將未淬火的鑰匙模具插入魔能機甲的殘骸，然後將灼燒過的鑰匙模具交給索爾瑪的羅霍克。','','去地獄火半島找索爾瑪的羅霍克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10759 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10759,'zhTW','尋找逃亡者','我覺得這些這幾頁日記上的內容應該可以湊成一篇完整的文獻，可現在我絞盡腦汁也沒理出什麼頭緒來。$B$B我們最好能找到日記中提到的這名逃亡者。如果他已經背棄了族人，你就有機會說服他幫助我們瞭解黑暗教團鴉人的陰謀。$B$B沿著西北方通往熔岩平原的道路開始搜尋吧，他很可能在平原上的某處避難。','在熔岩平原找到帕沙恩，並與他談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10760 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10760,'zhTW','斯克瑟隆廢墟','東邊的斯克瑟隆廢墟是個詭異的地方，苦工們都相信那片土地被詛咒了。$B$B然而，這裡沒有多少樹木，因此他們不得不冒險進入鴉人的廢墟砍伐木材。於是，鴉人之魂終日折磨著那些苦工，汲取他們的生命來強化邪惡的魔法。$B$B我們必須查明黑暗教團的意圖，及時阻止威脅蔓延。你現在就轉至斯克瑟隆廢墟，搜尋黑暗教團神秘計劃的證據。','從斯克瑟隆廢墟黑暗教團的鴉人身上奪得斯克瑟隆指揮官的日記 - 第1頁、斯克瑟隆指揮官的日記 - 第2頁，以及斯克瑟隆指揮官的日記 - 第3頁，將它們交給影月村的卡格魯爾中士。','','去影月谷找影月村的卡格魯爾中士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10761 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10761,'zhTW','尋找逃亡者','誰也無法解釋這些鴉人的靈魂為何依然盤踞在這個世界，以及他們為何對獸人如此恨之入骨，欲殺之而後快。$B$B日記中提到的那個逃亡者或許能提供線索。如果他真的背棄了族人，你就有機會說服他幫助我們瞭解黑暗教團鴉人的邪惡計劃。$B$B這條大路通向東南方的熔岩平原，沿途尋找他吧。','在熔岩平原找到帕沙恩，並與他談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10762 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10762,'zhTW','達姆菲大師','鑰匙柄上有著一個奇特的符號……這種符號應該很難在熔鑄的模具上直接印刻出來，不過我認得出這是碎手氏族的標記。$B$B這是個很好的機會，你可以利用這模具配出鑰匙，並進入破碎大廳。$B$B與達姆菲談一談。他精通各種鐵匠工藝，如果他都無法配製出鑰匙，那就沒人能辦得到了。','將原始鑰匙模具交給榮耀堡的達姆菲。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10763 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10763,'zhTW','達姆菲的要求','雖然邪獸人都是些沒腦子的笨蛋，但是他們的鍛造技術卻不像你想得那樣簡單。如果我們想要讓鑄造出的這把鑰匙真正能起作用，那麼在鑄造時就只能使用魔鐵，而其它的材料都有可能造成鑄造失敗的結果。$B$B給我帶一些魔鐵錠、奧法之塵和火焰微粒回來。我要親自試試看，不過不敢保證成功。','將4塊魔鐵錠、2份奧法之塵和4顆火焰微粒交給地獄火半島榮耀堡的達姆菲。','','去地獄火半島找榮耀堡的達姆菲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10764 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10764,'zhTW','比地獄更炎熱','不行啊。$g小夥子:姑娘，看來爐子的溫度不夠啊……這些材料根本無法熔化和混合。$B$B不過，你知道麼，燃燒軍團使用的那些魔能機甲是利用某種由十分灼熱的魔火所構成的核心所驅動的。那種魔火比一般火的溫度要高上許多。$B$B如果你能找到足夠的人手去毀掉一臺魔能機甲，就可以將這個模具放進機甲的核心中進行加溫。$c，一定要小心，那些魔能機甲的戰鬥力是非常強大的。','摧毀地獄火半島的魔能機甲，將未淬火的鑰匙模具插入魔能機甲的殘骸，然後將灼燒過的鑰匙模具交給榮耀堡的達姆菲。','','去地獄火半島找榮耀堡的達姆菲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10765 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10765,'zhTW','世界的碰撞……','在征服之路的南端，有一處商隊的大棚車營地。在那裡，我發現一個巨人在和一個血精靈使者密會。你大概也已經注意到，這一帶有許多體型較小的巨人出沒。這事情絕對不簡單，士兵。$B$B我要你殺入征服之路，到密會的現場去破壞他們的談判，再看看能否搜尋到什麼線索和資訊。完成任務後，使用訊號槍給我們馭風者發出訊號。','殺死特派使者莉芙·血葉和強大的考羅克，奪得伊利丹的命令。','','使用庫卡隆訊號槍召喚一名庫卡隆馭風者。$B$B如果你不慎丟失了庫卡隆訊號槍，可以問影月谷內影月村的奧巴洛恩大王另要一支。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10766 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10766,'zhTW','登陸場：災難','現在我們可以進入燃燒軍團位於登陸場：災難的基地了，所以我們要設法摧毀整個基地。只有殲滅影月谷這一地區內的全部燃燒軍團部隊，才能確蠻錘要塞的安全。$B$B我已經派出了一支先遣部隊轉至登陸場，幫助你清除燃燒軍團的殘餘勢力。你現在立刻返回軍團要塞，進入綠色水晶下的傳送裝置。普雷西會在登陸場：災難等你。','轉至登陸場：災難，向普雷西報到。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10767 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10767,'zhTW','登陸場：災難','現在我們可以進入燃燒軍團位於登陸場：災難的基地了，所以我們要設法摧毀整個基地。只有殲滅影月谷這一地區內的全部燃燒軍團部隊，才能確保影月村的安全。$B$B我已經派出了一支先遣部隊轉至登陸場，幫助你清除燃燒軍團的殘餘勢力。你現在立刻返回軍團要塞，進入綠色水晶下的傳送裝置。納斯坎會在登陸場：災難等你。','轉至登陸場：災難，向納坎斯報到。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10768 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10768,'zhTW','伊利達雷徽章','現在我們馭風者部隊必須返回影月村，馬上開始準備發動下一輪的進攻。而你，我命令你在這邊收集一些日蝕血精靈身上的徽章。$B$B收集到足夠的徽章之後，你可以使用庫卡隆訊號槍召喚來一名馭風者。$r，接下來你就要當間諜了！','收集10件伊利達雷徽章。','','使用庫卡隆訊號槍召喚一名庫卡隆馭風者。$B$B如果你不慎丟失了庫卡隆訊號槍，可以問影月谷內影月村的奧巴洛恩大王另要一支。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10769 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10769,'zhTW','散播敵意……','附魔材料全是研究員提歐魯斯準備的，我所要做的不過是將伊利達雷徽章浸入這些混合物中。好，完成了，這件徽章現在已經融合了伊利達雷的精華。$B$B帶上這件魔化伊利達雷徽章，轉至位於日蝕崗哨西南方的日蝕平原。你一進入平原後就立即換上它，偽裝成伊利丹的手下，之後，利用這偽裝殺死那些在平原上游蕩的瘋狂的巨人。這樣一來，他們必定會認為血精靈缺乏與其結盟的誠意！','偽裝成伊利達雷血精靈，殺死5個瘋狂的巨人，然後向影月谷內影月村的奧巴洛恩大王覆命，並將庫卡隆訊號槍一併交還給他。','','去影月谷找影月村的奧巴洛恩大王。','在偽裝狀態下殺死瘋狂的巨人','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10770 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10770, 'zhTW', '一些餘燼', '這裡東北方在我們上方的高原上躺著我老家之被燒盡的灰。在燃燒軍團派他們的灼熱小鬼去燒盡我們之前，有一大片森林在那些繁盛。在過了如此多個死寂的世紀後，我疲倦而老去的心甚至仍然渴望復仇。有太多敵人了以致於不能收復土地，但是你能使他們害怕。$B$B確定你願意幫助我?', '苔木長老想要你殺死8個灼熱小鬼，然後返回魯安曠野找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10771 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10771, 'zhTW', '來自灰燼', '如果你沿著東方的道路並上到山的側面，然後轉向北方，那你將會來到我長期失去的家。曾經在那裡有一棵樹。我早已忘記它的名字了。很久以前燃燒軍團召喚灼熱小鬼和其他火焰生物。我的家就被毀滅了，而我的族人逃離了。現在只有我留下來。$B$B我已經保存了一些可以在肥沃的火山土壤種植的鐵樹根種子。他們的魔力是強大的。為我做這件事，而我將與你同享一批被遺忘已久的財寶。', '苔木長老想要你旅行至斯卡德，並將鐵根種子種植在三座不同的肥沃的熔岩泥土內，然後返回魯安曠野到他那裡。', '', '', '南方火山泥土', '中央火山泥土', '北方火山泥土', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10772 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10772,'zhTW','征服之路','$N，我從獅鷲騎士們那邊得知，日蝕血精靈正在謀劃一次大規模的行動。他們當前已經開始在東南方的征服之路一帶聚集兵力。$B$B我要你轉至日蝕崗哨附近的征服之路偵察敵情。判斷清楚局勢後，使用這支訊號槍。一名蠻錘獅鷲騎士會在看到訊號之後去接應你。將你探得的情報告訴他，而他也會給你下一步的指示。','轉至影月谷的征服之路。','偵查征服之路','使用蠻錘訊號槍召喚一名蠻錘獅鷲騎士。$B$B如果你不慎丟失了蠻錘訊號槍，可以問影月谷內蠻錘要塞的大領主尤雷加爾另要一支。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10773 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10773,'zhTW','掃清道路','$r，我們必須得繼續深入調查。我和另一些獅鷲騎士將進入征服之路的上空。真希望我們能查探到更詳細的敵情。不過，請你為我們清理前面路上的障礙，當然，最重要的是，確保我們不被血精靈的弓箭給射下來！$B$B在你成功削減他們的數量之後，使用蠻錘訊號槍，給我們的獅鷲騎士編隊發出訊號。','殺死20名日蝕士兵、10名日蝕騎兵和5個考羅克之子。','','使用蠻錘訊號槍召喚一名蠻錘獅鷲騎士。$B$B如果你不慎丟失了蠻錘訊號槍，可以問影月谷內蠻錘要塞的大領主尤雷加爾另要一支。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10774 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10774,'zhTW','血精靈 + 巨人 = ？？','在征服之路的南端，有一處商隊的大棚車營地。在那裡，我發現一個巨人在和一個血精靈使者密會。你大概也已經注意到，這一帶有許多體型較小的巨人出沒。這事情絕對不簡單，士兵。$B$B我要你殺入征服之路，到密會的現場去破壞他們的談判，再看看能否搜尋到什麼線索和資訊。完成任務後，使用訊號槍給我們獅鷲騎士發出訊號。','殺死特派使者莉芙·血葉和強大的考羅克，奪得伊利丹的命令。','','使用蠻錘訊號槍召喚一名蠻錘獅鷲騎士。$B$B如果你不慎丟失了蠻錘訊號槍，可以問影月谷內蠻錘要塞的大領主尤雷加爾另要一支。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10775 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10775,'zhTW','伊利達雷徽章','現在我們獅鷲騎士編隊必須返回蠻錘要塞，馬上開始準備發動下一輪的進攻。而你，我命令你在這邊收集一些日蝕血精靈身上的徽章。$B$B收集到足夠的徽章之後，你可以使用蠻錘訊號槍召喚來一名獅鷲騎士。$r，接下來你就要當間諜了！','收集10件伊利達雷徽章。','','使用蠻錘訊號槍召喚一名蠻錘獅鷲騎士。$B$B如果你不慎丟失了蠻錘訊號槍，可以問影月谷內蠻錘要塞的大領主尤雷加爾另要一支。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10776 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10776,'zhTW','散播敵意……','附魔材料全是諾姆斯準備的，我所要做的不過是將伊利達雷徽章浸入這些混合物中。好，完成了，這件徽章現在已經融合了伊利達雷的精華。$B$B帶上這件魔化伊利達雷徽章，轉至位於日蝕崗哨西南方的日蝕平原。你一進入平原後就立即換上它，偽裝成伊利丹的手下，之後，利用這偽裝殺死那些在平原上游蕩的瘋狂的巨人。這樣一來，他們必定會認為血精靈缺乏與其結盟的誠意！','偽裝成伊利丹的手下，殺死5個瘋狂的巨人，然後向影月谷內蠻錘要塞的大領主尤雷加爾覆命，並將蠻錘訊號槍一併交還給他。','','去影月谷找蠻錘要塞的大領主尤雷加爾。','在偽裝狀態下殺死瘋狂的巨人','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10777 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10777,'zhTW','阿斯迦的圖騰','你從指揮官的日記中讀到的故事是真的。當初，就在古爾丹集結獸人大軍準備入侵艾澤拉斯世界時，我的族人們勇敢地提出抗議，想要阻止這場災難。古爾丹獲悉了這一切，便施放強大的法術摧毀了我們氏族的營地，扭曲了族人們的靈魂。$B$B必須在黑暗教團的傢伙釋放出更可怕的邪靈前阻止他們！轉至北方的斯克瑟隆廢墟尋找阿斯迦，取回他隨身攜帶的圖騰。這樣，我們就能制止黑暗教團的計劃了。','將斯克瑟隆作戰圖騰交給熔岩平原的帕沙恩。','','去影月谷找熔岩平原的帕沙恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10778 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10778,'zhTW','莉安絲魔棒','斯克瑟隆作戰圖騰尚不足以與黑暗教團的邪惡魔法抗衡。$B$B我們可將圖騰和其它擁有強大力量的物品組合起來，製作成一根聚能法杖。雖然已經無法將族人們從墮落的深淵中拯救出來，可我們至少能阻止他們越陷越深。$B$B首先我需要莉安絲魔棒，它在東南方日蝕崗哨的血精靈們手中。它被放置在廢墟頂層的營帳中，周圍有重兵把守。千萬小心，$N。','從日蝕崗哨的血精靈身上奪得莉安絲的鑰匙，用它開啟莉安絲的保險箱並取出莉安絲魔棒。然後向熔岩平原的帕沙恩覆命。','','去影月谷找熔岩平原的帕沙恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10779 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10779,'zhTW','獵人之道','你好，年輕的獵人。你看，像我這樣的技巧優秀的獵人都可以輕鬆控制住一隻野獸，並把它訓練成自己的夥伴。$B$B你現在必須立刻去LOCATION見見Huntress Kella Nightbow，她可以教你如何獲得一隻屬於自己的寵物。','與LOCATION的女獵人凱拉·夜弓談話。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10780 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10780,'zhTW','斯克瑟隆羽毛','製作法杖還缺一樣東西。我們必須將法杖的力量調整成可以針對黑暗教團精神力量的屬性。$B$B收集散落在斯克瑟隆營地周圍的羽毛來製作法杖。那個營地位於這裡以南，蠻錘要塞以東。$B$B古爾丹強大的力量徹底摧毀了族人們的肉身，只剩下他們的靈魂在世間遊蕩，可事情遠沒有終結。鴉人還汲取了殘留的魔法力量，他們那邪惡的儀式不斷吞噬著族人們的靈魂。','收集8片斯克瑟隆羽毛，然後向熔岩平原的帕沙恩覆命。','','去影月谷找熔岩平原的帕沙恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10781 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10781,'zhTW','火紅崗哨之戰','他們很可能正在征服之路附近搜尋你的下落。$r，快逃命去吧！$B$B別管我了，我已經不行了……這幫傢伙……我已經聽見他們的腳步聲了。現在就走！否則肯定來不及了！快逃走吧！如果你選擇留下來，就必須奮戰到底！$B$B若是你能在戰鬥中活下來，請一定要將此地的情形轉告給撒塔斯城的阿達爾。','擊敗駐守在火紅崗哨的伊利丹的部隊！$B$B獲勝後向撒塔斯城的阿達爾覆命。','消滅火色魔印的軍隊','去泰羅卡森林找撒塔斯城的阿達爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10782 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10782,'zhTW','為杖頭充能','法杖就快做好了！$B$B這片被詛咒的土地上依然湧動著古爾丹殘存的力量，我們需要將這種力量灌入未完成的杖頭。東邊的魔能熔池附近有一座詛咒祭壇，就在死亡熔爐南面。$B$B那兒禁錮著古爾丹的殘骸碎片。如果攜帶未完成的杖頭進入祭壇，某些實體可能會對此做出回應，你可別驚慌失措。此行危險重重，請千萬小心。','帶上未完成的杖頭，轉至詛咒祭壇，在古爾丹附近使用未完成的杖頭。將充滿能量的杖頭交給熔岩平原的帕沙恩。','','去影月谷找熔岩平原的帕沙恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10783 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10783, 'zhTW', '沙伯邁恩男爵', '我的計畫是。我們毒害巨魔們，然後消滅他們的古羅主人。在我於這些山中旅行期間，我遇見一個名為沙伯邁恩男爵的人。他精通鍊金術，且可確信會幫助我們。你可以在這裡北邊峽谷下方的血之環那裡找到他。無論他需要什麼代價，都由你來判斷是否接受。', '與在劍刃山脈之血之環的沙伯邁恩男爵談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10784 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10784, 'zhTW', '粉碎血槌營地', '<吐查克傾身接近低聲地說。>$B$B$N，你到目前為止對我們所做的比與巨魔戰鬥還要自豪。而當我對雷克薩所計畫的有信心時，我將依舊要求你在返回之前，粉碎血槌營地的巨魔們。$B$B那樣我們將加倍確信結果。$B$B要到那裡，向北走，走下雷霆王村外面的斜坡道。然後，在斜坡道底部，向西走越過飛龍之末，並向北穿過翻騰峽谷和匕爪峽谷。', '吐查克·雙爪要求你殺死10個血槌槌兵和5個血槌術士。之後，返回到劍刃山脈之雷霆王村的他那裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10785 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10785, 'zhTW', '它是一個陷阱!', '在這個世界沒有其他原因能比戈魯爾和他兒子們更能令我憎惡!他們屠殺我的族人-我的孩子-現在我將嚐到報仇的滋味!$B$B我已經利用龍火做成一個陷阱，如果你夠聰明的話，你甚至可以使用它來殺死古羅。$B$B快一點就對了，把陷阱拿給雷克薩。$B$B我渴求報仇的火焰必須要被撲滅!', '將龍火陷阱交付給劍刃山脈之雷霆王村的雷克薩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10786 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10786, 'zhTW', '圓面之地大屠殺', '我知道雷克薩有計畫要你向圓面之地前進。當你到那裡時，我有一些想要你去做的事情。$B$B我們必須把握任何能打倒這些山上的巨魔的機會，否則他們將佔領我們，這樣我們就會流血並且無意義的死去!$B$B圓面之地位於西北方遠處。向北走到魯安曠野，然後從那裡走向西邊，穿過隧道並通過烏鴉林。$B$B$N，我想要你殺掉圓面之地的劍刃巨魔們。徹底消滅他們!', '屠殺5個劍刃蠻卒和3個劍刃薩滿，然後返回劍刃山脈之雷霆王村的吐查克·雙爪那裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10787 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10787,'zhTW','飛龍之末的龍','如果我們要面對他，我們必須做些會激怒苟克的事情。\r\n\r\n現在你釋放了&&&，我想我知道要做什麼了!\r\n\r\n當你準備好時，讓我知道，而我將要求&&&載你飛到其中一個被刺穿在飛龍之末岩石上的龍的屍體處。\r\n\r\n取回屍體，並把它帶回來這裡給我，這樣我們就能創造一些必定可將苟克從隱藏中帶來出來的東西!','雷克薩已經要求你跟他講關於騎乘&&&出去到飛龍之末去收回一具黑龍屍體的事。當你收回屍體時，返回到劍刃山脈之雷神要塞的他那裡。','','到劍刃山脈的劍刃庭園找雷克薩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10788 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10788,'zhTW','返回塔萊尼婭身邊','你的老師，銀月城的塔萊尼婭想要見你，$N。我想你現在已經可以學習召喚並控制更為強大的惡魔了，所以我建議你儘快跟她會面。沿著謀殺小徑前行，塔萊尼婭就在那個名叫“聖殿”的洞穴中——這名字可真諷刺。','轉至銀月城，與塔萊尼婭談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10789 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10789,'zhTW','返回凱倫丁·哈加爾身邊','啊，$N，你終於露面了。$B$B幽暗城魔法區的凱倫丁·哈加爾傳話來叫你回去。這傢伙的耐性可不大好，所以我急著把這事兒告訴你。','轉至幽暗城，與凱倫丁·哈加爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10790 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10790,'zhTW','返回甘魯爾·血眼身邊','$R，離家多時了吧？是不是該回去跟你的老師甘魯爾·血眼討教點新知識了？他的博學多識幾乎人盡皆知。$B$B甘魯爾就居住在奧格瑪的暗影裂口。','轉至奧格瑪，與甘魯爾·血眼談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10791 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10791,'zhTW','迎接狼魂','儀式中要穿的祭袍我差不多已經製作好了。不過，還有最後一件事情要做，我要你幫我把\\r\\n這薰香放置在左邊符石附近的燭臺旁。$B$B這是以前的獸人部落製作的東西，我相信它能幫助我們引起狼之魂的注意。我還隱約能回憶起我的祖先們在每一次狩獵成功之後，在祭祀狼之魂的儀式上使用這種薰香的情景。$B$B一旦你將薰香放置好，我就將開始儀式。','在瑪魯卡茲的棚屋中靠近燭臺的地方使用儀祭薰香，並觀看儀式。儀式完成之後，與瑪魯卡茲談一談。','','去泰羅卡森林找裂石堡的瑪魯卡茲。','','幫助瑪魯卡茲召喚狼之魂','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10792 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10792,'zhTW','燃燒吧，塞斯高！','血環氏族背離了獸人高貴的傳統！只有誓死與瑪諾洛斯的嗜血詛咒抗爭過的勇士才算得上真正的獸人。我們鄙視那些邪惡的表親，瞧瞧他們軟弱低賤的模樣……墮落的獸人應該被燒死！$B$B進入東邊血環獸人的據點塞斯高，燒燬他們的建築物。從血環苦工手中奪得火炬，利用塞斯高的熔爐點燃火炬並將它們扔進獸人的房舍、獸欄和兵營。焚燬塞斯高，然後再回來找我！$B$B為了部落！','從血環苦工手中奪得火炬，利用塞斯高的熔爐點燃火炬，並將它們扔進塞斯高的建築物中。','','去地獄火半島找斷背崗哨的達克霍爾上尉。','燒燬兵營','燒燬東部小屋','燒燬西部小屋','燒燬獸欄',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10793 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10793,'zhTW','瓦薩雷克的日記：戰爭的前奏','日誌中記載了伊利丹軍隊近期的動向，還提到了瓦薩雷克率兵駐守征服之路的原因。原來這傢伙親手俘虜了一名沙塔爾高階將領。$B$B當前，這位將軍被關押在位於征服之路南端的火紅崗哨。一個名叫火色魔印的神秘組織負責看守囚犯。你若是想要調查此事，最好叫上你的朋友一同轉至。','轉至火紅崗哨尋找瑪庫斯·奧拉林，他是沙塔爾的高階將領。$B$B你可以在一間水晶監獄中找到他。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10794 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10794,'zhTW','碎手盜賊','$N，這世界上還有許多我們尚未掌握的秘密。奧格瑪的碎手氏族可以幫助你學會這些秘密的其中之一：製造毒藥。做他們要求你做的事情，首先獲得他們的信任吧。$B$B想去奧格瑪的話，你必須使用銀月城的傳送裝置抵達幽暗城。然後走出幽暗城外，找到附近的一處飛艇空港。從那裡就可以直接飛到奧格瑪了。到了那邊後，去暗影裂谷中找到申蘇爾吧。','與奧格瑪的申蘇爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10795 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10795, 'zhTW', '與多爾哥克的約會', '非常好，我已經看見你在附近，我一直有一些重要的事情想對你講。$B$B有報告說由於某些原因，血槌巨魔計畫對希爾瓦納和魯安曠野發動攻擊。我們不知道是誰或者什麼東西在催促他們做這事，但是我打算趁早摧毀他們的計畫!$B$B攻擊將從血槌營地開始。沿著魯安曠野外面斜坡道向西北走下去，你就會找到它。我要你殺死他們的領導人，多爾哥克!', '指揮官海法斯·石牆要你殺死血槌營地的多爾哥克。在你完成之後，返回劍刃山脈的永恆樹林找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10796 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10796, 'zhTW', '粉碎血槌營地!', '我聽說你到目前為止對我們所做的比與巨魔戰鬥還要自豪。現在，我將要求你再次面對他們。我要你摧毀血槌營地的巨魔!$B$B要去那裡，就從魯安曠野外的斜坡往西北方走下去。你將在斜坡道的底部找到他們。$B$B祝你好運，$c!', '中尉費爾威德要你殺死10個血槌槌兵和5個血槌術士。之後，返回劍刃山脈的永恆樹林找她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10797 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10797, 'zhTW', '古羅的支持', '一個小雕像標誌從多爾哥克死亡的爪子上掉下來。它與某個古羅有明顯的相似處。$B$B想必斜坡上往東，魯安曠野的永恆樹林有個指揮官海法斯·石牆會對這東西感興趣!', '將柯爾葛羅姆的徽章帶到劍刃山脈的永恆樹林交給指揮官海法斯·石牆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10798 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10798, 'zhTW', '拜訪男爵', '這是個壞消息。食龍者柯爾葛羅姆是最近對抗希爾瓦納血槌計畫的幕後主使者!為什麼他在操縱他們，而不只是利用劍刃，我不知道。但如果我們要對付古羅，我們就需要幫助。我認識一個精通各種奇特魔法的人。他的名字叫沙伯邁恩男爵，你可以在血之環找到他，回到西北邊的斜坡下，再往西南方通過峽谷。請他幫我們製作一個給古羅的陷阱。', '和沙伯邁恩男爵談談關於製作陷阱的事。他就在劍刃山脈的血之環。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10799 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10799,'zhTW','進入沸土峽谷','嗯，我會幫你製作龍火陷阱，但是你得用別的東西來交換。$B$B鮮血之環附近居住著一個戈隆，他手中有我想要的東西。但是你不能直接面對他，至少現在還不是時候。$B$B我打算利用硬殼穿地蟲的毒囊配製某種催眠粉。$B$B硬殼穿地蟲就分佈在西南方的沸土峽谷，把它們的毒囊帶回來給我，動作快點！','將7個硬殼穿地蟲的毒囊交給刀鋒山鮮血之環的薩博邁恩男爵。','','去刀鋒山找鮮血之環的薩博邁恩男爵。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10800 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10800,'zhTW','晚安，戈隆','我真是個天才。催眠粉已經配製好了，利用它去對付那個名叫格魯洛克的戈隆吧。我說過，這傢伙手中有我想要的東西。$B$B轉至鮮血之環另一側，巨龍之末東部邊緣的詛咒洞窟尋找他的蹤跡。$B$B如果我是你的話，一拿到格魯洛克的包裹，我就會立即離開。催眠粉的有效時間不會持續太長的。','偷走格魯洛克的包裹，將它交給刀鋒山鮮血之環的薩博邁恩男爵。','','去刀鋒山找鮮血之環的薩博邁恩男爵。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10801 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10801,'zhTW','這是個陷阱！','我對格魯爾之子和他們的父親簡直恨之入骨！他們殘忍地殺害了我的族人，連毫無抵抗力的孩子都沒有放過，我要復仇！$B$B這是龍火製成的陷阱，如果你夠聰明的話，應該能利用它殺死戈隆。$B$B我知道你有自己的計劃，不過我不在乎你殺死的是哪一個。把龍火陷阱交給指揮官海弗斯·石牆吧。$B$B平息我心中的怒火！','將龍火陷阱交給刀鋒山常青林的指揮官海弗斯·石牆。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10802 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10802, 'zhTW', '食龍者柯爾葛羅姆', '我們必須讓巨魔看看我們不是好欺負的。我們必須送出一個訊息。$B$B到圓面之地殺死那裡的巨魔。把他們的頭帶回來。$B$B然後去柯爾葛羅姆的祭壇，並且為他在那裡佈下陷阱。柯爾葛羅姆將會出現，而你必須誘騙他進入陷阱。當他死掉時，在他的屍體附近裝好你的可怕圖騰，以便巨魔能見他們倒下的主人和兄弟，並且知道想毀滅我們所需付出的代價。', '去圓面之地從圓面巨魔那裡收集3種可怕圖騰。在柯爾葛羅姆的祭壇使用沙伯邁恩的陷阱來召喚並殺死食龍者柯爾葛羅姆。$B$B當柯爾葛羅姆死掉時，把3種可怕圖騰放置在他的屍體附近，然後返回劍刃山脈的永恆樹林找指揮官海法斯·石牆。', '', '', '設置可怕圖騰', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10803 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10803, 'zhTW', '圓面之地大屠殺', '我知道我們有讓你向圓面之地前進的計畫。你去那裡的時候，我有些事情想要你去做。$B$B我們必須掌握任何能打倒這些山裡的巨魔的機會，否則他們將征服我們，這樣我們就會流盡鮮血無意義的死去!$B$B圓面之地位於西邊。走到西南方，越過橋並穿過隧道。在烏鴉林的西邊可以找到他們。$B$B$N，我想要你清除圓面之地的劍刃巨魔。', '屠殺5個圓面蠻卒和3個圓面薩滿，然後返回劍刃山脈的永恆樹林找中尉費爾威德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10804 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10804,'zhTW','友善','不知道它們受到了什麼驚嚇，$r。$B$B<莫德奈指著盤旋在空中的虛空幼龍。>$B$B它們甚至不肯下來進食。已經有好幾只虛空幼龍精疲力竭，直挺挺地墜落在地。$B$B我們必須挽救它們的性命！虛空幼龍以巖爪劫掠者為食。獵殺水晶附近的巖爪劫掠者，將巖爪劫掠者肉塊放在地上等待虛空幼龍前來進食。只要你站立不動，別做任何進攻性的動作，它們是不會傷害你的。','影月谷靈翼平原的莫德奈要你餵養8只成熟的靈翼幼龍。','','去影月谷找靈翼平原的莫德奈。','餵養成熟的靈翼幼龍','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10805 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10805, 'zhTW', '戈魯爾之巢大屠殺', '你已經證明你是足智多謀的，現在我想要請你加入我與戈魯爾和他的兒子間的戰鬥。$B$B劍刃家族擁護古羅，當你在別處消減他們的數量時，你還沒有對付到他們最強大的力量。$B$B戈魯爾只用最強壯的巨魔保護他的巢穴外部，而那些就是你必須殺死的人。往北走穿過匕爪峽谷，然後你就會在盡頭發現戈魯爾之巢。', '沙伯邁恩男爵要你和你的朋友殺死10個劍刃執行者，5個劍刃戰鬥法師，5個劍刃劫毀者和他們領導人，費葛羅姆的任務。當你已經設法完成這項偉績時，返回劍刃山脈的血之環找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10806 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10806, 'zhTW', '攤牌', '我們面對劍刃巨魔的主人，苟克，的時刻已經來到。那也是著手處理事情的時刻，去告別古羅的生命。$B$B拿著我的璽戒。當你到了苟克祭壇時，使用它，而我到來加入你。$B$B我們將一同毀滅苟克。', '在茍克祭壇使用沙伯邁恩的徽章，然後殺死茍克。當完成時，返回劍刃山脈的血之環找沙伯邁恩男爵。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10807 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10807,'zhTW','灰舌破碎者','灰舌氏族是所有破碎者中最可怕的存在，這個氏族的成員都經過阿卡瑪的精挑細選，個個生性邪惡、嗜血成癮。即使是與伊利丹麾下的其它納迦部隊、惡魔部隊或是血精靈部隊相比，他們的殘忍與無情也毫不遜色。眼下，有大批灰舌破碎者盤踞在北方的巴爾裡廢墟一帶。我們要先下手為強，在這幫傢伙有機會攻擊我們之前削弱他們的勢力。','勸誡者瓦倫要你進入巴爾裡廢墟，殺死3名灰舌馴獸者、4名灰舌戰士和6名灰舌薩滿祭司。$B$B為占星者完成任務將降低你在奧爾多陣營中的聲望等級。','','去影月谷找群星聖殿的勸誡者瓦倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10808 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10808,'zhTW','阻止黑暗教團','黑暗教團當前正在斯克瑟隆營地以南的熔岩坑舉行儀式，企圖召喚強大的上古邪靈。$B$B他們汲取了古爾丹殘存的魔法，強化了自身的力量，想要幫助邪靈來到我們的世界！$N，我們絕不能讓這種事發生。一旦黑暗教團的奸計得逞，上古邪靈引發的毀滅性後果簡直難以想象！$B$B帶上法杖轉至熔岩坑，徹底破壞黑暗教團的召喚儀式！','殺死黑暗教團儀祭者，然後使用帕沙恩的法杖破壞黑暗教團的召喚儀式。完成任務之後向熔岩平原的帕沙恩覆命。','','去影月谷找熔岩平原的帕沙恩。','終結黑暗教團的召喚儀式','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10809 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10809,'zhTW','通緝：座狼主宰卡魯什','通緝令：$B$B“懸賞擊殺座狼主宰卡魯什的勇士。卡魯什是血環氏族狼騎兵的首領，他曾多次率兵襲擊斷背崗哨的補給車隊。”$B$B“據斥候回報，他當前藏匿在塞斯高內。任何能取得他徽記的英雄將受到部落的感激，以及大筆賞金。”$B$B“- 達克霍爾上尉”','殺死座狼主宰卡魯什，將他的徽記交給斷背崗哨的達克霍爾上尉。','','去地獄火半島找斷背崗哨的達克霍爾上尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10810 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10810, 'zhTW', '破損的面具', '當你檢視破損的面具的時候，你聽見面具發出奇怪的聲音。假如面具沒有破損的話你可以聽見更清楚的聲音。$B$B魯安曠野的歐瑪利·贊普奈可能可以修理這個面具。', '將破損的面具帶給魯安曠野的歐瑪利·贊普奈。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10811 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10811,'zhTW','尋找奈爾薩拉庫','$N，虛空龍族的守護神在高空翱翔。看來你對龍族子嗣的關愛感動了他。向奈爾薩拉庫尋求幫助。這樣或許能解除虛空幼龍的困境。$B$B<莫德奈指向天空。>$B$B朋友，飛吧。','尋找奈爾薩拉庫，虛空龍族的領袖。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10812 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10812, 'zhTW', '神秘面罩', '沒問題，修好了。你問我這是什麼?哦，這是一個通訊裝置-它可以讓那些笨蛋跟彼此通訊。你知道的呀，燃燒軍團!我建議你把這個面具交給野蠻領主安德烈利安。他就在那邊走來走去。他總是不停的移動。$B$B那就快點去吧，他一直很想得到這個東西。', '將神秘面罩帶給魯安曠野的野蠻領主安德烈利安。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10813 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10813,'zhTW','格里洛克之眼','$N，你勇敢地進入血環獸人的老巢——可怕的塞斯高，並毫髮無傷地回來了！既然你這麼強，一定有能力幫助我窺探血環氏族最強的巫師格里洛克的思想！$B$B使用這塊碎片捕獲格里洛克之眼，讓眼球與你連線在一起，然後回到我這兒來，走近我的鍋……它會令格里洛克之眼與你分離。$B$B去吧，$N。小心一點。只要稍不留神，格里洛克之眼就可能把你暴露給我們的敵人。','使用塞薩克的碎片捕獲格里洛克之眼，然後利用塞薩克的熔鍋使格里洛克之眼與你分離。完成任務後將塞薩克的碎片還給塞薩克。','','去地獄火半島找斷背崗哨的塞薩克。','交回格里洛克之眼','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10814 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10814,'zhTW','奈爾薩拉庫的故事','這些資訊可能對你有用。請仔細聽我說，$r。','與奈爾薩拉庫談一談，聽聽他的故事。','奈爾薩拉庫的故事','去影月谷找靈翼平原的奈爾薩拉庫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10815 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10815,'zhTW','瓦薩雷克的日記：戰爭的前奏','日誌中記載了伊利丹軍隊近期的動向，還提到了瓦薩雷克率兵駐守征服之路的原因。原來這傢伙親手俘虜了一名沙塔爾高階將領。$B$B當前，這位將軍被關押在位於征服之路南端的火紅崗哨。一個名叫火色魔印的神秘組織負責看守囚犯。你若是想要調查此事，最好叫上你的朋友一同轉至。','轉至火紅崗哨尋找瑪庫斯·奧拉林，他是沙塔爾的高階將領。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10816 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10816,'zhTW','奪回聖地','$N，你狠狠地打擊了盤踞在巴爾裡廢墟的灰舌破碎者。現在，讓我們再來看看你如何對付伊利丹麾下的其它恐怖軍隊。$B$B影月氏族的邪獸人佔領了阿塔瑪平臺，那兒曾是我的族人們使用阿塔瑪水晶舉行神聖儀式的聖地。$B$B我們確信這幫傢伙將那塊阿塔瑪水晶藏在了阿塔瑪平臺附近，可惜我占卜不到它的下落。無論如何，邪獸人侵佔了德萊尼人的聖地，他們就得死。','殺死8名影月斬殺者、8名影月天選者和4名影月暗法師，然後向守備官奧魯門覆命。$B$B為奧爾多完成任務會使你在占星者陣營中的聲望等級降低。','','去影月谷找沙塔爾祭壇的守備官奧魯門。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10817 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10817,'zhTW','嚴厲的報復','你狠狠地打擊了灰舌破碎者的囂張氣焰，$N。如果你對自己有信心的話，我就再交給你一項任務。$B$B不久前，伊利丹手下的邪獸人曾大舉侵犯群星聖殿。$B$B我們斷定滋擾生事的是阿塔瑪平臺的影月谷獸人。$B$B讓這幫傢伙嚐嚐占星者的厲害。','勸誡者瓦倫要求你殺死8名影月斬殺者、8名影月天選者和4名影月暗法師。$B$B為占星者完成任務會使你在奧爾多陣營中的聲望等級降低。','','去影月谷找群星聖殿的勸誡者瓦倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10818 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10818,'zhTW','薩博邁恩男爵的邀請','$N，在你外出執行任務時，薩博邁恩男爵派了他的寵物龍送來訊息。$B$B他想見見你。看來男爵想讓你幫他對付戈隆。$B$B說起薩博邁恩男爵與戈隆的仇恨，我倒覺得你是整個外域最適合幫助他的人選。不過如果我是你的話，我就先叫上幾個夥伴，去鮮血之環打幾場。','薩博邁恩男爵邀請你與他商談要事。去刀鋒山的鮮血之環找他吧。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10819 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10819, 'zhTW', '邪誓防毒面具', '我有一個非常特殊的任務要交給你，$N。我要你滲透進入東邊的煉冶場:怒氣。當你到達煉冶場你將需要戴上邪誓防毒面具然後找到軍團通報器。一旦你找到通報裝置就跟裝置另一邊的人談話，不管他是誰。$B$B假如一切順利你就可以誆騙這些惡魔做出一些不光明正大的事情!試著告訴那個惡魔，煉冶場:怒氣已經造反了。$B$B祝你好運$C。', '戴著邪誓防毒面具使用煉冶場:怒氣的軍團通報器。$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10820 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10820,'zhTW','欺騙敵人','你要是再一聲也不吭，你就死定了！說話！說話呀！$B$B什麼？營地裡有叛亂？絕對不可能！我的僕從從來不會有膽子反抗我的權威。$B$B什麼，是真的？好吧，背叛的代價，可是會越來越沉重的，直到他們根本無法負擔。讓他們都永遠閉上嘴吧！完成了命令再來向我報告。','殺死4名末日熔爐隨從和4名末日熔爐技師。','','去刀鋒山找鑄魔營地：怒火的軍團聯絡器。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10821 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10821, 'zhTW', '你被開除了!', '末日哀嚎者沒有想辦法阻止那場叛變嗎?她真大膽!她一直以來都在質疑我的權威。不論如何，這會是她的最後一次了。你必須召喚她然後親自解決她。$B$B她的煉冶場守衛擁有可以召喚她到煉冶場:怒氣的鑰匙。取得五把鑰匙然後啟動五座軍團尖塔。那些方尖塔的啟動時間很短，所以確認要全部同時啟動。記住，煉冶場守衛擁有比較多的鑰匙。', '殺死末日哀嚎者然後回到永恆樹林向野蠻領主安德烈利安回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10822 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10822,'zhTW','單枚日怒徽記','','','','去找影月谷的戰鬥法師弗亞拉。','','','','',0);
