INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10824,'zhTW','日怒徽記','凱爾薩斯瘋狂地擴充兵力，占星者的生存面臨著危機。來自奎爾薩拉斯的血精靈不斷加入凱爾薩斯的部隊，為他贏得這場戰爭新增籌碼。他的兵力越雄厚，獲勝的希望就越大。$B$B但是，我們的新兵數量堪憂。向占星者證明你的價值吧，轉至西邊的日蝕崗哨和東北方的卡拉波廢墟，消滅那些與凱爾薩斯和伊利丹結盟的高階血精靈，將他們佩戴的日怒徽記帶回來給我。','將10枚日怒徽記交給群星聖殿的戰鬥法師弗亞拉。$B$B為占星者完成任務會使你在奧爾多陣營中的聲望等級降低。','','去影月谷找群星聖殿的戰鬥法師弗亞拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10825 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10825, 'zhTW', '未知的真相', '這個奇怪，魔法的寶珠從阿拉卡的廓羽下方落下。$B$B充滿著怪異，紫色的光輝，寶珠跟著一個聽不到的節拍跳動著。拿著它使你略感不舒服，因此你迅速地把它放到你的背包裡。$B$B或許穿過隧道越過龍骨橋，在魯安曠野西邊的林木守衛蕭恩會有興趣看看它?', '將葛瑞納寶珠送到劍刃山脈的魯安曠野給林木守衛蕭恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10826 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10826,'zhTW','薩格拉斯印記','現在你應該早已明白為什麼我們要與燃燒軍團及其爪牙為敵了吧。$B$B如果你想向奧爾多證明自己的價值，就轉至西邊的軍團要塞和死亡熔爐，消滅燃燒軍團的高階將士和暗影議會的爪牙們，將他們佩戴的薩格拉斯印記帶回來給我。','將10枚薩格拉斯印記交給影月谷的先驅者薩隆尼。$B$B為奧爾多完成任務會使你在占星者陣營中的聲望等級降低。','','去影月谷找沙塔爾祭壇的先驅者薩隆尼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10827 AND `locale` = 'zhTW';
