INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10829, 'zhTW', '樹老長者必須知道', '這真麻煩!阿拉卡害長者和保衛者被邪惡靈魂附身!但是有一位長者無論如何不能被影響。他的名字是樹老長者，如果我們要拯救烏鴉林的樹木，那你必須立刻去找他!回到烏鴉林。你可在過了葛瑞許納什的道路分岔處找到他。', '林木守衛蕭恩要你尋找並且與樹老長者交談，一位傳說住在劍刃山脈的烏鴉林裡的長者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10830 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10830, 'zhTW', '淨化樹林', '葛瑞納已經讓葉鬚樹人和石化樹人被邪惡的可伊靈魂佔據。$B$B我們必須拯救這些樹，否則整個烏鴉林很快將永遠消失!$B$B結合在葛瑞許納什找到的葛瑞許納什寶珠魔法，和兇暴烏鴉身上的一根可怕幼羽。$B$B使用結合成的驅邪羽毛引出可伊靈魂並盡快殺了它。石化樹人對這儀式來說太強大了，但如果我們拯救了足夠的葉鬚樹人，他們也將獲得自由。', '收集5個葛瑞許納什寶珠和5根可怕幼羽，然後將它們合併成驅邪羽毛。使用這些羽毛驅除並殺掉5個佔據烏鴉林葉鬚樹人的可伊靈魂。等你完成，返回劍刃山脈的烏鴉林找樹老長者。', '', '', '葉鬚樹人已驅魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10831 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10831,'zhTW','成為月布裁縫','如果你對月布裁縫感興趣的話，我可以教你。月布裁縫在製造原始月布時，消耗同等的材料卻能獲得兩倍於普通裁縫的產量，而且還能學到很多獨一無二的圖樣。你只需要透過一項簡單的測試就能成為一名月布裁縫。$B$B你得轉至塞納里奧庇護所，在月亮井中製造一塊原始月布樣品。我會為你提供所有的材料。完成任務後，將原始月布樣品帶回來給我。','在塞納里奧庇護所的月亮井中將一塊魔化靈紋布製造成原始月布樣品。將原始月布樣品交給撒塔斯城貧民窟的納絲瑪拉·月歌。$B$B*注意！* 你只能選擇一種裁縫專精。','','去找撒塔斯城的納絲瑪拉·月歌。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10832 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10832,'zhTW','成為魔焰裁縫','如果你對魔焰裁縫的技術感興趣的話，我可以教你。但我得先提醒你，這可是一項危險的事業。$B$B在虛空風暴製造魔法佈會招來強大的虛空怨靈。我需要更多的虛空怨靈精華來研究如何減少這一負面效應。$B$B帶上虛空怨靈信標轉至虛空風暴，用它召喚虛空怨靈。將虛空怨靈精華帶回來給我，我就收你為徒。魔焰裁縫技術在製造魔法布時，消耗同等的材料卻能獲得兩倍於普通裁縫的產量。此外，你還能學到很多獨一無二的圖樣。','將虛空怨靈精華的樣本交給撒塔斯城貧民窟的金吉·斯比維爾。$B$B*注意！* 你只能選擇一種裁縫專精。','','去找撒塔斯城的金吉·斯比維爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10833 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10833,'zhTW','成為暗紋裁縫','暗紋裁縫在製造暗影布時，消耗同等的材料卻能獲得兩倍於普通裁縫的產量，還能學到很多獨一無二的圖樣。$B$B當然，所有的裁縫都能使用暗影祭壇製造暗影布，但是暗影布裁縫與祭壇存在強大的魔法共鳴，能令祭壇的能量發揮到極致。$B$B帶上這塊深影水晶轉至影月谷東部，沿著靈翼平原的靈翼小徑一直往南走。影月谷的邊緣便是暗影祭壇。在祭壇處使用水晶。','在暗影祭壇附近使用深影水晶，使你與祭壇產生更強大的魔法共鳴，然後返回撒塔斯城的貧民窟，向安迪恩·達克斯賓覆命。$B$B*注意！* 你只能選擇一種裁縫專精。','','去找撒塔斯城的安迪恩·達克斯賓。','增強與暗影祭壇的共鳴','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10834 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10834,'zhTW','“暗眼”格里洛克','“暗眼”格里洛克將身體的一部分獻祭給了黑暗勢力，因此獲得強大的魔法能力。他失去了一隻眼睛，原本眼球的位置被灼燒成可怖的窟窿……他用眼罩遮住了這處背叛者的象徵，這眼罩中也是有秘密的。$B$B將格里洛克的眼罩帶來給我，$N，我一定會重重獎勵你的……','殺死“暗眼”格里洛克，將格里洛克的眼罩交給斷背崗哨的塞薩克。','','去地獄火半島找斷背崗哨的塞薩克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10835 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10835,'zhTW','藥劑師安東尼維奇','$N，我就當前針對血環獸人的研究發現寫了一份初步報告。我在索爾瑪的同事安東尼維奇一定很想看。他也在研究邪獸人的相關現象……希望能避免這樣的悲劇再次降臨在我們的獸人盟友身上。$B$B把這份報告書帶給他，我會繼續研究你帶來的血樣。運氣夠好的話，我們就能分析出使邪獸人陷入痛苦之中的真正原因了。','將阿爾布雷克的發現交給地獄火半島索爾瑪的藥劑師安東尼維奇。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10836 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10836,'zhTW','攻擊龍喉要塞','我一時半會兒也想不出法子來挽救我的子嗣和配偶。凡人，你得為我爭取時間。$B$B轉至靈翼平原東部邊緣的龍喉要塞，殺掉那裡的龍喉獸人。你製造的這場騷亂應該能阻撓他們的計劃。$B$B千萬小心，部分龍族成員已經被龍喉獸人侵蝕了心智。等待他們的只有死亡。我允許你一併了結他們的性命。','殺死15名龍喉獸人，然後向飛翔在影月谷靈翼平原上空的奈爾薩拉庫覆命。$B$B任何龍喉要塞的龍喉獸人都可以。','','去影月谷找靈翼平原的奈爾薩拉庫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10837 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10837,'zhTW','轉至靈翼浮島！','我能將自己的精華注入靈藤水晶，形成魔化靈藤水晶。這種魔化水晶蘊涵的力量足以從龍喉獸人手中釋放那些被奴役的虛空幼龍。$B$B轉至靈翼浮島收集靈藤水晶，靈翼浮島是漂浮在影月谷東南邊緣的一座小島。當你收集到足夠的靈藤水晶後就回來向我覆命。$B$B$N，當心居住在島上的龍喉獸人。','轉至靈翼浮島收集12枚靈藤水晶，然後向飛翔在影月谷靈翼平原上空的奈爾薩拉庫覆命。','','去影月谷找靈翼平原的奈爾薩拉庫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10838 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10838,'zhTW','惡魔占卜器','惡魔占卜器已經準備好了。轉至地獄火堡壘正後方的地獄火盆地，然後召喚惡魔占卜器。它會以地獄火堡壘為目標開始自動調幅。完成調幅後跟它談談，將它告訴你的語句都記錄下來，然後將這份手稿給我……$B$B去吧，$N，你千萬要做好準備。毫無疑問，地獄火堡壘會偵測到惡魔占卜器的存在，還會派出守衛來消滅它！','在地獄火盆地使用惡魔占卜器，等待它與地獄火堡壘建立共鳴，然後與惡魔占卜器交談並獲得惡魔占卜器之語。$B$B完成任務後將惡魔占卜器和惡魔占卜器之語一起交給索爾瑪的藥劑師安東尼維奇。','','去地獄火半島找索爾瑪的藥劑師安東尼維奇。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10839 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10839,'zhTW','基斯鴉巢：泰羅克黑石','基斯鴉巢位於難民車隊西北方，就在撒塔斯城以南某處隱蔽的小樹林中。據說鴉人在這座斯克提斯的屬地上建立了一座邪惡的祭壇。想要救贖基斯鴉巢的鴉人，就必須淨化這座泰羅克黑石。$B$B對著黑石使用這根淨化法杖，它受到過阿達爾的賜福，應該可以淨化黑石。出發吧，願聖光與你同在。','對基斯鴉巢的泰羅克黑石使用淨化之杖，然後向白骨荒野難民車隊的基爾利克復命。','嘗試淨化泰羅克黑石','去找白骨荒野難民車隊的覺醒者基爾利克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10840 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10840,'zhTW','聖光之墓','在東邊焦土之下，掩埋著聖光之墓，那是一處不為人知的死者安息之地。而在我的車隊被襲擊之前，我正準備去清除遊蕩在那附近大量邪靈。$B$B但現在，我卻得知另外一種邪惡的靈體生物已經完全佔據了聖光之墓。那些該死的虛靈居然還開始大肆掠奪很多年以前與那些死者共同安息在陵墓中的寶物。$B$B在我的車隊處於困境中時，我絕對不能離開，你是否可以幫忙替我去聖光之墓完成的我的工作呢？','高階祭司奧戈魯要你去聖光之墓，殺死10名虛靈邪術師和10名虛靈掠奪者，然後回到難民車隊向他覆命。','','去白骨荒野找難民車隊的高階祭司奧戈魯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10841 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10841,'zhTW','復仇先驅','[PH]  進入光明之墓，啟動那玩意兒。','[PH]  啟動那玩意兒。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10842 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10842,'zhTW','復仇的靈魂','聖光之墓現在已經被暗影議會所腐蝕了，裡面那些死去的德萊尼人的靈魂受到了深入骨髓的詛咒，成為了內心中充滿憤怒、困惑，以及對生者之怨念的邪靈。$B$B進入那座墓穴，找到那些悲慘的犧牲品。讓他們得到最後的安息。','高階祭司奧戈魯要你去聖光之墓，擊敗5名復仇的德萊尼。','','轉至白骨荒野的難民車隊，同那裡的高階祭司奧戈魯交談。','已殺死復仇的德萊尼','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10843 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10843, 'zhTW', '不知道從什麼時候開始……', '不知道從什麼時候開始，我們就已經在和劍刃巨魔作戰了。$B$B我們已經設法把他們擊退，因此現在他們只微弱的掌握住劍刃崗哨。按你來的路回去，在剃刀山脊的西南邊緣。$B$B藉由殺死他們的領導人，葛諾斯·布羅格納，向我證明你的價值。$B$B讓我們看看當你與巨魔作戰時，你是塊什麼料。', '為了向摩克納薩爾證明自己，李歐羅克斯已經命令你殺死葛諾斯·布羅格納，劍刃崗哨的巨魔領導人。完成後返回劍刃山脈的摩克納薩爾村找李歐羅克斯，不然就不要回來。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10844 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10844,'zhTW','煉冶場:怒氣','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10845 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10845, 'zhTW', '殺死幼龍之母', '我的獵人剛完成美聲山脊的偵察任務回來。看來寄生於那些水晶的虛空龍已經大幅增加並威脅到我們。$B$B既然你已證明你是一個有能力的殺手，讓我們看看你的$c技能是否敵的過一隻成年的龍。$B$B向南方穿過鱗翼沙洲並找到美聲山脊。進入那裡並殺死他們的母親，魔翼。', '李歐羅克斯要你殺死魔翼 。等你殺死她再返回摩克納薩爾村找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10846 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10846, 'zhTW', '了解摩克納薩爾', '<李歐羅克斯用一種讓你的靈魂凝結的眼神注視著你的眼睛。>$B$B你來到摩克納薩爾，但是你不了解我們。你不了解我們鬥爭以求生存。$B$B假如你要了解我們，那麼你必須忍受一次那種鬥爭的滋味。$B$B南方是維克尼爾阿拉卡。他們在一個叫做索格瑪領土的洞穴裡奴役一群巨魔，而他們的領導人，維克也在那裡。$B$B殺了他!', '要開始你對摩克納薩爾的了解，就要殺掉維克，維克尼爾阿拉卡的領導者。然後，返回劍刃山脈的摩克納薩爾村找李歐羅克斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10847 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10847,'zhTW','斯克提斯之眼','斯克提斯瀰漫著一股不祥的氣息。$B$B恐怖的邪惡力量籠罩了整個鴉人氏族，命運已經露出猙獰的面孔。我們曾濫用黑暗魔法，做了不少壞事。在阿達爾的指引之下，我才瞭解到聖光的真諦，並由此得到救贖。$B$B泰羅克透過施放了黑暗魔法的寶珠監視斯克提斯的所有屬地。從泰羅卡森林北部的里斯克鴉巢和西諾鴉巢偷回寶珠，讓我也透過斯克提斯之眼看看泰羅克都在監視些什麼。','將里斯克鴉巢之眼和西諾鴉巢之眼交給撒塔斯城貧民窟的救贖者瑞拉克。','','去找撒塔斯城貧民窟的救贖者瑞拉克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10848 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10848,'zhTW','哈茲鴉巢：邪惡的幽靈','哈茲鴉巢是斯克提斯最邪惡的屬地。$B$B儘管奧金頓大爆炸將整座村落夷為平地，泰羅克的力量依然侵蝕了遊蕩在那裡的邪靈。轉至西邊的哈茲鴉巢，消滅那些可悲的幽靈。他們聚集在位於白骨荒野和泰羅卡森林邊界的暗影墓穴。$B$B這將是我們向泰羅克和斯克提斯守護者發動的第一輪攻擊。','殺死4只死爪幽魂、4個尖嘯幽魂和2只幽靈烏鴉，然後向難民車隊的基爾利克復命。','','去找白骨荒野難民車隊的覺醒者基爾利克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10849 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10849,'zhTW','尋找基爾利克','還有另一位鴉人也選擇了背棄泰羅克的道路，那就是覺醒者基爾利克。$B$B在基爾利克看來，泰羅克根本稱不上先知，不過是個誇誇其談的騙子罷了。泰羅克唯一預見到的只有他自己的惡行招致的厄運而已。$B$B基爾利克引領著我們勇敢地逃離了斯克提斯。而在我們轉至撒塔斯城尋求聖光的救贖時，他則轉至別的屬地搭救其它不甘墮落的鴉人。$B$B這封信件講述了泰羅克透過寶珠監視屬地的情況。必須把此事告訴基爾利克！走出撒塔斯城之後，你沿著南邊的道路進入白骨荒野，尋找難民車隊，就可以找到他。','將瑞拉克的信件交給白骨荒野難民車隊的覺醒者基爾利克。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10850 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10850,'zhTW','虛空氣體燃料','','','','去虛空風暴找未啟用的魔能機甲。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10851 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10851, 'zhTW', '敵人的圖騰', '尊敬一個人的祖先有正確的方式，也有錯誤的方式。$B$B劍刃巨魔帶著圖騰，但是他們並非用它們來表現他們的尊敬。相反的，他們想使用它們去操作並且控制。$B$B我們應該偷取他們的圖騰，因為他們不值得擁有!我們會把它們拿來做更好的利用。$B$B去西方的劍刃崗哨，就在剃刀山脊的西南邊。殺死劍刃秘法師和粉碎者，並從他們那裡拿走圖騰!', '收集5個劍刃氏族圖騰交給劍刃山脈的摩克納薩爾村的招魂師多赫加。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10852 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10852,'zhTW','失蹤的夥伴','我們在這裡遇到了大麻煩。一些鳥人趁著夜晚闖了進來，引起了一場大騷亂。太嚇人了。都不知道我們什麼時候才能繼續前進。$B$B而且，我的一些朋友在那次騷亂之後就不見了，我們完全不知道他們在哪。我想，搞不好是是那群可怕的鳥人把他們帶到西北邊去了。他們現在說不定正被鎖在籠子裡，說不定，都已經被吃掉了！如果你能去找他們的話，那就再好不過了。說實話，我非常擔心他們的安危。','伊森要你去基斯鴉巢找到12位失蹤的夥伴，然後回難民車隊向他覆命。','','去白骨荒野找難民車隊的伊森。','營救兒童','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10853 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10853, 'zhTW', '呼喚靈魂', '美聲山脊的虛空龍靈魂需要解放。$B$B虛空龍不永遠都是虛空龍。他們過去是黑龍。$B$B但是，由於這個世界的毀滅，一股虛空能量改變了一切，並且產生了改變幼龍蛋的副作用。$B$B現在他們全都是以前自身的扭曲版本。我們必須幫助他們找到平靜。$B$B要這樣做就要去殺死一隻靠近召靈圖騰的龍，然後自它身上取走它的靈魂。', '招魂師多赫加要你使用召靈圖騰收集8個次級虛空龍靈魂然後回到劍刃山脈的摩克納薩爾村交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10854 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10854,'zhTW','奈爾薩拉庫之力','帶上魔化靈藤水晶返回龍喉要塞。尋找被奴役的虛空幼龍，然後釋放靈藤水晶中的魔法能量。我的精華將噴湧而出，幫助幼龍掙脫束縛。幼龍受盡折磨必定相當虛弱，你得幫它打敗龍喉獸人！$B$B$N，解救被奴役的虛空幼龍，然後向我覆命。','解救5只被奴役的靈翼幼龍，然後向飛翔在影月谷靈翼平原上空的奈爾薩拉庫覆命。','','去影月谷找靈翼平原的奈爾薩拉庫。','解救被奴役的靈翼幼龍','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10855 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10855,'zhTW','魔能機甲？不了，謝謝！','對，沒錯，魔能機甲！它無疑是燃燒軍團所造出的最可怕的機械生物。情報顯示，燃燒軍團準備投入三臺魔能機甲對風暴尖塔發動攻擊。$B$B幸運的是，他們還沒有啟動這些機甲。我們可以趁機搞點破壞，而不用與這些機械怪物硬碰硬地死磕。$B$B轉至鑄魔基地：湮滅，從甘爾葛機械師手中奪得濃縮靈能瓦斯，然後將其注入魔能機甲的燃料箱中。我相信機甲的引擎根本無法承受這種烈性燃料。','從風暴尖塔西北方的鑄魔基地：湮滅裡的甘爾葛機械師身上收集5份濃縮的虛空氣體，將它們灌入附近一臺未啟用的魔能機甲內。完成任務後向虛空獵手納烏希思覆命。','','去虛空風暴找風暴尖塔的虛空獵手納烏希思。','','摧毀未啟用的魔能機甲','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10856 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10856,'zhTW','最好的防禦','破壞敵人的機械生物只能略微改善我們所處的窘境，$N。鑄魔基地：湮滅是燃燒軍團裝配魔能機甲的集結點，鑄魔基地：煉獄則是軍團的主營地，他們在那裡架設了大量的傳送裝置。$B$B我要你轉至鑄魔營地：煉獄，削減惡魔軍隊的數量。那裡駐紮著整編的天罰使者軍團，我們不能容忍這支部隊的存在。','虛空獵手納烏希思要你轉至風暴尖塔以北的鑄魔基地：煉獄，消滅12名天罰使者。','','去虛空風暴找風暴尖塔的虛空獵手納烏希思。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10857 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10857,'zhTW','傳送這個看看！','或許你覺得斬殺惡魔很有意思，但是燃燒軍團總是能透過傳送裝置迅速補充兵力，因此我們必須破壞他們的傳送裝置，才能一勞永逸地解決問題。$B$B可惜我這裡沒有高效能的爆炸物……但是我們可以向看守傳送裝置的莫爾葛惡魔“借”。$B$B帶上這根魔杖……它可以擾亂莫爾葛惡魔腦波的頻率。返回鑄魔基地：煉獄，對莫爾葛惡魔使用魔杖。它的控制時間不會太長，你必須利用這段時間對傳送裝置使用莫爾葛的爆破能力。','虛空獵手納烏希思要你轉至鑄魔基地：煉獄，對莫爾葛惡魔使用精神干涉魔杖，然後對鑄魔基地內的三處傳送裝置使用他們的引爆傳送器能力。','','去虛空風暴找風暴尖塔的虛空獵手納烏希思。','摧毀西部傳送器','摧毀中部傳送器','摧毀東部傳送器','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10858 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10858,'zhTW','卡瑞納庫','$N，還有一件事要麻煩你，真是不好意思；但你是我們惟一的希望。如果無法解放我的配偶，靈翼龍族很可能因為無法繁衍子嗣而滅亡。$B$B轉至龍喉要塞尋找卡瑞納庫。$B$B我們將在龍喉要塞上空盤旋。一旦他們的防線出現了缺口，我們就會立即飛下來，與你並肩作戰。','轉至龍喉要塞，尋找卡瑞納庫。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10859 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10859, 'zhTW', '收集寶珠', '雷森伊斯利有一種奇怪的儀器會發出微小、粉紅色光芒的飄浮光球。它們讓我想起靈魂。$B$B它們不會與伊斯利死亡時所釋放的大黃球相混淆，這些完全是別種東西。$B$B我要你到北方的雷森平台設置一些圖騰，這些圖騰將會攻擊粉紅光球。$B$B把它們帶回來給我這樣我才能確切地判斷它們是什麼。', '招魂師多赫加要你使用寶珠召集圖騰收集15個雷森光球。任務完成後回到劍刃山脈的摩克納薩爾村向他回報。', '', '', '收集雷森光球', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10860 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10860, 'zhTW', '摩克納薩爾的款待', '餓嗎，$r?偉大的靈魂會幫助那些自助者。如果你想要掙一頓飯，我建議你注意聽著，因為布拉格爾那裡不會給你任何免費的東西，而且也不可口!$B$B剃刀山脊和鱗翼沙洲的迅猛龍及鱗翼具有你從未嚐過之最美味的兩種佳餚中所需要的東西。把他們的迅猛龍肋骨和毒蛇肉帶來給我，我將為你做出這兩道菜。$B$B我甚至可以教你如何自己烹煮它們，如果你動作快的話。', '女總管瓦拉給你一份可以製作兩道他最喜歡的菜餚的材料名單，包含了3個迅猛龍肋骨還有3份毒蛇肉。回到劍刃山脈的摩克納薩爾村的把材料交給她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10861 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10861,'zhTW','雷希鴉巢：先發制人','西南方的雷希鴉巢是斯克提斯的屬地之一，泰羅克的爪牙企圖在鴉人幼雛孵化之前就令他們墮落。雷希鴉巢的黑暗巫師們對那些尚未孵化的蛋施加了暗影詛咒，一旦幼雛破殼而出，就會對泰羅克唯命是從。$B$B你現在立刻轉至雷希鴉巢，在詛咒生效之前打破鳥蛋。如果為時已晚的話，你可以殺掉那些邪惡的雛鳥。$B$B要記住，聖光在黑暗中最為耀眼。','打破雷希鴉巢中被詛咒的鳥蛋。解救3只雛鳥，並殺死3只邪惡的雛鳥，然後向難民車隊的基爾利克復命。','','去找白骨荒野難民車隊的覺醒者基爾利克。','救贖雛鳥','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10862 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10862,'zhTW','向部落投降','那些可惡的鴉人簡直是無孔不入，整天都在尋求著攻擊我們的機會。他們會襲擊我們派出去的獵人，有時候甚至還會侵入到我們的城牆之內。儘管我們已經在全力消滅他們，可他們的魔法太強，常常都能從我們手中逃走。$B$B不過，我還知道，另有一些鴉人聲稱他們不想與部落採取敵對態度，這些鴉人就居住在西北邊的撒塔斯城。救贖者瑞拉克是他們的首領。去貧民窟把他找出來，逼迫他向我們偉大的部落投降。','羅卡格要你在撒塔斯城貧民窟找到救贖者瑞拉克，逼迫他和他的同族向部落投降。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10863 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10863,'zhTW','鴉人的秘密','在邊境地區，我們每天都得對付這群鴉人的騷擾。他們想什麼時候攻擊就什麼時候攻擊，他們可能直接過來攻擊這裡，也可能襲擊我們的供給線，還可能殺掉我們派出去的斥候。$B$B可是，我們對這些神秘的生物知之甚少。我聽說在西北邊的撒塔斯城居住著一群友好的鴉人。或許他們會願意分享同族的秘密。$B$B救贖者瑞拉克是他們的首領，他就居住在貧民窟的北邊，去找他吧。','德娜·肯尼迪要你找到撒塔斯城貧民窟的救贖者瑞拉克，並與他談一談。看看他對鴉人都知道些什麼。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10864 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10864,'zhTW','收集靈魂','我有一種分析邪惡魔法的裝置，叫作惡魔占卜器。我想讓你使用它進行分析工作，但在那之前……你必須先取悅它。你看，這裡面囚禁著一個具備高度智慧的生物，它的需求……怎麼說呢……很古怪。$B$B要想取悅它，你就得殺獸人，而且還必須是碎手獸人。占卜器想要他們的靈魂。$B$B收割到足夠的靈魂後再回來找我。地獄火堡壘北邊、南邊以及堡壘周圍都有碎手獸人。','殺死20個碎手獸人，然後向索爾瑪的藥劑師安東尼維奇覆命。','','去地獄火半島找索爾瑪的藥劑師安東尼維奇。','收割碎手之魂','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10865 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10865,'zhTW','通知萊歐洛克斯！','快，你必須將拉扎安碼頭的情況告訴萊歐洛克斯！$B$B那些光球是由靈魂凝聚而成的，其中一些是莫克納薩氏族成員的靈魂！','喚靈者多戈加爾請你立即將拉扎安虛靈的陰謀告知萊歐洛克斯。萊歐洛克斯就在刀鋒山的莫克納薩村。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10866 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10866,'zhTW','疲憊的祖魯希德','他蟄伏在我的思想裡。等待我崩潰的那一刻……要我屈服於他的意志。$B$B他的死期到了。我要呼喚他，告訴他我願意俯首聽令。你必須趁他現身之際殺掉這個傢伙，拿到鑰匙！$B$B祖魯希德是位獸人長者，擁有深不可測的強大力量，他必定得到了伊利丹的力量。你是在用生命做賭注，你真的願意做這樣大的犧牲嗎？','殺死疲憊的祖魯希德，取回祖魯希德的鑰匙，並用它開啟祖魯希德的鎖鏈，釋放卡瑞納庫。','','去影月谷找龍喉要塞的卡瑞納庫。','解救卡瑞納庫','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10867 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10867,'zhTW','只有一個辦法','只有一個辦法能阻止他們……阻止他們褻瀆莫克納薩氏族先祖的靈魂！$B$B願亡者的靈魂能享受安寧……$N，如果你願意幫助我們的話，就立即返回拉扎安碼頭。$B$B殺死拉扎安虛靈，直到他們的首領節點親王拉扎安露面。從拉扎安手中奪得靈魂之盒，然後將它交給喚靈者多戈加爾！','奪得靈魂之盒。','','去刀鋒山找莫克納薩村的喚靈者多戈加爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10868 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10868,'zhTW','鴉人的戰爭','那些鴉人再次偷襲了我們，他們這一次在夜間侵入，行動迅速，而且在我們的主力部隊衝出去反擊之前就利用黑暗魔法逃走了，甚至還有空利用召喚法陣救走了那些已被我軍重創的士兵。但是，如果我們去攻擊他們的老巢，他們恐怕就沒有辦法逃走了。里斯克鴉巢和西諾鴉巢就在北邊和東北邊。$B$B立刻找到這兩個巢穴，消滅盡量多的鴉人。','顧問菲埃拉要你殺掉14個西諾鴉爪戰士和6個西諾巫師，然後返回裂石堡向她覆命。','','去泰羅卡森林找裂石堡的顧問菲埃拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10869 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10869,'zhTW','剿滅鴉人','那群該死的鴉人再次攻擊了我們。這一次他們趁著天黑進行襲擊，然後趁我們集結軍隊反攻之前，利用他們的黑暗魔法逃走了。$B$B我要你立刻轉至北邊的里斯克鴉巢和西邊的西諾鴉巢，到那裡去幹掉裡面的所有鴉人。他們看來對我們完全沒有任何畏懼之意，所以我們至少要削弱他們的力量，若能震懾到他們，則更好。','加維·砂錘中尉要你殺掉14個西諾鴉爪戰士和6個西諾巫師，然後返回奧蕾莉亞要塞向他覆命。','','去泰羅卡森林找奧蕾莉亞要塞的加維·砂錘中尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10870 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10870,'zhTW','靈翼之盟','讓我送你回到莫德奈那裡吧。他一定想要再見你一面。','讓卡瑞納庫把你送回靈翼平原的莫德奈身邊。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10871 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10871,'zhTW','靈翼之盟','讓我送你回到莫德奈那裡吧。他一定想要再見你一面。','讓卡瑞納庫把你送回靈翼平原的莫德奈身邊。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10872 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10872,'zhTW','疲憊的祖魯希德','他蟄伏在我的思想裡。等待我崩潰的那一刻……要我屈服於他的意志。$B$B他的死期到了。我要呼喚他，告訴他我願意俯首聽令。你必須趁他現身之際殺掉這個傢伙，拿到鑰匙！$B$B祖魯希德是位獸人長者，擁有深不可測的強大力量，他必定得到了伊利丹的力量。你是在用生命做賭注，你真的願意做這樣大的犧牲嗎？','殺死疲憊的祖魯希德，取回祖魯希德的鑰匙，並用它開啟祖魯希德的鎖鏈，釋放卡瑞納庫。','','去影月谷找龍喉要塞的卡瑞納庫。','解救卡瑞納庫','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10873 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10873,'zhTW','夜間的綁架','我們的前哨站不斷地遭到各類攻擊。幾天前的一個晚上，白骨荒野東南邊緣靈網山脊一帶的蜘蛛甚至也向我們發動了一次突然襲擊。它們向我們許多同伴噴射了毒液，然後用蜘蛛網將他們裹起後帶走了。一些士兵勇敢地拿起武器抵抗這次攻擊，可他們在那些蜘蛛撤退後卻也毫無準備地追了上去。$B$B自那以後，我們再也沒見過被捉走的人和那些轉至追擊的士兵。我們希望還有他們都還活著，只是被蜘蛛囚禁了起來。不過，我們的人手已經不多了，無法分兵轉至救援。你願意幫我去尋找我們的同伴嗎？','斥候納弗林要你去靈網山脊解救6名被網住的沙塔爾戰士，然後返回沙塔爾營地向他覆命。','','去白骨荒野找沙塔爾營地的斥候納弗林。','解救沙塔爾戰士','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10874 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10874,'zhTW','沙拉斯鴉巢：訊號火焰','泰羅克的老巢斯克提斯位於白骨荒野以東，那裡的沙拉斯鴉巢是泰羅克勢力範圍內最難以對付的屬地。泰羅克的先遣軍就在沙拉斯鴉巢的要塞公然向聖光挑起了戰爭。$B$B沙拉斯鴉巢的駐軍利用複雜的魔法訊號火焰與他們的主人傳遞資訊。$r，轉至東邊的沙拉斯鴉巢熄滅訊號火焰。只有阻止沙拉斯鴉巢傳遞訊息，我們才有可能摧毀整個斯克提斯。$B$B但是，現在說這個還為時過早。','難民車隊的基爾利克要你熄滅沙拉斯鴉巢的4簇訊號火焰。','','去找白骨荒野難民車隊的覺醒者基爾利克。','熄滅藍玉訊號火焰','熄滅翡翠訊號火焰','熄滅紫羅蘭訊號火焰','熄滅血石訊號火焰',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10875 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10875,'zhTW','向納茲格雷爾報到','在你利用惡魔占卜器進行探測活動時，我把你在這邊針對邪獸人的行動報告發去了索爾瑪。而我們卓越的領袖納茲格雷爾似乎想與你談談。我相信他心裡一定有了一個完美的計劃……','與地獄火半島的索爾瑪的納茲格雷爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10876 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10876,'zhTW','城牆之底','指揮官戈拉克斯正在地獄火堡壘外訓練碎手軍官，要把這些軍官磨礪成最嗜血的利刃。你必須殺死他，$N。失去他對邪獸人來說將是一次非常沉重的打擊。$B$B但是，光殺死他還不夠。$B$B你把這面旗子帶上，到時候別忘了插在他旁邊。戈拉克斯的上級——卡加斯之手——如果還流淌有哪怕一滴真正的獸人之血，那麼他就一定會接受你的挑戰！$B$B卡加斯之手的徽記，就是我想要的東西。','殺死指揮官戈拉克斯，將部落的挑戰插在他旁邊。然後殺死卡加斯之手，將卡加斯之手的徽記交給索爾瑪的納茲格雷爾。','','去地獄火半島找索爾瑪的納茲格雷爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10877 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10877,'zhTW','恐怖聖物','很久以前，有一支車隊奉命轉至奧金頓古老的墓穴中尋找恐怖聖物。找到聖物之後，他們被那強大的力量嚇得逃走了，但聖物卻仍然毀滅了他們。那個聖物中蘊涵著邪惡的力量，一旦被觸碰就能召喚出強大的妖魔。後來，他們所有人都死在了篷車旁，就在這裡向東的某個地方。$B$B不過，這個黑暗的神器卻是擊敗那隻飄蕩在白骨荒野上的受詛者泰里布斯的關鍵之物。如果你願意的話，就幫我把它找回來，要小心，你的生命，甚至是你的靈魂都將面臨危險。','沃爾昆要你去東邊被遺棄的篷車找回恐怖聖物。任務完成後向沃爾昆覆命。','','去白骨荒野找沙塔爾營地的沃爾昆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10878 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10878,'zhTW','黑暗前夕','我們的車隊遭到暗影議會秘教信徒的襲擊之後，派遣了一位斥候來到撒塔斯城尋求幫助。可是，這裡的衛兵卻認為我們現在已經安全了，他們完全低估了那些瘋子。$B$B總之，我們絕對會被這些秘教新兵在半夜裡割破喉嚨。所以，你最好能在他們來攻擊我們之前把他們解決掉。$B$B在南邊的奧金頓北門就能找到那些襲擊者。','難民車隊的米克達要你消滅8名秘教散兵，4名秘教織法者和2名秘教新兵。','','去白骨荒野找難民車隊的米克達。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10879 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10879,'zhTW','斯克提斯的攻勢','斯克提斯對我們發動了攻擊！你召集到足夠的盟友守護撒塔斯城了嗎？$B$B阻止他們的攻擊！','擊敗入侵者，然後與瑞拉克談一談。','抵擋進攻','去找撒塔斯城貧民窟的救贖者瑞拉克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10880 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10880,'zhTW','秘教的命令','這封信上印有一個黑色的圖章，儘管它所使用的語言你可以理解，但似乎仍然使用了某些暗語。$B$B或許難民車隊裡有人能讀得懂這封信。','將秘教的命令交給泰羅卡森林難民車隊的米克達。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10881 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10881,'zhTW','暗影墓穴','許多人認為是暗影議會制造了爆炸使得奧金頓被炸得粉碎。根據這個傳說所說，他們喚醒了居住在奧金頓裡的一個非常邪惡的存在。$B$B如果傳聞是真的，那個惡魔一定與他們發生了激烈的戰鬥。根據這份命令所述，一些暗影議會成員逃離了奧金頓，並將許多聖物藏在了暗影墓穴。$B$B這其中，有三件聖物是非常強大的，它們是偉大的祖先阿魯內、克埃林和阿塔洛的遺物。我要你去把它們找回來。','進入難民車隊西邊的暗影墓穴，找回阿魯內的披風、克埃林的木槌和阿塔洛的卷軸。任務完成後返回難民車隊向米克達覆命。','','去白骨荒野找難民車隊的米克達。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10882 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10882,'zhTW','末日的預言者','<阿達爾發出的樂聲中突然攙雜了幾個“不悅的”重音。>$B$B凱爾薩斯王子的典獄官真是蹩腳，被關押在禁魔監獄的怪物已經掙脫了束縛。$B$B其中有一個名叫預言者斯克瑞斯的，這位上古之神的僕從妄圖實現他主人那征服世界的狂想。$B$B你必須阻止他逃出禁魔監獄，$N。進入風暴要塞的禁魔監獄，殺死預言者斯克瑞斯，阻止事態的進一步惡化！','進入風暴要塞的禁魔監獄，殺死預言者斯克瑞斯。完成任務後返回撒塔斯城的聖光廣場，向阿達爾覆命。','','去撒塔斯城找貧民窟的阿達爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10883 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10883,'zhTW','風暴鑰匙','你已經證明自己有著卓越的能力，$N。你發現了詛咒密碼，並調查到凱爾薩斯的捲入，這對我們來說十分重要。若是凱爾使用詛咒密碼的話，唯一可預知的結局就是這個世界將徹底崩壞。$B$B阿達爾認為一定要派人去阻止凱爾薩斯，並且他正在尋找能夠完成試煉的冒險者。只有那些擁有真正力量的勇士才會受到納魯的青睞。$B$B<卡德加點了點頭。>$B$B阿達爾正在等著你……','與撒塔斯城的阿達爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10884 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10884,'zhTW','納魯的試煉：仁慈','想要證明你自己擁有獲得風暴鑰匙的資格，你必須首先完成四個試煉。$B$B近日裡，有三名你的同族被囚禁在地獄火堡壘的破碎大廳中。他們被殘忍無情的卡加斯·拳刃所逮捕，很快就要被他以展示力量與氣概為由處死。你必須在這場暴行發生之前將這些可憐的囚徒拯救出來。你要帶回劊子手還未來得及使用的斬首斧作為證據。斧刃上不能有一滴鮮血存在！','撒塔斯城的阿達爾要求你從地獄火堡壘的破碎大廳中取回未使用的劊子手之斧。$B$B該任務必須在英雄等級難度的地下城中完成。','','去撒塔斯城找貧民窟的阿達爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10885 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10885,'zhTW','納魯的試煉：力量','想要證明你自己擁有獲得風暴鑰匙的資格，你必須首先完成四個試煉。$B$B力量的試煉將被分為兩部分。你必須摧毀盤牙水庫蒸汽地窟的首領，督軍卡利瑟里斯，並帶回他的三叉戟。此外，你還要殺死躲藏在奧金頓暗影迷宮中的外位面生物摩摩爾，並把他的精華給我帶回來。$B$B完成了這些，你就透過了力量之試煉。','撒塔斯城的阿達爾要求你取回卡利瑟里斯的三叉戟和摩摩爾的精華。$B$B該任務必須在英雄等級難度的地下城中完成。','','去撒塔斯城找貧民窟的阿達爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10886 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10886,'zhTW','納魯的試煉：堅韌','想要證明你自己擁有獲得風暴鑰匙的資格，你必須首先完成四個試煉。$B$B在我們長年的位面旅行中，我們遭遇過許多危險的存在。其中，有一部分這樣的生物被我們囚禁在了風暴要塞的禁魔監獄裡。$B$B其中，有一名囚徒卻是個無辜的犧牲品。他是一個在錯誤的時間登上錯誤飛船的偷渡者。$B$B立刻轉至禁魔監獄，救出侏儒米爾豪斯·法力風暴。確保他活著出來。','撒塔斯城的阿達爾要求你從風暴要塞的禁魔監獄中救出米爾豪斯·法力風暴。$B$B該任務必須在英雄等級難度的地下城中完成。','營救米爾豪斯·法力風暴','去撒塔斯城找貧民窟的阿達爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10887 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10887,'zhTW','逃離墓穴','我很感激你的幫助，$N。我還以為我會被殺掉呢。$B$B不過，現在我們得趕緊離開這裡了，用不了多久就會有更多的秘會教徒來追捕我們。','幫助阿庫諾回到泰羅卡森林的難民車隊。任務完成後與米克達談一談。','護送阿酷諾','去白骨荒野找難民車隊的米克達。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10888 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10888, 'zhTW', '那魯的試煉:瑪瑟里頓', '在你被那魯認可之前，你必須通過四次考驗。$B$B只剩一個障礙了，凡人。召集一支軍隊並且前往地獄火堡壘深處的瑪瑟里頓巢穴。一路殺進密室的中心，並毀滅那邪惡的腐敗者!', '撒塔斯城的阿達歐要你殺死瑪瑟里頓。', '', '去找沙塔斯城的阿達歐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10889 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10889,'zhTW','返回沙塔斯','泰羅克必定會發動復仇的反攻。$B$B立即轉至撒塔斯城，向瑞拉克報信！','轉至撒塔斯城，與貧民窟的救贖者瑞拉克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10890 AND `locale` = 'zhTW';
