INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10935,'zhTW','尤勒斯的驅魔儀式','$N，現在我們必須去拯救尤勒斯上校了。他的狀況又有惡化，巴拉達擔心如果我們還不能淨化他身上的腐蝕，他就要永遠離開我們了。$B$B拿著這串念珠去找學者巴拉達，馬上開始儀式。不要讓任何人打擾到儀式的進行……，如果一切順利，我想尤勒斯上校還是能拯救回來的。他的情況好轉之後，和他談談，然後再回來找我。','與學者巴拉達交談，利用祈禱唸珠幫助巴拉達完成儀式。與獲救的尤勒斯上校交談，然後向助手克拉圖覆命。','','去地獄火半島找榮耀堡的助手克拉圖。','拯救尤勒斯上校','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10936 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10936,'zhTW','托爾貝恩在找你','剛才我們正在忙碌的時候，有位信使一直等在大廳裡。我想他現在已經累得去休息了，要麼就是看到尤勒斯的身體浮起來的時候被嚇跑了吧。$B$B不管了，總之他說遠征軍指揮官達納斯正在找你。我建議你現在馬上就去兵營裡請求覲見他。','助手克拉圖要你轉至地獄火半島榮耀堡的兵營，與遠征軍指揮官達納斯·托爾貝恩談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10937 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10937,'zhTW','教官祖羅克','我收到的情報顯示，地獄火堡壘內外的所有碎手邪獸人正在嚴密的組織下準備發動一次全面攻擊。毫無疑問，他們對於你前幾日針對各邪獸人氏族所取得的成功很惱火，想要展開報復行動。$B$B現在你只要沿著榮耀之路走到頭，到達堡壘的下面，你就會發現所有的邪獸人都在忙著進行準備工作，這下你就能攻其不備了。$B$B殺死他們的頭目，教官祖羅克！','遠征軍指揮官達納斯·托爾貝恩命令你儘快殺死教官祖羅克。完成任務後返回地獄火半島的榮耀堡，向遠征軍指揮官覆命。','','去地獄火半島找榮耀堡的遠征軍指揮官達納斯·托爾貝恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10938 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10938,'zhTW','暗月祝福套牌','你現在已經收集到了祝福套牌的所有卡片，與前8張的背面圖案完全一樣的第9張卡片神秘地出現在你手中。在這張卡片上寫著，“將這些卡片拿到暗月馬戲團去，你就將獲得獎勵。”你聽說暗月馬戲團每過幾個月就會路過一次莫高雷和閃金鎮，因此你也許需要等待一段時間才能看到他們。','當暗月馬戲團來到鎮上的時候，把祝福套牌交給他們。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10939 AND `locale` = 'zhTW';
