INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10942,'zhTW','兒童周','有你做伴，哪怕只有很短的幾天，我們的這位小姑娘也一定會非常開心。$B$B收下這隻孤兒哨吧。只要吹響它，就可以召喚出你要照看的小孩子。你只需要負責照顧她一段時間就可以了——實際上就是兒童週期間。$B$B$N，召喚出這個孩子吧。她肯定迫不及待地想要跟你見面，隨你探索城外的美麗世界！','使用血精靈孤兒哨召喚出你將在兒童週期間照看的小孩。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10943 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10943,'zhTW','兒童周','有你做伴，哪怕只有很短的幾天，我們的這位小姑娘也一定會非常開心。$B$B收下這隻孤兒哨吧。只要吹響它，就可以召喚出你要照看的小孩子。你只需要負責照顧她一段時間就可以了——實際上就是兒童週期間。$B$B$N，召喚出這個孩子吧。她肯定迫不及待地想要跟你見面，隨你探索城外的美麗世界！','使用德萊尼孤兒哨召喚出你將在兒童週期間照看的小孩。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10944 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10944,'zhTW','危險的秘密','再次感謝你，$N，我知道你的名字。既然阿卡瑪相信你，讓你加入了他的計劃，那麼我也將給予你完全的信任。$B$B納迦已經發現我正在謀求推翻伊利丹的統治，還想用拷打與折磨這些老掉牙的手段讓我說出秘密。真可惜，我什麼也沒有告訴他們，冥想的力量幫我抵抗住了神經中傳來的痛苦……而這些，正是阿卡瑪教給我的。$B$B後來，伊利丹要求這些納迦把我帶到他那裡去。他可以直接看穿我的軀體，進入我的靈魂，竊取其中的秘密。$B$B必須向阿卡瑪報告這一切，我們的計劃當前已經陷入了極度的危機之中！','轉至影月谷內的守望者牢籠，與阿卡瑪談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10945 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10945,'zhTW','哈克烏和蘑菇人','我有個朋友叫哈克烏。她說她曾經被邪惡的真菌巨人追趕，慌亂之中迷了路，所幸被孤兒院收留。$B$B我們在這兒快樂地生活著，直到去年她的家人得知她的下落，接她離開了孤兒院。我記得她住在一個名叫孢子村的地方。$B$B我想去看看她和她生活的蘑菇村莊。孤兒院監護員說孢子村就在孢子湖和沼光湖之間，就在贊加沼澤西部。$B$B帶我去好嗎？帶我去好嗎？求你了？！','帶上孤兒薩蘭蒂亞，轉至位於贊加沼澤的孢子村。如果你抵達時發現她不在身邊，記得要先召喚她。然後，跟哈克烏談一談。','帶薩蘭蒂亞轉至孢子村','去找贊加沼澤的哈克烏。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10946 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10946, 'zhTW', '[Ruse of the Ashtongue]', '[Olum\'s sacrifice was tremendous.  I would never have asked him to give up his life myself.  But it is done.$B$BIf we\'re to lure Illidan back into a false sense of security, we need to do his bidding - at least for now.$B$BI command a vast army of Ashtongue, but - aside from the Deathsworn - none can be trusted.$B$BYou are to perform the deed that Illidan demands.  Take this cowl; it is magical in nature.  You will appear to be one of my men to any who see you slaying Kael\'s phoenix, Al\'ar.]', '[Travel into Tempest Keep and slay Al\'ar while wearing the Ashtongue Cowl.  Return to Akama in Shadowmoon Valley once you\'ve completed this task.]', '灰舌氏族的詭計', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10947 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10947, 'zhTW', '[An Artifact From the Past]', '[Illidan\'s attention is now on Kael\'thas, thanks to you.  The time has come to make our move.$B$BI\'ve had a vision of an artifact that will aid us in our final struggle - the phylactery of a lich known as Winterchill.  Unfortunately its power was lost forever after his defeat in the Battle of Mount Hyjal.$B$BThere might be a way to retrieve this artifact, however.  Legend speaks of a place in Azeroth guarded by bronze dragons...  a place where past and present meet.  It is there you will find what we seek.]', '[Go to the Caverns of Time in Tanaris and gain access to the Battle of Mount Hyjal.  Once inside, defeat Rage Winterchill and bring the Time-Phased Phylactery to Akama in Shadowmoon Valley.]', '', '去影月谷找守望者牢籠的阿卡瑪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10948 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10948, 'zhTW', '', '', '[Travel to Shattrath City to tell A\'dal about Akama\'s request.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10949 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10949, 'zhTW', '', '', '[Travel to the entrance to the Black Temple in Shadowmoon Valley and speak to Xi\'ri.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10950 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10950,'zhTW','奧金頓的儀式廣場','有位路經孤兒院的牧師跟我們講過奧金頓的故事，據說那地方對德萊尼一族至關重要，就在這附近哦。$B$B他說奧金頓曾經是德萊尼人的埋骨地，但是不久前發生了爆炸事件。$B$B我想去奧金頓的儀式廣場看看。孤兒院監護員說那地方就在白骨荒野的中間，泰羅卡森林的南部。$B$B親愛的$N$G先生:小姐，拜託你，帶我去好嗎？','帶上孤兒多爾南，轉至位於奧金頓中心儀式廣場的集合石。奧金頓就在泰羅卡森林內的白骨荒野的中心地帶。如果你抵達時發現她不在身邊，記得要先召喚她。','帶多爾南轉至儀式廣場','使用你的孤兒哨召喚德萊尼孤兒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10951 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10951,'zhTW','參觀黑暗之門','我們遊覽了這麼多有趣的地方，怎麼能錯過黑暗之門呢？！$B$B大人們總是跟我們講那些關於黑暗之門的恐怖故事，他們說那兒有很多惡魔和其它詭異生物，總之是個非常危險的地方。$B$B<薩蘭蒂亞轉動著眼珠。>$B$B但是有你保護我，情況應該不會太糟，是嗎？$B$B我想去親眼看看。黑暗之門應該在地獄火半島東部邊緣吧，你還記得確切的方位嗎？','帶上孤兒薩蘭蒂亞，登上命運階梯，站在地獄火半島的黑暗之門前。如果你抵達時發現她不在身邊，記得要先召喚她。','帶薩蘭蒂亞轉至黑暗之門','使用你的孤兒哨召喚血精靈孤兒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10952 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10952,'zhTW','參觀黑暗之門','要是我們沒別的地方可去，那就去黑暗之門吧！$B$B孤兒監護員們總是說那兒很危險，居住著很多惡魔什麼的，還說只有象你這樣的英雄才能跨越黑暗之門。$B$B<多爾南轉動著眼珠。>$B$B但是有你保護我，情況應該不會太糟，是嗎？$B$B我真得很想去親眼看看。黑暗之門就在地獄火半島東部邊緣吧，你還記得確切的方位嗎？','帶上孤兒多爾南，登上命運階梯，站在地獄火半島的黑暗之門前。如果你抵達時發現她不在身邊，記得要先召喚她。','帶多爾南轉至黑暗之門','使用你的孤兒哨召喚德萊尼孤兒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10953 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10953,'zhTW','參觀元素王座','你知不知道元素王座這個地方？據說啊，它就在納格蘭大草原上，那兒有許多許多強大的元素生物。$B$B很快，我就要變成為一個厲害的法師了，或者術士也行！我得掌握駕馭元素力量的能力。$B$B要不咱倆一起去元素王座？$B$B<薩蘭蒂亞狡猾地看著你。>$B$B你肯定會獲益良多的！那地方就在加拉達爾北邊，天歌湖的對岸。','帶上孤兒薩蘭蒂亞，轉至位於納格蘭的元素王座。如果你抵達時發現她不在身邊，記得要先召喚她。然後，與元素師沙爾瓦克談一談。','帶薩蘭蒂亞轉至元素王座','去找納格蘭的元素師沙爾瓦克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10954 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10954,'zhTW','埃瑞斯碼頭的希爾！','我有點想念我的哥哥希爾了。他比我大幾歲，所以監護員們讓他去納格蘭給虛靈們當學徒了。$B$B要是能去看看他就好了。他一直很喜歡地質學一類的東西，想必他在那兒過得挺開心的。$B$B孤兒監護員跟我說他在納格蘭一處名叫埃瑞斯碼頭的地方受訓。埃瑞斯碼頭就位於沃舒古山脈的西北方，沿著塔拉西邊的道路一直走就能到。','帶上孤兒多爾南，轉至位於納格蘭的埃瑞斯碼頭。如果你抵達時發現她不在身邊，記得要先召喚她。然後與希爾談一談。','帶多爾南轉至埃瑞斯碼頭','去找納格蘭的希爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10955 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10955,'zhTW','莫希斯·輕翼','早在塞納里奧議會統一所有的德魯伊教派之前，猛禽德魯伊就負責將飛行的訣竅傳授給那些年輕有為的德魯伊。猛禽德魯伊教派解散後，原先的成員在傳授飛行訣竅時就更為小心謹慎了。$B$B莫希斯·輕翼仍然在挑選合適的學徒，只有為數很少的德魯伊能掌握各種形態，不過你似乎可以滿足莫希斯對學生的要求。去贊加沼澤的塞納里奧庇護所找他吧。','與贊加沼澤塞納里奧庇護所的莫希斯·輕翼談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10956 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10956,'zhTW','納魯之座','你知道納魯的故事嗎？這些天使般的神靈一直以來都在無私地幫助德萊尼人。我曾在撒塔斯城附近見過他們。$B$B他們說有一位名叫沃洛斯的納魯去了你們的世界，就在艾克索達城中。我想親眼看看他。$B$B你能帶我去嗎？我敢打賭，要是我們利用撒塔斯城聖光廣場的傳送門，一定很快就能到達那兒！要是你在艾克索達中迷了路，可以隨時檢視你的地圖。','帶上孤兒多爾南轉至秘藍島的艾克索達，將她帶到納魯之座底部的沃洛斯面前。如果你到達時她不在你身邊，記得召喚她。$B$B進入主城後你可以檢視地圖確定沃洛斯的位置。','帶多爾南轉至納魯之座','去秘藍島找艾克索達的沃洛斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10957 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10957, 'zhTW', '[Redemption of the Ashtongue]', '[When Illidan obtained the Broken\'s allegiance, Akama was our wisest.  He knew that openly opposing the Betrayer would lead to the extinction of our race.$B$BInstead he has plotted and schemed for this very moment under utmost secrecy.  Failure would be catastrophic... not just for Akama, not just for the Broken, but for all of Outland.  No one this close to Illidan has ever been able to deliver such a terrible blow to him.$B$BHelp Akama free his soul and he will grant you access to Illidan\'s sanctum.]', '[Help Akama wrest control back of his soul by defeating the Shade of Akama inside the Black Temple.  Return to Seer Kanai when you\'ve completed this task.]', '', '去找黑暗神廟的先知卡奈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10958 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10958, 'zhTW', '', '', '[Find Akama\'s Deathsworn inside the Black Temple.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10959 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10959, 'zhTW', '[The Fall of the Betrayer]', '[With Illidan\'s lieutenants defeated, Akama will be able to force open the doors to Illidan\'s sanctum.  Be ready to bring your force inside as soon as Akama does.$B$BWe still do not know what has become of Maiev, but we must make our move without her.$B$BI hope your force is up to the task.  Illidan will not be pleased to see Akama.]', '[Seer Kanai wants you to defeat Illidan inside the Black Temple.]', '', '去找黑暗神廟的先知卡奈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10960 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10960,'zhTW','等我長大了……','你在我這個年紀時，能確定自己長大後要成為一名$c嗎？$B$B反正現在我還不太確定呢。法師？術士？或是聖騎士？血騎士？啊，我要成為一名血騎士！$B$B他們說真正的血騎士在銀月城傳授聖光的教義，那是你們的世界吧。你能帶我去那兒嗎？我聽說聖騎士訓練師在銀月城的遠行者廣場。$B$B帶我去吧。求你了！','將孤兒薩蘭蒂亞帶到銀月城遠行者廣場的聖騎士訓練師面前。如果你到達時她不在你身邊，記得召喚她。然後跟血騎士的領袖女伯爵莉亞德琳談談。$B$B進入主城後你可以檢視地圖並詢問衛兵，確定聖騎士訓練師的位置。','帶薩蘭蒂亞轉至銀月城拜訪聖騎士訓練師','去找銀月城的女伯爵莉亞德琳。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10961 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10961,'zhTW','喚醒戒衛','很久之前，用於傳授風暴烏鴉形態知識的聖物被託付給克林塔爾·夢行者保管。$B$B克林塔爾的軀體在月光林地的獸穴中休眠，他的靈魂則在翡翠夢境中徜徉。$B$B我得準備一劑可以令他的靈魂復甦的藥膏。製造這種混合劑需要一些普通的草藥，還有生長在贊加沼澤高大的蘑菇頂端的沼澤花。採集沼澤花的時候要小心，它們非常脆弱，而且可能會爆發出致命的毒氣。','將10株沼澤花、10簇遠古苔和10株夢露花交給塞納里奧庇護所的莫希斯·輕翼。','','去找贊加沼澤的莫希斯·輕翼。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10962 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10962,'zhTW','參觀時光之穴','曾經有位年老的牧師路經孤兒院，給我們講過時空之穴的故事。他說位於時間中心的時空之穴起著維護歷史程序的重要作用。$B$B我不知道那是什麼意思，但是他說那兒駐守著守護世界的龍族！我想看看龍長什麼樣！$B$B我們可以去時空之穴嗎？那位牧師說入口就在那片名叫塔納利斯的沙漠東部邊緣。$B$B我們去了那裡之後，你能給我買件紀念品嗎？','將孤兒多爾南帶到時光之穴中央平臺上的扎拉多姆面前。如果你到達時她不在你身邊，記得召喚她。$B$B然後在時間守護者的軍需官艾魯爾米那兒為她購買一個玩具龍，艾魯爾米就在入口通道底部附近。','帶多爾南轉至時光之穴','使用你的孤兒哨召喚德萊尼孤兒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10963 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10963,'zhTW','參觀時光之穴','曾經有位年老的牧師路經孤兒院，跟我們講起時光之穴的故事。他說位於時間中心的時光之穴起著維護歷史程序的重要作用。$B$B我不知道那是什麼意思，但是他說那兒駐守著守護世界的龍族！我真想看看龍是長什麼樣的啊！$B$B我們可以去時光之穴嗎？那位牧師說入口就在那片名叫塔納利斯的沙漠東部邊緣。$B$B還有還有，我們去了之後，你可以給我買件紀念品嗎？','將孤兒薩蘭蒂亞帶到時空之穴中央平臺上的扎拉多姆面前。如果你到達時她不在你身邊，記得召喚她。$B$B然後在時光守護者的軍需官艾魯爾米那兒為她購買一個玩具龍，艾魯爾米就在入口通道底部附近。','帶薩蘭蒂亞轉至時光之穴','使用你的孤兒哨召喚血精靈孤兒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10964 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10964,'zhTW','喚醒沉睡者','帶上喚醒戒衛轉至月光林地的怒風獸穴。克林塔爾·夢行者就在最南端的那個駐有夢境守衛者的洞穴中。$B$B喂他服下藥膏，等待他慢慢甦醒。在克林塔爾·夢行者的靈魂與身體重新結合的過程中，他會處於異常脆弱的狀態；當然，他是不可能認出你的。$N，一旦他恢復神志，請立即通報你的身份。他需要你的幫助才能收集到儀式所需的聖物。','使用喚醒戒衛幫助克林塔爾·夢行者從翡翠夢境中甦醒。當他恢復意識後跟他談談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10965 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10965,'zhTW','夢境危機','<克林塔爾聽你傳達莫希斯的指示，他點著頭，臉上卻流露出憂慮的神情。>$B$B我無法完全從翡翠夢境中脫身，但是這塊取自我的靈魂的碎片可以幫助你尋找聖物。$r，好好保護它，這東西相當脆弱。$B$B翡翠夢境已經成為了危機重重的是非之地。它緊緊地抓住我，只有等這兒恢復正常，我才可能全身而退。你所看到的不過是夢境中折射出的影像！','在克林塔爾·夢行者的靈魂收集艾維娜聖物時保護他，然後與夢境衛士魯羅薩談一談。','','去月光林地找月神湖的夢境衛士魯羅薩。','協助克林塔爾收集聖物','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10966 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10966,'zhTW','返回孤兒院','糟糕！我該返回撒塔斯城的孤兒院了。$B$B跟你在一起的日子非常愉快。$N，你是世界上最好的人！就像我的大$g哥哥:姐姐一樣！$B$B<多爾南的眼中泛起淚花。>$B$B我會想你的！長大之後，我要做一個像你一樣的人！！！','將德萊尼孤兒哨歸還給撒塔斯城貧民窟的孤兒院長莫希。','','去找撒塔斯城的孤兒院長莫希。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10967 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10967,'zhTW','返回孤兒院','糟糕！我該返回撒塔斯城的孤兒院了。$B$B跟你在一起的日子非常愉快。$N，你是世界上最好的人！就像我的親$g哥哥:姐姐一樣！$B$B<薩蘭蒂亞的眼中泛起淚花。>$B$B我會想你的！長大之後，我要做一個像你一樣的人！！！','將血精靈孤兒哨歸還給撒塔斯城貧民窟的孤兒院長莫希。','','去找撒塔斯城的孤兒院長莫希。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10968 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10968,'zhTW','拜訪預言者','我感覺得出，這孩子頗有與眾不同之處。$B$B你應該帶她去見艾克索達的預言者努波頓。我想他一定盼著你們倆呢。$B$B努波頓大人就在水晶大廳的最頂層。','帶上孤兒多爾南，轉至秘藍島艾克索達的水晶大廳拜訪預言者努波頓。如果你到那兒時她不在你身邊，記得召喚出她來。$B$B記住，你在城裡可以檢視地圖。','帶多爾南拜訪預言者努波頓','去秘藍島找艾克索達的預言者努波頓。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10969 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10969,'zhTW','尋找阿米爾','似乎某個外界勢力對星界財團的生意產生了濃厚的興趣。這兩天已經有五名星界財團的代理人失蹤了，我們懷疑此事與復仇軍有關。如果你願意協助調查的話，請直接聯絡維序派哨站的指揮官阿米爾。哨站就設立在東邊的浮島上。','轉至維序派哨站，找到指揮官阿米爾。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10970 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10970,'zhTW','拯救任務','上次進入復仇軍的地盤執行偵察任務時，我們發現了這個球狀監牢並將它帶了回來。當時要不是監牢中發出微弱的求救訊號，我們根本不會留意到它。$B$B我們猜測有位夥伴被困在這裡面，但是想要不傷害裡面的人就開啟它幾乎是不可能的。$B$B或許復仇軍的成員可能會隨身攜帶著這個監牢的鑰匙。只要奪得一把鑰匙，我們就能揭開其中的秘密了。','為虛空風暴維序派哨站的指揮官阿米爾奪得復仇軍監獄鑰匙。','','去虛空風暴找維序派哨站的指揮官阿米爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10971 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10971,'zhTW','復仇軍的秘密','<阿米爾舉起一枚標識牌。>$B$B我在一名維序派前鋒的屍體上找到了這塊身份標識牌。我猜他們在所有的囚犯身上都掛上了這種標識牌。$B$B接下來，我要將這些標識牌歸檔研究，看看能否對他們的刑獄系統有所瞭解。如果你找到更多的復仇軍監獄鑰匙的話，就用它們開啟此地正南方復仇軍前沿基地的監獄。將你發現的標識牌統統帶回來給我。','虛空風暴維序派哨站的指揮官阿米爾要你取回一塊復仇軍囚犯標識牌。','','去虛空風暴找維序派哨站的指揮官阿米爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10972 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10972,'zhTW','復仇軍囚犯的標識牌','我需要更多的身份標識牌，$N。我發現這些身份標識牌不僅用於標識囚犯身份，還記錄著囚犯被囚禁的地點！$B$B一旦破解了標識牌的密碼，我們就能找到所有被俘虜的夥伴，然後以最小的代價將他們解救出來。','','','去虛空風暴找維序派哨站的指揮官阿米爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10973 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10973,'zhTW','一千個世界','我已經破解了標識牌的密碼！標識牌上的編碼由固定的欄位組成。所有的標識牌正面都寫著“千百個世界……”，我不太理解這段文字的意思，不過聽上去就透露著邪氣。$B$B標識牌背面的資訊至關重要。編碼的前半部分表明關押地點，後半部分則是囚犯的種類。此外，似乎這些鑰匙能組合成進入另一類監獄的特殊鑰匙。現在，我需要更多的鑰匙來研究……','虛空風暴維序派哨站的指揮官阿米爾要你取回5把復仇軍監牢鑰匙。','','去虛空風暴找維序派哨站的指揮官阿米爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10974 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10974, 'zhTW', '貝許爾的靜止密室', '伊斯利恩在劍刃山脈最北邊人稱貝許爾平臺的沙洲上有一塊領地。根據鑰匙碎片上的記載，他們在貝許爾有更大規模的監獄。我應該跟你提一下，伊斯利恩稱呼那些監獄為靜止密室。$B$B這個鑰匙碎片可以讓你進入其中一個特殊的靜止秘室叫做靜止密室A。帶著這個鑰匙碎片前去調查吧。$B$B調查完成以後我的幻影將會在貝許爾平臺等你，跟我交談。', '使用伊斯利恩鑰匙片 - A打開在劍刃山脈貝許爾平臺的靜止密室A。$B$B將調查密室得到的證據交給貝許爾平臺的指揮官阿密爾的影像。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10975 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10975,'zhTW','巴什伊爾的房間','','','','去刀鋒山找巴什伊爾碼頭的指揮官阿米爾的影像。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10976 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10976, 'zhTW', '奈薩斯王印記', '我必須知道伊斯利恩在奧齊頓的法力墓地裡關著什麼樣的東西。$B$B在你與貝許爾的靜止密室野獸戰鬥的時候，你可能會看到一樣叫做奈薩斯王印記的東西。如果你找到這樣東西，馬上交給我!這是要製作通往法力墓地裡頭的靜止密室鑰匙所欠缺的最後一樣材料。', '劍刃山脈貝許爾平臺的指揮官阿密爾的影像要你交給他1個奈薩斯王印記。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10977 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10977,'zhTW','法力陵墓的靜止間','我利用你取回的這枚節點之王的印記鑄造了一把新鑰匙，可以用來開啟法力陵墓內的靜止間。$B$B從印記上雕刻的文字來看，法力陵墓設有兩處靜止間，一處在入口附近，另一處則在節點親王沙法爾旁邊。我給你的這把鑰匙能開啟入口附近的靜止間。$B$B我要你進入奧金頓的法力陵墓，開啟法力陵墓靜止間。','刀鋒山巴什伊爾碼頭的指揮官阿米爾的影像要你進入奧金頓的法力陵墓，對靜止間使用法力陵墓靜止間鑰匙。$B$B此任務必須在英雄難度的地下城中完成。','調查法力陵墓靜止間','去刀鋒山找巴什伊爾碼頭的指揮官阿米爾的影像。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10978 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10978,'zhTW','返回莫希斯·輕翼身邊','聖物已經取回，你必須立刻離開這裡，$N。克林塔爾置自己和夢境守衛者的安全於不顧，幫助你找回聖物；現在，他必須專心對抗那些滋擾翡翠夢境的入侵者了。$B$B將聖物交給莫希斯·輕翼，並將你看到的情形告訴他。或許他可以幫助我們判斷入侵翡翠夢境的人究竟是誰。','將艾維娜聖物交給贊加沼澤塞納里奧庇護所的莫希斯·輕翼。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10979 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10979,'zhTW','轉至常青林','你確定自己在獸穴中看到了一隻烏鴉？$B$B事情越來越令人困惑了。看來我們沒法直接幫助克林塔爾和夢境守護者，但是如果我們能查明究竟是什麼在滋擾翡翠夢境，或許就有辦法阻止這些神秘的入侵者。$B$B有報告稱刀鋒山上一支遠古的鴉人部族已經復甦，而他們所崇拜的神正是一隻烏鴉。去常青林找阿爾索恩·風歌，或許這支鴉人部族與翡翠夢境有著千絲萬縷的關係！','與刀鋒山常青林的阿爾索恩·風歌談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10980 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10980,'zhTW','烏鴉之書','莫希斯的猜測是對的，這支鴉人部族很可能跟翡翠夢境的躁動有關，但是在沒搞清楚情況之前，我們不能貿然行動。$B$B坦莫在研究中發現，鴉人部族很可能保有一本古老而神聖的“烏鴉之書”。$B$B鴉人的靈魂不會自己顯現在你的眼前，所以你需要帶著這塊石頭，到刀鋒山的西部高峰去，在烏鴉林的南邊弄到一顆以太鰩之眼。把它們組合起來，你就可以看到鴉人的靈魂了。你要尋找的目標，是一個名叫長者塞克卡爾的靈魂。','使用一顆以太鰩之眼和你的先知之石找到烏鴉教派的幽靈。在漩渦峰尋找長者塞克卡爾的靈魂，向他詢問有關烏鴉之書的問題，然後向常青林的阿爾索恩·風歌覆命。','','去刀鋒山找常青林的阿爾索恩·風歌。','瞭解有關烏鴉之書的知識','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10981 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10981,'zhTW','節點親王沙法爾的私人房間','','','','去刀鋒山找巴什伊爾碼頭的指揮官阿米爾的影像。','','','','',0);
