DELETE FROM `quest_template_locale` WHERE `ID` = 10983 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10983, 'zhTW', '乾癟的莫格多克', '莫格多克真聰明!他派葛羅克來城市，找幫助。血槌氏族需要幫助。莫格多克說找幾個強壯的小伙子來劍刃山脈找他。他站在血之環的塔頂。莫格多克真聰明!', '到劍刃山脈血之環外面的高塔頂端找乾癟的莫格多克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10984 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10984,'zhTW','援助食人魔','<弗埃盧那水晶般清澈的聲音在你腦海中迴盪。>$B$B貧民窟中有位食人魔，他不停地向路人乞求幫助。可惜很多人對他的哀求充耳不聞。$B$B你願意幫幫他嗎？$B$B他名叫葛羅克，就在東南邊商人聚集之地。$B$B謝謝你，$N。','與撒塔斯城貧民窟的食人魔葛羅克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10985 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10985,'zhTW','幫助阿卡瑪','<克希利身上發出陣陣淡泊的光芒，而他身邊的奧爾多和占星者軍隊也回應著他的命令。克希利的軍團已經完全準備好了，隨時可以將伊利丹的軍隊壓制住，並為阿卡瑪吸引敵人的注意力。現在，這位納魯正等待著你給出進攻開始的訊號。>','在克希利的軍隊發動佯攻之後，保護阿卡瑪和瑪維進入影月谷內的黑暗神殿。','幫助阿卡瑪和瑪維進入黑暗神殿。','去影月谷找巴爾裡廢墟的克希利。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10986 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10986,'zhTW','天空之眼','就算烏鴉之書的殘片都在，要找到它們也很困難。我們最好是利用比你的視線更為敏銳的眼睛。$B$B觀察者艾萊亞在納格蘭暮光嶺的東部邊緣研究當地的各種鳥類。去那兒找她吧，在她的幫助下，你或許可以藉助鳥類敏銳的視線找到烏鴉之書的殘片。','與納格蘭暮光嶺的觀察者艾萊亞談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10987 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10987,'zhTW','捕獲麻鷹','納格蘭的野生麻鷹是視覺最為敏銳的食肉鳥類。但是由於體型較小，因此受到風鵬的排擠，納格蘭大部分割槽域已經難尋它們的蹤跡。$B$B大多數的麻鷹棲息在暮光嶺。如果你能捕獲一隻麻鷹，我可以訓練它去尋找被掩埋的書典殘片。$B$B但是捕捉麻鷹並不是件容易的事，它們極易受到驚嚇，一旦有陌生人靠近就會立即飛走。我建議你悄悄接近這些敏感的生物，伺機投擲羅網。','用麻鷹網捕捉一隻野生麻鷹，把它交給暮光嶺的觀察者艾萊亞。','','去納格蘭找暮光嶺的觀察者艾萊亞。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10988 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10988,'zhTW','烏鴉石','經過訓練，這隻麻鷹已經能對鳥哨聲做出反應了。吹響鳥哨，它就會飛到你身邊，指引你尋找書典殘片。阿爾索恩捎話過來說，你要找的殘片應該都在斯克提斯及其周圍的峽谷中，去那裡找麻鷹吧。$B$B當你集齊殘片後，將鳥哨還給阿爾索恩，她會將這隻麻鷹放歸大自然的。$B$B代我向阿爾索恩問好。','在斯克提斯收集8塊烏鴉石，把它們交給刀鋒山常青林的阿爾索恩·風歌。','','去刀鋒山找常青林的阿爾索恩·風歌。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10989 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10989, 'zhTW', '乾癟的莫格多克', '乾癟的莫格多克在塔頂等你。他叫我找一個$r$c就像你這樣。你去找他說重要的事情。去吧，但是不要告訴別人。這是秘密!', '前往劍刃山脈的血之環找乾癟的莫格多克。他就站在劍刃山脈，血之環外的塔頂，丘特的旁邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10990 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10990,'zhTW','雄鷹精華','根據烏鴉之書的記載，在遠古時代，崇拜鴉神的鴉人捕捉三種與鴉神為敵的猛禽，將它們的精華封印在石頭神殿中。每座神殿都由專門的守護者看守，防止鴉神的敵人釋放這些被禁錮的精華。$B$B如果我們能拿到這些精華，就應該能引出鴉神並擊敗它。$B$B書中提到，第一座神殿中禁錮著雄鷹精華，這座神殿位於泰羅卡森林尤魯恩湖以南的山丘中。$B$B烏鴉之書中還說，雄鷹勇敢地戰鬥，但最終被潮水般湧來的敵人淹沒。你的熊形態所具備的堅韌與強壯應該可以在這場戰鬥中發揮巨大的作用。','擊敗雄鷹守護者，取得雄鷹精華。使用阿爾索恩的麻鷹哨以召喚麻鷹傳遞你獲勝的訊息。$B$B如果你弄丟了阿爾索恩的麻鷹哨，可以回到常青林找阿爾索恩·風歌再拿一個。','','去找阿爾索恩的麻鷹。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10991 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10991,'zhTW','獵鷹精華','<麻鷹口中傳出阿爾索恩的聲音。>$B$B崇拜烏鴉之神的鴉人們還封印了獵鷹精華。$B$B它被禁錮在斯克提斯附近的神殿中，昭示著烏鴉祭司那叱詫風雲的輝煌歲月。$B$B那座神殿就在斯克提斯西北方的艾雷諾湖岸邊。$B$B要戰勝獵鷹守護者，你必須藉助獵鷹的力量。在獵豹形態下，利用你的速度和敏捷，趁守護者恢復能力之前擊敗他！','擊敗獵鷹守護者，取得獵鷹精華。使用阿爾索恩的麻鷹哨以召喚麻鷹傳遞你獲勝的訊息。$B$B如果你弄丟了阿爾索恩的麻鷹哨，可以回到常青林找阿爾索恩·風歌再拿一個。','','去找阿爾索恩的麻鷹。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10992 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10992,'zhTW','山鷹精華','<麻鷹口中傳出阿爾索恩的聲音。>根據烏鴉之書記載，被封印的最後一塊也是最強大的一塊精華是山鷹精華。它被禁錮在遠離斯克提斯的神殿中，就在奧金頓東南方某座偏僻的小島上。$B$B從書中的描述來看，應該就是被稱為悲翼之地的島嶼。$B$B山鷹守護者幾乎對鳥類利爪的攻擊完全免疫。放棄物理攻擊吧，呼喚群星之怒擊敗他。不要重蹈山鷹的覆轍。','擊敗山鷹守護者，將山鷹精華交給常青林的阿爾索恩·風歌。','','去刀鋒山找常青林的阿爾索恩·風歌。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10993 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10993,'zhTW','返回塞納里奧庇護所','將這些精華交給莫希斯·輕翼，並告訴他我們收集到的關於鴉神的新情報。$B$B莫希斯懂得如何利用這些精華引出鴉神安蘇。快去找他吧，不知道克林塔爾和夢境守衛者還能在鴉神的攻擊下堅持多久！$B$B<在你準備轉身離開的時候，阿爾索恩抓住了你的手臂。>$B$B$N，拜託你告訴莫希斯，我幫你了多大的忙。我擔心他不知道我為此做出的貢獻！','將阿爾索恩的包裹交給塞納里奧庇護所的莫希斯·輕翼。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10994 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10994, 'zhTW', '[Chasing the Moonstone]', '[If the essences are combined within a rare gemstone such as a Southfury moonstone, you\'ll be able to release them when you\'re prepared to challenge Anzu.$B$BThe only problem is that Southfury moonstones are only found on the Azshara side of the river, on the cliffs near the river\'s source.$B$BTragedy befell the last night elf party that sought the stone. Their boat is still anchored in the river near where they sighted the moonstone. Keep your eyes open and approach the site by land from the Azshara side.]', '[Bring a Southfury Moonstone to Morthis Whisperwing at the Cenarion Refuge.]', '', '去找贊加沼澤的莫西斯·語翼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10995 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10995, 'zhTW', '葛魯洛克的兩個龍頭骨', '詛咒之谷位在東邊飛龍之末的邊界處。戈魯爾之子，葛魯洛克就在那邊策劃他的愚蠢計劃。$B$B我聽說他的一樣物品被人用巧妙的手法給偷走了。是你做的嗎?可惜他沒有在過程中喪失性命。$B$B如果我們想重獲自由，我要你搶走他最重要的資產，那就是他父親屠殺黑龍軍團的龍頭骨。你要取得龍頭骨的唯一方法就是殺死他。', '取得葛魯洛克的龍頭骨，帶到劍刃山脈的血之環外，交給塔頂乾癟的莫格多克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10996 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10996, 'zhTW', '瑪格歐克的寶箱', '瑪格歐克在剃刀山脊的山坡上以及東南邊巡邏。他的父親指派他為東邊山區的看守者，而他則享受著殘虐當地任何看不順眼的生物。$B$B為了我的部族生存權，身為戈魯爾之子的他必須被消滅。這就要靠你幫忙了。$B$B瑪格歐克總是隨身攜帶一個寶箱。將他的寶箱帶來給我，證明你已經殺死他。你可以拿走寶箱裡頭的任何東西。', '取得瑪格歐克的寶箱，帶到劍刃山脈的血之環，交給塔頂乾癟的莫格多克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10997 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10997, 'zhTW', '就連古羅也有軍旗', '你聽說過撒塔斯城嗎，$c?它的西北邊上方有個地方叫做阻礙之丘，一個你只能藉由飛行坐騎才能到達的地方。$B$B其中一位戈魯爾之子 - 史拉格，離鄉背井到那邊並且控制當地的戈杜尼巨魔。即使距離如此遙遠，我們也不能讓他坐大，免得當他的兄弟們都被殺死之後會回來復仇。$B$B$N，你必須到那邊並且取得他的軍旗，證明他已經被擊潰了。', '取得史拉格的軍旗，帶到劍刃山脈的血之環，交給塔頂乾癟的莫格多克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10998 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10998, 'zhTW', '搶奪魔典', '還有一個古羅要殺:史庫洛克·靈魂研磨者。他的藏身處非常隱密，但是有一個辦法可以引誘他現身。$B$B他曾經受過一個叫做邪惡的梵戈的巨魔術士訓練，你必須取得他的魔典!$B$B梵戈必須由你加上其他四名人員才能召喚，每個人站在一個火焰之環內。到東北邊的山區，靠近破碎荒野的附近尋找梵戈之環。$B$B還有一點，$N，假如你聽見梵戈說什麼變大之類的話，快回到你的火焰之環裡面!', '你必須取得梵戈的邪惡魔典。把它交給劍刃山脈血之環外塔頂的乾癟的莫格多克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10999 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10999, 'zhTW', '[One Shot, One Kill]', '[Bring me 8 trogg stone teeth.]', '[Bring me 8 trogg stone teeth.]', '', '去找喬‧蘭姆西。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11000 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11000, 'zhTW', '深入靈魂研磨者獸穴', '這本魔典是殺死史庫洛克的關鍵。$B$B在靈魂研磨者獸穴大聲的閱讀這本魔典以啟動儀式。接著一個叫做靈魂研磨者的東西會伴隨著許多史庫洛克的靈魂受害者出現，這些靈魂會試著破壞靈魂研磨者。你必須阻止這些靈魂這麼做，直到史庫洛克被迫在這個世界上現身為止。$B$B往北穿過匕爪峽谷，到達血之環的另一邊。$B$B獸穴的位置就在你到達戈魯爾之巢之前的右手邊。$B$B將史庫洛克的靈魂帶回來。', '取得史庫洛克的靈魂並且交給劍刃山脈血之環外塔頂的乾癟的莫格多克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11001 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11001, 'zhTW', '[Vanquish the Raven God]', '[We must waste no time in dealing with the raven god. You must take the essence-infused moonstone to a place of great power in order to lure the god from the relative safety of the Emerald Dream.$B$BDescend into the Sethekk Halls and set the moonstone in the clutches of the raven\'s claw. You\'ll find it in the chamber before the talon king\'s hall.$B$BAnzu must be made believe that his followers have gathered to welcome him back into the world. Once he has manifested, show him no mercy!]', '[Slay the Raven God and return to Morthis Whisperwing at Cenarion Refuge.$B$BThis quest must be completed in Heroic dungeon difficulty.]', '', '去找贊加沼澤的莫西斯·語翼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11002 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11002,'zhTW','瑪瑟裡頓之死','伊利丹·怒風的邪獸人軍隊之源已經被徹底剷除了。這座巨大的工廠已經停止了它那邪惡而骯髒的生產——至少現在如此。現在，這裡唯一剩下的就是這處斷壁殘垣與你手中所捧著的巨大徽記。事實上，這正是一個聯盟英雄的勝利象徵。$B$B將瑪瑟裡頓的徽記帶回榮耀堡，交給達納斯·托爾貝恩。','將瑪瑟裡頓的徽記交給榮耀堡的遠征軍指揮官達納斯·托爾貝恩。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11003 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11003,'zhTW','瑪瑟裡頓之死','伊利丹·怒風的邪獸人軍隊之源已經被徹底剷除了。這座巨大的工廠已經停止了它那邪惡而骯髒的生產——至少現在如此。現在，這裡唯一剩下的就是這處斷壁殘垣與你手中所捧著的巨大徽記。事實上，這正是一個部落英雄的勝利象徵。$B$B將瑪瑟裡頓的徽記帶回索爾瑪，交給納茲格雷爾。','將瑪瑟裡頓的徽記交給索爾瑪的納茲格雷爾。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11004 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11004, 'zhTW', '[World of Shadows]', '[Sky Commander Adaris was seriously injured during a Skettis incursion.  He\'s been in and out of consciousness since.$B$BI fear he has succumbed to a feverish delirium.  During brief lucid moments he demands that I prepare an elixir made from shadow dust carried by the arakkoa.  He seems to believe it will allow him to see into a "world of shadows" where the arakkoa\'s true leaders dwell.$B$BI do not believe this nonsense for a second, but I fear he won\'t rest until I obtain such an elixir.  Will you help?]', '[Severin wants you to venture into Skettis and retrieve 6 Shadow Dusts from the arakkoa that dwell there.]', '', '去找泰羅卡森林的瑟弗林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11005 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11005, 'zhTW', '魔爪祭司的秘密', '感謝你還聽我瘋狂的豪言壯語。一直以來我們都想要摧毀司凱提斯的指揮系統;我們已經探聽到他們有三個叫魔爪祭司的聖職人員，但是我們從未親眼見過。現在我們知道其中的原因。$B$B去跟瑟弗林交談以取得更多他發現的藥劑。使用藥劑找到並殺死那三個魔爪祭司:艾夏歐、史奇吉克以及札列克。據說他們住在迷霧亞拉芮克，靠近黑風湖的東邊海岸。', '從瑟弗林那裡取得暗影藥劑，用它找到並殺死司凱堤斯的魔爪祭司艾夏歐，魔爪祭司史奇吉克和魔爪祭司札列克。完成這個任務後回去找天空指揮官艾德瑞斯。', '', '去找泰羅卡森林的天空指揮官艾德瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11006 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11006, 'zhTW', '[More Shadow Dust]', '', '', '', '去找泰羅卡森林的瑟弗林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11007 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11007, 'zhTW', '[Kael\'thas and the Verdant Sphere]', '[The air around you hums - a gentle hum. The naaru are aware of your victory. Perhaps they are the reason you were compelled to pick up this sphere from the still-twitching remains of Kael\'thas Sunstrider. What secrets could it hold?$B$BPerhaps A\'dal in Shattrath City could make sense of the item.]', '[Take the Verdant Sphere to A\'dal in Shattrath City.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11008 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11008, 'zhTW', '向司凱堤斯開火', '你認為你夠資格成為禦天者的一員嗎?讓我們看看你在空中的能耐吧。阿拉卡正在培植一批數量龐大的變種攻擊寵物，用來攻擊我們的斥候。我要你拿著這些爆破彈炸毀阿拉卡住所屋頂的孵卵所。盡量避開守衛那些卵的巨大的卡里瑞，要不然在你還沒發現是什麼東西攻擊你之前，你已經從坐騎上被擊落了。', '在司凱堤斯住所的屋頂尋找巨大的卡里瑞蛋，並且對其使用禦天者爆破彈藥。完成之後回報天空士官多林。', '', '去找泰羅卡森林的天空士官多林。', '已摧毀巨大的卡里瑞蛋', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11009 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11009, 'zhTW', '巨魔的天堂', '既然你已經解放了我們的奴役生涯，我們可以開始重新統合整個部族。這可能要花點時間;部族之間的舊仇很難化解。但是現在有一件更迫切的事情，你必須前往位於西方上空的歐格利拉。你必須保護歐格利拉還有我們不受上方的軍隊威脅，就像之前古羅為了保護我們而對抗伊斯利、惡魔還有最可怕的黑龍軍團一樣。當你到達巨魔的天堂時，請教裘阿洛該如何做最好。', '乾癟的莫格多克要你去劍刃山脈的歐格利拉與裘阿洛交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11010 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11010, 'zhTW', '[Bombing Run]', '[You have a flying mount... so what!  You think you have what it takes to use it properly?$B$BForge Camp: Wrath and Forge Camp: Terror, to the north and south, are a major pain in my backside, as well as being a threat to peaceful Ogri\'la.  With all of those fel cannons shooting down the Skyguard left and right, we can\'t get through there to take care of business.$B$BYou want to prove yourself?  Take these bombs and knock out their ammo stacks.  Just don\'t let them shoot you down, too!]', '[Use the Skyguard Bombs to destroy 15 Fel Cannonball Stacks.]', '', '', '邪能砲彈堆已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11011 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11011,'zhTW','永恆的警惕','你擊敗了鴉神安蘇，這真是了不起的成就。不過，我認為他肯定不肯善罷甘休，並且會再找機會返回外域。$B$B只要鴉神的追隨者還在，他就可能死灰復燃。收下這顆灌注精華的月亮石以防萬一吧。','與莫希斯·輕翼談談，獲得一顆灌注精華的月亮石。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11012 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11012,'zhTW','靈翼血誓','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11013 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11013,'zhTW','為伊利達雷效力','靈翼浮島……那本是靈翼龍族的避難所，如今卻淪為龍喉氏族橫行之地。雖然獸人們侵佔了我們的領地，可是他們無法削弱龍族強大的魔法力量。憑藉這種力量，我們可以掩蓋你的真實身份，幫助你安全混入龍喉氏族。$B$B我已經備好一封書信，我要你飛往龍喉營地，將它交給莫格霍爾大王。屆時，你將以伊利丹·怒風麾下一名邪獸人的身份開始新的生活。','轉至靈翼浮島，將伊利達雷服役文書交給龍喉營地的莫格霍爾大王。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11014 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11014,'zhTW','會見工頭','<莫格霍爾將服役文書揉成一團，隨手扔到一旁。>$B$B好吧，重要的事先說。想加入我統率的龍喉軍團，你就得幹活——誰也不能例外。去找點事做吧，別搞砸了。我會根據你的表現決定要不要再派你做些別的事。$B$B與龍喉營地中心的工頭瓦爾庫勒·龍息談一談。他會根據你的技能，為你安排適當的差事。$B$B好了，滾吧！','與龍喉營地的工頭瓦爾庫勒·龍息談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11015 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11015,'zhTW','靈翼水晶','你什麼都不擅長嗎？好吧。你雖說有些愚鈍，不過還是可以替我們做些事的。獵殺靈翼浮島上的生物，你或許可以從它們身上找到靈翼水晶。替我收集一些靈翼水晶，今天的任務就算完成了。','將30塊靈翼水晶交給影月谷龍喉營地的工頭瓦爾庫勒·龍息。','','去影月谷找靈翼浮島的工頭瓦爾庫勒·龍息。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11016 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11016,'zhTW','虛空礦洞剝石者的外皮','嗯，剝皮師？這兒可是剝皮師的天堂啊！獵殺水晶蔟附近的剝石者，替我收集一些虛空礦洞剝石者的外皮。','將35張虛空礦洞剝石者的外皮交給影月谷龍喉營地的工頭瓦爾庫勒·龍息。','','去影月谷找靈翼浮島的工頭瓦爾庫勒·龍息。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11017 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11017,'zhTW','靈塵花粉','採藥者？！很有趣的營生啊……我們的法師和薩滿祭司正好需要你的幫助。靈翼浮島上的靈塵灌木擁有奇異的花粉，對他們研究魔法很有幫助。替我收集一些靈塵花粉，今天的任務就算完成了。','將40份靈塵花粉交給影月谷龍喉營地的工頭瓦爾庫勒·龍息。','','去影月谷找靈翼浮島的工頭瓦爾庫勒·龍息。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11018 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11018,'zhTW','虛空礦石','礦工！$B$B<瓦爾庫勒向你敬禮。>$B$B咱們真是志趣相投！瓦爾庫勒也是一名礦工！沒有什麼比蓬頭垢面地挖掘礦脈更有趣的事了，對吧？$B$B尋找虛空礦脈，替我收集一些虛空礦石。','將40塊虛空礦石交給影月谷龍喉營地的工頭瓦爾庫勒·龍息。','','去影月谷找靈翼浮島的工頭瓦爾庫勒·龍息。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11019 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11019,'zhTW','你的夥伴','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11020 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11020,'zhTW','緩慢的死亡','龍喉獸人幾乎在每叢水晶簇都設立了苦工營地。直接殺掉獸人必定會惹來不必要的麻煩，但是我們可以略施妙計，既能削減他們的數量，又不會引起莫格霍爾的懷疑。$B$B在影月谷中獵殺那些被感染的野生動物，取出它們的邪能腺體。將邪能腺體和這團羊肉混合起來，放在苦工營地附近。他們只要吃上一口就會倒地身亡！','影月谷龍喉營地的僱傭兵亞茲爾要你將邪能腺體和亞茲爾的羊肉的混合物投放在12座龍喉苦工營地附近，毒殺龍喉苦工。','','去影月谷找靈翼浮島的僱傭兵亞茲爾。','在龍喉苦工營地投毒','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11021 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11021, 'zhTW', '[Ishaal\'s Almanac]', '[This mysterious tome was on Talonpriest Ishaal\'s body.  It contains arcane symbols and charts of celestial bodies beyond your comprehension.$B$BAll writing is in a language you don\'t understand; likely an ancient version of the arakkoa written tongue.  Perhaps you should bring this to Sky Commander Adaris.]', '[Bring Ishaal\'s Almanac to Sky Commander Adaris north of Skettis.]', '', '去找泰羅卡森林的天空指揮官艾德瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11022 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11022,'zhTW','與莫戈多格會面','$N$G國王:女王陛下，請等等！在你轉至奧格瑞拉之前，不如跟枯瘦的莫戈多格談談！','與枯瘦的莫戈多格談一談，他就在刀鋒山鮮血之環東側的塔樓頂部。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11023 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11023, 'zhTW', '再度轟炸!', '那些高射火砲仍然對我們造成威脅，$N。$B$B你可別誤會我的意思，我認為你上次執行任務的表現非常出色。但事實上，那些該死的惡魔們補充砲彈的速度似乎比我們摧毀他們砲彈的速度還快。這同時表示我們的士兵很難通過該區域，更別提那些惡魔們對歐格利拉所造成的風險。$B$B你意下如何?想再次轟炸他們嗎?', '天空士官樊德麗要你炸毀15個惡魔砲彈堆。任務完成後回到劍刃山脈的禦天者崗哨向她回報。', '', '', '已摧毀惡魔砲彈堆', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11024 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11024, 'zhTW', '[An Ally in Lower City]', '[There is an arakkoa in Lower City by the name of Rilak...  He can be trusted.  Take the book... to him.$B$B<Adaris drifts into unconsciousness as he returns the book to you.>]', '[Bring Ishaal\'s Almanac to Rilak the Redeemed in the Lower City section of Shattrath City.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11025 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11025,'zhTW','頂尖水晶','經過適當的事前準備，那些山區中的水晶就能展現出它的奇異能量，就好像我們在歐格利拉發現它有使人思緒清晰的能力。$B$B山上的生物都垂涎著那些水晶裂片，並且將其裂片使用於他們私人的用途之上。那些水晶的價值甚至還引起了一些商機。$B$B想協助我們的話，你必須先學習了解頂尖裂片。幫我找一些裂片回來。除了這裡的生物會攜帶頂尖裂片之外，有時候你也可以在鐮奪怪挖掘水晶的地方發現裂片。','裘阿洛要你收集5塊頂尖裂片，然後回到劍刃山脈上方的歐格利拉交給他。','','去劍刃山脈找奧格瑞拉的庫洛爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11026 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11026, 'zhTW', '驅逐惡魔', '朋友，你到達的時間真是太完美了!我們真的需要幫助。你會得到一個非常稀有的物品作為回報，這樣你我兩方都能得到好處。$B$B我們已經不再是兇暴的巨魔了，不過附近的惡魔們威脅要侵擾我們和禦天者。對抗惡魔的問題是，他們一旦被殺死，就會以一個新的軀體重新回來! $B$B不過，如果你使用這個水晶來召喚一個驅逐傳送門，當他們在傳送門附近死亡時，他們的精華就會被抽走，並且放逐回他們的老家!', '克朗克要求你使用驅逐水晶來放逐劍刃山脈上煉冶場:憤怒與煉冶場:驚駭中的惡魔。當你完成任務後回去找他。', '', '', '已驅逐惡魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11027 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11027,'zhTW','你有黑暗符印嗎？','那個營地的惡魔時常修理他們的傳送門。賈克說$N這一次給那些惡魔好看！$B$B但是，賈克要另一個暗色符文來製作晶鑄暗色符文給你。','假如小$r沒有暗色符文，你就去跟克朗克說話。他試著每天做一個暗色符文！也許你可以去他的袋子裡拿一個？！','','去找刀鋒山的甘克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11028 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11028, 'zhTW', '', '', '[Return to Sky Commander Adaris at Blackwind Landing in Terokkar Forest with the news about Terokk\'s return.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11029 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11029, 'zhTW', '殘破的偽裝', '打開包裹，$N。這是一個偽裝。看起來沒什麼說服力對吧?$B$B我為伊斯利走私者製作它們以搜尋稀有的書本。有一個阿拉卡作家住在司凱堤斯的中心島嶼，泰洛克之墓;他的名字叫撒哈克。他既老又幾近全盲。$B$B利用這個偽裝來和他交談並取得那本叫敵人之血的書。小心點，$N。這個偽裝騙不了其他的阿拉卡。', '使用殘破的阿拉卡偽裝從撒哈克那裡取得敵人之血再回到海茲克那裡。', '', '去找泰羅卡森林的海茲克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11030 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11030, 'zhTW', '[Our Boy Wants To Be A Skyguard Ranger]', '[$C, we\'ve got a problem -- we have lots of sons.  And ever since the Skyguard moved in nearby, all our sons ever talk about is joining their ranks.$B$BAs a proud father, we want them to have every advantage for when they apply.  So, would you go to the fel crystalforge at either forge camp to the north or south, and procure a magic flask for our sons?  You can\'t miss their green smoke.$B$BWe think that they take ten apexis shards to make.  We\'d give you the shards, but we don\'t have any at the moment.]', '[Collect an Unstable Flask of the Beast.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11031 AND `locale` = 'zhTW';
