INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11035,'zhTW','危險的天空','龍喉獸人在靈翼浮島的東北邊緣設立了港口，用於運送靈翼水晶和靈翼聖物。龍喉碎天者負責將貨物從港口運往龍喉要塞，龍喉晉升者則擔當起地面的守衛工作，防止入侵者滋擾生事。$B$B我們可以利用龍喉空港這個防禦缺口，狠狠地打擊龍喉獸人的囂張氣焰。$B$B飛往龍喉空港，襲擊運送貨物的龍喉碎天者，奪回被偷走的靈翼聖物！','將10件靈翼聖物交給影月谷龍喉營地的僱傭兵亞茲爾。','','去影月谷找靈翼浮島的僱傭兵亞茲爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11036 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11036, 'zhTW', '絕無僅有的產品!', '我先承認我不太清楚這個訂單是要用來幹嘛的，但火箭主管夫斯拉吉的指示非常明確 - 只要品質最好的水果，製成足夠長期航行的罐頭食品並密封它們不受自然腐壞的影響。$B$B還有其他的說明，這個要無重力那個要低壓力。我不會假裝我了解，但價錢不錯，所以他會得到他要的超級食品。把這個木箱帶到52區給他。越過了虛空風暴後，順著路走直到你看見城鎮。', '將罐頭水果交給52區的火箭主管夫斯拉吉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11037 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11037,'zhTW','奇怪的幻象','$N，我曾看見巨大的箭形物體迅速躥至高空，後面還拖著長長的火焰尾巴。這種與眾不同的景象令我百思不得其解。雖然對法師而言，這樣的把戲簡直是小菜一碟，但是我很清楚，那絕對不是什麼魔法效果。$B$B艾澤拉斯世界的居民從來沒有取得過這樣的成就。$N，你必須找出那東西的製造者，並慷慨地伸出援手。若是沒有你的幫助，他們的創造物或許會失敗。','與52區的火箭主管弗斯拉格談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11038 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11038,'zhTW','協助大主教歐雷里斯','不久前，高階祭司伊沙娜派遣大主教歐雷里斯率領一隊學者轉至虛空風暴。此行的目的是調查凱爾薩斯的動向，不過到當前為止，我們還沒有收到任何反饋報告。$B$B我擔心他們勢單力薄，恐怕難以完成使命。你的知識和經驗必定對大主教歐雷里斯有所幫助。你願意轉至52區幫幫他嗎？','與52區的大主教歐雷里斯談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11039 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11039,'zhTW','向間諜大師薩羅迪恩報到','不久前，沃雷塔爾派了一隊密探轉至虛空風暴，想要調查凱爾薩斯的動向。我們的首領非常信任間諜大師薩羅迪恩和他手下的密探，便接受了他要求增援的請求。$B$B薩羅迪恩發回的報告非常簡短地說他遇到了一些麻煩事。$N，轉至52區向他報到，盡你所能地幫助他吧。','向52區的間諜大師薩羅迪恩報到。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11040 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11040, 'zhTW', '火箭主管的零件', '我和哥布林合作的次數用一隻手就數的出來。我們和他們比較像在競爭，但當我接到火箭主管夫斯拉吉的請求，我實在沒辦法拒絕他。$B$B這個木箱裝滿了我在這裡用不到的零件，但那個火箭主管或許可以用在他的工程上。如果你正要去52區的話可以幫忙運送它們嗎?$B$B誰知道，或許一些精細的地精零件可以讓他的創作免於爆炸!', '把波西的備用零件送給52區的火箭主管夫斯拉吉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11041 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11041,'zhTW','未完的工作……','以聖主之名……為伊利丹的榮耀而戰！$B$B莫格霍爾大王下令，不惜一切代價確保靈翼浮島的安全。島上的虛空幼龍要麼被我們俘虜，要麼已經逃之夭夭；剝石者趁勢猖獗起來，嚴重影響了水晶的開採工事。$B$B殺光它們，還有母獸巴萊什以及她的配偶阿爾沃安。$B$B這是莫格霍爾大王的命令！$B$B<看來這個獸人正被此事煩得焦頭爛額，不妨趁此機會證明你對莫格霍爾的忠誠！>','殺死10只靈翼礦洞剝石者和母獸巴萊什。完成任務後向龍喉營地的莫格霍爾大王覆命。','','去影月谷找靈翼浮島的莫格霍爾大王。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11042 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11042,'zhTW','神秘的幻象','我最近被一個奇怪的夢境幻象所困擾，$N。我看見一團巨大的煙霧迅速躥至高空，後面還拖著長長的火焰尾巴，速度越來越快。這種與眾不同的景象令我百思不得其解。我只知道這絕非自然現象，也不是惡魔的創造物。$B$B我沒看清它的模樣，不過它應該是許多人的心血之作。看來這些創造者需要幫助。$B$B$c，轉至虛空風暴尋找它的創造者，並慷慨地伸出援手吧。','與52區的火箭主管弗斯拉格談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11043 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11043, 'zhTW', '更好的獅鷲獸', '我聽說那些蠻錘矮人在影月谷的南邊要塞有一座獅鷲獸棲息處。假如你順路到那邊的話，可以幫我傳話給他們嗎?我有一些想法可以改良他們的獅鷲獸!明明可以在獅鷲獸身上裝飛行儀表板、照後鏡還有火箭，為什麼他們不武裝獅鷲獸呢?想想看裝了之後獅鷲獸可以飛的多快!我稱它為渦輪獅鷲獸8000型!', '跟蠻錘要塞的布朗恩·焰鬚談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11044 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11044,'zhTW','災難的幻象','我常常在睡夢中被災難的幻象驚醒——綠色的火焰雨不斷地砸向要塞和工事。這種幻象已經摺磨我好幾周的時間了，直到最近我才瞭解到其中的寓意。$B$B在遙遠的東方，影月谷的蠻錘矮人們正在遭受燃燒軍團和其它敵人的襲擊。他們勇敢地抵抗著敵人的進攻，但是孤軍作戰勢必會落敗。$N，轉至蠻錘要塞，幫助矮人們戰鬥吧。','與蠻錘要塞的空軍指揮官努埃恩談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11045 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11045,'zhTW','仲裁者索魯斯','影月谷歷經滄桑，在漫長的歲月中演變成如今的模樣。鮮有人願意觸碰這段歷史，惟恐為這片死氣沉沉的大地帶來新的生機。$B$B當然，並非所有人都這麼膽小。仲裁者索魯斯一直在探索那些徘徊在影月谷中的幽靈的秘密。不過，他的研究工作舉步維艱，我想他一定需要幫助。$B$B如果你有機會轉至蠻錘要塞，就去找他談談吧。','與蠻錘要塞的仲裁者索魯斯談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11046 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11046,'zhTW','主藥劑師希爾達迦','影月谷歷經滄桑，在漫長的歲月中演變成如今的模樣。鮮有人願意觸碰這段歷史，惟恐為這片死氣沉沉的大地帶來新的生機。$B$B當然，並非所有人都這麼膽小。主藥劑師希爾達迦一直在探索徘徊在影月谷中的幽靈的秘密。她的研究工作舉步維艱，我想她一定需要幫助。$B$B如果你有機會轉至影月村，就去找她談談吧。','與影月村的主藥劑師希爾達迦談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11047 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11047, 'zhTW', '學徒的請求', '身為雙足飛龍管理員的學徒，我的其中一項工作就是當牠們沒有執行飛行任務時要照顧牠們。問題是我們這邊的雙足飛龍數量太少了，牠們根本沒有休息的時間。假如我們不能補充雙足飛龍的數量的話，我怕牠們會操勞致死。影月谷西邊的影月村有一個大型的雙足飛龍廄。達瑪·野鬃負責照顧和訓練那裡的雙足飛龍。你可以幫我們去跟她講幾句好話，同時讓她了解我們的情況嗎?', '跟影月村的達瑪·野鬃談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11048 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11048,'zhTW','克洛坎的報告','我原本奉命暫時留守加拉達爾一段時間，然後再向影月村的血衛士古爾穆克報到。在駐留期間，我發現加拉達爾需要一位常駐聯絡員，以便隨時與部落保持聯絡。$B$B我也明白血衛士古爾穆克需要人手支援，但是我想他應該能理解明白這裡的任務也十分需要我來完成。轉至影月谷西北方的影月村，轉告血衛士古爾穆克，我要晚些時日才能向他報到。','與影月村的血衛士古爾穆克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11049 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11049,'zhTW','尋找靈翼龍卵','如果你在靈翼浮島上發現靈翼龍卵，就把它們統統帶回來給我。$B$B不過，靈翼龍卵極其罕見。找不到的話，也不必產生挫敗感。大多數靈翼龍卵都被龍喉獸人運往了未知的地方。$B$B你能在島上的各種生物身上找到靈翼龍卵，它們零星地分佈在水晶簇、礦洞、虛空礦脈或是靈塵灌木附近。$B$B保持低調，別引起莫格霍爾的注意。','將一枚靈翼龍卵交給影月谷龍喉營地的僱傭兵亞茲爾。','','去影月谷找靈翼浮島的僱傭兵亞茲爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11050 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11050,'zhTW','所有的龍卵','','','','去找影月谷的僱傭兵亞茲爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11051 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11051, 'zhTW', '放逐更多惡魔', '如果我們了解惡魔，其實基於我們深入地研究，我們是了解他們的，他們能快速修補珍貴的轉換門上所受到的任何傷害。$B$B所以，如果你想要取得另一個暗色符文的機會，帶著我們的驅逐水晶回到那裡並消滅更多惡魔。此外，你想幫我們減輕惡魔造成的威脅，對吧?$B$B我之所以會說「機會」是因為我們使用的程序會產生不同的結果。你可能會得到一個暗色符文，或是可能得到一個完全不同的東西。', '克朗克要求你使用驅逐水晶來放逐劍刃山脈上煉冶場:憤怒或煉冶場:驚駭中15個惡魔。當你完成任務後回去找他。', '', '', '已驅逐惡魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11052 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11052,'zhTW','阿卡瑪的保證','<阿卡瑪將水晶插入他手中的卡拉波護符裡。>$B$B$N，我已經已不再像從前一樣強大和自信了，$N。而且這些年來，我一直與真正的邪惡離得那麼近，攜帶這件如此強大的神器的同時，我真不知道自己到時候還能不能再相信自己。$B$B拿去吧，把這個作為我發誓要與你共同對抗伊利丹的信物，拿去吧。你可以把這個卡拉波護符交給撒塔斯城的阿達爾代為保管。','將卡拉波護符交給撒塔斯城的阿達爾。','','去泰羅卡森林找撒塔斯城的阿達爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11053 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11053,'zhTW','起立，督工！','很少有苦工能像你這樣活了這麼久還沒死的。而有幸得到晉升，徹底擺脫賤民生活的苦工就更罕見了。$B$B<瓦爾庫勒拍了拍手掌。>$B$B喏，大王要見你。毫無疑問，你得到晉升了。','與影月谷龍喉營地的莫格霍爾大王談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11054 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11054,'zhTW','新的監工：正確的選擇','你就是新來的監工吧？所有的監工都得配備一件合適的訓誡刑具。在你跑出去教訓那些懶惰的苦工之前，你最好給自己搞一雙這樣的訓誡靴。按照傳統，監工必須自己收集製造訓誡靴所需的材料，你也不例外。$B$B我需要一些結締皮和泰拉圖斯的硬皮。泰拉圖斯就在虛空風暴北部邊境處的邊緣生態圓頂中。','影月谷龍喉營地的高階監工瑪德拉普要你給他帶回10張結締皮和1張泰拉圖斯的硬皮。','','去影月谷找靈翼浮島的高階監工瑪德拉普。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11055 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11055,'zhTW','訓誡靴：懶惰苦工的懲戒','這是你的訓誡靴。世界上有許多訓誡靴，但這一雙是你的。$B$B做為一名監工，你必須利用訓誡靴好好教訓那些不服從命令的苦工。只要使用得當，苦工們自然會聽命於你，乖乖地替我們做事。$B$B去前面的水晶田監督苦工吧，懲罰那些懶散的傢伙，讓他們嚐嚐訓誡靴的厲害！','影月谷龍喉營地的高階監工瑪德拉普要你懲罰20名懶惰的龍喉苦工，然後將訓誡靴還給他。','','去影月谷找靈翼浮島的高階監工瑪德拉普。','教訓龍喉苦工','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11056 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11056, 'zhTW', '海茲克的交易', '不要讓我們的對話引來注意。艾德瑞斯不會贊同的。$B$B我是阿拉卡社會最低等級的人，$N。在泰洛克的規則裡，我早已被他的魔爪祭司崇拜的黑暗力量犧牲了。如果你說的是真的，魔爪祭司在尋求泰洛克的歸來，那麼你一定要阻止他們成功 - 不管你的領導者怎麼說!$B$B我有個對你有用的東西要給你。我在迷霧希拉克上層的舊居所有一個包裹。把它拿來給我!', '到東司凱堤斯，海茲克的住所取得海茲克的包裹再拿回去給他。', '', '去找泰羅卡森林的海茲克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11057 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11057, 'zhTW', '', '', '[Speak with Mog\'dorg the Wizened atop one of the towers just outside the Circle of Blood in the Blade\'s Edge Mountains. ]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11058 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11058, 'zhTW', '頂尖聖物', '很久以前有個已絕種的部族曾經住在這裡，一支叫頂尖的阿拉卡部族。他們文明遺物仍然存在。我們稱它們為頂尖聖物。$B$B我們只知道，適當地使用它們會帶來很多好處。每個聖物會呈現不一樣的顏色，以正確的順序去點按水晶，就會進入下一個等級，一次會比一次還要困難。$B$B要啟動聖物就需要一個頂尖裂片。等你洞悉了頂尖顫動後再來找我們。', '裘阿洛要你從一個頂尖聖物獲得頂尖顫動效果後回到劍刃山脈頂端的歐格利拉找他。', '已取得頂點震波', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11059 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11059, 'zhTW', '紀念碑護衛', '你已經知道怎麼使用這些單人型聖物，但如你所見，還有更大型的聖物，被單人型聖物環繞著。$B$B這些更大型的頂尖紀念碑功能差不多，但它們需要更多的頂尖裂片來啟動，並且需要四個人來操作。$B$B我們最擔心的就是使用它們時召喚出的護衛。這些水晶結構喚醒了它們很久以前的阿拉卡主人，現在危害著歐格利拉。$B$B我們要你摧毀一個並帶來給我們做為證據。', '裘阿洛要你取得頂尖守護者頭顱給他做為證據。完成後帶著它回到劍刃山脈頂端的歐格利拉找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11060 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11060,'zhTW','晶鑄黑暗符印','','','','去找刀鋒山的甘克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11061 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11061, 'zhTW', '[A Father\'s Duty]', '[As to that other magical flask, it can only be obtained from one spot: Bash\'ir Landing.  It\'s an ethereal base, and they aren\'t too friendly with outsiders, so it might be a little dangerous to obtain.$B$BWhere\'s Bash\'ir Landing, you ask?  Well, if you get on your flying steed and head north by northeast, well past Forge Camp: Wrath, you\'ll eventually spot it.  The Bash\'ir crystalforge itself is at the northeast corner of the landing.$B$BThank you for doing this, $N.  It\'ll mean the world to our sons!]', '[Collect an Unstable Flask of the Sorcerer for him.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11062 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11062, 'zhTW', '', '', '[Speak with Sky Commander Keller at the Skyguard Outpost in the Blade\'s Edge Mountains.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11063 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11063,'zhTW','你的雙翼','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11064 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11064, 'zhTW', '[Dragonmaw Race: The Ballad of Oldie McOld]', '[Don\'t let the gray hair fool you, grunt. I\'m still ten times the rider that you are! And don\'t go thinking that this old dog doesn\'t have any tricks up his sleeve.$B$BNow all you gotta do is follow me and try not to get knocked down off your mount. If you can do that, Oldie will admit defeat.$B$BWe\'ll lift off as soon as you\'re ready.$B$B]', '[Follow Murg "Oldie" Muckjaw while attempting to stay on your flying mount. Should you defeat Murg "Oldie" Muckjaw, report your victory to Ja\'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.]', '已擊敗「老骨頭」馬格·爛顎', '去找影月谷的傑‧諾斯利。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11065 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11065, 'zhTW', '[Wrangle Some Aether Rays!]', '[Wanna help the Skyguard and Ogri\'la?$B$BJust hear me out before you walk away, <hot stuff/girly>.  We\'re in need of remounts!  The bombing runs and missions to Bash\'ir Landing have taken a toll on our mounts.$B$BThe aether rays that fly around Vortex Pinnacle, and the Crystal Spine to the northeast, look like they\'d do just fine.  You don\'t even have to bring them back here, though that would be nice.  Just break and rope them, and we\'ll track them down later.$B$BThink you can wrangle me up some?]', '[Use the Wrangling Rope to capture 5 Aether Rays.]', '', '', '以太魟已被馴服', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11066 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11066, 'zhTW', '[Wrangle More Aether Rays!]', '[So, I hope that you\'re up to helping us wrangle up even more aether rays!  From what I can see, you\'re a natural with the rope!  And it\'s for a good cause, because not only do we get fresh mounts, but it helps us to protect Ogri\'la, which the ogres appreciate.$B$BRemember, the aether rays fly around Vortex Pinnacle, and the Crystal Spine to the northeast.$B$BThink you can wrangle me up some more?]', '[Use the Wrangling Rope to capture 5 Aether Rays.]', '', '', '以太魟已被馴服', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11067 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11067,'zhTW','壯志凌雲：粗野的特羅普','龍喉氏族看來待你不薄啊，$N。就連我這麼卑微下等的傢伙也有機會跟你玩玩了。現在，要想證明你對他們的價值，就必須先打敗我。$B$B看我的厲害吧，看我一口氣用龍尾巴把你像撣跳蚤一樣打飛出去……$B$B你準備好以後我們就可以開始了。','駕駛飛行坐騎緊緊跟隨粗野的特羅普。擊敗粗野的特羅普之後，將你的勝利訊息報告給向影月谷龍喉營地的亞恩·諾斯利。','擊敗粗野的特羅普','去影月谷找靈翼浮島的亞恩·諾斯利。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11068 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11068,'zhTW','壯志凌雲：獸醫考洛克','你想挑戰本大爺嗎？別開玩笑了！$B$B你不會是認真的吧？那好啊！你只要好好保住自己的小命就可以了。你不會死吧？？就算我拿些骷髏頭扔你，在你邊上轉圈你也不會死吧？$B$B準備好了就跟我說一聲，我們隨時可以開始。','駕駛飛行坐騎緊緊跟隨獸醫考洛克。擊敗獸醫考洛克之後，將你的勝利訊息報告給向影月谷龍喉營地的亞恩·諾斯利。','擊敗獸醫考洛克','去影月谷找靈翼浮島的亞恩·諾斯利。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11069 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11069,'zhTW','壯志凌雲：空軍指揮官艾克曼','三年多，我一直被囚禁在那該死的地方，霜狼氏族曾給過我三年多的俘虜生涯。那三年裡，我一直在那該死的哨塔裡聽他們抱怨丹巴達爾的狗屁大橋，以及什麼不平衡，不平衡，不平衡，不平衡……戰爭本來就什麼平衡不平衡的！都去見鬼吧，煩死了！分明是他們先仗著腳快佔了落雪墓地才導致沒進展的！$B$B後來，我好不容易逃出了那裡，到這裡來過點新生活。現在小穆穆和我正在競爭頂級騎手的位置。要是你也這麼想，就得先跟我比一場，呆瓜。$B$B準備好就開始吧！','駕駛飛行坐騎緊緊跟隨空軍指揮官艾克曼。擊敗空軍指揮官艾克曼之後，將你的勝利訊息報告給向影月谷龍喉營地的亞恩·諾斯利。','擊敗空軍指揮官艾克曼','去影月谷找靈翼浮島的亞恩·諾斯利。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11070 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11070,'zhTW','壯志凌雲：空軍指揮官穆維裡克','三年多的血淚生涯啊……有甜蜜也有悲傷，不過大多數時候是悲傷……你不會知道那些真正戰場的士兵，我當初的那些戰友真哭起來喊起來是什麼樣子的。$B$B“他們騎著馬就進塔了！”“聯盟基地怎麼那麼難打！”“急救站丟了，速度輸！”“別拿落雪，聽指揮啊！”$B$B這群白痴……$B$B反正後來，黑暗之門一開，我就馬上離開了那個村子，來到了這裡。老子現在壯志凌雲，要當龍喉氏族的第一騎手！你要是也這麼想，就得先打敗我。$B$B準備好以後就開始吧。','駕駛飛行坐騎緊緊跟隨空軍指揮官穆維裡克。擊敗空軍指揮官穆維裡克之後，將你的勝利訊息報告給向影月谷龍喉營地的亞恩·諾斯利。','擊敗空軍指揮官穆維裡克','去影月谷找靈翼浮島的亞恩·諾斯利。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11071 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11071,'zhTW','壯志凌雲：湯告魯士·碎空','你竟然有膽挑戰我湯告魯士？你周圍的世界會徹底墮入黑暗，而天堂也會被我的流星擊為碎片。$B$B你不會有任何機會的，士兵。不過，你既然這麼渴望一死……$B$B若只是為了向那些做著同樣愚蠢的夢，犯著同樣愚蠢的錯誤人們展示我的力量，那麼我就來好好享受你的惶恐與不安吧。$B$B你準備好了我們就開始！','駕駛飛行坐騎緊緊跟隨湯告魯士·碎空。擊敗湯告魯士·碎空之後，將你的勝利訊息報告給向影月谷龍喉營地的亞恩·諾斯利。','擊敗湯告魯士·碎空','去影月谷找靈翼浮島的亞恩·諾斯利。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11072 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11072, 'zhTW', '敵人之血', '被司凱堤斯魔爪祭司扣留為囚犯的子嗣都列在這本書裡:女獵人吉札拉，水晶巨人葛洛克，異教徒黑暗尖叫者阿卡萊和『風怒者』瓦奇茲。殺了他們才能讓泰洛卡回到這個世界。$B$B你需要時光流逝阿拉卡身上帶的卷軸，才能在司凱堤斯的召喚法陣召喚他們。幫我從他們身上各帶一個象徵物回來。你挑戰的是強大的生物;帶朋友一起去會比較好。', '在司凱堤斯的召喚法陣中央找到顱骨堆。在顱骨堆用10個時光流逝卷軸召喚並擊敗每個子嗣。帶著各個象徵物回到黑風平臺找海茲克。', '', '去找泰羅卡森林的海茲克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11073 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11073, 'zhTW', '[Terokk\'s Downfall]', '[I... I\'ve turned a blind eye to your dealings with the arakkoa prisoner, $N.  It looks like your instincts to cooperate with him were right.$B$BYou must understand... I would\'ve faced a mutiny in my current state if I endorsed your efforts to bring Terokk to this world.$B$BTake the items that Hazzik prepared for you and go ahead with your plan.  I will command my men to back you up when the time comes.  I recommend that you bring a force of your own as well.  I fear you\'ll only get one chance at this.]', '[Take the Time-Lost Offering prepared by Hazzik to the Skull Pile at the center of Skettis and summon and defeat Terokk.  Return to Sky Commander Adaris when you\'ve completed this task.]', '', '去找泰羅卡森林的天空指揮官艾德瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11074 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11074,'zhTW','仇敵的血脈','這本書中列有斯克提斯爪之祭司所囚禁著的所有泰羅克的宿敵的後裔，包括獵手吉薩拉克、水晶巨人卡爾洛格，還有被貶為異端的黑暗尖嘯者阿克卡萊和風怒者瓦克奇斯。必須要在泰羅克回到這個世界之前將他們全部殺死。$B$B你首先需要奪取一些迷失鴉人身上帶著的卷軸，然後在斯克提斯的召喚法陣中燒掉卷軸，召喚並殺死它們，從它們身上各找一樣信物帶回來。要知道，它們都是非常非常強大的存在，你最好帶上幾個朋友一起去。','從斯克提斯的迷失鴉人身上收集迷失卷軸，然後將它們拿到召喚法陣的徽記堆內，召喚出泰羅克仇敵的後裔，並擊敗它們。然後帶著阿克卡萊之爪、卡爾洛格之脊、瓦克奇斯之鱗和吉薩拉克之爪回去向哈吉克復命。','','去泰羅卡森林找黑風碼頭的哈吉克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11075 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11075,'zhTW','靈翼礦洞','靈翼礦洞需要你的幫助，監工$N。$B$B兩天前的突發事件迫使我們中斷了靈翼礦洞的開採作業。一名礦工在深井下工作時，將他的鎬敲在了一片非同尋常的水晶陣列上，而那片水晶竟然是一隻虛空龍身上的附著物！這頭被驚醒的野獸變得狂暴不已，殺死了所有的礦工。$B$B立即轉至西南方的靈翼礦洞，向礦洞女王報到。他們就在礦洞入口處等你。','轉至靈翼浮島，找到礦洞女王。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11076 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11076,'zhTW','回收貨物','我們的勞動成果！成堆的貨物被散亂地丟棄在礦洞中！當前的情況是一片混亂，我們根本沒法取回貨物。$B$B$N，這就是我叫你過來幫忙的原因。你在這裡的日常工作就是深入礦洞，收集那些被礦工拋下的貨物。$B$B將靈翼礦洞的貨物帶回來，交給我或是我的姐妹。','影月谷靈翼礦洞的礦洞女王要你取回15份虛空礦洞的貨物。','','去影月谷找靈翼礦洞的礦洞女王。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11077 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11077,'zhTW','龍？不是問題','被驚醒的虛空龍引發了一連續的騷動，混亂的場面激怒了其它居住在礦洞中的生物。其中，虛空礦洞剝石者和虛空礦洞掠食者簡直是龍喉氏族的眼中釘。你必須幫助我們清除這些野獸，我要你把這當做日常的工作來做。$B$B去吧，儘量削減它們的數量！','影月谷靈翼礦洞的龍喉工頭要你殺死15只虛空礦洞剝石者和5只虛空礦洞掠食者。','','去影月谷找靈翼礦洞的龍喉工頭。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11078 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11078, 'zhTW', '統治天空', '你四處飛行的時候，一定注意到上方的龍群了。我相信你還沒在他們的憤怒下成為受害者。幫我們結束它，$N!$B$B瑞文達科和歐比希迪亞主宰這個平臺，而印希迪恩和狂怒之翼則管理東北方平臺上方的天空。他們在各自的平臺都有自己的棲所。不知道你和你的朋友是否能去其中一個棲所，<小伙子/小姑娘>，打破一顆蛋把龍引下來。$B$B將龍牙交給我做為證據。要統治天空，不是我們死就是他們亡。', '天空指揮官凱勒要你取得龍牙，然後回到劍刃山脈頂端的禦天者崗哨交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11079 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11079, 'zhTW', '[A Fel Whip For Gahk]', '[Gahk think being smart is dumb sometimes.  Gahk not want to think.  Me want little $r to smash big demons!$B$BDey have some chiefs, and da chiefs all have whips to hurt da little demons.  You bring Gahk a whip!$B$BYou challenge demon chief in forge camps at burning, green, fel crystal prism.  Use many apexis shards to get dem to come.  Dey called Galvanoth, Braxxus, Zarcsin and da Mo\'arg Incinerator.]', '[Collect a Fel Whip.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11080 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11080, 'zhTW', '聖物的增益', '既然你已感受了頂尖聖物的啟發顫動，是時候讓你更了解它們的作用了。我們很希望得益於你對聖物的觀察!$B$B隨著你調合聖物的能力更進一步，你會獲得更高一層的知識。這個認知來自於聖物的放射增益。$B$B等你獲得這樣的放射增益後再來找我們。', '裘阿洛要你從頂尖聖物獲得頂尖放射增益效果再到劍刃山脈頂端的歐格利拉找他。', '已取得頂點放射物', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11081 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11081,'zhTW','暗血大逃亡','這份文件概述了暗血破碎者的叛逃計劃。看來他們企圖利用那隻虛空龍分佈我們的注意力，想要藉此機會集體逃亡。礦洞中橫七豎八地躺滿了暗血破碎者的屍體，很明顯，他們的計劃失敗了。$B$B將這份逃亡計劃交給礦洞女王。','將暗血逃亡計劃交給礦洞女王。','','去影月谷找靈翼礦洞的礦洞女王。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11082 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11082,'zhTW','尋找真相','這群愚蠢的礦工居然還制訂出了逃跑計劃。我們必須揪出煽動他們叛逃的幕後主使，然後狠狠地懲罰他。我要你深入礦洞，尋找暗血監工的下落。如果他們還沒有被礦洞中的野獸給幹掉的話，那肯定是找到什麼隱秘之處藏起來了。$B$B如果你搜出一名暗血監工，就立即拷問他，逼他供出逃亡計劃的主使者。得知幕後主謀的真實身份後，將監工之手帶回來向我覆命。','找到一名暗血監工，然後審訊他。向礦洞女王彙報審訊的結果，並將監工之手交給她。','收集暗血情報','去影月谷找靈翼礦洞的礦洞女王。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11083 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11083,'zhTW','瘋狂與困惑','別管那隻虛空龍，$N。我們自有別的安排……$B$B靈翼礦洞深處有一群瘋狂的暗血破碎者，自從虛空龍搗毀礦洞後，他們就被困在了下面。孤立無援的感受大概不好受吧，才兩天而已，這幫傢伙就徹底喪失了理智。$B$B他們竟然有了食屍的癖好，並開始自殘肢體。我們絕不容許這些癲狂的生物存在。去幹掉他們！一個不剩！','影月谷靈翼礦洞的驅奴者魯納格要你殺死瘋狂的暗血工頭和5名瘋狂的暗血礦工。','','去影月谷找靈翼礦洞的驅奴者魯納格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11084 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11084,'zhTW','立正，隊長！','哇呀呀，你……你還活著。很好，莫格霍爾大王要在他的塔樓召見你，要是你死了的話我還真不好交差。快去吧！','與影月谷龍喉營地的莫格霍爾大王談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11085 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11085, 'zhTW', '逃離司凱堤斯', '嗨，$N。謝謝你來幫我。$B$B阿拉卡的怪鳥在我進行偵察任務時把我從虛空鰭刺上擊下。$B$B我們快離開這裡，趁還來的及。', '安全護送禦天者囚犯並向天空士官多林報告。', '營救天空守衛的囚犯', '去找泰羅卡森林的天空士官多林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11086 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11086,'zhTW','暮光嶺的傳送門','身為一名龍喉隊長，你最重要的責任之一就是扼殺燃燒軍團在外域的一切活動。記住，讓那些打擾到伊利丹大人的傢伙都永遠閉嘴，這是你的義務！$B$B現在，那群愚蠢的惡魔正嘗試在納格蘭西方的暮光嶺一帶建立一處傳送門。他們必須為背叛而付出代價，而你，就將是我們派去收取這代價的代表。$B$B轉至暮光嶺，消滅那裡的惡魔。對他們的防禦工事，你至少每天得發動一次攻擊。','影月谷龍喉營地的莫格霍爾大王要你殺死20名死影密探。','','去影月谷找靈翼浮島的莫格霍爾大王。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11087 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11087,'zhTW','海加爾旗幟','伊利丹從永恆之井中取出了7瓶井水。他將其中3瓶倒入海加爾山巔的湖泊中，由此形成了第二口永恆之井。歲月流逝，剩下4瓶井水已不知去向。$B$B黑暗之門開啟後，我們得知伊利丹將2瓶井水交給了他的副官凱爾薩斯和瓦斯琪。取回殘餘的井水；我們可以利用它開啟通往近代或是遠古時期的海加爾山的時光通道。我們必須維持海加爾聖戰的成果。','時光之穴的索莉多米要你去從盤牙水庫的瓦斯琪女士身上取得瓦斯琪的殘存之瓶，從風暴要塞的凱爾薩斯·逐日者身上取得凱爾薩斯的殘存之瓶。','','去找塔納利斯的索莉多米。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11088 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11088,'zhTW','釐清你的訓練','幫我帶來很多的魔焰布，然後你就能忘記一切。','替強納森·巧手帶來10塊魔焰布。','','去找程式設計師之島的Jonathan LeCraft。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11089 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11089,'zhTW','雷薩赫爾的靈魂火炮','雷薩赫爾頓領導著納格蘭暮光谷的惡魔。讓這樣一個力量強大的艾瑞達人在這個世上囂張，實在是有損我們伊利達雷的臉面……但是我們也沒有足夠的力量去對付雷薩赫爾頓。至少在當前戰火已經燒到黑暗神殿門口的狀況下，我們沒有……哦……不對……我有個更好的計劃。$B$B你，沒錯，你將去制服雷薩赫爾頓，將他丟進暮光傳送門去，將他放逐出這個世界。但要執行這個計劃，必須先鑄造一臺靈魂火炮。$B$B把清單上所列的東西帶回來給我。','影月谷龍喉營地的伊利達雷領主巴塔斯要你將2塊魔鋼錠、1個精金框架、1個氪金能量核心和1份完美的奧術精華交給他。','','去影月谷找靈翼浮島的伊利達雷領主巴塔斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11090 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11090,'zhTW','征服者雷薩赫爾頓','<巴塔斯手裡拿著一件古怪的裝置。>$B$B這是一臺靈魂火炮，完成同調操作的火炮具備毀滅性的效果。我已經將它與我的血液進行了同調，而雷薩赫爾頓體內流動著的血液和我的完全相同。是的，他是我的兄弟。哎，可惜他選錯了效忠的主子，而這也就導致了他的滅亡。$B$B帶上靈魂火炮轉至納格蘭的暮光嶺，找到雷薩赫爾頓並向他開火！你必須待在你的座騎上，確保距離在射程之內。只要你堅持得住，最終他只能落敗而逃！','影月谷龍喉營地的伊利達雷領主巴塔斯要你轉至納格蘭，對征服者雷薩赫爾頓使用靈魂火炮。$B$B完成任務後歸還靈魂火炮。','戰勝征服者雷薩赫爾頓','去影月谷找靈翼浮島的伊利達雷領主巴塔斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11091 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11091, 'zhTW', '', '', '[Speak with Jho\'nass at Ogri\'la in the Blade\'s Edge Mountains.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11092 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11092,'zhTW','你好，指揮官！','$N隊長！$B$B<工頭瓦爾庫勒對你敬了個禮。>$B$B莫格霍爾大王請你立刻轉至他的房間接受覲見！','與影月谷龍喉營地的莫格霍爾大王談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11093 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11093, 'zhTW', '飢餓的虛空鰭刺', '虛空鰭刺一旦經過適當的訓練就會出奇地忠誠和順從。不幸的是司凱堤斯的戰役讓它們傷亡慘重。$B$B我們每天都有許多的突擊 - 可憐的伙伴們都很少休息。隨著最近食物短缺，如果那些可惡的鳥人不殺他們，飢餓也會把他們殺死。$B$B如果你可以幫個忙，帶一隻我們的鰭刺到南邊的樹林去。他們不喜歡扭曲追趕者的肉，除非是新鮮的。', '在黑風平臺南邊的樹林裡使用虛空鰭刺籠並殺死飢餓的虛空鰭刺附近的黑風扭曲追趕者。完成任務後回去找禦天者管理者迪塞克。', '', '去找泰羅卡森林的禦天者管理者迪塞克。', '', '鰭刺大餐', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11094 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11094,'zhTW','把他們都幹掉！','指揮官$N，立正！現在，你將立刻領導一隊碎天者轉至攻擊黑暗神殿西北方的占星者哨站。只要摧毀了群星聖殿，我們與庫斯卡崗哨之間的補給線就可以重新運作起來了。$B$B快去吧，用這個訊號槍指引碎天者展開攻擊！','將任務的相關情報和龍喉訊號槍一起交給群星聖殿的奧術師塞里斯。','','去影月谷找群星聖殿的奧術師塞里斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11095 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11095,'zhTW','指揮官霍布','龍喉氏族也就只敢趁我們不備時發動攻擊。要是我們有所準備的話，他們肯定沒有取勝的機會。$B$B$N，我要你引他們來戰。$B$B<塞里斯點了點頭。>$B$B對，沒錯……這是陷阱。莫格霍爾大王不是給了你一把訊號槍嗎？將訊號槍交給這座建築物外面的指揮官霍布。','將龍喉訊號槍交給影月谷群星聖殿的指揮官霍布。','','去影月谷找群星聖殿的指揮官霍布。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11096 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11096,'zhTW','臨近的威脅','這麼說，你想加入天空衛隊？好吧，我知道你確實能飛……可你會戰鬥嗎？$B$B天空衛隊誓死保衛沙塔斯免受一切威脅。當前居住在北方壁壘山中的戈杜尼食人魔是最緊迫的威脅。$B$B這些食人魔已經危害到了沙塔斯的地面交通和人員安全。這就是我們必須要去解決的問題。現在讓我們來看看你能幫上什麼忙吧。','在壁壘山殺死任意20個戈杜尼食人魔，然後向撒塔斯城的尤拉覆命。','','去找泰羅卡森林的尤拉。','戈杜尼食人魔','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11097 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11097,'zhTW','最致命的陷阱','帶上這些占星者勳章。戰鬥結束後，有了這些“勝利”的證據，莫格霍爾就會深信不疑了。他一定會以為這些都是由你從占星者士兵的屍體上拿來的。$B$B現在，唯一要做的事情就是利用這把訊號槍引來龍喉氏族的部隊。等你準備好之後我們就可以徹底消滅他們了。就等你發話呢。','協助指揮官霍布和占星者保衛群星聖殿。擊潰所有龍喉軍隊後，帶上占星者勳章返回龍喉營地，向莫格霍爾大王覆命。','擊敗龍喉氏族的軍隊','去影月谷找靈翼浮島的莫格霍爾大王。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11098 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11098, 'zhTW', '[To Skettis!]', '[The Barrier Hills are only one of the fronts where we\'ve been deployed.  A less immediate but far more dangerous threat looms from beyond the Skethyl Mountains, from within the arakkoa city of Skettis.$B$BA few months ago our scouts detected a huge increase in arakkoa activity there.  Several attacks against Shattrath followed.  We\'ve stationed forces outside of their city since.$B$BTake these explosives to Sergeant Doryn at Blackwind Landing, just outside Skettis.  Tell him you\'re a new recruit.]', '[Take the Explosives Package to Sky Sergeant Doryn at Blackwind Landing outside Skettis.]', '', '去找泰羅卡森林的天空士官多林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11099 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11099,'zhTW','把他們都幹掉！','指揮官$N，立正！現在，你將立刻領導一隊碎天者轉至攻擊黑暗神殿西北方的奧爾多哨站——沙塔爾祭壇。只要摧毀了沙塔爾祭壇，我們與庫斯卡崗哨之間的補給線就可以重新運作起來了。$B$B快去吧，用這個訊號槍指引碎天者展開攻擊！','將任務的相關情報和龍喉訊號槍一起交給沙塔爾祭壇的學者希拉。','','去影月谷找沙塔爾祭壇的學者希拉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11100 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11100, 'zhTW', '[Commander Arcus]', '[The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared.$B$BI want you to let them come, $N.$B$B<Ceyla nods.>$B$BYes... a trap. Take this flare that their overlord gave you and deliver it to Commander Arcus. He is standing guard right outside this building.$B$B]', '[Give the Dragonmaw Flare to Commander Arcus at the Altar of Sha\'tar in Shadowmoon Valley.]', '', '去找影月谷的指揮官阿克斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11101 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11101,'zhTW','最致命的陷阱','帶上這些奧爾多勳章。戰鬥結束後，有了這些“勝利”的證據，莫格霍爾就會深信不疑了。他一定會以為這些都是由你從奧爾多士兵的屍體上拿來的。$B$B現在，唯一要做的事情就是利用這把訊號槍引來龍喉氏族的部隊。等你準備好之後我們就可以徹底消滅他們了。就等你發話呢。','協助指揮官阿庫斯和奧爾多保衛沙塔爾祭壇。擊潰所有龍喉軍隊後，帶上奧爾多勳章返回龍喉營地，向莫格霍爾大王覆命。','擊敗龍喉氏族的軍隊','去影月谷找靈翼浮島的莫格霍爾大王。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11102 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11102, 'zhTW', '[Bombing Run]', '[You can fly around as a crow... so what!  Ever annihilate something on the ground while you were flying?  Want to?$B$BForge Camp: Wrath and Forge Camp: Terror, to the north and south, are a major pain in my backside, as well as being a threat to peaceful Ogri\'la.  With all of those fel cannons shooting down the Skyguard left and right, we can\'t get through there to take care of business.$B$BWant to prove yourself?  Take these bombs and knock out their ammo stacks.  Just don\'t let them shoot you down, too!]', '[Use the Skyguard Bombs to destroy 15 Fel Cannonball Stacks.]', '', '', '邪能砲彈堆已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11103 AND `locale` = 'zhTW';
