INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11116,'zhTW','納魯的試煉：瑪瑟裡頓','想要證明你自己擁有獲得風暴鑰匙的資格，你必須首先完成四個試煉。$B$B現在，你只需要跨越最後一個障礙了，凡人。聚集一支軍隊，轉至地獄火堡壘深處，在瑪瑟裡頓的巢穴中殺出一條血路，進入中央的密室，殺死那個邪惡的腐蝕者！$B$B完成了這個任務，你就將獲得風暴鑰匙。','撒塔斯城的阿達爾要求你殺死瑪瑟裡頓。','','到地獄火半島找阿達歐。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11117 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11117, 'zhTW', '抓住野生鹿角兔!', '就是現在。你聽到了嗎?從那邊的丘陵傳過來的。那是鹿角兔!被啤酒節氣味吸引過來的野生動物。我一直想抓一些，可惜我撞傷了小腿，跑不過那些兔崽子。但是你可以幫我!$B$B帶著這個網子然後用它抓住那些小傢伙。帶五隻回來給我，我會給你很不錯的報酬!還有一件事 - 你得喝到醉眼惺忪才能看到牠們!大杯乾下去或者跟我要一副模擬醉眼護目鏡!', '茍達克·狙獵者要你用鹿角兔捕網幫他抓5隻昏迷的鹿角兔。他提到你必須要喝醉或戴上模擬醉眼護目鏡才看得到那些鹿角兔。', '', '去找丹莫羅的苟達克‧狙獵者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11118 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11118, 'zhTW', '粉紅伊萊克遊行', '在啤酒節時喝醉是個長久以來的優良傳統 -- 是天殺的必要!問題是，我接到從艾澤拉斯各地的報告都指出，我們的慶典被幻像所騷擾!我們可不能容許這種事!$B$B這些伊萊克不能被一般武器所傷害 -- 武器會直接穿過牠們 -- 所以帶著這個驚人的地精裝置前往其他的啤酒廣場，讓牠們灰飛湮滅。要記得，你一定要喝醉或戴上模擬醉眼護目鏡才能看到牠們!如果你需要一副的話跟我說一聲。', '前往暴風城、達納蘇斯還有艾克索達外頭的啤酒廣場，在那些地方宰掉三頭伊萊克，然後回去找茍達克·狙獵者。你一定要喝醉或戴上模擬醉眼護目鏡才看得見那些粉紅伊萊克。', '', '去找丹莫羅的苟達克‧狙獵者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11119 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11119, 'zhTW', '', '', '[Speak with the Aether-tech Apprentice at Skyguard Outpost in the Blade\'s Edge Mountains.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11120 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11120, 'zhTW', '粉紅伊萊克遊行', '聽著，我們正在此地做點生意。人們都喝醉啦?這是筆好生意，但我得告訴你有件事情在限制我們的利潤 - 那些幻覺。你不知道那個嗎?那些孩子向我報告說，我忠實的老主顧們正在四處尋找粉紅伊萊克。$B$B我可不希望我的老主顧心神不寧。聽好，帶著這隻鰭刺去其他的啤酒廣場，並且替我好好照顧牠，行嗎?記得一定要喝醉啊!', '造訪銀月城、雷霆崖還有幽暗城外的啤酒廣場，在每個地方各宰掉三隻伊萊克，然後回去找葛羅卓克·獵狙者。你一定要喝醉才看得見那些粉紅伊萊克。', '', '去找杜隆塔爾的葛羅卓克‧獵狙者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11121 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11121,'zhTW','DAILY TEST QUEST (RAID)[日常]','<NYI>Seek <QUESTGIVER> in <LOCATION>.  S/he wishes for you to aid them in a difficult task.','Speak with <QUESTGIVER> in the <AREA>.','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11122 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11122, 'zhTW', '[There and Back Again]', '[So you want to help out at Brewfest?  I\'ve got the perfect task for ya.  I\'ll put you on one of my racing rams and you head down to Kharanos.  I\'ve got some kegs I need to pick up.  $B$BFlynn Firebrew is waiting on a hill near a stack of kegs.  He\'ll toss you a keg when you get near, then you run the keg back here and toss the keg to Pol Amberstill.  You can only carry one at a time.  $B$BReady?]', '[Get a keg from Flynn Firebrew in Kharanos and return it to Pol Amberstill.  Do this 3 times before your ram goes away.]', '', '去找丹莫羅的奈爾‧拉姆斯登。', '酒桶已運送', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11123 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11123,'zhTW','調查廢墟','可憐的詹姆斯還沒從樹蔭旅店的毀滅和他的家人被殺害的陰影中恢復過來。我和夥計們正在盡一切努力找到犯下這些罪惡的混蛋。$B$B我已經派出了最好的調查員塔雷姆去了廢墟，但這對於任何人來說都是個艱鉅的任務。如果你願意幫助塔雷姆的話，我們會非常感謝的。聖光作證，我們都很願意去那裡幫忙。$B$B這條大路會將你引向旅店，不過要多加小心，你的旅程超出了我們士兵的保護範圍。','去和樹蔭旅店的調查員塔雷姆談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11124 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11124,'zhTW','調查廢墟','如果你沿著這條路向南走，然後向西往貧瘠之地方向前進，就可以到達樹蔭旅店的廢墟。$B$B塞拉摩已經派出了調查員去調查旅店是怎麼變成現在這般模樣的。通常，我會勸告你不要多管閒事，不過我們收到了來自奧格瑪的要求“幫助”調查的命令。$B$B滿足塞拉摩調查員提出的任何要求，如果你高興的話，甚至可以向他透露一點情報，不過記住，把真正的發現告訴我。','去和樹蔭旅店的調查員塔雷姆談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11125 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11125,'zhTW','[PH] New Hinterlands Quest','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11126 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11126,'zhTW','叛徒','見到你很榮幸，$c。我來到塞拉摩是為了幫忙解決這些叛逃者的麻煩。他們不僅到處張貼宣傳海報，甚至已經有一些人滲透進了我們的城鎮。$B$B這些叛逃者正到處散佈著謠言和宣傳資料，希望能說服其它人加入他們的隊伍。$B$B事實上，從城鎮到碼頭的每個崗哨附近都能看到他們的身影。找到他們，揭露他們，然後羞辱他們。在現在這個節骨眼上，任何事情都有可能給他們帶來更多的同情者。','與5個叛逃煽動者對質，然後向塞拉摩碼頭附近的加莉亞·哈斯汀彙報。','','去塵泥沼澤找塞拉摩島的加莉亞·哈斯汀。','揭露叛逃煽動者的面目','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11127 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11127, 'zhTW', '[<NYI>Thunderbrew Secrets]', '[Now I\'d never steal a thing from our Thunderbrew cousins. They\'re good people. But if you want to get ahead in this business, sometimes you have to do unfortunate things, and that\'s why I hire other people to do it for me.$B$BGrimbooze Thunderbrew is a nutty member of the family who lives south of Moonbrook in the hills of Westfall. I hear he has a new recipe for ale, and I want it before it hits the market. You can fetch it for me, can\'t you? I\'ll reward you. A Barleybrew pays his debts.]', '偷走格林布茲在西部荒野營地裡的秘密配方，然後回到啤酒節廣場交給$n‧麥酒。', '', '去找丹莫羅的畢肯‧麥酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11128 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11128,'zhTW','宣傳戰','這些叛逃者並非只是在說服衛兵那麼簡單。我們還在碼頭的一艘船上發現了大量不知道怎麼偷運進來的叛逃者傳單。$B$B那艘用來運送傳單的船現在還停泊在塞拉摩，就在最遠端的碼頭那裡。如果你能潛入那艘船，奪走他們宣傳資料的話，他們的人就會失去最有力的工具。不過小心！這艘船被一群經驗豐富的海盜控制著，而且貨物很可能被藏在船長室裡。','將叛逃者傳單交給塞拉摩碼頭附近的加莉亞·哈斯汀。','','去塵泥沼澤找塞拉摩島的加莉亞·哈斯汀。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11129 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11129, 'zhTW', '凱爾失蹤了!', '幫幫我，$N! 我最寶貝的寵物，凱爾跑不見了!我只知道牠平常會在血蹄村附近亂跑，牠現在一定是迷了路又餓著肚子。$B$B你願意幫我找到牠並且餵牠嗎?只要牠吃飽了，牠就會安靜下來並且回家來。$B$B你需要去找食物來餵牠。牠最喜歡的就是嫩陸行鳥肉了，你只需要獵一隻並且拿那些多汁的肉給凱爾。你要是看見凱爾在村子裡，牠一定會過來找你的。', '莫高雷-血蹄村的亞哈伯·麥蹄希望你幫忙找他珍貴的寵物，狂怒的凱爾。$B$B餵凱爾吃嫩陸行鳥肉，然後回去找亞哈伯·麥蹄。', '', '去找莫高雷的亞哈伯·麥蹄。', '', '凱爾被餵飽了', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11130 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11130,'zhTW','閃亮閃亮的東西！','過來過來，$G夥計:寶貝兒;！讓我老格裡伏塔看看那些閃亮閃亮的東西……$B$B嗯嗯，嘿，不錯不錯，但應該還有更好的。對，對，好上許多的。$B$B<格裡伏塔向你斜過身來，低聲耳語道。>$B$B很多地方呢，有許多許多寶貴的閃亮閃亮的小玩意，但你得知道哪裡有才行！不過今天呢，可就是你的幸運日了。我認識一個能幫你忙的傢伙，可以讓你找到無數亮閃閃的東西，多得你都拿不動。$B$B去吧，去找我的老朋友巴德，他就在祖阿曼附近。你呢，就跟他說是老格裡伏塔派你去的，他就會讓你參加他的新計畫啦。','格裡伏塔要求你將他的便箋交給鬼魂之地的巴德，他就在祖阿曼外。','','到鬼魂之地找霸德·奈德瑞克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11131 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11131, 'zhTW', '[Stop the Fires!]', '[You must help us!  The Headless Horseman is attacking the village.  Fires are everywhere!  The children aren\'t safe!$B$BPlease, $n, join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who\'s closer to the blaze.  Put out all the fires and we may yet be saved!]', '[The Costumed Orphan Matron wants you to help put out all the village fires.  When they are out, speak again to the Costumed Orphan Matron.]', '撲滅火勢', '去找變裝的孤兒監護員。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11132 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11132, 'zhTW', '[Promises, Promises...]', '[My inscrutable theories confirm rumors of vast treasure in Zul\'Aman. There\'ll be mounts and mansions for everyone! First things first, though. You must earn your share, after all....$B$BOur initial efforts here haven\'t gone as well as I hoped. In fact, my map, and the recruits I lent it to, have gone missing. They were after a troll-beast named Nalorakk.$B$BForget the crew, I need that map! Succeed, and you\'ll go down in history as the one who helped Budd Nedreck unlock the secrets of Zul\'Aman!]', '[Budd Nedreck in Hatchet Hills wants you to retrieve his map from High Priest Nalorakk\'s terrace in Zul\'Aman.]', '', '去找幽魂之地的霸德·奈德瑞克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11133 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11133,'zhTW','羞辱叛逃者','我已經把你從叛逃者手中奪來的傳單修改了。現在，任何人讀到這些傳單，都會得到一個和他們的本意截然相反的觀點。$B$B如果我們將這些傳單分發給足夠多的衛兵，那樣這些叛逃者在我們的領地裡就會陷入空前的窘境。$B$B<加莉亞遞給你一疊修改過的傳單。>$B$B你為什麼不在我策劃下一步行動的時候趕緊行動起來呢？','加莉亞·哈斯汀希望你向6個塞拉摩衛兵發放修改過的傳單，然後返回塞拉摩碼頭附近向她覆命。','','去塵泥沼澤找塞拉摩島的加莉亞·哈斯汀。','發放傳單','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11134 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11134,'zhTW','叛逃者的末日','現在我們已經把這些叛逃者從塞拉摩掃了出去，是時候完成最後一擊了。我的線人告訴我，叛逃者們正在一艘停泊在碼頭東南面小島旁的船上部署著行動。$B$B逮捕他們的首領賈維斯·格雷希德，這樣應該會讓其它人失去戰鬥的決心。去船上找到他，並說服他投降。如果他表現出戰意的話，我一點都不驚訝。不過當他知道自己不可能獲勝的時候，他一定會投降的。','抓住賈維斯·格雷希德，然後向塞拉摩碼頭附近的加莉亞·哈斯汀覆命。','','去塵泥沼澤找塞拉摩島的加莉亞·哈斯汀。','抓獲賈維斯·格雷希德','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11135 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11135, 'zhTW', '', '', '此任務已經絕版。[Find the Headless Horseman\'s pumpkin Shrine.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11136 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11136,'zhTW','麻煩的事態','我們的斥候最近帶回來了一條非常令人困擾的訊息。他們說最近有一群戴著紅色面巾的迪菲亞強盜出現在了塞拉摩北部城牆外的恐懼海岸。$B$B那附近的一些船隻殘骸說明，他們所乘坐的船隻很可能遭遇了海難，不過我們的情報還是不夠完全。本城北部的重要哨塔——警戒崗哨的維摩爾上尉當前正在找人協助情報的收集和調查工作。','向警戒哨崗的維摩爾上尉報到。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11137 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11137,'zhTW','塵泥沼澤有迪菲亞兄弟會？','我手下的斥候前幾天報告說，有一條受了重創的遠航帆船擱淺在了東北方的海灘上。不過，海難並不是那條船上唯一不尋常的地方，報告還指出，船上的全部倖存者都戴著紅色的頭巾！$B$B要知道，迪菲亞兄弟會的主要成員都是石匠和公會成員，沒有水手。那麼這群人在一片他們完全不感興趣的大陸上對著船隻的殘骸又在幹些什麼呢？$B$B據說他們的頭目就在哨塔東北邊海岸對面的那座島嶼上。殺死他，把他那裡的所有檔案都帶回來。','從加恩·馬瑟斯手中奪得迪菲亞命令書，把它們交給警戒崗哨的維摩爾上尉。','','去塵泥沼澤找警戒哨崗的維摩爾上尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11138 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11138,'zhTW','雷恩·米克基爾','根據你帶來的這些命令書所說，這些迪菲亞的傢伙們當前第一優先要做的事情，就是找到並確保那個什麼貨物的安全。$B$B暴風城軍情七處有一位救援潛水員名叫雷恩·米克基爾，當前正在塞拉摩工作。他聽說海難的訊息之後，就轉至了迪菲亞兄弟會佔據的那座小島附近。$B$B如果我們想從迪菲亞兄弟會手裡搞到這個所謂的貨物，就必定需要他的幫助。總之，你可以到你之前剛剛拜訪過的那座島嶼北邊的一處小島旁去找他，他應該就在小島東北邊的水裡潛伏著。','將迪菲亞命令書交給恐懼海岸水邊的雷恩·米克基爾。','','去塵泥沼澤找恐懼海岸的瑞恩·米克基爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11139 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11139,'zhTW','二手潛水裝置','從這裡到奧卡茲島周圍的海底，到處都散佈著那條船的殘骸與碎片。而且，迪菲亞那邊已經派出了一些潛水員在附近搜尋著些什麼。只要穿上他們的裝備，我們也能把你派去混到他們中間，加入他們的搜尋活動。不過，首先你得非常非常“有創意”地借一點他們的東西過來。$B$B搜尋這座島嶼，給我弄來一箱潛水裝置，再帶些修理工具回來，我可以幫你把它們製作成合適的潛水裝置！','將工具包和損壞的潛水裝置交給塵泥沼澤的雷恩·米克基爾。','','去塵泥沼澤找恐懼海岸的瑞恩·米克基爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11140 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11140,'zhTW','找回貨物！','呃，我確實能把這東西徹底修好，能讓你真的用它去潛水。只是……時間上的估算略有一點小錯誤。$B$B沉船的殘骸當前遍佈整個海底，在這座島嶼東邊的海岸直到奧卡茲島之間幾乎都是。這頂頭盔可以確定出殘骸的位置，你可以用它來尋找殘骸。然後，再利用這個打撈裝置來搜尋殘骸，看看那個什麼貨物是否在其中。小心點，別太接近奧卡茲島，那些多頭蛇非常兇暴和危險。','將6只打撈上來的保險箱交給塵泥沼澤的雷恩·米克基爾。','','去塵泥沼澤找恐懼海岸的瑞恩·米克基爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11141 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11141,'zhTW','通知吉安娜','啊……你必須立刻把我們的發現通報給吉安娜女士，刻不容緩！迪菲亞兄弟會似乎是在運送某個囚犯，我們還不清楚那個囚犯的身份，以及他是否還活著。$B$B不過有一點很肯定，$N。迪菲亞兄弟會對這個囚犯相當客氣，看來他的身份十分重要。吉安娜女士一定能從這些發現中瞭解到些什麼，你必須立刻到塞拉摩中央的法師塔頂上去找她。','與塞拉摩的吉安娜·普羅德摩爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11142 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11142,'zhTW','調查奧卡茲島','看來，我們派瑞恩潛伏在奧卡茲島一帶的決定是對的。現在，我們需要更加仔細地調查那座島，不過那樣的話，我們恐怕得派整整一個軍團的士兵幫我們開道。$B$B問題是，塞拉摩的防務很緊張，沒有多餘的兵力。我已經安排了這裡的飛行管理員的學徒卡薩·赤翼來協助你，她會用她的獅鷲送你去進行空中偵查。$B$B奧卡茲島上隱藏著迪菲亞兄弟會的一切有關這次綁架的秘密。','與卡薩·赤翼談一談，乘坐她的獅鷲調查奧卡茲島。調查完成之後，回去向塞拉摩的吉安娜·普羅德摩爾報告。','偵察奧卡茲島','去塵泥沼澤找塞拉摩島的吉安娜·普羅德摩爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11143 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11143,'zhTW','恐怖圖騰','我已經把你在樹蔭旅店收集到的證據告訴調查員塔雷姆了。他似乎確信這些蹄印和你在那裡找到的盾牌都非常明顯地證明了這一切都是牛頭人的恐怖圖騰氏族所為。$B$B隨著恐怖圖騰在沼澤越來越活躍，這一切看上去都不僅僅是一場巧合。現在我派你去和達利爾上尉談談，他一直以來都在關注著恐怖圖騰。沿著這條路往北出城，轉至北點哨塔，就是沿路的第二座崗哨。','向北點哨塔的達利爾上尉報告。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11144 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11144,'zhTW','尋找證據','恐怖圖騰可能是牛頭人中最好戰的部族，但是他們絕不是是一盤散沙。如果是他們燒燬了樹蔭旅店，那麼他們必定是從他們的部族長者那裡接受了命令才會這麼做。$B$B在這裡的西北方，有一處龐大的恐怖圖騰定居點——黑蹄村。他們一直把黑蹄村作為進攻哨塔的基地，我打賭如果你去那裡尋找的話，一定會找到命令書之類的東西。去黑蹄村的長者那裡尋找證據吧。','將恐怖圖騰作戰計劃交給北點哨塔的達利爾上尉。','','去塵泥沼澤找北點哨塔的達利爾上尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11145 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11145,'zhTW','恐怖圖騰的囚犯','我們正在盡全力不讓恐怖圖騰的那些混賬接近這裡，但他們一直都在發動對哨塔的攻擊。更糟的是，他們發現並俘虜了上尉派去收集情報的斥候，開始在路上駐守起來。$B$B我懷疑那些俘虜都被關押在黑蹄村，就在這裡的西北方。根據我對恐怖圖騰的瞭解，村裡的衛兵很可能會隨身帶著囚籠的鑰匙。我不管你怎麼做，$c，我只想看到我們的人活著回來。','北點哨塔的盧卡斯中士希望你能解救5名塞拉摩囚犯。','','去找塵泥沼澤北點哨塔的盧卡斯中士。','解救塞拉摩囚犯','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11146 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11146,'zhTW','捕捉迅猛龍','這片沼澤的東北部有一塊地方被一群骯髒無比的迅猛龍佔據了。它們奪走了不止一個士兵的生命，但我想，我們可以利用它們來對付那幫牛頭人鄰居。$B$B將這根繩子帶過去，用它抓捕幾隻血沼迅猛龍或是血沼尖嘯龍來，當然，你得先制服它們。只有你先在戰鬥中將它們打得暈頭轉向以後才可以抓捕。總之，會有點困難，加油吧。','北點哨塔的盧卡斯中士要求你捕捉6只迅猛龍。血沼迅猛龍或是血沼尖嘯龍都可以滿足他的要求。','','去找塵泥沼澤北點哨塔的盧卡斯中士。','捕獲迅猛龍','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11147 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11147,'zhTW','放生迅猛龍','現在我們有迅猛龍了，下一步就是想辦法“鼓勵”它們去攻擊西北邊黑蹄村裡的那些恐怖圖騰牛頭人。$B$B我這裡剛好還有一些沒吃完的烤牛腰，或者是烤羊腰……不管了……愛是什麼是什麼吧。總之，你可以拿它當餌。把它放進黑蹄村中央那架風車的下面，那些迅猛龍就知道該做什麼了。','北點哨塔的盧卡斯中士要求你將迅猛龍誘餌放在黑蹄村的風車附近。','','去找塵泥沼澤北點哨塔的盧卡斯中士。','放生迅猛龍','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11148 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11148,'zhTW','恐怖圖騰的軍備','如果你在樹蔭旅店找到的裝備是屬於恐怖圖騰部隊的話，那麼很可能他們在西北部的營地裡會有更多類似的裝備。$B$B我們還不能從黑蹄村得到更多的情報。不過從襲擊者的規模來看，那裡駐守著大量的部隊。$B$B想辦法去那裡弄一些他們的裝備來，這樣我們就可以拿它們和你在旅店找到的那些比較一下了。','北點哨塔的達利爾上尉希望你能交給他7件黑蹄軍備。','','去塵泥沼澤找北點哨塔的達利爾上尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11149 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11149,'zhTW','塔貝薩的協助','我實在抽調不出其它人手來幫你尋找恐怖圖騰的另一個據點了，但我覺得有人也許可以幫助你。$B$B在這裡南面的泥潭沼澤深處，有一個屬於塔貝薩的農場。她看起來像是個隱士，但事實上她是個法師，還是個有名的占星者。沿著這條路往南，到她的農場去尋求她的幫助，找出究竟是誰該為樹蔭旅店的屠殺負責。','與塔貝薩農場的塔貝薩談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11150 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11150,'zhTW','燒燬恐角崗哨！','根本沒有必要用水晶球來看看我們的新“鄰居”在幹些什麼。如果這就是焚燬樹蔭旅店的那支部隊，那麼我們也沒有理由再容忍他們的存在。$B$B拿上這根火把，將他們的營地夷為平地吧！你可以在我的農場略北一些的地方找到恐角崗哨。你不可能看不到，真的，因為恐怖圖騰在那裡豎著許多非常華麗的圖騰，以此表明他們對圖騰的喜愛。','燒燬恐角崗哨的北部帳篷、東部帳篷和東北部帳篷，然後回到塔貝薩的農場，向塔貝薩覆命。','','去塵泥沼澤找塔貝薩的農場的塔貝薩。','燒燬北部帳篷','燒燬東北部帳篷','燒燬東部帳篷','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11151 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11151,'zhTW','為海厄爾一家復仇','儘管這些恐怖圖騰的傢伙對我來說只能算是一個小麻煩，維米斯隊長還是應該得知你所做的一切。把你追捕和解決了那些燒燬樹蔭旅店的傢伙的訊息告訴他吧。$B$B儘管這一切還是救不了海厄爾一家，但也許恐怖圖騰在攻擊塞拉摩人的時候會有所顧忌。','與塞拉摩城堡中的的蓋蘭·維米斯隊長談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11152 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11152,'zhTW','安息','我希望有辦法讓詹姆斯·海厄爾的妻兒知道我們已經將殺害他們的兇手繩之以法了。$B$B<維米斯隊長拿出了一個小花圈。>$B$B有人說只要這樣做，即使我們不能聯絡到他們，他們的在天之靈也會安息。我希望你可以把這個花圈放在海厄爾家族的墓碑前，就是塞拉摩大門北面墓地中的大石碑。','塞拉摩城堡中的蓋蘭·維米斯隊長想讓你在海厄爾家族墓碑前放上一個花圈。','','去塵泥沼澤找塞拉摩堡壘的蓋蘭·維米斯隊長。','在海厄爾家族墓碑前放置花圈','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11153 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11153, 'zhTW', '[Break the Blockade]', '[All of our ships are sunk! We need your help to break the pirate blockade below in the Shattered Straits!$B$BTake these cluster bombs and hitch a ride on the zeppelin that Harrowmeiser has \'loaned\' to us.  He\'ll fly you over the decks of those pirate scoundrels, and you make sure to give it to them good!$B$BIf you can\'t bomb them to smithereens, I\'m afraid we\'ll never be able to break the blockade.]', '[Take Petrov\'s Cluster Bombs and drop them on enough pirates to kill or destroy 25 Blockade Pirates and 10 Blockade Cannons.  Once you\'ve accomplished that, return to Bombardier Petrov at Westguard Keep.]', '', '去找嚎風峽灣的投彈手派特洛夫。', '', '封鎖砲台已摧毀', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11154 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11154, 'zhTW', '[Scare the Guano Out of Them!]', '[You, yes you... I need your help!$B$BPetrov sent me up here to get bat guano for the cluster bombs he\'s making back at the keep. He sent me to my doom!$B$BThe darkclaw bats hang out in the Rivenwood to the north, but I\'m not taking a step off of this platform unless it\'s to go home!$B$BBut you... you could get it for me! Yes? Pretty please?!!!$B$BHere, take these firecrackers. My thinking is that if you drop \'em underneath the bats, the guano will be scared right out of them!]', '[Collect 10 Darkclaw Guano and deliver them to Engineer Feknut at Steel Gate.]', '', '去找嚎風峽灣的工程師費克努。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11155 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11155, 'zhTW', '[Shoveltusk Soup Again?]', '[With all of the strange disappearances of our livestock, we better resupply in a hurry, or the beasties around these parts will be the least of our worries!$B$BSeeing as I\'m in charge of feeding this lot, I\'m going to need you to head east and get me some meat. More to the point, I\'m looking to cook us up some tender shoveltusk meat.$B$BJust beware the stags... they\'re mean!]', '[Chef Kettleblack has asked you to obtain 6 Shoveltusk Meat and deliver them to her at Westguard Keep.]', '', '去找嚎風峽灣的主廚黑壺。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11156 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11156,'zhTW','恐角襲擊者','恐怖圖騰的成員聚集在這裡北面的恐角崗哨，現在他們真是越來越大膽了。在晚上，你能常常聽到他們在頌唱與這裡的居民戰鬥的“事蹟”。$B$B他們決心把我們從農場上趕走，但是塔貝薩在這裡訓練了一代代的學徒，怎麼會說走就走呢？我們盡全力保護著農場，但學徒加里奧在上次戰鬥中受傷了。$B$B去恐角崗哨消滅你所找到的一切恐怖圖騰成員！必須阻止他們的進攻！','在恐角崗哨消滅12個恐怖圖騰成員，然後向塔貝薩農場的學徒莫蘭恩覆命。','','去塵泥沼澤找塔貝薩的農場的學徒莫蘭恩。','殺死恐角崗哨的恐怖圖騰成員','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11157 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11157, 'zhTW', '[The Clutches of Evil]', '[$N, I don\'t trust anyone but you to take care of this.  I need the proto-drake eggs and proto-whelps in the burning forest to the southeast destroyed!$B$BSince we arrived here, the Ember Clutch has been ablaze; there must be some sort of perverse magic at work. And lately it seems to be growing. My men tell me that if we don\'t do something quickly, we\'ll be surrounded on all sides by the fire within a few weeks\' time!$B$BGet down there and eliminate the threat by destroying those eggs and the proto-whelps.]', '[Destroy 15 Proto-Drake Eggs and 15 Proto-Whelps, and then return to Captain Adams at Westguard Keep.]', '', '去找嚎風峽灣的亞當斯隊長。', '元龍幼龍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11158 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11158,'zhTW','血沼羽毛','看見布洛格在這裡，你是不是非常驚訝呢，小$r？別擔心，泥鏈鎮的地精都是布洛格的朋友，你也可以喔。$B$B新的大王不敢向那些摧毀了我們故鄉並屠殺我們同胞的黑龍復仇，所以布洛格就離開了蕨牆村。布洛格來這裡，是為了讓那些朋友們的靈魂重新得到安息，並向黑龍復仇！不過，布洛格首先需要一些準備。為了儀式，布洛格需要羽毛，具有強大魔力的羽毛，比如鎮子西邊鮮血沼澤墓穴那邊的迅猛龍的羽毛。','將5片血沼羽毛交給泥鏈鎮的布洛格。','','去塵泥沼澤找泥鏈鎮的布洛格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11159 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11159,'zhTW','石槌之魂','布洛格已經完成了圖騰，它可以讓朋友們的靈魂迴歸安息。那些龍打過來的時候，殺死了幾乎所有沒來得及逃走的朋友。布洛格和莫格穆洛克大王，一直希望能領導其它倖存下來的石槌食人魔發動反擊。$B$B不過，反擊一直沒有開始，而死去同胞們的靈魂卻一直困擾著布洛格與其它人。把這根圖騰帶到石槌廢墟去，在那些食人魔的骸骨旁使用它，將他們的靈魂吸引到你這裡，擊敗那些靈魂，就能讓他們獲得安息了。','泥鏈鎮的布洛格要求你讓10個石槌之魂得到安息。','','去塵泥沼澤找泥鏈鎮的布洛格。','讓石槌之魂安息','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11160 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11160,'zhTW','石槌戰旗','當那些龍跑過來奪走布洛格的家時，大多數的石槌食人魔都逃跑了，沒來得及帶走任何東西，甚至包括氏族的旗幟。$B$B布洛格知道旗幟就藏在石槌食人魔山中，不過現在，那地方被稱作火焰洞穴了。布洛格一定要奪回旗幟，用它向那些殺死了朋友們的龍復仇。$B$B總之，布洛格氏族的領地，現在叫火焰洞穴，就在泥鏈鎮的西北方向，不過那裡現在全是龍了。旗幟一定就藏在洞穴深處，要小心，$N。','奪取石槌戰旗，並將它交給泥鏈鎮的布洛格。','','去塵泥沼澤找泥鏈鎮的布洛格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11161 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11161,'zhTW','憎恨的精華','要想做出布洛格在儀式上必須要用到的圖騰，就需要那些曾殺死朋友們的生物的精華。布洛格的敵人所發散出來的仇恨與憤怒，將會給魔法灌入仇恨的力量。$B$B去找火鬃斥候、火鬃灰尾龍人，還有火鬃守衛，殺死它們，再在屍體上使用圖騰。龍類只有在死去的時候才會釋放出精華。$B$B這些傢伙就在西北方的火焰洞穴和北方的石槌廢墟一帶活動。','將10份黑龍精華交給泥鏈鎮的布洛格。','','去塵泥沼澤找泥鏈鎮的布洛格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11162 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11162,'zhTW','挑戰黑龍軍團','布洛格已經決定要對沼澤裡那些黑龍展開復仇了。$N，你可以給我很大的幫助。你會幫忙嗎？$B$B把布洛格的氏族旗幟帶上，到東邊去找一處類似龍嘴的洞穴，把旗幟插在那裡。這樣就象徵著我正式對奧妮克希亞宣戰了。$B$B布洛格，還有石槌氏族一定要奪回屬於我們自己的土地！','將石槌戰旗插在奧妮克希亞的巢穴入口附近，等待奧妮克希亞的回應，然後回去向泥鏈鎮的布洛格覆命。','','去塵泥沼澤找泥鏈鎮的布洛格。','為石槌氏族復仇','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11163 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11163,'zhTW','對不起，我是臥底','<多娜環顧了一下週圍，然後對你悄悄地說。>$B$B$n，我接下來告訴你的事情一定要嚴格保密，你明白嗎？$B$B其實我是沙塔斯衛隊派到巴德身邊的臥底。說實話，你剛來的時候我一度認為你是他們組織中的關鍵人物。$B$B但是你的行動打消了我的疑慮，洗清了你的嫌疑。實際上，既然你幹掉了瘋狂的祖爾金，我一定要好好獎勵一下你！','向多娜·布拉斯庫報告你的英雄事蹟，並領取你的獎勵。多娜現在駐紮在祖阿曼外面的鬼魂之地。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11164 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11164, 'zhTW', '[Tuskin\' Raiders]', '[\'Ey mon! You be new around \'ere, eh? Lemme ask a favor of ya.$B$BBudd\'s been refinin\' his forest troll disguise. Says that he be close now - just be needin\' one last touch. Tusks.$B$BMy skinnin\' talents be wasted \'ere. Somethin\' about yankin\' troll tusks be makin me queasy. $B$BBring me back 10 troll tusks, eh mon?]', '[Prigmon needs you to collect 10 Forest Troll Tusks from the trolls in Zul\'Aman. Bring them to him at Budd\'s camp in the Ghostlands.]', '', '去找幽魂之地的皮格蒙。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11165 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11165, 'zhTW', '', '', '[Prigmon has tasked you with locating and assisting his cousin Zungam, somewhere within Zul\'Aman.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11166 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11166,'zhTW','X標記……你的末日！','那群蠢貨究竟是如何失敗的？$B$B我一再囑咐他們要小心，要小心——為了幫助他們潛入祖阿曼，我甚至把我的地圖和偽裝都給了他們。$B$B啊，不過任何事總有好的一面，他們的失敗對你和你的朋友們來說是個機會。只要成功了，你們就可以名正言順地加入我的隊伍，和我一起分享即將到手的那些無盡的榮譽。並不是\\r\\n我貪心，只是讓你意識到這點而已。$B$B在我將最終的挖掘計劃準備妥當之前，我的地圖上還有幾塊區域需要更詳盡的探索……','進入祖阿曼並調查哈爾拉茲的大廳、加亞萊的平臺和埃基爾松的平臺。將這些地方的細節報告給巴德，他的營地就在鬼魂之地。','','去找鬼魂之地的巴德·奈德雷克。','調查哈爾拉茲的大廳','調查加亞萊的平臺','調查埃基爾松的平臺','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11167 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11167, 'zhTW', '[The New Plague]', '[Not long after Arthas condemned us to this wretched existence, we in the Royal Apothecary Society endeavored to create a plague of our own.  A plague that would devour all flesh: living, dead or undead.$B$BWe\'ve succeeded in creating this plague and we\'re here to hand deliver it to the Scourge\'s doorstep.$B$BThe Alliance intercepted the ship carrying the latest strain engineered in our Undercity laboratories.  Head to the wreckage southeast of here and salvage whatever containers you can.]', '[Apothecary Lysander at Vengeance Landing wants you to recover 10 Intact Plague Containers from the wrecked ship to the southeast.]', '', '去找嚎風峽灣的藥劑師黎珊達。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11168 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11168, 'zhTW', '[Spiking the Mix]', '[I\'ve a feeling the long trip across the sea is affecting the effectiveness of our plague.  What is needed is a potent toxin to boost the potency of the strain.$B$BThe crabs near this beach are a distant relative of the much smaller brown-shelled tidecrawler.  The smaller tropical variety produces a paralytic toxin strong enough to knock out an ogre.$B$BAs we all know bigger is better!  The much larger glands on the local variety should prove more potent.  Bring me a few!]', '[Bring 3 Giant Toxin Glands from Giant Tidecrawlers to Apothecary Lysander at Vengeance Landing in Howling Fjord.]', '', '去找嚎風峽灣的藥劑師黎珊達。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11169 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11169,'zhTW','恐怖圖騰的武器','我在上次恐怖圖騰進攻的時候受傷了，不過在受傷之前，我從敵人那裡奪取了一根奇怪的圖騰。$B$B那個東西在戰鬥中會發出讓人感到刺痛的魔法箭，不過我實驗了這麼久，還是想不出它是怎麼運作的。如果你願意幫我測試一下那圖騰的話，我很願意把它借給你。$B$B那些令人討厭的塵泥雜斑鱷魚把農場周圍的泥沼地當成了自己的家。相信我，你不會找不到它們的。儘量在圖騰附近和鱷魚戰鬥吧。','塔貝薩農場的學徒加里奧希望你在10頭塵泥雜斑鱷魚身上測試被捕獲的圖騰。','','去塵泥沼澤找塔貝薩的農場的學徒加里奧。','測試圖騰','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11170 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11170, 'zhTW', '[Test at Sea]', '[We\'ve just received word of reinforcements coming to the aid of the Alliance forces.  Their timing couldn\'t be better!$B$BWe\'re in sore need of test subjects and these North Fleet reservists will do nicely!$B$BTake these plague vials with you and speak to Camille, the Bat Handler.  Tell her you need to commandeer a riding bat for a special assignment for us.$B$BOnce you\'re at sea, drop the vials on the reinforcement fleet.  I can\'t wait to see the results!]', '[Speak to Bat Handler Camille and take a riding bat to intercept the Alliance reinforcements.  Once above their fleet, use the Plague Vials to infect 16 North Fleet reservists.]', '', '去找嚎風峽灣的藥劑師黎珊達。', '北方艦隊後備兵已感染', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11171 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11171,'zhTW','妖術領主？哈！','太棒啦！看來我很快就能進入祖阿曼了。$B$B$N，你表現得非常出色。我和同伴們談過了，他們對你的印象頗好喲。你馬上就能成為我們中的一份子啦。眼下，你還得完成一項任務——除掉妖術領主。$B$B這對你來說簡直是小菜一碟。只要你毫不畏懼地向他發動攻擊，這傢伙就會膽怯地轉身逃走。那些年老體衰的巨魔通常會給自己冠上可怕的頭銜，以此掩飾他們脆弱的本性，你明白嗎？','戰斧嶺的巴德·奈德雷克要你轉至祖阿曼，殺死妖術領主瑪拉卡斯。','','去找鬼魂之地的巴德·奈德雷克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11172 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11172,'zhTW','墜毀的飛艇','不久前，一艘地精飛艇墜毀在了東面。幾天前，一個熱砂集團的代表經過了這裡。$B$B她到處詢問著關於飛艇上的貨物和飛行員比吉爾的訊息，不過我們都沒有仔細檢視過墜毀現場。我懷疑她一個人能否清理墜毀現場，或者找回飛船運載的貨物。$B$B如果你有時間的話，就去比吉爾的飛艇殘骸，看看你有什麼可以幫到她的吧。飛艇殘骸就在這裡的東面，山脈的附近。','與比吉爾的飛艇殘骸處的莫希·斯蒂格里談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11173 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11173,'zhTW','沼澤中的毒藥','如果你指望學徒莫蘭恩去做些什麼的話，我想他所能做的也只有對著材料發牢騷了。$B$B我通常都是無視他，但根本不起作用。這次，我要試些不同的方法。$B$B如果我在他發現之前把缺少的材料放回去，也許他就能讓我安靜一會了。我們都要用到的最常用的材料是沼澤毒藥，那東西可以從農場北面沼澤的暗牙爬行者和毒性切割者身上得到。如果你能幫我弄來毒藥，我就可以在莫蘭恩發現前把它放回去。','將6瓶沼澤毒藥交給塔貝薩農場的學徒加里奧。','','去塵泥沼澤找塔貝薩的農場的學徒加里奧。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11174 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11174,'zhTW','阻止腐蝕','看看這個地方！到處都是軟泥怪，要是我不想點什麼辦法控制它們的話，它們就會腐蝕掉殘骸和飛艇的貨物！$B$B我不能空手回去，$c！在這些軟泥怪消化掉所有東西之前，幫我消滅它們吧！$B$B這臺裝置充電後可以將能量集中到這些軟泥怪身上，讓它們爆炸。飛艇的能量核心碎片應該可以給這臺裝置提供能量，靠近主墜毀點的那個始終可以正常工作，不過其它的時好時壞。','莫希·斯蒂格里希望你去溶解10只軟泥怪，然後回到比吉爾的飛艇殘骸旁向她覆命。','','去塵泥沼澤找比吉爾的飛艇殘骸的莫希·斯蒂格里。','溶解軟泥怪','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11175 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11175, 'zhTW', '', '', '[Old Man Stonemantle has asked you to find his daughter, Overseer Irena Stonemantle, at Steel Gate.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11176 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11176, 'zhTW', '', '', '[Explorer Irena Stonemantle has asked you to speak with a Steel Gate Chief Archaeologist at Steel Gate.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11177 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11177,'zhTW','水光莊園的隱士','這一帶有個獨自居住在沼澤中的人，附近的人們都把他叫作“沼澤之眼”加爾。不知幾時以前，總之是前幾任屬主神秘消失之後，他“接管”了水光莊園。$B$B我經常會派人去看看他。你要知道，他經常讓我回憶起我的祖父，你明白嗎？而且，有些人說他的腦袋已經不太清楚了。$B$B沿路向西北方向離開塞拉摩以後，你要進入女巫嶺一帶，然後很快就可以在路折向西方之前發現水光莊園。','與水光莊園的“沼澤之眼”加爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11178 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11178,'zhTW','督軍之血','當你觀察這隻瓶子時，你突然想起了祖阿曼外面那個狂妄的傢伙。$B$B你迫不及待地想要看到巴德的表情！','把祖爾金之血交給祖阿曼外面鬼魂之地的巴德。','','去找鬼魂之地的巴德·奈德雷克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11179 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11179,'zhTW','芬雷沒膽','是誰負責維修弩手們的武器？是我，Finlay Fletcher！$B$B我們的部隊計劃轉移到Fort Wildervaar，指揮官指派我協助處理所有準備事宜，搞得我沒時間外出收集製作弓弦所需的腸線了！$B$B好心的$C，幫我個忙好嗎？獵殺凜風峽灣的霧刃豹，從它們身上弄到完整的腸線！那些弄斷的腸子就算啦。','收集7個新鮮的霧刃豹腸線，然後回到西部衛戍要塞向芬雷·伏萊齊回報。','','去凜風峽灣找西部衛戍要塞的芬雷·箭羽。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11180 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11180,'zhTW','女巫嶺的幽靈','我長途跋涉來到這裡拜訪加爾的新家，但無盡的恐懼一直在籠罩著我！這裡肯定有什麼東西有問題，並不是只有我的感覺有問題而已……$B$B你看到那些在女巫嶺附近遊蕩的鬼魂和屍體了嗎？如果說有人會知道這裡曾經發生過了什麼，我想也只有他們了。在這附近尋找復活的軀殼和復活的遊魂，打敗他們，讓他們安靜下來，在這些惡魔吞噬掉加爾之前，看看你能從他們身上瞭解到什麼！','水光莊園的摩丹特·格雷斯比希望你能從10個復活的軀殼或復活的遊魂身上收集到資訊。','','去塵泥沼澤找水光莊園的摩丹特·格雷斯比。','收集資訊','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11181 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11181,'zhTW','除巫草','在我身為草藥師的這麼多年裡，我觀察到大自然可以為大部分煩人的問題提供完美的解決方案。我曾經讀到流浪法師和巫醫經常使用一種被稱為“除巫草”的草藥，它的煙能將惡魔從隱藏的暗處吸引出來。$B$B如果這是真的，那麼除巫草應該就生長在女巫嶺的淺水附近。它有著闊葉和紅色莖稈，你應該很容易就能分辨出來。把你能找到的藥草都帶回來給我吧，$N。它可能是我們唯一的希望了。','將9根除巫草交給水光莊園的摩丹特·格雷斯比。','','去塵泥沼澤找水光莊園的摩丹特·格雷斯比。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11182 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11182, 'zhTW', '[Root Causes]', '[All things in nature seek a balance. It is only through the interference of those not in tune with that harmony that the balance is shifted.$B$BYou waste your efforts when you kill the whelps and drakes. The real culprits behind the expansion of these magically burning woods are the newly awakened vrykul and their master, Skeld Drakeson.$B$BIf it\'s blood on your hands that you seek, start with them. You will find their lair on the south side of the Ember Clutch.]', '[Slay 5 Dragonflayer Handlers and Skeld Drakeson.  If you manage to do so, return to an Ember Clutch Ancient in the Ember Clutch.]', '', '去找嚎風峽灣的餘燼窩巢古樹。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11183 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11183,'zhTW','淨化女巫嶺','火把已經準備好了。把它插在碼頭的盡頭，對可能出現的一切情況做好準備吧。$B$B我不知道火把的濃煙會帶來什麼……如果真的有東西出現的話。我必須說，我對這種民間魔法是有所懷疑的，但現在我們也沒有時間來想其它辦法了。看在你和加爾的份上，祝你好運。','水光莊園的摩丹特·格雷斯比希望你將火把放置在碼頭的盡頭，並打敗隨後出現的任何東西。','','去塵泥沼澤找水光莊園的摩丹特·格雷斯比。','淨化女巫嶺','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11184 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11184,'zhTW','懸賞：貪婪的血爪','旅行者以及從事野外作業的熱砂港僱員請注意，不要靠近城鎮西邊的鮮血沼澤墓穴。$B$B大群迅猛龍盤踞在那片區域，它們的首領“貪婪的血爪”既殘忍又狡猾，至少有兩名熱砂港工程師慘死於這隻野獸的利爪之下。$B$B如果誰能替泥鏈鎮解除威脅，德拉茲特·迪普瓦爾願意慷慨解囊，獎賞這位勇士。','殺死貪婪的血爪，然後向泥鏈鎮的德拉茲特·迪普瓦爾覆命。','','去塵泥沼澤找泥鏈鎮的德拉茲特·迪普瓦爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11185 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11185,'zhTW','藥劑師的信','這封信是從一個被遺忘者鍊金師的屍體上得到的，信的內容顯示了恐怖圖騰和洛丹倫新主人之間關係密切的證據。$B$B“作為善意的表示和我們新建立的信任的標誌，我們派出了鍊金師塞爾拉，幫助你們與卡利姆多大陸上的那些我們共同的敵人作戰。沒有人可以打敗我們聯合的力量和決心。”$B$B這封信應該會引起塔貝薩農場那位軍情七處密探安德羅·波特的注意。','將密封的信函交給塔貝薩農場中的安德羅·波特。','','去塵泥沼澤找泥潭沼澤的安德羅·波特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11186 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11186,'zhTW','背叛的端倪？','這封信是從一個被遺忘者鍊金師的屍體上找到的，信的內容暗示了恐怖圖騰和幽暗城之間的秘密聯絡。$B$B“作為善意的表示和我們新建立的信任的標誌，我們派出了鍊金師塞爾拉幫助你們在卡利姆多與我們共同的敵人作戰。沒有人能打敗我們聯合的力量和決心。”$B$B也許蕨牆村的納澤爾·血矛知道該怎麼處理這種資訊。','將密封的信函交給蕨牆村的納澤爾·血矛。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11187 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11187, 'zhTW', '', '', '[Captain Adams has asked you to speak with his advisor, Mage-Lieutenant Malister, at Westguard Keep.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11188 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11188, 'zhTW', '[Two Wrongs...]', '[Now that we\'ve riled up these Ember Clutch proto-drakes, they may be inclined to continue their attacks upon the keep. This will not do.$B$BI hate to compound one wrong with another, but in this case it would appear that we will have to destroy the creatures. A regrettable course of action, but one that we need to undertake regardless.$B$BTake my wand. I\'ve been experimenting with increasing its range, but it doesn\'t pack much of a punch. However, what it will do is get a proto-drake\'s attention.]', '[Mage-Lieutenant Malister at Westguard Keep has tasked you with the destruction of 3 Proto-Drakes.]', '', '去找嚎風峽灣的法師中尉瑪歷斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11189 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11189,'zhTW','最後一次','你好啊，我死了嗎？我想我應該是死了，因為我飄在我身體上！$B$B喔，這真是倒楣的一件事。我原本正打算向艾琳娜求婚的時候，天災軍團卻來突襲。$B$B我知道她還活著…我可以在心中感應到她。$B$B你有辦法把我帶到她身邊嗎？那些天災軍依舊看得到我的鬼魂，恐怕會對我做一些很可怕的事情。$B$B我想要最後再看一次她漂亮的臉龐。你可以轉告她我愛她。','護送探險者賈倫的鬼魂安全地送到探險者艾琳娜·石衣身邊，她就在凜風峽灣的鋼鐵之門。','安全護送探險者賈倫的鬼魂到探險者艾琳娜·石衣','去凜風峽灣找鋼鐵之門的工頭伊蕾娜·石衣。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11190 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11190, 'zhTW', '[One Size Does Not Fit All]', '[$G小夥子：小姑娘;, who\'s the genius that made our cannons a non-standard size? Now we have ta make special cannonballs ta shoot out o\' the infernal contraptions!$B$BI would look kindly on ye if ye would go out and find the balls we\'ve already shot. No doubt with the way these louts shoot they be all o\'er the place ta the south and east.$B$B<The cannoneer spaces his hands apart to give you an idea of how big the cannonballs are.>$B$BThat would be faster than us making \'em from scratch fer a certainty.]', '[Cannoneer Ely has tasked you with rounding up 10 Westguard Cannonballs and returning them to him at Westguard Keep.]', '', '去找嚎風峽灣的砲手伊利。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11191 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11191,'zhTW','破舊的燈塔','東邊的燈塔已經壞掉許多年了，但巴布·菲茲托克一直在想方設法讓它重新開始正常工作。$B$B我不知道她自己的詳細計劃和想法，但這畢竟可以使船隻進出港口更加便捷順利，也能增快貨物的航運，所以我無法拒絕她。說實話，比起上戰場，在港口服務真可以說是一件完全沒什麼可以抱怨的工作了。','與塞拉摩東邊島上燈塔裡的巴布·菲茲托克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11192 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11192,'zhTW','蛇頸魚油','燈塔裡古老的航海日誌上記載著，可以用生活在這附近海岸的蛇頸龍的油作為燃料。$B$B<巴布在提起這種過時的技術時皺了一下鼻子。>$B$B我想這會有用的，雖然只能算是個土辦法。日誌上還寫著，最年幼的黑色蛇頸龍是最好的選擇，而那些傢伙就生活在塞拉摩的碼頭下面。$B$B如果你要去那裡的話，能幫我弄點燈塔所需的燃料嗎？','將4瓶蛇頸龍油交給塞拉摩附近燈塔的巴布·菲茲托克。','','去塵泥沼澤塞拉摩島找巴布·菲茲托克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11193 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11193,'zhTW','深海中的卑鄙生物','要知道，能在這座古老的燈塔裡面找到這東西實在是太棒了。在我點亮了燈以後，我發現某個古老的箱子裡有本書。$B$B<巴布拿起書，激動地讀著書名。>$B$B《深海中的卑鄙生物》！$B$B啊，我想若是有幸看到裡面所說的生物，我可能會笑得昏過去！我相信這本書實在很搞笑，不過現在我完全沒時間去讀它。$B$B你知道誰會感興趣，就是那個碼頭上的魚商，“髒鬼”邁克爾·克羅維。他收藏古老的書籍。','將《深海中的卑鄙生物》交給塞拉摩碼頭上的“髒鬼”邁克爾·克羅維。','','去塵泥沼澤找塞拉摩島的“髒鬼”邁克爾·克羅維。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11194 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11194,'zhTW','這是真的嗎？','哦，我相信你和巴布肯定覺得這本書中的奇異描述和草圖很可笑，但是你有沒有想過，那可能是一些傳說的真相？$B$B如果你聽得足夠仔細，我想你仍然可以聽到水手們談論起泰瑟爾，書上所記載的生活在這裡的海洋生物！當然，如果你真的想知道更詳細的情況，可以去問問老納特·帕格。$B$B他在狂潮灣的小島上有個釣魚營地，就在塵泥海灣的西南。','轉至狂潮灣的納特的碼頭，與納特·帕格談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11195 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11195,'zhTW','破爛的巫毒人偶','我太感動了，$n，居然是真的。我都不記得上一次有$r幫助蘇加姆走出困境是什麼時候了。$B$B這個是我從一個忙著鎖住我的野蠻人身上弄來的，看上去並不值多少錢，但是如果說有人可以確定它的價值，我想就只有我的好朋友格里伏塔了！$B$B如果你能成功活著離開這裡，不如把這個交給他看看。','將破爛的巫毒人偶交給撒塔斯城的格里伏塔。','','去找撒塔斯城的格里伏塔。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11196 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11196,'zhTW','失蹤的巨魔','聽著，朋友，普雷蒙還有件事需要你幫忙，我那個沒用的表兄被困在了祖阿曼裡。不過他還活著——就在昨晚，我還看到了他的訊號彈！$B$B他給我帶來了這麼多麻煩，我真應該就這麼讓他在裡面爛掉。不過話說回來，他還欠我一大筆錢。$B$B儘量幫他一把，把他欠我的錢給我拿回來！','普雷蒙希望你深入祖阿曼，找到並幫助他的表兄蘇加姆。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11197 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11197,'zhTW','雷酒的秘密ZZOLD Upper Deck Promo - Ghost Wolf Mount OLD','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11198 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11198,'zhTW','擊敗泰瑟爾！','不管海怪是不是真的存在，我們都不準備讓船隻去冒險。我已經命令最棒的神射手做好與泰瑟爾交戰的準備了。炮兵已經在碼頭增加了三門迫擊炮。如果泰瑟爾進攻的話，你的任務就是在那個怪獸殺害所有神射手之前，用迫擊炮打倒它。','塞拉摩碼頭的米爾斯少校希望你打敗泰瑟爾。','保衛塞拉摩港口不受泰瑟爾破壞','去塵泥沼澤找塞拉摩島的米爾斯少校。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11199 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11199, 'zhTW', '', '', '[Captain Adams has asked you to report to Scout Knowles at the Ember Spear Tower.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11200 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11200,'zhTW','絕非偶然','我們從旅店的廢墟里收集了儘可能多的線索。我不知道調查的結果到底是什麼，但我們必須知道真相。$B$B這些蹄印和有著莫薩恩記號的盾牌，讓我感覺到恐怖圖騰可能和這件事有關。他們最近在沼澤地裡建立了一個被稱作黑蹄村的定居點，就在這裡的東北方向。去黑蹄村尋找更多莫薩恩的武器製品吧。','蕨牆村的克羅格希望你去收集7份黑蹄軍備。','','去塵泥沼澤找蕨牆村的克羅格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11201 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11201,'zhTW','恐怖圖騰的密謀','隨著恐怖圖騰在千針石林的行動被揭露，現在很多牛頭人都對他們產生了懷疑。我們瞭解到恐怖圖騰的高階成員使用謀殺和綁架的手段來提升他們的影響裡，也許我們會變成他們的下一個目標。$B$B東北邊靠近藍色沼澤的黑蹄村是恐怖圖騰新的大型據點。他們的長者都按照從雷霆崖送來的命令列事。去看看你是否能截獲他們的命令書，把它們拼湊起來，瞭解恐怖圖騰的計劃。','把恐怖圖騰作戰計劃交給蕨牆村的克羅格。','','去找塵泥沼澤的克羅格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11202 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11202, 'zhTW', '[Mission: Eternal Flame]', '[The Forsaken are up to no good and from what I can tell, those plague tanks of sludge are a big part of it.$B$BIf I may suggest, $g先生：女士;, we should probably destroy them before they can get any more use out of the things. I took the liberty of preparing a bundle of torches from the Ember Clutch. These things have been burning for days!$B$BHere, I\'m sure you can put them to better use than I in destroying those tanks.]', '[Scout Knowles at the Ember Spear Tower has recommended that you use the Ever-burning Torches to destroy the four Plague Tanks surrounding Halgrind.]', '', '去找嚎風峽灣的斥候諾雷斯。', '西南方瘟疫戰車已摧毀', '西北方瘟疫戰車已摧毀', '東北方瘟疫戰車已摧毀', '東南方瘟疫戰車已摧毀', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11203 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11203,'zhTW','尋找塔貝薩','你在黑蹄村找到的武器似乎並未在實戰中使用過，只是用作練習器械而已，這意味著摧毀樹蔭旅店的恐怖圖騰部隊仍然逍遙法外。$B$B在南面，泥潭沼澤的中心，有一位名叫塔貝薩的女巫。儘管她是個人類，但是她很值得我們尊重，而且她還幫助我們訓練了一些法師。$B$B去尋求她的幫助，尋找那些焚燬旅店的恐怖圖騰部隊。一定不能讓聯盟覺得我們是和恐怖圖騰串通一氣的。','轉至泥潭沼澤的農場，與那裡的塔貝薩談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11204 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11204,'zhTW','向克羅格彙報','我希望可以幫助你，但我確實沒有更多的資訊可以告訴你了。我和我的學徒們製造了這麼多武器和裝備，根本不可能知道每件裝備到底都是誰在使用。$B$B我們不僅僅供貨給保衛牛頭人領地的勇士們，恐怖圖騰也對我的製品有著特別的首選。一個有經驗的戰士一看就知道什麼是好裝備。','與蕨牆村的克羅格談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11205 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11205,'zhTW','燒燬恐角崗哨！','根本沒有必要用水晶球來看看我們的新“鄰居”在幹些什麼。如果這就是焚燬樹蔭旅店的那支部隊，那麼我們也沒有理由再容忍他們的存在。$B$B拿上這根火把，將他們的營地夷為平地吧！你可以在我的農場略北一些的地方找到恐角崗哨。你不可能看不到，真的，因為恐怖圖騰在那裡豎著許多非常華麗的圖騰，以此表明他們對圖騰的喜愛。','燒燬恐角崗哨的北部帳篷、東部帳篷和東北部帳篷，然後回到塔貝薩的農場，向塔貝薩覆命。','','去塵泥沼澤找塔貝薩的農場的塔貝薩。','燒燬北部帳篷','燒燬東北部帳篷','燒燬東部帳篷','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11206 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11206,'zhTW','伸張正義','我不相信恐怖圖騰會放棄他們把人類趕出沼澤的行動。不過至少我們懲治了對樹蔭旅店下毒手的罪犯。$B$B我相信派你來的調查員也同意這一點：部落不能再如此放任恐怖圖騰的行為了。終有一天，他們的行動會讓部落處於一個尷尬的境地。$B$B不管是吉安娜女士還是索爾酋長都不希望捲入另一場戰爭，但他們是不是會努力去避免戰事的發生呢？','回到蕨牆村的克羅格那裡覆命。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11207 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11207,'zhTW','回收貨物！','這艘飛艇運送了足足6個月的補給品給我們的泥鏈鎮！當然，他們可以想辦法堅持一段時間，但他們沒法堅持太久。$B$B我被派到這裡來尋找任何我能找到的貨物，但飛船的殘骸支離破碎地散落在這塊區域。我確信有很多貨物沒能在墜毀中倖存下來，但你能幫我找到儘可能多的貨物嗎？','比吉爾的飛艇殘骸處的莫希·斯蒂格里要你找回8件飛艇上的貨物。','','去塵泥沼澤找比吉爾的飛艇殘骸的莫希·斯蒂格里。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11208 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11208,'zhTW','給德拉茲特的貨物','德拉茲特會很高興看到這些貨物的，不過我不覺得這地方已經被清理乾淨了，所以我還不能離開這裡。如果你有時間的話，你願意幫我把貨物送到泥鏈鎮去給他嗎？$B$B如果你還沒去過那裡，那我告訴你，那裡是石槌廢墟另一邊的一個小小的定居點。你也可以沿著塔貝薩的農場那邊的路過去。在你到達泥鏈鎮以後，你要做的事情就是找到德拉茲特·迪普瓦爾。','把飛艇上的貨物交給泥鏈鎮的德拉茲特·迪普瓦爾。','','去塵泥沼澤找泥鏈鎮的德拉茲特·迪普瓦爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11209 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11209,'zhTW','納特的交易','這麼說來你找到了一本《深海中的卑鄙生物》，是嗎？好吧，以我的經驗來看，一切都是真的。我甚至還親眼見過幾個。$B$B不過你真的想知道什麼是泰瑟爾嗎？這樣吧，我和你來做筆交易吧，我正在研製一種新的魚餌，但我還沒有機會來測試它。我希望你能幫我去測試一下。$B$B只要把這些魚肉醬——沒錯，它聞上去有點腐爛的味道——粘在你身上，然後游到西南方的那座破船周圍去。如果你能活下來的話，回來告訴我效果如何！','納特的碼頭上的納特·帕格想讓你去測試一下他的新魚餌。','','去塵泥沼澤找納特的碼頭的納特·帕格。','測試魚肉醬','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11210 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11210,'zhTW','果然是真的','是的，泰瑟爾真的存在，而且它就在塞拉摩附近的水域裡。$B$B它對亮光有著特別的愛好，這就是他們關閉燈塔的原因。$B$B如果你再次點亮燈塔的話，它馬上就會游回來。不過一個神智正常的人是不會這麼做的。$B$B啊哈！那肯定就是你的計劃了！很高興能和你喝兩杯，不過如果泰瑟爾真的把你變成了魚餌，不要抱怨老納特沒有提醒過你。如果你確定要這麼做的話，先去和塞拉摩港口的米爾斯少校商量一下吧。','與塞拉摩港口的米爾斯少校談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11211 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11211,'zhTW','幫助泥鏈鎮','在那個地精……她叫什麼名字來著……對了，莫希·斯蒂格里！總之，在她經過這裡轉至飛艇廢墟的時候，她說泥鏈鎮遇到了一些麻煩。$B$B那艘墜毀的飛艇本來是要把新鮮的補給帶給他們的。如果你沿著這條路往南走，越過石槌廢墟，泥鏈鎮就在你眼前了。$B$B你為什麼不去找那裡的德拉茲特·迪普瓦爾，看看他是否有什麼事情需要你的幫助？','與泥鏈鎮的德拉茲特·迪普瓦爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11212 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11212,'zhTW','塔貝薩的農莊','有一位老巫女塔貝薩居住在沼澤的深處。我們對她的瞭解也不多，只是她會偶爾出現在這裡，然後留下很長一串貨物訂單而已。她還經常幫助我們，並且在我們的軍隊與部落劍拔弩張時，她數次平息了可能發生的戰事。$B$B她過去一直和我們定期聯絡，最近卻一直沒有她的訊息了。$B$B如果你有空，是否能去看看她？你只需要一直沿著北點哨塔一側的道路前進就可以了，路會折向南方，然後進入泥潭沼澤。她的小農莊就在路旁。','與泥潭沼澤中的一處小農莊裡的塔貝薩談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11213 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11213,'zhTW','尋找塔貝薩','一個名叫塔貝薩的人類女性居住在靠近沼澤中央的小農場裡。一般情況下，我是不會和一個人類交往的，不過她的幫助確實對我們很有裨益。$B$B不幸的是，我們很久都沒有聯絡她了，而我正想找個人去她的農場看看是否一切都安然無恙。$B$B沿著南面的那條路離開村莊，在進入沼澤深處後，靠近泥潭沼澤中央的地方就是她的農場。','與泥潭沼澤農場裡的塔貝薩談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11214 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11214,'zhTW','轉至泥鏈鎮','熱砂集團最近在塵泥沼澤的南部建立了一座新的據點，叫作泥鏈鎮。如果我記沒錯，那麼它應該就在石槌廢墟和塔貝薩農莊的正南方。$B$B這對我們來說，是一個建立新貿易線路的機會，吉安娜女士也讓我派一名代表過去，與他們建立聯絡。你願意過去嗎？','與泥鏈鎮的德拉茲特·迪普瓦爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11215 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11215,'zhTW','幫助泥鏈鎮','熱砂集團在沼澤南部新建的哨站處境不是太好。給泥鏈鎮運送補給的飛艇墜毀了，使他們陷入了沒有重要工具、食物和藥品支援的窘迫處境。$B$B沿著路向南走，走進沼澤的深處。經過塔貝薩的農場和石槌廢墟之後就可以到達泥鏈鎮，向那裡的領導者提供任何你可以提供的幫助吧。','與泥鏈鎮的德拉茲特·迪普瓦爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11216 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11216,'zhTW','大法師奧圖魯斯','我的導師讓我到這裡來尋求幫助，不過糟糕的是，我只被允許在貧民窟這裡活動，而且這裡的人看起來不像能幫得上忙的樣子。$B$B不過你不同，你更像是一位冒險者。如果你有興趣幫助我們的話，請到麥迪文過去的住所——卡拉贊之塔外面，與我的導師奧圖魯斯談談吧。$B$B與此同時，我得想辦法獲得進入城市其它部分的許可。據說我們以前的某個同事也在這裡。','與逆風小徑卡拉贊外的大法師奧圖魯斯談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11217 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11217,'zhTW','龍尾草','飛艇的墜毀延緩了補給品的到達，我們的藥品和繃帶都用完了。$B$B我們正在利用一切可以獲得的資源，不過這些蟲子、傷者和一切與我們為敵的傢伙都讓我們焦頭爛額，我快要堅持不下去了！我找到了一種草藥，可以治療傷口和緩解疼痛，但它也快要用完了。$B$B這種草藥被稱為龍尾草，它遍佈在村子東面的黑龍谷和巨龍沼澤地區。那種植物的莖杆是捲曲的，而且似乎會微微地跳動。','泥鏈鎮的吉茲克斯·格里古格希望你幫他收集8根龍尾草。','','去塵泥沼澤找泥鏈鎮的吉茲克斯·格里古格。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11218 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11218, 'zhTW', '[Danger! Explosives!]', '[$N, the captain\'s tasked me with a mission. I\'d like you to help.$B$BA bunch of my fellow Explorers\' League people went nuts digging up stuff in the Whisper Gulch just to the north. They\'re attacking anyone trying to get in!$B$BThe captain is only concerned with the ore for the keep. Lucky for us, I have just the thing to do the trick.$B$BGet in there, blow up the ore, and bring it back along with any gems you find. Running this place isn\'t cheap you know!$B$BI gotta warn you though, that ore is strange!]', '[Use Steelring\'s Foolproof Dynamite to collect 6 Whisper Gulch Ore Fragments and 18 Whisper Gulch Gems. Then return them to Sapper Steelring at Westguard Keep.]', '', '去找嚎風峽灣的賽波‧鋼環。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11219 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11219, 'zhTW', '[Stop the Fires!]', '[The Horde\'s children need you, $n.  The Headless Horseman, once a human paladin and now an insane fiend, has set fire to our village!  You must put out those fires!$B$BGrab a bucket and throw it onto the blaze, or toss it to an ally who is closer to the flames.  Extinguish all the fires and thwart the Headless Horseman!]', '[The Masked Orphan Matron wants you to help put out all the village fires.  When they are out, speak again to the Masked Orphan Matron in town.]', '撲滅火勢', '去找戴面具的孤兒監護員。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11220 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11220, 'zhTW', '', '', '此任務已經絕版。[Find the Headless Horseman\'s Pumpkin Shrine.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11221 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11221, 'zhTW', '[Reports from the Field]', '[Our mission in Northrend is to destroy Arthas.  The Alliance are but an obstacle that we\'ll crush wherever we find them.$B$BWe\'ve managed to destroy their easternmost fleet; but the survivors have barricaded themselves on the Derelict Strand, south of here.$B$BOur forces should\'ve overwhelmed their make-shift defenses long ago, but we underestimated their will to live.  Seek my officers in the field, Dark Ranger Lyana and Deathstalker Razael and get them to report on the situation.]', '[Speak to Dark Ranger Lyana and Deathstalker Razael in the battlefield at the Bleeding Vale south of Vengeance Landing.  Return to High Executor Anselm when you\'ve completed this task.]', '', '去找嚎風峽灣的高階執行官安賽姆。', '聆聽拉薩爾的回報', '聆聽萊亞娜的回報', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11222 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11222,'zhTW','叛變的證據','雖然奧妮克希亞的身份已經暴露，也已經被驅逐出皇家議會，但是遵照她的命令列事的迪菲亞盜賊必須得到應有的懲罰。去告訴暴風城要塞中的瓦里安·烏瑞恩國王，就是這些迪菲亞盜賊綁架了他。我敢說，他一定會以乾淨利落的手段裁決迪菲亞盜賊。$B$B我可以用魔法幫助你回到暴風城，準備好之後就告訴我，$N。','與暴風城要塞的瓦里安·烏瑞恩國王談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11223 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11223,'zhTW','返回吉安娜身邊','我得制定一個剿滅迪菲亞盜賊餘孽的計劃。請你回到塞拉摩，轉達我對吉安娜女士的謝意。一直以來，她都是我們忠誠的夥伴和堅定的盟友。$B$B你可以去城西法師區的法師塔下尋找大法師馬林，他可以用法術迅速將你送回塞拉摩。','與塞拉摩的吉安娜·普羅德摩爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11224 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11224, 'zhTW', '[Send Them Packing]', '[I\'ve heard rumors of bad happenings in the Whisper Gulch to the north. Most of the Explorers\' League went down into that place, and some say they went mad with what they discovered.$B$BThat doesn\'t change the fact that they took most of our mules and equipment with them, though. I won\'t lose those mules!$B$BIf you find yourself in there, and happen across any of my mules, just get up close on them and threaten them with a raised hand. They\'ll spook and come home for sure.]', '[Explorer Abigail has asked you to /raise your hand at 10 Abandoned Pack Mules and then return to her at Westguard Keep.]', '', '去找嚎風峽灣的探險者艾比蓋兒。', '遺棄的騾子已被趕走', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11225 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11225,'zhTW','女巫嶺的隱士','沼澤似乎對人類似乎有某種奇怪的效果。有人只是因為住在這裡就發瘋了。$B$B任何居住在水光莊園的人都以一種驚人的方式發瘋了，它最新的主人“沼澤之眼”加爾已經表現出了一定的跡象。$B$B我不是完全清楚那裡到底有些什麼，如果你去檢視一下的話，我會對你表示真摯的感謝。$B$B莊園就在沼澤的東部邊界，向東穿過藍色沼澤和北點哨塔，莊園就在那座鬧鬼的女巫嶺上。','與水光莊園的“沼澤之眼”加爾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11226 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11226,'zhTW','幽靈虎坐騎','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11227 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11227, 'zhTW', '[Let Them Eat Crow]', '[The high executor wants me to use my dogs to sniff out enemy scouts, but I can tell you right now these plaguehounds aren\'t going anywhere until they\'re properly fed.$B$BIf our military doesn\'t understand that these beasts are picky enough to not eat the rubbish they\'ve given me, then they can\'t expect them to be of any use in the field.$B$BYou seem to have some time on your hands, why don\'t you take one of these dogs out hunting for crows out west?  Their meat isn\'t very tasty to us, but my boys love it!]', '[Pontius, the kennel keeper at Vengeance Landing, wants you to use the Plaguehound Cage to summon a Hungry Plaguehound and feed it Crow Meat from Fjord Crows west of Vengeance Landing.]', '', '去找嚎風峽灣的龐提烏斯。', '已餵食瘟疫獵犬', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11228 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11228, 'zhTW', '', '', '[Speak with Vice Admiral Keller at Valgarde Port.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11229 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11229, 'zhTW', '', '', '[Speak to Bat Handler Camille at Vengeance Landing and obtain passage to the Windrunner. Report to Captain Harker aboard the ship.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11230 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11230, 'zhTW', '[Ambushed!]', '[This should have been a walk in the park.  Their forces are hungry, injured and ill equipped.  Yet somehow, we walked right into their trap.$B$BWe approached these reefs from the south to gain cover and were immediately boarded by the Alliance dogs.$B$BI\'m sorry to say, if you want our cannons to fire at anything, you\'re going to have to help us take our ships back.]', '[Captain Harker aboard the Windrunner wants you to kill 15 North Fleet Marines.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11231 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11231, 'zhTW', '[Of Keys and Cages]', '[The captain may not care, but from the little we know, the vrykul are conducting heinous rites in some sort of \'awakening\' ritual up north in Gjalerbron.$B$BThey\'re using living sacrifices to fuel their unholy rituals!$B$B$C, you must put a stop to this! It matters not who or what is in those cages, they must be freed. I\'d bet that the vrykul hold the keys.$B$BThe Light knows the last thing we need is more of those strange vrykul walking about, or worse yet, them wakening something even more evil!]', '[Father Levariol has asked you to collect enough Gjalerbron Cage Keys to free 10 Gjalerbron Prisoners. Return to him at Westguard Keep when you manage to do so.]', '', '去找嚎風峽灣的雷瓦瑞爾神父。', '傑拉布倫的囚犯已釋放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11232 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11232, 'zhTW', '[Guide Our Sights]', '[We should be able to kill our way back to our guns.  Unfortunately, visibility is less than desirable so you will have to mark our targets from the ground.$B$BTake these smoke flares with you and use them to mark the locations of the cannons along the northern wall in the Derelict Strand, west of here, where the Alliance are holding out.$B$BLet Lyana know as soon as the way is clear for the ground troops.  We can take care of ourselves over here.]', '[Use the Smoke Flares at the location of the Alliance Cannons on the northern wall of the Derelict Strand.  Report to Dark Ranger Lyana at the Bleeding Vale after you\'ve completed this task.]', '', '去找嚎風峽灣的黑暗遊俠利雅娜。', '東方火砲已標記', '西方火砲已標記', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11233 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11233, 'zhTW', '[Landing the Killing Blow]', '[You\'ve proven yourself in the field of battle, $N.  You might very well have changed the tides in our favor.$B$BI\'ve an important assignment for you now.  I\'m not sure how much longer the weakness we\'ve exposed is going to last, so we must use the element of surprise to our advantage.$B$BI want you to use the confusion created by our attack and go behind enemy lines to assassinate their leaders.  In order of rank, they are: Captain Olster, Lieutenant Celeyne and Sergeant Lorric.  Good luck, $c.]', '[Dark Ranger Lyana south of the Vengeance Landing wants you to kill Captain Olster, Lieutenant Celeyne, and Sergeant Lorric at the Derelict Strand.]', '', '去找嚎風峽灣的黑暗遊俠利雅娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11234 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11234, 'zhTW', '', '', '[Report back to High Executor Anselm at Vengeance Landing in Howling Fjord.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11235 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11235, 'zhTW', '[Dealing With Gjalerbron]', '[And now we have a different problem. My scouts that have lived to return have informed me that the vrykul are up to no good at their main fortress to the north.$B$BThey call the place Gjalerbron, though you\'d pronounce the \'Gj\' as if it were an \'Sh\'. Odd creatures.$B$BBut that\'s not important; what is, is that you get up there and put an end to the lives of as many of those creatures as you can while trying to figure out what they\'re up to.$B$BI know that I can count on you, $N.]', '[Captain Adams has asked you to kill 15 Gjalerbron Warriors, 8 Gjalerbron Rune-casters, and 8 Gjalerbron Sleep-watchers. Afterward, return to him at Westguard Keep.]', '', '去找嚎風峽灣的亞當斯隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11236 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11236, 'zhTW', '[Necro Overlord Mezhen]', '[The Scourge are at Gjalerbron and they have necromancers with them! They must be working to bring the vrykul into Arthas\' fold.$B$BI want the leader of these necrolords eliminated!$B$BDo whatever it takes, $N, but see to it that Necro Overlord Mezhen, and whatever he\'s attempting to accomplish, is neutralized.$B$BI will not see the vrykul successfully allied with the Scourge!$B$BLook for Mezhen on the platform in the rear right section of Gjalerbron.]', '[Kill Necro Overlord Mezhen. Then, return to Captain Adams at Westguard Keep.]', '', '去找嚎風峽灣的亞當斯隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11237 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11237, 'zhTW', '[Gjalerbron Attack Plans]', '[These plans detail an imminent attack upon Westguard Keep. It would appear that the frost wyrm, Glacion, who circles overhead is to be used for the offensive.$B$BSurely Mage-Lieutenant Malister would be of some assistance in this matter. Deliver the plans to him at the keep to the south.]', '[Deliver the Gjalerbron Attack Plans to Mage-Lieutenant Malister at Westguard Keep.]', '', '去找嚎風峽灣的法師中尉瑪歷斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11238 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11238, 'zhTW', '[The Frost Wyrm and its Master]', '[You were right to bring this to me, $N. You must take help back north with you to Gjalerbron and slay that wyrm and its master, Wyrmcaller Vile!$B$BEven now, as we speak here, the frost wyrm may be on its way.$B$BHowever, if I\'m reading these plans correctly, blowing the wyrmcaller\'s horn on his platform, outside in the rear left area of Gjalerbron, will call Glacion back. When the creature lands, destroy it!$B$BAnd $N, please bring me the horn. We wouldn\'t want it falling back into the wrong hands.]', '[Slay Wyrmcaller Vile and use the Wyrmcaller\'s Horn to call down and slay Glacion. Then, return with the horn to Mage-Lieutenant Malister at Westguard Keep.]', '', '去找嚎風峽灣的法師中尉瑪歷斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11239 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11239, 'zhTW', '[In Service to the Light]', '[Your service has been exemplary, $N, but there is something that is troubling me: the Scourge.$B$BThe Light cannot abide their presence, and neither shall we. I hope that it is not asking you too much, but I would have you return north to Gjalerbron and crush the unholy Scourge in that vile lair! Be sure to check for them in the Waking Halls beneath Gjalerbron as well.$B$BPurification is the key to salvation, my child. Make us proud!]', '[Slay 10 Deathless Watchers, 4 Fearsome Horrors, and 2 Putrid Wights. Afterward, inform Father Levariol at Westguard Keep of your success.]', '', '去找嚎風峽灣的雷瓦瑞爾神父。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11240 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11240, 'zhTW', '[Leader of the Deranged]', '[So, I hate to say it, pal, but while you were out, the captain took a keener interest in that place.$B$BLooks like he wants my old Explorers\' League boss in there dead. My guess would be that we\'re gearing up for an offensive to clear out the rest of them, and the captain wants their head lopped off, as it were.$B$BDo me a favor? Head back into Whisper Gulch and put an end to Squeeg Idolhunter. From what I remember, my guess would be that he\'s in the cave in the northwest corner.]', '[Slay Squeeg Idolhunter and then report back to Sapper Steelring at Westguard Keep.]', '', '去找嚎風峽灣的賽波‧鋼環。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11241 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11241, 'zhTW', '[Trail of Fire]', '[Thanks for bailing me out of this mess, $N.  I was not looking forward to what these Alliance scumbags had in store for me.$B$BLet\'s get out of here and see if we can get back at them somehow.  Is that a campfire over there?]', '[Escort Apothecary Hanes out of the Derelict Strand.  Report to Apothecary Lysander at Vengeance Landing in Howling Fjord when you\'ve completed this task.]', '營救藥劑師哈尼斯', '去找嚎風峽灣的藥劑師黎珊達。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11242 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11242, 'zhTW', '[Free at Last!]', '[Rage was my prison, $N, and you have freed me.  Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth.$B$BThank you for leading me back to the Light.  May I never again lose my way.$B$BTake this torn prayer book to an orphan matron, so the children may know that I will haunt them no more.]', '[Take the Tome of Thomas Thomson to the Costumed Orphan Matron in Goldshire, Kharanos or Azure Watch.]', '', '去找變裝的孤兒監護員。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11243 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11243, 'zhTW', '[If Valgarde Falls...]', '[If Valgarde falls, our primary supply line into Northrend will cease to exist. From there it\'ll only be a matter of time before we\'re all servants of the Lich King. Now I don\'t know about you, but I\'ve got a wife and three kids back in Elwynn and I\'ll be damned if I\'ll go down without a fight.$B$BThe situation here is critical and we can use all the manpower you\'re able to muster. Get to the front gate and help the guards defend the city against the invading monsters!]', '[Vice Admiral Keller at Valgarde Port in the Howling Fjord wants you to slay 12 Dragonflayer Invaders or Dragonflayer Worgs.$B$B]', '', '去找嚎風峽灣的海軍中將凱勒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11244 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11244, 'zhTW', '[Rescuing the Rescuers]', '[We\'d been here for a month when those malformed giants appeared out of thin air. We were ill-prepared for any sort of attack and paid dearly for our complacency. An entire archaeology team was lost and several townsfolk were abducted and taken to the ruins. We\'ve been on the defensive ever since.$B$BTo make matters worse, the scouts we sent to rescue our people have been harpooned by the vrykul and left for dead in the forest directly north of Valgarde. Dislodge those harpoons and free our scouts!$B$B]', '[Vice Admiral Keller at Valgarde Port in the Howling Fjord wants you to rescue 8 Valgarde Scouts that have been impaled and left for dead.]', '', '去找嚎風峽灣的海軍中將凱勒。', '已救出瓦爾加德偵察兵', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11245 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11245,'zhTW','危險的塔樓','$G先生:女士，如果我們想要透過斯克恩，就必須清除那些塔樓！$B$B如果您注意過那些塔樓，就會發現樓頂上站滿了施法者。太靠近它們的話，我們都會完蛋的！$B$B但我們已經從西部衛戍要塞請求了火力支援。為了準確地摧毀那些塔樓，我們要儘量靠近它們，然後放出定位的煙幕彈。$B$B別靠得太近就行了！','西部衛戍軍士要你轉至斯克恩，利用軍士的煙幕彈標記四座塔樓的位置，供炮擊定位用。','','去找西部衛戍軍士。如果西部衛戍軍士不在附近那麼請使用你的西部衛戍令牌。','標記西北塔樓','標記東部塔樓','標記西南塔樓','標記東南塔樓',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11246 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11246,'zhTW','可怕而必要的手段','我們得到報告說，這些維庫人會死而復生。他們和天災軍團不一樣，是另一種形式的不死生物。$B$B我們不能冒這個險。$B$B來，拿著我的刀。當我們穿過這個地區的時候，你要用它確保那些被我們打倒的維庫人不會再突然跳起來。這本該是我的工作，可惜我的胃比較脆弱。$B$B<中士幸災樂禍地笑了笑。>$B$B這把刀我已經磨了一上午了，肯定非常好用。','西部衛戍軍士要你轉至斯克恩，利用軍士的彎刀確保20個斯克恩部族的維庫人無法復活。','','去找西部衛戍軍士。如果西部衛戍軍士不在附近那麼請使用你的西部衛戍令牌。','確保斯克恩的維庫人不再復活','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11247 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11247,'zhTW','燃燒吧，斯克恩，燃燒吧！','亞當斯上尉曾經嚴令我必須重點打擊此地的基礎設施。$B$B但既然現在這裡由您負責，那您可以酌情處理。$B$B我建議我們是否可以去燒燬斯克恩窪地裡的那兩座長屋和兵營？我們只需要進入這些建築內部，然後把這根火炬扔進去就行了。','西部衛戍軍士要你轉至斯克恩，利用軍士的火炬燒燬東北方的長屋、西北方的長屋以及兵營。','','去找西部衛戍軍士。如果西部衛戍軍士不在附近那麼請使用你的西部衛戍令牌。','點燃西北方的長屋','點燃東北方的長屋','點燃兵營','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11248 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11248, 'zhTW', '[Operation: Skornful Wrath]', '[$N, I must now ask you to undertake an operation so hazardous, so deadly, that only you can see it through.$B$BThe vrykul fortress, Skorn, sits on our eastern border. My scouts inform me that those \'giants\' are poised to strike us, and with my forces scattered all over the fjord, I don\'t have the men to take the place by force.$B$BInstead, you\'re going to use your cunning. I\'ve sent a sergeant ahead with the details. Show this command insignia at Skorn and he\'ll reveal himself and follow your orders.]', '[Captain Adams has asked you to use the Westguard Command Insignia at Skorn, and then to speak with the Westguard Sergeant.]$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11249 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11249,'zhTW','阻止昇華！','這張巨大的卷軸是用龍皮製作的。展開這張長達十尺的卷軸之後，你看到覆蓋著鱗片的卷軸上畫著一副維庫人的神秘儀式的場景。$B$B一個維庫領主，在一群天使形象的生物的環繞中，正緩緩升入天堂。而這副圖的後臺，則是一個神秘而巨大的黑影。$B$B你突然意識到，這就是斯克恩的領主正要去做的事。你必須阻止他！在斯克恩的頂層，領主的房間外已經堆好了一大捆木柴。','在領主的火堆附近展開維庫昇華卷軸，召喚出維庫領主並殺死他。完成以後，鑑於這種儀式的性質，你確信西部衛戍要塞裡的萊瓦里安神父會對這張卷軸感興趣。','','去凜風峽灣找西部衛戍要塞的萊瓦里安神父。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11250 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11250, 'zhTW', '[All Hail the Conqueror of Skorn!]', '[We -- well, you -- have done everything that we were sent here to accomplish $g先生：女士;. I must say that it\'s been a pleasure taking orders from such a fine, young $r.$B$BThe captain is sure to want to hear of your success, but if you decide to stay out here for whatever reason, I am at your disposal.]', '[Return the Westguard Command Insignia to Captain Adams at Westguard Keep.]', '', '去找嚎風峽灣的亞當斯隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11251 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11251, 'zhTW', '', '', '[Scout Valory wants you to investigate the sounds of battle coming from the northeast of Wyrmskull Village.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11252 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11252, 'zhTW', '[Into Utgarde!]', '[Listen up, youngster. I\'ve put down me share of these creatures - and your share too fer that matter. Here be what ya need to know....$B$BThe vrykul are fearless in a fight. Seems they actually yearn fer a death in battle. With their numbers and that ferocity, we\'re doomed - plain and simple.$B$BThere\'s one they esteem though, goes by the name of Ingvar. I dunno why they be seekin\' his praise, but bring him down and you\'ll deal a mighty blow to their spirit.$B$BThen, perhaps, we\'ll have a chance....]', '[Defender Mordun has tasked you with the execution of Ingvar the Plunderer who resides deep in Utgarde.$B$BYou are then to bring his head to Vice Admiral Keller.]', '', '去找嚎風峽灣的海軍中將凱勒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11253 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11253, 'zhTW', '[Sniff Out the Enemy]', '[Now that this rascal\'s belly\'s full, maybe he will be more willing to cooperate.  Here\'s his leash, just come get him from his cage whenever you\'re ready to take him.$B$BI don\'t know what Anselm expects you to find, but look for clues wherever it is that the dog takes you.]', '[Use the Plaguehound Leash near the plaguehound cages at Vengeance Landing and look for clues at the location you\'re led to by the Plaguehound Tracker.]$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11254 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11254, 'zhTW', '[The Dragonskin Map]', '[Upon closer inspection, the scroll appears to be a heavily-illustrated map of the fjord.  The location of various villages are depicted in what seem to be tribal symbols.$B$BThe location of Vengeance Landing is marked with a disproportionately large skull.$B$BThis map will almost certainly be of military value to High Executor Anselm.]', '[Bring the Dragonskin Map to High Executor Anselm in Vengeance Landing.]', '', '去找嚎風峽灣的高階執行官安賽姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11255 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11255, 'zhTW', '[Prisoners of Wyrmskull]', '[This battle is far from over, $N. If our people are still alive inside that village, someone has to go and get \'em.$B$B<Vice Admiral Keller nods at you.>$B$BHead north and enter Wyrmskull Village. Once there, look for our people. If they are imprisoned you\'ll need to find a way to break them out.$B$BMaybe they\'ll have some more information about what it is that we\'re actually fighting.]', '[Vice Admiral Keller at Valgarde Port in the Howling Fjord wants you to rescue 3 Captured Valgarde Prisoners.]', '', '去找嚎風峽灣的海軍中將凱勒。', '已救出瓦爾加德的俘虜', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11256 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11256, 'zhTW', '[Skorn Must Fall!]', '[$N, the vrykul fortress, Skorn, sits to the south. Its strange giants have recently awakened and have begun to spread, attacking us wherever they can.$B$BMy scouts inform me that they are poised to strike at us here, but I do not have the strength to repel such a force. Instead, we will prepare to leave north to less dangerous lands.$B$BI ask that you use your cunning to buy us time. I\'ve sent a brave ahead with the details. Show this emblem at Skorn and he\'ll reveal himself and do all he can to aid you.]', '[Chieftain Ashtotem has asked you to use the Winterhoof Emblem at Skorn, and then to speak with the Winterhoof Brave.]$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11257 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11257, 'zhTW', '[Gruesome, But Necessary]', '[Our elders say that these vrykul may be able to rise from the dead; not unlike the walking dead you call the Scourge, but a different kind of undeath.$B$BWe should not take any chances.$B$BHere, take my machete. As we move through this place, carve up the remains of the vrykul that we slay.$B$BI spent the morning sharpening it, so it should cleave even through their thick bones.]', '[The Winterhoof Brave has asked you to use The Brave\'s Machete to dismember 20 Vrykul of the Winterskorn tribe at Skorn.]', '', '', '寒冬扭曲維库人已肢解', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11258 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11258, 'zhTW', '[Burn Skorn, Burn!]', '[Chieftain Ashtotem ordered me to destroy many buildings here.$B$BHowever, you are in charge, so it falls to your hands, $N.$B$BI suggest that we burn down the two longhouses and the barracks that are in the lower area of Skorn. All we have to do is get inside each and set them ablaze with this torch.]', '[The Winterhoof Brave suggests that you use the Brave\'s Torch to set fire to the Northeast and Northwest Longhouses and the Barracks at Skorn.]', '', '', '西北方長屋已點燃', '東北方長屋已點燃', '軍營已點燃', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11259 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11259, 'zhTW', '[Towers of Certain Doom]', '[As we move through Skorn, we must destroy the towers.$B$BIf you have a look at them, you\'ll notice that their tops are lined with casters. Getting too close to them would mean certain doom.$B$BHowever, we can call in wind rider air strikes from Camp Winterhoof. To do so, we need to get close enough so that you can lob a smoke flare atop of them.$B$BJust don\'t get too close.]', '[The Winterhoof Brave has informed you that using the Brave\'s Flare to target all four of the towers at Skorn for air strikes would be advisable.]', '', '', '西北方塔樓已標記', '東方塔樓已標記', '西南方塔樓已標記', '東南方塔樓已標記', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11260 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11260, 'zhTW', '[Stop the Ascension!]', '[This huge scroll is made from dragon skin. Unfurling its more-than-ten-foot length, you can see that the images painted upon its scaly surface depict a mysterious vrykul ritual.$B$BA vrykul thane, surrounded by angelic-looking beings, ascends into the heavens. A mysterious, darkened figure looms large in the picture\'s background.$B$BA tingling in your gut tells you that the thane of Skorn is about to do this. You must stop it! A large pyre sits at the top of Skorn in front of the thane\'s lodge.]', '[Present the Vrykul Scroll of Ascension near the Thane\'s Pyre to call him out and slay him. Afterward, due to the nature of the ritual, you\'re sure that Greatmother Ankha at Camp Winterhoof will be interested in seeing the scroll.]', '', '去找嚎風峽灣的主母安卡。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11261 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11261, 'zhTW', '[The Conqueror of Skorn!]', '[You have done everything that we were sent here to do, $c. I must admit that you fight well. Your people are not as strange as I first thought.$B$BChieftain Ashtotem is certain to want to hear of your success, but if you decide to stay out here for whatever reason, I will continue to fight at your side.]', '[Return the Winterhoof Token to Chieftain Ashtotem at Camp Winterhoof.]', '', '去找嚎風峽灣的灰燼圖騰酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11262 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11262, 'zhTW', '[Ingvar Must Die!]', '[Finally, someone\'s come. I\'ve been here far too long and my wits are beginning to fail me. Of our entire recon party, only I remain.$B$BI shall give you my report and it will be up to you to act upon the information. Know this, $c; it did not come cheaply.$B$BThese vrykul are relentless fighters. Given their numbers and their savage tactics, our only hope is to bring down their leader and pray it brings chaos to their ranks.$B$BIngvar is his name. Bring his head to Anselm when your duty is done.]', '[Dark Ranger Marrah has asked you to kill Ingvar the Plunderer in Utgarde Keep, then bring his head to High Executor Anselm at Vengeance Landing.]', '', '去找嚎風峽灣的高階執行官安賽姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11263 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11263, 'zhTW', '[Dealing With Gjalerbron]', '[My longrunners that have lived to return have informed me that the vrykul have awakened at their main fortress to the west.$B$BIt is a forbidden place known as Gjalerbron. The longrunners tell me that the vrykul are performing strange rituals.$B$BWe cannot allow this to continue.$B$BAre you willing to continue to assist us? Will you kill the vrykul at Gjalerbron before they finish whatever they are doing and attack us here?]', '[Chieftain Ashtotem has asked you to kill 15 Gjalerbron Warriors, 8 Gjalerbron Rune-casters, and 8 Gjalerbron Sleep-watchers. Afterward, return to him at Camp Winterhoof.]', '', '去找嚎風峽灣的灰燼圖騰酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11264 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11264, 'zhTW', '[Necro Overlord Mezhen]', '[The dead ones are at Gjalerbron and they have necromancers with them?$B$BWe must eliminate the leader of these necrolords.$B$BDo whatever it takes, $N, but see to it that Necro Overlord Mezhen, and whatever he\'s attempting to accomplish, is neutralized.$B$BWe cannot afford to see the vrykul successful in whatever they are doing with these undead creatures!$B$BLook for Mezhen on the platform in the rear right section of Gjalerbron.]', '[Kill Necro Overlord Mezhen. Then, return to Chieftain Ashtotem at Camp Winterhoof.]', '', '去找嚎風峽灣的灰燼圖騰酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11265 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11265, 'zhTW', '[Of Keys and Cages]', '[From the little we know, the vrykul are conducting unnatural rites in an \'awakening\' ritual to the west in Gjalerbron.$B$BThey\'re using living sacrifices to fuel their rituals.$B$B$N, you must stop this. It matters not who or what is in those cages, they must be freed. I would guess that the vrykul hold the keys.$B$BThe last thing we need is more of those strange vrykul threatening us, or worse, them wakening something even more evil....]', '[Greatmother Ankha has asked you to collect enough Gjalerbron Cage Keys to free 10 Gjalerbron Prisoners. Return to her at Camp Winterhoof when you manage to do so.]', '', '去找嚎風峽灣的主母安卡。', '傑拉布倫的囚犯已釋放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11266 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11266, 'zhTW', '[Gjalerbron Attack Plans]', '[These plans detail an imminent attack upon Camp Winterhoof. It would appear that the frost wyrm, Glacion, who circles overhead, is to be used for the offensive.$B$BSurely Celea Frozenmane would be of some assistance in this matter. Deliver the plans to her at the camp to the east.]', '[Deliver the Gjalerbron Attack Plans to Celea Frozenmane at Camp Winterhoof.]', '', '去找嚎風峽灣的賽利亞‧冰鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11267 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11267, 'zhTW', '[The Frost Wyrm and its Master]', '[Your instincts were right to bring this to me, but my wind riders cannot fight a dragon. You must take help back west with you to Gjalerbron and slay the frost wyrm and its master, Wyrmcaller Vile!$B$BEven now it may be on its way!$B$BIf I\'m reading these plans correctly, blowing the wyrmcaller\'s horn on his platform, outside in the rear left area of Gjalerbron, will  call Glacion back. When the creature lands, destroy it!$B$BAnd $N, bring me the horn. We wouldn\'t want it falling back into the wrong hands!]', '[Slay Wyrmcaller Vile and use the Wyrmcaller\'s Horn to call down and slay Glacion. Then, return with the horn to Celea Frozenmane at Camp Winterhoof.]', '', '去找嚎風峽灣的賽利亞‧冰鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11268 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11268, 'zhTW', '[The Walking Dead]', '[Your assistance to us has been tremendous, $N, but there is something that is troubling me: these so-called Scourge.$B$BThe spirits of the land and air, the waters and the fire below the world, would not abide their presence, but seem to do nothing about them. We will see to it that they are dealt with!$B$BPerhaps it is asking too much, but I would have you return west to Gjalerbron and destroy the unnatural Scourge in that vile lair. Be sure to check in the Waking Halls below Gjalerbron as well!]', '[Slay 10 Deathless Watchers, 4 Fearsome Horrors, and 2 Putrid Wights. Afterward, inform Greatmother Ankha at Camp Winterhoof of your success.]', '', '去找嚎風峽灣的主母安卡。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11269 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11269, 'zhTW', '[Down to the Wire]', '[The vanguard of the Alliance force will be arriving within days. The soldiers will be expecting their winter gear to be prepared, but I\'ve still got more cloaks to make.$B$BI\'ve been using spotted hippogryph down for the cloaks\' linings, but my stock won\'t last!$B$BYou\'ve got to help me, $N. Captain Adams will have my hide if those cloaks aren\'t ready in time! Bring me all the down you can find out there. It\'s dropped to the ground by molting hippogryphs flying over the wilderness around the fort.]', '[Gil Grisert wants you to bring him 10 clumps of Spotted Hippogryph Down.]', '', '去找嚎風峽灣的吉爾‧葛瑞斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11270 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11270, 'zhTW', '[War is Hell]', '[We\'re slowly finishing off the remnants of Stormwind\'s North Fleet stationed on this coast.  The bodies to the west are a testament to how brutal this confrontation has been.$B$BThis does not happen to bother my refined aesthetics, but it does present a danger to our lives.$B$BIn the lands of the Lich King, the dead are a weapon that can rise against us at any point in time.  Take this torch - you\'re going to make sure that doesn\'t happen.]', '[High Executor Anselm at Vengeance Landing wants you to take the Burning Torch and use it to burn 10 of the corpses littered to the west of town.]', '', '去找嚎風峽灣的高階執行官安賽姆。', '陣亡戰士已焚燒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11271 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11271, 'zhTW', '[Hasty Preparations]', '[The down of the spotted hippogryph is prized by my people and used for everything from fletching to ceremonial clothing. We\'re making preparations to leave the post, so this is the last chance I\'ll get to gather it this season.$B$BWith your help, I\'ll have enough to make sure everyone has the equipment they need for the long trek into the hills. Conditions worsen very quickly up there and a storm can blow in without warning.$B$BThe down can be found all over the ground in the area surrounding the post.]', '[Ahota Whitefrost at Camp Winterhoof wants you to bring him 10 clumps of Spotted Hippogryph Down.]', '', '去找嚎風峽灣的阿喉塔‧白霜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11272 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11272, 'zhTW', '[A Score to Settle]', '[This elf prince thinks he can come to my town, insult my queen, kill my men and get away with it?  He thinks we\'re going to stand by while the hordes of Utgarde build up to launch an attack?$B$BNot in a million years.$B$BYou\'re going to walk right into Utgarde and kill him in front of any of these vrykul gorillas that might be watching.  I want Arthas to know that we\'ve arrived and we\'re playing for keeps.]', '[High Executor Anselm wants you to to go into Utgarde and slay Prince Keleseth.]', '', '去找嚎風峽灣的高階執行官安賽姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11273 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11273, 'zhTW', '', '', '[Search Wyrmskull Village for Pulroy.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11274 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11274, 'zhTW', '', '', '[Search Wyrmskull Village for Zedd.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11275 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11275, 'zhTW', '[Making the Horn]', '[My people have been hunting the giant yeti of these hills for generations and I will be participating for the first time this year. It will probably be the last before we leave the post forever.$B$BTo prepare for the hunt, I must fashion a loud horn from the horns of the dire rams that roam the snowy areas near our camp. The elders tell me the sound mimics the mating call of the female yeti, but I have my doubts.$B$BBring me the best dire ram horns you can find, $N, and I\'ll select one from among them.]', '[Nokoma Snowseer at Camp Winterhoof wants you to bring her 6 Undamaged Ram Horns.]', '', '去找嚎風峽灣的諾可瑪‧雪先知。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11276 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11276, 'zhTW', '', '', '[Search the Utgarde Catacombs for Glorenfeld.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11277 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11277, 'zhTW', '[The Depths of Depravity]', '[They\'re keepin\' Daegarn locked up in a cage at the large fightin\' ring nearby. From what I\'ve gathered, the Dragonflayers bring out their prisoners to battle against their most powerful gladiators. They dump the losers in the basement where Scourge necromancers turn \'em into ghoulies! It\'s horrifying!$B$BBut first things first! The tablets are strewn about all across this dungeon. Let\'s get those recovered before you go off tryin\' to be a hero.]', '[Glorenfeld at the Utgarde Catacombs wants you to collect 10 Wyrmskull Tablets.]', '', '去找嚎風峽灣的葛羅倫費德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11278 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11278, 'zhTW', '[Return to Valgarde]', '[\'Tis a shame we lost two of our best dwarves while uncovering these relics. They sacrificed their lives to keep this information safe.$B$B<Glorenfeld wraps the cipher and tablets in a tattered cloth.>$B$BTake these back to Valgarde. McSorf will know what to do with the find.$B$BAs for me? I\'ll be alright on my own. I\'ve gotten this far in one piece!]', '[Take Glorenfeld\'s Package to Beltrand McSorf at Valgarde Port.]', '', '去找嚎風峽灣的貝爾川·麥克索夫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11279 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11279, 'zhTW', '[Green Eggs and Whelps]', '[This new plague that we\'re working on is wonderful and I think we should expand its testing.$B$BHow about testing it on proto-whelps?!$B$BJust think of the possibilities. The ability to infect not only humanoids, but extend our reach to any creature!$B$BHere, I\'ve hoarded an extra plague canister for the right time and place, and you look like the right person.$B$BSpray the eggs at Ember Clutch to the northwest, then get specimens from the plagued proto-whelps that hatch.]', '[Plaguebringer Tillinghast has asked you to collect 10 Plagued Proto-Whelp Specimens and deliver them to him at New Agamand.]', '', '去找嚎風峽灣的瘟疫使者提林加斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11280 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11280, 'zhTW', '[Draconis Gastritis]', '[Wait, that gives me an idea! What if it didn\'t kill the whelps because it was sprayed on the outside of their eggs?$B$B$N, we have to get the plague inside of them!$B$BI know! I\'ve got some plagued meat here. Take it to the Ember Clutch and get them to eat it!$B$BBut no, we\'re thinking too small. Let\'s get one of the proto-drakes flying overhead to come down and eat it.$B$BYes!$B$BStay close to the meat and observe what happens. Yes, it might attack you, but such is the price of progress.]', '[Plaguebringer Tillinghast at New Agamand wants you to use Tillinghast\'s Plagued Meat to attract down a Proto-Drake and observe its reaction to eating the stuff.]', '', '去找嚎風峽灣的瘟疫使者提林加斯特。', '已觀察始祖幼龍瘟疫的結果', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11281 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11281, 'zhTW', '[Mimicking Nature\'s Call]', '[The horn has been roughed out, but before I make the traditional carvings, I want to be certain that it will work. Ahota tells me that he tests his horns at the foot of the frozen waterfall to the northeast of the post. Ahota tells me that our hunters have used the acoustics of frozen water in this way for generations. I can\'t wait to learn more!$B$BWill you help me test out the horn? If I\'ve done everything right, you may even attract a yeti, so be prepared! Bring the horn back once you\'ve tested it. ]', '[Test the Carved Horn and then return to Nokoma Snowseer at Camp Winterhoof with the results.]', '', '去找嚎風峽灣的諾可瑪‧雪先知。', '測試諾科瑪之角', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11282 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11282, 'zhTW', '[A Lesson in Fear]', '[When you\'ve been in lots of fight like Gorth, you learn that to beat enemy good you have to make them really scared to die!$B$BBut these vrykuls not afraid.  You kill one and another comes... screaming louder and with a bigger weapon than the one before.$B$BOnly thing that makes vrykuls afraid is when we kill the biggest and baddest vrykul of all.$B$BGo fight the Winterskorn across the blockade until hero vrykuls show up!  Then you kill them dead and put queen\'s flag on corpses.  They must learn to fear!]', '[Gorth wants you to kill Ulf the Bloodletter, Oric the Baleful and Gunnar Thorvardsson and drive the Forsaken Banner through their corpses.  Slay Vrykul across the Forsaken blockade until they appear.]', '', '去找嚎風峽灣的葛司中士。', '邪惡者歐里克的屍體已被刺穿', '放血者烏爾夫的屍體已被刺穿', '岡納·索爾瓦森的屍體已被刺穿', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11283 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11283, 'zhTW', '[Baleheim Bodycount]', '[Them vrykuls just keeps coming and coming out from town west of here.  No end in sight!$B$BGorth has an idea.  You go INSIDE town and kill them Winterskorn there.  THEN they stop coming here!]', '[Sergeant Gorth wants you to kill 16 Winterskorn Vrykul inside Baleheim.]', '', '', '巴雷海姆的死亡人數', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11284 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11284, 'zhTW', '[The Yeti Next Door]', '[Maybe if the sentries won\'t help me, you will? I\'m the foreman of the mine just across the bridge. My men are mining ore for the weapons our expeditionary force will need to carve a path into the Grizzly Hills.$B$BA giant yeti has invaded the mine, blocking the tunnel we need to expand! We\'ve tried yelling at him and smoking him out, but nothing\'s worked.$B$BMaybe you could rouse it from its sleep with a meal of meat from the frosthorn rams in the snowy areas around town? Please? We\'re desperate!]', '[Foreman Colbey at Fort Wildervar wants you to defeat Shatterhorn.]', '', '去找嚎風峽灣的工頭寇畢。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11285 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11285, 'zhTW', '[Baleheim Must Burn!]', '[Killing the Winterskorns maybe not enough.  Maybe we burn their houses too!  Uh... and their bridges.  We should burn whole town to be safe!$B$BYou take this torch.  Go to Baleheim, to the west, and burn EVERYTHING!  That teach them good.]', '[Sergeant Gorth wants you to go to Baleheim and use Gorth\'s Torch to burn 1 Winterskorn Dwelling, 1 Winterskorn Watchtower, 1 Winterskorn Bridge and 1 Winterskorn Barracks.]', '', '', '寒冬扭曲住所已焚燒', '寒冬扭曲瞭望塔已焚燒', '寒冬扭曲橋樑已焚燒', '寒冬扭曲軍營已焚燒', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11286 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11286, 'zhTW', '[The Artifacts of Steel Gate]', '[I came out here for a different reason; an old friend of mine has been calling to me in my dreams. But now that I see these small things with their machines making a big hole in the ground, it makes my blood boil.$B$BFrom what I can see, these dwarves, as they are known, are digging up artifacts; artifacts that could be important to our past.$B$BI want you to go down there and get these things for me. Don\'t let any of those dwarves stand in your way.]', '[Sage Mistwalker has asked you to collect 10 Steel Gate Artifacts. When you have all of them, return to him at Steel Gate.]', '', '去找嚎風峽灣的賢者霧行。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11287 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11287, 'zhTW', '', '', '[Greatmother Ankha has asked you to check on the condition of Sage Mistwalker. She believes him to be at or near Steel Gate.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11288 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11288, 'zhTW', '[The Shining Light]', '[<Ares gasps for air as he tries to speak.>$B$BI am an envoy of the Argent Crusade, charged with a sacred duty.$B$BOur forces were decimated in the Plaguelands. By the light of dawn, the artifact was cleansed and made pure once more. So many perished in the wake of its redemption.$B$BThere is still a chance... still time.$B$BThe artifact was hurled into the den of the fallen, far below us. Guarded by the unmerciful dead.$B$B<Ares\' body glows with blinding light.>$B$BLight. Will. Protect. You.$B$B]', '[Ares the Oathbound in the Utgarde Catacombs wants you to recover the Sacred Artifact.$B$BThis is a timed quest.]', '', '去找嚎風峽灣的『誓縛』愛力士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11289 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11289, 'zhTW', '[Guided by Honor]', '[<Ares smiles.>$B$BGlory to the Light. You have done it!$B$B<Ares coughs.>$B$BTake the artifact and return it to Valgarde. Lord Irulon Trueblade awaits its return.$B$BFight with honor, friend. Always. Honor.$B$B<Ares dies.>]', '[Return the Sacred Artifact to Lord Irulon Trueblade at Valgarde.]', '', '去找嚎風峽灣的埃盧隆·真刃領主。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11290 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11290, 'zhTW', '[Dragonflayer Battle Plans]', '[While we were able to gather very little information as to the whereabouts of Ingvar, we do know that Yanis resides in a cave next to the worg pit inside Wyrmskull Village.$B$BIntelligence gathered from the rescued soldiers indicates that Yanis guards Dragonflayer battle plans.$B$BI need you to go back to Wyrmskull and recover those plans. Kill any vrykul that get in your way - including Yanis!]', '[Vice Admiral Keller at Valgarde Port in the Howling Fjord has asked that you bring him the Dragonflayer Battle Plans.$B$B]', '', '去找嚎風峽灣的海軍中將凱勒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11291 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11291, 'zhTW', '[To Westguard Keep!]', '[<Vice Admiral Keller rolls up the battle plans.>$B$BWe\'ve got all the information we need to keep Valgarde protected. You must take these battle plans to Westguard Keep, located on the western fjord cliff wall. Speak with the flight master assistant, Emilune Winterwind. She will put you on the back of a gryphon headed towards Westguard.$B$BOnce there, find Captain Adams. He\'s the one in charge. Adams will know what to do with these plans.]', '[Take the Dragonflayer Battle Plans to Captain Adams at Westguard Keep in the Howling Fjord.$B$B]', '', '去找嚎風峽灣的亞當斯隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11292 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11292, 'zhTW', '[Preying Upon the Weak]', '[Glad to meet you. I\'ve come here from the Grizzly Hills to do business with your cohorts. My people maintain a large outpost there, and you\'d do well to visit it when you head north.$B$BI\'ve set up traps in the woodlands and snowy areas around here. With the meat and the furs from the creatures they capture, I\'ll have plenty to barter with the townspeople.$B$BI can offer you a share of my profits if you\'re willing to help gather prey from the traps. Beware though, you won\'t be the only predator out there.]', '[Trapper Jethan at Fort Wildervar wants you to bring him 8 pieces of Trapped Prey.]', '', '去找嚎風峽灣的陷捕者傑桑。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11293 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11293, 'zhTW', '叫賣麥酒!', '我們需要讓大家知道有關麥酒家族在啤酒節的事。你得到銀行外、軍事區、探險者大廳以及秘法區外的旗幟下大聲叫喊。不過我會讓事情簡單點，我會借你競速山羊韁繩和一隻競速山羊4分鐘。用馬鞭驅趕山羊奔跑，不過試著別讓牠累過頭。', '在銀行外、軍事區、探險者大廳及秘法區外散佈有關啤酒節的訊息。', '', '去找丹莫羅的畢肯‧麥酒。', '在銀行外叫賣', '在軍事區叫賣', '在探險者大廳叫賣', '在秘法區叫賣', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11294 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11294, 'zhTW', '叫賣雷酒!', '是時候讓人們知道雷酒聽見了他們對於好啤酒的渴求。你得到銀行外、軍事區、探險者大廳以及秘法區外的旗幟下大聲叫喊。$B$B不過我會讓事情簡單點，我會借一隻山羊和一些馬鞭給你4分鐘。$B$B跑太快的時候要小心，你在鐵爐堡可找不到蘋果......我們可不想幫到麥酒的使者。', '在銀行外、軍事區、探險者大廳及秘法區外散佈有關啤酒節的訊息。', '', '去找丹莫羅的達然‧雷酒。', '在銀行外叫賣', '在軍事區叫賣', '在探險者大廳叫賣', '在秘法區叫賣', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11295 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11295, 'zhTW', '', '', '[Speak to Sergeant Gorth at the blockade near the elevator west of Vengeance Landing in Howling Fjord.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11296 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11296, 'zhTW', '[Rivenwood Captives]', '[Something, most likely the walking dead known as the Scourge, has agitated the creatures hereabouts.$B$BWhile escorting the sage here, we lost most of our hunting force to the riven widows -- huge and deadly spiders, which inhabit the Rivenwood to the north.$B$BI must stay here to protect the small force we have left, but you... you could see if my longrunners are still alive, trapped within the riven widow\'s cocoons.$B$BWould you do this, stranger?]', '[Longrunner Skycloud has asked you to free his 7 Winterhoof Longrunners. Once you have managed to do so, return to him at Steel Gate.]', '', '去找嚎風峽灣的遠偵斥候穹雲。', '已釋放冬蹄長跑者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11297 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11297, 'zhTW', '', '', '[Speak to Apothecary Malthus at the Apothecary Camp.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11298 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11298, 'zhTW', '[What\'s in That Brew?]', '[To the southeast is an area called Whisper Gulch. It\'s overrun with members of the Explorers\' League who\'ve gone mad! They attacked our caravan as it passed through the area, and they\'ve harried our foraging parties as well.$B$BI must know what\'s causing this madness! I suspect that whatever they\'re drinking from the kegs scattered around the gulch contributes to their insanity. I want you to steal the kegs from those dwarves while they\'re busy mining away.]', '[Apothecary Malthus at the Apothecary Camp wants you to bring him 5 Dwarven Kegs.]', '', '去找嚎風峽灣的藥劑師馬爾薩斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11299 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11299, 'zhTW', '', '', '[Find Daegarn in the Ring of Judgement located inside the Utgarde Catacombs.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11300 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11300, 'zhTW', '[Stunning Defeat at the Ring]', '[Oluf will come out if you defeat the other gladiators. That\'s \'bout the only way we\'re getting\' that cipher back. Put on your whompin\' boots and get busy in the Ring of Judgement. If you do manage to get the cipher back, return it to Glorenfeld o\'er near the entrance to these catacombs.$B$BMe? Don\'t worry about me! We\'re on the brink of discovering the missing link to human-kind!]', '[Defeat the gladiators at the Ring of Judgement and face Oluf the Violent. Defeat Oluf and recover the Ancient Cipher.$B$BReturn the Ancient Cipher to Glorenfeld at the entrance to the Utgarde Catacombs.]', '', '去找嚎風峽灣的葛羅倫費德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11301 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11301, 'zhTW', '[Brains! Brains! Brains!]', '[Has Malthus drawn you in with his blather about beer kegs and crazy dwarves?$B$BI\'m not questioning that the dwarves are crazy, but I don\'t think stealing their beer is going to do any good.$B$BWhat we need is brains. Lots of brains. We\'ll get down to the bottom of this mystery in no time, and perhaps even find a new component for the plague.$B$BTake this saw, go southeast into the Whisper Gulch, and kill yourself some dwarves. Use the saw to help you harvest the brains and bring them back here.]', '[Apothecary Grick at the Apothecary Camp wants you to bring him 12 Deranged Explorer Brains.]', '', '去找嚎風峽灣的藥劑師格里克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11302 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11302,'zhTW','神秘的冰雪樹妖','我們第一次到達這附近為要塞選址的時候，曾經在北邊的兩處林地附近遇到了一些懷有敵意的生物。再後來，我們穿越鎮子南邊的那塊被冰雪覆蓋的林地時，又遇到了幾隻饒有興趣地觀察著我們的樹妖。不過，跟北邊那些林地裡的不同，她們沒有攻擊我們。$B$B當時，我們被這裡的鬼天氣折磨得暈頭轉向，而且又餓又累，她們完全可以不費吹灰之力就把我們殺個精光，可她們沒有那麼做。$B$B或許我們應該主動和她們接觸一下，去爭取所有能夠爭取到的盟友？你願意轉至冰雪林地，向她們表達我們的友善之意嗎？','與冰雪林地的魯莉爾蕾談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11303 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11303, 'zhTW', '', '', '[Speak to Lydell at Lydell\'s Ambush.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11304 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11304, 'zhTW', '[New Agamand]', '[I\'m afraid our equipment isn\'t exactly the best here at Vengeance Landing.  After all it\'s a military controlled outpost.$B$BI will need you to take a sample of this strain to Chief Plaguebringer Harris in New Agamand, follow the road beyond Baleheim south and then west.  They have better equipment there - he will know what to do.$B$BYou must hurry, $N.  Our enemies are stronger and more numerous than us.  We need to develop a viable weapon against them!]', '[Bring Lysander\'s Strain to Chief Plaguebringer Harris in New Agamand in western Howling Fjord.]', '', '去找嚎風峽灣的首席瘟疫使者哈里斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11305 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11305, 'zhTW', '[A Tailor-Made Formula]', '[We\'ve been spraying down the vrykul village of Halgrind for weeks now and the vrykul just won\'t drop dead.$B$BLet\'s face it, $N, by now our Plague has been exposed to humans, dwarves, dogs, livestock... you name it.  As our strains adapt to their hosts, more impurities get thrown in the mix.  What we need is a strain made custom for the vrykul\'s biology.$B$BHalgrind\'s chieftain fled the town after we took it over; you\'ll find him west of here.  As a patriarch of the Dragonflayer clan, his blood is ideal.]', '[Obtain the Dragonflayer Patriarch\'s Blood from Thorvald at Thorvald\'s Camp and bring it to Chief Plaguebringer Harris in New Agamand.]', '', '去找嚎風峽灣的首席瘟疫使者哈里斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11306 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11306, 'zhTW', '[Apply Heat and Stir]', '[You\'ve done well so far, $N.  I\'d like to teach you some of my more advanced techniques, so that you gain a better understanding of the plague.$B$BTake this empty flask and fill it with blood from the cauldron to my left.  Mix it with the plague samples to my right until you obtain a well balanced mix.]', '[Fill the Empty Apothecary\'s Flask at the Cauldron of Vrykul Blood, then mix the Flask of Vrykul Blood with Harris\'s Plague Samples nearby until you\'ve obtained a Balanced Concoction.$B$BReturn to Chief Plaguebringer Harris when you\'ve completed this task.]', '', '去找嚎風峽灣的首席瘟疫使者哈里斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11307 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11307, 'zhTW', '[Field Test]', '[Now that we have a strain of the plague that has adapted to vrykul carriers, we really ought to test it on our specimens in Halgrind.  If all goes according to plan, they will disintegrate immediately as the plague devours their innards!$B$BYou will find Halgrind north of here.  Our plaguebringers are deploying the previous strain there - shouldn\'t be hard to spot.]', '[Venture into Halgrind and use the Plague Spray on 10 Plagued Dragonflayer Vrykul.  Return to Chief Plaguebringer Harris to report the results.]', '', '去找嚎風峽灣的首席瘟疫使者哈里斯。', '已對染疫維库人噴灑', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11308 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11308, 'zhTW', '', '', '[Speak to "Hacksaw" Jenny in New Agamand.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11309 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11309, 'zhTW', '[Parts for the Job]', '[So Harris wants a demolition job, eh?  Yeah, I can help out.$B$BYou\'re gonna have to get me some parts, though.  I can\'t afford to use up my choice components on something that\'s gonna get blown up.$B$BFirst of all, I\'m going to need shoveltusk ligaments... way better than the human kind.$B$BI will also need a pound of flesh.  A fellow known as Anton sells cheap meat.  He travels up and down the road to the west.]', '["Hacksaw" Jenny in New Agamand wants you to obtain 6 Shoveltusk Ligaments and 1 Fresh Pound of Flesh.]', '', '去找嚎風峽灣的『鋼鋸』潔妮。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11310 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11310, 'zhTW', '[Warning: Some Assembly Required]', '[Well, here you are!  Our friend\'s going to be somewhat... unstable.  So I suggest not putting him together until reaching Halgrind.$B$BOnce you\'re there, use the abomination to round up as many vrykul as you can before self-destructing.$B$BCome back with whatever\'s left once you\'re done.  I can always use more body parts!]', '[Use the Abomination Assembly Kit in Halgrind and round up plagued Vrykul with your Mindless Abomination.  Slay at least 20 and return to "Hacksaw" Jenny in New Agamand when you\'re done.]', '', '去找嚎風峽灣的『鋼鋸』潔妮。', '染疫維库人已消滅', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11311 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11311, 'zhTW', '[Suppressing the Elements]', '[If you are to survive here, as we have, you must learn to face the environment\'s challenges head on. The elements will claim your life if you\'re not vigilant, as the proliferation of elementals in these northern hills shows.$B$BWe must cull the elementals one last time before we can leave this place. Are you willing to aid us while we continue to make preparations?$B$BYou must kill any iceshard elementals or howling cyclones you encounter in the snowy hills surrounding the outpost.]', '[Wind Tamer Kagan at Camp Winterhoof wants you to kill 8 mountain elementals. You may kill either Howling Cyclones or Iceshard Elementals.]', '', '去找嚎風峽灣的馴風者卡剛。', '山脈元素生物已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11312 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11312, 'zhTW', '', '', '[Speak with Lurielle at the Frozen Glade.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11313 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11313, 'zhTW', '[Spirits of the Ice]', '[The ice elementals surrounding our glade were once our companions, but a volatile and destructive force has swept through the land, turning them against us!$B$BThis is but one of the horrors my sisters and I have endured. We have revealed ourselves to you in the hope that you will help us stave off the decay that has crept into our glades and poisoned our sisters!$B$BWe\'ve been gathering the cores of the ice elementals and keeping them safe so that one day, we might be able to restore them. Will you help?]', '[Lurielle at the Frozen Glade wants you to bring her 15 Icy Cores.]', '', '去找嚎風峽灣的露麗兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11314 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11314, 'zhTW', '[The Fallen Sisters]', '[To the southwest was a glade that used to look much like this one. Mysterious forces and alien magics are reshaping the land. The glade has thawed, the sisters living there driven mad by the sudden change.$B$BWe thought to reach out to them, but they attacked us. I fear many may be beyond saving, but I cannot give up hope.$B$BTake my pendant, travel southwest to the Vibrant Glade, and use it to try to free my sisters.]', '[Lurielle at the Frozen Glade wants you to use her pendant on 7 Chill Nymphs.]', '', '去找嚎風峽灣的露麗兒。', '已釋放寒冰水靈', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11315 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11315, 'zhTW', '[Wild Vines]', '[The sisters who lived in the Vibrant Glade, to the southwest, used to tend to gorgeous beds of scarlet ivy, but the same force that has driven them mad has transformed their beloved ivy.$B$BThe vines now grasp at the feet of the unwary, or lash at any who approach the glade. Before we can reclaim the glade, the vines must be tamed and uprooted.$B$BClear as much of the ivy as you are able. It has already begun to grow out of control.]', '[Lurielle at the Frozen Glade wants you to kill 8 Scarlet Ivy.]', '', '去找嚎風峽灣的露麗兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11316 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11316, 'zhTW', '[Spawn of the Twisted Glade]', '[The glade to the west has been transformed into a hideous place called the Twisted Glade. Horrible beasts dwell among the trees, stones, and pool of the glade.$B$BI cannot guess where the creatures came from or what horrible forces animate them, but they must be dealt with!$B$BI fear that if they are allowed to dominate the glade, they will poison it beyond redemption. Clear the glade of these creatures who murdered our sisters.]', '[Lurielle at the Frozen Glade wants you to kill 10 Thornvine Creepers.]', '', '去找嚎風峽灣的露麗兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11317 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11317, 'zhTW', '[The Cleansing]', '[We braved the Rivenwood because of my troubled dreams concerning my worg life-friend, Ulfang. He has called out for help, and you must go to him.$B$BBut, you do not have the means to speak with him, or walk amongst the other worgs. I know a way.$B$BFirst, you must cleanse your inner turmoil.$B$BThere is a shrine that sits at the top of Frostblade Peak, northeast of Camp Winterhoof. A single path leads up to it from the western base of the mountain.$B$BMeditate there and then return to me.]', '[Sage Mistwalker at Steel Gate has advised you to cleanse yourself of Your Inner Turmoil through meditation at the Frostblade Shrine.]', '', '去找嚎風峽灣的賢者霧行。', '已淨化內心的紛亂', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11318 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11318, 'zhTW', '現在就是山羊競速…差不多。', '所以你想瞧瞧競速山羊?希望你已經準備好面對極速挑戰了。『但是』在我讓你出發之前，你得向我證明你知道該如何操控這些良好的生物。$B$B條件如下:我會借給你一些競速韁繩還有一頭山羊。你得向我證明你會操縱這些山羊。$B$B讓山羊在疾馳、快步和慢跑的狀態下各維持8秒。假如你想知道如何駕馭這些山羊，去找我的學徒保爾·安伯斯堤爾吧。', '你有4分鐘的時間可以鞭打山羊，然後在3種不同速度下各維持8秒。', '', '去找丹莫羅的奈爾‧拉姆斯登。', '維持快步8秒', '維持慢跑8秒', '維持疾馳8秒', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11319 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11319, 'zhTW', '[Seeds of the Blacksouled Keepers]', '[The glade to the northwest, now the Twisted Glade, used to be home to a number of keepers of the glade. Together with the sisters, they saw to the glade\'s upkeep.$B$BWhen the glade changed, the sisters died, but somehow the keepers managed to survive. Now, they seed the land with poisonous spores that wither healthy greenery.$B$BI\'ll give you one of the cores from the ice elementals. Once you\'ve destroyed a spore, use the ice crystal to freeze it and keep it from regenerating.]', '[Lurielle at the Frozen Glade wants you to freeze 8 Spores.]', '', '去找嚎風峽灣的露麗兒。', '孢子已冰凍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11320 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11320, 'zhTW', '[[NYI] Now this is Ram Racing... Almost.]', '[Quest Description]', '[Log Descritpion ]', '', '去找丹莫羅的達然‧雷酒。', '維持綠色速度6秒', '維持黃色速度6秒', '維持紅色速度6秒', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11321 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11321,'zhTW','剛才有人說“紀念品”？','美酒節除了賽羊會外，還有一項傳統，那就是飲酒狂歡！如果你有時間的話，就將這張禮品券交給貝爾比吧。她就在美酒節營地的後面。要是你看不見她，沒關係，她一定會看見你的。$B$B無論如何，將禮品券交給她，你就能免費領到一隻美酒節酒杯。她還出售各種美酒哦。','在美酒節營地的貝爾比處兌換禮品券。','','去找丹\\r\\n莫羅的貝爾比。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11322 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11322, 'zhTW', '[The Cleansing]', '[Of late I\'ve had nightmares concerning a worg named Ulfang. He has called out for help, and you must go to him.$B$BHowever, you do not have the means to speak with him, or walk amongst the other worgs. I know a way.$B$BBut first, you must cleanse your inner turmoil through meditation.$B$BThere is a shrine that sits at the top of Frostblade Peak, far to the northeast. A single path leads up to it from the western base of the mountain.$B$BMeditate there to cleanse yourself and then return to me.]', '[Watcher Moonleaf at Steel Gate has advised you to cleanse yourself of Your Inner Turmoil through meditation at the Frostblade Shrine.]', '', '去找嚎風峽灣的看守者月葉。', '已淨化內心的紛亂', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11323 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11323, 'zhTW', '[In Worg\'s Clothing]', '[From my dreams, I know that Ulfang is in a cave on the snowy northwestern edge of the Rivenwood.$B$BHe is in great danger.$B$BI have devised a magical disguise that will make you appear as a worg while you are within the Rivenwood. The disguise is weak, relying upon the strange magics of that haunted wood. While it will only convince the worgs, it will allow you to get close to Ulfang.$B$BPlease, $c, find and help him.]', '[Sage Mistwalker has asked you to seek out and help Ulfang in the Rivenwood.$B$BIf you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement.]$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11324 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11324, 'zhTW', '[Alpha Worg]', '[When you\'ve eaten Talonshrike\'s eyes, you should be able see Garwal and rip out his throat!$B$B$R-thing, seek out and slay Garwal in the western Rivenwood. After you have killed him, go and tell Mistwalker that I am once more the alpha worg!]', '[Ulfang has asked you to slay Garwal. Then, return the Worg Disguise to Sage Mistwalker at Steel Gate.]', '', '去找嚎風峽灣的賢者霧行。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11325 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11325, 'zhTW', '[In Worg\'s Clothing]', '[From my dreams, I know that Ulfang is in a cave on the snowy northwestern edge of the Rivenwood.$B$BHe is in great danger!$B$BI have devised a magical disguise that will make you appear as a worg while you are within the Rivenwood. The disguise is weak, relying upon the strange magics of that haunted wood. While it will only convince the worgs, it will allow you to get close to Ulfang.$B$BPlease, $c, find and help him.]', '[Watcher Moonleaf has asked you to seek out and help Ulfang in the Rivenwood.$B$BIf you somehow lose the Worg Disguise, return to Watcher Moonleaf for a replacement.]$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11326 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11326, 'zhTW', '[Alpha Worg]', '[When you\'ve eaten Talonshrike\'s eyes, you should be able see Garwal and rip out his throat!$B$B$R-thing, seek out and slay Garwal in the western Rivenwood. After you have killed him, go and tell Moonleaf that I am once more the alpha worg!]', '[Ulfang has asked you to slay Garwal. Then, return the Worg Disguise to Watcher Moonleaf at Steel Gate.]', '', '去找嚎風峽灣的看守者月葉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11327 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11327, 'zhTW', '[Mission: Package Retrieval]', '[Well darn, we need some of that plague-stuff.$B$BI know!$B$BWhile you were destroying the vats, I happened to spy one of the apothecaries from New Agamand being pulled into Halgrind by the vrykul down in there. Poor fella\'.$B$B$N, I\'d bet anything that apothecary has the goods on him. Think you could go into Halgrind and retrieve his package?]', '[Scout Knowles has asked you to retrieve the Apothecary\'s Package from inside Halgrind. Once you have it, return to the scout at the Ember Spear Tower.]', '', '去找嚎風峽灣的斥候諾雷斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11328 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11328, 'zhTW', '[Mission: Forsaken Intel]', '[Right, so I think you should get this stuff over to Peppy Wrongnozzle back at the keep. She\'s something of an amateur alchemist, but she\'s the only one we\'ve got.$B$BOne thing about Peppy; she does love her drink. So, you\'ll likely find her at the tavern \'soaking up the atmosphere\'.$B$BI\'m sure she\'ll know what to do.]', '[Scout Knowles has asked you to deliver the Apothecary\'s Package to Peppy Wrongnozzle at Westguard Keep.]', '', '去找嚎風峽灣的派比·錯鼻。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11329 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11329, 'zhTW', '[I\'ll Try Anything!]', '[I never want to see another barrel of salted fish as long as I live! Filling barrels day in and day out, and there are still more to be filled!$B$BI wish I hadn\'t used up all that bait I bought from Nat Pagle. Worked like magic, it did. Now I\'m lucky if I can catch a fish an hour!$B$BI hear the northern barbfish make pretty good bait, but who\'s crazy enough to dive into a freezing cold lake and hack up the water plants in search of them? Not me... but maybe, just maybe, I can persuade you to...]', '[Christopher Sloan at Fort Wildervar wants you to bring him 5 Northern Barbfish.]', '', '去找嚎風峽灣的克里斯多夫·斯洛安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11330 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11330, 'zhTW', '[Absholutely... Thish Will Work!]', '[Voila, inshtant plague vacshine!$B$BBut I sure as heck am not going to try thish on myself. And I know you don\'t want to be my tesht shubject!$B$BOh, I\'ve got... I\'ve got an idea!$B$BWe\'ve got a vrykul prishoner being held down in the cells under the keep. Why don\'t you take thish mix I whipped up down there, and get that giant to drink it ...hic?!]', '[Peppy Wrongnozzle at Westguard Keep has suggested that you take her Peppy\'s Special Mix and administer it to the Dragonflayer Vrykul Prisoner to witness its results.]', '', '去找嚎風峽灣的派比·錯鼻。', '已對維库人囚犯施用佩皮的調製藥劑', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11331 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11331, 'zhTW', '', '', '[Peppy Wrongnozzle has suckered you into giving the bad news about the Forsaken plague to Captain Adams. Visit him at Westguard Keep.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11332 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11332, 'zhTW', '[Mission: Plague This!]', '[The Royal Apothecary Society thinks they\'re going to perfect a new plague to melt us down where we stand?!$B$BNot on my watch!$B$BGet out to the courtyard and speak with Greer Orehammer. He\'s got a gryphon and some bombs ready for you. I want you to bomb the plague tanks at New Agamand to smithereens!]', '[Captain Adams has ordered you to get 5 bomb hits on the Plague Tanks at New Agamand. Do not return to him at Westguard Keep until you have accomplished that.]', '', '去找嚎風峽灣的亞當斯隊長。', '瘟疫戰車命中次數', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11333 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11333, 'zhTW', '[Into the World of Spirits]', '[While the Explorers\' League may discern bits and pieces of the past through their archaeological findings and the Vice Admiral might extract some knowledge of the present through brute force, the truth lies with the spirits.$B$BWith the proper reagents I am able to see into the spirit world. It is there that the past, present and future of Northrend resides.$B$BIf you wish to learn more, I will require my reagent pouch. It was lost in a ship that is now at the bottom of Daggercap Bay, just east of here.]', '[Thoralius the Wise at Valgarde wants you to find his Reagent Pouch.]', '', '去找嚎風峽灣的『智者』索拉利亞思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11334 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11334,'zhTW','打中，得分！','[PH] 射擊已標記的目標。','[PH]瑞林要你射擊標靶，然後把標靶來福槍還給他。','','去找瑞林。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11335 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11335,'zhTW','戰鬥的召喚：阿拉希盆地','事實上，我們在多線作戰，$g小子:小姑娘，而且我們不能把軍隊部署得太過分佈，否則我們可能會全盤皆輸！$B$B我們需要以天為單位來部署最關鍵的部隊，今天，阿拉希盆地的戰鬥最需要勇敢的士兵！$B$B帶著勝利的訊息回來吧，$n。我們不允許部落狗來威脅屬於我們的資源！','在阿拉希盆地戰場中獲得一場勝利，然後向任意聯盟主城、冬握湖、達拉然或撒塔斯城中的聯盟准將覆命。','在阿拉希盆地獲勝','去找聯盟准將。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11336 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11336,'zhTW','戰鬥的召喚：奧特蘭克山谷','事實上，我們在多線作戰，$g小子:小姑娘，而且我們不能把軍隊部署得太過分佈，否則我們可能會全盤皆輸！$B$B我們需要以天為單位來部署最關鍵的部隊，今天，奧特蘭克山谷的戰鬥最需要勇敢的士兵們！$B$B現在就出發吧，$N，去幫助雷矛遠征軍。我們不能就這麼看著霜狼氏族逃脫他們應受的懲罰。','在奧特蘭克山谷戰場中獲得一場勝利，然後向任意聯盟主城、冬握湖、達拉然或撒塔斯城中的聯盟准將覆命。','在奧特蘭克山谷獲勝','去找聯盟准將。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11337 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11337, 'zhTW', '戰鬥的號角:暴風之眼', '和部落的鬥爭沒有邊界，$N。既使在外域，領土的糾紛與古老的仇恨依舊可以挑起戰爭的烽火。$B$B前往暴風之眼吧，確保聯盟將會像在艾澤拉斯一樣地獲勝。', '在暴風之眼的戰場中獲勝，然後向任何一座首都或撒塔斯的聯盟准將回報。', '風暴之眼的勝利', '去找聯盟准將。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11338 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11338,'zhTW','戰鬥的召喚：戰歌峽谷','銀翼哨兵透過戰鬥來保護戰歌峽谷的森林。我們幫助他們，並不是因為我們愛好樹木，而是因為森林為聯盟領地提供了天然的屏障。$B$B今天他們那裡的情勢非常危急，遠遠超過以往任何時候。我們必須立刻派出援軍，除非我們希望看到梣谷成為貧瘠之地的附屬地！','在戰歌峽谷戰場中獲得一場勝利，然後向任意聯盟主城、冬握湖、達拉然或撒塔斯城中的聯盟准將覆命。','在戰歌峽谷獲勝','去找聯盟准將。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11339 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11339,'zhTW','戰鬥的召喚：阿拉希盆地','阿拉希盆地快要讓聯盟奪走了，我們必須儘快派出援兵，否則我們所做的一切都將成為徒勞。$B$B不要拖延了，$c。去阿拉希盆地消滅敵人，勝利屬於部落！','在阿拉希盆地戰場中獲得一場勝利，然後向任意部落主城、冬握湖、達拉然或撒塔斯城中的部落戰爭使者覆命。','在阿拉希盆地獲勝','去找部落戰爭使者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11340 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11340,'zhTW','戰鬥的召喚：奧特蘭克山谷','我們就快要把雷矛入侵者從奧特蘭克山谷趕走了，因此我們必須調動一切可能的增援力量來幫助霜狼氏族。$B$B一場決定性的勝利可以讓我們騰出足夠的資源在其它戰場上消滅聯盟的那些混蛋。$B$B出發吧，$N。聽從霜狼氏族的號令，去贏得無上的榮耀吧！','在奧特蘭克山谷戰場中獲得一場勝利，然後向任意部落主城、冬握湖、達拉然或撒塔斯城中的部落戰爭使者覆命。','在奧特蘭克山谷獲勝','去找部落戰爭使者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11341 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11341, 'zhTW', '戰鬥的號角:暴風之眼', '我們將會戰鬥並擊敗我們在各處發現的敵人。艾澤拉斯，外域，各地都一樣。$B$B我們不允許聯盟在暴風之眼中佔有優勢。今天就去對他們開戰...明天可能就太遲了!', '在暴風之眼的戰場中獲勝，然後向任何一座首都或撒塔斯的部落戰爭使者回報。', '風暴之眼的勝利', '去找部落戰爭使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11342 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11342,'zhTW','戰鬥的召喚：戰歌峽谷','聯盟真是個陰險的敵人，$N。他們張口閉口說在保護梣谷的森林，以此證明他們對我們貧瘠之地領土的進攻行動是正當的。$B$B今天，我們有機會把敵人徹底趕出部落的領土。去戰歌峽谷，奪回一切本屬於我們的東西！','在戰歌峽谷戰場中獲得一場勝利，然後向任意部落主城、冬握湖、達拉然或撒塔斯城中的部落戰爭使者覆命。','在戰歌峽谷獲勝','去找部落戰爭使者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11343 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11343, 'zhTW', '[The Echo of Ymiron]', '[The spirit world has fallen under the sway of the Lich King. Fearsome creatures made of pure nightmare now stand watch over the realm of the elements. I sense that these val\'kyr are guarding a terrible secret.$B$BI am too old and weak to survive another journey. You must go in my place, $N.$B$BTake this incense burner to Wyrmskull Village and use it to enter the spirit world. Find the large dwelling in the northeast! Avoid the val\'kyr at all costs lest they make you a permanent fixture in their world.]', '[Thoralius the Wise wants you to search Wyrmskull Village while you are in the spirit world and find information about the Secrets of Wyrmskull.]', '巨龍顱骨的秘密已揭露', '去找嚎風峽灣的『智者』索拉利亞思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11344 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11344, 'zhTW', '[Anguish of Nifflevar]', '[All that we know of the vrykul indicates that they only recently appeared in Northrend. Why, then, are we seeing vrykul in visions that date back 15,000 years? Surely if the vrykul had previously existed in Northrend we would have known.$B$BYou must press on to Nifflevar. To get there you must go northeast, through Wyrmskull Village, and take the path leading up through the dam. Nifflevar is on the bluffs of the fjord.$B$BUse the incense burner once you arrive at Nifflevar and search the area for clues.]', '[Thoralius the Wise wants you to search Nifflevar while you are in the spirit world and find information about the Secrets of Nifflevar.]', '尼弗雷瓦爾的秘密已揭露', '去找嚎風峽灣的『智者』索拉利亞思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11345 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11345,'zhTW','打靶獎勵','[PH] 射擊已標記的目標。','[PH]瑞林要你射擊標靶，然後把標靶來福槍還給他。','','去找瑞林。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11346 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11346, 'zhTW', '[The Book of Runes]', '[The vast rocky area to the southeast, Giants\' Run, has been overrun by Iron Dwarves. Scouts have reported seeing the dwarves coaxing stone giants from the ground, then carving runes on them.$B$BI can\'t fathom their motives, but I suspect they\'re somehow trying to turn the giants into weapons. The iron rune stonecallers and binders carry large tomes with them, which must contain the runes they\'re carving on the giants.$B$BCapture the pieces of this book, assemble them, and bring it back to me, $N.]', '[Prospector Belvar at Fort Wildervar wants you to bring him The Book of Runes.]', '', '去找嚎風峽灣的勘察員貝爾瓦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11347 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11347,'zhTW','清理某些房間','我們有著堆積如山的包裹要送到卡拉諾斯的旅店去。這些包裹得儘快送到，所以我讓你借用我的競速山羊。就算你只送1個包裹我也會很感激。但你只有5分鐘，能送多少送多少吧，我會依數量獎勵你的。','把包裹送到卡拉諾斯，最少一次。送得越多次獎勵越好。','','去找。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11348 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11348, 'zhTW', '[The Rune of Command]', '[Can you feel the power emanating from the runes I\'ve carved on this tablet? They\'re smaller versions of the runes that the Iron Dwarves are using. We\'ll use it to shut down their operation.$B$BTake it to Giants\' Run and use it on a stone giant that the dwarves have not altered.$B$BThe giant should obey you, but I\'ve tailored the runes to restore it to its natural state after a time. The giant may prove a valuable ally in the battle against Binder Murdis, the leader of the Iron Dwarf forces at Giants\' Run.]', '[Prospector Belvar at Fort Wildervar wants you to test the Rune of Command and defeat Binder Murdis.]', '', '去找嚎風峽灣的勘察員貝爾瓦。', '測試指揮符文', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11349 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11349,'zhTW','掌控符文','我這倒是有鋤頭、鐵錘和鑿子什麼的，可惜它們不能雕刻符文。鐵矮人使用的雕琢工具就不一樣啦，他們在鑄造工具時向裡面灌注了魔法力量。$B$B使用這樣的工具進行雕刻，符文就不僅僅是簡單的字元了，它們具備了束縛、支配與扭曲的力量。$B$B這些我都瞭然於心，眼下就缺少雕琢工具進行實踐了。轉至巨人平原的鐵矮人營帳附近尋找工具箱，把它們帶回來給我。','將一套鐵符文雕刻工具交給維德瓦堡壘的勘測員貝瓦爾。','','去凜風峽灣找維德瓦堡壘的勘測員貝瓦爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11350 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11350, 'zhTW', '[The Book of Runes]', '[Chieftain Ashtotem dispatched me on a scouting mission to Giants\' Run, a broad, rocky plateau to the southeast, past the Frozen Glade.$B$BThe area has been taken over by Iron Dwarves who seem to be altering the giants as they emerge from the earth.$B$BThe iron rune stonecallers and binders carry large tomes with them, which must contain the runes they\'re carving on the giants.$B$BCapture the pieces of this book, assemble them, and bring it back to me. It\'s the only way we\'ll understand their plans.]', '[Longrunner Pembe at Camp Winterhoof wants you to bring him The Book of Runes.]', '', '去找嚎風峽灣的遠偵斥候潘比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11351 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11351, 'zhTW', '[Mastering the Runes]', '[I think I\'ve figured out what the Iron Dwarves are doing. The tools they use are imbued with magic during their forging.$B$BWhen they\'re used to carve runes, the symbols form much more than mere words. These runes have the power to bind, compel, and twist.$B$BIf I had a set of those tools, I could mimic the runes in the book. I captured one of these boxes from one of the pavilions at Giants\' Run, but it was empty. Look for similar boxes and recover a set of tools from them.]', '[Bring a set of Iron Rune Carving Tools to Longrunner Pembe at Camp Winterhoof.]', '', '去找嚎風峽灣的遠偵斥候潘比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11352 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11352, 'zhTW', '[The Rune of Command]', '[Can you feel the power emanating from the runes I\'ve carved on this tablet? They\'re smaller versions of the runes that the Iron Dwarves are using. We\'ll use it to shut down their operation.$B$BTake it to Giants\' Run and use it on a stone giant that the dwarves have not altered.$B$BThe giant should obey you, but I\'ve tailored the runes to restore it to its natural state after a time. The giant may prove a valuable ally in the battle against Binder Murdis, the leader of the Iron Dwarf forces at Giants\' Run.]', '[Longrunner Pembe at Camp Winterhoof wants you to test the Rune of Command and defeat Binder Murdis.]', '', '去找嚎風峽灣的遠偵斥候潘比。', '測試指揮符文', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11353 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11353,'zhTW','FLAG: Got the work shirt[日常]','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11354 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11354,'zhTW','懸賞：納杉的騎鞭','今天，有位顧客對伊利丹的傳令官及其坐騎表現出莫大的興趣。當然，我指的是傳令官瓦茲德和納杉。$B$B想要領取酬金的話，就轉至地獄火堡壘，進入地獄火城牆，將納杉的騎鞭帶回來。$B$B我得到的情報有點奇怪，據說納杉的騎鞭是由納杉自己來保管的，而且還據說這頭龍從來都不肯讓傳令官使用騎鞭。','商人扎雷姆要求你奪得納杉的騎鞭。將騎鞭帶回撒塔斯城的貧民窟交給他，就能領取獎賞。$B$B該任務只能在英雄模式下完成。','','去找泰羅卡森林的商人扎雷姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11355 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11355,'zhTW','巨人的遷徙','東邊的巨人平原起了騷動，刻有符文的石巨人開始往北邊的霜刃峰遷徙。我不知道他們的目的地是哪兒。$B$B刻在他們身上的符文散發著詭異的光芒，驅使他們前進。如果你能擊倒巨人，從他們體表剝下一些符文，符文的效力就會消散，便於我們展開研究。$B$B利用這把鋤從巨人身上剝下一些符文石板，然後把它們給我帶回來。','維德瓦堡壘的研究員艾德蘭要你在4個符文石巨人的屍體上使用符文搜尋之鋤。','','去凜風峽灣找維德瓦堡壘的研究員艾德蘭。','分析符文石巨人的屍體','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11356 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11356, 'zhTW', '', '', '[Speak with a Costumed Orphan Matron in either Goldshire, Kharanos or Azure Watch.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11357 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11357, 'zhTW', '', '', '[Speak with a Masked Orphan Matron in either Razor Hill, Brill or Falconwing Square.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11358 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11358, 'zhTW', '[The Lodestone]', '[If we can locate what\'s luring the giants northwest, we might be able to stop them before they reach their destination.$B$BAlthough I was able to decipher many of the runes on the samples you brought me, the ones I don\'t know concern me the most. When I visited Giants\' Run, I noticed a large broken tablet jutting from the ground where the northeastern part of the area met the snow at the foot of Frostblade Peak. Take this sample, compare the runes with the tablet, and see what you can learn.]', '[Researcher Aderan at Fort Wildervar wants you to compare the Rune Sample with the Broken Tablet.]', '', '去找嚎風峽灣的研究員艾德蘭。', '將符文與破碎石板比對', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11359 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11359, 'zhTW', '[Demolishing Megalith]', '[Binder Murdis created Megalith to be the most powerful of the runed giants and to lead them in their mission. Defeating Megalith will leave them lost and without direction. After the expeditionary force arrives, our soldiers will be able to isolate and defeat the remaining giants and oust their Iron Dwarf masters from their camps.$B$BSearch the foothills of Frostblade Peak, north of Giants\' Run for Megalith and defeat him!]', '[Defeat Megalith and return to Researcher Aderan at Fort Wildervar.]', '', '去找嚎風峽灣的研究員艾德蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11360 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11360, 'zhTW', '[Fire Brigade Practice]', '[With the Headless Horseman at large, the heroes of Goldshire are always ready to form a fire brigade.  Do you want to help?$B$BNorth of here, guards set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here, or the one near the fires.$B$BGood bye, $N.  When you\'re done with fire brigade practice, please visit us again!]', '[Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.]', '', '去找艾爾文森林的變裝的孤兒監護員。', '撲滅火勢', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11361 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11361, 'zhTW', '[Fire Training]', '[The grunts set up a fire training area outside the village.  These days, Razor Hill\'s buildings often catch fire -- you should lend a hand and train as a fire fighter!$B$BHead west out of Razor Hill, then turn right as you pass the village\'s wall.  Find the training area, then grab buckets and toss them on the practice fires.]', '[Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Razor Hill.]', '', '去杜隆塔爾找剃刀嶺的戴面具的孤兒監護員。', '撲滅火勢', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11362 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11362,'zhTW','懸賞：克里丹的羽飾法杖','俗話說青菜蘿蔔各有所愛，就拿我剛接待的顧客來說吧。$B$B地獄火堡壘中有個名叫擊碎者克里丹的邪獸人，他有一柄極其尋常的法杖，根本不值一哂，但這位顧客偏偏就指名要這柄法杖。$B$B我怎麼能拒絕顧客的請求呢？$B$B想要領取酬金的話，就轉至鮮血熔爐，從克里丹手中奪回法杖。','商人扎雷姆要求你奪得克里丹的羽飾法杖。將法杖帶回撒塔斯城的貧民窟交給他，就能領取獎賞。$B$B該任務只能在英雄模式下完成。','','去找泰羅卡森林的商人扎雷姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11363 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11363,'zhTW','懸賞：刃拳的印記','今天我接待了一名腰纏萬貫的收藏家，這位貴客想要購買某件特殊的器物。$B$B酋長卡加斯·刃拳總是隨身攜帶著一枚印章，用來簽署各類官方檔案。我要你替我奪回這東西。$B$B卡加斯·刃拳就在破碎大廳深處。毫無疑問，你需要剷除大量獸人雜兵才能到達酋長面前，不過我深信你會凱旋的。','商人扎雷姆要求你奪得刃拳的印記。將印記帶回撒塔斯城的貧民窟交給他，就能領取獎賞。$B$B該任務只能在英雄模式下完成。','','去找泰羅卡森林的商人扎雷姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11364 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11364,'zhTW','懸賞：碎手百夫長','你經常質疑你的主人嗎？瑪哈杜恩可絕對不會。$B$B現在，我需要的就是破碎之手氏族百夫長的血。你可以在地獄火堡壘的破碎大廳中找到他們。$B$B如果你還想要賞金，就趕緊去殺了他們再回來。','虛空獵手瑪哈杜恩要求你殺死4名碎手百夫長。完成任務後返回撒塔斯城的貧民窟，找他領取獎賞。','','去找泰羅卡森林的虛空獵手瑪哈杜恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11365 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11365, 'zhTW', '[March of the Giants]', '[To the east, at Giants\' Run, rune-inscribed stone giants have started to migrate north toward Frostblade Peak. I know nothing of their goals, nor of their destination.$B$BThe glowing runes inscribed in the stone flesh of the giants guide them on their journey. Fell some of these giants.$B$BTake this pick with you and use it on the corpses of the runed stone giants. It will deactivate the runes. Once you\'ve tested enough giants, return to me with your findings.]', '[Sage Edan and Camp Winterhoof wants you to use the Runeseeking Pick on the corpses of 4 Runed Stone Giants.]', '', '去找嚎風峽灣的賢者伊丹。', '符文石巨人屍體已分析', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11366 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11366, 'zhTW', '[The Lodestone]', '[We must find what\'s luring the giants northwest, so we can stop them before they reach their destination.$B$BWhile the rune samples gave us some clues, the unknown runes worry me.$B$BWhen I visited Giants\' Run, I noticed a large broken tablet jutting from the ground where the northeastern part of the area met the snow at the foot of Frostblade Peak. Take this sample, compare the runes with the tablet, and see what you can learn about the identity of this lodestone.]', '[Sage Edan at Camp Winterhoof wants you to compare the Rune Sample with the Broken Tablet.]', '', '去找嚎風峽灣的賢者伊丹。', '將符文與破碎石板比對', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11367 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11367, 'zhTW', '[Demolishing Megalith]', '[Binder Murdis created Megalith to be a kind of keystone for the runed giants and to lead them in their mission. Defeating Megalith will leave them lost and without direction. I will ask Chieftain Ashtotem to divert some of our men as we move north and dedicate them to eliminating the last of the runed giants. Without their giants, the Iron Dwarves cannot stand against us.$B$BSearch the foothills of Frostblade Peak, north of Giants\' Run for Megalith and defeat him!]', '[Defeat Megalith and return to Sage Edan at Camp Winterhoof.]', '', '去找嚎風峽灣的賢者伊丹。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11368 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11368, 'zhTW', '懸賞:奎克米瑞之心', '我有個不尋常的任務。我接觸到一個來自異世界的有錢人，對於恐怖的東西特別有興趣。$B$B她尤其想要奎克米瑞之心。$B$B我聽說那個怪物有三顆心臟，不過一顆就足夠滿足我們的需求。據我所知，你可以在奴隸監獄的深水池中找到奎克米瑞。', '風之貿易者札令姆要你取得奎克米瑞之心。將這顆心帶回撒塔斯陰鬱城交給他以領取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11369 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11369,'zhTW','懸賞：黑色闊步者的卵','據說，贊加沼澤的所有沼澤行者都有一個共同的母體，那就是黑色闊步者。假如黑色闊步者死去，它曾產下的卵就會孵化出來，成為新的黑色闊步者。$B$B現在，有位買家對那些卵感興趣，據說她的動物園裡想要新增一隻新動物，以吸引遊客。$B$B如果你對我開出的賞金感興趣，就趕快去幽暗沼澤的黑色闊步者那裡搞來它的卵吧。','商人扎雷姆要求你取回一枚黑色闊步者的卵。將卵帶回撒塔斯城的貧民窟交給他，就能領取獎賞。$B$B該任務只能在英雄模式下完成。','','去找泰羅卡森林的商人扎雷姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11370 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11370, 'zhTW', '懸賞:督軍的論述', '很多人都知道納迦族中的督軍卡利斯瑞是個強大的戰士，卻很少人知道他把他的知識全都記錄下來。$B$B我有位顧客得知了此事，有很高的興趣想把論述拿到手。$B$B我想拜託你去盤牙蓄湖的蒸汽洞窟把那本書拿來給我。', '風之貿易者札令姆要你取得督軍的論述。將東西帶回撒塔斯陰鬱城交給他以領取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11371 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11371, 'zhTW', '懸賞:盤牙侍從', '瑪頓恩聆聽並且遵從，我現在希望你協助我。$B$B現在這是我的職責了，盤牙部族的侍從必須被毀滅。去那些陰暗潮濕的角落尋找他們，就在盤牙蓄湖的蒸汽洞窟中。$B$B我只接受他們終極的滅絕。', '虛空行者瑪頓恩要你殺死14名盤牙侍從。完成之後回到撒塔斯陰鬱城找他領取賞金。', '', '去找泰羅卡森林的虛空行者瑪頓恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11372 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11372, 'zhTW', '懸賞:伊奇斯的冠羽', '最近有個牛頭人向我接頭，她的丈夫最近獲選成為酋長。她想替他的頭飾增添一點花樣。$B$B她尤其想拿到卑鄙的鷹王伊奇斯的冠羽。$B$B你要是對我的賞金有興趣的話，可以前去奧齊頓的賽司克大廳。', '風之貿易者札令姆要你取得伊奇斯的冠羽。將東西帶回撒塔斯陰鬱城交給他以領取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11373 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11373, 'zhTW', '懸賞:薩法爾的奇妙護符', '今天我有個私人的任務要拜託你，當然酬勞與它的危險度相等。$B$B我的家族和奈薩斯王子薩法爾還有他的手下，很有點『淵源』。要是他配戴的護符落入我的手中，那就表示他已經被解決了。$B$B如果你對我提供的賞金有興趣的話，你可以前往他在奧齊頓，法力墓穴的老巢。', '風之貿易者札令姆要你取得薩法爾的奇妙護符。將東西帶回撒塔斯陰鬱城交給他以領取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11374 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11374,'zhTW','懸賞：主教的靈魂寶鑽','在奧金尼地穴中，那些人為了瞭解通靈魔法的真諦，正進行著一系列令人作嘔的實驗。無數無辜的靈魂在那裡受到了無止境的折磨與摧殘。$B$B我有一位客戶非常希望解放這些靈魂。我聽說這些靈魂被囚禁在一塊靈魂寶石之內，而這塊寶石就在大大主教瑪拉達爾的手上。$B$B立刻到地穴內找到他，把寶石搶回來吧。','商人扎雷姆要求你奪得主教的靈魂寶鑽。將寶鑽帶回撒塔斯城的貧民窟交給他，就能領取獎賞。$B$B該任務只能在英雄模式下完成。','','去找泰羅卡森林的商人扎雷姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11375 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11375, 'zhTW', '懸賞:莫爾墨的低語', '等我說完，也許你就不會接下這個任務了。$B$B我有個古怪的客人專門在研究死去的存在。謠傳說現在被稱為莫爾墨的東西摧毀了那個他原先存在的世界。教授對他的「低語」很感興趣，想知道莫爾墨是如何完成這項任務。$B$B你願意前往奧齊頓的暗影迷宮，把那個東西帶來給我嗎?', '風之貿易者札令姆要你取得莫爾墨的低語。把東西帶到撒塔斯陰鬱城交給他好換取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11376 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11376, 'zhTW', '懸賞:惡毒導師', '瑪頓恩聽說沒有人比暗影迷宮中的六臂女惡魔更殘酷了。$B$B前往奧齊頓吧，那這些惡魔給揪出來，全部殺光。$B$B如果這麼簡單的任務你都無法達成，那我們彼此也沒什麼話好說了。', '虛空行者瑪頓恩要你殺死3名惡毒導師。完成之後回到撒塔斯陰鬱城找他領取賞金。', '', '去找泰羅卡森林的虛空行者瑪頓恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11377 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11377,'zhTW','甜美的復仇','我正在給一些與眾不同的客人準備伙食。他們中有個傢伙在從斯克提斯飛來的途中被一頭巨大的卡利鳥撞了個嘴啃泥——他的腿嚴重骨折了。$B$B他們希望我能給他的康復聚會提供一點特別的食物：燉卡利鳥。$B$B我可以把我的烹鍋借給你，這樣你就可以用它來烹製美味了。這個食譜其實很簡單，不過你需要一根巨型卡利鳥的翅膀和一些遷躍獸漢堡。','貧民窟的巨石洛克希望你用他的烹鍋製作一些燉卡利鳥，完成之後回去找他。','','去找泰羅卡森林的巨石洛克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11378 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11378,'zhTW','懸賞：時空獵手的徽記','我的客戶很多，品位從最平凡最普通的直到最奇特最古怪的都有。而且呢，有些時候，他們會用你能找到的最奇特最古怪的東西去做一些最平凡最普通的事情。$B$B你看，比如說剛才這樁委託。我這位匿名的客戶想要得到時空獵手的徽記來裝飾他家的牆壁。$B$B嗯，你現在是否可以透過時光之穴回到過去的希爾斯布萊德丘陵，去幫我把那個所謂的戰利品給帶回來呢？','商人扎雷姆要求你取回時空獵手的徽記。將徽記帶回撒塔斯城的貧民窟交給他，就能領取獎賞。$B$B該任務只能在英雄模式下完成。','','去找泰羅卡森林的商人扎雷姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11379 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11379,'zhTW','超級美味燒烤','我正在嘗試創造一些充滿活力的東西。不過說實話，現在我更像是一個只會紙上談兵的地精，我已經失去了冒險的感覺。$B$B但你……讓我想起了我年輕的日子，一手握著劍，一手握著一口鍋子。準備去征服整個世界吧！$B$B我希望你能拿上我最喜愛的烹鍋去刀鋒山，把一些肋排和香脆蛇——已經煮熟的最棒的香料——放在深淵烈焰使者的屍體上烤一下，那可是唯一可以把它們烤透的東西。','貧民窟的巨石洛克希望你用他的烹鍋、兩份莫克納薩肋排和一份香脆蛇製作一些惡魔燒烤，完成之後回去找他。','','去找泰羅卡森林的巨石洛克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11380 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11380,'zhTW','魔法美味','你知不知道，我剛把魚和肉儲存起來，就有個人過來要求我做一份既可以讓他吃飽、又能讓他精神振奮的食物：魔法草莓大餐。$B$B不幸的是，魔法莓只生長在虛空風暴的生態圓頂裡。對了，虛靈對魔法莓有著特別的偏愛，所以風暴尖塔附近的魔法莓都被採光了。$B$B我只相信只有那些受過良好烹飪訓練的廚師才能採到最好的魔法莓，所以不要讓我失望！','貧民窟的巨石洛克要求你從虛空風暴的生態圓頂中收集15顆魔法莓，完成之後回去找他。','','去找泰羅卡森林的巨石洛克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11381 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11381,'zhTW','靈魂之湯','我感覺到了一股強烈的殺氣。我還從未收到過這麼多購買我的名菜——靈魂之湯的訂單。$B$B我一眼就能看出，你和我一樣醉心廚藝……那麼你願意幫我一把，順便賺點小錢嗎？$B$B過來，拿上我的烹鍋，收集一些裂蹄牛肉，並且我會讓你分享我的秘密。什麼讓我的湯如此大補？因為那不是雞肉——我在納格蘭的先祖之地烹飪它，讓它在那裡吸收了所有靈氣。','貧民窟的巨石洛克希望你用他的烹鍋製作一些靈魂之湯，完成之後回去找他。','','去找泰羅卡森林的巨石洛克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11382 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11382,'zhTW','懸賞：埃歐努斯的沙漏','我敢發誓，這個客戶一定是瘋了。你看，世上有許多值得你去追求的東西，但也有你絕對不該想的！$B$B現在我的這個客戶的腦子絕對絕對是進水，魔法冰川水！他竟然覬覦垂涎起埃歐努斯的沙漏了。$B$B對，你沒有聽錯，永永恆之龍的埃歐努斯！$B$B但是……但是……他付出了能把一個國王贖回來的錢，我又有什麼好說的？總之，去吧，到時光之穴的黑色沼澤去，把那沙漏給我取回來。','商人扎雷姆要求你奪得埃歐努斯的沙漏。將沙漏帶回撒塔斯城的貧民窟交給他，就能領取獎賞。$B$B該任務只能在英雄模式下完成。','','去找泰羅卡森林的商人扎雷姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11383 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11383,'zhTW','懸賞：裂隙領主','瑪哈杜恩知道你該去哪兒，瑪哈杜恩還知道你必須得去殺裂隙領主，但問題是，瑪哈杜恩不知道你什麼時候該去。$B$B我知道這話你不明白，不過傳來的命令就是這樣了。$B$B轉至時光之穴的黑色沼澤，一切就都會明白了。','虛空獵手瑪哈杜恩要求你殺死4名裂隙領主。完成任務後返回撒塔斯城的貧民窟，找他領取獎賞。','','去找泰羅卡森林的虛空獵手瑪哈杜恩。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11384 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11384, 'zhTW', '懸賞:扭曲分裂者的剪枝', '不久之前，一個卡多雷的女德魯伊交給我一項任務。當然，還有不少的金幣!$B$B顯然達納蘇斯方面希望能夠讓一個名為扭曲分裂者的秘法古樹復原。那棵巨樹現在陷入了恍惚或是腐化中，我不是很確定，但你可以在風暴要塞的波塔尼卡深處找到它。$B$B她說他們只需要一小段剪枝來讓它重新生長。', '風之貿易者札令姆要你取得扭曲分裂者的剪枝。帶到撒塔斯的陰鬱城交給他以換取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11385 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11385, 'zhTW', '懸賞:尋日導魔師', '風又再對瑪頓恩低語，隸屬於尋日者的導魔師今天就得被殺死。$B$B你可以在風暴要塞的波塔尼卡中找到他們。$B$B你想要賞金的話，就殺死那些導魔師。', '虛空行者瑪頓恩要你殺死6名尋日導魔師。完成之後回到撒塔斯陰鬱城找他領取賞金。', '', '去找泰羅卡森林的虛空行者瑪頓恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11386 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11386, 'zhTW', '懸賞:帕薩里歐的投映器', '我一直以為操縱者帕薩里歐使用魔法將他的影像在外域各處投射。很顯然我錯了。$B$B我最近的一個客人告訴我，血精靈使用一種特殊的機械裝置來和凱爾薩斯王子的投影溝通。就我所知，他們是從虛空風暴的薩希斯反叛者那邊取得的。$B$B我的客戶想要那個投映器。你何不去拜訪一下帕薩里歐?他就在風暴要塞的麥克納爾。', '風之貿易者札令姆要你取得帕薩里歐的投映器。帶到撒塔斯的陰鬱城交給他以換取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11387 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11387, 'zhTW', '懸賞:風暴要塞-熔爐毀滅者', '有些機械構裝生物在麥克納爾之中，瑪頓恩被告知它們必須被毀掉。$B$B前往風暴要塞，把那些風暴要塞-熔爐毀滅者給毀掉。$B$B然後你可以回來領取你的賞金。', '虛空行者瑪頓恩要你殺死5名風暴要塞-熔爐毀滅者。完成之後回到撒塔斯陰鬱城找他領取賞金。', '', '去找泰羅卡森林的虛空行者瑪頓恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11388 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11388, 'zhTW', '懸賞:史蓋力司卷軸', '今天的客人想找樣真的很罕見的東西。$B$B傳說先驅者史蓋力司是上古諸神的僕人。還說他有著一個巨大的卷軸記載著他們要如何支配宇宙生命的指示。$B$B目前的這位買家希望<他/她>能親自摸摸那個卷軸，當然<他/她>是讀不了上頭的文字的。$B$B到風暴要塞的亞克崔茲，把東西拿來給我，好嗎，$c?', '風之貿易者札令姆要你取得史蓋力司卷軸。帶到撒塔斯的陰鬱城交給他以換取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11389 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11389, 'zhTW', '懸賞:亞克崔茲哨兵', '亞克崔茲的哨兵們陷入瘋狂了。裡面的囚犯們行為全都失控了而其他的守衛會攻擊想幫忙的人。$B$B瑪頓恩聽見了虛空之風中的細語。它說消滅那些哨兵們。$B$B完成這項任務的話，今天的賞金就屬於你的了。', '虛空行者瑪頓恩要你解決5個亞克崔茲哨兵。完成之後回到撒塔斯的陰鬱城找他領取賞金。', '', '去找泰羅卡森林的虛空行者瑪頓恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11390 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11390, 'zhTW', '[I\'ve Got a Flying Machine!]', '[Well, what are you waiting for, there\'s work to be done!$B$BHere\'s the keys to our flying machine. Grab three sacks of relics and haul them up to the crane platforms on the north and south sides of Steel Gate.  I\'ll mark them for you.$B$BHurry up! We haven\'t got all day!]', '[The Steel Gate Chief Archaeologist wants you to transport 3 Sacks of Relics from the bottom of the site and take them to the platform on the north or south side of Steel Gate.$B$BUse the grappling hook on the flying machine to do this.$B$BReport back to him after you\'ve done so.]', '', '去找嚎風峽灣的鋼鐵之門首席考古學家。', '遺物袋已送達', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11391 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11391, 'zhTW', '[Steel Gate Patrol]', '[Eh? Yer back for another day\'s work?$B$BWell, alright, here\'s the keys. We don\'t need any haulin\' today, so just keep an eye out for anything suspicious, okay?$B$BI\'ve hooked her up with some rockets and a machine gun - just in case.]', '[You\'re Steel Gate\'s ace pilot now, so the Steel Gate Chief Archaeologist wants you to keep patrol around the dig site and fight off anything that attacks.$B$BReport back to him when you\'re done with your patrol.]', '', '去找嚎風峽灣的鋼鐵之門首席考古學家。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11392 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11392,'zhTW','召喚無頭騎士','許多悲傷蠟燭裝飾著這座南瓜祭壇。','將一根悲傷蠟燭插入翻過的泥土。','','去找血色修道院的翻過的泥土。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11393 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11393, 'zhTW', '', '', '[Overseer Irena Stonemantle has asked you to locate her fiance, Explorer Jaren.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11394 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11394,'zhTW','比魚人更惡臭……','有傳言說切米爾海岸埋藏著珍貴的古器，於是我跟隨探險隊來這裡調查實情。我原本以為海灘是魚人的地盤，但是當我看見這一切時，簡直不敢相信自己的眼睛！$B$B<探險者伸出頭來瞧了瞧四周。>$B$B天災軍團佔領了切米爾海岸，他們將魚人和其它生物變成了一具具的行屍走肉！$B$B$C，我們應該做點什麼。你能解決掉那些天災軍團的成員嗎？','探險者亞倫要你轉至切米爾海岸，在那裡殺死15名任意種類的天災軍團成員，完成任務後向他覆命。','','去凜風峽灣找切米爾海岸的探險者亞倫。','殺死切米爾海岸的天災軍團成員','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11395 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11395, 'zhTW', '[It\'s a Scourge Device]', '[The Scourge creature you just destroyed had this device held in its clutches. It has a jewel set into it which looks similar to the one that tops the scourging crystals.$B$BSurely, Explorer Jaren would like to have a look at this.]', '[Deliver the Scourge Device to Explorer Jaren on the Chillmere Coast.]', '', '去找嚎風峽灣的探險者賈倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11396 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11396,'zhTW','關閉護盾','瞧，控制器側面有個按鈕。我敢打賭，如果你離天災水晶夠近的話，就可以用控制器關閉它的護盾。接下來嘛，在護盾恢復之前摧毀水晶就行啦。$B$B$N，怎麼樣？你願意接受這項任務嗎？只要你順利地關閉護盾並摧毀水晶，就能得到一份很棒的獎勵。$B$B天災軍團瘋狂地將其它生物轉換成他們的同類，這是我們唯一能阻止他們的方法。','切米爾海岸的探險者亞倫要你摧毀3顆天災水晶。','','去凜風峽灣找切米爾海岸的探險者亞倫。','摧毀天災水晶','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11397 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11397, 'zhTW', '[And You Thought Murlocs Smelled Bad!]', '[I came here to investigate a rumor about a Scourge presence nearby. I expected murlocs along the coast down below, but I never thought I\'d see this!$B$BThe Scourge are down there, and they\'re changing murlocs, and anything else they can get their hands on, into the walking dead!$B$B$C, we will not suffer them to create more of their kind, especially not from murlocs! There is a ramp down to the beach just northwest of the camp. See to it that you deal with the Scourge in a timely fashion!]', '[Apothecary Anastasia has asked you to destroy 15 Scourge of any type along the Chillmere Coast. Return to her at the Apothecary Camp once you have done so.]', '', '去找嚎風峽灣的藥劑師安娜塔西亞。', '寒湖海岸的天災已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11398 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11398, 'zhTW', '[It\'s a Scourge Device]', '[The Scourge creature you just destroyed had this device held in its clutches. It has a jewel set into it which looks similar to the one that tops the scourging crystals.$B$BSurely, Apothecary Anastasia would like to have a look at this.]', '[Deliver the Scourge Device to Apothecary Anastasia at the Apothecary Camp.]', '', '去找嚎風峽灣的藥劑師安娜塔西亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11399 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11399, 'zhTW', '[Bring Down Those Shields]', '[Look at the button on the side of the controller here. I bet if you got close enough to one of those scourging crystals, you could use the controller to bring its shield down. Then it would simply be a matter of destroying the thing before its shield goes back up.$B$BBrave enough to hazard another trip down there, $N? I can guarantee a nice reward for you if you can bring down those shields and destroy the crystals.$B$BHow can you refuse if it means less Scourge, especially ones made from murlocs?]', '[Apothecary Anastasia at the Apothecary Camp has asked you to destroy 3 Scourging Crystals.]', '', '去找嚎風峽灣的藥劑師安娜塔西亞。', '鞭笞水晶已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11400 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11400,'zhTW','美酒節賽羊會','如果你將手上的戳印給波爾·凍石看看，就能從他那裡買到賽羊會的賽羊。','給丹莫洛美酒節會場入口處的波爾·凍石看看你手上的戳印。','','去找丹莫洛的波爾·凍石。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11401 AND `locale` = 'zhTW';
