INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11402,'zhTW','Clayton/s Quest: Extreme！！[日常]','克雷頓要你去殺死12只邪惡松鼠。','真的，去殺死邪惡的松鼠！',' ','Return to Clayton\'s Test Creature.','','','','',0);
