INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11558, 'zhTW', '危險的愛', '這種像傳染病的愛有些不對勁。這情形很噁心，而且當它降低了我們的警戒心，對所有人來說都是個威脅。$B$B我們有這麼多人民都已經陷入如此荒繆的行為已經夠糟了。但我想這甚至還散播到我們的守衛那裡了，他們是應該對這種事免疫的人。$B$B找一名我們的守衛，看看他們是否已經得到了這愚蠢的病。', '取得一張守衛發霉的卡片並帶給幽暗城的芬斯塔德·阿吉歐。', '', '去找奧特蘭克山脈的芬斯塔德·阿吉歐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11559 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11559, 'zhTW', '[Winterfin Commerce]', '[Now that you can speak with the Winterfin, it is time for you to let them get to know you. One of the best ways to do that is to conduct business with them.$B$BThe murlocs prize clams over any other object and their only surviving merchant is Ahlurglgr. If I were you, I\'d collect a handful of Winterfin clams and give them to him as a gift.$B$BThe clams can be found all over down in the trench, as well as across it in the Winterfin village and their caverns.]', '[Collect 5 Winterfin Clams and deliver them to Ahlurglgr at Winterfin Retreat.]', '', '去找北風凍原的阿魯咕嚕咕爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11560 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11560, 'zhTW', '[Oh Noes, the Tadpoles!]', '[Oh good, you\'re back!$B$BWhen the landslide at the village across the water exposed the caverns, a malevolent lobstrok, known as Claximus, came out of the caves and stole the Winterfin tadpoles away.$B$BSomething happened to all of the murlocs that followed him in there, and when they re-emerged, they were under his control.$B$B$C, you must swim across the waters and rescue the Winterfin tadpoles in the village and caverns.$B$BThe future of the Winterfin tribe depends upon you!]', '[King Mrgl-Mrgl has asked you to rescue 20 Winterfin Tadpoles. Return to him at Winterfin Retreat once you have done so.]', '', '去找北風凍原的莫戈莫戈大王。', '已救出冬鰭蝌蚪', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11561 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11561, 'zhTW', '[Them!]', '[Our brothers and sisters across the water are now our mortal enemies. They have kidnapped our tadpoles, driven us out of our village, and killed more of us than I can count.$B$BProve yourself, $r! Swim across the rift and slay them!$B$BDespite the favor that the new king has shown you, only then will we consider accepting you here. Fail to do so, and you might as well leave now and never return!]', '[Brglmurgl at Winterfin Retreat has asked you to kill 15 Winterfin murlocs. Any combination of warriors, oracles, and shorestrikers will do.]', '', '去找北風凍原的布爾格墨葛。', '冬鰭魚人已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11562 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11562, 'zhTW', '', '', '[King Mrgl-Mrgl has asked you to speak with Mrmrglmr at the northwest end of Winterfin Retreat.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11563 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11563, 'zhTW', '[Grmmurggll Mrllggrl Glrggl!!!]', '[If your pathetic little eyes were any good, you\'d see that we\'re being slaughtered by the orcas to the north in the bay!$B$BAssuming your precious night elf king wants his spare costume back, I think you\'ll do me a favor and bring back the head of the king of the orcas, Glrggl: he who swims against the tides of fate -- eradicating the hope of life for all those who hear the siren song of death upon the waves!$B$BBe quick about it, $r, Winterfin murlocs are losing their lives even as we waste time talking!]', '[Mrmrglmr wants you to return to him at Winterfin Retreat with Glrggl\'s Head.]', '', '去找北風凍原的姆姆戈莫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11564 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11564, 'zhTW', '[Succulent Orca Stew]', '[Word is, strange $r, that you might be going after the king of the orcas, Glrggl.$B$BThat\'s all fine and good, but if you want to taste the stew that makes life worth living, then you\'ll bring me back the succulent blubber of the orcas that swim in Glimmer Bay.$B$BHurry... I have quite a bit of cutting to do on this carcass if you want to reap the benefits of your efforts.]', '[Cleaver Bmurglbrm has tasked you with acquiring 7 Succulent Orca Blubber. Return with them to him at Winterfin Retreat.]', '', '去找北風凍原的斬擊者布墨格伯姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11565 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11565, 'zhTW', '[The Spare Suit]', '[Very well, your king\'s secret is safe with me as long as he continues to help us against our enemies.$B$BHere, take this to him. I cleaned it up nicely, though I have no idea why he needs a second disguise.$B$BMaybe he has something in mind for you?]', '[Return King Mrgl-Mrgl\'s Spare Suit to him at Winterfin Retreat.]', '', '去找北風凍原的莫戈莫戈大王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11566 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11566, 'zhTW', '[Surrender... Not!]', '[The time has come to put an end to this unnatural situation, $N. For the Winterfin murlocs to have a chance at a future, Claximus must die!$B$BI want you to take my spare murloc suit and enter the Winterfin Caverns under the pretext of surrender. With the white flag in hand, the murlocs won\'t attack you.$B$BYou\'ll find him in the southwestern most corner of the caverns. Once you get close enough, deal with Claximus. Bring me one of his claws as proof that the grisly deed has been done.]', '[King Mrgl-Mrgl at Winterfin Retreat has asked you to bring him a Claw of Claximus.]', '', '去找北風凍原的莫戈莫戈大王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11567 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11567, 'zhTW', '[The Ancient Armor of the Kvaldir]', '[I was on the vessel that was bringing in the armor. We\'d just boarded the ship and were headin\' back here when we were attacked by a Forsaken destroyer.$B$BThey boarded our ship, took all the booty for themselves, and then sunk her.$B$BThat was the last I\'d seen of that armor. If you want, you can take my bomber from Scalawag to the dreaded isle that the destroyer be docked. Talk to my woman, Alanya, outside. She\'ll get you on the bomber.$B$BIf you manage to find the stuff, don\'t you dare bring it back!]', '[Recover the Ancient Armor of the Kvaldir and deliver it to Orfus of Kamagua in the Howling Fjord.]', '', '去找嚎風峽灣的卡瑪廓的歐弗斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11568 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11568, 'zhTW', '[A Return to Resting]', '[<Orfus hands you a satchel.>$B$BWithin this satchel are the artifacts that you recovered. Locate the burial mounds of Shield Hill, far to the southeast, where the items were originally stolen from and return the artifacts. It is my hope that this gesture will quell the spirits that now haunt our hunting grounds.$B$BBe strong, $N...]', '[Use the Bundle of Vrykul Artifacts at the ransacked burial mounds of Shield Hill to return the Frozen Heart of Isuldof, the Shield of the Aesirites, the Staff of Storm\'s Fury and the Ancient Armor of the Kvaldir.$B$BReturn to Orfus of Kamagua at the Ancient Lift should you succeed.]', '', '去找嚎風峽灣的卡瑪廓的歐弗斯。', '艾瑟萊特之盾已歸還', '風暴之怒法杖已歸還', '已歸還伊蘇多夫的冰封之心', '已歸還卡瓦迪爾的遠古護甲', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11569 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11569, 'zhTW', '[Keymaster Urmgrgl]', '[I have to get out of these caverns! There\'s magic stuff seeping in from Coldarra, above, and affecting everyone\'s minds.$B$BI don\'t intend to be controlled like these others!$B$BKeymaster Urmgrgl is in the cave below and to the south. He holds the key to my cage. Get it from him and bring it back so that I can unlock my cage and get out of here.$B$BHurry!]', '[Glrglrglr inside the Winterfin Caverns has asked you to retrieve Urmgrgl\'s Key.]', '', '去找北風凍原的葛勒格勒格勒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11570 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11570, 'zhTW', '[Escape from the Winterfin Caverns]', '[The lock on my cage doesn\'t look too solid, but I\'m not foolish enough to try to leave without assistance.$B$BWill you help me safely get out of these caverns? There\'s no time to waste, $r.$B$BWhen you get back to the retreat, please let the king know that I\'m okay. He\'s sure to give you a reward.]', '[Escort Lurgglbr to safety and then report to King Mrgl-Mrgl at Winterfin Retreat with the good news.]', '護送魯格布爾至安全處', '去找北風凍原的莫戈莫戈大王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11571 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11571, 'zhTW', '[Learning to Communicate]', '[To help, you must learn how to speak the Winterfin dialect. We\'ll work with the forces of nature and magic to do that.$B$BTake this empty conch shell. At the bottom of the watery trench below exists Scalder, an elemental of air and watery fury.$B$BOnce she is defeated, use the conch upon her remains to capture her magical steam. Return the full conch to me, and I\'ll imbue my knowledge of the Winterfin tongue into you.$B$BLuckily, a friend taught me a water breathing spell, which I will cast upon you.]', '[King Mrgl-Mrgl has given you a conch to use upon Scalder\'s remains. Return The King\'s Filled Conch to him at Winterfin Retreat.]', '', '去找北風凍原的莫戈莫戈大王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11572 AND `locale` = 'zhTW';
