INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11576, 'zhTW', '[Monitoring the Rift: Cleftcliff Anomaly]', '[Greetings, $r. I am Garren of Dalaran.$B$BNot long ago, the rift was a peaceful place - geothermally speaking at least.$B$BRecently though, earthquakes have occurred with alarming frequency and scars in the earth have appeared, exposing unique energy fields of chaotic power.$B$BMy mission here is to chart and monitor these anomalies. My instruments indicate that another has appeared on the cliff face to the southwest.$B$BTake this device with you and use it when you locate the new disruption.]', '[Garren on Amber Ledge wants you to use the Arcanometer at the Cleftcliff Anomaly.]', '', '去找北風凍原的圖書管理員加倫。', '已取得裂岩崖異常讀數', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11577 AND `locale` = 'zhTW';
