INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11582, 'zhTW', '[Monitoring the Rift: Sundered Chasm]', '[Did you feel that?! That was just an aftershock... you should\'ve been here a few minutes ago!$B$BI\'m afraid I must call upon your services again. My instruments indicate that there is an immense disruption just west of here, far beneath the water\'s surface.$B$BJust as before, I need you to take the arcanometer and capture the anomaly\'s data.$B$BI\'ll cast a spell that will enable you to breathe underwater. If it wears off before you find it, come let me know and I\'ll renew its effects.]', '[Garren at Amber Ledge wants you to use the Arcanometer at the Sundered Chasm anomaly and return to him with the readings.]', '', '去找北風凍原的圖書管理員加倫。', '已取得裂谷讀數', '', '', '', 0);
