INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11586, 'zhTW', '', '', '[Speak with Garrosh Hellscream in Warsong Hold.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11587 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11587, 'zhTW', '[Prison Break]', '[Greetings, $c. I am Donathan, a loyal representative of Dalaran.$B$BForgive my abruptness, but we find ourselves in the midst of a crisis. Mages all across Azeroth are being abducted and I have been authorized to conscript anyone able to assist in the unraveling of this mystery.$B$BThe camp just south of ours is where our investigation begins. I call upon you to rescue one of the imprisoned mages held there. You must obtain a key from one of the mage hunters and use it to open an arcane prison.]', '[Librarian Donathan on Amber Ledge wants you to collect the Beryl Prison Key from one of the Beryl Mage Hunters at Beryl Point and use it to release a trapped mage from an arcane prison.]', '', '去找北風凍原的圖書管理員唐納森。', '已救出奧術囚犯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11588 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11588,'zhTW','重複利用','阻止艾胡恩前來艾澤拉斯並引起一場元素大戰！','摧毀位於黑暗深淵內的元素艾胡恩。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11589 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11589,'zhTW','重複利用','阻止艾胡恩前來艾澤拉斯並引起一場元素大戰！','摧毀位於黑暗深淵內的元素艾胡恩。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11590 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11590, 'zhTW', '[Abduction]', '[$n, we have a situation.$B$BI\'ve just learned that one of our archmages en route from Dalaran has gone missing. Naturally, we suspect the mage hunters are behind her disappearance.$B$BTime is clearly of the essence. We must know what has become of Lady Evanor at once if we are to have any hope of rescuing her.$B$BTake this device. Return to Beryl Point and use it on a Beryl sorcerer when he is near death. It should bind him long enough for you to bring him here for questioning.]', '[Donathan wants you to use the Arcane Binder on a wounded Beryl Sorcerer at Beryl Point and return to Amber Ledge with him.]', '', '去找北風凍原的圖書管理員唐納森。', '被俘的碧藍術士', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11591 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11591, 'zhTW', '', '', '[Speak with Grunt Ragefist at Steeljaw\'s Caravan.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11592 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11592, 'zhTW', '[We Strike!]', '[One of your orcs named Steeljaw tried to save some time by taking a shortcut through our burial grounds. This had better not be how your Horde normally acts, $r, or you will find the taunka to be the end of you!$B$BBut, you look as if you want to help fix this situation. Good!$B$BSteeljaw\'s cursed spirit now haunts this place and disturbs the remains of my ancestors. We must put an end to him!$B$BIf we live through this, tell your Overlord Bor\'gorok at the outpost to the north.$B$BAre you with me?]', '[Help Longrunner Proudhoof and his Warsong raiders to survive the assault upon Steeljaw\'s Caravan and finish off the spirit of Force-Commander Steeljaw.$B$BIf successful, report to Overlord Bor\'gorok at Bor\'gorok Outpost.]', '已成功協助長跑者傲蹄的攻勢', '去找北風凍原的霸主博格洛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11593 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11593, 'zhTW', '[The Honored Dead]', '[Our fallen deserve a hero\'s funeral, but we cannot bury them here on sacred taunka ground.$B$BI\'ll not ask you to drag their bodies back here, but take this and head further into the cemetary.  When you come across our dead caravan guards and workers, put them to the torch.$B$BHonor our dead, $c!]', '[Grunt Ragefist at Steeljaw\'s Caravan has asked you to use Ragefist\'s Torch to burn any combination of 10 Dead Carvan Guards and Workers.]', '', '去找北風凍原的蠻兵怒拳。', '已焚燒陣亡的商隊護衛與工人', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11594 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11594, 'zhTW', '[Put Them to Rest]', '[Force-Commander Steeljaw\'s idiocy caused this mess. What was he thinking taking a caravan through a taunka burial mound?$B$BStill, what\'s done is done. Now it is up to us to deal with the consequences.$B$BOverlord Bor\'gorok asked me to help Longrunner Proudhoof in any way that I can. The longrunner has asked that we lay to rest the spirits of his ancestors.$B$BWhat do you say, $c? Are you $g男子漢：女強人; enough to handle such a simple task?]', '[Put 20 taunka spirits, either Ghostly Sages or Risen Longrunners, to rest and then report back to Grunt Ragefist at Steeljaw\'s Caravan.]', '', '去找北風凍原的蠻兵怒拳。', '陶爾金之靈已安息', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11595 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11595, 'zhTW', '', '', '[Report to Overlord Razgor at the hut on the south side of Warsong Hold.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11596 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11596, 'zhTW', '', '', '[Report to Overlord Razgor at the hut on the south side of Warsong Hold.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11597 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11597,'zhTW','戰歌要塞的防禦','我們似乎總是在最糟糕的情形下相遇呢，甲蟲之王。自從我們上一次見面以後，你還一直在拯救世界嗎？$B$B<薩魯法爾輕聲笑了起來。>$B$B不管我們年輕的指揮官怎麼說，北裂境非常需要你的説明。$B$B如果能有一打像你這麼強大的士兵，我們現在已經在奧格瑪舒服地烤火了。$B$B去向戰歌要塞南門外的拉茲格爾大王報導吧。','向戰歌要塞南方小屋裡的拉茲格爾大王報到。','','向霸王瑞茲葛回報，他就在戰歌堡外的南方主要通道。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11598 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11598, 'zhTW', '[Taking Back Mightstone Quarry]', '[While Warsong is protected by 10 feet of steel and stone on all sides, this quarry is soft and primed for attacks by the Nerubians.$B$B<Razgor points west.>$B$BBeyond this quarry stand thousands of Scourge, awaiting orders to attack. Should the Nerubians take down our inner defenses, we will be overrun by the undead legions of Arthas.$B$BWe can\'t let that happen - which is why you\'re going on the offensive and slaughtering the Nerubians in the quarry.$B$BBlood and thunder, soldier! Take \'em both with you.]', '[Overlord Razgor at Warsong Hold wants you to kill 15 Nerub\'ar Nerubians.]', '', '去找北風凍原的霸主瑞茲葛。', '納魯巴已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11599 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11599, 'zhTW', '', '', '[Look for William Allerton inside the Farshire mine.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11600 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11600, 'zhTW', '[The Late William Allerton]', '[William\'s neck has been cut by a sharp object.$B$BFurther inspection reveals a single clue to bring to Leryssa - an enlistment card bearing the name of William Allerton.]', '[Bring the Enlistment Card to Leryssa at Valiance Keep in Borean Tundra.]', '', '去找北風凍原的蕾瑞莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11601 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11601, 'zhTW', '', '', '[Speak to James Deacon at the inn in Valiance Keep.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11602 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11602, 'zhTW', '[Cutting Off the Source]', '[Aerial reconnaissance of the quarry reports that the Nerubians are storing their eggs on the scaffolding surrounding the base. Smart beasts these are... They\'re keeping the eggs high and dry, away from the epicenter of conflict.$B$BYou\'re going to have to go back out there and track down their eggs. Find \'em, smash \'em, and trash \'em.$B$BEach egg destroyed means twenty less Nerubians feeding on our corpses.$B$B]', '[Overlord Razgor at Warsong Hold wants you to destroy 10 Nerub\'ar Egg Sacs.]', '', '去找北風凍原的霸主瑞茲葛。', '', '', '', '納魯巴卵囊已摧毀', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11603 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11603, 'zhTW', '[In Wine, Truth]', '[The military was all that old man Colburn had.  After he retired, he still clung to it like a lifeline.$B$BHe knows the name of every general, unit, brigade, detachment... you name it.  He\'s the man you need.$B$BProblem is, his mind is scarred.  He won\'t talk to anyone unless he gets his Kul Tiras wine.  Takes him back to the times he was a marine.$B$BI haven\'t received a shipment in months.  The last merchant ship out of Kul Tiras sunk northeast of here.  See if you can salvage a bottle to bring Colburn.]', '[Salvage a bottle of Kul Tiras Wine from the underwater shipwreck northeast of Valiance Keep and bring it to Old Man Colburn in the Valiance Keep inn.]', '', '去找北風凍原的老人寇爾本。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11604 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11604, 'zhTW', '', '', '[Find the prison inside Inner Hold in Valiance Keep and speak to the deserter.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11605 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11605, 'zhTW', '[The Honored Ancestors]', '[<A distant voice echoes in your head as you regard the stone statue.>$B$BDo not be startled, stranger. I am Elder Atkanok, an ancient ancestor of the tuskarr people, a skilled craftsman in my own time and the guardian of this quarry for centuries.$B$BThe quarry has been overrun, leaving many statues unfinished while the ancestors\' spirits wander the world. Will you aid me in righting this wrong?$B$BFirst, I must know the names of these wandering ancestors. Look for the markers near their statues.]', '[Elder Atkanok outside Coldrock Quarry wants you to identify the statues of Elder Kesuk, Elder Sagani, and Elder Takret.]', '', '', '已辨識長老凱蘇克', '已辨識長老薩加尼', '已辨識長老塔克瑞特', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11606 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11606, 'zhTW', '[Patience is a Virtue that We Don\'t Need]', '[We can kill all the Nerubians that we see and destroy all the eggs that we find, but those things won\'t stop coming until we blow their tunnels and passageways up. Of course, we can\'t do that without some heavy grade munitions. Unfortunately, most of our stockpile is being used up by the goblins and blacksmiths for our siege tanks and weaponry.$B$BWe do happen to have a pretty good supply of the stuff out in Mightstone Quarry - underneath all the Nerubian crap. You\'ll just have to go out and get it for me.]', '[Quartermaster Holgoth at Warsong Hold wants you to recover 15 crates of Warsong Munitions.]', '', '去找北風凍原的軍需官侯加斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11607 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11607, 'zhTW', '[The Lost Spirits]', '[In the attack on the quarry, the shaman and craftsmen working here were slain. The violence threw the spirit world into utter chaos and we\'ll be unable to guide the ancestors home unless we find a way to soothe the spirits of the murdered.$B$BThe aggressors themselves pay no heed to the spirits, but their companions, the beryl hounds, sense the spirits and hold them in thrall.$B$BKill the beryl hounds, and using the raw energy left behind, break the imprisonment of the spirits of the innocent.]', '[Elder Atkanok, on the outskirts of Coldrock Quarry, wants you to free the spirits of 3 Kaskala Craftsmen and 3 Kaskala Shaman.]', '', '', '卡斯卡拉工匠之靈已釋放', '卡斯卡拉薩滿之靈已釋放', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11608 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11608, 'zhTW', '[Bury Those Cockroaches!]', '[North, south, east and west. Those are the locations that you should be concerned about. Surrounding this fortress, within Mightstone Quarry, are four perfectly situated Nerub\'ar sinkholes.$B$B<Holgoth hands you a bundle.>$B$BBe very careful with that package, $N. Mishandle it and you\'ll be dog meat.$B$BInside the bundle are seaforium depth charges. Get to each of those Nerub\'ar sinkholes and plant a depth charge at their center point. If all goes well, the tunnels will collapse.$B$BGet a move on!]', '[Quartermaster Holgoth at Warsong Hold wants you to use the Seaforium Depth Charge Bundle to destroy the Nerub\'ar sinkholes to the south, east, west and north of Warsong Hold.]', '', '去找北風凍原的軍需官侯加斯。', '南方納魯巴坑洞已摧毀', '東方納魯巴坑洞已摧毀', '西方納魯巴坑洞已摧毀', '北方納魯巴坑洞已摧毀', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11609 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11609, 'zhTW', '[Picking Up the Pieces]', '[With the spirits of the murdered craftsmen and shaman at rest, the way is clear for us to complete the ceremonies interrupted by the attack. You must perform a role traditionally reserved for a tuskarr shaman, and you must possess all the necessary ritual items.$B$BThere is no time to craft new ones, so you will need to scour the quarry for those left by the victims of the attack. Handle these objects with care, $N, for some are centuries old. You may need to wrest them from the hands of the invaders.]', '[Bring 6 Tuskarr Ritual Objects to Elder Atkanok, who stands outside Coldrock Quarry.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11610 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11610, 'zhTW', '[Leading the Ancestors Home]', '[With your help, the ancestor spirits can now be guided to their rightful homes, the statues lovingly prepared by Kaskala\'s craftsmen and shaman.$B$BThe ceremonies for these ancestors were interrupted during the attack on the quarry, and you will need to complete them. Take with you the objects that you recovered from the quarry, stand in front of the statues with the name markers, and recite this chant.$B$B<Words in a strange language flood your head, but you have no difficulty recalling them.>]', '[Elder Atkanok wants you to guide the spirits of Elder Kesuk, Elder Sagani, and Elder Takret to their stone monuments.]', '', '', '長老凱蘇克的儀式已完成', '長老薩加尼的儀式已完成', '長老塔克瑞特的儀式已完成', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11611 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11611, 'zhTW', '[Taken by the Scourge]', '[<Mortuus sighs.>$B$BPeons... We may as well post up a sign offering the Nerub\'ar a free meal.$B$BSee, the problem with a peon is that: (1) they\'re dumber than dirt; and (2) they\'re weaker than a leper gnome. Of course they\'re the first to be taken by the Scourge!$B$BThis puts me in a bit of a predicament, you see. Without peons, manual labor comes to a halt. No peons, no construction.$B$BFind and release my peons, $r. If they\'re alive, you\'ll find \'em spun up in webbing throughout Mightstone Quarry.$B$B]', '[Foreman Mortuus at Warsong Hold wants you to free 5 Warsong Peons.]', '', '去找北風凍原的工頭莫吐斯。', '戰歌苦工已釋放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11612 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11612, 'zhTW', '[Reclaiming the Quarry]', '[You\'re a welcome sight, $c. My name is Etaruk, and I used to be a craftsman here at the Coldrock Quarry.$B$BMy companions and I were preparing a new set of statues for their last set of rites when we saw those mysterious blue platforms come flying over the plateau.$B$BWhen they landed, the mages they carried swarmed the quarry, murdering my fellows and plundering the quarry. If we don\'t stop them, they\'ll destroy our statues and make off with our artifacts. Will you help me defeat the invaders?]', '[Etaruk, camped near the entrance to the Coldrock Quarry, wants you to kill 12 Beryl Treasure Hunters.]', '', '去找北風凍原的伊塔魯克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11613 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11613, 'zhTW', '[Karuk\'s Oath]', '[They call themselves the Kvaldir.  My people have legends about them; we call them the tuk-hariq - walkers of the fog.$B$BMy village was destroyed by these giant mist-men.  Everyone I knew was slain, including my father Ariut.$B$BBy tuskarr law I must seek retribution against those who shed my kin\'s blood.$B$BI am but a fisherman and I\'ve not yet passed the test of manhood... I cannot stand toe-to-toe with the vile Kvaldir.$B$BIf you were to carry out my blood duty for me, I will be in great debt to you.]', '[Karuk wants you to slay 6 Skadir Raiders and 5 Skadir Longboatsmen.]', '', '去找北風凍原的卡魯克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11614 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11614, 'zhTW', '', '', '[Find Shadowstalker Luther in Mightstone Quarry.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11615 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11615, 'zhTW', '[Nerub\'ar Secrets]', '[You skim through the pages of the book, looking for anything of importance. On the last page you discover what appears to be frantic scribbling:$B$BNecrolords. At least a dozen by my count.$B$BFarms to west being used as some sort of horrible spawning glade for Scourge.$B$BRow upon row of victims.$B$BI think they\'re on to me. Made a dash for the hold. I won\'t be captured alive.$B$BDreadvenom hemotoxin. If they decide to bite into me, they\'ll be in for a surprise.$B$BTake this information back to Barthus.]', '[Take Luther\'s Journal to Shadowstalker Barthus at Warsong Hold.]', '', '去找北風凍原的巡影者巴素司。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11616 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11616, 'zhTW', '[Message to Hellscream]', '[<Barthus tears out the last page and rolls it up.>$B$BTake this to Hellscream at once! In the meantime, I\'m going to send a team to scout out the farms.$B$BBe sure to tell Hellscream that we\'re going to need reinforcements. ]', '[Take Barthus\'s Note to Garrosh Hellscream at Warsong Hold.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11617 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11617, 'zhTW', '[Hampering Their Escape]', '[I\'m sure you\'ve seen those blue and white platforms hovering over the quarry. They\'re the transportation the mage hunters used to land their forces here, and now they\'re loading them up with our artifacts and fragments of our statues.$B$BWe must stop them before they leave the quarry.$B$BThe small creatures digging in the quarry carry explosives. Take them and use them to destroy the three floating platforms. The leader keeps watch from a fourth, grounded platform, but we\'ll deal with him afterward.]', '[Etaruk, outside the Coldrock Quarry, wants you to destroy the North Platform, the East Platform, and the West Platform.]', '', '去找北風凍原的伊塔魯克。', '東方平台已摧毀', '北方平台已摧毀', '西方平台已摧毀', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11618 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11618, 'zhTW', '', '', '[Seek out Shadowstalker Ickoris at the Warsong Farms Outpost west of Warsong Hold.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11619 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11619, 'zhTW', '[Gamel the Cruel]', '[My own father was slain by the leader of this raiding party, Gamel the Cruel.  He has made his abode inside a cave on the beach.$B$BYou\'ve dealt with his men already.  Finish what you\'ve started, $N.  Avenge my father and I will share with you what little I still have.]', '[Karuk wants you to defeat Gamel the Cruel at Riplash Strand.]', '', '去找北風凍原的卡魯克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11620 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11620, 'zhTW', '', '', '[Look for Veehja at the Shrine of Scales on Riplash Strand.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11621 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11621, 'zhTW', '萊維羅希的石板', '你清理了石板上的刻痕，找尋任何你看得懂的內容。你終於找到了以下的片段：「迷霧之子將要收集一千個靈魂，以獻給居於晦暗深海中的，喚醒他的特使。」卡魯克或許會對這個消息感興趣。', '把你在石板上找到的訊息告訴卡魯克。', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11622 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11622, 'zhTW', '裂鞭的秘密', '或許有人能夠解開這個謎團，$r。謠傳科瓦迪爾人讓一些納迦女祭司苟活下來，關在神殿中。高階女祭司薇迦一定很樂意把那些科瓦迪爾不速之客給趕走。或許她能告訴你更多石板文字的意義。', '在北風凍原的裂鞭遺跡找到薇迦。', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11623 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11623, 'zhTW', '[A Visit to the Curator]', '[The leader of the mage hunter forces is a fearsome creature called Curator Insivius. My people have hunted the beasts of the seas and land for countless generations, but I\'ve never seen anything like this curator before.$B$BHe\'s landed one of those flying disks on the upper rim of the quarry and oversees the operation from there. $N, I can only believe the ancestors themselves sent you to my rescue and I hope you will help me drive the mage hunters from this quarry once and for all.]', '[Etaruk, on the outskirts of the Coldrock Quarry, wants you to kill Curator Insivius.]', '', '去找北風凍原的伊塔魯克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11624 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11624, 'zhTW', '', '', '[Speak with Imperean at the Ruins of Eldra\'nath.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11625 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11625, 'zhTW', '[The Trident of Naz\'jan]', '[Five hundred years ago, Azshara imprisoned a being named Leviroth in the waters below.  Now these barbarians seek to undo our queen\'s work!$B$BThey took over our city and began to sacrifice my brethren to awaken him!  When they ran out of naga, they began to take tuskarr.  Their spirits will know no peace!$B$BI will help you, for it will go a long way towards quelling my vengeance.  Their captain, Ragnar, dwells deep inside northeastern Riplash.  He has in his possession a golden trident.  Bring it to me!]', '[Veehja in Riplash wants you to go to the far northeastern end of the Riplash Ruins.  Once there slay Ragnar Drakkarlund and obtain the Trident of Naz\'jan from him.]', '', '去找北風凍原的薇迦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11626 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11626, 'zhTW', '[The Emissary]', '[Raj Naz\'jan was the emperor of Riplash when Leviroth was imprisoned.  Azshara herself blessed his trident so it would slay the beast should it ever escape.$B$BNow you wield it, $r.  As much as it disgusts me, I will have my revenge on these barbaric giant-men.$B$BTake the trident to the depths beneath Riplash.  You will find Leviroth below an iceberg closest to northern Riplash.$B$BDrive the trident into his flesh and slay him!  Return to whomever sent you when you\'re done; I wish to see no more of you.]', '[Find Leviroth in the waters below the iceberg floating among the northern edge of Riplash Ruins.  Use the Trident of Naz\'jan to slay him and return to Karuk to the north of Riplash Strand.]', '', '去找北風凍原的卡魯克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11627 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11627, 'zhTW', '[Boiling Point]', '[Ah, it is information that you crave: the whereabouts and condition of your \'farseer\'. He did not see so far as to avoid the trouble which befell him.$B$BNevertheless, I will give you the means to acquire the knowledge. But first, you will do some things for me.$B$BNo doubt you have seen the war between fire and water to the south. Simmer keeps boiling Churn\'s pool, and the two have been battling for ages.$B$BGo to the Charred Rise and Blistering Pool, and convince each of them to stop their bickering.]', '[Imperean wants you to beat Simmer and Churn into submission.  Return to her at the Ruins of Eldra\'nath when they have submitted.]', '', '去找北風凍原的英波里安。', '希默爾已臣服', '邱恩已臣服', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11628 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11628, 'zhTW', '[Shrouds of the Scourge]', '[To the northeast looms the Temple City of En\'kilah, the Scourge\'s seat in Borean Tundra. From behind its walls, the Scourge commander has sent his Nerubians to surround us.$B$BRemaining on the defensive would doom my people, but my advisors differ in their strategies. Durm would charge in blindly, while Sage Aeire favors stealth.$B$BThe Temple City has blighted the nearby lands and the native creatures. Aeire believes the pelts of the scourged mammoths can serve as a cloak that may hide an infiltrator.]', '[Chieftain Wintergale at Taunka\'le Village wants you to bring him 5 Scourged Mammoth Pelts.]', '', '去找北風凍原的冬風酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11629 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11629, 'zhTW', '[Return to the Spirit Talker]', '[You have done what was asked, and now I give you that which you desire.$B$BDeliver this primal to the spirit talker back at your Bor\'gorok Outpost. If she is wise, she will know a ritual to gain you the information which you seek.]', '[Deliver Imperean\'s Primal to Spirit Talker Snarlfang at Bor\'gorok Outpost.]', '', '去找北風凍原的靈語者嗥牙。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11630 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11630, 'zhTW', '[The Bad Earth]', '[By curing the hides with the blighted earth outside the Temple City, Sage Aeire believes she can create a cloak which will cause most of the Scourge minions to ignore your presence. You should blend right in, she says.$B$BShe\'d best be correct. It\'s our only chance to gather information and plan our counterattack.$B$BYou should be able to find the earth she needs poking in the areas to the south and west of the fortress. Bring it to me when you\'ve finished gathering it.]', '[Bring 8 clods of Scourged Earth to Chieftain Wintergale at Taunka\'le Village.]', '', '去找北風凍原的冬風酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11631 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11631, 'zhTW', '[Vision of Air]', '[Here, $N, I\'ve attuned the primal to you.$B$BOpen your soul to it in the presence of my totem of air and concentrate upon the fate of Farseer Grimwalker.$B$BThe spirit of the wind touches all; with any luck you will be granted a vision.]', '[Use Imperean\'s Primal to perform a ritual at Snarlfang\'s Totem at Bor\'gorok Outpost to gain information concerning Farseer Grimwalker.$B$BAfterward, speak with Spirit Talker Snarlfang.]', '', '去找北風凍原的靈語者嗥牙。', '已占卜先知格林渥克的命運', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11632 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11632, 'zhTW', '[What the Cold Wind Brings...]', '[You hold the carapace fragment of Ith\'rix the Harvester and realize that this is only the beginning. Even now you sense that victory is fleeting. Surely the Lich King has a thousand more beasts like Ith\'rix, waiting to be unleashed upon the Horde.$B$BTake your trophy and present it to High Overlord Saurfang, inside Warsong Hold. He should be notified of your victory over a powerful Scourge agent.]', '[Take Ith\'rix\'s Hardened Carapace to High Overlord Saurfang at Warsong Hold.]', '', '去找北風凍原的薩魯法爾霸王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11633 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11633, 'zhTW', '[Blending In]', '[Sage Aeire has finished the shroud. Take it with you and travel to the Temple City of En\'kilah. Don the cloak within the city\'s bounds to hide yourself from most of the Scourge there. This will be our best opportunity to gather information about the enemy\'s fortifications and leaders.$B$BWhile wearing the cloak, scout the three large spires on the grounds of the city. While the shroud will shield you from most of the Scourge, the En\'kilah abominations will be able to find you if you get too close.]', '[Chieftain Wintergale at Taunka\'le Village wants you to wear the Imbued Scourge Shroud in the Temple City of En\'kilah and scout the Spire of Blood, the Spire of Pain, and the Spire of Decay.]', '', '去找北風凍原的冬風酋長。', '已偵察腐朽尖塔', '已偵察血之尖塔', '已偵察痛苦尖塔', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11634 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11634, 'zhTW', '', '', '[Report to Wind Master To\'bor at Warsong Hold.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11635 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11635, 'zhTW', '', '', '[Speak with Farseer Grimwalker\'s Spirit inside of Magmoth.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11636 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11636, 'zhTW', '', '', '[Talk to Yanni at Warsong Hold to arrange safe travel to the coast. Speak to Annihilator Grek\'lor once you arrive at Garrosh\'s Landing.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11637 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11637, 'zhTW', '[Kaganishu]', '[After my small force of grunts were killed, I was dragged down here and ritually murdered. The snobold who did this is known as Kaganishu.$B$BThough you have vanquished his shaman helpers, my spirit is still tethered to this place. After he slew me, he created a fetish from my body, which anchors me here. Kaganishu is using it to learn all that I know of shamanism.$B$BYou must retrieve the fetish from him and use it upon my spirit. Kaganishu is nearby in the caves.$B$BOnly then will I truly be free.]', '[Retrieve Kaganishu\'s Fetish and use it upon Farseer Grimwalker\'s Remains.$B$BYou will need to give the fetish to Farseer Grimwalker\'s Spirit inside of Magmoth.]', '', '', '已釋放先知格林渥克', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11638 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11638, 'zhTW', '[Return My Remains]', '[$N, now that my spirit has been freed would you do me the honor of returning my remains to Spirit Talker Snarlfang? They lay upon the ground beneath me.$B$BI sense that the spirit talker is still at Bor\'gorok Outpost to the west where last I saw her.]', '[Deliver Farseer Grimwalker\'s Remains, which are resting below his spirit, to Spirit Talker Snarlfang at Bor\'gorok Outpost.]', '', '去找北風凍原的靈語者嗥牙。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11639 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11639, 'zhTW', '[Revenge Upon Magmoth]', '[The overlord refuses to allow the shaman to heal my wounds. He says that it will be a good lesson for me and give me time to reflect upon my failure.$B$BBut you could get revenge for me and the others who fell at Magmoth!$B$BI know that the spirit talker wants you to go in there to save the farseer.$B$BIt\'s just to the east. Go, $c... go slay the magnataur and their snobold servants. Regain the outpost\'s honor!]', '[Kill 10 Magmoth Shaman, 5 Magmoth Foragers, 3 Magmoth Crushers, and 3 Mates of Magmothregar. Then, return to Ortrosh at Bor\'gorok Outpost.]', '', '去找北風凍原的甌爾卓希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11640 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11640, 'zhTW', '[Words of Power]', '[Within the spires you described dwell the main lieutenants of the Scourge leader, the high priests. Not only do they command the Scourge forces, but they hold the key to the necropolis above, and their master.$B$BAn endless stream of Scourge minions will overrun us if we can\'t find and defeat their leader. I cannot leave my people defenseless, however much Durm might want to bring the fight to the enemy. It falls to you, $N, to slay the high priests and take the scrolls they hold.]', '[Bring High Priest Naferset\'s Scroll, High Priest Talet-Kha\'s Scroll, and High Priest Andorath\'s Scroll to Chieftain Wintergale at Taunka\'le Village.]', '', '去找北風凍原的冬風酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11641 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11641, 'zhTW', '[A Courageous Strike]', '[From the beginning, I\'ve counseled that Chieftain Wintergale should assemble our mighty warriors and attack our enemy at their base. My advice has fallen on deaf ears and he has proven that he\'d rather tip-toe around according to Sage Aeire\'s plans.$B$BI\'ll wait no longer. If Chieftain Wintergale is too cowardly to send our warriors into battle, perhaps you\'d be willing to show him that a direct attack can succeed. Storm the Temple City of En\'kilah and slay all in your path, $N.]', '[Slay 15 En\'kilah Ghouls and 5 En\'kilah Necromancers and report back to Durm Icehide at Taunka\'le Village.]', '', '去找北風凍原的德姆‧冰隱。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11642 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11642, 'zhTW', '', '', '[Speak with Mobu at Garrosh\'s Landing.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11643 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11643, 'zhTW', '[Mobu\'s Pneumatic Tank Transjigamarig]', '[These wrenches are useless, buddy. I need my pneumatic tank transjigamarig to get these things up and running! Unfortunately, I left it at my old digs, on the other side of this landing. It\'s the beat down hut next to the stables. You\'re gonna have to go and get it for me, because I sure as hellfire am not going to go anywhere near the mist.$B$BOh yea, buddy, watch out for the mist. The mist is what tore up these shores.$B$B]', '[Mobu at the Coast of Echoes in the Borean Tundra wants you to recover his Pneumatic Tank Transjigamarig.$B$B]', '', '去找北風凍原的莫布。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11644 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11644, 'zhTW', '[Super Strong Metal Plates!]', '[I need metal to patch these tanks up! Super strong metal plates can be found scattered about all across Garrosh\'s Landing and at the bottom of the bay.$B$BJust be careful when you\'re out there searching for plates. The mist is... um... AGGRESSIVE! The mist is what took out the landing and the adjoining tuskarr town. Poor little tuskarr...]', '[Mobu at the Coast of Echoes in the Borean Tundra wants you to collect 10 Super Strong Metal Plates.]', '', '去找北風凍原的莫布。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11645 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11645, 'zhTW', '[Dirty, Stinkin\' Snobolds!]', '[Those dirty, stinkin\' snobolds... they stole all of my supplies!$B$BWhat\'s a snobold you ask? It\'s like a kobold, \'cept they serve the magnataur; kinda take care of them. I know, weird!$B$BAnywho, wanna help me out? I know the little creeps stole off with all of my stuff. Stupid me thinkin\' that it\'d be nice and safe, packed up on the north side of the airstrip.$B$BWhy don\'tcha do me a favor and head north to their stupid Magmoth. There\'s a cash reward if you bring all my stuff back quick!]', '[Retrieve 10 boxes of Crafty\'s Stuff and return them to Crafty Wobblesprocket at Fizzcrank Airstrip.]', '', '去找北風凍原的卡芙緹‧顛鏈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11646 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11646, 'zhTW', '', '', '[Donathan ordered you to offer your assistance to Librarian Normantis in the mage tower on Amber Ledge.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11647 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11647, 'zhTW', '[Neutralizing the Cauldrons]', '[The presence of plague cauldrons within the Temple City of En\'kilah worries me greatly, $N. It\'s clear that Chieftain Wintergale trusts your judgment and your knowledge of our enemy. Would you help me deal with the cauldrons as you help the chieftain carry out his plans in the Temple City?$B$BI\'ve prepared a totem which will attack and neutralize the contents of the cauldrons. All you must do is locate the cauldrons and use the totem near each. Each Scourge weapon we destroy brings us closer to victory.]', '[Sage Aeire at Taunka\'le Village wants you to use her totem to neutralize the East Cauldron, the Central Cauldron, and the West Cauldron in the Temple City of En\'kilah.]', '', '去找北風凍原的賢者艾睿。', '東方坩堝已淨化', '中央坩堝已淨化', '西方坩堝已淨化', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11648 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11648, 'zhTW', '[The Art of Persuasion]', '[It is fortunate you\'re here, $r.$B$BYou see, the Kirin Tor code of conduct frowns upon our taking certain \'extreme\' measures - even in desperate times such as these.$B$BYou, however, as an outsider, are not bound by such restrictions and could take any steps necessary in the retrieval of information.$B$BDo what you must. We need to know where Lady Evanor is being held at once!$B$BI\'ll just busy myself organizing these shelves here. Oh, and here, perhaps you\'ll find this old thing useful....]', '[Librarian Normantis on Amber Ledge wants you to use the Neural Needler on the Imprisoned Beryl Sorcerer until he reveals the location of Lady Evanor.]', '', '去找北風凍原的圖書管理員諾曼提司。', '已審問囚犯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11649 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11649, 'zhTW', '[Motes of the Enraged]', '[Now that their little squabble is dealt with, there is still the matter of helping you and your spirit talker.$B$BAs you can see, my vassals have been enraged by the ongoing war between fire and water. This will not change anytime soon, but it will serve to your advantage.$B$BIn order to assist you, what we need are their motes. Head further into the ruins and retrieve them from the tempests.]', '[Obtain 5 Tempest Motes and deliver them to Imperean at the Ruins of Eldra\'nath.]', '', '去找北風凍原的英波里安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11650 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11650, 'zhTW', '[Just a Few More Things...]', '[As you may have noticed, we created the airstrip on the southern border of a magnataur den!$B$B<Crafty says something uncharitable about Fizzcrank under her breath.>$B$BThe old man has put me in charge of finding a... ahem... creative solution to this situation: if we don\'t deal with them soon, they\'ll come down here and tear us limb from limb!$B$BThat\'s where you come in. I want you to get me everything on this shopping list. Please.]', '[Collect Crafty\'s Tools, an Overcharged Capacitor, and a Handful of Rocknar\'s Grit. Deliver them to Crafty Wobblesprocket at Fizzcrank Airstrip.]', '', '去找北風凍原的卡芙緹‧顛鏈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11651 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11651, 'zhTW', '', '', '[Speak to Annihilator Grek\'lor at the Coast of Echoes.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11652 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11652, 'zhTW', '[The Plains of Nasam]', '[Once you\'re ready, jump into one of the tanks and drive it out to the Plains of Nasam, southeast of here.$B$BUse the tank\'s weapon arsenal to take down the Scourge army. If you get in a jam, the "Meatpounder" will tear \'em up and the land mines will finish \'em off! If you find any of our soldiers, grab \'em! One last thing, fuel tanks can be found all over the field.$B$BTry to get close enough to that structure in the center and see what\'s going on.$B$BIf you do all of this and live, go to Hellscream!]', '[Use the Horde Siege Tank to destroy 100 Scourge Soldiers and rescue 3 Injured Warsong Soldiers on the Plains of Nasam. You must also discover the identity of the leader of the Scourge assault.$B$BReport to Garrosh Hellscream at Warsong Hold should you succeed.]', '已辨識天災首領', '去找北風凍原的卡爾洛斯‧地獄吼。', '天災單位已殲滅', '已救出受傷的戰歌士兵', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11653 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11653,'zhTW','哈...你現在可沒那麼大囉!','這樣就可以應付她了，老大!接下來，我要你這麼做...$B$B帶著我的光束槍，朝著北邊前往瑪格默斯。如果我們想要有機會對抗那些怪物，我們必須減小他們的體型...就這麼辦。$B$B為了評估光束槍的效能，我要你在猛瑪象人身上的光束槍效果結束之前殺掉牠們。任何粉碎者或是配偶都可以，不過放過那些後代吧...他們還很小，不用擔心。','在5隻瑪格默斯粉碎者或瑪格默斯瑞卡的配偶身上檢測卡芙緹的超進階初體版微縮光束槍。在完成後，回到嘶軸簡易機場找她。','','去北風凍原找菲茲蘭克機場的機靈鬼沃比斯波基。','測試卡芙緹的光束槍','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11654 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11654, 'zhTW', '[The Spire of Blood]', '[As you inspect the captured blood vial, you realize its contents are still warm. The victim must have just been bled and may still be alive.$B$BWhat use would the Scourge have for blood? They\'ve never shown an interest in live prisoners in the past. Perhaps if you can locate the source of the blood, you\'ll be able to discover what the Scourge is planning.]', '[Search the Spire of Blood for more information about the Vial of Fresh Blood.]', '', '去找北風凍原的雪地追蹤者古魯姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11655 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11655, 'zhTW', '[Into the Mist]', '[Across the mist to the north you will find Garrosh\'s Landing. To the south are the ruins of my old home, Pal\'ea. Both have been ransacked by an ancient force known as the Kvaldir.$B$BThese fearsome savages slew all of my people without mercy and drove your people inland.$B$BAll that remains of the tuskarr of Pal\'ea are our personal effects, taken as relics by the Kvaldir. While we are not a vengeful race, justice must be served. The tuskarr relics must be returned to me. Enter the mist and find them...]', '[Waltor of Pal\'ea at the Coast of Echoes in the Borean Tundra wants you to kill Kvaldir and recover 8 Tuskarr Relics.]', '', '去找北風凍原的帕雷亞的華特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11656 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11656, 'zhTW', '[Burn in Effigy]', '[Tuskarr magic is similar to what your people call shamanism. While we serve the elements differently than you, the power that we are able to call forth is formidable.$B$B<Waltor waves a torch-like baton in front of you.>$B$BWith this tuskarr torch I want you to return to the mist and strike at the Kvaldir vessels. You will find three of their vessels docked behind the mist at Garrosh\'s Landing, north of here, and one docked off the shores of Pal\'ea, to the south. Burn their ships in effigy! For all to see!]', '[Waltor of Pal\'ea at the Coast of Echoes in the Borean Tundra wants you to use the Tuskarr Torch to burn the Kvaldir ships at Pal\'ea and Garrosh\'s Landing. You must destroy the following ships: The Serpent\'s Maw, The Kur Drakkar, Bor\'s Hammer and Bor\'s Anvil.$B$B]', '', '去找北風凍原的帕雷亞的華特。', '巨蛇之顎已摧毀', '庫爾達卡爾已摧毀', '波爾的鐵鎚已摧毀', '波爾的鐵砧已摧毀', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11657 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11657, 'zhTW', '接住火炬', '既然你已經學會投擲火炬了，讓我們看看你接不接得住它!$B$B拿著這堆未點燃的火炬。去營火那邊然後把火炬高高地丟向空中!然後在火炬落地之前接住它...然後再把它丟回去!連續接住四個後，就回來找我。$B$B小心點!如果它們掉到地上可是很危險的!所以千萬別失誤!要是你真得失誤了，那你就得回到營火那再重新開始一次。祝你好運!', '連續接住4根火炬，然後跟吞火者大師談話。', '連續接住4支火把', '去找吞火者大師。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11658 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11658, 'zhTW', '[Plan B]', '[Okay, don\'t panic! The blaster might not\'ve worked, but we still have options.$B$B<Crafty snaps her fingers.>$B$BWe\'re going to divert attention away from the airstrip! To make this work, we\'ll need a few things first.$B$B<Wobblesprocket looks you up and down appraisingly.>$B$BSteeljaw\'s caravan, just to the west, stupidly took a shortcut through a taunka graveyard and was destroyed by their risen spirits.$B$BHead over there and get some outfits off of the dead orcs. Pick up one of their banners, too!]', '[Collect 10 Warsong Outfits and a Warsong Banner. Bring them back to Crafty Wobblesprocket at Fizzcrank Airstrip.]', '', '去找北風凍原的卡芙緹‧顛鏈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11659 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11659, 'zhTW', '[Shatter the Orbs!]', '[They\'re... bleeding the prisoners... putting the blood... in those globes.$B$B<Grumm\'s eyes close momentarily and he leans his head back.>$B$BThe blood... taken up to necropolis... to feed blood prince...$B$B<Grumm gasps for breath.>$B$BP-promise... you\'ll... destroy blood... globes... bring word... to Junek.$B$B<The snow tracker collapses into unconsciousness.>]', '[Destroy 5 Blood Globes and report to Snow Tracker Junek at Taunka\'le Village.]', '', '去找北風凍原的雪地追蹤者朱奈克。', '血球已擊碎', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11660 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11660, 'zhTW', '[Horn of the Ancient Mariner]', '[A Kvaldir lieutenant known as Orabus directed the initial incursion against my people at Pal\'ea, He oversaw the destruction of both villages and then disappeared into the mist.$B$BIn those early days there was talk of a horn that Orabus gifted to the Kvaldir mistweavers. This horn could be used to summon him should the need arise.$B$BWe need to get that horn from the Kvaldir mistweavers and call forth Orabus. If he is destroyed, these savages might retreat.$B$BSeek out mistweavers at Pal\'ea, to the south.]', '[Waltor of Pal\'ea at the Coast of Echoes in the Borean Tundra wants you to bring him the Horn of the Ancient Mariner.]', '', '去找北風凍原的帕雷亞的華特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11661 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11661, 'zhTW', '[Orabus the Helmsman]', '[Take the horn and travel west to the Warsong Jetty. Make your way to the end of the jetty and blow into the horn. The sound should rouse Orabus.$B$BSlay the foul beast and return to me!]', '[Waltor of Pal\'ea at the Coast of Echoes in the Borean Tundra wants you to use the Horn of the Ancient Mariner to summon Orabus the Helmsman. Once summoned, slay Orabus the Helmsman.]', '', '去找北風凍原的帕雷亞的華特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11662 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11662, 'zhTW', '', '', '[Seek out Karuk at Riplash Strand.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11663 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11663, 'zhTW', '', '', '[Normantis has asked you to report to Librarian Donathan on Amber Ledge.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11664 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11664, 'zhTW', '[Escaping the Mist]', '[I can hear the mist creatures outside. Their yells are driving me mad, but I dare not try to escape. And where would I even go? How long would it be until they caught up with me and executed me like the others?$B$BI wonder, how far has the mist crept, stranger? Has it overtaken this whole continent?$B$BWould you be willing to help me try and escape the mist? I think I can lead us back toward my father. I still sense his life spirit. He is close.]', '[Follow Mootoo the Younger out of the mist. Speak to Elder Mootoo should you successfully save Mootoo the Younger.]', '穆圖已救出', '去找北風凍原的穆圖長者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11665 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11665, 'zhTW', '城裡的鱷魚', '你好，<小夥子/姑娘>。我很高興你願意停下來和這個老人聊天 -- 家裡最近出了一些狀況。$B$B一個旅行商人把一窩鱷魚寶寶賣給了容易受騙的孩子。鱷魚是狂野的獸類，許多已經逃走，潛伏在城裡的下水道中。$B$B拿出你最堅固的釣魚竿吧，在暴風城或是奧格瑪垂下魚標，把一隻小惡魔帶回來給我。我急著想看看這些鱷魚寶寶。', '把一隻鱷魚寶寶帶給老人巴洛。你可以在撒塔斯城東北邊的泥濘湖畔找到他在那釣魚。', '', '去找泰羅卡森林的老人巴洛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11666 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11666, 'zhTW', '魚餌強盜', '你一定知道有關金色淡水小魚的事--牠們遍佈於所有泰洛卡森林的河中，對牧師來說是一道美味佳餚。不過這裡有個你從來都沒聽說過的:黑鰭小魚。$B$B這種魚是出名的狡詐且難以捕捉。你得在最佳的緊要關頭才能拉動你的釣線，因為牠們在咬住餌之前都很小心翼翼。$B$B將你的魚線丟入泰洛卡森林的河中，並將一尾黑鰭小魚帶來給我。別在湖中垂釣，黑鰭小魚只生長在流動的水中。', '帶一尾黑鰭小魚給老人巴洛。你可以在撒塔斯城東北邊的泥濘湖畔找到他在那釣魚。', '', '去找泰羅卡森林的老人巴洛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11667 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11667, 'zhTW', '逃脫的那個', '微光泥鰍是一種在納葛蘭水域中非常靈活的底棲魚。他們一生都在不斷成長，並以戰士的別稱聞名。$B$B許多年前，我抓到一隻我認為是世界上最大的泥鰍……直到牠咬斷我的魚線並且掙脫。$B$B像你這種程度的漁夫是不需要什麼指點 -- 你的命運正等在納葛蘭的湖畔。', '抓到世界最大的泥鰍，然後帶給老人巴洛。你可以在撒塔斯城東北邊的泥濘湖畔找到他在那釣魚。', '', '去找泰羅卡森林的老人巴洛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11668 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11668, 'zhTW', '抓蝦子一點都不簡單', '贊格沼澤的湖中擁有豐富的魚產。懷疑過他們以什麼為食嗎?$B$B就是蝦子。巨型清水蝦。洛克跟我說你可以用蝦子煮出無數的菜色。$B$B但是蝦子實在太小了，沒辦法用釣線來釣。所以這有個點子:把浮腫的倒刺鰓鱒魚剖開，夠幸運的話你會在當中找到一兩隻蝦子。', '帶10隻巨型清水蝦給老人巴洛。你可以在撒塔斯城東北方找到他在泥濘湖畔垂釣。', '', '去找泰羅卡森林的老人巴洛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11669 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11669, 'zhTW', '魔化之血肉片', '這個老人就快要去打獵了。我要去打敗艾薩拉海岸外的一隻巨大鯊魚。$B$B事情就是，我需要一種在水中也不會溶解的毒藥。想要製作出那樣的東西，我會需要一種腺體，來自於一種毒魚:魔化之血鯛魚。$B$B像這種邪惡的魚種只存活在地獄火半島和影月谷的惡水中。帶條大魚給我，我就會是個快樂的老人了。', '帶一尾可怕的魔化之血鯛魚給老人巴洛。你可以在撒塔斯城東北邊的泥濘湖畔找到他在那釣魚。', '', '去找泰羅卡森林的老人巴洛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11670 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11670,'zhTW','是獸人乾的！真的！','我費了好大勁才將這些衣料拼湊成一件戰歌獸人偽裝。別擔心，我在衣料中新增了去年萬聖節剩下的好東西，它應該非常結實。啊，我真是個天才！$B$B喏，袋子裡裝著獸人偽裝和你取回的那面旗幟。帶上它轉至獁格莫斯，殺死猛獁人的酋長獁格莫斯雷加。$B$B你必須在偽裝狀態下將旗幟插在獁格莫斯雷加的屍體上，令猛獁人的注意力轉移到戰歌獸人身上。','偽裝成戰歌獸人，將戰歌旗幟插在獁格莫斯雷加的屍體上。完成任務後返回菲茲蘭克機場，將偽裝還給機靈鬼沃比斯波基。','','去北風凍原找菲茲蘭克機場的機靈鬼沃比斯波基。','將戰歌旗幟插在獁格莫斯雷加的屍體上','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11671 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11671, 'zhTW', '[A Race Against Time]', '[So it\'s true. They have her.$B$BIt\'s clear what must be done, $r. She WILL be saved.$B$BI must remain here and aid in the rescue preparations. I call upon you again; this time to collect the prison key. All we know of this Salrand figure is that she cannot be harmed so long as her shield is intact.$B$BWe\'ve customized a special explosive that should strip her of this protection, allowing you to perform your duty. Return to me when you\'ve collected the key.$B$BHurry, $n. Lady Evanor is suffering!]', '[Donathan on Amber Ledge has tasked you with using the Beryl Shield Detonator to bring down the shield at Beryl Point. You are then to defeat Salrand and collect the key she holds.]', '', '去找北風凍原的圖書管理員唐納森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11672 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11672, 'zhTW', '', '', '[Meet with General Arlos inside the barracks in Valiance Keep.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11673 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11673, 'zhTW', '[Get Me Outa Here!]', '[I knew they\'d send someone for me sooner or later... turned out to be later, of course.$B$BI came in here to parlay with the snobolds, but their main shaman, Kaganishu, decided instead that I\'d make a tasty snack for Magmothregar.$B$BWait... what?! They didn\'t send you?!$B$BDID THEY FORGET ABOUT ME?!$B$BOkay, you\'re here now and that\'s all that matters.$B$BAs soon as you break this chain we\'ll make our way back to the airstrip. Then you can tell Fizzcrank I\'m safely back.$B$BIf he remembers me, that is.]', '[Escort Bonker Togglevolt to safety and then report in with Fizzcrank Fullthrottle at Fizzcrank Airstrip.]', '邦克·托格佛特已護送至安全處', '去找北風凍原的嘶軸‧滿閥。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11674 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11674, 'zhTW', '', '', '[Find Sage Highmesa near the Dens of Dying.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11675 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11675, 'zhTW', '[A Proper Death]', '[The magnataur at the Dens of Dying have contracted a plague. We must find the cause, but first we must put them out of their misery.$B$B$R, you must go north onto the slopes in front of us and destroy as many of the poor creatures as you can.]', '[Destroy 10 Plagued Magnataur and then return to Sage Highmesa south of The Dens of Dying.]', '', '去找北風凍原的賢者高臺。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11676 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11676, 'zhTW', '[Merciful Freedom]', '[The soldiers that they didn\'t kill are being held in cages scattered across this farmland. Through some thievery we\'ve managed to find a few keys, but we\'re unable to get close enough to any prisoners without being attacked.$B$BWe need your "talents" in securing those keys and freeing the prisoners. Bash in the brains of the necrolords and aberrations and take their keys. Use those keys to free Scourge prisoners.]', '[Shadowstalker Canarius at Warsong Farms Outpost wants you to free 5 Scourge Prisoners.]', '', '去找北風凍原的巡影者卡納利亞斯。', '天災囚犯已釋放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11677 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11677, 'zhTW', '[Stop the Plague]', '[I\'m convinced that the plague is being caused by something in the caves up there.$B$B$C, I want you to take these seeds. I normally use them as a ward against the Scourge, though perhaps they can be used to disrupt whatever foulness is happening in the dens.$B$BFind the source of the plague and throw them into it.]', '[Sage Highmesa, standing just south of The Dens of Dying, has asked you to use Highmesa\'s Cleansing Seeds at a Den of Dying Plague Cauldron to neutralize it.]', '', '去找北風凍原的賢者高臺。', '瘟疫坩堝已中和', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11678 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11678, 'zhTW', '', '', '[Find Longrunner Bristlehorn at Talramas.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11679 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11679, 'zhTW', '[Reforging the Key]', '[Delays, delays... the one thing we cannot afford right now!$B$BAs much as I hate to disturb Lord Surristrasz, he\'s our only hope of saving our beloved Evanor.$B$BBring him the key fragments and hope that his mood is favorable.$B$BHurry, $c, our assault team is waiting.]', '[Donathan wants you to speak to Surristrasz on Amber Ledge.]', '', '去找北風凍原的瑟利斯塔茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11680 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11680, 'zhTW', '[Taking Wing]', '[The key is forged anew.$B$BNow heed my counsel, $r. Succeed in your endeavor or die trying, for if a single scale falls from one of my drakes I shall hold you personally accountable.$B$BNow, off with you.]', '[Give Salrand\'s Key to Warmage Anzim when you are ready to free Evanor.]$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11681 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11681, 'zhTW', '', '', '[Anzim on Amber Ledge wants you to fly with his war mages to free Lady Evanor at Beryl Point. You are then to report to her in the mage tower on Amber Ledge.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11682 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11682, 'zhTW', '', '', '[Lady Evanor has sent you to speak with Surristrasz on Amber Ledge.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11683 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11683, 'zhTW', '[Fallen Necropolis]', '[The fallen necropolis to the west can only be assumed to still be filled with Scourge.$B$BWhile you are at Talramas, $c, I would ask that you dispatch all of the Lich King\'s servants that you find within and in the surrounding pools where it fell.]', '[Destroy 20 Scourge of any type at Talramas and the Festering Pools. Then, return to Sage Highmesa just to the south of The Dens of the Dying.]', '', '去找北風凍原的賢者高臺。', '塔拉瑪斯的天災已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11684 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11684, 'zhTW', '[Scouting the Sinkholes]', '[Can you feel the tremors in the earth?$B$BThe Scourge\'s nerubians are on the move deep beneath the ground. They\'ve emerged to the southwest in the Geyser Fields, and are harassing the patrols Chieftain Wintergale sent out.$B$B<The taunka elder offers you a worn map.>$B$BPerhaps a single person can succeed where the patrols have failed. Take this with you to the Geyser Fields and map out the locations of the Nerubian sinkholes.]', '[Greatfather Mahan at Taunka\'le Village wants you to use the Map of the Geyser Fields to mark the locations of the South Sinkhole, the Northwest Sinkhole, and the Northeast Sinkhole.]', '', '去找北風凍原的主父瑪哈。', '標記南方坑洞位置', '標記東北方坑洞位置', '標記西北方坑洞位置', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11685 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11685, 'zhTW', '[The Heart of the Elements]', '[Now that we know the exact locations of the nerubian sinkholes, we can collapse them to halt the Scourge offensive and cripple their force. Wind Tamer Barah knows a way to harness elementals to destroy the tunnels the Nerubians are using, but she will require your help.$B$BSoutheast of the village, near the coast beyond the Frozen Reach, you\'ll find an area dominated by frozen earth elementals. The hearts of these elements are exactly what Wind Tamer Barah will need.]', '[Bring 5 Elemental Hearts to Wind Tamer Barah at Taunka\'le Village.]', '', '去找北風凍原的馴風者巴拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11686 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11686, 'zhTW', '[The Warsong Farms]', '[According to Luther\'s notes the Scourge is now using this place as a breeding ground for those monsters you see lumbering across the field.$B$B<Ickoris shudders.>$B$BThose monsters were once orcs... tauren...$B$BWe need more information before a plan can be devised. I want you to investigate three sites that are heavily trafficked by Scourge: the Warsong Granary, southwest of us, Torp\'s Farm, directly west of us, and the old Warsong Slaughterhouse, north of us.$B$BReturn to me once you\'ve scouted \'em out.]', '[Shadowstalker Ickoris at Warsong Farms Outpost wants you to scout Warsong Granary, Torp\'s Farm, and Warsong Slaughterhouse.]', '', '去找北風凍原的巡影者艾寇里斯。', '偵察戰歌穀倉', '偵察托爾普的農場', '偵察戰歌屠宰場', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11687 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11687, 'zhTW', '[The Doctor and the Lich-Lord]', '[There are two... that must... be killed.$B$BThe doctor and... the lich-lord... are above. Find them... destroy them... before....$B$B...it is too... late....]', '[Destroy Doctor Razorgrin and Lich-Lord Chillwinter. Then, return to Sage Highmesa just to the south of The Dens of Dying.]', '', '去找北風凍原的賢者高臺。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11688 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11688, 'zhTW', '[Damned Filthy Swine]', '[Just look at \'em! My beautiful kodos are helpless to defend themselves against those filthy swine! I need you to buy me some time, $r. I think I can cure the kodo of the sickness, but you need to keep the unliving swine off \'em, else there\'ll be nothin\' left to cure!$B$BGet out there and send those swine to their graves - permanently!]', '[Farmer Torp at Warsong Farms Outpost wants you to kill 10 Unliving Swine.]', '', '去找北風凍原的農夫托普。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11689 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11689, 'zhTW', '', '', '[Speak with Greatmother Taiga at Taunka\'le Village.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11690 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11690, 'zhTW', '[Bring \'Em Back Alive]', '[Take this riding snaffle, $N. You\'ll notice that I\'ve placed a tiny medicine dispenser in the mouthpiece. That thing will cure the infection as soon as a kodo bites down. Once you\'ve cured the sick out of \'em, you\'ll need to ride \'em home. They\'ll be weak so you\'ll need to gently direct \'em here.$B$BBring my babies back, $N!$B$BOne last thing, you\'ve got ten minutes! That\'s how long the antidote will remain effective inside that snaffle.]', '[Farmer Torp at Warsong Farms Outpost wants you to rescue 8 Infected Kodo Beasts.]', '', '去找北風凍原的農夫托普。', '已救出科多獸', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11691 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11691, 'zhTW', '召喚艾胡恩', '我和手下的薩滿已經聚集我們的力量，為了接下來和冰霜領主的戰鬥做好準備。$N，你將會是大地之母的拳頭。$B$B帶著這根熔岩圖騰。對東北方的冰石使用它。艾胡恩正在透過那個石塊引導他的力量;我們希望圖騰能夠打斷他並且切斷他和元素位面的連結。$B$B如果我們夠幸運的話，那或許我們就能打敗他。$B$B做好準備，$n。如果艾胡恩和我們正面衝突，他將會非常瘋狂與憤怒。', '將陶土議會熔岩圖騰帶到冰石旁邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11692 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11692, 'zhTW', '', '', '[Mordle Cogspinner has asked you to find Bixie Wrenchshanker to the south of The Dens of Dying.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11693 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11693, 'zhTW', '[Oh Great... Plagued Magnataur!]', '[Tinky and I came out here stalking some old magnataur. Apparently those caves up there are where they go to die.$B$BOf course, we had no idea that they were going to get plagued when they went in there. We can\'t have plagued things just roaming about; it\'s not healthy.$B$BSay, why don\'t you put down a number of those things while I figure out what our next step should be?]', '[Kill 10 Plagued Magnataur and then return to Bixie Wrenchshanker to the south of The Dens of Dying.]', '', '去找北風凍原的碧西‧扭柄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11694 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11694,'zhTW','洞穴裡的古怪','所以呢，雖然你已經處理了那些染疫野獸，但是我還是偷看了一下洞穴的內部。$B$B裡頭的教徒們正在進行瘟疫化!$B$B他們將某種有毒的混合物放在大鍋中釀煮著。我有一種平常用來解毒的粉末，我將它混合了其它的東西。我想這將可中和他們的釀煮物!$B$B帶著這個粉末前往其中一個洞穴試試看有沒有效。','潛伏在垂死獸穴南方的碧西‧扭柄要你對垂死獸穴瘟疫大鍋使用碧西的抑制粉末來中和它。','','去找北風凍原的比希·鉗柄。','中和瘟疫大鍋','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11695 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11695, 'zhTW', '[The Horn of Elemental Fury]', '[I can fashion the likeness of an elemental from these pieces of inanimate stone, but breathing life into it is different. For that, we\'ll need help and a bit of luck.$B$BLegend tells of an ancient artifact called the Horn of Elemental Fury, sought after by a great hero. I\'ll lend you a scroll with a copy of the tale. I don\'t know if the legend is true, but it\'s our best bet. If the legend is right, the parts of the horn may be in the Flood Plains surrounding the village to the north and southwest.]', '[Reclaim the Lower Horn Half and Upper Horn Half from Chieftain Burblegoggle and Chieftain Gurgleboggle and bring them to Wind Tamer Barah at Taunka\'le Village.]', '', '去找北風凍原的馴風者巴拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11696 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11696, 'zhTW', '艾胡恩就在這裡!', '$n，你的出現真是個恩賜。艾胡恩就在那些洞穴之中，為他的攻擊積蓄力量。陶土議會已經派人出發了，但單靠他們是無法擊敗艾胡恩的。探索吧，$n。找到我們陶土議會的薩滿，和他們的領袖魯瑪·天空之母談談。或許加上你的力量，我們能在一切太遲之前打倒艾胡恩。', '在奴隸監獄中找到魯瑪·天空之母。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11697 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11697, 'zhTW', '', '', '[Find Tinky Wickwhistle inside Talramas.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11698 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11698,'zhTW','不如徹底消滅天譴軍團','如果那些洞穴上方的教徒們可以在這場破壞中存活下來，那麼只能假定西邊那個倒坍的亡域當中仍充滿著天譴軍團。前方的池子也一定滿滿的都是天譴軍！$B$B雖然你人在塔爾拉瑪斯，$c，你覺得你可以殺光所有在那發現的巫妖王奴僕嗎？','摧毀20個位於塔爾拉瑪斯和膿瘡之池的天譴軍，不限種類。接著，回到北風凍原的垂死獸穴正南方找碧西‧扭柄。','','去找北風凍原的比希·鉗柄。','摧毀塔爾拉瑪斯的天譴軍','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11699 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11699, 'zhTW', '[I\'m Stuck in this Damned Cage... But Not For Long!]', '[The cultists magicked me into this cage and there\'s no door to it. Little did they know that I\'m the chief transmatter engineer for the airstrip!$B$BWith your help, and a little elbow-grease, I won\'t be in here for long.$B$BI\'m going to need an engine-core crystal from one of the ghouls in here, a magical gyroscope from their doctor, and a piloting scourgestone from the lich-lord up top.$B$BWith all of that stuff, I should be able to make a port device to get back to Fizzcrank\'s and escape the gnome way!]', '[Collect an Engine-Core Crystal, a Magical Gyroscope, and a Piloting Scourgestone. Deliver them to Tinky Wickwhistle at Talramas.]', '', '去找北風凍原的汀基‧芯哨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11700 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11700, 'zhTW', '', '', '[Speak with Bixie Wrenchshanker just south of The Dens of Dying.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11701 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11701, 'zhTW', '', '', '[Speak with Fizzcrank Fullthrottle at Fizzcrank Airstrip in Borean Tundra.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11702 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11702, 'zhTW', '', '', '[Speak with King Mrgl-Mrgl at Winterfin Retreat.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11703 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11703, 'zhTW', '', '', '[Find Shadowstalker Getry at Warsong Farms.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11704 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11704, 'zhTW', '', '', '[Speak with King Mrgl-Mrgl at Winterfin Retreat.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11705 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11705, 'zhTW', '[Foolish Endeavors]', '[This is madness. How do they expect us to take on a Scourge necrolord and an unknown number of his minions?$B$B<Getry sighs.>$B$BIf Ickoris sent you he must think that you are capable of great feats. Perhaps you will call down a miracle today, eh?$B$BWhen you\'re ready we will descend and face Varidus.$B$BIf we make it out of this mess in one piece, report back to Hellscream in Warsong Hold.]', '[Help Getry defeat Varidus the Flenser at Warsong Farms.$B$BReport to Garrosh Hellscream should you succeed.$B$B]', '已擊敗剝皮者瓦里杜斯', '去找北風凍原的卡爾洛斯‧地獄吼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11706 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11706, 'zhTW', '[The Collapse]', '[I have created and bound Alluvius using the Horn of Elemental Fury. He will respond to the horn\'s call when you stand near the southernmost sinkhole in the Geyser Fields.$B$BThe quake Alluvius will unleash should collapse the Nerubian tunnels and put an end to their flanking attack. I wouldn\'t be surprised if the Nerubian commander showed himself after the quake. If the collapse of the tunnels doesn\'t break the back of their assault, the defeat of their leader surely will.]', '[Wind Tamer Barah at Taunka\'le Village wants you to collapse the Nerubian sinkholes using the Horn of Elemental Fury and defeat Lord Kryxix.]', '', '去找北風凍原的馴風者巴拉。', '', '納魯比坑道已崩塌', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11707 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11707, 'zhTW', '', '', '[Speak with Fizzcrank Fullthrottle at Fizzcrank Airstrip.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11708 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11708, 'zhTW', '[The Mechagnomes]', '[Now that you\'re here, it\'s time for me to tell you the full story of what\'s going on.$B$BAfter you\'ve heard my tale, go outside and find my second-in-command, Jinky Wingnut. She\'ll handle everything from here on out.]', '[Listen to Fizzcrank Fullthrottle\'s tale and then find Jinky Wingnut at Fizzcrank Airstrip.]', '已聆聽嘶嘶剎車的故事', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11709 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11709, 'zhTW', '', '', '[Speak to Warden Nork Bloodfrenzy at Warsong Hold in Borean Tundra.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11710 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11710, 'zhTW', '[What\'s the Matter with the Transmatter?]', '[There\'re spare parts strewn all over to the east in the Scalding Pools, the Geyser Fields... heck, probably even up on the pumping station still, too. Bring back a whole bunch. Maybe then I\'ll be able to get outgoing teleport on this thing working, not to mention getting the incoming transmatter ports aligned.$B$BI\'d hate to see another accident....]', '[Collect 15 Fizzcrank Spare Parts and deliver them to Mordle Cogspinner at Fizzcrank Airstrip.]', '', '去找北風凍原的莫爾斗‧旋輪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11711 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11711, 'zhTW', '[Coward Delivery... Under 30 Minutes or it\'s Free]', '[We\'re seeing more deserters show up at our gates with each passing day. We simply do not have enough room to keep all of these maggots caged up. Especially not if we want to keep the pigs happy.$B$B<Nork snorts as he laughs.>$B$BI want you to escort one of these cowards to the crossroads east of here and fire this flare gun. One of their captains will show up when they see the flare and take the coward off your hands.$B$BReport to Scout Tungok on the east road once the delivery has been made.$B$B]', '[Take the Alliance Deserter to the crossroads east of Warsong Hold and fire your Warsong Flare Gun to signal the Alliance.$B$BReport to Scout Tungok once you have successfully delivered the Alliance Deserter to their destination.]', '聯盟逃兵已送達', '去找北風凍原的斥候敦苟克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11712 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11712, 'zhTW', '[Re-Cursive]', '[If you listened to the old man, then you know that we have gnomes out there that were changed. Gearmaster Mechazod infected them with something that reversed the "Curse of the Flesh", and now they\'re robots!$B$BWe think we have a way to re-curse them back to normal. We want you to take this re-cursive transmatter injection and use it on the corpses of any mechagnomes you come across.$B$BWe\'re hoping that this stuff will cure them and allow us to lock onto them to port \'em out of there.$B$BWhaddya say, $N?]', '[Jinky Wingnut at Fizzcrank Airstrip has asked you to use the Re-Cursive Transmatter Injection on 6 Fizzcrank Mechagnomes.]', '', '去找北風凍原的金基‧翼果。', '嘶嘶剎車地精已被詛咒並傳送', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11713 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11713, 'zhTW', '[Scouting the Sinkholes]', '[Fizzcrank sent out an aerial surveillance team to map the Nerubian sinkholes in the southern part of the Geyser Fields, but they haven\'t yet returned. I can\'t afford to wait any longer for their information, so I\'m going to need someone to check out the sinkholes on foot.$B$BI understand the dangers involved, and I\'ll compensate you accordingly. Take this map with you and record the vital information about each of the sinkholes you encounter out there.]', '[Abner Fizzletorque at Fizzcrank Airstrip wants you to use the Map of the Geyser Fields to mark the locations of the South Sinkhole, the Northwest Sinkhole, and the Northeast Sinkhole.]', '', '去找北風凍原的艾伯奈‧嘶鍊。', '標記南方坑洞位置', '標記東北方坑洞位置', '標記西北方坑洞位置', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11714 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11714, 'zhTW', '[Vermin Extermination]', '[Perhaps you\'d be interested in helping me clean up these fields? They\'re littered with dirty little rat men! Kobolds, snobolds, whatever you wanna call \'em, they\'re all over the damned place. The stink alone is making my life hell!$B$BTake care of the vermin for me and I\'ll make it worth your while, $N.$B$B]', '[Scout Tungok at the Bloodspore Plains in the Borean Tundra wants you to kill 8 Bloodspore Harvesters, 5 Bloodspore Firestarters and 2 Bloodspore Roasters.]', '', '去找北風凍原的斥候敦苟克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11715 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11715, 'zhTW', '[Fueling the Project]', '[I plan to build a machine that will collapse the tunnels the Scourge is using to deploy their Nerubians, but with the main drilling rig out of order, we\'ll have to collect the fuel for the device some other way.$B$BOut in the Geyser Fields to the southeast, small pools of oil bubble up away from the main rig. If you can collect enough of the oil from those pools, I can make a crude fuel to power the machine.$B$BSimply deploy the collector near the rig, and it will pump and store the oil in its tank.]', '[Abner Fizzletorque at Fizzcrank Airstrip wants you to collect 8 Barrels of Oil using the Portable Oil Collector.]', '', '去找北風凍原的艾伯奈‧嘶鍊。', '已收集油桶', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11716 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11716, 'zhTW', '[The Wondrous Bloodspore]', '[We are witnessing something amazing here, $r. A whole undiscovered ecology lives and breathes not more than a few paces from us! I surmise it is the bloodspore plant that sets this environment abuzz.$B$BI have collected some pollen from the nearby male species of bloodspore plant but still lack female receptors for pollination. Fetch me a bushel of the bloodspore carpels. You\'ll find them near the larger plants surrounding us.$B$BBe wary of their guardians! The kobolds won\'t give them up easily!]', '[Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra wants you to recover 10 Bloodspore Carpels.]', '', '去找北風凍原的血法師羅瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11717 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11717, 'zhTW', '[Pollen from the Source]', '[It\'s obvious! The bloodspore moths are the entities responsible for pollination on these plains. It must be something that happens within the moth\'s internal system that acts as a catalyst for this pollen to work. It\'s all starting to make sense now, $N. That\'s why the kobolds don\'t kill the moths and instead go to great lengths to protect them! Those stupid little rats have it all figured out!$B$BWell we\'ll just have to get our own moth pollen! What do you say? Fetch me some in the name of science?]', '[Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra wants you to recover 5 Bloodspore Moth Pollen.$B$B]', '', '去找北風凍原的血法師羅瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11718 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11718, 'zhTW', '[A Bot in Mammoth\'s Clothing]', '[I\'ve reconfigured the skeleton of an old bot to create an earthquake large enough to collapse the tunnels, but the machinery is delicate and sensitive to Northrend\'s biting cold.$B$BI\'ve devised a means of insulating it using the thickest hides of the native mammoths. They roam the plains south of the airstrip and adjacent to the Geyser Fields. Bring back enough of the hides for me to finish the machine and then we\'ll be able to unleash it on the Nerubians!]', '[Abner Fizzletorque at Fizzcrank Airstrip wants you to bring him 6 Thick Mammoth Hides.]', '', '去找北風凍原的艾伯奈‧嘶鍊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11719 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11719, 'zhTW', '[A Suitable Test Subject]', '[<Laurith looks you over as if to size you up.>$B$BSo we\'ve got this pollinated bloodspore flower and nobody to test its effects on. Say, would you perhaps be interested in rubbing this on your skin and letting me observe? What\'s the worst that could happen anyway?$B$BDon\'t you worry, $N! Just take this sample and rub it all over your face. ]', '[Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra has asked that you use the Pollinated Bloodspore Flower and allow her to observe the results.]', '已使用血孢花', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11720 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11720, 'zhTW', '', '', '[Speak to Primal Mighthorn at the Bloodspore Plains in the Borean Tundra. ]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11721 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11721, 'zhTW', '[Gammothra the Tormentor]', '[Magnataur live in prides, much like lions: one or two dominant males and several females along with their offspring. In the case of Gammoth, the magnataur den west of here, Gammothra is the leader. It is Gammothra that controls this magnataur population and therefore it is Gammothra that must be slain to prevent any type of magnataur uprising.$B$BTake this pouch of crushed bloodspore flower to Gammoth. Use the powder from the pouch to weaken Gammothra and then slay him! Return his head to me as proof.]', '[Slay Gammothra and return the Head of Gammothra to Primal Mighthorn at the Bloodspore Plains in the Borean Tundra.]', '', '去找北風凍原的力角始祖。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11722 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11722, 'zhTW', '[Trophies of Gammoth]', '[We cannot take all of the credit for this Horde victory, $N. It was you who risked your life to test the bloodspore and it was you who ultimately put an end to Gammothra.$B$BHonor us by returning to Warsong Hold and presenting the head of Gammothra to Lord Hellscream.]', '[Take the Head of Gammothra to Garrosh Hellscream in Warsong Hold.]', '', '去找北風凍原的卡爾洛斯‧地獄吼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11723 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11723, 'zhTW', '[Deploy the Shake-n-Quake!]', '[Behold, the machine that will save us from the Nerubian threat!$B$B<Abner beams with pride as he presents the finished bot.>$B$BTake this remote control with you, and go out to the southernmost of the Nerubian sinkholes in the Geyser Fields. Use the remote to activate the Shake-n-Quake 5000. It will do the rest on its own.$B$BDon\'t be surprised if the quake it creates attracts the attention of a Nerubian leader. In fact, it would be a great opportunity to finish off the Nerubian offensive.]', '[Abner Fizzletorque at Fizzcrank Airstrip wants you to use the Shake-n-Quake 5000 to collapse the Nerubian tunnels and defeat Lord Kryxix.]', '', '去找北風凍原的艾伯奈‧嘶鍊。', '', '部署震撼者5000型', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11724 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11724, 'zhTW', '[Massive Moth Omelet?]', '[This egg was obviously important to somebody, as the corpse nearby can attest. As you look the egg over you notice that it has already been tagged for shipment to the Bloodspore Plains, care of Bloodmage Laurith. That\'s just east of here!$B$BCollect the egg and take it to the expectant Bloodmage.]', '[Take the Massive Glowing Egg to Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra.]', '', '去找北風凍原的血法師羅瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11725 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11725, 'zhTW', '', '', '[Locate Iggy "Tailspin" Cogtoggle in the Geyser Fields.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11726 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11726, 'zhTW', '[A Little Bit of Spice]', '[The wolves have been pawing through the wreckage ever since the crash and I\'m afraid they consumed the microfilm from our mission in the process.$B$BI have a plan to recover that microfilm, but I need your help to make it work.$B$BTo the south and east, in the Flood Plains, live creatures called gorlocs. They prepare their foods with noxious spices, which would sicken any other creature. If you can gather enough of the spice pouches from gorloc steam belchers or gorloc waddlers, I can make the wolf bait.]', '[Iggy "Tailspin" Cogtoggle in the Scalding Pools wants you to gather 4 Gorloc Spice Pouches.]', '', '去找北風凍原的『尾旋』艾基‧榫栓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11727 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11727, 'zhTW', '', '', '[Report to Sergeant Hammerhill at Valiance Keep.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11728 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11728, 'zhTW', '[Lupus Pupus]', '[Whatever you do, don\'t eat this bait yourself. Just set it down in the vicinity of an oil-soaked wolf. If they\'re desperate enough to eat the microfilm, they\'ll come running when they smell the bait.$B$BSimply wait for nature to take its course and then all you need to do is search the, uh... byproduct for the film.$B$BI\'d offer you my special lupus pupus scupus for the job, but I left it back at the airstrip. I\'m afraid you\'ll have to conduct the... err... search the old-fashioned way.]', '[Iggy "Tailspin" Cogtoggle in the Scalding Pools wants you to bring him 8 pieces of Microfilm.]', '', '去找北風凍原的『尾旋』艾基‧榫栓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11729 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11729, 'zhTW', '[The Ultrasonic Screwdriver]', '[The unit you just dismantled had this inside of its mechanical innards.$B$BIt looks pretty complicated... certainly someone back at the airstrip would want to take a look at it. Maybe Crafty Wobblesprocket?]', '[Deliver the Ultrasonic Screwdriver to Crafty Wobblesprocket at Fizzcrank Airstrip.]', '', '去找北風凍原的卡芙緹‧顛鏈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11730 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11730, 'zhTW', '[Master and Servant]', '[The Ultrasonic Screwdriver is the ultimate tool. It can do anything to mechanical stuff!$B$BHead back into the pools and dismantle a number of Mechazod\'s robots. Then all you have to do is use the screwdriver on their remains, and I\'m betting that they\'ll turn to our side, for a short time anyway.$B$BI\'m pretty sure it won\'t work on the mechagnomes, so don\'t even bother with them.$B$BOh, and if you want to take anything from the robot\'s insides, you\'ll want to do so before using the screwdriver!]', '[Use the Ultrasonic Screwdriver to reprogram 15 robots and then return to Crafty Wobblesprocket at Fizzcrank Airstrip.$B$BMake sure to loot the dead robot before you reprogram it.]', '', '去找北風凍原的卡芙緹‧顛鏈。', '機器人已重新編程', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11731 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11731, 'zhTW', '投擲火炬', '你想當一名火焰雜耍師?你已經具備這個資格了嗎?你夠靈敏嗎?反應夠快嗎?你有勇氣嗎?假如你認為你已經具備以上的條件，那麼我們來做個小小的練習吧!$B$B拿著這些火炬，然後跑到營火的旁邊。你會看到火盆上閃爍著標誌。對標示的火盆投擲一根火炬。動作要快!你得在標誌消失以前擲出火炬才算數!$B$B在時間結束之前擊中足夠數量的火盆，然後回到這裡……我們再來進行下一個課程。', '在火炬投擲遊戲中獲勝，然後與吞火者大師談話。', '擊中8個火盆', '去找吞火者大師。', '火盆已擊中', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11732 AND `locale` = 'zhTW';
