INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12172,'zhTW','達拉然的能量調和','歡迎你，法師。$B$B你現在肯定在想，達拉然在哪裡？怎樣才能去那裡呢？讓我來幫你吧。$B$B不過在我教你如何傳送到我們偉大的城市去之前，你必須得對你自己和北裂境的魔網能量線進行調和。否則，你可能會在傳送過程中傷害到自己。$B$B帶上這塊魔網調和水晶，轉至這裡西面的眠月花園，在那裡的湍流之針下面的深坑中使用它。這樣你就完成了學習法術的準備。','群星之墓的大法師茉德拉的影像要你與北裂境的魔網能量線進行調和。','','去龍骨荒野的群星之墓找大法師茉德拉的影像。','與北裂境的魔網能量線調和','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12173 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12173,'zhTW','達拉然的能量調和','歡迎你，法師。$B$B你現在肯定在想，達拉然在哪裡？怎樣才能去那裡呢？讓我來幫你吧。$B$B不過在我教你如何傳送到我們偉大的城市去之前，你必須得對你自己和北裂境的魔網能量線進行調和。否則，你可能會在傳送過程中傷害到自己。$B$B帶上這塊魔網調和水晶，轉至這裡西南面的眠月花園，在那裡的湍流之針下面的深坑中使用它。這樣你就完成了學習法術的準備。','阿格瑪之錘的大法師艾薩斯·奪日者的影像要你與北裂境的魔網能量線進行調和。','','去龍骨荒野的阿格瑪之錘找大法師艾薩斯·奪日者的影像。','與北裂境的魔網能量線調和','','','',0);
