INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12191, 'zhTW', '乾了再砸!', '那些討厭的黑鐵矮人又回來了!我們要確定你有保護自己的能力。更重要的是，我們要知道你能保護我們的財產!S.T.O.U.T.已經準備好了，對吧?把免費招待的啤酒節樣品給喝光，然後拿酒杯來丟擲S.T.O.U.T.!擊中目標5次之後再來找我。', '使用免費招待的啤酒節樣品並丟中S.T.O.U.T.5次，然後和比索·迅提談談。', '', '去找杜隆塔爾的比索‧迅提。', '命中S.T.O.U.T.', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12192 AND `locale` = 'zhTW';
