INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12238, 'zhTW', '淨化德拉克薩隆', '好朋友，時候終於到了。德拉克薩隆很快就會從邪惡的不死生物中淨化，回復到原本高貴的樣子。我的靈魂將會安息，同時報答你的幫助，要塞裡面最珍貴的寶藏就是你的了，老兄!要塞的頂端有一座神聖的通靈塔，只要你爬到塔頂，你必須最後一次召喚我過去，而我將完成儀式。哎呀，召喚我照例需要一些材料。從要塞的倖存者身上收集一些魔精吧。', '德拉庫魯需要你在德拉克薩隆的火盆上使用德拉庫魯的藥劑。你需要五個耐久魔精才能使用德拉庫魯的藥劑。', '', '', '', '', '', '', 0);
