INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12249, 'zhTW', '熊神厄索克', '是時候了，$N。帶著這些灰燼，尋找寇荻安跟你提過的熊怪。如果他動身尋找厄索克，他一定在厄索克的巢穴附近，灰喉鎮的北邊。你會需要他的協助，你是無法獨力擊敗厄索克的。當你打敗厄索克之後，使用這些灰燼來淨化他的靈魂，屆時才知道我們的努力是否會付諸流水。', '琥珀松小屋的祭師賽苓要你找到厄索克之穴附近的圖爾·怒掌，在他的協助之下擊潰厄索克。達成任務之後，在厄索克的屍身上使用淨化過的沃達希爾灰燼。', '', '去找灰熊丘陵的祭師賽苓。', '淨化厄索克', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12250 AND `locale` = 'zhTW';
