INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12411, 'zhTW', '', '', '[Look for Anya in the Duskhowl Den near Solstice Village.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12412 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12412, 'zhTW', '[My Enemy\'s Friend]', '[If there is one thing I can get through your head, let it be this: the Alliance will be crushed in the Grizzly Hills.$B$BThere is far too much lumber, ore, game and strategic territory for us to give up on any single battlefront here.$B$BSo far we\'ve been successful... but there\'s something that could tip the scales in our enemy\'s favor.$B$BFar to the east  of here, at the Forest Edge\'s Post, local trappers seek to join the Alliance.  Slaughter them before they have the chance to do so.]', '[Conqueror Krenna in Conquest Hold wants you to slay 8 Silverbrook Hunters and their leader, Vladek, at the Forest\'s Edge Post.]', '', '去找灰熊丘陵的征服者克蓮娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12413 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12413, 'zhTW', '[Attack on Silverbrook]', '[A few hours ago, the trappers were nothing but peasants threatening to add their number to the Alliance\'s.$B$BNow they\'ve become something else... an uncertainty.  I do not like uncertainties.  Go to the hills outside their main town in northern Grizzly Hills, Silverbrook, and help my men crush them.]', '[Conqueror Krenna at Conquest Hold wants you to slay 8 Silverbrook Defenders in the Silverbrook Hills.]', '', '去找灰熊丘陵的征服者克蓮娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12414 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12414, 'zhTW', '[Mounting Up]', '[Cap\'n Stoutmantle left most of our calvary... cavlary... uh, horsemen at the fight for Venture Bay.$B$BWe chose a good place to put the camp \'cause there are tons of highland mustangs running around near here and in the Boulder Hills to the northeast. The Cap\'n put me in charge of capturing some of \'em.$B$BWill you help? I\'ve got a stick and some string, and there are loads of wild carrots growing near the camp. Pick the carrots and use them with the stick to lure in the mustang, then ride it back here.]', '[Ride 5 Highland Mustangs back to Squire Percy at the Westfall Brigade Encampment.]', '', '去找灰熊丘陵的侍從派西。', '高地野馬已歸還', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12415 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12415, 'zhTW', '[The Horse Hollerer]', '[The Alliance\'s \'Westfall Brigade\' is camped far to the north, near Thor Modan. They have foolishly divided their forces to contest our control of Venture Bay, and they have been left without cavalry.$B$BThey\'re now trying to capture and tame the wild highland mustangs that roam the area around the Westfall Brigade Encampment and Boulder Hills. We must stop them before they\'re able to replace their lost mounts. Take this and throw it near the horses to drive them away.]', '[Scare 15 Highland Mustangs and return to Soulok Stormfury at Camp Oneqwah.]', '', '去找灰熊丘陵的索羅克‧風暴之怒。', '高地野馬已被驚嚇', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12416 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12416, 'zhTW', '[Heated Battle]', '[The Scourge have overrun the shrine. The shrine\'s keeper, Dahlia Suntouch, is nowhere to be found. The red wyrms that fell in the shrine\'s defense now beset us in the form of twisted skeletal emberwyrms. The situation is dire, $r.$B$BCaptain Iskandar leads a group of your kind in stemming the flow of the Scourge out of the shrine.$B$BGo to his aid... but please stay behind his men. The flow of Scourge is endless and I don\'t want to lose you in one of those scarred canyons.]', '[Aid Captain Iskandar in holding the canyons by participating in the death of 12 Frigid Ghoul Attackers, 8 Frigid Geist Attackers, and 1 Frigid Abomination Attacker.$B$BReturn to Ceristrasz once you have finished this task.]', '', '去找龍骨荒野的賽利斯塔茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12417 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12417, 'zhTW', '[Return to the Earth]', '[I have another task that needs attention. I have brothers who are falling in the battle overhead and if we do not act quickly, they will only bolster the emberwyrm ranks.$B$BGet into the shrine through one of the other passes to the south or north... the Scourge presence should be lighter there.$B$BSearch the shrine for ruby acorns that have fallen from the tree and plant them near the bodies of my fallen brood. Through this, they can give new life... a proud fate for any of my kind.]', '[Enter the Ruby Dragonshrine through one of the northern or southern passes and search for Ruby Acorns.  Use the Ruby Acorns on the fallen red dragons to return their bodies to the earth.  Return to Ceristrasz once the task is complete.]', '', '去找龍骨荒野的賽利斯塔茲。', '紅寶石守護者已回歸大地', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12418 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12418, 'zhTW', '[Through Fields of Flame]', '[I have one final task for you, $r... one that should turn the tide of this fight.$B$BReturn to the shrine and kill the necromancers that are fueling this onslaught. With them dead, we should be able to beat these forces back and eventually retake the shrine.$B$BI also need you to find the source of the corruption under the shrine and put an end to it.$B$BI know I have asked a lot of you, but if you do this for me, we will win this battle.]', '[Enter the Ruby Dragonshrine through one of the northern or southern passes, then kill 6 Frigid Necromancers and eliminate the source of the corruption under the shrine. Return to Ceristrasz once the task is complete.]', '', '去找龍骨荒野的賽利斯塔茲。', '', '紅寶石腐化已淨化', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12419 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12419, 'zhTW', '[The Fate of the Ruby Dragonshrine]', '[As you pick up the brooch, its faint glow brightens slightly.$B$BKrasus will want to know of Dahlia\'s fate. Take the brooch to him at Wyrmrest.]', '[Bring Dahlia Suntouch\'s Ruby Brooch to Krasus in the Ruling Council Chamber at Wyrmrest and inform him of Dahlia\'s fate.]', '', '去找龍骨荒野的卡薩斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12420 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12420, 'zhTW', '每月啤酒俱樂部', '會員享有優惠。成為「每月啤酒俱樂部」的會員，表示你有管道獲得到最新、最青的啤酒。$B$B帶著你的「每月啤酒」俱樂部會員表格給拉金·雷酒，他就在鐵爐堡的石火旅店中。', '把「每月啤酒」俱樂部會員表格帶給拉金·雷酒，他就在鐵爐堡的石火旅店中。', '', '去找丹莫羅的拉金‧雷酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12421 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12421, 'zhTW', '[Brew of the Month Club]', '[There is strength in numbers, $n.  Being part of the "Brew of the Month" club means knowing you and your brethren will always have access to the best brew.$B$BBring your "Brew of the Month" club membership form to Ray\'ma in the Darkbriar Lodge in Orgrimmar\'s Valley of Spirits.]', '[Bring the "Brew of the Month" club membership form to Ray\'ma in the Darkbriar Lodge in Orgrimmar\'s Valley of Spirits.]', '', '去找奧格瑪的雷瑪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12422 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12422, 'zhTW', '[Tactical Clemency]', '[Listen, $N.  I need you to act with discretion and speed.$B$BOne of Krenna\'s top sergeants has captured a trapper outcast outside of Silverbrook.  Now, if things turn out the way they usually do, the prisoner is going to be executed before the day is over.$B$BWe can\'t let that happen.  You see, the prisoner matches the description of Mikhail\'s older daughter in his diary.$B$BIf we set her loose and follow her closely, she\'ll lead us to whoever\'s controlling the trappers.  Take this letter to her.]', '[Deliver the Letter of Amnesty to the Captured Trapper in Silverbrook Hills.]', '', '去找灰熊丘陵的被俘虜的陷捕者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12423 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12423, 'zhTW', '[Mikhail\'s Journal]', '[From what you can gather, this journal was written by a denizen of Silverbrook named Mikhail.$B$BIt is written in some variant of the common human tongue.  Perhaps you should bring this back to Conqueror Krenna.]', '[Bring Mikhail\'s Journal to Conqueror Krenna in Conquest Hold.]', '', '去找灰熊丘陵的征服者克蓮娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12424 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12424, 'zhTW', '[Gorgonna]', '[This book is written in the pig-tongue the humans use.  It needs to be burned immediately.$B$BHand it to my sister Gorgonna and do not waste my time.]', '[Bring Mikhail\'s Journal to Gorgonna in Conquest Hold.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12425 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12425, 'zhTW', '', '', '[Speak to Ruuna the Blind at Ruuna\'s Camp near Vordrassil Pass.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12426 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12426, 'zhTW', 'DEPRECATED', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12427 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12427, 'zhTW', '[The Conquest Pit: Bear Wrestling!]', '[So you\'re interested in the fights, eh?  Well, Krenna has outlawed pit-fighting for all enlisted combatants.  But you, my friend, are technically a free agent and are not included in this prohibition.$B$BNice loophole, eh?$B$BAnyway, if you\'re interested I can start you off with something easy, a measly bear.  I\'ll even let you bring friends along!]', '[Defeat Ironhide inside the Conquest Pit and speak to Bookie Vel\'jen for a reward.]', '已擊敗鐵皮', '去找灰熊丘陵的布齊‧維爾占。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12428 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12428, 'zhTW', '[The Conquest Pit: Mad Furbolg Fighting]', '[You\'re not bad.  Not bad at all.$B$BThink you can take a furbolg?  What about one of those extra-large crazed Northrend furbolgs?$B$BGood, good.  Get your crew together, and head to the ring.  Let\'s give these folks a show... maybe we can earn some more coin while we\'re at it.]', '[Defeat Torgg Thundertotem inside the Conquest Pit and speak to Bookie Vel\'jen for a reward.$B$B]', '已擊敗托爾格·雷霆圖騰', '去找灰熊丘陵的布齊‧維爾占。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12429 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12429, 'zhTW', '[The Conquest Pit: Blood and Metal]', '[It\'s nice to have a real fighter around these parts... we\'d only had prisoners and caged beasts for the past few weeks.  The people get bored, ya know?$B$BAnyhow, your next challenge is a genuine iron golem stolen from the depths of Thor Modan... think you can swing it?]', '[Defeat Rustblood inside the Conquest Pit and speak to Bookie Vel\'jen for a reward.$B$B]', '已擊敗鏽血', '去找灰熊丘陵的布齊‧維爾占。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12430 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12430, 'zhTW', '[The Conquest Pit: Death Is Likely]', '[I\'m gonna shoot straight with ya, kid.  This next contender\'s a murderer.$B$BLiterally.$B$BHe was to be executed last week, but he strangled the hangman with his left hand, so Krenna\'s guards sort of let me have him.$B$BFeel free to pass on this one.  I wouldn\'t blame ya.]', '[Defeat Horgrenn Hellcleave inside the Conquest Pit and speak to Bookie Vel\'jen for a reward.$B$B]', '已擊敗霍格倫·地獄裂', '去找灰熊丘陵的布齊‧維爾占。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12431 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12431, 'zhTW', '[The Conquest Pit: Final Showdown]', '[You must\'ve really upset Krenna.  She and Gorgonna have had a spat and you\'re wanted in the pit immediately.$B$BThere are some wild rumors that it\'s a fight to the death!  That would be bad news for you, but great news for our business venture!$B$BAt any rate, you can\'t run away from fate... best get in there on the quick and get it over with.]', '[Defeat Krenna in the Conquest Pit and speak to Gorgonna for a reward.]', '', '去找灰熊丘陵的高耿娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12432 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12432, 'zhTW', '[Riding the Red Rocket]', '[You there, $r! Get your lousy carcass over here!$B$BThe Alliance have a shipment of lumber all ready for transport just northeast of here. Since getting our hands on that wood is out of the question, there\'s only one thing to do - destroy it!$B$BThe goblin at the end of the dock here has some torpedoes all ready to go. He\'s got all the fuel for them on the docked goblin ship to the north.$B$BGet some fuel, then commandeer one of the torpedoes and ride it into their ship.$B$BDismissed!]', '[General Gorlok at the lighthouse in Venture Bay wants you to destroy the Alliance Lumber Boat.$B$BGeneral Gorlok will only be present at the lighthouse when the Horde has it in their possession.]', '', '去找灰熊丘陵的戈洛科將軍。', '聯盟木材貨運已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12433 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12433, 'zhTW', '[Seeking Solvent]', '[Gah! Not again. Another blown gasket....$B$BEvery time one of these goes, lubricant gums up all of the gears. Without solvent, it takes hours to clean.$B$BTell ya what, $r. There\'s some fancy rocket fuel on the Venture Company barge in the dock there - element 115 I think they call it. That stuff makes for a great solvent.$B$BGet me one of those and I\'ll make it worth your trouble.]', '[Gurtor at the Venture Bay Horde base wants you to bring him a canister of Element 115.]', '', '去找灰熊丘陵的葛特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12434 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12434,'zhTW','繼續尋找溶解劑','','','','去找灰白之丘的古圖爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12435 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12435, 'zhTW', '', '', '[Speak with Lord Devrestrasz at Wyrmrest Temple.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12436 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12436, 'zhTW', '[Supplemental Income]', '[Hail, $c.  You\'ll find that here at Conquest Hold, we buy and sell what Krenna wants us to buy and sell... at the price that Krenna wants us to buy and sell.$B$BAll this is stifling business.  I\'m hoping to make a little bit of coin on the side and feed our grunts at the same time.  Why don\'t you go hunt down some stag and bring me the venison?$B$BThey\'re numerous in the area, so bring me only the best meat.]', '[Provisioner Lorkran at Conquest Hold wants you to obtain 5 Succulent Venison from  the nearby Tallhorn Stag.]', '', '去找灰熊丘陵的補給官羅克芮。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12437 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12437, 'zhTW', '[Riding the Red Rocket]', '[Listen, $n. This battle is as much over resources as tactical supremacy.$B$BI have a mission that could turn the tide in our struggle against the Horde here.$B$BThere are torpedoes at the end of the dock that we can use to take down the Horde\'s lumber ship to the northwest.$B$BYou\'ll need to get some of the fuel that\'s stored on the docked goblin ship just north of here, then ride one of the torpedoes into their transport!]', '[Commander Howser at the lighthouse in Venture Bay wants you to destroy the Horde lumber shipment.$B$BCommander Howser will only be present at the lighthouse when the Alliance has it in their possession.]', '', '去找灰熊丘陵的指揮官豪瑟。', '部落運木船已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12438 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12438, 'zhTW', '懸賞:克羅格·毀誓者', '公告者:伊魯希亞·盧恩$B$B克羅格·毀誓者，天譴軍的血肉巨人，必須為我的丈夫、小孩、與我的摯友語幕一家的死負責。具有足夠勇氣獵取這份獎金的人可以在東南方腐屍農地邊緣的懸崖找到克羅格。$B$B我要正義!殺死克羅格·毀誓者!$B$B假使有人殺掉了克羅格·毀誓者，我已經預先將金錢與物品交給了大領主李奧瑞克·馮·澤爾迪格，請他代發。$B$B請為我們復仇!', '殺死克羅格·毀誓者，然後向大領主李奧瑞克·馮·澤爾迪格領取賞金，他就在龍骨荒野的溫特加德要塞。', '', '去找龍骨荒野的李奧瑞克·馮·澤爾迪格公爵。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12439 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12439, 'zhTW', '', '', '[Speak to Rodney Wells at Wintergarde Keep to secure a ride to Stars\' Rest in western Dragonblight.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12440 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12440, 'zhTW', '', '', '[Speak with the Image of Archmage Modera at Stars\' Rest in western Dragonblight. ]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12441 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12441, 'zhTW', '懸賞:高階薩滿血掌', '公佈者:德羅菲$B$B就在異法陵地之上，我的表親史克羅堤和布羅特，遭到一幫邪惡的血掌獾狼怪襲擊。我們雖然企圖脫逃，但史克羅堤和布羅特恐怕已遭不測。$B$B我要懲罰這些傢伙!是否有勇者願意冒險前往東南方，也就是龍骨荒野的邊境，異法陵地上格殺高階薩滿血掌以及他的親信?$B$B本人將提供豐渥的賞銀交付給大領主李奧瑞克·馮·澤爾迪格，由他發放給任何完成此任務者!', '殺掉高階薩滿血掌，並回報給大領主李奧瑞克·馮·澤爾迪格以獲取你的獎賞;他就在龍骨荒野上的溫特加德要塞裡。', '', '去找龍骨荒野的李奧瑞克·馮·澤爾迪格公爵。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12442 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12442, 'zhTW', '懸賞:突襲軍指揮官艾尤圖斯', '公告者:大領主李奧瑞克·馮·澤爾迪格$B$B第七軍團的部隊在溫特加德東北方的小徑上遭到突襲軍指揮官艾尤圖斯與一群沒大腦的血色突襲軍狂徒襲擊。面對此等冷血狡詐的行為必須以以暴制暴!$B$B溫特加德要求正義!到東北方的突襲營地找出突襲軍指揮官艾尤圖斯，終結他可悲的生命。$B$B我會獎賞任何接受這任務的勇者!', '殺掉突襲軍指揮官艾尤圖斯，並回報給大領主李奧瑞克·馮·澤爾迪格以獲取你的獎賞;他就在龍骨荒野上的溫特加德要塞裡。', '', '去找龍骨荒野的李奧瑞克·馮·澤爾迪格公爵。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12443 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12443, 'zhTW', '[Seeking Solvent]', '[Gah! Not again. Another blown gasket....$B$BEvery time one of these goes, lubricant gums up all of the gears. Without solvent, it takes hours to clean.$B$BTell ya what, $r. There\'s some fancy rocket fuel on the Venture Company barge in the dock there - element 115 I think they call it. That stuff makes for a great solvent.$B$BGet me one of those and I\'ll make it worth your trouble.]', '[Barblefink at the Alliance base in Venture Bay wants you to bring him a canister of Element 115.]', '', '去找灰熊丘陵的巴爾玻芬克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12444 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12444, 'zhTW', '[Blackriver Skirmish]', '[The Venture Company\'s on its way out of Grizzly Hills.  They used to run logging operations here, but things got a little too dangerous for them.$B$BTheir abandoned sites are up for grabs and we sure as hell can\'t let the Horde get their hands on them.$B$BThe Blackriver Logging Camp is the smallest of the three logging sites in this zone, but we still need it.  Do your part and fend off the Horde forces.  Any lumber they get here will be made into weapons to be used against us elsewhere.]', '[Scout Captain Carter wants you to kill 10 Horde units or players in the Blackriver Logging Camp.]', '', '去找灰熊丘陵的斥候隊長卡特。', '黑河的部落成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12445 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12445, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12446 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12446,'zhTW','繼續尋找溶解劑','','','','去灰白之丘找風險灣的巴布芬克。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12447 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12447, 'zhTW', '', '', '[Travel to the Obsidian Dragonshrine Northwest of Wymrest and just West of the Wrath Gate. Locate Serinar inside of the shrine and offer him your aid.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12448 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12448, 'zhTW', '[Heated Battle]', '[The Scourge have overrun the shrine. The shrine\'s keeper, Dahlia Suntouch, is nowhere to be found. The red wyrms that fell in the shrine\'s defense now beset us in the form of twisted skeletal emberwyrms. The situation is dire, $r.$B$BCaptain Drayzen leads a group of your kind in stemming the flow of the Scourge out of the shrine.$B$BGo to his aid... but please stay behind his men. The flow of Scourge is endless and I don\'t want to lose you in one of those scarred canyons.]', '[Aid Captain Drayzen in holding the canyons by participating in the death of 12 Frigid Ghoul Attackers, 8 Frigid Geist Attackers, and 1 Frigid Abomination Attacker.$B$BReturn to Vargastrasz once you have finished this task.]', '', '去找龍骨荒野的凡加斯塔茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12449 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12449, 'zhTW', '[Return to the Earth]', '[I have another task that needs attention. I have brothers who are falling in the battle overhead and if we do not act quickly, they will only bolster the emberwyrm ranks.$B$BGet into the shrine through the pass in the south... the Scourge presence should be lighter there.$B$BSearch the shrine for ruby acorns that have fallen from the tree and plant them near the bodies of my fallen brood. Through this, they can give new life... a proud fate for any of my kind.]', '[Enter the Ruby Dragonshrine through the southern pass and search for Ruby Acorns.  Use the Ruby Acorns on the fallen red dragons to return their bodies to the earth.  Return to Vargastrasz once the task is complete.]', '', '去找龍骨荒野的凡加斯塔茲。', '紅寶石守護者已回歸大地', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12450 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12450, 'zhTW', '[Through Fields of Flame]', '[I have one final task for you, $r... one that should turn the tide of this fight.$B$BReturn to the shrine and kill the necromancers that are fueling this onslaught. With them dead, we should be able to beat these forces back and eventually retake the shrine.$B$BI also need you to find the source of the corruption under the shrine and put an end to it.$B$BI know I have asked a lot of you, but if you do this for me, we will win this battle.]', '[Enter the Ruby Dragonshrine through the southern pass, then kill 6 Frigid Necromancers and eliminate the source of the corruption under the shrine. Return to Vargastrasz once the task is complete.]', '', '去找龍骨荒野的凡加斯塔茲。', '', '紅寶石腐化已淨化', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12451 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12451, 'zhTW', '', '', '[Speak with Scout Vor\'takh at Camp Oneqwah.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12452 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12452,'zhTW','晶紅龍殿的命運','把達莉亞的紅寶石胸針帶給賽里斯特拉茲，並告知他她的命運。','將妲莉雅的紅寶石墜飾交給賽利斯塔茲，並將妲莉雅之死告訴他。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12453 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12453, 'zhTW', '[Eyes Above]', '[I\'ve been asked to lend my support to our efforts against the Alliance.  At the moment our military forces are about evenly matched and we\'re looking for ways to find an edge.$B$BThe imperial eagles that fly over the mountains and trees in this area would make excellent scouts for us.  Take this silver feather and use it to bind my sight to that of them.$B$BBeing able to see our enemy\'s movements will grant us the strategic advantage we need.  You\'ll find abundant eagles in the mountains to the east.]', '[Windseer Grayhorn wants you to use the Silver Feather on 6 Imperial Eagles in Grizzly Hills.]', '', '去找灰熊丘陵的風先知灰角。', '帝王鷹之眼已被束縛', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12454 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12454, 'zhTW', '[Cycle of Life]', '[Ysera sleeps in the Emerald Dream, watching over both the Dream and Azeroth. But a horrible nightmare has taken hold in the Dream, and now I fear that Ysera is being affected by it.$B$BRecently, I asked her to aid in the fight against the Scourge that are raising frostwyrms at the other dragonshrines. She misunderstood.$B$BInstead, she told our dragonshrine\'s defenders to treat those not of the green dragonflight as enemies.$B$BI need you to slay some of the skytalons. The shrine must regain its balance.]', '[Nishera the Garden Keeper at the Emerald Dragonshrine has asked you to slay 5 Emerald Skytalons.]', '', '去找龍骨荒野的『花園看守者』尼夏拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12455 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12455, 'zhTW', '[Scattered To The Wind]', '[The munitions drop went badly, friend. The shipment of ammo from Westguard Keep was intercepted by the frostwyrms circling overhead. The flying machines were torn apart in a matter of seconds and their cargo was scattered to the wind. Most of it is still topside - on the Carrion Fields.$B$BI\'m gonna need you to go back up and recover the munitions crates that are scattered all over this damned place.$B$BHurry it up! We can\'t start this offensive without guns and ammo, $g老兄：小妹;!]', '[Ambo Cash at the Wintergarde Mausoleum in Dragonblight wants you to recover 8 Wintergarde Munitions.]', '', '去找龍骨荒野的安柏·凱許。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12456 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12456, 'zhTW', '艾里史卓斯的長羽', '我能感覺到神殿尚未完全回歸平衡。青綠看守者已經被我們的舉動所觸怒，我感覺他聽不進我們任何理由。$B$B艾里史卓斯是一頭巨大的天爪，棲息在翡翠龍殿的南方，他同時控有整個龍殿的空中防禦，而恐怕我們得應付他的攻擊。$B$B拿著這些天爪蛻皮，並把蛻皮放在他視力所及的地面上，他會飛下來的。把他的長羽帶給我。', '翡翠龍殿的『花園看守者』尼夏拉要求你取得艾里史卓斯的長羽。', '', '去找龍骨荒野的『花園看守者』尼夏拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12457 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12457, 'zhTW', '[The Chain Gun And You]', '[We\'ve set up chain guns and barricades directly to the east and to the west. Our injured soldiers are hiding in both rooms - trying their best to not alert the mindless ghouls to their presence.$B$BNow that we have ammo, I need you to man one of the chain guns and use it to blast a path clear for our soldiers! Once you\'re on board, call a soldier out from hiding and then lay down heavy fire to keep the Scourge off him!$B$BGet a move on!]', '[Ambo Cash at the Wintergarde Mausoleum in Dragonblight wants you to save 8 Injured 7th Legion Soldiers.]', '', '去找龍骨荒野的安柏·凱許。', '已救出受傷的第七軍團士兵', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12458 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12458, 'zhTW', '[Seeds of the Lashers]', '[We need more weapons in the fight against the Scourge. The natural properties of the Emerald Dragonshrine to the southeast may be the answer.$B$BAny unliving creature, save those that Sylvanas has redeemed, that steps foot in the dragonshrine falls to dust.$B$BI want to test a theory, and I want you to be my instrument in doing so, young $r. Go to the Emerald Dragonshrine and take the seeds from the emerald lashers therein.]', '[Lord Itharius at the top of Wyrmrest Temple has asked you to return with 3 Lasher Seeds.]', '', '去找龍骨荒野的伊薩里奧斯領主。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12459 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12459, 'zhTW', '[That Which Creates Can Also Destroy]', '[Since we only have three seeds, we must put them to the best possible use.$B$BYour targets are one of the reanimated frost wyrms circling to the north near Galakrond\'s Rest, Turgid the Vile in the ruined barracks at the Carrion Fields to the east, and Overseer Deathgaze at Jintha\'kalar far to the northeast.$B$BWhile the seeds would outright destroy one of the lesser Scourge, they will greatly weaken these three. Enough so, in fact, that you should be able to handle them on your own.]', '[Lord Itharius at the top of Wyrmrest Temple has asked you to destroy a Weakened Reanimated Frost Wyrm, Weakened Turgid the Vile, and Weakened Overseer Deathgaze.]', '', '去找龍骨荒野的伊薩里奧斯領主。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12460 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12460, 'zhTW', '到晶紅龍殿報到', '我們在晶紅龍殿需要你。龍群已經被藍龍和天譴軍團四面包圍了…他們一點也不比我們好過。情況似乎非常危急，但這也給了我們一個結交珍貴盟友的好機會。我派出了一個兵團來幫助紅龍對抗晶紅龍殿的天譴軍團，如果你願意作戰的話，請前往龍殿東方的山脊上找賽利斯塔茲，然後盡你所能的提供協助。', '向晶紅龍殿東邊山脊上的賽利斯塔茲報到，就在龍眠神殿的西方。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12461 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12461, 'zhTW', '', '', '[Report to Vargastrasz on a ridge outside of the Ruby Dragonshrine, just east of Agmar\'s Hammer.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12462 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12462, 'zhTW', '[Breaking Off A Piece]', '[Just down the steps lies the gateway to damnation: Scourge as far as the eye can see and getting thicker with each passing moment. What little intelligence we\'ve been able to gather indicates that two Scourge necrolords are furiously working at emptying the first two crypts down below. Before we can breach the inner chamber to Thel\'zan, we\'ll need to take care of those two clowns and their Naxxramas cronies.$B$BGo down into the mausoleum and take out the necrolords and the Naxxramas dreadguards and shades.]', '[Yord "Calamity" Icebeard at the Wintergarde Mausoleum in Dragonblight wants you to kill Necrolord X\'avius, Necrolord Horus, and 15 Naxxramas Scourge.$B$B]', '', '去找龍骨荒野的『災禍』約德·冰鬚。', '', '', '納克薩瑪斯的天災已擊殺', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12463 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12463, 'zhTW', '', '', '[Ambo Cash at the Wintergarde Mausoleum in Dragonblight wants you to find Plunderbeard.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12464 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12464, 'zhTW', '[My Old Enemy]', '[My old enemy, High General Abbendis, has come to Northrend.$B$BSomehow she survived the attacks upon Tyr\'s Hand and brought a small force north. They\'ve established New Hearthglen to the south.$B$BWhile they could prove useful in fighting the Scourge, Abbendis herself is far too shrewd an opponent to let live. Trust me, if we let them stand, she will be at our throats before the dust settles.$B$BSo, we\'ll deprive them of their leadership and go about our business. Bring me her head as proof.]', '[Deliver The High General\'s Head to Commander Eligor Dawnbringer at Wintergarde Keep.]', '', '去找龍骨荒野的指揮官艾利格·攜晨者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12465 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12465, 'zhTW', '[Plunderbeard\'s Journal]', '[Whatever was written on the remaining pages of Plunderbeard\'s journal must be recovered. Search the chambers located on the other side of this tunnel for Plunderbeard\'s assailants. They must be the ones who tore the journal apart!$B$BShould you recover the missing pages, return them to Ambo Cash at the entrance of the Wintergarde Mausoleum.]', '[Recover Page 4 of Plunderbeard\'s Journal, Page 5 of Plunderbeard\'s Journal, Page 6 of Plunderbeard\'s Journal, and Page 7 of Plunderbeard\'s Journal and return them to Ambo Cash at the Wintergarde Mausoleum in Dragonblight.]', '', '去找龍骨荒野的安柏·凱許。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12466 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12466, 'zhTW', '', '', '[Report to Legion Commander Tyralion at the 7th Legion Front in central Dragonblight.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12467 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12467, 'zhTW', '[Chasing Icestorm: Thel\'zan\'s Phylactery]', '[Your frostwyrm is out there.$B$B<Tyralion points west.>$B$BAnd it\'s a big one!$B$BWhen you\'re ready to fight, go speak with "Wyrmbait." He\'ll "fetch" her. Once Icestorm is close enough we\'ll chain her to the ground and finish her off! Hopefully, with your help, we\'ll be able to take her down and get you that phylactery.$B$BOnce you\'ve got the phylactery, return to Wintergarde Keep and report to High Commander Halford Wyrmbane. He\'s been making preparations for the final showdown with Thel\'zan.]', '[Recover Thel\'zan\'s Phylactery from Icestorm and return it to High Commander Halford Wyrmbane at Wintergarde Keep.$B$B]', '', '去找龍骨荒野的高階指揮官海弗德·龍禍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12468 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12468, 'zhTW', '', '', '[Speak to Sergeant Nazgrim in Conquest Hold.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12469 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12469, 'zhTW', '[Return to Sender]', '[Upon closer examination, the goblin appears to have been running a pack full of explosives across the wastes for delivery. The harpy feathers half-buried in the snow nearby suggest how he met his ill fate.$B$BIt appears that the goblin was bringing the explosives towards the Wrath Gate from somewhere to the east. It seems most prudent to follow the ridge back to the east and inform the sender of their runner\'s fate.]', '[Follow the ridge to the east and deliver the pack of explosives to Xink at Nozzlerust Post in northern Dragonblight.]', '', '去找龍骨荒野的辛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12470 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12470, 'zhTW', '[Mystery of the Infinite]', '[A time storm at the Bronze Dragonshrine to the northeast is keeping immortals from entering.$B$BThe Infinite Dragonflight are in a fight inside with the defenders to wrest control of the dragonshrine. We must take this opportunity to gain information.$B$BYou are not immortal. You can cross into the dragonshrine and use the Hourglass of Eternity. Protect the hourglass for long enough and the leader of the Infinite Dragonflight should be revealed.$B$BBe warned, the Infinite Dragonflight will try to stop you!]', '[Chromie, at the top of Wyrmrest Temple, has asked you to travel to the Bronze Dragonshrine. Once inside, place the Hourglass of Eternity on the ground.$B$BProtect the hourglass for as long as it lasts and then return to her with whatever information you gain.]', '永恆沙漏已受保護', '去找龍骨荒野的克羅米。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12471 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12471, 'zhTW', '', '', '[Speak to Karuk about the Captured Tuskarr Prisoner.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12472 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12472, 'zhTW', '[Finality]', '[Thanks to your heroics, Lord Fordragon has given the command to launch a full assault against Thel\'zan. 7th Legion have made their way into the summoning chamber of the mausoleum and located what appears to be a gateway to hell. The only piece that\'s missing now is you.$B$BTake the phylactery and report to Legion Commander Yorik inside the Wintergarde Mausoleum.$B$BThere is a tunnel that the Scourge dug out just outside the keep that you can take to get to Yorik quickly. Go now, $N! Lead us to victory!]', '[Take Thel\'zan\'s Phylactery to Legion Commander Yorik inside the Wintergarde Mausoleum in Dragonblight.]', '', '去找龍骨荒野的軍團指揮官約立克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12473 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12473, 'zhTW', '[An End And A Beginning]', '[Every good story has a beginning and an ending, $N. While your story is far from over, I\'ll be damned if it\'s not already turning out to be the stuff of legend! No matter what happens to us when this is all over, what you\'ve done at Wintergarde will be a tale told for years to come.$B$BNow, ally, when you are ready I will use the phylactery to coax Thel\'zan out of hiding.$B$BShould we somehow succeed, report the victory to High Commander Halford Wyrmbane at Wintergarde Keep.]', '[Defeat Thel\'zan the Duskbringer and report to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.]', '已擊敗黃昏使者瑟爾贊', '去找龍骨荒野的高階指揮官海弗德·龍禍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12474 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12474, 'zhTW', '', '', '[Venture to Fordragon Hold in Dragonblight and speak with Highlord Bolvar Fordragon. ]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12475 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12475, 'zhTW', '[What Secrets Men Hide]', '[After the betrayal at the Forgotten Shore, Prince Arthas - with Muradin in tow - began his quest for Frostmourne. Could the location of the cavern where Frostmourne was found be near? What secrets could it hold? While the orb has no answers for these questions, it does show me something.$B$BTo the northeast of Wintergarde Keep is an outpost built by the Scarlet Onslaught. Somewhere within that outpost is a map. The orb tells me that this map will be of great use to us.$B$BRetrieve it!]', '[Zelig the Visionary at Wintergarde Keep in Dragonblight wants you to find the Onslaught Map and return it to him.]', '', '去找龍骨荒野的『遠識』齊利格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12476 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12476, 'zhTW', '[The Return of the Crusade?]', '[To the northeast of Wintergarde Keep is a newly built encampment, set up by the Scarlet Crusade - or rather - the Scarlet Onslaught as they now call themselves. While we are unsure as to why they are in Northrend, they are certainly no less dangerous than they were before. As of last night the Scarlet Onslaught has killed twelve of our soldiers. They must be taught a lesson, $N.$B$BGo to Onslaught Base Camp and thin them out. $B$B]', '[Commander Lynore Windstryke at Wintergarde Keep in Dragonblight wants you to kill 20 Scarlet Onslaught at the Onslaught Base Camp.]', '', '去找龍骨荒野的指揮官萊諾爾·風矛。', '血色十字軍已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12477 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12477, 'zhTW', '[The Path of Redemption]', '["The Path of Redemption," ever heard of it? It is allegedly a journal that holds the prophetic ramblings of High General Abbendis of the Scarlet Onslaught. Within that book can be found the motivations and goals of the Scarlet zealots - not to mention a whole lot of insanity.$B$BVenture to Onslaught Base Camp, northeast of Wintergarde Keep, and recover a copy of "The Path of Redemption" from one of the Onslaught soldiers.]', '[Return "The Path of Redemption" to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.]', '', '去找龍骨荒野的高階指揮官海弗德·龍禍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12478 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12478, 'zhTW', '[Frostmourne Cavern]', '[They have labeled the cave as Frostmourne Cavern. Why the Scarlet Onslaught is interested in such things is unknown, but by the look of things, the area surrounding the cave is heavily guarded. Nonetheless, we must proceed!$B$BTake this scrying orb and travel north out of town and then northwest towards Scarlet Point. Make your way into the cave and battle your way to the bottom. Once there, use the orb. Return here with what you discover.]', '[Zelig the Visionary at Wintergarde Keep in Dragonblight wants you to use Zelig\'s Scrying Orb at the bottom of Frostmourne Cavern. Unlock the secrets of the past!]', '', '去找龍骨荒野的『遠識』齊利格。', '過去的秘密已揭露', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12479 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12479,'zhTW','前往北裂境！','歡迎來到巫妖王之怒朋友家庭測試版。利用我身旁的傳送門開始你前往北裂境的旅程。$B$B你可以選擇要傳送至北風凍原的驍勇要塞或是凜風峽灣的瓦爾加德。','與北風凍原、驍勇要塞的聯盟招募員或是凜風峽灣、復仇臺地的聯盟招募員交談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12480 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12480,'zhTW','前往北裂境！',' 描述 歡迎來到巫妖王之怒朋友家庭測試版。利用我身旁的傳送門開始你前往北裂境的旅程。$B$B你可以選擇要傳送至北風凍原的戰歌堡或是凜風峽灣的復仇臺地。\\r\\n\\r\\n \\r\\n\\r\\n','與北風凍原、戰歌堡的部落招募員或是凜風峽灣、復仇臺地的部落招募員交談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12481 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12481, 'zhTW', '[Adding Injury to Insult]', '[The vrykul are being clever about this.  Fortunately I\'ve a trick up my sleeve.$B$BThis leader of theirs, Bjorn, is a real hothead.  We\'ve pieced together enough of their language to fashion what we think is a good insult.  Something involving his mother and large barnyard animals... we\'re not quite sure.$B$BTake this piece of paper and read it to him.  Once he starts chasing you, lure him back here.  We\'ll make sure he doesn\'t make it out alive.]', '[Read the Vrykul Insult to Bjorn Halgurdsson in Baleheim, then lead him back to Lydell\'s Ambush and help slay him.]', '', '去找嚎風峽灣的黎戴爾。', '已羞辱比約恩·哈爾古森', '已擊敗比約恩·哈爾古森', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12482 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12482, 'zhTW', '[Against Nifflevar]', '[We await reinforcements from Vengeance Landing to move against Nifflevar.  If we were to capture it earlier, though, it would provide us with a great advantage over the Alliance.$B$BHead into town and see if you can put a dent in their numbers.]', '[Ranger Captain Areiel wants you to go to Nifflevar and slay 5 Dragonflayer Warriors, 4 Dragonflayer Rune-Seers and 4 Dragonflayer Hunting Hounds.]', '', '去找嚎風峽灣的遊俠隊長艾瑞依爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12483 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12483, 'zhTW', '[Shimmercap Stew]', '[Say, while yer here, how bout ya help ol\' Prigmon with a little chore? I got a friend who can make a mean stew - one like ya never tasted before!$B$BThere be a few ingredients found in these parts that he be needin\'. They be in ruins to the southwest and the camp just north o\' here.$B$BWhatd\'ya say, mon?]', '[Prigmon in Granite Springs wants you to collect 5 Shimmering Snowcaps and 5 Ice Serpent Eyes from Drak\'Zin Ruins and 5 Sweetroot from Zeb\'Halak.]', '', '去找灰熊丘陵的皮格蒙。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12484 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12484, 'zhTW', '[Scourgekabob]', '[Ugh.$B$BWrappin\' up these unfortunate trolls be makin\' my heart ache, but not so much as my back!$B$BHelp ol\' Prigmon out and haul one of these carcasses over to Mack.$B$BIf we don\'t burn \'em they be walkin\' again in no time.]', '[Prigmon at Granite Springs wants you to bring a Mummified Troll Carcass to Mack Fearsen and place it in the fire.]', '', '去找灰熊丘陵的麥客‧菲爾森。', '木乃伊屍骸已焚燒', '', '', '', 0);
