INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12506, 'zhTW', '司瑟拉圖斯祭壇的麻煩', '蛇神的祭壇有麻煩了。天譴軍團的出現虛弱了這片大地，$r。現在輪到了野性諸神。我們知道德拉克瑞會利用這個機會對神祇做出邪惡的事。我需要你充當我的耳目。司瑟拉圖斯祭壇就在北邊大道的盡頭。偷偷潛入後方，看一眼主祭壇建築內部。無論如何，盡量避開預言者!', '銀白看臺的妖術師烏邦茍要你去調查司瑟拉圖斯祭壇的主祭壇建築。', '已調查斯瑞塔斯祭壇的主要建築', '去找祖爾德拉克的妖術師烏邦茍。', '', '', '', '', 0);
