INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12509,'zhTW','食人妖巡邏:勇氣','終於，巡邏抵達了!$B$B這就是目前的狀況，$r。我們在這場戰役中失去了許多精良的士兵，所以必須召集我們的新兵來填捕空缺。$B$B我們剛經歷了一場慘烈的戰役，許多新兵根本沒準備好要面對這次的敵人。往後還會有更多的戰鬥，我需要他們將身心準備好遵從命令。$B$B要是有什麼是我無法忍受的，那就是懦弱了。或許你可能幫助他們找回勇氣，好讓他們繼續迎戰。','德拉克索璀的魯伯特上尉要你去替畏縮的十字軍新兵回復勇氣。','','去祖爾德拉克找達克索塔的魯伯特上尉。','回復新兵的勇氣','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12510 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12510, 'zhTW', '珍貴的元素液體', '<妖術師檢驗了魔精瓶。>我有個對付司瑟拉圖斯預言者的點子。不過首先，我們會需要準備一些東西。德拉克索璀原野就在正南方。因為天譴軍團橫行的壓力和諸神殞落的影響，世界之間的壁壘變的脆弱，而元素不斷湧入。我們需要從元素領主身上取得珍貴的元素液體。如果你把三個那裡的元素拴繩結合在一起，就可以召喚一位元素的領主。', '銀白看臺的妖術師烏邦茍要你取得3個珍貴的元素液體。', '', '去找祖爾德拉克的妖術師烏邦茍。', '', '', '', '', 0);
