INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12516, 'zhTW', '樂極生悲', '瞧。我對魔精進行了調整。現在，當預言者喝掉它，他不只會失去部份的力量，連同他的心智都會被真菌的效果給混亂。至少理論上是這樣沒錯。至於要如何讓他喝掉魔精呢，我建議你不如直接把魔精丟給他如何?以他在祭壇表現的那種傲慢，他肯定會撿起來並直接喝掉。除非你能殺掉他，$c，否則你的銀白十字軍大概就完了吧。', '殺掉混亂的司瑟拉圖斯預言者，然後回到銀白看臺回報妖術師烏邦茍。', '', '去找祖爾德拉克的妖術師烏邦茍。', '', '', '', '', 0);
