INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12538, 'zhTW', '[The Mist Isn\'t Listening]', '[Gorillas and wasps are boring! Big-tongues the only thing fun to hunt.$B$BWhile we mess up rain shrine, we kill lots of mist big-tongues. That sure to make them not want to come back to village thing.$B$B<Zepik nods to himself confidently.>]', '[Zepik wants you to kill 12 Mistwhisper Gorlocs.$B$BIf you lose Zepik\'s Hunting Horn, speak to Elder Harkek in Frenzyheart Hill.]', '', '', '迷霧低語魚人', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12539 AND `locale` = 'zhTW';
