DELETE FROM `quest_template_locale` WHERE `ID` = 12540 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12540, 'zhTW', '[Just Following Orders]', '[Okay $g夥計：女士;, Rakjak have very important job. You go capture injured big-tongue that tracker spotted at river to north.$B$BNot bring hunter this time because they maybe want to just kill it. I want to hide it so that I can poke it and make it tell me things.$B$BGo you and bring me big-tongue prize thing.]', '[Locate an Injured Rainspeaker Oracle for High-Shaman Rakjak at Frenzyheart Hill.$B$B]', '', '', '找出受傷的雨語預言者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12541 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12541,'zhTW','食人妖巡邏:鍊金師的學徒','喔，你一定是那個他們承諾的巡邏兵。你來得正好。我們迫切地需要額外的人手。$B$B有個德拉克瑞囚犯被送來審問。在訊問開始之前，我需要有人幫忙我製作一份自白劑。$B$B製造自白劑是一項困難的工作，需要敏銳的直覺，完美的計時，每一步都需要臨機應變。$B$B當你準備好了就跟我講一聲，$r。記住，一切都是靠計時啊!','希伯伐洛克的鍊金師芬克斯坦要你協助他製作自白劑。$B$B你準備好要開始的時候就和他交談，然後遵循他的指示。','','去祖爾德拉克找赫布瓦羅的鍊金師菲肯斯坦。','完成自白劑','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12542 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12542, 'zhTW', '', '', '[Report to Crusader Valus at Light\'s Trust in Dragonblight. ]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12543 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12543, 'zhTW', '[An Offering for Soo-rahm]', '[We not know you, stranger, but we know you want something.$B$BWe will talk to Bones of Nozronn for you, but you must bring us offerings. We need powerful emperor cobra fangs to complete our oracle\'s necklace.$B$BGo to the Wildgrowth Mangal, northeast of our hut, find cobras and bring back best fangs. Then we make bones speak to you.]', '[Bring 5 Intact Cobra Fangs to Oracle Soo-rahm, near the Bones of Nozronn.]', '', '去找索拉查盆地的神諭者蘇-臘姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12544 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12544, 'zhTW', '[The Bones of Nozronn]', '[Bones of Nozronn, Oracle Soo-rahm sends $N to you!$B$BWe have prepared incense for you. Light it and place it near Nozronn\'s head and you will hear his voice.$B$B<Confused, you tell Soo-rahm that you haven\'t even told him your question.>$B$BTrue, we not know, but mighty Nozronn does. Do not doubt. Nozronn will answer your heart\'s question.$B$BGo. Nozronn not wait long.]', '[Use Soo-rahm\'s Incense near the Bones of Nozronn, then return to Hemet Nesingwary at Nesingwary\'s Base Camp with the information you learned.]', '', '去找索拉查盆地的赫米特·奈辛瓦里。', '法倫的位置已揭露', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12545 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12545, 'zhTW', '[The Cleansing Of Jintha\'kalar]', '[We wrested this ancient Drakkari temple from a swarm of invading Scourge. Not more than one-hundred paces from where we stand is the ruined city of Jintha\'kalar. Scourge necromancers run amok, turning the living Drakkari trolls that remain into servants of the Lich King.$B$BAll are now lost to the Light. All must be purged.$B$B<Valus looks upon you sternly.>$B$BAll.]', '[Crusader Valus at Light\'s Trust in Dragonblight has asked you to slay 15 Jintha\'kalar Scourge.]', '', '去找龍骨荒野的十字軍瓦魯思。', '金塔卡拉的天災已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12546 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12546, 'zhTW', '[Reclamation]', '[It is time, $N.  The Etymidian is one of the most destructive forces ever created by the titans and I am loathe to unleash him in my lands.$B$BThere is little choice, however.  Our enemies have forced my hand and the fury of the titans will cleanse all.]', '[Go to the Avalanche in Sholazar Basin and use the Omega Rune to deploy Etymidian.  Use him to slay 200 Scourge Minions, Bythius the Flesh-Shaper, Urgreth of the Thousand Tombs and Hailscorn.$B$BSpeak to the Avatar of Freya in Sholazar Basin when you\'ve completed this task.]', '', '去找索拉查盆地的芙蕾雅的化身。', '天災爪牙已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12547 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12547, 'zhTW', '[The Activation Rune]', '[This colossal being appears to be inactive.  You notice an empty rune-shaped slot on its chest.$B$BPerhaps you might be able to find the missing rune inside the nearby overlook.]', '[Obtain the Omega Rune inside the Shaper\'s Terrace and bring it to The Etymidian.]', '', '去找安戈洛環形山的伊提米迪安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12548 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12548, 'zhTW', '', '', '[Go through the Waygate in the southern end of Sholazar Basin and look for the weapon known as the Etymidian on the other side.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12549 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12549, 'zhTW', '[Dreadsaber Mastery: Becoming a Predator]', '[If you\'ve hunted with Hemet before, you know that he\'s tested his skill against many large cats, but the dreadsabers here in Sholazar are different. They\'re able to bring down larger game than I\'ve ever seen a cat hunt. To overcome and kill such a predator is the mark of a true hunter.$B$BIf you seek to prove you\'re up to the challenge, test yourself against the dreadsabers. They live in the wilderness surrounding the camp and south of the river.]', '[Kill 15 Dreadsabers and return to Buck Cantwell at the Nesingwary Base Camp.]', '', '去找索拉查盆地的巴克‧坎特威爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12550 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12550, 'zhTW', '[Dreadsaber Mastery: Stalking the Prey]', '[I have heard that the natives tell stories of a large dreadsaber they call Shango. I haven\'t seen any evidence of this Shango\'s existence, but my injuries have kept me from venturing outside the camp.$B$BIf you fancy yourself something of a tracker, you might be able to find out the truth about Shango. Debaar said she saw some large tracks on her last outing. Go north from the camp toward Bittertide Lake, and search its southern shore for the prints.]', '[Buck Cantwell at the Nesingwary Base Camp wants you to identify 3 Shango Tracks from the Dreadsaber Tracks near Bittertide Lake.]', '', '去找索拉查盆地的巴克‧坎特威爾。', '尚戈的蹤跡已辨識', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12551 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12551, 'zhTW', '[Crocolisk Mastery: The Trial]', '[I warn you, stranger -- do not make any comments about crashing the ship. I already get enough of it from the rest of the expedition.$B$BIf you\'re looking to try your hand at hunting, though, you should test your skills against the wily mangal crocolisks. They live all along the river to the south, and in the Wildgrowth Mangal to the east. Prove you can hold your own against them and we\'ll talk again, hunter.]', '[Kill 15 Mangal Crocolisks and return to Debaar at the Nesingwary Encampment.]', '', '去找索拉查盆地的戴巴爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12552 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12552, 'zhTW', '[Death to the Necromagi]', '[When the trolls brought down Kolramas, it crashed next to us to the southeast. Unfortunately the crash did not destroy all of the Scourge within.$B$BNow they\'re raising our men from the dead and using them against us!$B$BThis will not be allowed to continue. You will see to it that their necromagi are slaughtered! Do we understand each other?]', '[Sergeant Moonshard at Drak\'Sotra has asked you to destroy 8 Hath\'ar Necromagi.]', '', '去祖爾德拉克找達克索塔的月裂中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12553 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12553, 'zhTW', '[Skimmer Spinnerets]', '[Why do I always get the tough tasks to tackle?$B$BThe Scourge at Kolramas have plague sprayers that are getting dangerously close. You don\'t want to know what\'s going to happen if they start heading this way!$B$BI\'ve got an idea for how we might bring them down, but first we\'re going to need something... something from their own creatures.$B$BThe Hath\'ar skimmers can spin a very strong web that we can put to good use. Bring back some of their spinnerets.]', '[Specialist Cogwheel at Drak\'Sotra has asked you to collect 5 Intact Skimmer Spinnerets.]', '', '去祖爾德拉克找達克索塔的專家榫輪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12554 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12554, 'zhTW', '『墮落者』瑪拉斯', '$N，至少再找一個人，然後回去那裡!$B$B你會找到科爾拉瑪斯的領導者，『墮落者』瑪拉斯，得意洋洋的站在墜毀的亡域頂端。$B$B殺了他，提他的腦袋來見我!', '德拉克索璀的月裂中士強烈要求你帶著墮落者的頭顱回去找他。', '', '去祖爾德拉克找達克索塔的月裂中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12555 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12555, 'zhTW', '[A Tangled Skein]', '[There! One tangled skein thrower ready and waiting for you to take those plague sprayers down.$B$BYou just aim and let loose. The webbing should foul up their hover spells long enough to cause them to crash to the ground just like Kolramas.$B$BKind of poetic. I like that!]', '[Specialist Cogwheel at Drak\'Sotra has asked you to use the Tangled Skein Thrower in order to cause the destruction of 5 Plague Sprayers.]', '', '去祖爾德拉克找達克索塔的專家榫輪。', '瘟疫噴灑者已被蛛網纏繞並摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12556 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12556, 'zhTW', '[Rhino Mastery: The Kill]', '[Now that we know where to find Farunn, all that remains is the battle against the great beast. Are you ready to take on this rhino, $N? For all the spirit\'s blustering, I\'m certain it was telling the truth about the beast\'s strength.$B$BWhen you\'re ready to face him, head north past the Suntouched Pillar and look for Farunn on the northeast shore of the Bittertide Lake. It may even venture near the Glimmering Pillar. Bring back its horn to commemorate your kill.]', '[Bring Farunn\'s Horn to Hemet Nesingwary at the Nesingwary Base Camp.]', '', '去找索拉查盆地的赫米特·奈辛瓦里。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12557 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12557, 'zhTW', '[Lab Work]', '[I assume by your interruption that you wish to be numbered among those I am considering for apprenticeship.$B$BA worthy aspiration...$B$BShould I someday choose to accept your petition, I must be confident that you can find your way around my laboratory. I have many ingredients here; some plentiful, and others in short supply.$B$BTake your time, $c. Find a muddy mire maggot, a withered batwing, an amberseed, and some chilled serpent mucus.$B$BSucceed, and I\'ll know to take your request seriously.]', '[Alchemist Finklestein at Heb\'Valok wants you to find a Muddy Mire Maggot, a Withered Batwing, an Amberseed, and some Chilled Serpent Mucus from within his laboratory.]', '', '去找祖爾德拉克的鍊金師芬克斯坦。', '已找到泥沼蛆蟲', '已找到枯萎蝠翼', '已找到琥珀種子', '已找到寒冰巨蛇黏液', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12558 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12558, 'zhTW', '[Dreadsaber Mastery: Ready to Pounce]', '[Shango awaits, $N. If you have succeeded in your tracking, he will not know that you stalk him, and you will need the advantage.$B$BHe is supposed to be bigger, stronger, and more ferocious than the other dreadsabers of the basin. Travel north, to the western shore of Bittertide Lake and near the falls that feed it, do battle with Shango. If you succeed, return with his pelt.]', '[Bring Shango\'s Pelt to Buck Cantwell at the Nesingwary Base Camp.]', '', '去找索拉查盆地的巴克‧坎特威爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12559 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12559, 'zhTW', '[Powering the Waygate - The Maker\'s Perch]', '[It is time then.  Let us activate the waygate.$B$BYou will find the first switch inside the Maker\'s Perch in the western edge of the basin.$B$BBeware, $N.  The titans used the perch to watch over their creations.  Many of their stone servants still guard the place.]', '[The Avatar of Freya at the Rainspeaker Rapids wants you to go to the Maker\'s Perch and use the Activation Switch Gamma.]', '', '去找索拉查盆地的芙蕾雅的化身。', '伽瑪啟動開關', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12560 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12560, 'zhTW', '[Crocolisk Mastery: The Plan]', '[The mangal crocolisk is a master of the ambush, and I intend to beat the best at his game. To do that, we\'ll need to construct a convincing camouflage for you. We\'ll use plants that grow in the sandy soil of the riverbanks and lake beaches.$B$BThe sandfern is best for this purpose. It grows in the sandy areas near the shores of the Seabreach Flow, just to the south, Bittertide Lake and Bittertide Falls, to the north, and the edges of River\'s Heart, the large lake beyond the mangal to the east.]', '[Bring 5 Sandfern fronds to Debaar at the Nesingwary Base Camp.]', '', '去找索拉查盆地的戴巴爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12561 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12561, 'zhTW', '[An Issue of Trust]', '[This should never have happened.  The forces of undeath storm the very cradle of life!$B$BIf you\'re not here to destroy the minions of the Lich King, then leave at once.  Do not incur my wrath by distracting me from my duties.]', '[Obtain Freya\'s trust by destroying 6 Blighted Corpses and 10 Bonescythe Ravagers in the Lost Lands.]', '', '去找索拉查盆地的芙蕾雅的化身。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12562 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12562, 'zhTW', '[The Drakkari Do Not Need Water Elementals!]', '[Intelligence reports that ever since those water elementals appeared in the Drak\'Sotra Fields, a number of Drakkari shaman have come down from the upper tiers of Zul\'Drak to take control of them.$B$BI cannot stress enough, $g先生：女士;, how dangerous that could prove. We do not want them to have water elementals at their disposal.$B$BThe commander has ordered that these Drakkari water binders are to be put to the sword. Head south when you\'re ready.]', '[Sub-Lieutenant Jax at The Argent Stand has asked you to kill 10 Drakkari Water Binders.]', '', '去找祖爾德拉克的賈克斯中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12563 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12563, 'zhTW', '[Troll Patrol]', '[Unsheathe that weapon, $r. It\'s time to go on patrol!$B$BI\'ve got four posts under my command and it\'s crucial to our success that they remain in our control. I\'m ordering you to visit each of them and offer your assistance.$B$BYou can begin with Captain Brandon southeast of here. He\'ll direct you to the next post when he\'s finished with you.$B$BReport back to me once you\'ve assisted each of my men. And remember, you\'ll be more richly rewarded for returning to me quickly - so double-time it!$B$BDismissed!]', '[Commander Kunz at the Argent Stand wants you to visit the four Argent Crusade posts, follow their captain\'s orders, and then return and report to him.$B$BCaptain Brandon and Captain Rupert are posted at Drak\'Sotra, Captain Grondel is posted in Drak\'Agal, and Alchemist Finklestein is posted in Heb\'Valok.]', '', '去找祖爾德拉克的指揮官康茲。', '布蘭登隊長的任務', '魯伯特隊長的任務', '格龍德爾隊長的任務', '煉金術士芬克斯坦的任務', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12564 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12564, 'zhTW', '[Troll Patrol: Something for the Pain]', '[Gritty as my men are, they\'re still mortal.$B$BWounds and pain diminish their ability to perform their missions. No amount of training changes that simple fact of life.$B$BThankfully, one of our alchemists has developed a recipe for a salve that binds to our bandages and greatly reduces the pain our soldiers experience.$B$BThe salve requires a special poppy these trolls cultivate just west of here. Go to Drak\'Sotra Fields and harvest some of them to keep our stockpiles from running out.]', '[Captain Brandon at Drak\'Sotra wants you to collect 5 Mature Water-Poppies from Drak\'Sotra Fields.]', '', '去祖爾德拉克找達克索塔的布蘭登上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12565 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12565, 'zhTW', '[The Blessing of Zim\'Abwa]', '[I am heartened to see the zeal with which your Argent Crusade is dealing with the Scourge, $r. I would like to help with your efforts.$B$BThe Drakkari trolls of this once-great city used to make regular offerings to their gods, but now neglect them, or worse.$B$BIf you were to make offerings to the gods, they would show their appreciation in return.$B$BZim\'Abwa\'s statue is just to the southwest. Zim\'Abwa would gladly accept your offerings of Drakkari artifacts as a sign that you are protecting Zul\'Drak.]', '[Hexxer Ubungo at The Argent Stand wants you to present 10 Drakkari Offerings to the statue of Zim\'Abwa.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12566 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12566, 'zhTW', '', '', '[Speak with Chieftain Ashtotem at Camp Winterhoof.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12567 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12567, 'zhTW', '[Blessing of Zim\'Abwa]', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12568 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12568, 'zhTW', '[Troll Patrol: Done to Death]', '[Trust me, $r. I know....$B$BThe smell of burnt flesh has become sickening to even me, a Forsaken. Nevertheless, it is our solemn duty to ensure that our brethren never walk with the Scourge.$B$BPour this oil on the corpses of our fallen to ensure that we never face them on the battlefield as enemies.]', '[Captain Rupert wants you to use the Incinerating Oil on 5 Defeated Argent Footmen in Drak\'Sotra.]', '', '去祖爾德拉克找達克索塔的魯伯特上尉。', '已焚燒銀色步兵屍體', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12569 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12569, 'zhTW', '[Crocolisk Mastery: The Ambush]', '[The largest crocolisk in the basin, known around here as "Bushwhacker" for his ambush prowess, likes to sun himself in the shallow waters of River\'s Heart. It\'s the large lake at the basin\'s center, and is to the east of our camp.$B$BI want you to take the camouflage I\'ve prepared and hide on the western beach of River\'s Heart and ambush Bushwhacker when he shows himself. Bring back his mighty jaws if you are able to overcome him.]', '[Bring Bushwhacker\'s Jaw to Debaar at the Nesingwary Base Camp.]', '', '去找索拉查盆地的戴巴爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12570 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12570, 'zhTW', '[Fortunate Misunderstandings]', '[I sorry! I not mean to get you in trouble!$B$B<The injured oracle stares at you blankly for a long while.>$B$BYou save me! We thank you. We going to go back to village now. You come too... you can stay with us! Puppy-men kind of mean anyway.$B$BLet me know when you ready to go, okay?]', '[Escort the Injured Rainspeaker Oracle to Rainspaker Canopy and speak to High-Oracle Soo-say.]', '護送受傷的雨語預言者前往雨語樹冠', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12571 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12571, 'zhTW', '[Make the Bad Snake Go Away]', '[We were here long before the puppy-men came. This is very sacred place - we will not leave.$B$BYou seem like maybe you good, but we have Lafoo stay with you just in case. You understand we think.$B$BThere snakes thing that keeps trying to eat our hatchlings. Go with Lafoo and make them stop, okay? Especially big one near waterfall to northeast.]', '[High-Oracle Soo-say in Rainspeaker Canopy wants you to kill Venomtip and 10 Emperor Cobras.$B$BIf you lose Lafoo\'s Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy.]', '', '去找索拉查盆地的高階神諭者蘇-楔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12572 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12572, 'zhTW', '[Gods like Shiny Things]', '[Soo-say said we go with you. You be nice, okay?$B$BOoh, ooh! We know! We can make Soo-say happy if we bring back more offerings for shrine! We not need to go far, there\'s always stuffs to dig up around village... just look for sparkles in dirt!$B$BLet\'s go! Let\'s go! More offerings for shrine!]', '[Collect 6 of the treasures that Lafoo digs up and bring them to High-Oracle Soo-say in Rainspeaker Canopy.$B$BIf you lose Lafoo\'s Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy.]', '', '去找索拉查盆地的高階神諭者蘇-楔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12573 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12573, 'zhTW', '[Making Peace]', '[We have great idea. You were friends with puppy-men, they maybe listen to you.$B$BWe want you to go give offering to Shaman Vekjik. He southwest where river turns into waterfall.  Tell puppy-man we no want fight. Tell him we play nice.$B$BYou good $r. We trust you do this right.]', '[High-Oracle Soo-say at Rainspeaker Canopy wants you to give a peace offering to Shaman Vekjik and then return with his response.$B$BIf you lose Lafoo\'s Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy.]', '向薩滿維克吉克提出和平提議', '去找索拉查盆地的高階神諭者蘇-楔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12574 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12574, 'zhTW', '', '', '[Travel to Mistwhisper Refuge and speak to Mistcaller Soo-gan.If you lose Jaloot\'s Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12575 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12575, 'zhTW', '[The Lost Mistwhisper Treasure]', '[So some puppy-men come and smash blue crystals at Great Mist Stone! Lots of rain and lightning and badness... blue is wrong crystal for Great Mist Stone! Dumb puppy-men.$B$BAfter lightning, puppy-men stole big treasure we found in the sea-lake. We need treasure back to give to Great Mist Stone! Mist Stone is angry after what the puppy-men did!$B$BOne who took it named Tarter... no, Tiktak... no, no... Tartek. That it, Tartek! He went to the camp thing to north. Go get treasure back!]', '[Kill Warlord Tartek and retrieve the Mistwhisper Treasure for Mistcaller Soo-gan at Mistwhisper Refuge.$B$BIf you lose Jaloot\'s Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy.]', '', '去找索拉查盆地的喚霧者蘇-綱。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12576 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12576, 'zhTW', '[Forced Hand]', '[We try to be nice to puppy-men ever since they came, but they nothing but mean.$B$BWe okay with them being dumb - they not do much harm. Now they mess with sacred shrines though. Sacred shrines not for messing with. The Great Stones are here from all the way back when the Great Ones made us.$B$BWe wouldn\'t know what to do if the Great Mist Stone were hurt. Go to their camp to north... make puppy-men stop and not come back!]', '[Kill 8 Frenzyheart Spearbearers and 6 Frenzyheart Scavengers for Mistcaller Soo-gan at Mistwhisper Refuge.$B$BIf you lose Jaloot\'s Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy.]', '', '去找索拉查盆地的喚霧者蘇-綱。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12577 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12577, 'zhTW', '', '', '[Return to Rainspeaker Canopy.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12578 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12578, 'zhTW', '[The Angry Gorloc]', '[I not think you be back in time to go out again, but I wrong. I sending Moodle to nearby Mosswalker friends to bop silly Mosswalkers for not coming see shrine. Their village is east, up ridge, northeast of broken pillar.$B$BYou go with Moodle! He extra smart Rainspeaker... you listen to him good-like.]', '[Travel to Mosswalker Village and speak to Moodle once you\'ve arrived.$B$BIf you lose Moodle\'s Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy.]', '前往苔行者村', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12579 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12579, 'zhTW', '[Lifeblood of the Mosswalker Shrine]', '[I\'ve always suspected that the pillars have been the main reason for our weather and seclusion from the undead... this confirms it a bit.$B$BNot terribly long ago, there was a sound of a great explosion when the Lifeblood Pillar fell. The weather changed for the mosswalkers almost immediately... it began to snow, something we never see.$B$BThey were able to stop the snow by bringing more lifeblood crystals to the Great Moss Stone. Perhaps if we can do the same, it will help ward off the undead as well.]', '[Moodle wants you to collect 10 Lifeblood Shards, but stay away from the cave inside of the pillar itself.$B$BIf you lose Moodle\'s Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12580 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12580, 'zhTW', '[The Mosswalker Savior]', '[There\'s some small chance that the Mosswalkers are not all dead yet... and at the very least, they deserve to not be butchered like this.$B$BLet\'s find some revenge for this slaughter and see if there are any to be saved in the process.]', '[Moodle wants you to rescue 6 of the Mosswalker Victims in Mosswalker Village, though some of them may no longer be alive to save.$B$BIf you lose Moodle\'s Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy.]', '', '', '已救出苔行者受害者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12581 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12581, 'zhTW', '英雄的負擔', '也許那些水晶終將會把不死生物驅離，但是還有一件事情必須要做。$B$B我們得找到這些不死生物的領導者，把它殺掉，確保那些卑鄙的傢伙不會再度進犯。如果我的懷疑是對的，他應該就在倒下的柱子中的某處…就在破碎裂片中。$B$B一路被拖到那裡去的屍體也暗示同一個地方。$B$B我會把裂片放上苔石，然後把消息傳給蘇-楔…在這期間你得去尋求其他的幫助。', '殺死『無心者』阿楚依思。$B$B進行援救的過程中，強烈建議需要朋友的協助，穆斗沒有辦法陪你進行這項任務。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12582 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12582, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12583 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12583, 'zhTW', '墜毀的噴灑器', '我知道其中一台瘟疫噴灑器墜毀在西邊的德拉克索璀。$B$B你何不去試看看你能不能找到它呢?我可以使用噴灑器的零件來製作一台可以把那些東西打下來的機械!', '德拉克索璀的專家榫輪要你去收集瘟疫噴灑器零件。', '', '去祖爾德拉克找達克索塔的專家榫輪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12584 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12584, 'zhTW', '[Pure Evil]', '[We know that Kolramas, the crashed necropolis to the southeast, was carrying a large amount of an ore known as saronite when the trolls shot it down.$B$BMy scouts tell me that much of the saronite is strewn about within the innards of that thing.$B$BEitrigg and his friends back at The Argent Stand want a bunch of the stuff so that they can study it.$B$BI want you to head in there and see if you can collect enough for them.]', '[Captain Rupert has asked you to collect 10 Chunks of Saronite and deliver them to Eitrigg at The Argent Stand.]', '', '去找祖爾德拉克的伊崔格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12585 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12585, 'zhTW', '[Troll Patrol: Creature Comforts]', '[Well, it ain\'t glamorous, but it needs doin\'.$B$BMy troops have been fightin\' their hearts out while knee-deep in stagnant water for days on end. That just can\'t be good fer ya.$B$BWhat they need is a nice fire to dry \'em out and lighten their spirits.$B$BThis part of the city\'s soaked, but the dead roots of these thornwood trees have a way of resistin\' the moisture.$B$BRound us up some fuel for burnin\' and we\'ll be mighty grateful.]', '[Captain Grondel at Drak\'Agal wants you to bring him 20 pieces of Dead Thornwood.]', '', '去找祖爾德拉克的格隆戴爾上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12586 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12586,'zhTW','搜尋更大的獵物','好吧，$N，看來你已經成為探險隊裡的骨幹。要是沒有你，Debaar，buck和我不可能弄到這麼多引入注目的戰利品收集。$B$B不過，我聽說在盆地的另一塊本地有著更兇猛的怪物。我已經派遣了一隻探索隊轉至南面去看看有什麼野獸正等著我們。$B$B我希望你去與他們會合，看看他們發現了些什麼。往南走，越過Bittertide Lake，尋找他們的露營地。','與<x>的<x>交談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12587 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12587, 'zhTW', '[Troll Patrol]', '[Unsheathe that weapon, $r. It\'s time to go on patrol!$B$BI\'ve got four posts under my command and it\'s crucial to our success that they remain in our control. I\'m ordering you to visit each of them and offer your assistance.$B$BYou can begin with Captain Brandon southeast of here. He\'ll direct you to the next post when he\'s finished with you.$B$BReport back to me once you\'ve assisted each of my men. And remember, you\'ll be more richly rewarded for returning to me quickly - so double-time it!$B$BDismissed!]', '[Commander Kunz at the Argent Stand wants you to visit the four Argent Crusade posts, follow their captain\'s orders, and then return and report to him.$B$BCaptain Brandon and Captain Rupert are posted at Drak\'Sotra, Captain Grondel is posted in Drak\'Agal, and Alchemist Finklestein is posted in Heb\'valok.]', '', '去找祖爾德拉克的指揮官康茲。', '布蘭登隊長的任務', '魯伯特隊長的任務', '格龍德爾隊長的任務', '煉金術士芬克斯坦的任務', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12588 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12588, 'zhTW', '[Troll Patrol: Can You Dig It?]', '[One of our troops came across an old treasure map during our last offensive. If what it shows is true, then there are priceless troll artifacts nearby.$B$BMy soldiers have their hands full, pressed between the Drakkari and the Scourge. I need you to follow up on this intelligence.$B$BTake this shovel and use it at the loose dirt mounds to the southwest. Return to me after a diligent search has been conducted.]', '[Captain Brandon in Drak\'Sotra wants you to use the Steel Spade on the nearby Ancient Dirt Mounds to recover the Ancient Drakkari Relic.]', '', '去祖爾德拉克找達克索塔的布蘭登上尉。', '已調查遠古土堆', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12589 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12589, 'zhTW', '後座力?什麼後座力?', '你覺得你會射擊?$B$B好吧，咱們來試試看。來，我們先從好脾氣的目標開始。別擔心，這完全沒有後座力。記得不要把槍指向你沒有要射擊的目標。$B$B現在，你準備好了就瞄準老維爾海姆頭上的蘋果，然後開火吧!', '使用RJR步槍，射擊幸運的維爾海姆頭上的蘋果，然後和德羅斯坦交談。', '', '去找索拉查盆地的德羅斯坦。', '射中幸運的維爾海姆頭上的蘋果', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12590 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12590, 'zhTW', 'Blahblah[PH]', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12591 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12591, 'zhTW', '[Troll Patrol: Throwing Down]', '[Clever...$B$BJust when it seemed we were getting things under control, they tunneled right underneath us and secured the shrine!$B$BNow we\'re caught between two nethurbian armies and our predicament is worsening by the minute.$B$BAs our first course of action, we must stop them from reinforcing. Their tunnels must be sealed.$B$BTake these grenades and throw them down their craters to the northwest.]', '[Captain Rupert at Drak\'Sotra wants you to use High Impact Grenades near 5 Nethurbian Craters.]', '', '去祖爾德拉克找達克索塔的魯伯特上尉。', '納魯比坑道已崩塌', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12592 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12592, 'zhTW', '[The Great Hunter\'s Challenge]', '[So y\'have something of a hunter\'s instinct. You\'re not a bad shot, and Hemet hasn\'t driven you out, so he must be planning on including you in the hunt.$B$BHow\'d you like to have a bit of a competition, just me and you?$B$BHemet and the others will ask you to help in their hunting. Along the way, you and I will count up the kills we contribute to their goals. Now, this isn\'t something you can win in the blink of an eye, and you\'ll find yourself killing many different kinds of creatures. Good luck!]', '[Kill 60 Game Animals while you aid Hemet and his companions in their hunting. When you\'ve killed your 60, return to Drostan at the Nesingwary Base Camp to compare numbers.]', '', '去找索拉查盆地的德羅斯坦。', '獵物已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12593 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12593, 'zhTW', '', '', '[Report to Instructor Razuvious in the Heart of Acherus. ]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12594 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12594, 'zhTW', '[Troll Patrol: Couldn\'t Care Less]', '[Of all the posts, they throw me in this one.$B$BThe place is flooded with putrid, stagnant water and now it\'s host to sewage elementals!$B$BI don\'t really know what they are or why they\'re here, and frankly I couldn\'t care less. What I do know is they\'re making a mess of my sector! How am I supposed to conduct any dignified military operations with those foul things roaming around?$B$BGet out there, $c, and don\'t come back \'til you\'ve cleared your share of \'em off of my battlefield!]', '[Captain Grondel wants you to kill 7 Mossy Rampagers in Drak\'Agal.]', '', '去找祖爾德拉克的格隆戴爾上尉。', '苔蘚狂暴者已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12595 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12595, 'zhTW', '', '', '[Speak with Dorian Drakestalker at Dorian\'s Outpost in Sholazar Basin.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12596 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12596, 'zhTW', '[Pa\'Troll]', '[Welcome to The Argent Stand, scrub. I am Commander Kunz, but you - you can call me... Commander.$B$BDon\'t think you\'re going to just cruise through my region, picking which missions you\'re going to participate in, answering to no one.$B$BHere, you report to me and you follow my orders to the letter. Understood?!$B$BFirst, you\'re going to get familiar with my men and the region we\'re charged with clearing.$B$BReport to each of them and do as they ask. Return to me when your patrol is done.]', '[Commander Kunz at The Argent Stand wants you to visit the four Argent Crusade posts, follow their leaders\' orders, and then return and report to him.$B$BCaptain Brandon and Captain Rupert are posted at Drak\'Sotra, Southeast of here.$B$BCaptain Grondel is posted in Drak\'Agal, due east.$B$BAlchemist Finklestein is posted in Heb\'Valok, to the north.]', '', '去找祖爾德拉克的指揮官康茲。', '布蘭登隊長的任務', '魯伯特隊長的任務', '格龍德爾隊長的任務', '煉金術士芬克斯坦的任務', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12597 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12597, 'zhTW', '[Something for the Pain]', '[Gritty as my men are, they\'re still mortal.$B$BWounds and pain diminish their ability to perform their missions. No amount of training changes that simple fact of life.$B$BThankfully, one of our alchemists has developed a recipe for a salve that binds to our bandages and greatly reduces the pain our soldiers experience.$B$BThe salve requires a special poppy these trolls cultivate just west of here. Go to Drak\'Sotra Fields and harvest some of them to keep our stockpiles from running out.]', '[Captain Brandon at Drak\'Sotra wants you to collect 5 Mature Water-Poppies from Drak\'Sotra Fields.]', '', '去祖爾德拉克找達克索塔的布蘭登上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12598 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12598, 'zhTW', '[Throwing Down]', '[Clever...$B$BJust when it seemed we were getting things under control, they tunneled right underneath us and secured the shrine!$B$BNow we\'re caught between two Nerubian armies and our predicament is worsening by the minute.$B$BAs our first course of action, we must stop them from reinforcing. Their tunnels must be sealed.$B$BTake these grenades and throw them down their craters to the northwest.]', '[Captain Rupert at Drak\'Sotra wants you to use High Impact Grenades near 5 Nerubian Craters.]', '', '去祖爾德拉克找達克索塔的魯伯特上尉。', '納魯比坑道已封閉', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12599 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12599, 'zhTW', '[Creature Comforts]', '[Well, it ain\'t glamorous, but it needs doin\'.$B$BMy troops have been fightin\' their hearts out while knee-deep in stagnant water for days on end. That just can\'t be good fer ya.$B$BWhat they need is a nice fire to dry \'em out and lighten their spirits.$B$BThis part of the city\'s soaked, but the dead roots of these thornwood trees have a way of resistin\' the moisture.$B$BRound us up some fuel for burnin\' and we\'ll be mighty grateful.]', '[Captain Grondel at Drak\'Agal wants you to bring him 20 pieces of Dead Thornwood.]', '', '去找祖爾德拉克的格隆戴爾上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12600 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12600, 'zhTW', '巫妖王之怒 任務', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12601 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12601, 'zhTW', '[The Alchemist\'s Apprentice]', '[Ahh, you must be the promised patrol. Your timing couldn\'t be better. I have urgent need of an extra pair of hands.$B$BWe have a Drakkari prisoner who\'s been sent here to undergo questioning. Before the interrogation begins, I require assistance in the creation of a truth serum.$B$BCreating a truth serum is tricky business, demanding keen instincts, perfect timing, and improvisation at every step.$B$BLet me know when you\'re ready, $r. And remember, timing is everything!]', '[Alchemist Finklestein at Heb\'valok wants you to assist him in the creation of a truth serum.$B$BWhen you are ready to begin, you are to speak to him and follow his instructions.]', '', '去找祖爾德拉克的鍊金師芬克斯坦。', '真言血清已製造', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12602 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12602, 'zhTW', '[The Alchemist\'s Apprentice]', '[Ahh, you must be the promised patrol. Your timing couldn\'t be better. I have urgent need of an extra pair of hands.$B$BWe have a Drakkari prisoner who\'s been sent here to undergo questioning. Before the interrogation begins, I require assistance in the creation of a truth serum.$B$BCreating a truth serum is tricky business, demanding keen instincts, perfect timing, and improvisation at every step.$B$BLet me know when you\'re ready, $r. And remember, timing is everything!]', '[Alchemist Finklestein at Heb\'valok wants you to assist him in the creation of a truth serum.$B$BWhen you are ready to begin, you are to speak to him and follow his instructions.]', '', '去找祖爾德拉克的鍊金師芬克斯坦。', '真言血清已製造', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12603 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12603, 'zhTW', '[Sharpening Your Talons]', '[The primordial drakes occupy most of the area to the north and east, and I can feel the heat of their breath even at this distance. Before we can challenge the mightiest among the drakes, we must test our skills against the lesser creatures.$B$BStill, don\'t let your guard down; any one of these beasts can devour a man whole. Once you\'ve familiarized yourself with the combat tactics of these drakes, return and I will tell you our next step.]', '[Kill 6 Primordial Drakes and then speak with Dorian Drakestalker at Dorian\'s Outpost.]', '', '去找索拉查盆地的多里安‧龍巡者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12604 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12604, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12605 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12605, 'zhTW', '[Securing the Bait]', '[We\'re not likely to get Broodmother Slivina\'s attention waving our arms around like fools, but if we\'re smart, we can bait her into fighting us. We\'ll also secure more, uh, fodder for my little project.$B$B<Dorian glances over at Zootfizzle.>$B$BBut don\'t worry about that for now. Just look for the primordial drake eggs in the area east and northeast of the camp. Burst them open and scoop up the hatchlings that come out. When the broodmother realizes what we\'ve done, she\'ll have no choice but to face us.]', '[Bring 6 Primordial Hatchlings to Dorian Drakestalker at Dorian\'s Outpost.]', '', '去找索拉查盆地的多里安‧龍巡者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12606 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12606, 'zhTW', '[Cocooned!]', '[Now that the tunnels have been sealed, our next concern is recovering those who have fallen to the enemy.$B$BWith any luck, several of our soldiers are still alive and relatively well inside the nerubian cocoons.$B$BFree them, $c, while you still can!]', '[Captain Rupert wants you to open the Nerubian Cocoons in Drak\'Sotra and return to him once you have freed 3 Captive Footmen.]', '', '去祖爾德拉克找達克索塔的魯伯特上尉。', '已釋放被俘的步兵', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12607 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12607, 'zhTW', '[A Mammoth Undertaking]', '[Before you go off challenging Broodmother Slivina, Dorian thought it might be a good idea for you and Hemet to coordinate your efforts by riding into battle on the back of a mammoth.$B$BThe area around the camp is full of them. Just take this bridle and skip it over the head of a shattertusk mammoth. Be careful of the bulls, though. They won\'t tolerate the harness at all. Bring the mammoth back here when you\'ve found a suitable one.]', '[Bring a Shattertusk Mammoth to Zootfizzle at Dorian\'s Outpost.]', '', '去找索拉查盆地的狹嘶。', '碎牙長毛象已送達', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12608 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12608, 'zhTW', '', '', '[Speak to the Avatar of Freya at the Rainspeaker Rapids.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12609 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12609, 'zhTW', '[Stocking the Shelves]', '[Listen, $c. I realize that it\'s a lot to ask....$B$BFresh spider ichor is somewhat hard to come by, even in these heavily infested regions. But Finklestein said he\'d settle for no less than a vat of it, and that he needs it soon.$B$BI\'ll keep my men out in the field collecting reagents, but if the alchemist\'s order is going to be filled in time, they\'ll require some assistance.$B$BAs you roam the fields of Zul\'Drak, keep your eyes peeled for trapdoor crawlers and bring me all of the ichor you can find.]', '[Captain Arnath in Heb\'Valok asked you to collect 7 units of Fresh Spider Ichor from the Trapdoor Crawlers in Zul\'Drak.]', '', '去找祖爾德拉克的阿爾納斯上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12610 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12610, 'zhTW', '[Clipping Their Wings]', '[Ever since Finklestein\'s arrival, I\'ve been relegated to collecting various ingredients for his experiments and recipes.$B$BI\'ll follow my orders as I\'ve vowed to do, but I\'m a seasoned veteran. I\'ve taken part in dozens of conflicts. I\'d much rather be on the front lines, having a more direct impact on the Crusade\'s outcome here.$B$BHelp me, $r. Collect some bat wings for me so that I might get back to the real action sooner.]', '[Captain Arnath in Heb\'Valok has asked you to collect 7 Unblemished Bat Wings from Zul\'Drak Bats.]', '', '去找祖爾德拉克的阿爾納斯上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12611 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12611, 'zhTW', '[Returned Sevenfold]', '[The agents of the Lich King have foolishly trespassed upon these lands where the power of life rules supreme.  All harm they inflict will be returned to them sevenfold.$B$BThe monster directly responsible for corrupting the land is known as Thalgran Blightbringer; you will find him just to the north of here.  Take this ward and use it to reflect the power of death upon him.  Show the Scourge that the power of life prevails above all.]', '[The Avatar of Freya wants you defeat Thalgran Blightbringer by using Freya\'s Ward to reflect his Deathbolts back to him sevenfold.]', '', '去找索拉查盆地的芙蕾雅的化身。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12612 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12612, 'zhTW', '', '', '[Travel to the Lifeblood Pillar and look for clues to its destruction.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12613 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12613, 'zhTW', '[Powering the Waygate - The Maker\'s Overlook]', '[We cannot stop now, $r.  You\'ve triggered the first switch, but one remains.$B$BThe titans constructed a second vantage point where they oversaw their creations.  You\'ll find it to the east, high in the mountains.$B$BPull the activation switch theta inside the overlook and the waygate will open.]', '[The Avatar of Freya wants you to head to the Maker\'s Overlook in eastern Sholazar Basin and use the Activation Switch Theta.]', '', '去找索拉查盆地的芙蕾雅的化身。', '西塔啟動開關', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12614 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12614, 'zhTW', '[Post-partum Aggression]', '[Broodmother Slivina\'s likely to be a snarling ball of teeth, spikes, and talons. You\'ve gone and stolen her children away and no mother takes kindly to that.$B$B\'Tis true they hatched from eggs, but she loves the little beasts no less than your mother loves you.$B$BShe\'ll be desperate and fierce in equal measures, everything Hemet loves in a target. You and he, along with that mammoth, should be a match for her.$B$BShe\'s on her perch at the northern edge of the Savage Thicket and hungers for revenge.]', '[Kill Broodmother Slivina and return to Dorian Drakestalker at Dorian\'s Outpost.]', '', '去找索拉查盆地的多里安‧龍巡者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12615 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12615, 'zhTW', '[The Blessing of Zim\'Torga]', '[Hexxer Ubungo probably told you about making offerings to the gods of Zul\'Drak. Zim\'Abwa is not the only god that stands forgotten by the Drakkari.$B$BWe have taken refuge within the presence of Zim\'Torga, the Mother of Prosperity. As with Zim\'Abwa, if you were to give offerings of the Drakkari to her, she is sure to give you her blessing.]', '[Witch Doctor Khufu wants you to present 10 Drakkari Offerings to the statue of Zim\'Torga.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12616 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12616, 'zhTW', '', '', '[The Argent Dawn Emissary wants you to search the chamber of Tenris Mirkblood within the Servant\'s Quarters of Karazhan.]', '', '去找銀色特使。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12617 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12617, 'zhTW', '[Exterminate the Intruders]', '[I am an embodiment of but one aspect of Freya, daughter of the titans.  I am the Lifewarden -- I was left here to protect this land against the threat of the Scourge.$B$BI never anticipated the Lich King would send willing living servants to do his work.$B$BI could easily crush these cultists myself, but I am all that stands between the undead armies and the rest of the basin.  Go, $N.  Deliver my wrath to these insolent trespassers.]', '[The Avatar of Freya at the Rainspeaker Rapids wants you to go to the Death\'s Hand Encampment to the northwest and slay 8 Cultist Infiltrators.]', '', '去找索拉查盆地的芙蕾雅的化身。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12618 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12618, 'zhTW', '[Blessing of Zim\'Torga]', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12619 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12619, 'zhTW', '[The Emblazoned Runeblade]', '[The single most important piece of equipment to a death knight is the runeblade. It is through the runeblade that a death knight commands the powers of frost, blood and the unholy. The runeblade also acts as a vessel to store the death knight\'s runic power.$B$BThe time has come to create your first runeblade. Search the weapon racks on this floor and locate a battle-worn sword. Once found, take the sword to a nearby runeforge and use it to create a runeblade.]', '[Search the weapon racks in Ebon Hold for a Battle-worn Sword and then use it on a runeforge to craft a Runebladed Sword.$B$BReturn the Runebladed Sword to Instructor Razuvious in Ebon Hold.]', '', '去找黑鴉堡壘的講師拉祖維斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12620 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12620, 'zhTW', '[The Lifewarden\'s Wrath]', '[We were not quick enough, $N.  The cultist scum have arrived at the Glimmering Pillar and are making preparations to destroy it, I can sense them.$B$BWe don\'t have much time.  Blow upon this horn atop the Glimmering Pillar to channel my power through the crystal.$B$BWe shall show this scum to not trifle with the titans\' creations.]', '[The Avatar of Freya at the Rainspeaker Rapids wants you to use Freya\'s Horn atop of the Glimmering Pillar.]', '', '去找索拉查盆地的芙蕾雅的化身。', '生命守衛者之怒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12621 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12621, 'zhTW', '[Freya\'s Pact]', '[The cultists have been taken care of, but the Scourge\'s invasion has not slowed down.  The situation is becoming desperate, $N.$B$BThere exists a last resort.  Before I reveal any more, however, I must be sure I have your absolute trust.]', '[Listen to what the Avatar of Freya has to say.]', '', '去找索拉查盆地的芙蕾雅的化身。', '菲雅的契約', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12622 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12622, 'zhTW', '[The Leaders at Jin\'Alai]', '[You thinkin\' what Ahunae thinkin\', mon?$B$BSome of the Drakkari trolls have gathered at the Pools of Jin\'Alai to the southwest. We be needin\' to draw out their leaders, and Ahunae knows just how you be doin\' it, too!$B$BGo in there and kill those trolls. When you kill enough, their leaders show up.$B$BWhen they show up next to their totems, you make sure to be gettin\' the treasure of Kutube\'sa, Gawanil, and Chulo the Mad, mon.]', '[Scalper Ahunae at Zim\'Torga has asked you to retrieve the Treasure of Kutube\'sa, the Treasure of Gawanil, and the Treasure of Chulo the Mad.]', '', '去找祖爾德拉克的割顱者艾胡奈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12623 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12623, 'zhTW', '', '', '[Speak with Witch Doctor Khufu at Zim\'Torga.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12624 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12624, 'zhTW', '[It Could Be Anywhere!]', '[When I found out that Miss Boulian was helping Nesingwary with his expedition, I signed up as a deckhand immediately.  You see, I\'d been meaning to marry her for months!$B$BI had it all planned out.  I was going to propose the very night of the shipwreck... but now the ring is gone.  I\'ve searched everywhere!$B$BI know it might sound crazy, but I know the engagement ring is in the Basin.  If some Venture Company didn\'t steal it, maybe a wild creature ate it.  But it\'s here somewhere... I just know it!]', '[Look for a Golden Engagement Ring on the various creatures in Sholazar Basin.]', '', '去找索拉查盆地的查德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12625 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12625,'zhTW','支配阿徹魯斯','向偉大的死亡之城阿徹魯斯行注目禮吧！它是舉世無雙的超級堡壘！即使是納克薩瑪斯，也不能承受一次來自黑鋒要塞的突然襲擊！$B$B或許你的意識仍然有些模糊，但事實是，我們的時間確實不多了。你必須在短時間內充分了解阿徹魯斯，把這裡所有的細節都記在腦子裡。戰爭的號角已經吹響了！$B$B立刻到本層的樓梯間去，東北，西邊，南邊，北邊，四個邊樓梯間隨便你選。從樓梯走到上面一層的守備層，在那裡找到攻城鍛造大師科弗斯，向他索要報告書。報告書是要送給薩拉諾爾的。','向黑鋒要塞守備層的攻城鍛造大師科弗斯報到。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12626 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12626, 'zhTW', '[Company of the Damned]', '[<Corvus salutes.>$B$BOur stockpiles of weapons, armor and munitions are nearly at maximum capacity. We are ready for war!$B$B<Corvus rolls up a fleshy piece of vellum.>$B$BOn the other side of this garrison floor, southwest of here, you will find the officers\' quarters. Take this status report there and deliver it to Scourge Commander Thalanor, battalion commander of the Company of the Damned.]', '[Deliver Corvus\' Report to Scourge Commander Thalanor at the garrison floor of Ebon Hold.]', '', '去找瘟疫之地：血色禁地的天譴指揮官薩拉諾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12627 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12627, 'zhTW', '[Breaking Through Jin\'Alai]', '[I have been trying to commune with the gods. However, the medicine men at the Pools of Jin\'Alai are performing rituals that are interfering with my attempts.$B$BIt is imperative that we break through their obtrusion. If you were to head southwest into the pools area, I am certain that you would come across the cauldrons they are using for their magic.$B$BDisturb each of the cauldrons to bring down their ritual that is blocking me.]', '[Witch Doctor Khufu at Zim\'Torga has asked you to disturb the Blue Cauldron, Green Cauldron, Purple Cauldron, and Red Cauldron.]', '', '去找祖爾德拉克的巫醫庫弗。', '已擾動藍色坩堝', '已擾動綠色坩堝', '已擾動紫色坩堝', '已擾動紅色坩堝', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12628 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12628, 'zhTW', '', '', '[Speak with Har\'koa at the Altar of Har\'koa.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12629 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12629, 'zhTW', '[You Can Run, But You Can\'t Hide]', '[Once the Scourge have a target in their sights, they\'ll stop at nothing to acquire it.$B$BYou\'re doomed to a mindless existence as a walking corpse....$B$B<Stefan\'s face twists into a cruel grin.>$B$B... unless we can use their desires against them.$B$BI\'ll explain later. I have complex magic to prepare which requires certain material components.$B$BTravel due east of here to the Reliquary of Agony. Slay abominations and gather the ghoul drool you\'ll find there then return to me with their remnants.]', '[Stefan in Ebon Watch asked you to go to the Reliquary of Agony to collect 5 Putrid Abomination Guts from the Putrid Abominations and 5 Gooey Ghoul Drools.]', '', '去找祖爾德拉克的史戴芬·瓦度。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12630 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12630, 'zhTW', '[Kickin\' Nass and Takin\' Manes]', '[Before you meet Nass, there\'s something you should know.$B$BHe got a toxic dose of blight back in the day, and now he\'s deaf, blind, and mostly numb.$B$BIt\'s not all bad, though. He\'s virtually immune to the stuff now, which makes him perfect for certain tasks - like the one I\'m about to give you.$B$BThere are many freshly scourged trolls nearby and we need to study the blight\'s effect on them. Take Nass, and this boot. When you\'ve slain a troll, give him a good kick and he\'ll know to take a hair sample.]', '[Stefan in Ebon Watch wants you to use Nass to collect 10 hair samples from Withered Trolls.$B$BIf you lose Nass, return to Stefan to recover him.]', '', '去找祖爾德拉克的史戴芬·瓦度。', '已收集毛髮樣本', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12631 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12631, 'zhTW', '[An Invitation, of Sorts...]', '[Crafted of bone and dripping with blood, this choker is of intricate and deliberate design.$B$BGazing upon it overwhelms you with an ominous presence - one that compels you to wear it. You fight the urge, and resolve to bring it back to Ebon Watch.$B$BIf anyone can explain this, a death knight can....]', '[Take the Unliving Choker to Stefan at Ebon Watch.]$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12632 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12632, 'zhTW', '[But First My Offspring]', '[I am the last of the gods to be subdued, so we must first attempt to free the others. Bound by the magics of my subduers, I am unable to discern their fates.$B$BBut first, I would ask that you do me a kindness. Already the Drakkari turn my magic against me. They have transformed my offspring into monstrosities.$B$BTake one of my whiskers. Slay my tortured children and use the magic of it to release them from their nightmare, and bring them back to life.]', '[Har\'koa has asked you to use her whisker on the corpses of her children to free and resurrect them. Return to her at the Altar of Har\'koa when you are done.]', '', '去找祖爾德拉克的哈寇亞。', '哈爾科亞的被詛咒後裔已復活', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12633 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12633, 'zhTW', '[Darkness Calling]', '[Crafted of bone and dripping with blood, this choker is of intricate and deliberate design.$B$BGazing upon it overwhelms you with an ominous presence - one that compels you to wear it. You fight the urge, and resolve to bring it back to Ebon Watch.$B$BIf anyone can explain this, a death knight can....]', '[Take the Writhing Choker to Stefan in Ebon Watch.]$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12634 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12634, 'zhTW', '[Some Make Lemonade, Some Make Liquor]', '[Life\'s tossed me a cartload of lemons this time! When the ship ran aground, the kegs carrying my best brew burst! All we have now are a few bottles of rum, and it won\'t sustain a thirsty expedition!$B$BWe need to get some booze cooking, and fast!!$B$BThe trees in the Wildgrowth Mangal, to the east, seem laden with fruit, but it\'s too high for me to reach. Look for good, strong vines, see if you can use it to shake some of that fruit out of the trees. Bring me whatever you can find.]', '[Bring 1 Orange, 2 Banana Bunches, and 1 Papaya to Grimbooze Thunderbrew at the Nesingwary Base Camp.]', '', '去找索拉查盆地的葛林布茲·雷酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12635 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12635, 'zhTW', '[Relics of the Snow Leopard Goddess]', '[I overheard that you are going to see to the well-being of Har\'koa. Good luck to you.$B$BI am wondering if while you are in the vicinity of the altar, you would be willing to recover their relics? I do not require many, and it is only a short trip to the southeast.$B$BWhat do you say?]', '[Chronicler To\'kini at Zim\'Torga wants you to recover 10 Har\'koan Relics.]', '', '去找祖爾德拉克的撰史者托基尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12636 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12636, 'zhTW', '', '', '[Report to the Lich King in Ebon Hold.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12637 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12637, 'zhTW', '[Near Miss]', '[It was either wisdom or luck that prevented you from wearing this choker, $r.$B$BEither way, your acquiring it was no random occurance. You\'ve been targeted by someone, or something....$B$BTake your choker to Bloodrose, here. Let her demonstrate the fate that nearly befell you.]', '[Stefan at Ebon Watch wants you to take the Unliving Choker to Bloodrose Datura.]', '', '去找祖爾德拉克的史戴芬·瓦度。', '扼喉者的目的已揭露', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12638 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12638, 'zhTW', '[Close Call]', '[It was either wisdom or luck that prevented you from wearing this choker, $r.$B$BEither way, your acquiring it was no random occurence. You\'ve been targeted by someone, or something....$B$BTake your choker to Bloodrose, here. Let her demonstrate the fate that nearly befell you.]', '[Stefan at Ebon Watch wants you to take the Writhing Choker to Bloodrose Datura.]', '', '去找祖爾德拉克的史戴芬·瓦度。', '扼喉者的目的已揭露', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12639 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12639, 'zhTW', '[The Frozen Earth]', '[We captured these elementals from nearby, and I have plenty of defenders now. But, it takes a great deal of power to make them strong enough to stand up to our enemies.$B$BThe frozen earth at Drak\'Mabwa to the northwest have what I need to maintain our defenses. I\'ll need more of their essence if I\'m to keep this up.]', '[Element-Tamer Dagoda at Zim\'Torga wants you to collect 7 Essence of the Frozen Earth.]', '', '去找祖爾德拉克的元素馴伏者達苟答。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12640 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12640, 'zhTW', '[Sealing the Rifts]', '[Dagoda gonna be sendin\' you northwest to Drak\'Mabwa to get her more stuff for her defenders if she didn\'t already.$B$BWhile you up there, Ahunae be wantin\' you to destroy the rifts those elementals pourin\' out of. The last thing we needin\' is for them to attack us!$B$BJust watch out, more of those frozen earth\'ll show up when you try to seal the rifts.]', '[Scalper Ahunae at Zim\'Torga has asked you to seal 7 Elemental Rifts.]', '', '去找祖爾德拉克的割顱者艾胡奈。', '元素裂隙已封印', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12641 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12641, 'zhTW', '[Death Comes From On High]', '[Towering above this platform is the eye of Acherus. From it you will call forth a probe that you will then use to analyze Scarlet Crusade fortifications at New Avalon. The eye has a host of powers that should make the acquisition of this data simple.$B$BUse the eye\'s siphon to analyze the forge, town hall, hold, and chapel. The eye\'s control mechanisms are located on either side of this platform. Waste no more time, $N.$B$BThe Scourge will have this place. The Lich King commands it!]', '[The Lich King commands you to use the Eye of Acherus to analyze the Scarlet Hold, New Avalon Forge, New Avalon Town Hall and the Chapel of the Crimson Flame.$B$BControl the Eye of Acherus by using the Eye of Acherus Control Mechanism.]', '', '去找黑鴉堡壘的巫妖王。', '新阿瓦隆熔爐已分析', '新阿瓦隆市政廳已分析', '血色要塞已分析', '已分析緋紅烈焰禮拜堂', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12642 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12642, 'zhTW', '', '', '[Speak with the Spirit of Rhunok at the Altar of Rhunok.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12643 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12643, 'zhTW', '[Silver Lining]', '[Once the Scourge have a target in their sights, they\'ll stop at nothing to acquire it.$B$BYou\'re doomed to a mindless existence as a walking corpse....$B$B<Stefan\'s face twists into a cruel grin.>$B$B... unless we can use their desires against them.$B$BI\'ll explain later. I have complex magic to prepare which requires certain material components.$B$BTravel due east of here to the land beneath the Reliquary of Agony. Slay the ghouls and abominations you\'ll find there and return to me with their remnants.]', '[Stefan in Ebon Watch asked you to go to the Reliquary of Agony to collect 5 Putrid Abomination Guts from the Putrid Abominations and 5 Gooey Ghoul Drools.]', '', '去找祖爾德拉克的史戴芬·瓦度。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12644 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12644, 'zhTW', '[Still At It]', '[Now that we\'ve got the raw materials, I\'ve had my assistant ready the still. He\'ll oversee the process, but I want you to help keep everything under control. You might be tempted to think that we just throw everything into the still and let it sit, but you\'re wrong.$B$BIngredients and heat need to be added at certain times, and the pressure regulated at others. You\'ll have no more than 10 seconds to react to a situation. Speak with "Tipsy" McManus when you\'re ready to start distilling.]', '[Successfully complete the distillation process and bring the completed Thunderbrew\'s Jungle Punch to Grimbooze Thunderbrew at the Nesingwary Base Camp.]', '', '去找索拉查盆地的葛林布茲·雷酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12645 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12645, 'zhTW', '[The Taste Test]', '[And now for the moment of truth!$B$B<Grimbooze chuckles.>$B$BI\'ve always wanted to say that. Normally, I\'d debut a new drink at a banquet, but we can\'t have one in the middle of the jungle.$B$BInstead, just take samples to a few trusted friends and return with their comments. Let\'s see, we\'ll definitely want Hemet Nesingwary\'s opinion, and Hadrius Harlowe\'s, too. They\'re here in camp. You\'ll want to head over to Lakeside Landing, near the center of the Basin and offer Tamara Wobblesprocket a taste.]', '[Offer a sample of Thunderbrew\'s Jungle Punch to Hemet Nesingwary, Hadrius Harlowe, and Tamara Wobblesprocket, then return to Grimbooze Thunderbrew at the Nesingwary Base Camp.]', '', '去找索拉查盆地的葛林布茲·雷酒。', '海梅特的試味', '哈德里烏斯的試味', '塔瑪拉的試味', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12646 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12646, 'zhTW', '[My Prophet, My Enemy]', '[My prophet absorbed too much of my power too quickly, and subsequently killed himself. You can see the results at the water-filled crater to the south in Drak\'Mabwa.$B$BMy former priests have already resurrected him so that he can finish the job. They\'re channeling my power back into him, and it will not be long now before he reawakens.$B$BYou must put an end to him and return with my mojo before it is too late.]', '[The Spirit of Rhunok at the Altar of Rhunok has asked you to acquire his Arctic Bear God Mojo.]', '', '去找祖爾德拉克的魯諾克之靈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12647 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12647, 'zhTW', '[An End to the Suffering]', '[My body is too far gone now, $N. It is only a matter of time before a new prophet is elevated and finishes what the other began.$B$BI am going to imbue you with the last of my power. The tormentor inside the altar building carries incense, which will awaken my body and make it vulnerable.$B$BUse the incense and do me the kindness of putting an end to my suffering.$B$BI apologize if I fight back. Even for me, the will to survive is strong.]', '[The Spirit of Rhunok has asked you to use the Tormentor\'s Incense to awaken his body. You are then to slay Rhunok using the power that his spirit has imbued you with.$B$BIf for some reason you lose the Mojo of Rhunok aura, you can return to the Spirit of Rhunok to have it reapplied.]', '', '去找祖爾德拉克的魯諾克之靈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12648 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12648, 'zhTW', '[Dressing Down]', '[There... I\'ve created a disguise that should make you indistinguishable from the Scourge.$B$BYou\'ll be free to walk among them as long as the disguise holds. Only the blightguards will be able to see through my illusion. Watch out for them!$B$BAnother thing you must know is that the disguise is unstable and may drop unexpectedly, so stay alert.$B$BLet\'s test it out. Use the choker and visit the Scourge merchant just east of here. Return to me with a bottle of bitter plasma.]', '[Stefan at Ebon Watch wants you to use the Ensorceled Choker to apply the Scourge disguise.$B$BWhile in Scourge form, you are to purchase Bitter Plasma from Gristlegut.$B$BIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.]', '', '去找祖爾德拉克的史戴芬·瓦度。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12649 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12649, 'zhTW', '[Suit Up!]', '[There... I\'ve created a disguise that should make you indistinguishable from the Scourge.$B$BYou\'ll be free to walk among them as long as the disguise holds. Only the blightguards will be able to see through my illusion. Watch out for them!$B$BAnother thing you must know is that the disguise is unstable and may drop unexpectedly, so stay alert.$B$BLet\'s test it out. Use the choker and visit the Scourge vendor just east of here. Return to me with a bottle of bitter plasma.]', '[Stefan at Ebon Watch wants you to use the Ensorcelled Choker to apply the Scourge disguise.$B$BWhile in Scourge form, you are to purchase Bitter Plasma from Gristlegut.$B$BIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.]', '', '去找祖爾德拉克的史戴芬·瓦度。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12650 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12650, 'zhTW', '[Plundering Their Own]', '[There is another altar nearby where there are artifacts to be saved.$B$BIt is said that the Drakkari at the Altar of Rhunok to the northwest, beyond the broken tundra of Drak\'Mabwa, have already plundered their own holy site.$B$B$C, I would be appreciative if you could rescue those artifacts from their undeserving hands.]', '[Chronicler To\'kini at Zim\'Torga wants you to recover 7 Rhunokian Artifacts.]', '', '去找祖爾德拉克的撰史者托基尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12651 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12651, 'zhTW', '', '', '[Speak with Tamara Wobblesprocket at Lakeside Landing.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12652 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12652, 'zhTW', '[Feedin\' Da Goolz]', '[Git o\'er heer, gool! Yeh, I talkin\' to yoo.$B$BIt feedin\' time now. Gotta git da grub ta all da gools!$B$BSpeshal grub dis time! Bowels an\' brainz bowl... num, num, num.$B$BJus drop da bowl nexta da gool. Gud way ta make frenz.$B$BYoo got goolfrenz? Ha, ha, hah!]', '[Gristlegut at the Reliquary of Agony wants you to use Bowels and Brains Bowl next to 10 Decaying Ghouls.]', '', '去找祖爾德拉克的軟魄。', '已餵食腐爛食屍鬼', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12653 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12653, 'zhTW', '', '', '[Speak with Har\'koa at the Altar of Har\'koa.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12654 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12654, 'zhTW', '[The Part-time Hunter]', '[When Hemet asked me to accompany Marvin out here, I hoped that I might have the opportunity to work on my own hunting skills in between repairing the flying machines and setting up the camp.$B$BI wanted to take down a ferocious lion named Pitch. He\'s said to make his home south of here, near where the Wildgrowth Mangal meets the northern face of the Skyreach Pillar. If you can find the beast, would you bring back his remains? If the rumors are true, they\'d make a trophy even Hemet will respect!]', '[Bring Pitch\'s Remains to Tamara Wobblesprocket at Lakeside Landing.]', '', '去找索拉查盆地的塔瑪拉·顛鏈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12655 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12655, 'zhTW', '[The Blessing of Zim\'Rhuk]', '[There is another god of Zul\'Drak that is being neglected.$B$BZim\'Rhuk\'s statue lies directly to the north. Known as "The Wise One", Zim\'Rhuk is also known to be very protective of his domain. He maintains guardians that deal harshly with anyone that does not have the wits to slip past them.$B$BAvoid the guardians and give the Drakkari offerings to Zim\'Rhuk so that you will benefit from his blessing.]', '[Witch Doctor Khufu wants you to present 10 Drakkari Offerings to the statue of Zim\'Rhuk.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12656 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12656, 'zhTW', '[Blessing of Zim\'Rhuk]', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12657 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12657, 'zhTW', '', '', '[The Lich King commands you to carry his orders to Highlord Darion Mograine at Ebon Hold.Use the glowing transporter behind the Lich King to reach Highlord Darion Mograine in the Hall of Command.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12658 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12658, 'zhTW', '[My Pet Roc]', '[Dorian\'s had me training and feeding the baby drakes he captures, and it has gotten me thinking. I want a pet of my own!$B$BNo, not a juvenile drake. I don\'t want a pet capable of biting my hand off!$B$BHowever, in the Bonefields to the northeast of the camp, beyond the area dominated by the drakes, there\'s a large population of goretalon rocs. The grown ones are beyond hope of domesticating, but if you bring me the eggs from their nests, I can raise them from the time they hatch.]', '[Bring 7 Roc Eggs to Zootfizzle at Dorian\'s Outpost.]', '', '去找索拉查盆地的狹嘶。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12659 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12659, 'zhTW', '[Scalps!]', '[I thinkin\' it be time to do some scalpin\', mon!$B$BThe trolls at Heb\'Drakkar to the northeast should do nicely. With their fancy bats and attackin\' us, they got it comin\'!$B$BAhunae even give you his own knife so that you do the job right.]', '[Scalper Ahunae at Zim\'Torga wants you to use Ahunae\'s Knife to scalp 10 Heb\'Drakkar trolls.$B$BThe scalper reminds you that you should loot them first.]', '', '去找祖爾德拉克的割顱者艾胡奈。', '赫布達卡萊巨魔已被剝頭皮', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12660 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12660, 'zhTW', '[Weapons of Destruction]', '[The Lich King\'s lackeys have dared to bring weapons of destruction into my domain.  I will not stand for this.$B$BGo to their outpost to the north and destroy the weapons they would use against the land.  We cannot let the Scourge taint another inch of these sacred lands.]', '[The Avatar of Freya wants you to go to the Death\'s Hand Encampment to the northwest and destroy 4 Unstable Explosives.]', '', '去找索拉查盆地的芙蕾雅的化身。', '不穩定炸藥已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12661 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12661, 'zhTW', '[Infiltrating Voltarus]', '[By now you\'ve probably guessed the details of my plan.$B$BWe\'re using the Scourge\'s interest in you against them. You\'re going undercover. I know it\'s likely a death sentence, but if we do nothing your death is a certainty.$B$BTravel northeast to Reliquary of Pain and stand on the platform while wearing your disguise. Once inside Voltarus, you must earn the trust of the Scourge commander.$B$BWhen you\'ve completed your mission, blow this horn and I\'ll fly to your location to receive your report.]', '[Stefan wants you to use your Ensorcelled Choker to get into Voltarus and do whatever the Scourge leader there asks of you.$B$BIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.]', '', '去找祖爾德拉克的史戴芬·瓦度。', '上將達庫魯的任務已完成', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12662 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12662, 'zhTW', '[Bringing Down Heb\'Jin]', '[<Dagoda looks at Ahunae and sighs.>$B$BYou want to really deal with Heb\'Drakkar? Collecting scalps isn\'t going to get the job done. You have to take out their leader, Heb\'Jin.$B$BThe problem is, he\'s up on the bat rookery goading his forces on.$B$BBang his drum and I guarantee that he\'ll fly down. That\'s when you kill him.$B$BYou can take this net we got from one of his headhunters. Use it to trap his bat when he lands. That way you won\'t have to fight both of them.$B$B]', '[Element-Tamer Dagoda at Zim\'Torga wants you to kill Heb\'Jin.]', '', '去找祖爾德拉克的元素馴伏者達苟答。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12663 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12663, 'zhTW', '[Reunited]', '[$n!$B$BYa musta received mah gift! Turn around, mon, lemme get a good look at ya... Ahh, ya make me proud.$B$BWe come such a long way, you and I, and now we be servin\' da Lich King together.$B$BStick with me and big things be comin, mon. Big things... but first, we need to be gettin\' ya caught up. So much been happenin\' since I saw ya last.$B$BGo speak ta Gorebag for a tour of Zul\'Drak. Listen for me and I\'ll tell ya all ya be needin\' ta know. ]', '[Drakuru in Voltarus wants you to speak to Gorebag and take the tour of Zul\'Drak.]', '', '去找祖爾德拉克的德拉庫魯霸主。', '祖爾德拉克的巡禮已完成', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12664 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12664, 'zhTW', '[Dark Horizon]', '[Ahh, another supplicant answerin\' da Lich King\'s call.$B$B<Drakuru sniffs you.>$B$BFreshly scourged, eh? Ya still be reekin\' of da living!$B$BLong be da line of dem who seek da Lich King\'s blessings. Ya must rise above da masses and prove yerself worthy of wieldin\' true power.$B$BLookin\' down over Zul\'Drak, I sensed potential in ya. I ordered your - invitation.$B$BDa rest be up ta you....$B$BGo an\' speak ta Gorebag for a tour of Zul\'Drak. Dere be much ta do if you\'re to be of any worth to me.]', '[Drakuru in Voltarus wants you to speak to Gorebag and take the tour of Zul\'Drak.]', '', '去找祖爾德拉克的德拉庫魯霸主。', '祖爾德拉克的巡禮已完成', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12665 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12665, 'zhTW', '[I Sense a Disturbance]', '[There\'s something wrong with Quetz\'lun, the wind serpent goddess. What it is exactly I cannot sense, but I do know that her altar has been overrun with powerful creatures.$B$BI\'m going to send you there on the back of one of my children, which you saved. The two of you will move swiftly and with great stealth to uncover what has become of Quetz\'lun.$B$BMy child will see you safely back to me. Just keep your eyes open.$B$BWhen you are ready, ask and I will call one of my kittens for you.]', '[Har\'koa has asked you to determine what has happened to Quetz\'lun. Speak to her to be able to ride one of her children stealthily into the Altar of Quetz\'lun.$B$BReturn to her at the Altar of Har\'koa once you have done so.]', '奎茲倫的命運已揭露', '去找祖爾德拉克的哈寇亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12666 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12666, 'zhTW', '[Preparations for the Underworld]', '[Quetz\'lun may be dead, but I can still feel her spirit lingering in the underworld at the altar. We have to find a way to get you to her.$B$BLuckily for us, I just happen to have a supply of former supplicants at hand who are no longer in need of their sacred adornments. Both my subduers and claws are likely to still be wearing them.$B$BBring the adornments to me and I\'ll draw upon their energy to enable you to cross over into Quetz\'lun\'s underworld nightmare.]', '[Har\'koa wants you to collect 8 Sacred Adornments. Deliver them to her at the Altar of Har\'koa.]', '', '去找祖爾德拉克的哈寇亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12667 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12667, 'zhTW', '', '', '[Seek Quetz\'lun\'s Spirit at the Altar of Quetz\'lun.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12668 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12668, 'zhTW', '[Foundation for Revenge]', '[I have something special planned for my favorite high priests. But first you get to prove yourself in laying the foundation for my revenge.$B$BYou do still want to live, yes?$B$BAs you have seen, my devotees are enjoying their stay here, but now it\'s time for them to make final restitution.$B$BDo me the smallest of favors if you would, $N. Lure them near my soul fonts and then put an end to their existences.$B$BThey taste so delicious, and their sacrifice will not go in vain, I can assure you.]', '[Quetz\'lun\'s Spirit has tasked you with the destruction of 12 trolls, either Quetz\'lun Worshippers or Serpent-Touched Berserkers, near her Soul Fonts.$B$BOnly after you have accomplished this should you return to her at the Altar of Quetz\'lun.]', '', '去找祖爾德拉克的奎茲倫的靈魂。', '已在靈魂噴泉附近擊殺巨魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12669 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12669, 'zhTW', '[So Far, So Bad]', '[Everything you\'ve reported is consistent with what we know. Learning of Drakuru and earning his trust will lay the groundwork for your future missions.$B$BReturn to him and do as he says. Do whatever you must to appear sincere, $n. A great deal is riding upon your performance.$B$BThis time I\'m adding an additional assignment: While you\'re in the field, pour this additive into their blight cauldrons. It should neutralize the scourging agent and render the batch useless.]', '[Stefan at Ebon Watch wants you to return to Drakuru and complete any tasks he has for you.$B$BWhile at the Reliquary of Pain, you are to use the Diluting Additive on 5 Blight Cauldrons.$B$BIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.]', '', '去找祖爾德拉克的史戴芬·瓦度。', '達庫魯的任務已完成', '枯萎坩堝已稀釋', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12670 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12670, 'zhTW', '', '', '[Report to Prince Valanar at Death\'s Breach.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12671 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12671, 'zhTW', '[Reconnaissance Flight]', '[It\'s about time we had planes up and running in this place.  The professor\'s been asking me to check out a strange weather pattern coming from the northeast.$B$BThing is, I\'m going to need a co-pilot if we\'re going into uncharted territory.  No way in hell I\'m heading out there alone.$B$BWhat do you say, <tough-guy/hotshot>?  You might learn a thing or two.  And once you learn to deal with the northern winds... you can pretty much fly anywhere.]', '[Help Pilot Vic complete the Reconnaissance Flight.]', '偵察飛行', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12672 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12672, 'zhTW', '[Setting the Stage]', '[I will give you a chance at continued existence.$B$BThere are fragments of the power that fueled my curse scattered about the altar grounds. It is my desire that you collect some of them for me. Not so many that the curse will be lifted, but enough that I will be able to eventually make use of them to exact revenge upon my prophet.$B$BGo, insect. Run and do my bidding before I change my mind about letting you live.]', '[Quetz\'lun\'s Spirit has demanded that you collect 10 Underworld Power Fragments. Return to her at the Altar of Quetz\'lun only when you have done so.]', '', '去找祖爾德拉克的奎茲倫的靈魂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12673 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12673, 'zhTW', '[It Rolls Downhill]', '[If ya ever gonna be worthy of da Lich King\'s gifts, ya must learn ta be a great leader - one who be commandin\' respect!$B$BI got a task dat gonna refine your command skills, mon....$B$BSumma my minions be trained ta harvest blight crystals from da land below, but dey be lazy and slow. You gonna be in charge o\' dem, mon.$B$BTake dis scepter and teach \'em how to get da job done. When dey be under your control, make \'em harvest dem crystals!]', '[Overlord Drakuru in Voltarus wants you to use the Scepter of Suggestion on the Blight Geists and then order them to harvest 7 Blight Crystals.]', '', '去找祖爾德拉克的德拉庫魯霸主。', '已收集枯萎水晶', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12674 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12674, 'zhTW', '[Hell Hath a Fury]', '[It is now time for you to punish my three high priests: Mu\'funu, Tua-Tua, and Hawinni. You\'ll find them spread around the altar grounds.$B$BTake this hexxing stick. I\'ve empowered it with my rage and indignation. I\'m sure that it will prove potent.$B$BJust use it and proceed to destroy them. The hex will take care of the rest.$B$B<Quetz\'lun displays a toothy grin.>$B$BSucceed and I may let you go. Fail and die.]', '[Quetz\'lun\'s Spirit at the Altar of Quetz\'lun wants you to use Quetz\'lun\'s Hexxing Stick upon High Priest Mu\'funu, High Priestess Tua-Tua, and High Priest Hawinni. Once you have done this, slay them.]', '', '去找祖爾德拉克的奎茲倫的靈魂。', '大祭司穆夫努死前已被施咒', '大女祭司圖阿圖阿死前已被施咒', '大祭司哈溫尼死前已被施咒', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12675 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12675, 'zhTW', '[One Last Thing]', '[There is one last thing that is needed to enact the final revenge against my prophet. The power fragments you collected must be imbued with a portion of a living gods\' spirit. You\'re going to need to beseech Har\'koa for some of hers.$B$BOnce you\'ve done that, when you return here, you will not come to the underworld. Instead, you will return to the physical world of my altar. My children and guardians will no longer attack you, and you\'ll be able to get to my prophet without having to worry about them.]', '[Deliver the Underworld Power Fragments to Har\'koa and beseech her for a portion of her spirit. You will still find her at the Altar of Har\'koa.]', '', '去找祖爾德拉克的哈寇亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12676 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12676, 'zhTW', '[Sabotage]', '[While we\'re working to discover the purpose of these crystals, we need you back in Voltarus doing Drakuru\'s bidding.$B$BEvery task you perform successfully gets you closer to him, and brings us that much nearer to knowing his mind.$B$BWhile you\'re there, I have another mission for you. Drakuru\'s Scourgewagons pose a significant threat. We need them destroyed. $B$BMake your way to the wagons and activate these charges. Once they\'re set, get clear! The explosion will expose you if you\'re too close.]', '[Stefan at Ebon Watch wants you to perform another task for Drakuru.$B$BAdditionally, you are to use the Explosive Charges on 5 Scourgewagons at the  Reliquary of Pain.$B$BIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.]', '', '去找祖爾德拉克的史戴芬·瓦度。', '天災戰車已摧毀', '達庫魯的任務已完成', '得知達庫魯的秘密', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12677 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12677,'zhTW','危險物質','荒疫水晶?!這該死的德拉庫魯究竟想要做什麼?$B$B顯然，他在做的事很重要。繼續完成他的要求，也許當他跟你更熟了以後，就會讓你知道他的計畫。$B$B在此期間，我們得調查這些水晶。$B$B當你進入沃塔魯斯的時候，試著趁沒人注意的時候弄來一些採收的水晶。$B$B小心點!處理那些水晶的時候你的偽裝有可能會消失。','黯黑守望的史戴芬要你去沃塔魯斯完成任何德拉庫魯要你做的任務。當你到那裡的時候，要去偷取5個採收的荒疫水晶。$B$B如果你失去了蠱惑頸飾，回去黯黑守望找史戴芬再要一個。','','去祖爾德拉克找黑鋒哨站的斯特凡·瓦杜。','完成德拉庫魯的任務','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12678 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12678, 'zhTW', '[If Chaos Drives, Let Suffering Hold The Reins]', '[They make their stand now, outside of Death\'s Breach, futilely attempting to push us back in hopes of saving their horses, mines, lumber and citizens.$B$BThis will be your first lesson in Scourge warfare: TERROR!$B$BGo to the front lines, south of here, and destroy Scarlet Crusaders. Leave their corpses so that we may utilize them for the death march.$B$BBut most importantly: kill the fleeing villagers. Soldiers dying are an affordance, but villagers? That is what strikes fear into the hearts of man.]', '[Prince Valanar at Death\'s Breach commands you to slay 10 Scarlet Crusaders or Scarlet Peasants and 10 Citizens of Havenshire.]', '', '去找瘟疫之地：血色禁地的瓦拉納爾親王。', '血色十字軍已擊殺', '避難郡的居民已擊殺', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12679 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12679, 'zhTW', '[Tonight We Dine In Havenshire]', '[The Sky Darkeners are mindless constructs with one purpose: KILL! Specifically, they are aiming to kill any man or woman that they see fleeing Havenshire for the safety of New Avalon. We certainly can\'t allow those cowards to make it to safety and then take up arms against us!$B$BThere is one slight problem. They use saronite arrows for maximum range and damage. Saronite, however, is a metal only found in Northrend, so supplies are limited! Retrieve those arrows for me and I will reward you handsomely.]', '[Orithos the Sky Darkener at Death\'s Breach wants you to recover 15 Saronite Arrows.]', '', '去找瘟疫之地：血色禁地的『晦天者』歐里索斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12680 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12680, 'zhTW', '[Grand Theft Palomino]', '[How fortuitous it is that the Crusade has a stable full of horses a mere stone\'s throw from this post. Though they guard it tenaciously, an enterprising young death knight could break through their defenses and take what is rightfully $g他的：她的;!$B$BOnce you acquire a horse from the Havenshire Stables, return it to me and I will see what can be done about transforming it into a proper deathcharger.$B$BRemember, $N, it\'s only stealing if you\'re caught. Watch out for that deranged stable master, Kitrik!]', '[Salanar the Horseman asks that you steal a horse from the Havenshire Stables and return it to him at Death\'s Breach.]', '', '去找瘟疫之地：血色禁地的『騎士』撒拉納。', '已成功偷取馬匹', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12681 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12681, 'zhTW', '[Reagent Agent]', '[That Archmage Pentarus, back in Dalaran, will be expecting us to return with all kinds of reagents and talismans. It seems the locals are fond of animal parts. Twisted claws from the goretalon rocs are among their favorite.$B$BIt\'s not my place to say whether the rumors are true or not, but I\'ve a feeling there\'s something here.$B$BThe rocs live in the Bonefields off to the northeast, where they feed on the corpses of old mammoths. Will you help me gather talons for the archmage\'s research?]', '[Bring 5 Twisted Roc Claws to Colvin Norrington at Dorian\'s Outpost.]', '', '去找索拉查盆地的寇爾文‧諾靈頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12682 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12682,'zhTW','人跡未竟之地(DEPRECATED)','並非所有的遠征隊成員都是來狩獵取樂的，我們中的一部分人還肩負著重要的研究工作。$B$B冰封的北裂境中心竟然存在這樣一片熱帶天堂——休拉薩盆地真是不可思議的存在。如果我不能搞清楚這片土地的奧秘，就不配做個學者。$B$B這張地圖給你吧。','這次遠征隊裡並不是所有人都是來獵殺最大、最稀有的獵物的。我們之中有些人其實有正經事要做。$B$B這個地方的存在本身就令人費解——在北裂境的中央居然有一片熱帶樂園。如果我不花點心思試著了解這個地方，那我這個學者的頭銜可就名不副實了。$B$B拿著這些','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12683 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12683, 'zhTW', '[Burning to Help]', '[There\'s no more caustic material in all of the basin than bittertide hydra sputum. I\'ve got special containers to collect just such a thing for Archmage Pentarus\' studies. Now all I need is a brave, um... collector.$B$BYou look like a hardy, adventurous $c. How\'d you like to make a bit of money and aid Dalaran\'s cause at the same time?$B$BAll you need to do is take this container with you to Bittertide Lake, to the southwest. Engage the hydra and use the container to sample the sputum they shower you with.]', '[Colvin Norrington at Dorian\'s Outpost wants you to take 5 Hydra Sputum Samples and kill 5 Bittertide Hydra.]', '', '去找索拉查盆地的寇爾文‧諾靈頓。', '已收集痰液樣本', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12684 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12684, 'zhTW', '[Blood of a Dead God]', '[Mam\'toth, the god of the mammoths, destroyed himself, and took much of his temple with him, rather than allowing his trolls to gain his power.$B$BIf I\'m to sacrifice a portion of my spirit, I will need something with which to bolster myself.$B$BMam\'toth left behind an enormous crater to the northeast, just north of the Altar of Quetz\'lun. Within the crater his blood yet lives.$B$BBring it to me.]', '[Har\'koa has asked you to collect 7 Blood of Mam\'toth. Return them to her at the Altar of Har\'koa.]', '', '去找祖爾德拉克的哈寇亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12685 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12685, 'zhTW', '[You Reap What You Sow]', '[This is what it has come down to... revenge.$B$B<Har\'koa sighs.>$B$BTake this ritual kit and enact it near Quetz\'lun\'s corpse upon her altar. If everything works properly, her spirit should be drawn into the material world where she will be able to reclaim her power from the prophet.$B$BThe rest will be up to you, $N. You must slay the prophet in his drained state.]', '[Slay the Drained Prophet of Quetz\'lun and then inform Witch Doctor Khufu at Zim\'Torga.]', '', '去找祖爾德拉克的巫醫庫弗。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12686 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12686, 'zhTW', '[Zero Tolerance]', '[Ignorance! Dis be intolerable, mon! My entire batch of blight be useless!$B$BDat mongrel, Darmuk! He be responsible for watchin over da blight. He failed me, mon!$B$BDis be a good lesson for ya, $n. Failure be like a disease dat spreads. Ya gotta catch it and kill it early, before it be killin\' you!$B$BTake dis scepter. It make my scourged trolls stronger. Use dem ta kill Darmuk. He be lurkin\' down below just to da south.$B$BLet dat be an example to all, mon. Don\'t be failin\' Drakuru!]', '[Drakuru in Voltarus wants you to go to the Reliquary of Pain and use the Scepter of Empowerment on a Servant of Drakuru. You are then to use its abilities to defeat Darmuk.]', '', '去找祖爾德拉克的德拉庫魯霸主。', '已擊殺達爾穆克', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12687 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12687, 'zhTW', '[Into the Realm of Shadows]', '[The horse you stole has been taken to the Realm of Shadows. It is there that my dark rider will slay the beast and raise it as a deathcharger. Do you think yourself brave enough to enter the Realm of Shadows in pursuit of the deathcharger?$B$BIf you accept, I will transport you to the shadow world. Once there, seek out a dark rider in the open fields south of us. To emerge victorious you must slay him, overtake his deathcharger and return it to Death\'s Breach. Issue the Horseman\'s Call should you succeed.]', '[Salanar the Horseman at Death\'s Breach has challenged you to slay the Dark Rider of Acherus and take his Acherus Deathcharger.$B$BShould you succeed, return the Acherus Deathcharger to Death\'s Breach and use the Horseman\'s Call to summon Salanar.]', '騎士的挑戰', '去找瘟疫之地：血色禁地的『騎士』撒拉納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12688 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12688, 'zhTW', '[Engineering a Disaster]', '[These goblin goons and their minions have decided that they own this pillar and its crystals. I came here to explore the crystals and take samples, but they overpowered me and won\'t let me return to the camp.$B$BIf you\'ll help me fight our way out of here, we can teach these thugs a lesson they\'ll never forget!]', '[Help Engineer Helice escape from Swindlegrin\'s Dig, then speak with Hemet Nesingwary at the Nesingwary Base Camp.]', '護送工程師海莉絲離開斯溫格林的挖掘場', '去找索拉查盆地的赫米特·奈辛瓦里。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12689 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12689, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12690 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12690, 'zhTW', '[Fuel for the Fire]', '[It be time we start our march to Gundrak, mon. It be time for me ta turn ya loose on dem trolls!$B$BDey breached our wall and put a whole army just north of us.$B$BHahaha!$B$BDey be fuel for da fire, mon! We gunna take da chieftiains an\' kill da rest! It all be part of my master plan....$B$BYou take dis scepter and go command my abominations. Bring \'em to da Drakkari army and kill em all! When da chieftains come, my pet Shalewing gunna snatch \'em up and bring \'em here to me.]', '[Drakuru in Voltarus wants you to use the Scepter of Command on Bloated Abominations and then use their abilities at the Frigid Breach to kill 60 Drakkari Skullcrushers and lure out 3 Drakkari Chieftains.$B$BChieftains will appear when enough Skullcrushers have been slain.]', '', '去找祖爾德拉克的德拉庫魯霸主。', '達卡萊碎顱者已擊殺', '已引誘達卡萊酋長', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12691 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12691, 'zhTW', '[A Timeworn Coffer]', '[The stone coffer appears to be locked.  It appears that a key fits inside a large stone keyhole.$B$BPerhaps one of the guardians in the vicinity has this key in its possession.]', '[Obtain a Huge Stone Key from the nearby Sholazar Guardians and bring it to the Timeworn Coffer at the Maker\'s Overlook.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12692 AND `locale` = 'zhTW';
