INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12771,'zhTW','鐵爐堡','聖光響應了我們的祈禱！依靠撒塔斯城的納魯所賜予的聖光精華，以及虔誠信徒的祈福，我們終於創造出了神聖而強大的聖物，這些聖物將成為我們對抗巫妖王的利器。$B$B帶上這個，$n。你要仔細保護它，把它安全地送到鐵爐堡。麥格尼·銅鬚急於轉至北裂境參戰，這件聖物可以説明他達成目標。','拉莎莉爾主教要你將光明聖物交給鐵爐堡的國王麥格尼·銅鬚。','','到鐵爐堡找國王麥格尼·銅鬚。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12772 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12772, 'zhTW', '', '', '[Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12773 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12773, 'zhTW', '[Darnassus]', '[Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King\'s machinations.$B$BTake this, $n.  Guard it close, and secure its passage to Darnassus.  Deliver it to Tyrande Whisperwind -- her priests will find it a vital source of power in their fight against the unholy forces from the North.]', '[Bishop Lazaril wants you to bring the Light-infused Artifact to Tyrande Whisperwind in Darnassus.]', '', '去達納蘇斯找神殿花園的泰蘭妲·語風。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12774 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12774, 'zhTW', '[Stormwind]', '[Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King\'s machinations.$B$BTake this, $n.  Guard it close, and secure its passage to Stormwind.  The King of Stormwind has recently returned; I\'m sure he will welcome this tool.]', '[Bishop Lazaril wants you to bring the Light-infused Artifact to King Varian Wrynn in Stormwind.]', '', '去找艾爾文森林的瓦里安·烏瑞恩國王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12775 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12775, 'zhTW', '', '', '[Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12776 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12776,'zhTW','艾克索達','聖光響應了我們的祈禱！依靠撒塔斯城的納魯所賜予的聖光精華，以及虔誠信徒的祈福，我們終於創造出了神聖而強大的聖物，這些聖物將成為我們對抗巫妖王的利器。$B$B帶上這個，$n。你要仔細保護它，把它安全地送到艾克索達，交給聖光穹頂的先知維倫。他可以借用聖物的力量對抗阿爾薩斯的邪惡部隊。','拉莎莉爾主教要你將光明聖物交給艾克索達的維倫。','','到艾克索達找先知維倫。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12777 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12777,'zhTW','絕望的聯軍','親愛的$n，巫妖王在用疾病和侵略折磨著我們——部落和聯盟都深受其害。只有艾澤拉斯的這兩個偉大文明聯手，才有可能擊敗他。$B$B我們在撒塔斯城的聖光廣場結成了聯軍。$B$B為了幫助我們對抗巫妖王，請你到聖光廣場的新聯盟營地去，和拉莎莉爾主教談一談。$B$B願聖光保佑你，$n。','到撒塔斯城的聖光廣場去，與新聯盟營地中的拉莎莉爾主教談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12778 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12778, 'zhTW', '', '', '[Seek out the Lich King at Death\'s Breach.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12779 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12779, 'zhTW', '[An End To All Things...]', '[You have slaughtered legions beyond number and still your dark heart craves more. Your hunger knows no end, $N.$B$B<The Lich King pauses.>$B$BThere must come an end to all things, death knight. The Scarlet armies make their final stand against us. For them, there is no escape... no choice. And for this reason they will fight with a ferocity that you have yet to witness.$B$BUse this horn to call forth one of my wyrms. Climb upon its back and command it into battle. With it you will end the Scarlet Crusade.]', '[The Lich King has commanded you to eradicate the Scarlet Crusade.$B$BUse the Horn of the Frostbrood to call forth a Frostbrood Vanquisher and with it slay 150 Scarlet Soldiers and destroy 10 Scarlet Ballistas. Avoid incoming projectiles by moving out of their line of fire!]', '', '去找瘟疫之地：血色禁地的巫妖王。', '血色士兵已擊殺', '血色投石車已摧毀', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12780 AND `locale` = 'zhTW';
