INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12781, 'zhTW', '[Welcome!]', '[Welcome to the World of Warcraft!$B$BAs special thanks for purchasing the World of Warcraft Collector\'s Edition, turn in this gift voucher to Siouxsie the Banshee in Ebon Hold.  You\'ll then be given a gift: a little companion to join you on your quest for adventure and glory.$B$BThanks again, and enjoy your stay in the World of Warcraft!$B$B]', '[Bring the Ebon Hold Gift Voucher to Siouxsie the Banshee in Ebon Hold.]', '', '去找『女妖』席厄克希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12782 AND `locale` = 'zhTW';
