INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12785, 'zhTW', '[Orgrimmar]', '[We have a breakthrough!  Our zombie specimens have given us new insight into the nature of the Scourge\'s plague.  They have born rotten, delicious fruit...$B$BTake this box to Orgrimmar.  Inside is a head that is infected with the zombie plague, and something else we have devised -- an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.$B$BBring the box to my assistant, Apothecary Karlov.  He attends Warchief Thrall in Orgrimmar.]', '[Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Karlov in Orgrimmar.]', '', '去找奧格瑪的藥劑師卡洛孚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12786 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12786, 'zhTW', '[Thunder Bluff]', '[We have a breakthrough!  Our zombie specimens have given new insight into the nature of the Scourge\'s plague.  They have born rotten, delicious fruit...$B$BTake this box to Thunder Bluff.  Inside is a head that is infected with the zombie plague, and something else we have devised -- an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.$B$BBring the box to my assistant, Apothecary Chaney.  He attends Magatha Grimtotem in Thunder Bluff.]', '[Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Chaney in Thunder Bluff.]', '', '去莫高雷找雷霆崖的藥劑師夏睨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12787 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12787, 'zhTW', '[The Undercity]', '[The zombie plague was a blessing in disguise.  In our search for a cure, we have learned so much of the Scourge and their contagion.  Our research has given us weapons against them.  Weapons, and tools...$B$BTake this -- it is a zombie\'s head and has been partially cured of its plague by injecting it with a compound derived from our recent discoveries.  Deliver the head to Master Apothecary Faranell; I have a list of experiments I would like him to perform on it.]', '[Grand Apothecary Putress wants you to give the Dual-plagued Brain to Master Apothecary Faranell in the Undercity.]', '', '去找奧特蘭克山脈的藥劑大師法拉尼爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12788 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12788, 'zhTW', '[Silvermoon]', '[We have a breakthrough!  Our zombie specimens have given new insight into the nature of the Scourge\'s plague.  They have born rotten, delicious fruit...$B$BTake this box to Silvermoon City.  Inside is a head that is infected with the zombie plague, and something else... an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.$B$BBring the box to my assistant, Apothecary Tepesh.  She attends Lor\'themar Theron in Silvermoon City.]', '[Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Tepesh in Silvermoon City.]', '', '去找銀月城的藥劑師提琵希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12789 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12789, 'zhTW', '', '', '[Crusader Valus at Light\'s Trust wants you to report to Sergeant Riannah at Light\'s Breach in Zul\'Drak.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12790 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12790, 'zhTW', '[Learning to Leave and Return: the Magical Way]', '[Just in case you don\'t already know, you can use the crystal on the platform behind me to teleport to the Violet Stand in Crystalsong Forest beneath Dalaran.$B$BCorrespondingly, you can use the crystal at the stand below to return to the chamber above me.$B$BI would like for you to do this now.]', '[Archmage Celindra at The Violet Gate in Dalaran wants you to use the Teleport to Violet Stand Crystal and the Teleport to Dalaran Crystal.]', '', '去找達拉然的大法師瑟琳卓。', '已使用紫羅蘭崗哨傳送水晶', '已使用達拉然傳送水晶', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12791 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12791, 'zhTW', '[The Magical Kingdom of Dalaran]', '[Hello, $N. You may or may not be aware that we Kirin Tor moved our city here to Northrend.$B$BNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.$B$BWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.$B$BWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.]', '[Deliver the Kirin Tor Signet to Archmage Celindra at The Violet Gate in Dalaran.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12792 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12792, 'zhTW', '', '', '[Commander Kunz at Argent Stand wants you to report to Sergeant Riannah at Light\'s Breach.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12793 AND `locale` = 'zhTW';
