INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13069, 'zhTW', '[Shoot \'Em Up]', '[Jotunheim has aerial defenses, both in terms of proto-drake riders and harpoon guns. They\'ve concentrated these on their northern and western facings where they are most vulnerable.$B$BLet\'s use their defenses against them!$B$B<The Leaper pierces you with his single eye and cackles maniacally.>$B$BTake control of a harpoon gun on the platforms that overhang the cliffs on either side of Valhalas to the southwest. Take out the proto-drakes and their riders. Shoot \'em up!]', '[The Leaper at The Shadow Vault wants you to use a Jotunheim Rapid-Fire Harpoon to shoot down 15 Jotunheim Proto-Drakes and their riders.]', '', '去找冰冠冰川的跳躍者。', '尤頓海姆始祖幼龍與其騎士已擊落', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13070 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13070, 'zhTW', '', '', '[Report to Siegemaster Fezzik at the Argent Vanguard in Icecrown.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13071 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13071, 'zhTW', '[Vile Like Fire!]', '[Vile like fire! Vile like proto-drakes!$B$B<The abomination claps its hands excitedly.>$B$BLittle $N go to Jotunheim and steal a pretty proto-drake in Njorndar Village. Make proto-drake make pretty fires on Jotunheim buildings!]', '[Vile at The Shadow Vault wants you to steal a Njorndar Proto-Drake and use it to set fire to 8 vrykul buildings in the greater Jotunheim region.$B$BBalargarde Fortress, due to its nature, cannot be set ablaze.]', '', '去找冰冠冰川的暗邪。', '維库人建築已點燃', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13072 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13072, 'zhTW', '', '', '[Bring news of Crusader Bridenbrad\'s fate to Highlord Tirion Fordring at Crusaders\' Pinnacle.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13073 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13073, 'zhTW', '', '', '[Highlord Tirion Fordring at Crusaders\' Pinnacle has requested that you secure passage from Arch Druid Lilliandra and speak to Keeper Remulos in Moonglade.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13074 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13074, 'zhTW', '[Hope Within the Emerald Nightmare]', '[What we need exists only in the emerald dream... acorns that are infused with a powerful restorative magic. Many places in this sacred glade are closely tied with the dream, and my shrine is among them.$B$BI will send you into the dream to recover some of these acorns. Be prepared though $c, for this method of entering the dream is dangerous, and it is very likely you will be beset by nightmares.$B$BRecover a few acorns quickly, and then depart from my shrine or pinch yourself to return to our world.]', '[Keeper Remulos at Moonglade has instructed you to enter the emerald dream and recover 3 Emerald Acorns.$B$BLeave the vicinity of the Shrine of Remulos to return to Azeroth.]', '', '去月光林地找月神湖的守護者雷姆洛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13075 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13075, 'zhTW', '[The Boon of Remulos]', '[I shall open a portal to take you back to the druid that brought you here. You and your crusader have my well wishes. I hope that this acorn is able to purify your crusader and save him from the wretched fate of the plague.$B$BFarewell, $r.]', '[Return to Crusader Bridenbrad at the Silent Vigil in Icecrown with the Emerald Acorn.]', '', '去找冰冠冰川的十字軍布理登布萊特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13076 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13076, 'zhTW', '', '', '[Return to Highlord Tirion Fordring at Crusaders\' Pinnacle with news of Emerald Acorn\'s effects.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13077 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13077, 'zhTW', '', '', '[Request the aid of Alexstrasza the Life-Binder at Wyrmrest Temple.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13078 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13078, 'zhTW', '[Dahlia\'s Tears]', '[In this dark time, I\'ll not be the one to abandon a champion of the Light.$B$BWe will need something sacred for this to have a hope of saving your Bridenbrad... a remnant of a devout being that fell victim to this very same plague.$B$BGo now to the sacred soil of the passages outside my Ruby Dragonshrine where the battle is joined. As my Ruby Keepers fly down and set flame to the ground beneath undead feet, you will witness new life grow forth. Among that life are Dahlia\'s Tears - bring them to me.]', '[Alexstrasza the Life-Binder at Wyrmrest Temple has requested that you recover Dahlia\'s Tears from soil freshly cleansed by a Ruby Keeper\'s flames.]', '', '去找龍骨荒野的『生命守縛者』雅立史卓莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13079 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13079, 'zhTW', '[The Boon of Alexstrasza]', '[You must understand, young $r, that cleansing the body in favor of life anew is something well within my grasp... removing the plague of undeath without affecting the body, however, is beyond the scope of the powers that I control.$B$BIf this Bridenbrad is the beacon of light that you profess him to be, perhaps he will endure such a cleansing and thrive, but I cannot state with confidence that this is the salvation that you seek. Take it and go with all of my blessings.]', '[Bring the Breath of Alexstrasza to Crusader Bridenbrad at the Silent Vigil in Icecrown.]', '', '去找冰冠冰川的十字軍布理登布萊特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13080 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13080, 'zhTW', '', '', '[Return to Highlord Tirion Fordring at Crusaders\' Pinnacle with news of the effects of the Breath of Alexstrasza.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13081 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13081, 'zhTW', '', '', '[Request the aid of A\'dal at Shattrath City in Terokkar Forest.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13082 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13082, 'zhTW', '', '', '[Return to Crusader Bridenbrad at the Silent Vigil in Icecrown.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13083 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13083, 'zhTW', '[Light Within the Darkness]', '[<Crusader Bridenbrad\'s tabard rests in the bottom of the chest, shifting slightly as the howling wind finds its way in.>$B$BTirion will desire this last remnant of the great crusader.]', '[Bring Crusader Bridenbrad\'s Tabard to Highlord Tirion Fordring at Crusaders\' Pinnacle.]', '', '去找冰冠冰川的大領主提里奧‧弗丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13084 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13084, 'zhTW', '[Vandalizing Jotunheim]', '[Let us see if we can further weaken the resolve of the vrykul, $N.$B$BEach day I wish you to travel to Jotunheim and put their banners to the torch. It may seem a trivial thing, but to see their ancestral home vandalized on a daily basis will demoralize them more than any physical punishment you can inflict.$B$BAt least... it can\'t hurt.]', '[Duke Lankral at The Shadow Vault wants you to burn 10 Vrykul Banners.]', '', '去找冰冠冰川的蘭克洛公爵。', '維库人旗幟已焚燒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13085 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13085, 'zhTW', '', '', '[Speak with Vaelen the Flayed at The Shadow Vault.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13086 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13086, 'zhTW', '[The Last Line Of Defense]', '[I\'ve triggered the base\'s defenses, $c! Atop each of the Vanguard\'s four towers is a retractable Argent Crusade cannon, blessed by Father Gustav himself. You\'ll need to fly up to one of those towers and man a cannon. Use it to destroy the Scourge onslaught that the Lich King has deployed.$B$BJust one warning, the Scourge will undoubtedly send their frost wyrms to lay siege to the towers. Shoot them out of the sky! If they destroy the walls and towers of this base, we\'re done for!]', '[Use an Argent Cannon to destroy 100 Scourge attackers. You must also kill 3 Frostbrood Destroyers.$B$BReturn to Siegemaster Fezzik should you succeed.]', '', '去找冰冠冰川的攻城大師費茲克。', '天災攻擊者已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13087 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13087, 'zhTW', '北方廚藝', '所以說你既然沒有我要的燉肉，你在這裡幹嘛。我肚子餓的要死!至少給我弄來一些冷肉，讓我自己煮燉肉吧!如果你幫我弄來肉的話，我就給你食譜讓你可以自己煮。現在快點去給我弄點肉來!', '把四塊冷肉塊交給瓦爾加德的布隆·塗酒。北裂境的任何野獸身上都能找到冷肉塊。', '', '去找嚎風峽灣的布隆·塗酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13088 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13088, 'zhTW', '北方廚藝', '這兒有好多的新兵，而且這些小子都餓壞啦!如果你能夠去外頭幫我弄點燉肉用的冷肉塊來，我可以教你怎麼做這道菜。', '把四塊冷肉塊交給驍勇要塞的羅利克·麥克里爾。北裂境的任何野獸身上都能取得冷肉塊。', '', '去找北風凍原的羅利克‧麥克里爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13089 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13089, 'zhTW', '[Northern Cooking]', '[Nothing like a stew made from the living to warm your bones.   Bring me some of the chilled meat that can be found on the wretched beasts of this place, and I shall teach you to make a warm stew.]', '[Bring four chilled meat to Thomas Kolichio at Vengeance Landing.   Chilled meat can be found on any Northrend beast.]', '', '去找嚎風峽灣的湯瑪士‧寇里奇歐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13090 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13090, 'zhTW', '[Northern Cooking]', '[The warriors of the Warsong Offensive need food in their bellies to keep their strength up.   If you could bring some chilled meats from the Rhinos or other beasts, I could make them some stew.   I would be willing to teach you the recipe if you were willing.]', '[Bring four chilled meat to Orn Tenderhoof at Warsong Hold.   Chilled meat can be found on any Northrend beast.]', '', '去找北風凍原的翁恩‧柔蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13091 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13091, 'zhTW', '[The Art of Being a Water Terror]', '[The water lock outside my cave is teeming with elementals that the vrykul magi have yet to tame. I am going to teach you a trick for possessing these creatures for a short time, and you will use them to wreak havoc upon Jotunheim!$B$B<The banshee-infested vrykul draws magic in the air and touches a large finger to your forehead.>$B$BGo now and open the gate to the lock. A water terror will rush out and you will possess it to destroy our enemies!]', '[The Bone Witch in Njorndar Village wants you to possess a Water Terror and use it to slay 10 vrykul in the greater Jotunheim region.$B$BQualifying vrykul are Jotunheim Sleep-Watchers, Jotunheim Warriors, Mjordin Water Magi, Njorndar Spear-Sisters, and Valhalas Vargul.]', '', '去找冰冠冰川的骸骨女巫。', '已附身水中恐懼並擊殺尤頓海姆維库人', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13092 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13092, 'zhTW', '[Reading the Bones]', '[One of the benefits of possessing this creature is that I have access to all of her powers. As a bone witch and rune reader, she has the power to throw the bones and determine one\'s fate.$B$B<The Bone Witch smirks.>$B$BLucky for you and I that I have it within my power to influence those readings.$B$BBring me the bones of the vrykul that you kill here in Jotunheim and I will toss them to allow you to determine your own fate.]', '[The Bone Witch in Njorndar Village has instructed you to collect 15 Vrykul Bones.]', '', '去找冰冠冰川的骸骨女巫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13093 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13093, 'zhTW', '[Reading the Bones]', '', '', '', '去找冰冠冰川的骸骨女巫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13094 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13094, 'zhTW', '[Have They No Shame?]', '[Archmage Berinand is the Kirin Tor\'s foremost authority on Malygos. He\'s spent his life studying the aspect and his behaviors.$B$BRecently, he loaned me his research on the Arcanomicron, some sort of map that Malygos is trying to assemble. I made the mistake of discussing it with a group of Horde adventurers while they were restocking their goods here - and now it\'s gone!$B$BIt must have been them, $c. Please, follow them into the nexus and recover the book before Berinand comes to recover it.]', '[Librarian Serrah wants you to enter the Nexus and recover Berinand\'s Research.]', '', '去找北風凍原的圖書管理員瑟菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13095 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13095, 'zhTW', '[Have They No Shame?]', '[Archmage Berinand is the Kirin Tor\'s foremost authority on Malygos. He\'s spent his life studying the aspect and his behaviors.$B$BRecently, he loaned me his research on the Arcanomicron, some sort of map that Malygos is trying to assemble. I made the mistake of discussing it with a group of Alliance adventurers while they were restocking their goods here - and now it\'s gone!$B$BIt must have been them, $c. Please, follow them into the nexus and find the book before Berinand comes to recover it from me.]', '[Librarian Serrah wants you to enter the Nexus and recover Berinand\'s Research.]', '', '去找北風凍原的圖書管理員瑟菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13096 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13096, 'zhTW', '[Gal\'darah Must Pay]', '[Did ya see it, mon?$B$BIt musta been da most awful thing I ever seen. Da great Akali - slain right before my eyes. Horrible...$B$BI done took an oath not ta be gettin\' involved here. My job be to observe only. But dis cannot stand! Gal\'darah must pay!$B$BGo into Gundrak and seek him out. Come back to me when Akali\'s death been avenged, mon.]', '[Tol\'mar at Dubra\'Jin wants you to slay Gal\'darah in Gundrak.]', '', '去找祖爾德拉克的托爾瑪。', '已擊殺加爾達拉', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13097 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13097, 'zhTW', '', '', '[Har\'koa wants you to speak with Tol\'mar at Dubra\'jin.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13098 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13098, 'zhTW', '為了後代子孫', '剛德拉克已經完了，老兄。$B$B歷史就在咱們眼前重演啦。當食人妖背叛了自己的神明時，就注定要面臨末日了。這只是時間的問題而已。$B$B如果我們能夠清楚的紀錄這些事件，也許就能避免後世子孫重蹈覆轍。$B$B如果你夠勇敢，就進入剛德拉克，找找有什麼線索可以告訴我們德拉克瑞帝國怎麼會走到今天這一步。', '杜布拉金的撰史者巴琪妮要你進入剛德拉克收集6個德拉克瑞歷史石板。', '', '去找祖爾德拉克的撰史者巴琪妮。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13099 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13099, 'zhTW', '探班', '有些可怕的聲音從剛德拉克裡頭傳出來，老兄。而且還越來越大聲，越來越頻繁。我的老學生待在剛德拉克西邊的哨站記錄事情。也許你能夠幫我去探個班?', '托基尼要你與杜布拉金的撰史者巴琪妮談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13100 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13100, 'zhTW', '[Infused Mushroom Meatloaf]', '[We have an important order that needs to go out!  Orton Bennet in Curiosities & Moore needs a mushroom meatloaf.$B$BGet some infused mushrooms found in the Dalaran sewers, chilled meat, and cook them in this meatloaf pan.  When you\'re done, deliver the cooked meatloaf to Orton.]', '[Use your Meatloaf Pan to cook 4 Infused Mushrooms and 2 Chilled Meats and bring the finished Mushroom Meatloaf to Orton Bennet in Curiosities & Moore, located in Runeweaver Square in Dalaran.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13101 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13101, 'zhTW', '[Convention at the Legerdemain]', '[Arille Azuregaze at the Legerdemain Lounge has a convention coming in and needs a feast pronto!$B$BYou need to provide some Northern Stew and a Jug of Wine from the cheese shop "One More Glass" in central Dalaran.  The owner of the cheese shop owes me the wine and you should find it somewhere around the shop.$B$BBring the wine and stews to Arille.]', '[Bring 4 Northern Stew that you use your cooking skill to make and a Jug of Wine from the cheese shop in Dalaran to Arille Azuregaze at the Legerdemain Lounge found in Runeweaver Square in Dalaran.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13102 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13102, 'zhTW', '[Sewer Stew]', '[Ajay Green the innkeeper in the Dalaran sewers needs a vegetable stew for his customers as they are running low on food down there.$B$BCollect 4 Crystalsong Carrots from the Crystalsong Forest and cook them together with 4 Chilled Meat.$B$B You can get to the Crystalsong Forest from the portal chamber in the eastern corner of Runeweaver Square.$B$BOnce the vegetable stew is ready, bring it to Ajay.]', '[Cook 4 Crystalsong Carrots from Crystalsong Forest with 4 Chilled Meat in the Cookpot.$B$BOnce it is ready bring the Vegetable Stew to the Dalaran sewers Innkeeper Ajay Green.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13103 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13103, 'zhTW', '[Cheese for Glowergold]', '[Ranid Glowergold in the Leatherworkers shop in Dalaran has had a sudden craving for wine and cheese.$B$BCollect cheese which is on the shelf at "One More Glass" in central Dalaran and half full wine glasses found on tables all over the city.  Pour the wine together into a bottle and serve it with the cheese to Ranid.$B$BWe don\'t think he will know the difference.]', '[Combine the empty cheese platter with Aged Dalaran Limburger from the cheese shop "One More Glass" and with 6 Half Full Dalaran Wine Glasses found on tables around Dalaran.$B$BBring the Wine and Cheese platter to Ranid Glowergold at the Leatherworkers in the Magus Commerce Exchange.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13104 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13104, 'zhTW', '', '', '[Report to the Ebon Watcher in the Valley of Echoes just outside the Breach.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13105 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13105, 'zhTW', '', '', '[Report to the Ebon Watcher in the Valley of Echoes just outside the Breach.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13106 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13106, 'zhTW', '', '', '[Speak to Darkrider Arly at Blackwatch in Icecrown.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13107 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13107, 'zhTW', '[Mustard Dogs!]', '[Archmage Pentarus likes to watch the occasional game of battle ball and is preparing to go, but needs food for the trip.$B$BYou need to fill his picnic basket with 4 rhino dogs that you cook and then 4 wild mustard that are found in grassy areas of the city.$B$BBring him his picnic basket so he can be ready to go see the big game.]', '[Fill the Empty Picnic Basket with 4 Rhino Dogs that you cook with your cooking skill and 4 Wild Mustard that you find in the grassy areas of Dalaran.$B$BBring the Picnic Basket to Archmage Pentarus at Krasus\' Landing in Dalaran.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13108 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13108, 'zhTW', '[Whatever it Takes!]', '[One way or another, Loken shall fall.$B$BIf I have to rip him limb from limb myself, he soon shall pay for his wretched deeds.$B$BShould you meet with him before I do, the honor and glory of his defeat shall be yours.$B$BReturn to me with his lying tongue, and earn my blessing and gratitude.]', '[King Jokkum in Dun Niffelem wants you to enter the Halls of Lightning and defeat Loken. You are then to return to King Jokkum with Loken\'s Tongue.]', '', '去找風暴峭壁的裘庫姆王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13109 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13109, 'zhTW', '[Diametrically Opposed]', '[I shall speak plainly to you, little $r. My people have not been the same since our ties with Thorim were severed.$B$BAs their leader, I wish nothing more than for their hearts to be mended and our friendship with the Stormlord to be renewed. In your defeat of Fjorn, a step has been taken down that path. I would have you bring us a step further...$B$BIn the Halls of Lightning, one even greater than Fjorn sits in opposition to our existence. Volkhan will not rest until either he, or we, are no more.]', '[King Jokkum at Dun Niffelem wants you to enter the Halls of Lightning and defeat Volkhan.]', '', '去找風暴峭壁的裘庫姆王。', '已擊敗沃爾坎', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13110 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13110, 'zhTW', '[The Restless Dead]', '[Not all of our soldiers made it out of Scourgeholme. Many were slain and turned into twisted reflections of their former selves. Such is the way of the Scourge. For those damned souls, there is no eternal peace. We must provide their souls rest.$B$BTravel through the Breach into Scourgeholme and slay the skeletal reanimated crusaders. Sprinkle this holy water on their bones so that their spirits may be freed.]', '[Father Gustav at the Valley of Echoes in Icecrown wants you to use Holy Water on the corpses of Reanimated Crusaders to free 10 restless souls.]', '', '去找冰冠冰川的賈斯塔夫神父。', '不安的靈魂已釋放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13111 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13111, 'zhTW', '獨一無二', '聽著，老兄。$B$B就第一眼而言，這看來不過就是另一個古老的故事－食人妖藉由毀滅他們原應敬仰的種族，獲得了禁忌的力量。$B$B如果這個傳說是真的，應該還有某些和德拉克瑞有關的有趣玩意殘留下來。如果我聽到的是真的，剛德拉克內應該有尊特別的魔像－一尊獨一無二的魔像!$B$B你想要一趟刺激的冒險嗎，老兄?幫我從剛德拉克帶回那魔像的一部分，好讓我研究研究。', '杜布拉金的撰史者巴琪妮要求你，進入剛德拉克，並撿回一塊德拉克瑞巨像的碎片。', '', '去找祖爾德拉克的撰史者巴琪妮。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13112 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13112, 'zhTW', '[Infused Mushroom Meatloaf]', '[Orton Bennet in Curiosities & Moore be needin\' a mushroom meatloaf.$B$BGet ya some infused mushrooms found in the Dalaran sewers, chilled meat, and cook \'em in the meatloaf pan.  When ye be done, bring that meatloaf to Orton.$B$BIf only de council would let me serve me gnome specialty, I would show dem a real treat!]', '[Use your Meatloaf Pan to cook 4 Infused Mushrooms and 2 Chilled Meats and bring the finished Mushroom Meatloaf to Orton Bennet in Curiosities & Moore, located in Runeweaver Square in Dalaran.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13113 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13113, 'zhTW', '[Convention at the Legerdemain]', '[Can you believe da horde has outlawed cannibalism...it just ain\'t right I tell ya!  I guess I should keep me mind on me work when we gots an order to fill.$B$BArille Azuregaze at the Legerdemain Lounge has many a guest a\'comin to his place, mon.  You gots to be providin\' some Northern Stew and a Jug of Wine from the cheese shop in central Dalaran.$B$BBring the wine and stew to Arille.]', '[Bring 4 Northern Stews and a Jug of Wine from the cheese shop in Dalaran to Arille Azuregaze at the Legerdemain Lounge found in Runeweaver Square in Dalaran.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13114 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13114, 'zhTW', '[Sewer Stew]', '[We be havin\' another order to fill.  Da innkeeper in da Dalaran sewers needs a vegetable stew as his customers dey don\'t have so much to eat, mon.$B$BHe asked for a vegetable stew as he didn\'t appreciate da gnome that was in the last stew I sent.  Get 4 Crystalsong Carrots from the Crystalsong Forest and cook them together with 4 Chilled Meat and bring it to Ajay.$B$BYou can be gettin\' to da Forest from da portal chamber in da eastern corner of Runeweaver Square. ]', '[Cook 4 Crystalsong Carrots from Crystalsong Forest with 4 Chilled Meat in the Cookpot.$B$BThen bring the Vegetable Stew to the Dalaran sewers Innkeeper Ajay Green.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13115 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13115, 'zhTW', '[Cheese for Glowergold]', '[Ranid Glowergold in da Leatherworkers shop be havin\' a need for wine and cheese.  Why he don\'t want some tasty gnome is beyond me.$B$BCollect da cheese from da cheese shop in central Dalaran and da half full wine glasses found on tables around da city.  Bring da wine and serve it with the cheese to Ranid.$B$BYou can call da wine a Wine Medley, mon\'.]', '[Combine the empty cheese platter with Aged Dalaran Limburger from the cheese shop "One More Glass" and with 6 Half Full Dalaran Wine Glasses found on tables around Dalaran.$B$BBring the Wine and Cheese platter to Ranid Glowergold at the Leatherworkers in the Magus Commerce Exchange.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13116 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13116, 'zhTW', '[Mustard Dogs!]', '[Da Archmage Pentarus likes to be watchin\' his crazy battle ball game, but he be needin\' some food for da game.$B$BYou be needin\' to fill his picnic basket with 4 cooked rhino dogs and then 4 wild mustard that are found in da grassy corners of de city.$B$BFill up his basket with the mustard dog goodies, mon\'.]', '[Fill the Empty Picnic Basket with 4 Rhino Dogs that you be cookin\' with your skill and 4 Wild Mustard that you find in the grassy areas of Dalaran.$B$BBring the Picnic Basket to Archmage Pentarus at Krasus\' Landing in Dalaran.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13117 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13117, 'zhTW', '[Where Are They Coming From?]', '[The Lich King\'s tireless minions labor away night and day to assemble scores of abominations and flesh giants down there in the Fleshwerks.$B$BYet, that is not enough. More and more skeletal constructors keep appearing to increase the pace of work.$B$BIf we do not discover where they\'re coming from and how they\'re able to work so quickly, we\'ll be overrun before we can act in force. Search to the southeast and see if you can find the source of these skeletons.]', '[Investigate a Summoning Altar in the eastern part of the Fleshwerks, then report back to Darkrider Arly at Blackwatch.]', '', '去找冰冠冰川的黑騎兵亞爾利。', '已調查召喚祭壇', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13118 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13118, 'zhTW', '[The Purging Of Scourgeholme]', '[The Scourge have sent their armies at the Argent Crusade and have been repelled. What they do now is called a \'slash and burn.\' All prisoners that they hold at Scourgeholme will be executed and raised as servants of the Lich King.$B$BUndoubtedly the Argent Crusade will request that you give their soldiers a proper farewell. I\'ll ask no such thing of you. To succeed we must kill Scourge indiscriminately.$B$BVenture to Scourgeholme, northwest through the Breach, and lay waste to all that stand in your way.]', '[The Ebon Watcher at the Valley of Echoes in Icecrown wants you to kill 3 Forgotten Depths High Priests, 3 Forgotten Depths Underkings, and 8 Reanimated Crusaders.]', '', '去找冰冠冰川的黯黑看守者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13119 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13119, 'zhTW', '[Destroying the Altars]', '[So they\'re summoning in their workers and warriors at those altars?$B$BThey\'ll need to be the first thing to go. The master summoner should have a staff which allows him to activate the portal. If you kill the master summoner and take the staff, you can use it to overload the summoning portal and destroy its altar.$B$BDo this at all four of the altars and return to me once they\'ve been destroyed.]', '[Kill Master Summoner Zarod and use his Summoning Stave to destroy the First, Second, Third, and Fourth Summoning Altars. When you\'ve completed this task, report to Darkrider Arly at Blackwatch.]', '', '去找冰冠冰川的黑騎兵亞爾利。', '第一座召喚祭壇已摧毀', '第二座召喚祭壇已摧毀', '第三座召喚祭壇已摧毀', '第四座召喚祭壇已摧毀', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13120 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13120, 'zhTW', '[Death\'s Gaze]', '[The Fleshwerks is a vast operation, and it will be difficult to keep an eye on all that transpires there. Fortunately, I have a plan.$B$B<Arly produces an orb from the folds of her cloak and shows it to you.>$B$BThis is a death\'s gaze orb. With it, we can observe the Scourge\'s actions and decide how best to strike.$B$BPlace these orbs on the stands at three crucial areas -- the abomination lab and the flesh giant lab to the southwest, along with the area surrounding the green cauldron far to the west.]', '[Use the Death\'s Gaze Orb to place orbs on the Abomination Lab Orb Stand, the Flesh Giant Lab Orb Stand, and the Cauldron Area Orb Stand, then return to Darkrider Arly at Blackwatch.]', '', '去找冰冠冰川的黑騎兵亞爾利。', '法球已放置於憎惡實驗室', '法球已放置於血肉巨人實驗室', '法球已放置於坩堝區域', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13121 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13121, 'zhTW', '[Through the Eye]', '[We must use the Lich King\'s tools against him if we are to decide our next step.$B$BOver the mountain to the southwest lies Kul\'galar Keep. Within it reside the oracles of Jotunheim who receive orders from their master and scry upon others through the Eye of the Lich King.$B$BIt is the eye that you must fight your way to. While it cannot be used to pierce the veil within Icecrown Citadel, you should be able to use it to discern something of value so that we will know how best to proceed.]', '[The Bone Witch in Njorndar Village has tasked you with using the Eye of the Lich King to gain information.]', '', '去找冰冠冰川的骸骨女巫。', '已為骸骨女巫取得情報', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13122 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13122, 'zhTW', '[The Scourgestone]', '[A Scourgestone is an item given to all Scourge upon birth or creation. It provides certain benefits to the holder, but more importantly it allows Scourge leaders visibility into the location and movement of all of their units.$B$BWith enough Scourgestones, I might be able to track the movement of other Scourge units across Icecrown.$B$BAs you slaughter Scourge in Scourgeholme, gather all of the Scourgestones that you find. Return to me when your bags are full.]', '[The Ebon Watcher at the Valley of Echoes in Icecrown wants you to bring him 15 Scourgestones.]', '', '去找冰冠冰川的黯黑看守者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13123 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13123,'zhTW','巫妖王之怒典藏版: -DEM -E -FLAG','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13124 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13124, 'zhTW', '負隅頑抗', '戰鬥一直在持續進行，$n。我們設法避過了瑪里苟斯的偵測，繼續設法破壞他的陰謀。但好消息就到此為止了。我們的努力幾乎沒有產生任何效果。瑪里苟斯與他的手下日益壯大。現在連我們最後一支突襲隊都被俘虜關在奧核之眼中。我們一定得設法救援他們!貝加瑞斯塔茲與他的夥伴對我們來說非常重要。我們能夠倚重你嗎，$n?', '瑞洛拉茲要你進入奧核之眼並解救貝加瑞斯塔茲與他的同伴。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13125 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13125, 'zhTW', '[The Air Stands Still]', '[You must defeat the lords of Scourgeholme if this place is to be free of the Scourge\'s grasp.$B$BSalranax the Flesh Render lords over the temple on the first tier of Scourgeholme. Nearby Salranax you\'ll find High Priest Yath\'amon preaching at the spirit tower on the second tier. Underking Talonox holds court at the Pit of Fiends, up the high road.$B$BThese are formidable opponents and must be approached with caution. Use this war horn should you require aid. The death knights of Acherus will come.]', '[The Ebon Watcher at the Valley of Echoes in Icecrown wants you to kill Salranax the Flesh Render, Underking Talonox and High Priest Yath\'amon.]', '', '去找冰冠冰川的黯黑看守者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13126 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13126, 'zhTW', '[A Unified Front]', '[Please accept our gratitude, $r.$B$BYou and your friends have succeeded where we had failed - you have bested Drakos. From here, however, it will take our combined efforts to proceed.$B$BAbove us, Varos hides behind an impenetrable shield. To reach him, you must defeat the Centrifuge Constructs that power his shield. That is where my friends and I come in....$B$BWe each can provide you with drakes from our respective flights. Only with the help of these drakes will you be able to expose Varos.]', '[Belgaristrasz wants you to destroy 10 Centrifuge Constructs to bring down Varos\' shield. You then must defeat Varos Cloudstrider.]', '', '', '離心構造體已摧毀', '已擊敗瓦羅斯·逐雲者', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13127 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13127, 'zhTW', '[Mage-Lord Urom]', '[Only one obstacle stands between us and our ultimate goal here, $c. His name is Urom.$B$BAbove us, guarding the third ring, he awaits us. Beware his powerful conjurings, friend. He is a frightful opponent, certain to challenge your prowess.$B$BBring him down. Make him pay for his treacherous allegiance to the enemy!]', '[Belgaristrasz wants you to defeat Mage-Lord Urom in the Oculus.]', '', '', '已擊敗法師領主烏羅姆', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13128 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13128, 'zhTW', '[A Wing and a Prayer]', '[The time has come to face Eregos, friend.$B$BHe is cunning and strong. One of Malygos\' most trusted minions, he draws strength from the energies he is charged with defending - sipping from the well of the great aspect himself.$B$BThis shall not be easy....$B$BHowever, defeating the Mage-Lord has allowed us to unlock the full power of our drakes. Their skills shall be at your command. Use them wisely and Eregos shall surely fall.$B$BShould you succeed, return to Raelorasz and inform him of our victory.]', '[Belgaristrasz wants you to kill Eregos in the Oculus and then report to Raelorasz at the Transitus Shield in Coldarra.]', '', '去找北風凍原的瑞洛拉茲。', '已擊敗魔網守護者埃雷格斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13129 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13129, 'zhTW', '[Head Games]', '[Too lazy for their own good.... Wait! I know how to teach \'em!$B$B<Kurzel rips a long strip of material from her blouse and hands it to you.>$B$BHere, $r, take this. Dip it in the remains of that annoying lich over there and return it to Mack back at the camp.$B$BOnce the boys have stewed in their guilt for a while I\'ll show up and let them off the hook.$B$BThey\'ll learn not to let a lady wander off alone!]', '[Kurzel wants you to use Kurzel\'s Blouse Scrap at the corpse of Novos the Summoner, then take the Ichor-Stained Cloth to Mack.]', '', '去找灰熊丘陵的麥客‧菲爾森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13130 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13130, 'zhTW', '[The Stone That Started A Revolution]', '[You may look at Scourgeholme now and see a rancid pit of decay, but one day it will be a place of glory and honor. Highlord Fordring has deemed it "Justice Keep."$B$BAlas, even an impregnable fortress like Icecrown Citadel began with but a single stone. So begins our search for the stone to start a revolution.$B$BTravel to Crystalsong, south of here, and seek out the Unbound Thicket in the east. Once there gather crystalline heartwood from the thicket floor and elven masonry from the Ruins of Shandaral.]', '[Crusade Architect Silas at the Valley of Echoes in Icecrown wants you to retrieve 10 Trunks of Crystalline Heartwood and 10 pieces of Ancient Elven Masonry.]', '', '去找冰冠冰川的十字軍建築師席拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13131 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13131, 'zhTW', '我箱子裡的垃圾', '看看這個!我的箱子從未如此空虛。它應該裝著比現在多十倍的寶物!$B$B我的同伴妄想獨吞所有的戰利品，現在瞧他們怎麼了!一堆白骨，就是這樣的下場!$B$B就像我老媽告訴我的 - 唯一比沒有財寶還糟糕的事，就是受詛咒的財寶。$B$B聽著，遠方有一大票財寶，而且我敢打包票，不是受詛咒的那種。那些小王八蛋根本不需要它 - 對他們而言不過是垃圾罷了。$B$B幫我弄回來，我會分你一些油水的，小子。', '俄特加德之巔的布瑞格要求你，找到5個失去光澤的銀錠、3顆閃光的小珠、2只黃金高腳杯以及1尊碧玉雕像。', '', '去找烏特加德之巔的布瑞格·細柄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13132 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13132, 'zhTW', '我將復仇!', '呃!不能責怪他們，<小夥子/小姑娘>。誰不是這樣呢?$B$B他們將自己丟進了成堆的黃金當中 - 以為他們挖到了主礦脈，他們的確是。唉...但現在看看他們。喪失心智的奴隸，連一枚金幣都無法拾起。$B$B唯有幸運的我，免去了相同的命運。逃跑的途中，我被擊倒了 － 實在是不怎麼好的起步。一抬頭，看到他們其中一人率先轉身...$B$B做個好<孩子/女孩>，找到負責這裡的傢伙，教訓教訓他，教他別再欺壓我的夥伴。', '俄特加德之巔的布瑞格要求你，殺掉依米倫王。', '', '去找烏特加德之巔的布瑞格·細柄。', '殺死依米倫王', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13133 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13133, 'zhTW', '[Find the Ancient Hero]', '[Quickly, $N, head southwest to the Halls of the Ancestors!$B$BWithin you will find slumbering mjordin. Wake them until you find Iskalder. When you do, use this amulet upon him and bring him back to me.$B$BNow go. There is no time to waste!]', '[The Bone Witch at Njorndar Village wants you to return with Iskalder.]', '', '去找冰冠冰川的骸骨女巫。', '伊斯卡德已交給骸骨女巫', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13134 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13134, 'zhTW', '[Spill Their Blood]', '[The Scourge cannot create their flesh monsters without blood and embalming fluid to preserve the parts and keep them functioning. If we can deny them these materials, their army will fall apart and we can easily destroy their creations.$B$BThroughout the labs where the flesh giants and abominations are cobbled together, you will find vats of embalming fluid and large orbs filled with blood. Destroy these, and bring death to any who would stop you!]', '[Darkrider Arly at Blackwatch wants you to destroy 5 vats of Embalming Fluid and 5 Blood Orbs.]', '', '去找冰冠冰川的黑騎兵亞爾利。', '血珠已擊碎', '防腐液桶已摧毀', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13135 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13135, 'zhTW', '[It Could Kill Us All]', '[Southeast of here, at the eastern reaches of Crystalsong Forest, is an area known as the Unbound Thicket. Within that thicket creeps all manner of life. One thing all of the affected creatures of the thicket share in common is their affinity for magical energy. Each of them holds pure, crystallized energy. Enough to kill us all should it ever destabilize!$B$BTravel to the Unbound Thicket and kill its denizens for crystallized energy. We need fuel and they need to die. We call that a "win-win."]', '[Crusade Engineer Spitzpatrick at the Valley of Echoes in Icecrown wants you to retrieve 8 pieces of Crystallized Energy.]', '', '去找冰冠冰川的十字軍工程師史匹派崔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13136 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13136, 'zhTW', '[Jagged Shards]', '[You pulled this jagged, dark brittle shard from the body of a ghoul. The metal blade lacks a smooth edge, suggesting it was forged by an unskilled hand, or was broken from a larger piece.$B$BYou recall seeing similar shards embedded in the bodies of all the ghouls you\'ve encountered at the Fleshwerks, leading you to wonder why their creators bothered to include the metal at all. Perhaps Crusader Olakin Sainrith would have some insight if you brought him the shards from several ghouls.]', '[Bring 10 Jagged Shards to Crusader Olakin Sainrith at Blackwatch.]', '', '去找冰冠冰川的十字軍歐拉金·山瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13137 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13137, 'zhTW', '[Not-So-Honorable Combat]', '[Atop the tallest peak to the southwest overlooking Jotunheim is Battlescar Spire. It is a place of reverence for the vrykul, second only to Valhalas in terms of where they prefer to do honorable combat.$B$BWe shall visit not-so-honorable combat upon it.$B$BGather your companions and fly to the spire. When you are ready, light the signal fire and I will appear within the body of Iskalder.$B$BWe will fight, you will win, and Vardmadra is sure to come to witness the battle!]', '[The Bone Witch in Njorndar Village wants you to defeat Iskalder upon Battlescar Spire.]', '', '去找冰冠冰川的骸骨女巫。', '已在戰鬥中擊敗伊斯卡德', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13138 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13138, 'zhTW', '[I\'m Smelting... Smelting!]', '[<Olakin turns one of the shards over in an armored fist.>$B$BThese could pierce armor with enough force. We have to find out what they\'re made of and what the Lich King intends to do with them.$B$BTo the east, nestled next to Icecrown Citadel itself, lies Malykriss. From the few reports we have, it\'s full of smelting and smithing equipment. Bring these shards there, and smelt them in one of the open furnaces on the bottom level of Malykriss. Once the metal has been reformed, we can identify it.]', '[Use the Bag of Jagged Shards near one of the bottom level Malykriss furnaces. Return to Crusader Olakin Sainrith at Blackwatch with the Smelted Metal Bar.]', '', '去找冰冠冰川的十字軍歐拉金·山瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13139 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13139, 'zhTW', '[Into The Frozen Heart Of Northrend]', '[Silas and Spitzpatrick have signed off on the materials and fuel needed to begin construction of Justice Keep. Thanks to you and the Ebon Blade the Scourge presence within Scourgeholme has been decimated and their lieutenants have been defeated.$B$BI have chosen the site at which we will break ground, but first you must deliver my report to Highlord Tirion Fordring. We will begin our march into Icecrown on his command.$B$B]', '[Deliver Father Gustav\'s Report to Highlord Tirion Fordring at the Argent Vanguard in Icecrown.$B$B]', '', '去找冰冠冰川的大領主提里奧‧弗丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13140 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13140, 'zhTW', '[The Runesmiths of Malykriss]', '[Those shards you recovered can only have come from one place, Malykriss. It\'s the seat of the Lich King\'s metalworking operations, to the east of Corp\'rethar.$B$BWhat\'s puzzling is that metal isn\'t needed to stitch together abominations or flesh giants, or to summon skeletal servants. Find the skeletal runesmiths working on the bottom level of Malykriss and capture the plates they\'re working on. We need to find out why this metal is finding its way to the Fleshwerks.]', '[Bring 5 Runed Saronite Plates to Crusader Olakin Sainrith at Blackwatch.]', '', '去找冰冠冰川的十字軍歐拉金·山瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13141 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13141, 'zhTW', '[The Battle For Crusaders\' Pinnacle]', '[<Highlord Fordring holds a banner of the Argent Crusade.>$B$BThis banner is like no other, $N. It carries with it a powerful blessing, able to sanctify large tracts of blighted land.$B$BYou must take it northwest, through the Breach, to an area the Scourge have mockingly named Crusaders\' Pinnacle. Plant the banner atop the skulls of our fallen brethren at Crusaders\' Pinnacle and defend it against attack. Once the land is sanctified, return to Father Gustav.$B$BGo now, $N. Hold no fear in your heart.]', '[Venture to Crusaders\' Pinnacle and use the Blessed Banner of the Crusade atop the Pile of Crusader Skulls. Defend the banner against Scourge attack until the land atop the pinnacle is sanctified and then return to Father Gustav at the Valley of Echoes in Icecrown.]', '十字軍之巔的戰役', '去找冰冠冰川的賈斯塔夫神父。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13142 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13142, 'zhTW', '[Banshee\'s Revenge]', '[The time has come, $N. You and your friends must challenge the lord of Balargarde Fortress, the master of Jotunheim, Overthane Balargarde.$B$BAtop the fortress, which is on the southwestern edge of Jotunheim, you will find a horn. Blow into it. Allow your challenge to resound throughout the steadfast.$B$BBalargarde will have no choice but to face you. And I... excuse me, Vardmadra will be there to adjudicate the challenge.$B$B<The banshee-possessed vrykul lets out a bellowing cackle.>]', '[The Bone Witch at Njorndar Village has asked you to exact her revenge by challenging and defeating Overthane Balargarde.]', '', '去找冰冠冰川的骸骨女巫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13143 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13143, 'zhTW', '[New Recruit]', '[First things first. I saw some Lithe Stalkers on the ramparts just east of us. They used to serve us before we broke with Arthas, and they\'re about as perfect a scout as you can get... with a little prodding from an eye of dominion.$B$BFly up, find one of the stalkers, beat it down a bit, and then use this Sigil of the Ebon Blade to command its obedience. It will recognize the sigil, guaranteed. Lead it back to the top of the rocks northeast of here and it will find its way to me.]', '[Vereth the Cunning on the Rise of Suffering has requested that you bring a subdued Lithe Stalker to the top of the rocks northeast of the Rise of Suffering.]', '', '去找冰冠冰川的奸詐的維瑞希。', '已制伏並歸還敏捷潛行者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13144 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13144, 'zhTW', '[Killing Two Scourge With One Skeleton]', '[The workers in the Fleshwerks abomination lab have already completed a number of their creations. For now, the creatures are chained to the pillars around the edge of the lab, but if we do not act, they will march with the Lich King\'s armies.$B$BGrasping arms reach out of the bone piles spread throughout the Fleshwerks. These arms belong to skeletons enchanted with the power of fire. Find and free these skeletons, then take them near the completed abominations and watch the show!]', '[Darkrider Arly at Blackwatch wants you to destroy 3 Chained Abominations with Burning Skeletons.]', '', '去找冰冠冰川的黑騎兵亞爾利。', '鎖鏈憎惡已焚燒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13145 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13145, 'zhTW', '[The Vile Hold]', '[We need to know what we\'re up against.$B$BUse the eye of dominion to assume control of a lithe stalker and scout out the area. There are a few spots in particular I saw when flying in that I want you to get a closer look at: the overlook in the northeast, the work area in the southeast, the large forge near the center, and the ritual area in the southwest.$B$BThe stalker can leap far and won\'t be hurt by large falls - use that to your advantage to get up and down from those ramparts.]', '[Vereth the Cunning at the Rise of Suffering has requested that you use a Lithe Stalker to scout out Malykriss.]', '', '去找冰冠冰川的奸詐的維瑞希。', '已探索獻祭祭壇', '已探索熔血鍛爐', '已探索冰封瞭望台', '已探索符文工坊', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13146 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13146, 'zhTW', '[Generosity Abounds]', '[We need to cause some disruption... anything to bring those death knights away from their leaders. If we lay waste to their minions below, I suspect they\'ll have to devote more attention to keeping a close eye on operations.$B$BAbominations are easy prey - slow, predictable, and most importantly, stupid. Take advantage of their trust of the stalkers to drag them some of the Scourge bombs scattered throughout the construction area. You\'ll be able light the bombs far before they figure out what\'s going on.]', '[Vereth the Cunning wants you to use the Lithe Stalker\'s Iron Chain to drag Scourge Bombs to 4 Lumbering Atrocities inside Malykriss.]', '', '去找冰冠冰川的奸詐的維瑞希。', '天災炸彈禮物已送達', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13147 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13147, 'zhTW', '[Matchmaker]', '[The major difference between vargul and lesser undead minions is that vargul still possess enough of their minds to despise being used for labor. Never will a vargul be pleased to be working aside skeletons or ghouls.$B$BLets take advantage of this inevitable animosity and start some fights between the umbral brutes and the other undead in Malykriss. That should serve to slow production and bring the death knights down to babysit.$B$BShould be simple - throw rocks at the brutes as they near lesser undead.]', '[Vereth the Cunning at the Rise of Suffering wants you to use a Lithe Stalker to throw rocks at Umbral Brutes as they near lesser undead in Malykriss. Return after you\'ve started 5 fights.]', '', '去找冰冠冰川的奸詐的維瑞希。', '工人打鬥已開始', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13148 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13148, 'zhTW', '[Necklace Repair]', '[This damaged necklace has an invoice with it that reads "Property of Timothy Jones - Cartier and Co Fine Jewelry - Magus Commerce Exhange - Dalaran".$B$BPerhaps you should repair it and return it to him.$B$B]', '[Repair the necklace with a single Chalcedony and return it to Timothy Jones in at the Jewelcrafters Shop in the Magus Commerce Exchange in Dalaran.]', '', '去找達拉然的提摩西·瓊斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13149 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13149, 'zhTW', '驅散幻影', '總是來搗亂…$B$B恆龍軍團似乎藉由欺騙阿薩斯王子來擾亂歷史。$B$B如果他們說服他相信所有的穀物都沒有受到瘟疫感染，那麼他將不會做出肅清斯坦索姆的關鍵決定。$B$B這絕對不能發生。$B$B對任何可疑的箱裝穀物使用秘法干擾器，揭露它們的真面目。工作完成以後，和我在斯坦索姆的入口會合，在此處北方。', '克羅米要求你，在斯坦索姆的往日，對可疑的箱子使用秘法干擾器，然後在其入口附近和她交談。', '', '去找斯坦索姆的清剿的克羅米。', '驅散染疫的穀箱', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13150 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13150,'zhTW','ZZOLD失落:小飾物','“在飾物的底部有張發票，標示著在達拉然的‘提摩西·瓊斯 - 珠寶店名，區名’。或許，若你能修好它並物歸原主，他會給你一些回報。”','修好這個玩意，並歸還給達拉然珠寶工藝店的提摩西·瓊斯。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13151 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13151, 'zhTW', '[A Royal Escort]', '[The Infinite Dragonflight are not likely to give up so easily. I cannot be certain of what they\'re up to, but something tells me we haven\'t seen the last of them today.$B$BIn just a moment, Arthas will face a desperate dilemma, and make a momentous decision.$B$BDon\'t lose focus now, $n. I needn\'t remind you how much is at stake. I must call upon you to accompany the prince in his culling of Stratholme.$B$BArthas must make it through Stratholme alive and you must see to it that he defeats Mal\'Ganis!]', '[Chromie has asked you to accompany Arthas in the Culling of Stratholme. You are to speak with her again after Mal\'Ganis is defeated.]', '', '去找斯坦索姆的清剿的克羅米。', '已擊敗瑪爾加尼斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13152 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13152, 'zhTW', '[A Visit to the Doctor]', '[So they\'ve been embedding these ghouls with broken shards of saronite down in the Sanctum of Reanimation? We must put a stop to this, before these ghouls can be deployed against our troops.$B$BFind the entrance to the Sanctum of Reanimation in the flesh giant lab area of the Fleshwerks. There, the ghoul mastermind, Doctor Sabnok, keeps the most fearsome of his creations, Patches. Free Patches from his chains and help him take his revenge on the doctor. Let his own creation be his undoing.]', '[Darkrider Arly at Blackwatch wants you to destroy the Metal Stake imprisoning Patches in the Sanctum of Reanimation and help him get his revenge on Doctor Sabnok.]', '', '去找冰冠冰川的黑騎兵亞爾利。', '帕奇已釋放', '幫助帕奇殺死薩布諾克博士', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13153 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13153, 'zhTW', '[Warding the Warriors]', '[$n, good to see you. While the battle has subsided for now, we must hurry and replenish our stocks. My research indicates that the armor of soldiers recently slain in the Glacial Falls becomes imbued with an incredible amount of energy. The Horde has been seen collecting armor in the area.$B$BHead to the Glacial Falls and slay any of the Horde you find there. Return their imbued armor to me.$B$BIf you cannot find any of the Horde, you might find the armor of an adventurer slain by the elementals.]', '[Sorceress Kaylana at Wintergrasp Fortress wants you to retrieve 10 sets of Imbued Horde Armor from Horde players at the Glacial Falls.]', '', '去找冬握堡壘的巫女凱拉娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13154 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13154, 'zhTW', '[Bones and Arrows]', '[Dragons are incredible! Well, their bones at least! I\'ve been equipping our archers with arrowheads made of Dragonbone. Unfortunately, since the massacre at Angrathar, it has become almost impossible to get bone from Dragonblight.$B$BHowever, the Forest of Shadows on the western edge of Wintergrasp has enough bones to tide us over.$B$BHead to the Forest of Shadows and bring back any bone splinters you can find!$B$BThe Horde have been seen collecting bone splinters in the area. Slay them!]', '[Bowyer Randolph at Wintergrasp Fortress wants you to retrieve 10 Quivers of Dragonbone Arrows from Horde players at the Forest of Shadows.]', '', '去找冬握堡壘的弓箭商藍道夫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13155 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13155, 'zhTW', '', '', '[Report to Vereth the Cunning on the Rise of Suffering in Icecrown.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13156 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13156, 'zhTW', '[A Rare Herb]', '[My, it its quite chilly up here! Reminds me of the stormy peaks of Kaarinos on Argus. However, with all of this snow and ice, our soldiers can easily catch cold.$B$BHead to the Steppe of Life in southwestern Wintergrasp, and bring me back 10 of the Horde herb pouches you find. I will grind them into a medicine to help protect against the cold.$B$BThe Horde have been seen collecting them from the plant life in the area. Do not hesitate to slay them and retrieve the herbs!]', '[Anchorite Tessa in Wintergrasp Fortress wants you to retrieve 10 Horde Herb Pouches from Horde players in the Steppe of Life.]', '', '去找冬握堡壘的隱士泰莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13157 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13157, 'zhTW', '', '', '[Seek out Highlord Tirion Fordring at Crusaders\' Pinnacle in Icecrown.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13158 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13158, 'zhTW', '謹慎是關鍵', '聽我說，$r。不久前，紫羅蘭堡的一件意外引起了我的注意。看來藍龍即將對達拉然發動全面的入侵!我要你馬上前往監獄，並與守望者艾圖拉斯交談。他會告訴你詳情。不只這樣，我需要做到滴水不漏的地步。我們應該儘可能地不要驚動達拉然市民。我的指示夠清楚嗎?很好，現在去吧!', '羅甯要你前往達拉然的紫羅蘭堡，並與守望者艾圖拉斯交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13159 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13159, 'zhTW', '牽制', '這是監獄的鑰匙。$B$B我和我的人馬會待在這裡，萬一你無法壓制攻勢，我們將是最後一道防線。$B$B記得和辛克拉麗中尉交談。她會讓你進入監獄的防線。$B$B快點，$r。沒有時間了。若沒有你的協助，我留在裡面的人馬撐不了多久的。記得向我回報，一旦入侵的勢力成功地被壓制。', '守望者艾圖拉斯要你進入紫羅蘭堡，並擊退藍龍的攻勢。一旦霞妮苟莎被殺害，向艾圖拉斯回報。', '', '去找達拉然的守望者艾圖拉斯。', '殺害霞妮苟莎', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13160 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13160, 'zhTW', '[Stunning View]', '[Gargoyles make effective scouts and can be deadly if left to rain attacks from the air, but they have a very obvious weakness. Most of them have to go through long periods resting as stone to maintain the energy they need to carry their heavy bodies through the air.$B$BAs I peered through the eye you were using, I noticed dozens of iceskin sentries resting on the eastern and southern walls inside. Use the stalker to leap up to their ledges and devastate them while they sleep.]', '[Vereth the Cunning at the Rise of Suffering wants you to use a Lithe Stalker\'s heave ability to destroy 12 sleeping Iceskin Sentries.]', '', '去找冰冠冰川的奸詐的維瑞希。', '冰膚哨兵已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13161 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13161, 'zhTW', '穢邪騎士', '是時候斬除他們的首腦了。$B$B我曾經在洛基爾身邊待過好一陣子。他的穢邪技巧比我認識的每一個死亡騎士都好，他也同樣地殘忍無情。$B$B當洛基爾在自己的地盤上戰鬥時，他的力量最為強大。很不幸地，我們別無選擇也無法顧慮那麼多，你只能靠自己了，盡量避免和他的不死爪牙交鋒，然後竭盡全力取得勝利。$B$B敏捷靈活是關鍵，$c，還有切莫低估他。', '苦難高崗上奸詐的維瑞希要你殺死穢邪騎士洛基爾。', '', '去找冰冠冰川的奸詐的維瑞希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13162 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13162, 'zhTW', '冰霜騎士', '莎菲…莎菲是個不太一樣的死亡騎士。她會讓你沉浸於甜言蜜語之中，你在她身上嗅不出一絲邪惡的氣息。趁你鬆懈之時，她就會出奇不意地作掉你，臉上甚至還帶著笑容。$B$B我相信你能擊敗莎菲，但別過分自信。她的長處，就是令她的敵人錯估形勢，處於致命的懈怠中，然後以漫天蓋地的冰霜攻擊粉碎對手。$B$B別放鬆你的戒心，也別小看她。', '苦難高崗上奸詐的維瑞希要你殺死冰霜騎士莎菲。', '', '去找冰冠冰川的奸詐的維瑞希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13163 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13163, 'zhTW', '血魄騎士', '貝洛克是我所見過中極少數可以成為死亡騎士的維酷人之一，這多半要歸功於他的殘忍嗜血。若你能夠擊敗他，就算是替我們除去了一個心腹大患。$B$B和他戰鬥時，盡量和你的同伴保持距離。他會抽取你的生命能量為其所用，所以你必須儘可能地阻撓他使用這項技能。$B$B我對你有信心。你要確定他的死亡。', '苦難高崗上奸詐的維瑞希要你殺死血魄騎士貝洛克。', '', '去找冰冠冰川的奸詐的維瑞希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13164 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13164, 'zhTW', '血禍的命運', '隨著苦難大軍的騎士不斷死去，現在正是除去其領袖 - 歐貝茲·血禍的大好時刻。$B$B莫格萊尼在你出任務時來找過我，他告訴我歐貝茲的藏匿處。就在冰冠城塞正下方有個很大的深穴 - 你可以在其門外找到歐貝茲。$B$B我們已派遣一些黯刃騎士的菁英前往 - 集結夥伴並投入戰鬥吧。血禍的死期到了。', '苦難高崗上奸詐的維瑞希派遣你去殺死歐貝茲·血禍。', '', '去找冰冠冰川的奸詐的維瑞希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13165 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13165, 'zhTW', '', '', '[Use your Death Gate spell to return to Acherus: The Ebon Hold. Report to Highlord Darion Mograine once you arrive.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13166 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13166, 'zhTW', '[The Battle For The Ebon Hold]', '[The Hall of Command has been secured, but the Lich King has left us a little present in the Heart of Acherus. The stitched terror, Patchwerk, and a horde of abominations have taken over the second floor.$B$BUse the teleporter to get to the second floor and destroy the Scourge forces that remain. Do not engage Patchwerk alone! You must fight the monstrosity with other death knights of Acherus!$B$BGo, $N. You have my strength to carry you!]', '[Slay 10 Scourge and help kill Patchwerk. Return to Highlord Darion Mograine should you succeed.]', '', '去找黑鴉堡壘的大領主達瑞安‧莫格萊尼。', '', '縫補者', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13167 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13167, 'zhTW', '狙殺逆王', '逆王阿努巴拉克，以阿茲歐-奈幽，這個一度光榮輝煌的地底王國作為根據地。$B$B自他叛變以來，他已使我們的家鄉墮落成卑鄙污穢之地。他統率著一支不死奈幽蟲族的軍隊，如同其領導者，也都出賣了靈魂來服侍巫妖王。$B$B為逆王的統治畫下一個句點吧，$c。這對我們雙方的子民都好。$B$B若你能夠達成過往眾人所辦不到的事，就將阿努巴拉克的軀殼帶來見我。', '那金之淵裡的『排除者』齊力克斯交付給你一個任務，要你擊敗阿茲歐-奈幽的阿努巴拉克。然後將阿努巴拉克的裂殼帶回給齊力克斯。', '', '去找龍骨荒野的『排除者』齊力克斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13168 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13168, 'zhTW', '[Parting Gifts]', '[Look what we have here... eyes of dominion. The Cult normally goes to great lengths to keep these things safe, but I suppose their options for retreat are few when we\'re slaughtering them in their own home.$B$BThe eyes allow a being of any relative power to control an undead minion\'s actions precisely. As you can imagine, this can be extremely useful when it comes to your typical clumsy ghoul or skeleton.$B$BCare to try your hand at it? Use one of the eyes to control a captured shade.]', '[Keritose Bloodblade at the Shadow Vault wants you to use an Eye of Dominion to take control of a captured Eidolon Watcher.]', '奪取幻影守衛的控制權', '去找冰冠冰川的凱力多斯·血刃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13169 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13169, 'zhTW', '[An Undead\'s Best Friend]', '[As is usual practice, the undead at the saronite quarry to the southwest starve plaguehounds to keep them extra aggressive. Use the shade to get up close and feed some of those hounds and I promise you they\'ll be content to leave you alone, if not side with the hand that fed them.$B$BDon\'t get too close to those things until you\'ve fed them though. Their noses don\'t fall victim to your shade\'s elusiveness.]', '[Keritose Bloodblade at the Shadow Vault wants you to use the Eidolon Watcher to feed 18 Hungering Plaguehounds.]', '', '去找冰冠冰川的凱力多斯·血刃。', '已餵食飢餓瘟疫獵犬', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13170 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13170, 'zhTW', '[Honor is for the Weak]', '[Ghouls are fragile things when it comes down to it, and the lookouts at the saronite quarry down the path to the southwest are no exception. Using one of the shades, I have no doubt that you can sneak up and put down their lookouts without making a sound.$B$BClear out as many lookouts as you can reach in a reasonable amount of time... we\'ll want their ranks thinned for our assault to come.]', '[Keritose Bloodblade at the Shadow Vault would like you to assassinate 20 Restless Lookouts.]', '', '去找冰冠冰川的凱力多斯·血刃。', '不安的哨兵已暗殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13171 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13171, 'zhTW', '[From Whence They Came]', '[My main concern is the saronite quarry down the path to the southwest. They are pulling up immense amounts of ore from that quarry and I\'d like to know what they\'re building with it. To that end, we\'ll start by weakening their defenses.$B$BI noticed a series of crystals scattered throughout the base and I assume they are defensive structures of some sort, not unlike ziggurats. Use the eidolon watcher to destroy any of those crystals that you find.]', '[Keritose Bloodblade at the Shadow Vault has sent you to banish 10 Scourge Containment Crystals.]', '', '去找冰冠冰川的凱力多斯·血刃。', '被放逐的天災水晶', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13172 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13172, 'zhTW', '[Seeds of Chaos]', '[Effective tool, is it not? Excellent job weakening their defenses, $c. Now we can push the main assault.$B$BThe plan here is straight-foward - we\'re looking to destroy anything moving, and get in there and steal some information amidst the confusion.$B$BLet me know when you\'re ready and I\'ll set you up with a skeletal gryphon.]', '[Keritose Bloodblade at the Shadow Vault has dispatched you to slaughter 80 undead in the Weeping Quarry. Speak to him to secure a skeletal gryphon for the assault.]', '', '去找冰冠冰川的凱力多斯·血刃。', '哭泣採石場的亡靈已屠殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13173 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13173,'zhTW','騷動之中','我們已經弄到了不少工人。他們會很有用的。$B$B我要你用眼睛控制其中一個工人返回挖掘場。現在整個營地都陷入了混亂，他們肯定會把當成你在襲擊中走散的工人，你不會露餡的。$B$B你要找出工廠的負責人並動手幹活。如果夠幸運的話，我們很快就能發現那些邪鐵的去向。我會通過眼睛關注你的。','我們抓到了不少工人，他們應該能派上用場。$B$B我要你用眼睛把其中一名工人帶回採石場。既然整座營地已經亂成一團，他們絕對沒辦法把你跟其他被攻擊打散的工人分辨出來。$B$B找到負責這次行動的人，然後開始工作。運氣好的話，我們很快就能查出那些薩隆邪鐵被運去哪裡了。我會透過眼睛在旁看著你。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13174 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13174, 'zhTW', '[Amidst the Confusion]', '[Shutting down their operation is just half of the plan. The other important goal here is to find out where all that saronite is being sent. We know of a few places it\'s been ending up, but the amount they\'re pulling out suggests to me that there\'s a bigger project in the works.$B$BOnce you\'re inside the quarry, get your hands on any of their documents that you can find. If you\'re assaulting the place with one of the gryphons, you can drop down from it as soon as the wetwork is done.]', '[Keritose Bloodblade at the Shadow Vault has requested a Weeping Quarry Document, a Weeping Quarry Ledger, a Weeping Quarry Map, and a Weeping Quarry Schedule.]', '', '去找冰冠冰川的凱力多斯·血刃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13175 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13175, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13176 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13176, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13177 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13177, 'zhTW', '[No Mercy for the Merciless]', '[Welcome to the Wintergrasp Fortress, $n. Your mission is simple. Defeat ten of the Horde\'s finest. Now, go! Bring victory to the Alliance!]', '[Commander Zanneth in Wintergrasp Fortress wants you to slay 10 members of the Horde.]', '', '去找冬握堡壘的指揮官桑奈希。', '部落成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13178 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13178, 'zhTW', '[Slay them all!]', '[Welcome to the Wintergrasp Fortress, $n. Warlord Garrosh demands one thing: Slay them all!$B$BReturn to me when ten of the strongest members of the Alliance are dead.]', '[Commander Dardosh in Wintergrasp Fortress wants you to slay 10 members of the Alliance.]', '', '去找冬握堡壘的指揮官達多許。', '聯盟成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13179 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13179, 'zhTW', '[No Mercy for the Merciless]', '[Welcome to the Wintergrasp, $n. Your mission is simple. Defeat ten of the Horde\'s finest. Now, go! Bring victory to the Alliance!]', '[Commander Zanneth in Wintergrasp wants you to slay 10 members of the Horde.]', '', '去找冬握堡壘的指揮官桑奈希。', '部落成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13180 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13180, 'zhTW', '[Slay them all!]', '[Welcome to the Wintergrasp, $n. Warlord Garrosh demands one thing: Slay them all!$B$BReturn to me when ten of the strongest members of the Alliance are dead.]', '[Commander Dardosh in Wintergrasp wants you to slay 10 members of the Alliance.]', '', '去找冬握堡壘的指揮官達多許。', '聯盟成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13181 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13181,'zhTW','冬握之捷','指揮官桑奈希的腳下堆了這麼多的部落屍體，他一定很滿意，但是對驍勇遠征軍而言，控制冬握才是最重要的目標。你得確保我們能徹底控制冬握湖。$B$B不過，你別想只靠你的盟友做這些骯髒的事情來不勞而獲。如果你在戰鬥結束後還沒有到達徵召的第二級官階就別回來。','在冬握戰場中獲勝，並向冬握湖的戰術軍官阿布拉米斯回報。你必須參與戰鬥才能擁有勝利的榮耀。','在冬握湖取得勝利','到冬握湖找戰術軍官阿布拉米斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13182 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13182, 'zhTW', '別忘了那些蛋!', '遍佈於阿茲歐-奈幽，天譴奈幽蟲族總是小心翼翼地孵育將孵化的蛋，這是牠們數量迅速滋長的原因。$B$B若能清除掉不死生物玷汙過，用以鳩佔鵲巢的敗壞蟲蛋，對牠們的洞穴而言是件好事。$B$B當你探索那一度是阿茲歐-奈幽的廣袤地帶，一定要清理我們古老家園中，任何你看到的天譴蛋。', '那金之淵裡的『排除者』齊力克斯，要你進入阿茲歐-奈幽並摧毀6個奈幽天譴蛋。', '', '去找龍骨荒野的『排除者』齊力克斯。', '摧毀奈幽天譴蛋', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13183 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13183,'zhTW','冬握之捷','雖然達多許必定會為我們痛宰敵人感到滿意，但掌控冬握堡壘才是我們的最終目的。不擇手段也要確保冬握湖是我們的。$B$B然而，你別想只靠你的盟友做這些骯髒的事情來不勞而獲。如果你在戰鬥結束後還沒有到達徵召的第二級官階就別回來。','在冬握戰場中獲勝，並向冬握湖的戰術軍官科伊瑞斯回報。你必須要參與戰鬥才能擁有勝利的榮耀。','在冬握湖取得勝利','到冬握湖找戰術軍官科伊瑞斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13184 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13184, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13185 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13185, 'zhTW', '[Stop the Siege]', '[I hears dem! The Alliance come soon. Destroy three Alliance siege devices and come back to Murp.]', '[Lieutenant Murp in Wintergrasp Fortress wants you to destroy 3 Alliance siege machines.]', '', '去找冬握堡壘的莫普中尉。', '聯盟攻城裝置已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13186 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13186, 'zhTW', '[Stop the Siege]', '[It is only a matter of time before this castle is besieged by the forces of the Horde. Destroy three of their siege devices and return to me.]', '[Senior Demolitionist Legoso in Wintergrasp Fortress wants you to destroy 3 Horde siege machines.]', '', '去找冬握堡壘的資深爆破兵勒茍索。', '部落攻城裝置已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13187 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13187, 'zhTW', '[The Faceless Ones]', '[In my peoples\' struggle against the forces of the undead, they dug deeper as they lost ground. In desperation, they dug too deep.$B$BWe inadvertently exposed a tendril of the old god\'s will, which was made manifest in the creatures known only as the Faceless.$B$BIn the end, we could not fight on two fronts against such powerful enemies. Our misfortune cost us the war against the undead, and ultimately, our home.$B$BEnter Ahn\'kahet, $c, and cleanse our former home of these Faceless atrocities.]', '[Kilix the Unraveler in the Pit of Narjun wants you to kill Herald Volazj and the three Forgotten Ones that accompany him in Ahn\'Kahet.]', '', '去找龍骨荒野的『排除者』齊力克斯。', '被遺忘者已摧毀', '已擊敗傳令官沃拉茲', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13188 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13188, 'zhTW', '[Where Kings Walk]', '[You are now, and forever will be, a Knight of the Ebon Blade, $N, but know this: you were once a hero of the Alliance.$B$B<Darion stares at you.>$B$BThis order must establish allies for itself if it is to survive. You must represent the Knights of the Ebon Blade to the Alliance.$B$BOn the platform, southeast of me, is a portal to Stormwind City. Take this letter, given to me on your behalf by Lord Fordring, and deliver it to King Varian Wrynn. Use the portal.]', '[Deliver the letter to King Varian Wrynn of the Alliance at Stormwind Keep in Stormwind City.]', '', '去找艾爾文森林的瓦里安·烏瑞恩國王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13189 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13189, 'zhTW', '[Warchief\'s Blessing]', '[You are now, and forever will be, a Knight of the Ebon Blade, $N, but know this: you were once a hero of the Horde.$B$B<Darion stares at you.>$B$BThis order must establish allies for itself if it is to survive. You must represent the Knights of the Ebon Blade to the Horde.$B$BOn the platform, southeast of me, is a portal to Orgrimmar. Take this letter, given to me on your behalf by Lord Fordring, and deliver it to Thrall. Use the portal.]', '[Deliver the letter to Thrall, Warchief of the Horde at Orgrimmar.]', '', '去找奧格瑪的索爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13190 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13190, 'zhTW', '[All Things in Good Time]', '[Ahn\'kahet, from whence we came...$B$BOne day, I dream, we shall overcome the death and darkness that hold our ancient home in their grip. To that end, I have a plan to weaken the resolve of our enemies.$B$BTheir precious Watchers must burn!$B$BTake their corpses and place them upon the brazier deep within the city. The scent of their burnt remains will linger in the air, reminding our enemy of their weakness.$B$BBe mindful, $c! Their undead corpses are most fragile and will deteriorate rapidly.]', '[Kilix the Unraveler in the Pit of Narjun wants you to obtain an Ahn\'kahar Watcher\'s Corpse and place it upon the Ahn\'kahet Brazier in Ahn\'kahet.$B$BThis quest can only be completed on Heroic Difficulty.]', '', '去找龍骨荒野的『排除者』齊力克斯。', '安卡哈守望者的屍體已焚燒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13191 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13191, 'zhTW', '[Fueling the Demolishers]', '[Lok\'tar, $n! While the battle may be over, we must prepare for the Alliance\'s next assault! Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve ten eternal embers.$B$BThe embers are mixed in with coal to fuel the Demolishers and Siege Engines. $B$BWe\'ve heard reports of Alliance pigs collecting the embers all day. Slay them and take their embers! If they have already abandoned the area, then be prepared to fight the fire elementals there until you find some!]', '[Siegesmith Stronghoof at Wintergrasp Fortress wants you to retrieve 10 Eternal Embers from Alliance players in the Cauldron of Flames.]', '', '去找冬握堡壘的攻城鐵匠猛蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13192 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13192, 'zhTW', '[Warding the Walls]', '[Hey \'mon. This place be givin\' me dah heebie jeebies, don\'t cha know?$B$BWay too many spirits haunting dis place. I want ta be placing hoodoo wards up, but I be needin\' some souls, mon. Not any soul though, only da soul of a strong warrior could do da job.$B$BThe Glacial Falls in east Wintergrasp be havin\' dem special properties to extract da soul. Slay the Alliance there, mebbe they be havin\' the stuff we need.$B$BBring back da armor of the slain. If there be no Alliance maybe da elementals got \'em, mon.]', '[Hoodoo Master Fu\'jin at Wintergrasp Fortress wants you to retrieve 10 Enchanted Alliance Breastplates at the Glacial Falls.]', '', '去找冬握堡壘的咒毒大師符金。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13193 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13193, 'zhTW', '[Bones and Arrows]', '[Why would they set me to the task of arming our archers? I was a poet, not a ranger! Well, no use complaining. $n, I am in need of dragon bone for our arrowheads.$B$BTravel to the Forest of Shadows on the western side of Wintergrasp. Ever since the last skirmish, the Alliance have been scavenging dragon bones in the area. Slay them and take the bones.$B$BIf that fails, you might be lucky and get one from the spirits in the area. I hear they love to impale their living victims on the bones as they die.]', '[Lieutenant Vieron Blazefeather at Wintergrasp Fortress wants you to retrieve 10 Quivers of Dragonbone Arrows from Alliance players in the Forest of Shadows.]', '', '去找冬握堡壘的維耶隆‧炎羽。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13194 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13194, 'zhTW', '[Healing with Roses]', '[Between the battles, one might almost believe that there was hope for peace in this land. Sadly, that is not to be our fate.$B$BTravel to the Steppe of Life in southwestern Wintergrasp. I have need of the roses that grow there for salve to treat the wounded.$B$BSadly, the rose has become scarce due to the Alliance harvesting it too rapidly. Slay them on the Steppe of Life and retrieve their herb pouches from the bodies.$B$BIf that fails, perhaps a lasher or two might have one.]', '[Primalist Mulfort wants you to retrieve 10 Alliance Herb Pouches from Alliance players at the Steppe of Life.]', '', '去找冬握堡壘的原獵者穆法特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13195 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13195, 'zhTW', '[A Rare Herb]', '[My, it is quite chilly up here! Reminds me of the stormy peaks of Kaarinos on Argus. However, with all of this snow and ice, our soldiers can easily catch cold.$B$BHead to the Steppe of Life in southwestern Wintergrasp, and bring me back 10 Horde Herb Pouches. I will grind the herbs into a medicine to protect against the cold.$B$BThe Horde have been seen collecting them from the plant life in the area. Do not hesitate to slay them and retrieve the herbs!$B$BYou may also find one on a lasher in the area.]', '[Anchorite Tessa in Wintergrasp wants you to retrieve 10 Horde Herb Pouches from Horde players in the Steppe of Life.]', '', '去找冬握堡壘的隱士泰莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13196 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13196, 'zhTW', '[Bones and Arrows]', '[Dragons are incredible! Well, their bones at least! I\'ve been equipping our archers with arrowheads made of Dragonbone. Unfortunately, since the massacre at Angrathar, it has become almost impossible to get bone from Dragonblight.$B$BHowever, the Forest of Shadows on the western edge of Wintergrasp has enough bones to tide us over.$B$BHead to the Forest of Shadows and bring back any bone splinters you can find!$B$BThe Horde have been seen collecting bone splinters in the area. Slay them!]', '[Bowyer Randolph in Wintergrasp wants you to retrieve 10 Quivers of Dragonbone Arrows from Horde players at the Forest of Shadows.]', '', '去找冬握堡壘的弓箭商藍道夫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13197 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13197, 'zhTW', '[Fueling the Demolishers]', '[$n! About time you showed up. While we may have lost the last battle, we should prepare for the next! Travel to the Cauldron of Flames in southeastern Wintergrasp and retrieve several eternal embers.$B$BThe embers are mixed in with coal to fuel the Demolisher and Siege Engines. $B$BOh, and if you happen to see some of the Horde in the Cauldron, don\'t hesitate to slay them and take their embers. We must prevent them from holding the keep!]', '[Siegesmith Stouthandle in Wintergrasp wants you to retrieve 10 Eternal Embers from Horde players at the Cauldron of Flames.]', '', '去找冬握堡壘的攻城大師斯托哈德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13198 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13198, 'zhTW', '[Warding the Warriors]', '[$n, good to see you. We must prepare for our next assault on the fortress. My research indicates that the armor of soldiers recently slain in the Glacial Falls becomes imbued with an incredible amount of energy. The Horde has been collecting armor in the area.$B$BHead to the Glacial Falls and slay any of the Horde you find there. Return their imbued armor to me.$B$BIf you cannot find any of the Horde, you might find the armor of an adventurer slain by the elementals.]', '[Sorceress Kaylana in Wintergrasp wants you to retrieve 10 sets of Imbued Horde Armor at the Glacial Falls.]', '', '去找冬握堡壘的巫女凱拉娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13199 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13199, 'zhTW', '[Bones and Arrows]', '[Why would they set me to the task of arming our archers? I was a poet, not a ranger! Well, no use complaining. $n, I am in need of dragon bone for our arrowheads.$B$BTravel to the Forest of Shadows on the western side of Wintergrasp. Ever since the last skirmish, the Alliance have been scavenging dragon bones in the area. Slay them and take the bones.$B$BIf that fails, you might be lucky and get one from the spirits in the area. I hear they love to impale their living victims on the bones as they die.]', '[Lieutenant Vieron Blazefeather in Wintergrasp wants you to retrieve 10 Quivers of Dragonbone Arrows from Alliance players at the Forest of Shadows.]', '', '去找冬握堡壘的維耶隆‧炎羽。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13200 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13200, 'zhTW', '[Fueling the Demolishers]', '[Lok\'tar, $n! While the battle may have subsided, we must prepare to retake the fortress! Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve ten eternal embers.$B$BThe embers are mixed in with coal to fuel the Demolishers and Siege Engines. $B$BWe\'ve heard reports of Alliance pigs collecting the embers all day. Slay them and take their embers! If they have already abandoned the area, then be prepared to fight the fire elementals there until you find some!]', '[Siegesmith Stronghoof in Wintergrasp wants you to retrieve 10 Eternal Embers from Alliance players at the Cauldron of Flames.]', '', '去找冬握堡壘的攻城鐵匠猛蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13201 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13201, 'zhTW', '[Healing with Roses]', '[So many of our braves were lost during the battle, but even more shall die if left untreated. $B$BTravel to the Steppe of Life in southwestern Wintergrasp. I have need of the roses that grow there for salve to treat the wounded.$B$BSadly, the rose has become scarce due to the Alliance harvesting it too rapidly. Slay them on the Steppe of Life and retrieve their herb pouches from the bodies.$B$BIf that fails, perhaps a lasher or two might be in bloom.]', '[Primalist Mulfort in Wintergrasp wants you to retrieve 10 Alliance Herb Pouches from Alliance players at the Steppe of Life.]', '', '去找冬握堡壘的原獵者穆法特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13202 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13202, 'zhTW', '[Jinxing the Walls]', '[Hey \'mon. See dem Alliance sitting comfy in their keep?$B$BI think they be a bit too comfy, ya? I want ta be jinxing the place, but I be needin\' some souls, mon. Not any soul though, only da soul of a strong warrior could do da job.$B$BThe Glacial Falls in east Wintergrasp be havin\' dem special properties to extract da soul. Slay the Alliance there, they be havin\' the stuff we need.$B$BBring back da armor of the slain. If there be no Alliance maybe da elementals got \'em, mon.]', '[Hoodoo Master Fu\'jin in Wintergrasp wants you to retrieve 10 Enchanted Alliance Breastplates from Alliance players at the Glacial Falls.]', '', '去找冬握堡壘的咒毒大師符金。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13203 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13203, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13204 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13204, 'zhTW', '惡臭磨菇', '一朵畸形的磨菇-似乎是剛從蠻穴野獸惡臭又滿佈分泌物的屍塊上掉下來的磨菇。檢視它時，你被中人欲嘔的惡臭薰得差點昏過去。$B$B你想知道，是否這是奈幽蟲族的盤中美味。將這黏涕涕的噁心玩意放進你的背包，你決定要找出真相……', '你必須在安卡罕特的蠻穴野獸身上，採集6朵怪誕菌菇，並送去給那金之淵裡的『排除者』齊力克斯。', '', '去找龍骨荒野的『排除者』齊力克斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13205 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13205, 'zhTW', '[Disarmament]', '[Take it from me, $g小夥子：小姑娘;, them vrykul weapons be downright nasty!$B$BI\'ve felt their edge personally, and there be somethin\' unnatural about \'em. Deceptively well-balanced, wickedly sharp - just plain deadly.$B$BGet into their stronghold and if nuthin\' else, pilfer some o\' them weapons! Mebbe we can learn us a thing \'er two about \'em, mebbe not.$B$BBottom line - the fewer axes they be swingin\' around, the better.]', '[Defender Mordun wants you to enter Utgarde Keep and steal 5 Vrykul Weapons]', '', '去找嚎風峽灣的防衛者摩丹。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13206 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13206, 'zhTW', '[Disarmament]', '[We must discover the secret to these savages\' weapons!$B$BIf you\'d have seen how easily they cut through my companions, you\'d understand my sense of urgency. Just have a look at their forge if you doubt my words.$B$BScour the place. Gather all of their arms that you can carry and bring them to Anselm for his inspection.$B$BDo not fail us, $c. Every weapon you are able to bring out of this place is one less that we must face in the field.]', '[Dark Ranger Marrah wants you to steal 5 Vrykul Weapons from Utgarde Keep and bring them to High Executor Anselm in Vengeance Landing.]', '', '去找嚎風峽灣的高階執行官安賽姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13207 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13207, 'zhTW', '[Halls of Stone]', '[Well now, I\'m surprised to see other adventurers in a place such as this! It so happens that I could use a bit o\' company for what lies ahead.$B$BIf my research on these halls is accurate, there be monumental discoveries to be made here!$B$BAssumin\' I can count on ya to watch my back, you\'re welcome to tag along. So, what\'dya say, $c? Care ta join me?]', '[Brann Bronzebeard wants you to accompany him as he uncovers the secrets that lie in the Halls of Stone.]', '', '去找岩石大廳的布萊恩·銅鬚。', '布蘭恩的探索已完成', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13210 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13210,'zhTW','Blizzard Account: - DEM - E - FLAG','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13211 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13211, 'zhTW', '[By Fire Be Purged]', '[The Scourge uses our own fallen against us, by raising them as ghouls or skeletons, or by dismembering their corpses and using the parts to make abominations. This must stop!$B$BThe dead are heroes who fell in defense of all the living, and they cannot be confined to so grisly a fate. Moreover, we cannot afford to face them again on the field, used as weapons against us. Take this torch with you to the Fleshwerks, and burn any of the corpses you find in the Sanctum of Reanimation or the abomination lab.]', '[Crusader Olakin Sainrith at Blackwatch wants you to burn 7 Festering Corpses using Olakin\'s Torch.]', '', '去找冰冠冰川的十字軍歐拉金·山瑞斯。', '腐爛屍體已焚燒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13212 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13212, 'zhTW', '[He\'s Gone to Pieces]', '[With the abduction of Crusader Olakin, the Argent Crusade\'s forces will have no commander in the final assault on the Fleshwerks. While one crusader is the same as any other to me, the argents won\'t see it that way.$B$BI hate to see us waste time chasing after this, but I have no choice. Our gallant crusader has likely been dismembered by now, and his remains used to construct abominations. Go down into the Fleshwerks, kill the corpulent horrors fighting our forces, and recover Olakin\'s body parts.]', '[Recover Olakin\'s Torso, Olakin\'s Legs, Olakin\'s Left Arm, and Olakin\'s Right Arm and bring them to Darkrider Arly at Blackwatch.]', '', '去找冰冠冰川的黑騎兵亞爾利。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13213 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13213, 'zhTW', '', '', '[Speak with Geirrvif in Valhalas.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13214 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13214, 'zhTW', '[Battle at Valhalas: Fallen Heroes]', '[If you believe yourself ready to begin then I have just the match for you to cut your teeth on.$B$BAnother group of outsiders thought themselves prepared for the rigors of Valhalas. They had much hubris, but in the end they fell like all of the others.$B$BIf you think yourselves so different -- if you think that you have the skill and experience to fight here amongst such storied warriors -- then please accept the challenge.]', '[Geirrvif at Valhalas has challenged you to, in a single combat, defeat all six of the fallen heroes: Eldreth, Geness Half-Soul, Jhadras, Masud, Rith, and Talla.$B$BShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.]', '已擊敗陣亡英雄', '去找冰冠冰川的『殘酷』吉雍納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13215 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13215, 'zhTW', '[Battle at Valhalas: Khit\'rix the Dark Master]', '[A variety of beings travel the world to prove themselves within Valhalas. Some even come from under the world.$B$BKhit\'rix the Dark Master is one such.$B$BHailing from deep within the ground where insanity reigns, Khit\'rix has asked for someone exotic to face in the ring. You will do.$B$BDare you face this Nerubian nightmare, $r?]', '[Geirrvif at Valhalas has challenged you to defeat Khit\'rix the Dark Master.$B$BShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.]', '已擊敗黑暗宗師基特里克斯', '去找冰冠冰川的『殘酷』吉雍納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13216 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13216, 'zhTW', '[Battle at Valhalas: The Return of Sigrid Iceborn]', '[An old foe of yours has returned: Sigrid Iceborn. Perhaps you remember besting her in a duel upon the Savage Ledge?$B$BNo matter, she certainly remembers you. She\'s insisting upon a chance to prove herself once more.$B$BPersonally, I think it\'s more a chance for revenge, but that too can be useful in this place.$B$BI leave it up to you, $N. Will you face Sigrid Iceborn once more?]', '[Geirrvif at Valhalas has challenged you to defeat Sigrid Iceborn.$B$BShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.]', '已擊敗希格麗德·冰生者', '去找冰冠冰川的『殘酷』吉雍納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13217 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13217, 'zhTW', '[Battle at Valhalas: Carnage!]', '[You\'ve been successful up to this point, $N, but what you must face to continue to battle within Valhalas is a gigantic horror beyond imagining.$B$BI must warn you to turn away now. Carnage is a mountain of flesh constructed by the Lich King\'s most fiendish minds.$B$BI do not see how you and your friends will defeat it. However, the choice is yours.]', '[Geirrvif at Valhalas has challenged you to defeat Carnage.$B$BShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.]', '已擊敗卡奈奇', '去找冰冠冰川的『殘酷』吉雍納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13218 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13218, 'zhTW', '[Battle at Valhalas: Thane Deathblow]', '[Your skills have not gone unnoticed by the vrykul of Jotunheim, $N. Thane Banahogg has taken a personal interest in you and has insisted that he be your next match.$B$BIf you thought Carnage was bad, then you might want to go home now. Thane Banahogg\'s nickname is The Deathblow. I think you can guess how he earned it.$B$BDo you accept the thane\'s challenge?]', '[Geirrvif at Valhalas has challenged you to defeat Thane Banahogg, the Deathblow.$B$BShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.]', '已擊敗酋長巴納霍格', '去找冰冠冰川的『殘酷』吉雍納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13219 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13219, 'zhTW', '[Battle at Valhalas: Final Challenge]', '[I\'m afraid that your success is going to be your undoing, $N.$B$B<If the val\'kyr could turn more white, she would.>$B$BWord of your success in Valhalas has reached deep into Icecrown Citadel, stirring one whom you have no desire to meet.$B$BPrince Sandoval himself is on his way at this very moment. Gjonner warned you that you should run and I cannot disagree.$B$BWhat will you do? He\'s on his way. Will you face the blood prince in final battle?]', '[Geirrvif at Valhalas has challenged you to defeat Prince Sandoval.$B$BShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.]', '已擊敗桑多瓦爾王子', '去找冰冠冰川的『殘酷』吉雍納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13220 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13220, 'zhTW', '[Putting Olakin Back Together Again]', '[We can\'t afford to waste any time putting Olakin back together. Fortunately, the Scourge has provided a perfect place for you to stitch him back together.$B$BNear the Fleshwerks\' flesh giant lab is the Sanctum of Reanimation. Search the area for a spool of thread and the doctor\'s cleaver. Then, take Olakin\'s remains to the large slab in the middle of the sanctum and get to work.]', '[Obtain a Spool of Thread and the Doctor\'s Cleaver, then take them to the Sanctum of Reanimation Slab and use Olakin\'s remains to attempt to reanimate the crusader. Return to Darkrider Arly at Blackwatch when this task is complete.]', '', '去找冰冠冰川的黑騎兵亞爾利。', '已復活十字軍奧拉金·聖萊斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13221 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13221, 'zhTW', '[I\'m Not Dead Yet!]', '[The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their \'work\' here if I cannot escape.$B$BI cannot make it on my own, my child, but with your help, I may yet live to fight the Scourge again.$B$BWill you help me make my escape before the Scourge\'s butchers come to finish me off?]', '[Escort Father Kamaros to safety and then report to Absalan the Pious aboard the Skybreaker.]', '護送卡馬羅斯神父至安全處', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13222 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13222, 'zhTW', '[Defend the Siege]', '[Front and center, $n! We\'re beginning our assault on Wintergrasp Fortress. Those Horde animals think they can hide cowardly behind their walls? Well, I think not! We\'ll show them the power of Gnomish technology and smash their walls to bits!$B$BHowever, even the most powerful siege device is helpless without a crew. Pilot or protect one of our siege vehicles as it destroys three of the Horde structures.]', '[Senior Demolitionist Legoso in Wintergrasp wants you to pilot or protect a siege device as it destroys three structures.$B$BPlayers of private rank or higher can build siege devices at Goblin Workshops.]', '', '去找冬握堡壘的資深爆破兵勒茍索。', '已防禦攻城載具', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13223 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13223, 'zhTW', '[Defend the Siege]', '[Dem Alliance won\'t be long to hold that keep. Murp would smash walls, but Murp has to stay in camp. Murp wish he could smash Alliance who want to hurt Horde demolishers.$B$BYou, $n! You go in Murp\'s place. Protect 3 siege vehicles while they smash Alliance buildings. Alliance not expect you to defend demolisher. Show Alliance how smart Murp is! ]', '[Lieutenant Murp in Wintergrasp wants you to defend or pilot a siege vehicle while they destroy three Alliance structures.$B$BSiege devices can be built by ranked Horde players at the Goblin Workshops.]', '', '去找冬握堡壘的莫普中尉。', '已防禦部落攻城載具', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13224 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13224, 'zhTW', '', '', '[Seek out Sky-Reaver Korm Blackscar aboard Orgrim\'s Hammer flying above Icecrown.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13225 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13225, 'zhTW', '', '', '[Seek out High Captain Justin Bartlett aboard the Skybreaker flying above Icecrown.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13226 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13226, 'zhTW', '審判日將臨!', '我們無法獨力擊敗巫妖王。分裂的我們唯有敗亡一途!我懇求你回應我們的呼喚，<兄弟/姐妹>。銀白十字軍接受所有願意為戰爭奉獻心力的志士。大領主提里奧·弗丁在銀白先鋒駐地親自等著你!坐上你的坐騎，飛往寒冰皇冠的東南邊境。你可以在那裡找到大領主弗丁以及銀白十字軍的士兵。去吧，$c，為了審判日將臨!', '在寒冰皇冠的銀白先鋒駐地，向大領主提里奧·弗丁報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13227 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13227, 'zhTW', '', '', '[Report to Highlord Tirion Fordring at the Argent Vanguard in Icecrown.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13228 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13228, 'zhTW', '[The Broken Front]', '[What battle?! Those troops were on a recon mission!$B$BAnd what\'s this talk of Alliance - you\'re sure he said Alliance?$B$BListen to me, $n! I need to know what\'s going on and I need to know NOW!$B$BGet yourself down there and get me some answers! Scour the battlefield and look for survivors - clues - anything!]', '[Korm Blackscar on Orgrim\'s Hammer wants you to go to The Broken Front and question a Dying Berserker to discover what happened there.]', '', '去冰冠冰川找奧格瑞姆之錘的空奪者寇姆‧黑疤。', '已審問垂死的狂戰士', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13229 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13229, 'zhTW', '[I\'m Not Dead Yet!]', '[The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their \'work\' here if I cannot escape.$B$BI cannot make it on my own, $c, but with your help, I may yet live to fight the Scourge again.$B$BWill you help me make my escape before the Scourge\'s butchers come to finish me off?]', '[Escort Father Kamaros to safety and then report to Brother Keltan aboard Orgrim\'s Hammer.]', '護送卡馬羅斯神父至安全處', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13230 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13230, 'zhTW', '[Avenge Me!]', '[I hear them, $g兄弟：姊妹;....$B$BThe moans of the wounded Alliance... they taunt me...$B$BFinish what we have begun here, $c. Show no mercy... let none of them survive.$B$BFor... the Horde...]', '[A Dying Berserker has asked that you slay 5 Dying Soldiers at the Broken Front. Report to Sky-Reaver Korm Blackscar on Orgrim\'s Hammer when it is done.]', '', '去冰冠冰川找奧格瑞姆之錘的空奪者寇姆‧黑疤。', '垂死的聯盟士兵已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13231 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13231, 'zhTW', '破碎前線', '什麼?!不…!我們承受了多少的痛苦，只為了維持這回攻擊的低調。部落怎麼可能知道的?裝備…人力…全軍覆沒了嗎?不可能的!$B$B我們在寒冰皇冠的戰略，其關鍵在於比部落先奪下那道門。我們必須盡快重新整備，然後發動另一波攻勢。$B$B查看戰場，搜尋所有的生還者。檢討從這場悲劇中得到什麼教訓。$B$B還有，為了將臨的戰鬥，你得打點妥當，$n，我們必須兩面作戰…', '破天者號上的提督賈斯汀·巴特勒要求你，去破碎前線訊問一個垂死的士兵，並回報給他。', '', '去找冰冠冰川的提督賈斯汀·巴特勒。', '訊問垂死的士兵', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13232 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13232, 'zhTW', '[Finish Me!]', '[They taunt us - even as they lie dying here...$B$BPlease, $g兄弟：小姐;... Don\'t allow their mocking to be the last sounds I hear...$B$BFinish me... deliver me from this torment... into... the Light.$B$BSeek out  my companions... offer them the same mercy.$B$BLeave nothing for the Scourge to raise!$B$BI beg you...]', '[A Dying Soldier in the Broken Front wants you to kill 5 Dying Soldiers and report to High Captain Justin Bartlett on the Skybreaker.]', '', '去找冰冠冰川的提督賈斯汀·巴特勒。', '垂死的士兵已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13233 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13233, 'zhTW', '[No Mercy!]', '[It is as I told you. They were not merely idle words spoken in a fit of anger.$B$BTime and again, the Horde have demonstrated their disdain for everything we hold dear and holy. They must pay with their lives for their transgressions against the light.$B$BAll of them.$B$BJust imagine a world free of their stain, $n. Envision the joy our children will know. Think of the reverence your descendants will have for your memory, knowing they owe their happiness to you.$B$BNow go, and make that vision a reality!]', '[High Captain Justin Bartlett aboard the Skybreaker wants you to kill 15 Horde Players in Icecrown.]', '', '去找冰冠冰川的提督賈斯汀·巴特勒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13234 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13234, 'zhTW', '[Make Them Pay!]', '[The time has come!$B$BToo long have we suffered the company of the self-righteous Alliance! Too long have we stayed our hand from cleansing our world of the weak and the desperate.$B$BNow, we bring an end to our humiliation! Now, we show them the true meaning of fear! Now, we bring honor to the Horde!$B$BHere, at Icecrown, we break the Alliance!$B$BGo, $c. Hunt them down. Break them. Take their will to live!]', '[Sky-Reaver Korm Blackscar wants you to kill 15 Alliance Players in Icecrown.]', '', '去冰冠冰川找奧格瑞姆之錘的空奪者寇姆‧黑疤。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13235 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13235, 'zhTW', '[The Flesh Giant Champion]', '[You\'ve done well in destroying the Fleshwerks and slaughtering the Lich King\'s servants. Now, all that remains is to defeat the Fleshwerks\' greatest accomplishment -- the flesh giant known as Morbidus.$B$BIt will not be an easy fight, but the Shadow Vault has dispatched Margrave Dhakar with some reinforcements. Meet up with him at the highest point at the western end of the Fleshwerks. Tell him when you\'re ready to begin the attack and he\'ll order his forces into battle.]', '[Speak with Margrave Dhakar at the western end of the Fleshworks to engage Morbidus. After you have defeated Morbidus, report to Darkrider Arly at Blackwatch.]', '', '去找冰冠冰川的黑騎兵亞爾利。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13236 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13236, 'zhTW', '[Army of the Damned]', '[You probably think you\'re quite strong -- fighting these undead and crushing their bones beneath your war machines.$B$BThat is nothing compared to the strength it took to create them.$B$BI saw the prince do it himself.  I can show you how it happened... if you\'d like.]', '[Matthias Lehner at the First Legion Forward Camp wants you to raise an army of 100 Ghoulish Minions.]', '', '去找冰冠冰川的米希阿斯·薩爾奈。', '已喚起食屍鬼爪牙', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13237 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13237, 'zhTW', '[Poke and Prod]', '[While your commander has his focus diluted by his loathing of your Alliance rivals, you can depend on me to direct my attention squarely on the real enemy here - the Lich King and his minions.$B$BIn order to hold any hope of conquering him at the citadel, your people must take and hold each gate.$B$BFor now, let us focus on the first. Return to the front and prod their defenses. Look for any sign of weakness that we might exploit.$B$BI\'ll await your report, $c.]', '[Koltira Deathweaver aboard Orgrim\'s Hammer wants you to go the Broken Front and defeat 5 Hulking Abominations, 5 Malefic Necromancers, and 5 Shadow Adepts.]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '巨大憎惡已擊殺', '邪惡死靈法師已擊殺', '暗影行者已擊殺', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13238 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13238, 'zhTW', '', '', '[Sky-Reaver Korm Blackscar wants you to speak with Chief Engineer Copperclaw aboard Orgrim\'s Hammer.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13239 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13239, 'zhTW', '[Volatility]', '[Where to begin... well, you must know that as chief engineer of this vessel I have access to all of the intelligence reports - yes, yes, it\'s true, and I\'ve recently taken a particular interest in the frostwyrms you reported seeing to the south, and I do believe I\'ve developed a plan that just might work against them... now it\'ll take a little legwork on your part, but essentially, you build a dummy out of armor and coat it with a splash of this solution, then run for cover!$B$B...You still here, $r?]', '[Chief Engineer Copperclaw wants you to use Copperclaw\'s Volatile Oil at the Broken Front to attract 3 Frostbrood Skytalons.$B$BTo use the oil, you must collect a Pile of Bones, an Abandoned Helm, and Abandoned Armor from the battlefield there.]', '', '去冰冠冰川找奧格瑞姆之錘的首席工程師銅爪。', '已進行實地測試', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13240 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13240, 'zhTW', '[Timear Foresees Centrifuge Constructs in your Future!]', '[It is into the Oculus floating above Coldarra that you must travel, $N.$B$BI have foreseen a situation in which you must destroy the centrifuge constructs therein. I can assure you that if you do not first eliminate these magical creations, you and your friends will fail.$B$BThus I have seen, thus you must do.]', '此任務已經絕版。[Archmage Timear in Dalaran has foreseen that you must destroy 10 Centrifuge Constructs.]', '', '去找水晶歌森林的大法師泰彌亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13241 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13241, 'zhTW', '泰彌亞在你的未來預見了依米亞狂戰士!', '依米倫王的戰士就擋在汝與指日可待的勝利之間。$B$B汝將前往凜風峽灣深處，名為俄特加德之巔的要塞。余無法更加強調，汝輩能了結依米亞狂戰士，是如何地重要。$B$B若未能達成，將致汝輩之毀滅。$N!', '此任務已經絕版。達拉然的大法師泰彌亞要求你，殺掉7個依米亞狂戰士。', '', '去找水晶歌森林的大法師泰彌亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13242 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13242, 'zhTW', '[Darkness Stirs]', '[Darkness stirs, $N. A tragic event has transpired that none but the Timeless One could have foreseen. Soon your people will be gripped by anger and hatred. War is on the horizon.$B$BThe red dragonflight has done all that it can. What happens next is in the hands of the mortal races of Azeroth.$B$BRegrettably, your journey begins with anguish. A father has lost a child today. You must bear the grim news. Gather the armaments of Saurfang and return them to the elder Saurfang. $B$B]', '[Gather Saurfang\'s Battle Armor from the field of battle and return it to High Overlord Saurfang at Warsong Hold in Borean Tundra.]', '', '去找北風凍原的薩魯法爾霸王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13243 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13243, 'zhTW', '[Timear Foresees Infinite Agents in your Future!]', '[The timeline is in danger from the Infinite dragonflight. Without your intervention, all of time will unravel!$B$BYou must travel to a point in time known as the Culling of Stratholme within the Caverns of Time.$B$BIt gives me a migraine just to attempt to see into all of the possible pasts, but I do know that it is crucial for you to kill the Infinite agents.$B$BOnly by slaying them will the true past be preserved and the present and future kept from being undone forever!]', '此任務已經絕版。[Archmage Timear in Dalaran has foreseen that you must slay 4 Infinite Agents.]', '', '去找水晶歌森林的大法師泰彌亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13244 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13244, 'zhTW', '[Timear Foresees Titanium Vanguards in your Future!]', '[The entirety of Azeroth is in peril. The mad god Loken has it within his power to put an end to everything!$B$BWithin the Terrestrial Watchtower at the Halls of Lightning, the titanium vanguards stand poised to execute Loken\'s dread will upon countless unknowing victims.$B$BI have looked into the future, $N. You are the one to see that this does not come to pass!]', '此任務已經絕版。[Archmage Timear in Dalaran has foreseen that you must slay 7 Titanium Vanguards.]', '', '去找水晶歌森林的大法師泰彌亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13245 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13245, 'zhTW', '[Proof of Demise: Ingvar the Plunderer]', '[I need you to assemble a group and lead them into Utgarde Keep. Therein, you are to find and slay Ingvar the Plunderer before he can lead his vrykul forces to sack the nearby Alliance and Horde towns.$B$BI require his axe as proof that he has been dealt with. It\'s not that I don\'t trust you. It\'s simply prudent to be certain that the deed has been done.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with the Axe of the Plunderer.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13246 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13246, 'zhTW', '[Proof of Demise: Keristrasza]', '[Are you familiar with the story of Keristrasza?$B$BHow she was instrumental in the slaying of Saragosa, the mate of Malygos? How, in turn, he took Keristrasza as his consort, freezing her within a block of ice?$B$BWe have become aware that Malygos has been using his magic to break her will. This has driven her insane.$B$B$N, you must go into the Nexus in Coldarra and put an end to her before she can be fully turned.$B$BThough it saddens me, I must insist that you bring me her heart as proof.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with Keristrasza\'s Broken Heart.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13247 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13247, 'zhTW', '[Proof of Demise: Ley-Guardian Eregos]', '[The Nexus War rages on and we must do something to turn the tide! Are you willing to fly into the heart of the battle, $N?$B$BLey-Guardian Eregos is the protector of the conduit through which Malygos is funneling the magical power of Azeroth\'s ley lines. If he can be slain it will be a great blow to the enemy.$B$BPlease bring me one of his ley line tuners so that we might study it.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with a Ley Line Tuner.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13248 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13248, 'zhTW', '[Proof of Demise: King Ymiron]', '[King Ymiron of Utgarde Pinnacle is the favored vrykul of the Lich King. That alone is reason enough to put an end to him.$B$BBut should he blow the horns and call for all of the leaders of the ymirjar and mjordin alike, the vrykul will become a force more powerful than any other within the Scourge!$B$BIt is up to you, $N, to see to it that this does not come to pass. Bring me the locket from around his neck so that I will know that Ymiron no longer poses a threat.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with the Locket of the Deceased Queen.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13249 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13249, 'zhTW', '死亡證明:預言者薩隆杰', '德拉克薩隆要塞曾經是德拉克瑞王國的驕傲。如今卻淪為巫妖王的墊腳石，來毀滅祖爾德拉克，以便偷取食人妖眾神之力的力量。$B$B但假使我們能夠擊敗他們的領袖，預言者薩隆杰，或許便能遏止源源不竭的天譴食人妖妖援軍。至少，這能讓祖爾德拉克的銀白十字軍少點負擔。$B$B擊敗預言者後將他的附魔提基像帶回來給我。', '此任務已經絕版。達拉然的大法師朗達拉克要求你，帶回一個預言者的附魔提基像。$B$B這個任務只能在英雄難度下完成。', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13250 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13250, 'zhTW', '[Proof of Demise: Gal\'darah]', '[The Drakkari prophets of Zul\'Drak have done the unthinkable: they\'ve slain most of their gods to absorb their powers! The most dangerous of all is the High Prophet of Akali, Gal\'darah.$B$BSequestered within the bowels of Gundrak, Gal\'darah has absorbed almost all of the mojo from slain Akali and now stands poised to erupt with his followers from the city. If we do not kill him now, we will be awash in a sea of madness and unthinkable power!$B$BHurry, $N, bring me what\'s left of Akali\'s mojo.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with the Mojo Remnant of Akali.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13251 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13251, 'zhTW', '[Proof of Demise: Mal\'Ganis]', '[$N, a friend within the bronze dragonflight has given me information that we must exploit.$B$BThe mysterious beings of the Burning Legion called the dreadlords are also known racially as the Nathrezim. Little is known of their homeworld and even that is rumor.$B$BHowever, it is known that Mal\'Ganis of the past has made a critical error: he left behind an artifact from his homeworld!$B$BThrough the Caverns of Time, you must travel back to the time known as the Culling of Stratholme. Recover the artifact.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with the Artifact from the Nathrezim Homeworld.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13252 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13252, 'zhTW', '[Proof of Demise: Sjonnir The Ironshaper]', '[Little is understood about the condition known as the Curse of Flesh. However, there is information to be had within the Halls of Stone.$B$BSjonnir The Ironshaper seems to know a great deal with regard to the curse. We have it on good authority that he is carrying a Titan disc of information upon him that could answer all of our questions.$B$BRetrieve this disc for me, $N, so that we may learn.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with the Curse of Flesh Disc.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13253 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13253, 'zhTW', '[Proof of Demise: Loken]', '[Within the Halls of Lightning, Loken is poised to put an end to our world. Need I say more, $N?$B$BHe sits there listening to the mad whisperings of the Old God trapped beneath Northrend. You and your friends must travel to the Storm Peaks immediately!$B$BConfront Loken within the Terrestrial Watchtower and stop him before it is too late! Bring me his ruby ring so that I will know we are safe once more.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with the Celestial Ruby Ring.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13254 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13254, 'zhTW', '[Proof of Demise: Anub\'arak]', '[The Scourged nerubians are a plague upon our forces.$B$BWhile we are safe from them here, floating above the world, when we set foot upon the land below, it is always with the thought that the undead nerubians could burrow up from the depths of Azjol-Nerub and attack.$B$BIt\'s in the best interests of everyone if they are thrown into a state of disarray. Kill their former king, and major-domo to the Lich King, the crypt lord, Anub\'arak.$B$BPlease bring me his crown... not that he wears it any longer.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with the Idle Crown of Anub\'arak.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13255 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13255, 'zhTW', '[Proof of Demise: Herald Volazj]', '[The nerubians of Ahn\'kahet dug too deep during their attempt to escape the invasion of the Scourge. They got too close to the Old God under Northrend.$B$BRousing its awareness, the Old God sent its insane creatures against them, and the nerubians were caught between the proverbial rock and a hard place.$B$BThe leader of the Old Gods\' forces, Herald Volazj is one of the nightmarish beings known as The Faceless. Put an end to him and bring me his withered brain.$B$BJust please, try to keep your sanity.]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with the Faceless One\'s Withered Brain.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13256 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13256, 'zhTW', '[Proof of Demise: Cyanigosa]', '[We\'re being invaded! The blue dragonflight has teleported into the Violet Hold and they\'re planning on breaking out from there into the rest of Dalaran!$B$BThere have already been reports of prisoners inadvertently being freed by their actions. It wouldn\'t surprise me if they\'re purposefully letting some of them free.$B$B$N, can you assemble your team quickly and get in there? Cyanigosa is the leader of their invasion force. Bring me her head!]', '此任務已經絕版。[Archmage Lan\'dalock in Dalaran wants you to return with the Head of Cyanigosa.$B$BThis quest may only be completed on Heroic difficulty.]', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13257 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13257,'zhTW','戰爭的使者','酋長需要你，勇士。奧格瑪進入了全城戒嚴狀態，一場不可避免的衝突迫在眉睫。酋長已經下令關閉所有的商店和服務設施，全面備戰。$B$B我不能透露更多的消息了——至少現在不能。在這樣的場合跟你談論局勢也不合適。$B$B酋長傳下令來，部落最強大的勇士必須立即趕往王座廳向他報到。去吧，$N！穿過傳送門返回奧格瑪，向索爾報到。','轉至奧格瑪的格羅瑪什堡壘，向索爾報到。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13258 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13258, 'zhTW', '', '', '[Speak to Sergeant Kregga below Icecrown Citadel.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13259 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13259,'zhTW','確立優勢','我們必須把握唯一的機會，對城堡造成破壞——千萬不能搞砸了。$B$B我們已經弄到了天災軍團製造的強力薩隆邪鐵炸彈。但是在引爆炸彈之前，必須確保萬無一失。$B$B我們得在天災軍團的援軍趕來之前，迅速壓制他們的防禦部隊。$B$B幫助我的人消滅天災士兵吧，然後你就可以準備引爆炸彈了。','冰冠堡壘的克蕾迦中士要你去殺死10只笨重的恐屍。','','去冰冠冰川找冰冠堡壘的克蕾迦中士。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13260 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13260, 'zhTW', '', '', '[Sky-Reaver Korm wants you to speak to Koltira Deathweaver on Orgrim\'s Hammer.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13261 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13261, 'zhTW', '[Volatility]', '[Wahooo! It works! Not that I had any doubts in my supernatural ingenuity, only that I wasn\'t quite sure what kind of explosion to expect - let\'s just say I\'m glad to see that you didn\'t get your eyebrows singed off. So now I just need to show ol\' Korm how ya thaw out one \'a them wyrms. He\'ll hafta promote me to... to... to whatever comes after Chief Engineer! Here, you take another batch of the stuff and head back out to the front and I\'ll go get Korm...$B$BWell? Move out!]', '[Chief Engineer Copperclaw wants you to use Copperclaw\'s Volatile Oil at the Broken Front to attract 3 Frostbrood Skytalons.$B$BTo use the oil, you must collect a Pile of Bones, an Abandoned Helm, and Abandoned Armor from the battlefield there.]', '', '去冰冠冰川找奧格瑞姆之錘的首席工程師銅爪。', '已進行實地測試', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13262 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13262, 'zhTW', '', '', '[Go to the nearby Saronite Bomb Stack to light the fuse.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13263 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13263, 'zhTW', '', '', '[Look for clues wherever the fall takes you.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13264 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13264, 'zhTW', '[That\'s Abominable!]', '[Abominations...$B$BThey can be a very capable enemy. I\'ve seen them turn the tide of battle more than once. What few realize, is that they can also be very capable friends.$B$BThey are not deep thinkers. If you know the secrets of their creation, you can issue them basic orders that they will not question.$B$BFortunately for you, I know these secrets.$B$BThis kit will reanimate the remains of the abominations you defeat. Take it, and learn to use them against the Scourge on the death gate.]', '[Koltira Deathweaver on Orgrim\'s Hammer wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '冰霜食屍鬼已引爆', '凶殘幽魂已引爆', '復生的聯盟士兵已引爆', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13265 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13265, 'zhTW', '[Cloth Scavenging]', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13266 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13266,'zhTW','毫無遺憾的一生','當我的生命走到盡頭時，我希望自己能夠毫無遺憾地離開這個世界。那些因此悲傷的人會明白，作為部落的酋長，我做出的決定都是有利於我的子民的。$B$B但是瓦里瑪薩斯和普特雷斯的叛變……令我們過去的努力全都付之東流。$B$B<索爾沉重地嘆了口氣。>$B$B正義必須得到伸張。$B$B轉至幽暗城的傳送門馬上就會開啟，沃金正在等你，我稍後也會過去和你們碰面。我們要一起挽回殘局，$N。','穿過格羅瑪什堡壘內的傳送門，轉至幽暗城，向沃金報到。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13267 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13267,'zhTW','幽暗城之戰','瓦里瑪薩斯已經控制了整座幽暗城。我們的士兵整裝待發，只等酋長髮出進攻的指令。$B$B只要幫助我們奪回幽暗城，你就可以躋身部落最偉大的勇士之列！如果你能從戰場上活著回來，就去向索爾覆命吧。$B$B準備就緒後和酋長談一談。','幫助索爾和希爾瓦娜斯為部落奪回幽暗城。$B$B完成任務後向索爾覆命。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13268 AND `locale` = 'zhTW';
