INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13273, 'zhTW', '[Going After the Core]', '[With Norgannon\'s Shell in hand, only half of the archive key remains to be found. Luckily, I\'ve had the Explorers\' League hard at work chasing down leads about the whereabouts of Norgannon\'s Core.$B$BFar to the southeast of the Inventor\'s Library, on the slopes to the north of Dun Niffelem, is a camp bearing my name. The Explorers\' League representatives seeking the second half of the key are based there. Bring me the maps and the notes they\'ve made and we should be able to track down the other key half.]', '[Find Prospector Khrona\'s Notes and Prospector Soren\'s Maps at Brann\'s Base-Camp.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13274 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13274, 'zhTW', '[The Core\'s Keeper]', '[Prospector Soren\'s notes say that Norgannon\'s Core is in the keeping of a sentinel named Athan, one of Mimir\'s creations.$B$BSoren says the vault where Athan resides is called "Loken\'s Bargain" these days.$B$BLoken, eh? The earthen have mentioned him.$B$BThe vault is said to be southwest of the ruined Explorers\' League camp, with a round entrance on a mountainside overlooking the Valley of Ancient Winters.$B$BFind this Athan and get the core from him, but I wouldn\'t be surprised if you were in for a fight.]', '[Obtain Norgannon\'s Core.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13275 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13275, 'zhTW', '[Time to Hide]', '[You shouldn\'t have touched it.  But now that you did, he\'s going to come looking for you.$B$BAnd he\'ll find you.  Unless you hide yourself from him.$B$BBring me blood from the faceless ones if you want to live!]', '[Matthias Lehner wants you to obtain 3 Faceless One\'s Blood.]', '', '去找冰冠冰川的米希阿斯·薩爾奈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13276 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13276, 'zhTW', '[That\'s Abominable!]', '[You know what to do, $c.$B$BTake this kit and use the guts from their abominations to create one of your own, then command it to attack the enemy forces at the gate.$B$BYou would do well to refine this tactic for when we make our assault on the gate.]', '[Koltira Deathweaver on Orgrim\'s Hammer wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '冰霜食屍鬼已引爆', '凶殘幽魂已引爆', '復生的聯盟士兵已引爆', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13277 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13277, 'zhTW', '[Against the Giants]', '[While it\'s going to be crucial to defeat the Scourge on the ground, we mustn\'t neglect the gate itself.$B$BThe flesh giants on the ramparts are capable of hurling massive boulders and chunks of ice, inflicting devastating damage to enemy infantry below.$B$BMuster a force and defeat these giants. We need to know just what we\'re up against in terms of their strength.$B$BOh... and bring me their spines. If memory serves, there\'s a little trick I can share with you.]', '[Koltira Deathweaver on Orgrim\'s Hammer wants you to bring him 5 Pustulant Spines from the Pustulant Horrors on Mord\'rethar.]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13278 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13278,'zhTW','汙染者科普洛斯','有報告指出死亡之門有一隻非常強大的殭屍，$c。$B$B我們必須設法解除它帶來的潛在威脅。如果你能親自與它交手，應該可以瞭解到更多的有價值的情報。$B$B轉至死亡之門西面的大廳，向這隻怪物發起挑戰，找出它的弱點。','奧格瑞姆之錘的庫爾迪拉·織亡者要你轉至莫德雷薩，殺死汙染者科普洛斯。','','去冰冠冰川找奧格瑞姆之錘的庫爾迪拉·織亡者。','殺死汙染者科普洛斯','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13279 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13279,'zhTW','化學常識','<庫爾迪拉取過脊骨，把裡面的膿液倒進瓶子裡。>$B$B我們對血肉巨人的特性有一點點了解……$B$B它們的脊骨膿液可以以一種非常有趣的方式與瘟疫病菌溶合，將瘟疫轉換成一種腐蝕劑。$B$B雖然說從高高的城牆上潑下腐蝕劑會讓下面的士兵非常鬱悶，但至少受害者不會變成天災軍團的爪牙。$B$B把這隻瓶子裡的東西倒進死亡之門西面大廳內的瘟疫之鍋裡去。','奧格瑞姆之錘的庫爾迪拉·織亡者希望你轉至莫德雷薩，將脊骨膿液倒進那裡的瘟疫之鍋。','','去冰冠冰川找奧格瑞姆之錘的庫爾迪拉·織亡者。','中和瘟疫之鍋','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13280 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13280,'zhTW','佔山為王','瞧見伊米海姆西北方那座陡峭的山峰了麼，你只要駕駛我的跳躍機器人儘快爬上山頂就行啦，$N！$B$B布拉斯·炸雷是個懦弱的壞蛋，他正在擺弄自己的破爛機器人呢，大概馬上就要完工了吧。我們正在比賽，看誰能搶先佔領那座山頭！$B$B等你跳上去之後，將我們的軍旗插到徽記堆裡。讓大家知道，聯盟才是最棒的！我的工程學技術才是最棒的！','伊米海姆的弗拉索·磨輪要你使用弗拉索的跳躍機器人，將聯盟軍旗插到山頂的徽記堆上。','','去冰冠冰川找伊米海姆的弗拉索·磨輪。','插下聯盟軍旗','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13281 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13281,'zhTW','中和瘟疫','沒有我的幫助，你也可以中和敵人的瘟疫之鍋了，$r。$B$B去消滅死亡之門一帶的血肉巨人，用它們脊骨中的膿液中和瘟疫。$B$B你所打擊的是敵軍最重要的核心部分。這是一個重要的任務——對我們的事業而言生死攸關的任務。只要時間允許，就應該盡力去完成。$B$B記住，你可以在莫德雷薩找到血肉巨人和瘟疫之鍋。','奧格瑞姆之錘的庫爾迪拉·織亡者希望你轉至莫德雷薩，將脊骨膿液倒進那裡的瘟疫之鍋。$B$B你可以使用從起膿的血肉巨人身上收集而來的脊骨製造膿液。','','去冰冠冰川找奧格瑞姆之錘的庫爾迪拉·織亡者。','中和瘟疫之鍋','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13282 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13282,'zhTW','返回地面','現在你該走了。我身後有一道傳送門，它可以把你送到地面上去。$B$B我們還會見面的。他會來找你。$B$B他遲早會找到你。','返回奧格瑞姆之錘，向庫爾迪拉·織亡者覆命。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13283 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13283,'zhTW','佔山為王','嘿，你好啊，$N。跟昨天一樣，我要你駕駛跳躍機器人儘快爬上伊米海姆東南方那座山峰的頂部！$B$B弗拉索·磨輪這個自以為是的傢伙，她老是說她的跳躍機器人比我的好！呸！我們正在比賽，看誰能搶先佔領那座山頭！$B$B等你跳上去之後，將我們的軍旗插到徽記堆裡。讓大家知道，部落才是最棒的！我的工程學技術才是最棒的！','伊米海姆的布拉斯·炸雷要你使用布拉斯的跳躍機器人，將部落軍旗插到山頂的徽記堆上。','','去冰冠冰川找伊米海姆的布拉斯·炸雷。','插下部落軍旗','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13284 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13284,'zhTW','地面突襲','你好，$c。$B$B最近我們一直在對伊米海姆發動猛攻，但是這些維庫人比我們之前遇到過的要兇殘得多。每次部隊試圖向伊米海姆推進時都會遭到伏擊，我們的人員損失非常慘重。$B$B如果你願意參戰，幫助我的小分隊安全抵達伊米海姆的大門，我們會好好獎勵你的。抵達大門之後，我們就會挖掘壕溝，等待後援部隊。','護送破天號部隊抵達伊米海姆的門口。完成任務後返回伊米海姆東面的冰川邊緣，向地面指揮官庫普覆命。','','去冰冠冰川找失落希望之谷的地面指揮官庫普。','護送聯盟部隊前往伊米海姆','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13285 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13285, 'zhTW', '[Forging the Keystone]', '[Aha! Here it is: the Temple of Invention, the seat of Keeper Mimir himself! Of course, that\'s where one would go to join the two parts of the key.$B$BAccording to the prospector\'s notes, the Temple of Invention is one of the highest points on the western side of the Terrace of the Makers. That means it should be roughly east of your Grom\'arsh Crash Site.$B$BI\'ll meet you at the temple and we\'ll combine the parts together.]', '[Brann Bronzebeard wants you to meet him at the Temple of Invention and help him combine Norgannon\'s Shell and Norgannon\'s Core. Once you have helped Brann, report back to Boktar Bloodfury at the Grom\'arsh Crash-Site.]', '', '去找風暴峭壁的博克塔‧血怒。', '幫助布蘭恩製作鑰石', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13286 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13286,'zhTW','……所有可能的幫助','時局令人絕望，$c……$B$B我感到異常焦慮，打算接受一切可能的幫助——包括這裡的死亡騎士駐軍。$B$B和薩薩里安談一談吧。看看他能否幫助我們改良對抗天災軍團的戰術，確保我們一旦組織起足夠的人手，就能夠一擊而勝。$B$B我們已經走到了這一步……絕對不能功敗垂成！','破天號的高階指揮官加斯汀·巴雷特要你與薩薩里安談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13287 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13287,'zhTW','知己知彼','像你這樣擁有豐富作戰經驗的英雄必定了解這一點：沒有什麼途徑比親自與敵人交手更能摸清對方底細了。$B$B雖然你渴望獲得攻佔冰冠堡壘的榮耀，但是我們必須首先突破巫妖王的每一扇大門。所謂知己知彼，百戰百勝……$B$B我要你返回破碎前線，與敵人交戰。尋找他們的弱點，然後向我彙報詳細的情況。','破天號上的薩薩里安要你轉至破碎前線，殺死5名笨重的憎惡、5名邪惡通靈師和5名暗影專家。','','去冰冠冰川找破天號的薩薩里安。','殺死笨重的憎惡','殺死邪惡通靈師','殺死暗影專家','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13288 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13288,'zhTW','你的憎惡夥伴','憎惡……$B$B可怕的敵人。我不止一次目睹它們迅速地扭轉了戰局。事實上，它們也可以成為有用的夥伴，這一點倒是鮮為人知。$B$B憎惡並不聰明。只要你瞭解製造憎惡的秘密，就可以對它們發出簡單的指令。相信我，它們會毫不猶豫地執行你的命令。$B$B你很幸運，我恰好知曉其中的奧秘。$B$B對憎惡的殘骸使用這個工具包，將其復活。接下來你就可以利用它對付駐守在死亡之門的天災軍團了。','破天號上的薩薩里安要你使用憎惡復活工具包製造一名復活的憎惡，然後利用它殺死15只冰寒食屍鬼、15只殘忍的惡鬼和15名復活的聯盟士兵。','','去冰冠冰川找破天號的薩薩里安。','引爆冰寒食屍鬼','引爆殘忍的惡鬼','引爆復活的聯盟士兵','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13289 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13289,'zhTW','你的憎惡夥伴','你知道該怎麼做吧，$c。$B$B對憎惡的殘骸使用這個工具包，製造一隻聽命於你的憎惡，然後命令它去攻擊駐守在死亡之門的敵人。$B$B在我們對死亡之門再次發動攻擊之前，你可以好好地熟悉一下這種戰術。','破天號上的薩薩里安要你使用憎惡復活工具包製造一名復活的憎惡，然後利用它殺死15只冰寒食屍鬼、15只殘忍的惡鬼和15名復活的聯盟士兵。','','去冰冠冰川找破天號的薩薩里安。','引爆冰寒食屍鬼','引爆殘忍的惡鬼','引爆復活的聯盟士兵','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13290 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13290,'zhTW','請留意一下……','在斬雷號任職期間，首席技師波爾維克憑藉卓越的表現贏得了大家的喝彩。如今，他也是破天號不可或缺的關鍵人物。若不是他，我們的戰艦早就被轟成碎片，散落在這片冰原上了。$B$B不過這傢伙有個毛病，他喜歡與大家分享所有細微的發明或是發現——而其中大部分都超出了我的理解範圍。$B$B我必須集中注意力對抗敵軍，不能為這種事分心。$B$B請代我去跟他談一談，$n。如果可以的話，最好幫幫他。他就在船艙裡。','高階指揮官加斯汀·巴雷特要你與破天號的首席技師波爾維克談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13291 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13291,'zhTW','“借來”的技術','好吧，我明白了。指揮官沒時間關注我的小發現。這是他的損失！$B$B瞧，我設法從敵人那裡“得到”了一批液體。儘管我討厭改造下等的地精科技製品，不過這次就算破例啦。$B$B喏，拿著這份樣本。我要你實地測試它的功效，便於讓我透過逆向工程來重現它的製作流程。$B$B轉至破碎前線，收集製造假人的材料，然後使用液體。','破天號上的首席技師波爾維克要你在破碎前線使用偷來的液體。$B$B你需要收集被丟棄的頭盔、被丟棄的護甲和一堆白骨才能召喚假人，這些材料都可以在破碎前線找到。','','去冰冠冰川找破天號的首席技師波爾維克。','完成實驗','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13292 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13292,'zhTW','偷來的解決方案','嗯，嗯，再來一次怎麼樣？訓練總是不嫌多的。$B$B我們已經找到了對付冰霜巨龍的法子。$B$B$r，繼續削減它們的數量吧。你幹掉的冰霜巨龍越多，我們在進攻冰冠堡壘時遇到的阻擾就越少。$B$B祝你好運。記得將沒用完的液體帶回來給我。','破天號上的首席技師波爾維克要你在破碎前線使用偷來的液體。$B$B你需要收集被丟棄的頭盔、被丟棄的護甲和一堆白骨才能召喚假人，這些材料都可以在破碎前線找到。','','去冰冠冰川找破天號的首席技師波爾維克。','殺死霜巢天爪龍','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13293 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13293,'zhTW','轉至伊米海姆！','伊米海姆坐落在冰冠冰川的中心地帶，我要你潛入這座冰霜維庫人的大型城市。$B$B布拉斯·炸雷已經抵達城市西側，代表戰歌遠征軍與聯盟展開了競賽。他要使用跳躍機器人與對方進行搶佔山頭的比賽！$B$B別讓我們失望，$N。地精工程學的尊嚴就靠你來維護了！此外，這裡的士兵都指望著你呢。$B$B我們都下了注，賭你一定能勝過那些蠢貨！','與伊米海姆的布拉斯·炸雷談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13294 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13294,'zhTW','對抗巨人','儘管擊敗地面上的天災士兵至關重要，但我們也不能疏忽了死亡之門的威脅。$B$B城牆上的血肉巨人可以投擲巨大的石塊和冰塊，對下面的部隊造成毀滅性的傷害。$B$B集合一支隊伍去幹掉那些巨人。我們必須要對敵人有足夠的瞭解。$B$B啊，對了……把它們的脊骨給我帶回來。如果我沒記錯的話，那東西有一些特別的用處。','破天號上的薩薩里安要你轉至莫德雷薩，從起膿的血肉巨人身上取回5根起膿的脊骨給他。','','去冰冠冰川找破天號的薩薩里安。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13295 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13295,'zhTW','化學常識','<薩薩里安取過脊骨，把裡面的膿液倒進瓶子裡。>$B$B我們對血肉巨人的特性有一點點了解……$B$B它們的脊骨膿液可以以一種非常有趣的方式與瘟疫病菌溶合，將瘟疫轉換成一種腐蝕劑。$B$B雖然說從高高的城牆上潑下腐蝕劑會讓下面的士兵非常鬱悶，但至少受害者不會變成天災軍團的爪牙。$B$B把這隻瓶子裡的東西倒進死亡之門西面大廳內的瘟疫之鍋裡去。','破天號上的薩薩里安希望你轉至莫德雷薩，將脊骨膿液倒進那裡的瘟疫之鍋。','','去冰冠冰川找破天號的薩薩里安。','中和瘟疫之鍋','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13296 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13296,'zhTW','轉至伊米海姆！','伊米海姆坐落在冰冠冰川的中心地帶，我要你潛入這座冰霜維庫人的大型城市。$B$B弗拉索·磨輪已經抵達城市南側，代表無畏遠征軍與部落展開了競賽。她要使用跳躍機器人與對方進行搶佔山頭的比賽！$B$B別讓我們失望，$N。侏儒工程學的尊嚴就靠你來維護了！此外，這裡的士兵都指望著你呢。$B$B我們都下了注，賭你一定能勝過那些蠢貨！','與伊米海姆的弗拉索·磨輪談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13297 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13297,'zhTW','中和瘟疫','沒有我的幫助，你也可以中和敵人的瘟疫之鍋了，$r。$B$B去消滅死亡之門一帶的血肉巨人，用它們脊骨中的膿液中和瘟疫。$B$B你所打擊的是敵軍最重要的核心部分。這是一個重要的任務——對我們的事業而言生死攸關的任務。只要時間允許，就應該盡力去完成。$B$B記住，你可以在莫德雷薩找到血肉巨人和瘟疫之鍋。','破天號上的薩薩里安希望你轉至莫德雷薩，將脊骨膿液倒進那裡的瘟疫之鍋。$B$B你可以使用從起膿的血肉巨人身上收集而來的脊骨製造膿液。','','去冰冠冰川找破天號的薩薩里安。','中和瘟疫之鍋','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13298 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13298,'zhTW','汙染者科普洛斯','有報告指出死亡之門有一隻非常強大的殭屍，$c。$B$B我們必須設法解除它帶來的潛在威脅。如果你能親自與它交手，應該可以瞭解到更多的有價值的情報。$B$B轉至死亡之門西面的大廳，向這隻怪物發起挑戰，找出它的弱點。','破天號上的薩薩里安要你轉至莫德雷薩，殺死汙染者科普洛斯。','','去冰冠冰川找破天號的薩薩里安。','殺死汙染者科普洛斯','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13299 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13299,'zhTW','ZZOLD幽光披風','','','','去晶歌森林找衰弱之河的查理·沃爾斯。','Complete Achievement: Northrend Loremaster','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13300 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13300,'zhTW','薩隆邪鐵的奴隸','維庫人將他們的俘虜送去位於冰冠冰川中心的伊米海姆，迫使他們進入那座城市的薩隆邪鐵礦洞做苦工。巫妖王命令他們日夜不停地挖掘這種邪惡的礦石。$B$B我答應過弗丁大人，一定要將他們活著救出來。這就是我們眼下的任務。$B$B但是作為無畏遠征軍的使者，我不得不奉命待在這艘飛艇上。你能替我去救他們嗎，$N？','破天號上的虔誠的阿布薩蘭要你去營救10名薩隆邪鐵礦洞奴隸。','','去找冰冠冰川破天號上的虔誠的阿布薩蘭。','營救薩隆邪鐵礦洞奴隸','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13301 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13301,'zhTW','地面突襲','你好，$c。$B$B最近我們一直在對伊米海姆發動猛攻，但是這些維庫人比我們之前遇到過的要兇殘得多。每次部隊試圖向伊米海姆推進時都會遭到伏擊，我們的人員損失非常慘重。$B$B如果你願意參戰，幫助我的小分隊安全抵達伊米海姆的大門，我們會好好獎勵你的。抵達大門之後，我們就會挖掘壕溝，等待後援部隊。','護送庫卡隆部隊抵達伊米海姆的大門。完成任務後返回伊米海姆北面的冰川邊緣，向地面指揮官科特亞覆命。','','去冰冠冰川找轟炸場的地面指揮官庫普。','護送部落部隊前往伊米海姆','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13302 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13302,'zhTW','薩隆邪鐵的奴隸','維庫人將他們的俘虜送去位於冰冠冰川中心的伊米海姆，迫使他們進入那座城市的薩隆邪鐵礦洞做苦工。巫妖王命令他們日夜不停地挖掘這種邪惡的礦石。$B$B我答應過弗丁大人，一定要將他們活著救出來。這就是我們眼下的任務。$B$B但是作為戰歌遠征軍的使者，我不得不奉命待在這艘飛艇上。你能替我去救他們嗎，$N？','奧格瑞姆之錘的凱爾坦修士要你去營救10名薩隆邪鐵礦洞奴隸。','','去冰冠冰川找奧格瑞姆之錘的凱爾坦修士。','營救薩隆邪鐵礦洞奴隸','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13303 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13303,'zhTW','測試任務','','','','去找Jonathan LeCraft。','Complete Achievement: Northrend Loremaster','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13304 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13304,'zhTW','戰地維修','天災軍團還沒有從我們的這次攻勢中緩過氣來，$N。你順利地完成了引爆任務，極大地鼓舞了大家計程車氣，我們要一鼓作氣，繼續戰鬥。$B$B位於我們下方的開闊山谷是一處戰略要地。我們在失落希望之谷的東南角發現了一輛癱瘓的攻城車，似乎還可以使用。$B$B如果你能從食腐的惡鬼手裡搶回丟失的零件，或許能讓它重新運轉起來。一輛攻城車就足以對敵人的地面單位造成重創了。','奧格瑞姆之錘的庫爾迪拉·織亡者從食腐的惡鬼身上收集5塊攻城車零件，然後將它們帶去失落希望之谷的損毀的攻城車旁。','','去冰冠冰川的失落希望之谷找損毀的攻城車。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13305 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13305,'zhTW','竭盡全力','你要用這臺機器去對付天災軍團？你這樣是無法勝過他們的。$B$B你或許可以消滅幾百個敵人……甚至幾千個，但你無法取得勝利。這樣不行。$B$B等你擺弄夠了這臺機器，可以到北邊來找我。那裡有一座舊軍營。我會讓你認識到，你要面對的是怎樣的敵人。','使用整修過的攻城車，在失落希望之谷裡消滅150只腐朽的食屍鬼、20個霜顱大法師和2個白骨巨人。完成任務之後轉至第一軍團前線營地，與米斯希爾薩·阿奈爾談一談。','','去冰冠冰川找失落希望之谷的米斯希爾薩·阿奈爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13306 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13306,'zhTW','構建路障','一旦我們的部隊開始動身穿越奧爾杜薩，他們就很容易遭到來自鐵牆壁壘和廣袤的冰川平原地區的攻擊。$B$B我們沒有時間和資源去建造防禦工事，但可以搭建一些臨時性的路障，抵禦天災軍團的遠端火力和突擊，以保護我們的士兵。$B$B帶著這隻工具箱到奧爾杜薩西面的隕落英雄之谷去。按照我在那裡做好的記號，用這隻工具箱製造一些路障。','奧格瑞姆之錘的庫爾迪拉·織亡者要你使用路障搭設工具建造8處路障。','','去冰冠冰川找奧格瑞姆之錘的庫爾迪拉·織亡者。','建造路障','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13307 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13307,'zhTW','濺血的旗幟','天災軍團正在奧爾杜薩西面的隕落英雄之谷和冰冠冰川裡搜尋死者，想要用他們來對付我們。天災軍團的軍官已經復活了山谷中的一些死者，並賦予了他們可怕的力量和狂熱的忠誠。天災軍團首領所攜帶的旗幟是這種力量的源泉，去殺死那些旗手，以此減少他們所控制的被轉化英雄的數量。$B$B你必須幫我們除去這個障礙，並且在大部隊開拔之前幫助我們削弱天災軍團的抵抗力度。','奧格瑞姆之錘的庫爾迪拉·織亡者要你去殺死5個天災旗手、5個天災轉化者和20個被轉化的英雄。','','去冰冠冰川找奧格瑞姆之錘的庫爾迪拉·織亡者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13308 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13308,'zhTW','思維詭計','<你的腦海中響起了這個怪物的聲音，它似乎在痛苦中掙扎，顯得格外詭異。>$B$B$R，我需要你的幫助。和你那些被俘虜的朋友一樣，我也被巫妖王手下的巨人給抓起來的。我從地下世界一路往上，想要調查從這座洞穴中傳來的噪音，結果就被他們抓住並囚禁了起來。$B$B你願意幫我嗎？鐐銬的鑰匙就在礦洞中的工頭身上。殺死他！$B$B<你感到一股壓力衝擊著你的思維，似乎這個怪物正在迫使你執行它的命令。>','薩隆邪鐵礦洞的黑暗低語者阿克希姆要你去找到工頭的鑰匙，幫它開啟鐐銬。','','去冰冠冰川找薩隆邪鐵礦洞的黑暗低語者阿克希姆。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13309 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13309,'zhTW','空中突襲','我已經選出了合適的士兵，準備將他們送進伊米海姆。你的任務就是保證他們的安全。$B$B維庫人在圍牆內設定了一些自動矛槍，已經打下我們好幾架運兵機了。我們的工程師建造了一座壓制炮臺，可以讓那些矛槍啞火。只要向矛槍周圍掃射一通，炮彈產生的煙霧就可以擋住它的視線，阻塞它的機關。$B$B跳上這座炮臺吧，保證我的士兵們都能安全著陸。','伊米海姆北面冰川邊緣的地面指揮官庫普命令你使用破天號壓制炮臺，保證破天號運兵機安全降落並卸下所有部隊。','','去冰冠冰川找失落希望之谷的地面指揮官庫普。','破天號潛入者安全著陸','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13310 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13310,'zhTW','空中突襲','正好有事情可以交給你這個廢物去做，省得你整天遊手好閒的。$B$B我們正準備將一隊訓練有素的士兵空投到伊米海姆去。但是維庫人在圍牆內設定了自動魚叉炮，用於摧毀我們的運兵機。於是，我們請奧格瑞姆之錘的工程師建造了一座壓制炮臺。$B$B你要充當炮手，對維庫人的魚叉炮進行掃射，遮擋它們的視線，並摧毀它們的傳動裝置。你必須在確保運兵機完整的情況下讓所有士兵都安全降落。','伊米海姆北面冰川邊緣的地面指揮官科特亞命令你使用庫卡隆壓制炮臺，保證庫卡隆運兵機安全降落並卸下所有部隊。','','去冰冠冰川找轟炸場的地面指揮官庫普。','庫卡隆潛入者安全著陸','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13311 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13311, 'zhTW', '[Demons Deck]', '[Now that you have gathered all of the Demon cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card.$B$BYou feel the card could be used to communicate with someone or something.]', '[Use the Demons Deck to summon a Darkmoon Fortune Teller and give the deck to them.]', '', '去找暗月算命師。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13312 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13312, 'zhTW', '[The Ironwall Rampart]', '[The Ironwall Rampart overlooks the Valley of Fallen Heroes, west of Aldur\'thar. The rampart dominates the fields below on all sides. We will not be able to advance if the rampart cannot be taken, but it is held by Grimkor the Wicked and his Cult of the Damned disciples.$B$BIf you can weaken Grimkor, our forces know what to expect as we advance. Take this rune of distortion. Unleashing its power near Grimkor\'s orb at the end of the rampart should be enough to get the necromancer\'s attention.]', '[Defeat Grimkor the Wicked and return to Koltira Deathweaver aboard Orgrim\'s Hammer.]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13313 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13313, 'zhTW', '[Blinding the Eyes in the Sky]', '[The Alliance has somehow managed to field a squadron of recon vehicles over the Valley of Fallen Heroes and Icecrown Glacier, the broad areas west of Aldur\'thar.$B$BThey cannot be permitted to take the lead in this fight. Chief Engineer Copperclaw has supplied me with the perfect weapon to deal with this threat -- he calls his new missile the SGM-3. I have his assurances that it will take out the Alliance flying machines in a single hit. Go and use this weapon to give us the upper hand.]', '[Use the SGM-3 to destroy 6 Skybreaker Recon Fighters, then report back to Sky-Reaver Korm Blackscar aboard Orgrim\'s Hammer.]', '', '去冰冠冰川找奧格瑞姆之錘的空奪者寇姆‧黑疤。', '破天號偵察戰機已擊落', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13314 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13314,'zhTW','獲取情報','部落最近表現得很活躍，我討厭這樣。自從破碎前線的那次行動以後，他們已經開始變得越來越猖狂了。聯盟必須阻止他們。$B$B他們在冰冠冰川的上空、奧爾杜薩和鐵牆壁壘的西面有頻繁的活動，斥候和傳令兵騎著龍鷹進進出出，不斷傳遞情報和命令。帶上這把鏢槍，用它去幹掉那些奧格瑞姆之錘斥候。如果你也騎著飛行坐騎的話，這個任務應該更容易完成。','從奧格瑞姆之錘斥候身上截獲6份奧格瑞姆之錘急件，把它們交給破天號上的高階指揮官加斯汀·巴雷特。','','去冰冠冰川找破天號的高階指揮官加斯汀·巴雷特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13315 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13315,'zhTW','暗中偵察','一切都在計畫之中。我們策劃了一連串完美的計畫來奪下死亡之門。傷亡雖是必然， 但最終的勝利將屬於我們－咬緊牙關對付那些愛管閒事的部落...$B$B不論如何，我們的下一個需要關切的目標是荒寂之門。飛往那兒並試著熟悉敵人的據點。$B$B當你回來我會再給你進一步指示。','破天者號上的薩沙理安要你飛往荒寂之門，偵察門的南、中、北、西北區域。','','去冰冠冰川找破天號的薩薩里安。','前往奧多薩南部','前往奧多薩中部','前往奧多薩北部','前往奧多薩西北部',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13316 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13316, 'zhTW', '[The Guardians of Corp\'rethar]', '[Corp\'rethar, called the Horror Gate. It is the last barrier between us and the Icecrown Citadel. It waits to the south of the Ironwall Rampart, beyond the glacier and the Conflagration. By the time our troops reach it, they will be exhausted and worse.$B$BWe must weaken its defenses, or our army\'s strength will break upon its walls.$B$BIts battlements are manned by some of the Lich King\'s fiercest and most zealous servants. Do all you can to destroy these guardians and hope it is enough.]', '[Koltira Deathweaver, aboard Orgrim\'s Hammer, wants you to kill 5 Harbingers of Horror and 5 Corp\'rethar Guardians.]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13317 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13317,'zhTW','----','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13318 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13318, 'zhTW', '[Drag and Drop]', '[The Cult of the Damned hold the gate of desolation, eh? No surprise there.$B$BTime to have a little fun. At the southern end of the gate, you mentioned there were new cultists being trained. They\'re almost certain to be holding a special item given to all initiates - an Orb of Illusion.$B$BThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.$B$BKill the fools until you find one, $c, then use it on a subjugator.]', '[Thassarian, aboard the Skybreaker, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur\'thar and use them on 3 Dark Subjugators there.]', '', '去找冰冠冰川的薩沙理安。', '已拖拽並丟棄黑暗征服者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13319 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13319, 'zhTW', '[Chain of Command]', '[Based on your report, and my knowledge of the Cult, they have an overseer managing the operation of each encampment on the gate.$B$BWhile taking their leaders down will only be a temporary setback, it will at least slow them down and keep them off-balance. And that, $r, is a worthy enough goal for now.$B$BSeek out these overseers and return to me when they have been dispatched.]', '[Thassarian aboard the Skybreaker wants you to go to Aldur\'thar and defeat Overseer Faedris, Overseer Savryn, Overseer Veraj, and Overseer Jhaeqon.]', '', '去找冰冠冰川的薩沙理安。', '監工菲德里斯已擊殺', '監工賈昆已擊殺', '監工維拉吉已擊殺', '監工薩弗林已擊殺', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13320 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13320,'zhTW','無法複製','我在這裡都聞到了他們的大鍋散發出的氣味，不過鍋裡煮的並不是瘟疫病菌。$B$B所有宣誓為詛咒教派效力的人都必須飲下一種可以奪走他們的意願、使他們永遠效忠巫妖王的藥劑。$B$B有人說，這種藥劑中封存著那些受到殘酷折磨、並被無情屠殺的生物的扭曲之魂，不過我從來就沒能成功地複製過這種藥水……$B$B從荒涼之門西北區域的三處大鍋裡各採集一些樣本，裝進這隻瓶子裡，然後把它交給首席技師波爾維克。','破天號上的薩薩里安希望你轉至荒涼之門奧爾杜薩，在那裡的3處詛咒教徒的大鍋中使用分離的藥瓶，然後將其交給首席技師波爾維克。','','去冰冠冰川找破天號的首席技師波爾維克。','收集藍色樣本','收集綠色樣本','收集黑色樣本','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13321 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13321, 'zhTW', '[Retest Now]', '[This should do the trick!$B$BThose twisted hooligans are looking for souls to put in their crazy-juice? Then I say we help \'em out a bit!$B$BTake a swig of this - don\'t worry, I\'ve diluted it plenty... I\'m almost positive that its only effect will be to detect any cultist\'s essence once you\'ve defeated them.$B$BWhen you\'ve collected a bunch of them, throw the writhing mass of twisted souls into any of their cauldrons.$B$BLet\'s see how they like a taste of their own medicine!]', '[Chief Engineer Boltwrench aboard the Skybreaker wants you to throw a Writhing Mass into a cauldron at Aldur\'thar.]', '', '去找冰冠冰川的首席工程師栓鉗。', '蠕動之團已放逐', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13322 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13322,'zhTW','重新考驗','那些扭曲的詛咒教徒想要把別人的靈魂放進他們的飲料裡？那麼讓我們來幫他們一把吧！$B$B把這東西喝下去——不用擔心，我已經對它進行了稀釋……現在它唯一的作用只是讓在你幹掉詛咒教徒時可以發現他們的精華。$B$B等你收集到一些精華之後，把那些充滿扭曲靈魂怨念的沸騰魔質扔進他們的瘟疫之鍋裡。$B$B看看他們嚐到自己的藥劑之後會怎樣！','破天號上的首席技師波爾維克希望你喝下稀釋過的詛咒教徒滋補劑，殺死奧爾杜薩一帶的任意詛咒教徒，從他們身上收集被汙染的精華。然後將10份被汙染的精華組合成沸騰的魔質，把它扔進奧爾杜薩的瘟疫之鍋裡。','','去冰冠冰川找破天號的首席技師波爾維克。','投放沸騰的魔質','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13323 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13323,'zhTW','從天而“降”','看來那些新教徒的數量又增加了。你知道該怎麼做吧……$B$B新來的教徒在荒涼之門的南端接受訓練。他們之中的絕大部分人應該都持有一件特殊的物品——幻象寶珠。$B$B這種寶珠可以用來偽裝詛咒教徒，使他們能夠安全地自由行動，滲透或是完全偽裝成敵人的模樣。$B$B去幹掉那些蠢貨，從他們身上收集幻象寶珠，然後對黑暗壓制者使用它。','破天號上的薩薩里安希望你從奧爾杜薩的苦痛新兵身上奪取幻象寶珠，然後對那裡的3名黑暗壓制者使用。','','去冰冠冰川找破天號的薩薩里安。','扔下黑暗壓制者','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13324 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13324,'zhTW','暗月稜鏡套牌','你現在已經收集到了稜鏡套牌的所有卡片，與前8張的背面圖案完全一樣的第9張卡片神秘地出現在你手中。在這張卡片上寫著，“將這些卡片拿到暗月馬戲團去，你就將獲得獎勵。”你聽說暗月馬戲團每過幾個月就會路過一次莫高雷和閃金鎮，因此你也許需要等待一段時間才能看到他們。','當暗月馬戲團來到鎮上的時候，把稜鏡套牌交給他們。','','去找薩杜斯·帕雷教授。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13325 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13325,'zhTW','暗月混亂套牌','你現在已經收集到了混亂套牌的所有卡片，與前8張的背面圖案完全一樣的第9張卡片神秘地出現在你手中。在這張卡片上寫著，“將這些卡片拿到暗月馬戲團去，你就將獲得獎勵。”你聽說暗月馬戲團每過幾個月就會路過一次莫高雷和閃金鎮，因此你也許需要等待一段時間才能看到他們。','當暗月馬戲團來到鎮上的時候，把混亂套牌交給他們。','','去找薩杜斯·帕雷教授。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13326 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13326,'zhTW','暗月高尚套牌','你現在已經收集到了高尚套牌的所有卡片，與前8張的背面圖案完全一樣的第9張卡片神秘地出現在你手中。在這張卡片上寫著，“將這些卡片拿到暗月馬戲團去，你就將獲得獎勵。”你聽說暗月馬戲團每過幾個月就會路過一次莫高雷和閃金鎮，因此你也許需要等待一段時間才能看到他們。','當暗月馬戲團來到鎮上的時候，把高尚套牌交給他們。','','去找薩杜斯·帕雷教授。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13327 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13327,'zhTW','暗月死靈套牌','你現在已經收集到了死靈套牌的所有卡片，與前8張的背面圖案完全一樣的第9張卡片神秘地出現在你手中。在這張卡片上寫著，“將這些卡片拿到暗月馬戲團去，你就將獲得獎勵。”你聽說暗月馬戲團每過幾個月就會路過一次莫高雷和閃金鎮，因此你也許需要等待一段時間才能看到他們。','當暗月馬戲團來到鎮上的時候，把死靈套牌交給他們。','','去找薩杜斯·帕雷教授。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13328 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13328, 'zhTW', '[Shatter the Shards]', '[Atop the battlements of Corp\'rethar, the Lich King\'s minions have erected three crystals, the shards of horror, despair, and suffering. Should our men reach the walls of Corp\'rethar, he will unleash these weapons on our army.$B$BIn full effect, the crystals will afflict the minds of our men with paralyzing pain and fear. Then, the Scourge will be able to slaughter them at will.$B$BFind these shards, destroy them, and bring me their broken remains. We cannot allow the Lich King to deploy these weapons!]', '[Bring the Broken Shard of Horror, the Broken Shard of Despair, and the Broken Shard of Suffering to Koltira Deathweaver aboard Orgrim\'s Hammer.]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13329 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13329, 'zhTW', '[Before the Gate of Horror]', '[The Conflagration, the ground before Corp\'rethar, south of the Ironwall Rampart, is where the Lich King\'s elite soldiers have formed up to defend the citadel.$B$BLed by a contingent of death knights, a legion of skeletal reavers bars the way. I fear that even when these reavers fall, the Scourge will simply reconstitute them and send them back at us.$B$BI\'ve come up with a plan to stop this, but I have no way of knowing if it will work. Take this solution and use it to dissolve the remains of the reavers.]', '[Koltira Deathweaver, aboard Orgrim\'s Hammer, wants you to use the Volatile Acid to dissolve the remains of 6 Skeletal Reavers.]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '骷髏掠奪者的骨頭已溶解', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13330 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13330, 'zhTW', '[Blood of the Chosen]', '[Those vrykul that have gained the favor of the Lich King call themselves the Ymirjar. They inhabit a city in the center of Icecrown. We have a lot of preparations to make before we assault Icecrown Citadel, and the one that stands before us now is routing these so-called "Chosen" of the Lich King.$B$BGo to their city, Ymirheim, and slaughter them in their home. Let there be no questions as to who the stronger combatants are here.]', '[Warbringer Davos Rioht on Orgrim\'s Hammer has sent you to kill 20 vrykul in Ymirheim.]', '', '去冰冠冰川找奧格瑞姆之錘的戰爭使者戴沃斯‧里歐特。', '尤彌爾海姆的維库人已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13331 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13331, 'zhTW', '[Keeping the Alliance Blind]', '[The Alliance is tenacious, I\'ll give them that, but it\'ll take more than that to stop us. Take this SGM-3 with you and shoot down the Skybreaker\'s recon fighters once again.$B$BI doubt the message will get through their thick skulls, but there are enough missiles to keep trying to get our point across. Go and find their fighters flying above the Valley of Fallen Heroes, west of Aldur\'thar, and don\'t come back until you\'ve made wreckage of them.]', '[Use the SGM-3 to destroy 6 Skybreaker Recon Fighters, then report back to Sky-Reaver Korm Blackscar aboard Orgrim\'s Hammer.]', '', '去冰冠冰川找奧格瑞姆之錘的空奪者寇姆‧黑疤。', '破天號偵察戰機已擊落', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13332 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13332, 'zhTW', '[Raise the Barricades]', '[When our forces begin to move beyond Aldur\'thar, they will be vulnerable to attack from the Ironwall Rampart and the broad glacier below.$B$BWe have neither the time nor the materials to build fortifications, but we can put up some barricades to shield our men from fire and break up Scourge charges.$B$BTake this barricade kit to the Valley of Fallen Heroes, on the west side of Aldur\'thar. Locate the markers I\'ve placed there and use this kit to construct your barricades there.]', '[Thassarian, aboard the Skybreaker, wants you to construct 8 Barricades using your Barricade Construction Kit.]', '', '去找冰冠冰川的薩沙理安。', '已建造路障', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13333 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13333,'zhTW','搶奪急件','不僅我們在努力，部落也在不斷向鐵牆壁壘和奧爾杜薩西面的冰冠冰川派出斥候。$B$B不能讓部落透過這種方法領先我們。再帶上這把鏢槍，不要對那些奧格瑞姆之錘斥候手軟！把你截獲的急件都給我帶回來。$B$B部落的損失就是我們的成果。','從奧格瑞姆之錘斥候身上截獲6份奧格瑞姆之錘急件，把它們交給破天號上的高階指揮官加斯汀·巴雷特。','','去冰冠冰川找破天號的高階指揮官加斯汀·巴雷特。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13334 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13334, 'zhTW', '[Bloodspattered Banners]', '[In the Valley of Fallen Heroes and Icecrown Glacier, to the west of Aldur\'thar, the Scourge seeks to use the fallen against us. Scourge lieutenants have woken the valley\'s dead and imbued them with fearsome strength and fervor. The banners carried by the Scourge leaders in the glacier area are the source of these powers. Kill the banner-bearers, and you will weaken the converted heroes they lead.$B$BIt falls to you to rid us of this obstacle, and test the resistance before the main body can advance.]', '[Thassarian, aboard the Skybreaker, wants you to kill 5 Scourge Banner-Bearers, 5 Scourge Converters, and 20 Converted Heroes.]', '', '去找冰冠冰川的薩沙理安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13335 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13335,'zhTW','在恐懼之門前','戰火平原位於科雷薩的前方，鐵牆堡壘的南方。巫妖王在這裡佈置了精銳部隊以守衛冰冠堡壘。$B$B一隊死亡騎士率領著大群的冰冠劫掠者守住了道路。我擔心就算我們打倒了這些劫掠者，天災軍團也能復活它們，並把它們再次投入戰場。$B$B我已經有了一個解決方案，不過尚不知道能否奏效。帶著這瓶溶液，用它去溶解那些冰冠劫掠者的殘骸。','破天號的薩薩里安要你使用強酸溶解6具冰冠劫掠者的屍體。','','去冰冠冰川找破天號的薩薩里安。','溶解冰冠劫掠者的殘骸','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13336 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13336, 'zhTW', '受選者的血', '那些自稱依米亞的維酷人相當受到巫妖王的重用，他們在寒冰皇冠中央地帶建立了一個屬於他們的城市。在我們進攻冰冠城塞之前尚需許多準備，而我們目前正面對的一樣就是進攻這些自稱「受選」於巫妖王的維酷人。$B$B前往他們的城市依米海姆，在他們的地盤上擊敗他們。讓他們明白誰才是這裡無庸置疑的強者。', '破天者號上的騎士長德羅許要你到依米海姆殺掉20個維酷族。', '', '去找冰冠冰川的騎士長德羅許。', '殺死依米海姆維酷人', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13337 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13337, 'zhTW', '鐵牆壁壘', '鐵牆壁壘眺望著逝往英雄山谷，在奧多薩的西側、稱霸著四面八方的週遭。只要壁壘還未攻下我們根本無法越雷池一步。駐防者是邪惡的葛林克爾與他詛咒神教的爪牙們。$B$B只要你能削弱葛林克爾的力量，至少我們的軍隊就多少能在進軍時與之抗衡。拿著這個歪曲符文，在壁壘盡頭葛林克爾的寶珠旁釋放符文之力，應該多少能夠引起這個召喚師的注意。', '擊敗邪惡的葛林克爾然後回報破天者號上的薩沙理安。', '', '去找冰冠冰川的薩沙理安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13338 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13338, 'zhTW', '寇普雷薩的守衛者', '寇普雷薩，又稱驚怖之門。將是阻止我們進攻冰冠城塞的最後一道防線。座落在焚焰地與冰冠後方、鐵牆壁壘的南側。但當我們的軍隊行軍至此必定早已筋疲力竭。$B$B我們必須事先削弱它的防禦，否則軍隊很有可能就在此瓦解。$B$B這個要塞駐守著巫妖王最可怕與最狂熱的手下。盡你的全力毀掉這些守衛，那麼或許我們還有一線希望。', '破天者號上的薩沙理安要你殺掉5個恐慌先驅者與 5個寇普雷薩守護者。', '', '去找冰冠冰川的薩沙理安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13339 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13339,'zhTW','擊破碎片','巫妖王的手下在科雷薩的牆頭安裝了三種水晶，分別是絕望碎片、恐懼碎片和苦難碎片。一旦我們的部隊抵達科雷薩城下，他就會使用這三種水晶進行攻擊。$B$B如果讓這些水晶完全發動，士兵們的精神就會被痛苦和恐懼壓垮。這樣一來，天災軍團就可以輕易消滅他們。$B$B去找到那些碎片，摧毀它們，把水晶給我帶回來。我們不能讓這些武器留在巫妖王手裡！','將破損的絕望碎片、破損的恐懼碎片和破損的苦難碎片交給破天號的薩薩里安。','','去冰冠冰川找破天號的薩薩里安。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13340 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13340, 'zhTW', '', '', '[Report to Ground Commander Xutjja at the edge of the glacier north of Ymirheim.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13341 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13341,'zhTW','協助突襲','我們需要更多人手來參加對伊米海姆的進攻。$B$B凡是有點腦子的戰士，都會告訴你維庫人是兇猛的戰士，不可輕侮。伊米亞戰士更是如此。他們總是不遺餘力地向我們證明，為什麼巫妖王更看重他們。$B$B這場戰鬥由地面指揮官庫普指揮。伊米海姆位於冰冠冰川的中心，庫普的部隊就駐紮在城市東面，靠近冰川的邊緣的地方。','向伊米海姆東面冰川上的地面指揮官庫普報道。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13342 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13342, 'zhTW', '[Not a Bug]', '[Alright, $g朋友：小妹;, time to plant a bug.$B$BRelax, it\'s not a bug exactly, but it\'ll serve our purposes.$B$BIn the northern portion of Aldur\'thar the cult\'s void summoners enslave demonic minions. Use this rod to siphon the dark matter from the corpses of these enslaved minions, and then use their summoning crystal to bring our little spy into being.$B$BUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.]', '[Thassarian, aboard the Skybreaker, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur\'thar.]', '', '去找冰冠冰川的薩沙理安。', '已召喚黑暗信使', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13343 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13343, 'zhTW', '[Mystery of the Infinite, Redux]', '[There you are! Or, were we just talking?$B$B<Chromie muses over the temporal possibilities.>$B$BAnyway, the Infinites are after you! Well, not you per-se. Rather, they\'re after the past version of you that defended the Hourglass of Eternity. You remember, right?$B$BThat was you back then, except it\'s you now too. Wait, that\'s not important. What is important is that you head back to the Bronze Dragonshrine and defend yourself and the hourglass from their attacks before you get erased from history!]', '[Chromie, at the top of Wyrmrest Temple, has asked you to travel once more to the Bronze Dragonshrine.$B$BOnce inside, place the Hourglass of Eternity on the ground and help your Past Self to protect it from the forces of the Infinite Dragonflight.]', '永恆沙漏已受保護，免受無盡龍族侵害', '去找龍骨荒野的克羅米。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13344 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13344,'zhTW','活動竊聽器','教徒們已經發現了你上次召喚出來的信使，$r。$B$B雖然我們已經得到了大量的情報，但是能夠監控詛咒教派的每一步行動對我們非常重要。$B$B轉至奧爾杜薩，用這根魔棒從那些被奴役的爪牙的屍體上吸取一些黑暗物質，然後使用詛咒教派的召喚水晶，再幫我們召喚出一個黑暗信使。$B$B在黑暗信使被發現之前，它將一直作為我們的耳目，小心地觀察敵人的行動。','破天號上的薩薩里安希望你去收集5份黑暗物質，然後在奧爾杜薩召喚出一名黑暗信使。','','去冰冠冰川找破天號的薩薩里安。','召喚黑暗信使','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13345 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13345, 'zhTW', '[Need More Info]', '[The Cult of the Damned are notorious for concocting grandiose plans that in the end, rarely succeed. But something feels different this time....$B$BPerhaps it\'s the proximity to the Lich King that has their fervor heightened. Whatever it is, they appear to be more confident than ever. We must know what feeds this bravado and then find a way to strip them of it!$B$BI believe the key lies with their researchers. Find out what they\'re up to and report back to me with the details.]', '[Thassarian, aboard the Skybreaker, wants you to collect the 3 pages of Cultists\' Research from the Cult Researchers at Aldur\'thar and use them to create the Cult of the Damned Thesis.]', '', '去找冰冠冰川的薩沙理安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13346 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13346, 'zhTW', '別讓邪惡伺機喘息', '這些傻瓜這次還真的歪打正著了，而且極有可能阻礙我們的計畫!$B$B這一區的領袖，雅路麥斯，在儀式中犧牲自己讓他的僕從引導能量注入他的靈魂。$B$B如果讓他持續修練，很快他們就能將他們主子的靈魂轉化成一股強大的對手。$B$B蒐集雅路麥斯的心臟、顱骨、權杖與長袍然後在雅路麥斯的殘骸結合。$B$B快點，$r! 在他尚未變得太過強大之前摧毀他!', '破天者號上的薩沙理安要你在奧多薩擊敗飛升的雅路麥斯。', '', '去找冰冠冰川的薩沙理安。', '擊敗飛升的雅路麥斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13347 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13347,'zhTW','浴火重生','我們的命運在出生時就已註定。伯瓦爾之死雖然是一場悲劇，但這也是不可避免的。$B$B現在你所能做的，就是向英雄致敬，$N。從戰場上把伯瓦爾的盾牌拿回來，將其交給你的國王。在你將盾牌交給瓦里安的時候，告訴他：“我們並沒有失去一切。死去的英雄將會使我們變得更加團結，齊心協力將邪惡從這個世界中驅趕出去。”$B$B他一定不能失去信仰。去吧，$N。你的人民需要一個英雄，他們需要你。','從天災之門安加薩的戰場上取回弗塔根之盾，把它交給暴風城要塞中的瓦里安·烏瑞恩國王。','','去暴風城找暴風要塞的瓦里安·烏瑞恩國王。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13348 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13348, 'zhTW', '', '', '[Return to Koltira Deathweaver aboard Orgrim\'s Hammer.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13349 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13349, 'zhTW', '[Cradle of the Frostbrood]', '[We need to keep our momentum going.  Let\'s not give the Scourge forces any respite.$B$BSindragosa\'s Fall lies east just beyond the Valley of Lost Hope.  The Cult of the Damned operate there, under close supervision of the Lich King\'s undead vrykul lackeys.$B$BIt is a place of great power, possibly a blue dragonflight graveyard.  The feared frostbrood are raised there from the bones of blue dragons.$B$BAn attack there would have great impact on the enemy\'s access to frost wyrms.  Are you up to it, $N?]', '[Koltira Deathweaver aboard Orgrim\'s Hammer wants you to slay 5 Wyrm Reanimators, 8 Cultist Corrupters and 3 Vrykul Necrolords at Sindragosa\'s Fall.]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13350 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13350, 'zhTW', '[No Rest For The Wicked]', '[It\'s Alumeth... He\'s growing in power again. I can sense it. Again his underlings are channeling power to his soul.$B$BIf he\'s allowed to rest, their efforts will soon transform him into a mighty adversary.$B$BReturn to his chamber in the north portion of Aldur\'thar. Combine his heart, skull, scepter and robes, then use his remains on the crystal there.$B$BHurry, $r! Destroy him before he becomes any more powerful!]', '[Thassarian, aboard the Skybreaker, wants you to defeat Alumeth the Ascended at Aldur\'thar.]', '', '去找冰冠冰川的薩沙理安。', '已擊殺昇華者阿魯梅斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13351 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13351, 'zhTW', '[Sneak Preview]', '[Progress is being made. We have a promising array of tactics that should gain us control of the death gate. There will doubtlessly be many casualties, but in the end,  we should be able to prevail - barring any interference from the Alliance.$B$BOur next focus will be Aldur\'thar, the gate of desolation. Fly down and become familiar with it and with the enemies posted there.$B$BWhen you return, I will have your missions prepared.]', '[Koltira, aboard Orgrim\'s Hammer, wants you to fly down to the gate of desolation, visiting the south, central, north, and northwest regions of the gate. ]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '已造訪奧督薩爾南方', '已造訪奧督薩爾中央', '已造訪奧督薩爾北方', '已造訪奧督薩爾西北方', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13352 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13352, 'zhTW', '[Drag and Drop]', '[The Cult of the Damned hold the gate of desolation, eh? No surprise there.$B$BTime to have a little fun. At the southern end of the gate, you mentioned there were new cultists being trained. They\'re almost certain to be holding a special item given to all initiates - an Orb of Illusion.$B$BThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.$B$BKill the fools until you find one, $c, then use it on a subjugator.]', '[Koltira, aboard Orgrim\'s Hammer, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur\'thar and use them on 3 Dark Subjugators there.]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '已拖拽並丟棄黑暗征服者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13353 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13353, 'zhTW', '[Drag and Drop]', '[Looks like those initiates are increasing in number again. You know what to do...$B$BAt the southern portion of the gate, the new cultists are being trained. They\'re certain to be holding a special item given to all initiates - an Orb of Illusion.$B$BThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.$B$BSlay the fools until you find some, then use them on the subjugators there.]', '[Koltira, aboard Orgrim\'s Hammer, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur\'thar and use them on 3 Dark Subjugators there.]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '已拖拽並丟棄黑暗征服者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13354 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13354, 'zhTW', '[Chain of Command]', '[Based on your report, and my knowledge of the Cult, they have an overseer managing the operation of each encampment on the gate.$B$BWhile taking their leaders down will only be a temporary setback, it will at least slow them down and keep them off-balance. And that, $r, is a worthy enough goal for now.$B$BSeek out these overseers and return to me when they have been dispatched.]', '[Koltira aboard Orgrim\'s Hammer wants you to go to Aldur\'thar and defeat Overseer Faedris, Overseer Savryn, Overseer Veraj, and Overseer Jhaeqon.]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '監工菲德里斯已擊殺', '監工賈昆已擊殺', '監工維拉吉已擊殺', '監工薩弗林已擊殺', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13355 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13355, 'zhTW', '[Cannot Reproduce]', '[I smell their cauldrons from here, but that\'s not plague they\'re cooking.$B$BPledges to the cult are forced to drink a concoction that steals their will and enslaves them forever to the Lich King.$B$BSome say the potion contains the twisted soul of a being who was tormented before being mercilessly slaughtered, but I\'ve never been able to reproduce it...$B$BFill this flask with a sample from each of the three cauldrons in the northwest region of the gate and bring it to Chief Engineer Copperclaw.]', '[Koltira aboard Orgrim\'s Hammer wants you to use the Partitioned Flask at each of the 3 Cultists\' Cauldrons at Aldur\'thar, then bring it to Chief Engineer Copperclaw.]', '', '去冰冠冰川找奧格瑞姆之錘的首席工程師銅爪。', '已收集藍色樣本', '已收集綠色樣本', '已收集黑暗樣本', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13356 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13356, 'zhTW', '[Retest Now]', '[This should do the trick!$B$BThose twisted hooligans are looking for souls to put in their crazy-juice? Then I say we help \'em out a bit!$B$BTake a swig of this - don\'t worry, I\'ve diluted it plenty... Its only effect will be to detect any cultist\'s essence once you\'ve defeated them.$B$BWhen you\'ve collected a bunch of essences, throw the writhing mass of twisted souls into any of their cauldrons.$B$BLet\'s see how they like a taste of their own medicine!]', '[Chief Engineer Copperclaw aboard Orgrim\'s Hammer wants you to throw a Writhing Mass into a cauldron at Aldur\'thar.]', '', '去冰冠冰川找奧格瑞姆之錘的首席工程師銅爪。', '蠕動之團已放逐', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13357 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13357, 'zhTW', '[Retest Now]', '[Those twisted cultists are looking for souls to put in their crazy-juice? Then let\'s help \'em out a bit!$B$BTake a swig of this - don\'t worry, I\'ve diluted it plenty... I\'m almost positive that its only effect will be to detect any cultist\'s essence.$B$BOnce you\'ve collected a bunch of \'em, throw the writhing mass of twisted souls in one of their cauldrons.$B$BLet\'s see how they like a taste of their own medicine!]', '[Chief Engineer Copperclaw aboard Orgrim\'s Hammer wants you to throw a Writhing Mass into a cauldron at Aldur\'thar.]', '', '去冰冠冰川找奧格瑞姆之錘的首席工程師銅爪。', '蠕動之團已放逐', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13358 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13358, 'zhTW', '[Not a Bug]', '[Alright, $g朋友：小妹;, time to plant a bug.$B$BRelax, it\'s not a bug exactly, but it\'ll serve our purposes.$B$BIn the northern portion of Aldur\'thar, the cult\'s void summoners enslave demonic minions. Use this rod to siphon the dark matter from the corpses of these enslaved minions, and then use the cultists\' summoning crystal to bring our little spy into being.$B$BUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.]', '[Koltira, aboard Orgrim\'s Hammer, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur\'thar.]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '已召喚黑暗信使', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13359 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13359, 'zhTW', '[Where Dragons Fell]', '[A whole brood of blue dragons fell here.  And now, one by one, they\'re being raised by his servants.$B$BHe raised the biggest of them all himself.  Bring me some bone dust from the whelps and I\'ll show you exactly how he did it.]', '[Matthias Lehner at Sindragosa\'s Fall wants you to obtain 6 Whelp Bone Dusts.]', '', '去找冰冠冰川的米希阿斯·薩爾奈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13360 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13360, 'zhTW', '', '', '[Speak to Matthias Lehner at the Court of Bones.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13361 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13361, 'zhTW', '[The Hunter and the Prince]', '[Before the prince became a king, he fought many battles... but only one where he came close to dying.$B$BIt was fought right here.  After you let me show you what happened, you\'ll understand everything.$B$BFind a bloodstained stone and pick it up from the floor.  You\'ll see what happened.]', '[Matthias Lehner in the Court of Bones wants you to look for a Bloodstained Stone and complete the Prince\'s Destiny.]', '', '去找冰冠冰川的米希阿斯·薩爾奈。', '王子的命運', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13362 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13362, 'zhTW', '', '', '[Report back to Koltira aboard Orgrim\'s Hammer.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13363 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13363, 'zhTW', '', '', '[Speak to Highlord Tirion Fordring at the Crusader\'s Pinnacle.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13364 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13364, 'zhTW', '[Tirion\'s Gambit]', '[Just this morning, my scouts informed me of a Cult of the Damned procession leaving from Icecrown Citadel to the Cathedral of Darkness, bearing an artifact.$B$BAnd now I learn that it might be Arthas\'s own heart... a thing containing the last bit of his remaining humanity.$B$BThis is a sign of the Light.  As long as such an artifact exists, there is a chance that Arthas Menethil can become a man again!$B$BMeet me at the cathedral\'s entrance.  Be sure to bring a cultist\'s hood -- we\'re going incognito.]', '[Tirion Fordring, at the Crusader\'s Pinnacle, wants you to obtain and wear a Cultist Acolyte\'s Hood and meet him at the entrance of the Cathedral of Darkness, northwest of Icecrown Citadel.]', '', '去找冰冠冰川的大領主提里奧‧弗丁。', '', '提里奧的謀略', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13365 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13365, 'zhTW', '[Not a Bug]', '[The cultists have discovered the last messenger you summoned, $r.$B$BWhile it was quite informative, it\'s important that we continue to monitor the cult\'s every move.$B$BUse this rod to siphon the dark matter from the corpses of enslaved minions at Aldur\'thar. Then use their summoning crystal to bring another dark messenger into being.$B$BUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.]', '[Koltira, aboard Orgrim\'s Hammer, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur\'thar.]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '已召喚黑暗信使', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13366 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13366, 'zhTW', '[Need More Info]', '[The Cult of the Damned are notorious for concocting grandiose plans that in the end, rarely succeed. But something feels different this time....$B$BPerhaps it\'s the proximity to the Lich King that has their fervor heightened. Whatever it is, they appear to be more confident than ever. We must know what feeds this bravado and then find a way to strip them of it!$B$BI believe the key lies with their researchers. Find out what they\'re up to and report back to me with the details.]', '[Koltira, aboard Orgrim\'s Hammer, wants you to collect the 3 pages of Cultists\' Research from the Cult Researchers at Aldur\'thar and use them to create the Cult of the Damned Thesis.]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13367 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13367, 'zhTW', '[No Rest For The Wicked]', '[These fools have actually stumbled upon something that could pose a serious threat to our plans!$B$BThe leader of this particular sect, Alumeth, has ritualistically sacrificed himself and now his underlings are channeling power to his soul.$B$BIf he\'s allowed to rest, their efforts will soon transform him into a mighty adversary.$B$BCombine his heart, skull, scepter and robes from around their chamber and use his remains on the crystal there.$B$BHurry, $r! Destroy him before he becomes any more powerful!]', '[Koltira, aboard Orgrim\'s Hammer, wants you to slay Alumeth the Ascended at Aldur\'thar.]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '已擊敗昇華者阿魯梅斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13368 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13368, 'zhTW', '[No Rest For The Wicked]', '[It\'s Alumeth... He\'s growing in power again. I can sense it. Again his underlings are channeling power to his soul.$B$BIf he\'s allowed to rest, their efforts will soon transform him into a mighty adversary.$B$BReturn to his chamber in the north portion of Aldur\'thar. Combine his heart, skull, scepter and robes, then use his remains on the crystal there.$B$BHurry, $r! Destroy him while there\'s still time!]', '[Koltira, aboard Orgrim\'s Hammer, wants you to slay Alumeth the Ascended at Aldur\'thar.]', '', '去冰冠冰川找奧格瑞姆之錘的寇爾提拉‧亡織者。', '已擊敗昇華者阿魯梅斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13369 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13369,'zhTW','造化弄人','根據普羅德摩爾女士的要求，我允許她作為外交使節轉至奧格瑪，質問部落的索爾酋長。我會派你協助她，保證她的安全。把奧格瑪的訊息帶回來告訴我。$B$B等你做好出發的準備之後，就去跟吉安娜談談吧。','陪同吉安娜·普羅德摩爾轉至卡利姆多大陸的奧格瑪，與部落的索爾酋長交談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13370 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13370,'zhTW','政變','你們的勇士伯瓦爾為保衛我們這個世界而犧牲了。我們部落同樣為了失去這樣一位偉大的英雄而感到悲傷，但部落並不應該為普特雷斯在天災之門發動的偷襲而負責。我們也因為這次背叛失去了一位偉大的英雄。$B$B告訴你的國王，我們會盡一切努力將這次事件的主謀繩之以法。我們也會盡全力避免與聯盟發生衝突，不過如果我們受到挑釁，部落也會毫不猶豫地進行自衛。','使用格羅瑪什堡壘中的傳送門返回暴風要塞，把索爾的訊息轉達給瓦里安·烏瑞恩國王。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13371 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13371,'zhTW','殺戮時刻','在你從奧格瑪回來之前，我就派了布羅爾和瓦莉拉轉至幽暗城。事實上，他們現在已經駐紮在通往廢墟的下水道入口外面，等待著我的命令。$B$B普羅德摩爾女士會開啟一道傳送門，穿過它就可以直達幽暗城外，與我們的部隊匯合。去向布羅爾和瓦莉拉報到吧，我稍後就到。','使用暴風要塞內的通往幽暗城的傳送門轉至幽暗城。到達目的地之後，向布羅爾·熊皮報到。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13372 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13372, 'zhTW', '[The Key to the Focusing Iris]', '[A potent thrumming of magical nature can be heard and felt emanating from the eye-shaped jewel dropped from Sapphiron\'s clutches. To mortal ears it is nearly painful to be in the presence of the stone.$B$BSurely such a powerful item of import can only be taken to the queen of the dragons, Alexstrasza the Life-Binder. Seek her counsel atop Wyrmrest Temple in the Dragonblight.]', '[Deliver the Key to the Focusing Iris to Alexstrasza the Life-Binder atop Wyrmrest Temple in the Dragonblight.]', '', '去找龍骨荒野的『生命守縛者』雅立史卓莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13373 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13373, 'zhTW', '[Fringe Science Benefits]', '[I installed our infra-green technology into commandeered bombers; it\'ll protect you on your first mission into enemy territory!  Speak with Rizzy Ratchwiggle to get a bomber, then fly into The Bombardment!$B$BYou\'ll have bombs and rockets and shields.  Keep the shields charged and use bombs on the ground Scourge at The Bombardment.  Come back after you hit your targets, and more work will await you.]', '[Fringe Engineer Tezzla wants you to kill 40 Bombardment Infantry, 8 Bombardment Captains and 15 Gargoyle Ambushers.]', '', '去找冰冠冰川的偏激工程師泰茲菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13374 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13374, 'zhTW', '[Amped for Revolt!]', '[$N, only our best pilots are given a mission like this, one deep, deep into enemy territory with only the power of infra-green technology to protect you!$B$BRequest another bomber from Rizzle, and this time fly it through the Valley of Lost Hope.  You have both air and ground targets on this mission, so keep your eyes open and your shields at full!$B$BGood luck!]', '[Fringe Engineer Tezzla wants you to kill Bombardment Infantry, Gargoyle Ambushers, Frostbrood Sentries and Scourge War Machines.$B$B]', '', '去找冰冠冰川的偏激工程師泰茲菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13375 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13375, 'zhTW', '[The Heroic Key to the Focusing Iris]', '[A potent thrumming of magical nature can be heard and felt emanating from the eye-shaped jewel dropped from Sapphiron\'s clutches. To mortal ears it is nearly painful to be in the presence of the stone.$B$BSurely such a powerful item of import can only be taken to the queen of the dragons, Alexstrasza the Life-Binder. Seek her counsel atop Wyrmrest Temple in the Dragonblight.]', '[Deliver the Heroic Key to the Focusing Iris to Alexstrasza the Life-Binder atop Wyrmrest Temple in the Dragonblight.]', '', '去找龍骨荒野的『生命守縛者』雅立史卓莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13376 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13376, 'zhTW', '[Total Ohmage: The Valley of Lost Hope!]', '[$N, the struggle continues.  Lucky for us, we\'re stocked up on bombs and rockets!  Time for another bombing mission  --  this one\'s a long one, through the Bombardment and into the Valley of Lost Hope.  Head back out with an infra-green bomber and blow those Scourge into little scourge-lets!]', '[Fringe Engineer Tezzla wants you to kill 50 Bombardment Infantry, 20 Gargoyle Ambushers, 12 Frostbrood Sentries and 12 Scourge War Machines.]', '', '去找冰冠冰川的偏激工程師泰茲菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13377 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13377, 'zhTW', '[The Battle For The Undercity]', '[Deep inside the bowels of the Undercity hides the assassin responsible for the deaths of Bolvar and our brave soldiers at the Wrath Gate.$B$BVarian has brought the full might of the Alliance with him to assist in the take down. Join him and Lady Proudmoore in the manhunt and earn your place among the greatest champions of the Alliance!$B$BSpeak to King Varian Wrynn when you are ready.]', '[Assist King Varian Wrynn and Lady Jaina Proudmoore in bringing Grand Apothecary Putress to justice! Report to King Varian Wrynn should you succeed.]', '協助瓦里安·烏瑞恩國王', '去暴風城找暴風要塞的瓦里安·烏瑞恩國王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13378 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13378, 'zhTW', '首席工程師考伯克拉', '與首席工程師考伯克拉談談。', '與首席工程師考伯克拉談談。', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13379 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13379, 'zhTW', '', '', '[Speak with Fringe Engineer Tezzla.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13380 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13380, 'zhTW', '[Leading the Charge]', '[Infra-green technology allows us to stay hidden here, right over the Scourge\'s nose!  What\'s more, we installed infra-green in specially constructed bombers... but not to hide them, no!  We use infra-green tech to shield them!$B$BSpeak with Karen No and request a bomber.  Fly it over the Bombardment... use its shields and turret to protect yourself, and use the bomb launcher to hit Scourge targets.  Practice well, then return to me and I\'ll have an even more vital mission for you!]', '[Kibli Killohertz wants you to kill 40 Bombardment Infantry, 8 Bombardment Captains and 15 Gargoyle Ambushers.]', '', '去找冰冠冰川的碁伯里‧基羅赫茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13381 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13381, 'zhTW', '[Watts My Target]', '[Put on your lucky socks, $n, and say your favorite prayers.  This next mission will test your wit and fortitude like a visit from the in-laws!$B$BRequest another bomber from Karen No.  Take it beyond The Bombardment and over the Valley of Lost Hope.  You have more targets this time, both on the land an in the air.  Keep your shields charged and your ammo loaded, $n!  I\'ll see you when it\'s over.]', '[Kibli Killohertz wants you to kill Bombardment Infantry, Gargoyle Ambushers, Frostbrood Sentries and Scourge War Machines.]', '', '去找冰冠冰川的碁伯里‧基羅赫茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13382 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13382, 'zhTW', '[Putting the Hertz: The Valley of Lost Hope]', '[The fight goes on!  Your new orders arrived for a long-range bombing mission through the Bombardment and into the Valley of Lost Hope -- when you\'re ready, ask Karen for a bomber and pour those bombs and rockets onto the Scourge!  ]', '[Kibli Killohertz wants you to kill 50 Bombardment Infantry, 20 Gargoyle Ambushers, 12 Frostbrood Sentries and 12 Scourge War Machines.]', '', '去找冰冠冰川的碁伯里‧基羅赫茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13383 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13383, 'zhTW', '', '', '[Chief Engineer Boltwrench wants you to find Kibli Killohertz at the hidden Alliance airport above Aldur\'thar, the Desolation Gate.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13384 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13384, 'zhTW', '[Judgment at the Eye of Eternity]', '[Now that you have access to the focusing iris it\'s time to put that key to use.$B$BAs much as I would like to see Malygos brought back into the fold, that\'s just not going to happen at this point. With everything that\'s at stake, it is the judgment of the other Dragon Aspects that the Spell-Weaver needs to be put down.$B$B<Krasus says this last with a great deal of trepidation.>$B$B$N, travel to the Eye of Eternity, confront Malygos and return with the Heart of Magic.]', '[Krasus atop Wyrmrest Temple in the Dragonblight wants you to return with the Heart of Magic.$B$BThis quest is for the Normal mode, 10-person version of The Eye of Eternity.]', '', '去找龍骨荒野的卡薩斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13385 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13385, 'zhTW', '[Heroic Judgment at the Eye of Eternity]', '[Now that you have access to the focusing iris it\'s time to put that key to use.$B$BAs much as I would like to see Malygos brought back into the fold, that\'s just not going to happen at this point. With everything that\'s at stake, it is the judgment of the other Dragon Aspects that the Spell-Weaver needs to be put down.$B$B<Krasus says this last with a great deal of trepidation.>$B$B$N, travel to the Eye of Eternity, confront Malygos and return with the Heart of Magic.]', '[Krasus atop Wyrmrest Temple in the Dragonblight wants you to return with the Heart of Magic.$B$BThis quest can be completed in both 10-person and 25-person versions of The Eye of Eternity.]', '', '去找龍骨荒野的卡薩斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13386 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13386, 'zhTW', '', '', '[Speak to Captain Kendall below Icecrown Citadel.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13387 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13387,'zhTW','保護現場','薩隆邪鐵炸彈已經安裝完畢，$N。但是我們只有一次機會，千萬別搞砸了。$B$B為了確保安全爆破，我們必須奪得這片本地的臨時控制權。先去削減天災士兵的數量吧。','冰冠堡壘的肯達爾上尉要你去殺死10只笨重的恐屍。','','去冰冠冰川找冰冠堡壘的肯達爾上尉。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13388 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13388,'zhTW','引爆！','事情進展得非常順利，準備引爆炸彈吧。$B$B它們就堆在深坑附近。我這就開始疏散人員。','冰冠堡壘下面的肯達爾上尉要你轉至附近的薩隆邪鐵炸彈堆旁邊，點燃引線。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13389 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13389,'zhTW','引線太短','在你點燃引線的時候，你發現它的燃燒速度比你想象中的要快了許多。$B$B炸彈就要爆炸了，只有馬上跳進深坑，並且不被炸下來的雜物砸到，你才有可能活下來。','在你被雜物砸中的地方尋找線索。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13390 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13390,'zhTW','黑暗中的聲音','這東西根本不是水晶，而是某種被寒冰包裹的器官。$B$B當你碰到它的時候，你的手上傳來一陣劇痛。你覺得自己的手彷彿被砍掉了一樣，但卻看到不任何傷口。$B$B當你再次集中精神時，你聽見附近有一個小男孩的聲音在飄蕩。$B$B“你真的不該那麼做的。”','在納扎納克：遺忘深淵裡調查這個聲音的來源。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13391 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13391,'zhTW','藏匿行蹤','你不該碰它的。但你已經碰過了，他很快就會來找你。$B$B他一定會找到你，除非你能躲藏起來，不讓他發現。$B$B如果你還想活下去，就去弄一些無面者的鮮血回來！','米斯希爾薩·阿奈爾要你收集3份無面者之血。','','去冰冠冰川找納扎納克：遺忘深淵的米斯希爾薩·阿奈爾。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13392 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13392, 'zhTW', '', '', '[Return to Thassarian aboard the Skybreaker.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13393 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13393,'zhTW','戰地維修','好吧，現在還不到慶功的時候。你順利地完成了引爆任務，極大地鼓舞了部隊計程車氣，我們要一鼓作氣，繼續戰鬥。$B$B士兵們在下面的曠野中發現了一架部落的大型攻城車，似乎還可以使用。惡鬼們好像正在拆卸它的零件。$B$B如果能將它重新組裝起來，我們一定能重創山谷裡的天災軍團。$B$B當然，你可以要面對為數眾多的敵人，但是我對你有信心！','破天號上的薩薩里安要你從食腐的惡鬼身上收集5塊攻城車零件，然後將它們帶去失落希望之谷的毀壞的攻城車旁。','','去冰冠冰川的失落希望之谷找毀壞的攻城車。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13394 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13394, 'zhTW', '[Do Your Worst]', '[You\'re going to use this machine against the Scourge?  You\'re not going to win against them like that.$B$BYou can destroy hundreds... even thousands of them.  But you won\'t win.  Not out here.$B$BWhen you\'re done playing with your machine, meet me to the north.  There is an old army encampment.  What I will show you will teach you a little bit about who you\'re up against.]', '[Use the Refurbished Demolisher to destroy 150 Decomposed Ghouls, 20 Frostskull Mages and 2 Bone Giants in the Valley of Lost Hope.  Speak to Matthias Lehner at the First Legion Forward Camp when you\'ve completed this task.]', '', '去找冰冠冰川的米希阿斯·薩爾奈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13395 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13395, 'zhTW', '[Army of the Damned]', '[You probably think you\'re quite strong -- fighting these undead and crushing their bones beneath your war machines.$B$BThat is nothing compared to the strength it took to create them.$B$BI saw the prince do it himself.  I can show you how it happened... if you\'d like.]', '[Matthias Lehner at the First Legion Forward Camp wants you to raise an army of 100 Ghoulish Minions.]', '', '去找冰冠冰川的米希阿斯·薩爾奈。', '已喚起食屍鬼爪牙', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13396 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13396,'zhTW','徒勞','現在你明白了嗎？派你們的人去對付王子的部隊，只會讓他們獲得更多的士兵。$B$B我也不指望你能明白……你的下場或許會和其它人一樣。你還是回到派你來的人身邊去吧，他們可能在擔心你了。','返回破天號，向薩薩里安覆命。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13397 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13397,'zhTW','辛德拉苟莎之殞','你真的天生適合這行，$n。你瞧，通常當我指派任務給其他士兵。他們完成的機率大概一半一半，至於回來的機率...呃，大概要再少一點。$B$B但是你，永遠是使命必達。就像地精鐘錶一樣精準!$B$B總之呢，我還有任務給你。辛德拉苟莎之殞，就在山谷東邊。那邊有許多的教徒正蠢蠢欲動，更別提冰霜巨龍的紛擾。我要你去給我教訓那些傢伙。$B$B我討厭那些教徒。','破天者號上的薩沙理安要你在辛德拉苟莎之殞殺掉5個巨龍復生者、8個教徒墮落者以及3個維酷死靈領主。','','去冰冠冰川找破天號的薩薩里安。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13398 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13398, 'zhTW', '[Where Dragons Fell]', '[A whole brood of blue dragons fell here.  And now, one by one, they\'re being raised by his servants.$B$BHe raised the biggest of them all himself.  Bring me some bone dust from the whelps and I\'ll show you exactly how he did it.]', '[Matthias Lehner at Sindragosa\'s Fall wants you to obtain 6 Whelp Bone Dusts.]', '', '去找冰冠冰川的米希阿斯·薩爾奈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13399 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13399, 'zhTW', '', '', '[Speak to Matthias Lehner at the Court of Bones.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13400 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13400, 'zhTW', '[The Hunter and the Prince]', '[Before the prince became a king, he fought many battles... but only one where he came close to dying.$B$BIt was fought right here.  After you let me show you what happened, you\'ll understand everything.$B$BFind a bloodstained stone and pick it up from the floor.  You\'ll see what happened.]', '[Matthias Lehner in the Court of Bones wants you to look for a Bloodstained Stone and complete the Prince\'s Destiny.]', '', '去找冰冠冰川的米希阿斯·薩爾奈。', '王子的命運', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13401 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13401, 'zhTW', '', '', '[Report back to Thassarian aboard the Skybreaker.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13402 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13402, 'zhTW', '', '', '[Speak to Highlord Tirion Fordring at the Crusader\'s Pinnacle.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13403 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13403, 'zhTW', '[Tirion\'s Gambit]', '[Just this morning, my scouts informed me of a Cult of the Damned procession leaving from Icecrown Citadel to the Cathedral of Darkness, bearing an artifact.$B$BAnd now I learn that it might be Arthas\'s own heart... a thing containing the last bit of his remaining humanity.$B$BThis is a sign of the Light.  As long as such an artifact exists, there is a chance that Arthas Menethil can become a man again!$B$BMeet me at the cathedral\'s entrance.  Be sure to bring a cultist\'s hood -- we\'re going incognito.]', '[Tirion Fordring, at the Crusader\'s Pinnacle, wants you to obtain and wear a Cultist Acolyte\'s Hood and meet him at the entrance of the Cathedral of Darkness, northwest of Icecrown Citadel.]', '', '去找冰冠冰川的大領主提里奧‧弗丁。', '', '提里奧的謀略', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13404 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13404, 'zhTW', '[Static Shock Troops: the Bombardment]', '[This is a short-ranged mission, over The Bombardment.  A good warm up.  Ready?]', '[Kibli Killohertz wants you to kill 50 Bombardment Infantry, 10 Bombardment Captains and 20 Gargoyle Ambushers.]', '', '去找冰冠冰川的碁伯里‧基羅赫茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13405 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13405,'zhTW','戰鬥的召喚：遠古海灘','北裂境的戰鬥並不僅僅是對抗巫妖王的部隊，我們還要與那些部落交鋒。$B$B最近我們在遠古海灘發現了一件強大的泰坦神器。你應該知道，我們矮人向來都是這類神器的保管者，因此我們也同樣有資格獲得這件新發現的神器。$B$B眼下，部落對這件神器表現出了極大的興趣，他們很顯然想要盜取神器，並用它來對付我們。聯盟必須不惜一切代價阻止他們！','在遠古海灘戰場中獲得一場勝利，然後向任意聯盟主城、冬握湖、達拉然或撒塔斯城中的聯盟准將覆命。','在遠古海灘獲勝','去找聯盟准將。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13406 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13406, 'zhTW', '[Riding the Wavelength: The Bombardment]', '[Ready to warm up with a short bombing mission?  You have your orders, and we have our bombers stocked and ready.]', '[Fringe Engineer Tezzla wants you to kill 50 Bombardment Infantry, 10 Bombardment Captains and 20 Gargoyle Ambushers.]', '', '去找冰冠冰川的偏激工程師泰茲菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13407 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13407,'zhTW','戰鬥的召喚：遠古海灘','雖然說我們開進北裂境是為了掃平天災軍團，但這並不代表我們應該對聯盟不聞不問。$B$B探險者協會的矮人已經發現了一件強大的泰坦聖物的所在地，如果讓聯盟拿到它的話，我們就沒好日子過了。$B$B去吧，$N，消滅我們的敵人。讓他們明白，無論在哪裡相遇，他們永遠都是我們不共戴天的死敵。','在遠古海灘戰場中獲得一場勝利，然後向任意部落主城、冬握湖、達拉然或撒塔斯城中的部落戰爭使者覆命。','在遠古海灘獲勝','去找部落戰爭使者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13408 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13408,'zhTW','地獄火半島的工事','地獄火堡壘與我們的軍隊一直有著小規模的衝突與交戰。當前，我們自己的領地大多守備穩固，但一直沒能對他們發動真正的進攻。為了籌備進攻，我們要首先佔領地獄火堡壘外圍的戰略要地。$B$B我們的斥候當前確定了三處互成犄角之勢的工事，希望你能協助這三處的防守。佔領所有工事之後回來向我報告。$B$B願你能在接下來的戰鬥中有好運氣，$N，毫無疑問，你得面對部落的威脅，他們也同樣想佔領這三處重要的工事。','佔領瞭望臺、競賽場和碎石嶺，然後向地獄火半島上榮耀堡內的委任官翠希·普羅維爾覆命。','','去地獄火半島找榮耀堡的委任官翠希·普羅維爾。','佔領瞭望臺','佔領競賽場','佔領碎石嶺','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13409 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13409,'zhTW','地獄火半島的工事','在我們的故鄉肆虐的所有地獄火堡壘邪獸人都必須要消滅乾淨！但要想攻擊地獄火堡壘，我們必須首先佔領堡壘外圍的幾處戰略要地。$B$B巡邏隊發現有三處工事正好適合我們的目的。但聯盟竟與我們不謀而合，現在已經派出部隊佔領了那裡！$B$B我要求你立刻阻止聯盟的行動，並佔領這些工事。協助我軍佔領工事之後，立刻回來向我報告。$B$B為了部落！','佔領瞭望臺、競賽場和碎石嶺，然後向地獄火半島上索爾瑪的傳令官布萊肯·黑眼覆命。','','去地獄火半島找索爾瑪的傳令官布萊肯·黑眼。','佔領瞭望臺','佔領競賽場','佔領碎石嶺','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13410 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13410,'zhTW','地獄火半島的工事','地獄火堡壘與我們的軍隊一直有著小規模的衝突與交戰。當前，我們自己的領地大多守備穩固，但一直沒能對他們發動真正的進攻。為了籌備進攻，我們要首先佔領地獄火堡壘外圍的戰略要地。$B$B我們的斥候當前確定了三處互成犄角之勢的工事，希望你能協助這三處的防守。佔領所有工事之後回來向我報告。$B$B願你能在接下來的戰鬥中有好運氣，$N，毫無疑問，你得面對部落的威脅，他們也同樣想佔領這三處重要的工事。','佔領瞭望臺、競賽場和碎石嶺，然後向地獄火半島上榮耀堡內的委任官翠希·普羅維爾覆命。','','去地獄火半島找榮耀堡的委任官翠希·普羅維爾。','佔領瞭望臺','佔領競賽場','佔領碎石嶺','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13411 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13411,'zhTW','地獄火半島的工事','在我們的故鄉肆虐的所有地獄火堡壘邪獸人都必須要消滅乾淨！但要想攻擊地獄火堡壘，我們必須首先佔領堡壘外圍的幾處戰略要地。$B$B巡邏隊發現有三處工事正好適合我們的目的。但聯盟竟與我們不謀而合，現在已經派出部隊佔領了那裡！$B$B我要求你立刻阻止聯盟的行動，並佔領這些工事。協助我軍佔領工事之後，立刻回來向我報告。$B$B為了部落！','佔領瞭望臺、競賽場和碎石嶺，然後向地獄火半島上索爾瑪的傳令官布萊肯·黑眼覆命。','','去地獄火半島找索爾瑪的傳令官布萊肯·黑眼。','佔領瞭望臺','佔領競賽場','佔領碎石嶺','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13412 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13412,'zhTW','科拉絲塔薩','你好，$c。能請你幫個忙嗎？$B$B紅龍萊洛拉斯負責駐守這座崗哨，他有個妹妹叫作科拉絲塔薩。科拉絲塔薩不顧萊洛拉斯的反對，到魔樞上層偵察藍龍的活動去了。$B$B他雖然嘴上不說，但是心裡還是很牽掛自己的妹妹。如果能得到科拉絲塔薩的訊息，他肯定會很高興的。$B$B請你去找到她，叫她放下自尊，給她的兄弟捎個訊息回來。','圖書館員塞爾拉要你去跟考達拉的科拉斯塔薩談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13413 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13413,'zhTW','展翅高飛！','凡人，你居然有勇氣靠近瑪裡苟斯的巢穴？還是說你只是因為無知才闖進這裡的？答案很快就可以揭曉了……$B$B我是一名經驗豐富的訓練師，專門為紅龍軍團訓練優雅的幼龍。我來這裡研究敵人的作戰手段，並向我珍愛的寵物們傳授有效的禦敵手段，以便將來能對付藍龍軍團的主子。$B$B為了讓你有機會證明自己的勇氣和實力，我可以讓你騎著我的幼龍去對付敵人的爪牙。$B$B只要你開口，就可以得到這個寶貴的機會……','考達拉魔樞上層的科拉絲塔薩要你騎著她的幼龍殺死5名鱗誓精英。','','去北風凍原找魔樞的科拉絲塔薩。','殺死鱗誓精英','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13414 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13414,'zhTW','展翅高飛！','我們又見面了，$r。我要承認，我對你越來越感興趣了。$B$B如果我沒猜錯的話，你是來練習空戰技巧的吧？$B$B像平時一樣，我的寵物已經做好準備，隨時可以去消滅敵人。$B$B只要你開口，就可以隨意調遣它們。','考達拉魔樞上層的科拉絲塔薩要你騎著她的幼龍殺死5名鱗誓精英。','','去北風凍原找魔樞的科拉絲塔薩。','殺死鱗誓精英','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13415 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13415, 'zhTW', '[The Library Console]', '[Norgannon\'s shell is within our reach, $N. Take the inventor\'s disk into the library\'s interior. There should be a console there that you can activate with the disk. I imagine Mimir stored more there than just Norgannon\'s shell. There are probably enough schematics stored there to keep Ironforge\'s engineers occupied for years!$B$BAnyway, use the disk to recover the shell. Hopefully, Mimir hasn\'t decided to put any more obstacles in our way. ]', '[Take the Inventor\'s Disk to the Inventor\'s Library Console inside the Inventor\'s Library.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13416 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13416, 'zhTW', '[The Library Console]', '[Norgannon\'s shell is within our reach, $N. Take the inventor\'s disk into the library\'s interior. There should be a console there that you can activate with the disk. I imagine Mimir stored more there than just Norgannon\'s shell. There are probably enough schematics stored there to keep Ironforge\'s engineers occupied for years!$B$BAnyway, bring the disk to the console. Hopefully, Mimir hasn\'t decided to put any more obstacles in our way. ]', '[Take the Inventor\'s Disk to the Inventor\'s Library Console inside the Inventor\'s Library.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13417 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13417,'zhTW','銅鬚兄弟','成功了！我們終於拿到拱心石了…它好美啊！我曾經多次環遊世界，但這東西又再次喚起了我的不安與興奮。不過，我想現在不是呆呆的站著看的時候了，我們得看點逃出去。$B$B跳上我的飛行器，在出去的路上幫忙掩護我！','陪同布萊恩·銅鬚，搭乘其飛行器前往霜堡。','陪同布萊恩·銅鬚前往霜堡','去風暴峭壁找冰霜堡的維羅格·冰嘯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13418 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13418, 'zhTW', '', '', '[Speak to Officer Van Rossem to secure passage to the Skybreaker in Icecrown, and then report to High Captain Justin Bartlett.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13419 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13419, 'zhTW', '', '', '[Speak to Sky-Reaver Klum to secure passage to Orgrim\'s Hammer in Icecrown, and then report to Sky-Reaver Korm Blackscar.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13420 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13420, 'zhTW', '[Everfrost]', '[This piece of ice has been submitted to immense pressures and exposed to natural magics from deep beneath the world\'s surface. In combination, these effects have yielded an ice that will never melt.$B$BKnowing little of these things, you resolve to bring the sample back to Dun Niffelem. Someone there is bound to be familiar with its properties.]', '[You are to return to Dun Niffelem and ask Calder about the piece of Everfrost.]$B$B已提供物品：', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13421 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13421, 'zhTW', '[Remember Everfrost!]', '', '', '', '去找祖爾德拉克的考德爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13422 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13422, 'zhTW', '[Maintaining Discipline]', '[You\'ve succeeded where others have failed.  Yet you cannot rest on your laurels.$B$BYou must show others what strength and commitment really mean.$B$BThe male insubordinates inside the Forlorn Mine need to be disciplined once again.  Show them sister... show them what it means to disobey us.]', '[Gretta the Arbiter in Brunnhildar Village wants you to use the Disciplining Rod on 6 Exhausted Vrykul inside the Forlorn Mine.]', '', '去找風暴峭壁的『仲裁者』格瑞塔。', '已管教精疲力盡的維库人', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13423 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13423,'zhTW','衛冕','每個人都對你的表現印象深刻，姊妹。但是不要放鬆了戒心!每個迷於聲名的挑戰者都將會上前挑戰你的海茲戰后頭銜。$B$B給這些傲慢自大的傢伙一點教訓，讓她們見識一下你的戰后本色。','布倫希爾達村的『仲裁者』格瑞塔要求你擊敗六個挑戰者。','','去風暴峭壁找布倫希爾達村的仲裁者格蕾塔。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13424 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13424,'zhTW','重返深淵','要保持最好的騎術，你就得每天與其他海迪尼爾切磋。$B$B返回尖牙之淵，把你的技術展現給她們看。她們會很感激像你這樣高超的人將她們擊敗的。','布倫希爾達村的『仲裁者』格瑞塔要你到尖牙之淵使用冰喉族母韁繩，然後擊敗6頭海茲競技戰熊。','','去風暴峭壁找布倫希爾達村的仲裁者格蕾塔。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13425 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13425, 'zhTW', '[The Aberrations Must Die]', '[It is not enough to demonstrate your prowess among your peers.  You must also fight our enemies, dear sister.$B$BThe Valkyrion traitors continue to mock our noble drake-riding traditions by rearing plagued proto-drakes.$B$BSeize the frost oil they wield and use it to freeze their abominable plagued eggs.]', '[Gretta the Arbiter in Brunnhildar Village wants you to go to Valkyrion and obtain Vials of Frost Oil from the Valkyrion Aspirants.  Use the Vials of Frost Oil to destroy 30 Plagued Proto-Drake Eggs.]', '', '去找風暴峭壁的『仲裁者』格瑞塔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13426 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13426, 'zhTW', '', '', '[Speak with Xarantaur at Camp Tunka\'lo.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13427 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13427,'zhTW','戰鬥的召喚：奧特蘭克山谷','事實上，我們在多線作戰，$g小子:小姑娘，而且我們不能把軍隊部署得太過分佈，否則我們可能會全盤皆輸！$B$B我們需要以天為單位來部署最關鍵的部隊，今天，奧特蘭克山谷的戰鬥最需要勇敢的士兵們！$B$B現在就出發吧，$N，去幫助雷矛遠征軍。我們不能就這麼看著霜狼氏族逃脫他們應受的懲罰。','在奧特蘭克山谷戰場中獲得一場勝利，然後向任意聯盟主城、達拉然、冬握湖或撒塔斯城中的聯盟准將覆命。','在奧特蘭克山谷獲勝','去找聯盟准將。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13428 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13428,'zhTW','戰鬥的召喚：奧特蘭克山谷','我們就快要把雷矛入侵者從奧特蘭克山谷趕走了，因此我們必須調動一切可能的增援力量來幫助霜狼氏族。$B$B一場決定性的勝利可以讓我們騰出足夠的資源在其它戰場上消滅聯盟的那些混蛋。$B$B出發吧，$N。聽從霜狼氏族的號令，去贏得無上的榮耀吧！','在奧特蘭克山谷戰場中獲得一場勝利，然後向任意部落主城、達拉然、冬握湖或撒塔斯城中的部落戰爭使者覆命。','在奧特蘭克山谷獲勝','去找部落戰爭使者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13429 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13429, 'zhTW', '[A Distraction for Akama]', '[<Xi\'ri pulses with lights as the Aldor and Scryer forces around him respond to his orders.  Xi\'ri\'s army is ready to push Illidan\'s forces back and create a distraction for Akama.  The naaru awaits your request to begin the attack.>]', '[Ensure that Akama and Maiev enter the Black Temple in Shadowmoon Valley after Xi\'ri\'s forces create a distraction.]', '幫助阿卡瑪與麥維進入黑暗神廟', '去找影月谷的希瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13430 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13430, 'zhTW', '[Trial of the Naaru: Magtheridon]', '[Four trials you must pass before you are deemed worthy by the naaru.$B$BOnly one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon, deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!]', '[A\'dal in Shattrath City wants you to slay Magtheridon.]', '', '去找沙塔斯城的阿達歐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13431 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13431,'zhTW','卡達什聖杖','將製作聖杖所需的元素徽記給我帶回來！$B$B土靈徽記在屠龍者格魯爾手中，他就躲在刀鋒山的巢穴裡。$B$B另一枚徽記是夜之魘的心臟，據說這隻神秘的野獸居住在先知麥迪文的高塔內。$B$B迅速行動吧！','將土靈徽記和燦爛徽記交給盤牙水庫奴隸圍欄的異教徒斯卡希斯。','','去找奴隸圍欄的異教徒斯卡希斯。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13432 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13432,'zhTW','永恆水瓶','伊利丹從永恆之井中取出了七瓶水。他將其中三瓶倒入海加爾山顛的湖泊中，由此形成了第二口永恆之井。歲月流逝，剩下的四瓶水已不知去向。$B$B黑暗之門開啟後，我們得知伊利丹將兩瓶水交給了他的副官凱爾薩斯和瓦絲琪。取回殘餘的永恆之水，我們可以利用它開啟通往近代或是遠古時期的海加爾山的時光通道。我們必須維持海加爾聖戰的事件不被改變。','時光之穴的索莉多米要你從盤牙水庫的瓦絲琪那裡取回瓦絲琪的水瓶殘餘，並從風暴要塞的凱爾薩斯·逐日者那裡取回凱爾薩斯的水瓶殘餘。','','去找塔納利斯的索莉多米。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13433 AND `locale` = 'zhTW';
