INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13502, 'zhTW', '[A Tisket, a Tasket, a Noblegarden Basket]', '[Here... take this Egg Basket and go hunting for Brightly Colored Eggs. Return to me with the basket when you\'ve found ten Noblegarden Chocolates.]', '[The Noblegarden Vendor wants you to collect 10 Noblegarden Chocolates and return them along with the Egg Basket.]', '', '去找貴族花園商販。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13503 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13503, 'zhTW', '[A Tisket, a Tasket, a Noblegarden Basket]', '[Here... take this Egg Basket and go hunting for Brightly Colored Eggs. Return to me with the basket when you\'ve found ten Noblegarden Chocolates.]', '[The Noblegarden Merchant wants you to collect 10 Noblegarden Chocolates and return them along with the Egg Basket.]', '', '去找貴族花園商人。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13524 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13524,'zhTW','逃離銀溪鎮','你……你不是他們的人？快！快把我放出來！$B$B我們必須馬上逃往琥珀松木營地！一旦杜蒙特中尉發現這些傢伙的真面目，就會夷平這個鎮子！','開啟木籠，幫助聯盟斥候逃出銀溪鎮。抵達琥珀松木營地後向杜蒙特中尉彙報情況。','','去灰白之丘找琥珀松木營地的杜蒙特中尉。','逃出銀溪鎮','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13538 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13538, 'zhTW', '[Southern Sabotage]', '[The three towers south of the Wintergrasp river are draining power from the Fortress! $B$BDestroy Shadowsight Tower, Flamewatch Tower or Winter\'s Edge Tower, then return to me. Remember, only siege vehicles can damage a tower, so make sure to protect them from the Horde!]', '[Destroy Shadowsight Tower, Flamewatch Tower or Winter\'s Edge Tower and return to Tactical Officer Ahbramis in Wintergrasp.]', '', '去找冬握堡壘的戰術軍官阿布拉米斯。', '摧毀三座南方塔樓中的其中一座', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13539 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13539, 'zhTW', '[Toppling the Towers]', '[While the Alliance may be pounding on our doors, a true tactician looks beyond the obvious.$B$B"Attack him where he is unprepared, appear where you are not expected."$B$B$n, I need you to travel across the Wintergrasp River and destroy one of the three towers to the south. Our Warlocks report that the towers are draining power we could use to bolster our own troops.$B$BReturn to me once you\'ve destroyed a tower.]', '[Destroy Shadowsight Tower, Flamewatch Tower, or Winter\'s Edge Tower and return to Tactical Officer Kilrath in Wintergrasp.]', '', '去找冬握堡壘的戰術軍官科伊瑞斯。', '摧毀冬握堡壘南方的一座塔樓', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13541 AND `locale` = 'zhTW';
