INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13692, 'zhTW', '[The Sword and the Sea]', '[My sword was lost at sea.  Catch it and bring it back!]', '[Old Man Barlo in Crystalsong Forest wants you to bring him the Sword of Knighthood.]', '', '去找泰羅卡森林的老人巴洛。', '', '', '', '', 0);
