INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13697, 'zhTW', '[The Valiant\'s Charge]', '[In your training as a valiant, you\'ll have the chance to test your skills against valiants representing other cities. Although a valiant\'s battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents.$B$BThe valiants are a spirited lot, competing amongst themselves for honor and notoriety.$B$BTrain as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.]', '[Bring 25 Valiant\'s Seals to Mokra the Skullcrusher at the Argent Tournament Grounds.]', '', '去找冰冠冰川的『碎顱者』莫克拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13699 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13699, 'zhTW', '[The Valiant\'s Challenge]', '[You are nearly ready to compete on behalf of Stormwind in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade.$B$BGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants\' Ring on the western edge of the grounds. The squire will call out your opponent when you\'re ready.$B$BAfter the battle is concluded, we will speak of the outcome.]', '[Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Marshal Jacob Alerius at the Argent Tournament Grounds.$B$BIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.]', '', '去找冰冠冰川的傑科布‧亞雷瑞斯元帥。', '已擊敗銀色冠軍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13700 AND `locale` = 'zhTW';
