INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13713,'zhTW','驍士的挑戰','你幾乎已具備代表鐵爐堡參加技擊大賽的資格了。為了要證明你足以加入城市代表隊名單中，你必須要擊敗一位銀白十字軍的勇士。$B$B前往亭閣外的獸欄，裝備你的長槍並乘上坐騎。到聯賽場地西側的銀白驍士競技場找侍從丹尼。等你準備好之後，侍從會叫出你的對手。$B$B等戰鬥結束之後，我們再來談一談結果。','和侍從丹尼談談以召喚你的對手。一旦你擊敗銀白勇士，回到銀白聯賽場地去找菈娜‧頑錘。$B$B如果你弄丟了長槍，你可以從任何一個靠近獸欄或白銀誓盟亭閣的長槍架再拿一把。','','去找冰冠冰川的拉娜·硬錘。','擊敗銀白勇士','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13714 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13714, 'zhTW', '[The Valiant\'s Charge]', '[In your training as a valiant, you\'ll have the chance to test your skills against valiants representing other cities. Although a valiant\'s battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents.$B$BThe valiants are a spirited lot, competing amongst themselves for honor and notoriety.$B$BTrain as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.]', '[Bring 25 Valiant\'s Seals to Lana Stouthammer at the Argent Tournament Grounds.]', '', '去找冰冠冰川的菈娜‧頑錘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13715 AND `locale` = 'zhTW';
