INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13750, 'zhTW', '[The Grand Melee]', '[The grand melee is the most important of the tournament\'s competitions. We know everyone\'s looking forward to seeing us in the competition. To that end, we\'ve been honing our skills against the valiants representing the other Alliance capitals.$B$BI suggest you do the same.$B$BGo to the stables outside the pavilion, equip your lance, mount the stabled turbostrider, and challenge the valiants. They wait in the Alliance Valiants\' Ring just outside our tent.$B$B]', '[Bring 3 Marks of the Valiant to Flickin Gearspanner at the Argent Tournament Grounds.$B$BIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.]', '', '去找冰冠冰川的佛立金‧輪扳。', '', '', '', '', 0);
