INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13770, 'zhTW', '[The Edge Of Winter]', '[Curse that death knight for breaking my sword!$B$BIn southern Crystalsong Forest, overlooking the Crystal Vice\'s exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.$B$BBring it to the center of Winter\'s Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.$B$BProve your worth and earn the weapon that she has guarded for so long, $N.]', '[Zul\'tore at the Argent Tournament Grounds wants you to bring him Winter\'s Edge.]', '', '去找冰冠冰川的祖爾拓。', '', '', '', '', 0);
