INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13771, 'zhTW', '[A Valiant\'s Field Training]', '[The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.$B$BTravel to the area southwest of the Valley of Fallen Heroes and north of Corp\'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.]', '[Shadow Hunter Mezil-kree at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.]', '', '去找冰冠冰川的暗影獵手梅齊克里。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13772 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13772, 'zhTW', '[The Grand Melee]', '[The grand melee is the most important of the tournament\'s competitions. Victory will not be easy, but I am confident that we will win. You must practice with your mount until the two of you work as one.$B$BIt will help prepare you for the rigors of tournament combat.$B$BGo to the stables outside the pavilion, equip your lance, mount the stabled Darkspear raptor, and challenge the valiants. They wait in the Horde Valiants\' Ring just outside our tent.$B$B]', '[Bring 3 Marks of the Valiant to Gahju at the Argent Tournament Grounds.$B$BIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.]', '', '去找冰冠冰川的嘎尤。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13773 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13773, 'zhTW', '[A Blade Fit For A Champion]', '[I\'ve heard that the Alliance champions are seeking after ancient blades for their warriors. We can\'t afford to let them have that kind of advantage.$B$BThere\'s an old legend from Grizzly Hills about a maiden cursed with a frog\'s form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, $N. Otherwise, you\'ll catch warts.]', '[Retrieve the Ashwood Brand and bring it to Runok Wildmane at the Argent Tournament Grounds.]', '', '去找冰冠冰川的魯諾克‧蠻鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13774 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13774, 'zhTW', '[A Worthy Weapon]', '[Of all the times to have such rotten luck!$B$BMy tournament blade has gone missing and I need it for a match this afternoon.$B$BOne of the bards tells me that travelers used to present winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest\'s northwestern border with Icecrown. Gather the flowers and take them to Drak\'Mar lake in northeastern Dragonblight, near its border with Zul\'Drak and Grizzly Hills.]', '[Bring the Blade of Drak\'Mar to Runok Wildmane at the Argent Tournament Grounds.]', '', '去找冰冠冰川的魯諾克‧蠻鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13775 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13775, 'zhTW', '[The Edge Of Winter]', '[Curse that death knight for breaking my sword!$B$BIn southern Crystalsong Forest, overlooking the Crystal Vice\'s exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.$B$BBring it to the center of Winter\'s Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.$B$BProve your worth and earn the weapon that she has guarded for so long, $N.]', '[Runok Wildmane at the Argent Tournament Grounds wants you to bring him Winter\'s Edge.]', '', '去找冰冠冰川的魯諾克‧蠻鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13776 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13776, 'zhTW', '[A Valiant\'s Field Training]', '[The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.$B$BTravel to the area southwest of the Valley of Fallen Heroes and north of Corp\'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.]', '[Dern Ragetotem at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.]', '', '去找冰冠冰川的德恩‧狂暴圖騰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13777 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13777, 'zhTW', '[The Grand Melee]', '[The grand melee is the most important of the tournament\'s competitions. Victory will not be easy, but I am confident that we will win. You must practice with your mount until the two of you work as one.$B$BIt will help prepare you for the rigors of tournament combat.$B$BGo to the stables outside the pavilion, equip your lance, mount the stabled Mulgore kodo, and challenge the valiants. They wait in the Horde Valiants\' Ring just outside our tent.]', '[Bring 3 Marks of the Valiant to Anka Clawhoof at the Argent Tournament Grounds.$B$BIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.]', '', '去找冰冠冰川的安卡‧爪蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13778 AND `locale` = 'zhTW';
