INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13787, 'zhTW', '[The Grand Melee]', '[The grand melee is the most important of the tournament\'s competitions. Victory will not be easy, but I am confident that we will win. You must practice with your mount until the two of you work as one.$B$BIt will help prepare you for the rigors of tournament combat.$B$BGo to the stables outside the pavilion, equip your lance, mount the stabled Silvermoon hawkstrider, and challenge the valiants. They wait in the Horde Valiants\' Ring just outside our tent.$B$B]', '[Bring 3 Marks of the Valiant to Aneera Thuron at the Argent Tournament Grounds.$B$BIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.]', '', '去找冰冠冰川的安妮拉‧修倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13788 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13788, 'zhTW', '來自上空的威脅', '自從你揭發了詛咒神教的潛伏者之後，銀白十字軍就加倍了守衛的人數。他們認為詛咒神教不可能只因為黑騎士被擊敗就停止行動。$B$B根據銀白十字軍的斥候回報，有一隻叫做寒冽之喉的冰霜巨龍率領了一批神教突襲隊。如果我們沒有攔截他們，聯賽就會受到他們的攻擊。斥候回報看見寒冽之喉就在西南方，在鐵牆壁壘和奧多薩之間的地區飛行。', '銀白聯賽的克羅科·天譴剋星要你擊敗寒冽之喉和3個教徒投彈手。', '', '去找冰冠冰川的克羅科‧天譴剋星。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13789 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13789, 'zhTW', '[Taking Battle To The Enemy]', '[The coliseum is perched in the most dangerous part of the world, $N. The territory we\'ve taken from the Scourge has been paid for in blood and misery, yet the enemy continues to strike back with a seemingly limitless army. To make matters worse, this undead army is supported and assisted by mortal sympathizers, the Cult of the Damned.$B$BGo forth into Icecrown and slay any cultists you encounter. ]', '[Cellian Daybreak at the Argent Tournament Grounds wants you to kill 15 members of the Cult of the Damned. You may kill Cult of the Damned members in any part of Icecrown.]', '', '去找冰冠冰川的瑟利安‧破曉。', '詛咒教派成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13790 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13790, 'zhTW', '[Among the Champions]', '[As a champion, you have mastered the art of mounted combat, besting challengers of all levels. When the tournament begins, those you have defeated will have redoubled their efforts and will seek to avenge their losses to you.$B$BIt would be wise to continue practicing your skills against the combatants waiting in the Ring of Champions. Equip your lance, go to the stables on the southern side of the grounds. then mount up on any mount you\'re permitted to use, and face the champions.]', '[Bring 4 Marks of the Champion to Luuri at the Argent Tournament Grounds.$B$BIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.$B$B]', '', '去找冰冠冰川的露莉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13791 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13791, 'zhTW', '[Taking Battle To The Enemy]', '[While we all play at mock combat, it will do us good to remember that the real enemy surrounds us. The Argent Crusade wants to use competition to find the best fighters, but we can tell that by who returns from battle. Let\'s show the paladins that we are willing to take battle to the Cult of the Damned, even while making preparations for the tournament.$B$BGo forth into Icecrown and slay any of the cultists you encounter. They have a strong presence around Aldur\'thar and Deathspeaker\'s Watch.]', '[Zor\'be the Bloodletter at the Argent Tournament Grounds wants you to kill 15 members of the Cult of the Damned. You may kill cultists in any part of Icecrown.]', '', '去找冰冠冰川的『放血者』佐爾必。', '詛咒教派成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13793 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13793, 'zhTW', '[Among the Champions]', '[As a champion, you have mastered the art of mounted combat, overcoming challengers of all levels. You must make certain that you can defeat anyone you face when the tournament begins.$B$BYou should continue honing your own skills and learning more about the weaknesses of your opponents. Champions representing all cities practice in the Ring of Champions near the stables. Go to the stables, equip your lance, and pick any mount you\'re permitted to ride, then face the champions.]', '[Bring 4 Marks of the Champion to Illyrie Nightfall at the Argent Tournament Grounds.$B$BIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.]', '', '去找冰冠冰川的伊黎芮‧夜暮。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13794 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13794, 'zhTW', '', '', '[Speak with Eadric the Pure at the Argent Tournament Grounds.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13795 AND `locale` = 'zhTW';
