INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13807,'zhTW','旗幟:聯賽邀請','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13809 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13809, 'zhTW', '[Threat From Above]', '[Highlord Tirion Fordring has doubled the guard since your exposure of the Cult of the Damned\'s infiltrator. He doesn\'t believe that they will stop just because their Black Knight has been defeated.$B$BOur skytalon scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party. If we don\'t intercept them, the tournament will come under attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur\'thar.]', '[Eadric the Pure at the Argent Tournament wants you to defeat Chillmaw and 3 Cultist Bombardiers.]', '', '去找冰冠冰川的『純淨者』埃卓克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13810 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13810, 'zhTW', '[Taking Battle To The Enemy]', '[The coliseum is perched in the most dangerous part of the world, $N. The territory we\'ve taken from the Scourge has been paid for in blood and misery, yet the enemy continues to strike back with a seemingly limitless army. To make matters worse, this undead army is supported and assisted by mortal sympathizers, the Cult of the Damned.$B$BGo forth into Icecrown and slay any cultists you encounter.]', '[Cellian Daybreak at the Argent Tournament Grounds wants you to kill 15 members of the Cult of the Damned. You may kill cultists in any part of Icecrown.]', '', '去找冰冠冰川的瑟利安‧破曉。', '詛咒教派成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13811 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13811, 'zhTW', '[Among the Champions]', '[As a champion, you have mastered the art of mounted combat, besting challengers of all levels. When the tournament begins, those you have defeated will have redoubled their efforts and will seek to avenge their losses.$B$BIt would be wise to continue honing your own skills and learning from your opponents. Champions representing all cities practice in the Ring of Champions. Equip your lance, mount up on any mount you\'re entitled to use at the stables, and face the champions.]', '[Bring 4 Marks of the Champion to Luuri at the Argent Tournament Grounds.$B$BIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.]', '', '去找冰冠冰川的露莉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13812 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13812, 'zhTW', '[Threat From Above]', '[The Argent Crusade has doubled the guard since your exposure of the Cult of the Damned\'s infiltrator. They know the cultists won\'t stop until they\'ve destroyed this area and thwarted the tournament.$B$BThe Argent Crusade\'s scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party.$B$BYou must intercept and destroy them before they attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur\'thar.]', '[Crok Scourgebane at the Argent Tournament wants you to defeat Chillmaw and 3 Cultist Bombardiers.]', '', '去找冰冠冰川的克羅科‧天譴剋星。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13813 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13813, 'zhTW', '[Taking Battle To The Enemy]', '[While we all play at mock combat, it will do us good to remember that the real enemy surrounds us. The Argent Crusade wants to use competition to find the best fighters, but we can tell that by who returns from battle. Let\'s show the paladins that we are willing to take battle to the Cult of the Damned, even while making preparations for the tournament.$B$BGo forth into Icecrown and slay any of the cultists you encounter. They have a strong presence around Aldur\'thar and Deathspeaker\'s Watch.]', '[Zor\'be the Bloodletter at the Argent Tournament Grounds wants you to kill 15 members of the Cult of the Damned. You may kill cultists in any part of Icecrown.]', '', '去找冰冠冰川的『放血者』佐爾必。', '詛咒教派成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13814 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13814, 'zhTW', '[Among the Champions]', '[As a champion, you have mastered the art of mounted combat, overcoming challengers of all levels. You must make certain that you can defeat anyone you face when the tournament begins.$B$BYou should continue honing your own skills and learning more about the weaknesses of your opponents. Champions representing all cities practice in the Ring of Champions near the stables. Go to the stables, equip your lance, pick any mount you can ride, then face the champions in practice bouts.]', '[Bring 4 Marks of the Champion to Illyrie Nightfall at the Argent Tournament Grounds.$B$BIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.]', '', '去找冰冠冰川的伊黎芮‧夜暮。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13816 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13816, 'zhTW', '[Heroic: The Celestial Planetarium]', '[Listen, $g小夥子：小姑娘;!  Azeroth\'s fate is at stake here.$B$BOur only chance is to get to the Celestial Planetarium in time to find this Algalon and stop him from beaming back any messages to his Titan masters.$B$BLocate the Celestial Planetarium and come back with any information you get.  We might still have some time to prepare for Algalon\'s arrival.]', '[Prospector Loren at the Archivum in Ulduar wants you to locate the entrance to the Celestial Planetarium.]', '已找到天體天文館的入口', '去找奧杜爾的勘察員洛倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13817 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13817, 'zhTW', '[Heroic: Archivum Data Disc]', '[This platinum disc is surprisingly symmetrical and devoid of any scratches or imperfections.  Engraved along its edge, bold runes spell out the word "ARCHIVUM."$B$BThere must be a device inside Ulduar capable of reading the disc.]', '[Bring the Archivum Data Disc to the Archivum Console in Ulduar.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13818 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13818, 'zhTW', '[Heroic: Algalon]', '[You really did it, $N.  Take the sigils to the Archivum Console and see if you can gain access to the Celestial Planetarium.$B$BYou best hurry, $g小夥子：小姑娘;.  Time is of the essence.]', '[Bring the Sigils of the Watchers to the Archivum Console in Ulduar.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13819 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13819, 'zhTW', '[Heroic: All Is Well That Ends Well]', '[We\'d best hurry now, $N.  We\'re going to have to transmit the reply-code from Dalaran.$B$BTake it to Rhonin, I will meet you there.]', '[Take the Reply-Code Alpha to Rhonin in Dalaran.]', '', '去找水晶歌森林的羅甯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13820 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13820, 'zhTW', '', '', '[Speak with Bezzle Blastbolt at the Argent Tournament Grounds.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13821 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13821, 'zhTW', '[Heroic: Freya\'s Sigil]', '[Freya\'s Sigil is going to be one of the tougher ones, I reckon.$B$BAccording to the Archivum, the essence of the Sigil is tied to her three elder servants, Brightleaf, Ironbranch and Stonebark.  Should any of the elders be harmed, the Sigil\'s integrity will be compromised.$B$BSparing the elders, however, means that Freya will be more powerful when you face her.$B$BWhat can I say, $N.  We\'re stuck between a rock and hard place.]', '[Prospector Loren at the Archivum in Ulduar wants you to obtain Freya\'s Sigil.$B$BFor more information on obtaining Freya\'s Sigil consult the Archivum Console.]', '', '去找奧杜爾的勘察員洛倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13822 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13822, 'zhTW', '[Heroic: Hodir\'s Sigil]', '[Hodir\'s Sigil won\'t be easy to obtain.  Not only are ye going to have to defeat Hodir himself, but yer going to have to do it before he destroys the chest that contains it!$B$BCheck the Archivum console if you need more information.  That thing contains more knowledge than all of the world\'s libraries put together!]', '[Prospector Loren at the Archivum in Ulduar wants you to obtain Hodir\'s Sigil.$B$BFor more information on obtaining Hodir\'s Sigil, consult the Archivum Console.]', '', '去找奧杜爾的勘察員洛倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13823 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13823, 'zhTW', '[Heroic: Thorim\'s Sigil]', '[Thorim\'s not himself, $N.  He\'s come under a dark influence.$B$BAn evil presence under the guise of an illusion pretends to be his lost wife, Sif.$B$BYe can\'t let him be overcome by this impostor\'s spell.  If he does, the location of his sigil might forever be lost!$B$BYer going to have to beat some sense into him and yer going to have to do it quick.$B$BAs always, the Archivum Console will give ye all the gory details... even the ones ye don\'t like.]', '[Prospector Loren at the Archivum in Ulduar wants you to obtain Thorim\'s Sigil.$B$BFor more information on obtaining Thorim\'s Sigil consult the Archivum Console.]', '', '去找奧杜爾的勘察員洛倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13824 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13824, 'zhTW', '[Heroic: Mimiron\'s Sigil]', '[Mimiron\'s a clever one.  His entire abode is rigged with some sort of self-destruction mechanism.$B$BUnfortunately yer gonna have to race against it if ye want to get his sigil.  Check the Archivum Console for more details if ye need them.]', '[Prospector Loren at the Ulduar Archivum wants you to obtain Mimiron\'s Sigil.$B$BFor more information on obtaining Mimiron\'s Sigil consult the Archivum Console.]', '', '去找奧杜爾的勘察員洛倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13825 AND `locale` = 'zhTW';
