INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13827, 'zhTW', '巫妖王之怒 任務', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13828 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13828, 'zhTW', '[Mastery Of Melee]', '[The heart of tournament competition is mounted melee combat. Take this lance and mount the stabled Quel\'dorei steed just outside the pavilion.$B$BOnce you\'re mounted, seek out Jeran Lockwood. He\'s on the northern edge of the tournament grounds at the training area east of the Aspirants\' Ring. Jeran will instruct you on how to use your defenses to keep you safe while attacking a melee target at close range.]', '[Equip your lance, then mount the Stabled Quel\'dorei Steed outside the pavilion. Speak to Jeran Lockwood and use Thrust 5 times on a Melee Target, then return to Arcanist Taelis at the Argent Tournament Grounds.]', '', '去找冰冠冰川的秘法師泰利斯。', '傑蘭·洛克伍德的建議', '對近戰目標使用突刺', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13829 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13829, 'zhTW', '[Mastery Of Melee]', '[The heart of tournament competition is mounted melee combat. Take this lance and mount the stabled Sunreaver hawkstrider just outside the pavilion.$B$BOnce you\'re mounted, seek out Jeran Lockwood. He\'s on the northern edge of the tournament grounds at the training area east of the Aspirants\' Ring. Jeran will instruct you on how to use your defenses to keep you safe while attacking a melee target at close range.]', '[Equip your lance, then mount the Stabled Sunreaver Hawkstrider outside the pavilion. Speak to Jeran Lockwood and use Thrust 5 times on a Melee Target, then return to Magister Edien Sunhollow at the Argent Tournament Grounds.]', '', '去找冰冠冰川的博學者艾狄恩‧日谷。', '傑蘭·洛克伍德的建議', '對近戰目標使用突刺', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13830 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13830, 'zhTW', '[The Ghostfish]', '[Any Northrend angler worth $g他的：她的; salt knows about the pygmy suckerfish.  It\'s not edible, but sometimes useful to alchemists.$B$BThere is, however, a stealthy fish that hides among the suckerfish in the River\'s Heart of Sholazar Basin.  The phantom ghostfish.  When out of water, they become increasingly translucent until they fade away completely.  Some hypothesize they return to Sholazar, and others are more... superstitious.$B$BI want you to catch this fish and discover its secret by any means!]', '[Marcia Chase in Dalaran City wants you to discover the mystery of the Phantom Ghostfish.]', '發現幽靈魚的謎團', '去找達拉然的瑪西亞·切斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13832 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13832, 'zhTW', '[Jewel Of The Sewers]', '[Hard to believe that most people fish in the Dalaran Sewers for giant rats and mutated fish.  Especially when those waters are filled with priceless jewelry - discarded by broken hearted fools, thieves, and careless drunks.$B$BThe trick is to let your hook drag the bottom and don\'t pull up too hard when you get something.  Try it out, $N.  I\'d be willing to trade whatever you find for a few trinkets of my own.]', '[Marcia Chase in Dalaran City wants you to bring her a piece of Corroded Jewelry.]', '', '去找水晶歌森林的瑪西亞·切斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13833 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13833, 'zhTW', '[Blood Is Thicker]', '[The bloodtooth is a feisty little fish used in a recipe to cure infected wounds.  We could use some of them, if you\'re up to it.$B$BAs the name suggests, they\'ve a hunger for blood.  The only way I know how to catch the little devils is by creating a blood pool and fishing in it.$B$BGet yourself covered in blood - just slaughter a beast in the Borean Tundra - and then jump in the water.  It\'ll wash right off and create the perfect fishing spot.]', '[Marcia Chase in Dalaran City wants you to bring her 5 Bloodtooth Frenzies.]', '', '去找水晶歌森林的瑪西亞·切斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13834 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13834, 'zhTW', '[Dangerously Delicious]', '[The best fishing is often the most dangerous.  Wintergrasp boasts a bountiful catch for the brazen.$B$BIn fact, it\'s the only place to catch the fabled Terrorfish - a fish both lethal and delicious.  Bring me some, and we\'ll have something to discuss.]', '[Marcia Chase in Dalaran City wants you to bring her 10 Terrorfish.]', '', '去找水晶歌森林的瑪西亞·切斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13835 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13835, 'zhTW', '[Mastery Of The Shield-Breaker]', '[You\'ll need to learn how to break through an opponent\'s defenses to succeed in mounted combat. Take this lance and mount the stabled Quel\'dorei steed just outside the pavilion.$B$BOnce you\'re mounted, seek out Valis Windchaser. He\'ll be on the northern edge of the tournament grounds at the training area east of the Aspirants\' Ring. Valis will teach you the basics of using a ranged shield breaker attack to make a ranged target vulnerable.]', '[Equip your lance and mount the Stabled Quel\'dorei Steed outside the pavilion. Speak to Valis Windchaser and use Shield-Breaker on 2 vulnerable Ranged Targets, then return to Scout Shalyndria at the Argent Tournament Grounds.]', '', '去找冰冠冰川的斥候夏琳卓雅。', '瓦利斯·逐風者的建議', '對虛弱的遠程目標使用碎盾', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13836 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13836, 'zhTW', '[Disarmed!]', '[I\'ve received word of an unfortunate accident at the Dalaran prison; a guard had his arm severed and thrown into the water by a particularly vicious inmate.$B$BOur first aid clinic promises they can reattach the arm if we bring it back.$B$BYou fish long enough in the water outside the prison, and I\'d bet my favorite fishing pole that arm will surface.  Find that arm, and bring it to Olisarra the Kind here in Dalaran.  She\'ll know what to do.]', '[Olisarra the Kind in Dalaran City wants you to return the Severed Arm to her.]', '', '去找達拉然的仁慈的歐莉珊拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13837 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13837, 'zhTW', '[Mastery Of The Charge]', '[Your strongest attack in mounted combat is undoubtedly the charge. Take this lance and mount the stabled Quel\'dorei steed just outside the pavilion.$B$BOnce you\'re mounted, speak with Rugan Steelbelly. He\'s on the northern edge of the tournament grounds at the training area east of the Aspirants\' Ring. Rugan will tell you how to use this powerful ability and teach you some basic strategies.]', '[Equip your lance and mount the Stabled Quel\'dorei Steed outside the pavilion. Speak to Rugan Steelbelly and Charge 2 vulnerable Charge Targets, then return to Avareth Swiftstrike at the Argent Tournament Grounds.]', '', '去找冰冠冰川的阿凡瑞斯‧迅擊。', '魯根·鋼腹的建議', '衝鋒虛弱的衝鋒目標', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13838 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13838, 'zhTW', '[Mastery Of The Shield-Breaker]', '[You\'ll need to learn how to break through an opponent\'s defenses to succeed in mounted combat. Take this lance and mount the stabled Sunreaver hawkstrider just outside the pavilion.$B$BOnce you\'re mounted, seek out Valis Windchaser. He\'ll be on the northern edge of the tournament grounds at the training area east of the Aspirants\' Ring. Valis will teach you the basics of using a ranged shield breaker attack to make a ranged target vulnerable.]', '[Equip your lance and mount the Stabled Sunreaver Hawkstrider. Speak to Valis Windchaser and use Shield-Breaker on 2 vulnerable Ranged Targets, then return to Galathia Brightdawn at the Argent Tournament Grounds.]', '', '去找冰冠冰川的加拉西雅‧明曦。', '瓦利斯·逐風者的建議', '對虛弱的遠程目標使用碎盾', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13839 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13839, 'zhTW', '[Mastery Of The Charge]', '[Your strongest attack in mounted combat is undoubtedly the charge. Take this lance and mount the stabled Sunreaver hawkstrider just outside the pavilion.$B$BOnce you\'re mounted, speak with Rugan Steelbelly. He\'s on the northern edge of the tournament grounds at the training area east of the Aspirants\' Ring. Rugan will tell you how to use this powerful ability and teach you some basic strategies.]', '[Equip your lance and mount the Stabled Sunreaver Hawkstrider outside the pavilion. Speak to Rugan Steelbelly and Charge 2 vulnerable Charge Targets, then return to Amariel Sunsworn at the Argent Tournament Grounds.]', '', '去找冰冠冰川的艾瑪瑞爾‧日誓。', '魯根·鋼腹的建議', '衝鋒虛弱的衝鋒目標', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13840 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13840, 'zhTW', '[REUSE]', '["Cluck... cluck... cluck... BACAW!$B$BCluck... cluck... cluck."$B$BThe chicken looks up at you and then starts to scratch its claws into the ground. You think it is spelling out a word, but you are not sure what it is. Could it be... S-A-L-D-E-A-N? Before you can ask, the chicken turns away and goes about its business.]', '[Find some Special Chicken Feed and return to your befriended chicken. When you find it, /cheer at it before trying to give it the Special Chicken Feed.]', '', '去找雞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13843 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13843, 'zhTW', '', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13845 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13845, 'zhTW', '[Sealed Vial of Poison]', '[This vial of poison looks particularly dangerous.  Perhaps someone in Dalaran might be interested in it.]', '[Bring the Seal Vial of Poison to Alchemist Cinesra in the Dalaran Sewers.]', '', '去找達拉然的鍊金師席尼斯拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13846 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13846, 'zhTW', '[Contributin\' To The Cause]', '[The bestest of the champions come to the chapel to hear the argent confessor speak every day.$B$BYou should see how much she inspires them, $N. Not only do they fight for the Argent Crusade, but they put a lot of money into the collection basket when I take it around.$B$BMaybe you\'d like to contribute too?]', '[Speak with Squire Artie to contribute 10 gold to the Argent Crusade\'s cause.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13847 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13847, 'zhTW', '[At The Enemy\'s Gates]', '[Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy\'s stronghold of Icecrown Citadel.$B$BIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp\'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King\'s minions.$B$BDo not fear the masses of boneguard footmen, $N, for they can easily be trampled under your horse\'s hooves.]', '[Captain Joseph Holley at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, and 3 Boneguard Lieutenants.]', '', '去找冰冠冰川的約瑟夫‧霍雷上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13850 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13850,'zhTW','毒藥的免疫力','你想騎毒皮暴掠龍嗎？恐怕我有些壞訊息要告訴你。$B$B毒皮暴掠龍全身都是毒，從血液到唾沫，連皮膚表面都有毒素。你要是爬上去，不出幾個小時就會中毒而死。$B$B在我賣給你毒皮龍之前，你必須先獲得抵抗毒素的能力，這要花很長的時間，非常長……你需要去在戰鬥中沐浴毒血，要洗許多次。如果你真的對此感興趣，那麼你要知道，毒皮暴掠龍經常會出現在沼澤地的北部本地，你一直向西北方走，就能找到那裡了。','安戈洛環形山的莫維克說，如果你能被毒皮暴掠龍的血染上20次毒，就可以安全地騎它了。攻擊毒皮魔暴龍，有一定機率會中毒。','','去安戈洛環形山找沼澤地的莫維克。','灑上毒皮暴掠龍的血','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13851 AND `locale` = 'zhTW';
