INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13860, 'zhTW', '[At The Enemy\'s Gates]', '[Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy\'s stronghold of Icecrown Citadel.$B$BIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp\'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King\'s minions.$B$BDo not fear the masses of boneguard footmen, $N, for they can easily be trampled under your horse\'s hooves.]', '[Handler Dretch at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, 3 Boneguard Lieutenants.]', '', '去找冰冠冰川的管理者德瑞齊。', '', '', '', '', 0);
