INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14178,'zhTW','戰鬥的召喚：阿拉希盆地','$g小夥子:姑娘，在多條戰聯機同時進行戰爭的關鍵在於我們不能讓軍力過於分佈，否則我們就會面臨全面潰敗的風險。$B$B每一天，我們都要對關鍵的軍力佈置進行調整。今天我們必須派遣援軍的地方是阿拉希盆地。$B$B趕快到那裡去，並帶著勝利的訊息回來見我，$N決不能允許那些部落的惡徒佔據那裡本應屬於我們的資源！','在阿拉希盆地戰場中獲得一場勝利，然後向任意聯盟主城、冬握湖、達拉然或撒塔斯城中的聯盟准將覆命。','阿拉希盆地的勝利','去找聯盟准將。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14179 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14179,'zhTW','戰鬥的召喚：風暴之眼','對抗部落的戰鬥是沒有盡頭的，$N。即使在外域，對於地盤的爭奪和世代積累的仇恨同樣引發了一場場戰鬥。$B$B現在，進入風暴之眼，為聯盟奪取輝煌的勝利，就像我們在艾澤拉斯做的一樣。','在風暴之眼戰場中獲得一場勝利，然後向任意聯盟主城、冬握湖、達拉然或撒塔斯城中的聯盟準將覆命。','風暴之眼的勝利','去找聯盟準將。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14180 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14180,'zhTW','戰鬥的召喚：戰歌峽谷','銀翼哨兵正在竭盡全力保衛戰歌峽谷中的森林。我們必須援助他們，不只是因為我們熱愛森林，更因為那片森林是守護聯盟領土的天然屏障。$B$B現在我們比以往任何時候都更需要它們。所以我們必須立刻向那裡派遣援軍。否則梣谷森林很快就會被部落砍成荒蕪地了！','在戰歌峽谷戰場中獲得一場勝利，然後向任意聯盟主城、冬握湖、達拉然或撒塔斯城中的聯盟准將覆命。','戰歌峽谷的勝利','去找聯盟准將。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14181 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14181,'zhTW','戰鬥的召喚：阿拉希盆地','阿拉希盆地就要落進聯盟的手裡了。我們必須立刻向那裡派出援軍，否則我們在那裡的一切努力都將前功盡棄。$B$B不要有任何遲誤，$c，趕快到阿拉希盆地去，粉碎那裡的敵人。勝利屬於部落！','在阿拉希盆地戰場中獲得一場勝利，然後向任意部落主城、冬握湖、達拉然或撒塔斯城中的部落戰爭使者覆命。','阿拉希盆地的勝利','去找部落戰爭使者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14182 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14182,'zhTW','戰鬥的召喚：風暴之眼','我們要在所有地方將敵人擊潰，無論是在艾澤拉斯還是外域。$B$B絕不能允許聯盟在風暴之眼取得優勢。我們要在今天打敗他們……等到明天，一切都太遲了！','在風暴之眼戰場中獲得一場勝利，然後向任意部落主城、冬握湖、達拉然或撒塔斯城中的部落戰爭使者覆命。','風暴之眼的勝利','去找部落戰爭使者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14183 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14183,'zhTW','戰鬥的召喚：戰歌峽谷','聯盟真是一群陰險的敵人，$N。他們竟然以保衛梣谷森林的名義入侵了我們在貧瘠之地的領土。$B$B今天，我們要將敵人徹底從我們的土地上趕走。趕快到戰歌峽谷去，奪回本應屬於我們的東西！','在戰歌峽谷的戰場上贏得一場競賽，然後去見任意部落主城、冬握湖、達拉然或者沙塔斯的部落戰爭使者。','戰歌峽谷的勝利','去找部落戰爭使者。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14185 AND `locale` = 'zhTW';
