INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24218,'zhTW','戰鬥的召喚：戰歌峽谷','銀翼哨兵透過戰鬥來保護戰歌峽谷的森林。我們幫助他們，並不是因為我們愛好樹木，而是因為森林為聯盟領地提供了天然的屏障。$B$B今天他們那裡的情勢非常危急，遠遠超過以往任何時候。我們必須立刻派出援軍，除非我們希望看到梣谷成為貧瘠之地的附屬地！','在戰歌峽谷戰場中獲得一場勝利，然後向任意聯盟主城、冬握湖、達拉然或撒塔斯城中的聯盟准將覆命。','在戰歌峽谷獲勝','去找聯盟准將。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24219 AND `locale` = 'zhTW';
