INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24221,'zhTW','戰鬥的召喚：阿拉希盆地','阿拉希盆地快要讓聯盟奪走了，我們必須儘快派出援兵，否則我們所做的一切都將成為徒勞。$B$B不要拖延了，$c。去阿拉希盆地消滅敵人，勝利屬於部落！','在阿拉希盆地戰場中獲得一場勝利，然後向任意部落主城、冬握湖、達拉然或撒塔斯城中的部落戰爭使者覆命。','在阿拉希盆地獲勝','去找部落戰爭使者。','','','','',0);
