INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24428, 'zhTW', '[A Most Puzzling Circumstance]', '[You have accomplished the truly impossible. The brood mother of the Black Dragonflight lies dead at your feet. Seize her head and deliver it to Zardeth of the Black Claw.]', '[Take the Head of Onyxia to Zardeth of the Black Claw in the basement of the Slaughtered Lamb.]', '', '去找暴風城的黑爪加爾德斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24429 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24429, 'zhTW', '[A Most Puzzling Circumstance]', '[You have accomplished the truly impossible. The brood mother of the Black Dragonflight lies dead at your feet. Seize her head and deliver it to Neeru Fireblade.]', '[Take the Head of Onyxia to Neeru Fireblade in the Cleft of Shadow.]', '', '去找奧格瑪的尼爾魯·火刃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24431 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24431, 'zhTW', '[Waterlogged Recipe]', '[This appears to be the remains of a mixture for potent wine.  Perhaps the proprietor of One More Glass in Dalaran would be interested in it....]', '[Bring the Waterlogged Recipe to Christi Stockton in the Dalaran city.]', '', '去找達拉然的克利斯蒂·斯托克頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24442 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24442, 'zhTW', '科瓦迪爾的作戰計畫', '看著手中的攻擊計劃，你發現了一張東部王國和卡林多的地圖，且各個重大的據點都被劃上了標記。當你閱讀其中記載的細節，你發現科瓦迪爾的船長們正策劃著一連串的毀滅性攻擊。$B$B根據記載，這些攻擊即將在喚霧者伊格瓦「祈求迷霧之心」後展開。如果你可以取得位於赫魯斯加臺地西邊，喚霧者的洞穴之中所顯現的預兆，並通知審判者瑪瑞爾·真心，那或許你就可以延緩他們的攻擊。', '取得迷霧之心，並將其與科瓦迪爾攻擊計畫一同交給銀白聯賽場地的審判者瑪瑞爾·真心。', '', '去找冰冠冰川的審判者瑪瑞爾‧真心。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24451 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24451, 'zhTW', '[An Audience With The Arcanist]', '[I\'ve placed an enchantment on the tabard that should allow you to slip past the Silver Enclave\'s defenses for a short period of time. You should have enough time to find your way up to the top level of the Silver Enclave and meet up with the Silver Covenant\'s man there, known as Arcanist Tybalin.$B$BWhile disguised, obtain the copy of Ancient Dragonforged Blades that his men borrowed from Wyrmrest, and return the book to me.]', '[Retrieve the Ancient Dragonforged Blades tome from Arcanist Tybalin.]', '', '去找達拉然的博學者哈索瑞爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24454 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24454, 'zhTW', '[Return To Caladis Brightspear]', '[We must get this book to Caladis Brightspear immediately. Would you bring it to him? I cannot rely on anyone else to transport the book and you have proven adept at keeping the Sunreavers at bay.$B$BTake it with you to Quel\'Delar\'s rest, south of the Argent Tournament Grounds in Icecrown. Caladis and the sword will be waiting. The sooner we can identify the blade, the sooner we can claim it.]', '[Bring Ancient Dragonforged Blades to Caladis Brightspear at Quel\'Delar\'s Rest.]', '', '去找卡拉迪斯‧亮矛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24461 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24461, 'zhTW', '[Reforging The Sword]', '[We cannot allow Quel\'Delar to remain broken and disgraced. Take the remnants of the sword, along with the battered hilt you discovered, and venture into the Pit of Saron within Icecrown Citadel.$B$BIn the pit, the Lich King uses slaves to mine, process, and transform saronite ore. This infused saronite is what we will use to rebuild Quel\'Delar.$B$BYou must gather bars of infused saronite and capture the forgemaster\'s hammer, then bring them to the forgemaster\'s anvil and reforge the sword.]', '[Obtain 5 Infused Saronite Bars and the Forgemaster\'s Hammer and use them to make the Reforged Quel\'Delar.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24476 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24476, 'zhTW', '[Tempering The Blade]', '[At last, the pieces of Quel\'Delar are rejoined and the blade is whole, but it cannot see battle until you have tempered it. That jagged saronite edge is brittle and will shatter the moment it strikes anything.$B$BDeep in Icecrown Citadel\'s Forge of Souls is a place where the blade can safely be tempered. Take Quel\'Delar with you to the abode of the Devourer of Souls and look for the crucible. Plunge the blade into the crucible to temper it and bring it back to me in The Frozen Halls.]', '[Temper the Reforged Quel\'Delar in the Crucible of Souls.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24480 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24480, 'zhTW', '[The Halls Of Reflection]', '[You have reforged and tempered the sword, yet it sits quietly in its sheath, showing no signs of the power it should possess. You say the sword pulls you, as though it possesses a will?$B$BDare you bring it where it wishes to go? It\'s not right that the sword should be this silent and this insistent, yet I fear that if you do not take the sword to its destination, we will never learn why. Take it into Icecrown Citadel\'s Halls of Reflection, but be on your guard! I\'ll be waiting for you in The Frozen Halls.]', '[Bring your Tempered Quel\'Delar to Sword\'s Rest inside the Halls of Reflection. ]', '', '', '將奎爾德拉帶往沉思之殿', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24498 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24498, 'zhTW', '[The Path to the Citadel]', '[They\'ve put our captured soldiers to work in the quarry! Kill their captors and set them free, hero, and do it quickly. We will need their aid when we confront Scourgelord Tyrannus.]', '[Free 15 Alliance Slaves and kill Forgemaster Garfrost.]', '', '', '聯盟奴隸已解放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24499 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24499, 'zhTW', '[Echoes of Tortured Souls]', '[I cannot thank you enough for coming. We\'re severely undermanned to be risking a venture into the citadel, but opportunities like this are too rare to pass up.$B$BI\'m awaiting the arrival of champions from the coliseum, but if your reputation holds true, you should be more than equipped to fight through the forge yourself. Clear the way to the far side and secure the passage to the Pit of Saron. We will need to hold it to move our men further into the citadel.$B$BPlease hurry, $n. We\'re counting on you.]', '[Kill Bronjahm and the Devourer of Souls to secure access to the Pit of Saron.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24500 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24500, 'zhTW', '[Wrath of the Lich King]', '[Uther knew a great deal about how Arthas might be defeated. It\'s hard to believe that there is much hope of defeating Arthas upon the steps of his own throne. And who will take up the crown of Lich King if it comes to that?$B$BMany questions remain, but the answers that you\'ve uncovered may be critical to ensuring Arthas\' defeat. You need to find Jaina and escape the Lich King while there\'s still time.]', '[Find Lady Jaina Proudmoore and escape the Halls of Reflection]', '', '', '尋找珍娜·普羅德摩爾', '逃離巫妖王', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24506 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24506, 'zhTW', '', '', '[Enter The Forge of Souls from the side of Icecrown Citadel and locate Lady Sylvanas Windrunner.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24507 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24507, 'zhTW', '[The Path to the Citadel]', '[They\'ve put our captured soldiers to work in the quarry. Kill their captors and set them free, $c, and do it quickly. We will need their aid when we confront Scourgelord Tyrannus.]', '[Free 15 Horde Slaves and kill Forgemaster Garfrost.]', '', '', '部落奴隸已解放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24508 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24508,'zhTW','臨時任務記錄','','','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24509 AND `locale` = 'zhTW';
