INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24609, 'zhTW', '[A Gift for the Lord of Ironforge]', '[Did you want to make a Lovely Charm Bracelet for the Lord of Ironforge? I\'m sure he\'d be thrilled.$B$BDo you already have a Lovely Charm Collector\'s Kit?]', '[Present a Lovely Charm Bracelet to King Magni Bronzebeard in Ironforge.]', '', '去找丹莫羅的國王麥格尼·銅鬚。', '', '', '', '', 0);
