INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24610, 'zhTW', '[A Gift for the High Priestess of Elune]', '[Did you want to make a Lovely Charm Bracelet for the High Priestess of Elune? I\'m sure she\'d be thrilled.$B$BDo you already have a Lovely Charm Collector\'s Kit?]', '[Present a Lovely Charm Bracelet to Tyrande Whisperwind in Darnassus.]', '', '去達納蘇斯找神殿花園的泰蘭妲·語風。', '', '', '', '', 0);
