INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24611, 'zhTW', '[A Gift for the Prophet]', '[Did you want to make a Lovely Charm Bracelet for the Prophet of the Exodar? I\'m sure he\'d be thrilled.$B$BDo you already have a Lovely Charm Collector\'s Kit?]', '[Present a Lovely Charm Bracelet to Prophet Velen in the Exodar.]', '', '去找預言者費倫。', '', '', '', '', 0);
