INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24612, 'zhTW', '[A Gift for the Warchief]', '[Did you want to make a Lovely Charm Bracelet for the Warchief? I\'m sure he\'d be thrilled.$B$BDo you already have a Lovely Charm Collector\'s Kit?]', '[Present a Lovely Charm Bracelet to Thrall in Orgrimmar.]', '', '去找奧格瑪的索爾。', '', '', '', '', 0);
