INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24613, 'zhTW', '[A Gift for the Banshee Queen]', '[Did you want to make a Lovely Charm Bracelet for the Banshee Queen? I\'m sure she\'d be thrilled.$B$BDo you already have a Lovely Charm Collector\'s Kit?]', '[Present a Lovely Charm Bracelet to Lady Sylvanas Windrunner in Undercity.]', '', '去找希瓦娜斯·風行者女士。', '', '', '', '', 0);
