INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24614, 'zhTW', '[A Gift for the High Chieftain]', '[Did you want to make a Lovely Charm Bracelet for the High Chieftain? I\'m sure he\'d be thrilled.$B$BDo you already have a Lovely Charm Collector\'s Kit?]', '[Present a Lovely Charm Bracelet to Cairne Bloodhoof in Thunder Bluff.]', '', '去莫高雷找雷霆崖的凱恩·血蹄。', '', '', '', '', 0);
