INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24615, 'zhTW', '[A Gift for the Regent Lord of Quel\'Thalas]', '[Did you want to make a Lovely Charm Bracelet for the Regent Lord of Quel\'Thalas? I\'m sure he\'d be thrilled.$B$BDo you already have a Lovely Charm Collector\'s Kit?]', '[Present a Lovely Charm Bracelet to Lor\'themar Theron in Silvermoon City.]', '', '去找銀月城的洛索瑪·塞隆。', '', '', '', '', 0);
