INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24629, 'zhTW', '[A Perfect Puff of Perfume]', '[You look like a real go-getter, $c. How about we work out a little win-win scenario?$B$BCrown\'s looking to offer samples of our latest holiday-themed products to as many potential customers as possible. Help us share the love, and we\'ll give you discounts on some great Crown merchandise!$B$BYour time, our money, friend. What do you say?]', '[Spray 10 people with the Crown Perfume Sprayer.]', '', '', '已提供樣本', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24635 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24635, 'zhTW', '[A Cloudlet of Classy Cologne]', '[You seem the enterprising sort, $c. How about we make a little deal?$B$BCrown wants to offer samples of our latest holiday-themed products to as many potential customers as we can. Help us share the love while earning some fantastic Crown merchandise!$B$BYour time, our money, friend. What do you think?]', '[Spray 10 people with the Crown Cologne Sprayer.]', '', '', '已提供樣本', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24636 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24636, 'zhTW', '[Bonbon Blitz]', '[I can see you\'ve got an eye for opportunity, $c. What do you say we make a little coin together?$B$BCrown needs to push samples of our latest holiday-themed products to every potential customer in the city. Help us share the love, and we\'ll share some of that amazing Crown merchandise with you!$B$BYour time, our money, friend. We got a deal?]', '[Toss 10 people samples from the Crown Chocolate Sampler.]', '', '', '已提供樣本', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24638 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24638,'zhTW','粉碎皇冠藥劑公司','這賬本上提到了多處地點，我需要你前去調查並採取相應的行動，夥計。不能再拖下去了。$B$B這是我要你調查的一處地點：就在奧格瑪大門外，西面！他們肯定不會幹什麼好事。到那兒去解決掉他們。$B$B噢，對了，如果你發現了某些危險的大玩意兒需要當場銷燬的話，就朝它丟這個炸彈。','消滅5個皇冠僕從，並使用滑栓的氪金炸彈摧毀在杜隆塔爾的奧格瑪大門西方的一臺藥劑車。然後返回奧格瑪，去見偵探斯奈普·滑栓。','','轉至奧格瑪，去找力量谷的偵探斯奈普·滑栓。','摧毀藥劑車','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24645 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24645, 'zhTW', '[Crushing the Crown]', '[This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.$B$BHere\'s an entry I want you to check out: it\'s just outside Ambermill in Silverpine Forest. That can\'t be good. Get out there and rough \'em up.$B$BOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.]', '[Kill 5 Crown Thugs and use Snagglebolt\'s Khorium Bomb to destroy one chemical wagon outside of Ambermill in Silverpine Forest, then return to Detective Snap Snagglebolt in Orgrimmar.]', '', '去找奧格瑪的力量谷的警探史內卜‧凸栓。', '化學馬車已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24647 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24647, 'zhTW', '[Crushing the Crown]', '[This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.$B$BHere\'s an entry I want you to check out: it\'s just outside the village of Hillsbrad in -- you guessed it -- Hillsbrad Foothills. That can\'t be good. Get out there and rough \'em up.$B$BOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.]', '[Kill 5 Crown Dusters and use Snagglebolt\'s Khorium Bomb to destroy one chemical wagon just outside of Hillsbrad Village in Hillsbrad Foothills, then return to Detective Snap Snagglebolt in Orgrimmar.]', '', '去找奧格瑪的力量谷的警探史內卜‧凸栓。', '化學馬車已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24648 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24648,'zhTW','粉碎皇冠藥劑公司','這賬本上提到了多處地點，我需要你前去調查並採取相應的行動，夥計。不能再拖下去了。$B$B這是我要你調查的一處地點：就在塵泥沼澤的塞拉摩外面，靠近警戒哨崗一點。別那樣看著我，好嗎？這對我們大家都是個問題。他們肯定不會幹什麼好事。到那兒去解決掉他們。$B$B噢，對了，如果你發現了某些危險的大玩意兒需要當場銷燬的話，就朝它丟這個炸彈。','消滅5個皇冠惡霸，並使用滑栓的氪金炸彈摧毀塵泥沼澤塞拉摩外面的一臺藥劑車。然後返回奧格瑪，去見偵探斯奈普·滑栓。','','轉至奧格瑪，去找力量谷的偵探斯奈普·滑栓。','摧毀藥劑車','','','',0);
