INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24655, 'zhTW', '[Something Stinks]', '[Get a load of these guys, would ya? Steamwheedle\'s been handling the business of holidays for years, and all of a sudden, these guys bust into the market. They\'re not Steamwheedle; the cartel hired me to get to the bottom of this. Something stinks here and it ain\'t just perfume.$B$BTake this device I brought and go analyze the perfume clouds around the guards. I want to know what they\'re putting in that stuff. Things ain\'t natural.]', '[Use Snagglebolt\'s Air Analyzer to test the air around 6 heavily perfumed guards, then return to Inspector Snip Snagglebolt in Stormwind.]', '', '去找暴風城的巡官史尼卜‧凸栓。', '已分析噴香守衛', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24656 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24656,'zhTW','竊取香水','我就知道他們圖謀不軌！這東西含有某種思想控制的化學成分，但光憑這種小樣本，我仍無法掌握他們的把柄。我需要的是成品。
DELETE FROM `quest_template_locale` WHERE `ID` = 24657 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24657, 'zhTW', '[A Friendly Chat...]', '[<Marion listens with horror as you tell her why you\'re trying to track down Snivel.>$B$BYou mean, he might\'ve used some kind of chemical on me? Ew! I can\'t believe I fell for that fraud!$B$BIf he\'s finished all of his errands, he\'s on his way down to the docks to catch a ship to the South Seas! Whatever you do, $N, you can\'t let him get away with this.$B$BHurry down to Stormwind Harbor before you miss him!]', '[Go to Stormwind Harbor and question Snivel Rustrocket about the supplies. Return with any evidence he gives you.]', '', '去找暴風城的巡官史尼卜‧凸栓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24658 AND `locale` = 'zhTW';
