INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24710, 'zhTW', '[Deliverance from the Pit]', '[We need to make our way up the main path and through the cave to Tyrannus\' rise. There, he will be forced to confront us there lest we make our way into the citadel proper.$B$BGo now, $c. My men and I will be there to stand by you when the confrontation with Tyrannus comes.]', '[Kill Scourgelord Tyrannus.]', '', '', '', '', '', '', 0);
