INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24745, 'zhTW', '[Something is in the Air (and it Ain\'t Love)]', '[The inside of the card is scribbled with mad, detailed plans to infect most of Azeroth.  You should show this to one of Steamwheedle\'s investigators immediately!]', '[Bring the Faded Lovely Greeting Card to Inspector Snip Snagglebolt in Stormwind.]', '', '去找影牙城堡的巡官史尼卜‧凸栓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24746 AND `locale` = 'zhTW';
