INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25180, 'zhTW', '[Tablets of the Earth]', '[Some time ago, my brother Brann sent an urgent message from Ulduar. He said he\'d found an ancient titan cache with mysterious and important relics. King Wrynn dispatched one of his fastest ships to Northrend to transport the courier and the boat should\'ve arrived by now.$B$BI\'m worried, $N. I haven\'t heard anything about the courier\'s arrival. Would you be willing to travel to Stormwind Harbor and see if he\'s arrived?]', '[Bring the Tablets of Earth to King Magni Bronzebeard in Ironforge.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25181 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25181, 'zhTW', '[Tablets of Fire]', '[I\'m expecting the arrival of a courier traveling from Northrend. He\'s carrying a collection of ancient titan treasures, ones I\'m hoping will shed light on my troubling visions. The shaman should\'ve arrived on one of the recent zeppelin flights and I\'m starting to get worried.$B$BHe was to meet me by the zeppelin tower southwest of Orgrimmar\'s gates, but I don\'t want to miss my audience with the warchief. Would you be willing to look for the courier and see what\'s delaying him?]', '[Bring the Tablets of Fire to Seer Bahura in Orgrimmar.]', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25199 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25199, 'zhTW', '', '', '', '', '向特瑞德‧炫鼻上尉回報。', '向教官敬禮', '與教官一同咆哮', '與教官一同歡呼', '與教官一同跳舞', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25212 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25212, 'zhTW', '[Vent Horizon]', '[We thought that we could wait for the radiation to subside around Gnomeregan, but it doesn\'t appear to be getting better.$B$BIf we want to take back our city, we need to make sure it\'s safe for our troops to enter.$B$BTake these Radiageigatrons, hop in \'Thunderflash\' here,  and toss them at the ventilation shafts outside of Gnomeregan. They\'ll report the radiation levels directly to me.]', '[Use Pilot Muzzlesprock\'s flying machine to toss Radiageigatrons at the vents surrounding Gnomeregan.]$B$B已提供物品：', '', '去找駕駛員摩卓普拉克談話。', '輻射測量器', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25228 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25228,'zhTW','災難預言','奧格瑪的街道上出現了一幫傢伙，他們滿嘴都是災難即將降臨的蠢話。這在奧格瑪本不算什麼新鮮事。但這幫傢伙卻讓我相當擔憂。他們的行動很有組織性。暗巷區的許多人都受到了他們的影響。他們的勢力在那裡發展得相當迅速。$B$B我考慮過將他們剿除，或者制止他們的活動。但貿然行動只會讓他們轉入地下。我們需要對他們有更多瞭解。你能不能到暗巷區去，聽聽那些末日預言者都在傳播些什麼？你最好能找到一些與他們的理念相關的文字情報。','在暗巷區聽取一名末日預言者的演講，並取得名為《靈魂之元素火焰》、《萬物的終結對我有何意義？》和《在毀滅的世界中尋找安全與舒適》的小冊子。','','回到奧格瑪的力量谷向血衛士托雷克回報。','聽聽末日預言者的演說','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25229 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25229,'zhTW','好侏儒寥寥','我們的工程師正在為進攻諾莫瑞根而日夜不停地裝配我們的戰爭機械，但我們現在極端缺乏駕駛員！$B$B我們的工程師開發出一種名叫激勵儀的裝置。它能夠吸引侏儒們的注意力，並讓他們有勇氣響應我們的徵兵號令。$B$B用它鼓舞起幾名侏儒平民的勇氣，然後帶領他們去見鐵爐堡南邊，鋼架補給站的崔德·火鑽隊長。$B$B一定要小心。這個裝置還有些不太成熟。','使用激勵儀，在侏儒區徵募侏儒，並率領他們返回鋼架補給站，去見崔德·火鑽隊長。','','跟鋼架補給站的特瑞德‧炫鼻上尉談談。','應徵的侏儒','帶著受激勵的侏儒交給斯巴克諾茲船長','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25238 AND `locale` = 'zhTW';
