INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25444, 'zhTW', '[Da Perfect Spies]', '[Now, it would be foolish to go in blind \'ere, so I be creatin\' some tiny spies to gather information for Vol\'jin. He got to know what\'s goin\' on over on de islands.$B$BI could use da help, if you be feelin\' up to it. I tell ya how it\'s done. First, ya gotta catch de frogs. Dey like to stay in de shade of da palm trees around Sen\'jin.$B$BOnce ya have de frogs, bring \'em over here to my sentry totem an\' attune dem to me sight.]', '[Capture 5 Sen\'jin Frogs and attune them to Vanira\'s sight at her Sentry Totem.]', '', '去找凡妮拉。', '', '森金青蛙已調校', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25445 AND `locale` = 'zhTW';
