INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25500,'zhTW','遞送演講稿','好哇，$N，演講稿完成了！它能夠為所有偉大的戰爭作序言……它鼓舞人心，雄辯無礙，能夠為侏儒們清晰地指明方向。再也沒有比這個更優秀的演講稿了！$B$B把這份演講稿交給崔德·火鑽隊長，看看他還需要你做些什麼。','將演講稿交給鋼架補給站的崔德·火鑽隊長。','','將演講稿交給大工匠梅卡托克。','','','','',0);
